@dataclass(frozen=True)
class HostEnvironmentSnapshot:
    """Immutable, process-local tool-host facts; never the remote LLM server."""
    os_name: str = "Unknown OS"
    architecture: str = "unknown"
    cpu: str = "unknown"
    logical_cpus: int = 0
    physical_cores: int = 0
    ram_bytes: int = 0
    gpus: tuple[str, ...] = ()


_HOST_ENVIRONMENT_LOCK = threading.Lock()
_HOST_ENVIRONMENT_SNAPSHOT: HostEnvironmentSnapshot | None = None
_HOST_ENVIRONMENT_PROMPT = ""


def _host_label(value: Any, limit: int = 180) -> str:
    return re.sub(r"\s+", " ", str(value or "")).strip()[:limit]


def _host_positive_int(value: Any) -> int:
    try:
        return max(0, int(value or 0))
    except (TypeError, ValueError, OverflowError):
        return 0


def _host_read(path: str, limit: int = 131072) -> str:
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as stream:
            return stream.read(limit)
    except OSError:
        return ""


def _host_command(command: list[str]) -> str:
    """Only fixed local inventory commands, bounded once during startup."""
    try:
        result = subprocess.run(command, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL, timeout=4, check=False,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0) if os.name == "nt" else 0)
        if result.returncode != 0 or len(result.stdout) > 262144:
            return ""
        return result.stdout.decode("utf-8-sig", errors="replace")
    except (OSError, subprocess.SubprocessError):
        return ""


def _host_windows_inventory() -> dict[str, Any]:
    # Caption distinguishes Windows 11 from Windows 10's shared NT 10 version.
    # Project only requested facts: no hostname, account, serial, IP or device IDs.
    script = (
        "$ErrorActionPreference='Stop'; [Console]::OutputEncoding=[Text.UTF8Encoding]::new(); "
        "$o=$null;$c=@();$g=@(); "
        "try {$o=Get-CimInstance Win32_OperatingSystem} catch {}; "
        "try {$c=@(Get-CimInstance Win32_Processor | Select-Object Name,NumberOfCores,NumberOfLogicalProcessors)} catch {}; "
        "try {$g=@(Get-CimInstance Win32_VideoController | Select-Object -ExpandProperty Name)} catch {}; "
        "@{os=$o.Caption;build=$o.BuildNumber;arch=$o.OSArchitecture;"
        "ram=([uint64]$o.TotalVisibleMemorySize*1024);cpus=$c;gpus=$g} | ConvertTo-Json -Compress -Depth 4"
    )
    executable = str(Path(os.environ.get("SystemRoot", r"C:\Windows")) /
                     "System32" / "WindowsPowerShell" / "v1.0" / "powershell.exe")
    try:
        result = json.loads(_host_command([executable, "-NoLogo", "-NoProfile", "-NonInteractive", "-Command", script]))
        return result if isinstance(result, dict) else {}
    except (ValueError, TypeError):
        return {}


def _host_snapshot_from_windows(data: dict[str, Any], fallback: HostEnvironmentSnapshot) -> HostEnvironmentSnapshot:
    cpus = data.get("cpus", [])
    cpus = [cpus] if isinstance(cpus, dict) else cpus if isinstance(cpus, list) else []
    cpus = [row for row in cpus if isinstance(row, dict)]
    names = list(dict.fromkeys(_host_label(row.get("Name")) for row in cpus if _host_label(row.get("Name"))))
    gpus = data.get("gpus", [])
    gpus = [gpus] if isinstance(gpus, str) else gpus if isinstance(gpus, list) else []
    caption = _host_label(data.get("os")) or fallback.os_name
    build = _host_label(data.get("build"), 32)
    return HostEnvironmentSnapshot(
        os_name=caption + (f" (build {build})" if build else ""),
        architecture=_host_label(data.get("arch"), 40) or fallback.architecture,
        cpu="; ".join(names)[:360] or fallback.cpu,
        logical_cpus=sum(_host_positive_int(row.get("NumberOfLogicalProcessors")) for row in cpus) or fallback.logical_cpus,
        physical_cores=sum(_host_positive_int(row.get("NumberOfCores")) for row in cpus),
        ram_bytes=_host_positive_int(data.get("ram")) or fallback.ram_bytes,
        gpus=tuple(_host_label(name) for name in gpus[:16] if isinstance(name, str) and _host_label(name)),
    )


def _detect_host_environment() -> HostEnvironmentSnapshot:
    """Best-effort static inventory. Failure is cached just like success."""
    system = platform.system()
    cpu = _host_label(platform.processor()) or _host_label(os.environ.get("PROCESSOR_IDENTIFIER")) or "unknown"
    fallback = HostEnvironmentSnapshot(
        os_name=_host_label(f"{system} {platform.release()}"),
        architecture=_host_label(platform.machine(), 40) or "unknown",
        cpu=cpu, logical_cpus=_host_positive_int(os.cpu_count()),
    )
    if system == "Windows":
        # CIM is a single bounded call; optional fields may remain unknown.
        return _host_snapshot_from_windows(_host_windows_inventory(), fallback)
    if system == "Darwin":
        data: dict[str, Any] = {}
        try:
            raw = json.loads(_host_command(["/usr/sbin/system_profiler", "-json", "SPHardwareDataType", "SPDisplaysDataType"]))
            data = raw if isinstance(raw, dict) else {}
        except (TypeError, ValueError):
            pass
        hardware = next((r for r in data.get("SPHardwareDataType", []) if isinstance(r, dict)), {})
        ram = 0
        match = re.fullmatch(r"([\d.]+)\s*(GB|TB|MB)", str(hardware.get("physical_memory") or ""), re.I)
        if match:
            ram = int(float(match[1]) * {"MB": 2**20, "GB": 2**30, "TB": 2**40}[match[2].upper()])
        return HostEnvironmentSnapshot(
            os_name="macOS " + (_host_label(platform.mac_ver()[0]) or platform.release()),
            architecture=fallback.architecture, cpu=_host_label(hardware.get("chip_type") or hardware.get("cpu_type")) or fallback.cpu,
            logical_cpus=fallback.logical_cpus, ram_bytes=ram,
            gpus=tuple(_host_label(r.get("sppci_model")) for r in data.get("SPDisplaysDataType", [])
                       if isinstance(r, dict) and r.get("sppci_model"))[:16],
        )
    if system == "Linux":
        os_name = fallback.os_name
        for line in _host_read("/etc/os-release").splitlines():
            if line.startswith("PRETTY_NAME="):
                os_name = _host_label(line.split("=", 1)[1].strip('"\'')); break
        cpu_rows = _host_read("/proc/cpuinfo").splitlines()
        cpu = next((_host_label(line.split(":", 1)[1]) for line in cpu_rows
                    if ":" in line and line.split(":", 1)[0].strip() in ("model name", "Hardware")), fallback.cpu)
        ram = re.search(r"^MemTotal:\s*(\d+)\s+kB", _host_read("/proc/meminfo"), re.M)
        gpus = []
        lspci = shutil.which("lspci")
        if lspci:
            for line in _host_command([lspci, "-mm"]).splitlines():
                fields = re.findall(r'"([^"]*)"', line)
                if len(fields) >= 3 and fields[0] in ("VGA compatible controller", "3D controller", "Display controller"):
                    gpus.append(_host_label(" ".join(fields[1:3])))
        if not gpus:
            try:
                for path in sorted(Path("/proc/driver/nvidia/gpus").glob("*/information"))[:16]:
                    match = re.search(r"^Model:\s*(.+)$", _host_read(str(path)), re.M)
                    if match: gpus.append(_host_label(match[1]))
            except OSError:
                pass
        return HostEnvironmentSnapshot(os_name=os_name, architecture=fallback.architecture, cpu=cpu,
            logical_cpus=fallback.logical_cpus, ram_bytes=int(ram[1]) * 1024 if ram else 0, gpus=tuple(gpus[:16]))
    return fallback


def _format_host_environment(snapshot: HostEnvironmentSnapshot) -> str:
    counts: dict[str, int] = {}
    for name in snapshot.gpus:
        counts[name] = counts.get(name, 0) + 1
    gpu = "; ".join(f"{count} x {name}" if count > 1 else name for name, count in counts.items()) or "unknown / not exposed"
    cpu_counts = (f"; {snapshot.physical_cores} physical cores" if snapshot.physical_cores else "")
    cpu_counts += f"; {snapshot.logical_cpus} logical processors" if snapshot.logical_cpus else ""
    ram = f"{snapshot.ram_bytes / 2**30:.1f} GiB total" if snapshot.ram_bytes else "unknown"
    return ("VELOX LOCAL EXECUTION ENVIRONMENT\n\n"
        f"OS: {snapshot.os_name}; architecture: {snapshot.architecture}\n"
        f"CPU: {snapshot.cpu}{cpu_counts}\nRAM: {ram}\nGPU: {gpu}\n"
        "Detected once at Velox startup; these are the local tool-execution host's static facts, "
        "not the remote inference endpoint's hardware or currently free resources. "
        "Use them for platform-appropriate commands; inspect specific toolchains only when needed.")


def initialize_host_environment() -> HostEnvironmentSnapshot:
    global _HOST_ENVIRONMENT_SNAPSHOT, _HOST_ENVIRONMENT_PROMPT
    with _HOST_ENVIRONMENT_LOCK:
        if _HOST_ENVIRONMENT_SNAPSHOT is None:
            try:
                snapshot = _detect_host_environment()
            except Exception:
                snapshot = HostEnvironmentSnapshot()
            if not isinstance(snapshot, HostEnvironmentSnapshot):
                snapshot = HostEnvironmentSnapshot()
            _HOST_ENVIRONMENT_PROMPT = _format_host_environment(snapshot)
            _HOST_ENVIRONMENT_SNAPSHOT = snapshot  # Publish only after the complete immutable prompt exists.
        return _HOST_ENVIRONMENT_SNAPSHOT


def host_environment_prompt() -> str:
    if _HOST_ENVIRONMENT_SNAPSHOT is None:
        initialize_host_environment()  # Library/test construction also gets one cached snapshot.
    return _HOST_ENVIRONMENT_PROMPT


