# Page bodies, browser DOM/screenshot metadata, and extracted link sets can each be
# large enough to materially expand the next model prompt. When a model batches
# several page reads, expose at most the first context-heavy webpage result, then
# return to inference so it can decide whether another page is still necessary.
# Search results stay batchable because they are bounded discovery metadata rather
# than full page bodies.
WEB_PAGE_CONTEXT_TOOL_NAMES = frozenset({
    "web_fetch",
    "web_fetch_visible_content",
    "web_fetch_visible_content_and_links",
    "web_page_links",
    "browser_run_headless",
    "browser_demo_playback",
})


def serialize_web_page_result_batch(
    calls: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], int]:
    """Return the ordered prefix ending at the first context-heavy webpage call.

    Calls before the first page retrieval may still run in the same provider batch.
    Calls after it are deliberately deferred to the next inference round. This keeps
    one webpage result at a time in model context without serializing bounded search
    discovery calls or unrelated non-web tools unnecessarily.
    """
    normalized = list(calls or [])
    for index, call in enumerate(normalized):
        if str(call.get("name") or "") in WEB_PAGE_CONTEXT_TOOL_NAMES:
            selected = normalized[: index + 1]
            return selected, max(0, len(normalized) - len(selected))
    return normalized, 0


def filter_response_output_items_for_tool_calls(
    items: list[dict[str, Any]] | None,
    provider_tool_calls: list[dict[str, Any]] | None,
) -> list[dict[str, Any]]:
    """Keep Responses reasoning/message items plus only selected function calls."""
    selected_ids = {
        str(call.get("id") or "").strip()
        for call in (provider_tool_calls or [])
        if isinstance(call, dict) and str(call.get("id") or "").strip()
    }
    filtered: list[dict[str, Any]] = []
    for item in items or []:
        if not isinstance(item, dict):
            continue
        if str(item.get("type") or "") == "function_call":
            call_id = str(item.get("call_id") or item.get("id") or "").strip()
            if call_id not in selected_ids:
                continue
        filtered.append(copy.deepcopy(item))
    return filtered


def consecutive_image_tool_groups(
    calls: list[dict[str, Any]],
) -> list[list[dict[str, Any]]]:
    """Group only adjacent delegated image-analysis calls; preserve all order."""
    groups: list[list[dict[str, Any]]] = []
    index = 0
    while index < len(calls):
        call = calls[index]
        if str(call.get("name") or "") not in PARALLEL_IMAGE_ANALYSIS_TOOL_NAMES:
            groups.append([call])
            index += 1
            continue
        end = index + 1
        while (
            end < len(calls)
            and str(calls[end].get("name") or "") in PARALLEL_IMAGE_ANALYSIS_TOOL_NAMES
        ):
            end += 1
        groups.append(calls[index:end])
        index = end
    return groups


