def _build_common_emoji_chars() -> str:
    """Return a broad single-codepoint emoji/symbol atlas set.

    Emoji presentation is ultimately font/platform dependent and many modern
    emoji are multi-codepoint ZWJ sequences. Velox can atlas and render the
    single Unicode codepoints without adding a shaping dependency; compound
    emoji fall back to their component glyphs when the platform font cannot
    render the full sequence as one glyph.
    """
    seed = (
        '😀😃😄😁😆😅😂🤣🙂🙃😉😊😇🥰😍🤩😘😋😛😜🤪🤔🤐😐🙄😬😴😎🥳🤯🥺😭'
        '😤😱😢😡😠🤬😈👻🤖💩🤡💀😺😻🙈🙉🙊👍👎👌✌🤞🤝🙌👏🙏💪🧠👀👁👂👃'
        '💋👋🤚🖐✋🖖👊✊🤛🤜🫶❤💙💚💛💜🖤💯✅❌⭐🌟💡🔔📎🔗🔒🔥🚀📌📈📉'
        '📝📦📷🖼⚙🎉🌸🌻🌹🌳🍁🍄🌵🌿☀🌙🌈☁❄🐶🐱🐰🦊🐻🐼🐨🐯🦁🐮🐷🐸🐵'
    )
    # Include practical single-codepoint emoji bands in one atlas.
    # This is intentionally capped below 4096 glyphs so a 64-column grid remains
    # predictable in memory while covering all common UTF-8 emoji codepoints.
    ranges = [
        (0x1F000, 0x1FAFF),  # enclosed, pictographic, transport, symbols, supplemental, extended-A
        (0x2600, 0x27BF),    # misc symbols and dingbats
        (0x2300, 0x23FF),    # technical symbols that often have emoji presentation
        (0x2B00, 0x2BFF),    # arrows/stars/circles/squares with emoji presentation
        (0x1F1E6, 0x1F1FF),  # regional indicators for flags
    ]
    chars: list[str] = []
    seen: set[str] = set()

    def add(ch: str) -> None:
        if not ch or ch in seen or len(chars) >= 4096:
            return
        cat = unicodedata.category(ch)
        if cat.startswith('C'):
            return
        seen.add(ch)
        chars.append(ch)

    for ch in seed:
        add(ch)
    for start, end in ranges:
        for cp in range(start, end + 1):
            add(chr(cp))
            if len(chars) >= 4096:
                break
        if len(chars) >= 4096:
            break
    return ''.join(chars)

COMMON_EMOJI_CHARS = _build_common_emoji_chars()

# Curated chat atlas: common Western prose and technical output without attempting
# to pre-render all of Unicode. Control, unassigned, private-use, and non-space
# whitespace codepoints are excluded.
COMMON_CHAT_GLYPH_RANGES: tuple[tuple[int, int], ...] = (
    (0x0020, 0x007F),  # printable ASCII
    (0x00A0, 0x0250),  # Latin-1 and Latin Extended-A/B
    (0x02B0, 0x0370),  # spacing modifiers and combining marks
    (0x0370, 0x0530),  # Greek/Coptic and Cyrillic
    (0x1D00, 0x1DC0),  # phonetic extensions and combining supplement
    (0x1E00, 0x2000),  # Latin Extended Additional
    (0x2000, 0x2070),  # general punctuation
    (0x2070, 0x20D0),  # superscripts, subscripts, currency, combining symbols
    (0x2100, 0x2200),  # letterlike symbols, number forms, arrows
    (0x2200, 0x2300),  # mathematical operators
    (0x2300, 0x2500),  # technical symbols, control pictures, enclosed forms
    (0x2500, 0x25A0),  # box drawing and block elements
    (0x25A0, 0x2600),  # geometric shapes
    (0x2600, 0x27C0),  # miscellaneous symbols and dingbats
    (0x27C0, 0x2800),  # supplemental mathematical symbols/arrows
    (0x2E00, 0x2E80),  # supplemental punctuation
)
COMMON_CHAT_GLYPH_EXTRA = "’‘“”–—…•·‚„′″‹›«»‑−×÷±≤≥≠≈→←↑↓✓✔✕✖★☆⚙⌘⌥⌫⌦↵⇧�"
# Keep the atlas cardinality stable across Python 3.10+ Unicode database
# revisions. Newly assigned symbols can otherwise change the count, texture
# dimensions, VRAM estimate, and tests from one supported Python release to
# another. On an older Unicode database, the bounded fill below reserves slots
# for later-assigned pictographs; fonts simply omit surfaces they do not provide.
FONT_ATLAS_TARGET_GLYPH_COUNT = 6415

def _build_common_chat_glyph_chars() -> str:
    chars: list[str] = []
    seen: set[str] = set()

    def add(ch: str) -> None:
        if not ch or ch in seen:
            return
        category = unicodedata.category(ch)
        if category.startswith("C") or (ch.isspace() and ch != " "):
            return
        seen.add(ch)
        chars.append(ch)

    for range_start, range_end in COMMON_CHAT_GLYPH_RANGES:
        for codepoint in range(range_start, range_end):
            add(chr(codepoint))
    for ch in COMMON_CHAT_GLYPH_EXTRA + COMMON_EMOJI_CHARS:
        add(ch)

    # Python releases bundle different Unicode assignment tables. Fill any
    # shortfall from the same bounded pictographic ranges without consulting
    # unicodedata so the atlas remains exactly the documented size. These slots
    # cost no glyph-render work when the selected font lacks the codepoint.
    if len(chars) < FONT_ATLAS_TARGET_GLYPH_COUNT:
        for start, end in ((0x1F000, 0x1FAFF), (0x2B00, 0x2BFF)):
            for codepoint in range(start, end + 1):
                ch = chr(codepoint)
                if ch in seen:
                    continue
                seen.add(ch)
                chars.append(ch)
                if len(chars) >= FONT_ATLAS_TARGET_GLYPH_COUNT:
                    break
            if len(chars) >= FONT_ATLAS_TARGET_GLYPH_COUNT:
                break
    return "".join(chars[:FONT_ATLAS_TARGET_GLYPH_COUNT])


COMMON_CHAT_GLYPH_CHARS = _build_common_chat_glyph_chars()
FONT_ATLAS_GLYPH_COUNT = len(COMMON_CHAT_GLYPH_CHARS)
FONT_ATLAS_ESTIMATED_CELL_PX = 32
FONT_ATLAS_ESTIMATED_COLUMNS = 64
FONT_ATLAS_ESTIMATED_ROWS = math.ceil(FONT_ATLAS_GLYPH_COUNT / FONT_ATLAS_ESTIMATED_COLUMNS)
FONT_ATLAS_ESTIMATED_VRAM_BYTES_PER_VARIANT = (
    FONT_ATLAS_ESTIMATED_COLUMNS
    * FONT_ATLAS_ESTIMATED_ROWS
    * FONT_ATLAS_ESTIMATED_CELL_PX
    * FONT_ATLAS_ESTIMATED_CELL_PX
    * 4
)
FONT_ATLAS_VARIANT_COUNT = 5  # regular, bold, italic, bold-italic, and monospace
FONT_ATLAS_ESTIMATED_VRAM_MIB_PER_VARIANT = (
    FONT_ATLAS_ESTIMATED_VRAM_BYTES_PER_VARIANT / (1024.0 * 1024.0)
)
FONT_ATLAS_ESTIMATED_TOTAL_VRAM_BYTES = (
    FONT_ATLAS_ESTIMATED_VRAM_BYTES_PER_VARIANT * FONT_ATLAS_VARIANT_COUNT
)
FONT_ATLAS_ESTIMATED_TOTAL_VRAM_MIB = (
    FONT_ATLAS_ESTIMATED_TOTAL_VRAM_BYTES / (1024.0 * 1024.0)
)


def is_emoji_char(ch: str) -> bool:
    if not ch:
        return False
    cp = ord(ch[0])
    return (
        0x1F300 <= cp <= 0x1FAFF
        or 0x2600 <= cp <= 0x27BF
        or 0xFE00 <= cp <= 0xFE0F
    )

def emoji_font_path() -> str:
    for raw in EMOJI_FONT_CANDIDATES:
        try:
            if Path(raw).exists():
                return raw
        except Exception:
            continue
    return ""


# : expose actual installed sans and mono face names.  The UI always uses a
# sans-serif face; code blocks and code-like content use a mono face.  We keep
# this discovery lightweight and deterministic so it is safe at import/test time.
FONT_COMMON_SANS_ORDER = ["Verdana", "Segoe UI", "Arial", "Calibri", "Tahoma"]
FONT_COMMON_MONO_ORDER = ["Consolas", "Courier New", "Cascadia Code"]
FONT_FACE_PATH_BY_NAME: dict[str, dict[str, str]] = {"Sans": {}, "Mono": {}}


def _font_name_from_path(path: Path) -> str:
    stem = path.stem
    cleanup = ["-Regular", " Regular", "-Bold", " Bold", "-Italic", " Italic", "-Oblique", " Oblique"]
    for suffix in cleanup:
        if stem.endswith(suffix):
            stem = stem[: -len(suffix)]
    aliases = {
        "arial": "Arial", "segoeui": "Segoe UI", "seguiemj": "Segoe UI", "consola": "Consolas",
        "consolai": "Consolas", "consolab": "Consolas", "CascadiaMono": "Cascadia Mono",
        "CascadiaCode": "Cascadia Code", "DejaVuSans": "DejaVu Sans", "DejaVuSansMono": "DejaVu Sans Mono",
        "LiberationSans": "Liberation Sans", "LiberationMono": "Liberation Mono",
    }
    return aliases.get(stem, stem.replace("_", " ").replace("-", " ").strip() or path.name)


def _candidate_font_paths(kind: str) -> list[tuple[str, str]]:
    # Keep visible font choices conservative and validated. The
    # previous broad scanner could surface odd/unloadable family names on clean
    # or unusual Windows installs.  Only show the requested common sans/mono
    # faces when a known font file is present.  If none are available, discovery
    # below falls back to the first loadable sans/mono file it can find.
    if kind == "Mono":
        return [
            ("Consolas", "C:/Windows/Fonts/consola.ttf"),
            ("Courier New", "C:/Windows/Fonts/cour.ttf"),
            ("Cascadia Code", "C:/Windows/Fonts/CascadiaCode.ttf"),
            ("Cascadia Code", "C:/Windows/Fonts/CascadiaMono.ttf"),
            ("DejaVu Sans Mono", "/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf"),
            ("Liberation Mono", "/usr/share/fonts/truetype/liberation2/LiberationMono-Regular.ttf"),
            ("Menlo", "/System/Library/Fonts/Menlo.ttc"),
        ]
    return [
        ("Verdana", "C:/Windows/Fonts/verdana.ttf"),
        ("Segoe UI", "C:/Windows/Fonts/segoeui.ttf"),
        ("Arial", "C:/Windows/Fonts/arial.ttf"),
        ("Calibri", "C:/Windows/Fonts/calibri.ttf"),
        ("Tahoma", "C:/Windows/Fonts/tahoma.ttf"),
        ("DejaVu Sans", "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"),
        ("Liberation Sans", "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf"),
        ("Helvetica", "/System/Library/Fonts/Helvetica.ttc"),
    ]

def _discover_font_options(kind: str, limit: int = 12) -> list[str]:
    kind = "Mono" if kind == "Mono" else "Sans"
    requested_order = FONT_COMMON_MONO_ORDER if kind == "Mono" else FONT_COMMON_SANS_ORDER
    found: dict[str, str] = {}
    # First, use only the short requested list when the corresponding files are
    # present.  This keeps Settings readable and avoids invalid family names.
    for name, raw in _candidate_font_paths(kind):
        if name not in requested_order:
            continue
        try:
            path = Path(raw)
            if path.exists() and name not in found:
                found[name] = str(path)
        except Exception:
            continue

    # If none of the requested faces exist, find one loadable fallback so the app
    # can still launch on Linux/macOS/test containers.  Do not expose a huge list.
    if not found:
        search_roots: list[Path] = []
        if os.name == "nt":
            search_roots.append(Path(os.environ.get("WINDIR", "C:/Windows")) / "Fonts")
        elif sys.platform == "darwin":
            search_roots.extend([Path("/System/Library/Fonts"), Path("/Library/Fonts")])
        else:
            search_roots.extend([Path("/usr/share/fonts"), Path.home() / ".fonts", Path.home() / ".local/share/fonts"])
        mono_hint = re.compile(r"(mono|code|consol|courier|cascadia|menlo|sourcecode)", re.I)
        sans_hint = re.compile(r"(sans|arial|segoe|calibri|tahoma|verdana|helvetica|roboto|noto|liberation|dejavu)", re.I)
        for root in search_roots:
            try:
                if not root.exists():
                    continue
                for child in root.rglob("*"):
                    if child.suffix.lower() not in {".ttf", ".ttc", ".otf"}:
                        continue
                    name = _font_name_from_path(child)
                    hay = f"{name} {child.name}"
                    if kind == "Mono" and not mono_hint.search(hay):
                        continue
                    if kind == "Sans" and (mono_hint.search(hay) or not sans_hint.search(hay)):
                        continue
                    found[name] = str(child)
                    raise StopIteration
            except StopIteration:
                break
            except Exception:
                continue

    # Always expose at least one name.  If it lacks a path, FontAtlas gracefully
    # falls back to SDL debug metrics, which is better than crashing.
    preferred = [name for name in requested_order if name in found]
    for name in found:
        if name not in preferred:
            preferred.append(name)
    if not preferred:
        preferred = ["Consolas" if kind == "Mono" else "Segoe UI"]
    FONT_FACE_PATH_BY_NAME[kind] = {name: found.get(name, "") for name in preferred[:max(1, min(limit, 12))]}
    return preferred[:max(1, min(limit, 12))]


FONT_SANS_OPTIONS = _discover_font_options("Sans")
FONT_MONO_OPTIONS = _discover_font_options("Mono")
# Keep Verdana visible as the preferred app default even on non-Windows test
# environments where the file may not exist. Font loading falls back safely; the
# visible Settings list stays restricted to readable common faces.
if "Verdana" not in FONT_SANS_OPTIONS:
    allowed_sans_options = {"Segoe UI", "Arial", "Calibri", "Tahoma", "Verdana", "DejaVu Sans", "Liberation Sans", "Helvetica"}
    FONT_SANS_OPTIONS = ["Verdana"] + [name for name in FONT_SANS_OPTIONS if name in allowed_sans_options]
    FONT_FACE_PATH_BY_NAME.setdefault("Sans", {}).setdefault("Verdana", "")


def font_path_for_face(kind: str, name: str | None = None) -> str:
    kind = "Mono" if kind == "Mono" else "Sans"
    options = FONT_MONO_OPTIONS if kind == "Mono" else FONT_SANS_OPTIONS
    selected = str(name or "").strip()
    if selected not in FONT_FACE_PATH_BY_NAME.get(kind, {}):
        selected = options[0] if options else ""
    path = FONT_FACE_PATH_BY_NAME.get(kind, {}).get(selected, "")
    if path:
        return path
    # Fall back to old candidate paths.
    for raw in FONT_FACE_CANDIDATES.get(kind, []):
        try:
            if Path(raw).exists():
                return raw
        except Exception:
            pass
    return ""

FONT_ROLE_OPTIONS = ["Sans", "Mono"]
FONT_WEIGHT_OPTIONS = ["light", "medium", "heavy"]
# Weight is applied at draw time so changing Settings > UI has an immediate,
# visible effect without rebuilding every glyph atlas. Light deliberately lowers
# stroke opacity; Heavy adds a one-pixel high-opacity pass. The stronger values
# keep the thickness change visible at ordinary display scales.
FONT_LIGHT_ALPHA_SCALE = 0.62
FONT_HEAVY_ALPHA_SCALE = 0.84
FONT_HEAVY_X_OFFSET = 1.0

TABLE_CELL_MAX_CHARS = 256
TABLE_CELL_PAD_X = 14
TABLE_CELL_PAD_Y = 13
TABLE_MIN_COLUMN_WIDTH = 72
SELECTION_EDGE_PAD_PX = 2
TEXT_WRAP_CACHE_MAX_ENTRIES = 512

def normalize_font_weight(value: Any) -> str:
    raw = str(value or "heavy").strip().lower().replace("_", "-")
    if raw in {"light", "thin", "extra-light", "extralight", "300", "200", "100"}:
        return "light"
    if raw in {"heavy", "semibold", "semi-bold", "boldish", "600", "700", "default", ""}:
        return "heavy"
    if raw in {"normal", "regular", "medium", "400", "500"}:
        return "medium"
    return "heavy"

def preferred_ui_font_face() -> str:
    # Target Windows font requested for the app UI. On Linux/macOS test runners
    # the face may not be installed; FontAtlas falls back to the first loadable
    # sans font while preserving Verdana as the default stored preference.
    return "Verdana"

def normalize_font_role(value: Any) -> str:
    raw = str(value or "Sans").strip()
    alias = FONT_FACE_ALIASES.get(raw.lower())
    if alias in ("Sans", "Mono"):
        return alias
    if raw in ("Sans", "Mono"):
        return raw
    if raw in FONT_MONO_OPTIONS:
        return "Mono"
    return "Sans"

def preferred_font_face(role: str) -> str:
    role = normalize_font_role(role)
    options = FONT_MONO_OPTIONS if role == "Mono" else FONT_SANS_OPTIONS
    return options[0] if options else role


def normalize_font_style(value: Any) -> str:
    raw = str(value or "regular").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "normal": "regular",
        "roman": "regular",
        "regular": "regular",
        "b": "bold",
        "bold": "bold",
        "i": "italic",
        "italics": "italic",
        "italic": "italic",
        "oblique": "italic",
        "bolditalic": "bold_italic",
        "bold_italic": "bold_italic",
        "bold_oblique": "bold_italic",
        "bolditalics": "bold_italic",
    }
    return aliases.get(raw, "regular")


