# DeepSeek V4-compatible gateways can occasionally leak one of the model's
# internal DSML closing wrappers into otherwise ordinary assistant content.
# These exact strings are provider artifacts rather than user/model prose. Keep
# this list deliberately narrow: malformed JSON must never be repaired by
# arbitrary truncation.
KNOWN_PROVIDER_TRAILING_TEXT_ARTIFACTS: tuple[str, ...] = (
    "</｜DSML｜parameter>",
)


def normalize_known_provider_output_artifacts(text: Any) -> str:
    """Remove only known trailing provider wrappers from completed text.

    The normalization is intentionally suffix-only and exact. It may peel more
    than one repeated known wrapper, but it never searches for a brace, trims
    arbitrary malformed JSON, or otherwise guesses where provider output should
    have ended.
    """
    raw = str(text or "")
    value = raw
    changed = False
    while True:
        candidate = value.rstrip()
        matched = next(
            (artifact for artifact in KNOWN_PROVIDER_TRAILING_TEXT_ARTIFACTS if candidate.endswith(artifact)),
            "",
        )
        if not matched:
            break
        value = candidate[:-len(matched)]
        changed = True
    return value.rstrip() if changed else raw


class TrailingKnownProviderArtifactFilter:
    """Suppress only a known provider wrapper when it is truly terminal.

    Streaming can split a DeepSeek DSML wrapper across arbitrary deltas.  Keep at
    most the longest suffix that could still become one of the known artifacts;
    release it immediately if later model text proves it was not terminal.  At
    stream completion an exact known artifact is discarded, while an incomplete
    prefix is preserved verbatim.  This prevents provider markup from flashing in
    Chat UI or entering durable text without guessing at malformed output.
    """

    __slots__ = ("_pending",)

    def __init__(self) -> None:
        self._pending = ""

    @staticmethod
    def _held_suffix_length(value: str) -> int:
        best = 0
        for artifact in KNOWN_PROVIDER_TRAILING_TEXT_ARTIFACTS:
            limit = min(len(value), len(artifact))
            for size in range(limit, 0, -1):
                if value.endswith(artifact[:size]):
                    best = max(best, size)
                    break
        return best

    def feed(self, value: Any) -> str:
        piece = str(value or "")
        if not piece:
            return ""
        combined = self._pending + piece
        hold = self._held_suffix_length(combined)
        if hold:
            emitted = combined[:-hold]
            self._pending = combined[-hold:]
            return emitted
        self._pending = ""
        return combined

    def finish(self) -> str:
        pending = self._pending
        self._pending = ""
        if pending in KNOWN_PROVIDER_TRAILING_TEXT_ARTIFACTS:
            return ""
        return pending
