AGENT_TIMEOUT_MINUTES_DEFAULT = 1800 * LONG_TASK_LIMIT_MULTIPLIER
AGENT_TIMEOUT_MINUTES_MIN = 1
AGENT_CONTEXT_WINDOW_TOKENS_DEFAULT = 131_072
AGENT_CONTEXT_WINDOW_TOKENS_MIN = 8_192
AGENT_MAX_OUTPUT_TOKENS_DEFAULT = 32_768
AGENT_COMPACTION_RECENT_MESSAGES = 3
CHAT_COMPACTION_RECENT_MESSAGES = 8
CHAT_COMPACTION_MIN_MESSAGES = 8
COMPACTION_MAX_PASSES = 3
CONTEXT_OVERFLOW_RECOVERY_MAX_ATTEMPTS = 3  # default; editable per endpoint
COMPACTION_OVERSIZED_REASONING_PERCENT = 1
COMPACTION_SUMMARY_MIN_TOKENS = 2_048
COMPACTION_SUMMARY_MAX_TOKENS = 8_192
COMPACTION_MODEL_MIN_OUTPUT_TOKENS = 8_192
COMPACTION_MODEL_MAX_OUTPUT_TOKENS = 32_768
COMPACTION_LEDGER_MIN_TOKENS = 4_096
COMPACTION_LEDGER_MAX_TOKENS = 16_384
COMPACTION_LEDGER_ENTRY_MAX_CHARS = 1_200
AGENT_STATUSES = ("queued", "running", "paused", "succeeded", "failed", "cancelled")
AGENT_TERMINAL_STATUSES = frozenset({"succeeded", "failed", "cancelled"})
AGENT_DELETABLE_STATUSES = frozenset({"paused", "succeeded", "failed", "cancelled"})
AGENT_CHAT_ONLY_TOOL_NAMES = frozenset({
    "agents_start", "agents_list", "agents_pause", "agents_resume", "agents_stop",
    "terminal_get_agent_terminals", "terminal_get_agent_terminal_output",
})
TOOL_INLINE_MARKER_RE = re.compile(r"(?m)^[ \t]*\[\[VELOX_TOOL_ROW:(\d+)\]\][ \t]*$")
TOOL_CALL_BATCH_MAX = 64 * LONG_TASK_LIMIT_MULTIPLIER


def strip_tool_markup_from_text(text: str) -> str:
    """Remove only Velox's internal durable tool-row placeholders from prose."""
    raw = TOOL_INLINE_MARKER_RE.sub("", str(text or ""))
    return re.sub(r"\n{3,}", "\n\n", raw).strip("\n")


def neutralize_tool_protocol_markup_for_memory(text: str) -> str:
    """Prepare assistant text for factual Task memory in the native-only runtime."""
    raw = strip_tool_markup_from_text(str(text or ""))
    raw = re.sub(
        r"(?m)^[ \t]*\$\$AGENT_PROGRESS:[^\n]*$",
        "[agent control event omitted from Task memory]",
        raw,
    )
    return re.sub(r"\n{3,}", "\n\n", raw).strip()


def _normalized_tool_call_fingerprint(call: dict[str, Any]) -> str:
    return json.dumps(
        [str(call.get("name") or ""), call.get("arguments") or {}],
        ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str,
    )


def trim_repeated_normalized_tool_calls(
    calls: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], int]:
    """Keep the first unique prefix when a truncated response repeats its batch."""
    seen: set[str] = set()
    for index, call in enumerate(calls):
        fingerprint = _normalized_tool_call_fingerprint(call)
        if fingerprint in seen:
            return calls[:index], len(calls) - index
        seen.add(fingerprint)
    return calls, 0


def _merge_provider_tool_fragment(
    current: str,
    fragment: Any,
    *,
    snapshot: bool = False,
    preserve_repeated_delta: bool = False,
) -> str:
    """Merge one streamed native-call field according to its wire semantics.

    Function ``arguments`` are append-only JSON text. Adjacent argument chunks
    may legitimately be identical, especially for source code, escaped quotes,
    or repeated characters, so those chunks must never be de-duplicated. Call
    identifiers, call types, and function names are metadata; some compatible
    providers repeat the same complete metadata value in multiple deltas, and
    concatenating it would corrupt an otherwise valid call. A cumulative final
    ``message`` snapshot always replaces the accumulated field.
    """
    piece = str(fragment or "")
    if not piece:
        return current
    if snapshot:
        if not current:
            return piece
        if piece == current or piece.startswith(current):
            return piece
        if current.startswith(piece):
            return current
        if preserve_repeated_delta:
            try:
                if json.loads(current) == json.loads(piece):
                    return piece
            except Exception:
                pass
        raise ValueError("Conflicting provider tool-call snapshot fragment")
    if not current:
        return piece
    if preserve_repeated_delta:
        # Similar-looking deltas are still literal text, never inferred snapshots.
        return current + piece
    if piece == current:
        return current
    if len(piece) > len(current) and piece.startswith(current):
        return piece
    return current + piece


def _provider_tool_carriers(payload: Any) -> list[tuple[dict[str, Any], bool]]:
    """Return selected-choice native-call carriers as (object, is_snapshot).

    Only Chat Completions choice zero belongs to the active conversation.
    Streaming ``delta`` objects append fragments. Final ``message`` objects and
    direct response objects are cumulative snapshots and replace prior fields.
    """
    if not isinstance(payload, dict):
        return []
    carriers: list[tuple[dict[str, Any], bool]] = []
    choices = payload.get("choices")
    if isinstance(choices, list) and choices:
        choice = choices[0]
        if isinstance(choice, dict):
            delta = choice.get("delta")
            message = choice.get("message")
            if isinstance(delta, dict):
                carriers.append((delta, False))
            if isinstance(message, dict):
                carriers.append((message, True))
            if not isinstance(delta, dict) and not isinstance(message, dict):
                if any(field in choice for field in ("tool_calls", "function_call", "tool_call")):
                    carriers.append((choice, True))
    elif any(field in payload for field in ("tool_calls", "function_call", "tool_call")):
        carriers.append((payload, True))
    for key in ("response", "result", "data"):
        child = payload.get(key)
        if isinstance(child, dict):
            carriers.extend(_provider_tool_carriers(child))
    return carriers


def accumulate_provider_tool_call_attempt(
    accumulator: dict[str, dict[str, str]],
    payload: Any,
) -> bool:
    """Accumulate fragmented selected-choice OpenAI-compatible native calls."""
    found = False
    for carrier, is_snapshot in _provider_tool_carriers(payload):
        tool_calls = carrier.get("tool_calls")
        if isinstance(tool_calls, list):
            for position, item in enumerate(tool_calls):
                if not isinstance(item, dict):
                    continue
                raw_index = item.get("index")
                function = item.get("function") if isinstance(item.get("function"), dict) else item
                name_fragment = function.get("name")
                arguments = function.get("arguments", item.get("arguments", ""))
                call_id = item.get("id")
                call_type = item.get("type")
                if not any(value not in (None, "", {}, []) for value in (name_fragment, arguments, call_id, call_type)):
                    continue
                key = str(raw_index if raw_index is not None else position)
                if call_id:
                    matching_key = next((
                        existing_key for existing_key, existing in accumulator.items()
                        if str(existing.get("id") or "") == str(call_id)
                    ), "")
                    if matching_key:
                        key = matching_key
                    elif key in accumulator and str(accumulator[key].get("id") or "") not in {"", str(call_id)}:
                        key = f"id:{call_id}"
                entry = accumulator.setdefault(key, {"name": "", "arguments": "", "id": "", "type": ""})
                entry["name"] = _merge_provider_tool_fragment(entry.get("name", ""), name_fragment, snapshot=is_snapshot)
                if isinstance(arguments, (dict, list)):
                    arguments = json.dumps(arguments, ensure_ascii=False, separators=(",", ":"))
                entry["arguments"] = _merge_provider_tool_fragment(
                    entry.get("arguments", ""), arguments,
                    snapshot=is_snapshot, preserve_repeated_delta=True,
                )
                entry["id"] = _merge_provider_tool_fragment(entry.get("id", ""), call_id, snapshot=is_snapshot)
                entry["type"] = _merge_provider_tool_fragment(entry.get("type", ""), call_type, snapshot=is_snapshot)
                found = True
        for field, key in (("function_call", "function_call"), ("tool_call", "tool_call")):
            call = carrier.get(field)
            if not isinstance(call, dict):
                continue
            function = call.get("function") if isinstance(call.get("function"), dict) else call
            name_fragment = function.get("name")
            arguments = function.get("arguments", call.get("arguments", ""))
            call_id = call.get("id")
            call_type = call.get("type")
            if not any(value not in (None, "", {}, []) for value in (name_fragment, arguments, call_id, call_type)):
                continue
            entry = accumulator.setdefault(key, {"name": "", "arguments": "", "id": "", "type": ""})
            entry["name"] = _merge_provider_tool_fragment(entry.get("name", ""), name_fragment, snapshot=is_snapshot)
            if isinstance(arguments, (dict, list)):
                arguments = json.dumps(arguments, ensure_ascii=False, separators=(",", ":"))
            entry["arguments"] = _merge_provider_tool_fragment(
                    entry.get("arguments", ""), arguments,
                    snapshot=is_snapshot, preserve_repeated_delta=True,
                )
            entry["id"] = _merge_provider_tool_fragment(entry.get("id", ""), call_id, snapshot=is_snapshot)
            entry["type"] = _merge_provider_tool_fragment(entry.get("type", ""), call_type, snapshot=is_snapshot)
            found = True
    return found

def provider_tool_calls_from_accumulator(
    accumulator: dict[str, dict[str, str]],
) -> list[dict[str, Any]]:
    """Materialize one OpenAI Chat Completions v1 tool_calls array.

    Streaming providers split IDs, names, and JSON arguments across deltas. The
    shared accumulator reassembles those fragments. Provider call IDs remain the
    unique execution identity: duplicate compatibility carriers are collapsed,
    while conflicting carriers are rejected rather than silently selecting one.
    """
    materialized: list[dict[str, Any]] = []
    for ordinal, key in enumerate(
        sorted(
            accumulator,
            key=lambda value: (
                (0, int(str(value))) if str(value).isdigit() else (1, str(value))
            ),
        ),
        1,
    ):
        entry = accumulator.get(key) or {}
        name = str(entry.get("name") or "").strip()
        arguments = str(entry.get("arguments") or "")
        provider_call_id = str(entry.get("id") or "").strip()
        if not name and not arguments:
            # An ID-only fragment is not executable and must not reserve the ID;
            # a later compatibility carrier may contain the complete call.
            continue
        materialized.append({
            "id": provider_call_id or f"call_{ordinal}_{uuid_v4()}",
            "type": str(entry.get("type") or "function"),
            "function": {"name": name, "arguments": arguments},
        })
    return canonicalize_provider_tool_calls(materialized)


def provider_tool_calls_from_payload(payload: Any) -> list[dict[str, Any]]:
    accumulator: dict[str, dict[str, str]] = {}
    if not accumulate_provider_tool_call_attempt(accumulator, payload):
        return []
    return provider_tool_calls_from_accumulator(accumulator)

REQUEST_TOKEN_ESTIMATE_PROSE_NUMERATOR = 1
REQUEST_TOKEN_ESTIMATE_PROSE_DENOMINATOR = 4
REQUEST_TOKEN_ESTIMATE_STRUCTURE_NUMERATOR = 1
REQUEST_TOKEN_ESTIMATE_STRUCTURE_DENOMINATOR = 32
REQUEST_TOKEN_ESTIMATE_STRUCTURE_CHARS = "\n\r\t{}[],:;\\\""
REQUEST_TOKEN_ESTIMATE_NON_ASCII_BYTES_PER_TOKEN = 3


def _estimated_text_tokens(text: str) -> int:
    """Return a tight tokenizer-free estimate for model-visible text.

    Tokenizers differ by model and chat template, so this value is a prediction,
    not an upper bound. Four characters per token is the stable prose baseline;
    a deliberately small structural surcharge covers dense JSON/code framing,
    while a UTF-8 byte floor protects non-ASCII text. Provider-reported overflow
    counts remain authoritative and calibrate progressively stricter retries.
    """
    raw = str(text or "")
    if not raw:
        return 0
    length = len(raw)
    prose = (
        length * REQUEST_TOKEN_ESTIMATE_PROSE_NUMERATOR
        + REQUEST_TOKEN_ESTIMATE_PROSE_DENOMINATOR - 1
    ) // REQUEST_TOKEN_ESTIMATE_PROSE_DENOMINATOR
    structural_chars = sum(raw.count(ch) for ch in REQUEST_TOKEN_ESTIMATE_STRUCTURE_CHARS)
    structural = (
        structural_chars * REQUEST_TOKEN_ESTIMATE_STRUCTURE_NUMERATOR
        + REQUEST_TOKEN_ESTIMATE_STRUCTURE_DENOMINATOR - 1
    ) // REQUEST_TOKEN_ESTIMATE_STRUCTURE_DENOMINATOR
    estimate = prose + structural
    if not raw.isascii():
        utf8_bytes = len(raw.encode("utf-8", errors="replace"))
        estimate = max(
            estimate,
            (utf8_bytes + REQUEST_TOKEN_ESTIMATE_NON_ASCII_BYTES_PER_TOKEN - 1)
            // REQUEST_TOKEN_ESTIMATE_NON_ASCII_BYTES_PER_TOKEN,
        )
    return max(1, int(estimate))


def _compaction_value_tokens(value: Any) -> int:
    """Return the shared deterministic token estimate used by request fitting."""
    if value is None:
        return 0
    if isinstance(value, str):
        return _estimated_text_tokens(value)
    if isinstance(value, (dict, list)):
        try:
            return _estimated_text_tokens(
                json.dumps(value, ensure_ascii=False, separators=(",", ":"), default=str)
            )
        except Exception:
            return _estimated_text_tokens(str(value))
    return _estimated_text_tokens(str(value))


def _compaction_bounded_excerpt(value: Any, max_chars: int) -> str:
    """Return a stable head/tail excerpt at word boundaries for operational memory."""
    raw = re.sub(r"\s+", " ", neutralize_tool_protocol_markup_for_memory(str(value or ""))).strip()
    limit = max(96, int(max_chars))
    if len(raw) <= limit:
        return raw
    marker = " ... [details omitted] ... "
    remaining = max(32, limit - len(marker))
    head_len = max(16, int(remaining * 0.62))
    tail_len = max(16, remaining - head_len)
    head = raw[:head_len]
    tail = raw[-tail_len:]
    if " " in head:
        head = head.rsplit(" ", 1)[0]
    if " " in tail:
        tail = tail.split(" ", 1)[-1]
    return (head.rstrip() + marker + tail.lstrip())[:limit]


def _compaction_reasoning_summary(reasoning: Any, token_count: int) -> str:
    """Condense one oversized hidden reasoning trace without replaying it verbatim."""
    excerpt = _compaction_bounded_excerpt(reasoning, 1200)
    if not excerpt:
        excerpt = "No stable textual excerpt was available."
    return f"[Earlier execution notes: {excerpt}]"


def _condense_tagged_reasoning(
    content: str,
    *,
    threshold_tokens: int,
) -> tuple[str, int, int]:
    """Condense completed or unterminated reasoning tags above the threshold."""
    raw = str(content or "")
    tag_re = re.compile(r"(?is)<(/?)(think|thinking|reasoning)>")
    out: list[str] = []
    cursor = 0
    in_reasoning = False
    body_start = 0
    opening_name = "think"
    summarized_count = 0
    removed_tokens = 0
    for match in tag_re.finditer(raw):
        closing = bool(match.group(1))
        if not in_reasoning:
            if closing:
                continue
            out.append(raw[cursor:match.end()])
            cursor = match.end()
            body_start = cursor
            opening_name = str(match.group(2) or "think")
            in_reasoning = True
            continue
        if not closing:
            # Treat nested opening text as part of the hidden trace. Provider
            # output occasionally repeats an opening tag after a stream resume.
            continue
        body = raw[body_start:match.start()]
        body_tokens = _compaction_value_tokens(body)
        if body_tokens > threshold_tokens:
            replacement = "\n" + _compaction_reasoning_summary(body, body_tokens) + "\n"
            out.append(replacement)
            summarized_count += 1
            removed_tokens += max(0, body_tokens - _compaction_value_tokens(replacement))
        else:
            out.append(body)
        out.append(raw[match.start():match.end()])
        cursor = match.end()
        in_reasoning = False

    if in_reasoning:
        body = raw[body_start:]
        body_tokens = _compaction_value_tokens(body)
        if body_tokens > threshold_tokens:
            replacement = "\n" + _compaction_reasoning_summary(body, body_tokens) + "\n"
            out.append(replacement)
            # Close a truncated trace so later parsing cannot hide subsequent
            # visible memory or a real tool call after compaction.
            out.append(f"</{opening_name}>")
            summarized_count += 1
            removed_tokens += max(0, body_tokens - _compaction_value_tokens(replacement))
        else:
            out.append(body)
        cursor = len(raw)
    if cursor < len(raw):
        out.append(raw[cursor:])
    return "".join(out), summarized_count, removed_tokens


def compact_oversized_reasoning_message(
    message: dict[str, Any],
    *,
    prompt_capacity_tokens: int,
) -> tuple[dict[str, Any], int, int]:
    """Return a copy with any >1%-of-capacity hidden trace condensed.

    The visible answer or tool outcome remains unchanged. The dedicated reasoning
    field is replaced with compact operational memory, which preserves continuity
    for reasoning-replay endpoints without allowing one early trace to make all
    later history effectively irreducible.
    """
    out = copy.deepcopy(message)
    if str(out.get("role") or "") != "assistant":
        return out, 0, 0
    threshold = max(128, int(max(1, prompt_capacity_tokens) * COMPACTION_OVERSIZED_REASONING_PERCENT / 100.0))
    summarized_count = 0
    removed_tokens = 0

    reasoning = out.get("reasoning_content")
    reasoning_tokens = _compaction_value_tokens(reasoning)
    if reasoning_tokens > threshold:
        replacement = _compaction_reasoning_summary(reasoning, reasoning_tokens)
        out["reasoning_content"] = replacement
        summarized_count += 1
        removed_tokens += max(0, reasoning_tokens - _compaction_value_tokens(replacement))

    content = out.get("content")
    if isinstance(content, str) and content:
        condensed, count, removed = _condense_tagged_reasoning(
            content, threshold_tokens=threshold,
        )
        out["content"] = condensed
        summarized_count += count
        removed_tokens += removed
    return out, summarized_count, removed_tokens


def compaction_summary_budget_tokens(
    *,
    middle_tokens: int,
    target_tokens: int,
    preserved_tokens: int,
) -> int:
    """Size a summary from the reducible middle of the conversation.

    Budgeting only from space left after preserved messages can starve the
    compactor of visible output. Give it enough room to summarize; the candidate
    fit check then decides whether the result achieves the reduction target."""
    middle = max(0, int(middle_tokens))
    desired = int(math.ceil(middle * 0.08))
    desired = int(clamp(
        desired,
        COMPACTION_SUMMARY_MIN_TOKENS,
        COMPACTION_SUMMARY_MAX_TOKENS,
    ))
    # Keep these arguments in the contract and diagnostics even though exact preserved
    # context is deliberately no longer allowed to squeeze the summary back to 128.
    _ = max(0, int(target_tokens)), max(0, int(preserved_tokens))
    return desired


def compaction_model_output_budget_tokens(summary_budget_tokens: int) -> int:
    """Reserve room for reasoning-capable compactors to reach visible Markdown."""
    return int(clamp(
        max(COMPACTION_MODEL_MIN_OUTPUT_TOKENS, int(summary_budget_tokens) * 4),
        COMPACTION_MODEL_MIN_OUTPUT_TOKENS,
        COMPACTION_MODEL_MAX_OUTPUT_TOKENS,
    ))


def _compaction_message_content_text(value: Any) -> str:
    """Extract the textual portion of a normal or multimodal message."""
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        parts: list[str] = []
        for item in value:
            if isinstance(item, dict):
                if str(item.get("type") or "") == "text":
                    parts.append(str(item.get("text") or ""))
                elif item.get("image_url") or item.get("source"):
                    parts.append("[image input omitted from Task memory]")
                else:
                    parts.append(json.dumps(item, ensure_ascii=False, default=str))
            else:
                parts.append(str(item))
        return "\n".join(part for part in parts if part)
    if isinstance(value, dict):
        try:
            return json.dumps(value, ensure_ascii=False, default=str)
        except Exception:
            return str(value)
    return str(value or "")


def _compaction_strip_large_code_blocks(text: str) -> str:
    """Replace large fenced payloads with stable size/language markers."""
    raw = str(text or "")
    fence_re = re.compile(r"(?s)```([^\n`]*)\n(.*?)```")

    def replace_fence(match: re.Match[str]) -> str:
        language = str(match.group(1) or "code").strip() or "code"
        body = str(match.group(2) or "")
        if len(body) <= 480:
            return match.group(0)
        return f"[{language} block omitted from Task memory: {len(body):,} chars]"

    return fence_re.sub(replace_fence, raw)


_COMPACTION_SIGNAL_RE = re.compile(
    r"(?i)\b(error|failed?|failure|exception|warning|passed?|tests?|verify|verified|"
    r"decision|constraint|requirement|must|todo|next action|blocked|complete|completed|"
    r"created|wrote|updated|fixed?|bug|regression|path|file|url|sha256|exit code|"
    r"quality gate|plan|checkpoint|result)\b"
)
_COMPACTION_SECRET_KEY_RE = re.compile(
    r"(?i)(api[_-]?key|api[_-]?token|access[_-]?token|refresh[_-]?token|secret|password|"
    r"authorization|cookie|credential|private[_-]?key)"
)
_COMPACTION_PATH_RE = re.compile(
    r"(?:[A-Za-z]:[\\/][^\s\"'<>|]+|/(?:[^\s\"'<>|]+/)+[^\s\"'<>|]+|https?://[^\s\"'<>]+)"
)


def _compaction_high_signal_excerpt(value: Any, max_chars: int) -> str:
    """Keep first/last and decision/error/test lines while discarding payload bulk."""
    raw = neutralize_tool_protocol_markup_for_memory(
        _compaction_strip_large_code_blocks(_compaction_message_content_text(value))
    )
    lines = [re.sub(r"\s+", " ", line).strip() for line in raw.splitlines()]
    lines = [line for line in lines if line]
    if not lines:
        return ""
    joined = " | ".join(lines)
    limit = max(96, int(max_chars))
    if len(joined) <= limit:
        return joined
    selected: list[int] = [0]
    selected.extend(index for index, line in enumerate(lines) if _COMPACTION_SIGNAL_RE.search(line))
    selected.append(len(lines) - 1)
    ordered: list[int] = []
    seen: set[int] = set()
    for index in selected:
        if index not in seen:
            seen.add(index)
            ordered.append(index)
    # Preserve sequence order while limiting noisy repeated diagnostic lines.
    ordered = sorted(ordered[:10])
    selected_text = " | ".join(lines[index] for index in ordered)
    return _compaction_bounded_excerpt(selected_text or joined, limit)


def _compaction_tool_argument_hint(value: Any, index: int) -> str:
    raw = re.sub(r"\s+", " ", str(value or "")).strip()
    if not raw:
        return f"arg{index}=empty"
    if _COMPACTION_SECRET_KEY_RE.search(raw[:80]):
        return f"arg{index}=[sensitive value omitted]"
    if len(raw) > 220 or "\n" in str(value or ""):
        path_match = _COMPACTION_PATH_RE.search(raw)
        if path_match:
            return f"arg{index}={_compaction_bounded_excerpt(path_match.group(0), 160)}; payload={len(raw):,} chars"
        return f"arg{index}=[payload {len(raw):,} chars]"
    return f"arg{index}={_compaction_bounded_excerpt(raw, 180)}"


def _compaction_tool_call_record(message: dict[str, Any]) -> dict[str, Any] | None:
    """Summarize one native assistant function-call batch for compacted memory."""
    native_calls = message.get("tool_calls") if isinstance(message, dict) else None
    if not isinstance(native_calls, list) or not native_calls:
        return None
    call_parts: list[str] = []
    tool_names: list[str] = []
    for raw_call in native_calls:
        if not isinstance(raw_call, dict):
            continue
        function = raw_call.get("function") if isinstance(raw_call.get("function"), dict) else {}
        name = str(function.get("name") or "tool")
        tool_names.append(name)
        arguments = function.get("arguments")
        if isinstance(arguments, str):
            try:
                parsed = json.loads(arguments)
                arguments = parsed if isinstance(parsed, dict) else {"arguments": arguments}
            except Exception:
                arguments = {"arguments": arguments}
        if not isinstance(arguments, dict):
            arguments = {}
        hints = [
            f"{key}={_compaction_tool_argument_hint(value, index + 1).split('=', 1)[-1]}"
            for index, (key, value) in enumerate(list(arguments.items())[:4])
        ]
        if len(arguments) > 4:
            hints.append(f"+{len(arguments) - 4} args")
        call_parts.append(name + ("(" + "; ".join(hints) + ")" if hints else "()"))
    if not call_parts:
        return None
    prefix = _compaction_high_signal_excerpt(message.get("content"), 320)
    text = ((prefix + " | ") if prefix else "") + "Native tool call(s): " + ", ".join(call_parts)
    return {
        "text": _compaction_bounded_excerpt(text, COMPACTION_LEDGER_ENTRY_MAX_CHARS),
        "priority": 2,
        "tool_names": tool_names,
        "succeeded": 0,
        "failed": 0,
    }


def _compaction_compact_mapping_fields(value: Any, *, max_fields: int = 10) -> list[str]:
    """Extract operational fields from a potentially huge nested tool result."""
    selected: list[str] = []
    key_re = re.compile(
        r"(?i)(path|url|status|message|error|warning|passed|failed|total|count|bytes|sha|"
        r"exit|return|test|demo|marker|result|name|id|duration|elapsed|stdout|stderr|content|text|markdown)"
    )

    def walk(current: Any, prefix: str, depth: int) -> None:
        if len(selected) >= max_fields or depth > 3:
            return
        if isinstance(current, dict):
            priority = sorted(
                current.items(),
                key=lambda item: (0 if key_re.search(str(item[0])) else 1, str(item[0]).casefold()),
            )
            for key, item in priority:
                if len(selected) >= max_fields:
                    break
                key_text = str(key)
                if _COMPACTION_SECRET_KEY_RE.search(key_text) or key_text in _REVIEW_REASONING_FIELDS:
                    continue
                child_prefix = f"{prefix}.{key_text}" if prefix else key_text
                if isinstance(item, (dict, list, tuple)):
                    walk(item, child_prefix, depth + 1)
                elif key_re.search(key_text):
                    selected.append(
                        f"{child_prefix}={_compaction_bounded_excerpt(item, 1200 if key_text in {'stdout', 'stderr', 'text', 'content', 'markdown'} else 220)}"
                    )
        elif isinstance(current, (list, tuple)):
            if current and all(isinstance(item, dict) and "passed" in item for item in current):
                passed = sum(1 for item in current if bool(item.get("passed")))
                selected.append(f"{prefix or 'tests'}={passed}/{len(current)} passed")
                failures = [str(item.get("name") or item.get("error") or "failed") for item in current if not bool(item.get("passed"))]
                if failures:
                    selected.append(f"{prefix or 'tests'}.failures={_compaction_bounded_excerpt('; '.join(failures), 260)}")
                return
            for index, item in enumerate(current[:4]):
                walk(item, f"{prefix}[{index}]", depth + 1)
            if len(current) > 4 and len(selected) < max_fields:
                selected.append(f"{prefix or 'items'}.count={len(current)}")

    walk(value, "", 0)
    return selected[:max_fields]


def _compaction_tool_result_record(message: dict[str, Any]) -> dict[str, Any] | None:
    """Summarize one native role=tool result for compacted memory."""
    if str((message or {}).get("role") or "") != "tool":
        return None
    payload_text = _compaction_message_content_text((message or {}).get("content")).strip()
    payload_text = payload_text.split("\n... [truncated]", 1)[0].strip()
    payload: dict[str, Any] = {}
    try:
        parsed = json.loads(payload_text)
        if isinstance(parsed, dict):
            payload = parsed
    except Exception:
        payload = {}
    tool_name = str(
        (message or {}).get("name")
        or payload.get("tool_name")
        or payload.get("name")
        or "tool"
    )
    ok = payload.get("ok")
    if _tool_result_failure(tool_name, payload.get("result")):
        ok = False
    status = "succeeded" if ok is True else "failed" if ok is False else "reported"
    details: list[str] = []
    for key in ("error", "warning", "velox_message", "message"):
        if payload.get(key) and not _COMPACTION_SECRET_KEY_RE.search(key):
            details.append(f"{key}={_compaction_bounded_excerpt(payload.get(key), 260)}")
    details.extend(_compaction_compact_mapping_fields(payload.get("result"), max_fields=8))
    if not payload and payload_text:
        details.append(_compaction_high_signal_excerpt(payload_text, 480))
    text = f"Tool result {tool_name}: {status}"
    if details:
        text += " | " + "; ".join(part for part in details if part)
    return {
        "text": _compaction_bounded_excerpt(text, COMPACTION_LEDGER_ENTRY_MAX_CHARS),
        "priority": 4 if ok is False else 2,
        "tool_names": [tool_name],
        "succeeded": 1 if ok is True else 0,
        "failed": 1 if ok is False else 0,
    }


def _compaction_record_paths(text: str) -> list[str]:
    paths: list[str] = []
    for match in _COMPACTION_PATH_RE.finditer(str(text or "")):
        value = match.group(0).rstrip(".,;:)]}")
        if value not in paths:
            paths.append(value)
        if len(paths) >= 4:
            break
    return paths


def _pack_compaction_ledger_records(
    records: list[dict[str, Any]],
    *,
    max_tokens: int,
) -> tuple[str, dict[str, Any]]:
    """Pack every sequential record directly or through consecutive event windows."""
    max_chars = max(2_048, int(max_tokens) * 4)
    header = (
        "## Execution facts\n"
        "The following task facts are ordered by execution sequence and record paths, decisions, errors, "
        "test outcomes, tool status, unfinished work, and next actions.\n"
    )
    if not records:
        return header + "\n- No earlier execution facts are recorded.", {
            "source_message_count": 0,
            "ledger_record_count": 0,
            "ledger_window_count": 0,
        }

    direct_lines = [
        f"- Event {index}: {_compaction_bounded_excerpt(record.get('text'), COMPACTION_LEDGER_ENTRY_MAX_CHARS)}"
        for index, record in enumerate(records, 1)
    ]
    direct = header + "\n" + "\n".join(direct_lines)
    if len(direct) <= max_chars:
        return direct, {
            "source_message_count": len(records),
            "ledger_record_count": len(records),
            "ledger_window_count": len(records),
        }

    available = max(768, max_chars - len(header) - 2)
    window_count = min(len(records), max(6, min(32, available // 300)))
    chunk_size = max(1, int(math.ceil(len(records) / max(1, window_count))))
    chunks = [records[start:start + chunk_size] for start in range(0, len(records), chunk_size)]
    per_line = max(160, available // max(1, len(chunks)))
    lines: list[str] = []
    cursor = 1
    for chunk in chunks:
        start_index = cursor
        end_index = cursor + len(chunk) - 1
        cursor = end_index + 1
        tool_counts: dict[str, int] = {}
        succeeded = 0
        failed = 0
        for record in chunk:
            for name in record.get("tool_names") or []:
                tool_counts[str(name)] = tool_counts.get(str(name), 0) + 1
            succeeded += int(record.get("succeeded") or 0)
            failed += int(record.get("failed") or 0)
        chosen_indices = sorted(
            range(len(chunk)),
            key=lambda index: (-int(chunk[index].get("priority") or 0), index),
        )[:3]
        chosen_indices = sorted(set([0, len(chunk) - 1, *chosen_indices]))
        snippets = [
            _compaction_bounded_excerpt(chunk[index].get("text"), 260)
            for index in chosen_indices
            if str(chunk[index].get("text") or "").strip()
        ]
        paths: list[str] = []
        for record in chunk:
            for path in _compaction_record_paths(str(record.get("text") or "")):
                if path not in paths:
                    paths.append(path)
                if len(paths) >= 3:
                    break
            if len(paths) >= 3:
                break
        parts: list[str] = []
        if tool_counts:
            top_tools = sorted(tool_counts.items(), key=lambda item: (-item[1], item[0]))[:6]
            parts.append("tools " + ", ".join(f"{name}×{count}" for name, count in top_tools))
            parts.append(f"results {succeeded} succeeded/{failed} failed")
        if failed:
            failure_details = [
                _compaction_high_signal_excerpt(record.get("text"), 360)
                for record in chunk
                if int(record.get("failed") or 0) > 0
            ]
            failure_details = [detail for detail in failure_details if detail]
            if failure_details:
                # Failure evidence is a dedicated window field rather than one item in
                # the general event excerpt. This prevents a middle failure from being
                # discarded when the window body is tightened to its character budget.
                parts.append("failures: " + " / ".join(failure_details[:3]))
        if snippets:
            parts.append("key events: " + " / ".join(snippets))
        if paths:
            parts.append("paths: " + ", ".join(paths))
        body = "; ".join(parts) or "No material task fact was recorded in this event range"
        lines.append(
            f"- Events {start_index}-{end_index}: "
            + _compaction_bounded_excerpt(body, max(120, per_line - 24))
        )
    ledger = header + "\n" + "\n".join(lines)
    if len(ledger) > max_chars:
        # Tighten every window uniformly while retaining coverage of all windows.
        per_line = max(96, (max_chars - len(header) - len(lines) * 4) // max(1, len(lines)))
        tightened = []
        for line in lines:
            label, _, body = line.partition(": ")
            tightened.append(label + ": " + _compaction_bounded_excerpt(body, per_line))
        ledger = header + "\n" + "\n".join(tightened)
    return ledger[:max_chars].rstrip(), {
        "source_message_count": len(records),
        "ledger_record_count": len(records),
        "ledger_window_count": len(chunks),
    }


def build_compaction_operational_ledger(
    messages: list[dict[str, Any]],
    *,
    prompt_capacity_tokens: int,
    max_tokens: int,
) -> tuple[str, dict[str, Any]]:
    """Create a broad-coverage deterministic first-stage memory for semantic polish.

    Native function-call/result batches become one event, giant payloads become high-value fields,
    and long histories are represented by consecutive windows rather than preserving only
    the first two and newest few messages. The same ledger is a useful fallback when the
    compaction endpoint returns reasoning only or exhausts its output allowance.
    """
    safe_messages: list[dict[str, Any]] = []
    reasoning_count = 0
    reasoning_removed = 0
    for message in messages:
        if not isinstance(message, dict):
            continue
        safe, count, removed = compact_oversized_reasoning_message(
            message, prompt_capacity_tokens=prompt_capacity_tokens,
        )
        if safe.get("role") == "assistant":
            safe = _review_context(safe)
        safe_messages.append(safe)
        reasoning_count += count
        reasoning_removed += removed

    records: list[dict[str, Any]] = []
    index = 0
    while index < len(safe_messages):
        message = safe_messages[index]
        call_record = _compaction_tool_call_record(message)
        if call_record is not None:
            combined = dict(call_record)
            successful_result_texts: list[str] = []
            failed_result_texts: list[str] = []
            next_index = index + 1
            while next_index < len(safe_messages):
                result_record = _compaction_tool_result_record(safe_messages[next_index])
                if result_record is None:
                    break
                result_text = str(result_record.get("text") or "")
                if int(result_record.get("failed") or 0) > 0:
                    failed_result_texts.append(result_text)
                else:
                    successful_result_texts.append(result_text)
                combined["priority"] = max(int(combined.get("priority") or 0), int(result_record.get("priority") or 0))
                combined["tool_names"] = list(dict.fromkeys([
                    *(combined.get("tool_names") or []), *(result_record.get("tool_names") or []),
                ]))
                combined["succeeded"] = int(combined.get("succeeded") or 0) + int(result_record.get("succeeded") or 0)
                combined["failed"] = int(combined.get("failed") or 0) + int(result_record.get("failed") or 0)
                next_index += 1
            if failed_result_texts or successful_result_texts:
                # Put failures first so a bounded event record cannot hide the diagnostic
                # behind a large call description or successful payload metadata.
                combined_parts = [
                    *failed_result_texts,
                    str(combined.get("text") or ""),
                    *successful_result_texts,
                ]
                combined["text"] = _compaction_bounded_excerpt(
                    " | ".join(part for part in combined_parts if part),
                    COMPACTION_LEDGER_ENTRY_MAX_CHARS,
                )
            records.append(combined)
            index = next_index
            continue

        result_record = _compaction_tool_result_record(message)
        if result_record is not None:
            records.append(result_record)
            index += 1
            continue

        role = str(message.get("role") or "message").upper()
        content = _compaction_message_content_text(message.get("content"))
        # Hidden assistant reasoning is intentionally not promoted into durable task
        # memory. It contains candidate explanations and discarded hypotheses;
        # replaying it as a reasoning "outcome" can launder speculation into an
        # apparent fact after compaction. User input, native tool calls/results,
        # visible assistant output, Checklist state, and recent exact tail messages
        # already preserve the useful operational record.
        excerpt = _compaction_high_signal_excerpt(content, 760)
        if not excerpt:
            excerpt = "[empty message]"
        priority = 1
        if role != "ASSISTANT" and _COMPACTION_SIGNAL_RE.search(excerpt):
            priority = 3
        if role == "USER":
            priority = max(priority, 2)
        if excerpt.startswith(TASK_MEMORY_HEADER) or "## Execution facts" in excerpt:
            priority = max(priority, 3)
        role_label = "ASSISTANT CLAIM/PLAN (not independent evidence)" if role == "ASSISTANT" else role
        records.append({
            "text": f"{role_label}: {_compaction_bounded_excerpt(excerpt, COMPACTION_LEDGER_ENTRY_MAX_CHARS)}",
            "priority": priority,
            "tool_names": [],
            "succeeded": 0,
            "failed": 0,
        })
        index += 1

    ledger, metadata = _pack_compaction_ledger_records(records, max_tokens=max_tokens)
    metadata.update({
        "oversized_reasoning_blocks_summarized": reasoning_count,
        "estimated_reasoning_tokens_removed": reasoning_removed,
        "ledger_tokens": _compaction_value_tokens(ledger),
    })
    return ledger, metadata


def compaction_reduction_percent(before_tokens: int, after_tokens: int) -> float:
    before = max(0, int(before_tokens))
    after = max(0, int(after_tokens))
    if before <= 0:
        return 0.0
    return max(0.0, min(100.0, (before - after) * 100.0 / before))


def compaction_leading_system_indices(messages: list[dict[str, Any]]) -> set[int]:
    """Return every consecutive leading system message as irreducible context."""
    result: set[int] = set()
    for index, message in enumerate(messages):
        if str((message or {}).get("role") or "") != "system":
            break
        result.add(index)
    return result


def compaction_message_is_tool_result(message: dict[str, Any]) -> bool:
    return (
        str((message or {}).get("role") or "") == "tool"
        and bool(str((message or {}).get("tool_call_id") or "").strip())
    )


def compaction_message_is_tool_call(message: dict[str, Any]) -> bool:
    return (
        str((message or {}).get("role") or "") == "assistant"
        and (bool((message or {}).get("tool_calls")) or any(
            isinstance(item, dict) and item.get("type") == "function_call"
            for item in (message or {}).get("response_output_items", [])
        ))
    )


def expand_compaction_preserved_tool_pairs(
    messages: list[dict[str, Any]], preserved_indices: Iterable[int],
) -> set[int]:
    """Keep each assistant call and its consecutive tool results atomically.

    This covers native Chat Completions assistant ``tool_calls`` with matching
    role=``tool`` results. A preserved
    tail can begin inside a multi-call result batch. Sending a tool result
    without the assistant call that caused it, or a call without its returned results,
    breaks provider role semantics and can make the next model repeat a completed action.
    Expand to the nearest complete call/result boundary until the set is stable.
    """
    total = len(messages)
    preserved = {int(index) for index in preserved_indices if 0 <= int(index) < total}
    changed = True
    while changed:
        changed = False
        for index in tuple(sorted(preserved)):
            if compaction_message_is_tool_result(messages[index]):
                call_index = index - 1
                while call_index >= 0 and compaction_message_is_tool_result(messages[call_index]):
                    call_index -= 1
                if call_index >= 0 and compaction_message_is_tool_call(messages[call_index]):
                    if call_index not in preserved:
                        preserved.add(call_index)
                        changed = True
                    result_index = call_index + 1
                    while result_index < total and compaction_message_is_tool_result(messages[result_index]):
                        if result_index not in preserved:
                            preserved.add(result_index)
                            changed = True
                        result_index += 1
            elif compaction_message_is_tool_call(messages[index]):
                result_index = index + 1
                while result_index < total and compaction_message_is_tool_result(messages[result_index]):
                    if result_index not in preserved:
                        preserved.add(result_index)
                        changed = True
                    result_index += 1
    return preserved


def chat_compaction_message_is_substantive_user_request(message: dict[str, Any]) -> bool:
    """Exclude synthetic control/result messages when locating the active user task."""
    if str((message or {}).get("role") or "") != "user":
        return False
    if message.get("_velox_synthetic_context"):
        return False
    if bool((message or {}).get(CURRENT_CONTEXT_VISION_MESSAGE_MARKER)):
        return False
    content = str((message or {}).get("content") or "").strip()
    if not content:
        return False
    if message.get("_velox_substantive_user"):
        return True
    if content.startswith((
        "CHECKLISTS - CONTINUE", "CURRENT CHECKLISTS PROGRESS",
        "VELOX IMAGE LINK VALIDATION FAILED.",
        CHAT_APP_CONTEXT_DATE_HEADER, CHAT_APP_CONTEXT_DOCS_HEADER,
        CHAT_APP_CONTEXT_HISTORY_HEADER, CHAT_APP_CONTEXT_CALENDAR_HEADER, CHAT_APP_CONTEXT_STOP_HEADER,
    )):
        return False
    if content.startswith(TASK_MEMORY_HEADER):
        return False
    if content.startswith("VELOX DID NOT EXECUTE THAT ATTEMPTED TOOL CALL:"):
        return False
    return True

