def normalize_endpoint_model_type(value: Any) -> str:
    key = str(value or ENDPOINT_MODEL_TYPE_CUSTOM).strip().lower()
    return key if key in ENDPOINT_MODEL_TYPES else ENDPOINT_MODEL_TYPE_CUSTOM


def endpoint_api_transport_default(model_type: Any) -> str:
    return (
        ENDPOINT_API_TRANSPORT_RESPONSES
        if normalize_endpoint_model_type(model_type) in ENDPOINT_GPT_MODEL_TYPES
        else ENDPOINT_API_TRANSPORT_CHAT_COMPLETIONS
    )


def normalize_endpoint_api_transport(value: Any, model_type: Any = ENDPOINT_MODEL_TYPE_CUSTOM) -> str:
    raw = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "chat": ENDPOINT_API_TRANSPORT_CHAT_COMPLETIONS,
        "chat_completion": ENDPOINT_API_TRANSPORT_CHAT_COMPLETIONS,
        "chat_completions_v1": ENDPOINT_API_TRANSPORT_CHAT_COMPLETIONS,
        "completions": ENDPOINT_API_TRANSPORT_CHAT_COMPLETIONS,
        "response": ENDPOINT_API_TRANSPORT_RESPONSES,
        "responses_api": ENDPOINT_API_TRANSPORT_RESPONSES,
    }
    raw = aliases.get(raw, raw)
    return raw if raw in ENDPOINT_API_TRANSPORTS else endpoint_api_transport_default(model_type)


def endpoint_api_transport(profile: dict[str, Any] | None) -> str:
    profile = profile if isinstance(profile, dict) else {}
    return normalize_endpoint_api_transport(profile.get("api_transport"), profile.get("model_type"))


def endpoint_provider_default_from_url(url: Any) -> str:
    try:
        host = (urllib.parse.urlsplit(str(url or "")).hostname or "").lower().rstrip(".")
    except Exception:
        host = ""
    if host == "novita.ai" or host.endswith(".novita.ai"):
        return ENDPOINT_PROVIDER_NOVITA
    if host == "baseten.co" or host.endswith(".baseten.co"):
        return ENDPOINT_PROVIDER_BASETEN
    if host == "api.openai.com" or host.endswith(".openai.com"):
        return ENDPOINT_PROVIDER_OPENAI
    if endpoint_host_is_local(str(url or "")):
        # Existing bundled local endpoints are vLLM. llama.cpp is explicit so its
        # provider-specific request behavior is never guessed from a loopback URL.
        return ENDPOINT_PROVIDER_VLLM
    return ENDPOINT_PROVIDER_GENERIC


def normalize_endpoint_provider(value: Any, base_url: Any = "") -> str:
    """Return an explicit provider type.

    New profiles may infer a missing value. Persisted profiles must name a
    supported provider; the generic ``local`` value is not an alias."""
    raw = str(value or "").strip().lower()
    if not raw:
        return endpoint_provider_default_from_url(base_url)
    return raw if raw in ENDPOINT_PROVIDERS else ENDPOINT_PROVIDER_GENERIC


def endpoint_provider(profile: dict[str, Any] | None) -> str:
    profile = profile if isinstance(profile, dict) else {}
    return normalize_endpoint_provider(profile.get("provider"), profile.get("base_url"))


def endpoint_default_max_concurrent_requests(provider: Any) -> int:
    key = normalize_endpoint_provider(provider)
    return (
        ENDPOINT_MAX_CONCURRENT_LOCAL_DEFAULT
        if key in {ENDPOINT_PROVIDER_VLLM, ENDPOINT_PROVIDER_LLAMA_CPP}
        else ENDPOINT_MAX_CONCURRENT_HOSTED_DEFAULT
    )


def endpoint_default_rate_limit_enabled(provider: Any) -> bool:
    """Enable commercial-provider protection only where it is useful by default."""
    return normalize_endpoint_provider(provider) in {
        ENDPOINT_PROVIDER_NOVITA, ENDPOINT_PROVIDER_BASETEN,
    }


def endpoint_max_concurrent_requests(profile: dict[str, Any] | None) -> int:
    profile = profile if isinstance(profile, dict) else {}
    provider_key = endpoint_provider(profile)
    return bounded_positive_int(
        profile.get("max_concurrent_requests"),
        endpoint_default_max_concurrent_requests(provider_key),
        minimum=ENDPOINT_MAX_CONCURRENT_REQUESTS_MIN,
        maximum=None,
    )


