def endpoint_reasoning_level_options(model_type: Any) -> tuple[tuple[str, str], ...]:
    key = normalize_endpoint_model_type(model_type)
    return ENDPOINT_REASONING_LEVEL_OPTIONS.get(key, ENDPOINT_REASONING_LEVEL_OPTIONS[ENDPOINT_MODEL_TYPE_CUSTOM])


def endpoint_reasoning_level_default(model_type: Any) -> str:
    key = normalize_endpoint_model_type(model_type)
    return str(ENDPOINT_REASONING_LEVEL_DEFAULTS.get(key, ""))


def normalize_endpoint_reasoning_level(model_type: Any, value: Any) -> str:
    key = normalize_endpoint_model_type(model_type)
    raw = str(value or "").strip().lower()
    aliases = {
        "enabled": "on", "disabled": "off", "true": "on", "false": "off",
    }
    raw = aliases.get(raw, raw)
    allowed = {item[0] for item in endpoint_reasoning_level_options(key)}
    return raw if raw in allowed else endpoint_reasoning_level_default(key)


def endpoint_effective_reasoning_level(profile: dict[str, Any] | None, override: Any = None) -> str:
    profile = profile if isinstance(profile, dict) else {}
    model_type = normalize_endpoint_model_type(profile.get("model_type"))
    configured = normalize_endpoint_reasoning_level(model_type, profile.get("reasoning_effort"))
    if override is None or not str(override).strip():
        return configured
    raw = str(override).strip().lower()
    if model_type in {
        ENDPOINT_MODEL_TYPE_DEEPSEEK_V4,
        ENDPOINT_MODEL_TYPE_DEEPSEEK_V4_FLASH_VISION_EXP,
        ENDPOINT_MODEL_TYPE_GLM_5_3_FLASH,
    }:
        if raw in {"none", "minimal", "off"}:
            return "low"
        if raw in {"medium", "xhigh"}:
            return "high"
        return normalize_endpoint_reasoning_level(model_type, raw)
    if model_type in {ENDPOINT_MODEL_TYPE_QWEN_3_6, ENDPOINT_MODEL_TYPE_GEMMA_4}:
        return "off" if raw in {"none", "minimal", "low", "off"} else "on"
    if model_type in {ENDPOINT_MODEL_TYPE_QWEN_3_8, ENDPOINT_MODEL_TYPE_QWEN_3_8_FLASH_NEXT}:
        if raw in {"none", "minimal", "off", "low"}:
            return "low"
        if raw in {"medium"}:
            return "medium"
        return "xhigh"
    if model_type == ENDPOINT_MODEL_TYPE_KIMI_K2_6:
        return "on"
    if model_type == ENDPOINT_MODEL_TYPE_KIMI_K3:
        return "max"
    if model_type == ENDPOINT_MODEL_TYPE_MUSE_GLIMMER:
        return normalize_endpoint_reasoning_level(model_type, raw)
    return raw if raw in ENDPOINT_REASONING_EFFORT_VALUES else configured


def endpoint_model_type_defaults(model_type: Any) -> dict[str, Any]:
    """Return provider-recommended defaults for one supported model family.

    These are presets rather than hidden runtime overrides. The editor writes the
    values into the profile, and the user can change or clear every optional
    generation parameter afterward.
    """
    key = normalize_endpoint_model_type(model_type)
    common: dict[str, Any] = {
        "model_type": key,
        "api_transport": endpoint_api_transport_default(key),
        "model": "",
        "context_window_tokens": int(AGENT_CONTEXT_WINDOW_TOKENS_DEFAULT),
        "max_output_tokens": 32768,
        "vision_max_width": 4096,
        "vision_max_height": 4096,
        "max_image_inputs_per_prompt": 5,
        "vision": "auto",

        "preserve_thinking": False,
        "temperature": None,
        "top_p": None,
        "min_p": None,
        "top_k": None,
        "presence_penalty": None,
        "frequency_penalty": None,
        "repetition_penalty": None,
        "seed": None,
        "stop_sequences": [],
        "reasoning_effort": "",
        "extra_body_json": "",
        "system_prompt_addon": "",
    }
    if key == ENDPOINT_MODEL_TYPE_QWEN_3_6:
        common.update({
            "model": "Qwen/Qwen3.6-27B",
            "context_window_tokens": 98304,
            "max_output_tokens": 16384,
            "vision_max_width": 4096,
            "vision_max_height": 4096,
            "max_image_inputs_per_prompt": 5,
            "vision": "enabled",
            "preserve_thinking": False,
            "reasoning_effort": "off",
            "temperature": 1.0,
            "top_p": 0.95,
            "min_p": 0.0,
            "top_k": 20,
            "presence_penalty": 0.0,
            "repetition_penalty": 1.0,
        })
    elif key == ENDPOINT_MODEL_TYPE_QWEN_3_8:
        # Qwen3.8-27B is a native vision-language model. Its official model
        # card documents a 262,144-token native context, xhigh/medium/low
        # reasoning_effort controls, preserved thinking by default, and the
        # sampling values below for thinking-mode generation.
        common.update({
            "model": "Qwen/Qwen3.8-27B",
            "context_window_tokens": 262144,
            "max_output_tokens": 65536,
            "vision_max_width": 4096,
            "vision_max_height": 4096,
            "max_image_inputs_per_prompt": 32,
            "vision": "enabled",
            "preserve_thinking": True,
            "reasoning_effort": "xhigh",
            "temperature": 1.0,
            "top_p": 0.95,
            "min_p": 0.0,
            "top_k": 20,
            "presence_penalty": 0.0,
            "repetition_penalty": 1.0,
        })
    elif key == ENDPOINT_MODEL_TYPE_QWEN_3_8_FLASH_NEXT:
        # Qwen3.8-Flash-Next is a multimodal thinking model with a native
        # 262,144-token native context. The profile requests a 512K client budget and
        # 128K generation reserve; local servers must enable YaRN factor 2.0
        # and --max-model-len 524288. These fields cannot reconfigure a server.
        # Sampling, xhigh effort and preserved reasoning follow the model card.
        common.update({
            "model": "Qwen/Qwen3.8-Flash-Next",
            "context_window_tokens": DEFAULT_AGENTIC_CONTEXT_TOKENS,
            "max_output_tokens": DEFAULT_AGENTIC_OUTPUT_TOKENS,
            "vision_max_width": 4096,
            "vision_max_height": 4096,
            "max_image_inputs_per_prompt": 32,
            "vision": "enabled",
            "preserve_thinking": True,
            "reasoning_effort": "xhigh",
            "temperature": 1.0,
            "top_p": 0.95,
            "min_p": 0.0,
            "top_k": 20,
            "presence_penalty": 0.0,
            "repetition_penalty": 1.0,
        })
    elif key == ENDPOINT_MODEL_TYPE_KIMI_K2_6:
        # Kimi K2.6 thinking is enabled by default and its documented API does
        # not permit callers to modify temperature. Leave all sampling fields
        # unset so compatible hosted services and local vLLM chat templates
        # apply the model defaults. Preserved Thinking remains an
        # explicit profile choice because tool loops must replay reasoning_content.
        common.update({
            "model": "moonshotai/Kimi-K2.6",
            "context_window_tokens": 196608,
            "max_output_tokens": 65536,
            "max_image_inputs_per_prompt": 5,
            "vision": "enabled",
            "preserve_thinking": True,
            "reasoning_effort": "on",
        })
    elif key == ENDPOINT_MODEL_TYPE_KIMI_K3:
        # K3 always reasons and requires reasoning_content to survive tool-call
        # loops. Leave family-level sampling unset because hosted providers differ;
        # bundled profiles may store provider-specific editable defaults.
        common.update({
            "model": "moonshotai/kimi-k3",
            "context_window_tokens": 524288,
            "max_output_tokens": 131072,
            "max_image_inputs_per_prompt": 5,
            "vision": "enabled",
            "preserve_thinking": True,
            "reasoning_effort": "max",
        })
    elif key == ENDPOINT_MODEL_TYPE_GLM_5_3_FLASH:
        # Model/API sources: huggingface.co/zai-org/GLM-5.3-Flash and
        # docs.z.ai/guides/vlm/glm-5.3-flash; Novita advertises 1M context
        # and 128K output. Use a conservative decimal 1M hosted budget rather
        # than assuming the native 1,048,576-token model limit is served.
        # GLM always reasons: low/high/max control its budget, not an off mode.
        # Preserve exact thinking for Velox's coding/agent/tool workflows.
        # Five images and 4096px bounds are editable Velox limits, not claims
        # about provider maxima. Native image-analysis routing avoids fallback.
        common.update({
            "model": "zai-org/GLM-5.3-Flash",
            "context_window_tokens": DEFAULT_AGENTIC_CONTEXT_TOKENS,
            "max_output_tokens": DEFAULT_AGENTIC_OUTPUT_TOKENS,
            "vision": "enabled",
            "preserve_thinking": True,
            "reasoning_effort": "max",
            "temperature": 1.0,
            "top_p": 0.95,
        })
    elif key == ENDPOINT_MODEL_TYPE_DEEPSEEK_V4:
        # DeepSeek's model card recommends temperature 1.0 and top_p 0.95 for
        # agentic workloads, max reasoning effort, and preservation of
        # reasoning_content across tool-call rounds. The bundled local profile
        # uses a 1,000,000-token configured total context and reserves at most 256K for generated output,
        # leaving a 737,856-token configured prompt budget before provider framing and safety reserve.
        common.update({
            "model": "model",
            "context_window_tokens": DEFAULT_AGENTIC_CONTEXT_TOKENS,
            "max_output_tokens": DEFAULT_AGENTIC_OUTPUT_TOKENS,
            "vision": "disabled",
            "preserve_thinking": True,
            "temperature": 1.0,
            "top_p": 0.95,
            "reasoning_effort": "max",
        })
    elif key == ENDPOINT_MODEL_TYPE_DEEPSEEK_V4_FLASH_VISION_EXP:
        # DeepSeek-V4-Flash-Vision-Exp is the experimental multimodal
        # DeepSeek V4 Flash deployment. vLLM receives ordinary OpenAI
        # image_url content blocks and performs native processor/ViT/aligner
        # handling before merging visual embeddings into the V4 decoder.
        # The bundled profile permits up to 256 ordered image inputs per
        # request; vLLM receives each image as one intact multimodal item.
        common.update({
            "model": "deepseek-ai/DeepSeek-V4-Flash-Vision-Exp",
            "context_window_tokens": DEFAULT_AGENTIC_CONTEXT_TOKENS,
            "max_output_tokens": DEFAULT_AGENTIC_OUTPUT_TOKENS,
            "vision_max_width": 4096,
            "vision_max_height": 4096,
            "max_image_inputs_per_prompt": 256,
            "vision": "enabled",
            "preserve_thinking": True,
            "temperature": 1.0,
            "top_p": 0.95,
            "reasoning_effort": "max",
        })
    elif key == ENDPOINT_MODEL_TYPE_GEMMA_4:
        # Google's Gemma 4 model card recommends temperature 1.0, top_p 0.95,
        # and top_k 64. The 26B A4 QAT profile is multimodal; Gemma 4
        # thinking is off by default and may be explicitly enabled. Previous
        # thoughts are replayed only for tool-call turns while thinking is on.
        common.update({
            "model": "model",
            "context_window_tokens": 65536,
            "max_output_tokens": 32768,
            "vision_max_width": 1920,
            "vision_max_height": 1080,
            "max_image_inputs_per_prompt": 5,
            "vision": "enabled",
            "preserve_thinking": False,
            "reasoning_effort": "off",
            "temperature": 1.0,
            "top_p": 0.95,
            "top_k": 64,
        })
    elif key == ENDPOINT_MODEL_TYPE_GPT_5_2:
        common.update({
            "model": "gpt-5.2",
            "api_transport": ENDPOINT_API_TRANSPORT_RESPONSES,
            "context_window_tokens": 400000,
            "max_output_tokens": 128000,
            "max_image_inputs_per_prompt": 5,
            "vision": "enabled",
            "preserve_thinking": False,
            "reasoning_effort": "xhigh",
        })
    elif key == ENDPOINT_MODEL_TYPE_GPT_5_4:
        # The built-in preset uses a 400K
        # context budget even though OpenAI publishes a larger service maximum.
        common.update({
            "model": "gpt-5.4",
            "api_transport": ENDPOINT_API_TRANSPORT_RESPONSES,
            "context_window_tokens": 400000,
            "max_output_tokens": 128000,
            "max_image_inputs_per_prompt": 5,
            "vision": "enabled",
            "preserve_thinking": False,
            "reasoning_effort": "xhigh",
        })
    elif key == ENDPOINT_MODEL_TYPE_GPT_5_6_SOL:
        common.update({
            "model": "gpt-5.6-sol",
            "api_transport": ENDPOINT_API_TRANSPORT_RESPONSES,
            "context_window_tokens": 1050000,
            "max_output_tokens": 128000,
            "max_image_inputs_per_prompt": 5,
            "vision": "enabled",
            "preserve_thinking": False,
            "reasoning_effort": "xhigh",
        })
    elif key == ENDPOINT_MODEL_TYPE_GPT_5_6_LUNA:
        common.update({
            "model": "gpt-5.6-luna",
            "api_transport": ENDPOINT_API_TRANSPORT_RESPONSES,
            "context_window_tokens": 1050000,
            "max_output_tokens": 128000,
            "max_image_inputs_per_prompt": 5,
            "vision": "enabled",
            "preserve_thinking": False,
            "reasoning_effort": "xhigh",
        })
    elif key == ENDPOINT_MODEL_TYPE_MUSE_GLIMMER:
        # Muse Glimmer's official release documents a 128K-class context,
        # multimodal tool calling, OpenAI-compatible Chat Completions serving,
        # and a chat-template reasoning_strength control. Native OpenAI function
        # calling is therefore the family default; sampling values below are
        # editable Velox presets rather than claims about immutable model defaults.
        common.update({
            "model": "meta-models/Muse-Glimmer-30B",
            "context_window_tokens": 131072,
            "max_output_tokens": 32768,
            "max_image_inputs_per_prompt": 5,
            "vision": "enabled",
            "preserve_thinking": False,
            "reasoning_effort": "high",
            "temperature": 1.0,
            "top_p": 0.95,
            "top_k": 64,
        })
    common["token_estimate_chars_per_token"] = (
        3.2 if key == ENDPOINT_MODEL_TYPE_GLM_5_3_FLASH else 4.0
    )
    return common


def endpoint_model_type_preserves_reasoning(profile: dict[str, Any] | None, override: Any = None) -> bool:
    profile = profile if isinstance(profile, dict) else {}
    model_type = normalize_endpoint_model_type(profile.get("model_type"))
    level = endpoint_effective_reasoning_level(profile, override)
    if model_type == ENDPOINT_MODEL_TYPE_KIMI_K3:
        return True
    if model_type in {
        ENDPOINT_MODEL_TYPE_KIMI_K2_6, ENDPOINT_MODEL_TYPE_DEEPSEEK_V4,
        ENDPOINT_MODEL_TYPE_GLM_5_3_FLASH,
        ENDPOINT_MODEL_TYPE_DEEPSEEK_V4_FLASH_VISION_EXP,
        ENDPOINT_MODEL_TYPE_QWEN_3_8, ENDPOINT_MODEL_TYPE_QWEN_3_8_FLASH_NEXT,
    }:
        return bool(profile.get("preserve_thinking", True))
    if model_type in {ENDPOINT_MODEL_TYPE_QWEN_3_6, ENDPOINT_MODEL_TYPE_GEMMA_4}:
        return level == "on" and bool(profile.get("preserve_thinking", False))
    if model_type == ENDPOINT_MODEL_TYPE_MUSE_GLIMMER:
        return bool(profile.get("preserve_thinking", False))
    return bool(profile.get("preserve_thinking", False))


def endpoint_max_image_inputs(profile: dict[str, Any] | None) -> int:
    profile = profile if isinstance(profile, dict) else {}
    defaults = endpoint_model_type_defaults(profile.get("model_type"))
    return bounded_positive_int(
        profile.get("max_image_inputs_per_prompt"),
        defaults.get("max_image_inputs_per_prompt", 5),
        minimum=1, maximum=None,
    )


def message_image_input_count(messages: list[dict[str, Any]] | None) -> int:
    count = 0
    for message in messages or []:
        if not isinstance(message, dict):
            continue
        content = message.get("content")
        parts = content if isinstance(content, list) else []
        for part in parts:
            if not isinstance(part, dict):
                continue
            if (
                str(part.get("type") or "").strip().lower()
                in {"image_url", "input_image", "image"}
                or "image_url" in part
            ):
                count += 1
    return count


def prepend_endpoint_system_prompt_addon(
    messages: list[dict[str, Any]] | None,
    profile: dict[str, Any] | None,
) -> list[dict[str, Any]]:
    """Return a request-local message list with the endpoint add-on first."""
    current = list(messages or [])
    if current and current[0].get("_velox_endpoint_prompt_frozen") is True:
        return current
    addon = str((profile or {}).get("system_prompt_addon") or "").strip()
    if not addon:
        return current
    return [{"role": "system", "content": addon}] + current


def endpoint_vision_dimensions(profile: dict[str, Any] | None) -> tuple[int, int]:
    """Return the user-configured maximum image dimensions for one endpoint."""
    profile = profile if isinstance(profile, dict) else {}
    model_type = normalize_endpoint_model_type(profile.get("model_type"))
    defaults = endpoint_model_type_defaults(model_type)
    width = bounded_positive_int(
        profile.get("vision_max_width"), defaults.get("vision_max_width", 4096),
        minimum=64, maximum=32768,
    )
    height = bounded_positive_int(
        profile.get("vision_max_height"), defaults.get("vision_max_height", 4096),
        minimum=64, maximum=32768,
    )
    return width, height


def endpoint_output_token_field(
    profile: dict[str, Any] | None,
    provider: str = "",
) -> str:
    """Choose the provider-compatible Chat Completions output-limit field."""
    profile = profile if isinstance(profile, dict) else {}
    model_type = normalize_endpoint_model_type(profile.get("model_type"))
    if model_type in ENDPOINT_GPT_MODEL_TYPES:
        return "max_completion_tokens"
    return "max_tokens"

def normalize_http_user_agent(value: Any, fallback: str = "") -> str:
    """Return one safe HTTP User-Agent value, rejecting header injection."""
    raw = _strip_matching_outer_quotes(value).strip()
    if not raw:
        raw = str(fallback or "").strip()
    if any(ord(ch) < 32 or ord(ch) == 127 for ch in raw):
        raise ValueError("User-Agent contains a control character or line break")
    if len(raw) > 4096:
        raise ValueError("User-Agent is unreasonably long (maximum 4096 characters)")
    return raw


def endpoint_user_agent(profile: dict[str, Any] | None) -> str:
    profile = profile if isinstance(profile, dict) else {}
    mode = str(profile.get("user_agent_mode") or "generic").strip().lower()
    if mode == "custom":
        value = normalize_http_user_agent(profile.get("custom_user_agent"), "")
        if not value:
            raise ValueError("Custom endpoint User-Agent is selected but no value is configured")
        return value
    return ENDPOINT_GENERIC_USER_AGENT


def web_user_agent(mode: Any) -> str:
    key = str(mode or "desktop_firefox").strip().lower()
    if key not in WEB_USER_AGENT_STRINGS:
        key = "desktop_firefox"
    return WEB_USER_AGENT_STRINGS[key]


def web_request_headers(
    mode: Any,
    *,
    accept: str,
    referer: str = "",
) -> dict[str, str]:
    """Generate coherent browser/crawler headers for the selected web-tool UA."""
    key = str(mode or "desktop_firefox").strip().lower()
    if key not in WEB_USER_AGENT_STRINGS:
        key = "desktop_firefox"
    headers = {
        "User-Agent": web_user_agent(key),
        "Accept": str(accept or "*/*"),
        "Accept-Language": "en-US,en;q=0.9",
        "Accept-Encoding": "gzip, deflate",
        "Connection": "close",
    }
    if key == "googlebot":
        # Googlebot is a crawler, not an interactive browser. Browser navigation
        # and privacy headers would make the signature internally inconsistent.
        headers["Accept-Language"] = "en-US,en;q=0.8"
    else:
        headers.update({
            "Upgrade-Insecure-Requests": "1",
            "Sec-Fetch-Dest": "document",
            "Sec-Fetch-Mode": "navigate",
            "Sec-Fetch-Site": "none",
            "Sec-Fetch-User": "?1",
            "DNT": "1",
        })
    if referer:
        headers["Referer"] = str(referer)
    return headers


ENDPOINT_IMAGE_ANALYSIS_CONTEXTS = ("inline", "separate")
ENDPOINT_DEFAULTS_DESCRIPTION = (
    "One default for new chats and unscoped agents. Existing tasks retain their endpoint; "
    "image analysis always uses the requesting task's endpoint."
)


def endpoint_default_image_analysis_context(provider: Any) -> str:
    """Context policy is a provider default, independent of vision capability."""
    return "inline" if str(provider or "").strip().lower() == ENDPOINT_PROVIDER_VLLM else "separate"


def default_endpoint_profile(
    profile_id: str,
    label: str,
    *,
    timeout_seconds: int,
    base_url: str = "http://127.0.0.1:8090/v1/chat/completions",
    api_key: str = "",
    model: str | None = None,
    model_type: str = ENDPOINT_MODEL_TYPE_CUSTOM,
    provider: str | None = None,
    max_concurrent_requests: int | None = None,
) -> dict[str, Any]:
    provider_key = normalize_endpoint_provider(provider, base_url)
    profile: dict[str, Any] = {
        "id": str(profile_id),
        "label": str(label),
        "provider": provider_key,
        "max_concurrent_requests": int(
            max_concurrent_requests
            if max_concurrent_requests is not None
            else endpoint_default_max_concurrent_requests(provider_key)
        ),
        "base_url": str(base_url),
        "api_key": str(api_key),
        "timeout_seconds": int(timeout_seconds),
        "context_recovery_attempts": CONTEXT_OVERFLOW_RECOVERY_MAX_ATTEMPTS,
        "adaptive_token_estimation": True,
        "rate_limit_enabled": endpoint_default_rate_limit_enabled(provider_key),
        "rate_limit_requests_per_minute": ENDPOINT_RATE_LIMIT_REQUESTS_PER_MINUTE_DEFAULT,
        "error_recovery_enabled": True,
        "error_recovery_attempts": ENDPOINT_ERROR_RECOVERY_ATTEMPTS_DEFAULT,
        "error_recovery_delay_seconds": ENDPOINT_ERROR_RECOVERY_DELAY_SECONDS_DEFAULT,
        "user_agent_mode": "generic",
        "custom_user_agent": "",
    }
    profile.update(endpoint_model_type_defaults(model_type))
    profile["image_analysis_context"] = endpoint_default_image_analysis_context(provider_key)
    if model is not None:
        profile["model"] = str(model)
    return profile


