def _optional_finite_float(
    value: Any,
    field_name: str,
    *,
    minimum: float | None = None,
    maximum: float | None = None,
) -> float | None:
    if value is None or (isinstance(value, str) and not value.strip()):
        return None
    try:
        number = float(value)
    except Exception as exc:
        raise ValueError(f"{field_name} must be a finite number or blank") from exc
    if not math.isfinite(number):
        raise ValueError(f"{field_name} must be a finite number or blank")
    if minimum is not None and number < minimum:
        raise ValueError(f"{field_name} must be at least {minimum}")
    if maximum is not None and number > maximum:
        raise ValueError(f"{field_name} must be at most {maximum}")
    return number


def _optional_finite_int(value: Any, field_name: str, *, minimum: int | None = None) -> int | None:
    if value is None or (isinstance(value, str) and not value.strip()):
        return None
    try:
        number = int(str(value).strip())
    except Exception as exc:
        raise ValueError(f"{field_name} must be an integer or blank") from exc
    if minimum is not None and number < minimum:
        raise ValueError(f"{field_name} must be at least {minimum}")
    return number


def parse_endpoint_extra_body(value: Any) -> dict[str, Any]:
    raw = str(value or "").strip()
    if not raw:
        return {}
    try:
        parsed = json.loads(raw)
    except Exception as exc:
        raise ValueError(f"Extra body JSON is invalid: {exc}") from exc
    if not isinstance(parsed, dict):
        raise ValueError("Extra body JSON must be a JSON object")
    blocked = sorted(str(key) for key in parsed if str(key).lower() in ENDPOINT_EXTRA_BODY_RESERVED_FIELDS)
    if blocked:
        raise ValueError("Extra body JSON cannot override: " + ", ".join(blocked))
    return parsed


def normalize_endpoint_profile(profile: Any, *, location: str = "endpoint profile") -> dict[str, Any]:
    if not isinstance(profile, dict):
        raise ValueError(f"{location} must be an object")
    expected = set(ENDPOINT_PROFILE_USER_FIELDS)
    actual = set(profile)
    missing = sorted(expected - actual)
    extra = sorted(actual - expected)
    if missing or extra:
        details = []
        if missing:
            details.append("missing: " + ", ".join(missing))
        if extra:
            details.append("unexpected: " + ", ".join(extra))
        raise ValueError(f"{location} fields are invalid ({'; '.join(details)})")
    out = copy.deepcopy(profile)
    out["id"] = str(out.get("id") or "").strip()
    out["label"] = str(out.get("label") or "").strip()
    if not out["id"]:
        raise ValueError(f"{location}.id is required")
    if not out["label"]:
        raise ValueError(f"{location}.label is required")
    raw_provider = str(out.get("provider") or "").strip().lower()
    if raw_provider not in ENDPOINT_PROVIDERS:
        raise ValueError(
            f"{location}.provider must be one of: {', '.join(ENDPOINT_PROVIDERS)}"
        )
    out["provider"] = raw_provider
    out["max_concurrent_requests"] = bounded_positive_int(
        out.get("max_concurrent_requests"),
        endpoint_default_max_concurrent_requests(out["provider"]),
        minimum=ENDPOINT_MAX_CONCURRENT_REQUESTS_MIN,
        maximum=None,
    )
    out["model_type"] = normalize_endpoint_model_type(out.get("model_type"))
    out["api_transport"] = normalize_endpoint_api_transport(
        out.get("api_transport"), out["model_type"],
    )
    out["base_url"] = _strip_matching_outer_quotes(out.get("base_url")).strip()
    out["api_key"] = str(out.get("api_key") or "").strip()
    out["model"] = _strip_matching_outer_quotes(out.get("model")).strip()
    out["timeout_seconds"] = bounded_positive_int(out.get("timeout_seconds"), ENDPOINT_TIMEOUT_SECONDS_DEFAULT, minimum=1, maximum=None)
    try:
        context_retries = int(str(out.get("context_recovery_attempts")).strip())
    except (TypeError, ValueError) as exc:
        raise ValueError("context_recovery_attempts must be an integer from 0 to 10") from exc
    if isinstance(out.get("context_recovery_attempts"), bool) or not 0 <= context_retries <= 10:
        raise ValueError("context_recovery_attempts must be an integer from 0 to 10")
    out["context_recovery_attempts"] = context_retries
    try:
        chars_per_token = float(str(out.get("token_estimate_chars_per_token")).strip())
    except (TypeError, ValueError) as exc:
        raise ValueError("token_estimate_chars_per_token must be between 0.25 and 8") from exc
    if not math.isfinite(chars_per_token) or not 0.25 <= chars_per_token <= 8:
        raise ValueError("token_estimate_chars_per_token must be between 0.25 and 8")
    out["token_estimate_chars_per_token"] = chars_per_token
    if not isinstance(out.get("adaptive_token_estimation"), bool):
        raise ValueError("adaptive_token_estimation must be a boolean")
    if not isinstance(out.get("rate_limit_enabled"), bool):
        raise ValueError("rate_limit_enabled must be a boolean")
    out["rate_limit_enabled"] = bool(out.get("rate_limit_enabled"))
    try:
        requests_per_minute = int(str(out.get("rate_limit_requests_per_minute")).strip())
    except Exception as exc:
        raise ValueError("rate_limit_requests_per_minute must be an integer") from exc
    if (
        isinstance(out.get("rate_limit_requests_per_minute"), bool)
        or not 1 <= requests_per_minute <= ENDPOINT_RATE_LIMIT_REQUESTS_PER_MINUTE_MAX
    ):
        raise ValueError(
            "rate_limit_requests_per_minute must be between 1 and "
            f"{ENDPOINT_RATE_LIMIT_REQUESTS_PER_MINUTE_MAX}"
        )
    out["rate_limit_requests_per_minute"] = requests_per_minute
    if not isinstance(out.get("error_recovery_enabled"), bool):
        raise ValueError("error_recovery_enabled must be a boolean")
    try:
        retry_attempts = int(str(out.get("error_recovery_attempts")).strip())
    except Exception as exc:
        raise ValueError("error_recovery_attempts must be an integer") from exc
    if (
        isinstance(out.get("error_recovery_attempts"), bool)
        or not 0 <= retry_attempts <= ENDPOINT_ERROR_RECOVERY_ATTEMPTS_MAX
    ):
        raise ValueError(
            "error_recovery_attempts must be between 0 and "
            f"{ENDPOINT_ERROR_RECOVERY_ATTEMPTS_MAX}"
        )
    out["error_recovery_attempts"] = retry_attempts
    try:
        retry_cooldown = float(str(out.get("error_recovery_delay_seconds")).strip())
    except Exception as exc:
        raise ValueError("error_recovery_delay_seconds must be a finite number") from exc
    if (
        isinstance(out.get("error_recovery_delay_seconds"), bool)
        or not math.isfinite(retry_cooldown)
        or not 0.0 <= retry_cooldown <= ENDPOINT_ERROR_RECOVERY_DELAY_SECONDS_MAX
    ):
        raise ValueError(
            "error_recovery_delay_seconds must be between 0 and "
            f"{ENDPOINT_ERROR_RECOVERY_DELAY_SECONDS_MAX}"
        )
    out["error_recovery_delay_seconds"] = int(round(retry_cooldown))
    out["context_window_tokens"] = bounded_positive_int(
        out.get("context_window_tokens"), AGENT_CONTEXT_WINDOW_TOKENS_DEFAULT,
        minimum=AGENT_CONTEXT_WINDOW_TOKENS_MIN, maximum=None,
    )
    out["max_output_tokens"] = bounded_positive_int(out.get("max_output_tokens"), 32768, minimum=1, maximum=None)
    out["vision_max_width"] = bounded_positive_int(
        out.get("vision_max_width"), 4096, minimum=64, maximum=32768,
    )
    out["vision_max_height"] = bounded_positive_int(
        out.get("vision_max_height"), 4096, minimum=64, maximum=32768,
    )
    out["max_image_inputs_per_prompt"] = bounded_positive_int(
        out.get("max_image_inputs_per_prompt"), 5, minimum=1, maximum=None,
    )
    vision = str(out.get("vision") or "auto").strip().lower()
    out["vision"] = vision if vision in {"auto", "enabled", "disabled"} else "auto"
    image_context = out.get("image_analysis_context")
    if not isinstance(image_context, str) or image_context not in ENDPOINT_IMAGE_ANALYSIS_CONTEXTS:
        raise ValueError("image_analysis_context must be 'inline' or 'separate'")
    out["image_analysis_context"] = image_context
    out["preserve_thinking"] = bool(out.get("preserve_thinking", False))
    ua_mode = str(out.get("user_agent_mode") or "generic").strip().lower()
    out["user_agent_mode"] = ua_mode if ua_mode in ENDPOINT_USER_AGENT_MODES else "generic"
    out["custom_user_agent"] = str(out.get("custom_user_agent") or "").strip()
    # Validate the effective header now so a malformed value can never reach urllib.
    endpoint_user_agent(out)
    out["temperature"] = _optional_finite_float(out.get("temperature"), "temperature", minimum=0.0)
    out["top_p"] = _optional_finite_float(out.get("top_p"), "top_p", minimum=0.0, maximum=1.0)
    out["min_p"] = _optional_finite_float(out.get("min_p"), "min_p", minimum=0.0, maximum=1.0)
    out["top_k"] = _optional_finite_int(out.get("top_k"), "top_k", minimum=-1)
    out["presence_penalty"] = _optional_finite_float(out.get("presence_penalty"), "presence_penalty")
    out["frequency_penalty"] = _optional_finite_float(out.get("frequency_penalty"), "frequency_penalty")
    out["repetition_penalty"] = _optional_finite_float(out.get("repetition_penalty"), "repetition_penalty", minimum=0.000001)
    out["seed"] = _optional_finite_int(out.get("seed"), "seed")
    stops = out.get("stop_sequences")
    if isinstance(stops, str):
        try:
            stops = json.loads(stops) if stops.strip() else []
        except Exception as exc:
            raise ValueError("stop_sequences must be a JSON array of strings") from exc
    if not isinstance(stops, list) or any(not isinstance(item, str) for item in stops):
        raise ValueError("stop_sequences must be a JSON array of strings")
    out["stop_sequences"] = list(stops)
    effort = str(out.get("reasoning_effort") or "").strip().lower()
    if effort not in ENDPOINT_REASONING_EFFORT_VALUES:
        allowed = ", ".join(value or "blank" for value in sorted(ENDPOINT_REASONING_EFFORT_VALUES))
        raise ValueError(f"reasoning_effort must be one of: {allowed}")
    out["reasoning_effort"] = normalize_endpoint_reasoning_level(out["model_type"], effort)
    if out["model_type"] in {
        ENDPOINT_MODEL_TYPE_KIMI_K2_6, ENDPOINT_MODEL_TYPE_KIMI_K3,
        ENDPOINT_MODEL_TYPE_DEEPSEEK_V4, ENDPOINT_MODEL_TYPE_DEEPSEEK_V4_FLASH_VISION_EXP,
    }:
        out["preserve_thinking"] = True
    elif out["model_type"] in {ENDPOINT_MODEL_TYPE_QWEN_3_6, ENDPOINT_MODEL_TYPE_GEMMA_4} and out["reasoning_effort"] == "off":
        out["preserve_thinking"] = False
    out["extra_body_json"] = str(out.get("extra_body_json") or "").strip()
    parse_endpoint_extra_body(out["extra_body_json"])
    out["system_prompt_addon"] = str(out.get("system_prompt_addon") or "").strip()
    return out


def validate_endpoint_profiles_config(llm: Any, *, location: str = "settings.llm") -> None:
    if not isinstance(llm, dict):
        raise UnsupportedDataVersionError(f"{location} must be an object")
    profiles = llm.get("endpoint_profiles")
    if not isinstance(profiles, list) or not profiles:
        raise UnsupportedDataVersionError(f"{location}.endpoint_profiles must contain at least one profile")
    ids: set[str] = set()
    for index, profile in enumerate(profiles):
        try:
            clean = normalize_endpoint_profile(profile, location=f"{location}.endpoint_profiles[{index}]")
        except ValueError as exc:
            raise UnsupportedDataVersionError(str(exc)) from exc
        profile_id = clean["id"]
        if profile_id in ids:
            raise UnsupportedDataVersionError(f"{location}.endpoint_profiles contains duplicate id {profile_id!r}")
        ids.add(profile_id)
    selected = llm.get("default_profile_id")
    if not isinstance(selected, str) or selected not in ids:
        raise UnsupportedDataVersionError(f"{location}.default_profile_id does not name a saved endpoint profile")


def endpoint_profiles_from_config(config: dict[str, Any] | None) -> list[dict[str, Any]]:
    llm = (config or {}).get("llm") if isinstance(config, dict) else {}
    profiles = llm.get("endpoint_profiles") if isinstance(llm, dict) else []
    return [profile for profile in profiles if isinstance(profile, dict)] if isinstance(profiles, list) else []


def endpoint_profile_id_from_config(config: dict[str, Any] | None) -> str:
    """Return the single default used when creating a new, unscoped Task."""
    llm = (config or {}).get("llm") if isinstance(config, dict) else {}
    selected = str((llm or {}).get("default_profile_id") or "").strip() if isinstance(llm, dict) else ""
    profiles = endpoint_profiles_from_config(config)
    ids = [str(profile.get("id") or "") for profile in profiles]
    if selected in ids:
        return selected
    if DEFAULT_ENDPOINT_PROFILE_ID in ids:
        return DEFAULT_ENDPOINT_PROFILE_ID
    return ids[0] if ids else DEFAULT_ENDPOINT_PROFILE_ID


def endpoint_profile_for_id(config: dict[str, Any] | None, profile_id: str) -> dict[str, Any]:
    selected_id = str(profile_id or "").strip() or endpoint_profile_id_from_config(config)
    profiles = endpoint_profiles_from_config(config)
    profile = next((item for item in profiles if str(item.get("id") or "") == selected_id), None)
    if profile is None and profiles:
        fallback_id = endpoint_profile_id_from_config(config)
        profile = next((item for item in profiles if str(item.get("id") or "") == fallback_id), profiles[0])
    return dict(
        profile or {},
        profile_id=str((profile or {}).get("id") or selected_id),
        profile_label=str((profile or {}).get("label") or selected_id),
    )

def endpoint_profile_view_for_id(
    config: dict[str, Any] | None, profile_id: str,
) -> dict[str, Any]:
    """Return the saved profile object directly for read-only UI hot paths.

    Storage.load_config_view() already supplies a validated, Storage-owned tree.
    Avoiding the alias dictionary allocated by endpoint_profile_for_id() keeps
    per-frame endpoint labels and setup controls allocation-free.
    """
    selected_id = str(profile_id or "").strip() or endpoint_profile_id_from_config(config)
    profiles = endpoint_profiles_from_config(config)
    profile = next((item for item in profiles if str(item.get("id") or "") == selected_id), None)
    if profile is not None:
        return profile
    if profiles:
        fallback_id = endpoint_profile_id_from_config(config)
        return next((item for item in profiles if str(item.get("id") or "") == fallback_id), profiles[0])
    return {}


