def text_undo_limit_from_config(config: dict[str, Any] | None) -> int:
    """Return the per-editor undo depth stored in the strict settings model."""
    ui = (config or {}).get("ui") if isinstance(config, dict) else {}
    if not isinstance(ui, dict):
        ui = {}
    try:
        value = int(str(ui.get("text_undo_limit", TEXT_UNDO_LIMIT_DEFAULT)).strip())
    except Exception:
        value = TEXT_UNDO_LIMIT_DEFAULT
    return int(clamp(value, TEXT_UNDO_LIMIT_MIN, TEXT_UNDO_LIMIT_MAX))


def tooltip_limits_from_config(config: dict[str, Any] | None) -> tuple[int, int]:
    """Return strict tooltip row and per-line character limits."""
    ui = (config or {}).get("ui") if isinstance(config, dict) else {}
    if not isinstance(ui, dict):
        ui = {}
    try:
        lines = int(str(ui.get("tooltip_max_lines", TOOLTIP_MAX_LINES_DEFAULT)).strip())
    except Exception:
        lines = TOOLTIP_MAX_LINES_DEFAULT
    try:
        chars = int(str(ui.get("tooltip_max_chars_per_line", TOOLTIP_MAX_CHARS_PER_LINE_DEFAULT)).strip())
    except Exception:
        chars = TOOLTIP_MAX_CHARS_PER_LINE_DEFAULT
    return (
        int(clamp(lines, TOOLTIP_MAX_LINES_MIN, TOOLTIP_MAX_LINES_MAX)),
        int(clamp(chars, TOOLTIP_MAX_CHARS_PER_LINE_MIN, TOOLTIP_MAX_CHARS_PER_LINE_MAX)),
    )


def normalize_tooltip_text(
    text: Any,
    *,
    max_lines: int = TOOLTIP_MAX_LINES_DEFAULT,
    max_chars_per_line: int = TOOLTIP_MAX_CHARS_PER_LINE_DEFAULT,
) -> str:
    """Bound a tooltip by rows and characters per row while preserving logical lines."""
    line_limit = int(clamp(max_lines, TOOLTIP_MAX_LINES_MIN, TOOLTIP_MAX_LINES_MAX))
    char_limit = int(clamp(
        max_chars_per_line, TOOLTIP_MAX_CHARS_PER_LINE_MIN, TOOLTIP_MAX_CHARS_PER_LINE_MAX,
    ))
    raw = str(text or "").replace("\r\n", "\n").replace("\r", "\n")
    rows: list[str] = []
    truncated = False
    for source_line in raw.split("\n"):
        logical = " ".join(source_line.strip().split())
        if not logical:
            continue
        wrapped = textwrap.wrap(
            logical, width=char_limit, break_long_words=True, break_on_hyphens=False,
            replace_whitespace=False, drop_whitespace=True,
        ) or [""]
        for row in wrapped:
            if len(rows) >= line_limit:
                truncated = True
                break
            rows.append(row[:char_limit])
        if truncated:
            break
    if truncated and rows:
        tail = rows[-1].rstrip()
        rows[-1] = (tail[: max(0, char_limit - 1)].rstrip() + "…") if char_limit > 1 else "…"
    return "\n".join(rows)

