def append_system_prompt_addon(system_prompt: str, addon: str) -> str:
    base = str(system_prompt or "").rstrip()
    addon = str(addon or "").strip()
    if not addon:
        return base
    suffix = f"{SYSTEM_PROMPT_ADDON_HEADER}\n{addon}"
