def validate_agent_settings(agents: Any, *, location: str = "settings.agents") -> None:
    """Validate the strict General Agent and Personal Assistant settings model."""
    defaults = default_config()["agents"]
    try:
        validate_exact_mapping_shape(agents, defaults, location=location)
    except (TypeError, ValueError) as exc:
        raise ValueError(str(exc)) from exc
    if not isinstance(agents, dict):
        raise ValueError(f"{location} must be an object")

    def require_bool(mapping: dict[str, Any], key: str, field_location: str) -> None:
        if not isinstance(mapping.get(key), bool):
            raise ValueError(f"{field_location}.{key} must be a boolean")

    def require_int(
        mapping: dict[str, Any], key: str, field_location: str, minimum: int, maximum: int | None = None,
    ) -> int:
        value = mapping.get(key)
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError(f"{field_location}.{key} must be an integer")
        if value < minimum or (maximum is not None and value > maximum):
            suffix = f" between {minimum} and {maximum}" if maximum is not None else f" at least {minimum}"
            raise ValueError(f"{field_location}.{key} must be{suffix}")
        return value

    require_int(agents, "timeout_minutes", location, AGENT_TIMEOUT_MINUTES_MIN)
    require_bool(agents, "auto_compaction_enabled", location)

    pa = agents.get("personal_assistant")
    if not isinstance(pa, dict):
        raise ValueError(f"{location}.personal_assistant must be an object")
    pa_location = f"{location}.personal_assistant"
    require_bool(pa, "enabled", pa_location)
    start_time = pa.get("start_time")
    if not isinstance(start_time, str) or not re.fullmatch(r"(?:[01]\d|2[0-3]):[0-5]\d", start_time):
        raise ValueError(f"{pa_location}.start_time must use 24-hour HH:MM")
    require_int(pa, "check_interval_minutes", pa_location, PA_AGENT_CHECK_INTERVAL_MINUTES_MIN)
    require_int(
        pa, "report_days_back", pa_location,
        PA_AGENT_REPORT_DAYS_BACK_MIN, PA_AGENT_REPORT_DAYS_BACK_MAX,
    )
    require_int(pa, "timeout_minutes", pa_location, AGENT_TIMEOUT_MINUTES_MIN)
    require_bool(pa, "auto_compaction_enabled", pa_location)


