def endpoint_prompt_capacity_tokens(endpoint: dict[str, Any] | None) -> int:
    """Return the largest prompt vLLM can accept with this profile's output reserve.

    OpenAI-compatible vLLM validates ``input_tokens + max_tokens`` against the
    model's total context length. Compaction therefore targets this effective
    prompt capacity, not the headline context-window number.
    """
    context_tokens = endpoint_context_window_tokens(endpoint)
    output_tokens = endpoint_max_output_tokens(endpoint)
    return max(1, context_tokens - output_tokens)


def endpoint_prompt_capacity_tokens_from_config(config: dict[str, Any] | None, profile_id: str) -> int:
    return endpoint_prompt_capacity_tokens(endpoint_profile_for_id(config, profile_id))


CONTEXT_FIT_SAFETY_TOKENS_MIN = 256
CONTEXT_FIT_SAFETY_TOKENS_MAX = 8_192


def endpoint_prompt_safety_tokens(
    endpoint: dict[str, Any] | None,
    *,
    message_count: int = 0,
    native_tool_count: int = 0,
) -> int:
    """Return a small bounded reserve for tokenizer and provider framing variance.

    Velox estimates prompt tokens without importing one tokenizer per model family.
    Provider templates can count a handful of control tokens differently, especially
    after native tool calls/results are added. The reserve is deliberately tiny
    relative to large contexts, scales only with protocol objects, and prevents an
    exact-boundary request from exceeding ``context_window_tokens`` by one or a few
    tokens while still using more than 99 percent of the configured prompt budget.
    """
    context_tokens = endpoint_context_window_tokens(endpoint)
    raw_capacity = endpoint_prompt_capacity_tokens(endpoint)
    context_component = max(1, context_tokens // 4_096)
    protocol_component = max(0, int(message_count)) * 2 + max(0, int(native_tool_count)) * 8
    reserve = int(clamp(
        CONTEXT_FIT_SAFETY_TOKENS_MIN + context_component + protocol_component,
        CONTEXT_FIT_SAFETY_TOKENS_MIN,
        CONTEXT_FIT_SAFETY_TOKENS_MAX,
    ))
    return min(max(0, raw_capacity - 1), reserve)


def estimate_request_content_tokens(content: Any) -> int:
    """Estimate model-visible content without counting encoded image bytes as text."""
    if isinstance(content, list):
        total = 0
        for part in content:
            if isinstance(part, dict):
                part_type = str(part.get("type") or "").lower()
                if part_type in {"image_url", "input_image", "image"} or "image_url" in part:
                    detail = str(part.get("detail") or "").lower()
                    image_url = part.get("image_url")
                    if isinstance(image_url, dict):
                        detail = str(image_url.get("detail") or detail).lower()
                    total += (
                        ESTIMATED_LOW_DETAIL_IMAGE_TOKENS if detail == "low" else
                        ESTIMATED_HIGH_DETAIL_IMAGE_TOKENS if detail == "high" else
                        ESTIMATED_IMAGE_INPUT_TOKENS
                    )
                elif "text" in part:
                    total += _compaction_value_tokens(part.get("text"))
                elif "content" in part:
                    total += estimate_request_content_tokens(part.get("content"))
                else:
                    scrubbed = {
                        key: ("<omitted>" if key in {"data", "bytes", "b64_json"} else value)
                        for key, value in part.items()
                    }
                    total += _compaction_value_tokens(scrubbed)
            else:
                total += _compaction_value_tokens(part)
        return max(0, int(total))
    return _compaction_value_tokens(content)


def estimate_request_messages_tokens(messages: list[dict[str, Any]] | None) -> int:
    """Estimate one replay representation, not duplicated compatibility carriers."""
    total = 0
    for message in messages or []:
        if not isinstance(message, dict):
            continue
        ordinary = sum(estimate_request_content_tokens(message.get(field)) for field in (
            "content", "reasoning_content", "reasoning_details", "tool_calls", "tool_call_id", "name",
        ))
        preserved = message.get("response_output_items")
        # Runtime arrays may contain both transport mirrors. They are alternatives,
        # never concatenated by either payload builder. Conservatively use the larger.
        response_tokens = estimate_request_content_tokens(preserved) if preserved else 0
        total += 4 + max(ordinary, response_tokens)
    return max(0, int(total))


def bounded_request_output_tokens(
    endpoint: dict[str, Any] | None,
    *,
    messages: list[dict[str, Any]] | None,
    native_tools: list[dict[str, Any]] | None,
    requested_output_tokens: Any,
) -> tuple[int, dict[str, Any]]:
    """Clamp one request's output reserve before network I/O as a final guard.

    Normal Chat/Agent compaction keeps the configured output allowance intact.
    This clamp only handles estimator/template variance, disabled auto-compaction,
    and explicit per-call output overrides. For configured vLLM/llama.cpp
    endpoints, a local overestimate does not block the request: Velox sends the
    requested bounded output allowance so the provider tokenizer can return an
    authoritative arithmetic overflow for automatic recovery. Hosted/generic
    endpoints retain the conservative local rejection path.
    """
    requested = bounded_positive_int(requested_output_tokens, 32_768, maximum=None)
    estimated = estimate_request_messages_tokens(messages)
    capacity = prepared_request_capacity_snapshot(
        endpoint,
        estimated_message_tokens=estimated,
        message_count=len(messages or []),
        native_tools=native_tools,
    )
    available = (
        int(capacity["context_window_tokens"])
        - int(capacity["context_safety_tokens"])
        - int(capacity["complete_tokens"])
    )
    if available < 1:
        provider_key = endpoint_provider(endpoint)
        if provider_key in {ENDPOINT_PROVIDER_VLLM, ENDPOINT_PROVIDER_LLAMA_CPP}:
            # The local estimate is intentionally only predictive. Let the local
            # provider's real tokenizer/chat template decide whether the request
            # fits, preserving the requested generation budget when it does. A
            # genuine arithmetic overflow is parsed and compacted by the runtime.
            provider_output = min(
                requested,
                max(1, int(capacity["context_window_tokens"]) - 1),
            )
            capacity = dict(capacity)
            capacity.update({
                "local_estimate_exceeds_context": True,
                "provider_authoritative_overflow_check": True,
                "provider_authoritative_output_tokens": provider_output,
            })
            return provider_output, capacity
        raise LLMEndpointError(
            "Velox local context_length_exceeded (no HTTP request sent): local prompt estimate exceeds the endpoint context window even after reserving only one output token. "
            f"Estimated prompt={int(capacity['complete_tokens']):,}; "
            f"context={int(capacity['context_window_tokens']):,}; "
            f"safety reserve={int(capacity['context_safety_tokens']):,}."
        )
    capacity = dict(capacity)
    capacity.update({
        "local_estimate_exceeds_context": False,
        "provider_authoritative_overflow_check": False,
    })
    return min(requested, int(available)), capacity


def endpoint_context_recovery_attempts(endpoint: dict[str, Any] | None) -> int:
    """Additional safe attempts, independently of timeout/overload retry policy."""
    value = (endpoint or {}).get("context_recovery_attempts", CONTEXT_OVERFLOW_RECOVERY_MAX_ATTEMPTS)
    try:
        return max(0, min(10, int(value)))
    except (TypeError, ValueError):
        return CONTEXT_OVERFLOW_RECOVERY_MAX_ATTEMPTS


def endpoint_token_estimate_multiplier(endpoint: dict[str, Any] | None) -> float:
    """Scale the established code/Unicode-aware base estimate, not JSON bytes."""
    profile = endpoint or {}
    default = 3.2 if profile.get("model_type") == ENDPOINT_MODEL_TYPE_GLM_5_3_FLASH else 4.0
    try:
        chars_per_token = float(profile.get("token_estimate_chars_per_token", default))
        if not math.isfinite(chars_per_token) or not 0.25 <= chars_per_token <= 8.0:
            chars_per_token = default
    except (TypeError, ValueError):
        chars_per_token = default
    baseline = 4.0 / chars_per_token
    if profile.get("adaptive_token_estimation", True):
        try:
            learned = float(profile.get("_token_estimate_multiplier", 0.0))
            if math.isfinite(learned) and 0.0 < learned <= 16.0:
                baseline = max(baseline, learned)
        except (TypeError, ValueError):
            pass
    return baseline


def _endpoint_token_calibration_key(profile: dict[str, Any]) -> str:
    # Settings identifying the served tokenizer/template. Neither credentials nor
    # prompt content is written to the calibration record. Different roots stay isolated.
    identity = {key: profile.get(key) for key in (
        "id", "provider", "base_url", "api_transport", "model_type", "model",
        "preserve_thinking", "extra_body_json",
    )}
    return sha256_bytes(json.dumps(identity, sort_keys=True, ensure_ascii=False).encode("utf-8"))


def _endpoint_token_calibrations(storage: Any) -> tuple[Path, dict[str, Any]]:
    path = storage.paths.app_json_path.parent / "endpoint_token_calibration.json"
    try:
        st = path.stat()
        signature = (st.st_mtime_ns, st.st_size, st.st_ctime_ns, st.st_ino)
    except FileNotFoundError:
        signature = None
    cached = getattr(storage, "_endpoint_token_calibration_cache", None)
    if isinstance(cached, tuple) and len(cached) == 2 and cached[0] == signature:
        return path, cached[1]
    try:
        raw = json.loads(path.read_text(encoding="utf-8")) if signature else {}
        rows = raw.get("endpoints", {}) if raw.get("schema") == "endpoint_token_calibration.v1" else {}
        if not isinstance(rows, dict):
            rows = {}
    except (OSError, ValueError, TypeError, AttributeError):
        rows = {}
    storage._endpoint_token_calibration_cache = (signature, rows)
    return path, rows


def endpoint_with_token_calibration(storage: Any, endpoint: dict[str, Any]) -> dict[str, Any]:
    result = dict(endpoint)
    if not result.get("adaptive_token_estimation", True):
        return result
    try:
        _path, rows = _endpoint_token_calibrations(storage)
        record = rows.get(_endpoint_token_calibration_key(result))
        if isinstance(record, dict):
            factor = float(record.get("multiplier", 0.0))
            if math.isfinite(factor) and 0.0 < factor <= 16.0:
                result["_token_estimate_multiplier"] = factor
    except (OSError, ValueError, TypeError, AttributeError):
        pass  # Estimation metadata is optional; never stop otherwise valid inference.
    return result


def observe_endpoint_prompt_usage(storage: Any, endpoint: dict[str, Any], usage: Any) -> None:
    """Learn only from raw provider usage matched to this exact prepared request.

    Called before monitor/fallback counters are injected. Input is the whole prompt,
    never cached-input, output, totals, or billed-token counts. Persist a bounded,
    conservative high-water mark; completion, failure and replay bytes are untouched.
    """
    if not endpoint.get("adaptive_token_estimation", True) or not isinstance(usage, dict):
        return
    capacity = endpoint.get("_request_capacity")
    if not isinstance(capacity, dict):
        return
    base_tokens = capacity.get("base_complete_tokens")
    if not isinstance(base_tokens, int) or base_tokens < 1024:
        return  # Small framing-dominated samples should not calibrate a million-token request.
    measured = next((usage[key] for key in ("prompt_tokens", "input_tokens")
                     if isinstance(usage.get(key), int) and not isinstance(usage[key], bool) and usage[key] > 0), None)
    if measured is None or usage.get("token_counts_estimated") or usage.get("_estimated_prompt_tokens") or usage.get("_velox_token_counts_estimated"):
        return
    factor = float(measured) / base_tokens * 1.05
    if not math.isfinite(factor) or not 0.0 < factor <= 16.0:
        return
    try:
        path, _rows = _endpoint_token_calibrations(storage)
        with DATA_ROOTS.lock_for_path(path):
            # Fresh locked read prevents parallel requests losing a larger observation.
            storage._endpoint_token_calibration_cache = None
            _path, rows = _endpoint_token_calibrations(storage)
            key = _endpoint_token_calibration_key(endpoint)
            prior = rows.get(key, {})
            try:
                previous = float(prior.get("multiplier", 0.0)) if isinstance(prior, dict) else 0.0
                if not math.isfinite(previous) or not 0.0 < previous <= 16.0:
                    previous = 0.0
            except (TypeError, ValueError):
                previous = 0.0
            if math.isfinite(previous) and factor <= previous * 1.01:
                return
            rows = dict(rows)
            rows[key] = {"multiplier": factor, "base_prompt_tokens": base_tokens,
                         "provider_prompt_tokens": measured, "updated_at": now_iso()}
            if len(rows) > 64:
                ordered = sorted(rows, key=lambda k: str(rows[k].get("updated_at", "")) if isinstance(rows[k], dict) else "")
                for old in ordered[:-64]:
                    rows.pop(old, None)
            atomic_write_json(path, {"schema": "endpoint_token_calibration.v1", "endpoints": rows})
            storage._endpoint_token_calibration_cache = None
    except Exception:
        # This is secondary metadata: an unavailable disk must never turn a successful
        # provider response into a failed request or cause a model/tool retry.
        try:
            storage.append_app_log("endpoint.token_calibration_failed", {"error": traceback.format_exc(limit=3)})
        except Exception:
            pass


def prepared_request_capacity_snapshot(
    endpoint: dict[str, Any] | None,
    *,
    estimated_message_tokens: int,
    message_count: int,
    native_tools: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """Describe one complete prepared request against the safe prompt target."""
    native_tool_count = len(native_tools) if isinstance(native_tools, list) else 0
    tool_schema_tokens = estimate_native_tool_schema_tokens(native_tools)
    raw_capacity = endpoint_prompt_capacity_tokens(endpoint)
    safety_tokens = endpoint_prompt_safety_tokens(
        endpoint, message_count=message_count, native_tool_count=native_tool_count,
    )
    safe_capacity = max(1, raw_capacity - safety_tokens)
    base_complete_tokens = max(0, int(estimated_message_tokens)) + tool_schema_tokens
    multiplier = endpoint_token_estimate_multiplier(endpoint)
    complete_tokens = int(math.ceil(base_complete_tokens * multiplier))
    return {
        "context_window_tokens": endpoint_context_window_tokens(endpoint),
        "max_output_tokens": endpoint_max_output_tokens(endpoint),
        "raw_prompt_capacity_tokens": raw_capacity,
        "context_safety_tokens": safety_tokens,
        "prompt_capacity_tokens": safe_capacity,
        "message_tokens": max(0, int(estimated_message_tokens)),
        "tool_schema_tokens": tool_schema_tokens,
        "complete_tokens": complete_tokens,
        "base_complete_tokens": base_complete_tokens,
        "token_estimate_multiplier": multiplier,
        "base_prompt_capacity_tokens": max(1, int(math.floor(safe_capacity / multiplier))),
        "fits": complete_tokens <= safe_capacity,
    }


def chat_turns_summary_fingerprint(turns: list[dict[str, Any]]) -> str:
    parts: list[str] = []
    for t in turns:
        role = str(t.get("role") or "")
        if role not in {"user", "assistant"}:
            continue
        text = strip_reasoning_content(str(t.get("text") or ""))
        tool_count = len(t.get("tool_calls") or []) if isinstance(t.get("tool_calls"), list) else 0
        parts.append("|".join([
            str(t.get("turn_id") or ""),
            str(t.get("updated_at") or t.get("created_at") or ""),
            role,
            str(len(text)),
            sha256_bytes(text.encode("utf-8", errors="replace"))[:16],
            str(tool_count),
        ]))
    return sha256_bytes("\n".join(parts).encode("utf-8", errors="replace"))


def one_sentence_from_summary(text: str, limit: int = CHAT_ONE_SENTENCE_SUMMARY_HARD_CHARS) -> str:
    raw = re.sub(r"\s+", " ", strip_reasoning_content(str(text or ""))).strip(" -\t\n")
    if not raw:
        return ""
    m = re.search(r"(?<=[.!?])\s+", raw)
    sent = raw[:m.start()].strip() if m else raw
    sent = re.sub(r"^[#*`>\s-]+", "", sent).strip()
    return sent[:max(32, int(limit))].rstrip()


def parse_generated_chat_summary(text: str) -> tuple[str, str]:
    cleaned = strip_reasoning_content(str(text or "")).strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```(?:json|markdown)?\s*", "", cleaned, flags=re.IGNORECASE).strip()
        cleaned = re.sub(r"\s*```$", "", cleaned).strip()
    if not cleaned:
        return "", ""
    try:
        obj = json.loads(cleaned)
        if isinstance(obj, dict):
            one = str(obj.get("one_sentence_summary") or obj.get("one_sentence") or "").strip()
            bullets_obj = obj.get("bullet_summary_markdown") or obj.get("bullets") or obj.get("summary_markdown") or ""
            if isinstance(bullets_obj, list):
                bullets = "\n".join(f"- {str(x).strip()}" for x in bullets_obj if str(x).strip())
            else:
                bullets = str(bullets_obj or "").strip()
            return one_sentence_from_summary(one or bullets), bullets[:CHAT_BULLET_SUMMARY_HARD_CHARS].rstrip()
    except Exception:
        pass
    lines = [ln.rstrip() for ln in cleaned.splitlines()]
    one = ""
    bullet_lines: list[str] = []
    for ln in lines:
        low = ln.lower().strip()
        if not one and (low.startswith("one sentence") or low.startswith("one-sentence")):
            one = re.sub(r"^[^:]+:\s*", "", ln).strip()
            continue
        if re.match(r"^\s*(?:[-*+]\s+|\d+[.)]\s+)", ln):
            bullet_lines.append(re.sub(r"^\s*[*+]\s+", "- ", ln).strip())
    bullets = "\n".join(bullet_lines).strip() if bullet_lines else cleaned
    return one_sentence_from_summary(one or cleaned), bullets[:CHAT_BULLET_SUMMARY_HARD_CHARS].rstrip()


# =============================================================================
# Small utilities
# =============================================================================


def _detach_owner_directory(directory: Path) -> Path:
    """One atomic namespace change is the deletion commit; cleanup is secondary.

    The caller holds the app-root lock. A failed rename leaves the entire live
    record untouched. A failed purge leaves only an unlisted recovery tombstone,
    never a half-deleted selectable Chat/Agent.
    """
    if not directory.is_dir():
        raise FileNotFoundError(f"Owner directory no longer exists: {directory}")
    detached = directory.with_name(".deleted-" + directory.name + "-" + uuid.uuid4().hex)
    os.replace(directory, detached)
    return detached


def _purge_detached_owner(storage: Any, directory: Path) -> None:
    try:
        shutil.rmtree(directory)
    except FileNotFoundError:
        pass
    except OSError as exc:
        _best_effort_lifecycle_log(storage, "owner.delete_cleanup_pending", {
            "path": str(directory), "error": f"{type(exc).__name__}: {exc}",
        })


def _cleanup_detached_owners(storage: Storage) -> None:
    for parent in (storage.paths.chats_dir(), storage.paths.agents_dir()):
        if parent.is_dir():
            for directory in parent.glob(".deleted-*"):
                if directory.is_dir() and not directory.is_symlink():
                    _purge_detached_owner(storage, directory)


def _best_effort_lifecycle_log(storage: Any, event: str, data: dict[str, Any]) -> None:
    """An audit failure cannot roll back an already committed lifecycle operation."""
    try:
        storage.append_app_log(event, data)
    except Exception:
        pass


def _require_durable_owner(path: Path) -> None:
    """Reject late writes/reads beneath a deleted strict-root Chat or Agent.

    Call under DATA_ROOTS.lock_for_path(path) when followed by a write. This is
    deliberately not a directory creator: only the ordinary create methods may
    publish a new durable owner record.
    """
    context = DATA_ROOTS.context_for_path(path)
    if context is None:
        return
    try:
        relative = Path(path).resolve(strict=False).relative_to(context.root_dir)
    except ValueError:
        return
    parts = relative.parts
    if len(parts) < 2:
        return
    if parts[0] == "chats" and parts[1].startswith("chat_"):
        marker = context.root_dir / parts[0] / parts[1] / "chat.json"
    elif parts[0] == "agents" and parts[1].startswith("agent_"):
        marker = context.root_dir / parts[0] / parts[1] / "agent.json"
    else:
        return
    if not marker.is_file():
        raise FileNotFoundError(f"Durable owner no longer exists: {marker}")


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="microseconds").replace("+00:00", "Z")


def current_datetime_context() -> dict[str, Any]:
    # Use one current-time source for prompts and the time_now tool.
    utc = datetime.now(timezone.utc)
    local = utc.astimezone()
    return {
        "schema": "current_datetime.v1",
        "utc_iso": utc.isoformat(timespec="seconds").replace("+00:00", "Z"),
        "local_iso": local.isoformat(timespec="seconds"),
        "local_date": local.date().isoformat(),
        "utc_date": utc.date().isoformat(),
        "timezone": local.tzname() or "local",
        "epoch_seconds": int(utc.timestamp()),
    }


def current_date_system_line() -> str:
    ctx = current_datetime_context()
    return (
        f"Current date: {ctx['local_date']}. "
        "This is the live local date at request assembly. Treat it as newer and more reliable "
        "than model training data when deciding whether current information requires tools."
    )


# Cache-safe application context is appended chronologically as hidden Chat turns
# instead of being rebuilt inside the leading system prompt. Provider-side prefix
# caching can therefore reuse the exact historical prefix when date/background
# context changes between user messages.
CHAT_APP_CONTEXT_MARKER = "VELOX APPLICATION CONTEXT"
CHAT_APP_CONTEXT_DATE_KIND = "current_date"
CHAT_APP_CONTEXT_HISTORY_KIND = "recent_chat_history"
CHAT_APP_CONTEXT_DOCS_KIND = "context_docs"
CHAT_APP_CONTEXT_CALENDAR_KIND = "calendar"
CHAT_APP_CONTEXT_STOP_KIND = "checklist_user_stop"
CHAT_APP_CONTEXT_DATE_HEADER = "VELOX CURRENT DATE CONTEXT"
CHAT_APP_CONTEXT_HISTORY_HEADER = "VELOX RECENT CHAT HISTORY SNAPSHOT"
CHAT_APP_CONTEXT_DOCS_HEADER = "VELOX CONTEXT DOCS SNAPSHOT"
CHAT_APP_CONTEXT_CALENDAR_HEADER = "VELOX CALENDAR CONTEXT SNAPSHOT"
CHAT_APP_CONTEXT_STOP_HEADER = "VELOX CHECKLISTS CANCELLED BY USER"


def chat_application_context_fingerprint(text: str) -> str:
    return hashlib.sha256(str(text or "").encode("utf-8")).hexdigest()


def format_display_datetime(value: str | None) -> str:
    """Display UTC ISO timestamps in the system timezone without a timezone suffix.

    Storage remains UTC+00 (`Z`). UI cards use a compact local format such as
    `May 18 2026, 03:42`; the timezone name is intentionally omitted to keep
    message headers short and avoid clipping. Invalid timestamps are returned
    unchanged.
    """
    raw = str(value or "").strip()
    if not raw:
        return ""
    try:
        normalized = raw.replace("Z", "+00:00")
        dt = datetime.fromisoformat(normalized)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        local = dt.astimezone()
        month = local.strftime("%B")
        return f"{month} {local.day} {local.year}, {local:%H:%M}"
    except Exception:
        return raw


def uuid_v4() -> str:
    return str(uuid.uuid4())


def is_uuid_v4(value: Any) -> bool:
    return isinstance(value, str) and bool(UUID_RE.match(value))


JSON_COMPACT_SEPARATORS: tuple[str, str] = (",", ":")


def json_dumps(obj: Any) -> str:
    """Serialize durable JSON without pretty-print expansion.

    Context Docs and streaming checkpoints can contain hundreds of thousands of
    characters. Compact separators reduce bytes written, UTF-8 encoding work,
    page-cache pressure, and the amount later parsed while preserving the exact
    strict JSON data model.
    """
    return json.dumps(obj, ensure_ascii=False, separators=JSON_COMPACT_SEPARATORS)


def atomic_write_text(path: Path, text: str) -> None:
    file_write_text(Path(path), text)


def atomic_write_json(path: Path, obj: Any) -> None:
    atomic_write_text(path, json_dumps(obj))


class _RegisteredBackgroundWriter:
    """Shared lifecycle registry operations for daemon-backed durable writers."""

    def last_error(self, path: Path) -> str:
        with self._condition:
            return str(self._errors.get(Path(path), ""))

    @classmethod
    def shutdown_all(cls, *, timeout: float = 3.0) -> None:
        """Stop every live subclass instance with bounded teardown."""
        with cls._instances_lock:
            instances = list(cls._instances)
        for instance in instances:
            try:
                instance.shutdown(timeout=timeout)
            except Exception:
                pass


class CoalescingAtomicJSONWriter(_RegisteredBackgroundWriter):
    """Write only the newest pending JSON payload for each path off the UI loop.

    A streaming turn snapshot grows with the response. Serializing, flushing, and
    fsyncing that payload on the asyncio/UI thread can pause rendering for hundreds
    of milliseconds. This single daemon worker coalesces superseded snapshots and
    preserves atomic replacement. Terminal transitions cancel and drain a path so
    an older in-flight checkpoint cannot recreate a removed sidecar. Every instance
    is explicitly stoppable so Python shutdown cannot deadlock on an idle condition
    wait after tests or a normal application exit.
    """

    _instances_lock = threading.RLock()
    _instances: "weakref.WeakSet[CoalescingAtomicJSONWriter]" = weakref.WeakSet()

    def __init__(self, write_json: Callable[[Path, Any], None] | None = None) -> None:
        self._write_json = write_json or atomic_write_json
        self._condition = threading.Condition(threading.RLock())
        self._pending: dict[Path, tuple[int, Any]] = {}
        self._inflight: dict[Path, int] = {}
        self._generations: dict[Path, int] = {}
        self._cancelled_through: dict[Path, int] = {}
        self._errors: dict[Path, str] = {}
        self._thread: threading.Thread | None = None
        self._stopping = False
        with self._instances_lock:
            self._instances.add(self)

    def _ensure_thread_locked(self) -> None:
        if self._stopping:
            raise RuntimeError("stream snapshot writer is shutting down")
        if self._thread is not None and self._thread.is_alive():
            return
        self._thread = threading.Thread(
            target=self._run, name="VeloxStreamSnapshotWriter", daemon=True,
        )
        self._thread.start()

    def submit(self, path: Path, payload: Any) -> int:
        resolved = Path(path)
        with self._condition:
            self._ensure_thread_locked()
            generation = int(self._generations.get(resolved, 0)) + 1
            self._generations[resolved] = generation
            # Reinsert so a repeatedly updated path stays at the newest end while
            # every other chat still eventually receives service.
            self._pending.pop(resolved, None)
            self._pending[resolved] = (generation, payload)
            self._errors.pop(resolved, None)
            self._condition.notify_all()
            return generation

    def _run(self) -> None:
        while True:
            with self._condition:
                while not self._pending and not self._stopping:
                    self._condition.wait()
                if self._stopping and not self._pending:
                    self._thread = None
                    self._condition.notify_all()
                    return
                path = next(iter(self._pending))
                generation, payload = self._pending.pop(path)
                self._inflight[path] = generation
            error = ""
            try:
                self._write_json(path, payload)
            except Exception as exc:
                error = f"{type(exc).__name__}: {exc}"
            with self._condition:
                stale = int(self._generations.get(path, 0)) != int(generation)
                cancelled = generation <= self._cancelled_through.get(path, -1)
            if cancelled:
                # Only an explicit terminal invalidation removes a committed
                # snapshot. A newer queued checkpoint is not a durable replacement:
                # preserve the last good file until that next write succeeds.
                try:
                    path.unlink(missing_ok=True)
                except Exception:
                    pass
            with self._condition:
                if error and not stale:
                    self._errors[path] = error
                elif not stale:
                    self._errors.pop(path, None)
                if self._inflight.get(path) == generation:
                    self._inflight.pop(path, None)
                self._condition.notify_all()

    def flush(self, paths: Iterable[Path] | None = None, *, timeout: float = 15.0) -> bool:
        selected = None if paths is None else {Path(path) for path in paths}
        deadline = time.monotonic() + max(0.01, float(timeout))
        with self._condition:
            while True:
                if selected is None:
                    busy = bool(self._pending or self._inflight)
                else:
                    busy = any(path in self._pending or path in self._inflight for path in selected)
                if not busy:
                    return True
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    return False
                self._condition.wait(min(0.1, remaining))

    def cancel(self, path: Path, *, wait: bool = True) -> None:
        resolved = Path(path)
        with self._condition:
            self._generations[resolved] = int(self._generations.get(resolved, 0)) + 1
            cancelled_generation = self._generations[resolved]
            self._cancelled_through[resolved] = cancelled_generation
            self._pending.pop(resolved, None)
            self._errors.pop(resolved, None)
            self._condition.notify_all()
        if wait:
            self.flush((resolved,))
        with self._condition:
            if self._generations.get(resolved) == cancelled_generation:
                try:
                    resolved.unlink(missing_ok=True)
                except Exception:
                    pass


    def clear_for_tests(self) -> None:
        """Cancel all test jobs with one bounded drain, not one timeout per path.

        Test suites create many short-lived roots. Waiting up to the full production
        timeout independently for every historical path made teardown proportional
        to the number of tests and could turn a clean suite into a multi-minute hang.
        One generation bump invalidates every queued/in-flight payload, one bounded
        flush lets normal writes finish, and any genuinely slow stale worker removes
        its own output when it observes the generation mismatch.
        """
        with self._condition:
            paths = set(self._generations) | set(self._pending) | set(self._inflight)
            for path in paths:
                self._generations[path] = int(self._generations.get(path, 0)) + 1
                self._cancelled_through[path] = self._generations[path]
            self._pending.clear()
            self._errors.clear()
            self._condition.notify_all()
        # One overall wait prevents N paths from each consuming the 15-second
        # production drain timeout. Atomic JSON writes normally finish in a few ms.
        self.flush(paths, timeout=3.0)
        for path in paths:
            try:
                path.unlink(missing_ok=True)
            except Exception:
                pass
        with self._condition:
            # A timed-out worker remains represented until its normal completion
            # path removes it; clearing that entry early would let a later test
            # mistake the path for idle while a stale write was still running.
            for path in paths:
                if path not in self._inflight:
                    self._generations.pop(path, None)
                    self._cancelled_through.pop(path, None)
            self._errors.clear()
            self._condition.notify_all()


    def shutdown(self, *, timeout: float = 3.0) -> bool:
        """Drain queued snapshots, stop the idle worker, and join it boundedly."""
        self.flush(timeout=max(0.01, float(timeout)))
        with self._condition:
            self._stopping = True
            self._pending.clear()
            self._condition.notify_all()
            thread = self._thread
        if thread is not None and thread is not threading.current_thread():
            thread.join(max(0.01, float(timeout)))
        return not bool(thread and thread.is_alive())


def _write_owned_chat_snapshot(path: Path, payload: Any) -> None:
    with DATA_ROOTS.lock_for_path(path):
        if not (path.parent / "chat.json").is_file():
            return
        atomic_write_json(path, payload)


CHAT_STREAM_SNAPSHOT_WRITER = CoalescingAtomicJSONWriter(_write_owned_chat_snapshot)


def read_json(path: Path, default: Any = None) -> Any:
    """Parse one UTF-8 JSON file directly from bytes.

    ``json.loads`` accepts bytes and performs its own UTF-8 decode. Avoiding an
    intermediate Python string removes one full-size allocation for large Context
    Docs, manifests, snapshots, and provider records.
    """
    path = Path(path)
    try:
        path.stat()
    except FileNotFoundError:
        return default
    except (PermissionError, OSError):
        # The read helper below owns bounded retries for a transient sharing
        # denial; do not misclassify that denial as a missing optional file.
        pass
    try:
        return json.loads(file_read_bytes(path))
    except FileNotFoundError:
        return default


def _open_jsonl_append_handle(path: "Path") -> Any:
    """Open a JSONL file for binary append with Windows delete sharing.

    On Windows the file is opened with FILE_SHARE_DELETE so a concurrent unlink
    (for example a data-root reset) cannot fail with WinError 32 while a
    background batch holds the handle.
    """
    if os.name != "nt":
        return path.open("r+b")
    # Lazy Windows-only binding with reliable last-error capture.
    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.CreateFileW.restype = ctypes.c_void_p
    kernel32.CreateFileW.argtypes = [
        ctypes.c_wchar_p,
        ctypes.c_uint32,
        ctypes.c_uint32,
        ctypes.c_void_p,
        ctypes.c_uint32,
        ctypes.c_uint32,
        ctypes.c_void_p,
    ]
    kernel32.CloseHandle.restype = ctypes.c_int
    kernel32.CloseHandle.argtypes = [ctypes.c_void_p]
    GENERIC_READ = 0x80000000
    GENERIC_WRITE = 0x40000000
    FILE_SHARE_READ = 0x00000001
    FILE_SHARE_WRITE = 0x00000002
    FILE_SHARE_DELETE = 0x00000004
    OPEN_EXISTING = 3
    FILE_ATTRIBUTE_NORMAL = 0x00000080
    raw_handle = kernel32.CreateFileW(
        str(path),
        GENERIC_READ | GENERIC_WRITE,
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
        None,
        OPEN_EXISTING,
        FILE_ATTRIBUTE_NORMAL,
        None,
    )
    if raw_handle in (None, ctypes.c_void_p(-1).value):
        error = ctypes.get_last_error()
        exc = ctypes.WinError(error)
        exc.filename = str(path)
        raise exc
    import msvcrt

    # Ownership: until a CRT descriptor is adopted, this function owns the raw
    # handle and must close it on any failure before the helper returns.
    try:
        fd = msvcrt.open_osfhandle(int(raw_handle), os.O_RDWR | os.O_BINARY)
    except OSError:
        kernel32.CloseHandle(raw_handle)
        raise
    if fd < 0:
        last_error = ctypes.get_last_error()
        kernel32.CloseHandle(raw_handle)
        exc = ctypes.WinError(last_error or 6)
        exc.filename = str(path)
        raise exc
    try:
        # The returned stream owns the descriptor and handle from here on; the
        # helper must not close them.
        return os.fdopen(fd, "r+b")
    except Exception:
        # The descriptor owns the handle; close the descriptor to release it.
        try:
            os.close(fd)
        except OSError:
            pass
        raise


def _prepare_jsonl_for_append(handle: Any) -> None:
    """Repair only a crash-torn final JSONL fragment before appending.

    Completed interior rows remain untouched so strict readers can diagnose real
    corruption. A valid final object that merely lacks its newline is preserved
    and terminated; an invalid unterminated tail is discarded back to the last
    complete newline. The caller must hold the data-root lock.
    """
    handle.seek(0, os.SEEK_END)
    end = int(handle.tell())
    if end <= 0:
        return
    handle.seek(end - 1)
    if handle.read(1) == b"\n":
        return

    scan_at = end
    last_newline = -1
    chunk_size = 64 * 1024
    while scan_at > 0:
        take = min(chunk_size, scan_at)
        scan_at -= take
        handle.seek(scan_at)
        block = handle.read(take)
        index = block.rfind(b"\n")
        if index >= 0:
            last_newline = scan_at + index
            break
    tail_start = last_newline + 1
    handle.seek(tail_start)
    tail = handle.read(end - tail_start)
    try:
        parsed = json.loads(tail.decode("utf-8"))
        valid_unterminated_row = isinstance(parsed, dict)
    except Exception:
        valid_unterminated_row = False
    if valid_unterminated_row:
        handle.seek(0, os.SEEK_END)
        handle.write(b"\n")
    else:
        handle.truncate(tail_start)


def append_jsonl(path: Path, obj: Any) -> None:
    path = Path(path)
    line = (json.dumps(obj, ensure_ascii=False, separators=(",", ":")) + "\n").encode("utf-8")
    path.parent.mkdir(parents=True, exist_ok=True)
    with DATA_ROOTS.lock_for_path(path):
        mode = "r+b" if path.exists() else "w+b"
        with path.open(mode) as handle:
            _prepare_jsonl_for_append(handle)
            handle.seek(0, os.SEEK_END)
            handle.write(line)
            try:
                handle.flush()
                os.fsync(handle.fileno())
            except Exception:
                pass


class BatchedJSONLWriter(_RegisteredBackgroundWriter):
    """Batch append-only JSONL records on one daemon I/O thread.

    Application diagnostics are frequent during streaming and connector work. A
    synchronous open/repair/write/flush/fsync for every row can stall the shared
    asyncio/render thread even when the Chat screen is not visible. This writer
    serializes rows on its worker, groups records by path for a short interval,
    and performs one protected append and one flush/fsync per batch. Explicit
    reads and shutdown flush pending rows so observable ordering remains durable.
    Every instance is stoppable and registered for bounded process teardown.
    """

    _instances_lock = threading.RLock()
    _instances: "weakref.WeakSet[BatchedJSONLWriter]" = weakref.WeakSet()

    def __init__(
        self,
        *,
        batch_delay_seconds: float = 0.04,
        max_batch_rows: int = 256,
        write_batch: Callable[[Path, list[Any]], None] | None = None,
    ) -> None:
        self.batch_delay_seconds = max(0.0, float(batch_delay_seconds))
        self.max_batch_rows = max(1, int(max_batch_rows))
        self._write_batch_callback = write_batch or self._write_batch_default
        self._condition = threading.Condition(threading.RLock())
        self._pending: dict[Path, list[Any]] = {}
        self._pending_since: dict[Path, float] = {}
        self._force_paths: set[Path] = set()
        self._inflight: set[Path] = set()
        self._errors: dict[Path, str] = {}
        self._thread: threading.Thread | None = None
        self._stopping = False
        with self._instances_lock:
            self._instances.add(self)

    def _ensure_thread_locked(self) -> None:
        if self._stopping:
            raise RuntimeError("JSONL writer is shutting down")
        if self._thread is not None and self._thread.is_alive():
            return
        self._thread = threading.Thread(
            target=self._run, name="VeloxJSONLWriter", daemon=True,
        )
        self._thread.start()

    @staticmethod
    def _write_batch_default(path: Path, rows: list[Any]) -> None:
        encoded = b"".join(
            (json.dumps(row, ensure_ascii=False, separators=(",", ":"), default=str) + "\n").encode("utf-8")
            for row in rows
        )
        if not encoded:
            return
        path = Path(path)
        # The app/root initializer owns directory creation. A delayed diagnostic
        # batch must never recreate a temporary data root after a test or shutdown
        # has removed it. Recheck under the same data-root lock used by deletion-
        # aware test cleanup before opening the append handle.
        if not path.parent.is_dir():
            return
        with DATA_ROOTS.lock_for_path(path):
            # Storage initialization creates log.jsonl synchronously. A delayed
            # batch may append only to that existing file; it must never recreate
            # a removed root while shutdown, cleanup, or a reset is deleting it.
            if not path.is_file():
                return
            # Open with FILE_SHARE_DELETE on Windows so a data-root removal
            # (test teardown or a reset) can proceed while this batch is live.
            with _open_jsonl_append_handle(path) as handle:
                _prepare_jsonl_for_append(handle)
                handle.seek(0, os.SEEK_END)
                handle.write(encoded)
                try:
                    handle.flush()
                    os.fsync(handle.fileno())
                except Exception:
                    pass

    def _submit_snapshot(self, path: Path, row: Any) -> None:
        resolved = Path(path)
        with self._condition:
            bucket = self._pending.setdefault(resolved, [])
            if not bucket:
                self._pending_since[resolved] = time.monotonic()
            bucket.append(row)
            if len(bucket) >= self.max_batch_rows:
                self._force_paths.add(resolved)
            self._errors.pop(resolved, None)
            self._ensure_thread_locked()
            self._condition.notify_all()

    def submit(self, path: Path, row: Any) -> None:
        """Queue a detached snapshot for callers that retain/mutate ``row``."""
        self._submit_snapshot(path, copy.deepcopy(row))

    def submit_owned(self, path: Path, row: Any) -> None:
        """Queue a caller-owned record without a redundant deep copy.

        The caller transfers ownership and must not mutate the value afterward.
        Application logging constructs a fresh bounded flat record for every call,
        so this avoids one allocation-heavy deepcopy on the render/async thread.
        """
        self._submit_snapshot(path, row)

    def _run(self) -> None:
        while True:
            with self._condition:
                while not self._pending and not self._stopping:
                    self._condition.wait()
                if self._stopping and not self._pending:
                    self._thread = None
                    self._condition.notify_all()
                    return
                path = next(iter(self._pending))
                while True:
                    queued = self._pending.get(path) or []
                    if not queued:
                        break
                    force = path in self._force_paths or len(queued) >= self.max_batch_rows
                    deadline = float(self._pending_since.get(path, time.monotonic())) + self.batch_delay_seconds
                    remaining = deadline - time.monotonic()
                    if force or remaining <= 0:
                        break
                    self._condition.wait(min(remaining, 0.05))
                rows = self._pending.pop(path, [])
                self._pending_since.pop(path, None)
                self._force_paths.discard(path)
                if not rows:
                    continue
                self._inflight.add(path)
            error = ""
            try:
                self._write_batch_callback(path, rows)
            except Exception as exc:
                error = f"{type(exc).__name__}: {exc}"
            with self._condition:
                self._inflight.discard(path)
                if error:
                    self._errors[path] = error
                else:
                    self._errors.pop(path, None)
                self._condition.notify_all()

    def flush(self, paths: Iterable[Path] | None = None, *, timeout: float = 15.0) -> bool:
        selected = None if paths is None else {Path(path) for path in paths}
        deadline = time.monotonic() + max(0.01, float(timeout))
        with self._condition:
            if selected is None:
                self._force_paths.update(self._pending)
            else:
                self._force_paths.update(path for path in selected if path in self._pending)
            self._condition.notify_all()
            while True:
                if selected is None:
                    busy = bool(self._pending or self._inflight)
                else:
                    busy = any(path in self._pending or path in self._inflight for path in selected)
                if not busy:
                    return True
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    return False
                self._condition.wait(min(0.1, remaining))


    def clear_for_tests(self) -> None:
        # Force every queued path once, then perform one bounded suite-wide drain.
        # Never erase an in-flight marker early: the worker owns that transition.
        self.flush(timeout=3.0)
        with self._condition:
            self._pending.clear()
            self._pending_since.clear()
            self._force_paths.clear()
            self._errors.clear()
            self._condition.notify_all()


    def shutdown(self, *, timeout: float = 3.0) -> bool:
        """Flush pending diagnostics, stop the worker, and join it boundedly."""
        self.flush(timeout=max(0.01, float(timeout)))
        with self._condition:
            self._stopping = True
            self._pending.clear()
            self._pending_since.clear()
            self._force_paths.clear()
            self._condition.notify_all()
            thread = self._thread
        if thread is not None and thread is not threading.current_thread():
            thread.join(max(0.01, float(timeout)))
        return not bool(thread and thread.is_alive())


APP_LOG_WRITER = BatchedJSONLWriter()


def _flush_pending_jsonl_for_read(path: Path) -> None:
    writer = globals().get("APP_LOG_WRITER")
    if writer is not None:
        try:
            writer.flush((Path(path),), timeout=5.0)
        except Exception:
            pass


def iter_jsonl(path: Path) -> list[dict[str, Any]]:
    """Read JSONL while diagnosing corruption but tolerating a torn final row.

    Chat, request, and tool logs can become large. Streaming avoids a second full
    in-memory copy. A process interruption can leave only the final append without
    its newline and incomplete JSON; that one tail fragment is ignored and will
    be repaired before the next append. Newline-terminated corrupt rows remain
    visible as diagnostics and strict record loaders still reject them.
    """
    path = Path(path)
    _flush_pending_jsonl_for_read(path)
    if not path.exists():
        return []
    out: list[dict[str, Any]] = []
    try:
        with DATA_ROOTS.lock_for_path(path):
            with _plain_open_with_retry(
                path, "r", encoding="utf-8", errors="replace", newline="",
            ) as handle:
                for raw_line in handle:
                    line = raw_line.strip()
                    if not line:
                        continue
                    try:
                        obj = json.loads(line)
                        if isinstance(obj, dict):
                            out.append(obj)
                    except Exception:
                        if not raw_line.endswith(("\n", "\r")):
                            continue
                        out.append({"schema": "corrupt_jsonl_line.v1", "path": str(path), "line": line[:500]})
    except FileNotFoundError:
        return []
    return out


def iter_jsonl_tail(path: Path, limit: int) -> list[dict[str, Any]]:
    """Read at most the last ``limit`` non-empty JSONL records.

    The implementation scans backwards in bounded binary chunks, so developer
    request feeds and append-only histories do not reread an entire
    append-only log merely to display its newest rows. Returned rows preserve file
    order and corrupt-line diagnostics. A non-positive limit returns an empty list.
    """
    path = Path(path)
    _flush_pending_jsonl_for_read(path)
    limit = max(0, int(limit))
    if limit <= 0 or not path.exists():
        return []
    chunk_size = 64 * 1024
    data = bytearray()
    try:
        with DATA_ROOTS.lock_for_path(path):
            with _plain_open_with_retry(path, "rb") as handle:
                handle.seek(0, os.SEEK_END)
                position = handle.tell()
                newline_count = 0
                while position > 0 and newline_count <= limit:
                    take = min(chunk_size, position)
                    position -= take
                    handle.seek(position)
                    block = handle.read(take)
                    data[:0] = block
                    newline_count += block.count(b"\n")
            raw_lines = bytes(data).splitlines(keepends=True)
    except FileNotFoundError:
        return []
    non_empty = [line for line in raw_lines if line.strip()]
    # Include one extra candidate because an ignored crash-torn final fragment
    # must not reduce the requested number of preceding valid records.
    selected = non_empty[-(limit + 1):]
    out: list[dict[str, Any]] = []
    for raw in selected:
        line = raw.decode("utf-8", errors="replace").strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
            if isinstance(obj, dict):
                out.append(obj)
        except Exception:
            if not raw.endswith((b"\n", b"\r")):
                continue
            out.append({"schema": "corrupt_jsonl_line.v1", "path": str(path), "line": line[:500]})
    return out[-limit:]


LOG_FILE_NAME = "log.jsonl"
LOG_LEVEL_ERROR = 0
LOG_LEVEL_WARNING = 1
LOG_LEVEL_INFO = 2
LOG_SEVERITY_BY_LEVEL = {
    LOG_LEVEL_ERROR: "error",
    LOG_LEVEL_WARNING: "warning",
    LOG_LEVEL_INFO: "info",
}


def infer_log_level(event_type: Any = "", data: Any = None) -> int:
    """Classify one log event without treating empty error fields as failures."""
    event = str(event_type or "").strip().lower()

    def event_has(tokens: tuple[str, ...]) -> bool:
        if not event:
            return False
        pattern = r"(?:^|[._\-\s])(?:" + "|".join(re.escape(token) for token in tokens) + r")(?:$|[._\-\s])"
        return bool(re.search(pattern, event))

    if event_has(("error", "failed", "failure", "exception", "traceback", "crash", "crashed", "timeout", "timedout", "timed_out")):
        return LOG_LEVEL_ERROR
    if event_has(("warning", "warn", "cancelled", "canceled", "blocked", "retry", "retrying", "skipped")):
        return LOG_LEVEL_WARNING

    empty_values = (None, "", False)
    error_states = {"error", "failed", "failure", "exception", "crash", "crashed", "timeout", "timed_out"}
    warning_states = {"warning", "warn", "cancelled", "canceled", "blocked", "retry", "retrying", "skipped"}

    def inspect(value: Any, depth: int = 0) -> int | None:
        if depth > 4:
            return None
        if isinstance(value, dict):
            severity = str(value.get("severity") or "").strip().lower()
            if severity in error_states:
                return LOG_LEVEL_ERROR
            if severity in warning_states:
                return LOG_LEVEL_WARNING
            for key, item in value.items():
                normalized_key = str(key or "").strip().lower().replace("-", "_")
                nonempty = item not in empty_values and item != [] and item != {}
                if normalized_key in {"error", "errors", "error_message", "exception", "traceback"} and nonempty:
                    return LOG_LEVEL_ERROR
                if normalized_key in {"warning", "warnings", "warning_message"} and nonempty:
                    return LOG_LEVEL_WARNING
                if normalized_key in {"status", "state", "result_state"}:
                    state = str(item or "").strip().lower().replace("-", "_")
                    if state in error_states:
                        return LOG_LEVEL_ERROR
                    if state in warning_states:
                        return LOG_LEVEL_WARNING
            # Inspect nested records only after direct status/error fields so a
            # concrete parent state wins over incidental nested text.
            for item in value.values():
                nested = inspect(item, depth + 1)
                if nested in (LOG_LEVEL_ERROR, LOG_LEVEL_WARNING):
                    return nested
            return None
        if isinstance(value, (list, tuple)):
            for item in value:
                nested = inspect(item, depth + 1)
                if nested in (LOG_LEVEL_ERROR, LOG_LEVEL_WARNING):
                    return nested
        return None

    inferred = inspect(data)
    return LOG_LEVEL_INFO if inferred is None else inferred


LOG_COMPACT_MAX_STRING_CHARS = 1200
LOG_COMPACT_MAX_CONTAINER_ITEMS = 40
LOG_COMPACT_MAX_DEPTH = 5


def compact_log_payload(value: Any, *, _depth: int = 0) -> Any:
    """Bound log work before serialization instead of truncating afterward.

    A tool record can contain multi-megabyte streamed text or nested provider
    payloads. Serializing the complete object only to slice the result to 4,000
    characters made cancellation/finalization capable of monopolizing the UI
    thread. Small ordinary records remain structurally unchanged; large strings
    and containers receive explicit omission markers after a bounded walk.
    """
    if value is None or isinstance(value, (bool, int, float)):
        return value
    if isinstance(value, str):
        if len(value) <= LOG_COMPACT_MAX_STRING_CHARS:
            return value
        omitted = len(value) - LOG_COMPACT_MAX_STRING_CHARS
        return value[:LOG_COMPACT_MAX_STRING_CHARS] + f"...[{omitted:,} chars omitted]"
    if isinstance(value, bytes):
        return f"[bytes: {len(value):,}]"
    if _depth >= LOG_COMPACT_MAX_DEPTH:
        if isinstance(value, dict):
            return f"[object: {len(value):,} fields]"
        if isinstance(value, (list, tuple, set, frozenset)):
            return f"[sequence: {len(value):,} items]"
        return str(value)[:LOG_COMPACT_MAX_STRING_CHARS]
    if isinstance(value, dict):
        result: dict[str, Any] = {}
        priority = (
            "error", "errors", "warning", "warnings", "status", "state",
            "tool_name", "tool_call_id", "chat_id", "agent_id", "message",
        )
        ordered_keys: list[Any] = []
        seen: set[Any] = set()
        for key in priority:
            if key in value:
                ordered_keys.append(key)
                seen.add(key)
        for key in value:
            if key not in seen:
                ordered_keys.append(key)
                seen.add(key)
            if len(ordered_keys) >= LOG_COMPACT_MAX_CONTAINER_ITEMS:
                break
        for key in ordered_keys:
            result[str(key)] = compact_log_payload(value.get(key), _depth=_depth + 1)
        omitted = max(0, len(value) - len(ordered_keys))
        if omitted:
            result["__omitted_fields__"] = omitted
        return result
    if isinstance(value, (list, tuple, set, frozenset)):
        rows = list(itertools.islice(iter(value), LOG_COMPACT_MAX_CONTAINER_ITEMS))
        result = [compact_log_payload(row, _depth=_depth + 1) for row in rows]
        omitted = max(0, len(value) - len(rows))
        if omitted:
            result.append(f"[{omitted:,} items omitted]")
        return result
    return str(value)[:LOG_COMPACT_MAX_STRING_CHARS]


def _compact_log_message_from_bounded(event_type: Any, bounded: Any) -> str:
    event = str(event_type or "log").strip() or "log"
    if bounded is None or bounded == {}:
        return event[:2000]
    try:
        payload = json.dumps(bounded, ensure_ascii=False, separators=JSON_COMPACT_SEPARATORS, default=str)
    except Exception:
        payload = str(bounded)
    return f"{event} {payload}"[:4000]


def compact_log_message(event_type: Any, data: Any = None) -> str:
    return _compact_log_message_from_bounded(event_type, compact_log_payload(data))


def append_simple_log(path: Path, msg: str, level: int = LOG_LEVEL_INFO) -> None:
    path = Path(path)
    message = str(msg or "").strip()[:4000]
    if not message:
        return
    try:
        lvl = int(level)
    except Exception:
        lvl = LOG_LEVEL_INFO
    normalized_level = int(clamp(lvl, LOG_LEVEL_ERROR, LOG_LEVEL_INFO))
    APP_LOG_WRITER.submit_owned(path, {
        "severity": LOG_SEVERITY_BY_LEVEL[normalized_level],
        "level": normalized_level,
        "datetime": now_iso(),
        "log msg": message,
    })


def read_simple_logs(path: Path, max_level: int = LOG_LEVEL_INFO, limit: int = 500) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    try:
        threshold = int(max_level)
    except Exception:
        threshold = LOG_LEVEL_INFO
    for obj in iter_jsonl_tail(Path(path), max(1, int(limit))):
        # log.jsonl has one compact row shape. Ignore unrelated or malformed
        # objects instead of presenting them as application log entries.
        if not isinstance(obj, dict) or "log msg" not in obj:
            continue
        try:
            lvl = int(obj.get("level", LOG_LEVEL_INFO))
        except Exception:
            lvl = LOG_LEVEL_INFO
        row = {
            "severity": LOG_SEVERITY_BY_LEVEL[int(clamp(lvl, LOG_LEVEL_ERROR, LOG_LEVEL_INFO))],
            "level": int(clamp(lvl, LOG_LEVEL_ERROR, LOG_LEVEL_INFO)),
            "datetime": str(obj.get("datetime") or ""),
            "log msg": str(obj.get("log msg") or "")[:4000],
        }
        if int(row["level"]) <= threshold and row["log msg"]:
            rows.append(row)
    return rows


def safe_filename(name: str) -> str:
    name = re.sub(r"[^a-zA-Z0-9._ -]+", "_", name or "")
    return name.strip(" .")[:160] or "file"


def attachment_meta_is_image(meta: dict[str, Any] | None) -> bool:
    """Return whether attachment metadata describes an image MIME type."""
    return str((meta or {}).get("mime") or "").lower().startswith("image/")


BARE_WEB_LINK_RE = re.compile(
    r"(?i)(?:https?://|www\.)[^\s<>\[\]{}\"']+"
)
WINDOWS_ABSOLUTE_PATH_PREFIX_RE = re.compile(
    r"(?i)(?:[a-z]:[\\/]|\\\\[^\\/\s]+[\\/][^\\/\s]+)"
)
RELATIVE_LOCAL_PATH_ROOT_NAMES = ("workspace", "attachments", "attachments_processed", "temp")
RELATIVE_LOCAL_PATH_SUFFIXES = frozenset({
    ".png", ".jpg", ".jpeg", ".gif", ".bmp", ".webp", ".svg",
    ".txt", ".md", ".rst", ".log", ".json", ".jsonl", ".yaml", ".yml", ".toml",
    ".ini", ".cfg", ".conf", ".csv", ".tsv", ".xml", ".html", ".htm", ".css",
    ".js", ".mjs", ".cjs", ".ts", ".tsx", ".jsx", ".py", ".pyw", ".c", ".cc",
    ".cpp", ".cxx", ".h", ".hh", ".hpp", ".hxx", ".cs", ".java", ".kt", ".kts",
    ".go", ".rs", ".rb", ".php", ".sh", ".bash", ".zsh", ".ps1", ".bat", ".cmd",
    ".sql", ".pdf", ".doc", ".docx", ".xls", ".xlsx", ".ppt", ".pptx", ".odt",
    ".ods", ".odp", ".rtf", ".zip", ".7z", ".tar", ".gz", ".tgz", ".bz2", ".xz",
    ".rar", ".wasm", ".glsl", ".vert", ".frag", ".hlsl", ".spv", ".obj", ".fbx",
    ".gltf", ".glb", ".stl", ".wav", ".mp3", ".ogg", ".flac", ".mp4", ".webm", ".mov",
})
RELATIVE_LOCAL_PATH_RE = re.compile(
    r"(?i)(?:(?:workspace|attachments|attachments_processed|temp)[\\/]|(?:\.\.?)[\\/])?"
    r"(?:[A-Za-z0-9_.-]+[\\/])*[A-Za-z0-9_.-]+\.[A-Za-z0-9]{1,12}"
)


def _trim_autolink_trailing_punctuation(value: str) -> str:
    """Trim sentence punctuation without discarding balanced URL/path delimiters."""
    text = str(value or "").rstrip()
    while text and text[-1] in ".,;:!?":
        text = text[:-1]
    # A closing bracket belongs to the surrounding prose when it is unmatched
    # inside the candidate itself. Balanced brackets remain part of the target.
    pairs = ((")", "("), ("]", "["), ("}", "{"))
    changed = True
    while text and changed:
        changed = False
        for close, open_ in pairs:
            if text.endswith(close) and text.count(close) > text.count(open_):
                text = text[:-1].rstrip()
                changed = True
    return text


def match_bare_web_link_at(text: str, index: int) -> tuple[str, str, int] | None:
    """Return display text, browser target, and end for a well-formed bare URL."""
    raw = str(text or "")
    i = max(0, int(index))
    if i >= len(raw):
        return None
    if i > 0 and (raw[i - 1].isalnum() or raw[i - 1] in "_@"):
        return None
    match = BARE_WEB_LINK_RE.match(raw, i)
    if not match:
        return None
    display = _trim_autolink_trailing_punctuation(match.group(0))
    if not display:
        return None
    end = i + len(display)
    target = display if display.lower().startswith(("http://", "https://")) else "https://" + display
    try:
        parsed = urllib.parse.urlsplit(target)
        host = str(parsed.hostname or "")
        if parsed.scheme not in {"http", "https"} or not parsed.netloc or not host:
            return None
        normalized_host = host.rstrip(".")
        if normalized_host.lower() != "localhost":
            if ":" in normalized_host:
                if not re.fullmatch(r"[0-9A-Fa-f:.]+", normalized_host):
                    return None
            else:
                labels = normalized_host.split(".")
                if len(labels) < 2 or any(
                    not re.fullmatch(r"[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?", label)
                    for label in labels
                ):
                    return None
    except Exception:
        return None
    return display, target, end


def is_windows_absolute_path_text(value: Any) -> bool:
    text = str(value or "").strip().strip('"')
    return bool(WINDOWS_ABSOLUTE_PATH_PREFIX_RE.match(text))


def match_absolute_file_path_at(text: str, index: int) -> tuple[str, str, int] | None:
    """Detect an absolute Windows path in prose without linking relative paths.

    Unquoted paths without spaces are always recognized. For paths containing
    spaces, Velox additionally selects the longest prefix that exists on disk,
    which avoids swallowing the rest of an ordinary sentence.
    """
    raw = str(text or "")
    i = max(0, int(index))
    if i >= len(raw) or not WINDOWS_ABSOLUTE_PATH_PREFIX_RE.match(raw, i):
        return None
    if i > 0 and (raw[i - 1].isalnum() or raw[i - 1] == "_"):
        return None
    line_end = len(raw)
    for marker in ("\n", "\r", "<", ">", '"', "|", "`"):
        found = raw.find(marker, i)
        if found >= 0:
            line_end = min(line_end, found)
    candidate = raw[i:line_end].rstrip()
    if not candidate:
        return None

    # Quoted absolute paths have an unambiguous end, so preserve spaces even
    # when the target does not exist yet (for example, a planned output path).
    if i > 0 and raw[i - 1] in {'"', "'"} and is_windows_absolute_path_text(candidate):
        return candidate, candidate, i + len(candidate)

    # Prefer the longest real local path when spaces are present. This is used
    # only as disambiguation; no access restriction is imposed by the renderer.
    if " " in candidate and sys.platform == "win32":
        boundary_indices = {len(candidate)}
        boundary_indices.update(pos for pos, ch in enumerate(candidate, 1) if ch.isspace() or ch in ".,;:!?)]}")
        for end_rel in sorted(boundary_indices, reverse=True):
            probe = _trim_autolink_trailing_punctuation(candidate[:end_rel]).rstrip()
            if not is_windows_absolute_path_text(probe):
                continue
            try:
                if Path(probe).exists():
                    return probe, probe, i + len(probe)
            except Exception:
                continue

    # Conservative fallback for non-existing/unquoted paths: stop at whitespace.
    simple = re.match(r"(?i)(?:[a-z]:[\\/]|\\\\[^\\/\s]+[\\/][^\\/\s]+)[^\s<>\"|`]*", raw[i:])
    if not simple:
        return None
    display = _trim_autolink_trailing_punctuation(simple.group(0))
    if not display:
        return None
    return display, display, i + len(display)


def is_probable_relative_local_path_text(value: Any) -> bool:
    """Return whether text is a conservative chat-relative file reference."""
    raw = urllib.parse.unquote(str(value or "").strip().strip('"').strip("'"))
    if not raw or raw.startswith(("/", "\\")) or is_windows_absolute_path_text(raw):
        return False
    parsed = urllib.parse.urlsplit(raw)
    if parsed.scheme or parsed.netloc:
        return False
    normalized = raw.replace("\\", "/")
    if any(part in {"", "."} for part in normalized.split("/")[:-1]):
        # A leading ./ is valid; empty middle components are not useful links.
        if not normalized.startswith("./"):
            return False
    leaf = normalized.rsplit("/", 1)[-1]
    suffix = Path(leaf).suffix.casefold()
    return bool(leaf and suffix in RELATIVE_LOCAL_PATH_SUFFIXES)


def match_relative_file_path_at(text: str, index: int) -> tuple[str, str, int] | None:
    """Detect a conservative bare chat-workspace-relative file path in prose."""
    raw = str(text or "")
    i = max(0, int(index))
    if i >= len(raw):
        return None
    if i > 0 and (raw[i - 1].isalnum() or raw[i - 1] in "_@/\\"):
        return None
    match = RELATIVE_LOCAL_PATH_RE.match(raw, i)
    if not match:
        return None
    display = _trim_autolink_trailing_punctuation(match.group(0))
    if not display or not is_probable_relative_local_path_text(display):
        return None
    return display, display, i + len(display)


def local_path_from_link_target(target: str) -> Path | None:
    """Convert file:// or absolute Windows link targets into a local Path."""
    raw = str(target or "").strip()
    if not raw:
        return None
    if raw.lower().startswith("file://"):
        try:
            parsed = urllib.parse.urlsplit(raw)
            path_text = urllib.request.url2pathname(urllib.parse.unquote(parsed.path or ""))
            if parsed.netloc and parsed.netloc.lower() not in {"", "localhost"}:
                path_text = f"//{parsed.netloc}{path_text}"
            return Path(path_text)
        except Exception:
            return None
    if is_windows_absolute_path_text(raw):
        return Path(raw.strip('"'))
    try:
        path = Path(raw).expanduser()
        return path if path.is_absolute() else None
    except Exception:
        return None


def open_local_path_parent(path: Path) -> None:
    """Open a local file's containing directory, or a directory itself."""
    local = Path(path).expanduser()
    try:
        resolved = local.resolve(strict=False)
    except Exception:
        resolved = local
    folder = resolved if resolved.is_dir() else resolved.parent
    if sys.platform == "win32":
        subprocess.Popen(["explorer.exe", str(folder)])
    elif sys.platform == "darwin":
        subprocess.Popen(["open", str(folder)])
    else:
        subprocess.Popen(["xdg-open", str(folder)])


def open_local_path(path: Path) -> None:
    """Open a local file or directory with the operating-system default app."""
    local = Path(path).expanduser()
    try:
        resolved = local.resolve(strict=False)
    except Exception:
        resolved = local
    if sys.platform == "win32":
        os.startfile(str(resolved))  # type: ignore[attr-defined]
    elif sys.platform == "darwin":
        subprocess.Popen(["open", str(resolved)])
    else:
        subprocess.Popen(["xdg-open", str(resolved)])


def powershell_single_quoted_content(value: Any) -> str:
    """Escape content for a PowerShell single-quoted string literal.

    Python 3.10 is Velox's target runtime. Keep path normalization and escaping
    outside f-string expressions because Python 3.10 rejects backslashes inside
    f-string expression blocks.
    """
    return str(value or "").replace("'", "''")


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    path = Path(path)
    with DATA_ROOTS.lock_for_path(path):
        with path.open("rb") as handle:
            while True:
                chunk = handle.read(1024 * 1024)
                if not chunk:
                    break
                h.update(chunk)
    return h.hexdigest()

def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(bytes(data or b"")).hexdigest()


def ensure_inside(parent: Path, child: Path) -> Path:
    parent = parent.resolve()
    child = child.resolve()
    try:
        child.relative_to(parent)
    except ValueError:
        raise PermissionError(f"path outside allowed root: {child}")
    return child


def clamp(v: int | float, lo: int | float, hi: int | float) -> int | float:
    return max(lo, min(hi, v))


def bounded_timeout_seconds(
    requested: Any,
    configured_maximum: Any,
    *,
    minimum: float = 1.0,
    maximum: float | None = None,
) -> float:
    """Return a finite timeout no larger than the configured app limit.

    Tool-call timeout parameters are optional requests for a *smaller* budget;
    they must never bypass the user-configured maximum. Invalid, blank,
    non-finite, boolean, zero, and negative request values fall back to the
    configured maximum rather than producing an unbounded or immediate call.
    """
    floor = max(0.001, float(minimum))
    try:
        cap = float(configured_maximum)
    except Exception:
        cap = floor
    if not math.isfinite(cap) or cap < floor:
        cap = floor
    if maximum is not None:
        try:
            hard_maximum = float(maximum)
        except Exception:
            hard_maximum = cap
        if math.isfinite(hard_maximum) and hard_maximum >= floor:
            cap = min(cap, hard_maximum)
    if requested is None or isinstance(requested, bool) or not str(requested).strip():
        return cap
    try:
        candidate = float(requested)
    except Exception:
        return cap
    if not math.isfinite(candidate) or candidate <= 0:
        return cap
    return max(floor, min(candidate, cap))


def bounded_positive_int(
    value: Any,
    default: int,
    *,
    minimum: int = 1,
    maximum: int | None = None,
) -> int:
    """Return an integer with a minimum and an optional explicit maximum.

    Passing ``maximum=None`` is intentional: user-configured resource budgets do
    not receive a second hidden ceiling. Callers may pass a configured maximum to
    bound a per-call request, or a semantic/protocol maximum where one exists.
    """
    try:
        if isinstance(value, bool):
            raise ValueError("boolean is not an integer resource limit")
        parsed = int(value)
    except Exception:
        parsed = int(default)
    parsed = max(int(minimum), parsed)
    if maximum is not None:
        parsed = min(parsed, max(int(minimum), int(maximum)))
    return int(parsed)


def _config_mapping(config: dict[str, Any] | None, section: str) -> dict[str, Any]:
    raw = (config or {}).get(section) if isinstance(config, dict) else {}
    return raw if isinstance(raw, dict) else {}


def configured_int(
    config: dict[str, Any] | None,
    section: str,
    key: str,
    default: int,
    *,
    minimum: int = 1,
) -> int:
    """Read a user resource integer without imposing an undisclosed upper cap."""
    raw = _config_mapping(config, section).get(key, default)
    return bounded_positive_int(raw, default, minimum=minimum, maximum=None)


def configured_float(
    config: dict[str, Any] | None,
    section: str,
    key: str,
    default: float,
    *,
    minimum: float = 0.0,
) -> float:
    """Read a finite user resource float without an undisclosed upper cap."""
    try:
        if isinstance(_config_mapping(config, section).get(key, default), bool):
            raise ValueError("boolean is not a floating-point resource limit")
        value = float(_config_mapping(config, section).get(key, default))
    except Exception:
        value = float(default)
    if not math.isfinite(value):
        value = float(default)
    return max(float(minimum), value)


def llm_activity_stall_warning_seconds(config: dict[str, Any] | None) -> float:
    """Return the editable no-stream-progress warning threshold in seconds."""
    minutes = configured_float(
        config, "llm", "stall_detection_minutes",
        LLM_ACTIVITY_STALL_WARNING_MINUTES_DEFAULT,
        minimum=LLM_ACTIVITY_STALL_WARNING_MINUTES_MIN,
    )
    return float(minutes) * 60.0


def tool_setting_int(config: dict[str, Any] | None, key: str) -> int:
    default, minimum, _kind = TOOL_RESOURCE_SETTING_SPECS[key]
    return configured_int(config, "tools", key, int(default), minimum=int(minimum))


def tool_setting_float(config: dict[str, Any] | None, key: str) -> float:
    default, minimum, _kind = TOOL_RESOURCE_SETTING_SPECS[key]
    return configured_float(config, "tools", key, float(default), minimum=float(minimum))


def execution_timeout_minutes(
    config: dict[str, Any] | None, args: dict[str, Any] | None, setting_key: str, *, tool_name: str,
) -> float:
    """Bound the required per-call budget by the user-editable execution ceiling."""
    raw = (args or {}).get("timeout_minutes")
    if raw is None or raw == "":
        raise ValueError(f"{tool_name} timeout_minutes is required and must be a positive finite number")
    if isinstance(raw, bool):
        raise ValueError(f"{tool_name} timeout_minutes must be a positive finite number")
    try:
        value = float(raw)
    except Exception as exc:
        raise ValueError(f"{tool_name} timeout_minutes must be a positive finite number") from exc
    if not math.isfinite(value) or value <= 0:
        raise ValueError(f"{tool_name} timeout_minutes must be a positive finite number")
    return min(value, tool_setting_float(config, setting_key))


def web_setting_int(config: dict[str, Any] | None, key: str) -> int:
    default, minimum, _kind = WEB_RESOURCE_SETTING_SPECS[key]
    return configured_int(config, "web", key, int(default), minimum=int(minimum))


def web_setting_float(config: dict[str, Any] | None, key: str) -> float:
    default, minimum, _kind = WEB_RESOURCE_SETTING_SPECS[key]
    return configured_float(config, "web", key, float(default), minimum=float(minimum))


def _nonnegative_token_value(value: Any) -> int | None:
    """Return a finite non-negative token count, or None for an absent value."""
    if value is None or isinstance(value, bool):
        return None
    try:
        number = float(value)
    except Exception:
        return None
    if not math.isfinite(number) or number < 0:
        return None
    return int(number)


TOKEN_INPUT_ALIASES = (
    "prompt_tokens", "input_tokens", "prompt_eval_count", "prompt_n",
    "tokens_evaluated", "n_prompt_tokens",
)
TOKEN_OUTPUT_ALIASES = (
    "completion_tokens", "output_tokens", "eval_count", "predicted_n",
    "tokens_predicted", "n_decoded_tokens",
)
CHAT_INPUT_TOKEN_ALIASES = ("input_tokens", "prompt_tokens", "prompt_eval_count", "_estimated_prompt_tokens")
CHAT_OUTPUT_TOKEN_ALIASES = ("output_tokens", "completion_tokens", "eval_count", "approx_output_tokens")
def _stats_nonnegative_float(mapping: dict[str, Any] | None, *names: str) -> float | None:
    source = mapping if isinstance(mapping, dict) else {}
    for name in names:
        value = source.get(name)
        if value is None or isinstance(value, bool):
            continue
        try:
            number = float(value)
        except Exception:
            continue
        if math.isfinite(number) and number >= 0:
            return number
    return None


def _iso_timestamp_epoch(value: Any) -> float | None:
    """Return a finite epoch value from datetime, numeric epoch, or ISO text.

    Runtime UI code passes monotonic snapshots as numeric wall-clock epochs while
    persisted records use ISO timestamps. Keeping this coercion at the boundary
    prevents a malformed or mixed representation from crashing the render loop.
    """
    if isinstance(value, datetime):
        parsed = value
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        try:
            epoch = float(parsed.timestamp())
            return epoch if math.isfinite(epoch) else None
        except Exception:
            return None
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        try:
            epoch = float(value)
            return epoch if math.isfinite(epoch) else None
        except Exception:
            return None
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        epoch = float(parsed.timestamp())
        return epoch if math.isfinite(epoch) else None
    except Exception:
        return None


def chat_thread_runtime_stats(
    turns: Iterable[dict[str, Any]],
    *,
    current_time: datetime | float | int | None = None,
) -> dict[str, Any]:
    """Aggregate chat-owned inference and tool execution without counting agents.

    Per-turn ``execution_seconds`` is the wall-clock active period from the first
    request until that turn becomes terminal, so it is the authoritative total.
    Prompt/generation and tool durations are retained separately. Token rates are
    weighted across the chat by dividing summed tokens by summed active seconds;
    averaging already-rounded per-turn rates would over-weight short responses.
    """
    now_epoch = _iso_timestamp_epoch(current_time) if current_time is not None else None
    if now_epoch is None:
        now_epoch = time.time()
    totals: dict[str, Any] = {
        "turn_count": 0,
        "model_round_count": 0,
        "tool_call_count": 0,
        "failed_tool_call_count": 0,
        "compaction_count": 0,
        "total_runtime_seconds": 0.0,
        "inference_runtime_seconds": 0.0,
        "tool_runtime_seconds": 0.0,
        "endpoint_wait_seconds": 0.0,
        "overhead_runtime_seconds": 0.0,
        "prompt_seconds": 0.0,
        "generation_seconds": 0.0,
        "waiting_for_first_output_seconds": 0.0,
        "input_tokens": 0,
        **dict.fromkeys(CACHE_USAGE_FIELDS, 0),
        "output_tokens": 0,
        "measured_input_tokens": 0,
        "measured_output_tokens": 0,
        "unobserved_inference_seconds": 0.0,
        "largest_response_output_tokens": 0,
    }
    turn_rows = [turn for turn in (turns or []) if isinstance(turn, dict)]
    for turn in turn_rows:
        if str(turn.get("role") or "") not in {"assistant", "compaction"}:
            continue
        stats = turn.get("stats") if isinstance(turn.get("stats"), dict) else {}
        calls = [row for row in (turn.get("tool_calls") or []) if isinstance(row, dict)]
        if not stats and not calls:
            continue
        totals["turn_count"] += 1
        if str((turn.get("compaction_meta") or {}).get("kind") or "") == "chat_context_compaction" or str(turn.get("role") or "") == "compaction":
            totals["compaction_count"] += 1

        prompt_seconds = _stats_nonnegative_float(stats, "prompt_seconds") or 0.0
        generation_seconds = _stats_nonnegative_float(stats, "generation_seconds") or 0.0
        waiting_for_first_output_seconds = (
            _stats_nonnegative_float(stats, "waiting_for_first_output_seconds") or 0.0
        )
        explicit_tool_seconds = _stats_nonnegative_float(stats, "tool_seconds") or 0.0
        observed_tool_seconds = sum(
            tool_call_elapsed_seconds(row, current_time=now_epoch) for row in calls
        )
        tool_seconds = max(explicit_tool_seconds, observed_tool_seconds)
        endpoint_wait_seconds = (
            _stats_nonnegative_float(stats, "endpoint_wait_seconds") or 0.0
        )
        inference_seconds = _stats_nonnegative_float(stats, "inference_seconds")
        if inference_seconds is None:
            inference_seconds = (
                prompt_seconds + generation_seconds + waiting_for_first_output_seconds
            )

        execution_seconds = _stats_nonnegative_float(stats, "execution_seconds", "total_seconds")
        if execution_seconds is None:
            duration_ms = _stats_nonnegative_float(stats, "duration_ms")
            execution_seconds = (
                duration_ms / 1000.0 if duration_ms is not None
                else inference_seconds + tool_seconds + endpoint_wait_seconds
            )
        if str(turn.get("status") or "") == "streaming":
            started_epoch = _iso_timestamp_epoch(stats.get("started_at"))
            if started_epoch is None:
                started_epoch = _iso_timestamp_epoch(turn.get("created_at"))
            if started_epoch is not None:
                execution_seconds = max(execution_seconds, max(0.0, now_epoch - started_epoch))

        input_value = next(
            (parsed for key in CHAT_INPUT_TOKEN_ALIASES if (parsed := _nonnegative_token_value(stats.get(key))) is not None),
            0,
        )
        output_value = next(
            (parsed for key in CHAT_OUTPUT_TOKEN_ALIASES if (parsed := _nonnegative_token_value(stats.get(key))) is not None),
            0,
        )
        totals.update(add_cache_usage_counters(totals, stats))
        totals["input_tokens"] += int(input_value)
        totals["output_tokens"] += int(output_value)
        if prompt_seconds > 0:
            totals["measured_input_tokens"] += int(input_value)
        if generation_seconds > 0:
            totals["measured_output_tokens"] += int(output_value)
        totals["unobserved_inference_seconds"] += _stats_nonnegative_float(stats, "unobserved_inference_seconds") or 0.0
        if str(turn.get("role") or "") == "assistant":
            totals["largest_response_output_tokens"] = max(
                int(totals.get("largest_response_output_tokens") or 0), int(output_value),
            )
        totals["prompt_seconds"] += prompt_seconds
        totals["generation_seconds"] += generation_seconds
        totals["waiting_for_first_output_seconds"] += waiting_for_first_output_seconds
        totals["inference_runtime_seconds"] += max(0.0, inference_seconds)
        totals["tool_runtime_seconds"] += max(0.0, tool_seconds)
        totals["endpoint_wait_seconds"] += max(0.0, endpoint_wait_seconds)
        totals["total_runtime_seconds"] += max(0.0, execution_seconds)
        totals["overhead_runtime_seconds"] += max(
            0.0,
            execution_seconds - inference_seconds - tool_seconds - endpoint_wait_seconds,
        )
        totals["model_round_count"] += max(1, int(stats.get("model_round_count") or 1))
        totals["tool_call_count"] += max(int(stats.get("tool_call_count") or 0), len(calls))
        totals["failed_tool_call_count"] += sum(
            1 for row in calls
            if row.get("ok") is False or str(row.get("status") or "").lower() in {"failed", "error"}
        )

    prompt_seconds = float(totals["prompt_seconds"])
    generation_seconds = float(totals["generation_seconds"])
    totals["average_prompt_tokens_per_second"] = (
        float(totals["measured_input_tokens"]) / prompt_seconds if prompt_seconds > 0 else 0.0
    )
    totals["average_generation_tokens_per_second"] = (
        float(totals["measured_output_tokens"]) / generation_seconds if generation_seconds > 0 else 0.0
    )
    return totals


_DURABLE_SECRET_KEY_RE = re.compile(
    r"(?i)(?:api[_-]?key|api[_-]?token|access[_-]?token|refresh[_-]?token|client[_-]?secret|"
    r"password|authorization|cookie|credential|private[_-]?key|app[_-]?password|secret|(?:^|[_-])pat(?:$|[_-]))"
)
_DURABLE_SECRET_TEXT_PATTERNS: tuple[tuple[re.Pattern[str], str], ...] = (
    # Authenticated HTTP(S) Git/SCM URLs. Preserve the destination but never userinfo.
    (re.compile(r"(?i)\b(https?://)[^/\s:@]+:[^@\s/]+@([^\s/]+)"), r"\1[REDACTED]@\2"),
    # Authorization/Bearer credentials, including prose copies of headers.
    (re.compile(r"(?i)(authorization\s*[:=]\s*bearer\s+)[^\s,;\"']+"), r"\1[REDACTED]"),
    (re.compile(r"(?i)\b(bearer\s+)[A-Za-z0-9._~+/=-]{8,}"), r"\1[REDACTED]"),
    (re.compile(r"(?i)(authorization\s*[:=]\s*)(?!bearer\b)[^\s,;\"']+"), r"\1[REDACTED]"),
    # Recognizable token families. Bare hexadecimal hashes are deliberately absent.
    (re.compile(r"\b(?:ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9]{16,}\b", re.I), "[REDACTED]"),
    (re.compile(r"\bgithub_pat_[A-Za-z0-9_]{16,}\b", re.I), "[REDACTED]"),
    (re.compile(r"\b(?:sk[-_]|nvapi[-_]|msy_)[A-Za-z0-9_-]{12,}\b", re.I), "[REDACTED]"),
    (re.compile(r"\bxox[baprs]-[A-Za-z0-9-]{12,}\b", re.I), "[REDACTED]"),
    # Structured credential fields in JSON, config text, shell assignments, etc.
    (re.compile(r"(?i)([\"']?(?:api[_-]?key|api[_-]?token|access[_-]?token|refresh[_-]?token|client[_-]?secret|password|authorization|credential|private[_-]?key|app[_-]?password|secret|pat)[\"']?\s*[:=]\s*[\"'])[^\"']+([\"'])"), r"\1[REDACTED]\2"),
    (re.compile(r"(?i)(\b(?:api[_-]?key|api[_-]?token|access[_-]?token|refresh[_-]?token|client[_-]?secret|password|authorization|credential|private[_-]?key|app[_-]?password|secret|pat)\b\s*[:=]\s*)([^\s,;}\]]+)"), r"\1[REDACTED]"),
    (re.compile(r"(?i)([?&](?:api[_-]?key|api[_-]?token|access[_-]?token|token|auth|authorization|secret|password|credential)=)[^&#\s]+"), r"\1[REDACTED]"),
)


def redact_durable_secret_text(value: Any) -> str:
    """Redact recognizable credentials without touching ordinary hashes/IDs."""
    text = str(value if value is not None else "")
    for pattern, replacement in _DURABLE_SECRET_TEXT_PATTERNS:
        text = pattern.sub(replacement, text)
    return text


def redact_durable_secrets(value: Any, *, key_name: str = "") -> Any:
    """Return a recursively redacted copy suitable for durable review/debug artifacts."""
    if key_name and _DURABLE_SECRET_KEY_RE.search(str(key_name)):
        return "[REDACTED]"
    if isinstance(value, dict):
        return {
            str(key): redact_durable_secrets(item, key_name=str(key))
            for key, item in value.items()
        }
    if isinstance(value, list):
        return [redact_durable_secrets(item) for item in value]
    if isinstance(value, tuple):
        return tuple(redact_durable_secrets(item) for item in value)
    if isinstance(value, str):
        return redact_durable_secret_text(value)
    return copy.deepcopy(value)


_DEBUG_REPORT_SECRET_KEY_RE = _DURABLE_SECRET_KEY_RE
_DEBUG_REPORT_SECRET_TEXT_PATTERNS = _DURABLE_SECRET_TEXT_PATTERNS


def redact_chat_debug_text(value: Any) -> str:
    """Redact durable credential forms while retaining debugging structure and prose."""
    return redact_durable_secret_text(value)


def _iter_debug_report_section(title: str) -> Iterable[str]:
    yield from ("", "=" * 88, str(title), "=" * 88)


def debug_export_destination(raw: str | Path, directory: str | Path) -> Path:
    """Resolve a Save choice only at its action boundary, never each idle frame."""
    text = str(raw).strip().strip('"')
    if not text or "\x00" in text:
        raise ValueError("Enter a text report file name.")
    path = Path(text).expanduser()
    if not path.is_absolute():
        path = Path(directory).expanduser() / path
    path = Path(os.path.abspath(path))
    if path.is_dir():
        raise ValueError("Choose a file name, not a folder.")
    if path.suffix.lower() != ".txt":
        path = path.with_name(path.name + ".txt")
    if not path.parent.is_dir():
        raise ValueError("The destination folder does not exist.")
    debug_export_target_stamp(path)  # Reject symlinks and special files.
    return path


def debug_export_target_stamp(path: Path) -> tuple[int, int, int, int, int] | None:
    """Bind overwrite permission to the file actually selected by the user."""
    try:
        stat_result = path.lstat()
    except FileNotFoundError:
        return None
    import stat as stat_module
    if not stat_module.S_ISREG(stat_result.st_mode):
        raise ValueError("The export destination must be a regular file, not a link or device.")
    return (stat_result.st_dev, stat_result.st_ino, stat_result.st_size,
            stat_result.st_mtime_ns, stat_result.st_ctime_ns)


def write_debug_report_atomic(
    path: Path,
    lines: Iterable[str],
    *,
    expected_target: tuple[int, int, int, int, int] | None = None,
    cancel_event: threading.Event | None = None,
) -> dict[str, Any]:
    """Incrementally write a UTF-8 report, then atomically publish a complete file.

    None means create-only, NOT overwrite-anything. A confirmed existing target
    is rechecked before replacement. A new destination uses an atomic no-clobber
    operation; even a file created during export cannot be silently overwritten.
    """
    path = Path(path)
    temporary: Path | None = None
    size = 0
    digest = hashlib.sha256()

    def cancelled() -> None:
        if cancel_event is not None and cancel_event.is_set():
            raise InterruptedError("Debug report export cancelled before publication.")

    cancelled()
    if debug_export_target_stamp(path) != expected_target:
        raise FileExistsError("The export destination changed. Choose it again to confirm replacement.")
    try:
        fd, temp_name = tempfile.mkstemp(prefix=".velox-debug-", suffix=".tmp", dir=str(path.parent))
        temporary = Path(temp_name)
        with os.fdopen(fd, "wb", buffering=256 * 1024) as output:
            first = True
            for line in lines:
                cancelled()
                # Every scalar is redacted before splitting by the canonical
                # iterators. This final pass also protects header and key labels.
                text = ("" if first else "\n") + redact_chat_debug_text(line)
                first = False
                for offset in range(0, len(text), 64 * 1024):
                    cancelled()
                    data = text[offset:offset + 64 * 1024].encode("utf-8", errors="backslashreplace")
                    output.write(data)
                    size += len(data)
                    digest.update(data)
            cancelled()
            output.flush()
            os.fsync(output.fileno())
        with DATA_ROOTS.lock_for_path(path):
            cancelled()
            if debug_export_target_stamp(path) != expected_target:
                raise FileExistsError("The export destination changed during generation; existing file retained.")
            if expected_target is not None:
                os.replace(temporary, path)
                temporary = None
            elif os.name == "nt":
                # Windows rename is create-only, unlike POSIX rename.
                os.rename(temporary, path)
                temporary = None
            else:
                # Atomic no-clobber publication on POSIX. Unsupported filesystems
                # fail explicitly instead of falling back to a partial final file.
                os.link(temporary, path)
        return {"path": str(path), "bytes": size, "sha256": digest.hexdigest()}
    finally:
        if temporary is not None:
            try:
                temporary.unlink(missing_ok=True)
            except OSError:
                # A cleanup failure cannot undo a successfully published report
                # or mask the original disk/permission/generation error.
                pass


VLLM_CACHE_REPORTING_HINT = (
    "vLLM: enable --enable-prompt-tokens-details on the server; prefix caching alone "
    "does not enable usage reporting. If already enabled, check the serving version's "
    "cache reporting path. Missing per-request counts cannot be inferred from /metrics."
)


def cache_reporting_diagnostics(endpoint: dict[str, Any], usage: dict[str, Any] | None) -> dict[str, Any]:
    """Describe observed response reporting, without guessing a cache hit rate."""
    count = cached_input_tokens_from_usage(usage)
    total = first_usage_value(llm_usage_sources(usage), LLM_PROMPT_TOKEN_KEYS)
    fields = {}
    for source in llm_usage_sources(usage):
        for key in ("prompt_tokens_details", "input_tokens_details", "prompt_cache_hit_tokens"):
            if key in source and key not in fields:
                value = source[key]
                fields[key] = (dict(value) if isinstance(value, dict) else value)
    result = {
        "state": "reported" if count is not None else "not_reported_or_invalid",
        "input_tokens": total, "cached_input_tokens": count,
        "observed_fields": fields,
    }
    if count is None and endpoint_provider(endpoint) == ENDPOINT_PROVIDER_VLLM:
        result["guidance"] = VLLM_CACHE_REPORTING_HINT
    return result


def _iter_debug_report_value_lines(value: Any, *, indent: int=0, key_name: str='', seen: set[int] | None=None) -> Iterable[str]:
    """Render nested records as readable indented text, never JSON syntax."""
    prefix = ' ' * max(0, int(indent))
    if seen is None:
        seen = set()
    if _DEBUG_REPORT_SECRET_KEY_RE.search(str(key_name or '')):
        yield from [prefix + '[REDACTED]']
        return
    if isinstance(value, dict):
        identity = id(value)
        if identity in seen:
            yield from [prefix + '[circular reference]']
            return
        seen.add(identity)
        if not value:
            seen.discard(identity)
            yield from [prefix + '(empty mapping)']
            return
        for raw_key in sorted(value, key=lambda item: str(item).casefold()):
            key = str(raw_key)
            item = value[raw_key]
            if _DEBUG_REPORT_SECRET_KEY_RE.search(key):
                yield (prefix + key + ': [REDACTED]')
                continue
            if isinstance(item, (dict, list, tuple)):
                yield (prefix + key + ':')
                yield from _iter_debug_report_value_lines(item, indent=indent + 2, key_name=key, seen=seen)
            else:
                scalar = redact_chat_debug_text(item)
                if '\n' in scalar:
                    yield (prefix + key + ':')
                    yield from (prefix + '  | ' + part for part in scalar.splitlines() or [''])
                else:
                    yield (prefix + key + ': ' + (scalar if scalar else '(empty)'))
        seen.discard(identity)
        return
    if isinstance(value, (list, tuple)):
        identity = id(value)
        if identity in seen:
            yield from [prefix + '[circular reference]']
            return
        seen.add(identity)
        if not value:
            seen.discard(identity)
            yield from [prefix + '(empty list)']
            return
        for index, item in enumerate(value):
            label = f'- item {index + 1}'
            if isinstance(item, (dict, list, tuple)):
                yield (prefix + label + ':')
                yield from _iter_debug_report_value_lines(item, indent=indent + 2, key_name=key_name, seen=seen)
            else:
                scalar = redact_chat_debug_text(item)
                if '\n' in scalar:
                    yield (prefix + label + ':')
                    yield from (prefix + '  | ' + part for part in scalar.splitlines() or [''])
                else:
                    yield (prefix + label + ': ' + (scalar if scalar else '(empty)'))
        seen.discard(identity)
        return
    scalar = redact_chat_debug_text(value)
    if '\n' in scalar:
        yield from [prefix + '| ' + part for part in scalar.splitlines() or ['']]
        return
    yield from [prefix + (scalar if scalar else '(empty)')]
    return


def _chat_debug_report_value_lines(*args: Any, **kwargs: Any) -> list[str]:
    return list(_iter_debug_report_value_lines(*args, **kwargs))


def _chat_debug_report_section(lines: list[str], title: str) -> None:
    lines.extend(["", "=" * 88, str(title), "=" * 88])


def iter_chat_debug_report_lines(chat: dict[str, Any], turns: Iterable[dict[str, Any]], *, endpoint: dict[str, Any] | None=None, tool_settings: dict[str, Any] | None=None, summary_record: dict[str, Any] | None=None, data_root: str='', generated_at: str | None=None) -> Iterable[str]:
    """Build a detailed, human-readable diagnostic report for one chat.

    The report intentionally includes correspondence, reasoning, tool metadata,
    compaction records, endpoint settings, and aggregate timing while avoiding
    JSON formatting. Common credential fields and token-shaped strings are
    redacted before the text reaches the export.
    """
    turn_rows = [row for row in turns or [] if isinstance(row, dict)]
    aggregate = chat_thread_runtime_stats(turn_rows)
    yield from ['VELOX CHAT DEBUG REPORT', 'This report is intended for debugging Velox, model behavior, tools, prompts, and Skills.', 'Known credential fields and common token patterns are redacted. Review private content before sharing. Unpaired Unicode codepoints are escaped.', '', f'Generated: {generated_at or now_iso()}', f'Application version: {APP_VERSION}', f'Source revision: V{SOURCE_REVISION}', f'Application schema: {APP_SCHEMA}', f'Turn schema: {CHAT_TURN_SCHEMA}', f"Data root: {(redact_chat_debug_text(data_root) if data_root else '(not supplied)')}"]
    yield from _iter_debug_report_section('CHAT RECORD')
    yield from _iter_debug_report_value_lines(chat, indent=0, key_name='chat')
    yield from _iter_debug_report_section('AGGREGATE CHAT STATISTICS')
    aggregate_display = {'turns with runtime data': aggregate.get('turn_count'), 'model rounds': aggregate.get('model_round_count'), 'tool calls': aggregate.get('tool_call_count'), 'failed tool calls': aggregate.get('failed_tool_call_count'), 'compaction events': aggregate.get('compaction_count'), 'total execution runtime seconds': aggregate.get('total_runtime_seconds'), 'inference runtime seconds': aggregate.get('inference_runtime_seconds'), 'tool runtime seconds': aggregate.get('tool_runtime_seconds'), 'non-inference overhead seconds': aggregate.get('overhead_runtime_seconds'), 'input-processing seconds': aggregate.get('prompt_seconds'), 'waiting for first endpoint output seconds': aggregate.get('waiting_for_first_output_seconds'), 'generation seconds': aggregate.get('generation_seconds'), 'input tokens': aggregate.get('input_tokens'), 'cached input tokens': aggregate.get('cached_input_tokens'), 'cache reported requests': aggregate.get('cache_reported_rounds'), 'cache total requests': aggregate.get('cache_total_rounds'), 'output tokens': aggregate.get('output_tokens'), 'largest response output tokens': aggregate.get('largest_response_output_tokens'), 'weighted input tokens per second': aggregate.get('average_prompt_tokens_per_second'), 'weighted generation tokens per second': aggregate.get('average_generation_tokens_per_second')}
    yield from _iter_debug_report_value_lines(aggregate_display)
    yield from _iter_debug_report_section('ACTIVE ENDPOINT')
    if endpoint_provider(endpoint or {}) == ENDPOINT_PROVIDER_VLLM:
        yield VLLM_CACHE_REPORTING_HINT
    yield from _iter_debug_report_value_lines(endpoint or {}, key_name='endpoint')
    yield from _iter_debug_report_section('RELEVANT TOOL AND CHAT SETTINGS')
    yield from _iter_debug_report_value_lines(tool_settings or {}, key_name='settings')
    yield from _iter_debug_report_section('STORED CHAT SUMMARY')
    yield from _iter_debug_report_value_lines(summary_record or {}, key_name='summary')
    yield from _iter_debug_report_section('COMPLETE CORRESPONDENCE AND TURN METADATA')
    if not turn_rows:
        yield '(no turns)'
    for index, turn in enumerate(turn_rows, start=1):
        yield from ['', '-' * 88, f'TURN {index}', '-' * 88, f"role: {turn.get('role') or '(missing)'}", f"status: {turn.get('status') or '(missing)'}", f"turn_id: {turn.get('turn_id') or '(missing)'}", f"chat_id: {turn.get('chat_id') or chat.get('chat_id') or '(missing)'}", f"created_at: {turn.get('created_at') or '(missing)'}", f"updated_at: {turn.get('updated_at') or '(missing)'}", f"endpoint_profile_id: {turn.get('endpoint_profile_id') or '(none)'}", f"endpoint_label: {turn.get('endpoint_label') or '(none)'}"]
        for field_title, field_name in (('TEXT', 'text'), ('DEDICATED REASONING CONTENT', 'reasoning_content'), ('STREAMING TOOL PREVIEW', 'streaming_tool_preview')):
            value = turn.get(field_name)
            if value not in (None, ''):
                yield from ['', field_title, '~' * len(field_title)]
                yield from (redact_chat_debug_text(value).splitlines() or [''])
        for field_title, field_name in (('TURN STATISTICS', 'stats'), ('ATTACHMENTS', 'attachments'), ('TOOL CALLS', 'tool_calls'), ('COMPACTION METADATA', 'compaction_meta'), ('COMPACTION SUMMARY', 'compaction_summary'), ('COMPACTION RESULTING MESSAGES', 'compaction_messages'), ('COMPACTION REQUEST MESSAGES', 'compaction_request_messages'), ('COMPACTION DETAILS', 'compaction_details'), ('EDIT HISTORY', 'edit_history')):
            value = turn.get(field_name)
            if value not in (None, '', [], {}):
                yield from ['', field_title, '~' * len(field_title)]
                yield from _iter_debug_report_value_lines(value, key_name=field_name)
        remaining = {key: value for key, value in turn.items() if key not in {'role', 'status', 'turn_id', 'chat_id', 'created_at', 'updated_at', 'endpoint_profile_id', 'endpoint_label', 'text', 'reasoning_content', 'streaming_tool_preview', 'stats', 'attachments', 'tool_calls', 'compaction_meta', 'compaction_summary', 'compaction_messages', 'compaction_request_messages', 'compaction_details', 'edit_history'}}
        if remaining:
            yield from ['', 'OTHER TURN FIELDS', '~~~~~~~~~~~~~~~~~']
            yield from _iter_debug_report_value_lines(remaining, key_name='turn')
    yield from ['', '=' * 88, 'END OF VELOX CHAT DEBUG REPORT', '=' * 88, '']
    return


def format_chat_debug_report(*args: Any, **kwargs: Any) -> str:
    return "\n".join(iter_chat_debug_report_lines(*args, **kwargs))


def format_compact_duration_seconds(value: Any) -> str:
    try:
        seconds = max(0.0, float(value or 0.0))
    except Exception:
        seconds = 0.0
    if seconds < 60.0:
        return f"{seconds:.1f} s"
    minutes, remaining = divmod(seconds, 60.0)
    if minutes < 60.0:
        return f"{int(minutes)}m {remaining:.1f}s"
    hours, minutes = divmod(int(minutes), 60)
    return f"{hours}h {minutes}m {remaining:.0f}s"


def visible_text_vertical_bounds(font: Any, text: str) -> tuple[int, int]:
    """Return top/bottom pixel bounds of visible glyph ink relative to draw y."""
    line_h = max(1, int(getattr(font, "line_h", 1) or 1))
    glyphs = getattr(font, "glyphs", {})
    fallback_map = getattr(font, "fallback_map", FONT_FALLBACK_MAP if "FONT_FALLBACK_MAP" in globals() else {})
    missing = glyphs.get("?") if isinstance(glyphs, dict) else None
    tops: list[int] = []
    bottoms: list[int] = []
    if isinstance(glyphs, dict):
        for char in str(text or ""):
            if char.isspace():
                continue
            mapped = font_render_chars(font, char)
            for draw_char in mapped:
                glyph = glyphs.get(draw_char) or missing
                if glyph is None:
                    continue
                height = max(0, int(getattr(glyph, "ah", 0) or 0))
                if height <= 0:
                    continue
                top = int(getattr(glyph, "y_offset", 0) or 0)
                tops.append(top)
                bottoms.append(top + height)
    if tops and bottoms:
        return min(tops), max(max(tops) + 1, max(bottoms))
    return 0, line_h


def centered_visible_text_y(font: Any, text: str, area_y: int, area_h: int) -> int:
    """Center visible glyph ink, rather than the font line box, in a vertical area."""
    top, bottom = visible_text_vertical_bounds(font, text)
    visible_h = max(1, bottom - top)
    return int(area_y) + (int(area_h) - visible_h) // 2 - top


def estimated_button_width(
    label: Any,
    *,
    measured_width: int | float | None = None,
    horizontal_padding: int = 32,
    min_width: int = 0,
) -> int:
    """Return a safe UI button width for an ordinary text label.

    The 12-pixel-per-character floor is an intentional implementation rule for
    new controls. Real font measurement may be wider, so callers pass the same
    renderer measurement used to draw the label whenever it is available.
    """
    text = str(label or "")
    try:
        measured = max(0, int(measured_width or 0))
    except Exception:
        measured = 0
    padding = max(0, int(horizontal_padding))
    return max(int(min_width), len(text) * 12 + padding, measured + padding)


def point_in_rect(x: int | float, y: int | float, r: "Rect") -> bool:
    return r.x <= x < r.x + r.w and r.y <= y < r.y + r.h


def rect_intersection(a: "Rect", b: "Rect") -> "Rect | None":
    x1 = max(a.x, b.x)
    y1 = max(a.y, b.y)
    x2 = min(a.x + a.w, b.x + b.w)
    y2 = min(a.y + a.h, b.y + b.h)
    if x2 <= x1 or y2 <= y1:
        return None
    return Rect(int(x1), int(y1), int(x2 - x1), int(y2 - y1))


def virtualized_rounded_rect_geometry(
    rect: "Rect",
    clip: "Rect",
    radius: int,
) -> tuple[list["Rect"], list["Rect"]]:
    """Return bounded visible fill/border strips for a very tall rounded rect.

    Immediate-mode chat cards can become hundreds of thousands of pixels tall.
    Sending that full geometry to SDL is wasteful even with a clip rectangle, and
    using the ever-changing full height as a rounded-strip cache key creates avoidable
    cache churn while tokens stream. This helper emits at most ``2 * radius + 5``
    small rectangles plus one visible middle slab, independent of the card height.

    The second list contains one-pixel border strips. Top/bottom rounded caps are
    preserved when those real edges are visible; a middle viewport slice receives
    only the two vertical edges.
    """
    visible = rect_intersection(rect, clip)
    if visible is None or rect.w <= 0 or rect.h <= 0:
        return [], []
    r = int(clamp(radius, 0, max(0, min(rect.w, rect.h) // 2)))
    if r <= 1:
        border: list[Rect] = []
        if rect.x >= clip.x and rect.x < clip.x + clip.w:
            border.append(Rect(rect.x, visible.y, 1, visible.h))
        right_x = rect.x + rect.w - 1
        if right_x >= clip.x and right_x < clip.x + clip.w:
            border.append(Rect(right_x, visible.y, 1, visible.h))
        if rect.y >= clip.y and rect.y < clip.y + clip.h:
            border.append(Rect(visible.x, rect.y, visible.w, 1))
        bottom_y = rect.y + rect.h - 1
        if bottom_y >= clip.y and bottom_y < clip.y + clip.h:
            border.append(Rect(visible.x, bottom_y, visible.w, 1))
        return [visible], border

    fills: list[Rect] = []
    borders: list[Rect] = []
    rect_bottom = rect.y + rect.h
    top_cap_bottom = min(rect_bottom, rect.y + r)
    bottom_cap_top = max(rect.y, rect_bottom - r)

    def add_cap_row(y: int, *, top: bool) -> None:
        local = (y - rect.y) if top else (rect_bottom - 1 - y)
        # Match Renderer._rounded_rect_strips' circle approximation while only
        # materializing the scanlines that can affect the current viewport.
        dy = r - (float(local) + 0.5)
        dx = int(max(0.0, r - math.sqrt(max(0.0, float(r * r) - dy * dy))))
        row = Rect(rect.x + dx, y, max(1, rect.w - 2 * dx), 1)
        clipped = rect_intersection(row, clip)
        if clipped is None:
            return
        fills.append(clipped)
        left_x = row.x
        right_x = row.x + row.w - 1
        if clip.x <= left_x < clip.x + clip.w:
            borders.append(Rect(left_x, y, 1, 1))
        if clip.x <= right_x < clip.x + clip.w and right_x != left_x:
            borders.append(Rect(right_x, y, 1, 1))
        if (top and y == rect.y) or ((not top) and y == rect_bottom - 1):
            borders.append(clipped)

    for y in range(max(visible.y, rect.y), min(visible.y + visible.h, top_cap_bottom)):
        add_cap_row(y, top=True)

    middle_y1 = max(visible.y, top_cap_bottom)
    middle_y2 = min(visible.y + visible.h, bottom_cap_top)
    if middle_y2 > middle_y1:
        middle = rect_intersection(Rect(rect.x, middle_y1, rect.w, middle_y2 - middle_y1), clip)
        if middle is not None:
            fills.append(middle)
        if clip.x <= rect.x < clip.x + clip.w:
            borders.append(Rect(rect.x, middle_y1, 1, middle_y2 - middle_y1))
        right_x = rect.x + rect.w - 1
        if clip.x <= right_x < clip.x + clip.w:
            borders.append(Rect(right_x, middle_y1, 1, middle_y2 - middle_y1))

    for y in range(max(visible.y, bottom_cap_top), min(visible.y + visible.h, rect_bottom)):
        add_cap_row(y, top=False)
    return fills, borders


def rects_intersect_fast(ax: int, ay: int, aw: int, ah: int, bx: int, by: int, bw: int, bh: int) -> bool:
    # hot-path helper: avoid allocating Rects just to reject offscreen draw commands.
    return aw > 0 and ah > 0 and bw > 0 and bh > 0 and ax < bx + bw and ax + aw > bx and ay < by + bh and ay + ah > by


def fast_text_signature(text: str, *, exact_limit: int = 8192) -> tuple[int, int, int, int]:
    """Cheap stable-enough signature for large text in per-frame caches."""
    text = str(text or "")
    n = len(text)
    if n <= exact_limit:
        return (n, hash(text), 0, 0)
    head = text[:1024]
    mid_i = max(0, n // 2 - 512)
    mid = text[mid_i:mid_i + 1024]
    tail = text[-1024:]
    return (n, hash(head), hash(mid), hash(tail))


def text_has_non_whitespace(text: Any) -> bool:
    """Return whether text contains visible content without allocating a copy.

    ``str.strip()`` is convenient but can scan and materialize another multi-
    megabyte string in hot streaming paths. ``isspace`` is implemented in C,
    stops at the first ordinary character for normal prose, and never creates a
    second string.
    """
    value = text if isinstance(text, str) else str(text or "")
    return bool(value) and not value.isspace()


def estimate_wrapped_line_count_fast(text: str, cols: int) -> int:
    # Estimate wrapping in O(lines) without materializing every line string.
    text = str(text or "")
    cols = max(1, int(cols))
    if not text:
        return 1
    count = 0
    start = 0
    n = len(text)
    while start <= n:
        end = text.find("\n", start)
        if end < 0:
            end = n
        line_len = end - start
        count += max(1, (line_len + cols - 1) // cols)
        if end >= n:
            break
        start = end + 1
    return max(1, count)


def chat_stream_ui_interval_seconds(
    output_chars: int, preview_chars: int = 0, *, visible: bool = True,
) -> float:
    """Return the adaptive publication interval for one growing response.

    Provider chunks continue to be consumed immediately. A chat that is not the
    active visible Chat panel publishes at a lower cadence because no frame can
    display those intermediate revisions; switching back still sees the newest
    in-memory checkpoint.
    """
    size = max(0, int(output_chars), int(preview_chars))
    if size >= CHAT_STREAM_UI_HUGE_CHARS:
        base = CHAT_STREAM_UI_INTERVAL_HUGE_SECONDS
    elif size >= CHAT_STREAM_UI_LARGE_CHARS:
        base = CHAT_STREAM_UI_INTERVAL_LARGE_SECONDS
    elif size >= CHAT_STREAM_UI_MEDIUM_CHARS:
        base = CHAT_STREAM_UI_INTERVAL_MEDIUM_SECONDS
    else:
        base = CHAT_STREAM_UI_INTERVAL_SMALL_SECONDS
    if visible:
        return base
    if size >= CHAT_STREAM_UI_HUGE_CHARS:
        return max(base, CHAT_STREAM_UI_BACKGROUND_HUGE_SECONDS)
    return max(base, CHAT_STREAM_UI_BACKGROUND_MIN_SECONDS)


def chat_stream_checkpoint_interval_seconds(output_chars: int) -> float:
    """Bound active-turn checkpoint frequency without delaying live UI state."""
    size = max(0, int(output_chars))
    if size >= CHAT_STREAM_UI_HUGE_CHARS:
        return CHAT_STREAM_CHECKPOINT_MAX_SECONDS
    if size <= CHAT_STREAM_UI_MEDIUM_CHARS:
        return CHAT_STREAM_CHECKPOINT_MIN_SECONDS
    span = max(1, CHAT_STREAM_UI_HUGE_CHARS - CHAT_STREAM_UI_MEDIUM_CHARS)
    ratio = (size - CHAT_STREAM_UI_MEDIUM_CHARS) / span
    return float(
        CHAT_STREAM_CHECKPOINT_MIN_SECONDS
        + (CHAT_STREAM_CHECKPOINT_MAX_SECONDS - CHAT_STREAM_CHECKPOINT_MIN_SECONDS)
        * clamp(ratio, 0.0, 1.0)
    )


FONT_FORCED_FALLBACK_MAP = {
    # Invisible formatting controls are normalized even when a selected font
    # advertises glyph coverage. Visible punctuation is allowed to render natively.
    "\u00a0": " ",       # no-break space
    "\u202f": " ",       # narrow no-break space
    "\u00ad": "",        # discretionary soft hyphen
    "\ufe0f": "", "\ufe0e": "", "\u200d": "",
}

# These substitutions are used only when the selected font lacks the native
# curated glyph. Common English typography therefore stays typographically rich
# when supported and remains readable instead of degrading to a tofu square.
FONT_FALLBACK_MAP = {
    "\u2011": "-",       # non-breaking hyphen when the font lacks it
    "\u2018": "'", "\u2019": "'", "\u201a": "'", "\u201b": "'",
    "\u201c": '"', "\u201d": '"', "\u201e": '"', "\u201f": '"',
    "\u2013": "-", "\u2014": "--", "\u2026": "...", "\u2022": "*",
    "\u2212": "-", "\u00d7": "x", "\u00f7": "/",
}


def font_render_chars(font: Any, ch: str) -> str:
    """Return the glyph sequence actually rendered for one Unicode character.

    Invisible formatting controls are normalized first. Visible curated characters,
    including U+2011, render natively whenever the selected font supplied a glyph;
    readable ASCII substitutions are used only when the native glyph is unavailable.
    """
    glyphs = getattr(font, "glyphs", {})
    forced_map = getattr(font, "forced_fallback_map", FONT_FORCED_FALLBACK_MAP)
    fallback_map = getattr(font, "fallback_map", FONT_FALLBACK_MAP)

    def usable_mapping(mapping: Any) -> str:
        mapped = str(mapping or "")
        if not mapped:
            return ""
        if not isinstance(glyphs, dict) or all(candidate in glyphs for candidate in mapped):
            return mapped
        return "?" if isinstance(glyphs, dict) and "?" in glyphs else mapped

    if isinstance(forced_map, dict) and ch in forced_map:
        return usable_mapping(forced_map.get(ch))
    if isinstance(glyphs, dict) and ch in glyphs:
        return ch
    if isinstance(fallback_map, dict) and ch in fallback_map:
        return usable_mapping(fallback_map.get(ch))
    return "?" if isinstance(glyphs, dict) and "?" in glyphs else ch


REASONING_TAG_RE = re.compile(r"(?is)<(/?)(think|thinking|reasoning)>")
ASSISTANT_SECTION_TOKEN_RE = re.compile(
    r"(?im)<(/?)(think|thinking|reasoning)>|^\s*\[\[VELOX_TOOL_ROW:(\d+)\]\]\s*$"
)


def strip_reasoning_content(text: str) -> str:
    """Remove LLM thinking/reasoning blocks from text before summarization/history.

    Chat rendering can still show these blocks when the user enables the setting,
    but durable history summaries should only preserve final user-visible output.
    Handles completed and unterminated <think>/<thinking>/<reasoning> blocks.
    """
    raw = str(text or "")
    if not raw:
        return ""
    out: list[str] = []
    pos = 0
    in_reasoning = False
    for m in REASONING_TAG_RE.finditer(raw):
        if not in_reasoning and m.start() > pos:
            out.append(raw[pos:m.start()])
        closing = bool(m.group(1))
        in_reasoning = False if closing else True
        pos = m.end()
    if not in_reasoning and pos < len(raw):
        out.append(raw[pos:])
    cleaned = "".join(out)
    # Collapse excessive blank space left behind by stripped reasoning cards while
    # preserving ordinary paragraph separation.
    cleaned = re.sub(r"\n{3,}", "\n\n", cleaned)
    return cleaned.strip()


def reasoning_content_from_text(text: str) -> str:
    """Return the exact text inside reasoning tags, preserving block order."""
    raw = str(text or "")
    if not raw:
        return ""
    parts: list[str] = []
    pos = 0
    in_reasoning = False
    for match in REASONING_TAG_RE.finditer(raw):
        closing = bool(match.group(1))
        if in_reasoning and match.start() > pos:
            parts.append(raw[pos:match.start()])
        in_reasoning = not closing
        pos = match.end()
    if in_reasoning and pos < len(raw):
        parts.append(raw[pos:])
    return "\n\n".join(part.strip("\n") for part in parts if part.strip()).strip()


def assistant_message_for_model_text(
    text: str, tool_call_line: str | None = None,
    *, response_output_items: list[dict[str, Any]] | None = None,
    reasoning_fields: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Convert Velox display text into one OpenAI-compatible assistant message.

    Reasoning models stream thinking inside Velox display tags, but Kimi and Qwen
    require the prior reasoning to return through the dedicated
    ``reasoning_content`` field during multi-step tool loops.
    """
    raw = str(text or "")
    reasoning_parts: list[str] = []
    for match in re.finditer(
        r"(?is)<(?:think|thinking|reasoning)>(.*?)</(?:think|thinking|reasoning)>", raw,
    ):
        cleaned = strip_tool_markup_from_text(match.group(1)).strip()
        if cleaned:
            reasoning_parts.append(cleaned)
    visible = re.sub(
        r"(?is)<(?:think|thinking|reasoning)>.*?</(?:think|thinking|reasoning)>",
        "", raw,
    )
    visible = strip_tool_markup_from_text(visible).strip()
    content = (visible + "\n" + str(tool_call_line or "")).strip() if tool_call_line else visible
    message: dict[str, Any] = {"role": "assistant", "content": content}
    if reasoning_parts:
        message["reasoning_content"] = "\n\n".join(reasoning_parts)
    if response_output_items:
        message["response_output_items"] = copy.deepcopy(response_output_items)
    return apply_assistant_reasoning_fields(message, reasoning_fields)


def assistant_message_for_openai_tool_calls(
    text: str, tool_calls: list[dict[str, Any]],
    *, response_output_items: list[dict[str, Any]] | None = None,
    reasoning_fields: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Build the complete assistant message required by native tool calling.

    Kimi K3 requires the whole assistant turn to be replayed after a tool call,
    including its generated reasoning and exact provider ``tool_calls`` array.
    Velox's ``[[VELOX_TOOL_ROW:n]]`` placeholders are UI-only durable markup,
    never model content. Strip them from both visible and reasoning replay so a
    later model round cannot learn/echo a placeholder and manufacture a second
    visual row for one real native call.
    """
    raw = str(text or "")
    visible = strip_tool_markup_from_text(strip_reasoning_content(raw)).strip()
    reasoning = strip_tool_markup_from_text(reasoning_content_from_text(raw)).strip()
    message: dict[str, Any] = {
        "role": "assistant",
        "content": visible or None,
        "tool_calls": copy.deepcopy(tool_calls),
    }
    if reasoning:
        message["reasoning_content"] = reasoning
    if response_output_items:
        message["response_output_items"] = copy.deepcopy(response_output_items)
    return apply_assistant_reasoning_fields(message, reasoning_fields)


def openai_tool_result_message(
    tool_call: dict[str, Any], content: Any, *, name: str = "",
) -> dict[str, Any]:
    message: dict[str, Any] = {
        "role": "tool",
        "tool_call_id": str(tool_call.get("id") or ""),
        "content": content,
    }
    function = tool_call.get("function") if isinstance(tool_call.get("function"), dict) else {}
    resolved_name = str(name or function.get("name") or "").strip()
    if resolved_name:
        message["name"] = resolved_name
    return message


# =============================================================================
# Data manifest, robust writes, and plain local files
# =============================================================================


DATA_MANIFEST_NAME = "app.json"


class UnsupportedDataVersionError(RuntimeError):
    pass


def _plain_read_bytes_with_retry(
    path: Path,
    *,
    retries: int = 8,
    base_delay_seconds: float = 0.01,
) -> bytes:
    """Read one file with short Windows-friendly retries for transient sharing locks.

    Antivirus, indexing, backup, and cloud-sync processes can briefly deny reads
    while an atomic replacement is settling. Retrying only permission/sharing and
    replacement races avoids turning a one-frame transient into an application
    crash while still surfacing persistent access or data errors promptly.
    """
    target = Path(path)
    attempts = max(1, int(retries))
    last_error: BaseException | None = None
    for attempt in range(attempts):
        try:
            return target.read_bytes()
        except (PermissionError, FileNotFoundError) as exc:
            last_error = exc
            if attempt + 1 >= attempts:
                break
            time.sleep(min(0.15, max(0.0, float(base_delay_seconds)) * (attempt + 1)))
        except OSError as exc:
            # Windows sharing violations may arrive as a generic OSError. Retry
            # only the known access/share codes; unrelated I/O failures remain
            # immediately visible.
            if getattr(exc, "winerror", None) not in {5, 32, 33}:
                raise
            last_error = exc
            if attempt + 1 >= attempts:
                break
            time.sleep(min(0.15, max(0.0, float(base_delay_seconds)) * (attempt + 1)))
    if last_error is not None:
        raise last_error
    raise FileNotFoundError(str(target))


def _plain_open_with_retry(
    path: Path,
    mode: str,
    *,
    retries: int = 8,
    base_delay_seconds: float = 0.01,
    **kwargs: Any,
) -> Any:
    """Open a path after short retries for transient Windows sharing locks."""
    target = Path(path)
    attempts = max(1, int(retries))
    last_error: BaseException | None = None
    for attempt in range(attempts):
        try:
            return target.open(mode, **kwargs)
        except (PermissionError, FileNotFoundError) as exc:
            last_error = exc
        except OSError as exc:
            if getattr(exc, "winerror", None) not in {5, 32, 33}:
                raise
            last_error = exc
        if attempt + 1 < attempts:
            time.sleep(min(0.15, max(0.0, float(base_delay_seconds)) * (attempt + 1)))
    if last_error is not None:
        raise last_error
    raise FileNotFoundError(str(target))


def _write_all_bytes(handle: Any, data: bytes) -> int:
    """Write every byte to ``handle``, raising on a short or stalled write."""
    view = memoryview(data)
    offset = 0
    while offset < len(view):
        written = handle.write(view[offset:])
        if written is None:
            written = 0
        if written <= 0:
            raise OSError(f"short write: wrote {offset} of {len(data)} bytes")
        offset += written
    return offset


def _plain_atomic_write_bytes(path: Path, data: bytes, *, retries: int = 30) -> None:
    """Publish ``data`` at ``path`` atomically, never overwriting in place.

    The complete replacement is written, flushed and fsynced to a same-directory
    temporary file which is then renamed onto ``path``. Any write, flush, fsync,
    close or replacement failure leaves the previous destination bytes unchanged
    and propagates the failure. The destination is never opened for an in-place
    overwrite by this helper.
    """
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + f".tmp.{uuid_v4()}")
    max_attempts = max(1, int(retries))
    try:
        with tmp.open("wb") as handle:
            written = _write_all_bytes(handle, data)
            if written != len(data):
                raise OSError(f"short write: wrote {written} of {len(data)} bytes to {path}")
            handle.flush()
            os.fsync(handle.fileno())
        # The temporary file is closed before publication; a failure above
        # (write, flush, fsync or close) prevents os.replace from running.
        last_error: BaseException | None = None
        for attempt in range(max_attempts):
            try:
                os.replace(tmp, path)
                return
            except PermissionError as exc:
                last_error = exc
            except OSError as exc:
                winerror = getattr(exc, "winerror", None)
                if winerror not in (5, 32, 33):
                    raise
                last_error = exc
            if attempt + 1 < max_attempts:
                time.sleep(min(0.5, 0.015 * (attempt + 1)))
        raise last_error if last_error is not None else OSError(f"could not replace {path}")
    finally:
        if tmp.exists() and tmp != path:
            try:
                tmp.unlink(missing_ok=True)
            except Exception:
                pass


def create_default_skills_for_new_install(root_dir: Path) -> None:
    """Seed bundled Skills only when creating a new application data root.

    Ordinary startup leaves existing Skill files alone. The machine-generated
    C/C++ Skill is refreshed separately from live toolchain discovery."""
    skills_dir = Path(root_dir).expanduser().resolve() / "skills"
    skills_dir.mkdir(parents=True, exist_ok=True)
    web_programming_markdown = build_web_programming_skill_markdown()
    cpp_programming_markdown = build_cpp_programming_skill_markdown()
    for name, markdown in (
        (DEFAULT_WRITING_SKILL_NAME, DEFAULT_WRITING_SKILL_MARKDOWN),
        (DEFAULT_HIGH_EFFORT_SKILL_NAME, DEFAULT_HIGH_EFFORT_SKILL_MARKDOWN),
        (DEFAULT_PERSONALIZATION_SKILL_NAME, DEFAULT_PERSONALIZATION_SKILL_MARKDOWN),
        (DEFAULT_NEWS_SKILL_NAME, DEFAULT_NEWS_SKILL_MARKDOWN),
        (DEFAULT_RESEARCH_SKILL_NAME, DEFAULT_RESEARCH_SKILL_MARKDOWN),
        (DEFAULT_IMAGE_ANALYSIS_SKILL_NAME, DEFAULT_IMAGE_ANALYSIS_SKILL_MARKDOWN),
        (DEFAULT_UI_UX_SKILL_NAME, DEFAULT_UI_UX_SKILL_MARKDOWN),
        (DEFAULT_NATIVE_TEXT_GLYPH_RENDERING_SKILL_NAME, DEFAULT_NATIVE_TEXT_GLYPH_RENDERING_SKILL_MARKDOWN),
        (DEFAULT_GENERAL_PROGRAMMING_SKILL_NAME, DEFAULT_GENERAL_PROGRAMMING_SKILL_MARKDOWN),
        (DEFAULT_WEB_PROGRAMMING_SKILL_NAME, web_programming_markdown),
        (DEFAULT_WEBGL_PROGRAMMING_SKILL_NAME, DEFAULT_WEBGL_PROGRAMMING_SKILL_MARKDOWN),
        (DEFAULT_3D_RENDERING_PROGRAMMING_SKILL_NAME, DEFAULT_3D_RENDERING_PROGRAMMING_SKILL_MARKDOWN),
        (DEFAULT_CPP_PROGRAMMING_SKILL_NAME, cpp_programming_markdown),
        (DEFAULT_GENERAL_AGENT_SKILL_NAME, DEFAULT_GENERAL_AGENT_SKILL_MARKDOWN),
        (DEFAULT_PERSONAL_ASSISTANT_AGENT_SKILL_NAME, DEFAULT_PERSONAL_ASSISTANT_AGENT_SKILL_MARKDOWN),
        (DEFAULT_COMFYUI_SKILL_NAME, DEFAULT_COMFYUI_SKILL_MARKDOWN),
        (DEFAULT_MESHY_SKILL_NAME, DEFAULT_MESHY_SKILL_MARKDOWN),
    ):
        skill_dir = skills_dir / name
        skill_file = skill_dir / SKILL_FILE_NAME
        skill_dir.mkdir(parents=True, exist_ok=True)
        _plain_atomic_write_bytes(skill_file, markdown.encode("utf-8"))
        _plain_atomic_write_bytes(skill_dir / SKILL_MODE_FILE_NAME, json.dumps({
            "schema": SKILL_MODE_SCHEMA,
            "mode": "always" if name in DEFAULT_ALWAYS_SKILL_NAMES else "optional",
        }, sort_keys=True).encode("utf-8"))
        if name == DEFAULT_PERSONALIZATION_SKILL_NAME:
            _plain_atomic_write_bytes(
                skill_dir / PERSONALIZATION_USER_FILE_NAME,
                DEFAULT_PERSONALIZATION_USER_TEXT.encode("utf-8"),
            )


def refresh_machine_generated_skills_for_startup(root_dir: Path) -> None:
    """Regenerate machine-specific programming guidance from the live host on every startup."""
    skills_dir = Path(root_dir).expanduser().resolve() / "skills"
    cpp_dir = skills_dir / DEFAULT_CPP_PROGRAMMING_SKILL_NAME
    cpp_dir.mkdir(parents=True, exist_ok=True)
    _plain_atomic_write_bytes(
        cpp_dir / SKILL_FILE_NAME,
        build_cpp_programming_skill_markdown().encode("utf-8"),
    )


@dataclass
class DataRootContext:
    root_dir: Path

    @property
    def manifest_path(self) -> Path:
        return self.root_dir / DATA_MANIFEST_NAME


class DataRootRegistry:
    """Track app roots so atomic writes share one lock per running instance."""

    def __init__(self) -> None:
        self._contexts: dict[Path, DataRootContext] = {}
        self._locks: dict[Path, threading.RLock] = {}
        self._registry_lock = threading.RLock()
        # Path-to-root resolution occurs for every protected JSON/text read. Cache
        # exact normalized paths so repeated Context/Task scans and long-chat I/O
        # do not repeatedly call Path.resolve()/relative_to across every root.
        self._path_context_cache: dict[str, DataRootContext | None] = {}
        self._path_context_cache_limit = 32_768
        # Files outside a registered app root are uncommon but can still be
        # touched by explicitly requested absolute-path tools. One shared lock is
        # safer than returning a brand-new, ineffective lock for every call.
        self._external_lock = threading.RLock()

    def register(self, root_dir: Path) -> DataRootContext:
        root = Path(root_dir).expanduser().resolve()
        with self._registry_lock:
            ctx = self._contexts.get(root)
            if ctx is not None:
                return ctx
            ctx = DataRootContext(root)
            self._contexts[root] = ctx
            self._locks[root] = threading.RLock()
            # A newly registered nested root can change the best match for paths
            # cached before it existed.
            self._path_context_cache.clear()
            return ctx

    def context_for_path(self, path: Path) -> DataRootContext | None:
        raw = os.fspath(path)
        cache_key = os.path.normcase(os.path.abspath(os.path.expanduser(raw)))
        with self._registry_lock:
            if cache_key in self._path_context_cache:
                return self._path_context_cache[cache_key]
        try:
            resolved = Path(cache_key).resolve()
        except Exception:
            resolved = Path(cache_key)
        with self._registry_lock:
            best: DataRootContext | None = None
            best_len = -1
            for root, ctx in self._contexts.items():
                try:
                    resolved.relative_to(root)
                except Exception:
                    continue
                root_len = len(str(root))
                if root_len > best_len:
                    best = ctx
                    best_len = root_len
            if len(self._path_context_cache) >= self._path_context_cache_limit:
                self._path_context_cache.clear()
            self._path_context_cache[cache_key] = best
            return best

    def lock_for_path(self, path: Path) -> threading.RLock:
        ctx = self.context_for_path(path)
        if ctx is None:
            return self._external_lock
        with self._registry_lock:
            return self._locks.setdefault(ctx.root_dir, threading.RLock())

    def assert_supported(self, root_dir: Path) -> None:
        """Validate the on-disk manifest, never a stale registration snapshot."""
        ctx = self.register(root_dir)
        try:
            with self.lock_for_path(ctx.manifest_path):
                manifest = json.loads(_plain_read_bytes_with_retry(ctx.manifest_path).decode("utf-8"))
            current_version = str(manifest.get("data_version") or "") if isinstance(manifest, dict) else ""
        except FileNotFoundError:
            return
        except Exception:
            current_version = ""
        if current_version != DATA_FILE_VERSION:
            raise UnsupportedDataVersionError(
                f"Unsupported Velox data version {current_version or 'missing'}; "
                f"this build requires exactly {DATA_FILE_VERSION}."
            )

    def write_manifest(
        self,
        root_dir: Path,
        *,
        llm: dict[str, Any] | None = None,
    ) -> DataRootContext:
        root = Path(root_dir).expanduser().resolve()
        root.mkdir(parents=True, exist_ok=True)
        ctx = self.register(root)
        manifest = default_app_manifest()
        if isinstance(llm, dict):
            manifest.setdefault("settings", {})["llm"] = copy.deepcopy(llm)
        validate_exact_mapping_shape(manifest, default_app_manifest(), location="new app.json")
        validate_endpoint_profiles_config(manifest["settings"]["llm"], location="new app.json.settings.llm")
        manifest_path = root / DATA_MANIFEST_NAME
        with self.lock_for_path(manifest_path):
            _plain_atomic_write_bytes(
                manifest_path,
                json.dumps(manifest, ensure_ascii=False, indent=2).encode("utf-8"),
            )
            create_default_skills_for_new_install(root)
            with self._registry_lock:
                self._contexts[root] = ctx
                self._locks.setdefault(root, threading.RLock())
        return ctx

    def configure_first_run(self, root_dir: Path) -> DataRootContext:
        return self.write_manifest(root_dir)

    def clear_for_tests(self) -> None:
        # Drain background writers while their data-root locks still exist. A
        # test may remove and recreate the same temporary path immediately after
        # this call; no old worker may append into that replacement root.
        for writer_name in ("CHAT_STREAM_SNAPSHOT_WRITER", "APP_LOG_WRITER"):
            writer = globals().get(writer_name)
            if writer is not None:
                try:
                    writer.clear_for_tests()
                except Exception:
                    pass
        with self._registry_lock:
            self._contexts.clear()
            self._locks.clear()
            self._path_context_cache.clear()
        # Calendar record caches are keyed by absolute data-root path. Tests and
        # recovery flows may remove and recreate the same temporary path, so the
        # cache must not outlive a registry reset.
        for lock_name, cache_name in (
            ("_CALENDAR_RECORD_CACHES_LOCK", "_CALENDAR_RECORD_CACHES"),
            ("_VAULT_RECORD_CACHES_LOCK", "_VAULT_RECORD_CACHES"),
        ):
            cache_lock = globals().get(lock_name)
            caches = globals().get(cache_name)
            if cache_lock is not None and isinstance(caches, dict):
                with cache_lock:
                    caches.clear()


DATA_ROOTS = DataRootRegistry()


def default_app_manifest() -> dict[str, Any]:
    """Return the complete app.json payload for the current data model."""
    return {
        "schema": APP_SCHEMA,
        "data_version": DATA_FILE_VERSION,
        "settings": default_config(),
        "state": default_app_state(),
        "updated_at": now_iso(),
    }


def validate_exact_mapping_shape(value: Any, template: dict[str, Any], *, location: str) -> None:
    """Reject missing or unexpected dictionary fields at every schema level.

    Dictionary keys are structural, arrays remain arrays, and current scalar
    fields retain their JSON type. A successful write therefore cannot create an
    app.json that the next startup rejects because of a stale field or wrong type.
    """
    if not isinstance(value, dict):
        raise UnsupportedDataVersionError(f"{location} must be a JSON object")
    expected = set(template)
    actual = set(value)
    missing = sorted(str(key) for key in expected.difference(actual))
    extra = sorted(str(key) for key in actual.difference(expected))
    if missing or extra:
        details: list[str] = []
        if missing:
            details.append("missing: " + ", ".join(missing))
        if extra:
            details.append("unexpected: " + ", ".join(extra))
        raise UnsupportedDataVersionError(
            f"{location} fields do not match the current data model ({'; '.join(details)})"
        )
    for key, expected_value in template.items():
        actual_value = value[key]
        child_location = f"{location}.{key}"
        if isinstance(expected_value, dict):
            validate_exact_mapping_shape(actual_value, expected_value, location=child_location)
            continue
        if isinstance(expected_value, list):
            if not isinstance(actual_value, list):
                raise UnsupportedDataVersionError(f"{child_location} must be a JSON array")
            continue
        if isinstance(expected_value, bool):
            if not isinstance(actual_value, bool):
                raise UnsupportedDataVersionError(f"{child_location} must be a boolean")
            continue
        if isinstance(expected_value, (int, float)) and not isinstance(expected_value, bool):
            if isinstance(actual_value, bool) or not isinstance(actual_value, (int, float)):
                raise UnsupportedDataVersionError(f"{child_location} must be a finite number")
            if not math.isfinite(float(actual_value)):
                raise UnsupportedDataVersionError(f"{child_location} must be a finite number")
            continue
        if isinstance(expected_value, str):
            if not isinstance(actual_value, str):
                raise UnsupportedDataVersionError(f"{child_location} must be a string")
            continue
        # None is used for nullable scalar fields such as active_chat_id and
        # optional window coordinates. It must never conceal a nested object.
        if expected_value is None and isinstance(actual_value, (dict, list)):
            raise UnsupportedDataVersionError(f"{child_location} must be a scalar or null")


def file_read_bytes(path: Path) -> bytes:
    """Read a complete file under the app-root lock with transient-lock retries.

    Complete reads are still appropriate for bounded binary payloads such as
    images and API bodies. Text previews, copies, and hashes use streaming or
    prefix helpers so large user files do not need to fit in memory.
    """
    path = Path(path)
    with DATA_ROOTS.lock_for_path(path):
        return _plain_read_bytes_with_retry(path)


def file_write_bytes(path: Path, data: bytes) -> None:
    path = Path(path)
    with DATA_ROOTS.lock_for_path(path):
        _plain_atomic_write_bytes(path, data)


def atomic_copy_file(source: Path, destination: Path, *, chunk_size: int = 1024 * 1024) -> None:
    """Copy a file through a same-directory temporary file without loading it all."""
    source = Path(source)
    destination = Path(destination)
    destination.parent.mkdir(parents=True, exist_ok=True)
    with DATA_ROOTS.lock_for_path(destination):
        fd, temp_name = tempfile.mkstemp(prefix=f".{destination.name}.", suffix=".tmp", dir=str(destination.parent))
        temp_path = Path(temp_name)
        try:
            with _plain_open_with_retry(source, "rb") as src, os.fdopen(fd, "wb") as dst:
                fd = -1
                shutil.copyfileobj(src, dst, length=max(64 * 1024, int(chunk_size)))
                dst.flush()
                try:
                    os.fsync(dst.fileno())
                except OSError:
                    pass
            os.replace(temp_path, destination)
        except Exception:
            if fd >= 0:
                try:
                    os.close(fd)
                except OSError:
                    pass
            try:
                temp_path.unlink(missing_ok=True)
            except OSError:
                pass
            raise


def file_read_text(path: Path, *, encoding: str = "utf-8", errors: str = "strict") -> str:
    return file_read_bytes(path).decode(encoding, errors=errors)


def file_read_text_prefix(
    path: Path,
    max_chars: int,
    *,
    encoding: str = "utf-8",
    errors: str = "strict",
) -> tuple[str, bool]:
    """Read at most ``max_chars`` text characters and report truncation."""
    limit = max(1, int(max_chars))
    path = Path(path)
    with DATA_ROOTS.lock_for_path(path):
        with _plain_open_with_retry(
            path, "r", encoding=encoding, errors=errors, newline="",
        ) as handle:
            text = handle.read(limit + 1)
    return text[:limit], len(text) > limit


def file_write_text(path: Path, text: str, *, encoding: str = "utf-8") -> None:
    file_write_bytes(path, text.encode(encoding))


def file_size(path: Path) -> int:
    try:
        return Path(path).stat().st_size
    except Exception:
        return 0


def image_size_from_file(path: Path | str) -> tuple[int, int]:
    """Return image dimensions without importing UI code. Supports PIL and common PNG/JPEG headers."""
    path = Path(path)
    try:
        from PIL import Image  # type: ignore
        with Image.open(path) as im:
            return int(im.width), int(im.height)
    except Exception:
        pass
    try:
        with path.open("rb") as handle:
            data = handle.read(65536)
    except Exception:
        return 0, 0
    if data.startswith(b"\x89PNG\r\n\x1a\n") and len(data) >= 24:
        try:
            return int.from_bytes(data[16:20], "big"), int.from_bytes(data[20:24], "big")
        except Exception:
            return 0, 0
    if data[:6] in {b"GIF87a", b"GIF89a"} and len(data) >= 10:
        try:
            return int.from_bytes(data[6:8], "little"), int.from_bytes(data[8:10], "little")
        except Exception:
            return 0, 0
    if data.startswith(b"BM") and len(data) >= 26:
        try:
            width = abs(int.from_bytes(data[18:22], "little", signed=True))
            height = abs(int.from_bytes(data[22:26], "little", signed=True))
            return width, height
        except Exception:
            return 0, 0
    if data.startswith(b"RIFF") and data[8:12] == b"WEBP":
        try:
            if data[12:16] == b"VP8X" and len(data) >= 30:
                width = 1 + int.from_bytes(data[24:27], "little")
                height = 1 + int.from_bytes(data[27:30], "little")
                return width, height
            if data[12:16] == b"VP8L" and len(data) >= 25 and data[20] == 0x2F:
                width = 1 + data[21] + ((data[22] & 0x3F) << 8)
                height = 1 + ((data[22] & 0xC0) >> 6) + (data[23] << 2) + ((data[24] & 0x0F) << 10)
                return width, height
            marker = data.find(b"\x9d\x01\x2a", 20)
            if marker >= 0 and marker + 7 <= len(data):
                width = int.from_bytes(data[marker + 3:marker + 5], "little") & 0x3FFF
                height = int.from_bytes(data[marker + 5:marker + 7], "little") & 0x3FFF
                return width, height
        except Exception:
            return 0, 0
    if data.startswith(b"\xff\xd8"):
        i = 2
        try:
            while i + 9 < len(data):
                if data[i] != 0xFF:
                    i += 1
                    continue
                marker = data[i + 1]
                i += 2
                if marker in (0xD8, 0xD9):
                    continue
                seg_len = int.from_bytes(data[i:i + 2], "big")
                if marker in {0xC0, 0xC1, 0xC2, 0xC3, 0xC5, 0xC6, 0xC7, 0xC9, 0xCA, 0xCB, 0xCD, 0xCE, 0xCF} and i + 7 < len(data):
                    return int.from_bytes(data[i + 5:i + 7], "big"), int.from_bytes(data[i + 3:i + 5], "big")
                i += max(2, seg_len)
        except Exception:
            return 0, 0
    return 0, 0


MARKDOWN_IMAGE_THUMBNAIL_MAX_PX = 256
MARKDOWN_IMAGE_DOWNLOAD_MAX_BYTES = 50 * 1024 * 1024


class MarkdownImageCache:
    """Resolve local/online Markdown images without blocking the UI thread."""

    def __init__(self) -> None:
        self.cache_dir = Path(tempfile.gettempdir()) / "velox_markdown_images"
        self._records: dict[str, dict[str, Any]] = {}
        self._lock = threading.RLock()

    @staticmethod
    def _local_paths(
        source: str, local_candidates: Iterable[Path] | None = None,
    ) -> list[Path]:
        raw = str(source or "").strip()
        if not raw:
            return []
        if is_windows_absolute_path_text(raw):
            return [Path(raw.strip('"'))]
        parsed = urllib.parse.urlparse(raw)
        if parsed.scheme.lower() == "file":
            path_text = urllib.request.url2pathname(urllib.parse.unquote(parsed.path or ""))
            if parsed.netloc and parsed.netloc not in {"", "localhost"}:
                path_text = f"//{parsed.netloc}{path_text}"
            return [Path(path_text).expanduser().resolve()]
        if parsed.scheme.lower() in {"http", "https", "data", "blob"}:
            return []
        path = Path(urllib.parse.unquote(parsed.path or raw)).expanduser()
        if path.is_absolute():
            return [path.resolve()]
        candidates: list[Path] = []
        for candidate in local_candidates or ():
            try:
                resolved = Path(candidate).expanduser().resolve()
            except Exception:
                continue
            if resolved not in candidates:
                candidates.append(resolved)
        if candidates:
            return candidates
        return [(Path.cwd() / path).resolve()]


    def get(
        self, source: str, local_candidates: Iterable[Path] | None = None,
    ) -> dict[str, Any]:
        source = str(source or "").strip()
        if not source:
            return {"status": "broken", "source": source, "path": "", "error": "empty image link"}
        local_paths = self._local_paths(source, local_candidates)
        if local_paths:
            unsupported_path = ""
            for local in local_paths:
                try:
                    if local.is_file():
                        if image_size_from_file(local) != (0, 0):
                            return {"status": "ready", "source": source, "path": str(local), "error": ""}
                        unsupported_path = unsupported_path or str(local)
                except OSError:
                    continue
            first_path = unsupported_path or str(local_paths[0])
            error = (
                "local file exists but is not a supported image"
                if unsupported_path else "image file is not available"
            )
            return {"status": "broken", "source": source, "path": first_path, "error": error}
        parsed = urllib.parse.urlparse(source)
        if parsed.scheme.lower() not in {"http", "https"}:
            return {"status": "broken", "source": source, "path": "", "error": "unsupported image link"}
        with self._lock:
            record = self._records.get(source)
            if record is not None:
                return dict(record)
            digest = hashlib.sha256(source.encode("utf-8", errors="replace")).hexdigest()
            suffix = Path(parsed.path).suffix.lower()
            if suffix not in {".png", ".jpg", ".jpeg", ".gif", ".bmp", ".webp"}:
                suffix = ".img"
            path = self.cache_dir / f"{digest}{suffix}"
            if path.is_file() and image_size_from_file(path) != (0, 0):
                record = {"status": "ready", "source": source, "path": str(path), "error": ""}
                self._records[source] = record
                return dict(record)
            record = {"status": "loading", "source": source, "path": str(path), "error": ""}
            self._records[source] = record
            thread = threading.Thread(target=self._download, args=(source, path), name="velox-markdown-image", daemon=True)
            thread.start()
            return dict(record)

    def _download(self, source: str, path: Path) -> None:
        try:
            self.cache_dir.mkdir(parents=True, exist_ok=True)
            request = urllib.request.Request(source, headers={"User-Agent": WEB_USER_AGENT_DESKTOP_FIREFOX})
            with urllib.request.urlopen(request, timeout=30) as response:
                declared = int(response.headers.get("Content-Length") or 0)
                if declared > MARKDOWN_IMAGE_DOWNLOAD_MAX_BYTES:
                    raise ValueError("image exceeds the 50 MiB download limit")
                data = response.read(MARKDOWN_IMAGE_DOWNLOAD_MAX_BYTES + 1)
            if len(data) > MARKDOWN_IMAGE_DOWNLOAD_MAX_BYTES:
                raise ValueError("image exceeds the 50 MiB download limit")
            file_write_bytes(path, data)
            if image_size_from_file(path) == (0, 0):
                raise ValueError("downloaded content is not a supported image")
            record = {"status": "ready", "source": source, "path": str(path), "error": ""}
        except Exception as exc:
            try:
                path.unlink(missing_ok=True)
            except Exception:
                pass
            record = {"status": "broken", "source": source, "path": str(path), "error": f"{type(exc).__name__}: {exc}"}
        with self._lock:
            self._records[source] = record

    def clear_for_tests(self) -> None:
        with self._lock:
            self._records.clear()


MARKDOWN_IMAGE_CACHE = MarkdownImageCache()


MARKDOWN_IMAGE_LINK_RE = re.compile(r"!\[(?P<alt>(?:\\.|[^\]])*)\]\((?P<body>[^\n]*?)\)")
HTML_IMAGE_SOURCE_RE = re.compile(
    r"(?is)<img\b[^>]*?\bsrc\s*=\s*(?:\"(?P<double>[^\"]+)\"|'(?P<single>[^']+)'|(?P<bare>[^\s>]+))"
)


def markdown_image_sources(text: Any) -> list[str]:
    """Return unique Markdown/HTML image sources in visible assistant text.

    This parser is intentionally validation-oriented rather than a complete
    CommonMark implementation. It accepts ordinary ``![alt](path)`` links,
    angle-bracket destinations, optional Markdown titles, and HTML ``img`` tags.
    """
    raw = str(text or "")
    sources: list[str] = []

    def add(value: Any) -> None:
        source = str(value or "").strip()
        if source.startswith("<") and source.endswith(">"):
            source = source[1:-1].strip()
        # CommonMark titles follow a whitespace boundary. Preserve spaces in an
        # unquoted local path, but remove a conventional quoted title suffix.
        source = re.sub(r'\s+(?:"[^"]*"|\'[^\']*\'|\([^)]*\))\s*$', "", source).strip()
        source = source.replace(r"\)", ")").replace(r"\(", "(")
        if source and source not in sources:
            sources.append(source)

    for match in MARKDOWN_IMAGE_LINK_RE.finditer(raw):
        add(match.group("body"))
    for match in HTML_IMAGE_SOURCE_RE.finditer(raw):
        add(match.group("double") or match.group("single") or match.group("bare"))
    return sources


def _local_markdown_path_candidates(paths: "AppPaths", chat_id: str, source: str) -> list[Path]:
    """Resolve one Markdown link against the active Chat's local path roots.

    Bare relative paths are workspace-relative. Explicit ``workspace/``,
    ``attachments/``, ``attachments_processed/``, and ``temp/`` prefixes are
    relative to the Chat directory, so both ``image.png`` and
    ``workspace/image.png`` identify the same workspace file.
    """
    raw = str(source or "").strip().strip('"').strip("'")
    if not raw:
        return []
    if is_windows_absolute_path_text(raw):
        return [Path(raw)]
    parsed = urllib.parse.urlparse(raw)
    scheme = parsed.scheme.casefold()
    if scheme in {"http", "https", "data", "blob"}:
        return []
    if scheme == "file":
        path_text = urllib.request.url2pathname(urllib.parse.unquote(parsed.path or ""))
        if parsed.netloc and parsed.netloc not in {"", "localhost"}:
            path_text = f"//{parsed.netloc}{path_text}"
        return [Path(path_text).expanduser()]
    decoded = urllib.parse.unquote(parsed.path or raw)
    path = Path(decoded).expanduser()
    if path.is_absolute():
        return [path]

    chat_dir = paths.chat_dir(chat_id)
    workspace = paths.chat_workspace_dir(chat_id)
    attachments = paths.chat_attachments_dir(chat_id)
    processed = paths.chat_attachments_processed_dir(chat_id)
    temp_dir = paths.chat_temp_dir(chat_id)
    named_roots = {
        "workspace": workspace,
        "attachments": attachments,
        "attachments_processed": processed,
        "temp": temp_dir,
    }
    normalized_parts = [part for part in decoded.replace("\\", "/").split("/") if part not in {"", "."}]
    candidates: list[Path] = []

    def add(candidate: Path) -> None:
        key = os.path.normcase(os.path.normpath(str(candidate)))
        if all(os.path.normcase(os.path.normpath(str(existing))) != key for existing in candidates):
            candidates.append(candidate)

    if normalized_parts and normalized_parts[0].casefold() in named_roots:
        prefix = normalized_parts[0].casefold()
        tail = Path(*normalized_parts[1:]) if len(normalized_parts) > 1 else Path()
        add(chat_dir / Path(*normalized_parts))
        add(named_roots[prefix] / tail)
    else:
        add(workspace / path)
        add(attachments / path)
        add(processed / path)
        add(temp_dir / path)
        add(chat_dir / path)
        add(paths.root_dir / path)
    return candidates


def broken_local_markdown_image_links(
    text: Any, paths: "AppPaths", chat_id: str,
) -> list[dict[str, Any]]:
    """Return local image links that cannot produce a supported image preview.

    Remote URLs are deliberately excluded because validating them would add
    network I/O to completion handling. The existing asynchronous image cache
    continues to report remote download failures in the UI.
    """
    broken: list[dict[str, Any]] = []
    for source in markdown_image_sources(strip_reasoning_content(str(text or ""))):
        parsed = urllib.parse.urlparse(source)
        if parsed.scheme.casefold() in {"http", "https", "data", "blob"}:
            continue
        candidates = _local_markdown_path_candidates(paths, chat_id, source)
        resolved = ""
        error = "local image file does not exist"
        for candidate in candidates:
            try:
                target = candidate.resolve()
                if target.is_file():
                    if image_size_from_file(target) != (0, 0):
                        resolved = str(target)
                        break
                    error = "local file exists but is not a supported image"
            except (OSError, ValueError):
                continue
        if resolved:
            continue
        broken.append({
            "source": source,
            "error": error,
            "candidates": [str(candidate) for candidate in candidates[:6]],
        })
    return broken


def broken_image_link_correction_message(broken: list[dict[str, Any]]) -> str:
    rows = []
    for item in broken[:12]:
        source = str(item.get("source") or "")
        rows.append(f"- {source}: {item.get('error') or 'unavailable'}")
    return (
        "VELOX IMAGE LINK VALIDATION FAILED. The prior assistant response contains local image "
        "links that Velox cannot open:\n"
        + "\n".join(rows)
        + "\n\nReturn a corrected complete response now. Verify each intended image exists before "
        "linking it. Use an existing absolute local path with forward slashes, or omit the image "
        "when no valid file exists. Do not repeat any broken source. You may use filesystem or "
        "image tools before returning the corrected response."
    )

