ITEM_STATUSES: tuple[str, ...] = ("Info", "Action", "Agent WIP", "Review", "Done")
ITEM_PRIORITIES: tuple[str, ...] = ("P1", "P2", "P3")
CALENDAR_EVENT_STATUSES: tuple[str, ...] = ("confirmed", "tentative", "cancelled", "unknown")
CHAT_KINDS: tuple[str, ...] = ("standard", "week")
DEFAULT_ITEM_DURATION_MINUTES = 30
ITEM_DURATION_MINUTES_MIN = 1
ITEM_DURATION_MINUTES_MAX = 24 * 60
ISO_DATE_PATTERN = re.compile(r"^\d{4}-\d{2}-\d{2}$")
ISO_TIME_PATTERN = re.compile(r"^(?:[01]\d|2[0-3]):[0-5]\d$")


def normalize_iso_date(value: Any, *, field_name: str = "date") -> str:
    raw = str(value or "").strip()
    if not ISO_DATE_PATTERN.fullmatch(raw):
        raise ValueError(f"{field_name} must be an ISO date in YYYY-MM-DD form")
    try:
        date.fromisoformat(raw)
    except ValueError as exc:
        raise ValueError(f"{field_name} is not a valid calendar date") from exc
    return raw


def normalize_iso_time(value: Any, *, field_name: str = "start_time") -> str:
    raw = str(value or "").strip()
    if not ISO_TIME_PATTERN.fullmatch(raw):
        raise ValueError(f"{field_name} must be a 24-hour time in HH:MM form")
    try:
        datetime_time.fromisoformat(raw)
    except ValueError as exc:
        raise ValueError(f"{field_name} is not a valid time") from exc
    return raw


def _parse_iso_datetime(value: Any, *, field_name: str) -> datetime:
    raw = str(value or "").strip()
    if not raw:
        raise ValueError(f"{field_name} is required")
    try:
        parsed = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError as exc:
        raise ValueError(f"{field_name} must be an ISO date-time") from exc
    return parsed


def _comparable_datetime(value: Any) -> datetime:
    """Return one UTC datetime from the supported runtime timestamp forms.

    Persisted records remain strict ISO strings, but transient callers may carry a
    datetime or epoch number. Invalid values fail locally with a useful TypeError
    instead of producing an AttributeError from the frame-render path.
    """
    if isinstance(value, datetime):
        return value.replace(tzinfo=timezone.utc) if value.tzinfo is None else value.astimezone(timezone.utc)
    epoch = _iso_timestamp_epoch(value)
    if epoch is None:
        raise TypeError(f"Unsupported date-time value: {type(value).__name__}")
    return datetime.fromtimestamp(epoch, timezone.utc)


def _clean_optional_text(value: Any) -> str:
    return str(value or "").strip()


def _record_backup_path(path: Path) -> Path:
    """Return the adjacent backup path used by strict JSON record stores."""
    resolved = Path(path)
    return resolved.with_name(resolved.name + ".bak")


def _directory_signature(directory: Path) -> tuple[int, int, int]:
    """Return a cheap cross-platform directory-change signature."""
    try:
        stat = Path(directory).stat()
        return (
            int(getattr(stat, "st_mtime_ns", 0)),
            int(getattr(stat, "st_ctime_ns", 0)),
            int(getattr(stat, "st_ino", 0)),
        )
    except OSError:
        return (0, 0, 0)


def _json_record_paths(directory: Path, prefix: str) -> list[Path]:
    """List strict per-record JSON files while excluding adjacent backups."""
    resolved = Path(directory)
    if not resolved.is_dir():
        return []
    return sorted(
        candidate for candidate in resolved.glob(f"{prefix}_*.json")
        if candidate.is_file() and not candidate.name.endswith(".bak")
    )


def _normalize_person(value: Any) -> dict[str, str]:
    raw = value if isinstance(value, dict) else {}
    return {
        "name": _clean_optional_text(raw.get("name")),
        "email": _clean_optional_text(raw.get("email")),
    }


def _normalize_attendees(value: Any) -> list[dict[str, str]]:
    if not isinstance(value, list):
        return []
    attendees: list[dict[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for raw in value:
        if not isinstance(raw, dict):
            continue
        person = _normalize_person(raw)
        if not person["name"] and not person["email"]:
            continue
        key = (person["name"].casefold(), person["email"].casefold())
        if key in seen:
            continue
        seen.add(key)
        attendees.append(person)
    return attendees


def normalize_context_link(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError("Context Link must be an object")
    link_type = _clean_optional_text(value.get("type"))
    label = _clean_optional_text(value.get("label"))
    target = _clean_optional_text(value.get("url_or_path"))
    if not link_type:
        raise ValueError("Context Link type is required")
    if not label:
        raise ValueError("Context Link display label is required")
    if not target:
        raise ValueError("Context Link URL or local path is required")
    excerpt_value = value.get("source_excerpt")
    external_value = value.get("external_source_id")
    return {
        "schema": CONTEXT_LINK_SCHEMA,
        "type": link_type,
        "label": label,
        "url_or_path": target,
        "source_excerpt": None if excerpt_value in (None, "") else str(excerpt_value),
        "external_source_id": None if external_value in (None, "") else str(external_value),
    }


def validate_context_link(value: Any, *, location: str = "Context Link") -> dict[str, Any]:
    expected = {"schema", "type", "label", "url_or_path", "source_excerpt", "external_source_id"}
    if not isinstance(value, dict) or set(value) != expected or value.get("schema") != CONTEXT_LINK_SCHEMA:
        raise ValueError(f"Invalid Context Link record in {location}")
    for key in ("type", "label", "url_or_path"):
        if not isinstance(value.get(key), str) or not str(value.get(key) or "").strip():
            raise ValueError(f"Invalid Context Link {key} in {location}")
    for key in ("source_excerpt", "external_source_id"):
        if value.get(key) is not None and not isinstance(value.get(key), str):
            raise ValueError(f"Invalid Context Link {key} in {location}")
    return value


def default_week_chat_map() -> dict[str, Any]:
    return {
        "schema": WEEK_CHAT_MAP_SCHEMA,
        "data_version": DATA_FILE_VERSION,
        "week_start_to_chat_id": {},
        "updated_at": now_iso(),
    }


def validate_week_chat_map_record(value: Any, *, location: str = "week_chats.json") -> dict[str, Any]:
    expected = set(default_week_chat_map())
    if not isinstance(value, dict) or set(value) != expected:
        raise UnsupportedDataVersionError(f"Invalid Week Chat mapping shape in {location}")
    if value.get("schema") != WEEK_CHAT_MAP_SCHEMA or value.get("data_version") != DATA_FILE_VERSION:
        raise UnsupportedDataVersionError(f"Unsupported Week Chat mapping model in {location}")
    mapping = value.get("week_start_to_chat_id")
    if not isinstance(mapping, dict):
        raise ValueError(f"Invalid Week Chat mapping in {location}")
    for raw_date, raw_chat_id in mapping.items():
        normalized_date = normalize_iso_date(raw_date, field_name="Week Chat date")
        if (
            normalized_date != raw_date
            or calendar_week_start(normalized_date).isoformat() != normalized_date
            or not is_uuid_v4(raw_chat_id)
        ):
            raise ValueError(f"Invalid Week Chat entry in {location}")
    if not isinstance(value.get("updated_at"), str):
        raise ValueError(f"Invalid Week Chat updated_at in {location}")
    return value


