def normalize_google_calendar_row(value: Any, *, existing: dict[str, Any] | None = None) -> dict[str, Any]:
    """Normalize one CalendarList resource while preserving local enablement and token state."""
    if not isinstance(value, dict):
        raise ValueError("Google Calendar metadata must be an object")
    calendar_id = str(value.get("id") or value.get("calendar_id") or "").strip()
    if not calendar_id:
        raise ValueError("Google Calendar metadata is missing its calendar ID")
    prior = copy.deepcopy(existing) if isinstance(existing, dict) else default_google_calendar_row()
    access_role = str(value.get("accessRole") or value.get("access_role") or prior.get("access_role") or "").strip()
    deleted = bool(value.get("deleted", prior.get("deleted", False)))
    # Newly discovered Calendars are intentionally opt-in. Connecting a Google
    # account must never flood the day view before the user chooses the exact
    # calendars they want Velox to synchronize and display. Existing rows retain
    # their local enablement.
    enabled_default = False
    row = {
        "calendar_id": calendar_id,
        "display_name": str(
            value.get("summaryOverride")
            or value.get("summary")
            or value.get("display_name")
            or prior.get("display_name")
            or calendar_id
        ).strip(),
        "description": str(value.get("description") or prior.get("description") or ""),
        "primary": bool(value.get("primary", prior.get("primary", False))),
        "color_id": str(value.get("colorId") or value.get("color_id") or prior.get("color_id") or ""),
        "background_color": str(
            value.get("backgroundColor")
            or value.get("background_color")
            or prior.get("background_color")
            or ""
        ),
        "foreground_color": str(
            value.get("foregroundColor")
            or value.get("foreground_color")
            or prior.get("foreground_color")
            or ""
        ),
        "display_color": normalize_google_calendar_display_color(
            prior.get("display_color") if existing is not None else value.get("display_color"),
            calendar_id=calendar_id,
        ),
        "access_role": access_role,
        "time_zone": str(value.get("timeZone") or value.get("time_zone") or prior.get("time_zone") or ""),
        "enabled": (
            False
            if deleted or access_role == "none"
            else (bool(prior.get("enabled", enabled_default)) if existing is not None else enabled_default)
        ),
        "deleted": deleted,
        "sync_token": (
            "" if deleted or access_role == "none" else str(prior.get("sync_token") or "")
        ),
        "sync_window_start": (
            "" if deleted or access_role == "none" else str(prior.get("sync_window_start") or "")
        ),
        "sync_window_end": (
            "" if deleted or access_role == "none" else str(prior.get("sync_window_end") or "")
        ),
        "last_attempted_at": str(prior.get("last_attempted_at") or ""),
        "last_successful_at": str(prior.get("last_successful_at") or ""),
        "last_full_sync_at": str(prior.get("last_full_sync_at") or ""),
        "last_error": str(prior.get("last_error") or ""),
    }
    validate_google_calendar_row(row)
    return row


def validate_google_calendar_row(value: Any, *, location: str = "Google Calendar metadata") -> dict[str, Any]:
    expected = set(default_google_calendar_row())
    if not isinstance(value, dict) or set(value) != expected:
        raise UnsupportedDataVersionError(f"Invalid Google Calendar metadata shape in {location}")
    for key in (
        "calendar_id", "display_name", "description", "color_id", "background_color",
        "foreground_color", "display_color", "access_role", "time_zone", "sync_token", "sync_window_start",
        "sync_window_end", "last_attempted_at",
        "last_successful_at", "last_full_sync_at", "last_error",
    ):
        if not isinstance(value.get(key), str):
            raise ValueError(f"Invalid Google Calendar {key} in {location}")
    calendar_id = str(value.get("calendar_id") or "").strip()
    if not calendar_id:
        raise ValueError(f"Google Calendar ID is required in {location}")
    if value.get("display_color") not in GOOGLE_CALENDAR_DISPLAY_COLOR_KEYS:
        raise ValueError(f"Invalid Google Calendar display_color in {location}")
    for key in ("primary", "enabled", "deleted"):
        if not isinstance(value.get(key), bool):
            raise ValueError(f"Invalid Google Calendar {key} flag in {location}")
    return value


def validate_google_calendar_sync_state(
    value: Any,
    *,
    location: str = "google_sync.json",
) -> dict[str, Any]:
    expected = set(default_google_calendar_sync_state())
    if not isinstance(value, dict) or set(value) != expected:
        raise UnsupportedDataVersionError(f"Invalid Google Calendar sync-state shape in {location}")
    if value.get("schema") != GOOGLE_CALENDAR_SYNC_SCHEMA or value.get("data_version") != DATA_FILE_VERSION:
        raise UnsupportedDataVersionError(f"Unsupported Google Calendar sync-state model in {location}")
    account = value.get("connected_account")
    if not isinstance(account, dict) or set(account) != {"account_id", "email", "display_name"}:
        raise ValueError(f"Invalid connected Google Calendar account in {location}")
    if not all(isinstance(account.get(key), str) for key in account):
        raise ValueError(f"Invalid connected Google Calendar account fields in {location}")
    calendars = value.get("calendars")
    if not isinstance(calendars, list):
        raise ValueError(f"Invalid Google Calendar list in {location}")
    seen: set[str] = set()
    for index, row in enumerate(calendars):
        validate_google_calendar_row(row, location=f"{location}.calendars[{index}]")
        calendar_id = str(row["calendar_id"])
        if calendar_id in seen:
            raise ValueError(f"Duplicate Google Calendar ID in {location}: {calendar_id}")
        seen.add(calendar_id)
    for key in (
        "calendar_list_sync_token", "last_attempted_at", "last_successful_at", "last_error", "updated_at",
    ):
        if not isinstance(value.get(key), str):
            raise ValueError(f"Invalid Google Calendar sync-state {key} in {location}")
    return value


def system_local_timezone() -> Any:
    """Return the host's current local timezone object without requiring configuration."""
    return datetime.now().astimezone().tzinfo or timezone.utc


def resolve_vault_timezone(value: Any) -> Any:
    """Resolve the strict Vault timezone setting to a timezone-aware object."""
    raw = str(value or VAULT_LOCAL_TIMEZONE_DEFAULT).strip()
    if not raw or raw.casefold() == "system":
        return system_local_timezone()
    if raw.upper() in {"UTC", "Z"}:
        return timezone.utc
    try:
        return ZoneInfo(raw)
    except (ZoneInfoNotFoundError, ValueError) as exc:
        raise ValueError(
            "Vault local_timezone must be 'system', 'UTC', or a valid IANA timezone name"
        ) from exc


def configured_vault_timezone(storage: "Storage") -> Any:
    config = storage.load_config()
    vault = config.get("vault") if isinstance(config.get("vault"), dict) else {}
    return resolve_vault_timezone(vault.get("local_timezone"))


def _google_datetime_to_local_iso(value: Any, source_time_zone: str = "") -> str:
    raw = str(value or "").strip()
    if not raw:
        raise ValueError("Google Calendar timed Event is missing a dateTime")
    parsed = _parse_iso_datetime(raw, field_name="Google Calendar Event dateTime")
    if parsed.tzinfo is None:
        zone_name = str(source_time_zone or "").strip()
        if zone_name:
            try:
                parsed = parsed.replace(tzinfo=ZoneInfo(zone_name))
            except (ZoneInfoNotFoundError, ValueError):
                parsed = parsed.replace(tzinfo=timezone.utc)
        else:
            parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(system_local_timezone()).isoformat(timespec="seconds")


def google_calendar_meeting_url(event: dict[str, Any]) -> str:
    conference = event.get("conferenceData") if isinstance(event.get("conferenceData"), dict) else {}
    entries = conference.get("entryPoints") if isinstance(conference, dict) else []
    if isinstance(entries, list):
        for preferred_type in ("video", "more", "phone"):
            for entry in entries:
                if not isinstance(entry, dict) or str(entry.get("entryPointType") or "") != preferred_type:
                    continue
                uri = str(entry.get("uri") or "").strip()
                if uri:
                    return uri
    return str(event.get("hangoutLink") or "").strip()


def google_calendar_event_payload(
    event: Any,
    calendar_row: dict[str, Any],
    account_id: str,
    *,
    synced_at: str | None = None,
) -> dict[str, Any]:
    """Normalize one Google Event resource for CalendarStore.upsert_event().

    Google sends sparse cancellation tombstones during incremental sync. For
    those rows, only fields actually present are included so an existing local
    Event keeps its useful title, timing, participants, and links while its
    source status changes to cancelled.
    """
    if not isinstance(event, dict):
        raise ValueError("Google Calendar Event payload must be an object")
    external_event_id = str(event.get("id") or "").strip()
    if not external_event_id:
        raise ValueError("Google Calendar Event is missing its external ID")
    start_raw = event.get("start") if isinstance(event.get("start"), dict) else {}
    end_raw = event.get("end") if isinstance(event.get("end"), dict) else {}
    original_start = event.get("originalStartTime") if isinstance(event.get("originalStartTime"), dict) else {}
    recurrence_instance_id = str(
        original_start.get("dateTime") or original_start.get("date") or ""
    ).strip()
    raw_status = str(event.get("status") or "unknown").strip().lower()
    status = raw_status if raw_status in CALENDAR_EVENT_STATUSES else "unknown"
    cancelled = status == "cancelled"
    source_zone = str(
        start_raw.get("timeZone")
        or end_raw.get("timeZone")
        or calendar_row.get("time_zone")
        or ""
    ).strip()
    has_all_day_timing = bool(start_raw.get("date"))
    has_timed_timing = bool(start_raw.get("dateTime") and end_raw.get("dateTime"))
    has_timing = has_all_day_timing or has_timed_timing

    payload: dict[str, Any] = {
        "source_type": GOOGLE_CALENDAR_SOURCE_TYPE,
        "external_account_id": str(account_id or "").strip() or "google-calendar",
        "external_calendar_id": str(calendar_row.get("calendar_id") or "").strip(),
        "external_event_id": external_event_id,
        "calendar_name": str(
            calendar_row.get("display_name")
            or calendar_row.get("calendar_id")
            or "Google Calendar"
        ),
        "status": status,
        "last_synced_at": str(synced_at or now_iso()),
        "recurrence_instance_id": recurrence_instance_id,
        "raw_payload": copy.deepcopy(event),
    }

    if not cancelled or "summary" in event or has_timing:
        payload["title"] = str(event.get("summary") or "Busy")
    if not cancelled or "description" in event:
        payload["description"] = str(event.get("description") or "")
    if not cancelled or "location" in event:
        payload["location"] = str(event.get("location") or "")
    if isinstance(event.get("organizer"), dict):
        organizer = event["organizer"]
        payload["organizer"] = {
            "name": str(organizer.get("displayName") or ""),
            "email": str(organizer.get("email") or ""),
        }
    elif not cancelled:
        payload["organizer"] = {"name": "", "email": ""}
    if isinstance(event.get("attendees"), list):
        payload["attendees"] = [
            {
                "name": str(person.get("displayName") or ""),
                "email": str(person.get("email") or ""),
            }
            for person in event["attendees"]
            if isinstance(person, dict) and (person.get("displayName") or person.get("email"))
        ]
    elif not cancelled:
        payload["attendees"] = []
    if not cancelled or "conferenceData" in event or "hangoutLink" in event:
        payload["meeting_url"] = google_calendar_meeting_url(event)
    if not cancelled or "htmlLink" in event:
        payload["original_url"] = str(event.get("htmlLink") or "")
    if not cancelled or "created" in event:
        payload["external_created_at"] = str(event.get("created") or "")
    if not cancelled or "updated" in event:
        payload["external_updated_at"] = str(event.get("updated") or "")
    if not cancelled or "recurringEventId" in event:
        payload["recurring_event_id"] = str(event.get("recurringEventId") or "")

    if has_all_day_timing:
        start_date = str(start_raw.get("date") or "").strip()
        end_date = str(end_raw.get("date") or "").strip()
        if not end_date:
            end_date = (date.fromisoformat(start_date) + timedelta(days=1)).isoformat()
        payload["all_day"] = True
        payload["start"] = start_date
        payload["end"] = end_date
        payload["time_zone"] = source_zone
    elif has_timed_timing:
        payload["all_day"] = False
        payload["start"] = _google_datetime_to_local_iso(start_raw.get("dateTime"), source_zone)
        payload["end"] = _google_datetime_to_local_iso(end_raw.get("dateTime"), source_zone)
        payload["time_zone"] = source_zone
    elif not cancelled:
        raise ValueError("Google Calendar timed Event is missing start or end dateTime")
    elif source_zone:
        payload["time_zone"] = source_zone
    return payload


def calendar_event_external_identity(value: dict[str, Any]) -> tuple[str, str, str, str, str]:
    return (
        str(value.get("source_type") or "").strip(),
        str(value.get("external_account_id") or "").strip(),
        str(value.get("external_calendar_id") or "").strip(),
        str(value.get("external_event_id") or "").strip(),
        str(value.get("recurrence_instance_id") or "").strip(),
    )


def validate_calendar_event_record(value: Any, *, location: str = "Calendar Event") -> dict[str, Any]:
    expected = {
        "schema", "data_version", "event_id", "source_type", "external_account_id",
        "external_calendar_id", "external_event_id", "calendar_name", "title", "description",
        "start", "end", "all_day", "time_zone", "location", "organizer", "attendees",
        "meeting_url", "original_url", "status", "external_created_at", "external_updated_at",
        "last_synced_at", "recurring_event_id", "recurrence_instance_id", "raw_payload",
    }
    if not isinstance(value, dict) or set(value) != expected:
        raise UnsupportedDataVersionError(f"Invalid Calendar Event shape in {location}")
    if value.get("schema") != CALENDAR_EVENT_SCHEMA or value.get("data_version") != DATA_FILE_VERSION:
        raise UnsupportedDataVersionError(f"Unsupported Calendar Event model in {location}")
    if not is_uuid_v4(value.get("event_id")):
        raise ValueError(f"Invalid Calendar Event ID in {location}")
    for key in ("source_type", "external_account_id", "external_calendar_id", "external_event_id"):
        if not isinstance(value.get(key), str) or not str(value.get(key) or "").strip():
            raise ValueError(f"Calendar Event {key} is required in {location}")
    for key in (
        "calendar_name", "title", "description", "start", "end", "time_zone", "location",
        "meeting_url", "original_url", "external_created_at", "external_updated_at",
        "last_synced_at", "recurring_event_id", "recurrence_instance_id",
    ):
        if not isinstance(value.get(key), str):
            raise ValueError(f"Invalid Calendar Event {key} in {location}")
    if not isinstance(value.get("all_day"), bool):
        raise ValueError(f"Invalid Calendar Event all_day flag in {location}")
    if value.get("status") not in CALENDAR_EVENT_STATUSES:
        raise ValueError(f"Invalid Calendar Event status in {location}")
    organizer = value.get("organizer")
    if not isinstance(organizer, dict) or set(organizer) != {"name", "email"}:
        raise ValueError(f"Invalid Calendar Event organizer in {location}")
    if not all(isinstance(organizer.get(key), str) for key in ("name", "email")):
        raise ValueError(f"Invalid Calendar Event organizer fields in {location}")
    attendees = value.get("attendees")
    if not isinstance(attendees, list):
        raise ValueError(f"Invalid Calendar Event attendees in {location}")
    for index, attendee in enumerate(attendees):
        if not isinstance(attendee, dict) or set(attendee) != {"name", "email"}:
            raise ValueError(f"Invalid Calendar Event attendee {index} in {location}")
        if not all(isinstance(attendee.get(key), str) for key in ("name", "email")):
            raise ValueError(f"Invalid Calendar Event attendee {index} fields in {location}")
    raw_payload = value.get("raw_payload")
    if raw_payload is not None and not isinstance(raw_payload, dict):
        raise ValueError(f"Invalid Calendar Event raw payload in {location}")
    if value["all_day"]:
        start_date = date.fromisoformat(normalize_iso_date(value["start"], field_name="Event start"))
        end_date = date.fromisoformat(normalize_iso_date(value["end"], field_name="Event end"))
        if end_date <= start_date:
            raise ValueError(f"Calendar Event end must follow start in {location}")
    else:
        start_dt = _comparable_datetime(_parse_iso_datetime(value["start"], field_name="Event start"))
        end_dt = _comparable_datetime(_parse_iso_datetime(value["end"], field_name="Event end"))
        if end_dt <= start_dt:
            raise ValueError(f"Calendar Event end must follow start in {location}")
    return value


def normalize_calendar_event_payload(value: Any, *, existing: dict[str, Any] | None = None) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError("Calendar Event payload must be an object")
    base = copy.deepcopy(existing) if isinstance(existing, dict) else {
        "schema": CALENDAR_EVENT_SCHEMA,
        "data_version": DATA_FILE_VERSION,
        "event_id": uuid_v4(),
        "source_type": "",
        "external_account_id": "",
        "external_calendar_id": "",
        "external_event_id": "",
        "calendar_name": "",
        "title": "",
        "description": "",
        "start": "",
        "end": "",
        "all_day": False,
        "time_zone": "",
        "location": "",
        "organizer": {"name": "", "email": ""},
        "attendees": [],
        "meeting_url": "",
        "original_url": "",
        "status": "unknown",
        "external_created_at": "",
        "external_updated_at": "",
        "last_synced_at": now_iso(),
        "recurring_event_id": "",
        "recurrence_instance_id": "",
        "raw_payload": None,
    }
    text_fields = (
        "source_type", "external_account_id", "external_calendar_id", "external_event_id",
        "calendar_name", "title", "description", "start", "end", "time_zone", "location",
        "meeting_url", "original_url", "external_created_at", "external_updated_at",
        "recurring_event_id", "recurrence_instance_id",
    )
    for key in text_fields:
        if key in value:
            base[key] = _clean_optional_text(value.get(key))
    if "event_id" in value and is_uuid_v4(value.get("event_id")) and existing is None:
        base["event_id"] = str(value["event_id"])
    if "all_day" in value:
        if not isinstance(value.get("all_day"), bool):
            raise ValueError("Calendar Event all_day must be a boolean")
        base["all_day"] = value["all_day"]
    if "organizer" in value:
        base["organizer"] = _normalize_person(value.get("organizer"))
    if "attendees" in value:
        base["attendees"] = _normalize_attendees(value.get("attendees"))
    if "status" in value:
        status = _clean_optional_text(value.get("status")).lower() or "unknown"
        if status not in CALENDAR_EVENT_STATUSES:
            raise ValueError("Calendar Event status must be confirmed, tentative, cancelled, or unknown")
        base["status"] = status
    if "raw_payload" in value:
        base["raw_payload"] = copy.deepcopy(value.get("raw_payload")) if isinstance(value.get("raw_payload"), dict) else None
    base["schema"] = CALENDAR_EVENT_SCHEMA
    base["data_version"] = DATA_FILE_VERSION
    base["last_synced_at"] = _clean_optional_text(value.get("last_synced_at")) or now_iso()
    validate_calendar_event_record(base)
    return base


def validate_item_record(value: Any, *, location: str = "Item") -> dict[str, Any]:
    expected = {
        "schema", "data_version", "item_id", "title", "description", "status", "priority",
        "scheduled_date", "scheduled_start_time", "duration_minutes", "linked_event_id",
        "context_links", "attachments", "linked_agent_ids", "created_at", "updated_at",
        "completed_at",
    }
    if not isinstance(value, dict) or set(value) != expected:
        raise UnsupportedDataVersionError(f"Invalid Item shape in {location}")
    if value.get("schema") != ITEM_SCHEMA or value.get("data_version") != DATA_FILE_VERSION:
        raise UnsupportedDataVersionError(f"Unsupported Item model in {location}")
    if not is_uuid_v4(value.get("item_id")):
        raise ValueError(f"Invalid Item ID in {location}")
    if not isinstance(value.get("title"), str) or not str(value.get("title") or "").strip():
        raise ValueError(f"Item title is required in {location}")
    if not isinstance(value.get("description"), str):
        raise ValueError(f"Invalid Item description in {location}")
    if value.get("status") not in ITEM_STATUSES:
        raise ValueError(f"Invalid Item status in {location}")
    if value.get("priority") not in ITEM_PRIORITIES:
        raise ValueError(f"Invalid Item priority in {location}")
    scheduled_date = value.get("scheduled_date")
    scheduled_time = value.get("scheduled_start_time")
    duration = value.get("duration_minutes")
    if (scheduled_date is None) != (scheduled_time is None):
        raise ValueError(f"Item must have both a scheduled date and start time, or neither, in {location}")
    if scheduled_date is None:
        if duration is not None:
            raise ValueError(f"Backlog Item cannot retain a duration in {location}")
    else:
        normalize_iso_date(scheduled_date, field_name="Item scheduled date")
        normalize_iso_time(scheduled_time, field_name="Item scheduled start time")
        if isinstance(duration, bool) or not isinstance(duration, int):
            raise ValueError(f"Scheduled Item duration must be an integer in {location}")
        if not ITEM_DURATION_MINUTES_MIN <= duration <= ITEM_DURATION_MINUTES_MAX:
            raise ValueError(f"Scheduled Item duration is out of range in {location}")
    linked_event_id = value.get("linked_event_id")
    if linked_event_id is not None and not is_uuid_v4(linked_event_id):
        raise ValueError(f"Invalid linked Event ID in {location}")
    links = value.get("context_links")
    if not isinstance(links, list):
        raise ValueError(f"Invalid Item Context Links in {location}")
    for index, link in enumerate(links):
        validate_context_link(link, location=f"{location}.context_links[{index}]")
    attachments = value.get("attachments")
    if not isinstance(attachments, list) or any(not isinstance(path, str) or not path.strip() for path in attachments):
        raise ValueError(f"Invalid Item attachments in {location}")
    if len(set(attachments)) != len(attachments):
        raise ValueError(f"Duplicate Item attachments in {location}")
    linked_agents = value.get("linked_agent_ids")
    if not isinstance(linked_agents, list) or any(not is_uuid_v4(agent_id) for agent_id in linked_agents):
        raise ValueError(f"Invalid Item linked agents in {location}")
    if len(set(linked_agents)) != len(linked_agents):
        raise ValueError(f"Duplicate Item linked agents in {location}")
    for key in ("created_at", "updated_at"):
        if not isinstance(value.get(key), str) or not value.get(key):
            raise ValueError(f"Invalid Item {key} in {location}")
    completed_at = value.get("completed_at")
    if completed_at is not None and not isinstance(completed_at, str):
        raise ValueError(f"Invalid Item completed_at in {location}")
    if value.get("status") == "Done" and not completed_at:
        raise ValueError(f"Done Item must have a completed timestamp in {location}")
    if value.get("status") != "Done" and completed_at is not None:
        raise ValueError(f"Only a Done Item may have a completed timestamp in {location}")
    return value


def _normalize_context_links(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        return []
    links: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for raw in value:
        try:
            link = normalize_context_link(raw)
        except ValueError:
            continue
        key = (str(link["type"]).casefold(), str(link["url_or_path"]))
        if key in seen:
            continue
        seen.add(key)
        links.append(link)
    return links


def _normalize_unique_strings(value: Any, *, require_uuid: bool = False) -> list[str]:
    if not isinstance(value, list):
        return []
    rows: list[str] = []
    seen: set[str] = set()
    for raw in value:
        if not isinstance(raw, str):
            continue
        text = raw.strip()
        if not text or (require_uuid and not is_uuid_v4(text)) or text in seen:
            continue
        seen.add(text)
        rows.append(text)
    return rows


def new_item_record(
    title: str,
    description: str = "",
    status: str = "Action",
    priority: str = "P2",
    *,
    scheduled_date: str | None = None,
    scheduled_start_time: str | None = None,
    duration_minutes: int | None = None,
    linked_event_id: str | None = None,
    context_links: Any = None,
    attachments: Any = None,
    linked_agent_ids: Any = None,
) -> dict[str, Any]:
    clean_title = str(title or "").strip()
    if not clean_title:
        raise ValueError("Item title is required")
    clean_status = str(status or "").strip()
    clean_priority = str(priority or "").strip().upper()
    if clean_status not in ITEM_STATUSES:
        raise ValueError("Item status must be Info, Action, Agent WIP, Review, or Done")
    if clean_priority not in ITEM_PRIORITIES:
        raise ValueError("Item priority must be P1, P2, or P3")
    if (scheduled_date is None) != (scheduled_start_time is None):
        raise ValueError("An Item must have both a scheduled date and start time, or neither")
    resolved_date: str | None = None
    resolved_time: str | None = None
    resolved_duration: int | None = None
    if scheduled_date is not None:
        resolved_date = normalize_iso_date(scheduled_date, field_name="Item scheduled date")
        resolved_time = normalize_iso_time(scheduled_start_time, field_name="Item scheduled start time")
        if duration_minutes is not None and (isinstance(duration_minutes, bool) or not isinstance(duration_minutes, int)):
            raise ValueError("Item duration must be an integer number of minutes")
        resolved_duration = DEFAULT_ITEM_DURATION_MINUTES if duration_minutes is None else duration_minutes
    elif duration_minutes is not None:
        raise ValueError("A Backlog Item cannot have a duration")
    now = now_iso()
    record = {
        "schema": ITEM_SCHEMA,
        "data_version": DATA_FILE_VERSION,
        "item_id": uuid_v4(),
        "title": clean_title,
        "description": str(description or ""),
        "status": clean_status,
        "priority": clean_priority,
        "scheduled_date": resolved_date,
        "scheduled_start_time": resolved_time,
        "duration_minutes": resolved_duration,
        "linked_event_id": None if linked_event_id in (None, "") else str(linked_event_id),
        "context_links": _normalize_context_links(context_links),
        "attachments": _normalize_unique_strings(attachments),
        "linked_agent_ids": _normalize_unique_strings(linked_agent_ids, require_uuid=True),
        "created_at": now,
        "updated_at": now,
        "completed_at": now if clean_status == "Done" else None,
    }
    validate_item_record(record)
    return record


