# Normalized account-data records
# =============================================================================


def normalize_vault_timestamp(
    value: Any,
    *,
    field_name: str = "timestamp",
    allow_date: bool = False,
) -> str:
    """Return a timezone-safe ISO timestamp, or an ISO date for all-day records."""
    raw = str(value or "").strip()
    if not raw:
        return ""
    if allow_date and ISO_DATE_PATTERN.fullmatch(raw):
        return normalize_iso_date(raw, field_name=field_name)
    # Slack timestamps are decimal Unix seconds.
    if re.fullmatch(r"\d+(?:\.\d+)?", raw):
        try:
            numeric = float(raw)
            # Gmail internalDate values are Unix milliseconds; Slack ts values
            # are Unix seconds. Their magnitudes make the formats unambiguous.
            if abs(numeric) >= 100_000_000_000:
                numeric /= 1000.0
            parsed = datetime.fromtimestamp(numeric, tz=timezone.utc)
        except (OverflowError, OSError, ValueError) as exc:
            raise ValueError(f"{field_name} is not a valid Unix timestamp") from exc
    else:
        parsed = _parse_iso_datetime(raw, field_name=field_name)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=system_local_timezone())
    return parsed.astimezone(timezone.utc).isoformat(timespec="microseconds").replace("+00:00", "Z")


def validate_vault_timestamp_value(
    value: Any,
    *,
    field_name: str,
    allow_empty: bool = True,
    allow_date: bool = False,
) -> str:
    if not isinstance(value, str):
        raise ValueError(f"Invalid {field_name}")
    if not value:
        if allow_empty:
            return value
        raise ValueError(f"{field_name} is required")
    normalize_vault_timestamp(value, field_name=field_name, allow_date=allow_date)
    return value


def normalize_vault_participant(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError("Vault participant must be an object")
    role = str(value.get("role") or "").strip().lower()
    if role not in VAULT_PARTICIPANT_ROLES:
        raise ValueError("Vault participant role is invalid")
    participant_type = str(value.get("participant_type") or "person").strip().lower()
    if participant_type not in VAULT_PARTICIPANT_TYPES:
        participant_type = "unknown"
    record = {
        "schema": VAULT_PARTICIPANT_SCHEMA,
        "participant_type": participant_type,
        "external_id": str(value.get("external_id") or "").strip(),
        "display_name": str(value.get("display_name") or value.get("name") or "").strip(),
        "email": str(value.get("email") or "").strip(),
        "role": role,
        "response_status": str(value.get("response_status") or "").strip(),
        "metadata": copy.deepcopy(value.get("metadata") if isinstance(value.get("metadata"), dict) else {}),
    }
    return validate_vault_participant(record)


def validate_vault_participant(value: Any, *, location: str = "Vault participant") -> dict[str, Any]:
    expected = {
        "schema", "participant_type", "external_id", "display_name", "email",
        "role", "response_status", "metadata",
    }
    if not isinstance(value, dict) or set(value) != expected or value.get("schema") != VAULT_PARTICIPANT_SCHEMA:
        raise UnsupportedDataVersionError(f"Invalid Vault participant shape in {location}")
    if value.get("participant_type") not in VAULT_PARTICIPANT_TYPES:
        raise ValueError(f"Invalid Vault participant type in {location}")
    if value.get("role") not in VAULT_PARTICIPANT_ROLES:
        raise ValueError(f"Invalid Vault participant role in {location}")
    for key in ("external_id", "display_name", "email", "response_status"):
        if not isinstance(value.get(key), str):
            raise ValueError(f"Invalid Vault participant {key} in {location}")
    if not isinstance(value.get("metadata"), dict):
        raise ValueError(f"Invalid Vault participant metadata in {location}")
    return value


def normalize_vault_attachment(value: Any, *, item_id: str) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError("Vault attachment must be an object")
    resolved_item_id = str(item_id or "").strip()
    if not is_uuid_v4(resolved_item_id):
        raise ValueError("Vault attachment item_id must be a Velox UUID")
    external_id = str(value.get("external_id") or value.get("id_external") or "").strip()
    filename = str(value.get("filename") or value.get("name") or "").strip()
    content_id = str(value.get("content_id") or "").strip()
    attachment_id = str(value.get("id") or "").strip()
    if not is_uuid_v4(attachment_id):
        identity = external_id or content_id or filename or str(value.get("source_url") or value.get("url") or "")
        attachment_id = stable_uuid_v4(
            "velox-vault-attachment", f"{resolved_item_id}|{identity}",
        )
    size = value.get("size_bytes", 0)
    if isinstance(size, bool):
        size = 0
    try:
        size = max(0, int(size or 0))
    except Exception:
        size = 0
    record = {
        "schema": VAULT_ATTACHMENT_SCHEMA,
        "id": attachment_id,
        "item_id": resolved_item_id,
        "external_id": external_id,
        "filename": filename,
        "mime_type": str(value.get("mime_type") or value.get("mimetype") or "").strip(),
        "size_bytes": size,
        "source_url": str(value.get("source_url") or value.get("url") or value.get("permalink") or "").strip(),
        "is_inline": bool(value.get("is_inline", False)),
        "content_id": content_id,
        "metadata": copy.deepcopy(value.get("metadata") if isinstance(value.get("metadata"), dict) else {}),
    }
    return validate_vault_attachment(record)


def validate_vault_attachment(value: Any, *, location: str = "Vault attachment") -> dict[str, Any]:
    expected = {
        "schema", "id", "item_id", "external_id", "filename", "mime_type",
        "size_bytes", "source_url", "is_inline", "content_id", "metadata",
    }
    if not isinstance(value, dict) or set(value) != expected or value.get("schema") != VAULT_ATTACHMENT_SCHEMA:
        raise UnsupportedDataVersionError(f"Invalid Vault attachment shape in {location}")
    if not is_uuid_v4(value.get("id")) or not is_uuid_v4(value.get("item_id")):
        raise ValueError(f"Invalid Vault attachment identity in {location}")
    for key in ("external_id", "filename", "mime_type", "source_url", "content_id"):
        if not isinstance(value.get(key), str):
            raise ValueError(f"Invalid Vault attachment {key} in {location}")
    if isinstance(value.get("size_bytes"), bool) or not isinstance(value.get("size_bytes"), int) or value["size_bytes"] < 0:
        raise ValueError(f"Invalid Vault attachment size in {location}")
    if not isinstance(value.get("is_inline"), bool) or not isinstance(value.get("metadata"), dict):
        raise ValueError(f"Invalid Vault attachment fields in {location}")
    return value


def normalize_vault_data_source(value: Any, *, existing: dict[str, Any] | None = None) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError("Vault data source must be an object")
    source_type = str(value.get("source_type") or (existing or {}).get("source_type") or "").strip().lower()
    if source_type not in VAULT_SOURCE_TYPES:
        raise ValueError("Vault source_type must be google_calendar, google_drive, gmail, or slack")
    now = now_iso()
    record = copy.deepcopy(existing) if isinstance(existing, dict) else {
        "schema": VAULT_DATA_SOURCE_SCHEMA,
        "data_version": DATA_FILE_VERSION,
        "id": uuid_v4(),
        "source_type": source_type,
        "display_name": "",
        "account_identifier": "",
        "enabled": True,
        "connection_state": "not_configured",
        "credential_reference": "",
        "created_at": now,
        "updated_at": now,
        "last_sync_started_at": "",
        "last_sync_completed_at": "",
        "last_successful_sync_at": "",
        "last_sync_error": "",
        "metadata": {},
    }
    if is_uuid_v4(value.get("id")) and existing is None:
        record["id"] = str(value["id"])
    record.update({
        "schema": VAULT_DATA_SOURCE_SCHEMA,
        "data_version": DATA_FILE_VERSION,
        "source_type": source_type,
        "display_name": str(value.get("display_name", record.get("display_name", "")) or "").strip(),
        "account_identifier": str(value.get("account_identifier", record.get("account_identifier", "")) or "").strip(),
        "enabled": bool(value.get("enabled", record.get("enabled", True))),
        "connection_state": str(value.get("connection_state", record.get("connection_state", "not_configured")) or "not_configured").strip().lower(),
        "credential_reference": str(value.get("credential_reference", record.get("credential_reference", "")) or "").strip(),
        "last_sync_started_at": normalize_vault_timestamp(value.get("last_sync_started_at", record.get("last_sync_started_at", "")), field_name="Vault source last_sync_started_at"),
        "last_sync_completed_at": normalize_vault_timestamp(value.get("last_sync_completed_at", record.get("last_sync_completed_at", "")), field_name="Vault source last_sync_completed_at"),
        "last_successful_sync_at": normalize_vault_timestamp(value.get("last_successful_sync_at", record.get("last_successful_sync_at", "")), field_name="Vault source last_successful_sync_at"),
        "last_sync_error": str(value.get("last_sync_error", record.get("last_sync_error", "")) or ""),
        "metadata": copy.deepcopy(value.get("metadata") if isinstance(value.get("metadata"), dict) else record.get("metadata", {})),
        "updated_at": normalize_vault_timestamp(value.get("updated_at") or now, field_name="Vault source updated_at"),
    })
    record["created_at"] = normalize_vault_timestamp(record.get("created_at") or value.get("created_at") or now, field_name="Vault source created_at")
    if record["connection_state"] not in VAULT_CONNECTION_STATES:
        raise ValueError("Vault connection_state is invalid")
    return validate_vault_data_source(record)


def validate_vault_data_source(value: Any, *, location: str = "Vault data source") -> dict[str, Any]:
    expected = {
        "schema", "data_version", "id", "source_type", "display_name", "account_identifier",
        "enabled", "connection_state", "credential_reference", "created_at", "updated_at",
        "last_sync_started_at", "last_sync_completed_at", "last_successful_sync_at",
        "last_sync_error", "metadata",
    }
    if not isinstance(value, dict) or set(value) != expected:
        raise UnsupportedDataVersionError(f"Invalid Vault data source shape in {location}")
    if value.get("schema") != VAULT_DATA_SOURCE_SCHEMA or value.get("data_version") != DATA_FILE_VERSION:
        raise UnsupportedDataVersionError(f"Unsupported Vault data source model in {location}")
    if not is_uuid_v4(value.get("id")) or value.get("source_type") not in VAULT_SOURCE_TYPES:
        raise ValueError(f"Invalid Vault data source identity/type in {location}")
    if value.get("connection_state") not in VAULT_CONNECTION_STATES:
        raise ValueError(f"Invalid Vault data source connection state in {location}")
    if not isinstance(value.get("enabled"), bool) or not isinstance(value.get("metadata"), dict):
        raise ValueError(f"Invalid Vault data source fields in {location}")
    for key in (
        "display_name", "account_identifier", "credential_reference", "created_at", "updated_at",
        "last_sync_started_at", "last_sync_completed_at", "last_successful_sync_at", "last_sync_error",
    ):
        if not isinstance(value.get(key), str):
            raise ValueError(f"Invalid Vault data source {key} in {location}")
    validate_vault_timestamp_value(value["created_at"], field_name=f"{location}.created_at", allow_empty=False)
    validate_vault_timestamp_value(value["updated_at"], field_name=f"{location}.updated_at", allow_empty=False)
    for key in ("last_sync_started_at", "last_sync_completed_at", "last_successful_sync_at"):
        validate_vault_timestamp_value(value[key], field_name=f"{location}.{key}")
    return value


def normalize_vault_container(value: Any, *, existing: dict[str, Any] | None = None) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError("Vault container must be an object")
    source_id = str(value.get("source_id") or (existing or {}).get("source_id") or "").strip()
    external_id = str(value.get("external_id") or (existing or {}).get("external_id") or "").strip()
    container_type = str(value.get("container_type") or (existing or {}).get("container_type") or "").strip().lower()
    if not is_uuid_v4(source_id) or not external_id or container_type not in VAULT_CONTAINER_TYPES:
        raise ValueError("Vault container source, external ID, and type are required")
    now = now_iso()
    record = copy.deepcopy(existing) if isinstance(existing, dict) else {
        "schema": VAULT_CONTAINER_SCHEMA,
        "data_version": DATA_FILE_VERSION,
        "id": uuid_v4(),
        "source_id": source_id,
        "external_id": external_id,
        "container_type": container_type,
        "name": "",
        "display_name": "",
        "parent_container_id": None,
        "is_archived": False,
        "is_hidden": False,
        "created_at": now,
        "updated_at": now,
        "metadata": {},
    }
    if is_uuid_v4(value.get("id")) and existing is None:
        record["id"] = str(value["id"])
    parent = value.get("parent_container_id", record.get("parent_container_id"))
    record.update({
        "schema": VAULT_CONTAINER_SCHEMA,
        "data_version": DATA_FILE_VERSION,
        "source_id": source_id,
        "external_id": external_id,
        "container_type": container_type,
        "name": str(value.get("name", record.get("name", "")) or "").strip(),
        "display_name": str(value.get("display_name", record.get("display_name", "")) or "").strip(),
        "parent_container_id": None if parent in (None, "") else str(parent),
        "is_archived": bool(value.get("is_archived", record.get("is_archived", False))),
        "is_hidden": bool(value.get("is_hidden", record.get("is_hidden", False))),
        "updated_at": normalize_vault_timestamp(value.get("updated_at") or now, field_name="Vault Container updated_at"),
        "metadata": copy.deepcopy(value.get("metadata") if isinstance(value.get("metadata"), dict) else record.get("metadata", {})),
    })
    record["created_at"] = normalize_vault_timestamp(record.get("created_at") or value.get("created_at") or now, field_name="Vault Container created_at")
    return validate_vault_container(record)


def validate_vault_container(value: Any, *, location: str = "Vault container") -> dict[str, Any]:
    expected = {
        "schema", "data_version", "id", "source_id", "external_id", "container_type",
        "name", "display_name", "parent_container_id", "is_archived", "is_hidden",
        "created_at", "updated_at", "metadata",
    }
    if not isinstance(value, dict) or set(value) != expected:
        raise UnsupportedDataVersionError(f"Invalid Vault container shape in {location}")
    if value.get("schema") != VAULT_CONTAINER_SCHEMA or value.get("data_version") != DATA_FILE_VERSION:
        raise UnsupportedDataVersionError(f"Unsupported Vault container model in {location}")
    if not is_uuid_v4(value.get("id")) or not is_uuid_v4(value.get("source_id")):
        raise ValueError(f"Invalid Vault container identity in {location}")
    if value.get("container_type") not in VAULT_CONTAINER_TYPES or not str(value.get("external_id") or "").strip():
        raise ValueError(f"Invalid Vault container type/external ID in {location}")
    parent = value.get("parent_container_id")
    if parent is not None and not is_uuid_v4(parent):
        raise ValueError(f"Invalid parent Vault container in {location}")
    for key in ("name", "display_name", "created_at", "updated_at"):
        if not isinstance(value.get(key), str):
            raise ValueError(f"Invalid Vault container {key} in {location}")
    validate_vault_timestamp_value(value["created_at"], field_name=f"{location}.created_at", allow_empty=False)
    validate_vault_timestamp_value(value["updated_at"], field_name=f"{location}.updated_at", allow_empty=False)
    if not isinstance(value.get("is_archived"), bool) or not isinstance(value.get("is_hidden"), bool) or not isinstance(value.get("metadata"), dict):
        raise ValueError(f"Invalid Vault container fields in {location}")
    return value


def vault_item_content_hash(value: dict[str, Any]) -> str:
    """Hash normalized source content while excluding Velox-local record IDs."""
    stable = {
        key: copy.deepcopy(value.get(key))
        for key in (
            "source_id", "container_id", "external_id", "item_type", "thread_id", "parent_item_id",
            "title", "summary", "body_text", "body_html", "primary_timestamp", "start_timestamp",
            "end_timestamp", "created_timestamp", "updated_timestamp", "author_id",
            "author_display_name", "source_url", "is_unread", "is_deleted", "is_all_day",
            "metadata", "raw_payload_reference",
        )
    }
    stable["participants"] = [
        {key: copy.deepcopy(row.get(key)) for key in (
            "participant_type", "external_id", "display_name", "email", "role",
            "response_status", "metadata",
        )}
        for row in value.get("participants", []) if isinstance(row, dict)
    ]
    stable["attachments"] = [
        {key: copy.deepcopy(row.get(key)) for key in (
            "external_id", "filename", "mime_type", "size_bytes", "source_url",
            "is_inline", "content_id", "metadata",
        )}
        for row in value.get("attachments", []) if isinstance(row, dict)
    ]
    return sha256_bytes(
        json.dumps(stable, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    )


def normalize_vault_item(value: Any, *, existing: dict[str, Any] | None = None) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError("Vault item must be an object")
    source_id = str(value.get("source_id") or (existing or {}).get("source_id") or "").strip()
    container_id = str(value.get("container_id") or (existing or {}).get("container_id") or "").strip()
    external_id = str(value.get("external_id") or (existing or {}).get("external_id") or "").strip()
    item_type = str(value.get("item_type") or (existing or {}).get("item_type") or "").strip().lower()
    if not is_uuid_v4(source_id) or not is_uuid_v4(container_id) or not external_id or item_type not in VAULT_ITEM_TYPES:
        raise ValueError("Vault item source, container, external ID, and type are required")
    now = now_iso()
    record = copy.deepcopy(existing) if isinstance(existing, dict) else {
        "schema": VAULT_ITEM_SCHEMA,
        "data_version": DATA_FILE_VERSION,
        "id": uuid_v4(),
        "source_id": source_id,
        "container_id": container_id,
        "external_id": external_id,
        "item_type": item_type,
        "thread_id": "",
        "parent_item_id": None,
        "title": "",
        "summary": "",
        "body_text": "",
        "body_html": "",
        "primary_timestamp": "",
        "start_timestamp": "",
        "end_timestamp": "",
        "created_timestamp": "",
        "updated_timestamp": "",
        "author_id": "",
        "author_display_name": "",
        "source_url": "",
        "is_unread": False,
        "is_deleted": False,
        "is_all_day": False,
        "content_hash": "",
        "first_synced_at": now,
        "last_synced_at": now,
        "last_seen_sync_generation": 0,
        "participants": [],
        "attachments": [],
        "metadata": {},
        "raw_payload_reference": "",
    }
    if is_uuid_v4(value.get("id")) and existing is None:
        record["id"] = str(value["id"])
    parent = value.get("parent_item_id", record.get("parent_item_id"))
    all_day = bool(value.get("is_all_day", record.get("is_all_day", False)))
    primary = normalize_vault_timestamp(
        value.get("primary_timestamp", record.get("primary_timestamp", "")),
        field_name="Vault item primary_timestamp",
        allow_date=all_day,
    )
    if not primary:
        raise ValueError("Vault item primary_timestamp is required")
    record.update({
        "schema": VAULT_ITEM_SCHEMA,
        "data_version": DATA_FILE_VERSION,
        "source_id": source_id,
        "container_id": container_id,
        "external_id": external_id,
        "item_type": item_type,
        "thread_id": str(value.get("thread_id", record.get("thread_id", "")) or "").strip(),
        "parent_item_id": None if parent in (None, "") else str(parent),
        "title": str(value.get("title", record.get("title", "")) or ""),
        "summary": str(value.get("summary", record.get("summary", "")) or ""),
        "body_text": str(value.get("body_text", record.get("body_text", "")) or ""),
        "body_html": str(value.get("body_html", record.get("body_html", "")) or ""),
        "primary_timestamp": primary,
        "start_timestamp": normalize_vault_timestamp(value.get("start_timestamp", record.get("start_timestamp", "")), field_name="Vault item start_timestamp", allow_date=all_day),
        "end_timestamp": normalize_vault_timestamp(value.get("end_timestamp", record.get("end_timestamp", "")), field_name="Vault item end_timestamp", allow_date=all_day),
        "created_timestamp": normalize_vault_timestamp(value.get("created_timestamp", record.get("created_timestamp", "")), field_name="Vault item created_timestamp"),
        "updated_timestamp": normalize_vault_timestamp(value.get("updated_timestamp", record.get("updated_timestamp", "")), field_name="Vault item updated_timestamp"),
        "author_id": str(value.get("author_id", record.get("author_id", "")) or "").strip(),
        "author_display_name": str(value.get("author_display_name", record.get("author_display_name", "")) or "").strip(),
        "source_url": str(value.get("source_url", record.get("source_url", "")) or "").strip(),
        "is_unread": bool(value.get("is_unread", record.get("is_unread", False))),
        "is_deleted": bool(value.get("is_deleted", record.get("is_deleted", False))),
        "is_all_day": all_day,
        "last_synced_at": normalize_vault_timestamp(value.get("last_synced_at") or now, field_name="Vault item last_synced_at"),
        "last_seen_sync_generation": _vault_nonnegative_int(
            value.get("last_seen_sync_generation", record.get("last_seen_sync_generation", 0)),
        ),
        "metadata": copy.deepcopy(value.get("metadata") if isinstance(value.get("metadata"), dict) else record.get("metadata", {})),
        "raw_payload_reference": str(value.get("raw_payload_reference", record.get("raw_payload_reference", "")) or "").strip(),
    })
    record["first_synced_at"] = normalize_vault_timestamp(record.get("first_synced_at") or value.get("first_synced_at") or now, field_name="Vault item first_synced_at")
    participant_rows = value.get("participants", record.get("participants", []))
    participants: list[dict[str, Any]] = []
    if isinstance(participant_rows, list):
        for raw in participant_rows:
            try:
                participants.append(normalize_vault_participant(raw))
            except ValueError:
                continue
    record["participants"] = participants
    attachment_rows = value.get("attachments", record.get("attachments", []))
    attachments: list[dict[str, Any]] = []
    if isinstance(attachment_rows, list):
        for raw in attachment_rows:
            try:
                attachments.append(normalize_vault_attachment(raw, item_id=str(record["id"])))
            except ValueError:
                continue
    record["attachments"] = attachments
    record["content_hash"] = vault_item_content_hash(record)
    return validate_vault_item(record)


def validate_vault_item(value: Any, *, location: str = "Vault item") -> dict[str, Any]:
    expected = {
        "schema", "data_version", "id", "source_id", "container_id", "external_id",
        "item_type", "thread_id", "parent_item_id", "title", "summary", "body_text",
        "body_html", "primary_timestamp", "start_timestamp", "end_timestamp",
        "created_timestamp", "updated_timestamp", "author_id", "author_display_name",
        "source_url", "is_unread", "is_deleted", "is_all_day", "content_hash",
        "first_synced_at", "last_synced_at", "last_seen_sync_generation", "participants",
        "attachments", "metadata", "raw_payload_reference",
    }
    if not isinstance(value, dict) or set(value) != expected:
        raise UnsupportedDataVersionError(f"Invalid Vault item shape in {location}")
    if value.get("schema") != VAULT_ITEM_SCHEMA or value.get("data_version") != DATA_FILE_VERSION:
        raise UnsupportedDataVersionError(f"Unsupported Vault item model in {location}")
    if not all(is_uuid_v4(value.get(key)) for key in ("id", "source_id", "container_id")):
        raise ValueError(f"Invalid Vault item identity in {location}")
    if value.get("item_type") not in VAULT_ITEM_TYPES or not str(value.get("external_id") or "").strip():
        raise ValueError(f"Invalid Vault item type/external ID in {location}")
    parent = value.get("parent_item_id")
    if parent is not None and not is_uuid_v4(parent):
        raise ValueError(f"Invalid Vault item parent in {location}")
    for key in (
        "thread_id", "title", "summary", "body_text", "body_html", "primary_timestamp",
        "start_timestamp", "end_timestamp", "created_timestamp", "updated_timestamp",
        "author_id", "author_display_name", "source_url", "content_hash", "first_synced_at",
        "last_synced_at", "raw_payload_reference",
    ):
        if not isinstance(value.get(key), str):
            raise ValueError(f"Invalid Vault item {key} in {location}")
    if not value.get("primary_timestamp") or not re.fullmatch(r"[0-9a-f]{64}", str(value.get("content_hash") or "")):
        raise ValueError(f"Invalid Vault item timestamp/content hash in {location}")
    allow_date = bool(value.get("is_all_day"))
    validate_vault_timestamp_value(value["primary_timestamp"], field_name=f"{location}.primary_timestamp", allow_empty=False, allow_date=allow_date)
    for key in ("start_timestamp", "end_timestamp"):
        validate_vault_timestamp_value(value[key], field_name=f"{location}.{key}", allow_date=allow_date)
    for key in ("created_timestamp", "updated_timestamp"):
        validate_vault_timestamp_value(value[key], field_name=f"{location}.{key}")
    validate_vault_timestamp_value(value["first_synced_at"], field_name=f"{location}.first_synced_at", allow_empty=False)
    validate_vault_timestamp_value(value["last_synced_at"], field_name=f"{location}.last_synced_at", allow_empty=False)
    for key in ("is_unread", "is_deleted", "is_all_day"):
        if not isinstance(value.get(key), bool):
            raise ValueError(f"Invalid Vault item {key} in {location}")
    generation = value.get("last_seen_sync_generation")
    if isinstance(generation, bool) or not isinstance(generation, int) or generation < 0:
        raise ValueError(f"Invalid Vault item sync generation in {location}")
    if not isinstance(value.get("participants"), list) or not isinstance(value.get("attachments"), list) or not isinstance(value.get("metadata"), dict):
        raise ValueError(f"Invalid Vault item collections in {location}")
    for index, participant in enumerate(value["participants"]):
        validate_vault_participant(participant, location=f"{location}.participants[{index}]")
    for index, attachment in enumerate(value["attachments"]):
        validate_vault_attachment(attachment, location=f"{location}.attachments[{index}]")
        if attachment["item_id"] != value["id"]:
            raise ValueError(f"Vault attachment owner mismatch in {location}")
    return value


def normalize_vault_sync_state(value: Any, *, existing: dict[str, Any] | None = None) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError("Vault sync state must be an object")
    source_id = str(value.get("source_id") or (existing or {}).get("source_id") or "").strip()
    container_raw = value.get("container_id", (existing or {}).get("container_id"))
    cursor_type = str(value.get("cursor_type") or (existing or {}).get("cursor_type") or "generic").strip().lower()
    if not is_uuid_v4(source_id) or cursor_type not in VAULT_CURSOR_TYPES:
        raise ValueError("Vault sync state source and cursor type are required")
    now = now_iso()
    record = copy.deepcopy(existing) if isinstance(existing, dict) else {
        "schema": VAULT_SYNC_STATE_SCHEMA,
        "data_version": DATA_FILE_VERSION,
        "id": uuid_v4(),
        "source_id": source_id,
        "container_id": None,
        "cursor_type": cursor_type,
        "cursor_value": "",
        "sync_generation": 0,
        "last_attempt_at": "",
        "last_success_at": "",
        "last_error": "",
        "consecutive_failures": 0,
        "metadata": {},
        "updated_at": now,
    }
    if is_uuid_v4(value.get("id")) and existing is None:
        record["id"] = str(value["id"])
    record.update({
        "schema": VAULT_SYNC_STATE_SCHEMA,
        "data_version": DATA_FILE_VERSION,
        "source_id": source_id,
        "container_id": None if container_raw in (None, "") else str(container_raw),
        "cursor_type": cursor_type,
        "cursor_value": str(value.get("cursor_value", record.get("cursor_value", "")) or ""),
        "sync_generation": _vault_nonnegative_int(
            value.get("sync_generation", record.get("sync_generation", 0)),
        ),
        "last_attempt_at": normalize_vault_timestamp(value.get("last_attempt_at", record.get("last_attempt_at", "")), field_name="Vault sync last_attempt_at"),
        "last_success_at": normalize_vault_timestamp(value.get("last_success_at", record.get("last_success_at", "")), field_name="Vault sync last_success_at"),
        "last_error": str(value.get("last_error", record.get("last_error", "")) or ""),
        "consecutive_failures": _vault_nonnegative_int(
            value.get("consecutive_failures", record.get("consecutive_failures", 0)),
        ),
        "metadata": copy.deepcopy(value.get("metadata") if isinstance(value.get("metadata"), dict) else record.get("metadata", {})),
        "updated_at": normalize_vault_timestamp(value.get("updated_at") or now, field_name="Vault sync updated_at"),
    })
    return validate_vault_sync_state(record)


def validate_vault_sync_state(value: Any, *, location: str = "Vault sync state") -> dict[str, Any]:
    expected = {
        "schema", "data_version", "id", "source_id", "container_id", "cursor_type",
        "cursor_value", "sync_generation", "last_attempt_at", "last_success_at",
        "last_error", "consecutive_failures", "metadata", "updated_at",
    }
    if not isinstance(value, dict) or set(value) != expected:
        raise UnsupportedDataVersionError(f"Invalid Vault sync-state shape in {location}")
    if value.get("schema") != VAULT_SYNC_STATE_SCHEMA or value.get("data_version") != DATA_FILE_VERSION:
        raise UnsupportedDataVersionError(f"Unsupported Vault sync-state model in {location}")
    if not is_uuid_v4(value.get("id")) or not is_uuid_v4(value.get("source_id")):
        raise ValueError(f"Invalid Vault sync-state identity in {location}")
    if value.get("container_id") is not None and not is_uuid_v4(value.get("container_id")):
        raise ValueError(f"Invalid Vault sync-state container in {location}")
    if value.get("cursor_type") not in VAULT_CURSOR_TYPES:
        raise ValueError(f"Invalid Vault sync-state cursor type in {location}")
    for key in ("cursor_value", "last_attempt_at", "last_success_at", "last_error", "updated_at"):
        if not isinstance(value.get(key), str):
            raise ValueError(f"Invalid Vault sync-state {key} in {location}")
    validate_vault_timestamp_value(value["updated_at"], field_name=f"{location}.updated_at", allow_empty=False)
    validate_vault_timestamp_value(value["last_attempt_at"], field_name=f"{location}.last_attempt_at")
    validate_vault_timestamp_value(value["last_success_at"], field_name=f"{location}.last_success_at")
    for key in ("sync_generation", "consecutive_failures"):
        if isinstance(value.get(key), bool) or not isinstance(value.get(key), int) or value[key] < 0:
            raise ValueError(f"Invalid Vault sync-state {key} in {location}")
    if not isinstance(value.get("metadata"), dict):
        raise ValueError(f"Invalid Vault sync-state metadata in {location}")
    return value


def calendar_vault_external_id(event: dict[str, Any]) -> str:
    base = f"{str(event.get('external_calendar_id') or '').strip()}:{str(event.get('external_event_id') or '').strip()}"
    occurrence = str(event.get("recurrence_instance_id") or "").strip()
    return f"{base}@{occurrence}" if occurrence else base


def calendar_event_to_vault_item(
    event: dict[str, Any],
    source_id: str,
    container_id: str,
    *,
    sync_generation: int = 0,
    raw_payload_reference: str = "",
) -> dict[str, Any]:
    validate_calendar_event_record(event)
    raw = event.get("raw_payload") if isinstance(event.get("raw_payload"), dict) else {}
    raw_attendees = raw.get("attendees") if isinstance(raw.get("attendees"), list) else []
    response_by_identity: dict[tuple[str, str], str] = {}
    response_by_email: dict[str, str] = {}
    response_by_name: dict[str, str] = {}
    for attendee in raw_attendees:
        if not isinstance(attendee, dict):
            continue
        email_key = str(attendee.get("email") or "").strip().casefold()
        name_key = str(attendee.get("displayName") or "").strip().casefold()
        response = str(attendee.get("responseStatus") or "")
        response_by_identity[(email_key, name_key)] = response
        if email_key:
            response_by_email[email_key] = response
        if name_key:
            response_by_name[name_key] = response
    participants: list[dict[str, Any]] = []
    organizer = event.get("organizer") if isinstance(event.get("organizer"), dict) else {}
    if organizer.get("name") or organizer.get("email"):
        participants.append({
            "participant_type": "person", "external_id": str(organizer.get("email") or ""),
            "display_name": str(organizer.get("name") or ""), "email": str(organizer.get("email") or ""),
            "role": "organizer", "response_status": "", "metadata": {},
        })
    for attendee in event.get("attendees") or []:
        if not isinstance(attendee, dict):
            continue
        email_value = str(attendee.get("email") or "")
        name_value = str(attendee.get("name") or "")
        participants.append({
            "participant_type": "person", "external_id": email_value,
            "display_name": name_value, "email": email_value, "role": "attendee",
            "response_status": (
                response_by_identity.get((email_value.casefold(), name_value.casefold()))
                or response_by_email.get(email_value.casefold())
                or response_by_name.get(name_value.casefold())
                or ""
            ),
            "metadata": {},
        })
    all_day = bool(event.get("all_day"))
    metadata = {
        "google_event_id": str(event.get("external_event_id") or ""),
        "ical_uid": str(raw.get("iCalUID") or ""),
        "calendar_id": str(event.get("external_calendar_id") or ""),
        "calendar_display_name": str(event.get("calendar_name") or ""),
        "location": str(event.get("location") or ""),
        "event_status": str(event.get("status") or "unknown"),
        "visibility": str(raw.get("visibility") or ""),
        "time_zone": str(event.get("time_zone") or ""),
        "recurrence": copy.deepcopy(raw.get("recurrence") if isinstance(raw.get("recurrence"), list) else []),
        "recurring_series_id": str(event.get("recurring_event_id") or ""),
        "occurrence_identity": str(event.get("recurrence_instance_id") or ""),
        "conference_url": str(event.get("meeting_url") or ""),
        "all_day_start_date": str(event.get("start") or "") if all_day else "",
        "all_day_end_date_exclusive": str(event.get("end") or "") if all_day else "",
    }
    description = str(event.get("description") or "")
    return normalize_vault_item({
        "id": str(event["event_id"]),
        "source_id": source_id,
        "container_id": container_id,
        "external_id": calendar_vault_external_id(event),
        "item_type": "calendar_event",
        "thread_id": str(event.get("recurring_event_id") or ""),
        "title": str(event.get("title") or ""),
        "summary": description[:320],
        "body_text": description,
        "body_html": "",
        "primary_timestamp": str(event.get("start") or ""),
        "start_timestamp": str(event.get("start") or ""),
        "end_timestamp": str(event.get("end") or ""),
        "created_timestamp": str(event.get("external_created_at") or ""),
        "updated_timestamp": str(event.get("external_updated_at") or ""),
        "author_id": str(organizer.get("email") or ""),
        "author_display_name": str(organizer.get("name") or organizer.get("email") or ""),
        "source_url": str(event.get("original_url") or event.get("meeting_url") or ""),
        "is_unread": False,
        # Cancellation is retained in metadata as source status; it is not a Vault tombstone.
        "is_deleted": False,
        "is_all_day": all_day,
        "participants": participants,
        "attachments": [],
        "metadata": metadata,
        "raw_payload_reference": str(raw_payload_reference or f"calendar/events/event_{event['event_id']}.json"),
        "last_synced_at": str(event.get("last_synced_at") or now_iso()),
        "last_seen_sync_generation": int(sync_generation or 0),
    })


def gmail_stable_external_id(payload: dict[str, Any]) -> str:
    for key in ("x_gm_msgid", "gmail_message_id", "gm_msgid", "external_id"):
        value = str(payload.get(key) or "").strip()
        if value:
            return value
    uid = str(payload.get("imap_uid") or payload.get("uid") or "").strip()
    uidvalidity = str(payload.get("imap_uidvalidity") or payload.get("uidvalidity") or "").strip()
    if uid and uidvalidity:
        return f"imap:{uidvalidity}:{uid}"
    rfc_id = str(payload.get("rfc_message_id") or payload.get("message_id") or "").strip()
    if rfc_id:
        return f"rfc:{rfc_id}"
    raise ValueError("Gmail message requires X-GM-MSGID, UID/UIDVALIDITY, or RFC Message-ID")


def _vault_people_from_value(value: Any, role: str) -> list[dict[str, Any]]:
    rows = value if isinstance(value, list) else ([] if value in (None, "") else [value])
    participants: list[dict[str, Any]] = []
    for raw in rows:
        if isinstance(raw, dict):
            name_value = str(raw.get("display_name") or raw.get("name") or "")
            email_value = str(raw.get("email") or raw.get("address") or "")
            external_id = str(raw.get("external_id") or email_value)
        else:
            text = str(raw or "").strip()
            match = re.match(r"^(.*?)\s*<([^>]+)>$", text)
            name_value = match.group(1).strip().strip('"') if match else ""
            email_value = match.group(2).strip() if match else text
            external_id = email_value
        if not name_value and not email_value:
            continue
        participants.append({
            "participant_type": "person", "external_id": external_id,
            "display_name": name_value, "email": email_value, "role": role,
            "response_status": "", "metadata": {},
        })
    return participants


def gmail_message_to_vault_item(payload: dict[str, Any], source_id: str, container_id: str) -> dict[str, Any]:
    if not isinstance(payload, dict):
        raise ValueError("Gmail payload must be an object")
    external_id = gmail_stable_external_id(payload)
    internal_ts = payload.get("internal_received_timestamp") or payload.get("internal_date") or ""
    header_ts = payload.get("header_date_timestamp") or payload.get("date") or ""
    primary = internal_ts or header_ts
    if not primary:
        raise ValueError("Gmail message requires an internal or Date-header timestamp")
    participants: list[dict[str, Any]] = []
    participants += _vault_people_from_value(payload.get("from") or payload.get("sender"), "sender")
    participants += _vault_people_from_value(payload.get("to"), "recipient")
    participants += _vault_people_from_value(payload.get("cc"), "cc")
    participants += _vault_people_from_value(payload.get("bcc"), "bcc")
    sender = next((row for row in participants if row["role"] == "sender"), None) or {}
    flags = [str(row) for row in payload.get("flags", [])] if isinstance(payload.get("flags"), list) else []
    metadata = {
        "gmail_message_id": external_id,
        "gmail_thread_id": str(payload.get("x_gm_thrid") or payload.get("gmail_thread_id") or payload.get("thread_id") or ""),
        "rfc_message_id": str(payload.get("rfc_message_id") or payload.get("message_id") or ""),
        "imap_uid": str(payload.get("imap_uid") or payload.get("uid") or ""),
        "imap_uidvalidity": str(payload.get("imap_uidvalidity") or payload.get("uidvalidity") or ""),
        "mailbox_identifier": str(payload.get("mailbox_identifier") or payload.get("mailbox") or ""),
        "reply_to": copy.deepcopy(payload.get("reply_to") or []),
        "internal_received_timestamp": str(internal_ts or ""),
        "header_date_timestamp": str(header_ts or ""),
        "flags": flags,
        "labels": [str(row) for row in payload.get("labels", [])] if isinstance(payload.get("labels"), list) else [],
    }
    return normalize_vault_item({
        "id": stable_uuid_v4("velox-vault-item", f"{source_id}|{external_id}"),
        "source_id": source_id,
        "container_id": container_id,
        "external_id": external_id,
        "item_type": "gmail_message",
        "thread_id": metadata["gmail_thread_id"],
        "title": str(payload.get("subject") or "(No subject)"),
        "summary": str(payload.get("summary") or ""),
        "body_text": str(payload.get("body_text") or payload.get("text") or ""),
        "body_html": str(payload.get("body_html") or payload.get("html") or ""),
        "primary_timestamp": primary,
        "created_timestamp": header_ts,
        "updated_timestamp": str(payload.get("updated_timestamp") or ""),
        "author_id": str(sender.get("external_id") or sender.get("email") or ""),
        "author_display_name": str(sender.get("display_name") or sender.get("email") or ""),
        "source_url": str(payload.get("source_url") or ""),
        "is_unread": bool(payload.get("is_unread", "\\Seen" not in flags)),
        "is_deleted": bool(payload.get("is_deleted", False)),
        "is_all_day": False,
        "participants": participants,
        "attachments": payload.get("attachments") if isinstance(payload.get("attachments"), list) else [],
        "metadata": metadata,
        "raw_payload_reference": str(payload.get("raw_payload_reference") or ""),
        "last_seen_sync_generation": _vault_nonnegative_int(payload.get("last_seen_sync_generation")),
    })


def slack_message_external_id(conversation_id: str, timestamp: str) -> str:
    conversation = str(conversation_id or "").strip()
    ts = str(timestamp or "").strip()
    if not conversation or not re.fullmatch(r"\d+(?:\.\d+)?", ts):
        raise ValueError("Slack message requires a conversation ID and message timestamp")
    return f"{conversation}:{ts}"


def slack_message_to_vault_item(
    payload: dict[str, Any],
    source_id: str,
    container_id: str,
    *,
    parent_item_id: str | None = None,
) -> dict[str, Any]:
    """Normalize one read-only Slack message or reply for Vault storage."""
    if not isinstance(payload, dict):
        raise ValueError("Slack payload must be an object")
    conversation_id = str(payload.get("conversation_id") or payload.get("channel") or "").strip()
    timestamp = str(payload.get("message_timestamp") or payload.get("ts") or "").strip()
    external_id = slack_message_external_id(conversation_id, timestamp)
    thread_ts = str(payload.get("thread_timestamp") or payload.get("thread_ts") or "").strip()
    is_reply = bool(thread_ts and thread_ts != timestamp)
    author_id = str(payload.get("user_id") or payload.get("user") or payload.get("bot_id") or "").strip()
    author_name = str(payload.get("author_display_name") or payload.get("resolved_author_name") or author_id).strip()
    is_bot = bool(payload.get("bot_id") or payload.get("is_bot"))
    edited = payload.get("edited") if isinstance(payload.get("edited"), dict) else {}
    parent_timestamp = str(payload.get("parent_message_timestamp") or (thread_ts if is_reply else ""))
    files = copy.deepcopy(payload.get("files") if isinstance(payload.get("files"), list) else [])
    reactions = copy.deepcopy(payload.get("reactions") if isinstance(payload.get("reactions"), list) else [])
    links = copy.deepcopy(payload.get("links") if isinstance(payload.get("links"), list) else [])
    blocks = copy.deepcopy(payload.get("blocks") if isinstance(payload.get("blocks"), list) else [])
    reply_users = [str(row) for row in payload.get("reply_users", [])] if isinstance(payload.get("reply_users"), list) else []
    metadata = {
        "workspace_id": str(payload.get("workspace_id") or ""),
        "conversation_id": conversation_id,
        "conversation_type": str(payload.get("conversation_type") or ""),
        "message_timestamp": timestamp,
        "thread_timestamp": thread_ts,
        "parent_message_timestamp": parent_timestamp,
        "parent_external_id": slack_message_external_id(conversation_id, parent_timestamp) if parent_timestamp else "",
        "edited_timestamp": str(payload.get("edited_timestamp") or edited.get("ts") or ""),
        "subtype": str(payload.get("subtype") or ""),
        "reply_count": _vault_nonnegative_int(payload.get("reply_count")),
        "latest_reply_timestamp": str(payload.get("latest_reply_timestamp") or payload.get("latest_reply") or ""),
        "reply_users": reply_users,
        "reactions": reactions,
        "links": links,
        "files": files,
        "blocks": blocks,
        "raw_text": str(payload.get("raw_text") or payload.get("text") or ""),
        "bot_id": str(payload.get("bot_id") or ""),
        "username": str(payload.get("username") or ""),
    }
    attachments = []
    for file_row in files:
        if not isinstance(file_row, dict):
            continue
        attachments.append({
            "external_id": str(file_row.get("id") or ""),
            "filename": str(file_row.get("name") or file_row.get("title") or ""),
            "mime_type": str(file_row.get("mimetype") or ""),
            "size_bytes": _vault_nonnegative_int(file_row.get("size")),
            "source_url": str(file_row.get("permalink") or file_row.get("url_private") or ""),
            "is_inline": False,
            "content_id": "",
            "metadata": {
                "title": str(file_row.get("title") or ""),
                "thumb": str(file_row.get("thumb_360") or file_row.get("thumb_160") or ""),
            },
        })
    return normalize_vault_item({
        "id": stable_uuid_v4("velox-vault-item", f"{source_id}|{external_id}"),
        "source_id": source_id,
        "container_id": container_id,
        "external_id": external_id,
        "item_type": "slack_thread_reply" if is_reply else "slack_message",
        "thread_id": slack_message_external_id(conversation_id, thread_ts) if thread_ts else "",
        "parent_item_id": parent_item_id,
        "title": "",
        "summary": "",
        "body_text": str(payload.get("body_text") or payload.get("text") or ""),
        "body_html": "",
        "primary_timestamp": timestamp,
        "created_timestamp": timestamp,
        "updated_timestamp": metadata["edited_timestamp"],
        "author_id": author_id,
        "author_display_name": author_name,
        "source_url": str(payload.get("source_permalink") or payload.get("permalink") or ""),
        "is_unread": bool(payload.get("is_unread", False)),
        "is_deleted": bool(payload.get("is_deleted", False)),
        "is_all_day": False,
        "participants": [{
            "participant_type": "bot" if is_bot else "user",
            "external_id": author_id,
            "display_name": author_name,
            "email": "",
            "role": "slack_bot" if is_bot else "slack_user",
            "response_status": "",
            "metadata": {},
        }],
        "attachments": attachments,
        "metadata": metadata,
        "raw_payload_reference": str(payload.get("raw_payload_reference") or ""),
        "last_seen_sync_generation": _vault_nonnegative_int(payload.get("last_seen_sync_generation")),
    })


