def stable_uuid_v4(namespace: str, value: Any) -> str:
    """Return a deterministic UUID carrying RFC-4122 version-4 marker bits."""
    seed = f"{str(namespace or '').strip()}\0{str(value or '').strip()}".encode("utf-8")
    raw = bytearray(hashlib.sha256(seed).digest()[:16])
    raw[6] = (raw[6] & 0x0F) | 0x40
    raw[8] = (raw[8] & 0x3F) | 0x80
    return str(uuid.UUID(bytes=bytes(raw)))


def default_vault_source_id(source_type: str, account_identifier: str = "") -> str:
    resolved = str(source_type or "").strip().lower()
    if resolved not in VAULT_SOURCE_TYPES:
        raise ValueError("Unsupported Vault source type")
    account = str(account_identifier or "default").strip().casefold() or "default"
    return stable_uuid_v4("velox-vault-source", f"{resolved}|{account}")


def _vault_required_text(value: Any, label: str) -> str:
    text = str(value or "").strip()
    if not text:
        raise ValueError(f"{label} is required")
    return text


def _vault_metadata(value: Any) -> dict[str, Any]:
    return copy.deepcopy(value) if isinstance(value, dict) else {}


def _vault_nonnegative_int(value: Any, default: int = 0) -> int:
    """Best-effort normalization for optional connector counters and sizes."""
    if isinstance(value, bool):
        return max(0, int(default))
    try:
        return max(0, int(value or 0))
    except (TypeError, ValueError, OverflowError):
        return max(0, int(default))


def normalize_timezone_safe_timestamp(
    value: Any, *, field_name: str = "timestamp", allow_empty: bool = False,
) -> str:
    raw = str(value or "").strip()
    if not raw and allow_empty:
        return ""
    normalized = normalize_vault_timestamp(raw, field_name=field_name)
    if not normalized and not allow_empty:
        raise ValueError(f"{field_name} is required")
    return normalized


def vault_content_hash_payload(value: dict[str, Any]) -> str:
    return vault_item_content_hash(value)


def new_vault_data_source(
    source_type: str,
    display_name: str,
    account_identifier: str = "",
    *,
    enabled: bool = True,
    connection_state: str = "not_configured",
    credential_reference: str = "",
    metadata: Any = None,
    source_id: str | None = None,
) -> dict[str, Any]:
    resolved_type = _vault_required_text(source_type, "Vault source type").lower()
    resolved_account = _clean_optional_text(account_identifier)
    return normalize_vault_data_source({
        "id": source_id or default_vault_source_id(resolved_type, resolved_account),
        "source_type": resolved_type,
        "display_name": _vault_required_text(display_name, "Vault source display name"),
        "account_identifier": resolved_account,
        "enabled": bool(enabled),
        "connection_state": "disabled" if not enabled else str(connection_state or "not_configured").strip().lower(),
        "credential_reference": _clean_optional_text(credential_reference),
        "metadata": _vault_metadata(metadata),
    })


def new_vault_container(
    source_id: str,
    external_id: str,
    container_type: str,
    name: str,
    *,
    display_name: str = "",
    parent_container_id: str = "",
    is_archived: bool = False,
    is_hidden: bool = False,
    metadata: Any = None,
    container_id: str | None = None,
) -> dict[str, Any]:
    resolved_source = _vault_required_text(source_id, "Vault source ID")
    resolved_external = _vault_required_text(external_id, "Vault Container external ID")
    return normalize_vault_container({
        "id": container_id or stable_uuid_v4(
            "velox-vault-container", f"{resolved_source}|{resolved_external}",
        ),
        "source_id": resolved_source,
        "external_id": resolved_external,
        "container_type": _vault_required_text(container_type, "Vault Container type").lower(),
        "name": _vault_required_text(name, "Vault Container name"),
        "display_name": _clean_optional_text(display_name) or _vault_required_text(name, "Vault Container name"),
        "parent_container_id": _clean_optional_text(parent_container_id),
        "is_archived": bool(is_archived),
        "is_hidden": bool(is_hidden),
        "metadata": _vault_metadata(metadata),
    })


def new_vault_sync_state(
    source_id: str,
    cursor_type: str = "generic",
    *,
    container_id: str = "",
    sync_state_id: str | None = None,
) -> dict[str, Any]:
    resolved_source = _vault_required_text(source_id, "Vault sync source ID")
    resolved_container = _clean_optional_text(container_id)
    resolved_cursor = _vault_required_text(cursor_type, "Vault cursor type").lower()
    return normalize_vault_sync_state({
        "id": sync_state_id or stable_uuid_v4(
            "velox-vault-sync", f"{resolved_source}|{resolved_container}|{resolved_cursor}",
        ),
        "source_id": resolved_source,
        "container_id": resolved_container,
        "cursor_type": resolved_cursor,
    })


def gmail_vault_external_id(payload: dict[str, Any]) -> str:
    return gmail_stable_external_id(payload)


def gmail_payload_to_vault_item(
    payload: dict[str, Any],
    source_id: str,
    container_id: str,
    *,
    sync_generation: int = 0,
    existing_item_id: str | None = None,
) -> dict[str, Any]:
    source_payload = copy.deepcopy(payload)
    source_payload["last_seen_sync_generation"] = _vault_nonnegative_int(sync_generation)
    item = gmail_message_to_vault_item(source_payload, source_id, container_id)
    if existing_item_id:
        item["id"] = str(existing_item_id)
        for attachment in item["attachments"]:
            attachment["item_id"] = item["id"]
        item["content_hash"] = vault_item_content_hash(item)
        validate_vault_item(item)
    return item


def slack_vault_external_id(conversation_id: str, timestamp: str) -> str:
    return slack_message_external_id(conversation_id, timestamp)


def slack_payload_to_vault_item(
    payload: dict[str, Any],
    source_id: str,
    container_id: str,
    *,
    sync_generation: int = 0,
    existing_item_id: str | None = None,
    parent_item_id: str = "",
) -> dict[str, Any]:
    source_payload = copy.deepcopy(payload)
    source_payload["last_seen_sync_generation"] = _vault_nonnegative_int(sync_generation)
    item = slack_message_to_vault_item(
        source_payload, source_id, container_id, parent_item_id=parent_item_id or None,
    )
    if existing_item_id:
        item["id"] = str(existing_item_id)
        for attachment in item["attachments"]:
            attachment["item_id"] = item["id"]
        item["content_hash"] = vault_item_content_hash(item)
        validate_vault_item(item)
    return item


