def default_tool_usage_stats() -> dict[str, Any]:
    return {
        "schema": TOOL_USAGE_STATS_SCHEMA,
        "tool_calls_total": 0,
        "tool_calls_succeeded": 0,
        "tool_calls_failed": 0,
        "tool_calls_by_type": {},
    }


def validate_tool_usage_stats(stats: Any, *, location: str = "tool usage statistics") -> dict[str, Any]:
    """Validate aggregate tool statistics without coercion."""
    if not isinstance(stats, dict) or stats.get("schema") != TOOL_USAGE_STATS_SCHEMA:
        raise UnsupportedDataVersionError(f"Unsupported {location} model")
    expected_fields = set(default_tool_usage_stats())
    if set(stats) != expected_fields:
        missing = sorted(expected_fields.difference(stats))
        extra = sorted(set(stats).difference(expected_fields))
        details: list[str] = []
        if missing:
            details.append("missing: " + ", ".join(missing))
        if extra:
            details.append("unexpected: " + ", ".join(extra))
        raise UnsupportedDataVersionError(
            f"{location} fields do not match the current data model ({'; '.join(details)})"
        )

    def require_counter(value: Any, label: str) -> int:
        # JSON booleans are Python ints, so reject them explicitly. Accepting
        # strings or floats here would silently normalize malformed persisted
        # records and undermine the clean-model contract.
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError(f"Invalid counter {label} in {location}")
        if value < 0:
            raise ValueError(f"Negative counter {label} in {location}")
        return value

    total = require_counter(stats["tool_calls_total"], "tool_calls_total")
    succeeded = require_counter(stats["tool_calls_succeeded"], "tool_calls_succeeded")
    failed = require_counter(stats["tool_calls_failed"], "tool_calls_failed")
    if total != succeeded + failed:
        raise ValueError(f"Inconsistent counters in {location}")
    by_type = stats["tool_calls_by_type"]
    if not isinstance(by_type, dict):
        raise ValueError(f"Invalid tool_calls_by_type in {location}")
    expected_row_fields = {"total", "succeeded", "failed"}
    summed_total = summed_succeeded = summed_failed = 0
    for tool_name, row in by_type.items():
        if (
            not isinstance(tool_name, str)
            or not tool_name.strip()
            or tool_name != tool_name.strip()
            or not isinstance(row, dict)
        ):
            raise ValueError(f"Invalid tool row in {location}")
        if set(row) != expected_row_fields:
            raise UnsupportedDataVersionError(
                f"Tool row {tool_name!r} fields do not match the current data model in {location}"
            )
        row_total = require_counter(row["total"], f"{tool_name}.total")
        row_succeeded = require_counter(row["succeeded"], f"{tool_name}.succeeded")
        row_failed = require_counter(row["failed"], f"{tool_name}.failed")
        if row_total != row_succeeded + row_failed:
            raise ValueError(f"Inconsistent counters for {tool_name} in {location}")
        summed_total += row_total
        summed_succeeded += row_succeeded
        summed_failed += row_failed
    if (summed_total, summed_succeeded, summed_failed) != (total, succeeded, failed):
        raise ValueError(f"Per-tool counters do not match totals in {location}")
    return stats


def increment_tool_usage_stats(stats: Any, tool_name: str, succeeded: bool) -> dict[str, Any]:
    validate_tool_usage_stats(stats)
    current = copy.deepcopy(stats)
    name = str(tool_name or "unknown").strip() or "unknown"
    current["tool_calls_total"] += 1
    success_key = "tool_calls_succeeded" if succeeded else "tool_calls_failed"
    current[success_key] += 1
    by_type = current["tool_calls_by_type"]
    row = copy.deepcopy(by_type.get(name)) if name in by_type else {"total": 0, "succeeded": 0, "failed": 0}
    row["total"] += 1
    result_key = "succeeded" if succeeded else "failed"
    row[result_key] += 1
    by_type[name] = row
    current["tool_calls_by_type"] = by_type
    return current


def default_chat(
    name: str = "New Chat",
    *,
    chat_kind: str = "standard",
    week_start_date: str | None = None,
    endpoint_profile_id: str = DEFAULT_ENDPOINT_PROFILE_ID,
) -> dict[str, Any]:
    now = now_iso()
    chat_id = uuid_v4()
    resolved_kind = str(chat_kind or "standard").strip().lower()
    if resolved_kind not in CHAT_KINDS:
        raise ValueError("chat_kind must be standard or week")
    resolved_week_start = None
    if resolved_kind == "week":
        normalized_week_start = normalize_iso_date(week_start_date, field_name="Week Chat date")
        resolved_week_start = calendar_week_start(normalized_week_start).isoformat()
    elif week_start_date not in (None, ""):
        raise ValueError("Only a Week Chat may have week_start_date")
    return {
        "schema": CHAT_SCHEMA,
        "data_version": DATA_FILE_VERSION,
        "chat_id": chat_id,
        "name": str(name or "New Chat"),
        "status": "active",
        "chat_kind": resolved_kind,
        "agent_reports_suspended": False,
        "week_start_date": resolved_week_start,
        "endpoint_profile_id": str(endpoint_profile_id or DEFAULT_ENDPOINT_PROFILE_ID).strip(),
        "created_at": now,
        "updated_at": now,
        "stats": default_tool_usage_stats(),
        "tool_failure_count": 0,
        "features": {
            "file_tools_enabled": True,
            "system_tools_enabled": True,
            "web_tools_enabled": True,
            "agent_tools_enabled": True,
            "chat_history_enabled": True,
            "checklists_enabled": True,
            "show_reasoning_content": True,
        },
    }


