    def chat_stream_snapshot_json(self, chat_id: str) -> Path:
        """Checkpoint the one actively streaming turn outside turns.jsonl.

        The main transcript remains append/rewrite oriented. A dedicated live
        snapshot prevents every token batch from reparsing and atomically
        replacing the complete historical JSONL file.
        """
        return self.chat_dir(chat_id) / "streaming_turn.json"

