    def context_doc_revision_file(self, context_doc_id: str, filename: str) -> Path:
        resolved = str(filename or "").strip()
        if not re.fullmatch(r"revision_\d{4}-\d{2}-\d{2}(?:_\d{12,20}_[0-9a-f-]{36})?\.json", resolved):
            raise ValueError("Invalid Context Doc revision filename")
        return self.context_doc_revisions_dir(context_doc_id) / resolved

