def xor_credential_bytes(data: bytes, key: int = CREDENTIAL_XOR_BYTE) -> bytes:
    """Reversibly obscure credential bytes; this is not security or encryption."""
    resolved_key = int(key) & 0xFF
    return bytes(byte ^ resolved_key for byte in bytes(data))


def default_task_id_state() -> dict[str, Any]:
    return {
        "schema": TASK_ID_STATE_SCHEMA,
        "data_version": DATA_FILE_VERSION,
        "next_id": 1,
        "identities": {},
    }


def validate_task_id_state(value: Any, *, location: str = "task_ids.json") -> dict[str, Any]:
    if not isinstance(value, dict):
        raise UnsupportedDataVersionError(f"{location} must contain one JSON object")
    expected_fields = set(default_task_id_state())
    if set(value) != expected_fields:
        missing = sorted(expected_fields.difference(value))
        extra = sorted(set(value).difference(expected_fields))
        details = []
        if missing:
            details.append("missing: " + ", ".join(missing))
        if extra:
            details.append("unexpected: " + ", ".join(extra))
        raise UnsupportedDataVersionError(
            f"{location} fields do not match the current data model ({'; '.join(details)})"
        )
    if value.get("schema") != TASK_ID_STATE_SCHEMA or value.get("data_version") != DATA_FILE_VERSION:
        raise UnsupportedDataVersionError(f"Unsupported Task ID state in {location}")
    next_id = value.get("next_id")
    if isinstance(next_id, bool) or not isinstance(next_id, int) or next_id < 1:
        raise ValueError(f"Invalid next_id in {location}")
    identities = value.get("identities")
    if not isinstance(identities, dict):
        raise ValueError(f"Invalid identities in {location}")
    seen: set[int] = set()
    for key, raw_id in identities.items():
        if not isinstance(key, str) or not key.strip():
            raise ValueError(f"Invalid Task identity key in {location}")
        if isinstance(raw_id, bool) or not isinstance(raw_id, int) or raw_id < 1:
            raise ValueError(f"Invalid Task ID for {key!r} in {location}")
        if raw_id in seen:
            raise ValueError(f"Duplicate globally allocated Task ID {raw_id} in {location}")
        seen.add(raw_id)
    if seen and next_id <= max(seen):
        raise ValueError(f"next_id must exceed every allocated Task ID in {location}")
    return value


class TaskIdStore:
    """Persist one application-wide increasing integer namespace for Tasks and Agent runs."""

    def __init__(self, storage_or_paths: Any):
        self.paths = storage_or_paths.paths if hasattr(storage_or_paths, "paths") else storage_or_paths

    def ensure(self) -> dict[str, Any]:
        path = self.paths.task_ids_json_path
        path.parent.mkdir(parents=True, exist_ok=True)
        with DATA_ROOTS.lock_for_path(path):
            if not path.is_file():
                _plain_atomic_write_bytes(path, json_dumps(default_task_id_state()).encode("utf-8"))
            payload = validate_task_id_state(read_json(path), location=str(path))
        return copy.deepcopy(payload)

    def allocate(self, identity: str, *, preferred: int | None = None) -> int:
        key = str(identity or "").strip()
        if not key:
            raise ValueError("Task ID identity is required")
        path = self.paths.task_ids_json_path
        path.parent.mkdir(parents=True, exist_ok=True)
        with DATA_ROOTS.lock_for_path(path):
            payload = (
                validate_task_id_state(read_json(path), location=str(path))
                if path.is_file() else default_task_id_state()
            )
            identities = payload["identities"]
            existing = identities.get(key)
            if existing is not None:
                return int(existing)
            used = {int(value) for value in identities.values()}
            candidate = int(preferred or 0)
            if candidate < 1 or candidate in used:
                candidate = int(payload["next_id"])
                while candidate in used:
                    candidate += 1
            identities[key] = candidate
            payload["next_id"] = max(int(payload["next_id"]), candidate + 1)
            validate_task_id_state(payload, location=str(path))
            _plain_atomic_write_bytes(path, json_dumps(payload).encode("utf-8"))
            return candidate


class CredentialStore:
    """Cross-revision account files stored outside the strict app data model.

    Each account owns one small JSON payload whose UTF-8 bytes are XORed with
    0x77 before the atomic write. This only hides plain text from casual viewing;
    it is deliberately not presented as cryptographic protection.
    """

    _DEFAULTS: dict[str, dict[str, Any]] = {
        GITHUB_CREDENTIAL_ACCOUNT: {"username": "", "pat": ""},
        GOOGLE_CALENDAR_CREDENTIAL_ACCOUNT: {"client_id": "", "client_secret": "", "token": None},
        GOOGLE_DRIVE_CREDENTIAL_ACCOUNT: {"client_id": "", "client_secret": "", "token": None},
        GMAIL_CREDENTIAL_ACCOUNT: {"email_address": "", "app_password": ""},
        SLACK_CREDENTIAL_ACCOUNT: {
            "client_id": "", "client_secret": "", "access_token": "",
            "workspace_id": "", "authenticated_user_id": "", "team_name": "",
            "scopes": [],
        },
    }

    def __init__(self, paths: AppPaths):
        self.paths = paths
        # Credential files are shared by UI actions and background connector
        # threads. Keep cache reads and read-modify-write updates serialized so
        # a token refresh cannot overwrite a simultaneously edited OAuth client
        # value (or vice versa).
        self._lock = threading.RLock()
        self._cache: dict[str, tuple[tuple[int, int, int, int], dict[str, Any]]] = {}

    def ensure_directory(self) -> None:
        self.paths.credentials_dir().mkdir(parents=True, exist_ok=True)

    def _path(self, account: str) -> Path:
        key = str(account or "").strip().lower()
        if key == GITHUB_CREDENTIAL_ACCOUNT:
            return self.paths.github_credentials_file()
        if key == GOOGLE_CALENDAR_CREDENTIAL_ACCOUNT:
            return self.paths.google_calendar_credentials_file()
        if key == GOOGLE_DRIVE_CREDENTIAL_ACCOUNT:
            return self.paths.google_drive_credentials_file()
        if key == GMAIL_CREDENTIAL_ACCOUNT:
            return self.paths.gmail_credentials_file()
        if key == SLACK_CREDENTIAL_ACCOUNT:
            return self.paths.slack_credentials_file()
        raise ValueError(f"Unsupported credential account: {account}")

    @staticmethod
    def _signature(path: Path) -> tuple[int, int, int, int]:
        try:
            stat = path.stat()
            return (
                int(stat.st_mtime_ns), int(stat.st_ctime_ns),
                int(stat.st_size), int(getattr(stat, "st_ino", 0)),
            )
        except OSError:
            return 0, 0, 0, 0

    def _validate_values(self, account: str, values: Any) -> dict[str, Any]:
        defaults = self._DEFAULTS[account]
        if not isinstance(values, dict) or set(values) != set(defaults):
            raise ValueError(f"Malformed {account} credential fields")
        if account == GITHUB_CREDENTIAL_ACCOUNT:
            if not all(isinstance(values.get(key), str) for key in ("username", "pat")):
                raise ValueError("Malformed GitHub credentials")
            return {"username": str(values["username"]), "pat": str(values["pat"])}
        if account == GMAIL_CREDENTIAL_ACCOUNT:
            if not all(isinstance(values.get(key), str) for key in ("email_address", "app_password")):
                raise ValueError("Malformed Gmail credentials")
            return {
                "email_address": str(values["email_address"]).strip(),
                "app_password": str(values["app_password"]),
            }
        if account == SLACK_CREDENTIAL_ACCOUNT:
            text_fields = (
                "client_id", "client_secret", "access_token", "workspace_id",
                "authenticated_user_id", "team_name",
            )
            if not all(isinstance(values.get(key), str) for key in text_fields):
                raise ValueError("Malformed Slack credentials")
            scopes = values.get("scopes")
            if not isinstance(scopes, list) or not all(isinstance(row, str) for row in scopes):
                raise ValueError("Malformed Slack OAuth scopes")
            return {
                **{key: str(values[key]) for key in text_fields},
                "scopes": sorted({str(row).strip() for row in scopes if str(row).strip()}),
            }
        if not isinstance(values.get("client_id"), str) or not isinstance(values.get("client_secret"), str):
            raise ValueError("Malformed Google OAuth client credentials")
        token = values.get("token")
        if token is not None and not isinstance(token, dict):
            raise ValueError("Malformed Google OAuth token")
        return {
            "client_id": str(values["client_id"]),
            "client_secret": str(values["client_secret"]),
            "token": copy.deepcopy(token),
        }

    def _load(self, account: str) -> dict[str, Any]:
        key = str(account or "").strip().lower()
        path = self._path(key)
        # Always acquire the app-root lock before the instance cache lock. The
        # same ordering is used by _save() and _mutate(), preventing a direct
        # save in one thread from deadlocking with a read-modify-write update in
        # another thread using the same CredentialStore instance.
        with DATA_ROOTS.lock_for_path(path):
            with self._lock:
                signature = self._signature(path)
                cached = self._cache.get(key)
                if cached is not None and cached[0] == signature:
                    return copy.deepcopy(cached[1])
                if not path.is_file():
                    values = copy.deepcopy(self._DEFAULTS[key])
                    self._cache[key] = (signature, values)
                    return copy.deepcopy(values)
                try:
                    decoded = xor_credential_bytes(file_read_bytes(path)).decode("utf-8")
                    payload = json.loads(decoded)
                except Exception as exc:
                    raise ValueError(f"Credential file is malformed: {path}: {type(exc).__name__}: {exc}") from exc
                if (
                    not isinstance(payload, dict)
                    or payload.get("schema") != CREDENTIAL_FILE_SCHEMA
                    or payload.get("account") != key
                    or set(payload) != {"schema", "account", "credentials", "updated_at"}
                ):
                    raise ValueError(f"Credential file has an unsupported account payload: {path}")
                values = self._validate_values(key, payload.get("credentials"))
                self._cache[key] = (signature, copy.deepcopy(values))
                return copy.deepcopy(values)

    def _save(self, account: str, values: dict[str, Any]) -> dict[str, Any]:
        key = str(account or "").strip().lower()
        path = self._path(key)
        with DATA_ROOTS.lock_for_path(path):
            with self._lock:
                clean = self._validate_values(key, values)
                self.ensure_directory()
                payload = {
                    "schema": CREDENTIAL_FILE_SCHEMA,
                    "account": key,
                    "credentials": clean,
                    "updated_at": now_iso(),
                }
                raw = json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8")
                _plain_atomic_write_bytes(path, xor_credential_bytes(raw))
                self._cache[key] = (self._signature(path), copy.deepcopy(clean))
                return copy.deepcopy(clean)

    def _mutate(self, account: str, update: Callable[[dict[str, Any]], None]) -> dict[str, Any]:
        """Atomically read, modify, and save one account across store instances."""
        key = str(account or "").strip().lower()
        path = self._path(key)
        # DATA_ROOTS provides one re-entrant lock per app root, so independent
        # CredentialStore instances used by Settings and connector workers cannot
        # overwrite each other's client/token fields with stale snapshots.
        with DATA_ROOTS.lock_for_path(path):
            with self._lock:
                current = self._load(key)
                update(current)
                return self._save(key, current)

    def load_github(self) -> dict[str, str]:
        return self._load(GITHUB_CREDENTIAL_ACCOUNT)

    def save_github(self, username: str, pat: str) -> dict[str, str]:
        return self._save(GITHUB_CREDENTIAL_ACCOUNT, {
            "username": str(username or ""),
            "pat": str(pat or ""),
        })

    def load_google_calendar(self) -> dict[str, Any]:
        return self._load(GOOGLE_CALENDAR_CREDENTIAL_ACCOUNT)

    def save_google_oauth_client(self, client_id: str, client_secret: str) -> dict[str, Any]:
        def update(current: dict[str, Any]) -> None:
            current["client_id"] = str(client_id or "").strip()
            current["client_secret"] = str(client_secret or "").strip()
        return self._mutate(GOOGLE_CALENDAR_CREDENTIAL_ACCOUNT, update)

    def save_google_token(self, token: dict[str, Any]) -> dict[str, Any]:
        if not isinstance(token, dict):
            raise ValueError("Google Calendar token must be a JSON object")
        return self._mutate(
            GOOGLE_CALENDAR_CREDENTIAL_ACCOUNT,
            lambda current: current.__setitem__("token", copy.deepcopy(token)),
        )

    def clear_google_token(self) -> dict[str, Any]:
        return self._mutate(
            GOOGLE_CALENDAR_CREDENTIAL_ACCOUNT,
            lambda current: current.__setitem__("token", None),
        )

    def load_google_drive(self) -> dict[str, Any]:
        return self._load(GOOGLE_DRIVE_CREDENTIAL_ACCOUNT)

    def save_google_drive_oauth_client(self, client_id: str, client_secret: str) -> dict[str, Any]:
        def update(current: dict[str, Any]) -> None:
            current["client_id"] = str(client_id or "").strip()
            current["client_secret"] = str(client_secret or "").strip()
        return self._mutate(GOOGLE_DRIVE_CREDENTIAL_ACCOUNT, update)

    def save_google_drive_token(self, token: dict[str, Any]) -> dict[str, Any]:
        if not isinstance(token, dict):
            raise ValueError("Google Drive token must be a JSON object")
        return self._mutate(
            GOOGLE_DRIVE_CREDENTIAL_ACCOUNT,
            lambda current: current.__setitem__("token", copy.deepcopy(token)),
        )

    def clear_google_drive_token(self) -> dict[str, Any]:
        return self._mutate(
            GOOGLE_DRIVE_CREDENTIAL_ACCOUNT,
            lambda current: current.__setitem__("token", None),
        )

    def load_gmail(self) -> dict[str, str]:
        return self._load(GMAIL_CREDENTIAL_ACCOUNT)

    def save_gmail(self, email_address: str, app_password: str) -> dict[str, str]:
        return self._save(GMAIL_CREDENTIAL_ACCOUNT, {
            "email_address": str(email_address or "").strip(),
            "app_password": str(app_password or "").replace(" ", ""),
        })

    def clear_gmail_app_password(self) -> dict[str, str]:
        return self._mutate(
            GMAIL_CREDENTIAL_ACCOUNT,
            lambda current: current.__setitem__("app_password", ""),
        )

    def load_slack(self) -> dict[str, Any]:
        return self._load(SLACK_CREDENTIAL_ACCOUNT)

    def save_slack_oauth_client(self, client_id: str, client_secret: str) -> dict[str, Any]:
        def update(current: dict[str, Any]) -> None:
            current["client_id"] = str(client_id or "").strip()
            current["client_secret"] = str(client_secret or "").strip()
        return self._mutate(SLACK_CREDENTIAL_ACCOUNT, update)

    def save_slack_token(
        self,
        access_token: str,
        *,
        workspace_id: str = "",
        authenticated_user_id: str = "",
        team_name: str = "",
        scopes: Iterable[str] = (),
    ) -> dict[str, Any]:
        def update(current: dict[str, Any]) -> None:
            current.update({
                "access_token": str(access_token or "").strip(),
                "workspace_id": str(workspace_id or "").strip(),
                "authenticated_user_id": str(authenticated_user_id or "").strip(),
                "team_name": str(team_name or "").strip(),
                "scopes": sorted({str(row).strip() for row in scopes if str(row).strip()}),
            })
        return self._mutate(SLACK_CREDENTIAL_ACCOUNT, update)

    def clear_slack_token(self) -> dict[str, Any]:
        def update(current: dict[str, Any]) -> None:
            current.update({
                "access_token": "", "workspace_id": "", "authenticated_user_id": "",
                "team_name": "", "scopes": [],
            })
        return self._mutate(SLACK_CREDENTIAL_ACCOUNT, update)

    def validate_all(self) -> None:
        self.ensure_directory()
        for account in self._DEFAULTS:
            path = self._path(account)
            if path.is_file():
                self._load(account)


class Storage:
    def __init__(self, paths: AppPaths):
        self.paths = paths
        self.data_root = DATA_ROOTS.register(paths.root_dir)
        self._ensured = False
        self._ensuring = False
        # CPU hot-path cache: callers that only read Settings may share one
        # already-validated snapshot. Ordinary load_config() still returns an
        # isolated copy, while immediate-mode UI code uses load_config_view()
        # and avoids rebuilding/validating the full nested settings tree every
        # frame. In-process writes replace this object immediately; external
        # changes are detected by a bounded signature poll.
        self._config_view_lock = threading.RLock()
        self._config_view_cache: dict[str, Any] | None = None
        self._config_view_sig: tuple[int, int, int, int] | None = None
        self._config_view_checked_at: float = 0.0

    def ensure_first_run_files(self) -> None:
        """Create or validate the application data root and its local stores."""
        # This method sits beneath several read-only view helpers used by the
        # immediate-mode UI. Once initialization succeeds, avoid repeating
        # path resolution and DATA_ROOTS registry locking on every frame.
        if self._ensured or self._ensuring:
            return
        self.data_root = DATA_ROOTS.register(self.paths.root_dir)
        self._ensuring = True
        try:
            self.paths.root_dir.mkdir(parents=True, exist_ok=True)
            if not self.paths.app_json_path.exists():
                DATA_ROOTS.write_manifest(self.paths.root_dir)
                self.data_root = DATA_ROOTS.register(self.paths.root_dir)
            else:
                self.data_root = DATA_ROOTS.register(self.paths.root_dir)
            DATA_ROOTS.assert_supported(self.paths.root_dir)
            self._validate_current_manifest(self.paths.app_manifest())
            TaskIdStore(self).ensure()
            self.paths.chats_dir().mkdir(parents=True, exist_ok=True)
            self.paths.agents_dir().mkdir(parents=True, exist_ok=True)
            self.paths.pa_reports_dir().mkdir(parents=True, exist_ok=True)
            # The native C/C++ Skill is machine-generated from live Visual Studio, MSVC, and CMake discovery on every startup.
            self.paths.skills_dir().mkdir(parents=True, exist_ok=True)
            refresh_machine_generated_skills_for_startup(self.paths.root_dir)
            credentials = CredentialStore(self.paths)
            credentials.ensure_directory()
            credentials.validate_all()
            if not self.paths.log_jsonl_path.exists():
                atomic_write_text(self.paths.log_jsonl_path, "")
            for child in self.paths.chats_dir().iterdir():
                if not child.is_dir() or not child.name.startswith("chat_"):
                    continue
                meta_path = child / "chat.json"
                if not meta_path.exists():
                    raise ValueError(f"Chat directory is missing chat.json: {child}")
                meta = validate_chat_record(
                    read_json(meta_path), expected_chat_id=child.name.removeprefix("chat_"), location=str(meta_path),
                )
                cid = str(meta["chat_id"])
                load_chat_turn_records(self.paths, cid)
                load_chat_summary_record(self.paths, cid)
                for sub in ("attachments", "attachments_processed", "workspace", "temp"):
                    (child / sub).mkdir(parents=True, exist_ok=True)
            for child in self.paths.agents_dir().iterdir():
                if not child.is_dir() or not child.name.startswith("agent_"):
                    continue
                meta_path = child / "agent.json"
                if not meta_path.exists():
                    raise ValueError(f"Agent directory is missing agent.json: {child}")
                meta = validate_agent_record(
                    read_json(meta_path), expected_agent_id=child.name.removeprefix("agent_"), location=str(meta_path),
                )
                load_agent_event_records(self.paths, str(meta["agent_id"]))
            calendar_store = CalendarStore(self)
            calendar_store._ensure_layout_unchecked()
            calendar_store._validate_startup_metadata_unchecked()
            vault_store = VaultStore(self)
            # Large Calendar/Vault record sets are validated lazily when their
            # indexed caches are first opened. Startup validates only the small
            # manifests and directory layout so a recent sync cannot make launch
            # scale linearly with every mirrored Event or message.
            vault_store._ensure_layout_unchecked()
            scheduled_tasks = ScheduledTaskStore(self)
            scheduled_tasks.ensure_layout(seed_defaults=False)
            context_docs = ContextDocStore(self, scheduled_tasks)
            context_docs.ensure_layout(seed_defaults=False)
            self._ensured = True
        finally:
            self._ensuring = False

    @staticmethod
    def _validate_current_manifest(manifest: dict[str, Any]) -> None:
        if not isinstance(manifest, dict) or manifest.get("schema") != APP_SCHEMA or manifest.get("data_version") != DATA_FILE_VERSION:
            raise UnsupportedDataVersionError(f"app.json is not the Velox V{SOURCE_REVISION} data model")
        validate_exact_mapping_shape(manifest, default_app_manifest(), location="app.json")
        settings = manifest["settings"]
        validate_endpoint_profiles_config(settings.get("llm"), location="app.json.settings.llm")
        try:
            validate_chat_settings(settings.get("chat"), location="app.json.settings.chat")
            validate_agent_settings(settings.get("agents"), location="app.json.settings.agents")
        except ValueError as exc:
            raise UnsupportedDataVersionError(str(exc)) from exc
        web_mode = str(settings.get("web", {}).get("user_agent_mode") or "")
        if web_mode not in WEB_USER_AGENT_MODES:
            raise UnsupportedDataVersionError("app.json.settings.web.user_agent_mode is invalid")
        try:
            resolve_vault_timezone(settings.get("vault", {}).get("local_timezone"))
            normalize_vault_divider_fraction(settings.get("vault", {}).get("divider_fraction"))
            normalize_vault_divider_fraction(
                settings.get("vault", {}).get("google_drive", {}).get("divider_fraction")
            )
            validate_vault_connector_settings(settings.get("vault", {}))
        except ValueError as exc:
            raise UnsupportedDataVersionError(str(exc)) from exc
        state = manifest["state"]
        if settings.get("schema") != RUNTIME_CONFIG_SCHEMA or settings.get("data_version") != DATA_FILE_VERSION:
            raise UnsupportedDataVersionError("app.json settings are not the current Velox settings model")
        if state.get("schema") != APP_STATE_SCHEMA:
            raise UnsupportedDataVersionError("app.json state is not the current Velox state model")
        if normalize_active_panel(state.get("active_panel")) != state.get("active_panel"):
            raise UnsupportedDataVersionError("app.json state active_panel is invalid")
        try:
            normalized_calendar_date = normalize_iso_date(
                state.get("calendar_selected_date"), field_name="Calendar selected date",
            )
        except ValueError as exc:
            raise UnsupportedDataVersionError(str(exc)) from exc
        if normalized_calendar_date != state.get("calendar_selected_date"):
            raise UnsupportedDataVersionError("app.json state Calendar date is not normalized")
        value = state.get("calendar_chat_width")
        if (
            isinstance(value, bool) or not isinstance(value, int)
            or not (CALENDAR_CHAT_WIDTH_MIN <= value <= CALENDAR_CHAT_WIDTH_MAX)
        ):
            raise UnsupportedDataVersionError("app.json state calendar_chat_width is invalid")
        split_fraction = state.get("calendar_right_split_fraction")
        if (
            isinstance(split_fraction, bool)
            or not isinstance(split_fraction, (int, float))
            or not (CALENDAR_RIGHT_SPLIT_MIN <= float(split_fraction) <= CALENDAR_RIGHT_SPLIT_MAX)
        ):
            raise UnsupportedDataVersionError("app.json state calendar_right_split_fraction is invalid")

    def _install_config_view(
        self, config: dict[str, Any],
        *,
        signature: tuple[int, int, int, int] | None = None,
    ) -> dict[str, Any]:
        """Install and return one Storage-owned validated Settings snapshot."""
        snapshot = copy.deepcopy(config)
        with self._config_view_lock:
            self._config_view_cache = snapshot
            self._config_view_sig = signature if signature is not None else self.paths._app_manifest_sig()
            self._config_view_checked_at = time.monotonic()
            return snapshot

    def load_config_view(self, *, external_poll_seconds: float = 0.25) -> dict[str, Any]:
        """Return a shared read-only Settings view for CPU-sensitive callers.

        The returned dictionary is owned by Storage and must never be mutated.
        Local writes install a new view immediately. A cheap file-signature poll
        detects writes from another process/Storage instance without reparsing or
        revalidating app.json on every rendered frame.
        """
        self.ensure_first_run_files()
        now_mono = time.monotonic()
        poll_seconds = max(0.0, float(external_poll_seconds))
        with self._config_view_lock:
            cached = self._config_view_cache
            checked_at = self._config_view_checked_at
            cached_sig = self._config_view_sig
            if cached is not None and now_mono - checked_at < poll_seconds:
                return cached

        current_sig = self.paths._app_manifest_sig()
        with self._config_view_lock:
            cached = self._config_view_cache
            if cached is not None and (current_sig is None or current_sig == self._config_view_sig):
                self._config_view_checked_at = now_mono
                return cached

        manifest = self.paths.app_manifest()
        self._validate_current_manifest(manifest)
        return self._install_config_view(manifest["settings"], signature=current_sig)


    def load_config(self) -> dict[str, Any]:
        # Preserve the public isolated-copy contract while reusing the expensive
        # validated source object. A zero poll interval observes external writes
        # on every ordinary load without repeating full schema validation.
        return copy.deepcopy(self.load_config_view(external_poll_seconds=0.0))

    @staticmethod
    def _validated_config_copy(config: dict[str, Any]) -> dict[str, Any]:
        cfg = copy.deepcopy(config or {})
        if cfg.get("schema") != RUNTIME_CONFIG_SCHEMA or cfg.get("data_version") != DATA_FILE_VERSION:
            raise UnsupportedDataVersionError("Settings are not the current Velox settings model")
        validate_exact_mapping_shape(cfg, default_config(), location="settings")
        llm_cfg = cfg.get("llm", {})
        try:
            stall_minutes = float(llm_cfg.get("stall_detection_minutes"))
        except Exception as exc:
            raise UnsupportedDataVersionError(
                "settings.llm.stall_detection_minutes must be a finite number"
            ) from exc
        if (
            isinstance(llm_cfg.get("stall_detection_minutes"), bool)
            or not math.isfinite(stall_minutes)
            or stall_minutes < LLM_ACTIVITY_STALL_WARNING_MINUTES_MIN
        ):
            raise UnsupportedDataVersionError(
                "settings.llm.stall_detection_minutes must be at least "
                f"{LLM_ACTIVITY_STALL_WARNING_MINUTES_MIN:g}"
            )
        llm_cfg["stall_detection_minutes"] = stall_minutes
        profiles = llm_cfg.get("endpoint_profiles")
        try:
            cfg["llm"]["endpoint_profiles"] = [
                normalize_endpoint_profile(profile, location=f"settings.llm.endpoint_profiles[{index}]")
                for index, profile in enumerate(profiles or [])
            ]
        except ValueError as exc:
            raise UnsupportedDataVersionError(str(exc)) from exc
        validate_endpoint_profiles_config(cfg.get("llm"), location="settings.llm")
        try:
            validate_chat_settings(cfg.get("chat"), location="settings.chat")
            validate_agent_settings(cfg.get("agents"), location="settings.agents")
        except ValueError as exc:
            raise UnsupportedDataVersionError(str(exc)) from exc
        web_mode = str(cfg.get("web", {}).get("user_agent_mode") or "desktop_firefox").strip().lower()
        if web_mode not in WEB_USER_AGENT_MODES:
            raise UnsupportedDataVersionError("settings.web.user_agent_mode is invalid")
        cfg["web"]["user_agent_mode"] = web_mode
        timezone_name = str(cfg.get("vault", {}).get("local_timezone") or VAULT_LOCAL_TIMEZONE_DEFAULT).strip()
        try:
            resolve_vault_timezone(timezone_name)
        except ValueError as exc:
            raise UnsupportedDataVersionError(str(exc)) from exc
        cfg["vault"]["local_timezone"] = timezone_name or VAULT_LOCAL_TIMEZONE_DEFAULT
        try:
            cfg["vault"]["divider_fraction"] = normalize_vault_divider_fraction(
                cfg.get("vault", {}).get("divider_fraction")
            )
            cfg["vault"]["google_drive"]["divider_fraction"] = normalize_vault_divider_fraction(
                cfg.get("vault", {}).get("google_drive", {}).get("divider_fraction")
            )
            validate_vault_connector_settings(cfg.get("vault", {}))
        except ValueError as exc:
            raise UnsupportedDataVersionError(str(exc)) from exc
        return cfg

    def write_config(self, config: dict[str, Any], *, preserve_live_fields: bool = False) -> None:
        """Replace settings, optionally preserving fields owned by live UI/services.

        Settings autosave uses ``preserve_live_fields`` so a concurrent
        window-geometry write cannot be replayed away by an older long-lived
        editor draft. Account credentials are stored independently in credentials/.
        Explicit config.write calls retain full replacement semantics.
        """
        self.ensure_first_run_files()
        cfg = self._validated_config_copy(config)
        with DATA_ROOTS.lock_for_path(self.paths.app_json_path):
            # Bypass the short-lived read cache for read/modify/write. A second
            # Storage/AppPaths instance may have updated app.json since this
            # instance last read it, and replaying a cached manifest would erase
            # the other instance's settings or state change.
            manifest = self.paths._read_app_manifest_plain_uncached()
            self._validate_current_manifest(manifest)
            if preserve_live_fields:
                current = manifest["settings"]
                current_ui = current["ui"]
                for geometry_key in ("window_width", "window_height", "window_x", "window_y"):
                    cfg["ui"][geometry_key] = copy.deepcopy(current_ui[geometry_key])
                cfg = self._validated_config_copy(cfg)
            manifest["settings"] = cfg
            self.paths._write_app_manifest_plain(manifest)
        self._install_config_view(cfg)
        self.append_app_log("config.updated", {"keys": sorted(cfg.keys())})

    def update_config(self, updater: Callable[[dict[str, Any]], Any]) -> dict[str, Any]:
        """Atomically mutate the newest settings object and return the saved copy."""
        if not callable(updater):
            raise TypeError("config updater must be callable")
        self.ensure_first_run_files()
        with DATA_ROOTS.lock_for_path(self.paths.app_json_path):
            manifest = self.paths._read_app_manifest_plain_uncached()
            self._validate_current_manifest(manifest)
            cfg = copy.deepcopy(manifest["settings"])
            replacement = updater(cfg)
            if isinstance(replacement, dict):
                cfg = replacement
            cfg = self._validated_config_copy(cfg)
            manifest["settings"] = cfg
            self.paths._write_app_manifest_plain(manifest)
        self._install_config_view(cfg)
        self.append_app_log("config.updated", {"keys": sorted(cfg.keys()), "atomic_patch": True})
        return copy.deepcopy(cfg)

    def load_app_state(self) -> dict[str, Any]:
        self.ensure_first_run_files()
        manifest = self.paths.app_manifest()
        self._validate_current_manifest(manifest)
        state = copy.deepcopy(manifest["state"])
        state["active_panel"] = normalize_active_panel(state.get("active_panel"))
        state["calendar_selected_date"] = normalize_iso_date(
            state.get("calendar_selected_date"), field_name="Calendar selected date",
        )
        state["calendar_chat_width"] = int(clamp(
            int(state.get("calendar_chat_width") or CALENDAR_CHAT_WIDTH_DEFAULT),
            CALENDAR_CHAT_WIDTH_MIN, CALENDAR_CHAT_WIDTH_MAX,
        ))
        state["calendar_right_split_fraction"] = float(clamp(
            float(state.get("calendar_right_split_fraction") or CALENDAR_RIGHT_SPLIT_DEFAULT),
            CALENDAR_RIGHT_SPLIT_MIN, CALENDAR_RIGHT_SPLIT_MAX,
        ))
        # Persist the requested pixel width. The current window supplies its
        # upper limit in chat_layout_for_rect, including after a monitor resize.
        state["chat_list_width"] = max(80, int(state.get("chat_list_width") or CHAT_LIST_WIDTH_DEFAULT))
        state["chat_composer_height"] = int(clamp(
            int(state.get("chat_composer_height") or CHAT_COMPOSER_HEIGHT_DEFAULT),
            80, CHAT_COMPOSER_HEIGHT_MAX,
        ))
        state["calendar_chat_composer_height"] = int(clamp(
            int(state.get("calendar_chat_composer_height") or CALENDAR_CHAT_COMPOSER_HEIGHT_DEFAULT),
            80, CHAT_COMPOSER_HEIGHT_MAX,
        ))
        return state

    @staticmethod
    def _normalized_app_state_payload(state: dict[str, Any] | None) -> dict[str, Any]:
        if state is not None and not isinstance(state, dict):
            raise TypeError("app state update must be a dictionary")
        defaults = default_app_state()
        supplied = copy.deepcopy(state or {})
        unexpected = sorted(str(key) for key in set(supplied).difference(defaults))
        if unexpected:
            raise ValueError("unsupported app state fields: " + ", ".join(unexpected))
        payload = {key: supplied.get(key, value) for key, value in defaults.items()}
        payload["schema"] = APP_STATE_SCHEMA
        payload["active_panel"] = normalize_active_panel(payload.get("active_panel"))
        payload["calendar_selected_date"] = normalize_iso_date(
            payload.get("calendar_selected_date"), field_name="Calendar selected date",
        )
        payload["calendar_chat_width"] = int(clamp(
            int(payload.get("calendar_chat_width") or CALENDAR_CHAT_WIDTH_DEFAULT),
            CALENDAR_CHAT_WIDTH_MIN, CALENDAR_CHAT_WIDTH_MAX,
        ))
        payload["calendar_right_split_fraction"] = float(clamp(
            float(payload.get("calendar_right_split_fraction") or CALENDAR_RIGHT_SPLIT_DEFAULT),
            CALENDAR_RIGHT_SPLIT_MIN, CALENDAR_RIGHT_SPLIT_MAX,
        ))
        payload["chat_list_width"] = max(80, int(payload.get("chat_list_width") or CHAT_LIST_WIDTH_DEFAULT))
        payload["chat_composer_height"] = int(clamp(
            int(payload.get("chat_composer_height") or CHAT_COMPOSER_HEIGHT_DEFAULT),
            80, CHAT_COMPOSER_HEIGHT_MAX,
        ))
        payload["calendar_chat_composer_height"] = int(clamp(
            int(payload.get("calendar_chat_composer_height") or CALENDAR_CHAT_COMPOSER_HEIGHT_DEFAULT),
            80, CHAT_COMPOSER_HEIGHT_MAX,
        ))
        payload["updated_at"] = now_iso()
        validate_exact_mapping_shape(payload, defaults, location="app state")
        return payload

    def write_app_state_and_geometry(
        self, state: dict[str, Any], geometry: dict[str, Any] | None = None,
    ) -> None:
        """Commit state and optional window geometry with one app.json replacement."""
        self.ensure_first_run_files()
        payload = self._normalized_app_state_payload(state)
        requested_geometry = dict(geometry or {})
        with DATA_ROOTS.lock_for_path(self.paths.app_json_path):
            manifest = self.paths._read_app_manifest_plain_uncached()
            self._validate_current_manifest(manifest)
            manifest["state"] = payload
            if requested_geometry:
                config = copy.deepcopy(manifest["settings"])
                ui = config["ui"]
                for key in ("window_width", "window_height", "window_x", "window_y"):
                    value = requested_geometry.get(key)
                    if value is not None:
                        ui[key] = value
                manifest["settings"] = self._validated_config_copy(config)
            self.paths._write_app_manifest_plain(manifest)
        self._install_config_view(manifest["settings"])

    def write_app_state(self, state: dict[str, Any]) -> None:
        self.write_app_state_and_geometry(state, None)

    def record_tool_usage(self, tool_name: str, succeeded: bool, *, chat_id: str | None = None, agent_id: str | None = None) -> None:
        """Atomically persist per-tool totals for the source chat and agent."""
        targets: list[tuple[Path, str]] = []
        if chat_id:
            targets.append((self.paths.chat_json(chat_id), CHAT_SCHEMA))
        if agent_id:
            targets.append((self.paths.agent_json(agent_id), AGENT_SCHEMA))
        for path, schema in targets:
            if not path.is_file():
                continue
            with DATA_ROOTS.lock_for_path(path):
                obj = json.loads(_plain_read_bytes_with_retry(path).decode("utf-8"))
                if schema == CHAT_SCHEMA:
                    validate_chat_record(obj, expected_chat_id=chat_id, location=str(path))
                else:
                    validate_agent_record(obj, expected_agent_id=agent_id, location=str(path))
                obj["stats"] = increment_tool_usage_stats(obj.get("stats"), tool_name, succeeded)
                obj["updated_at"] = now_iso()
                _plain_atomic_write_bytes(path, json_dumps(obj).encode("utf-8"))

    def log_path(self) -> Path:
        return self.paths.log_jsonl_path

    def append_app_log(self, event_type: str, data: dict[str, Any]) -> None:
        # Bound the payload once. The former path recursively compacted the same
        # record a second time while building the message, doubling allocations
        # for frequent streaming/tool diagnostics.
        bounded = compact_log_payload(data)
        append_simple_log(
            self.paths.log_jsonl_path,
            _compact_log_message_from_bounded(event_type, bounded),
            infer_log_level(event_type, bounded),
        )


    def read_log_entries(self, max_level: int = LOG_LEVEL_INFO, limit: int = 500) -> list[dict[str, Any]]:
        return read_simple_logs(self.paths.log_jsonl_path, max_level=max_level, limit=limit)


class SkillStore:
    """Discover, enable, and load reusable instruction packages from ./skills/."""

    def __init__(self, storage: Storage):
        self.storage = storage
        self.paths = storage.paths
        self._list_cache: list[dict[str, Any]] = []
        self._list_cache_at = 0.0
        self._catalog_revision = 0
        self._cache_lock = threading.RLock()

    @property
    def root(self) -> Path:
        root = self.paths.skills_dir().resolve()
        root.mkdir(parents=True, exist_ok=True)
        return root

    @property
    def catalog_revision(self) -> int:
        """Return a stable revision that changes only after an in-app Skill edit."""
        with self._cache_lock:
            return int(self._catalog_revision)

    def _invalidate_cache(self) -> None:
        with self._cache_lock:
            self._list_cache = []
            self._list_cache_at = 0.0
            self._catalog_revision += 1

    @staticmethod
    def validate_skill_name(name: Any) -> str:
        """Return a portable direct-child skill directory name or raise ValueError."""
        raw = str(name or "")
        cleaned = raw.strip()
        if not cleaned:
            raise ValueError("Skill name is required.")
        if len(cleaned) > 120:
            raise ValueError("Skill name must be 120 characters or fewer.")
        if cleaned in {".", ".."} or cleaned.startswith("."):
            raise ValueError("Skill name must be a visible direct child directory name.")
        if cleaned.endswith((".", " ")):
            raise ValueError("Skill name cannot end with a dot or space.")
        if any(separator in cleaned for separator in ("/", "\\")):
            raise ValueError("Skill name cannot contain a path separator.")
        if any(unicodedata.category(ch).startswith("C") for ch in cleaned):
            raise ValueError("Skill name cannot contain control characters.")
        if any(ch in '<>:"|?*' for ch in cleaned):
            raise ValueError("Skill name contains characters that are not valid in a directory name.")
        stem = cleaned.split(".", 1)[0].casefold()
        if stem in {"con", "prn", "aux", "nul", *(f"com{i}" for i in range(1, 10)), *(f"lpt{i}" for i in range(1, 10))}:
            raise ValueError("Skill name is reserved by the operating system.")
        return cleaned

    def create_skill(self, name: Any) -> dict[str, Any]:
        """Create one skill directory and starter skill.md, rejecting duplicates."""
        clean_name = self.validate_skill_name(name)
        root = self.root
        with DATA_ROOTS.lock_for_path(root):
            try:
                children = list(root.iterdir())
            except OSError as exc:
                raise OSError(f"Could not inspect the Skills directory: {exc}") from exc
            duplicate = next((child.name for child in children if child.name.casefold() == clean_name.casefold()), None)
            if duplicate is not None:
                raise FileExistsError(f"A skill named {duplicate!r} already exists.")
            skill_dir = root / clean_name
            skill_dir.mkdir(parents=False, exist_ok=False)
            starter = (
                f"{clean_name} skill instructions for specialized work.\n\n"
                f"# {clean_name}\n\n"
                "Describe when this skill should be loaded, the workflow to follow, and how to use any supporting files in this directory.\n"
            )
            try:
                atomic_write_text(skill_dir / SKILL_FILE_NAME, starter)
            except Exception:
                shutil.rmtree(skill_dir, ignore_errors=True)
                raise
        self._invalidate_cache()
        self.storage.append_app_log("skill.created", {"name": clean_name, "path": str(skill_dir)})
        return next(
            row for row in self.list_skills(include_disabled=True, refresh=True)
            if str(row.get("name") or "").casefold() == clean_name.casefold()
        )

    def read_skill_text(self, name: str) -> str:
        """Return the complete skill.md text for the in-app editor."""
        _row, directory = self._resolve_skill(name)
        path = directory / SKILL_FILE_NAME
        if path.is_symlink() or not path.is_file():
            raise FileNotFoundError(f"skill.md is missing or is not a regular file: {path}")
        return file_read_text(path, encoding="utf-8", errors="replace")

    def save_skill_text(self, name: str, text: Any) -> dict[str, Any]:
        """Atomically replace the complete skill.md text and refresh discovery."""
        row, directory = self._resolve_skill(name)
        content = str(text or "")
        if not any(line.strip() for line in content.splitlines()):
            raise ValueError("skill.md must contain at least one non-empty line.")
        path = directory / SKILL_FILE_NAME
        if path.is_symlink() or not path.is_file():
            raise FileNotFoundError(f"skill.md is missing or is not a regular file: {path}")
        atomic_write_text(path, content)
        self._invalidate_cache()
        self.storage.append_app_log(
            "skill.updated", {"name": str(row.get("name") or name), "characters": len(content)},
        )
        return next(
            item for item in self.list_skills(include_disabled=True, refresh=True)
            if str(item.get("name") or "").casefold() == str(row.get("name") or "").casefold()
        )

    @staticmethod
    def _description_from_text(text: str) -> str:
        """Return one concise, control-character-free catalog description."""
        for raw_line in str(text or "").splitlines():
            line = raw_line.strip()
            if not line:
                continue
            line = re.sub(r"^#{1,6}\s+", "", line).strip()
            line = "".join(
                ch if not unicodedata.category(ch).startswith("C") else " "
                for ch in line
            )
            return re.sub(r"\s+", " ", line).strip()[:SKILL_DESCRIPTION_MAX_CHARS]
        return ""

    def _inventory(self, skill_dir: Path) -> tuple[list[str], bool]:
        """Return Settings-bounded package-relative regular files without following links."""
        files: list[str] = []
        truncated = False
        limit = tool_setting_int(self.storage.load_config(), "skill_supporting_file_limit")
        skill_root = Path(skill_dir).resolve()
        try:
            for current_root, dir_names, file_names in os.walk(skill_root, followlinks=False):
                safe_dirs: list[str] = []
                for name in sorted(dir_names, key=str.casefold):
                    if name.startswith("."):
                        continue
                    candidate = Path(current_root) / name
                    try:
                        if candidate.is_symlink():
                            continue
                        candidate.resolve().relative_to(skill_root)
                    except (OSError, ValueError):
                        continue
                    safe_dirs.append(name)
                dir_names[:] = safe_dirs
                for file_name in sorted(file_names, key=str.casefold):
                    if file_name == SKILL_MODE_FILE_NAME:
                        continue
                    path = Path(current_root) / file_name
                    try:
                        if path.is_symlink() or not path.is_file():
                            continue
                        resolved = path.resolve()
                        resolved.relative_to(skill_root)
                        rel = resolved.relative_to(skill_root).as_posix()
                    except (OSError, ValueError):
                        continue
                    files.append(rel)
                    if len(files) >= limit:
                        truncated = True
                        return files, truncated
        except OSError:
            pass
        return files, truncated

    def _scan(self) -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        seen_names: set[str] = set()
        root = self.root
        try:
            children = sorted(root.iterdir(), key=lambda path: path.name.casefold())
        except OSError:
            return rows
        for child in children:
            if child.name.startswith("."):
                continue
            try:
                if child.is_symlink():
                    continue
            except OSError:
                continue
            if any(unicodedata.category(ch).startswith("C") for ch in child.name):
                continue
            folded_name = child.name.casefold()
            if folded_name in seen_names:
                # Loading is case-insensitive so two such names would be
                # ambiguous on case-sensitive filesystems. Keep the first
                # deterministic entry and ignore the duplicate.
                continue
            try:
                resolved = child.resolve()
                resolved.relative_to(root)
                if not resolved.is_dir():
                    continue
            except Exception:
                continue
            skill_file = resolved / SKILL_FILE_NAME
            if not skill_file.is_file() or skill_file.is_symlink():
                continue
            seen_names.add(folded_name)
            try:
                prefix, _truncated = file_read_text_prefix(
                    skill_file, 16_384, encoding="utf-8", errors="replace",
                )
            except Exception:
                prefix = ""
            files, files_truncated = self._inventory(resolved)
            mode = self._read_mode(resolved)
            rows.append({
                "name": child.name,
                "description": self._description_from_text(prefix) or "No description provided.",
                "mode": mode,
                "enabled": mode != "disable",
                "directory": str(resolved),
                "skill_file": str(skill_file),
                "file_count": len(files),
                "file_list_truncated": files_truncated,
            })
        return rows

    def list_skills(self, *, include_disabled: bool = True, refresh: bool = False) -> list[dict[str, Any]]:
        now = time.monotonic()
        with self._cache_lock:
            if refresh or not self._list_cache or now - self._list_cache_at >= 1.0:
                self._list_cache = self._scan()
                self._list_cache_at = now
            rows = copy.deepcopy(self._list_cache)
        if include_disabled:
            return rows
        return [row for row in rows if bool(row.get("enabled"))]

    def _resolve_skill(self, name: str) -> tuple[dict[str, Any], Path]:
        requested = str(name or "").strip()
        if not requested:
            raise ValueError("skill name is required")
        if requested in {".", ".."} or any(separator in requested for separator in ("/", "\\")):
            raise ValueError("skill name must be one direct child directory name")
        matches = [
            row for row in self.list_skills(include_disabled=True, refresh=True)
            if str(row.get("name") or "").casefold() == requested.casefold()
        ]
        if not matches:
            available = ", ".join(str(row.get("name") or "") for row in self.list_skills(include_disabled=False))
            suffix = f" Available enabled skills: {available}." if available else " No enabled skills are available."
            raise FileNotFoundError(f"Skill not found: {requested}.{suffix}")
        row = matches[0]
        directory = Path(str(row.get("directory") or "")).resolve()
        directory.relative_to(self.root)
        return row, directory

    @staticmethod
    def _read_mode(directory: Path) -> str:
        path = directory / SKILL_MODE_FILE_NAME
        if path.is_symlink():
            raise ValueError(f"Skill mode must not be a symbolic link: {path}")
        try:
            raw = json.loads(path.read_text(encoding="utf-8"))
        except FileNotFoundError:
            return "optional"
        if not isinstance(raw, dict) or set(raw) != {"schema", "mode"} or raw.get("schema") != SKILL_MODE_SCHEMA:
            raise UnsupportedDataVersionError(f"Unsupported Skill mode schema in {path}")
        if raw.get("mode") not in SKILL_MODES:
            raise ValueError(f"Invalid Skill mode in {path}")
        return raw["mode"]

    def set_mode(self, name: str, mode: str) -> dict[str, Any]:
        """Persist Disable/Optional/Always for new contexts without rewriting old prefixes."""
        if not isinstance(mode, str) or mode not in SKILL_MODES:
            raise ValueError("Skill mode must be disable, optional or always")
        row, directory = self._resolve_skill(name)
        path = directory / SKILL_MODE_FILE_NAME
        with DATA_ROOTS.lock_for_path(path):
            if path.is_symlink():
                raise ValueError("Skill mode must not be a symbolic link")
            atomic_write_text(path, json.dumps({"schema": SKILL_MODE_SCHEMA, "mode": mode}, sort_keys=True))
        self._invalidate_cache()
        self.storage.append_app_log("skill.mode_changed", {"name": row["name"], "mode": mode})
        return next(item for item in self.list_skills(refresh=True)
                    if item["name"].casefold() == row["name"].casefold())

    def load_skill(self, name: str) -> dict[str, Any]:
        row, directory = self._resolve_skill(name)
        if not bool(row.get("enabled")):
            raise PermissionError(f"Skill is disabled globally in Settings: {row.get('name')}")
        skill_file = directory / SKILL_FILE_NAME
        try:
            if skill_file.is_symlink():
                raise ValueError(f"skill.md must be a regular file inside the skill directory: {skill_file}")
            resolved_skill_file = skill_file.resolve()
            resolved_skill_file.relative_to(directory)
            if not resolved_skill_file.is_file():
                raise FileNotFoundError(str(resolved_skill_file))
        except OSError as exc:
            raise FileNotFoundError(str(skill_file)) from exc
        instructions, truncated = file_read_text_prefix(
            resolved_skill_file,
            tool_setting_int(self.storage.load_config(), "skill_markdown_max_chars"),
            encoding="utf-8",
            errors="replace",
        )
        files, files_truncated = self._inventory(directory)
        supporting_files = [relative for relative in files if relative != SKILL_FILE_NAME]
        return {
            "name": str(row.get("name") or directory.name),
            "description": str(row.get("description") or ""),
            "directory": str(directory),
            "skill_file": str(resolved_skill_file),
            "instructions": instructions,
            "instructions_truncated": bool(truncated),
            "supporting_files": supporting_files,
            "supporting_files_truncated": bool(files_truncated),
        }


# =============================================================================
# Chat files and persistent chat data
# =============================================================================


class _StoragePathBound:
    """Share the immutable Storage/AppPaths binding used by operational services."""

    def __init__(self, storage: Storage) -> None:
        self.storage = storage
        self.paths = storage.paths


@dataclass(frozen=True)
class ExpertModeContext:
    """Strict execution identity for one Chat or Agent Checklist state."""

    owner_kind: str
    chat_id: str
    agent_id: str = ""
    task_run_id: int = 0

    @property
    def owner_id(self) -> str:
        return self.agent_id if self.owner_kind == "agent" else self.chat_id


def expert_mode_context_from_tool(storage: "Storage", ctx: "ToolContext") -> ExpertModeContext:
    chat_id = str(ctx.chat_id or "").strip()
    agent_id = str(ctx.agent_id or "").strip()
    if agent_id:
        task_run_id = int(ctx.agent_task_run_id or 0)
        if not chat_id:
            raise ValueError("Agent Checklist requires its source chat identity")
        if task_run_id < 1:
            raise ValueError("Agent Checklist requires a positive Task Run ID")
        path = storage.paths.agent_json(agent_id)
        if not path.is_file():
            raise ValueError("Agent Checklist requires an existing current Agent Task")
        agent = validate_agent_record(read_json(path), expected_agent_id=agent_id, location=str(path))
        if str(agent.get("source_chat_id") or "") != chat_id:
            raise ValueError("Agent Checklist source Chat does not match the current Agent Task")
        if int(agent.get("task_run_id") or 0) != task_run_id:
            raise ValueError("Agent Checklist Task Run ID does not match the current execution")
        return ExpertModeContext("agent", chat_id, agent_id, task_run_id)
    if not chat_id:
        raise ValueError("Checklist requires an active Chat or Agent Task")
    chat_path = storage.paths.chat_json(chat_id)
    if not chat_path.is_file():
        raise ValueError("Checklist requires an existing current Chat Task")
    validate_chat_record(read_json(chat_path), expected_chat_id=chat_id, location=str(chat_path))
    return ExpertModeContext("chat", chat_id)


def expert_mode_context_for_chat(chat_id: Any) -> ExpertModeContext:
    resolved = str(chat_id or "").strip()
    if not resolved:
        raise ValueError("chat_id is required")
    return ExpertModeContext("chat", resolved)


def expert_mode_context_for_agent(agent: dict[str, Any]) -> ExpertModeContext:
    agent_id = str((agent or {}).get("agent_id") or "").strip()
    chat_id = str((agent or {}).get("source_chat_id") or "").strip()
    task_run_id = int((agent or {}).get("task_run_id") or 0)
    if not agent_id or not chat_id or task_run_id < 1:
        raise ValueError("Agent record does not contain a valid Checklist execution identity")
    return ExpertModeContext("agent", chat_id, agent_id, task_run_id)


class ExpertModeStateError(ValueError):
    pass


class ExpertModeStore:
    """Persist task progress and provide the execution adapter for checklist review."""

    _TOP_LEVEL_KEYS = frozenset({
        "schema", "owner_kind", "chat_id", "agent_id", "task_run_id",
        "status", "requirements", "created_at", "updated_at", "exited_at",
        "continuation_count", "last_continuation_key",
    })
    _REQUIREMENT_KEYS = frozenset({
        "id", "text", "status", "summary", "updated_at",
    })
    _UPDATE_KEYS = frozenset({"requirement_id", "status", "summary"})

    def __init__(self, storage: "Storage", context: ExpertModeContext):
        self.storage = storage
        self.context = context
        if context.owner_kind == "agent":
            self.path = (
                storage.paths.agent_dir(context.agent_id)
                / f"agent_{context.task_run_id}_expert_mode.json"
            )
        elif context.owner_kind == "chat":
            self.path = storage.paths.chat_dir(context.chat_id) / EXPERT_MODE_ACTIVE_CHAT_FILENAME
        else:
            raise ExpertModeStateError(f"Unsupported Checklist owner kind: {context.owner_kind}")

    @classmethod
    def for_chat(cls, storage: "Storage", chat_id: Any) -> "ExpertModeStore":
        return cls(storage, expert_mode_context_for_chat(chat_id))

    @classmethod
    def for_agent(cls, storage: "Storage", agent: dict[str, Any]) -> "ExpertModeStore":
        return cls(storage, expert_mode_context_for_agent(agent))

    @staticmethod
    def _clean_requirement_text(value: Any) -> str:
        if not isinstance(value, str):
            raise ExpertModeStateError("Every Checklist requirement must be a string")
        text = " ".join(value.strip().split())
        if not text:
            raise ExpertModeStateError("Checklist requirements cannot be empty")
        if len(text) > EXPERT_MODE_REQUIREMENT_MAX_CHARS:
            raise ExpertModeStateError(
                f"Each Checklist requirement is limited to {EXPERT_MODE_REQUIREMENT_MAX_CHARS:,} characters"
            )
        return text

    @staticmethod
    def _clean_update_summary(value: Any) -> str:
        if not isinstance(value, str):
            raise ExpertModeStateError("Each Checklist update summary must be a string")
        text = " ".join(value.strip().split())
        if not text:
            raise ExpertModeStateError(
                "Each Checklist update needs one concise sentence describing progress or the completed result"
            )
        if len(text) > EXPERT_MODE_SUMMARY_MAX_CHARS:
            raise ExpertModeStateError(
                f"Each Checklist update summary is limited to {EXPERT_MODE_SUMMARY_MAX_CHARS:,} characters"
            )
        return text

    @staticmethod
    def _normalize_requirement_id(value: Any) -> str:
        requirement_id = str(value or "").strip().upper()
        if not re.fullmatch(r"R[1-9][0-9]*", requirement_id):
            raise ExpertModeStateError(f"Invalid Checklist requirement ID: {value}")
        return requirement_id

    @classmethod
    def _normalize_requirements(cls, values: Any) -> list[str]:
        if not isinstance(values, (list, tuple)):
            raise ExpertModeStateError("requirements must be a non-empty array of strings")
        if not 1 <= len(values) <= EXPERT_MODE_MAX_REQUIREMENTS:
            raise ExpertModeStateError(
                f"Checklist requires between 1 and {EXPERT_MODE_MAX_REQUIREMENTS} requirements"
            )
        output: list[str] = []
        seen: set[str] = set()
        for value in values:
            text = cls._clean_requirement_text(value)
            folded = text.casefold()
            if folded in seen:
                raise ExpertModeStateError(f"Duplicate Checklist requirement: {text}")
            seen.add(folded)
            output.append(text)
        return output

    @classmethod
    def _normalize_updates(cls, values: Any) -> list[dict[str, str]]:
        if not isinstance(values, (list, tuple)) or not values:
            raise ExpertModeStateError(
                "updates must contain at least one {requirement_id, status, summary} object"
            )
        if len(values) > EXPERT_MODE_MAX_REQUIREMENTS:
            raise ExpertModeStateError(
                f"One Checklist update call supports at most {EXPERT_MODE_MAX_REQUIREMENTS} requirements"
            )
        output: list[dict[str, str]] = []
        seen: set[str] = set()
        for raw in values:
            if not isinstance(raw, dict) or frozenset(raw.keys()) != cls._UPDATE_KEYS:
                raise ExpertModeStateError(
                    "Every Checklist update must be exactly {requirement_id, status, summary}"
                )
            requirement_id = cls._normalize_requirement_id(raw.get("requirement_id"))
            if requirement_id in seen:
                raise ExpertModeStateError(f"Duplicate Checklist update for {requirement_id}")
            status = str(raw.get("status") or "").strip().lower()
            if status not in {EXPERT_MODE_REQUIREMENT_INCOMPLETE, EXPERT_MODE_REQUIREMENT_DONE}:
                raise ExpertModeStateError("Requirement status must be exactly incomplete or done")
            summary = cls._clean_update_summary(raw.get("summary"))
            seen.add(requirement_id)
            output.append({
                "requirement_id": requirement_id,
                "status": status,
                "summary": summary,
            })
        return output

    def _validate(self, value: Any) -> dict[str, Any]:
        if not isinstance(value, dict):
            raise ExpertModeStateError("Checklist state must be a JSON object")
        keys = frozenset(value.keys())
        if keys != self._TOP_LEVEL_KEYS:
            missing = sorted(self._TOP_LEVEL_KEYS - keys)
            extra = sorted(keys - self._TOP_LEVEL_KEYS)
            details = []
            if missing:
                details.append("missing " + ", ".join(missing))
            if extra:
                details.append("unexpected " + ", ".join(extra))
            raise ExpertModeStateError("Invalid strict Checklist state: " + "; ".join(details))
        if value.get("schema") != EXPERT_MODE_SCHEMA:
            raise ExpertModeStateError(
                f"Checklist state schema must be {EXPERT_MODE_SCHEMA}; migration is unsupported"
            )
        context = self.context
        if str(value.get("owner_kind") or "") != context.owner_kind:
            raise ExpertModeStateError("Checklist owner kind does not match this Task")
        if str(value.get("chat_id") or "") != context.chat_id:
            raise ExpertModeStateError("Checklist source Chat does not match this Task")
        if str(value.get("agent_id") or "") != context.agent_id:
            raise ExpertModeStateError("Checklist Agent does not match this Task")
        if int(value.get("task_run_id") or 0) != int(context.task_run_id):
            raise ExpertModeStateError("Checklist Task Run ID does not match this Task")
        status = str(value.get("status") or "")
        if status not in {EXPERT_MODE_STATUS_ACTIVE, EXPERT_MODE_STATUS_SUCCEEDED}:
            raise ExpertModeStateError("Checklist state has an invalid status")
        requirements = value.get("requirements")
        if not isinstance(requirements, list) or not 1 <= len(requirements) <= EXPERT_MODE_MAX_REQUIREMENTS:
            raise ExpertModeStateError("Checklist state has an invalid requirements array")
        normalized_requirements: list[dict[str, Any]] = []
        for index, raw in enumerate(requirements, 1):
            if not isinstance(raw, dict) or frozenset(raw.keys()) != self._REQUIREMENT_KEYS:
                raise ExpertModeStateError("Every Checklist requirement must use the current requirement shape")
            requirement_id = str(raw.get("id") or "")
            if requirement_id != f"R{index}":
                raise ExpertModeStateError("Checklist requirement IDs and order must remain stable")
            requirement_text = self._clean_requirement_text(raw.get("text"))
            requirement_status = str(raw.get("status") or "")
            if requirement_status not in {
                EXPERT_MODE_REQUIREMENT_INCOMPLETE,
                EXPERT_MODE_REQUIREMENT_DONE,
            }:
                raise ExpertModeStateError(f"{requirement_id} has an invalid requirement status")
            summary = raw.get("summary")
            requirement_updated_at = raw.get("updated_at")
            if not isinstance(summary, str):
                raise ExpertModeStateError(f"{requirement_id} summary must be a string")
            if requirement_status == EXPERT_MODE_REQUIREMENT_INCOMPLETE:
                if summary:
                    normalized_summary = self._clean_update_summary(summary)
                    if not isinstance(requirement_updated_at, str) or not requirement_updated_at.strip():
                        raise ExpertModeStateError(
                            f"{requirement_id} has a progress note without an update timestamp"
                        )
                else:
                    normalized_summary = ""
                    if requirement_updated_at is not None:
                        raise ExpertModeStateError(
                            f"{requirement_id} has no progress note but contains an update timestamp"
                        )
            else:
                normalized_summary = self._clean_update_summary(summary)
                if not isinstance(requirement_updated_at, str) or not requirement_updated_at.strip():
                    raise ExpertModeStateError(
                        f"{requirement_id} is done without an update timestamp"
                    )
            normalized_requirements.append({
                "id": requirement_id,
                "text": requirement_text,
                "status": requirement_status,
                "summary": normalized_summary,
                "updated_at": requirement_updated_at,
            })
        for key in ("created_at", "updated_at"):
            if not isinstance(value.get(key), str) or not str(value.get(key)).strip():
                raise ExpertModeStateError(f"Checklist {key} must be a timestamp string")
        exited_at = value.get("exited_at")
        if status == EXPERT_MODE_STATUS_ACTIVE:
            if exited_at is not None:
                raise ExpertModeStateError("Active Checklist cannot contain an exit timestamp")
        else:
            if not isinstance(exited_at, str) or not exited_at.strip():
                raise ExpertModeStateError("Succeeded Checklist state requires an exit timestamp")
            incomplete = [
                item["id"] for item in normalized_requirements
                if item["status"] == EXPERT_MODE_REQUIREMENT_INCOMPLETE
            ]
            if incomplete:
                raise ExpertModeStateError("Succeeded Checklist state contains incomplete requirements")
        continuation_count = value.get("continuation_count")
        if isinstance(continuation_count, bool) or not isinstance(continuation_count, int) or continuation_count < 0:
            raise ExpertModeStateError("Checklist continuation_count must be a non-negative integer")
        if not isinstance(value.get("last_continuation_key"), str):
            raise ExpertModeStateError("Checklist last_continuation_key must be a string")
        result = copy.deepcopy(value)
        result["requirements"] = normalized_requirements
        return result

    def _load_locked(self, *, active_only: bool = False) -> dict[str, Any] | None:
        try:
            raw = read_json(self.path, None)
        except FileNotFoundError:
            raw = None
        if raw is None:
            return None
        state = self._validate(raw)
        if active_only and state["status"] != EXPERT_MODE_STATUS_ACTIVE:
            return None
        return state

    def load(self, *, active_only: bool = False) -> dict[str, Any] | None:
        with DATA_ROOTS.lock_for_path(self.path):
            return self._load_locked(active_only=active_only)

    def _write_locked(self, state: dict[str, Any]) -> dict[str, Any]:
        validated = self._validate(state)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        atomic_write_json(self.path, validated)
        return copy.deepcopy(validated)

    def _archive_terminal_state_locked(self, state: dict[str, Any]) -> Path | None:
        if state.get("status") == EXPERT_MODE_STATUS_ACTIVE or not self.path.exists():
            return None
        stamp = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
        stem = "chat" if self.context.owner_kind == "chat" else f"agent_{self.context.task_run_id}"
        target = self.path.with_name(f"retired_{stem}_expert_mode_{stamp}.json")
        suffix = 2
        while target.exists():
            target = self.path.with_name(f"retired_{stem}_expert_mode_{stamp}_{suffix}.json")
            suffix += 1
        os.replace(self.path, target)
        return target

    def _retired_history_paths_locked(self) -> list[Path]:
        stem = "chat" if self.context.owner_kind == "chat" else f"agent_{self.context.task_run_id}"
        return sorted(self.path.parent.glob(f"retired_{stem}_expert_mode_*.json"))

    def archive_succeeded(self) -> str:
        """Move the visible succeeded checklist into history and clear the active card."""
        with DATA_ROOTS.lock_for_path(self.path):
            state = self._load_locked()
            if not state or state.get("status") != EXPERT_MODE_STATUS_SUCCEEDED:
                return ""
            target = self._archive_terminal_state_locked(state)
            return str(target or "")

    def history(self, *, include_current: bool = True) -> list[dict[str, Any]]:
        """Return the current checklist plus prior reports, newest first."""
        with DATA_ROOTS.lock_for_path(self.path):
            current_entries: list[dict[str, Any]] = []
            if include_current:
                current = self._load_locked()
                if current is not None:
                    current_entries.append({
                        "key": "current:" + self.path.name,
                        "current": True,
                        "path": str(self.path),
                        "state": current,
                    })
            retired_entries: list[dict[str, Any]] = []
            for retired_path in self._retired_history_paths_locked():
                raw = read_json(retired_path, None)
                if raw is None:
                    continue
                state = self._validate(raw)
                retired_entries.append({
                    "key": "history:" + retired_path.name,
                    "current": False,
                    "path": str(retired_path),
                    "state": state,
                })
            retired_entries.sort(
                key=lambda entry: str(
                    entry["state"].get("exited_at")
                    or entry["state"].get("updated_at")
                    or entry["state"].get("created_at")
                    or ""
                ),
                reverse=True,
            )
            return [*current_entries, *retired_entries]

    def enter(self, requirements: Any) -> dict[str, Any]:
        texts = self._normalize_requirements(requirements)
        with DATA_ROOTS.lock_for_path(self.path):
            existing = self._load_locked()
            if existing and existing.get("status") == EXPERT_MODE_STATUS_ACTIVE:
                raise ExpertModeStateError(
                    "Checklist is already active. Read its status and continue the existing checklist"
                )
            if existing:
                self._archive_terminal_state_locked(existing)
            now = now_iso()
            context = self.context
            state = {
                "schema": EXPERT_MODE_SCHEMA,
                "owner_kind": context.owner_kind,
                "chat_id": context.chat_id,
                "agent_id": context.agent_id,
                "task_run_id": int(context.task_run_id),
                "status": EXPERT_MODE_STATUS_ACTIVE,
                "requirements": [
                    {
                        "id": f"R{index}",
                        "text": requirement_text,
                        "status": EXPERT_MODE_REQUIREMENT_INCOMPLETE,
                        "summary": "",
                        "updated_at": None,
                    }
                    for index, requirement_text in enumerate(texts, 1)
                ],
                "created_at": now,
                "updated_at": now,
                "exited_at": None,
                "continuation_count": 0,
                "last_continuation_key": "",
            }
            return self._write_locked(state)

    def update(self, updates: Any) -> dict[str, Any]:
        normalized = self._normalize_updates(updates)
        with DATA_ROOTS.lock_for_path(self.path):
            state = self._load_locked()
            if not state or state.get("status") != EXPERT_MODE_STATUS_ACTIVE:
                raise ExpertModeStateError("Checklist is not active for this Task")
            known = {item["id"] for item in state["requirements"]}
            unknown = [row["requirement_id"] for row in normalized if row["requirement_id"] not in known]
            if unknown:
                raise ExpertModeStateError("Unknown Checklist requirement ID(s): " + ", ".join(unknown))
            now = now_iso()
            changed = False
            updates_by_id = {row["requirement_id"]: row for row in normalized}
            for item in state["requirements"]:
                update = updates_by_id.get(item["id"])
                if update is None:
                    continue
                if item["status"] == EXPERT_MODE_REQUIREMENT_DONE:
                    if update["status"] == EXPERT_MODE_REQUIREMENT_DONE:
                        if item["summary"] != update["summary"]:
                            raise ExpertModeStateError(
                                f"{item['id']} is already done; reopen it as incomplete before replacing its validation summary"
                            )
                        continue
                    # Later concrete test, runtime, integration, or visual evidence may
                    # invalidate an earlier done result. The model supplies the concise
                    # contradiction/progress note; Velox preserves stable identity and
                    # returns the requirement to the ordinary persistence path.
                    item["status"] = EXPERT_MODE_REQUIREMENT_INCOMPLETE
                    item["summary"] = update["summary"]
                    item["updated_at"] = now
                    changed = True
                    continue
                if item["status"] == update["status"] and item["summary"] == update["summary"]:
                    continue
                item["status"] = update["status"]
                item["summary"] = update["summary"]
                item["updated_at"] = now
                changed = True
            if changed:
                state["updated_at"] = now
                state["last_continuation_key"] = ""
                return self._write_locked(state)
            return copy.deepcopy(state)

    @staticmethod
    def _concise(value: Any, width: int = 520) -> str:
        text = " ".join(str(value or "").split())
        if len(text) <= width:
            return text
        return textwrap.shorten(text, width=width, placeholder=" ...")

    @classmethod
    def incomplete_lines(cls, state: dict[str, Any] | None) -> list[str]:
        lines: list[str] = []
        for row in cls.rows(state):
            if not row["incomplete"]:
                continue
            lines.append(f"- {row['id']}: {cls._concise(row['requirement'])}")
            if row["summary"]:
                lines.append(f"  Progress: {cls._concise(row['summary'])}")
        return lines

    def exit(self) -> dict[str, Any]:
        with DATA_ROOTS.lock_for_path(self.path):
            state = self._load_locked()
            if not state or state.get("status") != EXPERT_MODE_STATUS_ACTIVE:
                raise ExpertModeStateError("Checklist is not active for this Task")
            incomplete = [
                item for item in state["requirements"]
                if item["status"] == EXPERT_MODE_REQUIREMENT_INCOMPLETE
            ]
            if incomplete:
                lines = self.incomplete_lines(state)
                raise ExpertModeStateError(
                    f"Checklist cannot exit while {len(incomplete)} requirement(s) remain incomplete:\n"
                    + "\n".join(lines)
                    + "\nContinue execution now. Do not ask permission, summarize, or produce a final report while requirements remain incomplete."
                )
            now = now_iso()
            state["status"] = EXPERT_MODE_STATUS_SUCCEEDED
            state["updated_at"] = now
            state["exited_at"] = now
            state["last_continuation_key"] = ""
            return self._write_locked(state)

    def claim_continuation(self, key: Any) -> tuple[dict[str, Any], bool]:
        normalized = str(key or "").strip()
        if not normalized:
            raise ExpertModeStateError("Checklist continuation key is required")
        canonical = _canonical_checklists(self)
        if canonical is not None:
            manager, owner = canonical
            return manager.claim_execution_continuation(owner, normalized)
        with DATA_ROOTS.lock_for_path(self.path):
            state = self._load_locked()
            if not state or state.get("status") != EXPERT_MODE_STATUS_ACTIVE:
                raise ExpertModeStateError("Checklist is not active for this Task")
            if state.get("last_continuation_key") == normalized:
                return copy.deepcopy(state), False
            state["last_continuation_key"] = normalized
            state["continuation_count"] = int(state.get("continuation_count") or 0) + 1
            state["updated_at"] = now_iso()
            return self._write_locked(state), True

    @staticmethod
    def rows(state: dict[str, Any] | None) -> list[dict[str, Any]]:
        output: list[dict[str, Any]] = []
        for item in ((state or {}).get("requirements") or []):
            if not isinstance(item, dict):
                continue
            requirement_status = str(item.get("status") or EXPERT_MODE_REQUIREMENT_INCOMPLETE)
            output.append({
                "id": str(item.get("id") or ""),
                "requirement": str(item.get("text") or ""),
                "requirement_status": requirement_status,
                "incomplete": requirement_status == EXPERT_MODE_REQUIREMENT_INCOMPLETE,
                "done": requirement_status == EXPERT_MODE_REQUIREMENT_DONE,
                "status": "✓" if requirement_status == EXPERT_MODE_REQUIREMENT_DONE else "",
                "summary": str(item.get("summary") or ""),
            })
        return output

    @classmethod
    def first_incomplete(cls, state: dict[str, Any] | None) -> dict[str, Any] | None:
        for row in cls.rows(state):
            if row["incomplete"]:
                return row
        return None

    @classmethod
    def format(cls, state: dict[str, Any] | None, *, include_instruction: bool = False) -> str:
        if not state:
            return "Checklist is not active for this Task."
        rows = cls.rows(state)
        done_count = sum(1 for row in rows if row["done"])
        lines = [
            f"CHECKLISTS - {str(state.get('status') or '').upper()} - "
            f"{done_count}/{len(rows)} DONE"
        ]
        for row in rows:
            marker = row["status"] or "☐"
            lines.append(f"{marker} {row['id']}  {row['requirement']}")
            if row["summary"]:
                label = "Done" if row["done"] else "Progress"
                lines.append(f"  {label}: {row['summary']}")
        if include_instruction and state.get("status") == EXPERT_MODE_STATUS_ACTIVE:
            lines.append("")
            if cls.first_incomplete(state):
                lines.extend([
                    "Checklist is a persistent progress checklist. Keep taking concrete actions while any requirement is incomplete.",
                    "Missing, unfinished, partially implemented, unverified, difficult, or currently blocked work remains incomplete work.",
                    "Use expert_mode_requirement_update after meaningful milestones and when materially advancing incomplete work.",
                    "For behavior, exercise the intended production path; for visual work, inspect the produced pixels.",
                    "A done summary states the strongest observed successful validation. Reopen only when later concrete evidence contradicts it.",
                    "Before expert_mode_exit, reconcile every done summary against the latest tool, runtime, test, and visual evidence.",
                    "When every requirement is done, call expert_mode_exit.",
                ])
            else:
                lines.append("Every requirement is done. Call expert_mode_exit now, then provide the final answer.")
        return "\n".join(lines)

    @classmethod
    def progress_snapshot(cls, state: dict[str, Any] | None) -> str:
        rows = cls.rows(state)
        done_count = sum(1 for row in rows if row["done"])
        lines = ["CURRENT CHECKLISTS PROGRESS", f"{done_count}/{len(rows)} requirements done."]
        incomplete_lines = cls.incomplete_lines(state)
        if incomplete_lines:
            lines.append("Incomplete requirements:")
            lines.extend(incomplete_lines)
        else:
            lines.append("All requirements are done.")
        return "\n".join(lines)

    @classmethod
    def task_memory_content(cls, task_facts: Any, state: dict[str, Any] | None = None) -> str:
        sections = [str(task_facts or "").strip()]
        if state and state.get("status") == EXPERT_MODE_STATUS_ACTIVE:
            sections.append(cls.progress_snapshot(state))
        body = "\n\n".join(section for section in sections if section)
        return TASK_MEMORY_HEADER + ("\n\n" + body if body else "")

    def continuation_prompt(self, state: dict[str, Any] | None = None) -> str:
        current = state if state is not None else self.load(active_only=True)
        if not current:
            raise ExpertModeStateError("Checklist is not active for this Task")
        rows = self.rows(current)
        done_count = sum(1 for row in rows if row["done"])
        incomplete = [row for row in rows if row["incomplete"]]
        lines = ["CHECKLISTS - CONTINUE", ""]
        if incomplete:
            lines.append(
                f"{done_count}/{len(rows)} requirements are done. The following requirements remain incomplete:"
            )
            lines.extend(self.incomplete_lines(current))
            lines.extend([
                "",
                "Continue execution now. Choose the next actionable incomplete requirement and take a concrete action. "
                "If one path is currently blocked, investigate or work around it, or continue another incomplete requirement. "
                "Update Checklist as meaningful progress is made. Do not produce a final report while requirements remain incomplete.",
            ])
        else:
            lines.extend([
                f"{done_count}/{len(rows)} requirements are done.",
                "Call expert_mode_exit now, then provide the final answer.",
            ])
        return "\n".join(lines)

def is_expert_mode_owned_filename(path_or_name: Any) -> bool:
    name = Path(str(path_or_name or "")).name
    return bool(
        name.lower() == EXPERT_MODE_ACTIVE_CHAT_FILENAME
        or EXPERT_MODE_AGENT_FILENAME_RE.fullmatch(name)
        or EXPERT_MODE_RETIRED_FILENAME_RE.fullmatch(name)
    )

class ChatStore:
    def __init__(self, storage: Storage):
        self.storage = storage
        self.paths = storage.paths
        self._list_cache: tuple[float, tuple[tuple[str, int, int], ...], list[dict[str, Any]]] | None = None
        self._turn_revisions: dict[str, int] = {}
        self._turn_change_history: dict[str, collections.deque[tuple[int, int]]] = {}
        self._chat_meta_cache: dict[str, tuple[int, int, dict[str, Any]]] = {}
        self._chat_meta_checked_at: dict[str, float] = {}
        # The active transcript is cached in memory and streaming turns are
        # patched in place. The prior implementation reparsed and atomically
        # rewrote the complete turns.jsonl file for every 60 ms UI update.
        self._turn_cache_lock = threading.RLock()
        self._turn_cache: dict[str, dict[str, Any]] = {}
        self._stream_checkpoint_state: dict[tuple[str, str], tuple[float, int, tuple[Any, ...]]] = {}

    @staticmethod
    def _cid(scope_or_chat_id: str | None, chat_id: str | None = None) -> str:
        cid = str(chat_id or scope_or_chat_id or "").strip()
        if not cid:
            raise ValueError("chat_id is required")
        return cid

    def _bump_turn_revision(
        self, _scope_id: str, chat_id: str, *, changed_from_index: int = 0,
    ) -> int:
        """Advance a transcript revision and retain its earliest changed turn.

        Streaming normally replaces only the final turn. Recording that index lets
        the renderer rebuild the changed suffix instead of walking hundreds of
        immutable historical prompts on every publication. A bounded history
        safely falls back to a full rebuild when a view was hidden for too long.
        """
        cid = self._cid(chat_id)
        revision = int(self._turn_revisions.get(cid, 0)) + 1
        self._turn_revisions[cid] = revision
        history = self._turn_change_history.setdefault(
            cid, collections.deque(maxlen=2048),
        )
        history.append((revision, max(0, int(changed_from_index))))
        return revision

    def turn_revision(self, _scope_id: str, chat_id: str) -> int:
        return int(self._turn_revisions.get(self._cid(chat_id), 0))

    def turn_change_from_index(
        self, _scope_id: str, chat_id: str, since_revision: int,
    ) -> int:
        """Return the earliest turn changed after ``since_revision``.

        Zero is the conservative full-rebuild sentinel. The history is bounded,
        so an observer older than the retained window receives zero rather than a
        potentially incomplete suffix hint.
        """
        cid = self._cid(chat_id)
        current = int(self._turn_revisions.get(cid, 0))
        since = int(since_revision)
        if since >= current:
            return 0
        history = self._turn_change_history.get(cid)
        if not history or int(history[0][0]) > since + 1:
            return 0
        changed = [index for revision, index in history if revision > since]
        return min(changed) if changed else 0

    def _invalidate_list_cache(self, _scope_id: str | None = None) -> None:
        self._list_cache = None
        self._chat_meta_cache.clear()
        self._chat_meta_checked_at.clear()

    @staticmethod
    def _path_signature(path: Path) -> tuple[int, int]:
        try:
            st = path.stat()
            return int(st.st_mtime_ns), int(st.st_size)
        except (FileNotFoundError, OSError):
            return 0, 0

    def _load_turn_cache(self, chat_id: str, *, force_disk: bool = False) -> dict[str, Any]:
        """Return the live cached transcript and merge genuinely newer disk state.

        Ordinary local streaming updates never stat or parse files: the cache is
        authoritative and has already been patched in place. A bounded explicit
        disk poll compares signatures. If only the optional sidecar changed, its
        turn is merged only when its timestamp is newer than the in-memory turn,
        preventing an asynchronous older checkpoint from rolling the UI backward.
        """
        cid = self._cid(chat_id)
        turns_path = self.paths.chat_turns_jsonl(cid)
        snapshot_path = self.paths.chat_stream_snapshot_json(cid)
        with self._turn_cache_lock:
            cached = self._turn_cache.get(cid)
            if cached is not None and not force_disk:
                return cached

            file_sig = self._path_signature(turns_path)
            snapshot_sig = self._path_signature(snapshot_path)
            if cached is not None and cached.get("file_sig") == file_sig:
                if cached.get("snapshot_sig") != snapshot_sig:
                    if snapshot_sig != (0, 0):
                        try:
                            snapshot = validate_chat_stream_snapshot_record(
                                read_json(snapshot_path), cid, location=str(snapshot_path),
                            )
                            live_turn = copy.deepcopy(snapshot["turn"])
                            turn_id = str(live_turn.get("turn_id") or "")
                            idx = (cached.get("index") or {}).get(turn_id)
                            turns = cached.get("turns") or []
                            if idx is not None and 0 <= int(idx) < len(turns):
                                current = turns[int(idx)]
                                if (
                                    str(current.get("status") or "") == "streaming"
                                    and str(live_turn.get("status") or "") == "streaming"
                                    and str(live_turn.get("updated_at") or "")
                                    > str(current.get("updated_at") or "")
                                ):
                                    turns[int(idx)] = live_turn
                                    self._bump_turn_revision(APP_SCOPE_ID, cid, changed_from_index=int(idx))
                        except Exception as exc:
                            self.storage.append_app_log(
                                "chat.stream_snapshot.ignored",
                                {"chat_id": cid, "error": f"{type(exc).__name__}: {exc}"},
                            )
                            try:
                                snapshot_path.unlink(missing_ok=True)
                            except Exception:
                                pass
                            snapshot_sig = (0, 0)
                    cached["snapshot_sig"] = snapshot_sig
                return cached

            with DATA_ROOTS.lock_for_path(turns_path):
                turns = load_chat_turn_records(self.paths, cid)
            # A turn_id is a strict transcript identity. Collapse any historical
            # duplicate in memory by keeping its newest record at the original
            # position; append_turn prevents new duplicates from being written.
            canonical_turns: list[dict[str, Any]] = []
            canonical_index: dict[str, int] = {}
            duplicate_count = 0
            for loaded_turn in turns:
                loaded_id = str(loaded_turn.get("turn_id") or "").strip()
                if loaded_id and loaded_id in canonical_index:
                    canonical_turns[canonical_index[loaded_id]] = loaded_turn
                    duplicate_count += 1
                else:
                    canonical_turns.append(loaded_turn)
                    if loaded_id:
                        canonical_index[loaded_id] = len(canonical_turns) - 1
            if duplicate_count:
                self.storage.append_app_log(
                    "chat.turn.duplicate_collapsed",
                    {"chat_id": cid, "duplicates": duplicate_count},
                )
            turns = canonical_turns
            index = canonical_index

            if snapshot_sig != (0, 0):
                try:
                    snapshot = validate_chat_stream_snapshot_record(
                        read_json(snapshot_path), cid, location=str(snapshot_path),
                    )
                    live_turn = copy.deepcopy(snapshot["turn"])
                    turn_id = str(live_turn.get("turn_id") or "")
                    idx = index.get(turn_id)
                    if idx is not None and str(turns[idx].get("status") or "") == "streaming":
                        turns[idx] = live_turn
                except Exception as exc:
                    self.storage.append_app_log(
                        "chat.stream_snapshot.ignored",
                        {"chat_id": cid, "error": f"{type(exc).__name__}: {exc}"},
                    )
                    try:
                        snapshot_path.unlink(missing_ok=True)
                    except Exception:
                        pass
                    snapshot_sig = (0, 0)

            cached = {
                "turns": turns,
                "index": index,
                "user_turn_count": sum(
                    1 for turn in turns
                    if turn.get("role") == "user" and not is_chat_application_injected_prompt_turn(turn)
                ),
                "file_sig": file_sig,
                "snapshot_sig": snapshot_sig,
            }
            self._turn_cache[cid] = cached
            return cached

    def _set_turn_cache_after_write(self, chat_id: str, turns: list[dict[str, Any]]) -> None:
        cid = self._cid(chat_id)
        turns_path = self.paths.chat_turns_jsonl(cid)
        snapshot_path = self.paths.chat_stream_snapshot_json(cid)
        owned = [copy.deepcopy(turn) for turn in turns]
        self._turn_cache[cid] = {
            "turns": owned,
            "index": {
                str(turn.get("turn_id") or ""): idx
                for idx, turn in enumerate(owned)
                if str(turn.get("turn_id") or "")
            },
            "user_turn_count": sum(
                1 for turn in owned
                if turn.get("role") == "user" and not is_chat_application_injected_prompt_turn(turn)
            ),
            "file_sig": self._path_signature(turns_path),
            "snapshot_sig": self._path_signature(snapshot_path),
        }

    def _clear_stream_snapshot(self, chat_id: str, turn_id: str | None = None) -> None:
        cid = self._cid(chat_id)
        path = self.paths.chat_stream_snapshot_json(cid)
        # Drain/cancel the coalescing worker before unlinking. Otherwise an older
        # in-flight large snapshot could recreate streaming_turn.json after the
        # terminal turn was already committed to turns.jsonl.
        CHAT_STREAM_SNAPSHOT_WRITER.cancel(path, wait=True)
        if turn_id:
            self._stream_checkpoint_state.pop((cid, str(turn_id)), None)
        else:
            for key in [key for key in self._stream_checkpoint_state if key[0] == cid]:
                self._stream_checkpoint_state.pop(key, None)
        cached = self._turn_cache.get(cid)
        if cached is not None:
            cached["snapshot_sig"] = (0, 0)

    def _checkpoint_streaming_turn(self, chat_id: str, turn: dict[str, Any], *, force: bool = False) -> bool:
        cid = self._cid(chat_id)
        turn_id = str(turn.get("turn_id") or "")
        if not turn_id or str(turn.get("status") or "") != "streaming":
            return False
        now_mono = time.monotonic()
        text_chars = len(str(turn.get("text") or "")) + len(str(turn.get("streaming_tool_preview") or ""))
        signature = (
            text_chars,
            len(turn.get("tool_calls") or []),
            str((turn.get("stats") or {}).get("output_chars") or ""),
        )
        state = self._stream_checkpoint_state.get((cid, turn_id))
        due = bool(force)
        if state is None:
            due = due or text_chars > 0
        else:
            last_at, last_chars, last_signature = state
            elapsed = max(0.0, now_mono - last_at)
            target_interval = chat_stream_checkpoint_interval_seconds(text_chars)
            due = due or elapsed >= CHAT_STREAM_CHECKPOINT_MAX_SECONDS
            due = due or (
                elapsed >= target_interval
                and (
                    abs(text_chars - last_chars) >= CHAT_STREAM_CHECKPOINT_MIN_CHAR_DELTA
                    or signature != last_signature
                )
            )
        if not due:
            return False
        if not self.paths.chat_json(cid).is_file():
            return False
        payload = chat_stream_snapshot_record(cid, turn)
        path = self.paths.chat_stream_snapshot_json(cid)
        # Every active checkpoint is serialized, atomically written, flushed,
        # and fsynced on the dedicated writer thread. Small responses are common
        # enough that synchronous writes here were still a visible frame hitch.
        CHAT_STREAM_SNAPSHOT_WRITER.submit(path, payload)
        if force:
            CHAT_STREAM_SNAPSHOT_WRITER.flush((path,))
        self._stream_checkpoint_state[(cid, turn_id)] = (now_mono, text_chars, signature)
        cached = self._turn_cache.get(cid)
        if cached is not None and force:
            cached["snapshot_sig"] = self._path_signature(path)
        if force:
            error = CHAT_STREAM_SNAPSHOT_WRITER.last_error(path)
            if error:
                raise OSError(f"stream checkpoint writer failed: {error}")
        return True

    def flush_streaming_snapshots(self) -> None:
        """Force and drain a crash-recovery checkpoint for every live turn."""
        paths: list[Path] = []
        with self._turn_cache_lock:
            for cid, cached in list(self._turn_cache.items()):
                for turn in cached.get("turns") or []:
                    if str(turn.get("status") or "") == "streaming":
                        try:
                            self._checkpoint_streaming_turn(cid, turn, force=True)
                            paths.append(self.paths.chat_stream_snapshot_json(cid))
                        except Exception as exc:
                            self.storage.append_app_log(
                                "chat.stream_snapshot.flush_failed",
                                {"chat_id": cid, "error": f"{type(exc).__name__}: {exc}"},
                            )
        if paths:
            CHAT_STREAM_SNAPSHOT_WRITER.flush(paths)

    def _default_chat_features_from_config(self) -> dict[str, Any]:
        config = self.storage.load_config_view()
        features = config.get("features") or {}
        return {
            "file_tools_enabled": bool(features.get("file_tools_enabled", True)),
            "system_tools_enabled": bool(features.get("system_tools_enabled", True)),
            "web_tools_enabled": bool(features.get("web_tools_enabled", True)),
            "agent_tools_enabled": bool(features.get("agent_tools_enabled", True)),
            "chat_history_enabled": bool(features.get("chat_history_enabled", True)),
            "checklists_enabled": True,
            "show_reasoning_content": bool(features.get("default_show_reasoning_content", True)),
        }

    def _normalize_chat_features(self, obj: dict[str, Any]) -> dict[str, Any]:
        raw = obj.get("features") if isinstance(obj.get("features"), dict) else {}
        defaults = self._default_chat_features_from_config()
        boolean_keys = {
            "file_tools_enabled", "system_tools_enabled", "web_tools_enabled", "agent_tools_enabled", "chat_history_enabled",
            "checklists_enabled", "show_reasoning_content",
        }
        features = {
            key: bool(raw.get(key, default)) if key in boolean_keys else str(raw.get(key) or default)
            for key, default in defaults.items()
        }
        obj["features"] = features
        return obj

    def create_chat(
        self,
        name: str = "New Chat",
        *,
        chat_kind: str = "standard",
        week_start_date: str | None = None,
        endpoint_profile_id: str = "",
    ) -> dict[str, Any]:
        chat_name = str(name or "New Chat")
        config = self.storage.load_config_view()
        selected_endpoint = str(endpoint_profile_id or endpoint_profile_id_from_config(config)).strip()
        valid_ids = {str(row.get("id") or "") for row in endpoint_profiles_from_config(config)}
        if selected_endpoint not in valid_ids:
            raise ValueError(f"Unknown chat endpoint profile: {selected_endpoint}")
        conv = default_chat(
            chat_name, chat_kind=chat_kind, week_start_date=week_start_date,
            endpoint_profile_id=selected_endpoint,
        )
        conv.setdefault("features", {}).update(self._default_chat_features_from_config())
        cid = str(conv["chat_id"])
        cdir = self.paths.chat_dir(cid)
        with DATA_ROOTS.lock_for_path(cdir):
            cdir.mkdir(parents=True, exist_ok=False)
            try:
                for sub in ("attachments", "attachments_processed", "workspace", "temp"):
                    (cdir / sub).mkdir()
                atomic_write_text(self.paths.chat_turns_jsonl(cid), "")
                atomic_write_json(
                    self.paths.chat_summary_json(cid),
                    default_chat_summary(cid, selected_endpoint),
                )
                # chat.json is the publication point; scanners never see a
                # partially initialized conversation as a selectable Chat.
                atomic_write_json(self.paths.chat_json(cid), conv)
            except Exception:
                shutil.rmtree(cdir, ignore_errors=True)
                raise
        with self._turn_cache_lock:
            self._set_turn_cache_after_write(cid, [])
        self._invalidate_list_cache()
        _best_effort_lifecycle_log(self.storage, "chat.created", {"chat_id": cid, "name": chat_name})
        return conv

    def list_chats_view(
        self, _scope_id: str | None = None, *, external_poll_seconds: float = 0.35,
    ) -> list[dict[str, Any]]:
        """Return the ChatStore-owned read-only chat list for UI hot paths.

        Local writes invalidate the cache immediately. External additions or
        edits are discovered by one bounded directory/signature poll, rather
        than by scanning and stat-ing every chat directory on every frame.
        Callers must not mutate the returned list or its records.
        """
        now_t = time.monotonic()
        poll_seconds = max(0.0, float(external_poll_seconds))
        cached = self._list_cache
        if cached is not None and now_t - cached[0] < poll_seconds:
            return cached[2]

        base = self.paths.chats_dir()
        if not base.exists():
            empty: list[dict[str, Any]] = []
            self._list_cache = (now_t, (), empty)
            return empty
        candidates: list[tuple[Path, Path]] = []
        signature_rows: list[tuple[str, int, int]] = []
        for child in base.iterdir():
            path = child / "chat.json"
            if not child.name.startswith("chat_") or not child.is_dir() or not path.exists():
                continue
            try:
                st = path.stat()
            except OSError:
                continue
            candidates.append((child, path))
            signature_rows.append((child.name, int(st.st_mtime_ns), int(st.st_size)))
        signature = tuple(sorted(signature_rows))
        cached = self._list_cache
        if cached is not None and cached[1] == signature:
            # Refresh only the external-poll timestamp. Preserve list and record
            # identity so downstream UI caches can reuse their derived maps.
            self._list_cache = (now_t, signature, cached[2])
            return cached[2]

        out: list[dict[str, Any]] = []
        for child, path in candidates:
            try:
                obj = read_json(path, None)
            except Exception as exc:
                # A chat can be deleted by this or another Velox process after
                # the directory snapshot above. Disappearance is not corruption.
                if not path.is_file():
                    continue
                raise ValueError(f"Invalid chat JSON: {path}: {type(exc).__name__}: {exc}") from exc
            if obj is None and not path.is_file():
                continue
            validate_chat_record(obj, expected_chat_id=child.name.removeprefix("chat_"), location=str(path))
            self._normalize_chat_features(obj)
            out.append(obj)
        # Keep ordinary chat rows stable after creation. Updates from streaming,
        # tools, summaries, titles, and metadata must not reorder the list.
        # Search mode keeps its independent relevance order in the UI.
        out.sort(
            key=lambda row: (
                str(row.get("created_at") or ""),
                str(row.get("chat_id") or ""),
            ),
            reverse=True,
        )
        self._list_cache = (now_t, signature, out)
        return out

    def list_chats(self, _scope_id: str | None = None) -> list[dict[str, Any]]:
        """Return an isolated list while reusing the validated list source."""
        return copy.deepcopy(
            self.list_chats_view(_scope_id, external_poll_seconds=0.0)
        )

    def load_chat_view(
        self, scope_or_chat_id: str, chat_id: str | None = None,
        *,
        external_poll_seconds: float = 0.25,
    ) -> dict[str, Any]:
        """Return one ChatStore-owned read-only metadata view.

        Immediate-mode draw code may call this every frame without allocating a
        deep copy or issuing a filesystem stat every time. Local writes clear the
        cache immediately; external edits are detected by a bounded signature
        poll. Callers must not mutate the returned mapping.
        """
        cid = self._cid(scope_or_chat_id, chat_id)
        path = self.paths.chat_json(cid)
        now_mono = time.monotonic()
        poll_seconds = max(0.0, float(external_poll_seconds))
        cached = self._chat_meta_cache.get(cid)
        if cached is not None and now_mono - self._chat_meta_checked_at.get(cid, 0.0) < poll_seconds:
            return cached[2]

        try:
            st = path.stat()
            cached = self._chat_meta_cache.get(cid)
            if cached and cached[0] == st.st_mtime_ns and cached[1] == st.st_size:
                self._chat_meta_checked_at[cid] = now_mono
                return cached[2]
        except Exception:
            st = None
        if not path.is_file():
            raise FileNotFoundError(f"chat not found: {cid}")
        raw = read_json(path)
        if raw is None and not path.is_file():
            self._chat_meta_cache.pop(cid, None)
            self._chat_meta_checked_at.pop(cid, None)
            raise FileNotFoundError(f"chat not found: {cid}")
        obj = validate_chat_record(raw, expected_chat_id=cid, location=str(path))
        self._normalize_chat_features(obj)
        if st is not None:
            self._chat_meta_cache[cid] = (st.st_mtime_ns, st.st_size, obj)
            self._chat_meta_checked_at[cid] = now_mono
        return obj

    def load_chat(self, scope_or_chat_id: str, chat_id: str | None = None) -> dict[str, Any]:
        """Return an isolated Chat metadata copy for mutable/non-UI callers."""
        return copy.deepcopy(
            self.load_chat_view(
                scope_or_chat_id, chat_id, external_poll_seconds=0.0,
            )
        )

    def _persist_chat_record(self, obj: dict[str, Any], *, preserve_current_stats: bool = True, preserve_report_gate: bool = True) -> dict[str, Any]:
        """Atomically write chat metadata without regressing concurrent counters."""
        cid = str(obj.get("chat_id") or "")
        path = self.paths.chat_json(cid)
        payload = copy.deepcopy(obj)
        with DATA_ROOTS.lock_for_path(path):
            _require_durable_owner(path)
            if preserve_current_stats:
                current = validate_chat_record(
                    read_json(path), expected_chat_id=cid, location=str(path),
                )
                if preserve_report_gate:
                    payload["agent_reports_suspended"] = current["agent_reports_suspended"]
                payload["stats"] = copy.deepcopy(current["stats"])
                payload["tool_failure_count"] = int(current.get("tool_failure_count") or 0)
            self._normalize_chat_features(payload)
            payload["updated_at"] = now_iso()
            validate_chat_record(payload, expected_chat_id=cid, location=f"chat {cid}")
            _plain_atomic_write_bytes(
                path, json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8"),
            )
        self._chat_meta_cache.pop(cid, None)
        self._chat_meta_checked_at.pop(cid, None)
        self._invalidate_list_cache()
        return copy.deepcopy(payload)

    def _touch_chat_metadata(self, chat_id: str, *, user_turn_text: str | None = None) -> dict[str, Any]:
        """Update a chat timestamp/name by mutating the latest on-disk record."""
        cid = self._cid(chat_id)
        path = self.paths.chat_json(cid)
        with DATA_ROOTS.lock_for_path(path):
            _require_durable_owner(path)
            obj = validate_chat_record(read_json(path), expected_chat_id=cid, location=str(path))
            if obj.get("name") in ("New Chat", "") and user_turn_text is not None:
                first_line = str(user_turn_text or "").strip().splitlines()[0:1]
                if first_line:
                    obj["name"] = first_line[0]
            obj["updated_at"] = now_iso()
            _plain_atomic_write_bytes(
                path, json_dumps(obj).encode("utf-8"),
            )
        self._chat_meta_cache.pop(cid, None)
        self._chat_meta_checked_at.pop(cid, None)
        self._invalidate_list_cache()
        return copy.deepcopy(obj)

    def write_chat(self, scope_or_chat: str | dict[str, Any], chat: dict[str, Any] | None = None) -> dict[str, Any]:
        obj = copy.deepcopy(chat if chat is not None else scope_or_chat)
        if not isinstance(obj, dict):
            raise TypeError("chat metadata must be a dictionary")
        cid = str(obj.get("chat_id") or "")
        validate_chat_record(obj, expected_chat_id=cid, location=f"chat {cid}")
        return self._persist_chat_record(obj, preserve_current_stats=True)

    def set_agent_reports_suspended(self, chat_id: str, suspended: bool) -> None:
        """Durable user-Stop fence; only a real new send/regenerate clears it."""
        path = self.paths.chat_json(chat_id)
        with DATA_ROOTS.lock_for_path(path):
            current = self.load_chat(chat_id)
            current["agent_reports_suspended"] = bool(suspended)
            self._persist_chat_record(current, preserve_report_gate=False)

    def get_chat_feature(self, _scope_id: str, chat_id: str | None, feature_name: str, default: bool = False) -> bool:
        if not chat_id:
            return bool(default)
        try:
            return bool((self.load_chat_view(chat_id).get("features") or {}).get(feature_name, default))
        except Exception:
            return bool(default)

    def set_chat_feature(self, _scope_id: str, chat_id: str, feature_name: str, enabled: bool) -> dict[str, Any]:
        allowed = {
            "file_tools_enabled",
            "system_tools_enabled",
            "web_tools_enabled",
            "agent_tools_enabled",
            "chat_history_enabled",
            "checklists_enabled",
            "show_reasoning_content",
        }
        feature_name = str(feature_name or "").strip()
        if feature_name not in allowed:
            raise ValueError(f"unsupported chat feature: {feature_name}")
        if feature_name in CHAT_TOOL_FEATURE_KEYS and self.is_chat_endpoint_locked(chat_id):
            raise ValueError("Chat tool settings are locked after the first user message.")
        conv = self.load_chat(chat_id)
        conv.setdefault("features", {})[feature_name] = bool(enabled)
        saved = self.write_chat(conv)
        _best_effort_lifecycle_log(self.storage, "chat.feature.updated", {"chat_id": chat_id, "feature": feature_name, "enabled": bool(enabled)})
        return saved

    def chat_user_turn_count(self, _scope_id: str, chat_id: str) -> int:
        """Return the cached scalar count without copying/scanning the transcript."""
        cid = self._cid(chat_id)
        with self._turn_cache_lock:
            cached = self._load_turn_cache(cid)
            return int(cached.get("user_turn_count") or 0)

    def get_chat_endpoint_profile_id(self, chat_id: str) -> str:
        return str(self.load_chat_view(chat_id).get("endpoint_profile_id") or "").strip()

    def get_chat_tool_features(self, chat_id: str) -> dict[str, bool]:
        chat = self.load_chat_view(chat_id)
        return normalize_tool_feature_flags(
            chat.get("features"), self._default_chat_features_from_config(),
        )

    def is_chat_endpoint_locked(self, chat_id: str) -> bool:
        return self.chat_user_turn_count(APP_SCOPE_ID, chat_id) > 0

    def set_chat_endpoint_profile_id(self, chat_id: str, profile_id: str) -> dict[str, Any]:
        cid = self._cid(chat_id)
        if self.is_chat_endpoint_locked(cid):
            raise ValueError("The chat endpoint is locked after the first user message.")
        config = self.storage.load_config_view()
        selected = str(profile_id or "").strip()
        valid_ids = {str(row.get("id") or "") for row in endpoint_profiles_from_config(config)}
        if selected not in valid_ids:
            raise ValueError(f"Unknown chat endpoint profile: {selected}")
        obj = self.load_chat(cid)
        obj["endpoint_profile_id"] = selected
        saved = self.write_chat(obj)
        summary_path = self.paths.chat_summary_json(cid)
        if summary_path.is_file():
            summary = load_chat_summary_record(self.paths, cid)
            summary["endpoint_profile_id"] = selected
            atomic_write_json(summary_path, summary)
        _best_effort_lifecycle_log(self.storage, "chat.endpoint.updated", {"chat_id": cid, "endpoint_profile_id": selected})
        return saved



    def get_endpoint_profile_id(self) -> str:
        """Return the single configured default for new Chats and unscoped Tasks."""
        return endpoint_profile_id_from_config(self.storage.load_config_view())

    def increment_tool_failure_count(self, chat_id: str) -> int:
        """Atomically consume one failure from a chat's lifetime failure budget."""
        cid = self._cid(chat_id)
        path = self.paths.chat_json(cid)
        with DATA_ROOTS.lock_for_path(path):
            obj = validate_chat_record(read_json(path), expected_chat_id=cid, location=str(path))
            count = int(obj.get("tool_failure_count") or 0) + 1
            obj["tool_failure_count"] = count
            obj["updated_at"] = now_iso()
            _plain_atomic_write_bytes(path, json_dumps(obj).encode("utf-8"))
        self._chat_meta_cache.pop(cid, None)
        self._chat_meta_checked_at.pop(cid, None)
        self._invalidate_list_cache()
        return count


    def append_turn(self, _scope_id: str, chat_id: str, turn: dict[str, Any], *, mark_stale: bool = True) -> None:
        """Append exactly one durable turn identity and publish it atomically to the UI cache.

        The cache lock intentionally spans the disk append. Previously the JSONL write
        happened first and the cache append happened later. A UI disk poll could reload
        the just-written turn between those operations and then receive the same turn a
        second time from the local append, producing duplicate continuation cards with
        one shared turn_id.
        """
        cid = self._cid(chat_id)
        validate_chat_turn_record(turn, cid, location=f"new turn for chat {cid}")
        turns_path = self.paths.chat_turns_jsonl(cid)
        turn_id = str(turn.get("turn_id") or "").strip()
        if not turn_id:
            raise ValueError("chat turn_id is required")
        changed_from_index = 0
        appended = False
        with self._turn_cache_lock:
            cached = self._load_turn_cache(cid)
            existing_idx = (cached.get("index") or {}).get(turn_id)
            if existing_idx is not None:
                turns = cached.get("turns") or []
                existing = turns[int(existing_idx)] if 0 <= int(existing_idx) < len(turns) else None
                if existing == turn:
                    return
                raise ValueError(f"Duplicate chat turn_id with conflicting payload: {turn_id}")
            owned = copy.deepcopy(turn)
            with DATA_ROOTS.lock_for_path(turns_path):
                _require_durable_owner(turns_path)
                append_jsonl(turns_path, owned)
            cached.setdefault("turns", []).append(owned)
            changed_from_index = len(cached["turns"]) - 1
            cached.setdefault("index", {})[turn_id] = changed_from_index
            if owned.get("role") == "user" and not is_chat_application_injected_prompt_turn(owned):
                cached["user_turn_count"] = int(cached.get("user_turn_count") or 0) + 1
            cached["file_sig"] = self._path_signature(turns_path)
            appended = True
        if not appended:
            return
        self._touch_chat_metadata(
            cid,
            user_turn_text=(
                str(turn.get("text") or "")
                if turn.get("role") == "user" and not is_chat_application_injected_prompt_turn(turn)
                else None
            ),
        )
        self._bump_turn_revision(APP_SCOPE_ID, cid, changed_from_index=changed_from_index)
        self.storage.append_app_log("chat.turn.appended", {"chat_id": cid, "turn_id": turn_id, "role": turn.get("role")})
        if mark_stale and turn.get("role") in ("user", "assistant") and not is_chat_application_injected_prompt_turn(turn):
            self.mark_chat_summary_stale(APP_SCOPE_ID, cid)

    def load_turns(self, _scope_id: str, chat_id: str) -> list[dict[str, Any]]:
        """Return an isolated transcript snapshot for non-UI callers."""
        cid = self._cid(chat_id)
        with self._turn_cache_lock:
            cached = self._load_turn_cache(cid)
            return copy.deepcopy(cached.get("turns") or [])

    def load_turns_view(
        self, _scope_id: str, chat_id: str, *, check_disk: bool = False,
    ) -> list[dict[str, Any]]:
        """Return ChatStore-owned read-only turns for immediate-mode rendering.

        Local writes patch this stable list and bump ``turn_revision``. The hot UI
        path therefore avoids filesystem metadata calls and a deep copy of every
        historical turn. A bounded external-file poll passes ``check_disk=True``.
        """
        cid = self._cid(chat_id)
        with self._turn_cache_lock:
            cached = self._load_turn_cache(cid, force_disk=bool(check_disk))
            return cached.get("turns") or []

    @staticmethod
    def _detach_streaming_turn_patch(patch: dict[str, Any]) -> dict[str, Any]:
        """Detach the small live patch without cloning unchanged turn history."""
        detached: dict[str, Any] = {}
        for key, value in (patch or {}).items():
            if key == "tool_calls" and isinstance(value, list):
                detached[key] = [
                    dict(row) if isinstance(row, dict) else copy.deepcopy(row)
                    for row in value
                ]
            elif key in {"stats", "compaction_meta"} and isinstance(value, dict):
                detached[key] = copy.deepcopy(value)
            elif key in {
                "response_output_items", "attachments", "compaction_messages",
                "compaction_request_messages",
            } and isinstance(value, list):
                detached[key] = [
                    dict(row) if isinstance(row, dict) else copy.deepcopy(row)
                    for row in value
                ]
            elif isinstance(value, (str, int, float, bool, bytes, type(None))):
                detached[key] = value
            else:
                detached[key] = copy.deepcopy(value)
        return detached

    def update_turn(
        self,
        _scope_id: str,
        chat_id: str,
        turn_id: str,
        patch: dict[str, Any],
        *,
        mark_stale: bool = False,
        expected_statuses: Iterable[str] | None = None,
        allow_terminal_transition: bool = False,
    ) -> bool:
        """Atomically compare-and-set one turn.

        Live inference, cancellation, compaction, and UI callbacks can be scheduled
        close together. Callers that own a streaming generation pass
        ``expected_statuses={"streaming"}``; after another callback reaches a
        terminal state, their delayed write is rejected even when it proposes the
        same terminal status. Terminal-to-terminal replacement is allowed only for
        an explicit, expected recovery path such as an agent-report fallback.
        """
        cid = self._cid(chat_id)
        blocked: dict[str, str] = {}
        requested_status = str((patch or {}).get("status") or "").strip()
        expected = (
            frozenset(str(value or "").strip() for value in expected_statuses)
            if expected_statuses is not None
            else None
        )
        if expected is not None and (
            not expected or any(value not in CHAT_TURN_STATUSES for value in expected)
        ):
            raise ValueError("expected_statuses must contain valid chat turn statuses")

        changed = False
        touch_metadata = False
        with self._turn_cache_lock:
            cached = self._load_turn_cache(cid)
            index = cached.get("index") or {}
            idx = index.get(str(turn_id))
            if idx is None:
                return False
            turns = cached.get("turns") or []
            current = turns[idx]
            current_status = str(current.get("status") or "")
            if expected is not None and current_status not in expected:
                blocked.update({
                    "reason": "expected_status_mismatch",
                    "from": current_status,
                    "to": requested_status or current_status,
                })
            elif (
                requested_status
                and current_status in CHAT_TURN_TERMINAL_STATUSES
                and requested_status != current_status
                and not allow_terminal_transition
            ):
                blocked.update({
                    "reason": "terminal_state_is_final",
                    "from": current_status,
                    "to": requested_status,
                })
            else:
                next_status = requested_status or current_status
                if current_status == "streaming" and next_status == "streaming":
                    # The live turn can contain multi-megabyte text and hundreds
                    # of tool rows.  Copying the entire current record on every
                    # token/progress publication monopolized the UI thread and
                    # made Stop appear frozen.  Build a new top-level record from
                    # the current immutable values plus only the detached patch.
                    updated = dict(current)
                    updated.update(self._detach_streaming_turn_patch(patch or {}))
                    updated["updated_at"] = now_iso()
                    validate_chat_turn_record(
                        updated, cid, location=f"updated turn {turn_id}",
                    )
                    turns[idx] = updated
                    changed = True
                    # Immediate in-memory publication; only the small live
                    # checkpoint file is written at a bounded cadence.
                    try:
                        self._checkpoint_streaming_turn(cid, updated)
                    except Exception as exc:
                        self.storage.append_app_log(
                            "chat.stream_snapshot.warning",
                            {"chat_id": cid, "turn_id": str(turn_id), "error": f"{type(exc).__name__}: {exc}"},
                        )
                    self._bump_turn_revision(APP_SCOPE_ID, cid, changed_from_index=int(idx))
                else:
                    # Terminal/edit transitions are uncommon and require a fully
                    # detached durable record before rewriting turns.jsonl.
                    updated = copy.deepcopy(current)
                    updated.update(copy.deepcopy(patch or {}))
                    if "text" in (patch or {}) and patch["text"] != current.get("text") and "model_replay_messages" not in patch:
                        updated.pop("model_replay_messages", None)
                    updated["updated_at"] = now_iso()
                    validate_chat_turn_record(updated, cid, location=f"updated turn {turn_id}")
                    if updated != current:
                        turns[idx] = updated
                        changed = True
                        # Terminal and edit transitions are durable immediately.
                        # They rewrite turns.jsonl exactly once, then remove the
                        # optional streaming sidecar.
                        self._write_all_turns(APP_SCOPE_ID, cid, turns)
                        self._clear_stream_snapshot(cid, str(turn_id))
                        touch_metadata = True
        if blocked:
            self.storage.append_app_log(
                "chat.turn.stale_write_ignored",
                {
                    "chat_id": cid,
                    "turn_id": str(turn_id),
                    "reason": blocked.get("reason"),
                    "from": blocked.get("from"),
                    "to": blocked.get("to"),
                },
            )
        if changed and touch_metadata:
            self._touch_chat_metadata(cid)
        if changed and mark_stale:
            self.mark_chat_summary_stale(APP_SCOPE_ID, cid)
        return changed

    def rename_chat(self, _scope_id: str, chat_id: str, name: str) -> dict[str, Any]:
        obj = self.load_chat(chat_id)
        obj["name"] = str(name or "").strip() or "Chat"
        result = self.write_chat(obj)
        _best_effort_lifecycle_log(self.storage, "chat.renamed", {"chat_id": chat_id, "name": result["name"]})
        return result

    def delete_chat(self, _scope_id: str, chat_id: str) -> None:
        """Detach the complete Chat atomically before best-effort file cleanup."""
        cid = self._cid(chat_id)
        chat_dir = self.paths.chat_dir(cid)
        # Never hold the root lock while waiting on the checkpoint writer.
        self._clear_stream_snapshot(cid)
        with DATA_ROOTS.lock_for_path(chat_dir):
            _require_durable_owner(self.paths.chat_json(cid))
            detached = _detach_owner_directory(chat_dir)
        self._turn_revisions.pop(cid, None)
        self._turn_change_history.pop(cid, None)
        self._chat_meta_cache.pop(cid, None)
        self._chat_meta_checked_at.pop(cid, None)
        with self._turn_cache_lock:
            self._turn_cache.pop(cid, None)
            for key in [key for key in self._stream_checkpoint_state if key[0] == cid]:
                self._stream_checkpoint_state.pop(key, None)
        self._invalidate_list_cache()
        try:
            CalendarStore(self.storage).remove_week_chat_mapping_for_chat(cid)
            app_state = self.storage.load_app_state()
            if str(app_state.get("active_chat_id") or "") == cid:
                app_state["active_chat_id"] = None
                self.storage.write_app_state(app_state)
        except Exception as exc:
            _best_effort_lifecycle_log(self.storage, "chat.delete_reference_cleanup_pending", {"chat_id": cid, "error": str(exc)})
        _purge_detached_owner(self.storage, detached)
        _best_effort_lifecycle_log(self.storage, "chat.deleted", {"chat_id": cid})

    @staticmethod
    def _retarget_turn_for_chat(turn: dict[str, Any], chat_id: str) -> dict[str, Any]:
        """Copy one turn while making all chat-owned attachment metadata local."""
        copied = copy.deepcopy(turn)
        copied["chat_id"] = chat_id
        attachments = copied.get("attachments")
        if isinstance(attachments, list):
            for attachment in attachments:
                if isinstance(attachment, dict):
                    attachment["chat_id"] = chat_id
                    attachment["scope"] = "chat"
        return copied

    def _copy_chat_subdirectory(self, source_chat_id: str, target_chat_id: str, name: str) -> None:
        source = self.paths.chat_dir(source_chat_id) / name
        target = self.paths.chat_dir(target_chat_id) / name
        if not source.exists():
            return
        shutil.rmtree(target, ignore_errors=True)
        shutil.copytree(source, target)
        if name == "attachments":
            for meta_path in target.rglob("*.meta.json"):
                try:
                    meta = read_json(meta_path, {}) or {}
                    if isinstance(meta, dict):
                        meta["chat_id"] = target_chat_id
                        meta["scope"] = "chat"
                        atomic_write_json(meta_path, meta)
                except Exception as exc:
                    self.storage.append_app_log(
                        "attachment.copy_metadata.failed",
                        {"chat_id": target_chat_id, "path": str(meta_path), "error": f"{type(exc).__name__}: {exc}"},
                    )

    def copy_chat(self, _scope_id: str, chat_id: str) -> dict[str, Any]:
        old_meta = self.load_chat(chat_id)
        new_conv = self.create_chat(
            "Copy of " + str(old_meta.get("name", "Chat")),
            endpoint_profile_id=str(old_meta.get("endpoint_profile_id") or ""),
        )
        # The copied first-user prompt already embodies this locked policy.
        # Reverting to new-Chat defaults could silently re-enable Checklists/tools.
        new_conv["features"] = copy.deepcopy(old_meta["features"])
        new_conv = self.write_chat(new_conv)
        new_chat_id = str(new_conv["chat_id"])
        copied_turns = [self._retarget_turn_for_chat(turn, new_chat_id) for turn in self.load_turns(APP_SCOPE_ID, chat_id)]
        self._write_all_turns(APP_SCOPE_ID, new_chat_id, copied_turns)
        for sub in ("attachments", "workspace"):
            self._copy_chat_subdirectory(chat_id, new_chat_id, sub)
        self.mark_chat_summary_stale(APP_SCOPE_ID, new_chat_id)
        return new_conv

    def edit_user_turn(self, _scope_id: str, chat_id: str, turn_id: str, new_text: str) -> None:
        changed = self._rewrite_turns(APP_SCOPE_ID, chat_id, lambda t: self._edit_turn_if_match(t, turn_id, new_text, {"user"}))
        if changed:
            self._touch_chat_metadata(chat_id)
            self.mark_chat_summary_stale(APP_SCOPE_ID, chat_id)

    def edit_assistant_turn(self, _scope_id: str, chat_id: str, turn_id: str, new_text: str) -> None:
        changed = self._rewrite_turns(APP_SCOPE_ID, chat_id, lambda t: self._edit_turn_if_match(t, turn_id, new_text, {"assistant"}))
        if changed:
            self._touch_chat_metadata(chat_id)
            self.mark_chat_summary_stale(APP_SCOPE_ID, chat_id)

    def delete_turn(self, _scope_id: str, chat_id: str, turn_id: str) -> None:
        cid = self._cid(chat_id)
        with self._turn_cache_lock:
            turns = copy.deepcopy(self._load_turn_cache(cid).get("turns") or [])
            keep = [turn for turn in turns if turn.get("turn_id") != turn_id]
            if len(keep) == len(turns):
                return
            self._write_all_turns(APP_SCOPE_ID, cid, keep)
            self._clear_stream_snapshot(cid, str(turn_id))
        self._touch_chat_metadata(cid)
        self.mark_chat_summary_stale(APP_SCOPE_ID, cid)


    def mark_chat_summary_stale(self, _scope_id: str, chat_id: str) -> None:
        path = self.paths.chat_summary_json(chat_id)
        with DATA_ROOTS.lock_for_path(path):
            obj = load_chat_summary_record(self.paths, chat_id)
            obj["stale"] = True
            atomic_write_json(path, obj)

    def _edit_turn_if_match(self, turn: dict[str, Any], turn_id: str, new_text: str, roles: set[str]) -> dict[str, Any]:
        if turn.get("turn_id") == turn_id and turn.get("role") in roles:
            turn.setdefault("edit_history", []).append({"edited_at": now_iso(), "old_text": turn.get("text", "")})
            turn["text"] = new_text
            turn["updated_at"] = now_iso()
        return turn

    def _rewrite_turns(self, _scope_id: str, chat_id: str, edit_fn: Callable[[dict[str, Any]], dict[str, Any]]) -> bool:
        cid = self._cid(chat_id)
        with self._turn_cache_lock:
            turns = copy.deepcopy(self._load_turn_cache(cid).get("turns") or [])
            changed = False
            rewritten: list[dict[str, Any]] = []
            for turn in turns:
                before = copy.deepcopy(turn)
                after = edit_fn(turn)
                rewritten.append(after)
                if after != before:
                    changed = True
            if changed:
                self._write_all_turns(APP_SCOPE_ID, cid, rewritten)
                self._clear_stream_snapshot(cid)
            return changed

    def _write_all_turns(self, _scope_id: str, chat_id: str, turns: list[dict[str, Any]]) -> None:
        cid = self._cid(chat_id)
        path = self.paths.chat_turns_jsonl(cid)
        rows: list[str] = []
        for turn in turns:
            validate_chat_turn_record(turn, cid, location=f"rewritten turns for chat {cid}")
            rows.append(json.dumps(turn, ensure_ascii=False, separators=(",", ":")))
        payload = ("\n".join(rows) + ("\n" if rows else "")).encode("utf-8")
        # Keep the transcript lock order consistent with append/load: cache first,
        # file second. This avoids a cache<->filesystem lock inversion under async UI polls.
        with self._turn_cache_lock:
            with DATA_ROOTS.lock_for_path(path):
                _require_durable_owner(path)
                _plain_atomic_write_bytes(path, payload)
            self._set_turn_cache_after_write(cid, turns)
        self._bump_turn_revision(APP_SCOPE_ID, cid, changed_from_index=0)

    def truncate_after_turn(self, _scope_id: str, chat_id: str, turn_id: str, *, include_turn: bool = True) -> list[dict[str, Any]]:
        cid = self._cid(chat_id)
        with self._turn_cache_lock:
            turns = copy.deepcopy(self._load_turn_cache(cid).get("turns") or [])
            keep: list[dict[str, Any]] = []
            found = False
            for turn in turns:
                if turn.get("turn_id") == turn_id:
                    found = True
                    if include_turn:
                        keep.append(turn)
                    break
                keep.append(turn)
            if not found:
                return turns
            self._write_all_turns(APP_SCOPE_ID, cid, keep)
            self._clear_stream_snapshot(cid)
        self._touch_chat_metadata(cid)
        self.mark_chat_summary_stale(APP_SCOPE_ID, cid)
        return keep

    def branch_chat(self, _scope_id: str, chat_id: str, turn_id: str) -> dict[str, Any]:
        old_meta = self.load_chat(chat_id)
        new_conv = self.create_chat(
            "Branch of " + str(old_meta.get("name", "Chat"))[:120],
            endpoint_profile_id=str(old_meta.get("endpoint_profile_id") or ""),
        )
        # The copied first-user prompt already embodies this locked policy.
        # Reverting to new-Chat defaults could silently re-enable Checklists/tools.
        new_conv["features"] = copy.deepcopy(old_meta["features"])
        new_conv = self.write_chat(new_conv)
        new_chat_id = str(new_conv["chat_id"])
        copied: list[dict[str, Any]] = []
        for turn in self.load_turns(APP_SCOPE_ID, chat_id):
            new_turn = self._retarget_turn_for_chat(turn, new_chat_id)
            copied.append(new_turn)
            if turn.get("turn_id") == turn_id:
                break
        self._write_all_turns(APP_SCOPE_ID, new_chat_id, copied)
        self._copy_chat_subdirectory(chat_id, new_chat_id, "attachments")
        self.mark_chat_summary_stale(APP_SCOPE_ID, new_chat_id)
        return new_conv


@dataclass
class VaultRecordCache:
    lock: threading.RLock = field(default_factory=threading.RLock)
    loaded: bool = False
    revision: int = 0
    last_poll: float = 0.0
    directory_signatures: dict[str, tuple[int, int, int]] = field(default_factory=dict)
    sources: dict[str, dict[str, Any]] = field(default_factory=dict)
    source_identity: dict[tuple[str, str], str] = field(default_factory=dict)
    containers: dict[str, dict[str, Any]] = field(default_factory=dict)
    container_identity: dict[tuple[str, str], str] = field(default_factory=dict)
    items: dict[str, dict[str, Any]] = field(default_factory=dict)
    item_identity: dict[tuple[str, str], str] = field(default_factory=dict)
    item_ids_by_source: dict[str, set[str]] = field(default_factory=dict)
    item_ids_by_container: dict[str, set[str]] = field(default_factory=dict)
    sync_states: dict[str, dict[str, Any]] = field(default_factory=dict)
    sync_identity: dict[tuple[str, str | None, str], str] = field(default_factory=dict)


_VAULT_RECORD_CACHES: dict[str, VaultRecordCache] = {}
_VAULT_RECORD_CACHES_LOCK = threading.RLock()


def vault_record_cache_for_root(root_dir: Path) -> VaultRecordCache:
    key = os.path.normcase(str(Path(root_dir).expanduser().resolve()))
    with _VAULT_RECORD_CACHES_LOCK:
        cache = _VAULT_RECORD_CACHES.get(key)
        if cache is None:
            cache = VaultRecordCache()
            _VAULT_RECORD_CACHES[key] = cache
        return cache


class VaultStore:
    """Normalized account-data storage shared by Calendar, Gmail and Slack.

    Calendar events retain their calendar-specific records and are also mirrored
    into this store. Query and UI code consume the common item model rather than
    provider-specific payloads."""

    def __init__(self, storage: Storage):
        self.storage = storage
        self.paths = storage.paths
        self._cache = vault_record_cache_for_root(self.paths.root_dir)

    def _ensure_layout_unchecked(self) -> None:
        for directory in (
            self.paths.vault_sources_dir(),
            self.paths.vault_containers_dir(),
            self.paths.vault_items_dir(),
            self.paths.vault_sync_states_dir(),
            self.paths.vault_raw_dir(),
        ):
            directory.mkdir(parents=True, exist_ok=True)

    def _ready(self) -> None:
        self.storage.ensure_first_run_files()
        self._ensure_layout_unchecked()

    def store_raw_payload(self, payload: Any) -> str:
        """Persist one optional connector payload by content hash.

        Normalized Vault records never require this file to render or query. The
        reference exists only for diagnostics and later connector repair work.
        """
        self._ready()
        encoded = json.dumps(
            payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        ).encode("utf-8")
        if len(encoded) > VAULT_RAW_PAYLOAD_MAX_BYTES:
            raise ValueError("Vault raw payload exceeds the configured 16 MiB limit")
        digest = sha256_bytes(encoded)
        path = self.paths.vault_raw_json(digest)
        with DATA_ROOTS.lock_for_path(path):
            if not path.exists():
                _plain_atomic_write_bytes(path, encoded)
        return path.relative_to(self.paths.root_dir).as_posix()

    def load_raw_payload(self, reference: str) -> Any:
        self._ready()
        raw_reference = str(reference or "").strip().replace("\\", "/")
        match = re.fullmatch(r"vault/raw/raw_([0-9a-f]{64})\.json", raw_reference)
        if not match:
            raise ValueError("Vault raw-payload reference is invalid")
        path = self.paths.vault_raw_json(match.group(1))
        encoded = file_read_bytes(path)
        if sha256_bytes(encoded) != match.group(1):
            raise ValueError("Vault raw payload content hash does not match its reference")
        return json.loads(encoded.decode("utf-8"))

    def _load_with_backup(
        self,
        path: Path,
        validator: Callable[..., dict[str, Any]],
        *,
        location: str,
    ) -> dict[str, Any]:
        primary_error: BaseException | None = None
        try:
            return copy.deepcopy(validator(read_json(path), location=location))
        except Exception as exc:
            primary_error = exc
        backup = _record_backup_path(path)
        if backup.is_file():
            try:
                recovered = copy.deepcopy(validator(read_json(backup), location=str(backup)))
                _plain_atomic_write_bytes(
                    path,
                    json.dumps(recovered, ensure_ascii=False, indent=2).encode("utf-8"),
                )
                self.storage.append_app_log(
                    "vault.record.recovered",
                    {
                        "path": str(path),
                        "backup": str(backup),
                        "error": f"{type(primary_error).__name__}: {primary_error}",
                    },
                )
                return recovered
            except Exception as backup_error:
                raise ValueError(
                    f"Malformed Vault data in {path}; backup recovery also failed: "
                    f"{type(backup_error).__name__}: {backup_error}"
                ) from primary_error
        raise ValueError(
            f"Malformed Vault data in {path}: {type(primary_error).__name__}: {primary_error}"
        ) from primary_error

    def _write_with_backup(
        self,
        path: Path,
        value: dict[str, Any],
        validator: Callable[..., dict[str, Any]],
        *,
        location: str,
    ) -> dict[str, Any]:
        payload = copy.deepcopy(validator(copy.deepcopy(value), location=location))
        with DATA_ROOTS.lock_for_path(path):
            if path.is_file():
                current = copy.deepcopy(validator(read_json(path), location=str(path)))
                _plain_atomic_write_bytes(
                    _record_backup_path(path),
                    json_dumps(current).encode("utf-8"),
                )
            _plain_atomic_write_bytes(
                path,
                json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8"),
            )
        return copy.deepcopy(payload)

    def _directories(self) -> dict[str, tuple[Path, str, Callable[..., dict[str, Any]]]]:
        return {
            "sources": (self.paths.vault_sources_dir(), "source", validate_vault_data_source),
            "containers": (self.paths.vault_containers_dir(), "container", validate_vault_container),
            "items": (self.paths.vault_items_dir(), "item", validate_vault_item),
            "sync_states": (self.paths.vault_sync_states_dir(), "sync", validate_vault_sync_state),
        }

    def _cache_signatures(self) -> dict[str, tuple[int, int, int]]:
        return {
            name: _directory_signature(directory)
            for name, (directory, _prefix, _validator) in self._directories().items()
        }

    def _load_all_unchecked(self) -> tuple[
        dict[str, dict[str, Any]],
        dict[str, dict[str, Any]],
        dict[str, dict[str, Any]],
        dict[str, dict[str, Any]],
    ]:
        loaded: dict[str, dict[str, dict[str, Any]]] = {}
        for name, (directory, prefix, validator) in self._directories().items():
            records: dict[str, dict[str, Any]] = {}
            for path in _json_record_paths(directory, prefix):
                record = self._load_with_backup(path, validator, location=str(path))
                record_id = str(record["id"])
                expected_id = path.stem.removeprefix(prefix + "_")
                if record_id != expected_id:
                    raise ValueError(f"Vault {name} identity does not match filename: {path}")
                records[record_id] = record
            loaded[name] = records
        return (
            loaded["sources"], loaded["containers"], loaded["items"], loaded["sync_states"],
        )

    @staticmethod
    def _validate_relationships(
        sources: dict[str, dict[str, Any]],
        containers: dict[str, dict[str, Any]],
        items: dict[str, dict[str, Any]],
        sync_states: dict[str, dict[str, Any]],
    ) -> None:
        container_keys: set[tuple[str, str]] = set()
        for container in containers.values():
            if container["source_id"] not in sources:
                raise ValueError("Vault Container references a missing source")
            key = (container["source_id"], container["external_id"])
            if key in container_keys:
                raise ValueError(f"Duplicate Vault Container external identity: {key}")
            container_keys.add(key)
            parent = container["parent_container_id"]
            if parent and parent not in containers:
                raise ValueError("Vault Container references a missing parent")
        item_keys: set[tuple[str, str]] = set()
        for item in items.values():
            if item["source_id"] not in sources or item["container_id"] not in containers:
                raise ValueError("Vault Item references a missing source or container")
            if containers[item["container_id"]]["source_id"] != item["source_id"]:
                raise ValueError("Vault Item source does not match its Container")
            key = (item["source_id"], item["external_id"])
            if key in item_keys:
                raise ValueError(f"Duplicate Vault Item external identity: {key}")
            item_keys.add(key)
            parent = item["parent_item_id"]
            if parent and parent not in items:
                raise ValueError("Vault Item references a missing parent")
        sync_keys: set[tuple[str, str, str]] = set()
        for state in sync_states.values():
            if state["source_id"] not in sources:
                raise ValueError("Vault sync state references a missing source")
            container_id = state["container_id"]
            if container_id and container_id not in containers:
                raise ValueError("Vault sync state references a missing Container")
            key = (state["source_id"], container_id, state["cursor_type"])
            if key in sync_keys:
                raise ValueError(f"Duplicate Vault sync cursor identity: {key}")
            sync_keys.add(key)


    def _ensure_cache(self, *, force: bool = False) -> None:
        self._ready()
        now_mono = time.monotonic()
        with self._cache.lock:
            if (
                not force
                and self._cache.loaded
                and now_mono - self._cache.last_poll < VAULT_CACHE_EXTERNAL_POLL_SECONDS
            ):
                return
            previous = dict(self._cache.directory_signatures)
            loaded = self._cache.loaded
            self._cache.last_poll = now_mono
        current = self._cache_signatures()
        if not force and loaded and current == previous:
            return
        with DATA_ROOTS.lock_for_path(self.paths.vault_dir()):
            sources, containers, items, sync_states = self._load_all_unchecked()
            self._validate_relationships(sources, containers, items, sync_states)
            final_signatures = self._cache_signatures()
        with self._cache.lock:
            self._cache.sources = {key: copy.deepcopy(value) for key, value in sources.items()}
            self._cache.source_identity = {
                (row["source_type"], row["account_identifier"].casefold()): row_id
                for row_id, row in self._cache.sources.items()
            }
            self._cache.containers = {key: copy.deepcopy(value) for key, value in containers.items()}
            self._cache.container_identity = {
                (row["source_id"], row["external_id"]): row_id
                for row_id, row in self._cache.containers.items()
            }
            self._cache.items = {key: copy.deepcopy(value) for key, value in items.items()}
            self._cache.item_identity = {
                (row["source_id"], row["external_id"]): row_id
                for row_id, row in self._cache.items.items()
            }
            self._cache.item_ids_by_source = {}
            self._cache.item_ids_by_container = {}
            for row_id, row in self._cache.items.items():
                self._cache.item_ids_by_source.setdefault(row["source_id"], set()).add(row_id)
                self._cache.item_ids_by_container.setdefault(row["container_id"], set()).add(row_id)
            self._cache.sync_states = {key: copy.deepcopy(value) for key, value in sync_states.items()}
            self._cache.sync_identity = {
                (row["source_id"], row["container_id"], row["cursor_type"]): row_id
                for row_id, row in self._cache.sync_states.items()
            }
            self._cache.directory_signatures = final_signatures
            self._cache.loaded = True
            self._cache.revision += 1
            self._cache.last_poll = time.monotonic()

    def _cache_put(self, group: str, record: dict[str, Any]) -> None:
        with self._cache.lock:
            if not self._cache.loaded:
                return
            row_id = str(record["id"])
            saved = copy.deepcopy(record)
            rows = getattr(self._cache, group)
            previous = rows.get(row_id)

            # Remove every old secondary index before replacing a record. Drive
            # files can move between My Drive and a Shared Drive while retaining
            # their stable file ID; leaving the old container index behind made
            # one item appear in both panes until a full cache reload.
            if previous is not None:
                if group == "sources":
                    old_key = (previous["source_type"], previous["account_identifier"].casefold())
                    if self._cache.source_identity.get(old_key) == row_id:
                        self._cache.source_identity.pop(old_key, None)
                elif group == "containers":
                    old_key = (previous["source_id"], previous["external_id"])
                    if self._cache.container_identity.get(old_key) == row_id:
                        self._cache.container_identity.pop(old_key, None)
                elif group == "items":
                    old_key = (previous["source_id"], previous["external_id"])
                    if self._cache.item_identity.get(old_key) == row_id:
                        self._cache.item_identity.pop(old_key, None)
                    old_source_ids = self._cache.item_ids_by_source.get(previous["source_id"])
                    if old_source_ids is not None:
                        old_source_ids.discard(row_id)
                        if not old_source_ids:
                            self._cache.item_ids_by_source.pop(previous["source_id"], None)
                    old_container_ids = self._cache.item_ids_by_container.get(previous["container_id"])
                    if old_container_ids is not None:
                        old_container_ids.discard(row_id)
                        if not old_container_ids:
                            self._cache.item_ids_by_container.pop(previous["container_id"], None)
                elif group == "sync_states":
                    old_key = (previous["source_id"], previous["container_id"], previous["cursor_type"])
                    if self._cache.sync_identity.get(old_key) == row_id:
                        self._cache.sync_identity.pop(old_key, None)

            rows[row_id] = saved
            if group == "sources":
                self._cache.source_identity[(saved["source_type"], saved["account_identifier"].casefold())] = row_id
            elif group == "containers":
                self._cache.container_identity[(saved["source_id"], saved["external_id"])] = row_id
            elif group == "items":
                self._cache.item_identity[(saved["source_id"], saved["external_id"])] = row_id
                self._cache.item_ids_by_source.setdefault(saved["source_id"], set()).add(row_id)
                self._cache.item_ids_by_container.setdefault(saved["container_id"], set()).add(row_id)
            elif group == "sync_states":
                self._cache.sync_identity[(saved["source_id"], saved["container_id"], saved["cursor_type"])] = row_id
            self._cache.directory_signatures = self._cache_signatures()
            self._cache.revision += 1
            self._cache.last_poll = time.monotonic()

    def revision(self) -> int:
        """Return a cheap monotonic revision for UI query-cache invalidation."""
        self._ensure_cache()
        with self._cache.lock:
            return int(self._cache.revision)

    def has_items(self, source_id: str, *, include_deleted: bool = False) -> bool:
        """Return whether a source has any matching cached item without copying records."""
        self._ensure_cache()
        target = str(source_id or "").strip()
        with self._cache.lock:
            for row_id in self._cache.item_ids_by_source.get(target, set()):
                row = self._cache.items.get(row_id)
                if row is not None and (include_deleted or not bool(row.get("is_deleted"))):
                    return True
        return False

    def list_data_sources(self) -> list[dict[str, Any]]:
        self._ensure_cache()
        with self._cache.lock:
            rows = [copy.deepcopy(row) for row in self._cache.sources.values()]
        rows.sort(key=lambda row: (str(row["source_type"]), str(row["display_name"]).casefold(), row["id"]))
        return rows

    def get_data_source(self, source_id: str) -> dict[str, Any]:
        self._ensure_cache()
        with self._cache.lock:
            row = self._cache.sources.get(str(source_id or "").strip())
            if row is None:
                raise FileNotFoundError(f"Vault data source not found: {source_id}")
            return copy.deepcopy(row)

    def find_data_source(self, source_type: str, account_identifier: str) -> dict[str, Any] | None:
        self._ensure_cache()
        key = (str(source_type or "").strip().lower(), str(account_identifier or "").strip().casefold())
        with self._cache.lock:
            row_id = self._cache.source_identity.get(key)
            row = self._cache.sources.get(row_id or "")
            return copy.deepcopy(row) if row is not None else None

    def upsert_data_source(
        self,
        source_type: str,
        display_name: str,
        account_identifier: str,
        *,
        enabled: bool = True,
        connection_state: str = "not_configured",
        credential_reference: str = "",
        metadata: Any = None,
        source_id: str | None = None,
    ) -> dict[str, Any]:
        self._ensure_cache()
        existing = self.find_data_source(source_type, account_identifier)
        if existing is None:
            record = new_vault_data_source(
                source_type,
                display_name,
                account_identifier,
                enabled=enabled,
                connection_state=connection_state,
                credential_reference=credential_reference,
                metadata=metadata,
                source_id=source_id,
            )
        else:
            record = normalize_vault_data_source({
                "source_type": source_type,
                "display_name": display_name,
                "account_identifier": account_identifier,
                "enabled": bool(enabled),
                "connection_state": "disabled" if not enabled else connection_state,
                "credential_reference": credential_reference,
                "metadata": existing["metadata"] if metadata is None else metadata,
            }, existing=existing)
            if all(record[key] == existing[key] for key in record if key != "updated_at"):
                return existing
        saved = self._write_with_backup(
            self.paths.vault_source_json(record["id"]), record, validate_vault_data_source,
            location="Vault data source",
        )
        self._cache_put("sources", saved)
        return saved

    def update_data_source_sync_status(
        self,
        source_id: str,
        *,
        connection_state: str | None = None,
        started_at: str | None = None,
        completed_at: str | None = None,
        successful_at: str | None = None,
        error: str | None = None,
    ) -> dict[str, Any]:
        record = self.get_data_source(source_id)
        if connection_state is not None:
            state = str(connection_state).strip().lower()
            if state not in VAULT_CONNECTION_STATES:
                raise ValueError("Unsupported Vault connection state")
            record["connection_state"] = state
        for key, raw in (
            ("last_sync_started_at", started_at),
            ("last_sync_completed_at", completed_at),
            ("last_successful_sync_at", successful_at),
        ):
            if raw is not None:
                record[key] = normalize_timezone_safe_timestamp(raw, field_name=key, allow_empty=True)
        if error is not None:
            record["last_sync_error"] = str(error)
        record["updated_at"] = normalize_vault_timestamp(
            now_iso(), field_name="Vault source updated_at",
        )
        saved = self._write_with_backup(
            self.paths.vault_source_json(record["id"]), record, validate_vault_data_source,
            location="Vault data source",
        )
        self._cache_put("sources", saved)
        return saved

    def list_containers(self, source_id: str | None = None) -> list[dict[str, Any]]:
        self._ensure_cache()
        with self._cache.lock:
            rows = [
                copy.deepcopy(row) for row in self._cache.containers.values()
                if source_id is None or row["source_id"] == source_id
            ]
        rows.sort(key=lambda row: (row["container_type"], row["display_name"].casefold(), row["id"]))
        return rows

    def get_container(self, container_id: str) -> dict[str, Any]:
        self._ensure_cache()
        with self._cache.lock:
            row = self._cache.containers.get(str(container_id or "").strip())
            if row is None:
                raise FileNotFoundError(f"Vault Container not found: {container_id}")
            return copy.deepcopy(row)

    def find_container(self, source_id: str, external_id: str) -> dict[str, Any] | None:
        self._ensure_cache()
        target = (source_id, str(external_id or "").strip())
        with self._cache.lock:
            row_id = self._cache.container_identity.get(target)
            row = self._cache.containers.get(row_id or "")
            return copy.deepcopy(row) if row is not None else None

    def upsert_container(
        self,
        source_id: str,
        external_id: str,
        container_type: str,
        name: str,
        *,
        display_name: str = "",
        parent_container_id: str = "",
        is_archived: bool = False,
        is_hidden: bool = False,
        metadata: Any = None,
        container_id: str | None = None,
    ) -> dict[str, Any]:
        self.get_data_source(source_id)
        existing = self.find_container(source_id, external_id)
        if existing is None:
            record = new_vault_container(
                source_id,
                external_id,
                container_type,
                name,
                display_name=display_name,
                parent_container_id=parent_container_id,
                is_archived=is_archived,
                is_hidden=is_hidden,
                metadata=metadata,
                container_id=container_id,
            )
        else:
            record = normalize_vault_container({
                "source_id": source_id,
                "external_id": external_id,
                "container_type": container_type,
                "name": name,
                "display_name": display_name or name,
                "parent_container_id": None if not str(parent_container_id or "").strip() else str(parent_container_id).strip(),
                "is_archived": bool(is_archived),
                "is_hidden": bool(is_hidden),
                "metadata": existing["metadata"] if metadata is None else metadata,
            }, existing=existing)
            if all(record[key] == existing[key] for key in record if key != "updated_at"):
                return existing
        saved = self._write_with_backup(
            self.paths.vault_container_json(record["id"]), record, validate_vault_container,
            location="Vault Container",
        )
        self._cache_put("containers", saved)
        return saved

    def list_items(
        self,
        *,
        source_id: str | None = None,
        container_id: str | None = None,
        item_types: Iterable[str] | None = None,
        include_deleted: bool = True,
    ) -> list[dict[str, Any]]:
        self._ensure_cache()
        allowed_types = set(item_types) if item_types is not None else None
        with self._cache.lock:
            if container_id is not None:
                ids = set(self._cache.item_ids_by_container.get(str(container_id), set()))
            elif source_id is not None:
                ids = set(self._cache.item_ids_by_source.get(str(source_id), set()))
            else:
                ids = set(self._cache.items)
            rows: list[dict[str, Any]] = []
            for row_id in ids:
                row = self._cache.items.get(row_id)
                if row is None:
                    continue
                if source_id is not None and row["source_id"] != source_id:
                    continue
                if container_id is not None and row["container_id"] != container_id:
                    continue
                if allowed_types is not None and row["item_type"] not in allowed_types:
                    continue
                if not include_deleted and row["is_deleted"]:
                    continue
                rows.append(copy.deepcopy(row))
        return rows

    def get_item(self, item_id: str, *, include_deleted: bool = True) -> dict[str, Any]:
        self._ensure_cache()
        with self._cache.lock:
            row = self._cache.items.get(str(item_id or "").strip())
            if row is None or (row["is_deleted"] and not include_deleted):
                raise FileNotFoundError(f"Vault Item not found: {item_id}")
            return copy.deepcopy(row)

    def find_item(self, source_id: str, external_id: str) -> dict[str, Any] | None:
        self._ensure_cache()
        target = (source_id, str(external_id or "").strip())
        with self._cache.lock:
            row_id = self._cache.item_identity.get(target)
            row = self._cache.items.get(row_id or "")
            return copy.deepcopy(row) if row is not None else None

    def _resolve_parent_for_item(self, record: dict[str, Any]) -> dict[str, Any]:
        if record["parent_item_id"]:
            return record
        parent_external = str(record.get("metadata", {}).get("parent_external_id") or "").strip()
        if not parent_external:
            return record
        parent = self.find_item(record["source_id"], parent_external)
        if parent is not None:
            record["parent_item_id"] = parent["id"]
            record["content_hash"] = vault_content_hash_payload(record)
        return record

    def upsert_item(self, record: dict[str, Any]) -> dict[str, Any]:
        self._ensure_cache()
        validate_vault_item(record)
        self.get_data_source(record["source_id"])
        container = self.get_container(record["container_id"])
        if container["source_id"] != record["source_id"]:
            raise ValueError("Vault Item source does not match its Container")
        existing = self.find_item(record["source_id"], record["external_id"])
        candidate = copy.deepcopy(record)
        if existing is not None:
            candidate["id"] = existing["id"]
            candidate["first_synced_at"] = existing["first_synced_at"]
            candidate["last_seen_sync_generation"] = max(
                int(existing["last_seen_sync_generation"]),
                int(candidate["last_seen_sync_generation"]),
            )
            candidate["attachments"] = [
                normalize_vault_attachment(attachment, item_id=candidate["id"])
                for attachment in candidate["attachments"]
            ]
            candidate["content_hash"] = vault_content_hash_payload(candidate)
        candidate = self._resolve_parent_for_item(candidate)
        validate_vault_item(candidate)
        if existing is not None and candidate["content_hash"] == existing["content_hash"]:
            if candidate["last_seen_sync_generation"] == existing["last_seen_sync_generation"]:
                return existing
            # A successful newer synchronization generation must be durable even
            # when source content is unchanged, but it should not churn content IDs.
            candidate["last_synced_at"] = now_iso()
        saved = self._write_with_backup(
            self.paths.vault_item_json(candidate["id"]), candidate, validate_vault_item,
            location="Vault Item",
        )
        self._cache_put("items", saved)
        # A parent can arrive after its replies. Resolve those local references
        # without changing source identity.
        with self._cache.lock:
            pending_ids = [
                row["id"] for row in self._cache.items.values()
                if not row["parent_item_id"]
                and row["source_id"] == saved["source_id"]
                and str(row.get("metadata", {}).get("parent_external_id") or "") == saved["external_id"]
            ]
        for pending_id in pending_ids:
            pending = self.get_item(pending_id)
            pending["parent_item_id"] = saved["id"]
            pending["content_hash"] = vault_content_hash_payload(pending)
            pending_saved = self._write_with_backup(
                self.paths.vault_item_json(pending_id), pending, validate_vault_item,
                location="Vault Item",
            )
            self._cache_put("items", pending_saved)
        return saved

    def upsert_calendar_event(
        self,
        event: dict[str, Any],
        *,
        sync_generation: int = 0,
    ) -> dict[str, Any]:
        validate_calendar_event_record(event)
        account_id = str(event["external_account_id"])
        source = self.upsert_data_source(
            GOOGLE_CALENDAR_SOURCE_TYPE,
            account_id or "Google Calendar",
            account_id or "google-calendar",
            enabled=True,
            connection_state="connected" if account_id else "not_configured",
            credential_reference="credentials/google_calendar.cred",
            metadata={"provider": "google", "read_only": True},
        )
        calendar_external_id = str(event["external_calendar_id"])
        existing_container = self.find_container(source["id"], calendar_external_id)
        container_metadata = copy.deepcopy(existing_container.get("metadata", {})) if existing_container else {}
        container_metadata["calendar_id"] = calendar_external_id
        container = self.upsert_container(
            source["id"],
            calendar_external_id,
            "calendar",
            str(event["calendar_name"] or calendar_external_id),
            display_name=str(event["calendar_name"] or calendar_external_id),
            metadata=container_metadata,
        )
        relative = self.paths.calendar_event_json(event["event_id"]).relative_to(self.paths.root_dir).as_posix()
        item = calendar_event_to_vault_item(
            event,
            source["id"],
            container["id"],
            sync_generation=sync_generation,
            raw_payload_reference=relative,
        )
        return self.upsert_item(item)


    def upsert_gmail_message(
        self,
        source_id: str,
        container_id: str,
        payload: dict[str, Any],
        *,
        sync_generation: int = 0,
    ) -> dict[str, Any]:
        external_id = gmail_vault_external_id(payload)
        existing = self.find_item(source_id, external_id)
        item = gmail_payload_to_vault_item(
            payload,
            source_id,
            container_id,
            sync_generation=sync_generation,
            existing_item_id=existing["id"] if existing else None,
        )
        return self.upsert_item(item)

    def upsert_slack_message(
        self,
        source_id: str,
        container_id: str,
        payload: dict[str, Any],
        *,
        sync_generation: int = 0,
    ) -> dict[str, Any]:
        conversation_id = str(payload.get("conversation_id") or payload.get("channel") or "").strip()
        message_ts = str(payload.get("message_timestamp") or payload.get("ts") or "").strip()
        external_id = slack_vault_external_id(conversation_id, message_ts)
        existing = self.find_item(source_id, external_id)
        thread_ts = str(payload.get("thread_timestamp") or payload.get("thread_ts") or "").strip()
        parent = None
        if thread_ts and thread_ts != message_ts:
            parent = self.find_item(source_id, slack_vault_external_id(conversation_id, thread_ts))
        item = slack_payload_to_vault_item(
            payload,
            source_id,
            container_id,
            sync_generation=sync_generation,
            existing_item_id=existing["id"] if existing else None,
            parent_item_id=parent["id"] if parent else "",
        )
        return self.upsert_item(item)

    def list_sync_states(self, source_id: str | None = None) -> list[dict[str, Any]]:
        self._ensure_cache()
        with self._cache.lock:
            rows = [
                copy.deepcopy(row) for row in self._cache.sync_states.values()
                if source_id is None or row["source_id"] == source_id
            ]
        rows.sort(key=lambda row: (row["source_id"], str(row["container_id"] or ""), row["cursor_type"]))
        return rows

    def find_sync_state(
        self,
        source_id: str,
        container_id: str,
        cursor_type: str,
    ) -> dict[str, Any] | None:
        self._ensure_cache()
        normalized_container = None if not str(container_id or "").strip() else str(container_id).strip()
        target = (str(source_id or "").strip(), normalized_container, str(cursor_type or "").strip().lower())
        with self._cache.lock:
            row_id = self._cache.sync_identity.get(target)
            row = self._cache.sync_states.get(row_id or "")
            return copy.deepcopy(row) if row is not None else None

    def next_sync_generation(self, source_id: str, container_id: str = "") -> int:
        values = [
            row["sync_generation"] for row in self.list_sync_states(source_id)
            if not container_id or row["container_id"] == container_id
        ]
        return max(values, default=0) + 1

    def commit_sync_state(
        self,
        source_id: str,
        container_id: str,
        cursor_type: str,
        cursor_value: Any,
        sync_generation: int,
        *,
        metadata: Any = None,
        attempted_at: str | None = None,
        successful_at: str | None = None,
    ) -> dict[str, Any]:
        self.get_data_source(source_id)
        if container_id:
            self.get_container(container_id)
        existing = self.find_sync_state(source_id, container_id, cursor_type)
        record = existing or new_vault_sync_state(
            source_id,
            cursor_type,
            container_id=container_id,
            sync_state_id=None,
        )
        generation = int(sync_generation)
        if generation < record["sync_generation"]:
            raise ValueError("Vault sync generation cannot move backwards")
        record.update({
            "cursor_value": str(cursor_value or ""),
            "sync_generation": generation,
            "last_attempt_at": normalize_timezone_safe_timestamp(
                attempted_at or now_iso(), field_name="Vault sync attempt",
            ),
            "last_success_at": normalize_timezone_safe_timestamp(
                successful_at or now_iso(), field_name="Vault sync success",
            ),
            "last_error": "",
            "consecutive_failures": 0,
            "metadata": _vault_metadata(metadata),
        })
        saved = self._write_with_backup(
            self.paths.vault_sync_state_json(record["id"]), record, validate_vault_sync_state,
            location="Vault sync state",
        )
        self._cache_put("sync_states", saved)
        return saved

    def record_sync_failure(
        self,
        source_id: str,
        container_id: str,
        cursor_type: str,
        error: str,
        *,
        attempted_at: str | None = None,
    ) -> dict[str, Any]:
        self.get_data_source(source_id)
        if container_id:
            self.get_container(container_id)
        existing = self.find_sync_state(source_id, container_id, cursor_type)
        record = existing or new_vault_sync_state(
            source_id,
            cursor_type,
            container_id=container_id,
        )
        record["last_attempt_at"] = normalize_timezone_safe_timestamp(
            attempted_at or now_iso(), field_name="Vault sync attempt",
        )
        record["last_error"] = str(error or "Unknown synchronization failure")
        record["consecutive_failures"] += 1
        saved = self._write_with_backup(
            self.paths.vault_sync_state_json(record["id"]), record, validate_vault_sync_state,
            location="Vault sync state",
        )
        self._cache_put("sync_states", saved)
        return saved

    def reconcile_items(
        self,
        source_id: str,
        container_id: str,
        sync_generation: int,
        *,
        complete: bool,
        item_types: Iterable[str] | None = None,
    ) -> list[dict[str, Any]]:
        """Apply tombstones only after a logically complete reconciliation."""
        self.get_data_source(source_id)
        self.get_container(container_id)
        if not complete:
            return []
        return self.reconcile_generation(
            source_id, container_id, sync_generation, item_types=item_types,
        )

    def reconcile_generation(
        self,
        source_id: str,
        container_id: str,
        sync_generation: int,
        *,
        item_types: Iterable[str] | None = None,
    ) -> list[dict[str, Any]]:
        """Tombstone records absent from one explicitly completed reconciliation.

        Callers never invoke this after an incomplete or failed page sequence, so
        absence from a partial network response cannot delete local data.
        """
        generation = int(sync_generation)
        allowed_types = set(item_types or VAULT_ITEM_TYPES)
        changed: list[dict[str, Any]] = []
        for item in self.list_items(include_deleted=True):
            if item["source_id"] != source_id or item["container_id"] != container_id:
                continue
            if item["item_type"] not in allowed_types or item["last_seen_sync_generation"] >= generation:
                continue
            if item["is_deleted"]:
                continue
            item["is_deleted"] = True
            item["last_synced_at"] = now_iso()
            item["content_hash"] = vault_content_hash_payload(item)
            changed.append(self.upsert_item(item))
        return changed


class VaultQueryService:
    """Source-scoped, inclusive local date and case-insensitive Vault queries."""

    def __init__(self, vault_store: VaultStore, *, local_timezone: Any | None = None):
        self.store = vault_store
        self.local_timezone = local_timezone if local_timezone is not None else configured_vault_timezone(vault_store.storage)

    def list_data_sources(self) -> list[dict[str, Any]]:
        return self.store.list_data_sources()

    def get_data_source(self, source_id: str) -> dict[str, Any]:
        return self.store.get_data_source(source_id)

    @staticmethod
    def _optional_date(value: str | None, field_name: str) -> date | None:
        if value in (None, ""):
            return None
        return date.fromisoformat(normalize_iso_date(value, field_name=field_name))

    def _date_range(self, start_date: str | None, end_date: str | None) -> tuple[date | None, date | None]:
        start = self._optional_date(start_date, "Vault start date")
        end = self._optional_date(end_date, "Vault end date")
        if start is not None and end is not None and start > end:
            raise ValueError("Vault start date cannot follow end date")
        return start, end

    def _item_day_span(self, item: dict[str, Any]) -> tuple[date, date]:
        if item["item_type"] == "calendar_event" and item["is_all_day"]:
            metadata = item.get("metadata", {})
            start_text = str(
                metadata.get("all_day_start_date")
                or item.get("start_timestamp")
                or item.get("primary_timestamp")
                or ""
            )
            end_text = str(
                metadata.get("all_day_end_date_exclusive")
                or item.get("end_timestamp")
                or ""
            )
            if start_text:
                start = date.fromisoformat(start_text)
                end = date.fromisoformat(end_text) - timedelta(days=1) if end_text else start
                return start, max(start, end)
        start_dt = _parse_iso_datetime(item["primary_timestamp"], field_name="Vault primary timestamp")
        start_local = start_dt.astimezone(self.local_timezone).date()
        if item["item_type"] == "calendar_event" and item["end_timestamp"]:
            end_dt = _parse_iso_datetime(item["end_timestamp"], field_name="Vault end timestamp")
            end_local = (end_dt.astimezone(self.local_timezone) - timedelta(microseconds=1)).date()
            return start_local, max(start_local, end_local)
        return start_local, start_local

    def _in_date_range(
        self,
        item: dict[str, Any],
        start: date | None,
        end: date | None,
    ) -> bool:
        item_start, item_end = self._item_day_span(item)
        if start is not None and item_end < start:
            return False
        if end is not None and item_start > end:
            return False
        return True

    def _search_text(self, item: dict[str, Any], container: dict[str, Any] | None) -> str:
        fields = [item["title"], item["summary"], item["body_text"], item["author_display_name"]]
        metadata = item.get("metadata", {})
        if item["item_type"] == "calendar_event":
            fields.extend([
                str(metadata.get("location") or ""),
                str(metadata.get("calendar_display_name") or ""),
            ])
            for participant in item["participants"]:
                fields.extend([participant["display_name"], participant["email"]])
        elif item["item_type"] == "google_drive_file":
            fields.extend([
                str(metadata.get("mime_type") or ""),
                str(metadata.get("original_filename") or ""),
                " ".join(str(row) for row in metadata.get("path_labels", []) if str(row)),
            ])
            for participant in item["participants"]:
                fields.extend([participant["display_name"], participant["email"]])
        elif item["item_type"] == "gmail_message":
            fields.append(str(metadata.get("subject") or ""))
            for participant in item["participants"]:
                if participant["role"] in {"sender", "recipient", "cc"}:
                    fields.extend([participant["display_name"], participant["email"]])
        elif item["item_type"] in {"slack_message", "slack_thread_reply"}:
            if container is not None:
                fields.extend([container["name"], container["display_name"]])
        return "\n".join(str(field or "") for field in fields).casefold()

    def _filtered_items(
        self,
        source_id: str,
        item_types: set[str],
        start_date: str | None,
        end_date: str | None,
        search_text: str,
        *,
        container_id: str | None = None,
    ) -> list[dict[str, Any]]:
        source = self.store.get_data_source(source_id)
        start, end = self._date_range(start_date, end_date)
        needle = str(search_text or "").strip().casefold()
        containers = {row["id"]: row for row in self.store.list_containers(source_id)}
        rows: list[dict[str, Any]] = []
        for item in self.store.list_items(
            source_id=source["id"],
            container_id=container_id,
            item_types=item_types,
            include_deleted=False,
        ):
            if not self._in_date_range(item, start, end):
                continue
            if needle and needle not in self._search_text(item, containers.get(item["container_id"])):
                continue
            rows.append(item)
        return rows

    def list_calendar_days(
        self,
        source_id: str,
        start_date: str | None = None,
        end_date: str | None = None,
        search_text: str = "",
    ) -> list[str]:
        start, end = self._date_range(start_date, end_date)
        rows = self._filtered_items(
            source_id, {"calendar_event"}, start_date, end_date, search_text,
        )
        days: set[date] = set()
        for item in rows:
            item_start, item_end = self._item_day_span(item)
            cursor = max(item_start, start) if start is not None else item_start
            final = min(item_end, end) if end is not None else item_end
            while cursor <= final:
                days.add(cursor)
                cursor += timedelta(days=1)
        return [day.isoformat() for day in sorted(days)]

    def list_calendar_events_for_day(
        self,
        source_id: str,
        day: str,
        search_text: str = "",
    ) -> list[dict[str, Any]]:
        day_value = normalize_iso_date(day, field_name="Vault Calendar day")
        rows = self._filtered_items(
            source_id, {"calendar_event"}, day_value, day_value, search_text,
        )
        rows.sort(key=lambda item: (
            0 if item["is_all_day"] else 1,
            item["start_timestamp"] or item["primary_timestamp"],
            item["title"].casefold(),
            item["id"],
        ))
        return rows

    def list_gmail_messages(
        self,
        source_id: str,
        start_date: str | None = None,
        end_date: str | None = None,
        search_text: str = "",
    ) -> list[dict[str, Any]]:
        rows = self._filtered_items(
            source_id, {"gmail_message"}, start_date, end_date, search_text,
        )
        rows.sort(key=lambda item: (item["primary_timestamp"], item["id"]), reverse=True)
        return rows

    def get_gmail_message(self, item_id: str) -> dict[str, Any]:
        item = self.store.get_item(item_id, include_deleted=False)
        if item["item_type"] != "gmail_message":
            raise ValueError("Vault Item is not a Gmail message")
        return item

    def list_google_drive_files(
        self,
        source_id: str,
        start_date: str | None = None,
        end_date: str | None = None,
        search_text: str = "",
    ) -> list[dict[str, Any]]:
        rows = self._filtered_items(
            source_id, {"google_drive_file"}, start_date, end_date, search_text,
        )
        rows.sort(key=lambda item: (
            0 if bool(item.get("metadata", {}).get("is_folder")) else 1,
            -(datetime.fromisoformat(item["primary_timestamp"].replace("Z", "+00:00")).timestamp()),
            item["title"].casefold(),
            item["id"],
        ))
        return rows

    def get_google_drive_file(self, item_id: str) -> dict[str, Any]:
        item = self.store.get_item(item_id, include_deleted=False)
        if item["item_type"] != "google_drive_file":
            raise ValueError("Vault Item is not a Google Drive file")
        return item


    def list_slack_channels(
        self,
        source_id: str,
        start_date: str | None = None,
        end_date: str | None = None,
        search_text: str = "",
    ) -> list[dict[str, Any]]:
        rows = self._filtered_items(
            source_id,
            {"slack_message", "slack_thread_reply"},
            start_date,
            end_date,
            search_text,
        )
        aggregates: dict[str, dict[str, Any]] = {}
        containers = {row["id"]: row for row in self.store.list_containers(source_id)}
        for item in rows:
            container = containers.get(item["container_id"])
            if container is None or container["is_archived"] or container["is_hidden"]:
                continue
            current = aggregates.get(item["container_id"])
            if current is None:
                current = copy.deepcopy(container)
                current.update({
                    "matching_message_count": 0,
                    "latest_matching_message_timestamp": "",
                })
                aggregates[item["container_id"]] = current
            current["matching_message_count"] += 1
            current["latest_matching_message_timestamp"] = max(
                current["latest_matching_message_timestamp"], item["primary_timestamp"],
            )
        result = list(aggregates.values())
        result.sort(key=lambda row: (
            -_parse_iso_datetime(row["latest_matching_message_timestamp"], field_name="Slack latest timestamp").timestamp(),
            row["display_name"].casefold(),
            row["id"],
        ))
        return result

    def list_slack_messages(
        self,
        source_id: str,
        channel_id: str,
        start_date: str | None = None,
        end_date: str | None = None,
        search_text: str = "",
    ) -> list[dict[str, Any]]:
        self.store.get_container(channel_id)
        rows = self._filtered_items(
            source_id,
            {"slack_message", "slack_thread_reply"},
            start_date,
            end_date,
            search_text,
            container_id=channel_id,
        )
        visible_ids = {row["id"] for row in rows}
        normalized: list[dict[str, Any]] = []
        for item in rows:
            row = copy.deepcopy(item)
            row["indentation_depth"] = 1 if row["item_type"] == "slack_thread_reply" else 0
            row["parent_outside_range"] = bool(
                row["parent_item_id"] and row["parent_item_id"] not in visible_ids
            )
            normalized.append(row)

        # Present visible replies immediately under their visible parent while
        # keeping parent groups and orphan replies chronologically ordered. A
        # reply whose parent is outside the current filter remains a standalone
        # indented row with parent_outside_range=True.
        parents = [row for row in normalized if row["item_type"] != "slack_thread_reply"]
        replies_by_parent: dict[str, list[dict[str, Any]]] = {}
        orphan_replies: list[dict[str, Any]] = []
        parent_ids = {row["id"] for row in parents}
        for row in normalized:
            if row["item_type"] != "slack_thread_reply":
                continue
            parent_id = str(row.get("parent_item_id") or "")
            if parent_id and parent_id in parent_ids:
                replies_by_parent.setdefault(parent_id, []).append(row)
            else:
                orphan_replies.append(row)
        for reply_rows in replies_by_parent.values():
            reply_rows.sort(key=lambda item: (item["primary_timestamp"], item["id"]))

        blocks: list[tuple[str, str, list[dict[str, Any]]]] = []
        for parent in parents:
            blocks.append((
                str(parent["primary_timestamp"]), str(parent["id"]),
                [parent, *replies_by_parent.get(str(parent["id"]), [])],
            ))
        for reply in orphan_replies:
            blocks.append((str(reply["primary_timestamp"]), str(reply["id"]), [reply]))
        blocks.sort(key=lambda block: (block[0], block[1]))
        return [row for _timestamp, _row_id, block in blocks for row in block]

    def get_visible_item_count(
        self,
        source_id: str,
        start_date: str | None = None,
        end_date: str | None = None,
        search_text: str = "",
        container_id: str | None = None,
    ) -> int:
        """Return the source-specific count shown in the data browser.

        Count days for Calendar, messages for Gmail, and conversations for Slack.
        Within a selected Slack container, count its messages and replies."""
        source = self.store.get_data_source(source_id)
        source_type = source["source_type"]
        if source_type == "google_calendar":
            return len(self.list_calendar_days(source_id, start_date, end_date, search_text))
        if source_type == "google_drive":
            return len(self._filtered_items(
                source_id,
                {"google_drive_file"},
                start_date,
                end_date,
                search_text,
                container_id=container_id,
            ))
        if source_type == "gmail":
            return len(self._filtered_items(
                source_id,
                {"gmail_message"},
                start_date,
                end_date,
                search_text,
                container_id=container_id,
            ))
        if source_type == "slack" and container_id:
            return len(self.list_slack_messages(
                source_id,
                container_id,
                start_date,
                end_date,
                search_text,
            ))
        if source_type == "slack":
            return len(self.list_slack_channels(source_id, start_date, end_date, search_text))
        raise ValueError(f"Unsupported Vault source type: {source_type}")

def normalize_vault_divider_fraction(value: Any) -> float:
    """Validate the persisted Vault split without hiding corrupt settings."""
    try:
        fraction = float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError("Vault divider fraction must be numeric") from exc
    if not math.isfinite(fraction) or not 0.18 <= fraction <= 0.72:
        raise ValueError("Vault divider fraction must be between 0.18 and 0.72")
    return fraction


def validate_vault_connector_settings(vault_config: Any) -> dict[str, Any]:
    """Validate strict Google Drive, Gmail, and Slack connector settings."""
    if not isinstance(vault_config, dict):
        raise ValueError("Vault settings must be an object")
    calendar = vault_config.get("google_calendar")
    drive = vault_config.get("google_drive")
    gmail = vault_config.get("gmail")
    slack = vault_config.get("slack")
    expected_calendar = set(default_config()["vault"]["google_calendar"])
    expected_drive = set(default_config()["vault"]["google_drive"])
    expected_gmail = set(default_config()["vault"]["gmail"])
    expected_slack = set(default_config()["vault"]["slack"])
    if not isinstance(calendar, dict) or set(calendar) != expected_calendar:
        raise ValueError("Google Calendar connector settings do not match the current model")
    if not isinstance(drive, dict) or set(drive) != expected_drive:
        raise ValueError("Google Drive connector settings do not match the current model")
    if not isinstance(gmail, dict) or set(gmail) != expected_gmail:
        raise ValueError("Gmail connector settings do not match the current model")
    if not isinstance(slack, dict) or set(slack) != expected_slack:
        raise ValueError("Slack connector settings do not match the current model")
    sync_window_days = calendar.get("sync_window_days")
    if (
        isinstance(sync_window_days, bool) or not isinstance(sync_window_days, int)
        or not (GOOGLE_CALENDAR_SYNC_WINDOW_DAYS_MIN <= sync_window_days <= GOOGLE_CALENDAR_SYNC_WINDOW_DAYS_MAX)
    ):
        raise ValueError(
            f"Google Calendar sync window must be an integer from {GOOGLE_CALENDAR_SYNC_WINDOW_DAYS_MIN} "
            f"to {GOOGLE_CALENDAR_SYNC_WINDOW_DAYS_MAX} days"
        )
    if not isinstance(drive.get("include_shared_drives"), bool):
        raise ValueError("Google Drive connector setting include_shared_drives must be a boolean")
    normalize_vault_divider_fraction(drive.get("divider_fraction"))
    for key in ("enabled", "include_spam", "include_trash"):
        if not isinstance(gmail.get(key), bool):
            raise ValueError(f"Gmail connector setting {key} must be a boolean")
    for key in (
        "enabled", "include_public_channels", "include_private_channels",
        "include_direct_messages", "include_group_direct_messages",
    ):
        if not isinstance(slack.get(key), bool):
            raise ValueError(f"Slack connector setting {key} must be a boolean")
    for label, value, minimum in (
        ("Gmail initial history days", gmail.get("initial_history_days"), 0),
        ("Gmail sync interval minutes", gmail.get("sync_interval_minutes"), 1),
        ("Slack initial history days", slack.get("initial_history_days"), 0),
        ("Slack sync interval minutes", slack.get("sync_interval_minutes"), 1),
    ):
        if isinstance(value, bool) or not isinstance(value, int) or value < minimum:
            raise ValueError(f"{label} must be an integer of at least {minimum}")
    redirect_uri = str(slack.get("redirect_uri") or "").strip()
    parsed = urllib.parse.urlparse(redirect_uri)
    if parsed.scheme != "http" or parsed.hostname not in {"127.0.0.1", "localhost"} or not parsed.port:
        raise ValueError("Slack redirect URI must be an http://127.0.0.1 or localhost URL with a port")
    return vault_config


def format_vault_day_label(value: Any) -> str:
    parsed = date.fromisoformat(normalize_iso_date(value, field_name="Vault day"))
    return parsed.strftime("%a %d/%m/%y")


def vault_local_datetime(value: Any, local_timezone: Any) -> datetime | None:
    raw = str(value or "").strip()
    if not raw or re.fullmatch(r"\d{4}-\d{2}-\d{2}", raw):
        return None
    return _parse_iso_datetime(raw, field_name="Vault timestamp").astimezone(local_timezone)


def format_vault_local_timestamp(value: Any, local_timezone: Any, *, include_date: bool = True) -> str:
    dt = vault_local_datetime(value, local_timezone)
    if dt is None:
        raw = str(value or "").strip()
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", raw):
            return date.fromisoformat(raw).strftime("%d/%m/%y")
        return ""
    return dt.strftime("%d/%m/%y %H:%M" if include_date else "%H:%M")


def human_bytes(value: Any) -> str:
    """Format a non-negative byte count for compact read-only metadata."""
    try:
        size = max(0, int(value or 0))
    except (TypeError, ValueError):
        size = 0
    units = ("B", "KiB", "MiB", "GiB", "TiB")
    amount = float(size)
    for unit in units:
        if amount < 1024.0 or unit == units[-1]:
            if unit == "B":
                return f"{int(amount)} {unit}"
            return f"{amount:.1f} {unit}"
        amount /= 1024.0
    return f"{size} B"


def google_drive_type_label(
    mime_type: Any,
    *,
    is_folder: bool = False,
    entry_kind: Any = "",
) -> str:
    """Return a concise human name for common Google Drive and Office formats."""
    if str(entry_kind or "").strip().lower() == "drive":
        return "Drive"
    if bool(is_folder):
        return "Folder"
    normalized = str(mime_type or "").strip().lower()
    if not normalized:
        return "File"
    mapped = GOOGLE_DRIVE_MIME_TYPE_LABELS.get(normalized)
    if mapped:
        return mapped
    if "/" in normalized:
        family, subtype = normalized.split("/", 1)
        cleaned = subtype.removeprefix("vnd.").replace("x-", "").replace("+xml", "")
        cleaned = re.sub(r"[._+-]+", " ", cleaned).strip()
        base = cleaned.title() or "File"
        if family == "image":
            return f"{base} image"
        if family == "video":
            return f"{base} video"
        if family == "audio":
            return f"{base} audio"
        if family == "text":
            return f"{base} text"
        return base
    return normalized.replace("_", " ").replace("-", " ").title() or "File"


def _vault_source_status_word(
    source: dict[str, Any] | None, status: dict[str, Any] | None,
) -> str:
    status = status if isinstance(status, dict) else {}
    if bool(status.get("operation_in_progress")) or str((source or {}).get("connection_state") or "") == "syncing":
        return "Syncing"
    if str(status.get("last_error") or "").strip() or str((source or {}).get("connection_state") or "") == "error":
        return "Error"
    if source is not None and not bool(source.get("enabled", True)):
        return "Disabled"
    connected = bool(status.get("connected")) or str((source or {}).get("connection_state") or "") == "connected"
    if connected:
        if str((source or {}).get("last_successful_sync_at") or "").strip():
            return "Synced"
        return "Connected"
    if bool(status.get("configured")):
        return "Not connected"
    return "Not connected"


def vault_source_option_rows(
    sources: Iterable[dict[str, Any]],
    status_by_type: dict[str, dict[str, Any]] | None = None,
) -> list[dict[str, Any]]:
    """Return exactly one concise option for each supported Vault source type."""
    grouped: dict[str, list[dict[str, Any]]] = {source_type: [] for source_type in VAULT_SOURCE_ORDER}
    for source in sources:
        source_type = str(source.get("source_type") or "")
        if source_type in grouped:
            grouped[source_type].append(copy.deepcopy(source))
    statuses = status_by_type if isinstance(status_by_type, dict) else {}
    rows: list[dict[str, Any]] = []
    state_rank = {"syncing": 4, "connected": 3, "error": 2, "not_configured": 1, "disabled": 0}
    for source_type in VAULT_SOURCE_ORDER:
        candidates = grouped[source_type]
        source = max(
            candidates,
            key=lambda row: (
                1 if bool(row.get("enabled", True)) else 0,
                state_rank.get(str(row.get("connection_state") or ""), -1),
                str(row.get("last_successful_sync_at") or row.get("updated_at") or ""),
                str(row.get("id") or ""),
            ),
            default=None,
        )
        status = statuses.get(source_type) if isinstance(statuses.get(source_type), dict) else {}
        word = _vault_source_status_word(source, status)
        configured = bool(source is not None or status.get("configured") or status.get("connected"))
        synthetic = source is None
        source_id = str(source.get("id") or "") if source is not None else f"adhoc:{source_type}"
        rows.append({
            "label": f"{VAULT_SOURCE_SHORT_LABELS[source_type]} [{word}]",
            "source_type": source_type,
            "source_id": source_id,
            "configured": configured,
            "enabled": bool(source.get("enabled", True)) if source is not None else configured,
            "source": source,
            "synthetic": synthetic,
            "status": copy.deepcopy(status),
        })
    return rows


@dataclass(frozen=True)
class VaultToolbarLayout:
    source: Rect
    search: Rect
    start_picker: Rect
    dash: Rect
    end_picker: Rect
    clear: Rect


def vault_toolbar_layout(rect: Rect, *, line_h: int = 20) -> VaultToolbarLayout:
    gap = VAULT_TOOLBAR_GAP
    control_h = max(34, min(rect.h - 8, int(line_h) + 16))
    y = rect.y + max(4, (rect.h - control_h) // 2)
    clear_w = 36
    dash_w = 14
    # The source selector is intentionally 70% wider than the earlier 160–240px
    # control so concise source/status labels remain readable. Search flexes first.
    source_w = int(clamp(round(rect.w * 0.30), 272, 408))
    date_w = int(clamp(round(rect.w * 0.19), 196, 260))
    fixed = source_w + date_w * 2 + dash_w + clear_w + gap * 5
    search_w = max(96, rect.w - fixed)
    if rect.w < fixed + 96:
        deficit = fixed + 96 - rect.w
        date_reduction = min(max(0, date_w - 168), (deficit + 1) // 2)
        date_w -= date_reduction
        deficit -= date_reduction * 2
        if deficit > 0:
            source_w = max(190, source_w - deficit)
        fixed = source_w + date_w * 2 + dash_w + clear_w + gap * 5
        search_w = max(72, rect.w - fixed)
    x = rect.x
    source = Rect(x, y, source_w, control_h)
    x += source.w + gap
    search = Rect(x, y, search_w, control_h)
    x += search.w + gap
    start_picker = Rect(x, y, date_w, control_h)
    x += date_w + gap
    dash = Rect(x, y, dash_w, control_h)
    x += dash_w + gap
    end_picker = Rect(x, y, date_w, control_h)
    x += date_w + gap
    clear = Rect(x, y, max(1, rect.x + rect.w - x), control_h)
    return VaultToolbarLayout(source, search, start_picker, dash, end_picker, clear)


@dataclass(frozen=True)
class VaultUILayout:
    toolbar: Rect
    left_header: Rect
    right_header: Rect
    left_body: Rect
    right_body: Rect
    divider: Rect


def vault_layout_for_rect(rect: Rect, divider_fraction: float, *, line_h: int = 20) -> VaultUILayout:
    fraction = normalize_vault_divider_fraction(divider_fraction)
    gap = 8
    toolbar_h = max(48, int(line_h) + 22)
    header_h = max(38, int(line_h) + 16)
    toolbar = Rect(rect.x, rect.y, rect.w, max(1, min(toolbar_h, rect.h)))
    body_y = toolbar.y + toolbar.h + gap
    body_h = max(1, rect.y + rect.h - body_y)
    divider_w = 6
    available = max(2, rect.w - divider_w)
    if available >= VAULT_DIVIDER_MIN_LEFT_PX + VAULT_DIVIDER_MIN_RIGHT_PX:
        left_w = int(clamp(round(available * fraction), VAULT_DIVIDER_MIN_LEFT_PX, available - VAULT_DIVIDER_MIN_RIGHT_PX))
    else:
        minimum_left = min(180, max(96, available // 3))
        minimum_right = min(260, max(120, available // 2))
        left_w = int(clamp(round(available * fraction), minimum_left, max(minimum_left, available - minimum_right)))
    right_w = max(1, available - left_w)
    left_header = Rect(rect.x, body_y, left_w, min(header_h, body_h))
    divider = Rect(left_header.x + left_header.w, body_y, divider_w, body_h)
    right_header = Rect(divider.x + divider.w, body_y, right_w, min(header_h, body_h))
    left_body = Rect(left_header.x, left_header.y + left_header.h, left_header.w, max(1, body_h - left_header.h))
    right_body = Rect(right_header.x, right_header.y + right_header.h, right_header.w, max(1, body_h - right_header.h))
    return VaultUILayout(toolbar, left_header, right_header, left_body, right_body, divider)


def vault_visible_row_range(scroll_y: int, row_h: int, row_count: int, viewport_h: int, *, overscan: int = 2) -> tuple[int, int]:
    if row_count <= 0 or row_h <= 0 or viewport_h <= 0:
        return 0, 0
    start = max(0, int(scroll_y) // int(row_h) - max(0, int(overscan)))
    end = min(int(row_count), (int(scroll_y) + int(viewport_h)) // int(row_h) + max(1, int(overscan)) + 1)
    return start, end


class VaultUIController:
    """Debounced, revision-aware query cache for the read-only Vault screen."""

    def __init__(
        self, query: VaultQueryService,
        status_provider: Callable[[], dict[str, dict[str, Any]]] | None = None,
    ):
        self.query = query
        self.status_provider = status_provider
        self._source_options_key: tuple[Any, ...] | None = None
        self._source_statuses: dict[str, dict[str, Any]] = {}
        self._source_status_polled_at = 0.0
        self._source_options: list[dict[str, Any]] = []
        self._left_key: tuple[Any, ...] | None = None
        self._left_rows: list[dict[str, Any]] = []
        self._left_row_ids: frozenset[str] = frozenset()
        self._left_first_id = ""
        self._right_key: tuple[Any, ...] | None = None
        self._right_rows: list[dict[str, Any]] = []
        self._source_data_key: tuple[int, str] | None = None
        self._source_has_data = False
        self.query_count = 0

    def clear(self) -> None:
        self._source_options_key = None
        self._source_options = []
        self._left_key = None
        self._left_rows = []
        self._left_row_ids = frozenset()
        self._left_first_id = ""
        self._right_key = None
        self._right_rows = []
        self._source_data_key = None
        self._source_has_data = False

    def revision(self) -> int:
        try:
            return int(self.query.store.revision())
        except Exception:
            return 0

    def source_options(self) -> list[dict[str, Any]]:
        revision = self.revision()
        now_mono = time.monotonic()
        if callable(self.status_provider) and (
            not self._source_statuses or now_mono - self._source_status_polled_at >= 1.0
        ):
            try:
                statuses = self.status_provider()
                self._source_statuses = copy.deepcopy(statuses if isinstance(statuses, dict) else {})
            except Exception:
                self._source_statuses = {}
            self._source_status_polled_at = now_mono
        status_key = tuple(
            (source_type, json.dumps(self._source_statuses.get(source_type, {}), ensure_ascii=False, sort_keys=True, default=str))
            for source_type in VAULT_SOURCE_ORDER
        )
        cache_key = (revision, status_key)
        if self._source_options_key != cache_key:
            self._source_options = vault_source_option_rows(
                self.query.list_data_sources(), self._source_statuses,
            )
            self._source_options_key = cache_key
        return self._source_options

    def resolve_source(self, source_type: str, source_id: str = "") -> tuple[dict[str, Any] | None, dict[str, Any]]:
        requested_type = source_type if source_type in VAULT_SOURCE_ORDER else VAULT_SOURCE_ORDER[0]
        requested_id = str(source_id or "").strip()
        options = self.source_options()
        # A persisted source ID is meaningful only inside its source type. A
        # stale Gmail ID supplied while switching to Drive must not silently
        # override the requested type and render the wrong panes.
        chosen = next((
            row for row in options
            if requested_id
            and row["source_type"] == requested_type
            and row["source_id"] == requested_id
        ), None)
        if chosen is None:
            chosen = next((row for row in options if row["source_type"] == requested_type and row["configured"]), None)
        if chosen is None:
            chosen = next(row for row in options if row["source_type"] == requested_type)
        source = chosen.get("source") if isinstance(chosen.get("source"), dict) else None
        return source, chosen

    def _left_query(self, source_type: str, source_id: str, start_date: str | None, end_date: str | None, search_text: str) -> list[dict[str, Any]]:
        self.query_count += 1
        if source_type == "google_calendar":
            return [
                {"id": day_value, "day": day_value, "label": format_vault_day_label(day_value)}
                for day_value in self.query.list_calendar_days(source_id, start_date, end_date, search_text)
            ]
        if source_type == "google_drive":
            return self.query.list_google_drive_files(source_id, start_date, end_date, search_text)
        if source_type == "gmail":
            return self.query.list_gmail_messages(source_id, start_date, end_date, search_text)
        if source_type == "slack":
            return self.query.list_slack_channels(source_id, start_date, end_date, search_text)
        return []

    def _right_query(self, source_type: str, source_id: str, selected_id: str, start_date: str | None, end_date: str | None, search_text: str) -> list[dict[str, Any]]:
        if not selected_id:
            return []
        self.query_count += 1
        if source_type == "google_calendar":
            return self.query.list_calendar_events_for_day(source_id, selected_id, search_text)
        if source_type == "google_drive":
            try:
                return [self.query.get_google_drive_file(selected_id)]
            except FileNotFoundError:
                return []
        if source_type == "gmail":
            try:
                return [self.query.get_gmail_message(selected_id)]
            except FileNotFoundError:
                return []
        if source_type == "slack":
            return self.query.list_slack_messages(source_id, selected_id, start_date, end_date, search_text)
        return []

    def load(
        self,
        source_type: str,
        source_id: str,
        start_date: str | None,
        end_date: str | None,
        search_text: str,
        selected_id: str,
    ) -> dict[str, Any]:
        source, option = self.resolve_source(source_type, source_id)
        resolved_type = str(option["source_type"])
        resolved_id = str(option["source_id"])
        revision = self.revision()
        if bool(option.get("synthetic")) or resolved_type == GOOGLE_DRIVE_SOURCE_TYPE:
            return {
                "source_type": resolved_type,
                "source_id": resolved_id,
                "source": source,
                "option": option,
                "left_rows": [],
                "right_rows": [],
                "selected_id": "",
                "visible_count": 0,
                "has_any_data": False,
            }
        if not resolved_id:
            return {
                "source_type": resolved_type,
                "source_id": "",
                "source": None,
                "option": option,
                "left_rows": [],
                "right_rows": [],
                "selected_id": "",
                "visible_count": 0,
                "has_any_data": False,
            }
        left_key = (revision, resolved_type, resolved_id, start_date or "", end_date or "", str(search_text or ""))
        if self._left_key != left_key:
            self._left_rows = self._left_query(resolved_type, resolved_id, start_date, end_date, search_text)
            self._left_row_ids = frozenset(
                str(row.get("id") or "") for row in self._left_rows if str(row.get("id") or "")
            )
            self._left_first_id = str(self._left_rows[0].get("id") or "") if self._left_rows else ""
            self._left_key = left_key
            self._right_key = None
        # Cached query rows are immutable to the UI. Return their list reference so
        # a 10,000-message result is not copied every rendered frame. Selection
        # membership is indexed once per query revision rather than rebuilding a
        # second 10,000-element ID list on every frame.
        left_rows = self._left_rows
        resolved_selected = str(selected_id or "")
        if resolved_selected not in self._left_row_ids:
            resolved_selected = self._left_first_id
        right_key = left_key + (resolved_selected,)
        if self._right_key != right_key:
            self._right_rows = self._right_query(
                resolved_type, resolved_id, resolved_selected, start_date, end_date, search_text,
            )
            self._right_key = right_key
        source_data_key = (revision, resolved_id)
        if self._source_data_key != source_data_key:
            self._source_has_data = self.query.store.has_items(resolved_id, include_deleted=False)
            self._source_data_key = source_data_key
        return {
            "source_type": resolved_type,
            "source_id": resolved_id,
            "source": source,
            "option": option,
            "left_rows": left_rows,
            "right_rows": self._right_rows,
            "selected_id": resolved_selected,
            "visible_count": len(left_rows),
            "has_any_data": bool(self._source_has_data),
        }


CALENDAR_CACHE_EXTERNAL_POLL_SECONDS = 1.0
CALENDAR_CACHE_MAX_INDEXED_EVENT_DAYS = 3660


@dataclass
class CalendarRecordCache:
    """Shared, mutation-aware in-memory indexes for one Velox data root.

    The Calendar UI renders every frame. Reading and parsing every Event and Item
    JSON file from that render path made a synchronized Calendar unusable. The
    cache is shared by every CalendarStore for the same root, updated immediately
    after Velox writes, and checks directory metadata at a bounded cadence so a
    manual external edit is still noticed without turning each frame into a disk
    scan.
    """

    lock: threading.RLock = field(default_factory=threading.RLock)
    events_loaded: bool = False
    items_loaded: bool = False
    event_dir_signature: tuple[int, int, int] = (0, 0, 0)
    item_dir_signature: tuple[int, int, int] = (0, 0, 0)
    last_event_poll: float = 0.0
    last_item_poll: float = 0.0
    events: dict[str, dict[str, Any]] = field(default_factory=dict)
    event_file_signatures: dict[str, tuple[int, int, int]] = field(default_factory=dict)
    event_date_ids: dict[str, set[str]] = field(default_factory=dict)
    long_event_ids: set[str] = field(default_factory=set)
    event_index_timezone_key: str = ""
    display_timezone_key: str = ""
    display_timezone: Any = None
    last_timezone_poll: float = 0.0
    items: dict[str, dict[str, Any]] = field(default_factory=dict)
    item_file_signatures: dict[str, tuple[int, int, int]] = field(default_factory=dict)
    scheduled_item_ids: dict[str, set[str]] = field(default_factory=dict)
    backlog_item_ids: set[str] = field(default_factory=set)
    google_sync_loaded: bool = False
    google_sync_signature: tuple[int, int, int] = (0, 0, 0)
    google_sync_state: dict[str, Any] = field(default_factory=dict)
    last_google_sync_poll: float = 0.0


_CALENDAR_RECORD_CACHES: dict[str, CalendarRecordCache] = {}
_CALENDAR_RECORD_CACHES_LOCK = threading.RLock()


def calendar_record_cache_for_root(root_dir: Path) -> CalendarRecordCache:
    key = os.path.normcase(str(Path(root_dir).expanduser().resolve()))
    with _CALENDAR_RECORD_CACHES_LOCK:
        cache = _CALENDAR_RECORD_CACHES.get(key)
        if cache is None:
            cache = CalendarRecordCache()
            _CALENDAR_RECORD_CACHES[key] = cache
        return cache


# =============================================================================
# Read-only Gmail and Slack connectors
# =============================================================================


class ConnectorCancelledError(RuntimeError):
    pass


class SlackAPIError(RuntimeError):
    def __init__(self, error: str, *, status: int = 0, missing_scope: str = ""):
        self.error = str(error or "unknown_error")
        self.status = int(status or 0)
        self.missing_scope = str(missing_scope or "")
        message = self.error
        if self.missing_scope:
            message += f" (missing scope: {self.missing_scope})"
        super().__init__(message)


def _connector_now() -> str:
    return now_iso()


def _decode_email_header(value: Any) -> str:
    raw = str(value or "")
    if not raw:
        return ""
    parts: list[str] = []
    try:
        decoded = decode_header(raw)
    except Exception:
        return raw
    for fragment, charset in decoded:
        if isinstance(fragment, bytes):
            for candidate in (charset, "utf-8", "latin-1"):
                if not candidate:
                    continue
                try:
                    parts.append(fragment.decode(candidate, errors="replace"))
                    break
                except (LookupError, UnicodeError):
                    continue
            else:
                parts.append(fragment.decode("utf-8", errors="replace"))
        else:
            parts.append(str(fragment))
    return "".join(parts).strip()


def _email_address_rows(value: Any) -> list[dict[str, str]]:
    raw_values = value if isinstance(value, list) else [str(value or "")]
    rows: list[dict[str, str]] = []
    for name, address in getaddresses([str(row or "") for row in raw_values]):
        clean_address = str(address or "").strip()
        clean_name = _decode_email_header(name).strip()
        if clean_name or clean_address:
            rows.append({"display_name": clean_name, "email": clean_address})
    return rows


def _safe_email_part_text(part: Any) -> str:
    try:
        value = part.get_content()
        if isinstance(value, str):
            return value
    except Exception:
        pass
    try:
        payload = part.get_payload(decode=True)
    except Exception:
        payload = None
    if not isinstance(payload, (bytes, bytearray)):
        return ""
    charset = ""
    try:
        charset = str(part.get_content_charset() or "")
    except Exception:
        charset = ""
    for candidate in (charset, "utf-8", "latin-1"):
        if not candidate:
            continue
        try:
            return bytes(payload).decode(candidate, errors="replace")
        except (LookupError, UnicodeError):
            continue
    return bytes(payload).decode("utf-8", errors="replace")


def html_to_readable_text(html_text: Any) -> str:
    """Convert stored email HTML to readable text without loading remote resources."""
    raw = str(html_text or "")
    raw = re.sub(r"(?is)<!--.*?-->", " ", raw)
    raw = re.sub(
        r"(?is)<(script|style|noscript|template|svg|canvas|iframe|object|embed|head)\b[^>]*>.*?</\1>",
        " ",
        raw,
    )
    raw = re.sub(r"(?is)<br\s*/?>", "\n", raw)
    raw = re.sub(
        r"(?is)</(p|div|section|article|header|footer|main|aside|nav|li|h[1-6]|tr|table|ul|ol|blockquote)>",
        "\n",
        raw,
    )
    raw = re.sub(r"(?is)<[^>]+>", " ", raw)
    text = html.unescape(raw)
    text = re.sub(r"[ \t\r\f\v]+", " ", text)
    text = re.sub(r"\n\s*\n\s*\n+", "\n\n", text)
    return "\n".join(line.strip() for line in text.splitlines() if line.strip())


def sanitize_email_html(html_text: Any) -> str:
    """Return inert normalized HTML for local display without scripts or remote resources."""
    readable = html_to_readable_text(html_text)
    if not readable:
        return ""
    return "<pre>" + html.escape(readable) + "</pre>"


def parse_gmail_mime_message(raw_message: bytes, metadata: dict[str, Any]) -> dict[str, Any]:
    """Parse one fetched Gmail message without loading remote resources."""
    try:
        message = email.message_from_bytes(bytes(raw_message), policy=email_policy.default)
    except Exception:
        message = email.message_from_bytes(bytes(raw_message), policy=email_policy.compat32)
    plain_parts: list[str] = []
    html_parts: list[str] = []
    attachments: list[dict[str, Any]] = []
    parts = list(message.walk()) if getattr(message, "is_multipart", lambda: False)() else [message]
    for part in parts:
        try:
            if part.is_multipart():
                continue
        except Exception:
            pass
        content_type = str(part.get_content_type() or "application/octet-stream").lower()
        disposition = str(part.get_content_disposition() or "").lower()
        filename = _decode_email_header(part.get_filename())
        content_id = str(part.get("Content-ID") or "").strip().strip("<>")
        if filename or disposition in {"attachment", "inline"}:
            try:
                payload_bytes = part.get_payload(decode=True) or b""
            except Exception:
                payload_bytes = b""
            attachments.append({
                "external_id": content_id or filename,
                "filename": filename or "attachment",
                "mime_type": content_type,
                "size_bytes": len(payload_bytes),
                "source_url": "",
                "is_inline": disposition == "inline",
                "content_id": content_id,
                "metadata": {},
            })
            continue
        if content_type == "text/plain":
            text = _safe_email_part_text(part)
            if text.strip():
                plain_parts.append(text)
        elif content_type == "text/html":
            text = _safe_email_part_text(part)
            if text.strip():
                html_parts.append(text)
    body_text = "\n\n".join(plain_parts).strip()
    raw_body_html = "\n\n".join(html_parts).strip()
    if not body_text and raw_body_html:
        body_text = html_to_readable_text(raw_body_html)
    body_html = sanitize_email_html(raw_body_html)
    header_date = str(message.get("Date") or "").strip()
    header_timestamp = ""
    if header_date:
        try:
            parsed = parsedate_to_datetime(header_date)
            if parsed is not None:
                if parsed.tzinfo is None:
                    parsed = parsed.replace(tzinfo=timezone.utc)
                header_timestamp = parsed.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")
        except Exception:
            header_timestamp = ""
    internal_timestamp = str(metadata.get("internal_received_timestamp") or "")
    if not internal_timestamp:
        internal_timestamp = header_timestamp or _connector_now()
    flags = [str(row) for row in metadata.get("flags", [])]
    labels = [str(row) for row in metadata.get("labels", [])]
    subject = _decode_email_header(message.get("Subject")) or "(No subject)"
    return {
        "x_gm_msgid": str(metadata.get("x_gm_msgid") or ""),
        "x_gm_thrid": str(metadata.get("x_gm_thrid") or ""),
        "imap_uid": str(metadata.get("imap_uid") or ""),
        "imap_uidvalidity": str(metadata.get("imap_uidvalidity") or ""),
        "mailbox_identifier": str(metadata.get("mailbox_identifier") or ""),
        "rfc_message_id": str(message.get("Message-ID") or "").strip(),
        "subject": subject,
        "from": _email_address_rows(message.get_all("From", [])),
        "to": _email_address_rows(message.get_all("To", [])),
        "cc": _email_address_rows(message.get_all("Cc", [])),
        "bcc": _email_address_rows(message.get_all("Bcc", [])),
        "reply_to": _email_address_rows(message.get_all("Reply-To", [])),
        "internal_received_timestamp": internal_timestamp,
        "header_date_timestamp": header_timestamp,
        "flags": flags,
        "labels": labels,
        "attachments": attachments,
        "body_text": body_text,
        "body_html": body_html,
        "summary": re.sub(r"\s+", " ", body_text).strip()[:320],
        "is_unread": not any(flag.casefold() == "\\seen" for flag in flags),
        "is_deleted": any(flag.casefold() == "\\deleted" for flag in flags),
        "raw_size_bytes": int(metadata.get("raw_size_bytes") or len(raw_message)),
    }


def imap_quote_mailbox_name(value: Any) -> str:
    """Return one IMAP quoted string suitable for SELECT/EXAMINE mailbox arguments."""
    raw = str(value or "")
    return '"' + raw.replace("\\", "\\\\").replace('"', '\\"') + '"'


def parse_imap_mailbox_list_line(value: Any) -> dict[str, Any] | None:
    text = value.decode("utf-8", errors="replace") if isinstance(value, bytes) else str(value or "")
    match = re.match(r'^\((?P<attrs>[^)]*)\)\s+(?P<delimiter>NIL|"(?:[^"\\]|\\.)*")\s+(?P<name>.+)$', text.strip())
    if not match:
        return None
    attrs = [row for row in re.findall(r'\\[^\s]+|[^\s]+', match.group("attrs")) if row]
    raw_name = match.group("name").strip()
    if raw_name.startswith('"') and raw_name.endswith('"'):
        raw_name = raw_name[1:-1].replace('\\"', '"').replace('\\\\', '\\')
    return {"attributes": attrs, "name": raw_name}


def _parse_imap_atom_list(value: str) -> list[str]:
    rows: list[str] = []
    for quoted, atom in re.findall(r'"((?:[^"\\]|\\.)*)"|([^\s]+)', str(value or "")):
        token = quoted.replace('\\"', '"').replace('\\\\', '\\') if quoted else atom
        if token:
            rows.append(token)
    return rows


def parse_gmail_fetch_data(data: Any, *, uidvalidity: str, mailbox: str) -> list[tuple[dict[str, Any], bytes]]:
    rows: list[tuple[dict[str, Any], bytes]] = []
    sequence = data if isinstance(data, list) else [data]
    for entry in sequence:
        if not (isinstance(entry, tuple) and len(entry) >= 2 and isinstance(entry[1], (bytes, bytearray))):
            continue
        meta_raw = entry[0].decode("utf-8", errors="replace") if isinstance(entry[0], bytes) else str(entry[0] or "")
        raw_message = bytes(entry[1])
        def capture(pattern: str) -> str:
            match = re.search(pattern, meta_raw, flags=re.IGNORECASE)
            return str(match.group(1) or "").strip() if match else ""
        internal_raw = capture(r'INTERNALDATE\s+"([^"]+)"')
        internal_timestamp = ""
        if internal_raw:
            try:
                parsed = parsedate_to_datetime(internal_raw)
                if parsed.tzinfo is None:
                    parsed = parsed.replace(tzinfo=timezone.utc)
                internal_timestamp = parsed.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")
            except Exception:
                internal_timestamp = ""
        labels_match = re.search(r'X-GM-LABELS\s+\((.*?)\)\s+(?:UID|FLAGS|INTERNALDATE|RFC822\.SIZE|BODY)', meta_raw, flags=re.I | re.S)
        flags_match = re.search(r'FLAGS\s+\((.*?)\)', meta_raw, flags=re.I | re.S)
        metadata = {
            "x_gm_msgid": capture(r'X-GM-MSGID\s+(\d+)'),
            "x_gm_thrid": capture(r'X-GM-THRID\s+(\d+)'),
            "imap_uid": capture(r'\bUID\s+(\d+)'),
            "imap_uidvalidity": str(uidvalidity or ""),
            "mailbox_identifier": str(mailbox or ""),
            "internal_received_timestamp": internal_timestamp,
            "raw_size_bytes": int(capture(r'RFC822\.SIZE\s+(\d+)') or len(raw_message)),
            "labels": _parse_imap_atom_list(labels_match.group(1) if labels_match else ""),
            "flags": _parse_imap_atom_list(flags_match.group(1) if flags_match else ""),
        }
        rows.append((metadata, raw_message))
    return rows


def _imap_capabilities(client: Any) -> set[str]:
    values: list[Any] = []
    try:
        status, data = client.capability()
        if str(status).upper() == "OK":
            values.extend(data or [])
    except Exception:
        values.extend(getattr(client, "capabilities", ()) or ())
    text = " ".join(
        row.decode("ascii", errors="ignore") if isinstance(row, bytes) else str(row or "")
        for row in values
    )
    return {token.upper() for token in text.split() if token}


def _imap_uidvalidity(client: Any) -> str:
    try:
        response = client.response("UIDVALIDITY")
        data = response[1] if isinstance(response, tuple) and len(response) > 1 else response
        if isinstance(data, (list, tuple)) and data:
            raw = data[0]
            text = raw.decode("ascii", errors="ignore") if isinstance(raw, bytes) else str(raw)
            match = re.search(r"\d+", text)
            if match:
                return match.group(0)
    except Exception:
        pass
    untagged = getattr(client, "untagged_responses", {}) or {}
    for key in ("UIDVALIDITY", b"UIDVALIDITY"):
        data = untagged.get(key)
        if data:
            raw = data[-1]
            text = raw.decode("ascii", errors="ignore") if isinstance(raw, bytes) else str(raw)
            match = re.search(r"\d+", text)
            if match:
                return match.group(0)
    return ""


def _imap_search_uids(client: Any, *criteria: str) -> list[int]:
    resolved = tuple(str(value) for value in criteria if str(value or "")) or ("ALL",)
    status, data = client.uid("search", None, *resolved)
    if str(status).upper() != "OK":
        raise RuntimeError(f"Gmail IMAP UID search failed: {status}")
    raw = b" ".join(row for row in (data or []) if isinstance(row, bytes))
    if not raw and data:
        raw = str(data[0] or "").encode("ascii", errors="ignore")
    return sorted({int(token) for token in re.findall(rb"\d+", raw)})


def _chunks(values: list[int], size: int) -> Iterable[list[int]]:
    resolved = max(1, int(size))
    for index in range(0, len(values), resolved):
        yield values[index:index + resolved]


class BaseVaultConnector(VaultConnectorContract):
    """Shared cancellation, progress, status, and data-change behavior."""

    connector_type = ""

    def __init__(
        self,
        storage: Storage,
        vault: VaultStore,
        credentials: CredentialStore,
        *,
        progress_callback: Callable[[str, dict[str, Any]], None] | None = None,
        data_changed_callback: Callable[[str], None] | None = None,
    ):
        self.storage = storage
        self.vault = vault
        self.credentials = credentials
        self.progress_callback = progress_callback
        self.data_changed_callback = data_changed_callback
        self._cancel_event = threading.Event()
        self._operation_lock = threading.RLock()
        self._operation_in_progress = False
        self._operation_name = ""
        self._status_message = ""
        self._last_error = ""
        self._status_events: list[str] = []

    def get_connector_type(self) -> str:
        return self.connector_type

    def cancel_sync(self) -> None:
        self._cancel_event.set()

    def _check_cancelled(self) -> None:
        if self._cancel_event.is_set():
            label = VAULT_SOURCE_LABELS.get(self.connector_type, self.connector_type)
            raise ConnectorCancelledError(f"{label} synchronization cancelled")

    def _progress(self, message: str, **details: Any) -> None:
        text = str(message or "").strip()
        if text:
            with self._operation_lock:
                self._status_message = text
                previous = self._status_events[-1].split("] ", 1)[-1] if self._status_events else ""
                if previous != text:
                    stamp = datetime.now().astimezone().strftime("%H:%M:%S")
                    self._status_events.append(f"[{stamp}] {text}")
                    del self._status_events[:-CONNECTOR_MAX_STATUS_EVENTS]
        if callable(self.progress_callback):
            try:
                self.progress_callback(self.connector_type, {"message": text, **copy.deepcopy(details)})
            except Exception as exc:
                # A transient UI/status consumer must not turn a successful
                # external synchronization into a connector failure.
                try:
                    self.storage.append_app_log(
                        f"{self.connector_type}.progress_callback_failed",
                        {"error": f"{type(exc).__name__}: {exc}", "message": text},
                    )
                except Exception:
                    pass

    def _data_changed(self) -> None:
        if callable(self.data_changed_callback):
            try:
                self.data_changed_callback(self.connector_type)
            except Exception as exc:
                try:
                    self.storage.append_app_log(
                        f"{self.connector_type}.data_changed_callback_failed",
                        {"error": f"{type(exc).__name__}: {exc}"},
                    )
                except Exception:
                    pass

    def _begin(self, operation: str) -> None:
        with self._operation_lock:
            if self._operation_in_progress:
                label = VAULT_SOURCE_LABELS.get(self.connector_type, self.connector_type)
                raise RuntimeError(f"{label} operation already in progress")
            self._operation_in_progress = True
            self._operation_name = str(operation or "sync")
            self._last_error = ""
            self._cancel_event.clear()

    def _finish(self, message: str) -> None:
        with self._operation_lock:
            self._operation_in_progress = False
            self._operation_name = ""
        self._progress(message)

    def _fail(self, exc: BaseException) -> None:
        error_text = f"{type(exc).__name__}: {exc}"
        with self._operation_lock:
            self._last_error = error_text
            operation = self._operation_name or "operation"
            self._operation_in_progress = False
            self._operation_name = ""
        label = {
            "sync": "Sync failed",
            "connect": "Connection failed",
            "test": "Connection test failed",
            "disconnect": "Disconnect failed",
        }.get(operation, "Operation failed")
        self._progress(f"{label}: {error_text}")

    def _source(self) -> dict[str, Any] | None:
        """Return the most relevant account when old synchronized sources remain.

        Connectors currently configure one live account per source type, while the
        Vault intentionally retains older local data. Alphabetical selection could
        therefore route status and tools to a stale disconnected account after a
        reconnect with different credentials. Prefer enabled/active and most
        recently updated sources deterministically.
        """
        rows = [row for row in self.vault.list_data_sources() if row["source_type"] == self.connector_type]
        if not rows:
            return None
        state_rank = {"syncing": 4, "connected": 3, "error": 2, "not_configured": 1, "disabled": 0}

        def timestamp_value(row: dict[str, Any]) -> float:
            for key in ("last_sync_completed_at", "updated_at", "created_at"):
                raw = str(row.get(key) or "").strip()
                if not raw:
                    continue
                try:
                    return _parse_iso_datetime(raw, field_name=f"Vault source {key}").timestamp()
                except Exception:
                    continue
            return 0.0

        return max(rows, key=lambda row: (
            1 if bool(row.get("enabled", True)) else 0,
            state_rank.get(str(row.get("connection_state") or ""), -1),
            timestamp_value(row),
            str(row.get("id") or ""),
        ))

    async def _run_blocking_lifecycle(
        self,
        operation: str,
        callback: Callable[[], dict[str, Any]],
        *,
        progress_message: str = "",
        success_message: str,
    ) -> dict[str, Any]:
        """Run one blocking connector lifecycle with consistent state transitions."""
        self._begin(operation)
        if progress_message:
            self._progress(progress_message)
        try:
            result = await asyncio.to_thread(callback)
            self._finish(success_message)
            return result
        except Exception as exc:
            self._fail(exc)
            raise

    async def connect_or_authorize(self) -> dict[str, Any]:
        return await self._run_blocking_lifecycle(
            "connect", self._connect_lifecycle_blocking,
            progress_message="Connecting...", success_message="Connected",
        )

    async def disconnect(self) -> dict[str, Any]:
        return await self._run_blocking_lifecycle(
            "disconnect", self._disconnect_lifecycle_blocking, success_message="Disconnected",
        )

    def get_status(self) -> dict[str, Any]:
        source = self._source()
        with self._operation_lock:
            busy = self._operation_in_progress
            operation = self._operation_name
            status_message = self._status_message
            last_error = self._last_error
            events = list(self._status_events)
        try:
            validation = self.validate_configuration()
            configured = bool(validation.get("configured"))
            configuration_error = ""
        except Exception as exc:
            validation = {"configured": False, "errors": [f"{type(exc).__name__}: {exc}"]}
            configured = False
            configuration_error = f"{type(exc).__name__}: {exc}"
        return {
            "connector_type": self.connector_type,
            "configured": configured,
            "validation": validation,
            "connected": bool(source and source.get("connection_state") == "connected"),
            "source": source,
            "operation_in_progress": busy,
            "operation": operation,
            "message": status_message,
            "last_error": last_error or configuration_error or str(source.get("last_sync_error") if source else ""),
            "events": events,
        }


class GoogleDriveConnector(BaseVaultConnector):
    """Read-only, ad-hoc Google Drive OAuth, search, metadata, and content retrieval.

    Drive is intentionally not mirrored into local Vault storage and has no
    periodic sync. Chats, agents, and the ad-hoc Vault explorer use the same
    read-only list/search/folder/get/read/download operations.
    """

    connector_type = GOOGLE_DRIVE_SOURCE_TYPE
    _FILE_FIELDS = (
        "id,name,mimeType,description,createdTime,modifiedTime,viewedByMeTime,"
        "sharedWithMeTime,parents,driveId,trashed,starred,shared,ownedByMe,viewedByMe,"
        "owners(displayName,emailAddress,permissionId),size,md5Checksum,sha1Checksum,"
        "sha256Checksum,webViewLink,webContentLink,fileExtension,fullFileExtension,"
        "originalFilename,version,spaces,capabilities,shortcutDetails,exportLinks"
    )
    _SHARED_DRIVE_FIELDS = "id,name,createdTime,hidden,capabilities,restrictions"

    def __init__(
        self,
        storage: Storage,
        vault: VaultStore,
        credentials: CredentialStore,
        *,
        dependencies_loader: Callable[[], Any] | None = None,
        dependency_installer: Callable[[], None] | None = None,
        service_factory: Callable[[Any, Any], Any] | None = None,
        progress_callback: Callable[[str, dict[str, Any]], None] | None = None,
        data_changed_callback: Callable[[str], None] | None = None,
    ):
        super().__init__(storage, vault, credentials, progress_callback=progress_callback, data_changed_callback=data_changed_callback)
        self.dependencies_loader = dependencies_loader
        self.dependency_installer = dependency_installer
        self.service_factory = service_factory

    def _settings(self) -> dict[str, Any]:
        value = self.storage.load_config().get("vault", {}).get("google_drive", {})
        return copy.deepcopy(value if isinstance(value, dict) else {})

    def _include_shared_drives(self) -> bool:
        return bool(self._settings().get("include_shared_drives", True))

    def _dependencies(self, *, install_if_missing: bool = False) -> Any:
        loader = self.dependencies_loader or load_google_calendar_dependencies
        try:
            return loader()
        except Exception:
            if not install_if_missing:
                raise
        (self.dependency_installer or install_google_calendar_dependencies)()
        return loader()

    def validate_configuration(self) -> dict[str, Any]:
        values = self.credentials.load_google_drive()
        client_id = str(values.get("client_id") or "").strip()
        client_secret = str(values.get("client_secret") or "").strip()
        token = values.get("token")
        errors: list[str] = []
        if not client_id:
            errors.append("Enter a Google OAuth Desktop app Client ID.")
        if not client_secret:
            errors.append("Enter the matching Google OAuth Client secret.")
        return {
            "configured": not errors,
            "client_id_present": bool(client_id),
            "client_secret_present": bool(client_secret),
            "token_present": isinstance(token, dict),
            "connected": isinstance(token, dict),
            "read_only": True,
            "ad_hoc_only": True,
            "scope": GOOGLE_DRIVE_SCOPES[0],
            "errors": errors,
        }

    def get_status(self) -> dict[str, Any]:
        validation = self.validate_configuration()
        with self._operation_lock:
            busy = bool(self._operation_in_progress)
            operation = str(self._operation_name or "")
            message = str(self._status_message or "")
            last_error = str(self._last_error or "")
            events = list(self._status_events)
        return {
            "connector_type": self.connector_type,
            "configured": bool(validation.get("configured")),
            "validation": validation,
            "connected": bool(validation.get("token_present")),
            "source": None,
            "operation_in_progress": busy,
            "operation": operation,
            "message": message or "Ready for ad-hoc Drive access",
            "last_error": last_error,
            "events": events,
        }

    def _save_credentials(self, credentials: Any) -> None:
        try:
            payload = json.loads(str(credentials.to_json()))
        except Exception as exc:
            raise RuntimeError("Google Drive returned malformed OAuth authorization data") from exc
        self.credentials.save_google_drive_token(payload)

    def _load_credentials(self, dependencies: Any) -> Any:
        token = self.credentials.load_google_drive().get("token")
        if not isinstance(token, dict):
            raise RuntimeError("Google Drive is not connected. Use Settings > Accounts > Google Drive > Connect.")
        try:
            credentials = dependencies.credentials_type.from_authorized_user_info(copy.deepcopy(token), list(GOOGLE_DRIVE_SCOPES))
        except Exception as exc:
            raise RuntimeError("The saved Google Drive authorization is invalid. Reconnect Google Drive.") from exc
        if not bool(getattr(credentials, "valid", False)):
            if bool(getattr(credentials, "expired", False)) and getattr(credentials, "refresh_token", None):
                try:
                    credentials.refresh(dependencies.request_type())
                    self._save_credentials(credentials)
                except Exception as exc:
                    raise RuntimeError("Google Drive authorization refresh failed. Reconnect Google Drive.") from exc
            else:
                raise RuntimeError("Google Drive authorization is no longer valid. Reconnect Google Drive.")
        return credentials

    def _build_service(self, credentials: Any, dependencies: Any) -> Any:
        if self.service_factory is not None:
            return self.service_factory(credentials, dependencies)
        raw_http = dependencies.http_type(timeout=GOOGLE_DRIVE_NETWORK_TIMEOUT_SECONDS)
        authorized_http = dependencies.authorized_http_type(credentials, http=raw_http)
        return dependencies.build("drive", "v3", http=authorized_http, cache_discovery=False)

    @staticmethod
    def _execute(request: Any) -> Any:
        if not hasattr(request, "execute"):
            raise RuntimeError("Google Drive returned an invalid request object")
        return request.execute()

    def _service_from_saved_credentials(self) -> tuple[Any, Any, Any]:
        dependencies = self._dependencies(install_if_missing=False)
        credentials = self._load_credentials(dependencies)
        return self._build_service(credentials, dependencies), credentials, dependencies

    def _about(self, service: Any) -> dict[str, Any]:
        payload = self._execute(service.about().get(fields="user"))
        if not isinstance(payload, dict):
            raise RuntimeError("Google Drive returned malformed account information")
        return payload

    async def test_connection(self) -> dict[str, Any]:
        self._begin("test")
        self._progress("Connecting...")
        try:
            service, _credentials, _dependencies = await asyncio.to_thread(self._service_from_saved_credentials)
            about = await asyncio.to_thread(self._about, service)
            self._finish("Connection test succeeded")
            return {"ok": True, "account": copy.deepcopy(about.get("user") or {}), "ad_hoc_only": True}
        except Exception as exc:
            self._fail(exc)
            raise

    def _connect_blocking(self) -> dict[str, Any]:
        values = self.credentials.load_google_drive()
        validation = self.validate_configuration()
        if not validation["configured"]:
            raise ValueError(" ".join(validation["errors"]))
        dependencies = self._dependencies(install_if_missing=True)
        flow = dependencies.installed_app_flow_type.from_client_config(
            google_oauth_client_config(values["client_id"], values["client_secret"]),
            list(GOOGLE_DRIVE_SCOPES),
        )
        try:
            credentials = flow.run_local_server(
                port=0,
                open_browser=True,
                authorization_prompt_message="Your browser is opening so Velox can connect Google Drive read-only.",
                success_message="Velox is connected to Google Drive. You can close this browser tab.",
            )
        except Exception as exc:
            raise RuntimeError(f"Google Drive connection failed: {exc}") from exc
        self._save_credentials(credentials)
        service = self._build_service(credentials, dependencies)
        about = self._about(service)
        return {"ok": True, "account": copy.deepcopy(about.get("user") or {}), "ad_hoc_only": True}

    async def connect_or_authorize(self) -> dict[str, Any]:
        return await self._run_blocking_lifecycle(
            "connect", self._connect_blocking,
            progress_message="Connecting...",
            success_message="Connected for ad-hoc read-only access",
        )

    async def sync(self) -> dict[str, Any]:
        raise RuntimeError(
            "Google Drive is ad-hoc only. Use drive_list_drives, drive_list_root, "
            "drive_list_children, drive_list, drive_search, drive_get, drive_read, or "
            "drive_download instead of synchronization."
        )

    def _disconnect_blocking(self) -> dict[str, Any]:
        self.credentials.clear_google_drive_token()
        return {"ok": True, "ad_hoc_only": True}

    async def disconnect(self) -> dict[str, Any]:
        return await self._run_blocking_lifecycle(
            "disconnect", self._disconnect_blocking, success_message="Disconnected",
        )

    @staticmethod
    def _escape_query_text(value: str) -> str:
        return str(value or "").replace("\\", "\\\\").replace("'", "\\'")

    @staticmethod
    def _public_file(payload: dict[str, Any]) -> dict[str, Any]:
        owners = payload.get("owners") if isinstance(payload.get("owners"), list) else []
        owner_names = [str(row.get("displayName") or row.get("emailAddress") or "") for row in owners if isinstance(row, dict)]
        return {
            "file_id": str(payload.get("id") or ""),
            "name": str(payload.get("name") or ""),
            "mime_type": str(payload.get("mimeType") or ""),
            "description": str(payload.get("description") or ""),
            "created_at": str(payload.get("createdTime") or ""),
            "modified_at": str(payload.get("modifiedTime") or ""),
            "owners": [name for name in owner_names if name],
            "size_bytes": int(payload.get("size") or 0) if str(payload.get("size") or "").isdigit() else 0,
            "source_url": str(payload.get("webViewLink") or ""),
            "drive_id": str(payload.get("driveId") or ""),
            "parents": list(payload.get("parents") or []) if isinstance(payload.get("parents"), list) else [],
            "is_folder": str(payload.get("mimeType") or "") == "application/vnd.google-apps.folder",
            "capabilities": copy.deepcopy(payload.get("capabilities") if isinstance(payload.get("capabilities"), dict) else {}),
            "export_links": copy.deepcopy(payload.get("exportLinks") if isinstance(payload.get("exportLinks"), dict) else {}),
        }

    @staticmethod
    def _public_shared_drive(payload: dict[str, Any]) -> dict[str, Any]:
        return {
            "drive_id": str(payload.get("id") or ""),
            "name": str(payload.get("name") or ""),
            "created_at": str(payload.get("createdTime") or ""),
            "hidden": bool(payload.get("hidden")),
            "capabilities": copy.deepcopy(
                payload.get("capabilities") if isinstance(payload.get("capabilities"), dict) else {}
            ),
            "restrictions": copy.deepcopy(
                payload.get("restrictions") if isinstance(payload.get("restrictions"), dict) else {}
            ),
        }

    def _list_shared_drives_with_service(self, service: Any, limit: int = 1000) -> dict[str, Any]:
        resolved_limit = max(1, int(limit))
        token = ""
        rows: list[dict[str, Any]] = []
        while len(rows) < resolved_limit:
            kwargs: dict[str, Any] = {
                "pageSize": min(100, resolved_limit - len(rows)),
                "fields": f"nextPageToken,drives({self._SHARED_DRIVE_FIELDS})",
            }
            if token:
                kwargs["pageToken"] = token
            payload = self._execute(service.drives().list(**kwargs))
            if not isinstance(payload, dict):
                raise RuntimeError("Google Drive returned a malformed shared-drive response")
            for row in payload.get("drives") or []:
                if isinstance(row, dict):
                    rows.append(self._public_shared_drive(row))
                    if len(rows) >= resolved_limit:
                        break
            token = str(payload.get("nextPageToken") or "")
            if not token:
                break
        return {
            "count": len(rows),
            "shared_drives": rows,
            "truncated": bool(token and len(rows) >= resolved_limit),
            "next_page_token_available": bool(token),
            "read_only": True,
        }

    @staticmethod
    def _result_limit(value: Any, *, default: int = GOOGLE_DRIVE_DEFAULT_RESULT_LIMIT) -> int:
        try:
            resolved = int(value)
        except (TypeError, ValueError):
            resolved = int(default)
        return int(clamp(resolved, 1, GOOGLE_DRIVE_MAX_RESULT_LIMIT))

    def _list_drives_blocking(self, limit: int = GOOGLE_DRIVE_MAX_RESULT_LIMIT) -> dict[str, Any]:
        resolved_limit = self._result_limit(limit, default=GOOGLE_DRIVE_MAX_RESULT_LIMIT)
        service, _credentials, _dependencies = self._service_from_saved_credentials()
        about = self._about(service)
        shared = self._list_shared_drives_with_service(service, resolved_limit)
        return {
            "account": copy.deepcopy(about.get("user") or {}),
            "my_drive": {"drive_id": "", "name": "My Drive", "kind": "my_drive"},
            **shared,
            "ad_hoc": True,
        }

    async def list_drives(self, limit: int = GOOGLE_DRIVE_MAX_RESULT_LIMIT) -> dict[str, Any]:
        return await asyncio.to_thread(self._list_drives_blocking, limit)

    def _file_list_pages(
        self,
        service: Any,
        *,
        q: str,
        limit: int,
        corpora: str,
        order_by: str = "",
        drive_id: str = "",
        include_all_drives: bool = False,
    ) -> dict[str, Any]:
        resolved_limit = self._result_limit(limit)
        token = ""
        rows: list[dict[str, Any]] = []
        incomplete_search = False
        while len(rows) < resolved_limit:
            kwargs: dict[str, Any] = {
                "q": str(q),
                "pageSize": min(1000, resolved_limit - len(rows)),
                "fields": f"nextPageToken,incompleteSearch,files({self._FILE_FIELDS})",
                "spaces": "drive",
                "corpora": str(corpora),
                "includeItemsFromAllDrives": bool(include_all_drives),
                "supportsAllDrives": True,
            }
            if drive_id:
                kwargs["driveId"] = str(drive_id)
            if order_by:
                kwargs["orderBy"] = str(order_by)
            if token:
                kwargs["pageToken"] = token
            payload = self._execute(service.files().list(**kwargs))
            if not isinstance(payload, dict):
                raise RuntimeError("Google Drive returned a malformed file-list response")
            incomplete_search = incomplete_search or bool(payload.get("incompleteSearch"))
            for row in payload.get("files") or []:
                if isinstance(row, dict):
                    rows.append(self._public_file(row))
                    if len(rows) >= resolved_limit:
                        break
            token = str(payload.get("nextPageToken") or "")
            if not token:
                break
        return {
            "count": len(rows),
            "files": rows,
            "read_only": True,
            "incomplete_search": incomplete_search,
            "truncated": bool(token and len(rows) >= resolved_limit),
            "next_page_token_available": bool(token),
        }

    def _list_or_search_files_blocking(
        self,
        *,
        query: str | None,
        limit: int,
        drive_id: str = "",
    ) -> dict[str, Any]:
        clean = str(query or "").strip()
        selected_drive_id = str(drive_id or "").strip()
        service, _credentials, _dependencies = self._service_from_saved_credentials()
        include_all = self._include_shared_drives()
        q = "trashed = false"
        is_full_text_search = bool(clean)
        if clean:
            escaped = self._escape_query_text(clean)
            q += f" and (name contains '{escaped}' or fullText contains '{escaped}')"
        if selected_drive_id:
            corpora = "drive"
            include_items = True
        else:
            corpora = "allDrives" if include_all else "user"
            include_items = include_all
        result = self._file_list_pages(
            service,
            q=q,
            limit=limit,
            corpora=corpora,
            order_by="" if is_full_text_search else "modifiedTime desc,name",
            drive_id=selected_drive_id,
            include_all_drives=include_items,
        )
        return {
            "query": clean,
            "drive_id": selected_drive_id,
            **result,
            "ad_hoc": True,
            "result_order": "relevance" if is_full_text_search else "modifiedTime desc,name",
            "corpora": corpora,
        }

    def _list_files_blocking(
        self, limit: int = GOOGLE_DRIVE_DEFAULT_RESULT_LIMIT, drive_id: str = "",
    ) -> dict[str, Any]:
        return self._list_or_search_files_blocking(query=None, limit=limit, drive_id=drive_id)

    async def list_files(
        self, limit: int = GOOGLE_DRIVE_DEFAULT_RESULT_LIMIT, drive_id: str = "",
    ) -> dict[str, Any]:
        return await asyncio.to_thread(self._list_files_blocking, limit, drive_id)

    def _search_files_blocking(
        self, query: str, limit: int = GOOGLE_DRIVE_DEFAULT_RESULT_LIMIT, drive_id: str = "",
    ) -> dict[str, Any]:
        clean = str(query or "").strip()
        if not clean:
            raise ValueError("Drive search query is required; use drive_list or drive_list_root for discovery")
        return self._list_or_search_files_blocking(query=clean, limit=limit, drive_id=drive_id)

    async def search_files(
        self, query: str, limit: int = GOOGLE_DRIVE_DEFAULT_RESULT_LIMIT, drive_id: str = "",
    ) -> dict[str, Any]:
        return await asyncio.to_thread(self._search_files_blocking, query, limit, drive_id)

    def _list_directory_with_service(
        self,
        service: Any,
        *,
        parent_id: str,
        drive_id: str,
        limit: int,
        folders_only: bool = False,
    ) -> dict[str, Any]:
        parent = str(parent_id or "").strip()
        if not parent:
            raise ValueError("Google Drive parent folder ID is required")
        shared_drive_id = str(drive_id or "").strip()
        escaped_parent = self._escape_query_text(parent)
        query = f"'{escaped_parent}' in parents and trashed = false"
        if folders_only:
            query += f" and mimeType = '{GOOGLE_DRIVE_FOLDER_MIME_TYPE}'"
        result = self._file_list_pages(
            service,
            q=query,
            limit=limit,
            corpora="drive" if shared_drive_id else "user",
            order_by="name_natural",
            drive_id=shared_drive_id,
            include_all_drives=bool(shared_drive_id),
        )
        result["files"] = sorted(
            list(result.get("files") or []),
            key=lambda row: (
                0 if bool(row.get("is_folder")) else 1,
                str(row.get("name") or "").casefold(),
                str(row.get("file_id") or ""),
            ),
        )
        result.update({
            "parent_id": parent,
            "drive_id": shared_drive_id,
            "folders_only": bool(folders_only),
            "result_order": "folders first,name_natural",
            "corpora": "drive" if shared_drive_id else "user",
            "ad_hoc": True,
        })
        return result

    def _list_root_blocking(
        self, drive_id: str = "", limit: int = GOOGLE_DRIVE_DEFAULT_RESULT_LIMIT,
        folders_only: bool = False,
    ) -> dict[str, Any]:
        shared_drive_id = str(drive_id or "").strip()
        service, _credentials, _dependencies = self._service_from_saved_credentials()
        parent_id = shared_drive_id or "root"
        result = self._list_directory_with_service(
            service, parent_id=parent_id, drive_id=shared_drive_id, limit=limit,
            folders_only=folders_only,
        )
        result["location"] = {
            "kind": "shared_drive_root" if shared_drive_id else "my_drive_root",
            "drive_id": shared_drive_id,
            "folder_id": parent_id,
            "name": "Shared Drive" if shared_drive_id else "My Drive",
        }
        return result

    async def list_root(
        self, drive_id: str = "", limit: int = GOOGLE_DRIVE_DEFAULT_RESULT_LIMIT,
        folders_only: bool = False,
    ) -> dict[str, Any]:
        return await asyncio.to_thread(self._list_root_blocking, drive_id, limit, folders_only)

    def _list_children_blocking(
        self, folder_id: str, limit: int = GOOGLE_DRIVE_DEFAULT_RESULT_LIMIT,
        folders_only: bool = False,
    ) -> dict[str, Any]:
        target = str(folder_id or "").strip()
        if not target:
            raise ValueError("Google Drive folder ID is required")
        service, _credentials, _dependencies = self._service_from_saved_credentials()
        raw_folder = self._execute(
            service.files().get(fileId=target, fields=self._FILE_FIELDS, supportsAllDrives=True)
        )
        if not isinstance(raw_folder, dict):
            raise RuntimeError("Google Drive returned malformed folder metadata")
        folder = self._public_file(raw_folder)
        if not folder.get("is_folder"):
            raise ValueError("The requested Google Drive item is not a folder")
        drive_id = str(folder.get("drive_id") or "")
        result = self._list_directory_with_service(
            service, parent_id=target, drive_id=drive_id, limit=limit,
            folders_only=folders_only,
        )
        result["folder"] = folder
        result["location"] = {
            "kind": "folder", "drive_id": drive_id,
            "folder_id": target, "name": str(folder.get("name") or "Folder"),
        }
        return result

    async def list_children(
        self, folder_id: str, limit: int = GOOGLE_DRIVE_DEFAULT_RESULT_LIMIT,
        folders_only: bool = False,
    ) -> dict[str, Any]:
        return await asyncio.to_thread(self._list_children_blocking, folder_id, limit, folders_only)

    def _get_file_blocking(self, file_id: str) -> dict[str, Any]:
        target = str(file_id or "").strip()
        if not target:
            raise ValueError("Google Drive file ID is required")
        service, _credentials, _dependencies = self._service_from_saved_credentials()
        payload = self._execute(service.files().get(fileId=target, fields=self._FILE_FIELDS, supportsAllDrives=True))
        if not isinstance(payload, dict):
            raise RuntimeError("Google Drive returned malformed file metadata")
        return self._public_file(payload)

    async def get_file(self, file_id: str) -> dict[str, Any]:
        return await asyncio.to_thread(self._get_file_blocking, file_id)

    def _read_file_blocking(self, file_id: str, max_chars: int) -> dict[str, Any]:
        target = str(file_id or "").strip()
        if not target:
            raise ValueError("Google Drive file ID is required")
        service, _credentials, _dependencies = self._service_from_saved_credentials()
        raw_metadata = self._execute(service.files().get(fileId=target, fields=self._FILE_FIELDS, supportsAllDrives=True))
        if not isinstance(raw_metadata, dict):
            raise RuntimeError("Google Drive returned malformed file metadata")
        metadata = self._public_file(raw_metadata)
        mime_type = metadata["mime_type"]
        if metadata["is_folder"]:
            raise ValueError("Google Drive folders do not have readable file content")
        if metadata["capabilities"].get("canDownload") is False:
            raise PermissionError("Google Drive does not allow this file to be downloaded or exported by the connected account")
        if mime_type in GOOGLE_DRIVE_NATIVE_EXPORT_MIME_TYPES:
            result_mime = GOOGLE_DRIVE_NATIVE_EXPORT_MIME_TYPES[mime_type]
            request = service.files().export_media(fileId=target, mimeType=result_mime)
        else:
            if not (mime_type.startswith("text/") or mime_type in GOOGLE_DRIVE_TEXT_MIME_TYPES):
                raise ValueError(
                    f"Google Drive file MIME type {mime_type or '(unknown)'} is not directly readable as text. "
                    "Download it explicitly and use the matching document tool."
                )
            result_mime = mime_type
            request = service.files().get_media(fileId=target, supportsAllDrives=True)
        payload = self._execute(request)
        if isinstance(payload, str):
            text = payload
            byte_count = len(payload.encode("utf-8"))
        elif isinstance(payload, (bytes, bytearray)):
            raw = bytes(payload)
            byte_count = len(raw)
            text = ""
            for encoding in ("utf-8-sig", "utf-16", "latin-1"):
                try:
                    text = raw.decode(encoding)
                    break
                except UnicodeError:
                    continue
        else:
            text = json.dumps(payload, ensure_ascii=False, indent=2)
            byte_count = len(text.encode("utf-8"))
        limit = max(1, int(max_chars))
        return {
            **metadata,
            "mime_type": result_mime,
            "byte_count": byte_count,
            "truncated": len(text) > limit,
            "content": text[:limit],
            "ad_hoc": True,
        }

    async def read_file(self, file_id: str, max_chars: int) -> dict[str, Any]:
        return await asyncio.to_thread(self._read_file_blocking, file_id, max_chars)

    @staticmethod
    def _unique_download_path(directory: Path, filename: str) -> Path:
        directory.mkdir(parents=True, exist_ok=True)
        candidate = directory / safe_filename(filename)
        if not candidate.exists():
            return candidate
        stem, suffix = candidate.stem, candidate.suffix
        for index in range(2, 10_000):
            next_path = directory / f"{stem}_{index}{suffix}"
            if not next_path.exists():
                return next_path
        raise FileExistsError(f"Could not allocate a unique Google Drive download path for {filename!r}")

    def _download_file_blocking(self, file_id: str, directory: Path, max_bytes: int) -> dict[str, Any]:
        target = str(file_id or "").strip()
        if not target:
            raise ValueError("Google Drive file ID is required")
        service, _credentials, _dependencies = self._service_from_saved_credentials()
        raw_metadata = self._execute(
            service.files().get(fileId=target, fields=self._FILE_FIELDS, supportsAllDrives=True)
        )
        if not isinstance(raw_metadata, dict):
            raise RuntimeError("Google Drive returned malformed file metadata")
        metadata = self._public_file(raw_metadata)
        if metadata["is_folder"]:
            raise ValueError("Google Drive folders cannot be downloaded as files")
        if metadata["capabilities"].get("canDownload") is False:
            raise PermissionError("Google Drive does not allow this file to be downloaded or exported by the connected account")

        source_mime = str(metadata.get("mime_type") or "")
        export = GOOGLE_DRIVE_NATIVE_DOWNLOAD_EXPORTS.get(source_mime)
        if export is not None:
            result_mime, extension = export
            request = service.files().export_media(fileId=target, mimeType=result_mime)
        else:
            result_mime = source_mime or "application/octet-stream"
            extension = Path(str(metadata.get("name") or "")).suffix
            request = service.files().get_media(fileId=target, supportsAllDrives=True)
        payload = self._execute(request)
        if isinstance(payload, str):
            raw = payload.encode("utf-8")
        elif isinstance(payload, (bytes, bytearray)):
            raw = bytes(payload)
        else:
            raw = json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8")
        byte_limit = max(1, int(max_bytes))
        if len(raw) > byte_limit:
            raise ValueError(
                f"Google Drive file is {len(raw):,} bytes, above the configured download limit of {byte_limit:,} bytes"
            )
        name = str(metadata.get("name") or target).strip() or target
        if extension and not name.lower().endswith(extension.lower()):
            name += extension
        destination = self._unique_download_path(Path(directory), name)
        file_write_bytes(destination, raw)
        return {
            **metadata,
            "mime_type": result_mime,
            "byte_count": len(raw),
            "path": str(destination.resolve()),
            "ad_hoc": True,
            "read_only_source": True,
        }

    async def download_file(self, file_id: str, directory: Path, max_bytes: int) -> dict[str, Any]:
        return await asyncio.to_thread(self._download_file_blocking, file_id, Path(directory), max_bytes)


class GmailConnector(BaseVaultConnector):
    """Read-only Gmail IMAP connector using one canonical All Mail mailbox."""

    connector_type = GMAIL_SOURCE_TYPE

    def __init__(
        self,
        storage: Storage,
        vault: VaultStore,
        credentials: CredentialStore,
        *,
        imap_factory: Callable[..., Any] = imaplib.IMAP4_SSL,
        progress_callback: Callable[[str, dict[str, Any]], None] | None = None,
        data_changed_callback: Callable[[str], None] | None = None,
        sleep: Callable[[float], None] = time.sleep,
        now: Callable[[], datetime] | None = None,
    ):
        super().__init__(
            storage, vault, credentials,
            progress_callback=progress_callback,
            data_changed_callback=data_changed_callback,
        )
        self.imap_factory = imap_factory
        self.sleep = sleep
        self.now = now or (lambda: datetime.now(timezone.utc))

    def _settings(self) -> dict[str, Any]:
        config = self.storage.load_config()
        validate_vault_connector_settings(config["vault"])
        return copy.deepcopy(config["vault"]["gmail"])

    def validate_configuration(self) -> dict[str, Any]:
        values = self.credentials.load_gmail()
        email_address = str(values.get("email_address") or "").strip()
        app_password = str(values.get("app_password") or "").strip()
        errors: list[str] = []
        if not email_address or "@" not in email_address:
            errors.append("Enter the full Google Workspace email address.")
        if not app_password:
            errors.append("Enter a Google app password.")
        return {
            "configured": not errors,
            "email_address": email_address,
            "app_password_present": bool(app_password),
            "host": GMAIL_IMAP_HOST,
            "port": GMAIL_IMAP_PORT,
            "read_only": True,
            "errors": errors,
        }

    @staticmethod
    def _is_transient_error(exc: BaseException) -> bool:
        return isinstance(exc, (imaplib.IMAP4.abort, TimeoutError, socket.timeout, OSError))

    @staticmethod
    def _require_gmail_extensions(info: dict[str, Any]) -> None:
        if not bool(info.get("gmail_extensions")):
            raise RuntimeError(
                "Gmail did not advertise X-GM-EXT-1; stable Gmail message identities are unavailable"
            )

    def _open_client_once(self, values: dict[str, Any]) -> Any:
        self._check_cancelled()
        try:
            client = self.imap_factory(
                GMAIL_IMAP_HOST, GMAIL_IMAP_PORT,
                timeout=GMAIL_IMAP_TIMEOUT_SECONDS,
            )
        except TypeError:
            client = self.imap_factory(GMAIL_IMAP_HOST, GMAIL_IMAP_PORT)
        try:
            result = client.login(str(values["email_address"]), str(values["app_password"]))
            if isinstance(result, tuple) and str(result[0]).upper() != "OK":
                raise imaplib.IMAP4.error("Gmail authentication failed")
            capabilities = _imap_capabilities(client)
            if "ID" in capabilities and hasattr(client, "_simple_command"):
                try:
                    client._simple_command(
                        "ID", f'("name" "Velox" "version" "{SOURCE_REVISION}" "vendor" "OpenAI")',
                    )
                except Exception:
                    pass
            return client
        except imaplib.IMAP4.error as exc:
            self._logout(client)
            raise RuntimeError(
                "Gmail rejected the email address or app password. Use a Google app password and verify that IMAP access is available."
            ) from exc
        except Exception:
            self._logout(client)
            raise

    @staticmethod
    def _logout(client: Any) -> None:
        try:
            client.logout()
        except Exception:
            try:
                client.shutdown()
            except Exception:
                pass

    def _discover_all_mail(self, client: Any) -> tuple[str, list[dict[str, Any]]]:
        # IMAP LIST has two arguments: a reference name and a mailbox pattern.
        # Gmail's documented form is LIST "" "*". imaplib does not add the
        # required quotes around an empty Python string, so pass the quoted
        # reference name explicitly rather than emitting the invalid LIST  *.
        status, data = client.list('""', '*')
        if str(status).upper() != "OK":
            detail = "; ".join(
                value.decode("utf-8", errors="replace") if isinstance(value, bytes) else str(value)
                for value in (data or [])
            )
            raise RuntimeError("Gmail could not list mailboxes" + (f": {detail}" if detail else ""))
        rows = [row for row in (parse_imap_mailbox_list_line(value) for value in (data or [])) if row]
        for row in rows:
            attrs = {str(value).casefold() for value in row["attributes"]}
            if "\\all" in attrs:
                return str(row["name"]), rows
        raise RuntimeError(
            "Gmail All Mail was not found. Velox requires the mailbox marked \\All to avoid duplicates."
        )

    def _connect_and_select_once(self) -> tuple[Any, dict[str, Any]]:
        validation = self.validate_configuration()
        if not validation["configured"]:
            raise ValueError(" ".join(validation["errors"]))
        values = self.credentials.load_gmail()
        client = self._open_client_once(values)
        try:
            capabilities = _imap_capabilities(client)
            mailbox, mailbox_rows = self._discover_all_mail(client)
            status, _data = client.select(imap_quote_mailbox_name(mailbox), readonly=True)
            if str(status).upper() != "OK":
                raise RuntimeError(f"Gmail could not open {mailbox!r} in read-only mode")
            return client, {
                "capabilities": sorted(capabilities),
                "gmail_extensions": "X-GM-EXT-1" in capabilities,
                "mailbox": mailbox,
                "mailboxes": mailbox_rows,
                "uidvalidity": _imap_uidvalidity(client),
                "email_address": str(values["email_address"]),
            }
        except Exception:
            self._logout(client)
            raise

    def _connect_and_select(self) -> tuple[Any, dict[str, Any]]:
        last_error: BaseException | None = None
        for attempt in range(CONNECTOR_TRANSIENT_RETRY_COUNT + 1):
            self._check_cancelled()
            try:
                return self._connect_and_select_once()
            except Exception as exc:
                last_error = exc
                if not self._is_transient_error(exc) or attempt >= CONNECTOR_TRANSIENT_RETRY_COUNT:
                    raise
                self._progress(f"Connection interrupted; retrying ({attempt + 1}/{CONNECTOR_TRANSIENT_RETRY_COUNT})...")
                self.sleep(0.5 * (attempt + 1))
        assert last_error is not None
        raise last_error

    def _ensure_source_and_mailbox(
        self, email_address: str, mailbox: str, *, connected: bool,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        source = self.vault.upsert_data_source(
            GMAIL_SOURCE_TYPE,
            email_address or "Gmail",
            email_address or "gmail",
            enabled=bool(self._settings().get("enabled")),
            connection_state="connected" if connected else "not_configured",
            credential_reference="credentials/gmail.cred",
            metadata={"provider": "gmail_imap", "read_only": True},
        )
        container = self.vault.upsert_container(
            source["id"], mailbox, "mailbox", mailbox,
            display_name="Gmail — All Mail",
            metadata={"imap_mailbox": mailbox, "special_use": "\\All"},
        )
        return source, container

    @staticmethod
    def _normalized_label_set(labels: Any) -> set[str]:
        rows = labels if isinstance(labels, list) else []
        return {str(row or "").strip().casefold() for row in rows if str(row or "").strip()}

    def _payload_is_included(self, payload: dict[str, Any], settings: dict[str, Any]) -> bool:
        labels = self._normalized_label_set(payload.get("labels"))
        if labels & GMAIL_DRAFT_LABELS or any(label.endswith("/drafts") for label in labels):
            return False
        if not bool(settings.get("include_spam")) and (
            labels & GMAIL_SPAM_LABELS or any(label.endswith("/spam") for label in labels)
        ):
            return False
        if not bool(settings.get("include_trash")) and (
            labels & GMAIL_TRASH_LABELS or any(label.endswith("/trash") for label in labels)
        ):
            return False
        return True

    @staticmethod
    def _metadata_external_id(metadata: dict[str, Any]) -> str:
        try:
            return gmail_stable_external_id(metadata)
        except Exception:
            return ""

    def _history_cutoff(self, settings: dict[str, Any]) -> datetime | None:
        try:
            history_days = int(settings.get("initial_history_days") or 0)
        except Exception:
            history_days = 0
        if history_days <= 0:
            return None
        current = self.now()
        if current.tzinfo is None:
            current = current.replace(tzinfo=timezone.utc)
        return current.astimezone(timezone.utc) - timedelta(days=history_days)

    @staticmethod
    def _payload_timestamp(payload: dict[str, Any]) -> datetime | None:
        for key in ("internal_received_timestamp", "header_date_timestamp"):
            value = str(payload.get(key) or "").strip()
            if not value:
                continue
            try:
                parsed = _parse_iso_datetime(value, field_name=f"Gmail {key}")
                if parsed.tzinfo is None:
                    parsed = parsed.replace(tzinfo=timezone.utc)
                return parsed.astimezone(timezone.utc)
            except Exception:
                continue
        return None

    def _payload_within_history(self, payload: dict[str, Any], cutoff: datetime | None) -> bool:
        if cutoff is None:
            return True
        timestamp = self._payload_timestamp(payload)
        return timestamp is not None and timestamp >= cutoff

    def _tombstone_outside_history_window(
        self, source_id: str, container_id: str, cutoff: datetime | None,
    ) -> int:
        if cutoff is None:
            return 0
        changed = 0
        for item in self.vault.list_items(
            source_id=source_id, container_id=container_id, include_deleted=True,
        ):
            if item.get("is_deleted"):
                continue
            try:
                timestamp = _parse_iso_datetime(
                    item.get("primary_timestamp"), field_name="Gmail primary timestamp",
                )
                if timestamp.tzinfo is None:
                    timestamp = timestamp.replace(tzinfo=timezone.utc)
                timestamp = timestamp.astimezone(timezone.utc)
            except Exception:
                continue
            if timestamp >= cutoff:
                continue
            item["is_deleted"] = True
            item["last_synced_at"] = _connector_now()
            item["content_hash"] = vault_item_content_hash(item)
            self.vault.upsert_item(item)
            changed += 1
        return changed

    def _mark_existing_excluded(
        self,
        source_id: str,
        container_id: str,
        payload: dict[str, Any],
        generation: int,
    ) -> bool:
        external_id = gmail_stable_external_id(payload)
        existing = self.vault.find_item(source_id, external_id)
        if existing is None:
            return False
        payload = copy.deepcopy(payload)
        payload["is_deleted"] = True
        self.vault.upsert_gmail_message(
            source_id, container_id, payload, sync_generation=generation,
        )
        return True

    async def test_connection(self) -> dict[str, Any]:
        self._begin("test")
        self._progress("Connecting...")
        try:
            client, info = await asyncio.to_thread(self._connect_and_select)
            await asyncio.to_thread(self._logout, client)
            self._require_gmail_extensions(info)
            self._finish("Connection test succeeded")
            return {"ok": True, **info}
        except Exception as exc:
            self._fail(exc)
            raise

    def _connect_lifecycle_blocking(self) -> dict[str, Any]:
        client, info = self._connect_and_select()
        try:
            self._require_gmail_extensions(info)
        finally:
            self._logout(client)
        self.storage.update_config(
            lambda config: config["vault"]["gmail"].__setitem__("enabled", True)
        )
        source, _container = self._ensure_source_and_mailbox(
            info["email_address"], info["mailbox"], connected=True,
        )
        self._data_changed()
        return {"ok": True, "source": source, **info}


    def _tombstone_recent_missing(
        self,
        source_id: str,
        container_id: str,
        uidvalidity: str,
        minimum_uid: int,
        seen_external_ids: set[str],
    ) -> int:
        changed = 0
        for item in self.vault.list_items(
            source_id=source_id, container_id=container_id, include_deleted=True,
        ):
            meta = item.get("metadata", {})
            if str(meta.get("imap_uidvalidity") or "") != str(uidvalidity):
                continue
            try:
                uid = int(str(meta.get("imap_uid") or "0"))
            except ValueError:
                continue
            if uid < minimum_uid or item["external_id"] in seen_external_ids or item["is_deleted"]:
                continue
            item["is_deleted"] = True
            item["last_synced_at"] = _connector_now()
            item["content_hash"] = vault_item_content_hash(item)
            self.vault.upsert_item(item)
            changed += 1
        return changed

    def _sync_once_blocking(self, attempted_at: str) -> dict[str, Any]:
        client, info = self._connect_and_select_once()
        source, container = self._ensure_source_and_mailbox(
            info["email_address"], info["mailbox"], connected=True,
        )
        self.vault.update_data_source_sync_status(
            source["id"], connection_state="syncing", started_at=attempted_at, error="",
        )
        try:
            self._progress("Loading containers...")
            capabilities = set(info["capabilities"])
            self._require_gmail_extensions(info)
            uidvalidity = str(info.get("uidvalidity") or "")
            if not uidvalidity:
                raise RuntimeError("Gmail did not return UIDVALIDITY for All Mail")
            uid_state = self.vault.find_sync_state(
                source["id"], container["id"], "gmail_imap_uid",
            )
            validity_state = self.vault.find_sync_state(
                source["id"], container["id"], "gmail_uidvalidity",
            )
            prior_validity = str(validity_state.get("cursor_value") or "") if validity_state else ""
            prior_uid = int(str(uid_state.get("cursor_value") or "0")) if uid_state else 0
            validity_changed = bool(prior_validity and prior_validity != uidvalidity)
            if validity_changed:
                self._progress(
                    f"UIDVALIDITY changed from {prior_validity} to {uidvalidity}; rebuilding UID mapping"
                )
                prior_uid = 0
            settings = self._settings()
            history_cutoff = self._history_cutoff(settings)
            history_days = int(settings.get("initial_history_days") or 0)
            window_uids: list[int] | None = None
            if history_cutoff is not None:
                # Gmail documents X-GM-RAW as the IMAP bridge to Gmail search
                # syntax. Epoch seconds avoid the PST-midnight interpretation of
                # date-only ``after:YYYY/MM/DD`` queries.
                window_uids = _imap_search_uids(
                    client, "X-GM-RAW", f'"after:{int(history_cutoff.timestamp())}"',
                )
            if prior_uid > 0:
                new_uids = _imap_search_uids(client, f"UID {prior_uid + 1}:*")
            elif window_uids is not None:
                new_uids = list(window_uids)
            else:
                new_uids = _imap_search_uids(client, "ALL")
            highest_available = max(new_uids, default=prior_uid) or prior_uid or 1
            recent_start = max(1, highest_available - GMAIL_RECENT_RECONCILE_UID_COUNT + 1)
            recent_uids = _imap_search_uids(client, f"UID {recent_start}:*")
            if window_uids is not None:
                allowed = set(window_uids)
                recent_uids = [uid for uid in recent_uids if uid in allowed]
            target_uids = sorted(set(new_uids).union(recent_uids))
            new_uid_set = set(new_uids)
            generation = self.vault.next_sync_generation(source["id"], container["id"])
            processed = 0
            excluded = 0
            malformed = 0
            outside_history = 0
            seen_external_ids: set[str] = set()
            highest_committed = prior_uid
            fetch_spec = (
                "(X-GM-MSGID X-GM-THRID X-GM-LABELS UID FLAGS "
                "INTERNALDATE RFC822.SIZE BODY.PEEK[])"
            )
            for batch_index, batch in enumerate(
                _chunks(target_uids, GMAIL_FETCH_BATCH_SIZE), start=1,
            ):
                self._check_cancelled()
                self._progress(f"Processing {processed} of {len(target_uids)} messages...")
                status, data = client.uid(
                    "fetch", ",".join(str(uid) for uid in batch), fetch_spec,
                )
                if str(status).upper() != "OK":
                    raise imaplib.IMAP4.abort(
                        f"Gmail IMAP fetch failed for UID batch {batch_index}"
                    )
                fetched = parse_gmail_fetch_data(
                    data, uidvalidity=uidvalidity, mailbox=info["mailbox"],
                )
                returned_uids = {
                    int(str(metadata.get("imap_uid") or "0"))
                    for metadata, _raw in fetched
                    if str(metadata.get("imap_uid") or "").isdigit()
                }
                missing_uids = sorted(set(batch) - returned_uids)
                if missing_uids:
                    raise imaplib.IMAP4.abort(
                        "Gmail IMAP fetch omitted requested UIDs: "
                        + ", ".join(str(uid) for uid in missing_uids[:12])
                    )
                for metadata, raw_message in fetched:
                    self._check_cancelled()
                    external_hint = self._metadata_external_id(metadata)
                    if external_hint:
                        seen_external_ids.add(external_hint)
                    try:
                        payload = parse_gmail_mime_message(raw_message, metadata)
                        external_id = gmail_stable_external_id(payload)
                        seen_external_ids.add(external_id)
                        if not self._payload_within_history(payload, history_cutoff):
                            outside_history += 1
                            self._mark_existing_excluded(
                                source["id"], container["id"], payload, generation,
                            )
                            continue
                        if not self._payload_is_included(payload, settings):
                            excluded += 1
                            self._mark_existing_excluded(
                                source["id"], container["id"], payload, generation,
                            )
                            continue
                        self.vault.upsert_gmail_message(
                            source["id"], container["id"], payload,
                            sync_generation=generation,
                        )
                        processed += 1
                    except Exception as exc:
                        malformed += 1
                        self.storage.append_app_log(
                            "gmail.message_skipped",
                            {
                                "uid": metadata.get("imap_uid"),
                                "error": f"{type(exc).__name__}: {exc}",
                            },
                        )
                new_in_batch = [uid for uid in batch if uid in new_uid_set]
                if new_in_batch:
                    highest_committed = max(highest_committed, max(new_in_batch))
                self.vault.commit_sync_state(
                    source["id"], container["id"], "gmail_imap_uid",
                    highest_committed, generation,
                    metadata={
                        "uidvalidity": uidvalidity,
                        "mailbox": info["mailbox"],
                        "batch_index": batch_index,
                        "history_days": history_days,
                    },
                    attempted_at=attempted_at,
                    successful_at=_connector_now(),
                )
                self._data_changed()
            self._progress("Finalizing...")
            tombstoned = self._tombstone_recent_missing(
                source["id"], container["id"], uidvalidity,
                recent_start, seen_external_ids,
            )
            history_pruned = self._tombstone_outside_history_window(
                source["id"], container["id"], history_cutoff,
            )
            finalized_at = _connector_now()
            self.vault.commit_sync_state(
                source["id"], container["id"], "gmail_imap_uid",
                highest_committed, generation,
                metadata={
                    "uidvalidity": uidvalidity,
                    "mailbox": info["mailbox"],
                    "last_reconciliation_at": finalized_at,
                    "recent_window_start_uid": recent_start,
                    "history_days": history_days,
                },
                attempted_at=attempted_at,
                successful_at=finalized_at,
            )
            self.vault.commit_sync_state(
                source["id"], container["id"], "gmail_uidvalidity",
                uidvalidity, generation,
                metadata={
                    "mailbox": info["mailbox"],
                    "highest_uid": highest_committed,
                    "last_reconciliation_at": finalized_at,
                },
                attempted_at=attempted_at,
                successful_at=finalized_at,
            )
            source = self.vault.update_data_source_sync_status(
                source["id"], connection_state="connected",
                completed_at=finalized_at, successful_at=finalized_at, error="",
            )
            self._data_changed()
            return {
                "ok": True,
                "source_id": source["id"],
                "processed": processed,
                "excluded": excluded,
                "malformed": malformed,
                "outside_history": outside_history,
                "history_pruned": history_pruned,
                "tombstoned": tombstoned,
                "history_days": history_days,
                "highest_uid": highest_committed,
                "uidvalidity": uidvalidity,
                "validity_changed": validity_changed,
            }
        finally:
            self._logout(client)

    def _record_final_sync_failure(self, exc: BaseException, attempted_at: str) -> None:
        source = self._source()
        if source is None:
            return
        self.vault.update_data_source_sync_status(
            source["id"], connection_state="error",
            completed_at=_connector_now(), error=str(exc),
        )
        containers = self.vault.list_containers(source["id"])
        if containers:
            self.vault.record_sync_failure(
                source["id"], containers[0]["id"], "gmail_imap_uid",
                str(exc), attempted_at=attempted_at,
            )

    def _sync_blocking(self) -> dict[str, Any]:
        attempted_at = _connector_now()
        last_error: BaseException | None = None
        for attempt in range(CONNECTOR_TRANSIENT_RETRY_COUNT + 1):
            self._check_cancelled()
            try:
                return self._sync_once_blocking(attempted_at)
            except Exception as exc:
                last_error = exc
                if not self._is_transient_error(exc) or attempt >= CONNECTOR_TRANSIENT_RETRY_COUNT:
                    self._record_final_sync_failure(exc, attempted_at)
                    raise
                self._progress(
                    f"Temporary Gmail connection failure; retrying ({attempt + 1}/{CONNECTOR_TRANSIENT_RETRY_COUNT})..."
                )
                self.sleep(0.5 * (attempt + 1))
        assert last_error is not None
        self._record_final_sync_failure(last_error, attempted_at)
        raise last_error

    async def sync(self) -> dict[str, Any]:
        return await self._run_blocking_lifecycle(
            "sync", self._sync_blocking,
            progress_message="Connecting...", success_message="Complete",
        )

    def _disconnect_lifecycle_blocking(self) -> dict[str, Any]:
        self.credentials.clear_gmail_app_password()
        self.storage.update_config(
            lambda config: config["vault"]["gmail"].__setitem__("enabled", False)
        )
        source = self._source()
        if source:
            source = self.vault.upsert_data_source(
                GMAIL_SOURCE_TYPE,
                source["display_name"],
                source["account_identifier"],
                enabled=False,
                connection_state="disabled",
                credential_reference="credentials/gmail.cred",
                metadata=source.get("metadata", {}),
                source_id=source["id"],
            )
        self._data_changed()
        return {"ok": True, "source": source}


def _http_header_value(headers: Any, name: str, default: str = "") -> str:
    target = str(name or "").casefold()
    try:
        rows = headers.items()
    except Exception:
        rows = []
    for key, value in rows:
        if str(key or "").casefold() == target:
            return str(value or default)
    return str(default)


def slack_granted_scopes(payload: Any, stored_scopes: Iterable[Any] = ()) -> set[str]:
    """Collect granted Slack user scopes from saved OAuth state and API headers."""
    scopes = {str(row or "").strip() for row in stored_scopes if str(row or "").strip()}
    raw = payload if isinstance(payload, dict) else {}
    for key in ("scope", "scopes"):
        value = raw.get(key)
        values = value if isinstance(value, list) else str(value or "").split(",")
        scopes.update(str(row or "").strip() for row in values if str(row or "").strip())
    headers = raw.get("_response_headers") if isinstance(raw.get("_response_headers"), dict) else {}
    header_value = _http_header_value(headers, "x-oauth-scopes")
    scopes.update(row.strip() for row in header_value.split(",") if row.strip())
    return scopes


class SlackWebAPIClient:
    """Small read-only Slack Web API client with pagination-safe retries."""

    def __init__(
        self,
        access_token: str,
        *,
        opener: Callable[..., Any] = urllib.request.urlopen,
        sleep: Callable[[float], None] = time.sleep,
        cancel_event: threading.Event | None = None,
    ):
        self.access_token = str(access_token or "").strip()
        self.opener = opener
        self.sleep = sleep
        self.cancel_event = cancel_event or threading.Event()

    def _wait(self, seconds: float) -> None:
        delay = max(0.0, float(seconds))
        if self.cancel_event.is_set():
            raise ConnectorCancelledError("Slack synchronization cancelled")
        if delay <= 0.0:
            self.sleep(0.0)
            return
        deadline = time.monotonic() + delay
        while time.monotonic() < deadline:
            if self.cancel_event.is_set():
                raise ConnectorCancelledError("Slack synchronization cancelled")
            self.sleep(min(0.1, max(0.0, deadline - time.monotonic())))

    @staticmethod
    def _header(headers: dict[str, Any], name: str, default: str = "") -> str:
        target = str(name).casefold()
        for key, value in headers.items():
            if str(key).casefold() == target:
                return str(value)
        return default

    def call(self, method: str, params: dict[str, Any] | None = None) -> dict[str, Any]:
        if not self.access_token:
            raise SlackAPIError("not_authed")
        encoded_params: dict[str, str] = {}
        for key, value in (params or {}).items():
            if value is None:
                continue
            if isinstance(value, bool):
                encoded_params[str(key)] = "true" if value else "false"
            else:
                encoded_params[str(key)] = str(value)
        body = urllib.parse.urlencode(encoded_params).encode("utf-8")
        request = urllib.request.Request(
            f"{SLACK_API_BASE_URL}/{str(method).strip()}",
            data=body,
            method="POST",
            headers={
                "Authorization": f"Bearer {self.access_token}",
                "Content-Type": "application/x-www-form-urlencoded; charset=utf-8",
                "User-Agent": CONNECTOR_USER_AGENT,
            },
        )
        last_error: BaseException | None = None
        for attempt in range(CONNECTOR_TRANSIENT_RETRY_COUNT + 1):
            if self.cancel_event.is_set():
                raise ConnectorCancelledError("Slack synchronization cancelled")
            status = 0
            headers: dict[str, Any] = {}
            raw = b""
            try:
                with self.opener(request, timeout=SLACK_NETWORK_TIMEOUT_SECONDS) as response:
                    status = int(getattr(response, "status", 200) or 200)
                    headers = dict(getattr(response, "headers", {}) or {})
                    raw = response.read()
            except urllib.error.HTTPError as exc:
                status = int(exc.code or 0)
                headers = dict(exc.headers or {})
                raw = exc.read() if hasattr(exc, "read") else b""
                last_error = exc
            except (urllib.error.URLError, TimeoutError, socket.timeout, OSError) as exc:
                last_error = exc
                if attempt < CONNECTOR_TRANSIENT_RETRY_COUNT:
                    self._wait(0.5 * (attempt + 1))
                    continue
                raise SlackAPIError(f"network_error: {exc}") from exc

            retry_after = float(self._header(headers, "Retry-After", "1") or 1)
            if status == 429:
                if attempt < CONNECTOR_TRANSIENT_RETRY_COUNT:
                    self._wait(retry_after)
                    continue
                raise SlackAPIError("ratelimited", status=status)
            if status >= 500 and attempt < CONNECTOR_TRANSIENT_RETRY_COUNT:
                self._wait(0.5 * (attempt + 1))
                continue

            try:
                payload = json.loads(raw.decode("utf-8"))
            except Exception as exc:
                if status >= 500 and attempt < CONNECTOR_TRANSIENT_RETRY_COUNT:
                    self._wait(0.5 * (attempt + 1))
                    continue
                error_name = f"http_{status}" if status else "malformed_response"
                raise SlackAPIError(error_name, status=status) from exc
            if not isinstance(payload, dict):
                raise SlackAPIError("malformed_response", status=status)
            if not bool(payload.get("ok")):
                error = str(payload.get("error") or (f"http_{status}" if status else "unknown_error"))
                missing_scope = str(payload.get("needed") or payload.get("missing_scope") or "")
                if (
                    error in {"ratelimited", "internal_error", "fatal_error", "request_timeout", "service_unavailable"}
                    and attempt < CONNECTOR_TRANSIENT_RETRY_COUNT
                ):
                    self._wait(retry_after if error == "ratelimited" else 0.5 * (attempt + 1))
                    continue
                raise SlackAPIError(error, status=status, missing_scope=missing_scope)
            if status >= 400:
                raise SlackAPIError(f"http_{status}", status=status)
            payload["_response_headers"] = {str(k): str(v) for k, v in headers.items()}
            return payload
        if last_error is not None:
            raise SlackAPIError(f"network_error: {last_error}") from last_error
        raise SlackAPIError("retry_exhausted")


def normalize_slack_text(
    value: Any,
    *,
    users: dict[str, dict[str, Any]] | None = None,
    channels: dict[str, dict[str, Any]] | None = None,
) -> tuple[str, list[dict[str, str]]]:
    text = html.unescape(str(value or ""))
    user_map = users or {}
    channel_map = channels or {}
    links: list[dict[str, str]] = []

    def replace_token(match: re.Match[str]) -> str:
        inner = match.group(1)
        if inner.startswith("@"):
            user_id = inner[1:]
            row = user_map.get(user_id, {})
            name = str(row.get("display_name") or row.get("real_name") or user_id)
            return "@" + name
        if inner.startswith("#"):
            body = inner[1:]
            channel_id, _, supplied = body.partition("|")
            row = channel_map.get(channel_id, {})
            name = supplied or str(row.get("name") or row.get("display_name") or channel_id)
            return "#" + name.lstrip("#")
        if inner.startswith("!"):
            return "@" + inner[1:].split("^", 1)[0]
        target, separator, label = inner.partition("|")
        if target.startswith(("http://", "https://", "mailto:")):
            clean_label = label or target
            links.append({"url": target, "label": clean_label})
            return f"{clean_label} ({target})" if clean_label != target else target
        return match.group(0)

    text = re.sub(r"<([^>]+)>", replace_token, text)
    return text, links


def slack_blocks_text(blocks: Any) -> str:
    if not isinstance(blocks, list):
        return ""
    rows: list[str] = []
    for block in blocks:
        if not isinstance(block, dict):
            continue
        block_type = str(block.get("type") or "")
        text_obj = block.get("text")
        if isinstance(text_obj, dict) and str(text_obj.get("text") or "").strip():
            rows.append(str(text_obj["text"]))
        if block_type == "rich_text":
            for element in block.get("elements") or []:
                if not isinstance(element, dict):
                    continue
                for child in element.get("elements") or []:
                    if isinstance(child, dict) and str(child.get("text") or "").strip():
                        rows.append(str(child["text"]))
    return "\n".join(rows).strip()


def _slack_user_row(raw: dict[str, Any]) -> dict[str, Any]:
    profile = raw.get("profile") if isinstance(raw.get("profile"), dict) else {}
    return {
        "id": str(raw.get("id") or ""),
        "display_name": str(profile.get("display_name") or profile.get("real_name") or raw.get("real_name") or raw.get("name") or raw.get("id") or ""),
        "real_name": str(profile.get("real_name") or raw.get("real_name") or ""),
        "email": str(profile.get("email") or ""),
        "deleted": bool(raw.get("deleted")),
        "is_bot": bool(raw.get("is_bot")),
        "avatar_url": str(profile.get("image_72") or profile.get("image_48") or ""),
        "updated": str(raw.get("updated") or ""),
    }


def _slack_conversation_type(raw: dict[str, Any]) -> str:
    if raw.get("is_im"):
        return "slack_direct_message"
    if raw.get("is_mpim"):
        return "slack_group_message"
    if raw.get("is_private"):
        return "slack_private_channel"
    return "slack_public_channel"


def _slack_conversation_name(raw: dict[str, Any], users: dict[str, dict[str, Any]]) -> str:
    if raw.get("is_im"):
        user_id = str(raw.get("user") or "")
        row = users.get(user_id, {})
        return str(row.get("display_name") or row.get("real_name") or user_id or raw.get("id") or "Direct message")
    if raw.get("is_mpim"):
        members = [str(row) for row in raw.get("members", []) if str(row)]
        names = [str(users.get(user_id, {}).get("display_name") or user_id) for user_id in members]
        return ", ".join(names) or str(raw.get("name") or raw.get("id") or "Group message")
    name = str(raw.get("name") or raw.get("name_normalized") or raw.get("id") or "channel")
    return "#" + name.lstrip("#")


class SlackConnector(BaseVaultConnector):
    """Read-only Slack Web API connector using a user OAuth token."""

    connector_type = SLACK_SOURCE_TYPE

    def __init__(
        self,
        storage: Storage,
        vault: VaultStore,
        credentials: CredentialStore,
        *,
        api_client_factory: Callable[..., Any] = SlackWebAPIClient,
        oauth_code_provider: Callable[..., Any] | None = None,
        oauth_opener: Callable[..., Any] = urllib.request.urlopen,
        browser_open: Callable[[str], Any] = webbrowser.open,
        progress_callback: Callable[[str, dict[str, Any]], None] | None = None,
        data_changed_callback: Callable[[str], None] | None = None,
    ):
        super().__init__(
            storage, vault, credentials,
            progress_callback=progress_callback,
            data_changed_callback=data_changed_callback,
        )
        self.api_client_factory = api_client_factory
        self.oauth_code_provider = oauth_code_provider
        self.oauth_opener = oauth_opener
        self.browser_open = browser_open

    def _settings(self) -> dict[str, Any]:
        config = self.storage.load_config()
        validate_vault_connector_settings(config["vault"])
        return copy.deepcopy(config["vault"]["slack"])

    @staticmethod
    def _scope_rows(values: Any) -> list[str]:
        rows = values if isinstance(values, list) else str(values or "").split(",")
        return sorted({str(row or "").strip() for row in rows if str(row or "").strip()})

    def validate_configuration(self) -> dict[str, Any]:
        values = self.credentials.load_slack()
        client_id = str(values.get("client_id") or "").strip()
        client_secret = str(values.get("client_secret") or "").strip()
        token = str(values.get("access_token") or "").strip()
        scopes = self._scope_rows(values.get("scopes"))
        missing_scopes = [scope for scope in SLACK_REQUIRED_USER_SCOPES if scopes and scope not in scopes]
        errors: list[str] = []
        if not client_id:
            errors.append("Enter the Slack client ID.")
        if not client_secret:
            errors.append("Enter the Slack client secret.")
        if token and not token.startswith("xoxp-"):
            errors.append("Slack requires a user access token with the xoxp- prefix.")
        if missing_scopes:
            errors.append("Slack authorization is missing read scopes: " + ", ".join(missing_scopes))
        return {
            "configured": bool(client_id and client_secret),
            "token_present": bool(token),
            "token_valid_shape": bool(not token or token.startswith("xoxp-")),
            "client_id": client_id,
            "workspace_id": str(values.get("workspace_id") or ""),
            "authenticated_user_id": str(values.get("authenticated_user_id") or ""),
            "team_name": str(values.get("team_name") or ""),
            "scopes": scopes,
            "missing_scopes": missing_scopes,
            "read_only": True,
            "errors": errors,
        }

    def _require_read_scopes(self, payload: dict[str, Any] | None = None) -> list[str]:
        values = self.credentials.load_slack()
        granted = slack_granted_scopes(payload or {}, values.get("scopes") or [])
        if granted:
            missing = [scope for scope in SLACK_REQUIRED_USER_SCOPES if scope not in granted]
            if missing:
                raise SlackAPIError("missing_scope", missing_scope=", ".join(missing))
        return sorted(granted)

    def _client(self) -> Any:
        values = self.credentials.load_slack()
        token = str(values.get("access_token") or "").strip()
        if not token:
            raise SlackAPIError("not_authed")
        if not token.startswith("xoxp-"):
            raise SlackAPIError("invalid_auth")
        scopes = self._scope_rows(values.get("scopes"))
        missing = [scope for scope in SLACK_REQUIRED_USER_SCOPES if scopes and scope not in scopes]
        if missing:
            raise SlackAPIError("missing_scope", missing_scope=", ".join(missing))
        try:
            return self.api_client_factory(token, cancel_event=self._cancel_event)
        except TypeError:
            return self.api_client_factory(token)

    @staticmethod
    def _next_cursor(payload: dict[str, Any]) -> str:
        metadata = payload.get("response_metadata") if isinstance(payload.get("response_metadata"), dict) else {}
        return str(metadata.get("next_cursor") or "").strip()

    def _paged(
        self,
        client: Any,
        method: str,
        params: dict[str, Any],
        key: str,
    ) -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        cursor = ""
        seen_cursors: set[str] = set()
        while True:
            self._check_cancelled()
            request = dict(params)
            if cursor:
                request["cursor"] = cursor
            payload = client.call(method, request)
            page_rows = payload.get(key)
            if not isinstance(page_rows, list):
                raise SlackAPIError("malformed_response")
            rows.extend(row for row in page_rows if isinstance(row, dict))
            next_cursor = self._next_cursor(payload)
            if not next_cursor:
                return rows
            if next_cursor in seen_cursors or next_cursor == cursor:
                raise SlackAPIError("repeated_cursor")
            seen_cursors.add(next_cursor)
            cursor = next_cursor

    def _run_oauth_callback(
        self,
        client_id: str,
        redirect_uri: str,
        scopes: tuple[str, ...],
    ) -> str:
        if self.oauth_code_provider is not None:
            result = self.oauth_code_provider(client_id, redirect_uri, scopes, self._cancel_event)
            if asyncio.iscoroutine(result):
                result = asyncio.run(result)
            if isinstance(result, dict):
                error = str(result.get("error") or "").strip()
                if error:
                    raise RuntimeError("Slack authorization was denied: " + error)
                result = result.get("code")
            code = str(result or "").strip()
            if not code:
                raise RuntimeError("Slack OAuth callback did not include an authorization code")
            return code

        parsed = urllib.parse.urlparse(redirect_uri)
        if parsed.scheme != "http" or parsed.hostname not in {"127.0.0.1", "localhost"} or not parsed.port:
            raise ValueError("Slack redirect URI must be a localhost HTTP URL with an explicit port")
        state_value = secrets.token_urlsafe(24)
        captured: dict[str, str] = {}
        expected_path = parsed.path or "/"

        class Handler(http.server.BaseHTTPRequestHandler):
            def do_GET(self) -> None:  # type: ignore[override]
                request_url = urllib.parse.urlparse(self.path)
                if request_url.path != expected_path:
                    self.send_error(404)
                    return
                query = urllib.parse.parse_qs(request_url.query)
                captured["state"] = str((query.get("state") or [""])[0])
                captured["code"] = str((query.get("code") or [""])[0])
                captured["error"] = str((query.get("error") or [""])[0])
                success = not captured["error"]
                body = (
                    b"<html><body><h2>Slack connected to Velox.</h2><p>You can close this window.</p></body></html>"
                    if success else
                    b"<html><body><h2>Slack authorization was not completed.</h2><p>You can close this window.</p></body></html>"
                )
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)

            def log_message(self, _format: str, *_args: Any) -> None:
                return

        server = http.server.HTTPServer((str(parsed.hostname), int(parsed.port)), Handler)
        server.timeout = 0.25
        query = urllib.parse.urlencode({
            "client_id": client_id,
            "user_scope": ",".join(scopes),
            "redirect_uri": redirect_uri,
            "state": state_value,
        })
        self.browser_open(SLACK_OAUTH_AUTHORIZE_URL + "?" + query)
        deadline = time.monotonic() + 300.0
        try:
            while time.monotonic() < deadline and not captured:
                self._check_cancelled()
                server.handle_request()
        finally:
            server.server_close()
        if not captured:
            raise TimeoutError("Slack OAuth browser sign-in timed out")
        if captured.get("state") != state_value:
            raise RuntimeError("Slack OAuth callback state did not match")
        if captured.get("error"):
            raise RuntimeError("Slack authorization was denied: " + captured["error"])
        if not captured.get("code"):
            raise RuntimeError("Slack OAuth callback did not include an authorization code")
        return captured["code"]

    def _exchange_oauth_code(
        self,
        client_id: str,
        client_secret: str,
        code: str,
        redirect_uri: str,
    ) -> dict[str, Any]:
        body = urllib.parse.urlencode({
            "client_id": client_id,
            "client_secret": client_secret,
            "code": code,
            "redirect_uri": redirect_uri,
        }).encode("utf-8")
        request = urllib.request.Request(
            SLACK_OAUTH_ACCESS_URL,
            data=body,
            method="POST",
            headers={
                "Content-Type": "application/x-www-form-urlencoded; charset=utf-8",
                "User-Agent": CONNECTOR_USER_AGENT,
            },
        )
        try:
            with self.oauth_opener(request, timeout=SLACK_NETWORK_TIMEOUT_SECONDS) as response:
                raw = response.read()
        except urllib.error.HTTPError as exc:
            raw = exc.read() if hasattr(exc, "read") else b""
            try:
                payload = json.loads(raw.decode("utf-8"))
            except Exception:
                payload = {}
            raise SlackAPIError(
                str(payload.get("error") or f"http_{int(exc.code or 0)}"),
                status=int(exc.code or 0),
            ) from exc
        try:
            payload = json.loads(raw.decode("utf-8"))
        except Exception as exc:
            raise SlackAPIError("malformed_response") from exc
        if not isinstance(payload, dict) or not payload.get("ok"):
            raise SlackAPIError(
                str(payload.get("error") if isinstance(payload, dict) else "malformed_response"),
                missing_scope=str(payload.get("needed") or "") if isinstance(payload, dict) else "",
            )
        return payload

    def _ensure_source(self, auth: dict[str, Any], *, connected: bool) -> dict[str, Any]:
        credentials = self.credentials.load_slack()
        workspace_id = str(
            auth.get("team_id") or auth.get("workspace_id")
            or credentials.get("workspace_id") or "slack"
        )
        team_name = str(
            auth.get("team") or auth.get("team_name")
            or credentials.get("team_name") or "Slack"
        )
        user_id = str(
            auth.get("user_id") or auth.get("authenticated_user_id")
            or credentials.get("authenticated_user_id") or ""
        )
        existing = self.vault.find_data_source(SLACK_SOURCE_TYPE, workspace_id)
        metadata = copy.deepcopy(existing.get("metadata", {})) if existing else {}
        metadata.update({
            "provider": "slack_web_api",
            "read_only": True,
            "authenticated_user_id": user_id,
        })
        return self.vault.upsert_data_source(
            SLACK_SOURCE_TYPE,
            team_name or "Slack",
            workspace_id,
            enabled=bool(self._settings().get("enabled")),
            connection_state="connected" if connected else "not_configured",
            credential_reference="credentials/slack.cred",
            metadata=metadata,
            source_id=existing["id"] if existing else None,
        )

    async def test_connection(self) -> dict[str, Any]:
        self._begin("test")
        self._progress("Connecting...")
        try:
            client = self._client()
            auth = await asyncio.to_thread(client.call, "auth.test", {})
            granted = self._require_read_scopes(auth)
            self._finish("Connection test succeeded")
            return {"ok": True, "granted_scopes": granted, **auth}
        except Exception as exc:
            self._fail(exc)
            raise

    def _connect_lifecycle_blocking(self) -> dict[str, Any]:
        values = self.credentials.load_slack()
        client_id = str(values.get("client_id") or "").strip()
        client_secret = str(values.get("client_secret") or "").strip()
        if not client_id or not client_secret:
            raise ValueError("Slack client ID and client secret are required")
        redirect_uri = str(self._settings().get("redirect_uri") or SLACK_REDIRECT_URI_DEFAULT)
        code = self._run_oauth_callback(client_id, redirect_uri, SLACK_USER_SCOPES)
        oauth = self._exchange_oauth_code(client_id, client_secret, code, redirect_uri)
        authed_user = oauth.get("authed_user") if isinstance(oauth.get("authed_user"), dict) else {}
        token = str(authed_user.get("access_token") or "").strip()
        if not token.startswith("xoxp-"):
            raise RuntimeError("Slack did not return a user access token")
        team = oauth.get("team") if isinstance(oauth.get("team"), dict) else {}
        scopes = self._scope_rows(authed_user.get("scope") or oauth.get("scope"))
        missing_scopes = [scope for scope in SLACK_REQUIRED_USER_SCOPES if scope not in scopes]
        if missing_scopes:
            raise SlackAPIError("missing_scope", missing_scope=", ".join(missing_scopes))
        self.credentials.save_slack_token(
            token,
            workspace_id=str(team.get("id") or ""),
            authenticated_user_id=str(authed_user.get("id") or ""),
            team_name=str(team.get("name") or ""),
            scopes=scopes,
        )
        self.storage.update_config(
            lambda config: config["vault"]["slack"].__setitem__("enabled", True)
        )
        client = self._client()
        auth = client.call("auth.test", {})
        granted = self._require_read_scopes(auth)
        source = self._ensure_source(auth, connected=True)
        self._data_changed()
        return {"ok": True, "source": source, "auth": auth, "scopes": granted or scopes}


    def _save_user_cache(
        self,
        source: dict[str, Any],
        users: dict[str, dict[str, Any]],
    ) -> dict[str, Any]:
        current = self.vault.get_data_source(source["id"])
        metadata = copy.deepcopy(current.get("metadata", {}))
        metadata["user_cache"] = copy.deepcopy(users)
        metadata["user_cache_updated_at"] = _connector_now()
        return self.vault.upsert_data_source(
            SLACK_SOURCE_TYPE,
            current["display_name"],
            current["account_identifier"],
            enabled=current["enabled"],
            connection_state=current["connection_state"],
            credential_reference=current["credential_reference"],
            metadata=metadata,
            source_id=current["id"],
        )

    def _load_users(
        self,
        client: Any,
        source: dict[str, Any],
    ) -> dict[str, dict[str, Any]]:
        metadata = copy.deepcopy(source.get("metadata", {}))
        cached = metadata.get("user_cache") if isinstance(metadata.get("user_cache"), dict) else {}
        updated_at = str(metadata.get("user_cache_updated_at") or "")
        stale = True
        if updated_at:
            try:
                age = datetime.now(timezone.utc) - _parse_iso_datetime(
                    updated_at, field_name="Slack user cache time",
                )
                stale = age.total_seconds() >= SLACK_USER_CACHE_MAX_AGE_SECONDS
            except Exception:
                stale = True
        if cached and not stale:
            return {
                str(key): copy.deepcopy(value)
                for key, value in cached.items()
                if isinstance(value, dict)
            }
        self._progress("Loading users...")
        rows = self._paged(client, "users.list", {"limit": SLACK_PAGE_SIZE}, "members")
        users = {
            str(row.get("id") or ""): _slack_user_row(row)
            for row in rows
            if str(row.get("id") or "")
        }
        self._save_user_cache(source, users)
        return users

    def _ensure_user(
        self,
        client: Any,
        source: dict[str, Any],
        users: dict[str, dict[str, Any]],
        user_id: str,
    ) -> dict[str, Any]:
        key = str(user_id or "").strip()
        if not key:
            return {}
        if key in users:
            return users[key]
        try:
            payload = client.call("users.info", {"user": key})
            raw = payload.get("user") if isinstance(payload.get("user"), dict) else {}
            if raw:
                users[key] = _slack_user_row(raw)
                self._save_user_cache(source, users)
                return users[key]
        except SlackAPIError as exc:
            self.storage.append_app_log(
                "slack.user_lookup_failed",
                {"user_id": key, "error": str(exc)},
            )
        users[key] = {
            "id": key,
            "display_name": key,
            "real_name": "",
            "email": "",
            "deleted": False,
            "is_bot": key.startswith("B"),
            "avatar_url": "",
            "updated": "",
        }
        return users[key]

    @staticmethod
    def _conversation_types(settings: dict[str, Any]) -> list[str]:
        rows: list[str] = []
        if settings.get("include_public_channels"):
            rows.append("public_channel")
        if settings.get("include_private_channels"):
            rows.append("private_channel")
        if settings.get("include_direct_messages"):
            rows.append("im")
        if settings.get("include_group_direct_messages"):
            rows.append("mpim")
        return rows

    def _resolve_conversation_members(
        self,
        client: Any,
        raw: dict[str, Any],
    ) -> dict[str, Any]:
        if not raw.get("is_mpim") or isinstance(raw.get("members"), list):
            return raw
        try:
            members: list[str] = []
            cursor = ""
            seen_cursors: set[str] = set()
            while True:
                self._check_cancelled()
                request: dict[str, Any] = {
                    "channel": str(raw.get("id") or ""),
                    "limit": SLACK_PAGE_SIZE,
                }
                if cursor:
                    request["cursor"] = cursor
                payload = client.call("conversations.members", request)
                page = payload.get("members")
                if not isinstance(page, list):
                    raise SlackAPIError("malformed_response")
                members.extend(str(row) for row in page if str(row))
                next_cursor = self._next_cursor(payload)
                if not next_cursor:
                    break
                if next_cursor == cursor or next_cursor in seen_cursors:
                    raise SlackAPIError("repeated_cursor")
                seen_cursors.add(next_cursor)
                cursor = next_cursor
            resolved = copy.deepcopy(raw)
            resolved["members"] = members
            return resolved
        except SlackAPIError as exc:
            self.storage.append_app_log(
                "slack.conversation_members_failed",
                {"conversation_id": str(raw.get("id") or ""), "error": str(exc)},
            )
            return raw

    def _message_payload(
        self,
        raw: dict[str, Any],
        *,
        client: Any,
        source: dict[str, Any],
        conversation_id: str,
        conversation_type: str,
        workspace_id: str,
        users: dict[str, dict[str, Any]],
        channels: dict[str, dict[str, Any]],
    ) -> dict[str, Any]:
        subtype = str(raw.get("subtype") or "")
        if subtype == "message_deleted":
            previous = raw.get("previous_message") if isinstance(raw.get("previous_message"), dict) else {}
            timestamp = str(raw.get("deleted_ts") or previous.get("ts") or raw.get("ts") or "")
            source_message = previous
            deleted = True
        else:
            source_message = raw
            timestamp = str(raw.get("ts") or "")
            deleted = False
        user_id = str(source_message.get("user") or source_message.get("bot_id") or "")
        user = self._ensure_user(client, source, users, user_id)
        raw_text = str(source_message.get("text") or "")
        body_source = raw_text or slack_blocks_text(source_message.get("blocks"))
        body_text, links = normalize_slack_text(body_source, users=users, channels=channels)
        author = str(
            user.get("display_name") or user.get("real_name")
            or source_message.get("username") or user_id or "Unknown"
        )
        payload = copy.deepcopy(source_message)
        payload.update({
            "workspace_id": workspace_id,
            "conversation_id": conversation_id,
            "conversation_type": conversation_type,
            "message_timestamp": timestamp,
            "thread_timestamp": str(source_message.get("thread_ts") or ""),
            "parent_message_timestamp": (
                str(source_message.get("thread_ts") or "")
                if str(source_message.get("thread_ts") or "") != timestamp else ""
            ),
            "user_id": user_id,
            "author_display_name": author,
            "raw_text": raw_text,
            "body_text": body_text,
            "links": links,
            "blocks": copy.deepcopy(
                source_message.get("blocks") if isinstance(source_message.get("blocks"), list) else []
            ),
            "files": copy.deepcopy(
                source_message.get("files") if isinstance(source_message.get("files"), list) else []
            ),
            "reactions": copy.deepcopy(
                source_message.get("reactions") if isinstance(source_message.get("reactions"), list) else []
            ),
            "reply_users": copy.deepcopy(
                source_message.get("reply_users") if isinstance(source_message.get("reply_users"), list) else []
            ),
            "latest_reply_timestamp": str(source_message.get("latest_reply") or ""),
            "is_bot": bool(source_message.get("bot_id") or user.get("is_bot")),
            "is_deleted": deleted,
            "source_permalink": str(source_message.get("permalink") or ""),
        })
        return payload

    def _reconcile_overlap(
        self,
        source_id: str,
        container_id: str,
        oldest: float,
        seen_external_ids: set[str],
    ) -> int:
        changed = 0
        for item in self.vault.list_items(
            source_id=source_id,
            container_id=container_id,
            include_deleted=True,
        ):
            try:
                timestamp = _parse_iso_datetime(
                    item["primary_timestamp"], field_name="Slack message timestamp",
                ).timestamp()
            except Exception:
                continue
            if timestamp < oldest or item["external_id"] in seen_external_ids or item["is_deleted"]:
                continue
            item["is_deleted"] = True
            item["last_synced_at"] = _connector_now()
            item["content_hash"] = vault_item_content_hash(item)
            self.vault.upsert_item(item)
            changed += 1
        return changed

    def _recent_thread_timestamps(
        self,
        source_id: str,
        container_id: str,
        oldest: float,
    ) -> set[str]:
        rows: set[str] = set()
        for item in self.vault.list_items(
            source_id=source_id,
            container_id=container_id,
            include_deleted=False,
        ):
            if item.get("item_type") != "slack_message":
                continue
            metadata = item.get("metadata") if isinstance(item.get("metadata"), dict) else {}
            if int(metadata.get("reply_count") or 0) <= 0:
                continue
            message_ts = str(metadata.get("message_timestamp") or "")
            latest_reply = str(metadata.get("latest_reply_timestamp") or "")
            try:
                active = float(latest_reply or message_ts or "0") >= oldest
            except ValueError:
                active = False
            if active and message_ts:
                rows.add(message_ts)
        return rows

    def _sync_thread(
        self,
        client: Any,
        source: dict[str, Any],
        container: dict[str, Any],
        parent_ts: str,
        users: dict[str, dict[str, Any]],
        channels: dict[str, dict[str, Any]],
        generation: int,
        seen: set[str],
    ) -> tuple[int, float]:
        replies = self._paged(
            client,
            "conversations.replies",
            {
                "channel": container["external_id"],
                "ts": parent_ts,
                "limit": SLACK_HISTORY_PAGE_SIZE,
            },
            "messages",
        )
        processed = 0
        newest = 0.0
        for reply in replies:
            self._check_cancelled()
            reply_ts = str(reply.get("ts") or "")
            if not reply_ts or reply_ts == parent_ts:
                # conversations.replies returns the parent first. The canonical
                # parent came from conversations.history and may contain richer
                # file, reaction, edit, and block metadata; do not overwrite it
                # with the frequently sparser thread copy.
                continue
            payload = self._message_payload(
                reply,
                client=client,
                source=source,
                conversation_id=container["external_id"],
                conversation_type=container["container_type"],
                workspace_id=source["account_identifier"],
                users=users,
                channels=channels,
            )
            item = self.vault.upsert_slack_message(
                source["id"], container["id"], payload,
                sync_generation=generation,
            )
            seen.add(item["external_id"])
            newest = max(newest, float(reply_ts))
            processed += 1
        return processed, newest

    def _sync_conversation(
        self,
        client: Any,
        source: dict[str, Any],
        container: dict[str, Any],
        raw_conversation: dict[str, Any],
        users: dict[str, dict[str, Any]],
        channels: dict[str, dict[str, Any]],
        settings: dict[str, Any],
        index: int,
        total: int,
    ) -> dict[str, Any]:
        self._check_cancelled()
        self._progress(f"Synchronizing {index} of {total} channels...")
        state = self.vault.find_sync_state(
            source["id"], container["id"], "slack_latest_timestamp",
        )
        try:
            previous = float(str(state.get("cursor_value") or "0")) if state else 0.0
        except ValueError:
            previous = 0.0
        if previous > 0:
            oldest = max(0.0, previous - SLACK_INCREMENTAL_OVERLAP_SECONDS)
        else:
            history_days = int(settings.get("initial_history_days") or 0)
            oldest = 0.0 if history_days == 0 else max(
                0.0, time.time() - history_days * 86400.0,
            )
        generation = self.vault.next_sync_generation(source["id"], container["id"])
        attempted_at = _connector_now()
        history = self._paged(
            client,
            "conversations.history",
            {
                "channel": container["external_id"],
                "oldest": f"{oldest:.6f}",
                "inclusive": True,
                "limit": SLACK_HISTORY_PAGE_SIZE,
            },
            "messages",
        )
        seen: set[str] = set()
        newest = previous
        processed = 0
        thread_timestamps = self._recent_thread_timestamps(
            source["id"], container["id"], oldest,
        )
        for raw in sorted(
            history,
            key=lambda row: float(str(row.get("ts") or row.get("deleted_ts") or "0")),
        ):
            self._check_cancelled()
            try:
                payload = self._message_payload(
                    raw,
                    client=client,
                    source=source,
                    conversation_id=container["external_id"],
                    conversation_type=container["container_type"],
                    workspace_id=source["account_identifier"],
                    users=users,
                    channels=channels,
                )
                message_ts = str(payload.get("message_timestamp") or "")
                if not message_ts:
                    continue
                item = self.vault.upsert_slack_message(
                    source["id"], container["id"], payload,
                    sync_generation=generation,
                )
                seen.add(item["external_id"])
                newest = max(newest, float(message_ts))
                processed += 1
                if int(raw.get("reply_count") or 0) > 0:
                    thread_timestamps.add(str(raw.get("ts") or ""))
            except ConnectorCancelledError:
                raise
            except Exception as exc:
                self.storage.append_app_log(
                    "slack.message_skipped",
                    {
                        "conversation_id": container["external_id"],
                        "timestamp": str(raw.get("ts") or raw.get("deleted_ts") or ""),
                        "error": f"{type(exc).__name__}: {exc}",
                    },
                )
                continue
        for parent_ts in sorted(
            (value for value in thread_timestamps if value),
            key=lambda value: float(value),
        ):
            self._check_cancelled()
            thread_processed, thread_newest = self._sync_thread(
                client, source, container, parent_ts,
                users, channels, generation, seen,
            )
            processed += thread_processed
            newest = max(newest, thread_newest)
        self._progress(f"Processing {processed} messages in {container['display_name']}...")
        tombstoned = self._reconcile_overlap(
            source["id"], container["id"], oldest, seen,
        )
        successful_at = _connector_now()
        self.vault.commit_sync_state(
            source["id"],
            container["id"],
            "slack_latest_timestamp",
            f"{newest:.6f}" if newest else "",
            generation,
            metadata={
                "overlap_seconds": SLACK_INCREMENTAL_OVERLAP_SECONDS,
                "conversation_id": container["external_id"],
                "last_reconciliation_at": successful_at,
                "tombstoned": tombstoned,
            },
            attempted_at=attempted_at,
            successful_at=successful_at,
        )
        self._data_changed()
        return {
            "processed": processed,
            "newest": newest,
            "tombstoned": tombstoned,
        }

    def _sync_blocking(self) -> dict[str, Any]:
        attempted_at = _connector_now()
        client = self._client()
        self._progress("Connecting...")
        auth = client.call("auth.test", {})
        self._require_read_scopes(auth)
        source = self._ensure_source(auth, connected=True)
        self.vault.update_data_source_sync_status(
            source["id"],
            connection_state="syncing",
            started_at=attempted_at,
            error="",
        )
        settings = self._settings()
        try:
            users = self._load_users(client, source)
            source = self.vault.get_data_source(source["id"])
            types = self._conversation_types(settings)
            if not types:
                raise ValueError("Enable at least one Slack conversation type")
            self._progress("Loading containers...")
            conversations = self._paged(
                client,
                "conversations.list",
                {
                    "types": ",".join(types),
                    "exclude_archived": False,
                    "limit": SLACK_PAGE_SIZE,
                },
                "channels",
            )
            resolved_conversations: list[dict[str, Any]] = []
            for raw in conversations:
                resolved = self._resolve_conversation_members(client, raw)
                for user_id in [
                    str(resolved.get("user") or ""),
                    *[str(row) for row in resolved.get("members", []) if str(row)],
                ]:
                    if user_id:
                        self._ensure_user(client, source, users, user_id)
                resolved_conversations.append(resolved)
            raw_by_id = {
                str(row.get("id") or ""): row
                for row in resolved_conversations
                if str(row.get("id") or "")
            }
            channel_map: dict[str, dict[str, Any]] = {}
            containers: list[dict[str, Any]] = []
            for raw in resolved_conversations:
                conversation_id = str(raw.get("id") or "")
                if not conversation_id:
                    continue
                name = _slack_conversation_name(raw, users)
                container_type = _slack_conversation_type(raw)
                container = self.vault.upsert_container(
                    source["id"],
                    conversation_id,
                    container_type,
                    name,
                    display_name=name,
                    is_archived=bool(raw.get("is_archived")),
                    is_hidden=False,
                    metadata={
                        "name": str(raw.get("name") or ""),
                        "name_normalized": str(raw.get("name_normalized") or ""),
                        "topic": copy.deepcopy(
                            raw.get("topic") if isinstance(raw.get("topic"), dict) else {}
                        ),
                        "purpose": copy.deepcopy(
                            raw.get("purpose") if isinstance(raw.get("purpose"), dict) else {}
                        ),
                        "is_member": bool(raw.get("is_member")),
                        "is_shared": bool(raw.get("is_shared")),
                        "is_ext_shared": bool(raw.get("is_ext_shared")),
                        "user": str(raw.get("user") or ""),
                        "members": [
                            str(row) for row in raw.get("members", []) if str(row)
                        ] if isinstance(raw.get("members"), list) else [],
                    },
                )
                channel_map[conversation_id] = {
                    "name": name.lstrip("#"),
                    "display_name": name,
                }
                if not container["is_archived"]:
                    containers.append(container)
            self._data_changed()
            processed = 0
            tombstoned = 0
            failures: list[str] = []
            for index, container in enumerate(containers, start=1):
                try:
                    summary = self._sync_conversation(
                        client,
                        source,
                        container,
                        raw_by_id.get(container["external_id"], {}),
                        users,
                        channel_map,
                        settings,
                        index,
                        len(containers),
                    )
                    processed += int(summary.get("processed") or 0)
                    tombstoned += int(summary.get("tombstoned") or 0)
                except ConnectorCancelledError:
                    raise
                except SlackAPIError as exc:
                    if exc.error in SLACK_GLOBAL_AUTH_ERRORS:
                        raise
                    error = f"{container['display_name']}: {exc}"
                    failures.append(error)
                    self.vault.record_sync_failure(
                        source["id"],
                        container["id"],
                        "slack_latest_timestamp",
                        error,
                        attempted_at=attempted_at,
                    )
                    self.storage.append_app_log(
                        "slack.channel_sync_failed",
                        {
                            "channel_id": container["external_id"],
                            "error": str(exc),
                        },
                    )
                    continue
                except Exception as exc:
                    error = f"{container['display_name']}: {type(exc).__name__}: {exc}"
                    failures.append(error)
                    self.vault.record_sync_failure(
                        source["id"],
                        container["id"],
                        "slack_latest_timestamp",
                        error,
                        attempted_at=attempted_at,
                    )
                    self.storage.append_app_log(
                        "slack.channel_sync_failed",
                        {
                            "channel_id": container["external_id"],
                            "error": f"{type(exc).__name__}: {exc}",
                        },
                    )
                    continue
            self._progress("Finalizing...")
            completed_at = _connector_now()
            if containers and len(failures) == len(containers):
                raise RuntimeError(
                    "Every accessible Slack conversation failed to synchronize. "
                    + "; ".join(failures[:4])
                )
            source = self.vault.update_data_source_sync_status(
                source["id"],
                connection_state="connected",
                completed_at=completed_at,
                successful_at=completed_at,
                error="; ".join(failures[:4]),
            )
            self._data_changed()
            return {
                "ok": True,
                "source_id": source["id"],
                "containers": len(containers),
                "processed": processed,
                "tombstoned": tombstoned,
                "failures": failures,
            }
        except Exception as exc:
            self.vault.update_data_source_sync_status(
                source["id"],
                connection_state="error",
                completed_at=_connector_now(),
                error=str(exc),
            )
            self._data_changed()
            raise

    async def sync(self) -> dict[str, Any]:
        return await self._run_blocking_lifecycle(
            "sync", self._sync_blocking, success_message="Complete",
        )

    def _disconnect_lifecycle_blocking(self) -> dict[str, Any]:
        self.credentials.clear_slack_token()
        self.storage.update_config(
            lambda config: config["vault"]["slack"].__setitem__("enabled", False)
        )
        source = self._source()
        if source:
            source = self.vault.upsert_data_source(
                SLACK_SOURCE_TYPE,
                source["display_name"],
                source["account_identifier"],
                enabled=False,
                connection_state="disabled",
                credential_reference="credentials/slack.cred",
                metadata=source.get("metadata", {}),
                source_id=source["id"],
            )
        self._data_changed()
        return {"ok": True, "source": source}


class VaultConnectorManager:
    """Independent manual, startup, and periodic scheduling for Vault connectors."""

    _OPERATIONS = frozenset({"sync", "connect", "disconnect", "test"})

    def __init__(
        self,
        storage: Storage,
        google_drive: GoogleDriveConnector,
        gmail: GmailConnector,
        slack: SlackConnector,
        *,
        data_changed_callback: Callable[[str], None] | None = None,
        clock: Callable[[], float] = time.time,
    ):
        self.storage = storage
        self.connectors: dict[str, VaultConnectorContract] = {
            GOOGLE_DRIVE_SOURCE_TYPE: google_drive,
            GMAIL_SOURCE_TYPE: gmail,
            SLACK_SOURCE_TYPE: slack,
        }
        self.data_changed_callback = data_changed_callback
        self.clock = clock
        self.tasks: dict[str, asyncio.Task] = {}
        now = self.clock()
        self.next_due: dict[str, float] = {
            GMAIL_SOURCE_TYPE: now + CONNECTOR_STARTUP_DELAY_SECONDS,
            SLACK_SOURCE_TYPE: now + CONNECTOR_STARTUP_DELAY_SECONDS,
        }
        self._shutting_down = False

    def connector(self, source_type: str) -> VaultConnectorContract:
        key = str(source_type or "").strip().lower()
        if key not in self.connectors:
            raise ValueError(f"Unsupported Vault connector: {source_type}")
        return self.connectors[key]

    def _interval_seconds(self, source_type: str) -> float:
        if source_type == GOOGLE_DRIVE_SOURCE_TYPE:
            return 0.0
        config = self.storage.load_config()["vault"][source_type]
        return max(60.0, float(config.get("sync_interval_minutes") or 1) * 60.0)

    def _enabled(self, source_type: str) -> bool:
        config = self.storage.load_config()["vault"][source_type]
        try:
            status = self.connector(source_type).validate_configuration()
        except Exception:
            return False
        if source_type == SLACK_SOURCE_TYPE:
            return bool(
                config.get("enabled")
                and status.get("configured")
                and status.get("token_present")
                and status.get("token_valid_shape", True)
                and not status.get("missing_scopes")
            )
        return bool(config.get("enabled") and status.get("configured"))

    async def _run(self, source_type: str, operation: str) -> dict[str, Any]:
        connector = self.connector(source_type)
        method = {
            "sync": connector.sync,
            "connect": connector.connect_or_authorize,
            "disconnect": connector.disconnect,
            "test": connector.test_connection,
        }[operation]
        try:
            result = await method()
            if operation in {"sync", "connect", "disconnect"} and callable(self.data_changed_callback):
                try:
                    self.data_changed_callback(source_type)
                except Exception as exc:
                    try:
                        self.storage.append_app_log(
                            f"{source_type}.manager_data_changed_callback_failed",
                            {"error": f"{type(exc).__name__}: {exc}"},
                        )
                    except Exception:
                        pass
            return result
        finally:
            if source_type in self.next_due:
                self.next_due[source_type] = self.clock() + self._interval_seconds(source_type)

    def _consume_finished_task(self, source_type: str, task: asyncio.Task) -> None:
        """Retrieve one completed task result before replacing or dropping it."""
        if not task.done():
            return
        try:
            task.result()
        except (asyncio.CancelledError, ConnectorCancelledError):
            pass
        except Exception as exc:
            try:
                self.storage.append_app_log(
                    f"{source_type}.background_sync_failed",
                    {"error": f"{type(exc).__name__}: {exc}"},
                )
            except Exception:
                pass

    def start(self, source_type: str, operation: str = "sync") -> asyncio.Task:
        if self._shutting_down:
            raise RuntimeError("Vault connector scheduler is shutting down")
        key = str(source_type or "").strip().lower()
        resolved_operation = str(operation or "").strip().lower()
        if resolved_operation not in self._OPERATIONS:
            raise ValueError(f"Unsupported Vault connector operation: {operation}")
        self.connector(key)
        if key == GOOGLE_DRIVE_SOURCE_TYPE and resolved_operation == "sync":
            raise RuntimeError("Google Drive is ad-hoc only and is not synchronized into Vault")
        existing = self.tasks.get(key)
        if existing is not None:
            if not existing.done():
                raise RuntimeError(
                    f"{VAULT_SOURCE_LABELS.get(key, key)} operation already in progress"
                )
            # A user can start a new manual operation before the periodic tick
            # has cleaned up the previous completed task. Retrieve its result
            # first so a failed task is never silently overwritten or reported
            # later as an unhandled asyncio exception.
            self._consume_finished_task(key, existing)
            self.tasks.pop(key, None)
        task = asyncio.create_task(self._run(key, resolved_operation))
        self.tasks[key] = task
        return task

    async def tick(self) -> None:
        if self._shutting_down:
            return
        now = self.clock()
        for key, task in list(self.tasks.items()):
            if not task.done():
                continue
            self._consume_finished_task(key, task)
            self.tasks.pop(key, None)
        for source_type in (GMAIL_SOURCE_TYPE, SLACK_SOURCE_TYPE):
            if source_type in self.tasks or now < self.next_due.get(source_type, 0.0):
                continue
            if self._enabled(source_type):
                self.start(source_type, "sync")
            else:
                self.next_due[source_type] = now + self._interval_seconds(source_type)

    def status(self, source_type: str) -> dict[str, Any]:
        return self.connector(source_type).get_status()

    async def shutdown(self) -> None:
        self._shutting_down = True
        for connector in self.connectors.values():
            connector.cancel_sync()
        tasks = list(self.tasks.values())
        for task in tasks:
            if not task.done():
                task.cancel()
        if tasks:
            # Gather completed tasks too. This retrieves any exception from a
            # task that finished between the last scheduler tick and shutdown.
            await asyncio.gather(*tasks, return_exceptions=True)
        self.tasks.clear()


class CalendarStore:
    """Atomic local persistence and operations for Events, Items, and Week Chats."""

    def __init__(self, storage: Storage):
        self.storage = storage
        self.paths = storage.paths
        self._cache = calendar_record_cache_for_root(self.paths.root_dir)

    def _ensure_layout_unchecked(self) -> None:
        self.paths.calendar_events_dir().mkdir(parents=True, exist_ok=True)
        self.paths.calendar_items_dir().mkdir(parents=True, exist_ok=True)
        mapping_path = self.paths.calendar_week_chats_json()
        if not mapping_path.exists():
            atomic_write_json(mapping_path, default_week_chat_map())
        google_sync_path = self.paths.calendar_google_sync_json()
        if not google_sync_path.exists():
            atomic_write_json(google_sync_path, default_google_calendar_sync_state())

    def _ready(self) -> None:
        self.storage.ensure_first_run_files()
        self._ensure_layout_unchecked()

    def _load_with_backup(
        self,
        path: Path,
        validator: Callable[..., dict[str, Any]],
        *,
        location: str,
    ) -> dict[str, Any]:
        path = Path(path)
        primary_error: BaseException | None = None
        try:
            value = read_json(path)
            return copy.deepcopy(validator(value, location=location))
        except Exception as exc:
            primary_error = exc
        backup = _record_backup_path(path)
        if backup.is_file():
            try:
                recovered = copy.deepcopy(validator(read_json(backup), location=str(backup)))
                _plain_atomic_write_bytes(
                    path,
                    json.dumps(recovered, ensure_ascii=False, indent=2).encode("utf-8"),
                )
                self.storage.append_app_log(
                    "calendar.record.recovered",
                    {"path": str(path), "backup": str(backup), "error": f"{type(primary_error).__name__}: {primary_error}"},
                )
                return recovered
            except Exception as backup_error:
                raise ValueError(
                    f"Malformed Calendar data in {path}; backup recovery also failed: "
                    f"{type(backup_error).__name__}: {backup_error}"
                ) from primary_error
        raise ValueError(
            f"Malformed Calendar data in {path}: {type(primary_error).__name__}: {primary_error}"
        ) from primary_error

    def _write_with_backup(
        self,
        path: Path,
        value: dict[str, Any],
        validator: Callable[..., dict[str, Any]],
        *,
        location: str,
    ) -> dict[str, Any]:
        payload = copy.deepcopy(validator(copy.deepcopy(value), location=location))
        path = Path(path)
        with DATA_ROOTS.lock_for_path(path):
            if path.is_file():
                current = copy.deepcopy(validator(read_json(path), location=str(path)))
                _plain_atomic_write_bytes(
                    _record_backup_path(path),
                    json_dumps(current).encode("utf-8"),
                )
            _plain_atomic_write_bytes(
                path,
                json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8"),
            )
        return copy.deepcopy(payload)

    def _event_paths(self) -> list[Path]:
        return _json_record_paths(self.paths.calendar_events_dir(), "event")

    def _item_paths(self) -> list[Path]:
        return _json_record_paths(self.paths.calendar_items_dir(), "item")

    def _load_event_path(self, path: Path) -> dict[str, Any]:
        record = self._load_with_backup(path, validate_calendar_event_record, location=str(path))
        expected_id = path.stem.removeprefix("event_")
        if record["event_id"] != expected_id:
            raise ValueError(f"Calendar Event identity does not match filename: {path}")
        return record

    def _load_item_path(self, path: Path) -> dict[str, Any]:
        record = self._load_with_backup(path, validate_item_record, location=str(path))
        expected_id = path.stem.removeprefix("item_")
        if record["item_id"] != expected_id:
            raise ValueError(f"Item identity does not match filename: {path}")
        return record

    @staticmethod
    def _file_signature(path: Path) -> tuple[int, int, int]:
        try:
            stat = Path(path).stat()
            return (
                int(getattr(stat, "st_mtime_ns", 0)),
                int(getattr(stat, "st_size", 0)),
                int(getattr(stat, "st_ctime_ns", 0)),
            )
        except OSError:
            return (0, 0, 0)

    def _calendar_display_timezone(self, *, force_poll: bool = False) -> tuple[str, Any]:
        """Return the configured display timezone without parsing app.json every frame."""
        now_mono = time.monotonic()
        with self._cache.lock:
            if (
                not force_poll
                and self._cache.display_timezone_key
                and now_mono - self._cache.last_timezone_poll < CALENDAR_CACHE_EXTERNAL_POLL_SECONDS
            ):
                return self._cache.display_timezone_key, self._cache.display_timezone
        config = self.storage.load_config()
        vault = config.get("vault") if isinstance(config.get("vault"), dict) else {}
        key = str(vault.get("local_timezone") or VAULT_LOCAL_TIMEZONE_DEFAULT).strip() or VAULT_LOCAL_TIMEZONE_DEFAULT
        zone = resolve_vault_timezone(key)
        with self._cache.lock:
            self._cache.display_timezone_key = key
            self._cache.display_timezone = zone
            self._cache.last_timezone_poll = now_mono
        return key, zone

    def display_timezone(self) -> Any:
        return self._calendar_display_timezone()[1]

    def _remove_event_index_unlocked(self, event_id: str) -> None:
        for day_value in list(self._cache.event_date_ids):
            ids = self._cache.event_date_ids[day_value]
            ids.discard(event_id)
            if not ids:
                self._cache.event_date_ids.pop(day_value, None)
        self._cache.long_event_ids.discard(event_id)

    def _add_event_index_unlocked(self, event: dict[str, Any], *, display_zone: Any | None = None) -> None:
        event_id = str(event["event_id"])
        start_day, end_day = self._event_local_dates(event, display_zone=display_zone)
        span_days = (end_day - start_day).days
        if span_days < 0:
            return
        if span_days > CALENDAR_CACHE_MAX_INDEXED_EVENT_DAYS:
            self._cache.long_event_ids.add(event_id)
            return
        cursor = start_day
        while cursor <= end_day:
            self._cache.event_date_ids.setdefault(cursor.isoformat(), set()).add(event_id)
            cursor += timedelta(days=1)

    def _put_event_cache(self, event: dict[str, Any]) -> None:
        timezone_key, display_zone = self._calendar_display_timezone()
        with self._cache.lock:
            if not self._cache.events_loaded:
                return
            event_id = str(event["event_id"])
            if event_id in self._cache.events:
                self._remove_event_index_unlocked(event_id)
            self._cache.events[event_id] = copy.deepcopy(event)
            self._cache.event_file_signatures[event_id] = self._file_signature(
                self.paths.calendar_event_json(event_id)
            )
            self._add_event_index_unlocked(event, display_zone=display_zone)
            self._cache.event_index_timezone_key = timezone_key
            self._cache.event_dir_signature = _directory_signature(self.paths.calendar_events_dir())
            self._cache.last_event_poll = time.monotonic()

    def _drop_event_cache(self, event_id: str) -> None:
        with self._cache.lock:
            if not self._cache.events_loaded:
                return
            self._cache.events.pop(event_id, None)
            self._cache.event_file_signatures.pop(event_id, None)
            self._remove_event_index_unlocked(event_id)
            self._cache.event_dir_signature = _directory_signature(self.paths.calendar_events_dir())
            self._cache.last_event_poll = time.monotonic()

    def _remove_item_index_unlocked(self, item_id: str) -> None:
        self._cache.backlog_item_ids.discard(item_id)
        for day_value in list(self._cache.scheduled_item_ids):
            ids = self._cache.scheduled_item_ids[day_value]
            ids.discard(item_id)
            if not ids:
                self._cache.scheduled_item_ids.pop(day_value, None)

    def _add_item_index_unlocked(self, item: dict[str, Any]) -> None:
        item_id = str(item["item_id"])
        day_value = item.get("scheduled_date")
        if day_value is None:
            self._cache.backlog_item_ids.add(item_id)
        else:
            self._cache.scheduled_item_ids.setdefault(str(day_value), set()).add(item_id)

    def _put_item_cache(self, item: dict[str, Any]) -> None:
        with self._cache.lock:
            if not self._cache.items_loaded:
                return
            item_id = str(item["item_id"])
            if item_id in self._cache.items:
                self._remove_item_index_unlocked(item_id)
            self._cache.items[item_id] = copy.deepcopy(item)
            self._cache.item_file_signatures[item_id] = self._file_signature(
                self.paths.calendar_item_json(item_id)
            )
            self._add_item_index_unlocked(item)
            self._cache.item_dir_signature = _directory_signature(self.paths.calendar_items_dir())
            self._cache.last_item_poll = time.monotonic()

    def _drop_item_cache(self, item_id: str) -> None:
        with self._cache.lock:
            if not self._cache.items_loaded:
                return
            self._cache.items.pop(item_id, None)
            self._cache.item_file_signatures.pop(item_id, None)
            self._remove_item_index_unlocked(item_id)
            self._cache.item_dir_signature = _directory_signature(self.paths.calendar_items_dir())
            self._cache.last_item_poll = time.monotonic()

    def _ensure_event_cache(self) -> None:
        self._ready()
        timezone_key, display_zone = self._calendar_display_timezone()
        now_mono = time.monotonic()
        with self._cache.lock:
            timezone_changed = (
                self._cache.events_loaded
                and self._cache.event_index_timezone_key != timezone_key
            )
            if timezone_changed:
                self._cache.event_date_ids = {}
                self._cache.long_event_ids = set()
                for event in self._cache.events.values():
                    self._add_event_index_unlocked(event, display_zone=display_zone)
                self._cache.event_index_timezone_key = timezone_key
            if (
                self._cache.events_loaded
                and now_mono - self._cache.last_event_poll < CALENDAR_CACHE_EXTERNAL_POLL_SECONDS
            ):
                return
            expected_signature = self._cache.event_dir_signature
            loaded = self._cache.events_loaded
            self._cache.last_event_poll = now_mono
        current_signature = _directory_signature(self.paths.calendar_events_dir())
        if loaded and current_signature == expected_signature:
            return
        with DATA_ROOTS.lock_for_path(self.paths.calendar_events_dir()):
            events = {
                str(event["event_id"]): event
                for event in (self._load_event_path(path) for path in self._event_paths())
            }
            final_signature = _directory_signature(self.paths.calendar_events_dir())
        with self._cache.lock:
            self._cache.events = {key: copy.deepcopy(value) for key, value in events.items()}
            self._cache.event_file_signatures = {
                event_id: self._file_signature(self.paths.calendar_event_json(event_id))
                for event_id in self._cache.events
            }
            self._cache.event_date_ids = {}
            self._cache.long_event_ids = set()
            for event in self._cache.events.values():
                self._add_event_index_unlocked(event, display_zone=display_zone)
            self._cache.event_index_timezone_key = timezone_key
            self._cache.event_dir_signature = final_signature
            self._cache.events_loaded = True
            self._cache.last_event_poll = time.monotonic()

    def _ensure_item_cache(self) -> None:
        self._ready()
        now_mono = time.monotonic()
        with self._cache.lock:
            if (
                self._cache.items_loaded
                and now_mono - self._cache.last_item_poll < CALENDAR_CACHE_EXTERNAL_POLL_SECONDS
            ):
                return
            expected_signature = self._cache.item_dir_signature
            loaded = self._cache.items_loaded
            self._cache.last_item_poll = now_mono
        current_signature = _directory_signature(self.paths.calendar_items_dir())
        if loaded and current_signature == expected_signature:
            return
        with DATA_ROOTS.lock_for_path(self.paths.calendar_items_dir()):
            items = {
                str(item["item_id"]): item
                for item in (self._load_item_path(path) for path in self._item_paths())
            }
            final_signature = _directory_signature(self.paths.calendar_items_dir())
        with self._cache.lock:
            self._cache.items = {key: copy.deepcopy(value) for key, value in items.items()}
            self._cache.item_file_signatures = {
                item_id: self._file_signature(self.paths.calendar_item_json(item_id))
                for item_id in self._cache.items
            }
            self._cache.scheduled_item_ids = {}
            self._cache.backlog_item_ids = set()
            for item in self._cache.items.values():
                self._add_item_index_unlocked(item)
            self._cache.item_dir_signature = final_signature
            self._cache.items_loaded = True
            self._cache.last_item_poll = time.monotonic()

    def _refresh_event_record_if_changed(self, event_id: str) -> None:
        path = self.paths.calendar_event_json(event_id)
        current_signature = self._file_signature(path)
        with self._cache.lock:
            cached_signature = self._cache.event_file_signatures.get(event_id)
        if current_signature == cached_signature:
            return
        if current_signature == (0, 0, 0):
            self._drop_event_cache(event_id)
            return
        with DATA_ROOTS.lock_for_path(path):
            event = self._load_event_path(path)
        self._put_event_cache(event)

    def _refresh_item_record_if_changed(self, item_id: str) -> None:
        path = self.paths.calendar_item_json(item_id)
        current_signature = self._file_signature(path)
        with self._cache.lock:
            cached_signature = self._cache.item_file_signatures.get(item_id)
        if current_signature == cached_signature:
            return
        if current_signature == (0, 0, 0):
            self._drop_item_cache(item_id)
            return
        with DATA_ROOTS.lock_for_path(path):
            item = self._load_item_path(path)
        self._put_item_cache(item)

    def _load_week_chat_map(self) -> dict[str, Any]:
        return self._load_with_backup(
            self.paths.calendar_week_chats_json(),
            validate_week_chat_map_record,
            location=str(self.paths.calendar_week_chats_json()),
        )

    def _save_week_chat_map(self, mapping: dict[str, Any]) -> dict[str, Any]:
        payload = copy.deepcopy(mapping)
        payload["updated_at"] = now_iso()
        return self._write_with_backup(
            self.paths.calendar_week_chats_json(),
            payload,
            validate_week_chat_map_record,
            location="Week Chat mapping",
        )

    def _load_google_sync_state(self) -> dict[str, Any]:
        return self._load_with_backup(
            self.paths.calendar_google_sync_json(),
            validate_google_calendar_sync_state,
            location=str(self.paths.calendar_google_sync_json()),
        )

    def _put_google_sync_cache(self, state: dict[str, Any]) -> None:
        path = self.paths.calendar_google_sync_json()
        with self._cache.lock:
            self._cache.google_sync_state = copy.deepcopy(state)
            self._cache.google_sync_signature = self._file_signature(path)
            self._cache.google_sync_loaded = True
            self._cache.last_google_sync_poll = time.monotonic()

    def _get_google_sync_state_cached(self, *, force_poll: bool = False) -> dict[str, Any]:
        """Return Calendar metadata without blocking the render loop on every frame."""
        path = self.paths.calendar_google_sync_json()
        now = time.monotonic()
        with self._cache.lock:
            loaded = self._cache.google_sync_loaded
            last_poll = self._cache.last_google_sync_poll
            cached_signature = self._cache.google_sync_signature
            cached_state = copy.deepcopy(self._cache.google_sync_state)
        if loaded and not force_poll and now - last_poll < CALENDAR_CACHE_EXTERNAL_POLL_SECONDS:
            return cached_state
        current_signature = self._file_signature(path)
        if loaded and current_signature == cached_signature:
            with self._cache.lock:
                self._cache.last_google_sync_poll = now
            return cached_state
        state = self._load_google_sync_state()
        self._put_google_sync_cache(state)
        return copy.deepcopy(state)

    def _mirror_google_sync_state_to_vault(self, state: dict[str, Any]) -> None:
        account = state.get("connected_account") if isinstance(state.get("connected_account"), dict) else {}
        account_identifier = str(account.get("account_id") or account.get("email") or "google-calendar").strip()
        display_name = str(account.get("display_name") or account.get("email") or "Google Calendar").strip()
        connected = bool(account.get("account_id") or account.get("email"))
        vault = VaultStore(self.storage)
        source = vault.upsert_data_source(
            GOOGLE_CALENDAR_SOURCE_TYPE,
            display_name,
            account_identifier,
            enabled=True,
            connection_state=("error" if state.get("last_error") else ("connected" if connected else "not_configured")),
            credential_reference="credentials/google_calendar.cred",
            metadata={"provider": "google", "read_only": True},
        )
        source = vault.update_data_source_sync_status(
            source["id"],
            connection_state=("error" if state.get("last_error") else ("connected" if connected else "not_configured")),
            started_at=str(state.get("last_attempted_at") or ""),
            completed_at=str(state.get("last_successful_at") or ""),
            successful_at=str(state.get("last_successful_at") or ""),
            error=str(state.get("last_error") or ""),
        )
        list_token = str(state.get("calendar_list_sync_token") or "")
        list_success = str(state.get("last_successful_at") or "")
        if list_token and list_success:
            existing_list = vault.find_sync_state(source["id"], "", "google_calendar_list_sync_token")
            generation = int(existing_list.get("sync_generation") or 0) if existing_list else 0
            if existing_list is None or existing_list.get("cursor_value") != list_token:
                generation += 1
            vault.commit_sync_state(
                source["id"], "", "google_calendar_list_sync_token", list_token, generation,
                metadata={"provider": "google_calendar"},
                attempted_at=str(state.get("last_attempted_at") or list_success),
                successful_at=list_success,
            )
        for row in state.get("calendars", []):
            if not isinstance(row, dict):
                continue
            calendar_id = str(row.get("calendar_id") or "").strip()
            if not calendar_id:
                continue
            container = vault.upsert_container(
                source["id"],
                calendar_id,
                "calendar",
                str(row.get("display_name") or calendar_id),
                display_name=str(row.get("display_name") or calendar_id),
                is_archived=bool(row.get("deleted")),
                is_hidden=not bool(row.get("enabled")),
                metadata={
                    "calendar_id": calendar_id,
                    "description": str(row.get("description") or ""),
                    "primary": bool(row.get("primary")),
                    "color_id": str(row.get("color_id") or ""),
                    "background_color": str(row.get("background_color") or ""),
                    "foreground_color": str(row.get("foreground_color") or ""),
                    "display_color": normalize_google_calendar_display_color(
                        row.get("display_color"), calendar_id=calendar_id,
                    ),
                    "access_role": str(row.get("access_role") or ""),
                    "time_zone": str(row.get("time_zone") or ""),
                },
            )
            token = str(row.get("sync_token") or "")
            successful = str(row.get("last_successful_at") or "")
            if token and successful:
                existing = vault.find_sync_state(source["id"], container["id"], "google_calendar_event_sync_token")
                generation = int(existing.get("sync_generation") or 0) if existing else 0
                if existing is None or existing.get("cursor_value") != token:
                    generation += 1
                vault.commit_sync_state(
                    source["id"], container["id"], "google_calendar_event_sync_token", token, generation,
                    metadata={"last_full_sync_at": str(row.get("last_full_sync_at") or "")},
                    attempted_at=str(row.get("last_attempted_at") or successful),
                    successful_at=successful,
                )

    def _save_google_sync_state(self, state: dict[str, Any]) -> dict[str, Any]:
        payload = copy.deepcopy(state)
        payload["schema"] = GOOGLE_CALENDAR_SYNC_SCHEMA
        payload["data_version"] = DATA_FILE_VERSION
        payload["updated_at"] = now_iso()
        saved = self._write_with_backup(
            self.paths.calendar_google_sync_json(),
            payload,
            validate_google_calendar_sync_state,
            location="Google Calendar sync state",
        )
        self._put_google_sync_cache(saved)
        # Vault mirroring can touch several files. Do it only after the small
        # Calendar state file lock is released so UI readers never wait behind
        # a complete connector bookkeeping pass.
        self._mirror_google_sync_state_to_vault(saved)
        return saved

    def get_google_sync_state(self) -> dict[str, Any]:
        self._ready()
        return self._get_google_sync_state_cached()

    def save_google_sync_state(self, state: dict[str, Any]) -> dict[str, Any]:
        self._ready()
        return self._save_google_sync_state(state)

    def set_google_calendar_enabled(self, calendar_id: str, enabled: bool) -> dict[str, Any]:
        self._ready()
        target = str(calendar_id or "").strip()
        if not target:
            raise ValueError("Google Calendar ID is required")
        path = self.paths.calendar_google_sync_json()
        with DATA_ROOTS.lock_for_path(path):
            state = self._load_google_sync_state()
            found = False
            for row in state["calendars"]:
                if row["calendar_id"] != target:
                    continue
                row["enabled"] = bool(enabled)
                found = True
                break
            if not found:
                raise FileNotFoundError(f"Google Calendar metadata not found: {target}")
            payload = copy.deepcopy(state)
            payload["updated_at"] = now_iso()
            saved = self._write_with_backup(
                path, payload, validate_google_calendar_sync_state,
                location="Google Calendar sync state",
            )
        self._put_google_sync_cache(saved)
        self._mirror_google_sync_state_to_vault(saved)
        return saved

    def set_google_calendar_display_color(self, calendar_id: str, color_key: str) -> dict[str, Any]:
        self._ready()
        target = str(calendar_id or "").strip()
        if not target:
            raise ValueError("Google Calendar ID is required")
        normalized_color = str(color_key or "").strip().lower()
        if normalized_color not in GOOGLE_CALENDAR_DISPLAY_COLOR_KEYS:
            raise ValueError(
                "Google Calendar display color must be one of: "
                + ", ".join(GOOGLE_CALENDAR_DISPLAY_COLOR_KEYS)
            )
        path = self.paths.calendar_google_sync_json()
        with DATA_ROOTS.lock_for_path(path):
            state = self._load_google_sync_state()
            found = False
            for row in state["calendars"]:
                if row["calendar_id"] != target:
                    continue
                row["display_color"] = normalized_color
                found = True
                break
            if not found:
                raise FileNotFoundError(f"Google Calendar metadata not found: {target}")
            payload = copy.deepcopy(state)
            payload["updated_at"] = now_iso()
            saved = self._write_with_backup(
                path, payload, validate_google_calendar_sync_state,
                location="Google Calendar sync state",
            )
        self._put_google_sync_cache(saved)
        self._mirror_google_sync_state_to_vault(saved)
        return saved

    def clear_google_connection_state(self) -> dict[str, Any]:
        """Forget OAuth identity and sync tokens while retaining metadata and Events."""
        self._ready()
        path = self.paths.calendar_google_sync_json()
        with DATA_ROOTS.lock_for_path(path):
            state = self._load_google_sync_state()
            state["connected_account"] = default_google_calendar_account_identity()
            state["calendar_list_sync_token"] = ""
            state["last_error"] = ""
            for row in state["calendars"]:
                row["sync_token"] = ""
                row["sync_window_start"] = ""
                row["sync_window_end"] = ""
                row["last_error"] = ""
            payload = copy.deepcopy(state)
            payload["updated_at"] = now_iso()
            saved = self._write_with_backup(
                path, payload, validate_google_calendar_sync_state,
                location="Google Calendar sync state",
            )
        self._put_google_sync_cache(saved)
        self._mirror_google_sync_state_to_vault(saved)
        return saved

    def _validate_startup_metadata_unchecked(self) -> None:
        self._ensure_layout_unchecked()
        self._load_google_sync_state()
        mapping = self._load_week_chat_map()
        for week_start, chat_id in mapping["week_start_to_chat_id"].items():
            chat_path = self.paths.chat_json(chat_id)
            if not chat_path.is_file():
                raise ValueError(f"Week Chat mapping references a missing chat for {week_start}")
            chat = validate_chat_record(
                read_json(chat_path), expected_chat_id=chat_id, location=str(chat_path),
            )
            if chat.get("chat_kind") != "week" or chat.get("week_start_date") != week_start:
                raise ValueError(f"Week Chat mapping does not match chat metadata for {week_start}")


    def _event_local_dates(
        self, event: dict[str, Any], *, display_zone: Any | None = None,
    ) -> tuple[date, date]:
        if bool(event.get("all_day")):
            start_day = date.fromisoformat(str(event["start"]))
            end_exclusive = date.fromisoformat(str(event["end"]))
            return start_day, end_exclusive - timedelta(days=1)
        zone = display_zone or self.display_timezone()
        start_dt = _parse_iso_datetime(event.get("start"), field_name="Event start")
        end_dt = _parse_iso_datetime(event.get("end"), field_name="Event end")
        if start_dt.tzinfo is None:
            start_dt = start_dt.replace(tzinfo=timezone.utc)
        if end_dt.tzinfo is None:
            end_dt = end_dt.replace(tzinfo=timezone.utc)
        start_local = start_dt.astimezone(zone)
        end_inclusive = end_dt.astimezone(zone) - timedelta(microseconds=1)
        return start_local.date(), end_inclusive.date()

    def _event_sort_key(self, event: dict[str, Any]) -> tuple[str, int, str, str]:
        all_day_rank = 0 if bool(event.get("all_day")) else 1
        if bool(event.get("all_day")):
            start_key = str(event.get("start") or "")
        else:
            start_dt = _parse_iso_datetime(event.get("start"), field_name="Event start")
            if start_dt.tzinfo is None:
                start_dt = start_dt.replace(tzinfo=timezone.utc)
            start_key = start_dt.astimezone(self.display_timezone()).isoformat(timespec="seconds")
        return start_key[:10], all_day_rank, start_key, str(event.get("title") or "").casefold()

    @staticmethod
    def _event_visible_for_calendars(
        event: dict[str, Any], calendar_enabled: dict[str, bool],
    ) -> bool:
        source_type = str(event.get("source_type") or "").strip().casefold()
        if source_type not in {"google", "google_calendar"}:
            return True
        calendar_id = str(event.get("external_calendar_id") or "").strip()
        # Local fixtures and retained external records remain visible when their
        # calendar has not been discovered in the current account metadata. Once
        # a CalendarList row exists, its enable switch is authoritative.
        return calendar_enabled.get(calendar_id, True)

    def list_events(self, start_date: str, end_date: str | None = None) -> list[dict[str, Any]]:
        self._ensure_event_cache()
        start_day = date.fromisoformat(normalize_iso_date(start_date, field_name="Event range start"))
        end_day = date.fromisoformat(normalize_iso_date(end_date or start_date, field_name="Event range end"))
        if end_day < start_day:
            raise ValueError("Event range end cannot precede its start")
        sync_state = self._get_google_sync_state_cached()
        calendar_enabled = {
            str(row.get("calendar_id") or ""): bool(row.get("enabled") and not row.get("deleted"))
            for row in sync_state.get("calendars", [])
            if isinstance(row, dict) and str(row.get("calendar_id") or "")
        }
        span_days = (end_day - start_day).days
        with self._cache.lock:
            if span_days <= CALENDAR_CACHE_MAX_INDEXED_EVENT_DAYS:
                event_ids = set(self._cache.long_event_ids)
                cursor = start_day
                while cursor <= end_day:
                    event_ids.update(self._cache.event_date_ids.get(cursor.isoformat(), ()))
                    cursor += timedelta(days=1)
            else:
                event_ids = set(self._cache.events)
            rows = []
            for event_id in event_ids:
                event = self._cache.events.get(event_id)
                if event is None or not self._event_visible_for_calendars(event, calendar_enabled):
                    continue
                if event_id in self._cache.long_event_ids or span_days > CALENDAR_CACHE_MAX_INDEXED_EVENT_DAYS:
                    event_start, event_end = self._event_local_dates(event)
                    if event_start > end_day or event_end < start_day:
                        continue
                rows.append(copy.deepcopy(event))
        rows.sort(key=self._event_sort_key)
        return rows

    def list_events_for_date(self, day_value: str) -> list[dict[str, Any]]:
        return self.list_events(day_value, day_value)

    def list_all_events(self) -> list[dict[str, Any]]:
        """Return every normalized Event without re-reading JSON on every frame."""
        self._ensure_event_cache()
        with self._cache.lock:
            rows = [copy.deepcopy(event) for event in self._cache.events.values()]
        rows.sort(key=self._event_sort_key)
        return rows

    def get_event(self, event_id: str) -> dict[str, Any]:
        self._ensure_event_cache()
        resolved = str(event_id or "").strip()
        self._refresh_event_record_if_changed(resolved)
        with self._cache.lock:
            event = self._cache.events.get(resolved)
            if event is None:
                raise FileNotFoundError(f"Calendar Event not found: {resolved}")
            return copy.deepcopy(event)

    def _find_event_by_external_identity(self, identity: tuple[str, str, str, str, str]) -> dict[str, Any] | None:
        self._ensure_event_cache()
        with self._cache.lock:
            for event in self._cache.events.values():
                if calendar_event_external_identity(event) == identity:
                    return copy.deepcopy(event)
        return None

    @staticmethod
    def _event_payload_identity(payload: Any) -> tuple[str, str, str, str, str]:
        if not isinstance(payload, dict):
            raise ValueError("Calendar Event payload must be an object")
        required_identity_keys = (
            "source_type", "external_account_id", "external_calendar_id", "external_event_id",
        )
        if any(
            not isinstance(payload.get(key), str) or not str(payload.get(key) or "").strip()
            for key in required_identity_keys
        ):
            raise ValueError("Calendar Event source, account, calendar, and external event IDs are required strings")
        recurrence_instance = payload.get("recurrence_instance_id")
        if recurrence_instance is not None and not isinstance(recurrence_instance, str):
            raise ValueError("Calendar Event recurrence instance ID must be a string when provided")
        return (
            str(payload["source_type"]).strip(),
            str(payload["external_account_id"]).strip(),
            str(payload["external_calendar_id"]).strip(),
            str(payload["external_event_id"]).strip(),
            str(recurrence_instance or "").strip(),
        )

    def upsert_event(self, payload: dict[str, Any]) -> dict[str, Any]:
        self._ensure_event_cache()
        identity = self._event_payload_identity(payload)
        existing = self._find_event_by_external_identity(identity)
        record = normalize_calendar_event_payload(payload, existing=existing)
        path = self.paths.calendar_event_json(record["event_id"])
        saved = self._write_with_backup(path, record, validate_calendar_event_record, location="Calendar Event")
        self._put_event_cache(saved)
        VaultStore(self.storage).upsert_calendar_event(saved)
        self.storage.append_app_log(
            "calendar.event.upserted",
            {"event_id": saved["event_id"], "created": existing is None, "status": saved["status"]},
        )
        return saved

    def upsert_events(self, payloads: Iterable[dict[str, Any]]) -> dict[str, Any]:
        """Best-effort batch upsert using the shared external-identity cache."""
        self._ensure_event_cache()
        rows = list(payloads)
        saved_rows: list[dict[str, Any]] = []
        errors: list[dict[str, Any]] = []
        created_count = 0
        with self._cache.lock:
            existing_by_identity = {
                calendar_event_external_identity(event): copy.deepcopy(event)
                for event in self._cache.events.values()
            }
        for index, payload in enumerate(rows):
            try:
                identity = self._event_payload_identity(payload)
                existing = existing_by_identity.get(identity)
                record = normalize_calendar_event_payload(payload, existing=existing)
                path = self.paths.calendar_event_json(record["event_id"])
                saved = self._write_with_backup(
                    path, record, validate_calendar_event_record, location="Calendar Event",
                )
                saved_rows.append(saved)
                existing_by_identity[identity] = saved
                self._put_event_cache(saved)
                VaultStore(self.storage).upsert_calendar_event(saved)
                if existing is None:
                    created_count += 1
            except Exception as exc:
                external_id = str(payload.get("external_event_id") or "") if isinstance(payload, dict) else ""
                errors.append({
                    "index": index,
                    "external_event_id": external_id,
                    "error": f"{type(exc).__name__}: {exc}",
                })
        if saved_rows or errors:
            self.storage.append_app_log(
                "calendar.events.batch_upserted",
                {
                    "received": len(rows),
                    "saved": len(saved_rows),
                    "created": created_count,
                    "failed": len(errors),
                },
            )
        return {"saved": saved_rows, "errors": errors, "created": created_count}

    def mark_event_cancelled(self, event_id: str) -> dict[str, Any]:
        self._ready()
        event = self.get_event(event_id)
        event["status"] = "cancelled"
        event["last_synced_at"] = now_iso()
        saved = self._write_with_backup(
            self.paths.calendar_event_json(event_id), event, validate_calendar_event_record,
            location="Calendar Event",
        )
        self._put_event_cache(saved)
        VaultStore(self.storage).upsert_calendar_event(saved)
        self.storage.append_app_log("calendar.event.cancelled", {"event_id": event_id})
        return saved

    @staticmethod
    def _item_sort_key(item: dict[str, Any]) -> tuple[str, str, str, str]:
        return (
            str(item.get("scheduled_date") or ""),
            str(item.get("scheduled_start_time") or ""),
            str(item.get("priority") or "P3"),
            str(item.get("title") or "").casefold(),
        )

    def get_item(self, item_id: str) -> dict[str, Any]:
        self._ensure_item_cache()
        resolved = str(item_id or "").strip()
        self._refresh_item_record_if_changed(resolved)
        with self._cache.lock:
            item = self._cache.items.get(resolved)
            if item is None:
                raise FileNotFoundError(f"Item not found: {resolved}")
            return copy.deepcopy(item)

    def list_scheduled_items(self, day_value: str) -> list[dict[str, Any]]:
        self._ensure_item_cache()
        day_value = normalize_iso_date(day_value, field_name="Item date")
        with self._cache.lock:
            rows = [
                copy.deepcopy(self._cache.items[item_id])
                for item_id in self._cache.scheduled_item_ids.get(day_value, ())
                if item_id in self._cache.items
            ]
        rows.sort(key=self._item_sort_key)
        return rows

    def list_backlog_items(self) -> list[dict[str, Any]]:
        self._ensure_item_cache()
        with self._cache.lock:
            rows = [
                copy.deepcopy(self._cache.items[item_id])
                for item_id in self._cache.backlog_item_ids
                if item_id in self._cache.items
            ]
        priority_order = {"P1": 0, "P2": 1, "P3": 2}
        rows.sort(key=lambda item: (
            priority_order.get(str(item.get("priority")), 3),
            str(item.get("created_at") or ""),
            str(item.get("title") or "").casefold(),
        ))
        return rows

    def list_items(self) -> list[dict[str, Any]]:
        """Return every local Item from the shared in-memory snapshot."""
        self._ensure_item_cache()
        with self._cache.lock:
            rows = [copy.deepcopy(item) for item in self._cache.items.values()]
        priority_order = {"P1": 0, "P2": 1, "P3": 2}
        rows.sort(key=lambda item: (
            0 if item.get("scheduled_date") is None else 1,
            str(item.get("scheduled_date") or ""),
            str(item.get("scheduled_start_time") or ""),
            priority_order.get(str(item.get("priority")), 3),
            str(item.get("title") or "").casefold(),
        ))
        return rows

    def list_items_linked_to_event(self, event_id: str) -> list[dict[str, Any]]:
        self.get_event(event_id)
        return [item for item in self.list_items() if item.get("linked_event_id") == event_id]

    def _assert_event_exists(self, event_id: str | None) -> None:
        if event_id is not None:
            self.get_event(event_id)

    def _assert_agents_exist(self, agent_ids: Iterable[str]) -> None:
        agent_store = AgentStore(self.storage)
        for agent_id in agent_ids:
            agent_store.load_agent(agent_id)

    def create_item(
        self,
        title: str,
        description: str = "",
        status: str = "Action",
        priority: str = "P2",
        *,
        scheduled_date: str | None = None,
        scheduled_start_time: str | None = None,
        duration_minutes: int | None = None,
        linked_event_id: str | None = None,
        context_links: Any = None,
        attachments: Any = None,
        linked_agent_ids: Any = None,
    ) -> dict[str, Any]:
        self._ensure_item_cache()
        record = new_item_record(
            title, description, status, priority,
            scheduled_date=scheduled_date,
            scheduled_start_time=scheduled_start_time,
            duration_minutes=duration_minutes,
            linked_event_id=linked_event_id,
            context_links=context_links,
            attachments=attachments,
            linked_agent_ids=linked_agent_ids,
        )
        self._assert_event_exists(record.get("linked_event_id"))
        self._assert_agents_exist(record.get("linked_agent_ids") or [])
        with DATA_ROOTS.lock_for_path(self.paths.calendar_dir()):
            saved = self._write_with_backup(
                self.paths.calendar_item_json(record["item_id"]), record,
                validate_item_record, location="Item",
            )
            self._put_item_cache(saved)
        if saved.get("scheduled_date"):
            self.get_or_create_week_chat(str(saved["scheduled_date"]))
        self.storage.append_app_log(
            "item.created",
            {"item_id": saved["item_id"], "status": saved["status"], "priority": saved["priority"]},
        )
        return saved

    def update_item(self, item_id: str, changes: dict[str, Any]) -> dict[str, Any]:
        self._ensure_item_cache()
        if not isinstance(changes, dict):
            raise ValueError("Item changes must be an object")
        allowed = {
            "title", "description", "status", "priority", "scheduled_date",
            "scheduled_start_time", "duration_minutes", "linked_event_id",
            "context_links", "attachments", "linked_agent_ids",
        }
        unexpected = sorted(set(changes).difference(allowed))
        if unexpected:
            raise ValueError("Unsupported Item fields: " + ", ".join(unexpected))
        with DATA_ROOTS.lock_for_path(self.paths.calendar_dir()):
            item = self.get_item(item_id)
            if "title" in changes:
                title = str(changes.get("title") or "").strip()
                if not title:
                    raise ValueError("Item title is required")
                item["title"] = title
            if "description" in changes:
                item["description"] = str(changes.get("description") or "")
            if "status" in changes:
                status = str(changes.get("status") or "").strip()
                if status not in ITEM_STATUSES:
                    raise ValueError("Item status must be Info, Action, Agent WIP, Review, or Done")
                item["status"] = status
            if "priority" in changes:
                priority = str(changes.get("priority") or "").strip().upper()
                if priority not in ITEM_PRIORITIES:
                    raise ValueError("Item priority must be P1, P2, or P3")
                item["priority"] = priority
            for key in ("scheduled_date", "scheduled_start_time", "duration_minutes"):
                if key in changes:
                    item[key] = changes[key]
            if item.get("scheduled_date") is not None:
                item["scheduled_date"] = normalize_iso_date(item.get("scheduled_date"), field_name="Item scheduled date")
            if item.get("scheduled_start_time") is not None:
                item["scheduled_start_time"] = normalize_iso_time(item.get("scheduled_start_time"), field_name="Item scheduled start time")
            if item.get("duration_minutes") is not None:
                if isinstance(item.get("duration_minutes"), bool) or not isinstance(item.get("duration_minutes"), int):
                    raise ValueError("Item duration must be an integer")
            if "linked_event_id" in changes:
                raw_event = changes.get("linked_event_id")
                item["linked_event_id"] = None if raw_event in (None, "") else str(raw_event)
            if "context_links" in changes:
                item["context_links"] = _normalize_context_links(changes.get("context_links"))
            if "attachments" in changes:
                item["attachments"] = _normalize_unique_strings(changes.get("attachments"))
            if "linked_agent_ids" in changes:
                item["linked_agent_ids"] = _normalize_unique_strings(changes.get("linked_agent_ids"), require_uuid=True)
            self._assert_event_exists(item.get("linked_event_id"))
            self._assert_agents_exist(item.get("linked_agent_ids") or [])
            item["completed_at"] = (
                item.get("completed_at") or now_iso()
                if item.get("status") == "Done" else None
            )
            item["updated_at"] = now_iso()
            saved = self._write_with_backup(
                self.paths.calendar_item_json(item_id), item, validate_item_record, location="Item",
            )
            self._put_item_cache(saved)
        if saved.get("scheduled_date"):
            self.get_or_create_week_chat(str(saved["scheduled_date"]))
        self.storage.append_app_log("item.updated", {"item_id": item_id, "fields": sorted(changes)})
        return saved

    def delete_item(self, item_id: str) -> None:
        self._ensure_item_cache()
        path = self.paths.calendar_item_json(item_id)
        with DATA_ROOTS.lock_for_path(path):
            if not path.is_file():
                raise FileNotFoundError(f"Item not found: {item_id}")
            path.unlink()
            _record_backup_path(path).unlink(missing_ok=True)
            self._drop_item_cache(str(item_id))
        self.storage.append_app_log("item.deleted", {"item_id": item_id})

    def schedule_item(
        self,
        item_id: str,
        scheduled_date: str,
        scheduled_start_time: str,
        duration_minutes: int | None = None,
    ) -> dict[str, Any]:
        if duration_minutes is not None and (isinstance(duration_minutes, bool) or not isinstance(duration_minutes, int)):
            raise ValueError("Item duration must be an integer number of minutes")
        resolved_duration = DEFAULT_ITEM_DURATION_MINUTES if duration_minutes is None else duration_minutes
        return self.update_item(item_id, {
            "scheduled_date": normalize_iso_date(scheduled_date, field_name="Item scheduled date"),
            "scheduled_start_time": normalize_iso_time(scheduled_start_time, field_name="Item scheduled start time"),
            "duration_minutes": resolved_duration,
        })

    def reschedule_item(
        self,
        item_id: str,
        scheduled_date: str,
        scheduled_start_time: str,
        duration_minutes: int | None = None,
    ) -> dict[str, Any]:
        return self.schedule_item(item_id, scheduled_date, scheduled_start_time, duration_minutes)

    def move_item_to_backlog(self, item_id: str) -> dict[str, Any]:
        return self.update_item(item_id, {
            "scheduled_date": None,
            "scheduled_start_time": None,
            "duration_minutes": None,
        })

    def link_event(self, item_id: str, event_id: str) -> dict[str, Any]:
        self.get_event(event_id)
        return self.update_item(item_id, {"linked_event_id": event_id})

    def unlink_event(self, item_id: str) -> dict[str, Any]:
        return self.update_item(item_id, {"linked_event_id": None})

    def add_context_link(self, item_id: str, link: dict[str, Any]) -> dict[str, Any]:
        item = self.get_item(item_id)
        normalized = normalize_context_link(link)
        links = copy.deepcopy(item["context_links"])
        key = (normalized["type"].casefold(), normalized["url_or_path"])
        if not any((row["type"].casefold(), row["url_or_path"]) == key for row in links):
            links.append(normalized)
        return self.update_item(item_id, {"context_links": links})

    def remove_context_link(self, item_id: str, url_or_path: str) -> dict[str, Any]:
        target = str(url_or_path or "").strip()
        if not target:
            raise ValueError("Context Link URL or local path is required")
        item = self.get_item(item_id)
        links = [row for row in item["context_links"] if row.get("url_or_path") != target]
        if len(links) == len(item["context_links"]):
            raise FileNotFoundError(f"Context Link not found on Item: {target}")
        return self.update_item(item_id, {"context_links": links})

    def add_attachment(self, item_id: str, path: str) -> dict[str, Any]:
        target = str(path or "").strip()
        if not target:
            raise ValueError("Attachment path is required")
        item = self.get_item(item_id)
        attachments = list(item["attachments"])
        if target not in attachments:
            attachments.append(target)
        return self.update_item(item_id, {"attachments": attachments})

    def remove_attachment(self, item_id: str, path: str) -> dict[str, Any]:
        target = str(path or "").strip()
        item = self.get_item(item_id)
        attachments = [row for row in item["attachments"] if row != target]
        if len(attachments) == len(item["attachments"]):
            raise FileNotFoundError(f"Attachment not found on Item: {target}")
        return self.update_item(item_id, {"attachments": attachments})

    def set_status(self, item_id: str, status: str) -> dict[str, Any]:
        return self.update_item(item_id, {"status": status})

    def set_priority(self, item_id: str, priority: str) -> dict[str, Any]:
        return self.update_item(item_id, {"priority": priority})

    def link_agent(self, item_id: str, agent_id: str) -> dict[str, Any]:
        AgentStore(self.storage).load_agent(agent_id)
        item = self.get_item(item_id)
        agent_ids = list(item["linked_agent_ids"])
        if agent_id not in agent_ids:
            agent_ids.append(agent_id)
        return self.update_item(item_id, {"linked_agent_ids": agent_ids})

    def unlink_agent(self, item_id: str, agent_id: str) -> dict[str, Any]:
        item = self.get_item(item_id)
        agent_ids = [row for row in item["linked_agent_ids"] if row != agent_id]
        if len(agent_ids) == len(item["linked_agent_ids"]):
            raise FileNotFoundError(f"Agent is not linked to Item: {agent_id}")
        return self.update_item(item_id, {"linked_agent_ids": agent_ids})

    def _normalized_week_start(self, day_value: str) -> str:
        return calendar_week_start(
            normalize_iso_date(day_value, field_name="Week Chat date")
        ).isoformat()

    def _find_existing_week_chat(self, day_value: str) -> dict[str, Any] | None:
        week_start = self._normalized_week_start(day_value)
        for chat in ChatStore(self.storage).list_chats(APP_SCOPE_ID):
            if chat.get("chat_kind") == "week" and chat.get("week_start_date") == week_start:
                return chat
        return None

    def has_week_chat(self, day_value: str) -> bool:
        return self.get_week_chat(day_value) is not None

    def get_week_chat(self, day_value: str) -> dict[str, Any] | None:
        self._ready()
        week_start = self._normalized_week_start(day_value)
        with DATA_ROOTS.lock_for_path(self.paths.calendar_dir()):
            mapping = self._load_week_chat_map()
            chat_id = str(mapping["week_start_to_chat_id"].get(week_start) or "")
            if not chat_id:
                existing = self._find_existing_week_chat(week_start)
                if existing is None:
                    return None
                mapping["week_start_to_chat_id"][week_start] = existing["chat_id"]
                self._save_week_chat_map(mapping)
                return existing
            try:
                chat = ChatStore(self.storage).load_chat(chat_id)
            except FileNotFoundError:
                mapping["week_start_to_chat_id"].pop(week_start, None)
                self._save_week_chat_map(mapping)
                return None
            if chat.get("chat_kind") != "week" or chat.get("week_start_date") != week_start:
                raise ValueError(f"Week Chat mapping is inconsistent for {week_start}")
            return chat

    def get_or_create_week_chat(self, day_value: str) -> dict[str, Any]:
        self._ready()
        week_start = self._normalized_week_start(day_value)
        with DATA_ROOTS.lock_for_path(self.paths.calendar_dir()):
            existing = self.get_week_chat(week_start)
            if existing is not None:
                return existing
            chat = ChatStore(self.storage).create_chat(
                calendar_week_chat_title(week_start), chat_kind="week", week_start_date=week_start,
            )
            mapping = self._load_week_chat_map()
            mapping["week_start_to_chat_id"][week_start] = chat["chat_id"]
            self._save_week_chat_map(mapping)
        self.storage.append_app_log("week_chat.created", {"week_start": week_start, "chat_id": chat["chat_id"]})
        return chat

    def remove_week_chat_mapping_for_chat(self, chat_id: str) -> None:
        self._ready()
        with DATA_ROOTS.lock_for_path(self.paths.calendar_dir()):
            mapping = self._load_week_chat_map()
            dates = [value for value, mapped in mapping["week_start_to_chat_id"].items() if mapped == chat_id]
            if not dates:
                return
            for value in dates:
                mapping["week_start_to_chat_id"].pop(value, None)
            self._save_week_chat_map(mapping)

    def open_week_chat(self, day_value: str) -> dict[str, Any]:
        chat = self.get_or_create_week_chat(day_value)
        state = self.storage.load_app_state()
        state["active_chat_id"] = chat["chat_id"]
        state["active_panel"] = "chat"
        self.storage.write_app_state(state)
        return chat

    def inspect_day(self, day_value: str) -> dict[str, Any]:
        day_value = normalize_iso_date(day_value, field_name="Calendar date")
        week_start = self._normalized_week_start(day_value)
        chat = self.get_week_chat(week_start)
        return {
            "schema": "calendar_day.v303",
            "date": day_value,
            "week_start": week_start,
            "week_end": (date.fromisoformat(week_start) + timedelta(days=6)).isoformat(),
            "events": self.list_events_for_date(day_value),
            "items": self.list_scheduled_items(day_value),
            "week_chat": None if chat is None else {
                "chat_id": chat["chat_id"], "name": chat["name"],
                "chat_kind": chat["chat_kind"], "week_start_date": chat["week_start_date"],
            },
        }

    def compact_week_context(self, day_value: str) -> str:
        week_start = self._normalized_week_start(day_value)
        days = calendar_week_dates(week_start)
        lines = [
            "WEEK CHAT CONTEXT", "",
            f"Week: {days[0]} through {days[-1]}",
            "Use Calendar and Item tools for full records and all mutations. Do not infer missing source details.",
        ]
        total_events = total_items = 0
        for current_day in days:
            events = self.list_events_for_date(current_day)
            items = self.list_scheduled_items(current_day)
            total_events += len(events)
            total_items += len(items)
            lines.extend(["", f"{current_day}:"])
            if not events and not items:
                lines.append("* No Events or scheduled Items")
                continue
            for event in events[:40]:
                time_label = "all day" if event["all_day"] else str(event["start"])
                cancelled = " [cancelled]" if event["status"] == "cancelled" else ""
                lines.append(f"* Event {time_label} — {event['title'] or '[untitled Event]'}{cancelled} (event_id={event['event_id']})")
            for item in items[:60]:
                lines.append(
                    f"* Item {item['scheduled_start_time']} — {item['title']} "
                    f"[{item['status']}, {item['priority']}] (item_id={item['item_id']})"
                )
        lines.insert(4, f"Totals: {total_events} Events; {total_items} scheduled Items")
        return "\n".join(lines)

    def compact_selected_context(self, selected_kind: Any, selected_id: Any) -> str:
        """Return compact model context for the Calendar object's current selection.

        The selected-object block deliberately omits descriptions, source excerpts,
        URLs, and file contents. Week Chat can retrieve those through existing tools.
        """
        kind = str(selected_kind or "").strip().lower()
        object_id = str(selected_id or "").strip()
        if not kind or not object_id:
            return ""
        lines = ["CURRENTLY SELECTED CALENDAR OBJECT", ""]
        if kind == "item":
            item = self.get_item(object_id)
            if item.get("scheduled_date") is None:
                schedule = "Backlog"
            else:
                schedule = f"{item['scheduled_date']} {item['scheduled_start_time']}"
                if item.get("duration_minutes") is not None:
                    schedule += f" for {item['duration_minutes']} minutes"
            context_labels = [
                f"{str(link.get('type') or 'source')}: {str(link.get('label') or 'Link')}"
                for link in item.get("context_links") or []
                if isinstance(link, dict)
            ]
            attachment_names = [
                Path(str(value)).name or str(value)
                for value in item.get("attachments") or []
                if str(value or "").strip()
            ]
            lines.extend([
                "Selected kind: Item",
                f"Item ID: {item['item_id']}",
                f"Title: {item['title']}",
                f"Status: {item['status']}",
                f"Priority: {item['priority']}",
                f"Schedule: {schedule}",
                f"Linked Event ID: {item.get('linked_event_id') or 'None'}",
                "Context Links: " + (", ".join(context_labels[:12]) if context_labels else "None"),
                "Attachments: " + (", ".join(attachment_names[:12]) if attachment_names else "None"),
                "Linked agent IDs: " + (", ".join(item.get("linked_agent_ids") or []) or "None"),
            ])
        elif kind == "event":
            event = self.get_event(object_id)
            if event.get("all_day"):
                schedule = f"{event['start']} through {event['end']} (all day; end is exclusive)"
            else:
                schedule = f"{event['start']} through {event['end']}"
            linked_items = self.list_items_linked_to_event(event["event_id"])
            linked_labels = [f"{item['title']} ({item['item_id']})" for item in linked_items[:20]]
            lines.extend([
                "Selected kind: Event",
                f"Event ID: {event['event_id']}",
                f"Title: {event.get('title') or '[untitled Event]'}",
                f"When: {schedule}",
                f"Calendar: {event.get('calendar_name') or 'Unknown'}",
                f"Source status: {event.get('status') or 'unknown'}",
                "Linked Items: " + (", ".join(linked_labels) if linked_labels else "None"),
                "External Event fields are read-only in Velox.",
            ])
        else:
            return ""
        lines.extend([
            "",
            "Use Calendar and Item tools to retrieve full details or perform allowed Item changes.",
        ])
        return "\n".join(lines)

class GoogleCalendarDependencyError(RuntimeError):
    pass


class GoogleCalendarAuthorizationError(RuntimeError):
    pass


@dataclass(frozen=True)
class GoogleCalendarDependencies:
    request_type: Any
    credentials_type: Any
    installed_app_flow_type: Any
    build: Callable[..., Any]
    http_error_type: Any
    http_type: Any
    authorized_http_type: Any


def load_google_calendar_dependencies() -> GoogleCalendarDependencies:
    """Import the optional supported Google client stack only when it is used."""
    try:
        import httplib2
        from google.auth.transport.requests import Request
        from google.oauth2.credentials import Credentials
        from google_auth_httplib2 import AuthorizedHttp
        from google_auth_oauthlib.flow import InstalledAppFlow
        from googleapiclient.discovery import build
        from googleapiclient.errors import HttpError
    except Exception as exc:
        raise GoogleCalendarDependencyError(
            "Google Calendar support needs the optional Google Python libraries. Run: "
            + GOOGLE_CALENDAR_INSTALL_COMMAND
        ) from exc
    return GoogleCalendarDependencies(
        request_type=Request,
        credentials_type=Credentials,
        installed_app_flow_type=InstalledAppFlow,
        build=build,
        http_error_type=HttpError,
        http_type=httplib2.Http,
        authorized_http_type=AuthorizedHttp,
    )


def install_google_calendar_dependencies() -> None:
    """Install the optional Google client stack into the active Python environment."""
    command = [sys.executable, "-m", "pip", "install", "--upgrade", *GOOGLE_CALENDAR_PIP_PACKAGES]
    try:
        completed = subprocess.run(
            command,
            capture_output=True,
            text=False,
            timeout=600,
            check=False,
        )
    except Exception as exc:
        raise GoogleCalendarDependencyError(
            "Could not install Google Calendar support automatically. Run: "
            + GOOGLE_CALENDAR_INSTALL_COMMAND
        ) from exc
    if completed.returncode != 0:
        details = (
            decode_captured_subprocess_output(completed.stderr)
            or decode_captured_subprocess_output(completed.stdout)
            or "pip returned a nonzero exit code"
        ).strip()
        if len(details) > 1800:
            details = details[-1800:]
        raise GoogleCalendarDependencyError(
            "Could not install Google Calendar support automatically. "
            f"Run `{GOOGLE_CALENDAR_INSTALL_COMMAND}` manually. Details: {details}"
        )


def google_oauth_client_config(client_id: str, client_secret: str) -> dict[str, Any]:
    """Build the installed-app OAuth configuration used by the browser flow."""
    resolved_id = str(client_id or "").strip()
    resolved_secret = str(client_secret or "").strip()
    if not resolved_id or not resolved_secret:
        raise GoogleCalendarAuthorizationError(
            "Google OAuth app setup is incomplete. Paste the Desktop app Client ID and "
            "Client secret in Settings > Accounts > Google Calendar, then click Connect again."
        )
    if any(ch.isspace() for ch in resolved_id) or any(ch.isspace() for ch in resolved_secret):
        raise GoogleCalendarAuthorizationError(
            "Google OAuth Client ID and Client secret cannot contain whitespace."
        )
    return {
        "installed": {
            "client_id": resolved_id,
            "project_id": "velox-local",
            "auth_uri": GOOGLE_OAUTH_AUTH_URI,
            "token_uri": GOOGLE_OAUTH_TOKEN_URI,
            "auth_provider_x509_cert_url": GOOGLE_OAUTH_CERTS_URI,
            "client_secret": resolved_secret,
            "redirect_uris": list(GOOGLE_OAUTH_REDIRECT_URIS),
        }
    }


def google_http_status(exc: BaseException) -> int:
    for candidate in (
        getattr(getattr(exc, "resp", None), "status", None),
        getattr(exc, "status_code", None),
        getattr(exc, "status", None),
    ):
        try:
            if candidate is not None:
                return int(candidate)
        except Exception:
            continue
    return 0


def google_calendar_sync_window(config: dict[str, Any] | None, *, today: date | None = None) -> tuple[str, str, int]:
    """Return inclusive-start/exclusive-end UTC bounds centered on today."""
    vault = (config or {}).get("vault") if isinstance(config, dict) else {}
    calendar_cfg = vault.get("google_calendar") if isinstance(vault, dict) else {}
    try:
        days = int((calendar_cfg or {}).get("sync_window_days", GOOGLE_CALENDAR_SYNC_WINDOW_DAYS_DEFAULT))
    except Exception:
        days = GOOGLE_CALENDAR_SYNC_WINDOW_DAYS_DEFAULT
    days = int(clamp(days, GOOGLE_CALENDAR_SYNC_WINDOW_DAYS_MIN, GOOGLE_CALENDAR_SYNC_WINDOW_DAYS_MAX))
    current = today or date.today()
    before = days // 2
    after = days - before
    start_day = current - timedelta(days=before)
    end_exclusive = current + timedelta(days=after)
    return (
        start_day.isoformat() + "T00:00:00Z",
        end_exclusive.isoformat() + "T00:00:00Z",
        days,
    )


class GoogleCalendarIntegration:
    """One-account, read-only Google Calendar OAuth and synchronization service."""

    def __init__(
        self,
        storage: Storage,
        calendar: CalendarStore,
        *,
        dependencies_loader: Callable[[], GoogleCalendarDependencies] = load_google_calendar_dependencies,
        dependency_installer: Callable[[], None] = install_google_calendar_dependencies,
        service_factory: Callable[[Any, GoogleCalendarDependencies], Any] | None = None,
    ) -> None:
        self.storage = storage
        self.calendar = calendar
        self.paths = storage.paths
        self.credentials = CredentialStore(self.paths)
        self.dependencies_loader = dependencies_loader
        self.dependency_installer = dependency_installer
        self.service_factory = service_factory
        self._operation_lock = threading.Lock()
        self._shutdown_requested = threading.Event()
        self._dependency_status_cache: dict[str, Any] | None = None
        self._dependency_status_checked_at = 0.0

    def request_shutdown(self) -> None:
        self._shutdown_requested.set()

    def dependency_status(self, *, refresh: bool = False) -> dict[str, Any]:
        """Return cached dependency state without importing Google libraries on the UI thread."""
        cached = self._dependency_status_cache
        if cached is not None and not refresh:
            return copy.deepcopy(cached)
        if not refresh:
            return {
                "available": None,
                "message": "Google Calendar libraries are checked in the background when Connect or Sync starts.",
            }
        try:
            self.dependencies_loader()
            status = {"available": True, "message": "Google Calendar support is ready."}
        except Exception:
            status = {
                "available": False,
                "message": "Google Calendar support will install automatically when Connect is clicked.",
            }
        self._dependency_status_cache = status
        self._dependency_status_checked_at = time.monotonic()
        return copy.deepcopy(status)

    def _configured_oauth_client(self) -> tuple[str, str, str]:
        """Return client ID, client secret, and their non-sensitive source label."""
        try:
            google_cfg = self.credentials.load_google_calendar()
        except Exception:
            google_cfg = {"client_id": "", "client_secret": "", "token": None}
        configured_id = str(google_cfg.get("client_id") or "").strip()
        configured_secret = str(google_cfg.get("client_secret") or "").strip()
        if configured_id or configured_secret:
            return configured_id, configured_secret, "credentials"
        environment_id = str(os.environ.get(GOOGLE_OAUTH_CLIENT_ID_ENV) or "").strip()
        environment_secret = str(os.environ.get(GOOGLE_OAUTH_CLIENT_SECRET_ENV) or "").strip()
        if environment_id or environment_secret:
            return environment_id, environment_secret, "environment"
        return "", "", "missing"

    def _oauth_client_config(self) -> dict[str, Any]:
        client_id, client_secret, _source = self._configured_oauth_client()
        return google_oauth_client_config(client_id, client_secret)

    def _dependencies_for_connect(self) -> GoogleCalendarDependencies:
        """Load Google libraries, installing them once when they are absent."""
        try:
            return self.dependencies_loader()
        except GoogleCalendarDependencyError:
            self.storage.append_app_log("google_calendar.dependencies_install_started", {})
            self.dependency_installer()
            self._dependency_status_cache = None
            self._dependency_status_checked_at = 0.0
            try:
                dependencies = self.dependencies_loader()
            except Exception as exc:
                raise GoogleCalendarDependencyError(
                    "Google Calendar support was installed but could not be imported. Restart Velox or run: "
                    + GOOGLE_CALENDAR_INSTALL_COMMAND
                ) from exc
            self.storage.append_app_log("google_calendar.dependencies_install_completed", {})
            return dependencies

    def status(self) -> dict[str, Any]:
        state = self.calendar.get_google_sync_state()
        account = state.get("connected_account") if isinstance(state.get("connected_account"), dict) else {}
        client_id, client_secret, client_source = self._configured_oauth_client()
        try:
            token_present = isinstance(self.credentials.load_google_calendar().get("token"), dict)
        except Exception:
            token_present = False
        return {
            "connected": bool(token_present and str(account.get("account_id") or "")),
            "token_present": token_present,
            "oauth_client_configured": bool(client_id and client_secret),
            "oauth_client_source": client_source,
            "dependencies": self.dependency_status(),
            "account": copy.deepcopy(account),
            "calendars": copy.deepcopy(state.get("calendars") or []),
            "last_attempted_at": str(state.get("last_attempted_at") or ""),
            "last_successful_at": str(state.get("last_successful_at") or ""),
            "last_error": str(state.get("last_error") or ""),
            "operation_in_progress": self._operation_lock.locked(),
        }

    def _save_credentials(self, credentials: Any) -> None:
        text = str(credentials.to_json())
        try:
            parsed = json.loads(text)
        except Exception as exc:
            raise GoogleCalendarAuthorizationError("Google returned malformed OAuth authorization data") from exc
        self.credentials.save_google_token(parsed)

    def _load_credentials(self, dependencies: GoogleCalendarDependencies) -> Any:
        try:
            token_info = self.credentials.load_google_calendar().get("token")
        except Exception as exc:
            raise GoogleCalendarAuthorizationError(
                "The saved Google authorization could not be loaded. Reconnect Google Calendar."
            ) from exc
        if not isinstance(token_info, dict):
            raise GoogleCalendarAuthorizationError(
                "Google Calendar is not connected. Use Settings > Accounts > Google Calendar > Connect."
            )
        try:
            credentials = dependencies.credentials_type.from_authorized_user_info(
                copy.deepcopy(token_info), list(GOOGLE_CALENDAR_SCOPES),
            )
        except Exception as exc:
            raise GoogleCalendarAuthorizationError(
                "The saved Google authorization could not be loaded. Reconnect Google Calendar."
            ) from exc
        if not bool(getattr(credentials, "valid", False)):
            if bool(getattr(credentials, "expired", False)) and getattr(credentials, "refresh_token", None):
                try:
                    credentials.refresh(dependencies.request_type())
                    self._save_credentials(credentials)
                except Exception as exc:
                    raise GoogleCalendarAuthorizationError(
                        "Google authorization refresh failed. Reconnect Google Calendar."
                    ) from exc
            else:
                raise GoogleCalendarAuthorizationError(
                    "Google authorization is no longer valid. Reconnect Google Calendar."
                )
        return credentials

    def _build_service(self, credentials: Any, dependencies: GoogleCalendarDependencies) -> Any:
        if self.service_factory is not None:
            return self.service_factory(credentials, dependencies)
        raw_http = dependencies.http_type(timeout=GOOGLE_CALENDAR_NETWORK_TIMEOUT_SECONDS)
        authorized_http = dependencies.authorized_http_type(credentials, http=raw_http)
        return dependencies.build(
            "calendar", "v3", http=authorized_http, cache_discovery=False,
        )

    async def connect(self) -> dict[str, Any]:
        return await asyncio.to_thread(self._connect_blocking)

    def _connect_blocking(self) -> dict[str, Any]:
        if not self._operation_lock.acquire(blocking=False):
            raise RuntimeError("A Google Calendar operation is already in progress")
        try:
            self._shutdown_requested.clear()
            client_config = self._oauth_client_config()
            dependencies = self._dependencies_for_connect()
            try:
                flow = dependencies.installed_app_flow_type.from_client_config(
                    client_config, list(GOOGLE_CALENDAR_SCOPES),
                )
                credentials = flow.run_local_server(
                    port=0,
                    open_browser=True,
                    authorization_prompt_message=(
                        "Your browser is opening so Velox can connect Google Calendar read-only."
                    ),
                    success_message=(
                        "Velox is connected to Google Calendar. You can close this browser tab."
                    ),
                )
            except Exception as exc:
                raise GoogleCalendarAuthorizationError(f"Google Calendar connection failed: {exc}") from exc
            self._save_credentials(credentials)
            service = self._build_service(credentials, dependencies)
            result = self._refresh_locked(service)
            result["connected"] = True
            calendar_rows = self.calendar.get_google_sync_state().get("calendars") or []
            result["message"] = (
                "Google Calendar connected; choose Calendars to synchronize"
                if not any(row.get("enabled") and not row.get("deleted") for row in calendar_rows if isinstance(row, dict))
                else "Google Calendar connected and synchronized"
            )
            return result
        finally:
            self._operation_lock.release()

    async def refresh(self) -> dict[str, Any]:
        return await asyncio.to_thread(self._refresh_blocking)

    def _refresh_blocking(self) -> dict[str, Any]:
        if not self._operation_lock.acquire(blocking=False):
            raise RuntimeError("A Google Calendar operation is already in progress")
        try:
            self._shutdown_requested.clear()
            dependencies = self.dependencies_loader()
            credentials = self._load_credentials(dependencies)
            service = self._build_service(credentials, dependencies)
            return self._refresh_locked(service)
        finally:
            self._operation_lock.release()

    async def disconnect(self) -> dict[str, Any]:
        return await asyncio.to_thread(self._disconnect_blocking)

    def _disconnect_blocking(self) -> dict[str, Any]:
        if not self._operation_lock.acquire(blocking=False):
            raise RuntimeError("A Google Calendar operation is already in progress")
        try:
            self.credentials.clear_google_token()
            state = self.calendar.clear_google_connection_state()
            self.storage.append_app_log("google_calendar.disconnected", {})
            return {
                "connected": False,
                "message": "Google Calendar disconnected; synchronized Events were retained",
                "last_successful_sync_at": str(state.get("last_successful_at") or ""),
            }
        finally:
            self._operation_lock.release()

    def set_calendar_enabled(self, calendar_id: str, enabled: bool) -> dict[str, Any]:
        state = self.calendar.set_google_calendar_enabled(calendar_id, enabled)
        self.storage.append_app_log(
            "google_calendar.calendar_enabled",
            {"calendar_id": calendar_id, "enabled": bool(enabled)},
        )
        return state

    def set_calendar_display_color(self, calendar_id: str, color_key: str) -> dict[str, Any]:
        state = self.calendar.set_google_calendar_display_color(calendar_id, color_key)
        self.storage.append_app_log(
            "google_calendar.calendar_display_color",
            {"calendar_id": calendar_id, "display_color": str(color_key or "")},
        )
        return state

    def _list_calendar_resources(
        self,
        service: Any,
        prior_state: dict[str, Any],
        *,
        allow_token_reset: bool = True,
    ) -> tuple[list[dict[str, Any]], str]:
        """Synchronize CalendarList metadata with full/incremental pagination."""
        existing = {
            str(row.get("calendar_id") or ""): copy.deepcopy(row)
            for row in prior_state.get("calendars") or []
            if isinstance(row, dict) and str(row.get("calendar_id") or "")
        }
        prior_calendar_ids = frozenset(existing)
        token = str(prior_state.get("calendar_list_sync_token") or "")
        incremental = bool(token)
        page_token = ""
        next_sync_token = ""
        received: list[dict[str, Any]] = []
        try:
            while True:
                if self._shutdown_requested.is_set():
                    raise RuntimeError("Google Calendar synchronization stopped because Velox is closing")
                kwargs: dict[str, Any] = {
                    "maxResults": GOOGLE_CALENDAR_LIST_PAGE_SIZE,
                    "showDeleted": True,
                    "showHidden": True,
                }
                if token:
                    kwargs["syncToken"] = token
                if page_token:
                    kwargs["pageToken"] = page_token
                page = service.calendarList().list(**kwargs).execute()
                if not isinstance(page, dict):
                    raise RuntimeError("Google Calendar returned a malformed Calendar list response")
                received.extend(raw for raw in (page.get("items") or []) if isinstance(raw, dict))
                page_token = str(page.get("nextPageToken") or "")
                next_sync_token = str(page.get("nextSyncToken") or next_sync_token)
                if not page_token:
                    break
        except Exception as exc:
            if token and allow_token_reset and google_http_status(exc) == 410:
                prior_state["calendar_list_sync_token"] = ""
                self.calendar.save_google_sync_state(prior_state)
                return self._list_calendar_resources(
                    service, prior_state, allow_token_reset=False,
                )
            raise
        if not next_sync_token:
            self.storage.append_app_log(
                "google_calendar.calendar_list_sync_token_missing",
                {"received_count": len(received), "incremental": incremental},
            )
            # CalendarList normally supplies a token on its last page. Some
            # compatible or transient responses omit it while still returning
            # usable rows. Keep the data and repeat a bounded full list next time.
            next_sync_token = ""

        if incremental:
            merged = existing
            for raw in received:
                calendar_id = str(raw.get("id") or "").strip()
                if not calendar_id:
                    continue
                merged[calendar_id] = normalize_google_calendar_row(
                    raw, existing=merged.get(calendar_id),
                )
            rows = list(merged.values())
        else:
            rows = []
            seen: set[str] = set()
            for raw in received:
                calendar_id = str(raw.get("id") or "").strip()
                if not calendar_id or calendar_id in seen:
                    continue
                rows.append(normalize_google_calendar_row(raw, existing=existing.get(calendar_id)))
                seen.add(calendar_id)
            for calendar_id, prior in existing.items():
                if calendar_id in seen:
                    continue
                retained = copy.deepcopy(prior)
                retained["deleted"] = True
                retained["enabled"] = False
                retained["sync_token"] = ""
                rows.append(validate_google_calendar_row(retained))
        rows.sort(key=lambda row: (not bool(row.get("primary")), str(row.get("display_name") or "").casefold()))
        assign_google_calendar_display_colors(rows, existing_ids=prior_calendar_ids)
        return rows, next_sync_token

    @staticmethod
    def _account_identity(rows: list[dict[str, Any]]) -> dict[str, str]:
        primary = next((row for row in rows if row.get("primary") and not row.get("deleted")), None)
        selected = primary or next((row for row in rows if not row.get("deleted")), None)
        if selected is None:
            return default_google_calendar_account_identity()
        account_id = str(selected.get("calendar_id") or "")
        email = account_id if "@" in account_id else ""
        return {
            "account_id": account_id,
            "email": email,
            "display_name": str(selected.get("display_name") or email or account_id),
        }

    @staticmethod
    def _raw_google_identity(raw: dict[str, Any], account_id: str, calendar_id: str) -> tuple[str, str, str, str, str] | None:
        event_id = str(raw.get("id") or "").strip()
        if not event_id:
            return None
        original = raw.get("originalStartTime") if isinstance(raw.get("originalStartTime"), dict) else {}
        instance = str(original.get("dateTime") or original.get("date") or "").strip()
        return GOOGLE_CALENDAR_SOURCE_TYPE, account_id, calendar_id, event_id, instance

    def _sync_one_calendar(
        self,
        service: Any,
        row: dict[str, Any],
        account_id: str,
        *,
        allow_token_reset: bool = True,
    ) -> dict[str, Any]:
        attempted_at = now_iso()
        row["last_attempted_at"] = attempted_at
        window_start, window_end, window_days = google_calendar_sync_window(
            self.storage.load_config(),
            today=datetime.now(self.calendar.display_timezone()).date(),
        )
        if (
            str(row.get("sync_window_start") or "") != window_start
            or str(row.get("sync_window_end") or "") != window_end
        ):
            row["sync_token"] = ""
        token = str(row.get("sync_token") or "")
        full_sync = not token
        page_token = ""
        next_sync_token = ""
        resources: list[dict[str, Any]] = []
        try:
            while True:
                if self._shutdown_requested.is_set():
                    raise RuntimeError("Google Calendar synchronization stopped because Velox is closing")
                kwargs: dict[str, Any] = {
                    "calendarId": str(row["calendar_id"]),
                    "maxResults": GOOGLE_CALENDAR_EVENTS_PAGE_SIZE,
                    "showDeleted": True,
                    "singleEvents": True,
                }
                if token:
                    kwargs["syncToken"] = token
                else:
                    kwargs["timeMin"] = window_start
                    kwargs["timeMax"] = window_end
                if page_token:
                    kwargs["pageToken"] = page_token
                page = service.events().list(**kwargs).execute()
                if not isinstance(page, dict):
                    raise RuntimeError("Google Calendar returned a malformed Events response")
                for raw in page.get("items") or []:
                    if isinstance(raw, dict):
                        resources.append(raw)
                page_token = str(page.get("nextPageToken") or "")
                next_sync_token = str(page.get("nextSyncToken") or next_sync_token)
                if not page_token:
                    break
        except Exception as exc:
            if token and allow_token_reset and google_http_status(exc) == 410:
                row["sync_token"] = ""
                return self._sync_one_calendar(
                    service, row, account_id, allow_token_reset=False,
                )
            raise
        missing_sync_token_warning = ""
        if not next_sync_token:
            missing_sync_token_warning = (
                "Google Calendar did not return a nextSyncToken; Velox will repeat a bounded full "
                "synchronization for this calendar next time instead of failing the refresh."
            )
            self.storage.append_app_log(
                "google_calendar.sync_token_missing",
                {
                    "calendar_id": str(row.get("calendar_id") or ""),
                    "calendar_name": str(row.get("display_name") or ""),
                    "sync_window_start": window_start,
                    "sync_window_end": window_end,
                },
            )

        existing_events = [
            event for event in self.calendar.list_all_events()
            if event.get("source_type") == GOOGLE_CALENDAR_SOURCE_TYPE
            and event.get("external_account_id") == account_id
            and event.get("external_calendar_id") == row["calendar_id"]
        ]
        seen_identities: set[tuple[str, str, str, str, str]] = set()
        payloads: list[dict[str, Any]] = []
        skipped = 0
        for raw in resources:
            identity = self._raw_google_identity(raw, account_id, str(row["calendar_id"]))
            if identity is not None:
                seen_identities.add(identity)
            try:
                payloads.append(
                    google_calendar_event_payload(raw, row, account_id, synced_at=attempted_at)
                )
            except Exception as exc:
                skipped += 1
                self.storage.append_app_log(
                    "google_calendar.event_skipped",
                    {
                        "calendar_id": row["calendar_id"],
                        "external_event_id": str(raw.get("id") or ""),
                        "error": f"{type(exc).__name__}: {exc}",
                    },
                )
        batch = self.calendar.upsert_events(payloads)
        upserted = len(batch["saved"])
        for failure in batch["errors"]:
            skipped += 1
            self.storage.append_app_log(
                "google_calendar.event_skipped",
                {
                    "calendar_id": row["calendar_id"],
                    "external_event_id": str(failure.get("external_event_id") or ""),
                    "error": str(failure.get("error") or "Calendar Event validation failed"),
                },
            )
        cancelled_missing = 0
        if full_sync:
            window_start_day = date.fromisoformat(window_start[:10])
            window_end_day = date.fromisoformat(window_end[:10])
            for existing in existing_events:
                try:
                    existing_start, existing_end = self.calendar._event_local_dates(existing)
                except Exception:
                    continue
                if existing_end < window_start_day or existing_start >= window_end_day:
                    continue
                if calendar_event_external_identity(existing) in seen_identities:
                    continue
                if existing.get("status") != "cancelled":
                    self.calendar.mark_event_cancelled(str(existing["event_id"]))
                    cancelled_missing += 1

        completed_at = now_iso()
        warning_parts: list[str] = []
        if skipped:
            warning_parts.append(
                f"Skipped {skipped} Event record{'s' if skipped != 1 else ''}; details are in log.jsonl"
            )
        if missing_sync_token_warning:
            warning_parts.append(missing_sync_token_warning)
        warning = " ".join(warning_parts)
        row["sync_token"] = next_sync_token
        row["sync_window_start"] = window_start
        row["sync_window_end"] = window_end
        row["last_successful_at"] = completed_at
        row["last_error"] = warning
        if full_sync:
            row["last_full_sync_at"] = completed_at
        return {
            "calendar_id": row["calendar_id"],
            "calendar_name": row["display_name"],
            "full_sync": full_sync,
            "events_received": len(resources),
            "events_upserted": upserted,
            "events_skipped": skipped,
            "missing_events_cancelled": cancelled_missing,
            "warning": warning,
            "sync_window_start": window_start,
            "sync_window_end": window_end,
            "sync_window_days": window_days,
        }

    def _refresh_locked(self, service: Any) -> dict[str, Any]:
        attempted_at = now_iso()
        prior = self.calendar.get_google_sync_state()
        working = copy.deepcopy(prior)
        working["last_attempted_at"] = attempted_at
        working["last_error"] = ""
        self.calendar.save_google_sync_state(working)
        try:
            rows, list_token = self._list_calendar_resources(service, working)
            account = self._account_identity(rows)
            if not str(account.get("account_id") or ""):
                prior_account = prior.get("connected_account") if isinstance(prior.get("connected_account"), dict) else {}
                if str(prior_account.get("account_id") or ""):
                    account = copy.deepcopy(prior_account)
            working["connected_account"] = account
            working["calendar_list_sync_token"] = list_token
            working["calendars"] = rows
            working = self.calendar.save_google_sync_state(working)
            account_id = str(account.get("account_id") or "google-calendar")
            deleted_calendar_ids = {
                str(row.get("calendar_id") or "")
                for row in rows
                if row.get("deleted") and str(row.get("calendar_id") or "")
            }
            deleted_calendar_events_cancelled = 0
            if deleted_calendar_ids:
                for event in self.calendar.list_all_events():
                    if (
                        event.get("source_type") == GOOGLE_CALENDAR_SOURCE_TYPE
                        and event.get("external_account_id") == account_id
                        and event.get("external_calendar_id") in deleted_calendar_ids
                        and event.get("status") != "cancelled"
                    ):
                        self.calendar.mark_event_cancelled(str(event["event_id"]))
                        deleted_calendar_events_cancelled += 1
            successes: list[dict[str, Any]] = []
            failures: list[dict[str, str]] = []
            warnings: list[dict[str, str]] = []
            total_upserted = 0
            total_skipped = 0
            enabled_calendar_ids = [
                str(row["calendar_id"])
                for row in working["calendars"]
                if row.get("enabled") and not row.get("deleted")
            ]
            for calendar_id in enabled_calendar_ids:
                row = next(
                    candidate for candidate in working["calendars"]
                    if candidate["calendar_id"] == calendar_id
                )
                try:
                    summary = self._sync_one_calendar(service, row, account_id)
                    successes.append(summary)
                    total_upserted += int(summary.get("events_upserted") or 0)
                    total_skipped += int(summary.get("events_skipped") or 0)
                    warning = str(summary.get("warning") or "")
                    if warning:
                        warnings.append({"calendar_id": str(row["calendar_id"]), "warning": warning})
                except Exception as exc:
                    row["last_attempted_at"] = now_iso()
                    row["last_error"] = f"{type(exc).__name__}: {exc}"
                    failures.append({"calendar_id": str(row["calendar_id"]), "error": row["last_error"]})
                working = self.calendar.save_google_sync_state(working)
            if failures and not successes and enabled_calendar_ids:
                message = "; ".join(f"{row['calendar_id']}: {row['error']}" for row in failures[:4])
                raise RuntimeError("Every enabled Google Calendar failed to synchronize. " + message)
            completed_at = now_iso()
            working["last_successful_at"] = completed_at
            visible_issues = [
                f"{row['calendar_id']}: {row['error']}" for row in failures[:4]
            ]
            remaining_issue_slots = max(0, 4 - len(visible_issues))
            visible_issues.extend(
                f"{row['calendar_id']}: {row['warning']}"
                for row in warnings[:remaining_issue_slots]
            )
            working["last_error"] = "; ".join(visible_issues)
            working = self.calendar.save_google_sync_state(working)
            self.storage.append_app_log(
                "google_calendar.synchronized",
                {
                    "calendars_succeeded": len(successes),
                    "calendars_failed": len(failures),
                    "events_upserted": total_upserted,
                    "events_skipped": total_skipped,
                    "deleted_calendar_events_cancelled": deleted_calendar_events_cancelled,
                },
            )
            if not enabled_calendar_ids:
                message = "Google Calendar refreshed; no Calendars are enabled"
            elif failures:
                message = f"Calendar refreshed: {len(successes)} synchronized, {len(failures)} failed"
                if total_skipped:
                    message += f", {total_skipped} Event record{'s' if total_skipped != 1 else ''} skipped"
            elif total_skipped:
                message = (
                    f"Calendar refreshed: {len(successes)} Calendar{'s' if len(successes) != 1 else ''} synchronized; "
                    f"{total_skipped} Event record{'s' if total_skipped != 1 else ''} skipped"
                )
            else:
                message = f"Calendar refreshed: {len(successes)} Calendar{'s' if len(successes) != 1 else ''} synchronized"
            return {
                "message": message,
                "last_successful_sync_at": completed_at,
                "calendars_succeeded": len(successes),
                "calendars_failed": len(failures),
                "events_upserted": total_upserted,
                "events_skipped": total_skipped,
                "deleted_calendar_events_cancelled": deleted_calendar_events_cancelled,
                "failures": failures,
                "warnings": warnings,
            }
        except Exception as exc:
            try:
                failed_state = self.calendar.get_google_sync_state()
                failed_state["last_attempted_at"] = attempted_at
                failed_state["last_error"] = f"{type(exc).__name__}: {exc}"
                self.calendar.save_google_sync_state(failed_state)
            except Exception:
                pass
            self.storage.append_app_log(
                "google_calendar.sync_failed", {"error": f"{type(exc).__name__}: {exc}"},
            )
            raise


class AgentStore:
    """Durable app-wide background-agent records and append-only transcripts."""

    def __init__(self, storage: Storage):
        self.storage = storage
        self.paths = storage.paths
        self._list_cache: tuple[float, list[dict[str, Any]]] | None = None
        self._meta_cache: dict[str, tuple[int, int, dict[str, Any]]] = {}
        self._compaction_count_cache: dict[str, tuple[int, int, int]] = {}

    def _invalidate(self, agent_id: str | None = None) -> None:
        self._list_cache = None
        if agent_id:
            resolved = str(agent_id)
            self._meta_cache.pop(resolved, None)
            self._compaction_count_cache.pop(resolved, None)
        else:
            self._meta_cache.clear()
            self._compaction_count_cache.clear()

    @staticmethod
    def _is_reviewer_record(agent: dict[str, Any] | None) -> bool:
        return str((agent or {}).get("context") or "").startswith(
            "VELOX_INTERNAL_CHECKLIST_REVIEW_"
        )

    def _is_reviewer_agent_id(self, agent_id: str) -> bool:
        try:
            return self._is_reviewer_record(self.load_agent(str(agent_id or "")))
        except Exception:
            return False

    def create_agent(
        self,
        chat_id: str,
        task: str,
        *,
        title: str = "",
        endpoint_profile_id: str = "",
        context: str = "",
        timeout_minutes: int = AGENT_TIMEOUT_MINUTES_DEFAULT,
        auto_compaction_enabled: bool = True,
        context_window_tokens: int = AGENT_CONTEXT_WINDOW_TOKENS_DEFAULT,
        max_output_tokens: int = AGENT_MAX_OUTPUT_TOKENS_DEFAULT,
        agent_kind: str = AGENT_KIND_GENERAL,
        pa_date: str | None = None,
        tool_features: dict[str, bool] | None = None,
        parent_agent_id: str = "",
        parent_task_run_id: int = 0,
    ) -> dict[str, Any]:
        chat_id = str(chat_id or "").strip()
        task = str(task or "").strip()
        if not chat_id or not self.paths.chat_json(chat_id).is_file():
            raise ValueError("agents_start requires an existing source chat")
        if not task:
            raise ValueError("agents_start requires a non-empty task")
        endpoint_profile_id = str(endpoint_profile_id or "").strip() or endpoint_profile_id_from_config(self.storage.load_config_view())
        reviewer_durable = str(context or "").startswith("VELOX_INTERNAL_CHECKLIST_REVIEW_")
        if reviewer_durable:
            # Dedicated Reviewer prompts are durable acceptance artifacts. Never
            # copy recognizable credentials from the parent task into agent.json
            # or the Reviewer transcript/context. Reviewers use normal sensitive
            # credential/tool paths when credentials are actually required.
            task = redact_durable_secret_text(task)
            context = redact_durable_secret_text(context)
            title = redact_durable_secret_text(title)
        agent = default_agent(
            chat_id, task, title=title, endpoint_profile_id=endpoint_profile_id, context=context, timeout_minutes=timeout_minutes,
            auto_compaction_enabled=auto_compaction_enabled,
            context_window_tokens=context_window_tokens,
            max_output_tokens=max_output_tokens,
            agent_kind=agent_kind,
            pa_date=pa_date,
            tool_features=normalize_tool_feature_flags(
                tool_features, ChatStore(self.storage).get_chat_tool_features(chat_id),
            ),
        )
        if parent_agent_id:
            parent = self.load_agent(parent_agent_id)
            if (parent["source_chat_id"] != chat_id or parent["task_run_id"] != parent_task_run_id
                    or parent["status"] in AGENT_TERMINAL_STATUSES):
                raise PermissionError("The originating Agent run is not active or belongs to another Chat")
            agent["parent_agent_id"] = parent_agent_id
            agent["parent_task_run_id"] = parent_task_run_id
        elif parent_task_run_id:
            raise ValueError("parent_task_run_id requires parent_agent_id")
        agent_id = str(agent["agent_id"])
        task_run_id = TaskIdStore(self.storage).allocate(f"agent-run:{agent_id}")
        agent["task_run_id"] = task_run_id
        agent_dir = self.paths.agent_dir(agent_id)
        created_data = {
            "title": agent["title"],
            "agent_kind": agent["agent_kind"],
            "task_run_id": agent["task_run_id"],
            "pa_date": agent["pa_date"],
            "task": agent["task"],
            "context": agent["context"],
            "source_chat_id": chat_id,
            "parent_agent_id": agent["parent_agent_id"],
            "parent_task_run_id": agent["parent_task_run_id"],
            "endpoint_profile_id": agent["endpoint_profile_id"],
            "tool_features": copy.deepcopy(agent["tool_features"]),
            "timeout_minutes": agent["timeout_minutes"],
            "auto_compaction_enabled": agent["auto_compaction_enabled"],
            "context_window_tokens": agent["context_window_tokens"],
            "max_output_tokens": agent["max_output_tokens"],
            "prompt_capacity_tokens": max(1, int(agent["context_window_tokens"]) - int(agent["max_output_tokens"])),
        }
        created_event = make_agent_event(agent_id, "created", created_data)
        with DATA_ROOTS.lock_for_path(agent_dir):
            if not self.paths.chat_json(chat_id).is_file():
                raise FileNotFoundError(f"Source chat no longer exists: {chat_id}")
            if parent_agent_id:
                # Publication and lifecycle updates share the data-root lock.
                # A Stop/deletion during setup must not publish an orphan child.
                parent = self.load_agent(parent_agent_id)
                if (parent["source_chat_id"] != chat_id or parent["task_run_id"] != parent_task_run_id
                        or parent["status"] in AGENT_TERMINAL_STATUSES):
                    raise PermissionError("The originating Agent run ended during child setup")
            agent_dir.mkdir(parents=True, exist_ok=False)
            try:
                atomic_write_text(self.paths.agent_transcript_jsonl(agent_id), json_dumps(created_event) + "\n")
                atomic_write_json(self.paths.agent_json(agent_id), agent)
            except Exception:
                shutil.rmtree(agent_dir, ignore_errors=True)
                raise
        self._invalidate(agent_id)
        _best_effort_lifecycle_log(self.storage, "agent.created", {
            "agent_id": agent_id,
            "chat_id": chat_id,
            "title": agent["title"],
            "task_run_id": agent["task_run_id"],
        })
        return copy.deepcopy(agent)

    def _load_agent_view(self, agent_id: str) -> dict[str, Any]:
        agent_id = str(agent_id or "").strip()
        path = self.paths.agent_json(agent_id)
        try:
            st = path.stat()
            cached = self._meta_cache.get(agent_id)
            if cached and cached[0] == st.st_mtime_ns and cached[1] == st.st_size:
                return cached[2]
        except Exception:
            st = None
        if not path.is_file():
            raise FileNotFoundError(f"agent not found: {agent_id}")
        raw = read_json(path)
        if raw is None and not path.is_file():
            self._invalidate(agent_id)
            raise FileNotFoundError(f"agent not found: {agent_id}")
        obj = validate_agent_record(raw, expected_agent_id=agent_id, location=str(path))
        if st is not None:
            self._meta_cache[agent_id] = (st.st_mtime_ns, st.st_size, obj)
        return obj


    def load_agent(self, agent_id: str) -> dict[str, Any]:
        return copy.deepcopy(self._load_agent_view(agent_id))

    def load_status(self, agent_id: str) -> dict[str, Any]:
        """Small detached status projection; do not clone a Task's entire prompt."""
        record = self._load_agent_view(agent_id)
        return {key: record.get(key) for key in (
            "agent_id", "source_chat_id", "status", "completed_at", "failure_message", "pause_requested",
        )}

    def write_agent(self, agent: dict[str, Any]) -> dict[str, Any]:
        """Write a complete agent record while preserving newer tool counters."""
        obj = copy.deepcopy(agent or {})
        agent_id = str(obj.get("agent_id") or "").strip()
        path = self.paths.agent_json(agent_id)
        with DATA_ROOTS.lock_for_path(path):
            _require_durable_owner(path)
            current = validate_agent_record(
                read_json(path), expected_agent_id=agent_id, location=str(path),
            )
            for key in ("agent_id", "source_chat_id", "task_run_id", "created_at"):
                if obj.get(key) != current.get(key):
                    raise ValueError(f"Agent identity field cannot change: {key}")
            if str(current.get("status") or "") in AGENT_TERMINAL_STATUSES:
                # A stale complete-record snapshot is not a new Task run.
                return copy.deepcopy(current)
            obj["stats"] = copy.deepcopy(current["stats"])
            if self._is_reviewer_record(obj):
                obj = redact_durable_secrets(obj)
            obj["updated_at"] = now_iso()
            validate_agent_record(obj, expected_agent_id=agent_id, location=f"agent {agent_id}")
            _plain_atomic_write_bytes(
                path, json_dumps(obj).encode("utf-8"),
            )
        self._invalidate(agent_id)
        return copy.deepcopy(obj)

    def update_agent(self, agent_id: str, patch: dict[str, Any]) -> dict[str, Any]:
        """Atomically patch the latest agent record with terminal-state safety.

        A cancelled/succeeded/failed agent is immutable as a Task state.  Delayed
        timeout, pause, resume, or worker callbacks may still update bookkeeping
        fields, but they cannot reopen or replace a terminal outcome.
        """
        agent_id = str(agent_id or "").strip()
        path = self.paths.agent_json(agent_id)
        blocked_transition: tuple[str, str] | None = None
        with DATA_ROOTS.lock_for_path(path):
            _require_durable_owner(path)
            obj = validate_agent_record(
                read_json(path), expected_agent_id=agent_id, location=str(path),
            )
            status_before = str(obj.get("status") or "")
            effective_patch = copy.deepcopy(patch or {})
            if self._is_reviewer_record(obj):
                effective_patch = redact_durable_secrets(effective_patch)
            requested_status = str(effective_patch.get("status") or "").strip()
            if (
                requested_status
                and status_before in AGENT_TERMINAL_STATUSES
                and requested_status != status_before
            ):
                blocked_transition = (status_before, requested_status)
                saved = copy.deepcopy(obj)
                status_after = status_before
            else:
                for key, value in effective_patch.items():
                    if key in {"agent_id", "task_run_id", "schema", "data_version", "created_at", "source_chat_id"}:
                        continue
                    obj[key] = copy.deepcopy(value)
                status_after = str(obj.get("status") or status_before)
                if status_after not in AGENT_STATUSES:
                    raise ValueError(f"unsupported agent status: {status_after}")
                if status_after in AGENT_TERMINAL_STATUSES and not obj.get("completed_at"):
                    obj["completed_at"] = now_iso()
                if status_after == "running" and not obj.get("started_at"):
                    obj["started_at"] = now_iso()
                obj["updated_at"] = now_iso()
                validate_agent_record(obj, expected_agent_id=agent_id, location=f"agent {agent_id}")
                _plain_atomic_write_bytes(
                    path, json_dumps(obj).encode("utf-8"),
                )
                saved = copy.deepcopy(obj)
        self._invalidate(agent_id)
        if blocked_transition:
            _best_effort_lifecycle_log(self.storage, 
                "agent.stale_transition_ignored",
                {
                    "agent_id": agent_id,
                    "chat_id": saved.get("source_chat_id"),
                    "from": blocked_transition[0],
                    "to": blocked_transition[1],
                },
            )
            return saved
        if status_after != status_before:
            _best_effort_lifecycle_log(self.storage, "agent.status", {
                "agent_id": agent_id,
                "chat_id": saved.get("source_chat_id"),
                "from": status_before,
                "to": status_after,
            })
        return saved

    def append_event(self, agent_id: str, kind: str, data: dict[str, Any] | None = None) -> dict[str, Any]:
        durable_data = copy.deepcopy(data or {})
        if self._is_reviewer_agent_id(agent_id):
            durable_data = redact_durable_secrets(durable_data)
        event = make_agent_event(agent_id, kind, durable_data)
        path = self.paths.agent_transcript_jsonl(agent_id)
        with DATA_ROOTS.lock_for_path(path):
            _require_durable_owner(path)
            append_jsonl(path, event)
        if str(kind or "") == "context_compacted":
            self._compaction_count_cache.pop(str(agent_id or ""), None)
        return event

    def load_transcript(self, agent_id: str) -> list[dict[str, Any]]:
        resolved = str(agent_id or "")
        path = self.paths.agent_transcript_jsonl(resolved)
        with DATA_ROOTS.lock_for_path(path):
            return load_agent_event_records(self.paths, resolved)

    def transcript_compaction_count(self, agent_id: str) -> int:
        """Count durable compaction checkpoints with a transcript signature cache."""
        resolved = str(agent_id or "").strip()
        if not resolved:
            return 0
        path = self.paths.agent_transcript_jsonl(resolved)
        try:
            stat = path.stat()
            signature = (int(stat.st_mtime_ns), int(stat.st_size))
        except Exception:
            signature = (0, 0)
        cached = self._compaction_count_cache.get(resolved)
        if cached and cached[:2] == signature:
            return int(cached[2])
        count = sum(
            1 for event in self.load_transcript(resolved)
            if str(event.get("kind") or "") == "context_compacted"
        )
        self._compaction_count_cache[resolved] = (signature[0], signature[1], count)
        return count

    def detail_signature(self, agent_id: str) -> tuple[int, int, int, int]:
        """Return a cheap signature for the metadata plus transcript files."""
        values: list[int] = []
        for path in (self.paths.agent_json(agent_id), self.paths.agent_transcript_jsonl(agent_id)):
            try:
                stat = path.stat()
                values.extend((int(stat.st_mtime_ns), int(stat.st_size)))
            except Exception:
                values.extend((0, 0))
        return values[0], values[1], values[2], values[3]

    def list_agents(self, chat_id: str | None = None) -> list[dict[str, Any]]:
        now_t = time.monotonic()
        if self._list_cache and now_t - self._list_cache[0] < 0.25:
            rows = [copy.deepcopy(row) for row in self._list_cache[1]]
        else:
            rows: list[dict[str, Any]] = []
            base = self.paths.agents_dir()
            if base.exists():
                for child in base.iterdir():
                    path = child / "agent.json"
                    if not child.name.startswith("agent_") or not child.is_dir() or not path.is_file():
                        continue
                    try:
                        obj = read_json(path, None)
                    except Exception as exc:
                        # Agent deletion can race the list snapshot. A vanished
                        # record is expected and must not be reported as corrupt.
                        if not path.is_file():
                            continue
                        raise ValueError(f"Invalid agent JSON: {path}: {type(exc).__name__}: {exc}") from exc
                    if obj is None and not path.is_file():
                        continue
                    validate_agent_record(obj, expected_agent_id=child.name.removeprefix("agent_"), location=str(path))
                    rows.append(obj)
            rows.sort(key=lambda row: str(row.get("created_at") or ""), reverse=True)
            self._list_cache = (now_t, [copy.deepcopy(row) for row in rows])
        if chat_id is not None:
            wanted = str(chat_id or "")
            rows = [row for row in rows if str(row.get("source_chat_id") or "") == wanted]
        return [copy.deepcopy(row) for row in rows]

    def delete_agent(self, agent_id: str, *, force: bool = False) -> dict[str, Any]:
        """Validate and detach under the same lock as pause/resume and writes."""
        resolved = str(agent_id or "").strip()
        if not resolved:
            raise ValueError("agent_id is required")
        agent_dir = self.paths.agent_dir(resolved)
        with DATA_ROOTS.lock_for_path(agent_dir):
            agent = self.load_agent(resolved)
            status = str(agent.get("status") or "")
            if not force and status not in AGENT_DELETABLE_STATUSES:
                allowed = ", ".join(sorted(AGENT_DELETABLE_STATUSES))
                raise ValueError(f"Agent must be paused or finished before deletion (allowed states: {allowed}).")
            detached = _detach_owner_directory(agent_dir)
        self._invalidate(resolved)
        _purge_detached_owner(self.storage, detached)
        _best_effort_lifecycle_log(self.storage, "agent.deleted", {
            "agent_id": resolved, "chat_id": agent.get("source_chat_id"), "status": status, "force": bool(force),
        })
        return copy.deepcopy(agent)

    def status_counts(self) -> dict[str, int]:
        counts = {status: 0 for status in AGENT_STATUSES}
        for row in self.list_agents():
            status = str(row.get("status") or "")
            if status in counts:
                counts[status] += 1
        counts["completed"] = counts["succeeded"] + counts["failed"] + counts["cancelled"]
        counts["total"] = sum(counts[status] for status in AGENT_STATUSES)
        return counts


    @staticmethod
    def _agent_active_duration_seconds(row: dict[str, Any], now_dt: datetime | None = None) -> float:
        """Return active runtime, including the current active span when needed."""
        try:
            seconds = max(0.0, float(row.get("active_seconds") or 0.0))
        except Exception:
            seconds = 0.0
        active_started = str(row.get("active_started_at") or "").strip()
        if active_started and str(row.get("status") or "") in {"queued", "running"}:
            try:
                started = datetime.fromisoformat(active_started.replace("Z", "+00:00"))
                current = now_dt or datetime.now(timezone.utc)
                if started.tzinfo is None:
                    started = started.replace(tzinfo=timezone.utc)
                seconds += max(0.0, (current - started.astimezone(timezone.utc)).total_seconds())
            except Exception:
                pass
        if seconds <= 0.0:
            start_raw = str(row.get("started_at") or "").strip()
            end_raw = str(row.get("completed_at") or "").strip()
            if start_raw and end_raw:
                try:
                    start = datetime.fromisoformat(start_raw.replace("Z", "+00:00"))
                    end = datetime.fromisoformat(end_raw.replace("Z", "+00:00"))
                    if start.tzinfo is None:
                        start = start.replace(tzinfo=timezone.utc)
                    if end.tzinfo is None:
                        end = end.replace(tzinfo=timezone.utc)
                    seconds = max(0.0, (end - start).total_seconds())
                except Exception:
                    pass
        return seconds

    def statistics(self) -> dict[str, Any]:
        """Return outcome, token, duration, compaction, and tool-use aggregates."""
        rows = self.list_agents()
        counts = {status: 0 for status in AGENT_STATUSES}
        input_tokens = 0
        output_tokens = 0
        compaction_events = 0
        terminal_durations: list[float] = []
        grouped_tool_totals = {
            "all_tool_calls": 0,
            "web_searches": 0,
            "web_page_downloads": 0,
            "files_read": 0,
            "files_edited": 0,
            "scripts_run": 0,
            "image_3d_calls": 0,
            "other_tool_calls": 0,
        }
        tool_call_totals_by_type: dict[str, dict[str, int]] = {}
        tool_groups = {
            "web_searches": {"web_search"},
            "web_page_downloads": {
                "web_fetch", "web_fetch_visible_content", "web_fetch_visible_content_and_links", "web_page_links",
                "web_download_file", "web_fetch_to_pdf",
            },
            "files_read": {
                "fs_list", "fs_read", "fs_search", "doc_import",
                "doc_read", "doc_pdf_images",
            },
            "files_edited": {"fs_write", "fs_append", "fs_edit"},
            "scripts_run": {"shell_exec", "python_exec"},
            "image_3d_calls": {
                "image_analyze", "image_analyze_ui", "image_analyze_3D_scene", "desktop_screenshot", "comfy_text_to_image",
                "comfy_image_to_image", "meshy_text_to_3d", "meshy_image_to_3d",
                "meshy_ai_texturing", "meshy_rig", "meshy_animate",
            },
        }
        tool_group_by_name = {
            tool_name: group_name
            for group_name, tool_names in tool_groups.items()
            for tool_name in tool_names
        }
        for row in rows:
            status = str(row.get("status") or "")
            if status in counts:
                counts[status] += 1
            try:
                row_input_tokens = max(0, int(float(row.get("input_tokens") or 0)))
            except Exception:
                row_input_tokens = 0
            input_tokens += row_input_tokens
            try:
                output_tokens += max(0, int(float(row.get("output_tokens") or 0)))
            except Exception:
                pass
            try:
                metadata_compactions = max(0, int(float(row.get("compaction_count") or 0)))
            except Exception:
                metadata_compactions = 0
            try:
                durable_compactions = self.transcript_compaction_count(str(row.get("agent_id") or ""))
            except Exception:
                durable_compactions = 0
            compaction_events += max(metadata_compactions, durable_compactions)
            if status in AGENT_TERMINAL_STATUSES:
                terminal_durations.append(self._agent_active_duration_seconds(row))
            stats = row.get("stats") if isinstance(row.get("stats"), dict) else {}
            try:
                grouped_tool_totals["all_tool_calls"] += max(0, int(stats.get("tool_calls_total") or 0))
            except Exception:
                pass
            by_type = stats.get("tool_calls_by_type") if isinstance(stats.get("tool_calls_by_type"), dict) else {}
            for tool_name, tool_row in by_type.items():
                normalized_name = str(tool_name or "").strip()
                if not normalized_name or not isinstance(tool_row, dict):
                    continue
                try:
                    total = max(0, int(tool_row.get("total") or 0))
                except Exception:
                    total = 0
                try:
                    succeeded = max(0, int(tool_row.get("succeeded") or 0))
                except Exception:
                    succeeded = 0
                try:
                    failed = max(0, int(tool_row.get("failed") or 0))
                except Exception:
                    failed = 0
                total = max(total, succeeded + failed)
                aggregate = tool_call_totals_by_type.setdefault(
                    normalized_name, {"total": 0, "succeeded": 0, "failed": 0},
                )
                aggregate["total"] += total
                aggregate["succeeded"] += succeeded
                aggregate["failed"] += failed
                group_name = tool_group_by_name.get(normalized_name)
                if group_name:
                    grouped_tool_totals[group_name] += total
        grouped_categories = (
            "web_searches", "web_page_downloads", "files_read", "files_edited", "scripts_run", "image_3d_calls",
        )
        grouped_tool_totals["other_tool_calls"] = max(
            0,
            grouped_tool_totals["all_tool_calls"] - sum(grouped_tool_totals[key] for key in grouped_categories),
        )
        total_tasks = len(rows)
        terminal_tasks = counts["succeeded"] + counts["failed"] + counts["cancelled"]
        outcome_percentages = {
            key: ((counts[key] * 100.0 / terminal_tasks) if terminal_tasks else 0.0)
            for key in ("succeeded", "failed", "cancelled")
        }
        average_tool_usage = {
            key: (value / total_tasks if total_tasks else 0.0)
            for key, value in grouped_tool_totals.items()
        }
        tool_call_success = []
        for tool_name in sorted(tool_call_totals_by_type, key=lambda value: value.casefold()):
            aggregate = tool_call_totals_by_type[tool_name]
            total = max(0, int(aggregate.get("total") or 0))
            succeeded = max(0, int(aggregate.get("succeeded") or 0))
            failed = max(0, int(aggregate.get("failed") or 0))
            tool_call_success.append({
                "tool_type": tool_name,
                "total": total,
                "succeeded": succeeded,
                "failed": failed,
                "success_percent": (succeeded * 100.0 / total) if total else 0.0,
            })
        return {
            "counts": counts,
            "total_tasks": total_tasks,
            "terminal_tasks": terminal_tasks,
            "outcome_percentages": outcome_percentages,
            "input_tokens": input_tokens,
            **{field: sum(int(row.get(field) or 0) for row in rows) for field in CACHE_USAGE_FIELDS},
            "output_tokens": output_tokens,
            "total_tokens": input_tokens + output_tokens,
            "compaction_events": compaction_events,
            "average_compaction_events": (compaction_events / total_tasks) if total_tasks else 0.0,
            "average_task_seconds": (sum(terminal_durations) / len(terminal_durations)) if terminal_durations else 0.0,
            "average_input_tokens": (input_tokens / total_tasks) if total_tasks else 0.0,
            "average_output_tokens": (output_tokens / total_tasks) if total_tasks else 0.0,
            "grouped_tool_totals": grouped_tool_totals,
            "average_tool_usage": average_tool_usage,
            "tool_call_success": tool_call_success,
        }

    def recover_interrupted(self) -> int:
        """Restore normal pauses; return interrupted work without rerunning review."""
        recovered = 0
        _cleanup_detached_owners(self.storage)
        _recover_interrupted_checklist_reviews(self.storage)
        for row in self.list_agents():
            status = str(row.get("status") or "")
            reviewer = _is_reviewer_agent(row)
            orphan = not self.paths.chat_json(str(row.get("source_chat_id") or "")).is_file()
            if status == "paused" and not reviewer and not orphan:
                continue
            if status not in {"queued", "running", "paused"}:
                continue
            agent_id = str(row.get("agent_id") or "")
            try:
                if bool(row.get("pause_requested")) and not reviewer and not orphan:
                    self.update_agent(agent_id, {
                        "status": "paused", "pause_requested": False,
                        "active_started_at": None, "progress_message": "Paused",
                    })
                    self.append_event(agent_id, "paused", {"message": "Pause restored after restart.", "recovered_after_restart": True})
                    recovered += 1
                    continue
                diagnostic = (
                    "The source Chat no longer exists."
                    if orphan else
                    "Velox stopped before this background agent reached a terminal event."
                )
                if reviewer:
                    diagnostic += " The independent Reviewer has no surviving source waiter; request a fresh review explicitly."
                saved = self.update_agent(agent_id, {
                    "status": "failed", "pause_requested": False,
                    "pending_tool_call": None, "active_started_at": None,
                    "failure_message": diagnostic, "progress_message": "Interrupted",
                    "paused_due_to_timeout": False, "paused_due_to_llm_timeout": False,
                })
                self.append_event(agent_id, "failed", {"message": diagnostic, "recovered_after_restart": True})
                recovered += 1
            except FileNotFoundError:
                continue
        if recovered:
            _best_effort_lifecycle_log(self.storage, "agent.recovered_interrupted", {"count": recovered})
        return recovered


def agent_transcript_markdown(agent: dict[str, Any], events: list[dict[str, Any]]) -> str:
    """Render a complete, selectable audit transcript for the agent dialog."""
    status = str(agent.get("status") or "unknown")
    percent = agent.get("progress_percent")
    progress = str(agent.get("progress_message") or "").strip()
    progress_label = f"{percent}%" if percent is not None else status.title()
    if progress:
        progress_label += f" — {progress}"
    timeout_minutes = int(agent.get("timeout_minutes") or AGENT_TIMEOUT_MINUTES_DEFAULT)
    compactions = max(
        int(agent.get("compaction_count") or 0),
        sum(1 for event in events if str(event.get("kind") or "") == "context_compacted"),
    )
    request_timeouts = int(agent.get("llm_request_timeout_count") or 0)
    last_request_timeout_seconds = int(agent.get("last_llm_timeout_seconds") or 0)
    stats = agent.get("stats") if isinstance(agent.get("stats"), dict) else default_tool_usage_stats()
    by_type = stats.get("tool_calls_by_type") if isinstance(stats.get("tool_calls_by_type"), dict) else {}
    parts = [
        f"# {str(agent.get('title') or 'Background agent')}",
        f"**Status:** {status}  ",
        f"**Progress:** {progress_label}  ",
        f"**Agent ID:** `{agent.get('agent_id', '')}`  ",
        f"**Agent Task Run ID:** `{int(agent.get('task_run_id') or 0)}`  ",
        f"**Source chat:** `{agent.get('source_chat_id', '')}`  ",
        f"**Endpoint profile:** `{agent.get('endpoint_profile_id', '')}`  ",
        f"**Current timeout:** {timeout_minutes:,} minutes  ",
        f"**Timeout extensions:** {int(agent.get('timeout_extension_count') or 0):,}  ",
        f"**LLM request timeouts:** {request_timeouts:,}  ",
        *(
            [f"**Last endpoint request limit:** {last_request_timeout_seconds:,} seconds  "]
            if last_request_timeout_seconds > 0 else []
        ),
        f"**Context compactions:** {compactions:,}  ",
        f"**Created:** {agent.get('created_at') or ''}  ",
        f"**Started:** {agent.get('started_at') or ''}  ",
        f"**Completed:** {agent.get('completed_at') or ''}",
        "",
        "## Tools Usage Stats",
        f"**Total calls:** {int(stats.get('tool_calls_total') or 0):,}  ",
        f"**Succeeded:** {int(stats.get('tool_calls_succeeded') or 0):,}  ",
        f"**Failed:** {int(stats.get('tool_calls_failed') or 0):,}",
    ]
    if by_type:
        for tool_name in sorted(by_type, key=lambda name: (-int((by_type.get(name) or {}).get("total") or 0), str(name))):
            row = by_type.get(tool_name) if isinstance(by_type.get(tool_name), dict) else {}
            parts.append(
                f"- `{tool_name}` — {int(row.get('total') or 0):,} total; "
                f"{int(row.get('succeeded') or 0):,} succeeded; {int(row.get('failed') or 0):,} failed"
            )
    else:
        parts.append("_No tool calls recorded._")
    parts.extend([
        "",
        "## Task",
        str(agent.get("task") or "_No task text stored._"),
    ])
    if str(agent.get("context") or "").strip():
        parts.extend(["", "## Additional context", str(agent.get("context") or "")])
    parts.extend(["", "## Activity transcript"])
    if not events:
        parts.append("_No events recorded._")
    for index, event in enumerate(events, 1):
        kind = str(event.get("kind") or "event")
        created_at = str(event.get("created_at") or "")
        data = event.get("data") if isinstance(event.get("data"), dict) else {}
        title = kind.replace("_", " ").title()
        parts.extend(["", f"### {index}. {title} — {created_at}"])
        if kind == "llm_output":
            text = str(data.get("text") or "")
            parts.append(text or "_Empty LLM output._")
            metadata = {key: value for key, value in data.items() if key != "text" and value not in (None, "", {}, [])}
            if metadata:
                parts.extend(["", "~~~~json", json.dumps(metadata, ensure_ascii=False, indent=2, default=str), "~~~~"])
        elif kind == "progress":
            msg = str(data.get("message") or "")
            pct = data.get("percent")
            parts.append((f"**{pct}%** — " if pct is not None else "") + (msg or "Progress reported."))
        elif kind == "expert_mode_continuation":
            parts.append("Velox injected the active Checklist checklist into this Agent conversation.")
            metadata = {
                key: value for key, value in data.items()
                if key not in {"message", "request_message"} and value not in (None, "", {}, [])
            }
            if metadata:
                parts.extend(["", "~~~~json", json.dumps(metadata, ensure_ascii=False, indent=2, default=str), "~~~~"])
        elif kind in {"succeeded", "failed", "cancelled", "started", "paused", "resumed", "timeout_paused"}:
            msg = str(data.get("message") or "")
            parts.append(msg or title)
            extra = {key: value for key, value in data.items() if key != "message" and value not in (None, "", {}, [])}
            if extra:
                parts.extend(["", "~~~~json", json.dumps(extra, ensure_ascii=False, indent=2, default=str), "~~~~"])
        elif kind == "context_compacted":
            parts.append(
                f"Reduced estimated context from **{int(data.get('before_tokens') or 0):,}** to "
                f"**{int(data.get('after_tokens') or 0):,}** tokens."
            )
            parts.extend(["", str(data.get("summary") or "_No compacted summary stored._")])
            metadata = {key: value for key, value in data.items() if key not in {"summary", "messages"} and value not in (None, "", {}, [])}
            if metadata:
                parts.extend(["", "~~~~json", json.dumps(metadata, ensure_ascii=False, indent=2, default=str), "~~~~"])
        elif kind == "conversation_message":
            role = str(data.get("role") or "user").upper()
            parts.extend([f"**{role}**", str(data.get("content") or "")])
        else:
            parts.extend(["~~~~json", json.dumps(data, ensure_ascii=False, indent=2, default=str), "~~~~"])
    return "\n".join(parts).strip() + "\n"


def format_duration_hms(seconds: float | int | None) -> str:
    """Return an unbounded HH:MM:SS duration used by Agent Task tables."""
    try:
        total = max(0, int(round(float(seconds or 0.0))))
    except Exception:
        total = 0
    hours, remainder = divmod(total, 3600)
    minutes, secs = divmod(remainder, 60)
    return f"{hours:02d}:{minutes:02d}:{secs:02d}"


def format_dashboard_start_time(value: Any) -> str:
    """Format a Task start timestamp as DD/MM/YY HH:MM:SS in local time."""
    epoch = _iso_timestamp_epoch(value)
    if epoch is None:
        return "—"
    try:
        return datetime.fromtimestamp(epoch, tz=timezone.utc).astimezone().strftime("%d/%m/%y %H:%M:%S")
    except Exception:
        return "—"


def _agent_metric_number(container: Any, *keys: str) -> float | None:
    if not isinstance(container, dict):
        return None
    for key in keys:
        value = container.get(key)
        if isinstance(value, bool) or value is None:
            continue
        try:
            number = float(value)
        except Exception:
            continue
        if math.isfinite(number) and number >= 0.0:
            if key.endswith("_ms"):
                number /= 1000.0
            return number
    return None


def agent_task_statistics(
    agent: dict[str, Any],
    events: Iterable[dict[str, Any]] = (),
    *,
    current_time: datetime | None = None,
) -> dict[str, Any]:
    """Aggregate one Agent Task for row tooltips and the shared statistics dialog."""
    event_rows = [row for row in (events or []) if isinstance(row, dict)]
    stats = agent.get("stats") if isinstance(agent.get("stats"), dict) else default_tool_usage_stats()
    total_calls = max(0, int(stats.get("tool_calls_total") or 0))
    succeeded_calls = max(0, int(stats.get("tool_calls_succeeded") or 0))
    failed_calls = max(0, int(stats.get("tool_calls_failed") or 0))
    success_rate = (100.0 * succeeded_calls / total_calls) if total_calls else 0.0
    input_tokens = max(0, int(agent.get("input_tokens") or 0))
    output_tokens = max(0, int(agent.get("output_tokens") or 0))
    prompt_seconds = 0.0
    generation_seconds = 0.0
    prompt_rate_weighted = 0.0
    prompt_rate_weight = 0.0
    generation_rate_weighted = 0.0
    generation_rate_weight = 0.0
    llm_outputs = 0
    for event in event_rows:
        if str(event.get("kind") or "") != "llm_output":
            continue
        llm_outputs += 1
        data = event.get("data") if isinstance(event.get("data"), dict) else {}
        raw = data.get("raw_response") if isinstance(data.get("raw_response"), dict) else {}
        candidates = [
            data.get("usage") if isinstance(data.get("usage"), dict) else {},
            raw.get("usage") if isinstance(raw.get("usage"), dict) else {},
            raw.get("timings") if isinstance(raw.get("timings"), dict) else {},
            raw,
        ]
        event_in = max(0, int(data.get("input_tokens") or 0))
        event_out = max(0, int(data.get("output_tokens") or 0))
        event_prompt_seconds = next((value for candidate in candidates if (value := _agent_metric_number(
            candidate, "prompt_seconds", "prompt_time", "prompt_ms", "prefill_seconds", "prefill_ms"
        )) is not None), None)
        event_generation_seconds = next((value for candidate in candidates if (value := _agent_metric_number(
            candidate, "generation_seconds", "generation_time", "generation_ms", "decode_seconds", "decode_ms"
        )) is not None), None)
        if event_prompt_seconds is not None:
            prompt_seconds += event_prompt_seconds
        if event_generation_seconds is not None:
            generation_seconds += event_generation_seconds
        prompt_rate = next((value for candidate in candidates if (value := _agent_metric_number(
            candidate, "prompt_tokens_per_second", "prefill_tokens_per_second", "prompt_tps", "prefill_tps"
        )) is not None), None)
        generation_rate = next((value for candidate in candidates if (value := _agent_metric_number(
            candidate, "generation_tokens_per_second", "tokens_per_second", "decode_tokens_per_second", "generation_tps", "decode_tps"
        )) is not None), None)
        if prompt_rate is not None:
            weight = max(1.0, float(event_in))
            prompt_rate_weighted += prompt_rate * weight
            prompt_rate_weight += weight
        if generation_rate is not None:
            weight = max(1.0, float(event_out))
            generation_rate_weighted += generation_rate * weight
            generation_rate_weight += weight
    prompt_rate = (input_tokens / prompt_seconds) if prompt_seconds > 0 else (
        prompt_rate_weighted / prompt_rate_weight if prompt_rate_weight > 0 else 0.0
    )
    generation_rate = (output_tokens / generation_seconds) if generation_seconds > 0 else (
        generation_rate_weighted / generation_rate_weight if generation_rate_weight > 0 else 0.0
    )
    compactions = max(
        max(0, int(agent.get("compaction_count") or 0)),
        sum(1 for event in event_rows if str(event.get("kind") or "") == "context_compacted"),
    )
    duration_seconds = AgentStore._agent_active_duration_seconds(agent, current_time)
    return {
        "status": str(agent.get("status") or "queued"),
        "duration_seconds": duration_seconds,
        "duration_hms": format_duration_hms(duration_seconds),
        "input_tokens": input_tokens,
        **{field: int(agent.get(field) or 0) for field in CACHE_USAGE_FIELDS},
        "output_tokens": output_tokens,
        "total_tokens": input_tokens + output_tokens,
        "model_rounds": max(max(0, int(agent.get("llm_turn_count") or 0)), llm_outputs),
        "prompt_seconds": prompt_seconds,
        "generation_seconds": generation_seconds,
        "average_prompt_tokens_per_second": prompt_rate,
        "average_generation_tokens_per_second": generation_rate,
        "tool_calls_total": total_calls,
        "tool_calls_succeeded": succeeded_calls,
        "tool_calls_failed": failed_calls,
        "tool_call_success_rate": success_rate,
        "compaction_count": compactions,
        "last_context_tokens": max(0, int(agent.get("last_context_tokens") or 0)),
        "llm_request_timeout_count": max(0, int(agent.get("llm_request_timeout_count") or 0)),
    }


def agent_statistics_tooltip(agent: dict[str, Any], events: Iterable[dict[str, Any]] = ()) -> str:
    metrics = agent_task_statistics(agent, events)
    input_rate = float(metrics.get("average_prompt_tokens_per_second") or 0.0)
    generated = float(metrics.get("average_generation_tokens_per_second") or 0.0)
    input_rate_text = f"{input_rate:,.2f} t/s" if input_rate > 0 else "unavailable"
    generated_text = f"{generated:,.2f} t/s" if generated > 0 else "unavailable"
    return "\n".join([
        f"Status: {str(metrics.get('status') or 'queued').title()}",
        f"Duration: {metrics.get('duration_hms')}",
        f"Input tokens: {int(metrics.get('input_tokens') or 0):,}",
        f"Output tokens: {int(metrics.get('output_tokens') or 0):,}",
        f"Input: {input_rate_text}",
        f"Generated: {generated_text}",
        f"Tool success: {float(metrics.get('tool_call_success_rate') or 0.0):.1f}% "
        f"({int(metrics.get('tool_calls_succeeded') or 0):,}/{int(metrics.get('tool_calls_total') or 0):,})",
        f"Model rounds: {int(metrics.get('model_rounds') or 0):,}",
        f"Compactions: {int(metrics.get('compaction_count') or 0):,}",
    ])


def agent_statistics_text(agent: dict[str, Any], events: Iterable[dict[str, Any]] = ()) -> str:
    metrics = agent_task_statistics(agent, events)
    input_rate = float(metrics.get("average_prompt_tokens_per_second") or 0.0)
    generated = float(metrics.get("average_generation_tokens_per_second") or 0.0)
    lines = [
        f"Agent: {str(agent.get('title') or 'Background agent')}",
        f"Status: {str(metrics.get('status') or 'queued').title()}",
        f"Duration: {metrics.get('duration_hms')}",
        f"Endpoint profile: {str(agent.get('endpoint_profile_id') or '(none)')}",
        "",
        f"Input tokens: {int(metrics.get('input_tokens') or 0):,}",
        f"Output tokens: {int(metrics.get('output_tokens') or 0):,}",
        f"Total tokens: {int(metrics.get('total_tokens') or 0):,}",
        f"Average input throughput: {input_rate:.2f} tokens/s" if input_rate > 0 else "Average input throughput: unavailable",
        f"Average generation throughput: {generated:.2f} tokens/s" if generated > 0 else "Average generation throughput: unavailable",
        f"Model rounds: {int(metrics.get('model_rounds') or 0):,}",
        f"Last context estimate: {int(metrics.get('last_context_tokens') or 0):,} tokens",
        f"Context compactions: {int(metrics.get('compaction_count') or 0):,}",
        f"LLM request timeouts: {int(metrics.get('llm_request_timeout_count') or 0):,}",
        "",
        f"Tool calls: {int(metrics.get('tool_calls_total') or 0):,}",
        f"Succeeded tool calls: {int(metrics.get('tool_calls_succeeded') or 0):,}",
        f"Failed tool calls: {int(metrics.get('tool_calls_failed') or 0):,}",
        f"Tool success rate: {float(metrics.get('tool_call_success_rate') or 0.0):.1f}%",
    ]
    return "\n".join(lines)


def agent_tool_statistics_rows(agent: dict[str, Any]) -> list[dict[str, Any]]:
    stats = agent.get("stats") if isinstance(agent.get("stats"), dict) else default_tool_usage_stats()
    by_type = stats.get("tool_calls_by_type") if isinstance(stats.get("tool_calls_by_type"), dict) else {}
    rows: list[dict[str, Any]] = []
    for name, raw in sorted(by_type.items(), key=lambda item: (-int((item[1] or {}).get("total") or 0), str(item[0]).casefold())):
        row = raw if isinstance(raw, dict) else {}
        rows.append({
            "id": str(name), "tool": str(name),
            "total": max(0, int(row.get("total") or 0)),
            "succeeded": max(0, int(row.get("succeeded") or 0)),
            "failed": max(0, int(row.get("failed") or 0)),
        })
    return rows


def iter_agent_debug_report_lines(agent: dict[str, Any], events: Iterable[dict[str, Any]], *, endpoint: dict[str, Any] | None=None, source_chat: dict[str, Any] | None=None, data_root: str='', generated_at: str | None=None) -> Iterable[str]:
    """Build a redacted, human-readable diagnostic report for one Agent Task."""
    event_rows = [row for row in events or [] if isinstance(row, dict)]
    metrics = agent_task_statistics(agent, event_rows)
    yield from ['VELOX AGENT DEBUG REPORT', 'This report is intended for debugging Velox, model behavior, tools, prompts, and Skills.', 'Known credential fields and common token patterns are redacted. Review private content before sharing. Unpaired Unicode codepoints are escaped.', '', f'Generated: {generated_at or now_iso()}', f'Application version: {APP_VERSION}', f'Source revision: V{SOURCE_REVISION}', f'Application schema: {APP_SCHEMA}', f'Agent schema: {AGENT_SCHEMA}', f'Agent event schema: {AGENT_EVENT_SCHEMA}', f"Data root: {(redact_chat_debug_text(data_root) if data_root else '(not supplied)')}"]
    yield from _iter_debug_report_section('AGENT RECORD')
    yield from _iter_debug_report_value_lines(agent, key_name='agent')
    yield from _iter_debug_report_section('AGENT TASK STATISTICS')
    yield from _iter_debug_report_value_lines(metrics, key_name='statistics')
    yield from _iter_debug_report_section('ACTIVE ENDPOINT')
    if endpoint_provider(endpoint or {}) == ENDPOINT_PROVIDER_VLLM:
        yield VLLM_CACHE_REPORTING_HINT
    yield from _iter_debug_report_value_lines(endpoint or {}, key_name='endpoint')
    yield from _iter_debug_report_section('SOURCE CHAT')
    yield from _iter_debug_report_value_lines(source_chat or {}, key_name='chat')
    yield from _iter_debug_report_section('COMPLETE AGENT TRANSCRIPT')
    if not event_rows:
        yield '(no events)'
    for index, event in enumerate(event_rows, 1):
        yield from ['', '-' * 88, f'EVENT {index}', '-' * 88]
        yield from _iter_debug_report_value_lines(event, key_name='event')
    yield from ['', '=' * 88, 'END OF VELOX AGENT DEBUG REPORT', '=' * 88, '']
    return


def format_agent_debug_report(*args: Any, **kwargs: Any) -> str:
    return "\n".join(iter_agent_debug_report_lines(*args, **kwargs))

def agent_compaction_results_text(events: list[dict[str, Any]]) -> str:
    """Return the literal post-compaction context for every recorded event."""
    compacted = [
        event for event in events
        if isinstance(event, dict) and str(event.get("kind") or "") == "context_compacted"
    ]
    if not compacted:
        return "No context compaction events were recorded for this agent task."
    sections: list[str] = []
    for index, event in enumerate(compacted, 1):
        data = event.get("data") if isinstance(event.get("data"), dict) else {}
        messages = data.get("messages") if isinstance(data.get("messages"), list) else []
        sections.extend([
            f"====== Compaction Event #{index} ======",
            f"Recorded: {str(event.get('created_at') or '')}",
            (
                f"Complete request: {int(data.get('complete_before_tokens') or 0):,} -> "
                f"{int(data.get('complete_after_tokens') or 0):,} calibrated tokens "
                f"(window {int(data.get('context_window_tokens') or 0):,}; "
                f"effective prompt capacity {int(data.get('calibrated_prompt_capacity_tokens') or 0):,}; "
                f"fits: {'yes' if bool(data.get('fits_effective_context')) else 'no'})"
            ),
            (
                f"Compaction request tokens: {int(data.get('compaction_input_tokens') or 0):,} input / "
                f"{int(data.get('compaction_output_tokens') or 0):,} output"
            ),
            (
                f"Summarized intermediate messages: {int(data.get('summarized_message_count') or 0):,}; "
                f"recent messages retained: {int(data.get('preserved_recent_message_count') or 0):,}"
            ),
        ])
        fallback_error = str(data.get("fallback_error") or "").strip()
        if fallback_error:
            sections.append(f"Compaction diagnostic: {fallback_error}")
        sections.extend(["", f"LITERAL NEW CONTEXT ({len(messages):,} messages)", ""])
        if messages:
            for message_index, message in enumerate(messages, 1):
                if not isinstance(message, dict):
                    role = "UNKNOWN"
                    content = json.dumps(message, ensure_ascii=False, indent=2, default=str)
                else:
                    role = str(message.get("role") or "unknown").upper()
                    raw_content = message.get("content")
                    content = (
                        str(raw_content)
                        if isinstance(raw_content, str)
                        else json.dumps(raw_content, ensure_ascii=False, indent=2, default=str)
                    )
                sections.extend([
                    f"----- Message {message_index} of {len(messages)} | {role} -----",
                    content if content else "[empty message]",
                    "",
                ])
        else:
            # Retain readability for an event that lacks the full
            # checkpoint, although current Velox writes the literal context.
            sections.extend([
                "[No literal message checkpoint was stored for this event.]",
                str(data.get("summary") or "[No compacted summary stored.]"),
                "",
            ])
    return "\n".join(sections).rstrip() + "\n"


# =============================================================================
# LLM, context, summaries, tools, and runtime services
# =============================================================================


@dataclass
class LLMRequest:
    scope_id: str | None
    endpoint_profile_id: str
    messages: list[dict[str, Any]]
    stream: bool = True
    max_output_tokens: int | None = None
    reasoning_effort_override: str | None = None
    cancel_event: threading.Event | None = None
    native_tools: list[dict[str, Any]] | None = None
    # Queue/monitor metadata describes one logical Chat, Agent, Image, or System Task.
    # A Task may issue many endpoint requests; each request independently acquires
    # endpoint inference capacity and no slot is retained across tools/cooldowns.
    monitor_task_id: str | None = None
    task_kind: str = "system"
    task_title: str = ""
    # Transient source/context metadata for Dashboard Task inspection. This is not
    # a compatibility layer or persisted request model; it is copied into the
    # current strict-revision Task monitor record when that record is auto-created.
    task_metadata: dict[str, Any] | None = None
    # One small shared observation for dataclasses.replace-derived transport requests.
    # Never part of model messages. Populated only after selecting the real wire shape.
    prepared_capacity: dict[str, Any] = field(default_factory=dict)

    def __deepcopy__(self, memo: dict[int, Any]) -> "LLMRequest":
        """Detach request data while sharing the non-copyable cancellation signal.

        Tests, inspectors, and retry bookkeeping legitimately snapshot complete
        requests. ``threading.Event`` owns a lock and cannot be pickled/deep-copied;
        the event is intentionally one shared cancellation channel for every
        derived snapshot of the same in-flight request.
        """
        existing = memo.get(id(self))
        if isinstance(existing, LLMRequest):
            return existing
        values: dict[str, Any] = {}
        for field_info in dataclasses.fields(self):
            value = getattr(self, field_info.name)
            values[field_info.name] = (
                value if field_info.name == "cancel_event"
                else copy.deepcopy(value, memo)
            )
        result = type(self)(**values)
        memo[id(self)] = result
        return result


@dataclass
class LLMChunk:
    text: str = ""
    reasoning_text: str = ""
    usage: dict[str, Any] | None = None
    done: bool = False
    error: str | None = None
    finish_reason: str | None = None
    stop_reason: str | None = None
    native_tool_calls: list[dict[str, Any]] | None = None
    response_output_items: list[dict[str, Any]] | None = None
    # Optional provider-reported prefill progress. Most OpenAI-compatible
    # endpoints expose no live prefill counter, so the Chat toolbar falls back
    # to an elapsed Prompt timer. Compatible gateways may report either a
    # percentage directly or processed/total prompt-token counters.
    prompt_progress_percent: float | None = None
    prompt_tokens_processed: int | None = None
    prompt_tokens_total: int | None = None
    # Runtime-only retry disposition. Never sent to the provider or treated as output.
    endpoint_recovery_exhausted: bool = False
    endpoint_failure: dict[str, Any] | None = None
    # Runtime/parser metadata, not fields sent blindly to an endpoint.
    meaningful_progress: bool | None = None
    model_output_observed: bool = False
    progress_monotonic: float | None = None
    # Exact completed provider reasoning fields; text deltas still stream separately.
    reasoning_fields: dict[str, Any] | None = None
    provider_diagnostics: dict[str, Any] | None = None


@dataclass(slots=True)
class EndpointQueueTicket:
    ticket_id: str
    endpoint_profile_id: str
    endpoint_label: str
    monitor_task_id: str | None
    task_kind: str
    submitted_monotonic: float
    sequence: int
    auto_monitor_task: bool = False
    granted: bool = False
    cancelled: bool = False
    request_active: bool = False
    release_requested: bool = False


class EndpointInferenceLease:
    """One provider request admitted to one physical endpoint inference slot.

    A lease exists only while a provider request is actually in flight. Tool work,
    cooldowns, review waits, sleeps, and other non-inference phases hold no endpoint
    capacity. Cleanup runs in its own shielded task so cancellation cannot strand a
    request-active marker or endpoint capacity.
    """

    def __init__(self, scheduler: "EndpointInferenceScheduler", ticket: EndpointQueueTicket):
        self.scheduler = scheduler
        self.ticket = ticket
        self.released = False
        self._release_task: asyncio.Task[None] | None = None

    def _release_done(self, task: asyncio.Task[None]) -> None:
        if not task.cancelled() and task.exception() is None:
            self.released = True

    async def release(self) -> None:
        if self.released:
            return
        if self._release_task is None:
            self._release_task = asyncio.create_task(self.scheduler.finish_request(self.ticket))
            self._release_task.add_done_callback(self._release_done)
        await asyncio.shield(self._release_task)
        self.released = True


class EndpointInferenceScheduler:
    """Priority-aware per-endpoint provider-request scheduler.

    Each endpoint admits at most ``max_concurrent_requests`` requests that are
    actually performing provider inference. A completed provider round releases its
    slot before ordinary tool work, rate-limit/retry cooldowns, Reviewer waits,
    ``time_sleep``, or manual pauses. The next provider round competes normally for
    capacity, while duplicate concurrent rounds from the same logical Task remain
    serialized. The sole user-pinned Task wins, then queued Chat/Chat-owned Image
    requests, then Agents/Agent-owned Image requests, then System work. Lower classes
    age upward after bounded waits so continuous Chat traffic cannot starve them.

    Core invariant: active endpoint slots are exactly the requests currently in
    provider inference; retained logical Task affinity never consumes capacity.
    """

    ACTIVE_PHASES = frozenset({"inference"})
    YIELD_PHASES = frozenset({"paused", "waiting", "sleeping"})
    QUEUE_AGING_SECONDS = 30.0

    def __init__(
        self,
        storage: "Storage",
        endpoint_resolver: Callable[[str], dict[str, Any]],
        monitor: "LLMTaskMonitor | None" = None,
    ) -> None:
        self.storage = storage
        self.endpoint_resolver = endpoint_resolver
        self.monitor: "LLMTaskMonitor | None" = None
        self._condition = asyncio.Condition()
        self._queued: dict[str, dict[str, EndpointQueueTicket]] = {}
        # Active entries are physical provider-request slots. A Task performing
        # tools/cooldowns/review/sleep has no entry here.
        self._active: dict[str, dict[str, EndpointQueueTicket]] = {}
        self._request_active_ticket_ids: set[str] = set()
        self._sequence = itertools.count(1)
        self._closed = False
        self._loop: asyncio.AbstractEventLoop | None = None
        self.bind_monitor(monitor)

    def bind_monitor(self, monitor: "LLMTaskMonitor | None") -> None:
        if self.monitor is monitor:
            return
        old = self.monitor
        if old is not None:
            unregister = getattr(old, "unregister_lifecycle_listener", None)
            if callable(unregister):
                try:
                    unregister(self._on_monitor_lifecycle)
                except Exception:
                    pass
        self.monitor = monitor
        if monitor is not None:
            register = getattr(monitor, "register_lifecycle_listener", None)
            if callable(register):
                try:
                    register(self._on_monitor_lifecycle)
                except Exception:
                    pass

    def _profile(self, endpoint_profile_id: str) -> dict[str, Any]:
        try:
            return self.endpoint_resolver(str(endpoint_profile_id or ""))
        except Exception:
            return {
                "profile_id": str(endpoint_profile_id or "endpoint"),
                "profile_label": str(endpoint_profile_id or "Endpoint"),
                "provider": ENDPOINT_PROVIDER_GENERIC,
                "max_concurrent_requests": ENDPOINT_MAX_CONCURRENT_HOSTED_DEFAULT,
            }

    def _capacity(self, endpoint_profile_id: str) -> int:
        return endpoint_max_concurrent_requests(self._profile(endpoint_profile_id))

    @staticmethod
    def _kind(value: Any) -> str:
        raw = str(value or "system").strip().lower()
        return raw if raw in {"chat", "agent", "image", "system"} else "system"

    def _monitor_metadata_snapshot(self, task_id: str | None) -> dict[str, Any]:
        monitor = self.monitor
        if not task_id or monitor is None:
            return {}
        getter = getattr(monitor, "record_metadata", None)
        if not callable(getter):
            return {}
        try:
            value = getter(task_id)
            return dict(value) if isinstance(value, dict) else {}
        except Exception:
            return {}

    def _monitor_state(self, task_id: str | None) -> str:
        monitor = self.monitor
        if not task_id or monitor is None:
            return ""
        getter = getattr(monitor, "record_state", None)
        if not callable(getter):
            return ""
        try:
            return str(getter(task_id) or "").strip().lower()
        except Exception:
            return ""

    def _monitor_is_terminal(self, task_id: str | None) -> bool:
        return self._monitor_state(task_id) in {"completed", "cancelled", "failed"}

    def _ticket_is_paused(self, ticket: EndpointQueueTicket) -> bool:
        metadata = self._monitor_metadata_snapshot(ticket.monitor_task_id)
        return bool(metadata.get("pause_requested")) or str(metadata.get("phase") or "").lower() == "paused"

    def _ticket_is_yielded(self, ticket: EndpointQueueTicket) -> bool:
        """Return whether this logical Task is intentionally not using endpoint capacity."""
        metadata = self._monitor_metadata_snapshot(ticket.monitor_task_id)
        phase = str(metadata.get("phase") or "").strip().lower()
        return bool(metadata.get("pause_requested")) or phase in self.YIELD_PHASES

    @staticmethod
    def _ticket_logical_key(ticket: EndpointQueueTicket) -> str:
        return str(ticket.monitor_task_id or ticket.ticket_id)

    def _ticket_effective_kind(self, ticket: EndpointQueueTicket) -> str:
        """Classify delegated Image work with the Chat or Agent that owns it."""
        kind = self._kind(ticket.task_kind)
        if kind != "image":
            return kind
        metadata = self._monitor_metadata_snapshot(ticket.monitor_task_id)
        if str(metadata.get("agent_id") or "").strip():
            return "agent"
        if str(metadata.get("chat_id") or metadata.get("source_chat_id") or "").strip():
            return "chat"
        return "system"

    def _ticket_is_prioritized(self, ticket: EndpointQueueTicket) -> bool:
        monitor = self.monitor
        if monitor is None or not ticket.monitor_task_id:
            return False
        getter = getattr(monitor, "is_task_prioritized", None)
        if callable(getter):
            try:
                return bool(getter(ticket.monitor_task_id))
            except Exception:
                return False
        return bool(self._monitor_metadata_snapshot(ticket.monitor_task_id).get("pinned_priority"))

    def _priority_key(self, ticket: EndpointQueueTicket) -> tuple[Any, ...]:
        """Return deterministic selection order with bounded starvation aging."""
        effective_kind = self._ticket_effective_kind(ticket)
        prioritized = self._ticket_is_prioritized(ticket) and self._kind(ticket.task_kind) != "system"
        if prioritized:
            return (0, ticket.sequence, ticket.ticket_id)
        if effective_kind == "chat":
            base_group = 1
        elif effective_kind == "agent":
            base_group = 2
        else:
            base_group = 3
        waited = max(0.0, time.monotonic() - float(ticket.submitted_monotonic or 0.0))
        promotions = int(waited // max(0.001, float(self.QUEUE_AGING_SECONDS)))
        group = max(1, base_group - promotions)
        return (group, ticket.sequence, ticket.ticket_id)

    def _assert_slot_invariant_locked(self) -> None:
        """Fail fast if endpoint capacity accounting diverges from live requests."""
        active_ids = {
            ticket_id
            for active_map in self._active.values()
            for ticket_id, ticket in active_map.items()
            if not ticket.cancelled
        }
        if active_ids != self._request_active_ticket_ids:
            raise RuntimeError(
                "Endpoint scheduler slot invariant violated: active slots must equal "
                "request-active provider inferences."
            )


    def _active_ticket_for_logical_key_locked(
        self, endpoint_profile_id: str, logical_key: str,
    ) -> EndpointQueueTicket | None:
        for ticket in self._active.get(endpoint_profile_id, {}).values():
            if not ticket.cancelled and self._ticket_logical_key(ticket) == logical_key:
                return ticket
        return None

    @staticmethod
    def _consume_background_task(task: asyncio.Task[Any]) -> None:
        try:
            task.result()
        except BaseException:
            pass

    def _schedule_task_slot_release(self, task_id: str) -> None:
        loop = self._loop
        if loop is None or not loop.is_running() or self._closed:
            return

        def launch() -> None:
            if self._closed:
                return
            task = loop.create_task(self.release_task(task_id))
            task.add_done_callback(self._consume_background_task)

        try:
            running = asyncio.get_running_loop()
        except RuntimeError:
            running = None
        if running is loop:
            launch()
        else:
            try:
                loop.call_soon_threadsafe(launch)
            except RuntimeError:
                pass

    def _on_monitor_lifecycle(self, task_id: str, state: str, phase: str) -> None:
        resolved_phase = str(phase or "").lower()
        if (
            str(state or "").lower() in {"completed", "cancelled", "failed"}
            or resolved_phase in self.YIELD_PHASES
        ):
            self._schedule_task_slot_release(str(task_id or ""))

    def _monitor_metadata(self, request_id: str | None, patch: dict[str, Any]) -> None:
        monitor = self.monitor
        if not request_id or monitor is None:
            return
        updater = getattr(monitor, "update_metadata", None)
        if callable(updater):
            try:
                updater(request_id, patch, persist=False)
            except Exception:
                pass

    def _monitor_phase(self, request_id: str | None, phase: str) -> None:
        monitor = self.monitor
        if not request_id or monitor is None:
            return
        setter = getattr(monitor, "set_phase", None)
        if callable(setter):
            try:
                setter(request_id, phase, persist=False)
            except Exception:
                pass

    def _ordered_unique_runnable_locked(self, endpoint_profile_id: str) -> list[EndpointQueueTicket]:
        candidates = sorted(
            (
                row for row in self._queued.get(endpoint_profile_id, {}).values()
                if not row.cancelled and not self._ticket_is_yielded(row)
            ),
            key=self._priority_key,
        )
        seen: set[str] = set()
        ordered: list[EndpointQueueTicket] = []
        for row in candidates:
            logical_key = self._ticket_logical_key(row)
            if logical_key in seen:
                continue
            seen.add(logical_key)
            ordered.append(row)
        return ordered

    def _refresh_priorities_locked(self, endpoint_profile_id: str) -> None:
        active_map = self._active.get(endpoint_profile_id, {})
        active = [row for row in active_map.values() if not row.cancelled]
        queued = [
            row for row in self._queued.get(endpoint_profile_id, {}).values()
            if not row.cancelled
        ]
        yielded = [row for row in queued if self._ticket_is_yielded(row)]
        paused = [row for row in yielded if self._ticket_is_paused(row)]
        # Active provider requests keep their slots until that request unwinds and
        # are shown first. Pinned state affects the next free slot but never preempts
        # a provider request already holding capacity.
        active_ordered = sorted(
            active,
            key=lambda row: (
                0 if self._ticket_is_prioritized(row) else 1,
                row.sequence,
                row.ticket_id,
            ),
        )
        queued_ordered = self._ordered_unique_runnable_locked(endpoint_profile_id)
        profile = self._profile(endpoint_profile_id)
        provider_key = endpoint_provider(profile)
        for index, ticket in enumerate(active_ordered + queued_ordered, 1):
            if self._monitor_is_terminal(ticket.monitor_task_id):
                continue
            if ticket.ticket_id in active_map:
                state = "inference"
            else:
                state = "queued"
            patch = {
                "queue_endpoint": ticket.endpoint_label,
                "queue_priority": index,
                "queue_state": state,
                "endpoint_profile_id": endpoint_profile_id,
                "endpoint_label": ticket.endpoint_label,
                "provider": provider_key,
                "task_type": self._kind(ticket.task_kind).title(),
                "preemption_requested": False,
            }
            if state == "queued":
                patch.update({"phase": "queued", "phase_started_monotonic": None})
            self._monitor_metadata(ticket.monitor_task_id, patch)
        for ticket in yielded:
            if self._monitor_is_terminal(ticket.monitor_task_id):
                continue
            metadata = self._monitor_metadata_snapshot(ticket.monitor_task_id)
            phase = str(metadata.get("phase") or "ready").strip().lower() or "ready"
            queue_state = "paused" if ticket in paused else phase
            patch = {
                "phase_started_monotonic": None,
                "queue_priority": 0,
                "queue_state": queue_state,
                "endpoint_profile_id": endpoint_profile_id,
                "endpoint_label": ticket.endpoint_label,
                "provider": provider_key,
                "task_type": self._kind(ticket.task_kind).title(),
                "preemption_requested": False,
            }
            if ticket in paused:
                patch["phase"] = "paused"
            self._monitor_metadata(ticket.monitor_task_id, patch)

    def _ensure_monitor_task(
        self, request: LLMRequest, profile: dict[str, Any],
    ) -> tuple[str | None, bool]:
        monitor = self.monitor
        task_id = str(request.monitor_task_id or "").strip() or None
        if task_id or monitor is None:
            return task_id, False
        kind = self._kind(request.task_kind)
        label = str(profile.get("profile_label") or profile.get("label") or request.endpoint_profile_id)
        default_title = {
            "chat": "Chat Task",
            "agent": "Agent Task",
            "image": "Image analysis",
            "system": "System Task",
        }[kind]
        title = str(request.task_title or "").strip() or default_title
        metadata = copy.deepcopy(request.task_metadata or {})
        metadata.update({
            "endpoint_profile_id": request.endpoint_profile_id,
            "endpoint_label": label,
            "task_type": monitor._task_kind_label(kind),
            "title": title,
            "phase": "queued",
        })
        task_id = monitor.start(
            request.scope_id, title, task_kind=kind, metadata=metadata,
        )
        return task_id, True

    async def acquire(self, request: LLMRequest) -> EndpointInferenceLease:
        if self._closed:
            raise RuntimeError("Endpoint inference scheduler is closed")
        self._loop = asyncio.get_running_loop()
        endpoint_id = str(request.endpoint_profile_id or "").strip()
        profile = self._profile(endpoint_id)
        endpoint_label = str(profile.get("profile_label") or profile.get("label") or endpoint_id)
        request_id, auto_record = self._ensure_monitor_task(request, profile)
        ticket = EndpointQueueTicket(
            ticket_id=uuid_v4(),
            endpoint_profile_id=endpoint_id,
            endpoint_label=endpoint_label,
            monitor_task_id=request_id,
            task_kind=self._kind(request.task_kind),
            submitted_monotonic=time.monotonic(),
            sequence=next(self._sequence),
            auto_monitor_task=auto_record,
        )
        logical_key = self._ticket_logical_key(ticket)
        acquired = False
        queued_inserted = False
        try:
            async with self._condition:
                while True:
                    if self._closed:
                        raise RuntimeError("Endpoint inference scheduler is closed")
                    if request.cancel_event is not None and request.cancel_event.is_set():
                        raise LLMRequestCancelledError("Endpoint request cancelled while queued")
                    if request_id and self._monitor_is_terminal(request_id):
                        raise LLMRequestCancelledError("Logical Task ended while waiting for endpoint capacity")

                    existing = self._active_ticket_for_logical_key_locked(endpoint_id, logical_key)
                    if existing is not None and not existing.release_requested:
                        # A Task already owns a slot. Serialize its provider rounds
                        # but do not make it compete with unrelated queued Tasks.
                        self._queued.get(endpoint_id, {}).pop(ticket.ticket_id, None)
                        queued_inserted = False
                        if existing.ticket_id not in self._request_active_ticket_ids:
                            existing.request_active = True
                            self._request_active_ticket_ids.add(existing.ticket_id)
                            acquired = True
                            self._assert_slot_invariant_locked()
                            self._monitor_phase(request_id, "inference")
                            self._refresh_priorities_locked(endpoint_id)
                            self._condition.notify_all()
                            return EndpointInferenceLease(self, existing)
                    elif not queued_inserted:
                        self._queued.setdefault(endpoint_id, {})[ticket.ticket_id] = ticket
                        queued_inserted = True
                        # Never overwrite an explicit paused/waiting/sleeping phase
                        # merely because the Task attempts to queue a future round.
                        if not self._ticket_is_yielded(ticket):
                            self._monitor_phase(request_id, "queued")

                    queued_map = self._queued.setdefault(endpoint_id, {})
                    active_map = self._active.setdefault(endpoint_id, {})
                    ordered = self._ordered_unique_runnable_locked(endpoint_id)
                    capacity = self._capacity(endpoint_id)
                    available = max(0, capacity - len(active_map))
                    can_start = available > 0 and ticket in ordered[:available]
                    self._refresh_priorities_locked(endpoint_id)
                    if can_start:
                        queued_map.pop(ticket.ticket_id, None)
                        queued_inserted = False
                        ticket.granted = True
                        ticket.request_active = True
                        active_map[ticket.ticket_id] = ticket
                        self._request_active_ticket_ids.add(ticket.ticket_id)
                        acquired = True
                        self._assert_slot_invariant_locked()
                        self._monitor_phase(request_id, "inference")
                        self._refresh_priorities_locked(endpoint_id)
                        self._condition.notify_all()
                        return EndpointInferenceLease(self, ticket)
                    try:
                        await asyncio.wait_for(self._condition.wait(), timeout=0.25)
                    except asyncio.TimeoutError:
                        pass
        finally:
            if not acquired:
                async with self._condition:
                    ticket.cancelled = True
                    ticket.request_active = False
                    self._request_active_ticket_ids.discard(ticket.ticket_id)
                    self._queued.get(endpoint_id, {}).pop(ticket.ticket_id, None)
                    if self._active.get(endpoint_id, {}).get(ticket.ticket_id) is ticket:
                        self._active.get(endpoint_id, {}).pop(ticket.ticket_id, None)
                    self._assert_slot_invariant_locked()
                    self._refresh_priorities_locked(endpoint_id)
                    self._condition.notify_all()
                if auto_record and self.monitor is not None:
                    self.monitor.cancel(request_id)

    async def finish_request(self, ticket: EndpointQueueTicket) -> None:
        """End one provider request and immediately release endpoint capacity."""
        endpoint_id = ticket.endpoint_profile_id
        async with self._condition:
            self._request_active_ticket_ids.discard(ticket.ticket_id)
            ticket.request_active = False
            active_map = self._active.get(endpoint_id, {})
            if active_map.get(ticket.ticket_id) is ticket:
                active_map.pop(ticket.ticket_id, None)
                ticket.granted = False
                ticket.cancelled = True
                # Preserve an explicit yielded phase already advanced by the
                # runtime. Otherwise close inference before tools/cooldowns or
                # before the Task queues its next provider round.
                if not self._monitor_is_terminal(ticket.monitor_task_id):
                    phase = str(
                        self._monitor_metadata_snapshot(ticket.monitor_task_id).get("phase") or ""
                    ).strip().lower()
                    if phase == "inference":
                        self._monitor_phase(ticket.monitor_task_id, "ready")
                        phase = "ready"
                    self._monitor_metadata(ticket.monitor_task_id, {
                        "queue_priority": 0,
                        "queue_state": phase if phase in self.YIELD_PHASES else "ready",
                        "preemption_requested": False,
                    })
            self._assert_slot_invariant_locked()
            self._refresh_priorities_locked(endpoint_id)
            self._condition.notify_all()

    async def release(self, ticket: EndpointQueueTicket) -> None:
        """Compatibility alias for releasing one physical provider-request slot."""
        await self.finish_request(ticket)

    async def release_task(self, task_id: str | None) -> None:
        """Apply terminal/yield lifecycle state without stranding queued callers.

        Provider capacity is request-scoped. A nonterminal yielded Task (Pause,
        Reviewer wait, or sleep) remains queued but non-runnable so the coroutine can
        resume from the same acquire when the owner resumes. Terminal Tasks cancel
        their queued tickets. Any live provider request is marked for safe release
        when its current request unwinds.
        """
        rid = str(task_id or "").strip()
        if not rid:
            return
        state = self._monitor_state(rid)
        phase = str(self._monitor_metadata_snapshot(rid).get("phase") or "").lower()
        terminal = state in {"completed", "cancelled", "failed"}
        yielded = phase in self.YIELD_PHASES
        if self.monitor is not None and state and not terminal and not yielded:
            # Stale lifecycle callback after an immediate resume.
            return
        if not terminal and yielded:
            self._monitor_metadata(rid, {
                "phase_started_monotonic": None,
                "queue_priority": 0,
                "queue_state": phase,
                "preemption_requested": False,
            })
        async with self._condition:
            affected_endpoints: set[str] = set()
            if terminal:
                for endpoint_id, queued_map in self._queued.items():
                    for ticket_id, ticket in list(queued_map.items()):
                        if self._ticket_logical_key(ticket) != rid:
                            continue
                        ticket.cancelled = True
                        queued_map.pop(ticket_id, None)
                        affected_endpoints.add(endpoint_id)
            else:
                # Keep nonterminal yielded queue tickets alive. They are filtered
                # from runnable admission by _ticket_is_yielded and wake on resume.
                for endpoint_id, queued_map in self._queued.items():
                    if any(
                        self._ticket_logical_key(ticket) == rid and not ticket.cancelled
                        for ticket in queued_map.values()
                    ):
                        affected_endpoints.add(endpoint_id)
            for endpoint_id, active_map in self._active.items():
                for ticket_id, ticket in list(active_map.items()):
                    if self._ticket_logical_key(ticket) != rid:
                        continue
                    affected_endpoints.add(endpoint_id)
                    ticket.release_requested = True
                    if ticket_id not in self._request_active_ticket_ids:
                        active_map.pop(ticket_id, None)
                        ticket.granted = False
                        ticket.cancelled = True
            self._assert_slot_invariant_locked()
            for endpoint_id in affected_endpoints:
                self._refresh_priorities_locked(endpoint_id)
            self._condition.notify_all()

    async def _notify_priority_change(self) -> None:
        async with self._condition:
            for endpoint_id in set(self._queued) | set(self._active):
                self._refresh_priorities_locked(endpoint_id)
            self._condition.notify_all()

    def _schedule_priority_refresh(self) -> None:
        try:
            running = asyncio.get_running_loop()
        except RuntimeError:
            running = None
        loop = running or self._loop
        if loop is None or not loop.is_running() or self._closed:
            return

        def launch() -> None:
            if self._closed:
                return
            task = loop.create_task(self._notify_priority_change())
            task.add_done_callback(self._consume_background_task)

        if running is loop:
            launch()
        else:
            try:
                loop.call_soon_threadsafe(launch)
            except RuntimeError:
                pass

    def notify_task_state_changed(self) -> None:
        """Wake queued admission after a direct Chat/Agent pause or resume change."""
        self._schedule_priority_refresh()

    def prioritize_task(self, task_id: str | None) -> bool:
        monitor = self.monitor
        setter = getattr(monitor, "prioritize_task", None) if monitor is not None else None
        if not callable(setter) or not setter(task_id):
            return False
        self._schedule_priority_refresh()
        return True

    def deprioritize_task(self, task_id: str | None) -> bool:
        monitor = self.monitor
        setter = getattr(monitor, "deprioritize_task", None) if monitor is not None else None
        if not callable(setter) or not setter(task_id):
            return False
        self._schedule_priority_refresh()
        return True

    def snapshot(self) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for endpoint_id in set(self._queued) | set(self._active):
            active = sorted(
                (row for row in self._active.get(endpoint_id, {}).values() if not row.cancelled),
                key=lambda row: (row.sequence, row.ticket_id),
            )
            queued = [
                row for row in self._queued.get(endpoint_id, {}).values()
                if not row.cancelled
            ]
            paused = [row for row in queued if self._ticket_is_paused(row)]
            runnable = self._ordered_unique_runnable_locked(endpoint_id)
            active_ticket_ids = {row.ticket_id for row in active}
            request_active_ids = {
                row.ticket_id for row in active
                if row.ticket_id in self._request_active_ticket_ids
            }
            result[endpoint_id] = {
                "capacity": self._capacity(endpoint_id),
                "slots_consumed": len(active_ticket_ids),
                "inference_requests": len(request_active_ids),
                "slot_invariant_ok": active_ticket_ids == request_active_ids,
                "active": [row.ticket_id for row in active],
                "active_task_ids": [row.monitor_task_id for row in active],
                "request_active": sorted(request_active_ids),
                "queued": [row.ticket_id for row in runnable],
                "paused": [row.ticket_id for row in paused],
                "task_ids": [row.monitor_task_id for row in active + runnable + paused],
            }
        return result

    async def close(self) -> None:
        auto_record_ids: list[str] = []
        async with self._condition:
            self._closed = True
            for rows in (*self._queued.values(), *self._active.values()):
                for ticket in rows.values():
                    ticket.cancelled = True
                    ticket.granted = False
                    ticket.request_active = False
                    ticket.release_requested = True
                    if not self._monitor_is_terminal(ticket.monitor_task_id):
                        self._monitor_metadata(ticket.monitor_task_id, {
                            "queue_priority": 0,
                            "queue_state": "ready",
                            "preemption_requested": False,
                        })
                    if ticket.auto_monitor_task and ticket.monitor_task_id:
                        auto_record_ids.append(str(ticket.monitor_task_id))
            self._queued.clear()
            self._active.clear()
            self._request_active_ticket_ids.clear()
            self._assert_slot_invariant_locked()
            self._condition.notify_all()
        monitor = self.monitor
        self.bind_monitor(None)
        if monitor is not None:
            for task_id in auto_record_ids:
                monitor.cancel(task_id)

def estimate_native_tool_schema_tokens(native_tools: Any) -> int:
    """Conservatively estimate provider framing plus native function schemas."""
    if not isinstance(native_tools, list) or not native_tools:
        return 0
    try:
        raw = json.dumps(native_tools, ensure_ascii=False, separators=(",", ":"), default=str)
    except Exception:
        raw = str(native_tools)
    return max(16, _estimated_text_tokens(raw) + 8 * len(native_tools))


def _request_usage_token_values(value: Any) -> tuple[int | None, int | None]:
    """Return provider token counters while preserving the absent/zero distinction."""
    sources = llm_usage_sources(value if isinstance(value, dict) else {})
    input_tokens = first_usage_value(sources, LLM_PROMPT_TOKEN_KEYS)
    output_tokens = first_usage_value(sources, LLM_COMPLETION_TOKEN_KEYS)
    return (
        max(0, int(input_tokens)) if input_tokens is not None else None,
        max(0, int(output_tokens)) if output_tokens is not None else None,
    )


def estimate_llm_request_input_tokens(request: LLMRequest) -> int:
    """Estimate complete request input for live Dashboard accounting fallback."""
    if request.prepared_capacity:
        return max(0, int(request.prepared_capacity.get("complete_tokens", 0)))
    return max(0, int(
        estimate_request_messages_tokens(request.messages)
        + estimate_native_tool_schema_tokens(request.native_tools)
    ))


def estimate_llm_output_structure_tokens(value: Any) -> int:
    """Estimate current function-call/output-item snapshots without double counting deltas."""
    if not value:
        return 0
    try:
        raw = json.dumps(value, ensure_ascii=False, separators=(",", ":"), default=str)
    except Exception:
        raw = str(value)
    return max(0, _estimated_text_tokens(raw))


def _provider_usage_seconds(value: Any, names: Iterable[str]) -> float | None:
    sources = llm_usage_sources(value if isinstance(value, dict) else {})
    for source in sources:
        for name in names:
            raw = source.get(name)
            if raw is None:
                continue
            try:
                number = float(raw)
            except Exception:
                continue
            if not math.isfinite(number) or number < 0:
                continue
            lname = str(name).lower()
            if lname.endswith("_ms") or "milliseconds" in lname:
                return number / 1000.0
            # llama.cpp exposes several *_duration counters in nanoseconds.
            if "duration" in lname and number > 10_000:
                return number / 1_000_000_000.0
            return number
    return None


LLM_STREAM_BRIDGE_FLUSH_SECONDS = 0.016


class LLMStreamChunkBridge:
    """Coalesce worker-thread provider deltas before waking the UI event loop.

    urllib reads happen on a worker thread, but scheduling one asyncio callback
    for every token can still flood the shared render loop. The first delta arms
    one short loop timer; subsequent deltas append to small rope lists under the
    bridge lock. This avoids quadratic pending-string concatenation and long GIL
    holds on very fast local inference servers. The loop swaps the pending batch
    in O(1), joins each rope once, preserves exact text order and terminal
    metadata, and yields an explicit sentinel only after the final aggregate.
    """

    def __init__(
        self,
        loop: asyncio.AbstractEventLoop,
        *,
        flush_seconds: float = LLM_STREAM_BRIDGE_FLUSH_SECONDS,
    ) -> None:
        self.loop = loop
        self.flush_seconds = max(0.0, float(flush_seconds))
        self.queue: asyncio.Queue[LLMChunk | None] = asyncio.Queue()
        self._lock = threading.RLock()
        self._pending_text_parts: list[str] = []
        self._pending_reasoning_parts: list[str] = []
        self._pending_usage: dict[str, Any] = {}
        self._pending_reasoning_fields: dict[str, Any] | None = None
        self._pending_provider_diagnostics: dict[str, Any] | None = None
        self._pending_meaningful_progress: bool | None = None
        self._pending_model_output_observed = False
        self._pending_progress_monotonic: float | None = None
        # Worker-side output arrival times are bridge metadata, not provider
        # usage. Keep them outside the public usage mapping so callers see the
        # provider's exact token payload while the scheduler can still measure
        # generation time across a coalesced stream.
        self._pending_first_delta_monotonic: float | None = None
        self._pending_last_delta_monotonic: float | None = None
        self._pending_terminal_monotonic: float | None = None
        self._pending_done = False
        self._pending_error = ""
        self._pending_endpoint_failure: dict[str, Any] | None = None
        self._pending_finish_reason = ""
        self._pending_stop_reason = ""
        self._pending_native_tool_calls: list[dict[str, Any]] = []
        self._pending_response_output_items: list[dict[str, Any]] = []
        self._pending_prompt_progress_percent: float | None = None
        self._pending_prompt_tokens_processed: int | None = None
        self._pending_prompt_tokens_total: int | None = None
        self._pending_present = False
        self._armed = False
        self._closed = False
        self._sentinel_sent = False
        self.cross_thread_wakeups = 0
        self.delivered_batches = 0

    def _append_pending_locked(self, chunk: LLMChunk) -> None:
        text = str(chunk.text or "")
        reasoning = str(chunk.reasoning_text or "")
        has_model_output = bool(chunk.model_output_observed or (
            chunk.meaningful_progress is None
            and (text or reasoning or chunk.native_tool_calls or chunk.response_output_items)
        ))
        if chunk.reasoning_fields is not None:
            self._pending_reasoning_fields = copy.deepcopy(chunk.reasoning_fields)
        if chunk.provider_diagnostics is not None:
            self._pending_provider_diagnostics = copy.deepcopy(chunk.provider_diagnostics)
        if chunk.meaningful_progress is not None:
            self._pending_meaningful_progress = bool(self._pending_meaningful_progress or chunk.meaningful_progress)
        self._pending_model_output_observed |= chunk.model_output_observed
        if chunk.progress_monotonic is not None:
            self._pending_progress_monotonic = max(self._pending_progress_monotonic or 0.0, chunk.progress_monotonic)
        if text:
            self._pending_text_parts.append(text)
        if reasoning:
            self._pending_reasoning_parts.append(reasoning)
        if chunk.usage:
            self._pending_usage = update_llm_usage_snapshot(self._pending_usage, chunk.usage)
        if has_model_output:
            # The bridge may coalesce an entire fast local response into one event-
            # loop chunk. Preserve worker-side first/last output arrival times as
            # private chunk metadata, never as provider usage fields.
            now_mono = time.monotonic()
            if self._pending_first_delta_monotonic is None:
                self._pending_first_delta_monotonic = now_mono
            self._pending_last_delta_monotonic = now_mono
        if chunk.done:
            # End generation at the provider's terminal event, not after later tool
            # work, queueing, UI publication, or consumer-side bookkeeping.
            self._pending_terminal_monotonic = time.monotonic()
        self._pending_done = bool(self._pending_done or chunk.done)
        if chunk.error:
            self._pending_error = str(chunk.error)
        if chunk.endpoint_failure is not None:
            self._pending_endpoint_failure = copy.deepcopy(chunk.endpoint_failure)
        if chunk.finish_reason:
            self._pending_finish_reason = str(chunk.finish_reason)
        if chunk.stop_reason:
            self._pending_stop_reason = str(chunk.stop_reason)
        if chunk.native_tool_calls:
            self._pending_native_tool_calls = copy.deepcopy(chunk.native_tool_calls)
        if chunk.response_output_items:
            self._pending_response_output_items = copy.deepcopy(chunk.response_output_items)
        if chunk.prompt_progress_percent is not None:
            try:
                progress = min(100.0, max(0.0, float(chunk.prompt_progress_percent)))
            except Exception:
                progress = None
            if progress is not None:
                self._pending_prompt_progress_percent = max(
                    float(self._pending_prompt_progress_percent or 0.0), progress,
                )
        if chunk.prompt_tokens_processed is not None:
            try:
                processed = max(0, int(chunk.prompt_tokens_processed))
            except Exception:
                processed = None
            if processed is not None:
                self._pending_prompt_tokens_processed = max(
                    int(self._pending_prompt_tokens_processed or 0), processed,
                )
        if chunk.prompt_tokens_total is not None:
            try:
                total = max(0, int(chunk.prompt_tokens_total))
            except Exception:
                total = None
            if total is not None:
                self._pending_prompt_tokens_total = max(
                    int(self._pending_prompt_tokens_total or 0), total,
                )
        self._pending_present = True

    def _take_pending_locked(self) -> tuple[Any, ...] | None:
        if not self._pending_present:
            return None
        batch = (
            self._pending_text_parts,
            self._pending_reasoning_parts,
            self._pending_usage,
            self._pending_first_delta_monotonic,
            self._pending_last_delta_monotonic,
            self._pending_terminal_monotonic,
            self._pending_done,
            self._pending_error,
            self._pending_endpoint_failure,
            self._pending_finish_reason,
            self._pending_stop_reason,
            self._pending_native_tool_calls,
            self._pending_response_output_items,
            self._pending_prompt_progress_percent,
            self._pending_prompt_tokens_processed,
            self._pending_prompt_tokens_total,
            self._pending_reasoning_fields,
            self._pending_provider_diagnostics,
            self._pending_meaningful_progress,
            self._pending_model_output_observed,
            self._pending_progress_monotonic,
        )
        self._pending_text_parts = []
        self._pending_reasoning_parts = []
        self._pending_usage = {}
        self._pending_reasoning_fields = None
        self._pending_provider_diagnostics = None
        self._pending_meaningful_progress = None
        self._pending_model_output_observed = False
        self._pending_progress_monotonic = None
        self._pending_first_delta_monotonic = None
        self._pending_last_delta_monotonic = None
        self._pending_terminal_monotonic = None
        self._pending_done = False
        self._pending_error = ""
        self._pending_endpoint_failure = None
        self._pending_finish_reason = ""
        self._pending_stop_reason = ""
        self._pending_native_tool_calls = []
        self._pending_response_output_items = []
        self._pending_prompt_progress_percent = None
        self._pending_prompt_tokens_processed = None
        self._pending_prompt_tokens_total = None
        self._pending_present = False
        return batch

    @staticmethod
    def _materialize_batch(batch: tuple[Any, ...]) -> LLMChunk:
        (
            text_parts,
            reasoning_parts,
            usage,
            first_delta_monotonic,
            last_delta_monotonic,
            terminal_monotonic,
            done,
            error,
            endpoint_failure,
            finish_reason,
            stop_reason,
            native_tool_calls,
            response_output_items,
            prompt_progress_percent,
            prompt_tokens_processed,
            prompt_tokens_total,
            reasoning_fields,
            provider_diagnostics,
            meaningful_progress,
            model_output_observed,
            progress_monotonic,
        ) = batch
        chunk = LLMChunk(
            text="".join(text_parts),
            reasoning_text="".join(reasoning_parts),
            reasoning_fields=reasoning_fields,
            provider_diagnostics=provider_diagnostics,
            meaningful_progress=meaningful_progress,
            model_output_observed=model_output_observed,
            progress_monotonic=progress_monotonic,
            usage=dict(usage) or None,
            done=bool(done),
            error=str(error) or None,
            endpoint_failure=endpoint_failure,
            finish_reason=str(finish_reason) or None,
            stop_reason=str(stop_reason) or None,
            native_tool_calls=copy.deepcopy(native_tool_calls) or None,
            response_output_items=copy.deepcopy(response_output_items) or None,
            prompt_progress_percent=(
                float(prompt_progress_percent) if prompt_progress_percent is not None else None
            ),
            prompt_tokens_processed=(
                int(prompt_tokens_processed) if prompt_tokens_processed is not None else None
            ),
            prompt_tokens_total=(
                int(prompt_tokens_total) if prompt_tokens_total is not None else None
            ),
        )
        # LLMChunk deliberately remains provider-shaped. Dynamic private fields
        # carry bridge timing to the queued wrapper without polluting usage.
        chunk._velox_stream_first_delta_monotonic = first_delta_monotonic
        chunk._velox_stream_last_delta_monotonic = last_delta_monotonic
        chunk._velox_stream_terminal_monotonic = terminal_monotonic
        return chunk

    def publish(self, chunk: LLMChunk) -> None:
        with self._lock:
            if self._closed:
                return
            self._append_pending_locked(chunk)
            if self._armed:
                return
            self._armed = True
            self.cross_thread_wakeups += 1
        try:
            self.loop.call_soon_threadsafe(self._arm_on_loop)
        except RuntimeError:
            with self._lock:
                self._closed = True
                self._armed = False

    def close(self) -> None:
        with self._lock:
            self._closed = True
            if self._armed:
                return
            self._armed = True
            self.cross_thread_wakeups += 1
        try:
            self.loop.call_soon_threadsafe(self._arm_on_loop)
        except RuntimeError:
            with self._lock:
                self._armed = False

    def _arm_on_loop(self) -> None:
        try:
            self.loop.call_later(self.flush_seconds, self._flush_on_loop)
        except RuntimeError:
            self._flush_on_loop()

    def _flush_on_loop(self) -> None:
        with self._lock:
            batch = self._take_pending_locked()
            closed = self._closed
            self._armed = False
        if batch is not None:
            self.queue.put_nowait(self._materialize_batch(batch))
            self.delivered_batches += 1

        schedule_again = False
        send_sentinel = False
        with self._lock:
            pending_again = self._pending_present
            if pending_again and not self._armed:
                self._armed = True
                schedule_again = True
            elif closed and not self._sentinel_sent:
                self._sentinel_sent = True
                send_sentinel = True
        if schedule_again:
            try:
                self.loop.call_later(self.flush_seconds, self._flush_on_loop)
            except RuntimeError:
                with self._lock:
                    self._armed = False
        elif send_sentinel:
            self.queue.put_nowait(None)


LLM_PROMPT_TOKEN_KEYS = TOKEN_INPUT_ALIASES
LLM_COMPLETION_TOKEN_KEYS = TOKEN_OUTPUT_ALIASES
LLM_USAGE_ACCUMULATE_KEYS = frozenset({
    *LLM_PROMPT_TOKEN_KEYS,
    *LLM_COMPLETION_TOKEN_KEYS,
    "total_tokens",
    "prompt_seconds", "prompt_time", "prompt_ms", "prompt_eval_duration",
    "prompt_processing_time", "generation_seconds", "generation_time",
    "completion_time", "eval_duration", "total_duration",
})
LLM_TRUNCATION_REASONS = frozenset({
    "length", "max_tokens", "max_output_tokens", "max_new_tokens",
    "token_limit", "context_length", "model_length", "output_limit",
    "incomplete",
})
LLM_TOOL_REASONS = frozenset({"tool_call", "tool_calls", "function_call", "function_calls"})
LLM_SAFETY_REASONS = frozenset({
    "content_filter", "safety", "blocked", "guardrail", "policy", "moderation",
})


def first_usage_value(sources: Iterable[dict[str, Any]], keys: Iterable[str]) -> int | None:
    """Return the first valid non-negative token count across alias fields."""
    for source in sources:
        if not isinstance(source, dict):
            continue
        for key in keys:
            parsed = _nonnegative_token_value(source.get(key))
            if parsed is not None:
                return parsed
    return None


def llm_usage_sources(response: dict[str, Any] | None) -> list[dict[str, Any]]:
    """Return unique provider usage containers in precedence order."""
    payload = response if isinstance(response, dict) else {}
    raw = payload.get("raw") if isinstance(payload.get("raw"), dict) else {}
    sources: list[dict[str, Any]] = []
    for candidate in (payload.get("usage"), raw.get("usage"), raw.get("timings"), raw, payload):
        if not isinstance(candidate, dict):
            continue
        if any(candidate is existing for existing in sources):
            continue
        sources.append(candidate)
    return sources


# Cached input is a subset of total input, never an additional token charge.
CACHE_USAGE_FIELDS = (
    "cached_input_tokens", "cache_reported_input_tokens",
    "cache_reported_rounds", "cache_total_rounds",
)


def _cache_token_value(value: Any) -> int | None:
    """Accept whole non-negative provider counts, not booleans or estimates."""
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, int):
        return value if value >= 0 else None
    if isinstance(value, float):
        return int(value) if math.isfinite(value) and value >= 0 and value.is_integer() else None
    if isinstance(value, str) and re.fullmatch(r"[0-9]+", value):
        try:
            return int(value)
        except ValueError:
            return None
    return None


def cached_input_tokens_from_usage(value: dict[str, Any] | None) -> int | None:
    """Read explicit cache *hits* from Chat Completions, Responses or DeepSeek.

    None means unreported/unusable, whereas zero is a reported zero. Cache writes,
    output tokens, timings and prompt-prefix similarity are not cache-hit evidence.
    Aliases are alternative representations of one count and are never added.
    """
    sources = llm_usage_sources(value)
    total = first_usage_value(sources, LLM_PROMPT_TOKEN_KEYS)
    for source in sources:
        candidates = []
        for field in ("prompt_tokens_details", "input_tokens_details"):
            detail = source.get(field)
            if isinstance(detail, dict):
                candidates.append(detail.get("cached_tokens"))
        candidates.append(source.get("prompt_cache_hit_tokens"))
        for candidate in candidates:
            count = _cache_token_value(candidate)
            if count is not None and (total is None or count <= total):
                return count
    return None


def llm_cache_usage_summary(value: dict[str, Any] | None) -> dict[str, int]:
    """Project one request, a merged turn, or durable counters without inventing hits."""
    for source in llm_usage_sources(value):
        summary = source.get("_velox_cache_summary")
        if not isinstance(summary, dict) and "cache_total_rounds" in source:
            summary = source
        if isinstance(summary, dict):
            result = {field: _cache_token_value(summary.get(field)) or 0 for field in CACHE_USAGE_FIELDS}
            result["cache_total_rounds"] = max(result["cache_total_rounds"], int(source.get("_model_rounds") or 0))
            return result
    total = first_usage_value(llm_usage_sources(value), LLM_PROMPT_TOKEN_KEYS) or 0
    cached = cached_input_tokens_from_usage(value)
    # A partial snapshot may report hits before the total. Keep the raw value in
    # the stream, but do not display a percentage until a coherent total arrives.
    reported = cached is not None and cached <= total
    return {
        "cached_input_tokens": int(cached) if reported else 0,
        "cache_reported_input_tokens": total if reported else 0,
        "cache_reported_rounds": int(reported),
        "cache_total_rounds": 1,
    }


def add_cache_usage_counters(previous: dict[str, Any], value: dict[str, Any]) -> dict[str, int]:
    """Add a completed request once; callers own request/turn identity."""
    current = llm_cache_usage_summary(value)
    return {field: (_cache_token_value(previous.get(field)) or 0) + current[field]
            for field in CACHE_USAGE_FIELDS}


def cached_input_label(metrics: dict[str, Any], *, include_percent: bool = True) -> str:
    """Compact cache subset; coverage and uncertainty belong in the tooltip."""
    reported = max(0, int(metrics.get("cache_reported_rounds") or 0))
    if not reported:
        return "N/A"
    total = max(0, int(metrics.get("input_tokens") or 0))
    cached = max(0, int(metrics.get("cached_input_tokens") or 0))
    if cached > total:
        return "N/A"  # Do not invent a ratio for an incoherent partial snapshot.
    text = f"{cached:,}"
    if include_percent:
        ratio = cached * 100.0 / total if total else 0.0
        text += f" [{ratio:.1f}%]"
    return text


def cached_input_tooltip(metrics: dict[str, Any]) -> str:
    total = max(0, int(metrics.get("input_tokens") or 0))
    label = cached_input_label(metrics)
    lines = [f"Input: {total:,} total tokens (includes cached input)",
             "Cached Input: " + label]
    reported = max(0, int(metrics.get("cache_reported_rounds") or 0))
    rounds = max(reported, int(metrics.get("cache_total_rounds") or 0))
    if label != "N/A":
        coverage = f"Cache reporting: {reported:,}/{rounds:,} requests"
        if reported < rounds:
            coverage += "; reported subset, percentage is a lower bound."
        lines.append(coverage)
    else:
        lines.append("Cache reporting: no usable provider cache-hit count; not a reported zero.")
        if rounds and metrics.get("endpoint_provider") == ENDPOINT_PROVIDER_VLLM:
            lines.append("vLLM server: --enable-prompt-tokens-details (restart required).")
            lines.append("Already enabled? Check the server's cache-reporting support; /metrics is not per-Task.")
    return "\n".join(lines)


LLM_PROMPT_PROGRESS_PERCENT_KEYS = (
    "prompt_progress_percent", "prefill_progress_percent",
    "prompt_processing_progress_percent", "prompt_percent", "prefill_percent",
    "prompt_progress", "prefill_progress", "prompt_processing_progress",
)
LLM_PROMPT_PROGRESS_PROCESSED_KEYS = (
    "prompt_tokens_processed", "prefill_tokens_processed",
    "processed_prompt_tokens", "processed_prefill_tokens",
    "num_prompt_tokens_processed", "num_prefill_tokens_processed",
)
LLM_PROMPT_PROGRESS_TOTAL_KEYS = (
    "prompt_tokens_total", "prefill_tokens_total",
    "total_prompt_tokens", "total_prefill_tokens",
    "num_prompt_tokens_total", "num_prefill_tokens_total",
)


def llm_prompt_progress_snapshot(value: Any) -> tuple[float | None, int | None, int | None]:
    """Extract optional live input progress from provider payloads.

    OpenAI-compatible streaming does not standardize prefill progress. Velox
    therefore recognizes conservative, explicit aliases only. A normal terminal
    ``usage.prompt_tokens`` value is deliberately not interpreted as progress.
    Direct progress values in [0, 1] are treated as fractions unless the key
    explicitly says ``percent``; processed/total token counters are preferred
    whenever both are present.
    """
    sources: list[dict[str, Any]] = []
    seen: set[int] = set()

    def add(candidate: Any, depth: int = 0) -> None:
        if not isinstance(candidate, dict) or depth > 3 or id(candidate) in seen:
            return
        seen.add(id(candidate))
        sources.append(candidate)
        for name in ("usage", "metrics", "timings", "progress", "data", "response"):
            nested = candidate.get(name)
            if isinstance(nested, dict):
                add(nested, depth + 1)

    add(value)

    def finite_number(raw: Any) -> float | None:
        if isinstance(raw, bool) or raw is None:
            return None
        try:
            number = float(raw)
        except Exception:
            return None
        return number if math.isfinite(number) and number >= 0.0 else None

    processed: int | None = None
    total: int | None = None
    for source in sources:
        if processed is None:
            for key in LLM_PROMPT_PROGRESS_PROCESSED_KEYS:
                number = finite_number(source.get(key))
                if number is not None:
                    processed = max(0, int(number))
                    break
        if total is None:
            for key in LLM_PROMPT_PROGRESS_TOTAL_KEYS:
                number = finite_number(source.get(key))
                if number is not None:
                    total = max(0, int(number))
                    break
        if processed is not None and total is not None:
            break

    if processed is not None and total is not None and total > 0:
        return min(100.0, max(0.0, processed * 100.0 / total)), processed, total

    for source in sources:
        for key in LLM_PROMPT_PROGRESS_PERCENT_KEYS:
            number = finite_number(source.get(key))
            if number is None:
                continue
            if "percent" not in key and number <= 1.0:
                number *= 100.0
            return min(100.0, max(0.0, number)), processed, total
    return None, processed, total


def merge_llm_usage(total: dict[str, Any], current: dict[str, Any] | None) -> dict[str, Any]:
    """Merge one completed request's usage into a multi-request turn total.

    Streaming providers may repeat one usage object in several chunks, so callers
    first collapse a single request with ``update_llm_usage_snapshot`` and invoke this exactly
    once per request. Token and timing counters are summed; metadata is replaced
    by the newest value.
    """
    has_previous_request = bool(total and (
        "_velox_cache_summary" in total or any(key in total for key in (*LLM_PROMPT_TOKEN_KEYS, *LLM_COMPLETION_TOKEN_KEYS))
    ))
    previous_summary = llm_cache_usage_summary(total) if has_previous_request else dict.fromkeys(CACHE_USAGE_FIELDS, 0)
    current_summary = llm_cache_usage_summary(current) if current else dict.fromkeys(CACHE_USAGE_FIELDS, 0)
    previous_tokens = _request_usage_token_values(total)
    current_tokens = _request_usage_token_values(current)
    merged = dict(total or {})
    for key, value in (current or {}).items():
        if key in LLM_USAGE_ACCUMULATE_KEYS and not isinstance(value, bool):
            try:
                number = float(value)
            except Exception:
                merged[key] = copy.deepcopy(value)
                continue
            if not math.isfinite(number):
                continue
            previous = merged.get(key, 0)
            try:
                previous_number = float(previous)
            except Exception:
                previous_number = 0.0
            result = previous_number + number
            if isinstance(value, int) and not isinstance(value, bool) and float(result).is_integer():
                merged[key] = int(result)
            else:
                merged[key] = result
        elif isinstance(value, dict) and isinstance(merged.get(key), dict):
            nested = dict(merged[key])
            for nested_key, nested_value in value.items():
                if isinstance(nested_value, (int, float)) and not isinstance(nested_value, bool):
                    try:
                        nested[nested_key] = nested.get(nested_key, 0) + nested_value
                    except Exception:
                        nested[nested_key] = copy.deepcopy(nested_value)
                else:
                    nested[nested_key] = copy.deepcopy(nested_value)
            merged[key] = nested
        else:
            merged[key] = copy.deepcopy(value)
    if total or current:
        merged["_velox_cache_summary"] = {
            field: previous_summary[field] + current_summary[field] for field in CACHE_USAGE_FIELDS
        }
    # Normalize mixed provider aliases at the multi-request boundary, not in replay.
    for index, field in enumerate(("prompt_tokens", "completion_tokens")):
        if previous_tokens[index] is not None or current_tokens[index] is not None:
            merged[field] = int(previous_tokens[index] or 0) + int(current_tokens[index] or 0)
    return merged


def update_llm_usage_snapshot(total: dict[str, Any], current: dict[str, Any] | None) -> dict[str, Any]:
    """Replace cumulative counters within one request, retaining omitted details."""
    merged = dict(total or {})
    for key, value in (current or {}).items():
        if value is None:
            if key in {"prompt_tokens_details", "input_tokens_details"} and key not in merged:
                merged[key] = None
            continue
        if key in {"cached_tokens", "prompt_cache_hit_tokens", "prompt_cache_miss_tokens"} and _cache_token_value(value) is None:
            continue
        if isinstance(value, dict):
            previous = merged.get(key) if isinstance(merged.get(key), dict) else {}
            merged[key] = update_llm_usage_snapshot(previous, value)
        else:
            merged[key] = copy.deepcopy(value)
    return merged


def normalize_llm_termination_reason(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, (dict, list)):
        try:
            value = json.dumps(value, ensure_ascii=False, sort_keys=True)
        except Exception:
            value = str(value)
    return re.sub(r"[^a-z0-9]+", "_", str(value).strip().lower()).strip("_")


def llm_termination_category(finish_reason: Any, stop_reason: Any = None) -> str:
    values = {
        normalize_llm_termination_reason(finish_reason),
        normalize_llm_termination_reason(stop_reason),
    } - {""}
    if values & LLM_SAFETY_REASONS:
        return "safety"
    if values & LLM_TRUNCATION_REASONS:
        return "truncated"
    if values & LLM_TOOL_REASONS:
        return "tool"
    return "normal"


def llm_response_termination(raw: Any) -> tuple[str, str]:
    """Extract provider termination metadata from an OpenAI-compatible response."""
    if not isinstance(raw, dict):
        return "", ""
    choice: dict[str, Any] = {}
    choices = raw.get("choices")
    if isinstance(choices, list) and choices and isinstance(choices[0], dict):
        choice = choices[0]

    def first_present(*values: Any) -> Any:
        # Empty compatibility fields must not mask a meaningful fallback on the
        # top-level response. Several gateways emit finish_reason="" in choice
        # zero while preserving the real reason at the response level.
        for value in values:
            if value is None:
                continue
            if isinstance(value, str) and not value.strip():
                continue
            return value
        return None

    finish = first_present(
        choice.get("finish_reason"), choice.get("finishReason"),
        raw.get("finish_reason"), raw.get("finishReason"),
    )
    stop = first_present(
        choice.get("stop_reason"), choice.get("stopReason"),
        raw.get("stop_reason"), raw.get("stopReason"),
    )
    return normalize_llm_termination_reason(finish), normalize_llm_termination_reason(stop)


def usable_assistant_text(text: Any) -> str:
    """Return user-visible prose after removing reasoning and tool envelopes."""
    visible = strip_reasoning_content(str(text or ""))
    visible = strip_tool_markup_from_text(visible)
    return visible.strip()


def unusable_assistant_completion_diagnostic(text: Any) -> dict[str, Any]:
    """Describe why a provider completion has no user-visible assistant answer."""
    raw = str(text or "")
    visible = usable_assistant_text(raw)
    reasoning_parts = re.findall(
        r"(?is)<(?:think|thinking|reasoning)>(.*?)(?:</(?:think|thinking|reasoning)>|$)",
        raw,
    )
    reasoning_text = "\n".join(part.strip() for part in reasoning_parts if part.strip())
    protocol_detected = "[[VELOX_TOOL_ROW:" in raw
    if not raw.strip():
        category = "empty"
        explanation = "the provider returned no assistant text"
    elif reasoning_text and not visible:
        category = "reasoning_only"
        explanation = (
            f"the provider returned {len(reasoning_text):,} reasoning character(s) "
            "but no user-visible answer"
        )
    elif protocol_detected and not visible:
        category = "control_only"
        explanation = "the provider returned only tool/control markup and no user-visible answer"
    else:
        category = "non_visible"
        explanation = "the provider returned content that contained no user-visible assistant answer"
    return {
        "category": category,
        "explanation": explanation,
        "raw_chars": len(raw),
        "reasoning_chars": len(reasoning_text),
        "visible_chars": len(visible),
        "protocol_detected": protocol_detected,
    }


def is_chat_expert_mode_prompt_turn(turn: Any) -> bool:
    """Return whether Velox injected an Checklist continuation prompt."""
    if not isinstance(turn, dict) or str(turn.get("role") or "").lower() != "user":
        return False
    stats = turn.get("stats") if isinstance(turn.get("stats"), dict) else {}
    return bool(stats.get("expert_mode_prompt"))


def is_chat_application_injected_prompt_turn(turn: Any) -> bool:
    return (
        is_chat_expert_mode_prompt_turn(turn)
    )


def llm_snapshot_suffix(emitted: str, snapshot: Any) -> str:
    """Return only new text from a provider's cumulative message snapshot.

    Some OpenAI-compatible streaming servers emit normal ``delta`` chunks and
    then append a final ``message`` object containing the entire response.  Treat
    that object as a snapshot, not another delta, or the answer/reasoning appears
    twice and can make the UI look as though it rewrote itself.  Already-streamed
    deltas remain authoritative when a conflicting snapshot arrives.
    """
    prior = str(emitted or "")
    current = str(snapshot or "")
    if not current:
        return ""
    if not prior:
        return current
    if current.startswith(prior):
        return current[len(prior):]
    if prior.startswith(current):
        return ""
    return ""


class AppendOnlyTextAccumulator:
    """Accumulate provider deltas without quadratic immutable-string copying.

    Normal streaming providers emit many tiny deltas.  Keeping those fragments in
    a list makes append O(1); a contiguous string is built only when a cumulative
    provider snapshot must be compared or a caller explicitly asks for it.
    Conflicting/shorter snapshots never replace already emitted deltas.
    """

    __slots__ = ("_base", "_parts", "_pending_chars", "materialization_count")

    def __init__(self) -> None:
        self._base = ""
        self._parts: list[str] = []
        self._pending_chars = 0
        self.materialization_count = 0

    @property
    def total_chars(self) -> int:
        return len(self._base) + self._pending_chars

    def append_delta(self, value: Any) -> str:
        piece = str(value or "")
        if piece:
            self._parts.append(piece)
            self._pending_chars += len(piece)
        return piece

    def materialize(self) -> str:
        if self._parts:
            self._base = "".join((self._base, *self._parts))
            self._parts.clear()
            self._pending_chars = 0
            self.materialization_count += 1
        return self._base

    def accept_snapshot(self, value: Any) -> str:
        current = str(value or "")
        if not current:
            return ""
        prior = self.materialize()
        suffix = llm_snapshot_suffix(prior, current)
        if not prior or current.startswith(prior):
            # Reuse the provider-owned complete string instead of concatenating
            # the suffix back onto the prior immutable value.
            self._base = current
        return suffix


class LLMRequestCancelledError(RuntimeError):
    """Identify an endpoint request stopped by a chat or tool cancellation."""


class LLMRequestTimeoutError(TimeoutError):
    """Identify an endpoint request timeout without confusing it with an agent budget timeout."""

    def __init__(self, endpoint_profile_id: str, timeout_seconds: int, detail: str = "timed out"):
        self.endpoint_profile_id = str(endpoint_profile_id or "endpoint")
        self.timeout_seconds = max(1, int(timeout_seconds or 1))
        self.detail = str(detail or "timed out")
        super().__init__(
            f"Endpoint profile {self.endpoint_profile_id!r} timed out after {self.timeout_seconds} seconds: {self.detail}"
        )



def llm_reported_reasoning_tokens(usage: Any) -> int | None:
    """A token count is accounting, not proof that reasoning text was returned."""
    if not isinstance(usage, dict):
        return None
    for key in ("completion_tokens_details", "output_tokens_details", "token_details", "usage_details"):
        value = usage.get(key)
        if isinstance(value, dict):
            for field in ("reasoning_tokens", "thinking_tokens"):
                parsed = _nonnegative_token_value(value.get(field))
                if parsed is not None:
                    return parsed
    return _nonnegative_token_value(usage.get("reasoning_tokens"))


def llm_reasoning_timing_unobservable(usage: dict[str, Any], reasoning_chars: int) -> bool:
    reported = llm_reported_reasoning_tokens(usage)
    if not reported or reasoning_chars > 0:
        return False
    explicit = _provider_usage_seconds({"usage": usage}, (
        "generation_seconds", "generation_time", "decode_seconds", "completion_time", "eval_time",
        "eval_duration", "generation_ms", "decode_ms",
    ))
    return explicit is None or explicit <= 0


def llm_measured_phase_seconds(usage: dict[str, Any], reasoning_chars: int,
                               prefill_seconds: float, generation_seconds: float) -> tuple[float, float]:
    if llm_reasoning_timing_unobservable(usage, reasoning_chars):
        return 0.0, 0.0
    provider_generation = _provider_usage_seconds({"usage": usage}, (
        "generation_seconds", "generation_time", "decode_seconds", "completion_time",
        "eval_time", "eval_duration", "generation_ms", "decode_ms",
    ))
    provider_prefill = _provider_usage_seconds({"usage": usage}, (
        "prompt_seconds", "prefill_seconds", "prompt_time", "prompt_ms",
        "prompt_eval_duration", "prompt_processing_time",
    ))
    if provider_generation is not None:
        generation_seconds = provider_generation
        if reasoning_chars == 0 and llm_reported_reasoning_tokens(usage):
            # The first received tool/answer delta was after the hidden thinking.
            # Without a provider prefill timer, that entire delay is not prefill.
            prefill_seconds = 0.0
    if provider_prefill is not None:
        prefill_seconds = provider_prefill
    return prefill_seconds, generation_seconds


class StreamingReasoningPresence:
    """Recognize real inline thought text across split tags with a bounded tail.

    Presence suffices for timing observability. Once established, later chunks
    are O(1); before that we retain only a partial control tag, never the stream.
    """
    TAGS = tuple(f"<{slash}{name}>" for name in ("think", "thinking", "reasoning") for slash in ("", "/"))
    PATTERN = re.compile(r"<(/?)(?:think|thinking|reasoning)>", re.I)

    def __init__(self) -> None:
        self.tail = ""
        self.inside = False
        self.seen = False

    def feed(self, text: str) -> bool:
        if self.seen:
            return True
        value = self.tail + text
        self.tail = ""
        offset = 0
        for match in self.PATTERN.finditer(value):
            if self.inside and value[offset:match.start()].strip():
                self.seen = True
                return True
            self.inside = match.group(1) != "/"
            offset = match.end()
        rest = value[offset:]
        keep = next((count for count in range(min(len(rest), 12), 0, -1)
                     if any(tag.startswith(rest[-count:].lower()) for tag in self.TAGS)), 0)
        safe = rest[:-keep] if keep else rest
        self.tail = rest[-keep:] if keep else ""
        if self.inside and safe.strip():
            self.seen = True
        return self.seen


class StructuredReasoningAccumulator:
    """Preserve Novita/OpenAI-compatible reasoning packets without inventing text.

    Streaming packets are deltas; message packets are cumulative snapshots. Stable
    index/id joins fragments, while text ropes avoid quadratic copying in very long
    thinking streams. Opaque/signature data is replay-only, never rendered as prose.
    """
    TEXT_FIELDS = {"reasoning.text": "text", "reasoning.summary": "summary"}

    def __init__(self) -> None:
        self.rows: dict[int, dict[str, Any]] = {}
        self.values: dict[tuple[int, str], AppendOnlyTextAccumulator] = {}
        self.ids: dict[str, int] = {}

    def accept(self, packets: Any, *, snapshot: bool = False) -> tuple[str, bool]:
        if packets is None:
            return "", False
        if not isinstance(packets, list) or any(not isinstance(row, dict) for row in packets):
            raise ValueError("Provider reasoning_details must be an array of objects")
        pieces: list[str] = []
        opaque_progress = False
        seen: set[int] = set()
        for position, packet in enumerate(packets):
            raw_index = packet.get("index")
            if raw_index is not None and (type(raw_index) is not int or raw_index < 0):
                raise ValueError("Provider reasoning_details index must be a nonnegative integer")
            identity = str(packet.get("id") or "")
            index = raw_index if raw_index is not None else self.ids.get(identity, position)
            if (raw_index is None and identity and identity not in self.ids
                    and self.rows.get(index, {}).get("id") not in (None, "", identity)):
                index = max(self.rows, default=-1) + 1
            if index in seen:
                raise ValueError("Duplicate provider reasoning_details index")
            seen.add(index)
            if identity and identity in self.ids and self.ids[identity] != index:
                raise ValueError("Conflicting provider reasoning_details identity")
            row = self.rows.setdefault(index, {})
            if identity and row.get("id") and row["id"] != identity:
                raise ValueError("Conflicting provider reasoning_details identity")
            if identity:
                self.ids[identity] = index
            if packet.get("type") and row.get("type") and row["type"] != packet["type"]:
                raise ValueError("Conflicting provider reasoning_details type")
            # Metadata is not text. Repeated IDs/signatures never count as progress.
            for key, value in packet.items():
                if key not in {"text", "summary", "data"}:
                    row[key] = copy.deepcopy(value)
            visible_field = self.TEXT_FIELDS.get(str(row.get("type") or ""))
            for key in ("text", "summary", "data"):
                if key not in packet:
                    continue
                value = packet[key]
                if not isinstance(value, str):
                    # Unknown future packet payloads survive replay, but must not
                    # be mistaken for user-visible thoughts or activity evidence.
                    row[key] = copy.deepcopy(value)
                    continue
                acc = self.values.setdefault((index, key), AppendOnlyTextAccumulator())
                if snapshot:
                    prior = acc.materialize()
                    if prior and value and not (value.startswith(prior) or prior.startswith(value)):
                        raise ValueError("Conflicting provider reasoning_details snapshot")
                    piece = acc.accept_snapshot(value)
                else:
                    piece = acc.append_delta(value)
                if key == visible_field:
                    pieces.append(piece)
                elif key == "data" and piece:
                    opaque_progress = True
        return "".join(pieces), opaque_progress

    def snapshot(self) -> list[dict[str, Any]]:
        result: list[dict[str, Any]] = []
        for index, source in sorted(self.rows.items()):
            row = copy.deepcopy(source)
            for key in ("text", "summary", "data"):
                acc = self.values.get((index, key))
                if acc is not None:
                    row[key] = acc.materialize()
            result.append(row)
        return result


def provider_reasoning_fields(message: Any) -> dict[str, Any]:
    """Canonical scalar alias plus exact structured packets for assistant replay."""
    if not isinstance(message, dict):
        return {}
    result: dict[str, Any] = {}
    for key in ("reasoning_content", "reasoning", "thoughts"):
        text = provider_visible_text(message.get(key))
        if text:
            result["reasoning_content"] = text
            break
    if message.get("reasoning_details") is not None:
        details = StructuredReasoningAccumulator()
        details.accept(message["reasoning_details"], snapshot=True)
        # A complete provider array is already ordered; validation must not
        # reorder signed/opaque packets or normalize away extension metadata.
        result["reasoning_details"] = copy.deepcopy(message["reasoning_details"])
    return result


def provider_reasoning_text(message: Any) -> str:
    fields = provider_reasoning_fields(message)
    if fields.get("reasoning_content"):
        return str(fields["reasoning_content"])
    details = StructuredReasoningAccumulator()
    text, _opaque = details.accept(fields.get("reasoning_details"), snapshot=True)
    return text


def apply_assistant_reasoning_fields(message: dict[str, Any], fields: Any) -> dict[str, Any]:
    """Keep original provider fields instead of deriving a second copy from UI text."""
    if isinstance(fields, dict) and fields:
        message.pop("reasoning_content", None)
        for key in ("reasoning_content", "reasoning_details"):
            if key in fields:
                message[key] = copy.deepcopy(fields[key])
    return message


class LLMRequestDeadline:
    """No-meaningful-progress watchdog, not a limit on healthy generation duration.

    Only the network/parser worker advances this clock. UI backlog, comments,
    role-only frames, unchanged counters and repeated snapshots cannot extend it.
    Wall elapsed time counts suspend on hosts whose monotonic clock stops. A late
    delta cannot revive an already expired attempt. Completed responses are frozen
    before queueing so a delayed consumer cannot time out work already completed.
    """
    def __init__(self, endpoint_profile_id: str, seconds: float):
        self.endpoint_profile_id = endpoint_profile_id
        self.seconds = max(0.001, float(seconds))
        self.started_monotonic = time.monotonic()
        self.started_wall = time.time()
        self._lock = threading.RLock()
        self._last_monotonic = self.started_monotonic
        self._last_wall = self.started_wall
        self._expired = False
        self._finished = False
        self.model_output_observed = False
        self._progress_counters: dict[str, float] = {}
        self._call_sizes: dict[str, tuple[int, int]] = {}
        self._opaque_sizes: dict[str, int] = {}

    def _remaining_locked(self) -> float:
        if self._expired:
            return 0.0
        if self._finished:
            return math.inf
        remaining = self.seconds - max(0.0, time.monotonic() - self._last_monotonic,
                                       time.time() - self._last_wall)
        if remaining <= 0:
            self._expired = True
        return remaining

    def remaining(self) -> float:
        with self._lock:
            return self._remaining_locked()

    def _counter_advanced(self, key: str, value: Any) -> bool:
        if isinstance(value, bool) or value is None:
            return False
        try:
            parsed = float(value)
        except (ValueError, TypeError, OverflowError):
            return False
        if not math.isfinite(parsed) or parsed <= self._progress_counters.get(key, 0.0):
            return False
        self._progress_counters[key] = parsed
        return True

    def observe(self, chunk: LLMChunk) -> bool:
        """Called before bridge publication. Return False for expired/late output."""
        with self._lock:
            if self._remaining_locked() <= 0 or self._finished:
                return False
            output = bool(chunk.model_output_observed)
            progress = bool(chunk.meaningful_progress)
            if chunk.meaningful_progress is not False and (chunk.text or chunk.reasoning_text):
                progress = output = True
            for call in chunk.native_tool_calls or []:
                fn = call.get("function") if isinstance(call.get("function"), dict) else {}
                key = str(call.get("id") or call.get("index") or "")
                lengths = (len(str(fn.get("name") or "")), len(str(fn.get("arguments") or "")))
                old = self._call_sizes.get(key, (0, 0))
                if any(new > prior for new, prior in zip(lengths, old)):
                    progress = output = True
                self._call_sizes[key] = tuple(max(new, prior) for new, prior in zip(lengths, old))
            for index, item in enumerate(chunk.response_output_items or []):
                if not isinstance(item, dict) or item.get("type") != "reasoning":
                    continue
                key = str(item.get("id") or index)
                size = len(str(item.get("encrypted_content") or ""))
                if size > self._opaque_sizes.get(key, 0):
                    self._opaque_sizes[key] = size
                    progress = output = True
            usage = chunk.usage if isinstance(chunk.usage, dict) else {}
            completed = first_usage_value([usage], LLM_COMPLETION_TOKEN_KEYS)
            if self._counter_advanced("output_tokens", completed):
                progress = output = True
            if self._counter_advanced("reasoning_tokens", llm_reported_reasoning_tokens(usage)):
                progress = output = True
            progress |= self._counter_advanced("prompt_percent", chunk.prompt_progress_percent)
            progress |= self._counter_advanced("prompt_processed", chunk.prompt_tokens_processed)
            chunk.meaningful_progress = bool(progress)
            chunk.model_output_observed = bool(output)
            self.model_output_observed |= output
            if progress:
                self._last_monotonic, self._last_wall = time.monotonic(), time.time()
                chunk.progress_monotonic = self._last_monotonic
            if chunk.done:
                self._finished = True
            return True

    def finish(self) -> bool:
        with self._lock:
            if self._remaining_locked() <= 0:
                return False
            self._finished = True
            return True

    def error(self) -> LLMRequestTimeoutError:
        error = LLMRequestTimeoutError(
            self.endpoint_profile_id, int(math.ceil(self.seconds)),
            "no-progress deadline exceeded: no meaningful provider progress within the configured inactivity timeout",
        )
        error.partial_output = self.model_output_observed
        return error

    async def next_chunk(self, queue: asyncio.Queue, cancelled: Callable[[], bool]) -> Any:
        while True:
            if cancelled():
                raise LLMRequestCancelledError("Endpoint request cancelled")
            remaining = self.remaining()
            if remaining <= 0:
                raise self.error()
            try:
                chunk = await asyncio.wait_for(queue.get(), min(remaining, 0.1))
            except asyncio.TimeoutError:
                continue
            if cancelled():
                raise LLMRequestCancelledError("Endpoint request cancelled")
            if self.remaining() <= 0:
                raise self.error()
            return chunk


def endpoint_timeout_operation_budget(profile: dict[str, Any]) -> None:
    """No total LLM-operation cap: each attempt has its own no-progress watchdog."""
    return None


def llm_inference_activity_snapshot(metadata: dict[str, Any], now_mono: float) -> tuple[str, float, float]:
    """One interpretation of the live provider phase for Chat and Dashboard."""
    activity = str(metadata.get("activity") or "prompt").strip().lower()
    if activity not in {"prompt", "thinking", "answer", "error"}:
        # A tool/sleep stage is not a valid provider stage once admission says
        # inference. Both views must normalize it, rather than disagree on stalls.
        activity = "prompt"
    def elapsed(*keys: str) -> float:
        for key in keys:
            try:
                raw = metadata.get(key)
                if raw is not None and math.isfinite(float(raw)):
                    return max(0.0, now_mono - float(raw))
            except (TypeError, ValueError):
                pass
        return 0.0
    return (activity, elapsed("activity_started_monotonic", "phase_started_monotonic"),
            elapsed("activity_last_progress_monotonic", "activity_started_monotonic", "phase_started_monotonic"))


def provider_visible_text(value: Any) -> str:
    """Extract user-visible text/refusal content without stringifying metadata.

    OpenAI-compatible gateways use strings, typed content arrays, or small
    dictionaries for message content. Refusals are user-visible assistant output
    too; dropping them turns a valid policy response into an apparent empty
    provider completion.
    """
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        return "".join(provider_visible_text(item) for item in value)
    if isinstance(value, dict):
        for key in ("text", "refusal", "content"):
            if key in value:
                text = provider_visible_text(value.get(key))
                if text:
                    return text
        return ""
    return str(value)


def _provider_arguments_equivalent(left: Any, right: Any) -> bool:
    """Return whether two complete provider argument payloads are equivalent."""
    a = str(left or "")
    b = str(right or "")
    if a == b:
        return True
    if not a or not b:
        return False
    try:
        return json.loads(a) == json.loads(b)
    except Exception:
        return False


def canonicalize_provider_tool_calls(calls: Iterable[dict[str, Any]]) -> list[dict[str, Any]]:
    """Collapse duplicate provider call IDs and reject conflicting identities.

    A provider call ID is one execution identity. Compatibility layers sometimes
    surface the same call in multiple carriers. Exact/JSON-equivalent duplicates
    and cumulative argument snapshots are merged; incompatible names, types, or
    arguments are protocol corruption and are never silently chosen or executed.
    Calls without provider IDs remain distinct.
    """
    out: list[dict[str, Any]] = []
    by_id: dict[str, int] = {}
    for ordinal, raw_call in enumerate(calls, 1):
        if not isinstance(raw_call, dict):
            continue
        function = raw_call.get("function") if isinstance(raw_call.get("function"), dict) else {}
        name = str(function.get("name") or "").strip()
        arguments = function.get("arguments", "")
        if not isinstance(arguments, str):
            arguments = json.dumps(arguments or {}, ensure_ascii=False, separators=(",", ":"))
        provider_id = str(raw_call.get("id") or "").strip()
        call_type = str(raw_call.get("type") or "function").strip() or "function"
        call = {
            "id": provider_id or f"call_{ordinal}_{uuid_v4()}",
            "type": call_type,
            "function": {"name": name, "arguments": arguments},
        }
        if not provider_id:
            out.append(call)
            continue
        existing_index = by_id.get(provider_id)
        if existing_index is None:
            by_id[provider_id] = len(out)
            out.append(call)
            continue
        existing = out[existing_index]
        existing_function = existing.get("function") if isinstance(existing.get("function"), dict) else {}
        old_name = str(existing_function.get("name") or "").strip()
        old_arguments = str(existing_function.get("arguments") or "")
        old_type = str(existing.get("type") or "function").strip() or "function"
        if old_name and name and old_name != name:
            raise ValueError(f"Conflicting function names for provider tool call id {provider_id!r}")
        if old_type and call_type and old_type != call_type:
            raise ValueError(f"Conflicting tool types for provider tool call id {provider_id!r}")
        if old_arguments and arguments:
            if arguments.startswith(old_arguments) and len(arguments) > len(old_arguments):
                existing_function["arguments"] = arguments
            elif old_arguments.startswith(arguments):
                pass
            elif not _provider_arguments_equivalent(old_arguments, arguments):
                raise ValueError(f"Conflicting function arguments for provider tool call id {provider_id!r}")
        elif arguments:
            existing_function["arguments"] = arguments
        if not old_name and name:
            existing_function["name"] = name
        existing["function"] = existing_function
    return out


def normalize_known_provider_artifacts_in_response_item(item: dict[str, Any]) -> dict[str, Any]:
    """Strip known text-only provider wrappers from replayable Responses items."""
    normalized = copy.deepcopy(item)
    if str(normalized.get("type") or "") == "message":
        content = normalized.get("content")
        if isinstance(content, list):
            for part in content:
                if not isinstance(part, dict):
                    continue
                if str(part.get("type") or "") == "output_text" and isinstance(part.get("text"), str):
                    part["text"] = normalize_known_provider_output_artifacts(part.get("text"))
                elif str(part.get("type") or "") == "refusal" and isinstance(part.get("refusal"), str):
                    part["refusal"] = normalize_known_provider_output_artifacts(part.get("refusal"))
    return normalized


def canonicalize_responses_output_items(items: Iterable[dict[str, Any]]) -> list[dict[str, Any]]:
    """Collapse duplicate Responses function-call identities without reordering other items."""
    out: list[dict[str, Any]] = []
    by_call_id: dict[str, int] = {}
    for raw_item in items:
        if not isinstance(raw_item, dict):
            continue
        item = normalize_known_provider_artifacts_in_response_item(raw_item)
        if str(item.get("type") or "") != "function_call":
            out.append(item)
            continue
        call_id = str(item.get("call_id") or item.get("id") or "").strip()
        if not call_id:
            out.append(item)
            continue
        existing_index = by_call_id.get(call_id)
        if existing_index is None:
            by_call_id[call_id] = len(out)
            out.append(item)
            continue
        existing = out[existing_index]
        old_name = str(existing.get("name") or "").strip()
        new_name = str(item.get("name") or "").strip()
        old_args = existing.get("arguments", "")
        new_args = item.get("arguments", "")
        old_call = {
            "id": call_id, "type": "function",
            "function": {"name": old_name, "arguments": old_args},
        }
        new_call = {
            "id": call_id, "type": "function",
            "function": {"name": new_name, "arguments": new_args},
        }
        merged = canonicalize_provider_tool_calls([old_call, new_call])[0]
        fn = merged["function"]
        if fn.get("name"):
            existing["name"] = fn["name"]
        if fn.get("arguments") is not None:
            existing["arguments"] = fn["arguments"]
        # Prefer metadata from the later cumulative carrier without replacing the
        # stable execution identity or changing its original output ordering.
        for key, value in item.items():
            if key not in {"call_id", "id", "name", "arguments"} and value not in (None, "", [], {}):
                existing[key] = copy.deepcopy(value)
    return out


def iter_openai_compatible_stream_frames(
    response: Any,
    *,
    response_max_bytes: int,
    cancelled: Callable[[], bool] | None = None,
) -> Iterable[tuple[str, bytes]]:
    """Frame OpenAI-compatible SSE or raw JSON without dropping bytes/events.

    SSE events may legally contain multiple ``data:`` lines; those lines belong
    to one event and are joined with a newline at the blank-line boundary. The
    configured byte cap applies to the complete wire body, not just an individual
    line. Non-SSE bodies are returned once as raw bytes. Mixing raw JSON and SSE
    in one HTTP response is rejected instead of guessing which representation is
    authoritative.
    """
    limit = max(1, int(response_max_bytes))
    total = 0
    raw = bytearray()
    sse_data: list[bytes] = []
    saw_sse = False
    saw_raw = False

    def is_cancelled() -> bool:
        return bool(cancelled and cancelled())

    def flush_sse() -> tuple[str, bytes] | None:
        nonlocal sse_data
        if not sse_data:
            return None
        payload = b"\n".join(sse_data)
        sse_data = []
        if payload.strip() == b"[DONE]":
            return ("done", b"")
        return ("sse", payload)

    while True:
        if is_cancelled():
            raise LLMRequestCancelledError("Endpoint request cancelled while streaming")
        line = response.readline(limit + 1)
        if is_cancelled():
            raise LLMRequestCancelledError("Endpoint request cancelled while streaming")
        if not line:
            break
        total += len(line)
        if total > limit:
            raise ValueError(f"LLM response exceeded the configured {limit}-byte limit")
        bare = line.rstrip(b"\r\n")
        if bare == b"":
            event = flush_sse()
            if event is not None:
                if saw_raw:
                    raise ValueError("OpenAI-compatible stream mixed raw JSON and SSE framing")
                yield event
                if event[0] == "done":
                    return
            continue
        if bare.startswith(b":"):
            saw_sse = True
            continue
        field, sep, value = bare.partition(b":")
        field_lower = field.lower()
        if sep and field_lower in {b"data", b"event", b"id", b"retry"}:
            saw_sse = True
            if saw_raw:
                raise ValueError("OpenAI-compatible stream mixed raw JSON and SSE framing")
            if field_lower == b"data":
                if value.startswith(b" "):
                    value = value[1:]
                sse_data.append(value)
            continue
        if saw_sse:
            # Unknown SSE fields are valid extension fields; ignore the field as
            # the SSE spec requires, but never reinterpret it as raw JSON.
            continue
        saw_raw = True
        raw.extend(line)
    event = flush_sse()
    if event is not None:
        if saw_raw:
            raise ValueError("OpenAI-compatible stream mixed raw JSON and SSE framing")
        yield event
        if event[0] == "done":
            return
    if raw:
        yield ("raw", bytes(raw))


def parse_openai_raw_json_payloads(raw_bytes: bytes) -> list[Any]:
    """Parse strict UTF-8 JSON or NDJSON; never repair bytes or skip bad records."""
    text = raw_bytes.decode("utf-8")
    try:
        return [json.loads(text)]
    except Exception as whole_exc:
        rows: list[Any] = []
        nonblank = [line.strip() for line in text.splitlines() if line.strip()]
        if len(nonblank) <= 1:
            raise ValueError("HTTP response was not valid JSON") from whole_exc
        for line_number, line in enumerate(nonblank, 1):
            try:
                rows.append(json.loads(line))
            except Exception as exc:
                raise ValueError(f"NDJSON record {line_number} was not valid JSON") from exc
        return rows


class LLMEndpointError(RuntimeError):
    """A redacted, user-visible OpenAI-compatible endpoint failure."""

    def __init__(
        self,
        message: str,
        *,
        endpoint_profile_id: str = "",
        url: str = "",
        status_code: int | None = None,
        reason: str = "",
        response_body: str = "",
        response_headers: Any = None,
    ):
        self.endpoint_profile_id = str(endpoint_profile_id or "")
        self.url = str(url or "")
        self.status_code = int(status_code) if status_code is not None else None
        self.reason = str(reason or "")
        self.response_body = str(response_body or "")
        try:
            self.response_headers = dict(response_headers.items()) if response_headers is not None else {}
        except Exception:
            try:
                self.response_headers = dict(response_headers or {})
            except Exception:
                self.response_headers = {}
        super().__init__(str(message or "LLM endpoint request failed"))


def endpoint_rate_limit_enabled(profile: dict[str, Any] | None) -> bool:
    row = profile if isinstance(profile, dict) else {}
    value = row.get("rate_limit_enabled")
    if isinstance(value, bool):
        return value
    return endpoint_default_rate_limit_enabled(endpoint_provider(row))


def endpoint_rate_limit_requests_per_minute(profile: dict[str, Any] | None) -> int:
    row = profile if isinstance(profile, dict) else {}
    try:
        value = int(row.get(
            "rate_limit_requests_per_minute",
            ENDPOINT_RATE_LIMIT_REQUESTS_PER_MINUTE_DEFAULT,
        ))
    except Exception:
        value = ENDPOINT_RATE_LIMIT_REQUESTS_PER_MINUTE_DEFAULT
    return int(clamp(value, 1, ENDPOINT_RATE_LIMIT_REQUESTS_PER_MINUTE_MAX))


def endpoint_error_recovery_enabled(profile: dict[str, Any] | None) -> bool:
    row = profile if isinstance(profile, dict) else {}
    return row.get("error_recovery_enabled", True) is True


def endpoint_error_recovery_attempts(profile: dict[str, Any] | None) -> int:
    row = profile if isinstance(profile, dict) else {}
    try:
        value = int(row.get(
            "error_recovery_attempts", ENDPOINT_ERROR_RECOVERY_ATTEMPTS_DEFAULT,
        ))
    except Exception:
        value = ENDPOINT_ERROR_RECOVERY_ATTEMPTS_DEFAULT
    return int(clamp(value, 0, ENDPOINT_ERROR_RECOVERY_ATTEMPTS_MAX))


def endpoint_error_recovery_delay_seconds(profile: dict[str, Any] | None) -> int:
    row = profile if isinstance(profile, dict) else {}
    try:
        value = float(row.get(
            "error_recovery_delay_seconds",
            ENDPOINT_ERROR_RECOVERY_DELAY_SECONDS_DEFAULT,
        ))
    except Exception:
        value = float(ENDPOINT_ERROR_RECOVERY_DELAY_SECONDS_DEFAULT)
    if not math.isfinite(value):
        value = float(ENDPOINT_ERROR_RECOVERY_DELAY_SECONDS_DEFAULT)
    return int(round(clamp(
        value, 0.0, float(ENDPOINT_ERROR_RECOVERY_DELAY_SECONDS_MAX),
    )))


def _retry_after_seconds_from_headers(headers: Any) -> float | None:
    if headers is None:
        return None
    value: Any = None
    try:
        value = next((v for k, v in headers.items() if str(k).lower() == "retry-after"), None)
    except Exception:
        return None
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        seconds = float(raw)
        if math.isfinite(seconds) and seconds >= 0.0:
            return seconds
    except Exception:
        pass
    try:
        parsed = parsedate_to_datetime(raw)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return max(0.0, parsed.timestamp() - time.time())
    except Exception:
        return None


ENDPOINT_TRANSIENT_FAILURE_REASONS = frozenset({
    "network_error", "connection_error", "connection_reset", "connection_closed",
    "timeout", "timeout_error", "request_timeout", "read_timeout", "gateway_timeout",
    "rate_limit", "rate_limit_error", "rate_limit_exceeded", "too_many_requests",
    "overloaded", "overloaded_error", "server_overload", "server_overloaded",
    "server_error", "internal_error", "internal_server_error", "service_unavailable",
    "temporarily_unavailable", "insufficient_system_resource", "engine_overloaded",
    "upstream_error", "upstream_timeout", "bad_gateway",
})
ENDPOINT_TERMINAL_FAILURE_REASONS = frozenset({
    "error", "failed", "cancelled", "canceled", "aborted",
}) | ENDPOINT_TRANSIENT_FAILURE_REASONS


def llm_endpoint_termination_error(finish_reason: Any, stop_reason: Any = None) -> LLMEndpointError | None:
    """HTTP 200 is not success when a provider reports a failed generation."""
    reasons = [normalize_llm_termination_reason(finish_reason), normalize_llm_termination_reason(stop_reason)]
    # Safety and cancellation dominate an inconsistent transient reason.
    if any(reason in LLM_SAFETY_REASONS for reason in reasons):
        return None
    code = next((r for r in reasons if r in {"cancelled", "canceled", "aborted"}), "")
    code = code or next((r for r in reasons if r in ENDPOINT_TRANSIENT_FAILURE_REASONS), "")
    code = code or next((r for r in reasons if r in ENDPOINT_TERMINAL_FAILURE_REASONS), "")
    if not code:
        return None
    message = f"Provider generation failed (finish_reason={reasons[0] or 'unspecified'}"
    if reasons[1]:
        message += f", stop_reason={reasons[1]}"
    message += ")."
    return LLMEndpointError(message, status_code=200, reason=code,
                            response_body=json.dumps({"error": {"code": code, "message": message}}))


def llm_response_has_model_output(value: Any) -> bool:
    """Conservative replay guard for complete/error payloads, not request bodies."""
    if not isinstance(value, dict):
        return False
    if any(value.get(key) for key in ("text", "reasoning_text", "reasoning_fields", "tool_calls", "response_output_items")):
        return True
    if value.get("output"):
        return True
    for choice in value.get("choices", []) if isinstance(value.get("choices"), list) else []:
        if not isinstance(choice, dict):
            continue
        if choice.get("text"):
            return True
        for key in ("message", "delta"):
            message = choice.get(key)
            if isinstance(message, dict) and any(message.get(field) for field in (
                "content", "refusal", "reasoning", "reasoning_content", "reasoning_details", "thoughts",
                "tool_calls", "function_call",
            )):
                return True
    return llm_response_has_model_output(value.get("response")) or llm_response_has_model_output(value.get("raw"))


def llm_error_has_partial_output(value: Any) -> bool:
    if bool(getattr(value, "partial_output", False)):
        return True
    if isinstance(value, LLMEndpointError):
        try:
            return llm_response_has_model_output(json.loads(value.response_body))
        except (ValueError, TypeError):
            pass
    return False


def llm_endpoint_error_recovery_details(value: Any) -> dict[str, Any] | None:
    """Classify actual transient failures, never advice or unrelated model text.

    This is independent of proactive request throttling. The caller owns one
    consecutive retry budget and the separate partial-output/cancellation guard.
    """
    if isinstance(value, (asyncio.CancelledError, GeneratorExit, LLMRequestCancelledError)):
        return None
    carried = getattr(value, "endpoint_failure", None)
    if isinstance(carried, dict):
        return dict(carried) if carried.get("retryable") else None
    if llm_context_overflow_details(value) is not None:
        return None
    status = value.status_code if isinstance(value, LLMEndpointError) else None
    headers = value.response_headers if isinstance(value, LLMEndpointError) else None
    diagnostic = str(value or "")
    body = value.response_body if isinstance(value, LLMEndpointError) else ""
    reason = value.reason if isinstance(value, LLMEndpointError) else ""
    # Full diagnostics also contain e.g. 'Timeout: 900' and suggestions to retry.
    # They are not failure signals. Match only the actual failure and response.
    failure_text = diagnostic.split("Suggested checks:", 1)[0]
    failure_line = re.search(r"(?m)^Failure:\s*([^\r\n]+)", failure_text)
    if failure_line:
        failure_text = failure_line.group(1)
    text = "\n".join(x for x in (reason, body, failure_text) if x)
    lower = text.lower()
    if status is None:
        match = re.search(r"\bHTTP\s+(\d{3})\b", failure_text, re.I)
        if match:
            status = int(match.group(1))
    # Quota/billing/configuration/certificate problems will not heal by replaying
    # unchanged requests, even when a gateway mislabels one as HTTP 429 or 500.
    fatal_terms = (
        "invalid api key", "invalid_api_key", "authentication", "unauthorized", "forbidden",
        "permission denied", "model_not_found", "model not found", "unsupported model",
        "invalid_request", "invalid request", "bad request", "insufficient_quota",
        "insufficient balance", "insufficient_balance", "insufficient credits", "payment required",
        "billing_hard_limit", "account suspended", "certificate_verify_failed", "certificate verify failed",
        "sslcertverificationerror", "llmrequestcancellederror",
    )
    if any(term in lower for term in fatal_terms):
        return None
    if status is not None and 400 <= status < 500 and status not in {408, 429}:
        return None
    if status in {None, 200} and any(term in str(reason).lower() for term in (
        "not valid", "not an object", "not an array", "invalid responses tool-call protocol",
        "invalid utf", "byte limit", "did not contain an output array",
    )):
        return None
    if isinstance(value, (ValueError, TypeError, UnicodeError)) and not isinstance(value, LLMEndpointError):
        return None
    nodes: list[BaseException] = []
    current = value
    for _ in range(6):
        if not isinstance(current, BaseException) or any(current is x for x in nodes):
            break
        nodes.append(current)
        nested = getattr(current, "reason", None)
        current = nested if isinstance(nested, BaseException) else getattr(current, "__cause__", None)
    if any(isinstance(x, (ssl.CertificateError, ssl.SSLCertVerificationError, LLMRequestCancelledError)) for x in nodes):
        return None
    code = ""
    message = ""
    try:
        parsed = json.loads(body or failure_text)
        parsed = parsed if isinstance(parsed, dict) else {}
        nested_response = parsed.get("response") if isinstance(parsed.get("response"), dict) else parsed
        if str(nested_response.get("status") or "").lower() in {"cancelled", "canceled"}:
            return None
        error = nested_response.get("error", nested_response)
        if isinstance(error, dict):
            code = normalize_llm_termination_reason(error.get("code") or error.get("type"))
            message = str(error.get("message") or "")
            if status in {None, 200}:
                error_status = error.get("status_code", error.get("status", error.get("code")))
                if str(error_status).isdigit() and 400 <= int(str(error_status)) <= 599:
                    status = int(str(error_status))
        elif isinstance(error, str):
            message = error
    except (ValueError, TypeError):
        pass
    if status is not None and 400 <= status < 500 and status not in {408, 429}:
        return None
    if code in {"cancelled", "canceled", "aborted", "content_filter", "safety"}:
        return None
    if status in {408, 504, 522, 524}:
        category = "timeout"
    elif status == 429:
        category = "rate_limit"
    elif status in {500, 502, 503, 520, 521, 523, 529}:
        category = "server"
    elif code in ENDPOINT_TRANSIENT_FAILURE_REASONS or normalize_llm_termination_reason(reason) in ENDPOINT_TRANSIENT_FAILURE_REASONS:
        category = "provider"
    elif any(isinstance(x, (TimeoutError, socket.timeout)) for x in nodes):
        category = "timeout"
    elif any(isinstance(x, (ConnectionError, socket.gaierror, http.client.IncompleteRead, ssl.SSLEOFError))
             or isinstance(x, OSError) and getattr(x, "errno", None) in {50, 51, 54, 57, 60, 61, 64, 65, 101, 104, 110, 111, 113, 10050, 10051, 10054, 10060, 10061, 10065}
             for x in nodes):
        category = "network"
    elif re.search(r"\b(?:LLMRequestTimeoutError|TimeoutError|timed out|timeout_error|request_timeout)\b", text, re.I):
        category = "timeout"
    elif re.search(r"\b(?:ConnectionRefusedError|ConnectionResetError|ConnectionAbortedError|BrokenPipeError|RemoteDisconnected|IncompleteRead|gaierror|network_error|connection_error|connection reset|connection refused|remote end closed|network is unreachable|host is unreachable)\b", text, re.I):
        category = "network"
    elif re.search(r"\b(?:too many requests|rate[ _-]limit(?:ed|_exceeded|_error)?|throttl\w*|overload(?:ed|_error)?|server_overload(?:ed)?|temporarily unavailable|service unavailable|bad gateway|gateway timeout|insufficient_system_resource|server_error|internal_server_error)\b", text, re.I):
        category = "server"
    else:
        return None
    summary = (f"HTTP {status}" if status is not None and status != 200
               else code or reason or next(iter(failure_text.splitlines()), "Transient endpoint error"))
    if not message:
        match = re.search(r'"message"\s*:\s*"([^"\r\n]+)"', text)
        message = match.group(1) if match else ""
    if message and message.lower() not in summary.lower():
        summary += f": {message}"
    return {
        "retryable": True, "category": category, "status_code": status,
        "summary": redact_endpoint_secrets(summary)[:500],
        "diagnostic": redact_endpoint_secrets(diagnostic)[:12000],
        "retry_after_seconds": _retry_after_seconds_from_headers(headers),
    }


def endpoint_failure_metadata(error: Any) -> dict[str, Any]:
    details = llm_endpoint_error_recovery_details(error)
    return details if details is not None else {"retryable": False}


def _monitor_begin_endpoint_cooldown(
    monitor: Any,
    task_id: str | None,
    *,
    seconds: float,
    reason: str,
    kind: str,
    attempt: int = 0,
    maximum: int = 0,
) -> None:
    if monitor is None or not task_id:
        return
    remaining = max(0.0, float(seconds or 0.0))
    until = time.monotonic() + remaining
    detail = str(reason or "Endpoint cooldown")[:2000]
    try:
        monitor.set_phase(task_id, "ready", persist=False)
    except Exception:
        pass
    try:
        monitor.set_activity(
            task_id, "cooldown", detail=detail, restart_timer=True, persist=False,
        )
    except Exception:
        pass
    try:
        monitor.update_metadata(task_id, {
            "cooldown_until_monotonic": until,
            "cooldown_reason": detail,
            "cooldown_kind": str(kind or "rate_limit"),
            "cooldown_attempt": max(0, int(attempt or 0)),
            "cooldown_maximum": max(0, int(maximum or 0)),
        }, persist=False)
    except Exception:
        pass


def _monitor_finish_endpoint_cooldown(
    monitor: Any,
    task_id: str | None,
    *,
    waited_seconds: float,
) -> None:
    if monitor is None or not task_id:
        return
    waited = max(0.0, float(waited_seconds or 0.0))
    try:
        metadata = monitor.record_metadata(task_id)
    except Exception:
        metadata = {}
    cumulative = max(0.0, float((metadata or {}).get("endpoint_wait_seconds") or 0.0)) + waited
    try:
        monitor.update_metadata(task_id, {
            "endpoint_wait_seconds": cumulative,
            "cooldown_until_monotonic": None,
            "cooldown_reason": "",
            "cooldown_kind": "",
            "cooldown_attempt": 0,
            "cooldown_maximum": 0,
        }, persist=False)
    except Exception:
        pass
    try:
        monitor.set_phase(task_id, "ready", persist=False)
    except Exception:
        pass
    try:
        monitor.set_activity(task_id, "inactive", persist=False)
    except Exception:
        pass


async def wait_for_endpoint_retry_cooldown(
    seconds: float,
    *,
    cancel_event: threading.Event | None = None,
    cancelled: Callable[[], bool] | None = None,
    monitor: Any = None,
    task_id: str | None = None,
    reason: str = "Endpoint Error Recovery",
    kind: str = "error_recovery",
    attempt: int = 0,
    maximum: int = 0,
) -> float:
    duration = max(0.0, float(seconds or 0.0))
    _monitor_begin_endpoint_cooldown(
        monitor, task_id, seconds=duration, reason=reason,
        kind=kind, attempt=attempt, maximum=maximum,
    )
    started = time.monotonic()
    deadline = started + duration
    try:
        while True:
            if cancel_event is not None and cancel_event.is_set():
                raise asyncio.CancelledError()
            if cancelled is not None and bool(cancelled()):
                raise asyncio.CancelledError()
            remaining = deadline - time.monotonic()
            if remaining <= 0.0:
                return max(0.0, time.monotonic() - started)
            await asyncio.sleep(min(0.25, remaining))
    finally:
        _monitor_finish_endpoint_cooldown(
            monitor, task_id, waited_seconds=max(0.0, time.monotonic() - started),
        )


class EndpointRequestRateLimiter:
    """Process-local, per-endpoint fixed-window request admission guard.

    Once an enabled endpoint reaches its configured request budget, the next
    request starts one shared 60-second cooldown. All Tasks targeting that
    endpoint observe the same boundary, remain cancellation-responsive, and
    resume before competing for an endpoint inference slot.
    """

    def __init__(self, *, window_seconds: float = ENDPOINT_RATE_LIMIT_WINDOW_SECONDS) -> None:
        self.window_seconds = max(0.001, float(window_seconds))
        self._lock = asyncio.Lock()
        self._timestamps: dict[str, collections.deque[float]] = {}
        self._cooldown_until: dict[str, float] = {}

    async def acquire(
        self,
        profile: dict[str, Any],
        *,
        cancel_event: threading.Event | None = None,
        monitor: Any = None,
        task_id: str | None = None,
    ) -> float:
        if not endpoint_rate_limit_enabled(profile):
            return 0.0
        endpoint_id = str(profile.get("profile_id") or profile.get("id") or "endpoint")
        limit = endpoint_rate_limit_requests_per_minute(profile)
        total_wait = 0.0
        while True:
            now = time.monotonic()
            async with self._lock:
                rows = self._timestamps.setdefault(endpoint_id, collections.deque())
                while rows and now - rows[0] >= self.window_seconds:
                    rows.popleft()
                cooldown_until = float(self._cooldown_until.get(endpoint_id) or 0.0)
                if cooldown_until > now:
                    wait_seconds = cooldown_until - now
                elif len(rows) >= limit:
                    cooldown_until = now + self.window_seconds
                    self._cooldown_until[endpoint_id] = cooldown_until
                    wait_seconds = self.window_seconds
                else:
                    rows.append(now)
                    self._cooldown_until.pop(endpoint_id, None)
                    return total_wait
            reason = (
                f"Endpoint request budget reached ({limit} requests/minute); "
                f"next request resumes after the {self.window_seconds:g}-second cooldown"
            )
            waited = await wait_for_endpoint_retry_cooldown(
                wait_seconds,
                cancel_event=cancel_event,
                monitor=monitor,
                task_id=task_id,
                reason=reason,
                kind="rate_limit",
            )
            total_wait += waited
            async with self._lock:
                if time.monotonic() >= float(self._cooldown_until.get(endpoint_id) or 0.0):
                    self._timestamps.setdefault(endpoint_id, collections.deque()).clear()
                    self._cooldown_until.pop(endpoint_id, None)


_CONTEXT_TOKEN_NUMBER = r"([0-9][0-9,]*)"


def _context_error_token_value(text: str, *patterns: str) -> int | None:
    for pattern in patterns:
        match = re.search(pattern, text, re.I | re.S)
        if not match:
            continue
        try:
            return max(0, int(match.group(1).replace(",", "")))
        except Exception:
            continue
    return None


def llm_context_overflow_details(value: Any) -> dict[str, Any] | None:
    """Recognize provider errors where prompt plus reserved output exceed context.

    Recovery is deliberately narrow: generic HTTP 400 responses, empty responses,
    and output truncation are not treated as context overflow. The returned token
    fields are diagnostic hints; detection still succeeds when a provider omits one.
    """
    if isinstance(value, LLMEndpointError):
        text = str(value.response_body or str(value))
        status_code = value.status_code
    else:
        text = str(value or "")
        status_match = re.search(r"Failure: HTTP (\d{3})", text)
        status_code = int(status_match.group(1)) if status_match else None
    if "Response body:" in text:
        text = text.split("Response body:", 1)[1].split("Suggested checks:", 1)[0].strip()
    if status_code is not None and status_code not in {200, 400, 413, 422}:
        return None
    lowered = text.lower()
    context_signal = (
        "maximum context length" in lowered
        or "maximum model length" in lowered
        or "context window" in lowered and "token" in lowered
    )
    arithmetic_signal = (
        ("input tokens" in lowered or "prompt contains" in lowered or "prompt tokens" in lowered)
        and ("output tokens" in lowered or "max_tokens" in lowered or "completion tokens" in lowered)
    )
    reduction_signal = (
        "reduce the length of the input" in lowered
        or "reduce the input" in lowered
        or "reduce the length of the prompt" in lowered
        or "input_tokens" in lowered
    )
    error_codes = {"context_length_exceeded", "context_window_exceeded", "max_context_length_exceeded"}
    try:
        parsed = json.loads(text)
        error_object = parsed.get("error", parsed) if isinstance(parsed, dict) else {}
        error_object = error_object if isinstance(error_object, dict) else {}
    except (ValueError, TypeError):
        error_object = {}
    explicit_context_error = any(error_object.get(key) in error_codes for key in ("code", "type")
                                 if isinstance(error_object.get(key), str))
    explicit_context_error |= bool(re.match(
        r"(?i)^\s*(?:LLMEndpointError:\s*)?(?:Velox local )?(?:context_length_exceeded|context_window_exceeded|max_context_length_exceeded)(?:[:\s]|$)", text))
    explicit_context_error |= any(signal in lowered for signal in (
        "the input is longer than the model's context length",
        "input exceeds the model's context", "prompt exceeds the model's context",
        "input token count exceeds", "input tokens exceed the maximum",
    ))
    explicit_context_error |= context_signal and any(signal in lowered for signal in (
        "messages resulted in", "but the input has", "context length exceeded",
    ))
    if not (explicit_context_error or (context_signal and arithmetic_signal and reduction_signal)):
        return None
    context_tokens = _context_error_token_value(
        text,
        rf"maximum context length is\s*{_CONTEXT_TOKEN_NUMBER}",
        rf"maximum model length is\s*{_CONTEXT_TOKEN_NUMBER}",
        rf"context window(?: is| of|:)\s*{_CONTEXT_TOKEN_NUMBER}",
    )
    output_tokens = _context_error_token_value(
        text,
        rf"requested\s*{_CONTEXT_TOKEN_NUMBER}\s*(?:output|completion) tokens",
        rf"max_tokens\s*[=:]\s*{_CONTEXT_TOKEN_NUMBER}",
        rf"max_completion_tokens\s*[=:]\s*{_CONTEXT_TOKEN_NUMBER}",
    )
    input_tokens = _context_error_token_value(
        text,
        rf"prompt contains(?: at least)?\s*{_CONTEXT_TOKEN_NUMBER}\s*input tokens",
        rf"{_CONTEXT_TOKEN_NUMBER}\s*input tokens",
        rf"messages resulted in\s*{_CONTEXT_TOKEN_NUMBER}\s*tokens",
        rf"but the input has\s*{_CONTEXT_TOKEN_NUMBER}\s*tokens",
        rf"input_tokens[^0-9]+{_CONTEXT_TOKEN_NUMBER}",
    )
    total_tokens = _context_error_token_value(
        text,
        rf"total of(?: at least)?\s*{_CONTEXT_TOKEN_NUMBER}\s*tokens",
        rf"total(?: requested)?[^0-9]+{_CONTEXT_TOKEN_NUMBER}\s*tokens",
    )
    if total_tokens is None and input_tokens is not None and output_tokens is not None:
        total_tokens = input_tokens + output_tokens
    return {
        "status_code": status_code,
        "context_window_tokens": context_tokens,
        "max_output_tokens": output_tokens,
        "input_tokens": input_tokens,
        "total_tokens": total_tokens,
        "message": text,
    }


PROVIDER_OVERFLOW_ESTIMATE_MARGIN_BASE = 1.03
PROVIDER_OVERFLOW_ESTIMATE_MARGIN_STEP = 0.04


def provider_overflow_recovery_capacity(
    endpoint: dict[str, Any] | None,
    overflow: dict[str, Any] | None,
    *,
    estimated_complete_tokens: int,
    message_count: int,
    native_tool_count: int,
    recovery_attempt: int = 1,
) -> dict[str, Any]:
    """Translate one provider-reported overflow into a stricter local target.

    Provider input counts include the model's real tokenizer, chat template, and
    tool framing. When they exceed Velox's estimate, the ratio is a measured lower
    bound because several vLLM errors say the prompt contains *at least* N tokens.
    Recovery therefore applies that ratio plus a progressively larger margin,
    compacts to the stricter target, and may retry several times. Configured
    context is still authoritative when it is lower than the provider's headline
    limit.
    """
    profile = endpoint if isinstance(endpoint, dict) else {}
    details = overflow if isinstance(overflow, dict) else {}
    configured_context = endpoint_context_window_tokens(profile)
    configured_output = endpoint_max_output_tokens(profile)
    try:
        reported_context = max(0, int(details.get("context_window_tokens") or 0))
    except Exception:
        reported_context = 0
    try:
        reported_output = max(0, int(details.get("max_output_tokens") or 0))
    except Exception:
        reported_output = 0
    try:
        reported_input = max(0, int(details.get("input_tokens") or 0))
    except Exception:
        reported_input = 0
    effective_context = min(
        configured_context, reported_context if reported_context > 0 else configured_context,
    )
    effective_output = max(configured_output, reported_output)
    effective_output = int(clamp(effective_output, 1, max(1, effective_context - 1)))
    recovery_endpoint = {
        "context_window_tokens": effective_context,
        "max_output_tokens": effective_output,
    }
    safety_tokens = endpoint_prompt_safety_tokens(
        recovery_endpoint,
        message_count=message_count,
        native_tool_count=native_tool_count,
    )
    provider_safe_prompt_tokens = max(
        1, effective_context - effective_output - safety_tokens,
    )
    local_complete = max(1, int(estimated_complete_tokens or 0))
    measured_ratio = (float(reported_input) / float(local_complete)) if reported_input else 1.0
    attempt = max(1, int(recovery_attempt or 1))
    estimate_margin = (
        PROVIDER_OVERFLOW_ESTIMATE_MARGIN_BASE
        + PROVIDER_OVERFLOW_ESTIMATE_MARGIN_STEP * (attempt - 1)
    )
    estimate_multiplier = max(endpoint_token_estimate_multiplier(profile), measured_ratio) * estimate_margin
    estimated_prompt_capacity_tokens = max(
        1, int(math.floor(provider_safe_prompt_tokens / estimate_multiplier)),
    )
    # A vague rejection supplies no authoritative capacity. Force real progress
    # relative to the failed input, not merely a smaller output reservation.
    if reported_input <= 0:
        estimated_prompt_capacity_tokens = min(
            estimated_prompt_capacity_tokens, max(1, int(local_complete * 0.75)),
        )
    return {
        "provider_context_window_tokens": reported_context,
        "provider_max_output_tokens": reported_output,
        "provider_reported_input_tokens": reported_input,
        "effective_context_window_tokens": effective_context,
        "effective_max_output_tokens": effective_output,
        "provider_safe_prompt_tokens": provider_safe_prompt_tokens,
        "local_estimated_complete_tokens": local_complete,
        "measured_estimate_ratio": measured_ratio,
        "recovery_attempt": attempt,
        "estimate_margin": estimate_margin,
        "estimate_multiplier": estimate_multiplier,
        "estimated_prompt_capacity_tokens": estimated_prompt_capacity_tokens,
    }


def provider_overflow_output_retry_budget(
    endpoint: dict[str, Any] | None,
    overflow: dict[str, Any] | None,
    *,
    current_output_tokens: int | None,
    message_count: int,
    native_tool_count: int,
    recovery_attempt: int = 1,
) -> dict[str, int] | None:
    """Return a smaller exact output budget when input itself must remain unchanged.

    Provider arithmetic errors report the real prompt-token count and the output
    allowance that was rejected. When no older history can be compacted—most
    importantly for an initial user message—Velox preserves every input byte and
    retries with only the output allowance reduced. The returned budget always
    makes strict progress and keeps a small progressively larger edge reserve.
    """
    profile = endpoint if isinstance(endpoint, dict) else {}
    details = overflow if isinstance(overflow, dict) else {}
    try:
        reported_input = max(0, int(details.get("input_tokens") or 0))
    except Exception:
        reported_input = 0
    if reported_input <= 0:
        return None
    configured_context = endpoint_context_window_tokens(profile)
    try:
        reported_context = max(0, int(details.get("context_window_tokens") or 0))
    except Exception:
        reported_context = 0
    effective_context = min(
        configured_context,
        reported_context if reported_context > 0 else configured_context,
    )
    try:
        reported_output = max(0, int(details.get("max_output_tokens") or 0))
    except Exception:
        reported_output = 0
    prior_output = max(
        1,
        int(
            current_output_tokens
            if current_output_tokens is not None
            else reported_output or endpoint_max_output_tokens(profile)
        ),
    )
    attempt = max(1, int(recovery_attempt or 1))
    edge_endpoint = {
        "context_window_tokens": effective_context,
        "max_output_tokens": 1,
    }
    reserve = endpoint_prompt_safety_tokens(
        edge_endpoint,
        message_count=message_count,
        native_tool_count=native_tool_count,
    )
    reserve = int(clamp(
        reserve + (attempt - 1) * 256,
        CONTEXT_FIT_SAFETY_TOKENS_MIN,
        CONTEXT_FIT_SAFETY_TOKENS_MAX,
    ))
    available_output = effective_context - reported_input - reserve
    next_output = min(prior_output - 1, available_output)
    if next_output < 1:
        return None
    return {
        "recovery_attempt": attempt,
        "effective_context_window_tokens": effective_context,
        "provider_reported_input_tokens": reported_input,
        "previous_output_tokens": prior_output,
        "retry_output_tokens": int(next_output),
        "output_retry_reserve_tokens": reserve,
    }


def context_overflow_recovery_failure_note(
    *,
    message_count: int,
    minimum_compaction_messages: int,
    successful_recoveries: int,
    maximum_attempts: int = CONTEXT_OVERFLOW_RECOVERY_MAX_ATTEMPTS,
) -> str:
    """Explain why automatic overflow recovery stopped without altering input."""
    if maximum_attempts == 0:
        reason = "Automatic context recovery is disabled for this endpoint."
    elif successful_recoveries >= maximum_attempts:
        reason = f"The bounded limit of {maximum_attempts} automatic recovery attempts was exhausted."
    elif message_count < minimum_compaction_messages:
        reason = (
            "There is no older reducible history; the current user request was "
            "preserved exactly and was not compacted."
        )
    else:
        reason = (
            "Compaction found no additional safe reduction and the provider did "
            "not leave enough room for even a smaller output allowance."
        )
    return "Velox context recovery stopped. " + reason


def _strip_matching_outer_quotes(value: Any) -> str:
    text = str(value or "").strip()
    for _ in range(2):
        if len(text) >= 2 and text[0] == text[-1] and text[0] in {"'", '"'}:
            text = text[1:-1].strip()
        else:
            break
    return text


def normalize_endpoint_api_key(value: Any) -> str:
    """Return a raw credential suitable for one exactly-once Bearer prefix."""
    text = _strip_matching_outer_quotes(value)
    if re.match(r"(?i)^authorization\s*:", text):
        text = re.sub(r"(?i)^authorization\s*:\s*", "", text, count=1).strip()
    # Users commonly paste either the raw key or the complete Bearer value. Strip
    # repeated prefixes so Velox never sends ``Bearer Bearer ...``.
    for _ in range(4):
        updated = re.sub(r"(?i)^bearer\s+", "", text, count=1).strip()
        if updated == text:
            break
        text = updated
    if any(ord(ch) < 32 or ord(ch) == 127 for ch in text):
        raise ValueError("API key contains a control character; paste the raw key without line breaks")
    if any(ch.isspace() for ch in text):
        raise ValueError("API key contains whitespace; paste the raw key or one Bearer value")
    return text


_ENDPOINT_SECRET_QUERY_RE = re.compile(
    r"(?i)(?:^|[-_])(api[-_]?key|access[-_]?key|key|token|auth|secret|authorization|signature|sig|credential|password)(?:$|[-_])"
)
_ENDPOINT_SECRET_VALUE_RE = re.compile(
    r'''(?i)(authorization\s*[:=]\s*['"]?bearer\s+)([^\s,'"}]+)'''
)
_GENERIC_API_KEY_RE = re.compile(
    r"(?i)\b(?:sk[-_][A-Za-z0-9_-]{8,}|nvapi[-_][A-Za-z0-9_-]{8,})\b"
)


def redact_endpoint_secrets(text: Any, secrets: Iterable[str] = ()) -> str:
    output = str(text or "")
    for secret in secrets:
        value = str(secret or "")
        if not value:
            continue
        output = output.replace(value, "[REDACTED]")
        try:
            encoded = urllib.parse.quote(value, safe="")
            if encoded and encoded != value:
                output = output.replace(encoded, "[REDACTED]")
        except Exception:
            pass
    output = _ENDPOINT_SECRET_VALUE_RE.sub(r"\1[REDACTED]", output)
    output = _GENERIC_API_KEY_RE.sub("[REDACTED_API_KEY]", output)
    return output


def safe_endpoint_url(value: Any) -> str:
    raw = _strip_matching_outer_quotes(value)
    if not raw:
        return ""
    try:
        parts = urllib.parse.urlsplit(raw)
        # Use the original host/port spelling instead of ``parts.port`` so a
        # malformed port cannot make the diagnostic fallback expose URL userinfo.
        host_port = str(parts.netloc or "").rsplit("@", 1)[-1]
        netloc = ("[REDACTED]@" if "@" in str(parts.netloc or "") else "") + host_port
        pairs: list[tuple[str, str]] = []
        for key, value_text in urllib.parse.parse_qsl(parts.query, keep_blank_values=True):
            redacted = "[REDACTED]" if _ENDPOINT_SECRET_QUERY_RE.search(str(key)) else value_text
            pairs.append((key, redacted))
        query = urllib.parse.urlencode(pairs, doseq=True)
        return urllib.parse.urlunsplit((parts.scheme, netloc, parts.path, query, ""))
    except Exception:
        fallback = re.sub(r"(?i)(https?://)([^/@\s]+)@", r"\1[REDACTED]@", raw)
        fallback = re.sub(
            r"(?i)([?&](?:api[-_]?key|access[-_]?key|key|token|auth|secret|authorization|signature|sig|credential|password)=)[^&#]*",
            r"\1[REDACTED]",
            fallback,
        )
        return redact_endpoint_secrets(fallback)


def endpoint_host_is_local(url: str) -> bool:
    try:
        host = (urllib.parse.urlsplit(str(url or "")).hostname or "").strip().lower().rstrip(".")
    except Exception:
        return False
    if not host:
        return False
    if (
        host in {"localhost", "host.docker.internal", "gateway.docker.internal"}
        or "." not in host
        or host.endswith((".localhost", ".local", ".lan", ".internal", ".home", ".home.arpa"))
    ):
        return True
    try:
        address = ipaddress.ip_address(host)
        return bool(address.is_loopback or address.is_private or address.is_link_local)
    except ValueError:
        return False


def endpoint_provider_name(url: str, configured_provider: Any = "") -> str:
    """Return the explicit endpoint provider, falling back to conservative URL detection."""
    configured = str(configured_provider or "").strip()
    if configured:
        return normalize_endpoint_provider(configured, url)
    return endpoint_provider_default_from_url(url)


def _endpoint_header_value(headers: Any, name: str) -> str:
    try:
        value = headers.get(name, "")
    except Exception:
        value = ""
    return str(value or "")


def _endpoint_response_header_summary(headers: Any) -> list[str]:
    wanted = {
        "content-type", "content-length", "content-encoding", "server", "date", "via",
        "retry-after", "www-authenticate", "x-request-id", "request-id",
        "x-correlation-id", "traceparent", "cf-ray", "x-envoy-upstream-service-time",
    }
    rows: list[tuple[str, str]] = []
    try:
        items = list(headers.items())
    except Exception:
        items = []
    for key, value in items:
        lower = str(key).lower()
        if (
            lower in wanted
            or lower.startswith("x-ratelimit-")
            or lower.endswith(("request-id", "requestid", "trace-id", "traceid"))
        ):
            rows.append((str(key), redact_endpoint_secrets(value)))
    return [f"{key}: {value}" for key, value in rows[:24]]


def decode_endpoint_body_excerpt(
    data: bytes,
    headers: Any = None,
    *,
    secrets: Iterable[str] = (),
    max_bytes: int = LLM_ERROR_BODY_MAX_BYTES,
    max_chars: int = LLM_ERROR_BODY_MAX_CHARS,
) -> str:
    max_bytes = max(1, int(max_bytes))
    max_chars = max(1, int(max_chars))
    raw = bytes(data or b"")
    truncated_bytes = len(raw) > max_bytes
    raw = raw[:max_bytes]
    content_encoding = _endpoint_header_value(headers, "Content-Encoding").lower().strip()
    if raw and content_encoding:
        def bounded_decompress(wbits: int) -> tuple[bytes, bool]:
            decoder = zlib.decompressobj(wbits)
            output = decoder.decompress(raw, max_bytes + 1)
            truncated = len(output) > max_bytes or bool(decoder.unconsumed_tail)
            if not truncated:
                remaining = max_bytes + 1 - len(output)
                output += decoder.flush(max(1, remaining))
                truncated = len(output) > max_bytes
            return output[:max_bytes], truncated

        try:
            if "gzip" in content_encoding:
                raw, expanded_truncated = bounded_decompress(16 + zlib.MAX_WBITS)
                truncated_bytes = truncated_bytes or expanded_truncated
            elif "deflate" in content_encoding:
                try:
                    raw, expanded_truncated = bounded_decompress(zlib.MAX_WBITS)
                except zlib.error:
                    raw, expanded_truncated = bounded_decompress(-zlib.MAX_WBITS)
                truncated_bytes = truncated_bytes or expanded_truncated
        except Exception:
            # Keep the bounded raw bytes if an intermediary mislabeled the body.
            pass
    content_type = _endpoint_header_value(headers, "Content-Type")
    charset = "utf-8"
    match = re.search(r'(?i)charset\s*=\s*[\'"]?([^;\s\'"]+)', content_type)
    if match:
        charset = match.group(1)
    try:
        text = raw.decode(charset, errors="replace")
    except Exception:
        text = raw.decode("utf-8", errors="replace")
    stripped = text.strip()
    if stripped:
        try:
            parsed = json.loads(stripped)
            text = json.dumps(parsed, ensure_ascii=False, indent=2, default=str)
        except Exception:
            text = stripped
    else:
        text = "[empty response body]"
    text = redact_endpoint_secrets(text, secrets)
    truncated_chars = len(text) > max_chars
    if truncated_chars:
        text = text[:max_chars]
    if truncated_bytes or truncated_chars:
        text += "\n[response body excerpt truncated by Velox]"
    return text


def is_timeout_exception(exc: BaseException | None) -> bool:
    """Return whether an exception or one of its wrappers represents a real I/O timeout."""
    seen: set[int] = set()
    current: BaseException | Any | None = exc
    for _ in range(8):
        if current is None or id(current) in seen:
            break
        seen.add(id(current))
        if isinstance(current, (LLMRequestTimeoutError, TimeoutError)):
            return True
        reason = getattr(current, "reason", None)
        if isinstance(reason, BaseException):
            current = reason
            continue
        cause = getattr(current, "__cause__", None)
        if isinstance(cause, BaseException):
            current = cause
            continue
        context = getattr(current, "__context__", None)
        if isinstance(context, BaseException):
            current = context
            continue
        break
    if exc is None:
        return False
    text = f"{type(exc).__name__}: {exc}".lower()
    return "timed out" in text or "timeout" in type(exc).__name__.lower()


VISION_MODEL_HINT_RE = re.compile(
    r"(vision|multimodal|mm|vl|v-l|qwen[^\n]{0,24}vl|llava|bakllava|pixtral|molmo|internvl|ovis|idefics|minicpm|gpt-4o|gpt-4\.1|gemini|claude-3|kimi|moonshot|k2[._ -]?6|glm[-_ ]?5[._]3[-_ ]?flash\b)",
    re.IGNORECASE,
)

def endpoint_supports_vision(endpoint: dict[str, Any] | None) -> bool:
    """Best-effort capability check for OpenAI-compatible local endpoints.

    Explicit capability flags take priority, while model and endpoint names are
    used as a fallback hint. Direct image/PDF attachments opt in separately
    through ``should_send_vision_inputs``.
    """
    endpoint = endpoint or {}
    if bool(endpoint.get("text_only") or endpoint.get("disable_vision") or endpoint.get("vision_disabled")):
        return False
    for key in ("vision", "supports_vision", "multimodal"):
        if key not in endpoint:
            continue
        value = endpoint.get(key)
        if value is True:
            return True
        if isinstance(value, str):
            raw = value.strip().lower()
            if raw in {"1", "true", "yes", "on", "vision", "multimodal", "enabled"}:
                return True
            if raw in {"0", "false", "no", "off", "text", "text-only", "disabled"}:
                return False
            if raw == "auto":
                continue
    # Family selection remains meaningful when the server uses an opaque alias.
    # Explicit disabled/text-only flags above remain authoritative.
    if normalize_endpoint_model_type(endpoint.get("model_type")) == ENDPOINT_MODEL_TYPE_GLM_5_3_FLASH:
        return True
    haystack = " ".join(str(endpoint.get(k) or "") for k in ("model", "served_model_name", "name", "base_url", "profile_label"))
    return bool(VISION_MODEL_HINT_RE.search(haystack))


CURRENT_CONTEXT_VISION_HANDOFF_SCHEMA = "velox_current_context_vision_handoff.v1"
CURRENT_CONTEXT_VISION_RESULT_KEY = "current_context_image_handoff"
CURRENT_CONTEXT_VISION_MESSAGE_MARKER = "_velox_current_context_vision"


def endpoint_uses_inline_image_analysis(endpoint: dict[str, Any] | None) -> bool:
    """Whether the requesting Task receives pixels rather than an isolated review."""
    return (endpoint or {}).get("image_analysis_context") == "inline"


def current_context_vision_handoffs_from_tool_results(
    tool_results: Iterable[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Collect direct-vision handoffs from image tools or nested browser reviews.

    Browser tools may contain several automatic image-analysis results inside
    ``visualReview.reviews``. Recursing only for the exact handoff key lets the
    same Chat/Agent replay path inject those screenshots without treating normal
    image metadata or paths as multimodal content.
    """
    rows: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str, str]] = set()

    def visit(value: Any, depth: int = 0) -> None:
        if depth > 24:
            return
        if isinstance(value, dict):
            candidate = value.get(CURRENT_CONTEXT_VISION_RESULT_KEY)
            if isinstance(candidate, dict):
                if str(candidate.get("schema") or "") == CURRENT_CONTEXT_VISION_HANDOFF_SCHEMA:
                    row = copy.deepcopy(candidate)
                    identity = (
                        str(row.get("tool_call_id") or ""),
                        str(row.get("tool_name") or ""),
                        str(row.get("absolute_path") or ""),
                        str(row.get("prompt") or ""),
                    )
                    if identity not in seen:
                        seen.add(identity)
                        rows.append(row)
            for key, child in value.items():
                if key == CURRENT_CONTEXT_VISION_RESULT_KEY:
                    continue
                if isinstance(child, (dict, list, tuple)):
                    visit(child, depth + 1)
        elif isinstance(value, (list, tuple)):
            for child in value:
                visit(child, depth + 1)

    for result in tool_results:
        if not isinstance(result, dict) or result.get("ok") is False:
            continue
        visit(result)
    return rows


def remove_current_context_vision_messages(messages: list[dict[str, Any]]) -> int:
    """Remove older tool-injected images so a one-image endpoint can inspect the next one."""
    before = len(messages)
    messages[:] = [
        message for message in messages
        if not (isinstance(message, dict) and bool(message.get(CURRENT_CONTEXT_VISION_MESSAGE_MARKER)))
    ]
    return before - len(messages)


def retain_latest_current_context_vision_message(messages: list[dict[str, Any]]) -> int:
    """Normalize replayed Agent history to the newest direct-vision handoff window."""
    marked = [
        index for index, message in enumerate(messages)
        if isinstance(message, dict) and bool(message.get(CURRENT_CONTEXT_VISION_MESSAGE_MARKER))
    ]
    if len(marked) <= 1:
        return 0
    keep = marked[-1]
    before = len(messages)
    messages[:] = [
        message for index, message in enumerate(messages)
        if index == keep or not (
            isinstance(message, dict) and bool(message.get(CURRENT_CONTEXT_VISION_MESSAGE_MARKER))
        )
    ]
    return before - len(messages)


def build_current_context_vision_message(
    existing_messages: list[dict[str, Any]],
    tool_results: Iterable[dict[str, Any]],
    endpoint: dict[str, Any] | None,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    """Build one ordered OpenAI multimodal user message for current-context analysis.

    Every unique image is represented by the standard ``image_url`` content
    block followed immediately by the original analysis instruction. Older generated
    images remain byte-stable while capacity permits; explicit pixel-budget
    compaction replaces old pixels with omission notices without moving their text.
    Ordinary user-attached images retain priority. Real execution identities make
    durable visual delivery idempotent across interrupted Agent recovery.
    """
    tool_results = list(tool_results)
    handoffs = current_context_vision_handoffs_from_tool_results(tool_results)
    source_ids = [str(row.get("tool_call_id")) for row in tool_results if row.get("tool_call_id")]
    summary = {
        "requested_handoffs": len(handoffs),
        "included_images": 0,
        "included_requests": 0,
        "omitted_images": 0,
        "max_images": endpoint_max_image_inputs(endpoint),
    }
    if not handoffs:
        return None, summary

    if source_ids and any(row.get("_velox_vision_source_ids") == source_ids for row in existing_messages):
        summary["already_committed"] = True
        return None, summary

    max_images = int(summary["max_images"])
    incoming_paths = {str(row.get("absolute_path") or "") for row in handoffs}
    incoming_count = sum(1 for path in incoming_paths if path and Path(path).is_file())
    summary["compacted_older_images"] = _make_vision_context_room(existing_messages, endpoint or {}, incoming_count)
    existing_images = message_image_input_count(existing_messages)
    available = max(0, max_images - existing_images)
    summary["existing_images"] = existing_images
    summary["available_images"] = available
    content: list[dict[str, Any]] = []
    included_paths: set[str] = set()
    omitted_paths: set[str] = set()

    for handoff in handoffs:
        raw_path = str(handoff.get("absolute_path") or "").strip()
        path = Path(raw_path).expanduser().resolve() if raw_path else Path()
        identity = str(path)
        is_new_image = identity not in included_paths
        if is_new_image and len(included_paths) >= available:
            omitted_paths.add(identity or raw_path or "[missing path]")
            continue
        if not path.is_file():
            omitted_paths.add(identity or raw_path or "[missing path]")
            continue
        mime = str(handoff.get("mime") or mimetypes.guess_type(path.name)[0] or "image/png")
        if not mime.startswith("image/"):
            omitted_paths.add(identity)
            continue
        if is_new_image:
            image_bytes = file_read_bytes(path)
            data_url = f"data:{mime};base64,{base64.b64encode(image_bytes).decode('ascii')}"
            content.append({
                "type": "image_url",
                "image_url": {"url": data_url},
            })
            included_paths.add(identity)
        tool_name = str(handoff.get("tool_name") or "image_analyze")
        prompt = str(handoff.get("prompt") or "Inspect this image.").strip()
        instruction = str(handoff.get("analysis_instruction") or "").strip()
        message_text = (
            f"Velox has now injected the exact prepared image requested by {tool_name} into your current "
            "Chat/Agent context. You can see the pixels directly. Analyze the image yourself in this response "
            "and report the visual findings before continuing.\n\n"
            f"Original analysis request:\n{prompt}"
        )
        if instruction:
            message_text += "\n\nReview contract:\n" + instruction
        content.append({"type": "text", "text": message_text})
        summary["included_requests"] = int(summary["included_requests"]) + 1

    summary["included_images"] = len(included_paths)
    summary["omitted_images"] = len(omitted_paths)
    if omitted_paths:
        content.append({
            "type": "text",
            "text": (
                f"Velox could not inject {len(omitted_paths)} additional unique image(s) because this endpoint "
                f"allows at most {max_images} image input(s) per prompt and {existing_images} ordinary image "
                "input(s) are already retained. Finish the visible image analysis first, then call the relevant "
                "image-analysis tool again for another image; the next handoff replaces this tool-injected window."
            ),
        })
    if not content:
        return None, summary
    return {
        "role": "user",
        "content": content,
        CURRENT_CONTEXT_VISION_MESSAGE_MARKER: True,
        **({"_velox_vision_source_ids": source_ids} if source_ids else {}),
    }, summary


def should_send_vision_inputs(endpoint: dict[str, Any] | None, *, has_image_attachment: bool = False, force_pdf_images: bool = False) -> bool:
    """Return whether the configured endpoint may receive direct image parts.

    Attachments do not upgrade a text-only or unknown endpoint into a multimodal
    one. Capability comes from explicit endpoint configuration or recognized model
    metadata; the attachment flags remain inputs for call-site clarity only.
    """
    _ = has_image_attachment, force_pdf_images
    return endpoint_supports_vision(endpoint)


_TRANSPORT_CLOSE_DIAGNOSTICS: list[str] = []
_WS2_32: Any = None


def _win_ws2_32() -> Any:
    """Lazy pointer-width ws2_32 binding with Winsock last-error capture."""
    global _WS2_32
    if _WS2_32 is None:
        binding = ctypes.WinDLL("ws2_32", use_last_error=True)
        binding.closesocket.restype = ctypes.c_int
        binding.closesocket.argtypes = [ctypes.c_void_p]
        binding.WSAGetLastError.restype = ctypes.c_int
        binding.WSAGetLastError.argtypes = []
        _WS2_32 = binding
    return _WS2_32


def _record_transport_diagnostic(message: str) -> None:
    """Record a non-fatal transport close failure for later diagnostics."""
    _TRANSPORT_CLOSE_DIAGNOSTICS.append(message)
    if str(os.environ.get("VELOX_TRANSPORT_TRACE") or "").strip():
        try:
            sys.stderr.write(f"[transport-close] {message}\n")
        except Exception:
            pass


def _interrupt_blocked_socket(sock: socket.socket) -> None:
    """Interrupt a blocked Windows socket read by closing its descriptor.

    The descriptor is detached exactly once and closed immediately with the
    pointer-width Winsock binding. If the socket is already detached or closed
    the call is a no-op, so a descriptor that has since been reused is never
    closed and an error cannot leave a detached handle with no cleanup owner.
    """
    if os.name != "nt":
        return
    try:
        if sock.fileno() < 0:
            return
        fd = sock.detach()
    except (OSError, ValueError):
        return
    if fd < 0:
        return
    ws2_32 = _win_ws2_32()
    try:
        result = int(ws2_32.closesocket(fd))
        if result == ctypes.c_int(-1).value:
            wsa_error = int(ws2_32.WSAGetLastError())
            _record_transport_diagnostic(f"Winsock closesocket failed with error {wsa_error} (fd={fd})")
    except Exception as exc:
        _record_transport_diagnostic(
            f"Winsock closesocket raised {type(exc).__name__}: {exc} (fd={fd})"
        )


class LLMClient:
    def __init__(self, storage: Storage):
        self.storage = storage
        self._endpoint_cache_key: tuple[int, int, int, int] | None = None
        self._endpoint_config_cache: dict[str, Any] | None = None
        self.request_scheduler: EndpointInferenceScheduler | None = None
        self.request_monitor: "LLMTaskMonitor | None" = None
        self.request_rate_limiter = EndpointRequestRateLimiter()

    def bind_request_scheduler(
        self, scheduler: EndpointInferenceScheduler | None, monitor: "LLMTaskMonitor | None" = None,
    ) -> None:
        self.request_scheduler = scheduler
        self.request_monitor = monitor
        if scheduler is not None:
            scheduler.bind_monitor(monitor)

    async def _wait_for_endpoint_request_budget(self, request: LLMRequest) -> float:
        """Admit one actual HTTP request through the profile's shared RPM guard."""
        try:
            endpoint = self.resolve_endpoint(request.endpoint_profile_id)
        except Exception:
            return 0.0
        if (
            not str(endpoint.get("base_url") or "").strip()
            or not str(endpoint.get("model") or "").strip()
        ):
            return 0.0
        return await self.request_rate_limiter.acquire(
            endpoint,
            cancel_event=request.cancel_event,
            monitor=self.request_monitor,
            task_id=request.monitor_task_id,
        )

    def _cache_reporting_diagnostics(self, request: LLMRequest, usage: Any, diagnostics: Any) -> dict[str, Any]:
        try:
            endpoint = self.resolve_endpoint(request.endpoint_profile_id)
        except Exception:
            endpoint = {}
        return dict(diagnostics or {}, cache_reporting=cache_reporting_diagnostics(endpoint, usage))

    def _begin_monitored_inference(self, request: LLMRequest) -> str | None:
        monitor = self.request_monitor
        task_id = str(request.monitor_task_id or "").strip()
        if monitor is None or not task_id:
            return None
        try:
            endpoint = self.resolve_endpoint(request.endpoint_profile_id)
        except Exception:
            endpoint = {
                "profile_label": str(request.endpoint_profile_id or ""),
                "api_transport": ENDPOINT_API_TRANSPORT_CHAT_COMPLETIONS,
            }
        try:
            return monitor.begin_inference_round(task_id, request, endpoint)
        except Exception:
            return None

    def _append_monitored_inference_chunk(
        self, request: LLMRequest, round_id: str | None, chunk: LLMChunk,
    ) -> None:
        monitor = self.request_monitor
        task_id = str(request.monitor_task_id or "").strip()
        if monitor is None or not task_id or not round_id:
            return
        try:
            monitor.append_inference_chunk(task_id, round_id, chunk)
        except Exception:
            pass

    def _finish_monitored_inference(
        self,
        request: LLMRequest,
        round_id: str | None,
        *,
        result: dict[str, Any] | None = None,
        error: BaseException | str | None = None,
    ) -> None:
        monitor = self.request_monitor
        task_id = str(request.monitor_task_id or "").strip()
        if monitor is None or not task_id or not round_id:
            return
        try:
            monitor.finish_inference_round(task_id, round_id, result=result, error=error)
        except Exception:
            pass

    def _endpoint_cache_signature(self) -> tuple[int, int, int, int]:
        try:
            stat = self.storage.paths.app_json_path.stat()
            # Atomic settings writes can preserve the same byte length and, on
            # coarse filesystems, the same visible modification timestamp. ctime
            # and inode/file-id keep endpoint changes from remaining stale.
            return (
                int(getattr(stat, "st_mtime_ns", 0)),
                int(stat.st_size),
                int(getattr(stat, "st_ctime_ns", 0)),
                int(getattr(stat, "st_ino", 0)),
            )
        except Exception:
            return 0, 0, 0, 0

    def _load_endpoint_config_cached(self) -> dict[str, Any]:
        key = self._endpoint_cache_signature()
        if self._endpoint_cache_key == key and self._endpoint_config_cache is not None:
            return self._endpoint_config_cache
        config = self.storage.load_config()
        self._endpoint_cache_key = key
        self._endpoint_config_cache = config
        return config

    def resolve_endpoint(self, endpoint_profile_id: str) -> dict[str, Any]:
        config = self._load_endpoint_config_cached()
        requested = str(endpoint_profile_id or "").strip()
        if requested and not any(str(p.get("id") or "") == requested for p in endpoint_profiles_from_config(config)):
            raise ValueError(f"Unknown endpoint profile: {requested}")
        return endpoint_with_token_calibration(self.storage, endpoint_profile_for_id(config, requested))

    def _chat_completions_url(self, base_url: str) -> str:
        """Normalize an API root, /v1 base, Responses URL, or chat endpoint."""
        raw = _strip_matching_outer_quotes(base_url)
        if not raw:
            return ""
        if any(ord(ch) < 32 or ord(ch) == 127 for ch in raw):
            raise ValueError("Endpoint URL contains a control character or line break")
        parts = urllib.parse.urlsplit(raw)
        scheme = str(parts.scheme or "").lower()
        if scheme not in {"http", "https"} or not parts.netloc:
            raise ValueError(
                "Endpoint URL must be an absolute http:// or https:// URL, for example "
                "http://127.0.0.1:8000/v1/chat/completions"
            )
        path = str(parts.path or "").rstrip("/")
        lower = path.lower()
        host = str(parts.hostname or "").lower().rstrip(".")
        is_novita = host == "novita.ai" or host.endswith(".novita.ai")
        if lower.endswith("/chat/completion"):
            path = path[:-len("/chat/completion")] + "/chat/completions"
        elif lower.endswith("/chat/completions"):
            pass
        elif lower.endswith("/responses"):
            path = path[:-len("/responses")] + "/chat/completions"
        elif is_novita and lower in {"", "/", "/openai", "/openai/v1", "/v1"}:
            path = "/openai/v1/chat/completions"
        elif lower.endswith("/v1"):
            path = path + "/chat/completions"
        elif lower in {"", "/"}:
            path = "/v1/chat/completions"
        else:
            path = path + "/chat/completions"
        if is_novita and path.lower() in {"/openai/chat/completions", "/v1/chat/completions"}:
            path = "/openai/v1/chat/completions"
        return urllib.parse.urlunsplit((parts.scheme, parts.netloc, path, parts.query, ""))

    def is_endpoint_configured(self, endpoint_profile_id: str) -> bool:
        endpoint = self.resolve_endpoint(endpoint_profile_id)
        return bool(str(endpoint.get("base_url") or "").strip() and str(endpoint.get("model") or "").strip())

    def missing_endpoint_message(self, endpoint_profile_id: str) -> str:
        endpoint = self.resolve_endpoint(endpoint_profile_id)
        label = str(endpoint.get("profile_label") or endpoint.get("label") or endpoint_profile_id or "selected endpoint")
        return f"The LLM endpoint profile {label!r} is not configured. Open Settings and set both Endpoint URL and Model."

    def request_timeout_seconds(self, endpoint_profile_id: str) -> int:
        """Return a finite timeout for one directly selected endpoint profile."""
        endpoint = self.resolve_endpoint(endpoint_profile_id)
        return bounded_positive_int(
            endpoint.get("timeout_seconds"), ENDPOINT_TIMEOUT_SECONDS_DEFAULT, minimum=1, maximum=None,
        )


    def response_max_bytes(self) -> int:
        try:
            return tool_setting_int(self.storage.load_config(), "llm_response_max_bytes")
        except Exception:
            return LLM_RESPONSE_MAX_BYTES_HARD

    def error_body_max_bytes(self) -> int:
        try:
            return tool_setting_int(self.storage.load_config(), "llm_error_body_max_bytes")
        except Exception:
            return LLM_ERROR_BODY_MAX_BYTES

    def error_body_max_chars(self) -> int:
        try:
            return tool_setting_int(self.storage.load_config(), "llm_error_body_max_chars")
        except Exception:
            return LLM_ERROR_BODY_MAX_CHARS

    @staticmethod
    def _payload_error_value(raw: Any) -> Any | None:
        if not isinstance(raw, dict):
            return None
        error = raw.get("error")
        if error not in (None, False, "", {}, []):
            return error
        if str(raw.get("object") or "").strip().lower() == "error":
            return raw
        if raw.get("success") is False and any(key in raw for key in ("message", "detail", "code")):
            return raw
        return None

    @staticmethod
    def _failure_advice(
        status_code: int | None,
        provider: str,
        url: str,
        underlying: BaseException | None = None,
        response_body: str = "",
    ) -> list[str]:
        advice: list[str] = []
        body_lower = str(response_body or "").lower()
        if provider == "novita":
            advice.append(
                "Novita direct REST chat requests use /openai/v1/chat/completions. "
                "Velox normalizes the common /openai/chat/completions form automatically."
            )
        if status_code == 400 or status_code == 422:
            advice.append("The provider rejected the JSON payload or one of its fields; inspect the response body above.")
        elif status_code == 401:
            advice.append("Check that the API key is current and permitted. Velox sends exactly one Bearer prefix and never prints the key.")
        elif status_code == 403:
            if any(marker in body_lower for marker in ("browser_signature_banned", "error 1010", "user-agent has been banned", "browser's signature")):
                advice.append(
                    "The gateway blocked the HTTP client signature. In Settings > Endpoints, edit this saved endpoint and use the Generic commercial API User-Agent or a provider-approved custom value."
                )
                advice.append("Do not retry this exact signature; Cloudflare Error 1010 is a policy denial rather than a transient endpoint failure.")
            else:
                advice.append(
                    "The server received the request but denied it. Check the provider message for account, key, model-access, billing, verification, proxy, request-policy, or User-Agent restrictions."
                )
        elif status_code == 404:
            advice.append("Check the effective endpoint path and model ID; 404 commonly means the REST path or endpoint profile or model ID is wrong.")
        elif status_code == 405:
            advice.append("The configured URL may be an API page rather than the POST chat-completions endpoint, or a redirect may have changed the method.")
        elif status_code in {408, 425}:
            advice.append("The provider did not complete the request in time; retry after checking service health and the endpoint timeout.")
        elif status_code == 413:
            advice.append("The request body or assembled prompt is larger than the provider accepts.")
        elif status_code == 429:
            advice.append("The provider rate-limited or quota-limited the request; inspect Retry-After and rate-limit headers above.")
        elif status_code is not None and 500 <= status_code <= 599:
            advice.append("The remote service or gateway failed; retry after checking provider status and any reverse proxy in front of it.")
        if underlying is not None:
            lower = f"{type(underlying).__name__}: {underlying}".lower()
            if isinstance(underlying, socket.gaierror) or "name or service not known" in lower or "getaddrinfo" in lower:
                advice.append("DNS resolution failed; verify the hostname, network connection, VPN, and proxy settings.")
            elif isinstance(underlying, ConnectionRefusedError) or "connection refused" in lower:
                advice.append("The host refused the TCP connection; verify the server is listening, the port is correct, and the firewall permits it.")
            elif isinstance(underlying, (ssl.SSLError, ssl.CertificateError)) or "certificate verify failed" in lower:
                advice.append("TLS validation failed; verify the system clock, certificate chain, hostname, and any HTTPS-inspecting proxy.")
            elif isinstance(underlying, (ConnectionResetError, BrokenPipeError)) or "connection reset" in lower:
                advice.append("The peer or an intermediary closed the connection unexpectedly; check proxy/gateway logs and retry.")
        return advice

    def _log_endpoint_failure(self, data: dict[str, Any]) -> None:
        try:
            self.storage.append_app_log("llm.endpoint.error", data)
        except Exception:
            pass

    def _endpoint_error(
        self,
        exc: BaseException | None,
        *,
        endpoint: dict[str, Any],
        url: str,
        headers: dict[str, str],
        timeout: int,
        payload: dict[str, Any],
        stream: bool,
        status_code: int | None = None,
        reason: str = "",
        response_headers: Any = None,
        response_body_bytes: bytes | None = None,
        final_url: str = "",
    ) -> LLMEndpointError:
        profile_id = str(endpoint.get("profile_id") or endpoint.get("id") or "endpoint")
        configured_url = str(endpoint.get("_configured_base_url") or endpoint.get("base_url") or "")
        provider = str(endpoint.get("_provider") or endpoint_provider_name(url, endpoint.get("provider")))
        api_key = ""
        try:
            api_key = normalize_endpoint_api_key(endpoint.get("api_key"))
        except Exception:
            api_key = ""
        underlying: BaseException | None = None
        if isinstance(exc, urllib.error.HTTPError):
            if status_code is None:
                status_code = int(getattr(exc, "code", 0) or 0) or None
            if not reason:
                reason = str(getattr(exc, "reason", "") or "")
            if response_headers is None:
                response_headers = getattr(exc, "headers", None)
            if not final_url:
                try:
                    final_url = str(exc.geturl() or "")
                except Exception:
                    final_url = ""
            if response_body_bytes is None:
                try:
                    response_body_bytes = exc.read(self.error_body_max_bytes() + 1)
                except Exception as body_exc:
                    response_body_bytes = f"[could not read error response body: {type(body_exc).__name__}: {body_exc}]".encode("utf-8", errors="replace")
        elif isinstance(exc, urllib.error.URLError):
            candidate = getattr(exc, "reason", None)
            underlying = candidate if isinstance(candidate, BaseException) else exc
        elif exc is not None:
            underlying = exc
        effective_url = final_url or url
        safe_configured = safe_endpoint_url(configured_url)
        safe_request = safe_endpoint_url(url)
        safe_final = safe_endpoint_url(effective_url)
        status_label = ""
        if status_code is not None:
            status_label = f"HTTP {status_code}" + (f" {reason}" if reason else "")
        elif exc is not None:
            status_label = f"{type(exc).__name__}: {exc}"
        else:
            status_label = reason or "Endpoint protocol failure"

        request_items = payload.get("messages") if isinstance(payload.get("messages"), list) else payload.get("input")
        message_count = len(request_items or []) if isinstance(request_items, list) else 0
        request_item_label = "messages" if isinstance(payload.get("messages"), list) else "input items"
        request_bytes = len(json.dumps(payload, ensure_ascii=False, default=str).encode("utf-8"))
        output_limit_field = (
            "max_output_tokens" if "max_output_tokens" in payload else
            "max_completion_tokens" if "max_completion_tokens" in payload else "max_tokens"
        )
        output_limit_value = payload.get(output_limit_field)
        auth_present = bool(headers.get("Authorization"))
        lines = [
            "LLM endpoint request failed.",
            f"Endpoint profile: {str(endpoint.get('profile_label') or endpoint.get('label') or 'Unnamed')} ({str(endpoint.get('profile_id') or endpoint.get('id') or 'unknown')})",
            f"Failure: {status_label}",
        ]
        if safe_configured and safe_configured != safe_request:
            lines.append(f"Configured URL: {safe_configured}")
        lines.append(f"Request URL: {safe_request}")
        if safe_final and safe_final != safe_request:
            lines.append(f"Final URL after redirect: {safe_final}")
        if underlying is not None and underlying is not exc:
            lines.append(
                "Underlying error: "
                + redact_endpoint_secrets(f"{type(underlying).__name__}: {underlying}", (api_key,))
            )
        lines.extend([
            "Method: POST",
            f"Model: {redact_endpoint_secrets(payload.get('model', ''), (api_key,))}",
            f"Streaming: {'yes' if stream else 'no'}",
            f"Timeout: {int(timeout)} seconds",
            f"Request summary: {message_count} {request_item_label}; {request_bytes} JSON bytes; {output_limit_field}={output_limit_value}",
            f"Payload fields: {', '.join(sorted(str(key) for key in payload))}",
            (
                f"Authorization: configured (Bearer credential; {int(endpoint.get('_api_key_length') or len(api_key))} characters; value redacted)"
                if auth_present else "Authorization: not configured"
            ),
            f"Request headers: Content-Type={headers.get('Content-Type', '')}; Accept={headers.get('Accept', '')}; User-Agent={headers.get('User-Agent', '')}",
        ])
        capacity = endpoint.get("_request_capacity")
        if isinstance(capacity, dict):
            lines.append("Prompt accounting: " + json.dumps(capacity, sort_keys=True, ensure_ascii=False))
        try:
            proxies = urllib.request.getproxies()
            scheme = urllib.parse.urlsplit(url).scheme.lower()
            if proxies.get(scheme) or proxies.get("all"):
                lines.append(f"Proxy environment: {scheme.upper()} proxy configured (value redacted)")
        except Exception:
            pass
        header_rows = _endpoint_response_header_summary(response_headers)
        if header_rows:
            lines.append("Response headers:")
            lines.extend(f"  {row}" for row in header_rows)
        body_excerpt = ""
        if response_body_bytes is not None:
            body_excerpt = decode_endpoint_body_excerpt(
                response_body_bytes,
                response_headers,
                secrets=(api_key,),
                max_bytes=self.error_body_max_bytes(),
                max_chars=self.error_body_max_chars(),
            )
            lines.extend(["Response body:", body_excerpt])
        elif status_code is not None:
            lines.extend(["Response body:", "[not available]"])
        advice = self._failure_advice(status_code, provider, effective_url, underlying, body_excerpt)
        if advice:
            lines.append("Suggested checks:")
            lines.extend(f"- {item}" for item in advice)
        text = redact_endpoint_secrets("\n".join(lines), (api_key,))
        error = LLMEndpointError(
            text,
            endpoint_profile_id=profile_id,
            url=safe_final or safe_request,
            status_code=status_code,
            reason=reason,
            response_body=body_excerpt,
            response_headers=response_headers,
        )
        error.__cause__ = underlying or exc
        self._log_endpoint_failure({
            "endpoint_profile_id": profile_id,
            "profile_id": str(endpoint.get("profile_id") or endpoint.get("id") or ""),
            "profile_label": str(endpoint.get("profile_label") or endpoint.get("label") or ""),
            "provider": provider,
            "configured_url": safe_configured,
            "request_url": safe_request,
            "final_url": safe_final,
            "status_code": status_code,
            "reason": redact_endpoint_secrets(reason, (api_key,)),
            "exception_type": type(exc).__name__ if exc is not None else "",
            "model": redact_endpoint_secrets(payload.get("model", ""), (api_key,)),
            "stream": bool(stream),
            "timeout_seconds": int(timeout),
            "authorization_present": auth_present,
            "response_body_excerpt": body_excerpt[:8000],
        })
        return error

    def _normalize_messages_for_chat_template(
        self,
        messages: list[dict[str, Any]],
        *,
        include_reasoning_fields: bool = True,
        reasoning_policy: str = "all",
    ) -> list[dict[str, Any]]:
        # Some HF/vLLM chat templates, including Qwen-family templates, reject
        # any system message that is not the very first message. Velox internally
        # builds several system/context blocks, so collapse them into one leading
        # system message immediately before sending the request.
        #
        # Scalar aliases normalize to reasoning_content. Structured reasoning_details
        # is a distinct provider-owned replay carrier and must also survive when
        # present. Display-only aliases are never sent as extra endpoint fields.
        system_chunks: list[str] = []
        normalized: list[dict[str, Any]] = []
        for msg in messages or []:
            if not isinstance(msg, dict):
                continue
            role = str(msg.get("role") or "user")
            content = msg.get("content", "")
            if role == "system":
                if isinstance(content, str):
                    text = content
                else:
                    text = json.dumps(content, ensure_ascii=False, default=str)
                if text.strip():
                    system_chunks.append(text.strip())
                continue
            if role == "tool":
                out_msg = {
                    "role": "tool",
                    "content": content,
                    "tool_call_id": str(msg.get("tool_call_id") or ""),
                }
                if str(msg.get("name") or "").strip():
                    out_msg["name"] = str(msg.get("name") or "").strip()
                normalized.append(out_msg)
                continue
            elif role not in ("user", "assistant"):
                role = "user"
            out_msg: dict[str, Any] = {"role": role, "content": content}
            if role == "assistant" and isinstance(msg.get("tool_calls"), list):
                out_msg["tool_calls"] = copy.deepcopy(msg.get("tool_calls") or [])
            preserve_this_reasoning = (
                role == "assistant"
                and include_reasoning_fields
                and (
                    reasoning_policy != "tool_only"
                    or bool(out_msg.get("tool_calls"))
                )
            )
            if preserve_this_reasoning:
                if isinstance(msg.get("reasoning_details"), list):
                    out_msg["reasoning_details"] = copy.deepcopy(msg["reasoning_details"])
                reasoning: Any = msg.get("reasoning_content")
                if reasoning in (None, ""):
                    reasoning = msg.get("reasoning")
                if reasoning in (None, ""):
                    thinking = msg.get("thinking")
                    if isinstance(thinking, str):
                        reasoning = thinking
                if reasoning in (None, ""):
                    blocks = msg.get("thinking_blocks")
                    if isinstance(blocks, list):
                        parts = [
                            str(block.get("thinking") or block.get("text") or "").strip()
                            for block in blocks if isinstance(block, dict)
                        ]
                        reasoning = "\n\n".join(part for part in parts if part)
                if reasoning not in (None, ""):
                    out_msg["reasoning_content"] = str(reasoning)
            normalized.append(out_msg)
        if system_chunks:
            return [{"role": "system", "content": "\n\n".join(system_chunks)}] + normalized
        return normalized

    @staticmethod
    def _gemma_image_first_messages(messages: list[dict[str, Any]]) -> list[dict[str, Any]]:
        """Place image parts before text for Gemma multimodal requests.

        Google's Gemma examples recommend image-before-text ordering. Preserve
        message identity and non-list content while reordering only multimodal
        content parts inside each message.
        """
        ordered: list[dict[str, Any]] = []
        for message in messages:
            current = dict(message)
            content = current.get("content")
            if isinstance(content, list):
                image_parts = [
                    part for part in content
                    if isinstance(part, dict) and str(part.get("type") or "") in {"image_url", "input_image"}
                ]
                other_parts = [
                    part for part in content
                    if not (isinstance(part, dict) and str(part.get("type") or "") in {"image_url", "input_image"})
                ]
                current["content"] = image_parts + other_parts
            ordered.append(current)
        return ordered

    @staticmethod
    def _merge_payload_object(payload: dict[str, Any], field: str, defaults: dict[str, Any]) -> None:
        """Merge model-compatibility defaults without hiding explicit user overrides."""
        existing = payload.get(field)
        merged = dict(defaults)
        if isinstance(existing, dict):
            merged.update(existing)
        payload[field] = merged


    def _chat_payload_and_headers(self, request: LLMRequest, *, stream: bool) -> tuple[dict[str, Any], str, bytes, dict[str, str], int, dict[str, Any]]:
        request.prepared_capacity.clear()
        endpoint = self.resolve_endpoint(request.endpoint_profile_id)
        configured_url = _strip_matching_outer_quotes(endpoint.get("base_url"))
        model = _strip_matching_outer_quotes(endpoint.get("model"))
        if any(ord(ch) < 32 or ord(ch) == 127 for ch in model):
            raise ValueError("Model ID contains a control character or line break")
        url = self._chat_completions_url(configured_url)
        provider = endpoint_provider_name(url, endpoint.get("provider"))
        model_type = normalize_endpoint_model_type(endpoint.get("model_type"))
        requested_max_tokens = request.max_output_tokens if request.max_output_tokens is not None else endpoint.get("max_output_tokens")
        token_field = endpoint_output_token_field(endpoint, provider)
        reasoning_level = endpoint_effective_reasoning_level(endpoint, request.reasoning_effort_override)
        preserve_reasoning = endpoint_model_type_preserves_reasoning(endpoint, request.reasoning_effort_override)
        native_tools_enabled = bool(request.native_tools)
        endpoint_messages = prepend_endpoint_system_prompt_addon(request.messages, endpoint)
        normalized_messages = self._normalize_messages_for_chat_template(
            endpoint_messages,
            include_reasoning_fields=preserve_reasoning,
            reasoning_policy="tool_only" if model_type == ENDPOINT_MODEL_TYPE_GEMMA_4 else "all",
        )
        if model_type == ENDPOINT_MODEL_TYPE_GEMMA_4:
            normalized_messages = self._gemma_image_first_messages(normalized_messages)
        if model_type == ENDPOINT_MODEL_TYPE_MUSE_GLIMMER:
            strength_line = f"Reasoning strength: {reasoning_level}"
            placed = False
            for message in normalized_messages:
                if str(message.get("role") or "") == "system":
                    content = str(message.get("content") or "").strip()
                    if not re.search(r"(?im)^Reasoning strength:\s*", content):
                        message["content"] = (content + "\n\n" + strength_line).strip()
                    placed = True
                    break
            if not placed:
                normalized_messages.insert(0, {"role": "system", "content": strength_line})
        image_count = message_image_input_count(normalized_messages)
        max_image_inputs = endpoint_max_image_inputs(endpoint)
        if image_count > max_image_inputs:
            raise ValueError(
                f"Endpoint profile {endpoint.get('profile_label') or endpoint.get('profile_id') or request.endpoint_profile_id!r} "
                f"allows at most {max_image_inputs} image input(s) per prompt, but this request contains {image_count}."
            )
        effective_max_tokens, request_capacity = bounded_request_output_tokens(
            endpoint,
            messages=normalized_messages,
            native_tools=request.native_tools,
            requested_output_tokens=requested_max_tokens,
        )
        payload: dict[str, Any] = {
            "model": model,
            "messages": normalized_messages,
            "stream": bool(stream),
            token_field: effective_max_tokens,
        }
        if native_tools_enabled:
            payload["tools"] = copy.deepcopy(request.native_tools or [])
            payload["tool_choice"] = "auto"
        for field in ENDPOINT_PROFILE_OPTIONAL_FLOAT_FIELDS + ENDPOINT_PROFILE_OPTIONAL_INT_FIELDS:
            value = endpoint.get(field)
            if value is not None:
                payload[field] = value
        stop_sequences = endpoint.get("stop_sequences")
        if isinstance(stop_sequences, list) and stop_sequences:
            payload["stop"] = list(stop_sequences)
        if model_type in {
            ENDPOINT_MODEL_TYPE_DEEPSEEK_V4, ENDPOINT_MODEL_TYPE_DEEPSEEK_V4_FLASH_VISION_EXP,
            ENDPOINT_MODEL_TYPE_KIMI_K3, ENDPOINT_MODEL_TYPE_GLM_5_3_FLASH,
            ENDPOINT_MODEL_TYPE_QWEN_3_8, ENDPOINT_MODEL_TYPE_QWEN_3_8_FLASH_NEXT,
        }:
            # Baseten's Kimi K3 OpenAI-compatible contract exposes K3 as an
            # always-reasoning model without a reasoning_effort request field.
            # Other configured Kimi/GLM/DeepSeek/Qwen providers retain their existing
            # explicit effort controls.
            if not (model_type == ENDPOINT_MODEL_TYPE_KIMI_K3 and provider == ENDPOINT_PROVIDER_BASETEN):
                payload["reasoning_effort"] = reasoning_level
        elif model_type == ENDPOINT_MODEL_TYPE_CUSTOM and reasoning_level not in {"", "on", "off"}:
            payload["reasoning_effort"] = reasoning_level
        payload.update(parse_endpoint_extra_body(endpoint.get("extra_body_json")))

        # Model-family compatibility is explicit and limited to the published
        # Chat Completions or vLLM chat-template controls for that family.
        if model_type == ENDPOINT_MODEL_TYPE_QWEN_3_6:
            if provider in {ENDPOINT_PROVIDER_VLLM, ENDPOINT_PROVIDER_LLAMA_CPP}:
                self._merge_payload_object(payload, "chat_template_kwargs", {
                    "enable_thinking": reasoning_level == "on",
                })
        elif model_type in {ENDPOINT_MODEL_TYPE_QWEN_3_8, ENDPOINT_MODEL_TYPE_QWEN_3_8_FLASH_NEXT}:
            # Qwen3.8-family models expose xhigh/medium/low reasoning_effort and
            # recommend preserving historical reasoning. vLLM forwards the
            # matching chat-template flags while the top-level effort remains
            # available to the Qwen reasoning parser.
            if provider in {ENDPOINT_PROVIDER_VLLM, ENDPOINT_PROVIDER_LLAMA_CPP}:
                self._merge_payload_object(payload, "chat_template_kwargs", {
                    "enable_thinking": True,
                    "preserve_thinking": bool(preserve_reasoning),
                })
            else:
                payload.setdefault("enable_thinking", True)
                payload.setdefault("preserve_thinking", bool(preserve_reasoning))
        elif model_type == ENDPOINT_MODEL_TYPE_KIMI_K2_6:
            # Instant/off mode is deliberately not exposed for K2.6 because it
            # is unreliable in the deployment targeted by this profile.
            if provider in {ENDPOINT_PROVIDER_VLLM, ENDPOINT_PROVIDER_LLAMA_CPP}:
                self._merge_payload_object(payload, "chat_template_kwargs", {
                    "thinking": True,
                    "preserve_thinking": bool(preserve_reasoning),
                })
            else:
                thinking = {"type": "enabled"}
                if preserve_reasoning:
                    thinking["keep"] = "all"
                payload["thinking"] = thinking
        elif model_type == ENDPOINT_MODEL_TYPE_GLM_5_3_FLASH:
            # Keep GLM's actual low/high/max values, including max on Novita.
            # Do not apply DeepSeek's hosted reasoning-object remapping, or
            # send Z.ai-specific thinking/tool_stream switches to Novita.
            # Only local template servers receive the published template kwargs.
            if provider in {ENDPOINT_PROVIDER_VLLM, ENDPOINT_PROVIDER_LLAMA_CPP}:
                self._merge_payload_object(payload, "chat_template_kwargs", {
                    "reasoning_effort": reasoning_level,
                    "clear_thinking": not preserve_reasoning,
                })
        elif model_type in {
            ENDPOINT_MODEL_TYPE_DEEPSEEK_V4,
            ENDPOINT_MODEL_TYPE_DEEPSEEK_V4_FLASH_VISION_EXP,
        }:
            # DeepSeek V4 Flash supports low, high, and max. The local profile
            # receives vLLM chat-template controls. Novita documents hosted
            # reasoning through a runtime-owned reasoning object; all other
            # compatible hosted endpoints retain the generic thinking shape.
            if provider in {ENDPOINT_PROVIDER_VLLM, ENDPOINT_PROVIDER_LLAMA_CPP}:
                self._merge_payload_object(payload, "chat_template_kwargs", {
                    "thinking": True,
                    "reasoning_effort": reasoning_level,
                })
            elif provider == "novita":
                payload.pop("reasoning_effort", None)
                payload["reasoning"] = {
                    "effort": "high" if reasoning_level in {"high", "max"} else "low",
                }
            else:
                payload["thinking"] = {"type": "enabled"}
        elif model_type == ENDPOINT_MODEL_TYPE_GEMMA_4:
            enabled = reasoning_level == "on"
            if provider in {ENDPOINT_PROVIDER_VLLM, ENDPOINT_PROVIDER_LLAMA_CPP}:
                self._merge_payload_object(payload, "chat_template_kwargs", {
                    "enable_thinking": enabled,
                })
            else:
                payload["thinking"] = {"type": "enabled" if enabled else "disabled"}
        elif model_type == ENDPOINT_MODEL_TYPE_MUSE_GLIMMER:
            # Muse Glimmer exposes reasoning_strength through its chat template.
            # vLLM's OpenAI-compatible server forwards per-request template
            # arguments through chat_template_kwargs; retain the nearby system
            # line as an explicit fallback for compatible hosted gateways.
            if provider in {ENDPOINT_PROVIDER_VLLM, ENDPOINT_PROVIDER_LLAMA_CPP}:
                self._merge_payload_object(payload, "chat_template_kwargs", {
                    "reasoning_strength": reasoning_level,
                })
        elif model_type == ENDPOINT_MODEL_TYPE_CUSTOM and provider in {ENDPOINT_PROVIDER_VLLM, ENDPOINT_PROVIDER_LLAMA_CPP} and preserve_reasoning:
            payload["preserve_thinking"] = True
            payload["clear_thinking"] = False

        if stream and provider in {
            ENDPOINT_PROVIDER_VLLM, ENDPOINT_PROVIDER_LLAMA_CPP,
            ENDPOINT_PROVIDER_OPENAI, ENDPOINT_PROVIDER_NOVITA, ENDPOINT_PROVIDER_BASETEN,
        }:
            existing_stream_options = payload.get("stream_options")
            if not isinstance(existing_stream_options, dict):
                existing_stream_options = {}
            stream_options = dict(existing_stream_options, include_usage=True)
            if provider == ENDPOINT_PROVIDER_BASETEN:
                stream_options["continuous_usage_stats"] = True
            payload["stream_options"] = stream_options
        body = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        effective_user_agent = endpoint_user_agent(endpoint)
        headers = {
            "Content-Type": "application/json",
            "Accept": "text/event-stream, application/json" if stream else "application/json",
            "Accept-Encoding": "identity",
            "User-Agent": effective_user_agent,
        }
        api_key = normalize_endpoint_api_key(endpoint.get("api_key"))
        if api_key:
            headers["Authorization"] = f"Bearer {api_key}"
        fallback_timeout = ENDPOINT_TIMEOUT_SECONDS_DEFAULT
        timeout = bounded_positive_int(endpoint.get("timeout_seconds"), fallback_timeout, minimum=1, maximum=None)
        endpoint = dict(endpoint)
        endpoint["_requested_max_output_tokens"] = bounded_positive_int(requested_max_tokens, 32768, maximum=None)
        endpoint["_effective_max_output_tokens"] = effective_max_tokens
        request_capacity = dict(request_capacity)
        request_capacity["requested_output_tokens"] = endpoint["_requested_max_output_tokens"]
        request_capacity["effective_output_tokens"] = endpoint["_effective_max_output_tokens"]
        request.prepared_capacity.clear()
        request.prepared_capacity.update(request_capacity)
        endpoint["_request_capacity"] = request_capacity
        endpoint["_configured_base_url"] = configured_url
        endpoint["_request_url"] = url
        endpoint["_provider"] = provider
        endpoint["_model_type"] = model_type
        endpoint["_api_key_length"] = len(api_key)
        endpoint["_effective_user_agent"] = effective_user_agent
        return endpoint, url, body, headers, timeout, payload


    def _responses_url(self, base_url: str) -> str:
        """Normalize an API root, /v1 base, chat URL, or Responses endpoint."""
        raw = _strip_matching_outer_quotes(base_url)
        if not raw:
            return ""
        if any(ord(ch) < 32 or ord(ch) == 127 for ch in raw):
            raise ValueError("Endpoint URL contains a control character or line break")
        parts = urllib.parse.urlsplit(raw)
        scheme = str(parts.scheme or "").lower()
        if scheme not in {"http", "https"} or not parts.netloc:
            raise ValueError(
                "Endpoint URL must be an absolute http:// or https:// URL, for example "
                "https://api.openai.com/v1/responses"
            )
        path = str(parts.path or "").rstrip("/")
        lower = path.lower()
        host = str(parts.hostname or "").lower().rstrip(".")
        is_novita = host == "novita.ai" or host.endswith(".novita.ai")
        if lower.endswith("/chat/completion"):
            path = path[:-len("/chat/completion")] + "/responses"
        elif lower.endswith("/chat/completions"):
            path = path[:-len("/chat/completions")] + "/responses"
        elif lower.endswith("/responses"):
            pass
        elif is_novita and lower in {"", "/", "/openai", "/openai/v1", "/v1"}:
            path = "/openai/v1/responses"
        elif lower.endswith("/v1"):
            path = path + "/responses"
        elif lower in {"", "/"}:
            path = "/v1/responses"
        else:
            path = path + "/responses"
        if is_novita and path.lower() in {"/openai/responses", "/v1/responses"}:
            path = "/openai/v1/responses"
        return urllib.parse.urlunsplit((parts.scheme, parts.netloc, path, parts.query, ""))

    def _uses_openai_responses(self, endpoint: dict[str, Any] | None) -> bool:
        return endpoint_api_transport(endpoint) == ENDPOINT_API_TRANSPORT_RESPONSES

    @staticmethod
    def _responses_function_tools(native_tools: list[dict[str, Any]] | None) -> list[dict[str, Any]]:
        """Convert Chat Completions function wrappers to Responses function tools."""
        converted: list[dict[str, Any]] = []
        for row in native_tools or []:
            if not isinstance(row, dict) or str(row.get("type") or "") != "function":
                continue
            fn = row.get("function") if isinstance(row.get("function"), dict) else {}
            name = str(fn.get("name") or "").strip()
            if not name:
                continue
            item: dict[str, Any] = {
                "type": "function",
                "name": name,
                "description": str(fn.get("description") or ""),
                "parameters": copy.deepcopy(fn.get("parameters") or {"type": "object", "properties": {}}),
            }
            if "strict" in fn:
                item["strict"] = bool(fn.get("strict"))
            converted.append(item)
        return converted

    @staticmethod
    def _responses_content_parts(content: Any, *, assistant: bool = False) -> list[dict[str, Any]]:
        """Translate Chat Completions text/image content into Responses content parts."""
        text_type = "output_text" if assistant else "input_text"
        if isinstance(content, str):
            return [{"type": text_type, "text": content}] if content else []
        if not isinstance(content, list):
            text = str(content or "")
            return [{"type": text_type, "text": text}] if text else []
        parts: list[dict[str, Any]] = []
        for part in content:
            if not isinstance(part, dict):
                text = str(part or "")
                if text:
                    parts.append({"type": text_type, "text": text})
                continue
            kind = str(part.get("type") or "")
            if kind in {"text", "input_text", "output_text"}:
                text = str(part.get("text") or "")
                if text:
                    parts.append({"type": text_type, "text": text})
            elif kind in {"image_url", "input_image"} and not assistant:
                image_url = part.get("image_url")
                if isinstance(image_url, dict):
                    image_url = image_url.get("url")
                url = str(image_url or part.get("url") or "").strip()
                if url:
                    image_part: dict[str, Any] = {"type": "input_image", "image_url": url}
                    detail = str(part.get("detail") or "").strip()
                    if not detail and isinstance(part.get("image_url"), dict):
                        detail = str(part.get("image_url", {}).get("detail") or "").strip()
                    if detail:
                        image_part["detail"] = detail
                    parts.append(image_part)
        return parts

    def _responses_input_and_instructions(
        self, messages: list[dict[str, Any]],
    ) -> tuple[list[dict[str, Any]], str]:
        """Build stateless Responses input while preserving returned reasoning items."""
        instructions: list[str] = []
        input_items: list[dict[str, Any]] = []
        for message in messages or []:
            if not isinstance(message, dict):
                continue
            role = str(message.get("role") or "user")
            content = message.get("content", "")
            if role in {"system", "developer"}:
                text = content if isinstance(content, str) else json.dumps(content, ensure_ascii=False, default=str)
                if str(text).strip():
                    instructions.append(str(text).strip())
                continue
            if role == "tool":
                call_id = str(message.get("tool_call_id") or "").strip()
                if call_id:
                    output = content if isinstance(content, str) else json.dumps(content, ensure_ascii=False, default=str)
                    input_items.append({
                        "type": "function_call_output",
                        "call_id": call_id,
                        "output": str(output),
                    })
                continue
            if role == "assistant":
                preserved = message.get("response_output_items")
                if isinstance(preserved, list) and preserved:
                    input_items.extend(canonicalize_responses_output_items(
                        [item for item in preserved if isinstance(item, dict)]
                    ))
                    continue
                assistant_parts = self._responses_content_parts(content, assistant=True)
                if assistant_parts:
                    input_items.append({"type": "message", "role": "assistant", "content": assistant_parts})
                for call in message.get("tool_calls") or []:
                    if not isinstance(call, dict):
                        continue
                    fn = call.get("function") if isinstance(call.get("function"), dict) else {}
                    call_id = str(call.get("id") or "").strip()
                    name = str(fn.get("name") or "").strip()
                    if call_id and name:
                        arguments = fn.get("arguments")
                        if not isinstance(arguments, str):
                            arguments = json.dumps(arguments or {}, ensure_ascii=False, separators=(",", ":"))
                        input_items.append({
                            "type": "function_call",
                            "call_id": call_id,
                            "name": name,
                            "arguments": arguments,
                        })
                continue
            user_parts = self._responses_content_parts(content, assistant=False)
            if user_parts:
                input_items.append({"type": "message", "role": "user", "content": user_parts})
        return input_items, "\n\n".join(instructions)

    @staticmethod
    def _responses_reasoning_config(
        endpoint: dict[str, Any], reasoning_level: str, provider: str,
    ) -> dict[str, Any] | None:
        """Build a conservative Responses reasoning object for the selected family."""
        model_type = normalize_endpoint_model_type(endpoint.get("model_type"))
        level = str(reasoning_level or "").strip().lower()
        if level in {"", "off"}:
            return None
        if level == "on":
            level = "high"
        config: dict[str, Any] = {"effort": level, "summary": "auto"}
        if provider == "openai" and model_type in ENDPOINT_GPT_5_6_MODEL_TYPES:
            config.update({"mode": "pro", "context": "all_turns"})
        return config

    def _responses_payload_and_headers(
        self, request: LLMRequest, *, stream: bool,
    ) -> tuple[dict[str, Any], str, bytes, dict[str, str], int, dict[str, Any]]:
        request.prepared_capacity.clear()
        endpoint = self.resolve_endpoint(request.endpoint_profile_id)
        configured_url = _strip_matching_outer_quotes(endpoint.get("base_url"))
        model = _strip_matching_outer_quotes(endpoint.get("model"))
        if any(ord(ch) < 32 or ord(ch) == 127 for ch in model):
            raise ValueError("Model ID contains a control character or line break")
        url = self._responses_url(configured_url)
        provider = endpoint_provider_name(url, endpoint.get("provider"))
        model_type = normalize_endpoint_model_type(endpoint.get("model_type"))
        endpoint_messages = prepend_endpoint_system_prompt_addon(request.messages, endpoint)
        input_items, instructions = self._responses_input_and_instructions(endpoint_messages)
        image_count = message_image_input_count(endpoint_messages)
        max_image_inputs = endpoint_max_image_inputs(endpoint)
        if image_count > max_image_inputs:
            raise ValueError(
                f"Endpoint profile {endpoint.get('profile_label') or endpoint.get('profile_id') or request.endpoint_profile_id!r} "
                f"allows at most {max_image_inputs} image input(s) per prompt, but this request contains {image_count}."
            )
        requested_max_tokens = request.max_output_tokens if request.max_output_tokens is not None else endpoint.get("max_output_tokens")
        reasoning_level = endpoint_effective_reasoning_level(endpoint, request.reasoning_effort_override)
        effective_max_tokens, request_capacity = bounded_request_output_tokens(
            endpoint,
            messages=[{"content": instructions}, *[{"content": [item]} for item in input_items]],
            native_tools=self._responses_function_tools(request.native_tools),
            requested_output_tokens=requested_max_tokens,
        )
        payload: dict[str, Any] = {
            "model": model,
            "input": input_items,
            "stream": bool(stream),
            "max_output_tokens": effective_max_tokens,
            "store": False,
        }
        if instructions:
            payload["instructions"] = instructions
        reasoning_config = self._responses_reasoning_config(endpoint, reasoning_level, provider)
        if reasoning_config:
            payload["reasoning"] = reasoning_config
            if provider == "openai":
                payload["include"] = ["reasoning.encrypted_content"]
        response_tools = self._responses_function_tools(request.native_tools)
        if response_tools:
            payload["tools"] = response_tools
            payload["tool_choice"] = "auto"
        payload.update(parse_endpoint_extra_body(endpoint.get("extra_body_json")))
        body = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        effective_user_agent = endpoint_user_agent(endpoint)
        headers = {
            "Content-Type": "application/json",
            "Accept": "text/event-stream, application/json" if stream else "application/json",
            "Accept-Encoding": "identity",
            "User-Agent": effective_user_agent,
        }
        api_key = normalize_endpoint_api_key(endpoint.get("api_key"))
        if api_key:
            headers["Authorization"] = f"Bearer {api_key}"
        timeout = bounded_positive_int(
            endpoint.get("timeout_seconds"), ENDPOINT_TIMEOUT_SECONDS_DEFAULT, minimum=1, maximum=None,
        )
        endpoint = dict(endpoint)
        endpoint["_requested_max_output_tokens"] = bounded_positive_int(requested_max_tokens, 32768, maximum=None)
        endpoint["_effective_max_output_tokens"] = effective_max_tokens
        request_capacity = dict(request_capacity)
        request_capacity["requested_output_tokens"] = endpoint["_requested_max_output_tokens"]
        request_capacity["effective_output_tokens"] = endpoint["_effective_max_output_tokens"]
        request.prepared_capacity.clear()
        request.prepared_capacity.update(request_capacity)
        endpoint["_request_capacity"] = request_capacity
        endpoint["_configured_base_url"] = configured_url
        endpoint["_request_url"] = url
        endpoint["_provider"] = provider
        endpoint["_model_type"] = model_type
        endpoint["_api_key_length"] = len(api_key)
        endpoint["_effective_user_agent"] = effective_user_agent
        endpoint["_api_transport"] = ENDPOINT_API_TRANSPORT_RESPONSES
        return endpoint, url, body, headers, timeout, payload

    def _payload_and_headers(
        self, request: LLMRequest, *, stream: bool,
    ) -> tuple[dict[str, Any], str, bytes, dict[str, str], int, dict[str, Any]]:
        endpoint = self.resolve_endpoint(request.endpoint_profile_id)
        if self._uses_openai_responses(endpoint):
            return self._responses_payload_and_headers(request, stream=stream)
        return self._chat_payload_and_headers(request, stream=stream)

    @staticmethod
    def _responses_reasoning_summary(item: dict[str, Any]) -> str:
        parts: list[str] = []
        for row in item.get("summary") or []:
            if isinstance(row, dict):
                text = str(row.get("text") or row.get("summary_text") or "").strip()
            else:
                text = str(row or "").strip()
            if text:
                parts.append(text)
        return "\n\n".join(parts)

    def _responses_parse_output(
        self, raw: dict[str, Any],
    ) -> tuple[str, str, list[dict[str, Any]], list[dict[str, Any]], dict[str, Any], str, str]:
        raw_output = raw.get("output") if isinstance(raw.get("output"), list) else []
        output = canonicalize_responses_output_items(
            [item for item in raw_output if isinstance(item, dict)]
        )
        text_parts: list[str] = []
        reasoning_parts: list[str] = []
        tool_calls: list[dict[str, Any]] = []
        for item in output:
            if not isinstance(item, dict):
                continue
            kind = str(item.get("type") or "")
            if kind == "reasoning":
                summary = self._responses_reasoning_summary(item)
                if summary:
                    reasoning_parts.append(summary)
            elif kind == "function_call":
                call_id = str(item.get("call_id") or item.get("id") or "").strip()
                name = str(item.get("name") or "").strip()
                arguments = item.get("arguments")
                if not isinstance(arguments, str):
                    arguments = json.dumps(arguments or {}, ensure_ascii=False, separators=(",", ":"))
                if call_id and name:
                    tool_calls.append({
                        "id": call_id,
                        "type": "function",
                        "function": {"name": name, "arguments": arguments},
                    })
            elif kind == "message":
                content_rows = item.get("content") if isinstance(item.get("content"), list) else []
                for part in content_rows:
                    if not isinstance(part, dict):
                        continue
                    part_kind = str(part.get("type") or "")
                    if part_kind == "output_text":
                        text = provider_visible_text(part.get("text"))
                        if text:
                            text_parts.append(text)
                    elif part_kind == "refusal":
                        refusal = provider_visible_text(part.get("refusal"))
                        if refusal:
                            text_parts.append(refusal)
        usage = raw.get("usage") if isinstance(raw.get("usage"), dict) else {}
        status = str(raw.get("status") or "").lower()
        incomplete = raw.get("incomplete_details") if isinstance(raw.get("incomplete_details"), dict) else {}
        stop_reason = str(incomplete.get("reason") or "")
        canonical_calls = canonicalize_provider_tool_calls(tool_calls)
        if status in {"incomplete", "failed", "cancelled", "canceled"}:
            finish_reason = status
        elif canonical_calls:
            finish_reason = "tool_calls"
        else:
            finish_reason = "stop" if status in {"", "completed"} else status
        return (
            normalize_known_provider_output_artifacts("".join(text_parts)),
            "\n\n".join(reasoning_parts),
            canonical_calls,
            copy.deepcopy(output),
            copy.deepcopy(usage),
            finish_reason,
            stop_reason,
        )


    @staticmethod
    def _close_response_transport(response: Any) -> None:
        """Run off-loop; interrupt an owned urllib read before buffered close.

        HTTPResponse owns fp.raw._sock; HTTPError wraps that response in fp.
        Opaque adapters retain best-effort close without assuming a socket API.

        On Windows a ``shutdown(SHUT_RDWR)`` does not wake a blocked ``recv``
        when the socket is wrapped by a ``makefile`` BufferedReader: the reader
        holds the reader lock while blocked, so ``response.close()`` would wait
        on that lock.  The owned socket descriptor is detached exactly once and
        closed with the pointer-width Winsock binding; the blocked read is
        interrupted and the descriptor is reclaimed without risking closing a
        descriptor that has since been reused by another connection.
        """
        current = response
        for _ in range(2):
            try:
                fp = getattr(current, "fp", None)
                sock = getattr(getattr(fp, "raw", None), "_sock", None)
                if isinstance(sock, socket.socket):
                    try:
                        sock.shutdown(socket.SHUT_RDWR)
                    except OSError:
                        pass  # Already closed, reset, or concurrently completed.
                    _interrupt_blocked_socket(sock)
                    break
                current = fp
            except Exception:
                break
        try:
            response.close()
        except Exception:
            pass

    async def _responses_stream(self, request: LLMRequest):
        """Stream first-party OpenAI Responses events into Velox's shared chunk model."""
        endpoint, url, body, headers, timeout, payload = self._responses_payload_and_headers(request, stream=True)
        response_max_bytes = self.response_max_bytes()
        error_body_max_bytes = self.error_body_max_bytes()
        loop = asyncio.get_running_loop()
        bridge = LLMStreamChunkBridge(loop)
        q = bridge.queue
        consumer_stopped = threading.Event()
        external_cancel_event = request.cancel_event
        worker_done = threading.Event()
        response_lock = threading.RLock()
        response_holder: dict[str, Any] = {"response": None}
        close_dispatched = threading.Event()

        def request_cancelled() -> bool:
            return consumer_stopped.is_set() or bool(external_cancel_event and external_cancel_event.is_set())

        def close_active_response() -> None:
            with response_lock:
                response = response_holder.get("response")
            if response is not None:
                self._close_response_transport(response)

        def dispatch_close_active_response() -> None:
            """Close urllib response on a daemon worker; response.close can block on Windows."""
            with response_lock:
                if close_dispatched.is_set():
                    return
                close_dispatched.set()
            threading.Thread(
                target=close_active_response,
                name="velox-llm-response-close",
                daemon=True,
            ).start()

        def put(chunk: LLMChunk | None) -> None:
            if consumer_stopped.is_set():
                return
            if chunk is None:
                bridge.close()
            elif deadline.observe(chunk):
                bridge.publish(chunk)

        def worker() -> None:
            usage: dict[str, Any] = {}
            reasoning_open = False
            saw_valid_payload = False
            response_headers: Any = None
            response_status = 200
            response_url = url
            finish_reason = ""
            stop_reason = ""
            emitted_text = AppendOnlyTextAccumulator()
            emitted_reasoning = AppendOnlyTextAccumulator()
            content_filter = TrailingKnownProviderArtifactFilter()
            output_items: dict[int, dict[str, Any]] = {}
            completed_response: dict[str, Any] | None = None
            last_prompt_progress: tuple[float | None, int | None, int | None] = (None, None, None)

            def publish_prompt_progress(source: Any) -> None:
                nonlocal last_prompt_progress
                snapshot = llm_prompt_progress_snapshot(source)
                if snapshot == last_prompt_progress or snapshot[0] is None:
                    return
                last_prompt_progress = snapshot
                put(LLMChunk(
                    prompt_progress_percent=snapshot[0],
                    prompt_tokens_processed=snapshot[1],
                    prompt_tokens_total=snapshot[2],
                ))

            def protocol_error(reason: str, raw_bytes: bytes) -> LLMEndpointError:
                return self._endpoint_error(
                    None, endpoint=endpoint, url=url, headers=headers, timeout=timeout,
                    payload=payload, stream=True, status_code=response_status, reason=reason,
                    response_headers=response_headers, response_body_bytes=raw_bytes,
                    final_url=response_url,
                )

            def emit_reasoning_piece(piece: Any) -> None:
                nonlocal reasoning_open
                text = str(piece or "")
                if not text:
                    return
                if not reasoning_open:
                    put(LLMChunk(text="<think>\n", meaningful_progress=False))
                    reasoning_open = True
                put(LLMChunk(text=text, reasoning_text=text))

            def emit_content_wire_piece(piece: Any) -> None:
                nonlocal reasoning_open
                safe_piece = content_filter.feed(piece)
                if not safe_piece:
                    return
                if reasoning_open:
                    put(LLMChunk(text="\n</think>\n", meaningful_progress=False))
                    reasoning_open = False
                put(LLMChunk(text=safe_piece))

            def emit_content_delta(value: Any) -> None:
                piece = emitted_text.append_delta(value)
                if piece:
                    emit_content_wire_piece(piece)

            def emit_content_snapshot(value: Any) -> None:
                piece = emitted_text.accept_snapshot(value)
                if piece:
                    emit_content_wire_piece(piece)

            def emit_reasoning_delta(value: Any) -> None:
                piece = emitted_reasoning.append_delta(value)
                if piece:
                    emit_reasoning_piece(piece)

            def emit_reasoning_snapshot(value: Any) -> None:
                # Do not append previously unseen reasoning *after* visible answer
                # text. A terminal snapshot may contain both sections even when a
                # gateway only streamed answer deltas. Preserve chronological UI.
                if emitted_text.total_chars and not reasoning_open:
                    return
                piece = emitted_reasoning.accept_snapshot(value)
                if piece:
                    emit_reasoning_piece(piece)

            def finish_visible_stream() -> None:
                nonlocal reasoning_open
                tail = content_filter.finish()
                if tail:
                    if reasoning_open:
                        put(LLMChunk(text="\n</think>\n", meaningful_progress=False))
                        reasoning_open = False
                    put(LLMChunk(text=tail))
                if reasoning_open:
                    put(LLMChunk(text="\n</think>\n", meaningful_progress=False))
                    reasoning_open = False

            def item_index_for_event(obj: dict[str, Any]) -> int:
                raw_index = obj.get("output_index")
                if isinstance(raw_index, int) and raw_index >= 0:
                    return raw_index
                item_id = str(obj.get("item_id") or "")
                if item_id:
                    for index, item in output_items.items():
                        if str(item.get("id") or "") == item_id:
                            return index
                return max(output_items.keys(), default=-1) + 1

            def current_calls() -> list[dict[str, Any]]:
                calls: list[dict[str, Any]] = []
                for index in sorted(output_items):
                    item = output_items[index]
                    if str(item.get("type") or "") != "function_call":
                        continue
                    call_id = str(item.get("call_id") or item.get("id") or f"response_call_{index}")
                    name = str(item.get("name") or "")
                    arguments = item.get("arguments")
                    if not isinstance(arguments, str):
                        arguments = json.dumps(arguments or {}, ensure_ascii=False, separators=(",", ":"))
                    calls.append({
                        "id": call_id,
                        "type": "function",
                        "function": {"name": name, "arguments": arguments},
                    })
                return canonicalize_provider_tool_calls(calls)

            def publish_calls() -> None:
                calls = current_calls()
                if calls:
                    put(LLMChunk(
                        native_tool_calls=calls,
                        response_output_items=[copy.deepcopy(output_items[i]) for i in sorted(output_items)],
                    ))

            def reconcile_item_snapshot(item: dict[str, Any]) -> None:
                kind = str(item.get("type") or "")
                if kind == "message":
                    parsed_text, _parsed_reasoning, _calls, _items, _usage, _finish, _stop = self._responses_parse_output({
                        "status": "completed", "output": [item],
                    })
                    if parsed_text:
                        emit_content_snapshot(parsed_text)
                elif kind == "reasoning":
                    summary = self._responses_reasoning_summary(item)
                    if summary:
                        emit_reasoning_snapshot(summary)

            def process_event(obj: Any, raw_bytes: bytes) -> None:
                nonlocal usage, saw_valid_payload, finish_reason, stop_reason, completed_response
                if not isinstance(obj, dict):
                    raise protocol_error("Responses streaming event was not an object", raw_bytes)
                provider_error = self._payload_error_value(obj)
                event_type = str(obj.get("type") or "")
                if provider_error is not None and event_type not in {"response.failed", "error"}:
                    raise protocol_error("Provider returned an error object", raw_bytes)
                saw_valid_payload = True
                publish_prompt_progress(obj)
                event_response = obj.get("response") if isinstance(obj.get("response"), dict) else {}
                event_usage = obj.get("usage") or event_response.get("usage")
                if isinstance(event_usage, dict):
                    usage = update_llm_usage_snapshot(usage, event_usage)
                    put(LLMChunk(usage=usage))
                if event_type in {"response.output_text.delta", "response.refusal.delta"}:
                    emit_content_delta(obj.get("delta"))
                elif event_type in {"response.output_text.done", "response.refusal.done"}:
                    done_value = obj.get("text")
                    if done_value is None:
                        done_value = obj.get("refusal")
                    if done_value is None:
                        done_value = obj.get("delta")
                    emit_content_snapshot(done_value)
                elif event_type in {"response.reasoning_summary_text.delta", "response.reasoning_text.delta"}:
                    emit_reasoning_delta(obj.get("delta"))
                elif event_type in {"response.reasoning_summary_text.done", "response.reasoning_text.done"}:
                    emit_reasoning_snapshot(obj.get("text") if obj.get("text") is not None else obj.get("delta"))
                elif event_type == "response.output_item.added":
                    item = obj.get("item") if isinstance(obj.get("item"), dict) else {}
                    index = item_index_for_event(obj)
                    output_items[index] = copy.deepcopy(item)
                    reconcile_item_snapshot(item)
                    publish_calls()
                elif event_type == "response.output_item.done":
                    item = obj.get("item") if isinstance(obj.get("item"), dict) else {}
                    index = item_index_for_event(obj)
                    output_items[index] = copy.deepcopy(item)
                    reconcile_item_snapshot(item)
                    publish_calls()
                elif event_type == "response.function_call_arguments.delta":
                    index = item_index_for_event(obj)
                    item = output_items.setdefault(index, {
                        "type": "function_call",
                        "id": str(obj.get("item_id") or f"response_item_{index}"),
                        "call_id": str(obj.get("call_id") or obj.get("item_id") or f"response_call_{index}"),
                        "name": str(obj.get("name") or ""),
                        "arguments": "",
                    })
                    if obj.get("name") and not item.get("name"):
                        item["name"] = str(obj.get("name"))
                    item["arguments"] = str(item.get("arguments") or "") + str(obj.get("delta") or "")
                    publish_calls()
                elif event_type == "response.function_call_arguments.done":
                    index = item_index_for_event(obj)
                    item = output_items.setdefault(index, {
                        "type": "function_call",
                        "id": str(obj.get("item_id") or f"response_item_{index}"),
                        "call_id": str(obj.get("call_id") or obj.get("item_id") or f"response_call_{index}"),
                        "name": str(obj.get("name") or ""),
                    })
                    if obj.get("name") and not item.get("name"):
                        item["name"] = str(obj.get("name"))
                    if obj.get("arguments") is not None:
                        item["arguments"] = str(obj.get("arguments") or "")
                    publish_calls()
                elif event_type in {
                    "response.completed", "response.incomplete", "response.failed",
                    "response.cancelled", "response.canceled",
                }:
                    response = obj.get("response") if isinstance(obj.get("response"), dict) else obj
                    completed_response = copy.deepcopy(response)
                    parsed_text, parsed_reasoning, calls, items, parsed_usage, parsed_finish, parsed_stop = self._responses_parse_output(response)
                    usage = update_llm_usage_snapshot(usage, parsed_usage)
                    finish_reason = parsed_finish
                    stop_reason = parsed_stop
                    if items:
                        output_items.clear()
                        output_items.update({index: copy.deepcopy(item) for index, item in enumerate(items)})
                    if parsed_reasoning:
                        emit_reasoning_snapshot(parsed_reasoning)
                    if parsed_text:
                        emit_content_snapshot(parsed_text)
                    if calls:
                        publish_calls()
                    if event_type == "response.failed":
                        error_obj = response.get("error") if isinstance(response.get("error"), dict) else {}
                        message = str(error_obj.get("message") or "OpenAI Responses request failed")
                        raise protocol_error(message, raw_bytes)
                    if event_type in {"response.cancelled", "response.canceled"}:
                        raise protocol_error("OpenAI Responses request was cancelled by the provider", raw_bytes)
                elif event_type == "error":
                    raw_error = obj.get("error")
                    error_message = (
                        str(raw_error.get("message") or "")
                        if isinstance(raw_error, dict)
                        else str(raw_error or "")
                    )
                    message = str(obj.get("message") or error_message or "OpenAI Responses stream error")
                    raise protocol_error(message, raw_bytes)
                elif not event_type and isinstance(obj.get("output"), list):
                    completed_response = copy.deepcopy(obj)
                    parsed_text, parsed_reasoning, calls, items, parsed_usage, parsed_finish, parsed_stop = self._responses_parse_output(obj)
                    usage = update_llm_usage_snapshot(usage, parsed_usage)
                    finish_reason = parsed_finish
                    stop_reason = parsed_stop
                    output_items.clear()
                    output_items.update({index: copy.deepcopy(item) for index, item in enumerate(items)})
                    if parsed_reasoning:
                        emit_reasoning_snapshot(parsed_reasoning)
                    if parsed_text:
                        emit_content_snapshot(parsed_text)
                    if calls:
                        publish_calls()

            try:
                if request_cancelled():
                    raise LLMRequestCancelledError("Endpoint request cancelled before connection")
                req = urllib.request.Request(url, data=body, headers=headers, method="POST")
                with urllib.request.urlopen(req, timeout=timeout) as resp:
                    with response_lock:
                        response_holder["response"] = resp
                    if request_cancelled():
                        raise LLMRequestCancelledError("Endpoint request cancelled")
                    response_headers = getattr(resp, "headers", None)
                    try:
                        response_status = int(getattr(resp, "status", 0) or resp.getcode() or 200)
                    except Exception:
                        response_status = 200
                    try:
                        response_url = str(resp.geturl() or url)
                    except Exception:
                        response_url = url
                    if response_status < 200 or response_status >= 300:
                        response_body = resp.read(error_body_max_bytes + 1)
                        raise self._endpoint_error(
                            None, endpoint=endpoint, url=url, headers=headers, timeout=timeout,
                            payload=payload, stream=True, status_code=response_status,
                            reason="Endpoint returned a non-success HTTP status",
                            response_headers=response_headers, response_body_bytes=response_body,
                            final_url=response_url,
                        )
                    saw_sse_frame = False
                    saw_done_frame = False
                    for frame_kind, frame_bytes in iter_openai_compatible_stream_frames(
                        resp, response_max_bytes=response_max_bytes, cancelled=request_cancelled,
                    ):
                        if frame_kind == "done":
                            saw_done_frame = True
                            break
                        if frame_kind == "sse":
                            saw_sse_frame = True
                            try:
                                obj = json.loads(frame_bytes.decode("utf-8"))
                            except Exception as parse_exc:
                                raise protocol_error(
                                    "Responses SSE data event was not valid JSON", frame_bytes,
                                ) from parse_exc
                            process_event(obj, frame_bytes)
                        else:
                            try:
                                payloads = parse_openai_raw_json_payloads(frame_bytes)
                            except Exception as parse_exc:
                                raise protocol_error(
                                    "HTTP 200 response was not valid Responses JSON or strict NDJSON", frame_bytes,
                                ) from parse_exc
                            for obj in payloads:
                                process_event(obj, frame_bytes)
                    if not saw_valid_payload or (saw_sse_frame and not saw_done_frame and completed_response is None):
                        raise LLMEndpointError(
                            "Endpoint connection closed before a complete provider response",
                            endpoint_profile_id=request.endpoint_profile_id, reason="connection_closed",
                            response_headers=response_headers,
                        )
                finish_visible_stream()
                final_items = [copy.deepcopy(output_items[index]) for index in sorted(output_items)]
                final_calls = current_calls()
                if completed_response is not None and not final_items:
                    parsed_text, parsed_reasoning, final_calls, final_items, parsed_usage, parsed_finish, parsed_stop = self._responses_parse_output(completed_response)
                    usage = update_llm_usage_snapshot(usage, parsed_usage)
                    finish_reason = parsed_finish or finish_reason
                    stop_reason = parsed_stop or stop_reason
                    if parsed_reasoning:
                        emit_reasoning_snapshot(parsed_reasoning)
                    if parsed_text:
                        emit_content_snapshot(parsed_text)
                if final_calls and not finish_reason:
                    finish_reason = "tool_calls"
                if not request_cancelled():
                    observe_endpoint_prompt_usage(self.storage, endpoint, usage)
                termination_error = llm_endpoint_termination_error(finish_reason, stop_reason)
                put(LLMChunk(
                    done=True,
                    error=str(termination_error) if termination_error else None,
                    endpoint_failure=endpoint_failure_metadata(termination_error) if termination_error else None,
                    usage=usage,
                    finish_reason=finish_reason or ("tool_calls" if final_calls else "stop"),
                    stop_reason=stop_reason or None,
                    native_tool_calls=final_calls or None,
                    response_output_items=final_items or None,
                ))
            except Exception as exc:
                try:
                    finish_visible_stream()
                except Exception:
                    pass
                error: BaseException = exc
                if request_cancelled() or isinstance(exc, LLMRequestCancelledError):
                    error = LLMRequestCancelledError(f"Endpoint profile '{request.endpoint_profile_id}' request was cancelled")
                elif isinstance(exc, LLMEndpointError):
                    error = exc
                elif is_timeout_exception(exc):
                    error = LLMRequestTimeoutError(
                        str(endpoint.get("profile_id") or request.endpoint_profile_id), timeout,
                        f"{type(exc).__name__}: {exc}; URL: {safe_endpoint_url(url)}",
                    )
                else:
                    error = self._endpoint_error(
                        exc, endpoint=endpoint, url=url, headers=headers, timeout=timeout,
                        payload=payload, stream=True, response_headers=response_headers,
                        final_url=response_url,
                    )
                put(LLMChunk(
                    error=f"{type(error).__name__}: {error}", done=True, usage=usage,
                    endpoint_failure=endpoint_failure_metadata(error),
                    model_output_observed=llm_error_has_partial_output(error),
                    finish_reason=finish_reason or None, stop_reason=stop_reason or None,
                    # A failed provider stream is non-executable. Preserve output
                    # items for diagnostics/replay inspection, but never attach a
                    # partial native-call batch to the terminal error chunk.
                    native_tool_calls=None,
                    response_output_items=[copy.deepcopy(output_items[i]) for i in sorted(output_items)] or None,
                ))
            finally:
                with response_lock:
                    response_holder["response"] = None
                worker_done.set()
                put(None)

        if external_cancel_event is not None:
            def cancellation_watcher() -> None:
                while not worker_done.wait(0.05):
                    if consumer_stopped.is_set():
                        return
                    if external_cancel_event.is_set():
                        dispatch_close_active_response()
                        return
            threading.Thread(target=cancellation_watcher, daemon=True).start()
        deadline = LLMRequestDeadline(request.endpoint_profile_id, timeout)
        threading.Thread(target=worker, daemon=True).start()
        try:
            while True:
                try:
                    chunk = await deadline.next_chunk(q, request_cancelled)
                except LLMRequestCancelledError as exc:
                    consumer_stopped.set()
                    dispatch_close_active_response()
                    yield LLMChunk(error=f"LLMRequestCancelledError: {exc}", done=True)
                    break
                except LLMRequestTimeoutError as exc:
                    # Do not cancel the Chat task: this is an endpoint failure,
                    # not user Stop. The outer owner can safely retry empty output.
                    consumer_stopped.set()
                    dispatch_close_active_response()
                    yield LLMChunk(error=f"LLMRequestTimeoutError: {exc}", done=True, model_output_observed=deadline.model_output_observed)
                    break
                if chunk is None:
                    break
                yield chunk
                await asyncio.sleep(0)
                if chunk.done:
                    break
        finally:
            consumer_stopped.set()
            dispatch_close_active_response()

    async def _chat_completions_stream_unqueued(self, request: LLMRequest):
        # Chat Completions remains the default and primary compatibility transport.
        # Endpoint profiles explicitly opt into Responses when the configured service supports it.
        endpoint = self.resolve_endpoint(request.endpoint_profile_id)
        if self._uses_openai_responses(endpoint):
            async with contextlib.aclosing(self._responses_stream(request)) as owned_stream:
                async for chunk in owned_stream:
                    yield chunk
            return
        if not str(endpoint.get("base_url") or "").strip() or not str(endpoint.get("model") or "").strip():
            # No configured endpoint means no assistant prose. The UI displays a
            # warning banner; background summaries simply skip.
            yield LLMChunk(done=True, usage={"no_endpoint_configured": True, "endpoint_profile_id": endpoint.get("profile_id", request.endpoint_profile_id)})
            return

        endpoint, url, body, headers, timeout, payload = self._payload_and_headers(request, stream=True)
        response_max_bytes = self.response_max_bytes()
        error_body_max_bytes = self.error_body_max_bytes()
        loop = asyncio.get_running_loop()
        bridge = LLMStreamChunkBridge(loop)
        q = bridge.queue
        consumer_stopped = threading.Event()
        external_cancel_event = request.cancel_event
        worker_done = threading.Event()
        response_lock = threading.RLock()
        response_holder: dict[str, Any] = {"response": None}
        close_dispatched = threading.Event()

        def request_cancelled() -> bool:
            return consumer_stopped.is_set() or bool(external_cancel_event and external_cancel_event.is_set())

        def close_active_response() -> None:
            with response_lock:
                response = response_holder.get("response")
            if response is not None:
                self._close_response_transport(response)

        def dispatch_close_active_response() -> None:
            """Close urllib response on a daemon worker; response.close can block on Windows."""
            with response_lock:
                if close_dispatched.is_set():
                    return
                close_dispatched.set()
            threading.Thread(
                target=close_active_response,
                name="velox-llm-response-close",
                daemon=True,
            ).start()

        def put(chunk: LLMChunk | None) -> None:
            if consumer_stopped.is_set():
                return
            if chunk is None:
                bridge.close()
            elif deadline.observe(chunk):
                bridge.publish(chunk)

        def worker() -> None:
            usage: dict[str, Any] | None = None
            reasoning_open = False
            emitted_reasoning = AppendOnlyTextAccumulator()
            scalar_reasoning = AppendOnlyTextAccumulator()
            structured_reasoning = StructuredReasoningAccumulator()
            reasoning_channel = ""
            provider_message_fields: set[str] = set()

            def diagnostics() -> dict[str, Any]:
                return {
                    "transport": "chat_completions", "stream": True,
                    "provider_message_fields": sorted(provider_message_fields),
                    "reasoning_text_chars": emitted_reasoning.total_chars,
                    "scalar_reasoning_chars": scalar_reasoning.total_chars,
                    "reasoning_packet_types": sorted({str(row.get("type") or "")[:80] for row in structured_reasoning.rows.values()}),
                    "reasoning_packet_count": len(structured_reasoning.rows),
                    "reported_reasoning_tokens": llm_reported_reasoning_tokens(usage),
                }

            def final_reasoning_fields() -> dict[str, Any]:
                fields: dict[str, Any] = {}
                if scalar_reasoning.total_chars:
                    fields["reasoning_content"] = scalar_reasoning.materialize()
                if structured_reasoning.rows:
                    fields["reasoning_details"] = structured_reasoning.snapshot()
                return fields

            emitted_content = AppendOnlyTextAccumulator()
            content_filter = TrailingKnownProviderArtifactFilter()
            provider_tool_fragments: dict[str, dict[str, str]] = {}
            saw_valid_payload = False
            response_headers: Any = None
            response_status = 200
            response_url = url
            finish_reason = ""
            stop_reason = ""
            last_prompt_progress: tuple[float | None, int | None, int | None] = (None, None, None)

            def publish_prompt_progress(source: Any) -> None:
                nonlocal last_prompt_progress
                snapshot = llm_prompt_progress_snapshot(source)
                if snapshot == last_prompt_progress or snapshot[0] is None:
                    return
                last_prompt_progress = snapshot
                put(LLMChunk(
                    prompt_progress_percent=snapshot[0],
                    prompt_tokens_processed=snapshot[1],
                    prompt_tokens_total=snapshot[2],
                ))

            def protocol_error(reason: str, raw_bytes: bytes) -> LLMEndpointError:
                return self._endpoint_error(
                    None,
                    endpoint=endpoint,
                    url=url,
                    headers=headers,
                    timeout=timeout,
                    payload=payload,
                    stream=True,
                    status_code=response_status,
                    reason=reason,
                    response_headers=response_headers,
                    response_body_bytes=raw_bytes,
                    final_url=response_url,
                )

            def first_meaningful(container: dict[str, Any], *names: str) -> Any:
                for name in names:
                    if name not in container:
                        continue
                    value = container.get(name)
                    if value is None:
                        continue
                    if isinstance(value, str) and value == "":
                        continue
                    if isinstance(value, (list, dict)) and not value:
                        continue
                    return value
                return None

            def emit_content_wire_piece(piece: Any) -> None:
                nonlocal reasoning_open
                safe_piece = content_filter.feed(piece)
                if not safe_piece:
                    return
                if reasoning_open:
                    put(LLMChunk(text="\n</think>\n", meaningful_progress=False))
                    reasoning_open = False
                put(LLMChunk(text=safe_piece))

            def finish_visible_stream() -> None:
                nonlocal reasoning_open
                tail = content_filter.finish()
                if tail:
                    if reasoning_open:
                        put(LLMChunk(text="\n</think>\n", meaningful_progress=False))
                        reasoning_open = False
                    put(LLMChunk(text=tail))
                if reasoning_open:
                    put(LLMChunk(text="\n</think>\n", meaningful_progress=False))
                    reasoning_open = False

            def process_object(obj: Any, raw_bytes: bytes) -> None:
                nonlocal usage, reasoning_open, saw_valid_payload
                nonlocal finish_reason, stop_reason, reasoning_channel
                if not isinstance(obj, dict):
                    raise protocol_error("HTTP response JSON was not an object", raw_bytes)
                provider_error = self._payload_error_value(obj)
                if provider_error is not None:
                    raise protocol_error("Provider returned an error object", raw_bytes)
                saw_valid_payload = True
                publish_prompt_progress(obj)
                if isinstance(obj.get("usage"), dict):
                    usage = update_llm_usage_snapshot(usage or {}, obj.get("usage"))
                    put(LLMChunk(usage=usage))
                if accumulate_provider_tool_call_attempt(provider_tool_fragments, obj):
                    try:
                        calls = provider_tool_calls_from_accumulator(provider_tool_fragments)
                    except ValueError as exc:
                        raise protocol_error(str(exc), raw_bytes) from exc
                    put(LLMChunk(native_tool_calls=calls))
                parsed_finish, parsed_stop = llm_response_termination(obj)
                if parsed_finish:
                    finish_reason = parsed_finish
                if parsed_stop:
                    stop_reason = parsed_stop
                choices = obj.get("choices") or []
                if not isinstance(choices, list):
                    raise protocol_error("OpenAI-compatible response field 'choices' was not an array", raw_bytes)
                if not choices:
                    return
                choice = choices[0] or {}
                if not isinstance(choice, dict):
                    raise protocol_error("OpenAI-compatible response choice was not an object", raw_bytes)
                parsed_finish, parsed_stop = llm_response_termination({"choices": [choice]})
                if parsed_finish:
                    finish_reason = parsed_finish
                if parsed_stop:
                    stop_reason = parsed_stop
                delta = choice.get("delta") if isinstance(choice.get("delta"), dict) else {}
                message = choice.get("message") if isinstance(choice.get("message"), dict) else {}

                for container in (delta, message):
                    for field in container:
                        if len(provider_message_fields) < 64:
                            provider_message_fields.add(str(field)[:80])
                delta_reasoning = first_meaningful(delta, "reasoning_content", "reasoning", "thoughts")
                message_reasoning = first_meaningful(message, "reasoning_content", "reasoning", "thoughts")
                scalar_piece = ""
                if delta_reasoning is not None:
                    scalar_piece += scalar_reasoning.append_delta(provider_visible_text(delta_reasoning))
                if message_reasoning is not None:
                    scalar_piece += scalar_reasoning.accept_snapshot(provider_visible_text(message_reasoning))
                detail_piece, opaque_progress = structured_reasoning.accept(delta.get("reasoning_details"))
                snapshot_piece, snapshot_opaque = structured_reasoning.accept(message.get("reasoning_details"), snapshot=True)
                detail_piece += snapshot_piece
                if opaque_progress or snapshot_opaque:
                    put(LLMChunk(meaningful_progress=True, model_output_observed=True))
                if not reasoning_channel:
                    reasoning_channel = "scalar" if scalar_piece else "structured" if detail_piece else ""
                # These fields may be duplicate compatibility carriers. Render one
                # channel, preserve both originals; never concatenate two versions.
                reasoning_piece = scalar_piece if reasoning_channel == "scalar" else detail_piece
                if reasoning_piece:
                    emitted_reasoning.append_delta(reasoning_piece)
                    if not reasoning_open:
                        put(LLMChunk(text="<think>\n", meaningful_progress=False))
                        reasoning_open = True
                    put(LLMChunk(text=reasoning_piece, reasoning_text=reasoning_piece))

                # Refusals are visible assistant output. Prefer content, then refusal,
                # and fall back from an empty delta field to a cumulative message
                # snapshot in the same compatibility chunk.
                delta_content = first_meaningful(delta, "content", "refusal")
                message_content = first_meaningful(message, "content", "refusal")
                content = delta_content if delta_content is not None else message_content
                content_is_snapshot = delta_content is None and message_content is not None
                if content is None and isinstance(choice.get("text"), str) and choice.get("text"):
                    content = choice.get("text")
                    content_is_snapshot = True
                content_text = provider_visible_text(content)
                if content_text:
                    content_piece = (
                        emitted_content.accept_snapshot(content_text)
                        if content_is_snapshot else emitted_content.append_delta(content_text)
                    )
                    if content_piece:
                        emit_content_wire_piece(content_piece)

            try:
                if request_cancelled():
                    raise LLMRequestCancelledError("Endpoint request cancelled before connection")
                req = urllib.request.Request(url, data=body, headers=headers, method="POST")
                with urllib.request.urlopen(req, timeout=timeout) as resp:
                    with response_lock:
                        response_holder["response"] = resp
                    if request_cancelled():
                        raise LLMRequestCancelledError("Endpoint request cancelled")
                    response_headers = getattr(resp, "headers", None)
                    try:
                        response_status = int(getattr(resp, "status", 0) or resp.getcode() or 200)
                    except Exception:
                        response_status = 200
                    try:
                        response_url = str(resp.geturl() or url)
                    except Exception:
                        response_url = url
                    if response_status < 200 or response_status >= 300:
                        try:
                            response_body = resp.read(error_body_max_bytes + 1)
                        except Exception as body_exc:
                            response_body = (
                                f"[could not read error response body: {type(body_exc).__name__}: {body_exc}]"
                            ).encode("utf-8", errors="replace")
                        raise self._endpoint_error(
                            None,
                            endpoint=endpoint,
                            url=url,
                            headers=headers,
                            timeout=timeout,
                            payload=payload,
                            stream=True,
                            status_code=response_status,
                            reason="Endpoint returned a non-success HTTP status",
                            response_headers=response_headers,
                            response_body_bytes=response_body,
                            final_url=response_url,
                        )
                    saw_sse_frame = False
                    saw_done_frame = False
                    for frame_kind, frame_bytes in iter_openai_compatible_stream_frames(
                        resp, response_max_bytes=response_max_bytes, cancelled=request_cancelled,
                    ):
                        if frame_kind == "done":
                            saw_done_frame = True
                            break
                        if frame_kind == "sse":
                            saw_sse_frame = True
                            try:
                                obj = json.loads(frame_bytes.decode("utf-8"))
                            except Exception as parse_exc:
                                raise protocol_error(
                                    "Streaming SSE data event was not valid JSON", frame_bytes,
                                ) from parse_exc
                            process_object(obj, frame_bytes)
                        else:
                            try:
                                payloads = parse_openai_raw_json_payloads(frame_bytes)
                            except Exception as parse_exc:
                                raise protocol_error(
                                    "HTTP 200 response was not valid JSON, SSE, or strict NDJSON", frame_bytes,
                                ) from parse_exc
                            for obj in payloads:
                                process_object(obj, frame_bytes)
                    if not saw_valid_payload or (saw_sse_frame and not saw_done_frame and not finish_reason):
                        raise LLMEndpointError(
                            "Endpoint connection closed before a complete provider response",
                            endpoint_profile_id=request.endpoint_profile_id, reason="connection_closed",
                            response_headers=response_headers,
                        )
                finish_visible_stream()
                try:
                    final_calls = provider_tool_calls_from_accumulator(provider_tool_fragments)
                except ValueError as exc:
                    raise protocol_error(str(exc), b"") from exc
                if not request_cancelled():
                    observe_endpoint_prompt_usage(self.storage, endpoint, usage)
                termination_error = llm_endpoint_termination_error(finish_reason, stop_reason)
                put(LLMChunk(
                    done=True,
                    error=str(termination_error) if termination_error else None,
                    endpoint_failure=endpoint_failure_metadata(termination_error) if termination_error else None,
                    usage=usage,
                    finish_reason=finish_reason or None,
                    stop_reason=stop_reason or None,
                    native_tool_calls=final_calls,
                    reasoning_fields=final_reasoning_fields() or None,
                    provider_diagnostics=diagnostics(),
                ))
            except Exception as exc:
                try:
                    finish_visible_stream()
                except Exception:
                    pass
                error: BaseException = exc
                if request_cancelled() or isinstance(exc, LLMRequestCancelledError):
                    error = LLMRequestCancelledError(
                        f"Endpoint profile '{request.endpoint_profile_id}' request was cancelled"
                    )
                elif isinstance(exc, LLMEndpointError):
                    error = exc
                elif is_timeout_exception(exc):
                    error = LLMRequestTimeoutError(
                        str(endpoint.get("profile_id") or request.endpoint_profile_id),
                        timeout,
                        f"{type(exc).__name__}: {exc}; URL: {safe_endpoint_url(url)}",
                    )
                else:
                    error = self._endpoint_error(
                        exc,
                        endpoint=endpoint,
                        url=url,
                        headers=headers,
                        timeout=timeout,
                        payload=payload,
                        stream=True,
                        response_headers=response_headers,
                        final_url=response_url,
                    )
                put(LLMChunk(
                    error=f"{type(error).__name__}: {error}", done=True, usage=usage,
                    endpoint_failure=endpoint_failure_metadata(error),
                    model_output_observed=llm_error_has_partial_output(error),
                    finish_reason=finish_reason or None,
                    stop_reason=stop_reason or None,
                    # Never let a partial provider call survive an errored stream
                    # as an executable terminal batch.
                    native_tool_calls=None,
                    reasoning_fields=final_reasoning_fields() or None,
                    provider_diagnostics=diagnostics(),
                ))
            finally:
                with response_lock:
                    response_holder["response"] = None
                worker_done.set()
                put(None)

        if external_cancel_event is not None:
            def cancellation_watcher() -> None:
                while not worker_done.wait(0.05):
                    if consumer_stopped.is_set():
                        return
                    if external_cancel_event.is_set():
                        dispatch_close_active_response()
                        return
            threading.Thread(target=cancellation_watcher, daemon=True).start()
        deadline = LLMRequestDeadline(request.endpoint_profile_id, timeout)
        threading.Thread(target=worker, daemon=True).start()
        try:
            while True:
                try:
                    chunk = await deadline.next_chunk(q, request_cancelled)
                except LLMRequestCancelledError as exc:
                    consumer_stopped.set()
                    dispatch_close_active_response()
                    yield LLMChunk(error=f"LLMRequestCancelledError: {exc}", done=True)
                    break
                except LLMRequestTimeoutError as exc:
                    # Do not cancel the Chat task: this is an endpoint failure,
                    # not user Stop. The outer owner can safely retry empty output.
                    consumer_stopped.set()
                    dispatch_close_active_response()
                    yield LLMChunk(error=f"LLMRequestTimeoutError: {exc}", done=True, model_output_observed=deadline.model_output_observed)
                    break
                if chunk is None:
                    break
                yield chunk
                # Even when the queue already contains another aggregate, yield
                # once so frame rendering and unrelated background tasks run.
                await asyncio.sleep(0)
                if chunk.done:
                    break
        finally:
            # Stop queue publication and close the active urllib response so chat,
            # agent, and per-tool cancellation release the endpoint connection
            # instead of leaving a worker blocked until the configured timeout.
            consumer_stopped.set()
            dispatch_close_active_response()

    async def chat_completions_once(self, request: LLMRequest) -> str:
        # Feature: support non-streaming calls for summaries and utility requests.
        return (await self.chat_completions_once_full(dataclasses.replace(request, stream=False))).get("text", "")

    async def chat_completions_stream_full(self, request: LLMRequest) -> dict[str, Any]:
        """Collect one streaming request into the full-response shape.

        Long-running Agents need the stream path even when their execution loop
        consumes one complete response at a time. Streaming exposes real time to
        first output and generation duration, so Dashboard PP/TG rates do not
        disappear merely because the provider omits non-streaming timing fields.
        """
        pieces: list[str] = []
        usage: dict[str, Any] = {}
        finish_reason = ""
        stop_reason = ""
        native_tool_calls: list[dict[str, Any]] = []
        response_output_items: list[dict[str, Any]] = []
        reasoning_fields: dict[str, Any] = {}
        provider_diagnostics: dict[str, Any] = {}
        terminal_seen = False
        reasoning_only_open = False
        partial_output = False
        async for chunk in self.chat_completions_stream(
            dataclasses.replace(request, stream=True)
        ):
            partial_output |= chunk.model_output_observed
            if chunk.provider_diagnostics is not None:
                provider_diagnostics = copy.deepcopy(chunk.provider_diagnostics)
            if chunk.reasoning_fields is not None:
                reasoning_fields = copy.deepcopy(chunk.reasoning_fields)
            if chunk.usage:
                usage = update_llm_usage_snapshot(usage, chunk.usage)
            if chunk.finish_reason:
                finish_reason = normalize_llm_termination_reason(chunk.finish_reason)
            if chunk.stop_reason:
                stop_reason = normalize_llm_termination_reason(chunk.stop_reason)
            if chunk.native_tool_calls:
                native_tool_calls = copy.deepcopy(chunk.native_tool_calls)
                partial_output = True
            if chunk.response_output_items:
                response_output_items = copy.deepcopy(chunk.response_output_items)
                partial_output = True
            text_piece = str(chunk.text or "")
            reasoning_piece = str(chunk.reasoning_text or "")
            if text_piece:
                if reasoning_only_open:
                    pieces.append("\n</think>\n")
                    reasoning_only_open = False
                pieces.append(text_piece)
                partial_output = True
            elif reasoning_piece:
                if not reasoning_only_open:
                    pieces.append("<think>\n")
                    reasoning_only_open = True
                pieces.append(reasoning_piece)
                partial_output = True
            if chunk.error:
                if reasoning_only_open:
                    pieces.append("\n</think>\n")
                    reasoning_only_open = False
                error = RuntimeError(str(chunk.error))
                setattr(error, "partial_output", bool(partial_output))
                setattr(error, "endpoint_recovery_exhausted", chunk.endpoint_recovery_exhausted)
                setattr(error, "endpoint_failure", copy.deepcopy(chunk.endpoint_failure))
                setattr(error, "provider_diagnostics", copy.deepcopy(chunk.provider_diagnostics or {}))
                raise error
            if chunk.done:
                terminal_seen = True
                break
        if reasoning_only_open:
            pieces.append("\n</think>\n")
        if not terminal_seen:
            error = RuntimeError("Endpoint stream ended without a terminal completion chunk")
            setattr(error, "partial_output", bool(partial_output))
            raise error
        endpoint = self.resolve_endpoint(request.endpoint_profile_id)
        return {
            "text": normalize_known_provider_output_artifacts("".join(pieces)),
            "prompt_accounting": dict(request.prepared_capacity),
            "raw": {"stream_collected": True},
            "model": str(endpoint.get("model") or ""),
            "endpoint": str(endpoint.get("profile_id") or request.endpoint_profile_id),
            "usage": usage,
            "finish_reason": finish_reason,
            "stop_reason": stop_reason,
            "tool_calls": native_tool_calls,
            "response_output_items": response_output_items,
            "reasoning_fields": reasoning_fields,
            "provider_diagnostics": provider_diagnostics,
        }

    def _extract_text_from_raw_response(self, raw: dict[str, Any]) -> str:
        choices = raw.get("choices") or []
        if not isinstance(choices, list) or not choices or not isinstance(choices[0], dict):
            return ""
        choice = choices[0]
        msg = choice.get("message") if isinstance(choice.get("message"), dict) else {}
        content = msg.get("content")
        if content in (None, "", [], {}):
            content = msg.get("refusal")
        reasoning = msg.get("reasoning_content") or msg.get("reasoning") or msg.get("thoughts")
        if content in (None, "", [], {}) and isinstance(choice.get("text"), str):
            content = choice.get("text")
        text = provider_visible_text(content)
        reasoning_text = provider_reasoning_text(msg)
        if reasoning_text:
            return normalize_known_provider_output_artifacts(
                f"<think>\n{reasoning_text}\n</think>\n" + text
            )
        return normalize_known_provider_output_artifacts(text)


    async def _run_nonstreaming_worker(
        self, request: LLMRequest, work: Callable[[Callable[[Any], None]], dict[str, Any]],
    ) -> dict[str, Any]:
        loop = asyncio.get_running_loop()
        result: asyncio.Future[dict[str, Any]] = loop.create_future()
        stopped = threading.Event()
        response_lock = threading.Lock()
        response_holder: list[Any] = [None]

        def cancelled() -> bool:
            return stopped.is_set() or bool(request.cancel_event and request.cancel_event.is_set())

        def register_response(response: Any) -> None:
            with response_lock:
                response_holder[0] = response
            # A cancellation during connect must also close the late response,
            # before reading any body or publishing a completed result.
            if cancelled():
                raise asyncio.CancelledError("Endpoint request cancelled")

        def deliver(value: Any, error: BaseException | None) -> None:
            if result.done():
                return
            if error is not None:
                result.set_exception(error)
            else:
                result.set_result(value)

        def worker() -> None:
            value, error = None, None
            try:
                if cancelled():
                    raise asyncio.CancelledError("Endpoint request cancelled")
                value = work(register_response)
                if not deadline.finish():
                    raise deadline.error()
                if cancelled():
                    raise asyncio.CancelledError("Endpoint request cancelled")
            except BaseException as exc:
                error = exc
            finally:
                with response_lock:
                    response_holder[0] = None
                try:
                    loop.call_soon_threadsafe(deliver, value, error)
                except RuntimeError:
                    pass  # The event loop can close while cancelled I/O unwinds.

        def close_response() -> None:
            with response_lock:
                response = response_holder[0]
            if response is not None:
                self._close_response_transport(response)

        if cancelled():
            raise asyncio.CancelledError("Endpoint request cancelled")
        deadline = LLMRequestDeadline(request.endpoint_profile_id, self.request_timeout_seconds(request.endpoint_profile_id))
        threading.Thread(target=worker, name="velox-llm-response", daemon=True).start()
        try:
            while not result.done():
                if deadline.remaining() <= 0.0:
                    raise deadline.error()
                await asyncio.wait({result}, timeout=min(0.05, max(0.001, deadline.remaining())))
                if cancelled():
                    raise asyncio.CancelledError("Endpoint request cancelled")
            if cancelled():
                raise asyncio.CancelledError("Endpoint request cancelled")
            if deadline.remaining() <= 0.0:
                raise deadline.error()
            return result.result()
        finally:
            stopped.set()
            if not result.done():
                result.cancel()
                threading.Thread(target=close_response, name="velox-llm-response-close", daemon=True).start()
            elif not result.cancelled():
                result.exception()  # Consume an error that raced explicit cancellation.

    async def _responses_once_full(self, request: LLMRequest) -> dict[str, Any]:
        """Run one non-streaming first-party OpenAI Responses request."""
        endpoint, url, body, headers, timeout, payload = self._responses_payload_and_headers(request, stream=False)
        response_max_bytes = self.response_max_bytes()

        def do_request(register_response: Callable[[Any], None]) -> dict[str, Any]:
            req = urllib.request.Request(url, data=body, headers=headers, method="POST")
            try:
                opened = urllib.request.urlopen(req, timeout=timeout)
            except urllib.error.HTTPError as exc:
                try:
                    register_response(exc)
                    raise self._endpoint_error(
                        exc, endpoint=endpoint, url=url, headers=headers, timeout=timeout,
                        payload=payload, stream=False,
                    ) from exc
                finally:
                    exc.close()
            with opened as resp:
                register_response(resp)
                response_headers = getattr(resp, "headers", None)
                try:
                    response_status = int(getattr(resp, "status", 0) or resp.getcode() or 200)
                except Exception:
                    response_status = 200
                try:
                    response_url = str(resp.geturl() or url)
                except Exception:
                    response_url = url
                payload_bytes = resp.read(response_max_bytes + 1)
            if len(payload_bytes) > response_max_bytes:
                raise ValueError(f"LLM response exceeded the configured {response_max_bytes}-byte limit")
            if response_status < 200 or response_status >= 300:
                raise self._endpoint_error(
                    None, endpoint=endpoint, url=url, headers=headers, timeout=timeout,
                    payload=payload, stream=False, status_code=response_status,
                    reason="Endpoint returned a non-success HTTP status",
                    response_headers=response_headers, response_body_bytes=payload_bytes,
                    final_url=response_url,
                )
            if not payload_bytes:
                raise self._endpoint_error(
                    None, endpoint=endpoint, url=url, headers=headers, timeout=timeout,
                    payload=payload, stream=False, status_code=response_status,
                    reason="Endpoint returned an empty response body",
                    response_headers=response_headers, response_body_bytes=b"",
                    final_url=response_url,
                )
            try:
                raw = json.loads(payload_bytes.decode("utf-8"))
            except Exception as parse_exc:
                raise self._endpoint_error(
                    parse_exc, endpoint=endpoint, url=url, headers=headers, timeout=timeout,
                    payload=payload, stream=False, status_code=response_status,
                    reason="HTTP response was not valid JSON",
                    response_headers=response_headers, response_body_bytes=payload_bytes,
                    final_url=response_url,
                ) from parse_exc
            if not isinstance(raw, dict):
                raise self._endpoint_error(
                    None, endpoint=endpoint, url=url, headers=headers, timeout=timeout,
                    payload=payload, stream=False, status_code=response_status,
                    reason="Responses API response JSON was not an object",
                    response_headers=response_headers, response_body_bytes=payload_bytes,
                    final_url=response_url,
                )
            if self._payload_error_value(raw) is not None or str(raw.get("status") or "").lower() in {"failed", "cancelled", "canceled"}:
                raise self._endpoint_error(
                    None, endpoint=endpoint, url=url, headers=headers, timeout=timeout,
                    payload=payload, stream=False, status_code=response_status,
                    reason="OpenAI Responses API returned an error response",
                    response_headers=response_headers, response_body_bytes=payload_bytes,
                    final_url=response_url,
                )
            if not isinstance(raw.get("output"), list):
                raise self._endpoint_error(
                    None, endpoint=endpoint, url=url, headers=headers, timeout=timeout,
                    payload=payload, stream=False, status_code=response_status,
                    reason="OpenAI Responses API response did not contain an output array",
                    response_headers=response_headers, response_body_bytes=payload_bytes,
                    final_url=response_url,
                )
            return raw

        try:
            raw = await self._run_nonstreaming_worker(request, do_request)
        except LLMEndpointError:
            raise
        except Exception as exc:
            if is_timeout_exception(exc):
                raise LLMRequestTimeoutError(
                    str(endpoint.get("profile_id") or request.endpoint_profile_id), timeout,
                    f"{type(exc).__name__}: {exc}; URL: {safe_endpoint_url(url)}",
                ) from exc
            if isinstance(exc, ValueError) and "configured" in str(exc) and "byte limit" in str(exc):
                raise
            raise self._endpoint_error(
                exc, endpoint=endpoint, url=url, headers=headers, timeout=timeout,
                payload=payload, stream=False,
            ) from exc
        try:
            visible, reasoning, calls, output_items, usage, finish_reason, stop_reason = self._responses_parse_output(raw)
        except ValueError as exc:
            raise self._endpoint_error(
                exc, endpoint=endpoint, url=url, headers=headers, timeout=timeout,
                payload=payload, stream=False, status_code=200,
                reason=f"Invalid Responses tool-call protocol: {exc}",
                response_body_bytes=json.dumps(raw, ensure_ascii=False, default=str).encode("utf-8"),
            ) from exc
        text = visible
        if reasoning:
            text = f"<think>\n{reasoning}\n</think>\n" + text
        await asyncio.to_thread(observe_endpoint_prompt_usage, self.storage, endpoint, usage)
        return {
            "text": text,
            "prompt_accounting": dict(request.prepared_capacity),
            "raw": raw,
            "model": str(raw.get("model") or endpoint.get("model") or ""),
            "endpoint": endpoint.get("profile_id"),
            "usage": usage,
            "finish_reason": finish_reason,
            "stop_reason": stop_reason,
            "tool_calls": calls,
            "response_output_items": output_items,
            "response_id": str(raw.get("id") or ""),
        }

    async def _chat_completions_once_full_unqueued(self, request: LLMRequest) -> dict[str, Any]:
        # Utility requests follow the endpoint profile's selected API transport.
        endpoint = self.resolve_endpoint(request.endpoint_profile_id)
        if self._uses_openai_responses(endpoint):
            if not str(endpoint.get("base_url") or "").strip() or not str(endpoint.get("model") or "").strip():
                return {
                    "text": "", "raw": {"no_endpoint_configured": True},
                    "usage": {"no_endpoint_configured": True, "endpoint_profile_id": endpoint.get("profile_id", request.endpoint_profile_id)},
                    "model": "", "endpoint": endpoint.get("profile_id", request.endpoint_profile_id),
                }
            return await self._responses_once_full(dataclasses.replace(request, stream=False))
        base_url = _strip_matching_outer_quotes(endpoint.get("base_url"))
        model = _strip_matching_outer_quotes(endpoint.get("model"))
        if not base_url or not model:
            return {
                "text": "",
                "raw": {"no_endpoint_configured": True},
                "usage": {"no_endpoint_configured": True, "endpoint_profile_id": endpoint.get("profile_id", request.endpoint_profile_id)},
                "model": "",
                "endpoint": endpoint.get("profile_id", request.endpoint_profile_id),
            }
        endpoint, url, body, headers, timeout, payload = self._payload_and_headers(request, stream=False)
        response_max_bytes = self.response_max_bytes()

        def do_request(register_response: Callable[[Any], None]) -> dict[str, Any]:
            req = urllib.request.Request(url, data=body, headers=headers, method="POST")
            try:
                opened = urllib.request.urlopen(req, timeout=timeout)
            except urllib.error.HTTPError as exc:
                try:
                    register_response(exc)
                    raise self._endpoint_error(
                        exc, endpoint=endpoint, url=url, headers=headers, timeout=timeout,
                        payload=payload, stream=False,
                    ) from exc
                finally:
                    exc.close()
            with opened as resp:
                register_response(resp)
                response_headers = getattr(resp, "headers", None)
                try:
                    response_status = int(getattr(resp, "status", 0) or resp.getcode() or 200)
                except Exception:
                    response_status = 200
                try:
                    response_url = str(resp.geturl() or url)
                except Exception:
                    response_url = url
                payload_bytes = resp.read(response_max_bytes + 1)
            if len(payload_bytes) > response_max_bytes:
                raise ValueError(
                    f"LLM response exceeded the configured {response_max_bytes}-byte limit"
                )
            if response_status < 200 or response_status >= 300:
                raise self._endpoint_error(
                    None,
                    endpoint=endpoint,
                    url=url,
                    headers=headers,
                    timeout=timeout,
                    payload=payload,
                    stream=False,
                    status_code=response_status,
                    reason="Endpoint returned a non-success HTTP status",
                    response_headers=response_headers,
                    response_body_bytes=payload_bytes,
                    final_url=response_url,
                )
            if not payload_bytes:
                raise self._endpoint_error(
                    None,
                    endpoint=endpoint,
                    url=url,
                    headers=headers,
                    timeout=timeout,
                    payload=payload,
                    stream=False,
                    status_code=response_status,
                    reason="Endpoint returned an empty response body",
                    response_headers=response_headers,
                    response_body_bytes=b"",
                    final_url=response_url,
                )
            try:
                raw = json.loads(payload_bytes.decode("utf-8"))
            except Exception as parse_exc:
                raise self._endpoint_error(
                    parse_exc,
                    endpoint=endpoint,
                    url=url,
                    headers=headers,
                    timeout=timeout,
                    payload=payload,
                    stream=False,
                    status_code=response_status,
                    reason="HTTP response was not valid JSON",
                    response_headers=response_headers,
                    response_body_bytes=payload_bytes,
                    final_url=response_url,
                ) from parse_exc
            if not isinstance(raw, dict):
                raise self._endpoint_error(
                    None,
                    endpoint=endpoint,
                    url=url,
                    headers=headers,
                    timeout=timeout,
                    payload=payload,
                    stream=False,
                    status_code=response_status,
                    reason="HTTP response JSON was not an object",
                    response_headers=response_headers,
                    response_body_bytes=payload_bytes,
                    final_url=response_url,
                )
            if self._payload_error_value(raw) is not None:
                raise self._endpoint_error(
                    None,
                    endpoint=endpoint,
                    url=url,
                    headers=headers,
                    timeout=timeout,
                    payload=payload,
                    stream=False,
                    status_code=response_status,
                    reason="Provider returned an error object",
                    response_headers=response_headers,
                    response_body_bytes=payload_bytes,
                    final_url=response_url,
                )
            choices = raw.get("choices")
            if not isinstance(choices, list) or not choices:
                raise self._endpoint_error(
                    None,
                    endpoint=endpoint,
                    url=url,
                    headers=headers,
                    timeout=timeout,
                    payload=payload,
                    stream=False,
                    status_code=response_status,
                    reason="OpenAI-compatible response did not contain a non-empty choices array",
                    response_headers=response_headers,
                    response_body_bytes=payload_bytes,
                    final_url=response_url,
                )
            if not isinstance(choices[0], dict):
                raise self._endpoint_error(
                    None, endpoint=endpoint, url=url, headers=headers, timeout=timeout,
                    payload=payload, stream=False, status_code=response_status,
                    reason="OpenAI-compatible response choice zero was not an object",
                    response_headers=response_headers, response_body_bytes=payload_bytes,
                    final_url=response_url,
                )
            return raw

        try:
            raw = await self._run_nonstreaming_worker(request, do_request)
        except LLMEndpointError:
            raise
        except Exception as exc:
            if is_timeout_exception(exc):
                raise LLMRequestTimeoutError(
                    str(endpoint.get("profile_id") or request.endpoint_profile_id),
                    timeout,
                    f"{type(exc).__name__}: {exc}; URL: {safe_endpoint_url(url)}",
                ) from exc
            if isinstance(exc, ValueError) and "configured" in str(exc) and "byte limit" in str(exc):
                raise
            raise self._endpoint_error(
                exc,
                endpoint=endpoint,
                url=url,
                headers=headers,
                timeout=timeout,
                payload=payload,
                stream=False,
            ) from exc
        finish_reason, stop_reason = llm_response_termination(raw)
        response_text = self._extract_text_from_raw_response(raw)
        try:
            native_calls = provider_tool_calls_from_payload(raw)
        except ValueError as exc:
            raise self._endpoint_error(
                exc, endpoint=endpoint, url=url, headers=headers, timeout=timeout,
                payload=payload, stream=False, status_code=200,
                reason=f"Invalid provider native tool-call protocol: {exc}",
                response_body_bytes=json.dumps(raw, ensure_ascii=False, default=str).encode("utf-8"),
            ) from exc
        await asyncio.to_thread(observe_endpoint_prompt_usage, self.storage, endpoint, raw.get("usage"))
        return {
            "text": response_text,
            "prompt_accounting": dict(request.prepared_capacity),
            "raw": raw,
            "reasoning_fields": provider_reasoning_fields((raw.get("choices") or [{}])[0].get("message", {})),
            "model": model,
            "endpoint": endpoint.get("profile_id"),
            "usage": raw.get("usage") if isinstance(raw.get("usage"), dict) else {},
            "finish_reason": finish_reason,
            "stop_reason": stop_reason,
            "tool_calls": native_calls,
        }

    def _set_request_activity(
        self,
        request_id: str | None,
        activity: str,
        *,
        detail: str = "",
        prompt_progress_percent: float | None = None,
        prompt_tokens_processed: int | None = None,
        prompt_tokens_total: int | None = None,
        restart_timer: bool = False,
    ) -> None:
        monitor = self.request_monitor
        if monitor is None or not request_id:
            return
        setter = getattr(monitor, "set_activity", None)
        if not callable(setter):
            return
        try:
            setter(
                request_id, activity, detail=detail,
                prompt_progress_percent=prompt_progress_percent,
                prompt_tokens_processed=prompt_tokens_processed,
                prompt_tokens_total=prompt_tokens_total,
                restart_timer=restart_timer,
                persist=False,
            )
        except Exception:
            pass

    def _touch_request_activity(self, request_id: str | None, observed_at: float | None = None) -> None:
        """Record real provider stream progress without publishing every token."""
        monitor = self.request_monitor
        if monitor is None or not request_id:
            return
        touch = getattr(monitor, "touch_activity", None)
        if not callable(touch):
            return
        try:
            touch(request_id, observed_at=observed_at) if observed_at is not None else touch(request_id)
        except Exception:
            pass

    def _update_request_activity_from_chunk(
        self, request_id: str | None, chunk: LLMChunk,
    ) -> None:
        """Advance the transient stage and heartbeat from one provider chunk.

        Stage changes remain low-frequency monitor events. Only meaningful worker-
        observed progress refreshes the heartbeat; unchanged metadata and empty
        frames cannot conceal a stall. A terminal Task rejects both updates.
        """
        if not request_id:
            return
        if chunk.error:
            self._set_request_activity(
                request_id, "error", detail=str(chunk.error),
            )
            return
        if chunk.meaningful_progress is False:
            return
        if chunk.meaningful_progress is None and not any((chunk.text, chunk.reasoning_text,
                chunk.native_tool_calls, chunk.response_output_items, chunk.prompt_progress_percent is not None,
                chunk.model_output_observed)):
            return
        if chunk.reasoning_text or (chunk.model_output_observed and not any((chunk.text, chunk.native_tool_calls, chunk.response_output_items))):
            self._set_request_activity(request_id, "thinking")
        else:
            text = str(chunk.text or "")
            visible = usable_assistant_text(text)
            if visible or chunk.native_tool_calls or chunk.response_output_items:
                self._set_request_activity(request_id, "answer")
            elif re.search(r"(?is)<(?:think|thinking|reasoning)>", text):
                self._set_request_activity(request_id, "thinking")
            elif chunk.prompt_progress_percent is not None:
                self._set_request_activity(
                    request_id, "prompt",
                    prompt_progress_percent=chunk.prompt_progress_percent,
                    prompt_tokens_processed=chunk.prompt_tokens_processed,
                    prompt_tokens_total=chunk.prompt_tokens_total,
                )
        self._touch_request_activity(request_id, chunk.progress_monotonic)


    def _record_inference_metric_snapshot(
        self,
        request_id: str | None,
        round_id: str | None,
        *,
        input_tokens: int,
        output_tokens: int,
        prefill_seconds: float,
        generation_seconds: float,
        estimated: bool,
        final: bool = False,
        cached_input_tokens: int | None = None,
    ) -> None:
        monitor = self.request_monitor
        if monitor is None or not request_id or not round_id:
            return
        try:
            monitor.set_inference_round_metrics(
                request_id, round_id,
                input_tokens=input_tokens, cached_input_tokens=cached_input_tokens,
                output_tokens=output_tokens,
                prefill_seconds=prefill_seconds, generation_seconds=generation_seconds,
                estimated=estimated, final=final,
            )
        except Exception:
            pass

    def _endpoint_recovery_owner(self, request: LLMRequest) -> tuple[LLMRequest, bool, int]:
        profile = self.resolve_endpoint(request.endpoint_profile_id)
        retries = endpoint_error_recovery_attempts(profile) if endpoint_error_recovery_enabled(profile) else 0
        owned = False
        if self.request_scheduler is not None:
            task_id, owned = self.request_scheduler._ensure_monitor_task(request, profile)
            request = dataclasses.replace(request, monitor_task_id=task_id)
        return request, owned, retries

    def _finish_endpoint_recovery_owner(
        self, request: LLMRequest, owned: bool, failure: BaseException | None,
    ) -> None:
        if not owned or self.request_monitor is None:
            return
        monitor = self.request_monitor
        if isinstance(failure, (asyncio.CancelledError, GeneratorExit, LLMRequestCancelledError)) or (
            request.cancel_event and request.cancel_event.is_set()
        ):
            monitor.cancel(request.monitor_task_id)
        elif failure is not None:
            monitor.fail(request.monitor_task_id, f"{type(failure).__name__}: {failure}")
        else:
            monitor.complete(request.monitor_task_id)

    def _endpoint_recovery_cancelled(self, request: LLMRequest) -> bool:
        monitor = self.request_monitor
        return bool((request.cancel_event and request.cancel_event.is_set()) or (
            monitor is not None and request.monitor_task_id
            and monitor.record_state(request.monitor_task_id) in monitor.TERMINAL_STATES
        ))

    async def _wait_for_endpoint_recovery(
        self, request: LLMRequest, retry: int, limit: int,
        details: dict[str, Any], events: list[dict[str, Any]],
    ) -> float:
        """One cancellation-aware, slot-free delay shared by every transient error."""
        if self._endpoint_recovery_cancelled(request):
            raise asyncio.CancelledError("Endpoint Error Recovery cancelled")
        profile = self.resolve_endpoint(request.endpoint_profile_id)
        delay = float(endpoint_error_recovery_delay_seconds(profile))
        retry_after = details.get("retry_after_seconds")
        if isinstance(retry_after, (int, float)) and math.isfinite(retry_after):
            delay = max(delay, float(retry_after))
        event = {
            "attempt": retry, "maximum": limit, "delay_seconds": delay,
            "category": details.get("category"), "status_code": details.get("status_code"),
            "summary": str(details.get("summary") or "Transient endpoint failure")[:500],
            "diagnostic": str(details.get("diagnostic") or "")[:12000],
            "started_at": now_iso(),
        }
        events.append(event)
        monitor = self.request_monitor
        if monitor is not None and request.monitor_task_id:
            monitor.update_metadata(request.monitor_task_id, {"endpoint_error_recovery": dict(event)}, persist=False)
        try:
            await asyncio.to_thread(self.storage.append_app_log, "llm.endpoint_error_recovery", {
                "task_id": request.monitor_task_id, "endpoint_profile_id": request.endpoint_profile_id, **event,
            })
        except Exception:
            pass  # Diagnostics cannot suppress recovery or block UI work.
        started = time.monotonic()
        waited: float | None = None
        try:
            waited = await wait_for_endpoint_retry_cooldown(
                delay, cancel_event=request.cancel_event,
                cancelled=lambda: self._endpoint_recovery_cancelled(request),
                monitor=monitor, task_id=request.monitor_task_id,
                reason=event["summary"], kind="error_recovery", attempt=retry, maximum=limit,
            )
            return waited
        finally:
            event["waited_seconds"] = waited if waited is not None else max(0.0, time.monotonic() - started)
            event["cumulative_wait_seconds"] = sum(float(row.get("waited_seconds") or 0.0) for row in events)
            event["ended_at"] = now_iso()

    @staticmethod
    def _endpoint_recovery_disposition(partial: bool, retries: int, limit: int) -> str:
        if partial:
            return "Partial model output received; automatic replay suppressed."
        if limit == 0:
            return "Endpoint Error Recovery is disabled (zero re-attempts)."
        return f"Endpoint Error Recovery exhausted after {retries} re-attempt(s) ({retries + 1} total attempts)."

    @staticmethod
    def _endpoint_recovery_diagnostics(
        existing: Any, events: list[dict[str, Any]], limit: int, wait: float, disposition: str,
    ) -> dict[str, Any]:
        diagnostics = dict(existing or {})
        if events or disposition != "succeeded":
            diagnostics["endpoint_error_recovery"] = {
                "maximum_retries": limit, "retries_used": len(events),
                "wait_seconds": round(wait, 6), "disposition": disposition,
                "attempts": copy.deepcopy(events),
            }
        return diagnostics

    async def chat_completions_stream(self, request: LLMRequest):
        request, owned, retry_limit = self._endpoint_recovery_owner(request)
        failure: BaseException | None = None
        events: list[dict[str, Any]] = []
        wait_total = 0.0
        try:
            for attempt in range(retry_limit + 1):
                if self._endpoint_recovery_cancelled(request):
                    raise asyncio.CancelledError("Endpoint request cancelled")
                terminal: LLMChunk | None = None
                partial_output = False
                try:
                    async with contextlib.aclosing(self._chat_completions_stream_attempt(request)) as stream:
                        async for chunk in stream:
                            partial_output |= bool(chunk.text or chunk.reasoning_text or chunk.native_tool_calls
                                                   or chunk.response_output_items or chunk.model_output_observed
                                                   or chunk.reasoning_fields)
                            if chunk.done or chunk.error:
                                terminal = chunk
                            else:
                                yield chunk
                except (asyncio.CancelledError, GeneratorExit, LLMRequestCancelledError):
                    raise
                except Exception as exc:
                    if not isinstance(exc, (LLMEndpointError, TimeoutError, ConnectionError, urllib.error.URLError, http.client.HTTPException)):
                        raise  # Programmer/protocol bugs are not transport retries.
                    partial_output |= llm_error_has_partial_output(exc)
                    terminal = LLMChunk(error=f"{type(exc).__name__}: {exc}", done=True,
                                        endpoint_failure=endpoint_failure_metadata(exc))
                # The previous attempt and its inference lease are closed before
                # waiting or reacquiring. The exact input is reused, without new
                # assistant/user messages or another tool-dispatch pass.
                if terminal is None:
                    missing = LLMEndpointError("Endpoint connection closed before a terminal completion", reason="connection_closed")
                    terminal = LLMChunk(error=str(missing), done=True, endpoint_failure=endpoint_failure_metadata(missing))
                if self._endpoint_recovery_cancelled(request):
                    raise asyncio.CancelledError("Endpoint request cancelled")
                if not terminal.error:
                    semantic_error = llm_endpoint_termination_error(terminal.finish_reason, terminal.stop_reason)
                    if semantic_error is not None:
                        terminal = dataclasses.replace(terminal, error=str(semantic_error),
                                                       endpoint_failure=endpoint_failure_metadata(semantic_error))
                wait_total += float(_stats_nonnegative_float(terminal.usage or {}, "endpoint_wait_seconds") or 0.0)
                if terminal.endpoint_failure is not None:
                    details = terminal.endpoint_failure if terminal.endpoint_failure.get("retryable") else None
                else:
                    details = llm_endpoint_error_recovery_details(terminal.error) if terminal.error else None
                if terminal.error and details is not None and not partial_output and attempt < retry_limit:
                    wait_total += await self._wait_for_endpoint_recovery(request, attempt + 1, retry_limit, details, events)
                    continue
                disposition = "succeeded"
                if terminal.error:
                    disposition = self._endpoint_recovery_disposition(partial_output, attempt, retry_limit) if details else "Non-retryable endpoint failure."
                    terminal = dataclasses.replace(
                        terminal, error=f"{terminal.error}\n{disposition}",
                        endpoint_recovery_exhausted=details is not None,
                        model_output_observed=partial_output, native_tool_calls=None, response_output_items=None,
                    )
                    failure = RuntimeError(str(terminal.error))
                usage = dict(terminal.usage or {})
                if wait_total:
                    usage["endpoint_wait_seconds"] = round(wait_total, 6)
                terminal = dataclasses.replace(terminal, usage=usage or None,
                    provider_diagnostics=self._endpoint_recovery_diagnostics(
                        terminal.provider_diagnostics, events, retry_limit, wait_total, disposition))
                terminal.provider_diagnostics = self._cache_reporting_diagnostics(
                    request, usage, terminal.provider_diagnostics)
                # The bridge can coalesce all partial text with the error. Preserve
                # that draft visibly, but never expose a failed tool batch as executable.
                if terminal.error and (terminal.text or terminal.reasoning_text):
                    yield dataclasses.replace(terminal, done=False, error=None, usage=None,
                                              endpoint_recovery_exhausted=False)
                    terminal = dataclasses.replace(terminal, text="", reasoning_text="")
                self._finish_endpoint_recovery_owner(request, owned, failure)
                owned = False
                yield terminal
                return
        except BaseException as exc:
            failure = exc
            raise
        finally:
            self._finish_endpoint_recovery_owner(request, owned, failure)

    async def chat_completions_once_full(self, request: LLMRequest) -> dict[str, Any]:
        request, owned, retry_limit = self._endpoint_recovery_owner(request)
        failure: BaseException | None = None
        events: list[dict[str, Any]] = []
        wait_total = 0.0
        try:
            for attempt in range(retry_limit + 1):
                if self._endpoint_recovery_cancelled(request):
                    raise asyncio.CancelledError("Endpoint request cancelled")
                try:
                    response = await self._chat_completions_once_full_attempt(request)
                    if self._endpoint_recovery_cancelled(request):
                        raise asyncio.CancelledError("Endpoint request cancelled")
                    semantic_error = llm_endpoint_termination_error(response.get("finish_reason"), response.get("stop_reason"))
                    if semantic_error is not None:
                        semantic_error.partial_output = llm_response_has_model_output(response)
                        raise semantic_error
                    response = dict(response)
                    usage = dict(response.get("usage") or {})
                    if wait_total:
                        usage["endpoint_wait_seconds"] = round(wait_total + float(_stats_nonnegative_float(usage, "endpoint_wait_seconds") or 0.0), 6)
                    response["usage"] = usage
                    response["provider_diagnostics"] = self._endpoint_recovery_diagnostics(
                        response.get("provider_diagnostics"), events, retry_limit, wait_total, "succeeded")
                    response["provider_diagnostics"] = self._cache_reporting_diagnostics(
                        request, usage, response["provider_diagnostics"])
                    return response
                except (asyncio.CancelledError, LLMRequestCancelledError):
                    raise
                except Exception as exc:
                    wait_total += float(_stats_nonnegative_float(
                        {"seconds": getattr(exc, "endpoint_wait_seconds", 0.0)}, "seconds") or 0.0)
                    details = llm_endpoint_error_recovery_details(exc)
                    partial = llm_error_has_partial_output(exc)
                    if details is not None and not partial and attempt < retry_limit:
                        wait_total += await self._wait_for_endpoint_recovery(request, attempt + 1, retry_limit, details, events)
                        continue
                    if details is None:
                        exc.provider_diagnostics = self._endpoint_recovery_diagnostics(
                            getattr(exc, "provider_diagnostics", {}), events, retry_limit, wait_total,
                            "Non-retryable endpoint failure.")
                        raise
                    disposition = self._endpoint_recovery_disposition(partial, attempt, retry_limit)
                    if isinstance(exc, LLMRequestTimeoutError):
                        exhausted = LLMRequestTimeoutError(exc.endpoint_profile_id, exc.timeout_seconds, f"{exc.detail}; {disposition}")
                    else:
                        exhausted = LLMEndpointError(
                            f"{exc}\n{disposition}", endpoint_profile_id=request.endpoint_profile_id,
                            url=getattr(exc, "url", ""), status_code=getattr(exc, "status_code", None),
                            reason=getattr(exc, "reason", ""), response_body=getattr(exc, "response_body", ""),
                            response_headers=getattr(exc, "response_headers", None),
                        )
                    exhausted.endpoint_recovery_exhausted = True
                    exhausted.partial_output = partial
                    exhausted.endpoint_failure = details
                    exhausted.provider_diagnostics = self._endpoint_recovery_diagnostics({}, events, retry_limit, wait_total, disposition)
                    raise exhausted from exc
            raise AssertionError("Endpoint Error Recovery loop ended without a disposition")
        except BaseException as exc:
            failure = exc
            raise
        finally:
            self._finish_endpoint_recovery_owner(request, owned, failure)

    async def _chat_completions_stream_attempt(self, request: LLMRequest):
        scheduler = self.request_scheduler

        def clean_usage(value: Any) -> tuple[dict[str, Any], float | None, float | None, float | None]:
            usage = dict(value) if isinstance(value, dict) else {}
            markers: list[float | None] = []
            for key in (
                "_velox_stream_first_delta_monotonic",
                "_velox_stream_last_delta_monotonic",
                "_velox_stream_terminal_monotonic",
            ):
                raw = usage.pop(key, None)
                try:
                    number = float(raw) if raw is not None else None
                except Exception:
                    number = None
                markers.append(number if number is not None and math.isfinite(number) else None)
            return usage, markers[0], markers[1], markers[2]

        if scheduler is None:
            # Worker-side stream timestamps are private transport metadata. Never
            # leak them into public chunks, persisted turns, or provider usage.
            endpoint_wait_seconds = await self._wait_for_endpoint_request_budget(request)
            round_id = self._begin_monitored_inference(request)
            failure: BaseException | None = None
            monitor = self.request_monitor
            if monitor is not None and request.monitor_task_id:
                try:
                    monitor.set_phase(request.monitor_task_id, "inference", persist=False)
                except Exception:
                    pass
            self._set_request_activity(request.monitor_task_id, "prompt", restart_timer=True)
            try:
                async with contextlib.aclosing(self._chat_completions_stream_unqueued(request)) as owned_stream:
                    async for chunk in owned_stream:
                        public_usage, _first, _last, _terminal = clean_usage(chunk.usage)
                        if chunk.done and request.prepared_capacity:
                            chunk.provider_diagnostics = dict(chunk.provider_diagnostics or {}, prompt_accounting=dict(request.prepared_capacity))
                        if chunk.done and endpoint_wait_seconds > 0.0:
                            public_usage["endpoint_wait_seconds"] = round(endpoint_wait_seconds, 6)
                        public_chunk = dataclasses.replace(chunk, usage=public_usage)
                        self._update_request_activity_from_chunk(request.monitor_task_id, public_chunk)
                        self._append_monitored_inference_chunk(request, round_id, public_chunk)
                        yield public_chunk
            except BaseException as exc:
                failure = exc
                if isinstance(exc, (asyncio.CancelledError, GeneratorExit, LLMRequestCancelledError)):
                    self._set_request_activity(request.monitor_task_id, "inactive")
                else:
                    self._set_request_activity(
                        request.monitor_task_id, "error",
                        detail=f"{type(exc).__name__}: {exc}",
                    )
                raise
            finally:
                self._finish_monitored_inference(request, round_id, error=failure)
                if monitor is not None and request.monitor_task_id:
                    try:
                        if monitor.record_state(request.monitor_task_id) == "running":
                            monitor.set_phase(request.monitor_task_id, "ready", persist=False)
                    except Exception:
                        pass
            return
        # Rate-limit/cooldown waiting is not provider inference and must not consume
        # endpoint capacity. Admit through the RPM guard before taking a scheduler slot.
        endpoint_wait_seconds = await self._wait_for_endpoint_request_budget(request)
        lease = await scheduler.acquire(request)
        request_id = lease.ticket.monitor_task_id
        request = dataclasses.replace(request, monitor_task_id=request_id)
        self._set_request_activity(request_id, "prompt", restart_timer=True)
        monitored_round_id = self._begin_monitored_inference(request)
        started = time.monotonic()
        first_stream_output: float | None = None
        provider_first_output: float | None = None
        provider_last_output: float | None = None
        provider_terminal: float | None = None
        last_usage: dict[str, Any] = {}
        failure: BaseException | None = None
        finalize_task: asyncio.Task[dict[str, Any]] | None = None
        metric_round_id = monitored_round_id or uuid_v4()
        estimated_input_tokens = estimate_llm_request_input_tokens(request)
        observed_reasoning_chars = 0
        inline_reasoning_presence = StreamingReasoningPresence()
        estimated_text_output_tokens = 0
        estimated_structure_output_tokens = 0
        last_metric_publish = 0.0

        def publish_metric_snapshot(*, force: bool = False, final: bool = False) -> tuple[int, int, bool]:
            nonlocal last_metric_publish
            now = time.monotonic()
            if not force and now - last_metric_publish < 0.25:
                provider_input, provider_output = _request_usage_token_values({"usage": last_usage})
                return (
                    provider_input if provider_input is not None and provider_input > 0 else estimated_input_tokens,
                    provider_output if provider_output is not None and provider_output > 0 else estimated_text_output_tokens + estimated_structure_output_tokens,
                    provider_input is None or provider_output is None,
                )
            provider_input, provider_output = _request_usage_token_values({"usage": last_usage})
            use_provider_input = provider_input is not None and (provider_input > 0 or final)
            use_provider_output = provider_output is not None and (provider_output > 0 or final)
            input_tokens = provider_input if use_provider_input else estimate_llm_request_input_tokens(request)
            output_tokens = (
                provider_output if use_provider_output
                else estimated_text_output_tokens + estimated_structure_output_tokens
            )
            first_at = provider_first_output or first_stream_output
            if first_at is None:
                prefill_seconds = 0.0
                generation_seconds = 0.0
            else:
                prefill_seconds = max(0.0, first_at - started)
                terminal_at = (
                    provider_terminal or provider_last_output
                    or (now if final or output_tokens > 0 else first_at)
                )
                generation_seconds = max(0.0, terminal_at - first_at)
            prefill_seconds, generation_seconds = llm_measured_phase_seconds(
                last_usage, observed_reasoning_chars, prefill_seconds, generation_seconds)
            estimated = not (use_provider_input and use_provider_output)
            self._record_inference_metric_snapshot(
                request_id, metric_round_id,
                input_tokens=int(input_tokens or 0),
                cached_input_tokens=cached_input_tokens_from_usage(last_usage),
                output_tokens=int(output_tokens or 0),
                prefill_seconds=prefill_seconds, generation_seconds=generation_seconds,
                estimated=estimated, final=final,
            )
            last_metric_publish = now
            return int(input_tokens or 0), int(output_tokens or 0), estimated

        # Show a useful prompt count as soon as the request owns the endpoint slot;
        # exact provider usage reconciles this same round later.
        publish_metric_snapshot(force=True)

        async def finalize_impl(current_failure: BaseException | None) -> dict[str, Any]:
            ended = time.monotonic()
            input_tokens, output_tokens, token_counts_estimated = publish_metric_snapshot(
                force=True, final=True,
            )
            first_at = provider_first_output or first_stream_output
            terminal_at = provider_terminal or provider_last_output or ended
            if first_at is None:
                # No provider delta ever arrived. The elapsed request is transport /
                # provider wait, not measured prompt processing, and must not poison
                # PP throughput after a stall, cancellation, or endpoint timeout.
                prefill_seconds = 0.0
                generation_seconds = 0.0
            else:
                if terminal_at < first_at:
                    terminal_at = ended
                prefill_seconds = max(0.0, first_at - started)
                generation_seconds = max(0.0, terminal_at - first_at)
            unobservable = llm_reasoning_timing_unobservable(last_usage, observed_reasoning_chars)
            prefill_seconds, generation_seconds = llm_measured_phase_seconds(
                last_usage, observed_reasoning_chars, prefill_seconds, generation_seconds)
            timing_usage = dict(last_usage)
            timing_usage["_velox_generation_timing_basis"] = "unavailable_reasoning_not_received" if unobservable else "stream_observed"
            timing_usage["_velox_unobserved_inference_seconds"] = max(0.0, ended - started) if unobservable else 0.0
            if _request_usage_token_values({"usage": timing_usage})[0] is None:
                timing_usage["prompt_tokens"] = input_tokens
            if _request_usage_token_values({"usage": timing_usage})[1] is None:
                timing_usage["completion_tokens"] = output_tokens
            timing_usage.update({
                "_velox_prefill_seconds": prefill_seconds,
                "_velox_generation_seconds": generation_seconds,
                "_velox_inference_wall_seconds": max(0.0, ended - started),
                "_velox_waiting_for_first_output_seconds": (
                    max(0.0, ended - started) if first_at is None else 0.0
                ),
                "_velox_token_counts_estimated": bool(token_counts_estimated),
                "endpoint_wait_seconds": round(endpoint_wait_seconds, 6),
            })
            # Auto-created one-request Tasks terminalize before request cleanup so
            # their monitor state accurately reflects the one provider round. Every
            # scheduler lease, including normal Chat/Agent/System Tasks, releases
            # endpoint capacity as this provider request unwinds.
            monitor = self.request_monitor
            if lease.ticket.auto_monitor_task and monitor is not None:
                if (
                    isinstance(current_failure, (asyncio.CancelledError, GeneratorExit))
                    or (request.cancel_event and request.cancel_event.is_set())
                ):
                    monitor.cancel(request_id)
                elif current_failure is not None:
                    monitor.fail(request_id, f"{type(current_failure).__name__}: {current_failure}")
                else:
                    monitor.complete(request_id)
            await lease.release()
            return timing_usage

        def consume_finalize_result(task: asyncio.Task[dict[str, Any]]) -> None:
            try:
                task.result()
            except BaseException:
                pass

        async def finalize(current_failure: BaseException | None = None) -> dict[str, Any]:
            nonlocal finalize_task
            if finalize_task is None:
                finalize_task = asyncio.create_task(finalize_impl(current_failure))
                finalize_task.add_done_callback(consume_finalize_result)
            # Shield the cleanup task. The caller's cancellation still propagates,
            # but scheduler/monitor cleanup continues to completion on the loop.
            return await asyncio.shield(finalize_task)

        try:
            async with contextlib.aclosing(self._chat_completions_stream_unqueued(request)) as owned_stream:
                async for chunk in owned_stream:
                    public_usage, first_marker, last_marker, terminal_marker = clean_usage(chunk.usage)
                    if chunk.done and request.prepared_capacity:
                        chunk.provider_diagnostics = dict(chunk.provider_diagnostics or {}, prompt_accounting=dict(request.prepared_capacity))
                    # Bridge timing is private chunk metadata rather than provider
                    # usage. Read it here so coalescing does not collapse measured
                    # generation time, while public usage remains provider-exact.
                    if first_marker is None:
                        try:
                            raw_first = getattr(chunk, "_velox_stream_first_delta_monotonic", None)
                            first_marker = float(raw_first) if raw_first is not None else None
                        except Exception:
                            first_marker = None
                    if last_marker is None:
                        try:
                            raw_last = getattr(chunk, "_velox_stream_last_delta_monotonic", None)
                            last_marker = float(raw_last) if raw_last is not None else None
                        except Exception:
                            last_marker = None
                    if terminal_marker is None:
                        try:
                            raw_terminal = getattr(chunk, "_velox_stream_terminal_monotonic", None)
                            terminal_marker = float(raw_terminal) if raw_terminal is not None else None
                        except Exception:
                            terminal_marker = None
                    if first_marker is not None:
                        provider_first_output = (
                            first_marker if provider_first_output is None
                            else min(provider_first_output, first_marker)
                        )
                    if last_marker is not None:
                        provider_last_output = (
                            last_marker if provider_last_output is None
                            else max(provider_last_output, last_marker)
                        )
                    if terminal_marker is not None:
                        provider_terminal = (
                            terminal_marker if provider_terminal is None
                            else max(provider_terminal, terminal_marker)
                        )
                    if public_usage:
                        last_usage = update_llm_usage_snapshot(last_usage, public_usage)
                    observed_reasoning_chars += len(str(chunk.reasoning_text or ""))
                    output_piece = str(chunk.text or chunk.reasoning_text or "")
                    if inline_reasoning_presence.feed(output_piece):
                        observed_reasoning_chars = max(1, observed_reasoning_chars)
                    if output_piece:
                        estimated_text_output_tokens += _estimated_text_tokens(output_piece)
                    if chunk.native_tool_calls:
                        estimated_structure_output_tokens = estimate_llm_output_structure_tokens(
                            chunk.native_tool_calls
                        )
                    elif chunk.response_output_items:
                        estimated_structure_output_tokens = estimate_llm_output_structure_tokens(
                            chunk.response_output_items
                        )
                    if first_stream_output is None and (
                        bool(chunk.text) or bool(chunk.reasoning_text) or bool(chunk.native_tool_calls)
                        or bool(chunk.response_output_items)
                    ):
                        first_stream_output = time.monotonic()
                    public_chunk = dataclasses.replace(chunk, usage=public_usage)
                    self._update_request_activity_from_chunk(request_id, public_chunk)
                    publish_metric_snapshot(force=bool(public_usage or chunk.done), final=False)
                    if chunk.done:
                        terminal_failure = RuntimeError(str(chunk.error)) if chunk.error else None
                        terminal_usage = await finalize(terminal_failure)
                        terminal_chunk = dataclasses.replace(public_chunk, usage=terminal_usage)
                        self._append_monitored_inference_chunk(request, monitored_round_id, terminal_chunk)
                        yield terminal_chunk
                        return
                    self._append_monitored_inference_chunk(request, monitored_round_id, public_chunk)
                    yield public_chunk
        except BaseException as exc:
            failure = exc
            if isinstance(exc, (asyncio.CancelledError, GeneratorExit, LLMRequestCancelledError)):
                self._set_request_activity(request_id, "inactive")
            else:
                self._set_request_activity(
                    request_id, "error", detail=f"{type(exc).__name__}: {exc}",
                )
            raise
        finally:
            if finalize_task is None or not finalize_task.done():
                await finalize(failure)
            self._finish_monitored_inference(request, monitored_round_id, error=failure)

    async def _chat_completions_once_full_attempt(self, request: LLMRequest) -> dict[str, Any]:
        scheduler = self.request_scheduler
        if scheduler is None:
            endpoint_wait_seconds = await self._wait_for_endpoint_request_budget(request)
            if self.request_monitor is not None and request.monitor_task_id:
                try:
                    self.request_monitor.set_phase(request.monitor_task_id, "inference", persist=False)
                except Exception:
                    pass
            monitored_round_id = self._begin_monitored_inference(request)
            result: dict[str, Any] | None = None
            failure: BaseException | None = None
            self._set_request_activity(
                request.monitor_task_id, "prompt", restart_timer=True,
            )
            try:
                result = await self._chat_completions_once_full_unqueued(request)
                semantic_error = llm_endpoint_termination_error(result.get("finish_reason"), result.get("stop_reason"))
                if semantic_error is not None:
                    semantic_error.partial_output = llm_response_has_model_output(result)
                    raise semantic_error
                if isinstance(result, dict):
                    usage = dict(result.get("usage") or {})
                    usage["endpoint_wait_seconds"] = round(endpoint_wait_seconds, 6)
                    result["usage"] = usage
                self._set_request_activity(request.monitor_task_id, "answer")
                return result
            except BaseException as exc:
                failure = exc
                exc.endpoint_wait_seconds = endpoint_wait_seconds
                if isinstance(exc, (asyncio.CancelledError, GeneratorExit, LLMRequestCancelledError)):
                    self._set_request_activity(request.monitor_task_id, "inactive")
                else:
                    self._set_request_activity(
                        request.monitor_task_id, "error",
                        detail=f"{type(exc).__name__}: {exc}",
                    )
                raise
            finally:
                self._finish_monitored_inference(
                    request, monitored_round_id, result=result, error=failure,
                )
        # Rate-limit/cooldown waiting is not provider inference and must not consume
        # endpoint capacity. Admit through the RPM guard before taking a scheduler slot.
        endpoint_wait_seconds = await self._wait_for_endpoint_request_budget(request)
        lease = await scheduler.acquire(request)
        request_id = lease.ticket.monitor_task_id
        request = dataclasses.replace(request, monitor_task_id=request_id)
        self._set_request_activity(request_id, "prompt", restart_timer=True)
        monitored_round_id = self._begin_monitored_inference(request)
        started = time.monotonic()
        result: dict[str, Any] | None = None
        failure: BaseException | None = None
        metric_round_id = monitored_round_id or uuid_v4()
        estimated_input_tokens = estimate_llm_request_input_tokens(request)
        self._record_inference_metric_snapshot(
            request_id, metric_round_id, input_tokens=estimated_input_tokens, output_tokens=0,
            prefill_seconds=0.0, generation_seconds=0.0, estimated=True, final=False,
        )

        async def finalize_impl() -> None:
            ended = time.monotonic()
            provider_input, provider_output = _request_usage_token_values(result or {})
            estimated_output_tokens = 0
            if isinstance(result, dict):
                estimated_output_tokens += _estimated_text_tokens(str(result.get("text") or ""))
                estimated_output_tokens += estimate_llm_output_structure_tokens(result.get("tool_calls"))
            input_tokens = provider_input if provider_input is not None and provider_input > 0 else estimate_llm_request_input_tokens(request)
            output_tokens = provider_output if provider_output is not None and provider_output > 0 else estimated_output_tokens
            token_counts_estimated = not (
                provider_input is not None and provider_input > 0
                and provider_output is not None and provider_output >= 0
            )
            # Non-streaming APIs can report true provider timings. Without those
            # fields, do not mislabel total HTTP wall time as generation time.
            prefill_seconds = _provider_usage_seconds(
                result or {},
                ("prompt_seconds", "prefill_seconds", "prompt_time", "prompt_eval_time", "prompt_eval_duration", "prompt_ms", "prefill_ms"),
            )
            generation_seconds = _provider_usage_seconds(
                result or {},
                ("generation_seconds", "decode_seconds", "completion_time", "eval_time", "eval_duration", "generation_ms", "decode_ms"),
            )
            if prefill_seconds is None and generation_seconds is not None:
                prefill_seconds = max(0.0, ended - started - generation_seconds)
            elif prefill_seconds is None:
                prefill_seconds = 0.0
            if generation_seconds is None:
                generation_seconds = 0.0
            if isinstance(result, dict):
                usage = result.get("usage") if isinstance(result.get("usage"), dict) else {}
                usage = dict(usage)
                if _request_usage_token_values({"usage": usage})[0] is None:
                    usage["prompt_tokens"] = int(input_tokens)
                if _request_usage_token_values({"usage": usage})[1] is None:
                    usage["completion_tokens"] = int(output_tokens)
                usage.update({
                    "_velox_prefill_seconds": float(prefill_seconds),
                    "_velox_generation_seconds": float(generation_seconds),
                    "_velox_inference_wall_seconds": max(0.0, ended - started),
                    "_velox_token_counts_estimated": bool(token_counts_estimated),
                    "endpoint_wait_seconds": round(endpoint_wait_seconds, 6),
                })
                result["usage"] = usage
            self._finish_monitored_inference(
                request, monitored_round_id, result=result, error=failure,
            )
            self._record_inference_metric_snapshot(
                request_id, metric_round_id,
                input_tokens=int(input_tokens),
                cached_input_tokens=cached_input_tokens_from_usage(result),
                output_tokens=int(output_tokens),
                prefill_seconds=float(prefill_seconds), generation_seconds=float(generation_seconds),
                estimated=bool(token_counts_estimated), final=True,
            )
            monitor = self.request_monitor
            if lease.ticket.auto_monitor_task and monitor is not None:
                if (
                    isinstance(failure, (asyncio.CancelledError, GeneratorExit))
                    or (request.cancel_event and request.cancel_event.is_set())
                ):
                    monitor.cancel(request_id)
                elif failure is not None:
                    monitor.fail(request_id, f"{type(failure).__name__}: {failure}")
                else:
                    monitor.complete(request_id)
            await lease.release()

        try:
            result = await self._chat_completions_once_full_unqueued(request)
            semantic_error = llm_endpoint_termination_error(result.get("finish_reason"), result.get("stop_reason"))
            if semantic_error is not None:
                semantic_error.partial_output = llm_response_has_model_output(result)
                raise semantic_error
            self._set_request_activity(request_id, "answer")
            return result
        except BaseException as exc:
            failure = exc
            exc.endpoint_wait_seconds = endpoint_wait_seconds
            if isinstance(exc, (asyncio.CancelledError, GeneratorExit, LLMRequestCancelledError)):
                self._set_request_activity(request_id, "inactive")
            else:
                self._set_request_activity(
                    request_id, "error", detail=f"{type(exc).__name__}: {exc}",
                )
            raise
        finally:
            cleanup_task = asyncio.create_task(finalize_impl())
            try:
                await asyncio.shield(cleanup_task)
            except asyncio.CancelledError:
                # Cleanup continues independently; consume a rare cleanup error so
                # it cannot become an unhandled task exception during shutdown.
                def consume_cleanup_result(task: asyncio.Task[None]) -> None:
                    try:
                        task.result()
                    except BaseException:
                        pass
                cleanup_task.add_done_callback(consume_cleanup_result)
                raise


class ContextAssembler:
    """Build the request-local system context shared by chats and agents."""

    FILE_GUIDANCE = r"""Relative file paths resolve from the Velox application root, not the workspace. Use supplied absolute paths with forward slashes. Store final work in workspace and disposable work in temp; attachments are read-only. Work outside this Chat directory requires the user's explicit authorization."""
    AGENT_GUIDANCE = r"""agents_start delegates bounded work with exclusive absolute writable files/directories or explicit read-only scope. Ownership is file-level: disjoint files may share a directory. Keep the child's writable scope untouched until its automatic return; work on disjoint resources meanwhile. Inspect and integrate returned results. Ready results arrive between model rounds. Use agents_get_result for an identified Agent's saved outcome or agents_get_output for its detailed output; thinking and tool calls are opt-in. These are read-only retrieval tools, not a reason to repeatedly poll active workers."""
    SKILL_SELECTION_GUIDANCE = r"""Load materially relevant non-preloaded Skills before planning or implementation; reuse already loaded instructions."""
    EXECUTION_PRIORITY_GUIDANCE = r"""After a tool result, take the next evidence-producing action. Convert surprises into a specific hypothesis, check literal commands/paths and current artifacts, and run a distinguishing test. Update the diagnosis from evidence. Preserve the requested scope; use bounded implementation checkpoints to finish it."""

    # Skills supplement this policy; they cannot turn a disabled capability on.
    CHECKLIST_DISABLED_GUIDANCE = (
        "Checklists are disabled for this Task by its locked user settings. Do not create, update, resume or verify "
        "durable Checklists, simulate their state through files, or delegate around this restriction. "
        "Checklist directions in Skills apply only when the capability is enabled. Plan as needed, carry out the "
        "complete requested work, validate it and answer directly without a Checklist continuation or review gate."
    )
    BASE_AGENT_GUIDANCE = AGENT_GUIDANCE

    @classmethod
    def agent_guidance(cls, checklists_enabled: bool = True) -> str:
        return cls.AGENT_GUIDANCE if checklists_enabled else cls.BASE_AGENT_GUIDANCE

    # Bound to CHECKLIST_GUIDANCE after the generic Checklist definitions load.
    EXPERT_MODE_GUIDANCE = ""
    SOURCE_COMPREHENSION_GUIDANCE = r"""Read the entire current file when reasonably sized. For large files read the complete affected functions/types, relevant data definitions, callers/callees and tests. For cross-cutting edits cover each affected subsystem. Use narrow searches to navigate, then coherent context to edit. Refresh stale source after edits by others or failed anchors."""
    WEB_RESEARCH_GUIDANCE = r"""Before major or unfamiliar/version-sensitive work, prefer primary API documentation, release notes and a known-good example. Immediately use web_search for unfamiliar terms, APIs, errors or releases; verify current facts rather than guessing. Use Velox native web_search/web_fetch, fetch context-heavy pages sequentially, and reuse confirmed evidence. For empty, blocked or JavaScript-only pages try browser_run_headless on the URL. Keep shell/Python for local execution rather than web retrieval."""
    BUILD_TEST_VISUAL_GUIDANCE = r"""Respect the pixels. Implement one coherent observable behavior, build/run the smallest real target, inspect actual output/state and representative pixels, add a defect regression, repair and rerun before expanding. Keep material runtime/visual defects in progress. Use real user-facing production paths; source, a stub, metadata or exit code alone cannot prove behavior. For each named visual demo/state, inspect its defining feature and use distinct states for temporal behavior. Resolve conflicting image findings with focused diagnostics and fresh post-fix captures. Preserve validated work while repairing the causal subsystem."""

    @classmethod
    def engineering_workflow_guidance(
        cls, *, file_tools: bool, system_tools: bool, web_tools: bool, checklists_enabled: bool = True,
    ) -> str:
        """Return one concise capability-aware workflow block for Chat and Agent prompts."""
        steps = [
            "Understand what the user actually needs and preserve explicit constraints. " + QUALITY_EFFORT_GUIDANCE,
            cls.EXPERT_MODE_GUIDANCE if checklists_enabled else cls.CHECKLIST_DISABLED_GUIDANCE,
        ]
        if file_tools:
            steps.append(cls.SOURCE_COMPREHENSION_GUIDANCE)
        if web_tools:
            steps.append(cls.WEB_RESEARCH_GUIDANCE)
        if system_tools:
            steps.append(cls.BUILD_TEST_VISUAL_GUIDANCE)
        steps.append(
            "Validate the final integrated artifact against the complete request. Run focused and full checks, "
            "reconcile evidence with current files, and report exact results and any untested environment. "
            + ("For Checklist work, finish the independent root acceptance pass before claiming success. " if checklists_enabled else "")
            + REVIEW_EVIDENCE_GUIDANCE
        )
        numbered = (f"{index}. {text}" for index, text in enumerate(steps, 1))
        return "STREAMLINED ENGINEERING WORKFLOW\n\n" + "\n\n".join(numbered)

    EXECUTION_TIMEOUT_GUIDANCE = r"""Each shell_exec/python_exec call supplies a positive finite timeout_minutes sized for the operation. Await a state-changing result before dependent work. Diagnose stalls from output/progress and cancellation rather than merely enlarging the timeout."""

    MARKDOWN_GUIDANCE = r"""Display useful images once at first mention: ![alt text](path-or-URL). Use image_analyze when content or relevance is uncertain. Prefer concise Chat-relative links: result.png resolves from workspace; workspace/, attachments/, attachments_processed/ and temp/ resolve from their Chat directories. Absolute local paths open the parent directory; web URLs are clickable. Wrap paths with spaces in inline code only when mentioned as text. Select readable relevant images and omit decorative duplicates."""
    BROWSER_VERIFICATION_GUIDANCE = r"""Use 1920x1080 by default (bounds 1280x720 through 3820x2160). Read each screenshot's visualReview.reviews. Add a specialized review for a new question or newer diagnostic capture. Validate expected pixels as well as DOM, tests and markers; resolve material discrepancies."""
    SLEEP_GUIDANCE = r"""Use time_sleep for a concrete external wait with a wake instruction. Agent results return automatically; do useful independent work while waiting."""
    TERMINAL_GUIDANCE = r"""Use terminal tools for interactive/long commands, prompts, SSH, servers and builds. Reconnect to the existing terminal. terminal_write sends exact input; terminal_write_line adds Enter; terminal_respond answers prompts; terminal_send_key sends control/navigation; terminal_interrupt sends Ctrl+C; terminal_read reads output. Terminals are owner-private. Use shell_exec for simple one-shot commands (including Git). Windows shell_exec uses cmd.exe: separate commands with &&, & or ||; a semicolon is literal. Read the returned returncode. Prefer native file/search tools for discovery."""

    def __init__(self, paths: AppPaths, context_docs: "ContextDocStore | None" = None):
        self.paths = paths
        self.context_docs = context_docs
        self.week_chat_selection_provider: Callable[[str], Any] | None = None

    def set_week_chat_selection_provider(self, provider: Callable[[str], Any] | None) -> None:
        """Bind process-local Calendar selection state without persisting UI details."""
        self.week_chat_selection_provider = provider

    def _week_chat_selection(self, day_value: str) -> tuple[str, str] | None:
        provider = self.week_chat_selection_provider
        if provider is None:
            return None
        raw = provider(day_value)
        if isinstance(raw, dict):
            kind = str(raw.get("kind") or "").strip().lower()
            object_id = str(raw.get("id") or raw.get("object_id") or "").strip()
        elif isinstance(raw, (tuple, list)) and len(raw) >= 2:
            kind = str(raw[0] or "").strip().lower()
            object_id = str(raw[1] or "").strip()
        else:
            return None
        if kind not in {"item", "event"} or not object_id:
            return None
        return kind, object_id

    @staticmethod
    def _prompt_path(path: Path) -> str:
        return str(path).replace("\\", "/")

    def assemble_chat_context(self, _scope_id: str, chat_id: str) -> list[dict[str, Any]]:
        try:
            manifest = read_json(self.paths.app_json_path, {}) or {}
            config = manifest.get("settings") if isinstance(manifest, dict) else {}
        except Exception:
            config = {}
        # A missing/corrupt policy is an error, never permission to enable tools.
        chat_meta = validate_chat_record(
            read_json(self.paths.chat_json(chat_id)),
            expected_chat_id=chat_id,
            location=str(self.paths.chat_json(chat_id)),
        )
        config_features = config.get("features") if isinstance(config, dict) else {}
        tool_features = normalize_tool_feature_flags(
            chat_meta.get("features"),
            config_features if isinstance(config_features, dict) else None,
        )
        file_tools = bool(tool_features.get("file_tools_enabled"))
        system_tools = bool(tool_features.get("system_tools_enabled"))
        web_tools = bool(tool_features.get("web_tools_enabled"))
        agent_tools = bool(tool_features.get("agent_tools_enabled"))
        chat_tools = bool(tool_features.get("chat_history_enabled"))
        checklists_enabled = bool(tool_features["checklists_enabled"])
        any_tools = any(tool_features.values())

        sections = [
            (
                "You are an assistant inside Velox, a local personal AI chat application. Be practical, accurate, "
                + (
                    "and use only the native tools supplied with this Task when useful."
                    if any_tools
                    else "and answer directly using the supplied context; no tools are enabled for this Task."
                )
            ),
        ]
        if not any_tools:
            sections.append(
                "NO TOOLS - ALL CAPABILITIES DISABLED\n\n"
                "File, System, Web, Agent, Chat-history and Checklist tools are disabled. Answer directly from supplied "
                "context. Do not pretend unavailable research, file access, external verification or background work occurred."
            )
        else:
            enabled_labels = [
                label for key, label in CHAT_TOOL_CATEGORY_LABELS if tool_features.get(key)
            ]
            sections.append(
                "TASK TOOL POLICY\n\nEnabled categories: "
                + ", ".join(enabled_labels)
                + ". Use no other category."
            )
            if system_tools and not file_tools:
                sections.append(
                    "FILE TOOL BOUNDARY\n\nFile tools are disabled. Do not use shell_exec, python_exec, "
                    "terminal tools, or another System tool as a substitute for reading, writing, editing, "
                    "searching, importing, or deleting local files."
                )

        sections.append(host_environment_prompt())
        sections.append(self.engineering_workflow_guidance(
            file_tools=file_tools, system_tools=system_tools, web_tools=web_tools, checklists_enabled=checklists_enabled,
        ))

        if file_tools:
            sections.append(
                "PATHS\n\n"
                "Velox application root:\n" + self._prompt_path(self.paths.root_dir)
                + "\n\nCurrent chat directory:\n" + self._prompt_path(self.paths.chat_dir(chat_id))
                + "\n\nDurable workspace:\n" + self._prompt_path(self.paths.chat_workspace_dir(chat_id))
                + "\n\nTemporary directory:\n" + self._prompt_path(self.paths.chat_temp_dir(chat_id))
                + "\n\nRead-only user attachments:\n" + self._prompt_path(self.paths.chat_attachments_dir(chat_id))
                + "\n\nSkills root:\n" + self._prompt_path(self.paths.skills_dir())
                + "\n\n" + self.FILE_GUIDANCE
            )

        if system_tools:
            sections.extend([
                "GENERAL BEHAVIOR\n\n" + self.SKILL_SELECTION_GUIDANCE,
                "EXECUTION PRIORITY\n\n" + self.EXECUTION_PRIORITY_GUIDANCE,
                "SHELL AND PYTHON TIMEOUTS\n\n" + self.EXECUTION_TIMEOUT_GUIDANCE,
                self.MARKDOWN_GUIDANCE,
                self.SLEEP_GUIDANCE,
                "INTERACTIVE TERMINALS\n\n" + self.TERMINAL_GUIDANCE,
            ])
            account_block = github_account_prompt_block(CredentialStore(self.paths).load_github())
            if account_block:
                sections.append(account_block)
        else:
            sections.append(
                "GENERAL BEHAVIOR\n\nComplete the user's requested outcome faithfully. Preserve explicit constraints, "
                "distinguish facts from uncertainty, and do not promise an action that this Task cannot execute."
            )

        if agent_tools:
            sections.append("BACKGROUND AGENTS\n\n" + self.agent_guidance(checklists_enabled))

        if web_tools:
            sections.append("BROWSER VERIFICATION\n\n" + self.BROWSER_VERIFICATION_GUIDANCE)
        if chat_tools:
            sections.append(
                "CHAT HISTORY\n\nUse the supplied chat-history functions only when prior stored conversation context "
                "materially helps. Do not claim to have searched history unless a native function result confirms it."
            )

        # Request-varying Context Docs and Calendar state are deliberately not
        # placed in the leading system message. ChatRuntime appends durable hidden
        # context snapshots in chronological order instead, so a changed document,
        # event, or UI selection extends the request suffix rather than invalidating
        # the entire provider prefix/KV cache for an established Chat.
        content = "\n\n".join(part for part in sections if str(part or "").strip())
        return [{"role": "system", "content": content}]


def chat_summary_markdown(summary: dict[str, Any]) -> str:
    """Return the best stored summary text from one chat summary object."""
    if not isinstance(summary, dict):
        return ""
    return str(
        summary.get("bullet_summary_markdown")
        or summary.get("summary_markdown")
        or summary.get("one_sentence_summary")
        or ""
    ).strip()


def build_all_chat_summaries(
    paths: AppPaths,
    chats: ChatStore,
    *,
    max_chars: int | None = None,
    exclude_chat_id: str | None = None,
) -> tuple[list[dict[str, Any]], str]:
    """Append stored chat summaries newest-first without splitting a chat block.

    When ``max_chars`` is supplied, the first older block that would exceed the
    budget terminates collection. This preserves strict newest-first priority.
    """
    budget = TOOL_RESULT_MAX_CHARS if max_chars is None else max(0, int(max_chars))
    rows: list[dict[str, Any]] = []
    blocks: list[str] = []
    used = 0
    ordered_chats = sorted(
        chats.list_chats(APP_SCOPE_ID),
        key=lambda row: (
            str(row.get("updated_at") or row.get("created_at") or ""),
            str(row.get("chat_id") or ""),
        ),
        reverse=True,
    )
    for chat in ordered_chats:
        chat_id = str(chat.get("chat_id") or "")
        if not chat_id or chat_id == str(exclude_chat_id or ""):
            continue
        summary = load_chat_summary_record(paths, chat_id)
        text = chat_summary_markdown(summary)
        if not text:
            continue
        name = str(chat.get("name") or "Chat").strip() or "Chat"
        updated_at = str(chat.get("updated_at") or summary.get("updated_at") or "")
        block = f"## {name}\nChat ID: {chat_id}\nUpdated: {updated_at or 'unknown'}\n{text}".strip()
        addition = block if not blocks else "\n\n" + block
        if len(addition) + used > budget:
            break
        used += len(addition)
        blocks.append(block)
        rows.append({
            "chat_id": chat_id,
            "name": name,
            "updated_at": updated_at,
            "one_sentence_summary": str(summary.get("one_sentence_summary") or ""),
            "summary_markdown": text,
        })
    return rows, "\n\n".join(blocks)


def build_recent_chat_context_lines(
    paths: AppPaths,
    chats: ChatStore,
    *,
    max_chars: int,
    exclude_chat_id: str | None = None,
) -> tuple[list[dict[str, Any]], str]:
    """Return newest-first one-line context for every other chat that fits.

    Chats without a generated summary are still represented so a newly opened
    conversation receives a complete view of recent chat titles rather than
    silently omitting threads whose background summary has not run yet.
    """
    budget = max(0, int(max_chars or 0))
    candidates: list[dict[str, Any]] = []
    ordered_chats = sorted(
        chats.list_chats(APP_SCOPE_ID),
        key=lambda row: (
            str(row.get("updated_at") or row.get("created_at") or ""),
            str(row.get("chat_id") or ""),
        ),
        reverse=True,
    )
    for chat in ordered_chats:
        chat_id = str(chat.get("chat_id") or "")
        if not chat_id or chat_id == str(exclude_chat_id or ""):
            continue
        summary = load_chat_summary_record(paths, chat_id)
        one_line = str(summary.get("one_sentence_summary") or "").strip()
        if not one_line:
            one_line = one_sentence_from_summary(chat_summary_markdown(summary))
        one_line = re.sub(r"\s+", " ", one_line).strip()
        if not one_line:
            one_line = "No stored summary yet."
        name = re.sub(r"\s+", " ", str(chat.get("name") or "Chat")).strip() or "Chat"
        candidates.append({
            "chat_id": chat_id,
            "name": name[:160],
            "updated_at": str(chat.get("updated_at") or summary.get("updated_at") or ""),
            "one_sentence_summary": one_line[:360],
        })

    rows: list[dict[str, Any]] = []
    lines: list[str] = []
    used = 0
    for row in candidates:
        line = f"- {row['name']} [{row['chat_id']}]: {row['one_sentence_summary']}"
        addition = line if not lines else "\n" + line
        if used + len(addition) > budget:
            break
        rows.append(row)
        lines.append(line)
        used += len(addition)
    omitted = len(candidates) - len(rows)
    if omitted:
        marker = f"- [{omitted} older chat(s) omitted from the configured history snapshot.]"
        addition = marker if not lines else "\n" + marker
        if used + len(addition) <= budget:
            lines.append(marker)
    return rows, "\n".join(lines)


def register_current_asyncio_task_cancel(
    monitor: "LLMTaskMonitor | None", request_id: str | None,
) -> None:
    """Make a monitor Cancel action terminate the owning coroutine safely.

    System summary/compaction requests are ordinary asyncio tasks rather than
    ChatRuntime or AgentRuntime owners. Registering their exact current task keeps
    Dashboard cancellation truthful and prevents background-summary shutdown from
    merely changing monitor state while the provider request continues.
    """
    if monitor is None or not request_id:
        return
    try:
        task = asyncio.current_task()
        loop = asyncio.get_running_loop()
    except RuntimeError:
        return
    if task is None:
        return

    def cancel_task() -> bool:
        if task.done():
            return False
        try:
            loop.call_soon_threadsafe(task.cancel)
            return True
        except Exception:
            return False

    monitor.register_cancel_callback(request_id, cancel_task)


class SummaryService:
    """Maintain one independent stored summary per chat."""

    def __init__(self, storage: Storage, chats: ChatStore, llm: LLMClient, monitor: "LLMTaskMonitor | None" = None):
        self.storage = storage
        self.paths = storage.paths
        self.chats = chats
        self.llm = llm
        self.monitor = monitor
        self.max_chat_summaries_per_tick = 1
        self._discarded_chat_ids: set[str] = set()

    def discard_chat(self, chat_id: str) -> None:
        """Prevent any in-flight summary request from writing this deleted chat."""
        resolved = str(chat_id or "").strip()
        if resolved:
            self._discarded_chat_ids.add(resolved)

    def restore_chat(self, chat_id: str) -> None:
        """Resume summaries when a requested deletion failed and the chat remains."""
        resolved = str(chat_id or "").strip()
        if resolved:
            self._discarded_chat_ids.discard(resolved)

    def _write_summary_if_chat_exists(self, chat_id: str, path: Path, obj: dict[str, Any]) -> None:
        """Atomically write a summary only while its owning chat still exists.

        The same app-root lock is acquired by ChatStore.delete_chat(). Holding it
        across the existence check and atomic replacement closes the race where a
        slow summary LLM response could recreate a chat directory after deletion.
        """
        resolved = str(chat_id or "").strip()
        summary_path = Path(path)
        with DATA_ROOTS.lock_for_path(summary_path):
            if resolved in self._discarded_chat_ids or not self.paths.chat_json(resolved).is_file():
                raise FileNotFoundError(
                    f"chat was deleted while its summary was being generated: {resolved or '<missing>'}"
                )
            atomic_write_json(summary_path, obj)

    @staticmethod
    def _clamp_summary(text: str, hard_limit: int) -> str:
        text = (text or "").strip()
        if len(text) <= hard_limit:
            return text
        cut = text[:hard_limit].rstrip()
        para = cut.rfind("\n\n")
        sent = max(cut.rfind(". "), cut.rfind("! "), cut.rfind("? "))
        boundary = para if para > int(hard_limit * 0.72) else sent
        if boundary > int(hard_limit * 0.72):
            cut = cut[:boundary + 1].rstrip()
        return cut[:hard_limit].rstrip()

    async def _fast_summary_call_or_none(
        self,
        _scope_id: str,
        prompt: str,
        *,
        description: str = "Chat summary",
        metadata: dict[str, Any] | None = None,
    ) -> str | None:
        monitor_metadata = dict(metadata or {"background": True})
        monitor_metadata.setdefault("prompt", prompt)
        req_id = self.monitor.start(
            APP_SCOPE_ID, description, task_kind="summary", metadata=monitor_metadata,
        ) if self.monitor else None
        register_current_asyncio_task_cancel(self.monitor, req_id)
        try:
            response = await self.llm.chat_completions_once_full(
                LLMRequest(
                    scope_id=APP_SCOPE_ID, endpoint_profile_id="fast",
                    messages=[{"role": "user", "content": prompt}], stream=False,
                    monitor_task_id=req_id, task_kind="system", task_title=description,
                )
            )
            text = completed_document_text(response, operation="Chat summary")
            if self.monitor:
                self.monitor.update_metadata(req_id, {"output": text}, persist=True)
                self.monitor.complete(req_id)
            return text
        except asyncio.CancelledError:
            if self.monitor:
                self.monitor.cancel(req_id)
            raise
        except (asyncio.TimeoutError, TimeoutError) as exc:
            if self.monitor:
                self.monitor.fail(req_id, str(exc))
            self.storage.append_app_log("summary.llm.timeout", {"error": str(exc)})
            return None
        except Exception as exc:
            if self.monitor:
                self.monitor.fail(req_id, f"{type(exc).__name__}: {exc}")
            self.storage.append_app_log("summary.llm.failed", {"error": f"{type(exc).__name__}: {exc}"})
            return None

    async def idle_tick(
        self,
        _active_scope_id: str | None = None,
        *,
        idle_guard: Callable[[], bool] | None = None,
    ) -> None:
        """Refresh at most one stale Chat summary while the app remains truly idle.

        The caller owns the 15-second quiescence timer. This guard is rechecked
        before every candidate and immediately before endpoint work so a Task or
        tool that starts between desktop frames cannot race a background summary.
        """
        refreshed = 0
        for chat in self.chats.list_chats(APP_SCOPE_ID):
            if callable(idle_guard) and not bool(idle_guard()):
                return
            chat_id = str(chat.get("chat_id") or "")
            if not chat_id or self.is_chat_summary_current(APP_SCOPE_ID, chat_id):
                continue
            try:
                if callable(idle_guard) and not bool(idle_guard()):
                    return
                await self.refresh_chat_summary(APP_SCOPE_ID, chat_id)
                refreshed += 1
                if refreshed >= self.max_chat_summaries_per_tick:
                    return
            except asyncio.CancelledError:
                raise
            except (asyncio.TimeoutError, TimeoutError) as exc:
                self.storage.append_app_log("summary.idle_tick.timeout", {"chat_id": chat_id, "error": str(exc)})
            except Exception as exc:
                self.storage.append_app_log("summary.idle_tick.failed", {"chat_id": chat_id, "error": f"{type(exc).__name__}: {exc}"})

    def chat_summary_fingerprint(self, _scope_id: str, chat_id: str) -> str:
        turns = [turn for turn in self.chats.load_turns(APP_SCOPE_ID, chat_id) if turn.get("role") in ("user", "assistant")]
        return chat_turns_summary_fingerprint(turns)

    def is_chat_summary_current(self, _scope_id: str, chat_id: str) -> bool:
        summary = load_chat_summary_record(self.paths, chat_id)
        return bool(not summary.get("stale") and summary.get("source_fingerprint") == self.chat_summary_fingerprint(APP_SCOPE_ID, chat_id))

    async def refresh_chat_summary(self, _scope_id: str, chat_id: str) -> dict[str, Any]:
        path = self.paths.chat_summary_json(chat_id)
        existing = load_chat_summary_record(self.paths, chat_id)
        if llm_endpoint_missing(self.llm, "fast"):
            return existing
        turns = [turn for turn in self.chats.load_turns(APP_SCOPE_ID, chat_id) if turn.get("role") in ("user", "assistant")]
        fingerprint = chat_turns_summary_fingerprint(turns)
        if turns and not existing.get("stale") and existing.get("source_fingerprint") == fingerprint:
            return existing
        if not turns:
            obj = default_chat_summary(
                chat_id, self.chats.get_chat_endpoint_profile_id(chat_id),
            )
            obj.update({
                "updated_at": now_iso(),
                "source_fingerprint": fingerprint,
                "source_turn_count": 0,
                "stale": False,
            })
            self._write_summary_if_chat_exists(chat_id, path, obj)
            return obj

        source_blocks: list[str] = []
        for turn in turns[-80:]:
            role = str(turn.get("role") or "message").lower()
            text = strip_reasoning_content(str(turn.get("text") or "")).strip()[:4000]
            label = "USER-PROVIDED TEXT" if role == "user" else "AI-GENERATED RESPONSE"
            if text:
                source_blocks.append(f"## {label}\n{text}")
            if role == "assistant":
                for call in (turn.get("tool_calls") or [])[:12]:
                    if not isinstance(call, dict):
                        continue
                    tool_name = str(call.get("tool_name") or call.get("name") or "tool")
                    excerpt = str(call.get("output_excerpt") or call.get("output") or call.get("result") or call.get("error") or "").strip()[:2000]
                    if excerpt:
                        source_blocks.append(f"## TOOL-GATHERED INPUT: {tool_name}\n{excerpt}")
        body = "\n\n".join(source_blocks)
        prompt = chat_summary_prompt_from_config(self.storage.load_config()) + "\n\n# Chat content\n" + body[-24000:]
        generated = await self._fast_summary_call_or_none(
            APP_SCOPE_ID,
            prompt,
            description="Idle chat summary",
            metadata={"background": True, "chat_id": chat_id},
        )
        if generated is None:
            return existing
        one, bullets = parse_generated_chat_summary(generated)
        bullets = self._clamp_summary(bullets or generated, CHAT_BULLET_SUMMARY_HARD_CHARS)
        one = self._clamp_summary(one or one_sentence_from_summary(bullets), CHAT_ONE_SENTENCE_SUMMARY_HARD_CHARS)
        obj = default_chat_summary(
            chat_id, self.chats.get_chat_endpoint_profile_id(chat_id),
        )
        obj.update({
            "updated_at": now_iso(),
            "one_sentence_summary": one,
            "bullet_summary_markdown": bullets,
            "summary_markdown": bullets,
            "source_fingerprint": fingerprint,
            "source_turn_count": len(turns),
            "stale": False,
        })
        self._write_summary_if_chat_exists(chat_id, path, obj)
        self.storage.append_app_log("chat.summary.updated", {"chat_id": chat_id, "turn_count": len(turns)})
        return obj


def llm_endpoint_missing(llm: Any, endpoint_profile_id: str) -> bool:
    """Return whether a concrete Velox client lacks the selected endpoint profile config.

    Test doubles intentionally need only implement the request method. Using
    ``isinstance`` keeps those lightweight while also covering legitimate
    LLMClient subclasses, unlike the former exact-class identity checks.
    """
    return isinstance(llm, LLMClient) and not llm.is_endpoint_configured(endpoint_profile_id)


class SearchService(_StoragePathBound):
    """Bounded search over app chat data and chat-local files."""

    SEARCHABLE_SCOPES = frozenset({"chats", "logs", "files", "web"})


    def search_app(self, query: str, limit: int = 200, scopes: Any = None) -> list[dict[str, Any]]:
        terms = [part.lower() for part in re.split(r"\s+", str(query or "").strip()) if part]
        if not terms:
            return []
        normalized_scopes = self._normalize_scopes(scopes)
        candidates: list[tuple[Path, str, str | None]] = []
        if "logs" in normalized_scopes and self.paths.log_jsonl_path.exists():
            candidates.append((self.paths.log_jsonl_path, "log", None))
        for chat in ChatStore(self.storage).list_chats(APP_SCOPE_ID):
            chat_id = str(chat.get("chat_id") or "")
            chat_dir = self.paths.chat_dir(chat_id)
            if "chats" in normalized_scopes:
                for name in ("chat.json", "turns.jsonl", "summary.json"):
                    candidate = chat_dir / name
                    if candidate.exists():
                        candidates.append((candidate, "chat", chat_id))
            if "files" in normalized_scopes:
                workspace = self.paths.chat_workspace_dir(chat_id)
                if workspace.exists():
                    candidates.extend((path, "file", chat_id) for path in workspace.rglob("*") if path.is_file())
            if "web" in normalized_scopes:
                web_dir = self.paths.chat_web_dir(chat_id)
                if web_dir.exists():
                    candidates.extend((path, "web", chat_id) for path in web_dir.rglob("*") if path.is_file())

        results: list[dict[str, Any]] = []
        allowed_suffixes = {".txt", ".md", ".json", ".jsonl", ".py", ".log", ".toml", ".yaml", ".yml", ".csv", ".html"}
        for candidate, result_type, chat_id in candidates:
            if len(results) >= max(1, int(limit)) * 3:
                break
            if candidate.suffix.lower() not in allowed_suffixes:
                continue
            try:
                if candidate.stat().st_size > 2_000_000:
                    continue
                text = file_read_text(candidate, encoding="utf-8", errors="replace")
            except Exception:
                continue
            lowered = text.lower()
            if not all(term in lowered for term in terms):
                continue
            first = min((lowered.find(term) for term in terms if term in lowered), default=0)
            try:
                rel = candidate.relative_to(self.paths.root_dir).as_posix()
            except Exception:
                rel = str(candidate)
            results.append({
                "type": result_type,
                "chat_id": chat_id,
                "path": rel,
                "snippet": self._make_snippet(text, first),
                "score": sum(lowered.count(term) for term in terms),
            })
        return sorted(results, key=lambda row: (-int(row.get("score", 0)), str(row.get("path", ""))))[:max(1, int(limit))]

    def _normalize_scopes(self, scopes: Any) -> set[str]:
        if scopes is None:
            return set(self.SEARCHABLE_SCOPES)
        values = [scopes] if isinstance(scopes, str) else list(scopes) if isinstance(scopes, (list, tuple, set, frozenset)) else []
        aliases = {"file": "files", "work": "files", "chat": "chats"}
        normalized = {aliases.get(str(value or "").strip().lower(), str(value or "").strip().lower()) for value in values}
        normalized &= set(self.SEARCHABLE_SCOPES)
        return normalized or set(self.SEARCHABLE_SCOPES)

    def search_chats(self, query: str, limit: int = 100) -> list[dict[str, Any]]:
        terms = [part.lower() for part in re.split(r"\s+", str(query or "").strip()) if part]
        if not terms:
            return []
        store = ChatStore(self.storage)
        results: list[dict[str, Any]] = []
        for chat in store.list_chats():
            chat_id = str(chat.get("chat_id") or "")
            chat_name = str(chat.get("name") or "Chat")
            name_lower = chat_name.lower()
            if all(term in name_lower for term in terms):
                results.append({
                    "type": "chat",
                    "chat_id": chat_id,
                    "turn_id": None,
                    "name": chat_name,
                    "role": "chat",
                    "snippet": chat_name,
                    "score": 100 + sum(name_lower.count(term) for term in terms),
                })
            for turn in store.load_turns(APP_SCOPE_ID, chat_id):
                turn_text = strip_reasoning_content(str(turn.get("text") or ""))
                lowered = turn_text.lower()
                if not all(term in lowered for term in terms):
                    continue
                first = min((lowered.find(term) for term in terms if term in lowered), default=0)
                results.append({
                    "type": "chat",
                    "chat_id": chat_id,
                    "turn_id": turn.get("turn_id"),
                    "name": chat_name,
                    "role": turn.get("role", "message"),
                    "snippet": self._make_snippet(turn_text, first),
                    "score": sum(lowered.count(term) for term in terms),
                })
                if len(results) >= max(1, int(limit)) * 2:
                    break
        return sorted(results, key=lambda row: (-int(row.get("score", 0)), str(row.get("name", ""))))[:max(1, int(limit))]

    @staticmethod
    def _make_snippet(text: str, index: int, radius: int = 140) -> str:
        clean = " ".join(str(text or "").replace("\r", " ").replace("\n", " ").split())
        if not clean:
            return ""
        start = max(0, int(index) - radius)
        end = min(len(clean), int(index) + radius)
        return ("..." if start else "") + clean[start:end] + ("..." if end < len(clean) else "")


class ToolCancelledError(RuntimeError):
    """Raised by a tool that observed an explicit cancellation request."""

    def __init__(self, message: str = "Tool call cancelled") -> None:
        super().__init__(str(message or "Tool call cancelled"))


@dataclass
class ToolContext:
    scope_id: str
    chat_id: str | None = None
    agent_id: str | None = None
    agent_task_run_id: int | None = None
    endpoint_profile_id: str | None = None
    allow_web_search: bool = True
    tool_call_id: str | None = None
    monitor_task_id: str | None = None
    task_kind: str = ""
    cancel_event: threading.Event | None = None
    progress_callback: Callable[[dict[str, Any]], None] | None = None

    def is_cancelled(self) -> bool:
        return bool(self.cancel_event and self.cancel_event.is_set())

    def raise_if_cancelled(self, message: str = "Tool call cancelled") -> None:
        if self.is_cancelled():
            raise ToolCancelledError(message)

    def report_progress(self, **fields: Any) -> None:
        self.raise_if_cancelled()
        callback = self.progress_callback
        if callback is not None and fields:
            callback(dict(fields))


@dataclass
class ActiveToolExecution:
    tool_call_id: str
    tool_name: str
    chat_id: str | None
    agent_id: str | None
    started_mono: float
    cancel_event: threading.Event
    loop: asyncio.AbstractEventLoop
    live_record: dict[str, Any]
    task: asyncio.Task[Any] | None = None
    cancel_reason: str = ""
    cancelled_by_user: bool = False


@dataclass
class ToolDefinition:
    name: str
    description: str
    parameters: dict[str, Any]
    handler: Callable[[ToolContext, dict[str, Any]], Any]
    positional_arguments: tuple["ToolArgumentSpec", ...] = ()

    def __post_init__(self) -> None:
        """Reject malformed registrations before they can break every Chat/Agent request."""
        if self.positional_arguments is None:
            raise TypeError(f"Tool {self.name!r} positional_arguments cannot be None")
        if not isinstance(self.positional_arguments, tuple):
            self.positional_arguments = tuple(self.positional_arguments)
        if not callable(self.handler):
            raise TypeError(f"Tool {self.name!r} handler must be callable")
        if not isinstance(self.parameters, dict):
            raise TypeError(f"Tool {self.name!r} parameters must be a JSON-schema object")
        if self.parameters.get("type") not in (None, "object"):
            raise TypeError(f"Tool {self.name!r} parameters must describe a JSON object")
        properties = self.parameters.get("properties") or {}
        if not isinstance(properties, dict):
            raise TypeError(f"Tool {self.name!r} schema properties must be an object")
        signature_names = [str(argument.name) for argument in self.positional_arguments]
        if len(signature_names) != len(set(signature_names)):
            raise TypeError(f"Tool {self.name!r} positional argument names must be unique")
        property_names = [str(name) for name in properties]
        if set(signature_names) != set(property_names):
            schema_only = sorted(set(property_names) - set(signature_names))
            signature_only = sorted(set(signature_names) - set(property_names))
            details = []
            if schema_only:
                details.append("schema-only: " + ", ".join(schema_only))
            if signature_only:
                details.append("signature-only: " + ", ".join(signature_only))
            raise TypeError(
                f"Tool {self.name!r} JSON schema and native signature disagree ({'; '.join(details)})"
            )
        required = self.parameters.get("required") or []
        if not isinstance(required, list) or any(not isinstance(name, str) for name in required):
            raise TypeError(f"Tool {self.name!r} schema required must be an array of field names")
        unknown_required = sorted(set(required) - set(property_names))
        if unknown_required:
            raise TypeError(
                f"Tool {self.name!r} schema requires unknown field(s): {', '.join(unknown_required)}"
            )
        for argument in self.positional_arguments:
            schema = properties.get(argument.name) or {}
            if not isinstance(schema, dict):
                raise TypeError(f"Tool {self.name!r} schema for {argument.name!r} must be an object")
            declared_types: set[str] = set()
            if isinstance(schema.get("type"), str):
                declared_types.add(str(schema["type"]))
            for branch in schema.get("anyOf") or []:
                if isinstance(branch, dict) and isinstance(branch.get("type"), str):
                    declared_types.add(str(branch["type"]))
            if argument.value_type == "boolean":
                compatible = "boolean" in declared_types
            elif argument.value_type == "number":
                compatible = bool(declared_types.intersection({"integer", "number"}))
            elif argument.value_type == "text" and argument.encoding in {"json_array", "lines"}:
                compatible = "array" in declared_types
            elif argument.value_type == "text" and argument.encoding == "json_object":
                compatible = "object" in declared_types
            elif argument.value_type == "text":
                compatible = "string" in declared_types
            else:
                raise TypeError(
                    f"Tool {self.name!r} has unsupported native argument contract "
                    f"{argument.value_type!r}/{argument.encoding!r} for {argument.name!r}"
                )
            if declared_types and not compatible:
                raise TypeError(
                    f"Tool {self.name!r} argument {argument.name!r} schema type(s) "
                    f"{sorted(declared_types)!r} do not match native contract "
                    f"{argument.value_type!r}/{argument.encoding!r}"
                )


@dataclass(frozen=True)
class ToolArgumentSpec:
    """One canonical function argument mapped to an existing Velox handler."""

    name: str
    value_type: str
    encoding: str = "text"


# Native Chat Completions function arguments are JSON. Long code, patches, prompts,
# and commands are substantially less fragile when a model may send an array of
# source lines rather than one deeply escaped string. Velox joins these arrays with
# literal newlines before invoking the existing handler. Paths, URLs, identifiers,
# and ordinary scalar fields remain strict strings.
NATIVE_LINE_ARRAY_ARGUMENT_NAMES = frozenset({
    "content", "script", "command", "newText", "old", "new", "text", "task", "prompt",
})


# Every registered tool has one fixed canonical argument signature. OpenAI-native
# JSON arguments are validated against the public schema, then decoded through
# these specifications before invoking the existing handler.
