    def register(self, name: str, description: str, parameters: dict[str, Any], handler: Callable[[ToolContext, dict[str, Any]], Any]) -> None:
        canonical_signature = TOOL_POSITIONAL_SIGNATURES.get(name)
        if canonical_signature is None:
            raise RuntimeError(f"registered tool {name!r} has no canonical native function signature")
        properties = parameters.get("properties") if isinstance(parameters, dict) else {}
        properties = properties if isinstance(properties, dict) else {}
        # Some extensions (currently agents_start) intentionally register a small
        # base schema and replace it with a wider schema later in the same registry
        # construction. Select only canonical specs present in this exact schema,
        # but never tolerate schema fields that lack a canonical native spec.
        signature = tuple(spec for spec in canonical_signature if spec.name in properties)
        missing_specs = sorted(set(properties) - {spec.name for spec in signature})
        if missing_specs:
            raise RuntimeError(
                f"registered tool {name!r} schema has no canonical native signature for: "
                + ", ".join(missing_specs)
            )
        self.tools[name] = ToolDefinition(name, description, parameters, handler, signature)


    def _tool_group_for_name(self, name: str) -> str:
        """Classify every current tool into one user-facing chat toggle."""
        canonical = str(name or "")
        if canonical in EXPERT_MODE_TOOL_NAMES or canonical in set(globals().get("CHECKLIST_TOOL_NAMES", ())):
            return "checklists_enabled"
        if canonical.startswith(FILE_TOOL_PREFIXES):
            return "file_tools_enabled"
        if canonical.startswith("web_") or canonical.startswith("browser_"):
            return "web_tools_enabled"
        if canonical.startswith("chats_"):
            return "chat_history_enabled"
        if canonical.startswith("agents_") or canonical in {
            "terminal_get_agent_terminals", "terminal_get_agent_terminal_output",
        }:
            return "agent_tools_enabled"
        return "system_tools_enabled"


    def _global_group_enabled(self, group_key: str, default: bool = True) -> bool:
        features = self.storage.load_config().get("features") or {}
        if group_key == "file_tools_enabled":
            return bool(features.get("file_tools_enabled", default))
        if group_key == "system_tools_enabled":
            return bool(features.get("system_tools_enabled", default))
        if group_key == "web_tools_enabled":
            return bool(features.get("web_tools_enabled", default))
        if group_key == "agent_tools_enabled":
            return bool(features.get("agent_tools_enabled", default))
        if group_key == "chat_history_enabled":
            return bool(features.get("chat_history_enabled", default))
        return bool(default)

    def _chat_group_enabled(
        self,
        scope_id: str | None,
        chat_id: str | None,
        group_key: str,
        default: bool = True,
        *,
        feature_overrides: dict[str, bool] | None = None,
    ) -> bool:
        if isinstance(feature_overrides, dict) and group_key in feature_overrides:
            return bool(feature_overrides[group_key])
        global_default = self._global_group_enabled(group_key, default)
        if chat_id is None:
            return global_default
        if group_key == "checklists_enabled":
            return bool(ChatStore(self.storage).load_chat_view(str(chat_id))["features"][group_key])
        return ChatStore(self.storage).get_chat_feature(APP_SCOPE_ID, str(chat_id), group_key, global_default)

    def _enabled_tool_definitions(
        self,
        scope_id: str | None,
        chat_id: str | None = None,
        *,
        excluded_names: set[str] | frozenset[str] | None = None,
        feature_overrides: dict[str, bool] | None = None,
    ) -> list[ToolDefinition]:
        excluded = {str(name) for name in (excluded_names or set())}
        # Retained expert_mode_* functions are an internal compatibility adapter for
        # the independent reviewer lifecycle. They must never appear in any
        # model-facing tool list, regardless of provider or feature-toggle path.
        hidden_model_tools = {
            str(name) for name in globals().get("_INTERNAL_EXPERT_TOOL_NAMES", ())
        }
        return [
            tool for tool in sorted(self.tools.values(), key=lambda row: (row.name.casefold(), row.name))
            if tool.name not in excluded
            and tool.name not in hidden_model_tools
            and self._chat_group_enabled(
                scope_id, chat_id, self._tool_group_for_name(tool.name), default=True,
                feature_overrides=feature_overrides,
            )
        ]

    @staticmethod
    def _signature_text(tool: ToolDefinition) -> str:
        arguments = ", ".join(
            f"{argument.name}:{argument.value_type}"
            for argument in tool.positional_arguments
        )
        return f"{tool.name}({arguments})"

    def tool_definitions_for_context(
        self,
        scope_id: str | None,
        chat_id: str | None = None,
        *,
        excluded_names: set[str] | frozenset[str] | None = None,
        feature_overrides: dict[str, bool] | None = None,
    ) -> list[dict[str, Any]]:
        return [
            {
                "name": tool.name,
                "description": tool.description,
                "signature": self._signature_text(tool),
                "arguments": [dataclasses.asdict(argument) for argument in tool.positional_arguments],
                "param_style": "openai_function_json_schema_v1",
            }
            for tool in self._enabled_tool_definitions(
                scope_id, chat_id, excluded_names=excluded_names,
                feature_overrides=feature_overrides,
            )
        ]

    def build_openai_chat_completion_tools(
        self,
        scope_id: str | None,
        chat_id: str | None = None,
        *,
        excluded_names: set[str] | frozenset[str] | None = None,
        feature_overrides: dict[str, bool] | None = None,
    ) -> list[dict[str, Any]]:
        """Expose current Velox tools through OpenAI Chat Completions v1 schemas."""
        rows: list[dict[str, Any]] = []
        for tool in self._enabled_tool_definitions(
            scope_id, chat_id, excluded_names=excluded_names,
            feature_overrides=feature_overrides,
        ):
            parameters = copy.deepcopy(tool.parameters)
            if isinstance(parameters, dict) and parameters.get("type") == "object":
                parameters.setdefault("additionalProperties", False)
                properties = parameters.get("properties")
                if isinstance(properties, dict):
                    for spec in tool.positional_arguments:
                        if (
                            spec.value_type == "text"
                            and spec.encoding == "text"
                            and spec.name in NATIVE_LINE_ARRAY_ARGUMENT_NAMES
                            and isinstance(properties.get(spec.name), dict)
                        ):
                            scalar_schema = copy.deepcopy(properties[spec.name])
                            description = str(scalar_schema.get("description") or "").strip()
                            properties[spec.name] = {
                                "anyOf": [
                                    scalar_schema,
                                    {"type": "array", "items": {"type": "string"}},
                                ],
                                "description": (
                                    description + (" " if description else "")
                                    + "For multiline content, an array of source lines is accepted and joined with literal newlines."
                                ),
                            }
            rows.append({
                "type": "function",
                "function": {
                    "name": tool.name,
                    "description": tool.description,
                    "parameters": _canonical_mapping(parameters),
                },
            })
        return rows

    def build_openai_tool_system_block(
        self,
        scope_id: str | None,
        chat_id: str | None = None,
        *,
        excluded_names: set[str] | frozenset[str] | None = None,
        feature_overrides: dict[str, bool] | None = None,
    ) -> str:
        """Return guidance only for tool schemas actually present in this Task."""
        enabled = self._enabled_tool_definitions(
            scope_id, chat_id, excluded_names=excluded_names,
            feature_overrides=feature_overrides,
        )
        if not enabled:
            return ""
        names = {tool.name for tool in enabled}
        lines = [
            "TOOL CALLING",
            "",
            f"Velox exposes {len(enabled)} currently enabled tools through the provider-native function-calling field. "
            "Use only a supplied function schema. Velox validates the function name and arguments, executes the "
            "registered handler, then appends the matching tool result. Do not emit MCP, Kimi XTML, XML wrappers, "
            "or JSON pseudo-calls in ordinary assistant text. Native function calling is the only executable tool path. "
            "Never announce an action and stop; emit the native function call in the same response. Arguments must be "
            "one complete JSON object that exactly matches the supplied schema. Independent calls may be returned "
            "together, but dependent operations must wait for the preceding tool result.",
        ]
        if names.intersection(EXPERT_MODE_TOOL_NAMES) or names.intersection(set(globals().get("CHECKLIST_TOOL_NAMES", ()))):
            lines.append(
                "Named Checklist tools are execution-scoped durable work controls. Follow the shared Checklist workflow in the base prompt; "
                "use only the advertised generic checklist_* / verify_checklist functions, and never access Checklist state files through "
                "file, shell, Python, document, or terminal tools."
            )
        if names.intersection({"fs_write", "fs_append", "fs_edit", "python_exec", "shell_exec"}):
            lines.append(
                "Use forward-slash paths. Avoid nested shell quoting such as shell_exec with python -c when "
                "python_exec can carry the script directly. For multiline arguments whose schema accepts it, prefer "
                "an array of source lines; Velox joins it with literal newlines. Otherwise use bounded file calls or "
                "smaller sequential calls so quotes, backslashes, and newlines remain valid JSON."
            )
        if names.intersection({"browser_run_headless", "browser_demo_playback"}):
            lines.append(
                "Browser playback key events may use friendly names such as w and left_arrow or DOM code names such "
                "as KeyW and ControlLeft."
            )
        if names.intersection({"drive_list_drives", "drive_list_root", "drive_list_children", "drive_list", "drive_search"}):
            lines.append(
                "For Google Drive discovery, call drive_list_drives first, then drive_list_root for My Drive or a "
                "shared Drive and drive_list_children for folders; set folders_only=true when only directories are "
                "needed. Drive list/search limits accept 1 through 1000; inspect truncated and incomplete flags."
            )
        if "shell_exec" in names:
            lines.append(
                "On Windows, shell_exec uses Windows cmd.exe command-shell semantics, not Bash or PowerShell. "
                "Use && to run a following command only on success, & for unconditional chaining, and || on failure; "
                "semicolon is literal text in cmd.exe and is NOT a command separator, so an unquoted ';' can silently "
                "become part of an option or filename. shell_exec already returns returncode; do not append echo %ERRORLEVEL% "
                "merely to discover exit status. Prefer native Velox file/search tools for file discovery and text search; "
                "for one-shot Windows commands use commands such as dir and where instead of assuming ls, grep, sed, head, or tail exist."
            )
        if names.intersection({"shell_exec", "python_exec"}):
            lines.append(
                "Every shell_exec and python_exec call must include timeout_minutes as a positive finite number. "
                "Choose the smallest realistic per-call budget; omission is a validation error. The user-configured shell/Python execution ceiling (60 minutes by default) caps this budget."
            )
        return "\n\n".join(lines)

    @staticmethod
    def _native_argument_as_positional_text(
        definition: ToolDefinition, spec: ToolArgumentSpec, value: Any,
    ) -> str:
        if spec.value_type == "boolean":
            if not isinstance(value, bool):
                raise ValueError(f"{definition.name} argument {spec.name!r} must be boolean")
            return "true" if value else "false"
        if spec.value_type == "number":
            if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(float(value)):
                raise ValueError(f"{definition.name} argument {spec.name!r} must be a finite number")
            return str(value)
        if spec.value_type != "text":
            raise ValueError(f"unsupported native argument type {spec.value_type!r}")
        if (
            spec.encoding == "text"
            and spec.name in NATIVE_LINE_ARRAY_ARGUMENT_NAMES
            and isinstance(value, list)
        ):
            if any(not isinstance(item, str) for item in value):
                raise ValueError(f"{definition.name} argument {spec.name!r} line array must contain only strings")
            return "\n".join(value)
        if spec.encoding == "json_array":
            if not isinstance(value, list):
                raise ValueError(f"{definition.name} argument {spec.name!r} must be a JSON array")
            return json.dumps(value, ensure_ascii=False, separators=(",", ":"))
        if spec.encoding == "json_object":
            if not isinstance(value, dict):
                raise ValueError(f"{definition.name} argument {spec.name!r} must be a JSON object")
            return json.dumps(value, ensure_ascii=False, separators=(",", ":"))
        if spec.encoding == "lines":
            if not isinstance(value, list) or any(not isinstance(item, str) for item in value):
                raise ValueError(f"{definition.name} argument {spec.name!r} must be an array of strings")
            return "\n".join(value)
        if not isinstance(value, str):
            raise ValueError(f"{definition.name} argument {spec.name!r} must be text")
        return value

    def convert_openai_tool_call(
        self, raw_call: Any,
        *,
        allowed_names: set[str] | None = None,
    ) -> dict[str, Any]:
        """Validate and translate one native function call into the Velox record."""
        if not isinstance(raw_call, dict):
            raise ValueError("native tool call must be an object")
        call_type = str(raw_call.get("type") or "function").strip()
        if call_type != "function":
            raise ValueError(f"native tool call type must be 'function', got {call_type!r}")
        function = raw_call.get("function")
        if not isinstance(function, dict):
            raise ValueError("native tool call is missing a function object")
        name = str(function.get("name") or "").strip()
        call_id = str(raw_call.get("id") or "").strip()
        if not call_id:
            raise ValueError("native tool call is missing id")
        if name not in self.tools:
            raise ValueError(f"unknown tool: {name}")
        if allowed_names is not None and name not in allowed_names:
            raise ValueError(f"tool is disabled or unavailable in this context: {name}")
        raw_arguments = function.get("arguments", "")
        if isinstance(raw_arguments, dict):
            decoded = raw_arguments
            arguments_json = json.dumps(raw_arguments, ensure_ascii=False, separators=(",", ":"))
        else:
            arguments_json = str(raw_arguments or "").lstrip("\ufeff").strip()
            try:
                decoded = json.loads(arguments_json or "{}")
                # A few OpenAI-compatible gateways serialize the JSON object a
                # second time. Accept exactly one complete extra encoding layer;
                # never guess missing braces, quotes, escapes, or truncated text.
                if isinstance(decoded, str):
                    decoded = json.loads(decoded.lstrip("\ufeff").strip() or "{}")
            except Exception as exc:
                raise ValueError(
                    f"{name} arguments must be one complete valid JSON object: {exc}. "
                    "Use forward-slash paths, call python_exec instead of nesting python -c inside shell_exec, "
                    "and split very large multiline arguments into smaller calls."
                ) from exc
        if not isinstance(decoded, dict):
            raise ValueError(f"{name} arguments must decode to a JSON object")
        # Replay the canonical decoded object rather than an accidental second
        # JSON encoding layer. This keeps the stored assistant tool-call message
        # valid for Kimi and other models that require exact multi-turn state.
        arguments_json = json.dumps(decoded, ensure_ascii=False, separators=(",", ":"))
        definition = self.tools[name]
        expected_names = [spec.name for spec in definition.positional_arguments]
        required_names = {
            str(value) for value in (definition.parameters.get("required") or [])
            if isinstance(value, str)
        }
        missing = [key for key in expected_names if key in required_names and key not in decoded]
        extra = [str(key) for key in decoded if str(key) not in expected_names]
        if missing or extra:
            details = []
            if missing:
                details.append("missing: " + ", ".join(missing))
            if extra:
                details.append("unexpected: " + ", ".join(extra))
            raise ValueError(f"{name} arguments do not match its schema ({'; '.join(details)})")
        arguments: dict[str, Any] = {}
        for spec in definition.positional_arguments:
            if spec.name not in decoded:
                continue
            raw = self._native_argument_as_positional_text(definition, spec, decoded[spec.name])
            arguments[spec.name] = self._decode_positional_argument(definition, spec, raw)
        provider_call = {
            "id": call_id,
            "type": "function",
            "function": {"name": name, "arguments": arguments_json},
        }
        return {
            "name": name,
            "arguments": arguments,
            "raw_call": json.dumps(provider_call, ensure_ascii=False, separators=(",", ":")),
            "provider_tool_call_id": call_id,
            "provider_tool_call": provider_call,
        }

    def convert_openai_tool_call_batch(
        self,
        raw_calls: Any,
        scope_id: str | None,
        chat_id: str | None = None,
        *,
        excluded_names: set[str] | frozenset[str] | None = None,
        feature_overrides: dict[str, bool] | None = None,
    ) -> list[dict[str, Any]]:
        if not isinstance(raw_calls, list):
            return []
        allowed = {
            tool.name for tool in self._enabled_tool_definitions(
                scope_id, chat_id, excluded_names=excluded_names,
                feature_overrides=feature_overrides,
            )
        }
        converted: list[dict[str, Any]] = []
        seen_call_ids: set[str] = set()
        for raw_call in raw_calls:
            try:
                raw_id = str(raw_call.get("id") or "").strip() if isinstance(raw_call, dict) else ""
                if raw_id and raw_id in seen_call_ids:
                    raise ValueError(f"duplicate native tool call id: {raw_id}")
                row = self.convert_openai_tool_call(raw_call, allowed_names=allowed)
                seen_call_ids.add(str(row.get("provider_tool_call_id") or ""))
                converted.append(row)
            except Exception as exc:
                function = raw_call.get("function") if isinstance(raw_call, dict) and isinstance(raw_call.get("function"), dict) else {}
                call_id = str(raw_call.get("id") or "").strip() if isinstance(raw_call, dict) else ""
                name = str(function.get("name") or "malformed_tool_call").strip() or "malformed_tool_call"
                canonical_id = call_id if call_id and call_id not in seen_call_ids else f"call_invalid_{uuid_v4()}"
                seen_call_ids.add(canonical_id)
                provider_call = copy.deepcopy(raw_call) if isinstance(raw_call, dict) else {"raw": raw_call}
                if isinstance(provider_call, dict):
                    provider_call["id"] = canonical_id
                converted.append({
                    "name": name,
                    "arguments": {},
                    "raw_call": json.dumps(provider_call, ensure_ascii=False, default=str),
                    "provider_tool_call_id": canonical_id,
                    "provider_tool_call": provider_call,
                    "validation_error": f"{type(exc).__name__}: {exc}",
                })
        return converted

    def build_skill_system_block(
        self,
        scope_id: str | None,
        chat_id: str | None = None,
        *,
        feature_overrides: dict[str, bool] | None = None,
    ) -> str:
        """Return only skill instructions reachable with this Task's tool policy."""
        enabled = self.skill_store.list_skills(include_disabled=False)
        enabled_by_key = {
            str(row.get("name") or "").casefold(): row
            for row in enabled
            if str(row.get("name") or "").strip()
        }
        preloaded_keys = {
            key for key, row in enabled_by_key.items() if row.get("mode") == "always"
        }
        preloaded_labels = [str(enabled_by_key[key].get("name") or key) for key in preloaded_keys]
        loading_enabled = self._chat_group_enabled(
            scope_id, chat_id, self._tool_group_for_name("skills_load"), default=True,
            feature_overrides=feature_overrides,
        )
        lines = ["SKILLS", ""]
        if loading_enabled:
            lines.append(
                "Load materially relevant non-preloaded Skills with skills_load before planning or implementation."
            )
            if preloaded_labels:
                lines.extend([
                    "Already loaded for this Task: " + ", ".join(sorted(preloaded_labels, key=str.casefold)) + ".",
                    "Their instructions are below; reuse them. Load other enabled Skills when relevant.",
                ])
            else:
                lines.append("Load relevant enabled skills with skills_load before following their instructions or calling tool families documented by them.")
            lines.extend([
                "Always Skills are loaded once at the start of each Chat/Agent; Optional Skills load on demand. "
                "Settings changes apply to new contexts, not existing prompt snapshots. Skills supplement the "
                "system prompt and user request; they never enable absent or disabled tools.",
                "For code load General Programming, then the relevant platform Skill; add UI and UX for interfaces.",
                "Use exact documented tool signatures and failure handling. Read needed supporting files in the Skill directory.",
                "",
                "Enabled skills:",
            ])
            if enabled:
                config = self.storage.load_config()
                catalog_skill_limit = tool_setting_int(config, "skill_catalog_max_skills")
                catalog_char_limit = tool_setting_int(config, "skill_catalog_max_chars")
                catalog_chars = 0
                shown = 0
                for row in enabled:
                    if shown >= catalog_skill_limit:
                        break
                    name = str(row.get("name") or "")
                    suffix = " (already loaded)" if name.casefold() in preloaded_keys else ""
                    catalog_line = f"* {name} — {row.get('description')}{suffix}"
                    if catalog_chars + len(catalog_line) + 1 > catalog_char_limit:
                        break
                    lines.append(catalog_line)
                    catalog_chars += len(catalog_line) + 1
                    shown += 1
                omitted = max(0, len(enabled) - shown)
                if omitted:
                    lines.append(f"* [{omitted} additional enabled skill(s) omitted from this bounded catalog.]")
            else:
                lines.append("* No enabled skills are available.")
        elif preloaded_labels:
            lines.append(
                "System tools are disabled for this Task. Only the already loaded Skills below apply; no additional "
                "Skill can be loaded and no Skill-documented tool may be called."
            )
        else:
            return ""

        total_instruction_chars = 0
        total_cap = tool_setting_int(self.storage.load_config(), "skill_combined_instruction_max_chars")
        for key in sorted(preloaded_keys):
            row = enabled_by_key[key]
            name = str(row.get("name") or key)
            personalization_text: str | None = None
            try:
                skill = self.skill_store.load_skill(name)
                instructions = str(skill.get("instructions") or "").strip()
                total_instruction_chars += len(instructions)
                if skill.get("instructions_truncated") or total_instruction_chars > total_cap:
                    raise ValueError(f"Always Skill {name!r} exceeds the configured Skill instruction limits; "
                                     "increase the limits or choose Optional in Settings")
                directory = str(skill.get("directory") or "")
                if key == DEFAULT_PERSONALIZATION_SKILL_NAME.casefold():
                    user_path = Path(directory) / PERSONALIZATION_USER_FILE_NAME
                    if user_path.is_symlink() or not user_path.is_file():
                        personalization_text = "[user.txt is missing; no personal profile is available.]"
                    else:
                        profile, truncated = file_read_text_prefix(
                            user_path, PERSONALIZATION_USER_TEXT_MAX_CHARS,
                            encoding="utf-8", errors="replace",
                        )
                        personalization_text = profile.strip()
                        if not personalization_text:
                            personalization_text = "[user.txt is empty; no personal profile is available.]"
                        elif truncated:
                            personalization_text += "\n[The personalization profile was truncated at the configured safety limit.]"
            except Exception as exc:
                raise ValueError(f"Cannot initialize Always Skill {name!r}: {exc}") from exc
            lines.extend([
                "",
                f"===== Already loaded Task skill: {name} =====",
                f"Absolute directory: {directory}" if directory else "Absolute directory: unavailable",
                "----- skill.md instructions -----",
                instructions,
            ])
            if personalization_text is not None:
                lines.extend([
                    "----- user.txt personalization profile -----",
                    personalization_text,
                ])
            lines.append(f"===== End already loaded Task skill: {name} =====")
        return "\n".join(lines)

    def _decode_positional_argument(
        self,
        definition: ToolDefinition,
        spec: ToolArgumentSpec,
        raw_value: str,
    ) -> Any:
        """Validate and decode one canonical native function argument."""
        raw = str(raw_value)
        properties = definition.parameters.get("properties") if isinstance(definition.parameters, dict) else {}
        schema = properties.get(spec.name) if isinstance(properties, dict) else {}
        schema = schema if isinstance(schema, dict) else {}

        if spec.value_type == "boolean":
            if raw not in {"true", "false"}:
                raise ValueError(
                    f"{definition.name} argument {spec.name!r} must be exactly true or false"
                )
            value: Any = raw == "true"
        elif spec.value_type == "number":
            if not re.fullmatch(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)", raw):
                raise ValueError(
                    f"{definition.name} argument {spec.name!r} must be an ordinary base-10 number"
                )
            number = float(raw)
            if not math.isfinite(number):
                raise ValueError(f"{definition.name} argument {spec.name!r} must be finite")
            if schema.get("type") == "integer":
                if not number.is_integer():
                    raise ValueError(f"{definition.name} argument {spec.name!r} must be an integer")
                value = int(number)
            else:
                value = int(number) if number.is_integer() else number
        elif spec.value_type == "text":
            if spec.encoding in {"json_object", "json_array"}:
                expected_label = "object" if spec.encoding == "json_object" else "array"
                expected_type = dict if spec.encoding == "json_object" else list
                try:
                    value = json.loads(raw)
                except Exception as exc:
                    raise ValueError(
                        f"{definition.name} argument {spec.name!r} must be strict JSON {expected_label} text: {exc}"
                    ) from exc
                if not isinstance(value, expected_type):
                    raise ValueError(
                        f"{definition.name} argument {spec.name!r} must decode to a JSON {expected_label}"
                    )
            elif spec.encoding == "lines":
                value = [line.strip() for line in raw.splitlines() if line.strip()]
            else:
                value = raw
        else:
            raise ValueError(f"unsupported positional argument type {spec.value_type!r}")

        if isinstance(value, str):
            minimum_length = schema.get("minLength")
            if minimum_length is not None and len(value) < int(minimum_length):
                raise ValueError(
                    f"{definition.name} argument {spec.name!r} must contain at least {minimum_length} character(s)"
                )
            maximum_length = schema.get("maxLength")
            if maximum_length is not None and len(value) > int(maximum_length):
                raise ValueError(
                    f"{definition.name} argument {spec.name!r} must contain at most {maximum_length} character(s)"
                )
            pattern = schema.get("pattern")
            if isinstance(pattern, str) and re.fullmatch(pattern, value) is None:
                raise ValueError(
                    f"{definition.name} argument {spec.name!r} does not match the required format"
                )
        if isinstance(value, list):
            minimum_items = schema.get("minItems")
            if minimum_items is not None and len(value) < int(minimum_items):
                raise ValueError(
                    f"{definition.name} argument {spec.name!r} must contain at least {minimum_items} item(s)"
                )
            maximum_items = schema.get("maxItems")
            if maximum_items is not None and len(value) > int(maximum_items):
                raise ValueError(
                    f"{definition.name} argument {spec.name!r} must contain at most {maximum_items} item(s)"
                )
        if isinstance(value, dict):
            minimum_properties = schema.get("minProperties")
            if minimum_properties is not None and len(value) < int(minimum_properties):
                raise ValueError(
                    f"{definition.name} argument {spec.name!r} must contain at least {minimum_properties} field(s)"
                )

        enum = schema.get("enum")
        if isinstance(enum, list) and value not in enum:
            raise ValueError(
                f"{definition.name} argument {spec.name!r} must be one of: "
                + ", ".join(repr(item) for item in enum)
            )
        items = schema.get("items") if isinstance(schema.get("items"), dict) else {}
        item_enum = items.get("enum") if isinstance(items, dict) else None
        if isinstance(item_enum, list) and isinstance(value, list):
            invalid = [item for item in value if item not in item_enum]
            if invalid:
                raise ValueError(
                    f"{definition.name} argument {spec.name!r} contains unsupported values: {invalid}"
                )
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            if schema.get("exclusiveMinimum") is not None and value <= float(schema["exclusiveMinimum"]):
                raise ValueError(
                    f"{definition.name} argument {spec.name!r} must be greater than {schema['exclusiveMinimum']}"
                )
            if schema.get("minimum") is not None and value < float(schema["minimum"]):
                raise ValueError(
                    f"{definition.name} argument {spec.name!r} must be at least {schema['minimum']}"
                )
            if schema.get("exclusiveMaximum") is not None and value >= float(schema["exclusiveMaximum"]):
                raise ValueError(
                    f"{definition.name} argument {spec.name!r} must be less than {schema['exclusiveMaximum']}"
                )
            if schema.get("maximum") is not None and value > float(schema["maximum"]):
                raise ValueError(
                    f"{definition.name} argument {spec.name!r} must be at most {schema['maximum']}"
                )
        return value


    def _normalize_tool_call(self, tool_call: dict[str, Any]) -> tuple[str, dict[str, Any]]:
        """Accept one validated native call while allowing omitted optional arguments."""
        if not isinstance(tool_call, dict):
            raise ValueError("tool call must be a normalized object")
        name = str(tool_call.get("name") or "").strip()
        if name not in self.tools:
            raise ValueError(f"unknown tool: {name}")
        arguments = tool_call.get("arguments")
        if not isinstance(arguments, dict):
            raise ValueError("tool call arguments must be a validated object")
        definition = self.tools[name]
        expected_names = [spec.name for spec in definition.positional_arguments]
        required_names = {
            str(value) for value in (definition.parameters.get("required") or [])
            if isinstance(value, str)
        }
        provided_names = list(arguments.keys())
        canonical_provided_names = [key for key in expected_names if key in arguments]
        missing = [key for key in expected_names if key in required_names and key not in arguments]
        extra = [str(key) for key in provided_names if key not in expected_names]
        out_of_order = provided_names != canonical_provided_names
        if missing or extra or out_of_order:
            details: list[str] = []
            if missing:
                details.append("missing: " + ", ".join(missing))
            if extra:
                details.append("unexpected: " + ", ".join(extra))
            if out_of_order and not extra:
                details.append("arguments are not in canonical signature order")
            raise ValueError(
                f"{name} arguments do not match its positional signature "
                f"({'; '.join(details)}; signature: {', '.join(expected_names)})"
            )
        return name, arguments


    def _remember_tool_record(self, record: dict[str, Any]) -> None:
        """Publish an already detached terminal record under a tiny lock."""
        tool_call_id = str(record.get("tool_call_id") or "").strip()
        if not tool_call_id:
            return
        # The expensive detachment happens on a worker in execute_tool_call. The
        # supplied snapshot is never mutated afterward, so this critical section
        # only updates two bounded indexes.
        with self._active_tool_lock:
            self._recent_tool_records[tool_call_id] = record
            self._recent_tool_records.move_to_end(tool_call_id)
            while len(self._recent_tool_records) > 512:
                self._recent_tool_records.popitem(last=False)

    @staticmethod
    def _build_recent_tool_record_snapshot(
        record: dict[str, Any], final: dict[str, Any],
    ) -> dict[str, Any]:
        """Detach successful results exactly and terminal failures in bounded form."""
        if "result" in final:
            recent_record = copy.deepcopy(record)
            recent_record["result"] = copy.deepcopy(final.get("result"))
            return recent_record

        # Stop can arrive while a tool owns megabytes of streamed provider data.
        # Deep-copying that cancelled record still monopolized the GIL even when
        # performed by to_thread, making the SDL loop appear frozen. Failure and
        # cancellation details need diagnostics, not an exact giant payload.
        scalar_keys = (
            "schema", "tool_call_id", "chat_id", "agent_id", "tool_name",
            "status", "started_at", "ended_at", "elapsed_seconds", "updated_at",
            "ok", "cancelled", "cancelled_by_user", "cancel_requested",
            "cancel_reason", "error", "velox_status", "velox_message",
            "provider_tool_call_id", "tool_failure_count", "malformed_tool_call_streak",
        )
        recent_record = {
            key: compact_log_payload(record.get(key))
            for key in scalar_keys if key in record
        }
        recent_record["input"] = compact_log_payload(
            final.get("input") if "input" in final else record.get("input")
        )
        for key in (
            "output_excerpt", "endpoint_stream_text", "stream_output",
            "endpoint_reasoning", "endpoint_answer", "raw_tool_call",
            "provider_tool_call", "retry_instructions",
        ):
            source = final.get(key) if key in final else record.get(key)
            if source not in (None, "", [], {}):
                recent_record[key] = compact_log_payload(source)
        if final.get("error"):
            recent_record["error"] = compact_log_payload(final.get("error"))
        recent_record["payload_bounded_after_failure"] = True
        return recent_record

    @staticmethod
    def _terminal_tool_log_record(record: dict[str, Any]) -> dict[str, Any]:
        """Return bounded audit metadata without serializing the full result."""
        return {
            "tool_call_id": str(record.get("tool_call_id") or ""),
            "tool_name": str(record.get("tool_name") or ""),
            "chat_id": str(record.get("chat_id") or ""),
            "agent_id": str(record.get("agent_id") or ""),
            "status": str(record.get("status") or ""),
            "ok": record.get("ok"),
            "started_at": str(record.get("started_at") or ""),
            "ended_at": str(record.get("ended_at") or ""),
            "elapsed_seconds": record.get("elapsed_seconds"),
            "cancelled": bool(record.get("cancelled")),
            "cancelled_by_user": bool(record.get("cancelled_by_user")),
            "error": str(record.get("error") or "")[:2000],
            "output_excerpt": str(record.get("output_excerpt") or "")[:2000],
        }

    @staticmethod
    def _tool_progress_notification(record: dict[str, Any]) -> dict[str, Any]:
        """Build a tiny immutable callback view without copying the live payload.

        Chat uses progress callbacks only as a redraw signal.  Returning the entire
        active record forced Python to traverse every accumulated provider field on
        each streamed update, and a Stop click could not be serviced until that
        traversal released the UI/event-loop thread.  Keep exact progress in the
        live record, but notify observers with bounded status and tail excerpts.
        """
        notification: dict[str, Any] = {}
        for key in (
            "schema", "tool_call_id", "chat_id", "agent_id", "tool_name",
            "status", "ok", "started_at", "ended_at", "elapsed_seconds",
            "updated_at", "cancel_requested", "cancel_reason", "endpoint_phase",
            "endpoint_profile_id", "endpoint_label", "endpoint_complete",
            "endpoint_finish_reason", "endpoint_stop_reason",
        ):
            if key in record:
                value = record.get(key)
                if isinstance(value, (str, int, float, bool, type(None))):
                    notification[key] = value
                else:
                    notification[key] = compact_log_payload(value)
        for key in (
            "output_excerpt", "endpoint_stream_text", "stream_output",
            "endpoint_reasoning", "endpoint_output",
            "browser_visual_review_phase", "browser_visual_review_path",
        ):
            if key in record:
                value = record.get(key)
                if isinstance(value, str):
                    notification[key] = value[-4000:]
                elif value not in (None, "", [], {}):
                    notification[key] = compact_log_payload(value)
        usage = record.get("endpoint_usage")
        if isinstance(usage, dict):
            notification["endpoint_usage"] = {
                str(key): value
                for key, value in usage.items()
                if isinstance(value, (str, int, float, bool, type(None)))
            }
        return notification

    def tool_execution_snapshot(self, tool_call_id: str) -> dict[str, Any] | None:
        resolved = str(tool_call_id or "").strip()
        if not resolved:
            return None
        # This path is entered from a UI click. Missing one live snapshot is safer
        # than ever waiting behind tool progress; the durable row remains usable.
        if not self._active_tool_lock.acquire(blocking=False):
            return None
        try:
            active = self._active_tool_executions.get(resolved)
            if active is not None:
                row = dict(active.live_record)
                started_mono = float(active.started_mono)
                cancel_requested = active.cancel_event.is_set()
                cancel_reason = str(active.cancel_reason or "")
            else:
                recent = self._recent_tool_records.get(resolved)
                row = dict(recent) if isinstance(recent, dict) else None
                started_mono = 0.0
                cancel_requested = False
                cancel_reason = ""
        finally:
            self._active_tool_lock.release()
        if row is None:
            return None
        # Recent records are detached and immutable after publication. Avoid a
        # second deep copy on the UI click path; successful giant results remain
        # available by reference, while failed/cancelled records are already bounded.
        if active is not None:
            row = copy.deepcopy(row)
            row["elapsed_seconds"] = round(
                max(0.0, time.monotonic() - started_mono), 3,
            )
            if cancel_requested:
                row["cancel_requested"] = True
                row["cancel_reason"] = cancel_reason
        return row

    @staticmethod
    def _schedule_active_tool_task_cancel(
        task: asyncio.Task[Any] | None, loop: asyncio.AbstractEventLoop | None,
    ) -> None:
        if task is None or task.done():
            return
        try:
            if loop is not None:
                loop.call_soon_threadsafe(task.cancel)
            else:
                task.cancel()
        except Exception:
            try:
                task.cancel()
            except Exception:
                pass

    @staticmethod
    def _mark_active_tool_cancel_unlocked(
        active: ActiveToolExecution, *, reason: str, cancelled_by_user: bool,
    ) -> tuple[asyncio.Task[Any] | None, asyncio.AbstractEventLoop]:
        active.cancel_reason = str(reason or "Tool call cancelled").strip()
        active.cancelled_by_user = bool(cancelled_by_user)
        active.cancel_event.set()
        active.live_record["cancel_requested"] = True
        active.live_record["cancel_reason"] = active.cancel_reason
        return active.task, active.loop

    def _cancel_tool_ids(
        self,
        tool_call_ids: Iterable[str],
        *,
        reason: str,
        cancelled_by_user: bool,
    ) -> int:
        scheduled: list[tuple[asyncio.Task[Any] | None, asyncio.AbstractEventLoop]] = []
        with self._active_tool_lock:
            for tool_call_id in tool_call_ids:
                active = self._active_tool_executions.get(str(tool_call_id or "").strip())
                if active is not None:
                    scheduled.append(self._mark_active_tool_cancel_unlocked(
                        active, reason=reason, cancelled_by_user=cancelled_by_user,
                    ))
        for task, loop in scheduled:
            self._schedule_active_tool_task_cancel(task, loop)
        return len(scheduled)

    def cancel_tool_call(
        self,
        tool_call_id: str,
        *,
        reason: str = "The user cancelled this tool call.",
        cancelled_by_user: bool = True,
    ) -> bool:
        """Cancel one active tool call and its cooperative child operation."""
        resolved = str(tool_call_id or "").strip()
        if not resolved:
            return False
        return bool(self._cancel_tool_ids(
            (resolved,), reason=reason, cancelled_by_user=cancelled_by_user,
        ))

    def request_cancel_tool_call(
        self,
        tool_call_id: str,
        *,
        reason: str = "The user cancelled this tool call.",
        cancelled_by_user: bool = True,
    ) -> bool:
        """Queue cancellation without ever waiting for a contended progress lock."""
        resolved = str(tool_call_id or "").strip()
        if not resolved:
            return False
        if self._active_tool_lock.acquire(blocking=False):
            try:
                active = self._active_tool_executions.get(resolved)
                if active is None:
                    return False
                task, loop = self._mark_active_tool_cancel_unlocked(
                    active, reason=reason, cancelled_by_user=cancelled_by_user,
                )
            finally:
                self._active_tool_lock.release()
            self._schedule_active_tool_task_cancel(task, loop)
            return True
        threading.Thread(
            target=self.cancel_tool_call,
            kwargs={
                "tool_call_id": resolved, "reason": reason,
                "cancelled_by_user": cancelled_by_user,
            },
            name=f"velox-cancel-tool-{resolved[:8]}", daemon=True,
        ).start()
        return True

    def has_active_tool_calls(self) -> bool:
        """Return whether any tool execution is active without blocking the UI."""
        if not self._active_tool_lock.acquire(blocking=False):
            return True
        try:
            return bool(self._active_tool_executions)
        finally:
            self._active_tool_lock.release()


    def has_active_chat_tool_calls(self, chat_id: str | None) -> bool:
        """Return active state without allowing a decorative UI probe to wait."""
        resolved = str(chat_id or "").strip()
        if not resolved:
            return False
        if not self._active_tool_lock.acquire(blocking=False):
            # A contended lock means tool state is actively changing. Preserve the
            # working glow for this frame rather than blocking rendering.
            return True
        try:
            return any(
                str(active.chat_id or "") == resolved
                for active in self._active_tool_executions.values()
            )
        finally:
            self._active_tool_lock.release()

    def cancel_chat_tool_calls(
        self,
        chat_id: str,
        *,
        reason: str = "The conversation was stopped while this tool call was running.",
        cancelled_by_user: bool = False,
    ) -> int:
        resolved = str(chat_id or "").strip()
        if not resolved:
            return 0
        scheduled: list[tuple[asyncio.Task[Any] | None, asyncio.AbstractEventLoop]] = []
        with self._active_tool_lock:
            for active in self._active_tool_executions.values():
                if str(active.chat_id or "") == resolved:
                    scheduled.append(self._mark_active_tool_cancel_unlocked(
                        active, reason=reason, cancelled_by_user=cancelled_by_user,
                    ))
        for task, loop in scheduled:
            self._schedule_active_tool_task_cancel(task, loop)
        return len(scheduled)

    def request_cancel_chat_tool_calls(
        self,
        chat_id: str,
        *,
        reason: str = "The conversation was stopped while this tool call was running.",
        cancelled_by_user: bool = False,
    ) -> int:
        """Request all chat-owned cancellations without blocking the UI thread."""
        resolved = str(chat_id or "").strip()
        if not resolved:
            return 0
        if self._active_tool_lock.acquire(blocking=False):
            scheduled: list[tuple[asyncio.Task[Any] | None, asyncio.AbstractEventLoop]] = []
            try:
                for active in self._active_tool_executions.values():
                    if str(active.chat_id or "") == resolved:
                        scheduled.append(self._mark_active_tool_cancel_unlocked(
                            active, reason=reason, cancelled_by_user=cancelled_by_user,
                        ))
            finally:
                self._active_tool_lock.release()
            for task, loop in scheduled:
                self._schedule_active_tool_task_cancel(task, loop)
            return len(scheduled)
        threading.Thread(
            target=self.cancel_chat_tool_calls,
            kwargs={
                "chat_id": resolved, "reason": reason,
                "cancelled_by_user": cancelled_by_user,
            },
            name=f"velox-cancel-chat-tools-{resolved[:8]}", daemon=True,
        ).start()
        # The request has been accepted; the exact count is intentionally deferred.
        return 1

    def cancel_agent_tool_calls(
        self,
        agent_id: str,
        *,
        reason: str = "The Agent was stopped while this tool call was running.",
        cancelled_by_user: bool = False,
    ) -> int:
        """Cancel every active tool execution owned by one Agent Task."""
        resolved = str(agent_id or "").strip()
        if not resolved:
            return 0
        scheduled: list[tuple[asyncio.Task[Any] | None, asyncio.AbstractEventLoop]] = []
        with self._active_tool_lock:
            for active in self._active_tool_executions.values():
                if str(active.agent_id or "") == resolved:
                    scheduled.append(self._mark_active_tool_cancel_unlocked(
                        active, reason=reason, cancelled_by_user=cancelled_by_user,
                    ))
        for task, loop in scheduled:
            self._schedule_active_tool_task_cancel(task, loop)
        return len(scheduled)

    def request_cancel_agent_tool_calls(
        self,
        agent_id: str,
        *,
        reason: str = "The Agent was stopped while this tool call was running.",
        cancelled_by_user: bool = False,
    ) -> int:
        """Request Agent-owned tool cancellation without blocking the UI thread."""
        resolved = str(agent_id or "").strip()
        if not resolved:
            return 0
        if self._active_tool_lock.acquire(blocking=False):
            scheduled: list[tuple[asyncio.Task[Any] | None, asyncio.AbstractEventLoop]] = []
            try:
                for active in self._active_tool_executions.values():
                    if str(active.agent_id or "") == resolved:
                        scheduled.append(self._mark_active_tool_cancel_unlocked(
                            active, reason=reason, cancelled_by_user=cancelled_by_user,
                        ))
            finally:
                self._active_tool_lock.release()
            for task, loop in scheduled:
                self._schedule_active_tool_task_cancel(task, loop)
            return len(scheduled)
        threading.Thread(
            target=self.cancel_agent_tool_calls,
            kwargs={
                "agent_id": resolved, "reason": reason,
                "cancelled_by_user": cancelled_by_user,
            },
            name=f"velox-cancel-agent-tools-{resolved[:8]}", daemon=True,
        ).start()
        return 1

    def cancel_all_tool_calls(
        self,
        *,
        reason: str = "Velox is stopping; the active tool call was cancelled.",
    ) -> int:
        with self._active_tool_lock:
            ids = tuple(self._active_tool_executions)
        return self._cancel_tool_ids(
            ids, reason=reason, cancelled_by_user=False,
        )


    async def execute_tool_call(self, _scope_id: str, tool_call: dict[str, Any], **origin: Any) -> dict[str, Any]:
        name, args = self._normalize_tool_call(tool_call)
        started_mono = time.monotonic()
        chat_id = str(origin.get("chat_id") or "") or None
        agent_id = str(origin.get("agent_id") or "") or None
        monitor_task_id = str(origin.get("monitor_task_id") or "") or None
        reviewer_context = globals().get("_REVIEWER_CONTEXT")
        reviewer = bool(reviewer_context.get()) if reviewer_context is not None else False
        if not reviewer and agent_id:
            reviewer_lookup = globals().get("_reviewer_agent_from_id")
            if callable(reviewer_lookup):
                reviewer = reviewer_lookup(self.storage, agent_id) is not None
        reviewer_denylist = globals().get("EXPERT_MODE_REVIEWER_READ_ONLY_TOOL_DENYLIST", frozenset())
        if reviewer and (
            name in reviewer_denylist
            or name == "verify_checklist"
            or name.startswith("checklist_")
            or name.startswith("agents_")
        ):
            requested_id = str(origin.get("tool_call_id") or tool_call.get("provider_tool_call_id") or "").strip() or uuid_v4()
            now = now_iso()
            error = f"Checklist Reviewer is read-only and cannot execute mutating tool {name!r}."
            self.storage.append_app_log(
                "expert_review.tool_blocked",
                {"agent_id": agent_id or "", "chat_id": chat_id or "", "tool_name": name, "tool_call_id": requested_id},
            )
            return {
                "ok": False, "status": "failed", "tool_name": name,
                "error": error, "reviewer_read_only": True,
                "tool_call_id": requested_id, "input": redact_sensitive_tool_arguments(name, args),
                "started_at": now, "ended_at": now, "elapsed_seconds": 0.0,
            }
        monitor = self.task_monitor
        safe_args = redact_sensitive_tool_arguments(name, args)
        supplied_record = origin.get("live_record")
        record = supplied_record if isinstance(supplied_record, dict) else make_tool_call_record(
            name, safe_args, chat_id=chat_id, agent_id=agent_id,
        )
        requested_id = str(origin.get("tool_call_id") or record.get("tool_call_id") or "").strip()
        if not requested_id:
            requested_id = uuid_v4()
        signature = hashlib.sha256(json.dumps(
            [chat_id, agent_id, name, args], sort_keys=True, ensure_ascii=False,
            separators=(",", ":"), default=str,
        ).encode("utf-8")).hexdigest()
        replay: dict[str, Any] | None = None
        with self._active_tool_lock:
            claim = self._tool_execution_claims.get(requested_id)
            if claim is not None:
                if claim != signature:
                    raise PermissionError("Tool execution ID belongs to another owner or invocation")
                if requested_id in self._active_tool_executions:
                    raise RuntimeError("Tool execution is already running; duplicate invocation was not executed")
                recent = self._recent_tool_records.get(requested_id, {})
                replay = recent.get("_tool_execution_result")
                if not isinstance(replay, dict):
                    raise RuntimeError("Tool execution already finished; its result expired, so it was not executed again")
            else:
                self._tool_execution_claims[requested_id] = signature
        if replay is not None:
            return await asyncio.to_thread(copy.deepcopy, replay)
        record.update({
            "schema": TOOL_CALL_SCHEMA,
            "tool_call_id": requested_id,
            "chat_id": chat_id,
            "agent_id": agent_id,
            "tool_name": name,
            "input": safe_args,
            "status": "running",
            "started_at": str(record.get("started_at") or now_iso()),
            "ended_at": None,
            "elapsed_seconds": 0.0,
            "error": None,
            "ok": None,
        })
        cancel_event = threading.Event()
        loop = asyncio.get_running_loop()
        active = ActiveToolExecution(
            tool_call_id=requested_id,
            tool_name=name,
            chat_id=chat_id,
            agent_id=agent_id,
            started_mono=started_mono,
            cancel_event=cancel_event,
            loop=loop,
            live_record=record,
        )
        # Register before preparation yields: Stop must see preparing work too.
        with self._active_tool_lock:
            self._active_tool_executions[requested_id] = active
        if monitor is not None and monitor_task_id:
            try:
                monitor.record_tool_call(monitor_task_id, name)
            except Exception:
                pass
        external_progress = origin.get("progress_callback")

        def publish_progress(fields: dict[str, Any]) -> None:
            # Tool progress producers hand ownership of this top-level mapping to
            # the registry.  Strings and scalars are immutable; detach only nested
            # mutable values so a producer cannot alter the durable live record
            # after returning.  Do not clone the whole ever-growing record.
            patch: dict[str, Any] = {}
            if isinstance(fields, dict):
                for key, value in fields.items():
                    patch[str(key)] = (
                        value
                        if isinstance(value, (str, int, float, bool, bytes, type(None)))
                        else copy.deepcopy(value)
                    )
            if not patch:
                return
            # The global active-execution lock protects only the tiny mutable
            # registry/update window. Never deep-copy a potentially enormous
            # streamed result while holding it: Stop for another chat must remain
            # immediate even under concurrent high-volume tool progress.
            with self._active_tool_lock:
                if self._active_tool_executions.get(requested_id) is not active or record.get("status") != "running":
                    return
                # Progress cannot rewrite execution identity or terminal outcome.
                for protected in ("tool_call_id", "chat_id", "agent_id", "tool_name", "input", "status", "ok", "ended_at"):
                    patch.pop(protected, None)
                record.update(patch)
                record["elapsed_seconds"] = round(
                    max(0.0, time.monotonic() - started_mono), 3,
                )
                record["updated_at"] = now_iso()
                stream_text = str(
                    record.get("endpoint_stream_text")
                    or record.get("stream_output")
                    or ""
                )
                if stream_text:
                    record["output_excerpt"] = stream_text[-4000:]
                notification = self._tool_progress_notification(record)
            if callable(external_progress):
                try:
                    external_progress(notification)
                except Exception as exc:
                    self.storage.append_app_log(
                        "tool.progress.warning",
                        {"tool_name": name, "tool_call_id": requested_id,
                         "error": f"{type(exc).__name__}: {exc}"},
                    )

        agent_task_run_id: int | None = None
        if agent_id:
            try:
                durable_agent = AgentStore(self.storage).load_agent(agent_id)
                agent_task_run_id = int(durable_agent.get("task_run_id") or 0) or None
            except Exception:
                agent_task_run_id = None
        ctx = ToolContext(
            scope_id=APP_SCOPE_ID,
            chat_id=chat_id,
            agent_id=agent_id,
            agent_task_run_id=agent_task_run_id,
            endpoint_profile_id=str(origin.get("endpoint_profile_id") or "") or None,
            tool_call_id=requested_id,
            monitor_task_id=monitor_task_id,
            task_kind=str(origin.get("task_kind") or ""),
            cancel_event=cancel_event,
            progress_callback=publish_progress,
        )
        _best_effort_log(self.storage, "tool.started", self._terminal_tool_log_record(record))
        final: dict[str, Any] | None = None
        handler_task: asyncio.Task[Any] | None = None
        parent_cancelled = False
        try:
            timeout_seconds, handler = await asyncio.to_thread(
                self._prepare_tool_execution,
                name,
                args,
                chat_id,
                agent_id,
                str(origin.get("endpoint_profile_id") or "") or None,
            )

            async def invoke_handler() -> Any:
                ctx.raise_if_cancelled()
                if asyncio.iscoroutinefunction(handler):
                    return await handler(ctx, args)
                result_value = await asyncio.to_thread(handler, ctx, args)
                if inspect.isawaitable(result_value):
                    return await result_value
                return result_value

            ctx.raise_if_cancelled("Tool call cancelled during preparation; handler was not started")
            handler_task = asyncio.create_task(invoke_handler())
            active.task = handler_task
            done, _pending = await asyncio.wait({handler_task}, timeout=timeout_seconds)
            if not done:
                cancel_event.set()
                active.cancel_reason = f"Tool call exceeded its {float(timeout_seconds):g}-second execution budget."
                handler_task.cancel()
                await _drain_cancelled_tool_handler(handler_task)
                raise _ToolExecutionTimeout(active.cancel_reason)
            # An inner TimeoutError retains its own diagnostic, not the outer budget.
            result = handler_task.result()
            ctx.raise_if_cancelled()
            failure = _tool_result_failure(name, result)
            record["status"] = "failed" if failure else "complete"
            record["ok"] = not bool(failure)
            record["error"] = failure or None
            record["output_excerpt"] = json.dumps(result, ensure_ascii=False, default=str)[:4000]
            final = {
                "ok": not bool(failure), "status": record["status"], "tool_name": name,
                "result": result, "tool_call_id": requested_id, "input": safe_args,
            }
            if failure:
                final["error"] = failure
        except asyncio.CancelledError:
            cancel_event.set()
            if handler_task is not None and not handler_task.done():
                handler_task.cancel()
                await _drain_cancelled_tool_handler(handler_task)
            reason = active.cancel_reason or (
                "The conversation was stopped while this tool call was running."
            )
            record.update({
                "status": "cancelled",
                "ok": False,
                "cancelled": True,
                "cancelled_by_user": bool(active.cancelled_by_user),
                "error": reason,
            })
            final = {
                "ok": False,
                "status": "cancelled",
                "cancelled": True,
                "cancelled_by_user": bool(active.cancelled_by_user),
                "tool_name": name,
                "error": reason,
                "tool_call_id": requested_id,
                "input": safe_args,
            }
            parent_cancelled = not active.cancelled_by_user
        except ToolCancelledError as exc:
            reason = active.cancel_reason or str(exc) or "Tool call cancelled"
            record.update({
                "status": "cancelled",
                "ok": False,
                "cancelled": True,
                "cancelled_by_user": bool(active.cancelled_by_user),
                "error": reason,
            })
            final = {
                "ok": False,
                "status": "cancelled",
                "cancelled": True,
                "cancelled_by_user": bool(active.cancelled_by_user),
                "tool_name": name,
                "error": reason,
                "tool_call_id": requested_id,
                "input": safe_args,
            }
        except Exception as exc:
            record["status"] = "failed"
            record["ok"] = False
            record["error"] = f"{type(exc).__name__}: {exc}"
            timed_out = isinstance(exc, (TimeoutError, subprocess.TimeoutExpired))
            timeout_kind = "execution_budget" if isinstance(exc, _ToolExecutionTimeout) else "handler"
            record["timed_out"] = timed_out
            final = {
                "ok": False,
                "status": "failed",
                "tool_name": name,
                "error": record["error"],
                "timed_out": timed_out,
                **({"timeout_kind": timeout_kind} if timed_out else {}),
                "tool_call_id": requested_id,
                "input": safe_args,
            }
        finally:
            elapsed = round(max(0.0, time.monotonic() - started_mono), 3)
            record["ended_at"] = now_iso()
            record["elapsed_seconds"] = elapsed
            if final is None:
                final = {
                    "ok": False,
                    "status": "failed",
                    "tool_name": name,
                    "error": "Tool call ended without a result.",
                    "tool_call_id": requested_id,
                    "input": safe_args,
                }
            final.update({
                "started_at": record["started_at"],
                "ended_at": record["ended_at"],
                "elapsed_seconds": elapsed,
            })
            if record.get("status") == "cancelled":
                final["error"] = (
                    f"{record.get('error') or 'Tool call cancelled'} "
                    f"Elapsed before cancellation: {elapsed:.3f} seconds."
                )
                record["error"] = final["error"]
                final["cancelled"] = True
                final["cancelled_by_user"] = bool(record.get("cancelled_by_user"))
            # A secondary log/statistics/snapshot failure must not relabel committed
            # tool work or make a repeated invocation execute the side effect again.
            try:
                recent_record = await asyncio.to_thread(
                    self._build_recent_tool_record_snapshot, dict(record), dict(final),
                )
            except asyncio.CancelledError:
                parent_cancelled = True
                recent_record = dict(record)
                if "result" in final:
                    recent_record["result"] = final["result"]
            except Exception:
                recent_record = dict(record)
                if "result" in final:
                    recent_record["result"] = final["result"]
            replay_result = dict(final)
            replay_result["input"] = recent_record.get("input", safe_args)
            if "result" in recent_record:
                replay_result["result"] = recent_record["result"]
            recent_record["_tool_execution_result"] = replay_result
            with self._active_tool_lock:
                self._remember_tool_record(recent_record)
                if self._active_tool_executions.get(requested_id) is active:
                    self._active_tool_executions.pop(requested_id, None)
            log_event = {"complete": "tool.completed", "cancelled": "tool.cancelled"}.get(
                str(record.get("status") or ""), "tool.failed")
            _best_effort_log(self.storage, log_event, self._terminal_tool_log_record(record))
            try:
                await asyncio.to_thread(
                    self.storage.record_tool_usage, name, record.get("status") == "complete",
                    chat_id=chat_id, agent_id=agent_id,
                )
            except asyncio.CancelledError:
                parent_cancelled = True
            except Exception as stats_exc:
                _best_effort_log(self.storage, "tool.stats.warning", {
                    "tool_name": name, "error": f"{type(stats_exc).__name__}: {stats_exc}"})
        if parent_cancelled:
            raise asyncio.CancelledError()
        return final

    def _prepare_tool_execution(
        self,
        name: str,
        args: dict[str, Any],
        chat_id: str | None,
        agent_id: str | None = None,
        endpoint_profile_id: str | None = None,
    ) -> tuple[float | None, Callable[[ToolContext, dict[str, Any]], Any]]:
        """Resolve locked Chat/Agent tool policy and timeout on a worker."""
        if agent_id:
            owner = AgentStore(self.storage).load_agent(agent_id)
            if str(owner.get("source_chat_id") or "") != str(chat_id or ""):
                raise PermissionError("Agent tool context does not match its source Chat")
        if name in {
            "shell_exec", "python_exec", "terminal_write", "terminal_write_line", "terminal_respond",
        }:
            try:
                serialized_args = json.dumps(args or {}, ensure_ascii=False, default=str)
            except Exception:
                serialized_args = str(args or {})
            if EXPERT_MODE_OWNED_FILENAME_SEARCH_RE.search(serialized_args):
                raise PermissionError(
                    "Checklist state is Velox-owned and cannot be created, read, edited, renamed, deleted, "
                    "or retired through shell, Python, or terminal tools. Use the expert_mode_* tools."
                )
        self._reject_disabled_tool(APP_SCOPE_ID, name, chat_id, agent_id=agent_id)
        if name not in self.tools:
            raise KeyError(f"unknown tool: {name}")
        cfg = self.storage.load_config()
        return (
            self._timeout_for_tool(
                name,
                args,
                config=cfg,
                endpoint_profile_id=endpoint_profile_id,
            ),
            self.tools[name].handler,
        )

    def _timeout_for_tool(
        self,
        name: str,
        args: dict[str, Any],
        *,
        config: dict[str, Any] | None = None,
        endpoint_profile_id: str | None = None,
    ) -> float | None:
        """Return an outer operation budget derived only from current Settings."""
        cfg = config if isinstance(config, dict) else self.storage.load_config()
        if name == "verify_checklist":
            # This is a join on a separately budgeted durable Reviewer Task, not
            # one tool operation. Timing out the join discards its verdict waiter.
            # Reviewer requests/tools and its active-time budget remain bounded.
            return None
        if name == "time_sleep":
            try:
                minutes = float((args or {}).get("minutes"))
            except Exception:
                minutes = 0.0
            if not math.isfinite(minutes) or minutes <= 0:
                return 35.0
            return min(tool_setting_float(cfg, "sleep_max_minutes"), minutes) * 60.0 + 30.0
        if name == "terminal_read":
            return max(20.0, tool_setting_float(cfg, "terminal_read_wait_seconds") + 15.0)
        if name.startswith("terminal_"):
            return float(tool_setting_int(cfg, "fallback_timeout_seconds")) + 5.0
        if name in {"browser_run_headless", "browser_demo_playback"}:
            # Browser execution has its own bounded process/CDP timeout. Its
            # subsequent image reviews own independent no-progress watchdogs.
            return None
        if name.startswith("web_"):
            per_request = float(web_setting_int(cfg, "fetch_timeout_seconds"))
            if name == "web_search":
                return per_request * 2.0 + 130.0
            if name == "web_fetch_to_pdf":
                return per_request + 120.0
            return per_request + 15.0
        if name == "shell_exec":
            return execution_timeout_minutes(cfg, args, "shell_timeout_minutes", tool_name=name) * 60.0 + 5.0
        if name == "python_exec":
            return execution_timeout_minutes(cfg, args, "python_timeout_minutes", tool_name=name) * 60.0 + 5.0
        if name.startswith("comfy_"):
            configured = ((cfg.get("llm") or {}).get("comfy") or {}).get("timeout_seconds", 900)
            return float(configured) + 30.0
        if name.startswith("meshy_"):
            configured = (cfg.get("meshy") or {}).get("timeout_seconds", 1800)
            return float(configured) + 30.0
        if name == "desktop_screenshot":
            return float(tool_setting_int(cfg, "desktop_screenshot_timeout_seconds")) + 30.0
        if name in {"image_analyze", "image_analyze_ui", "image_analyze_3D_scene"}:
            return None  # Current-context handoff or independently guarded LLM stream.
        fallback = tool_setting_int(cfg, "fallback_timeout_seconds")
        return float(fallback) + 5.0

    def _reject_disabled_tool(
        self,
        scope_id: str | None,
        name: str,
        chat_id: str | None = None,
        *,
        agent_id: str | None = None,
    ) -> None:
        group_key = self._tool_group_for_name(name)
        feature_overrides: dict[str, bool] | None = None
        if agent_id:
            try:
                feature_overrides = normalize_tool_feature_flags(
                    AgentStore(self.storage).load_agent(str(agent_id)).get("tool_features")
                )
            except Exception:
                feature_overrides = {key: False for key in CHAT_TOOL_FEATURE_KEYS}
        if self._chat_group_enabled(
            scope_id, chat_id, group_key, default=True,
            feature_overrides=feature_overrides,
        ):
            return
        scope = "this agent Task" if agent_id else ("this chat" if chat_id else "the app")
        if all(
            not self._chat_group_enabled(
                scope_id, chat_id, key, default=True,
                feature_overrides=feature_overrides,
            )
            for key in CHAT_TOOL_FEATURE_KEYS
        ):
            raise PermissionError(f"all tools are disabled for {scope}")
        if group_key == "web_tools_enabled":
            raise PermissionError(f"web tools are disabled for {scope}")
        label = {
            "file_tools_enabled": "file tools (local file and document read/write/import functions)",
            "system_tools_enabled": "system tools (execution, ordinary terminals, images, Calendar, Data, and other local functions)",
            "agent_tools_enabled": "agent tools (start, list, pause, resume, stop, and inspect current-chat agents)",
            "chat_history_enabled": "chat history tools (chat search and summaries)",
            "checklists_enabled": "Checklist tools",
        }.get(group_key, group_key)
        raise PermissionError(f"{label} are disabled for {scope}")

    @staticmethod
    def _expert_mode_tool_result(
        store: ExpertModeStore, state: dict[str, Any] | None, *, action: str,
    ) -> dict[str, Any]:
        rows = ExpertModeStore.rows(state)
        return {
            "schema": "expert_mode_tool_result.v303",
            "action": action,
            "active": bool(state and state.get("status") == EXPERT_MODE_STATUS_ACTIVE),
            "status": str((state or {}).get("status") or "inactive"),
            "state_file": str(store.path),
            "owner_kind": store.context.owner_kind,
            "chat_id": store.context.chat_id,
            "agent_id": store.context.agent_id,
            "task_run_id": store.context.task_run_id,
            "summary": ExpertModeStore.format(
                state, include_instruction=bool(state and state.get("status") == EXPERT_MODE_STATUS_ACTIVE),
            ),
            "requirements": rows,
            "not_started_count": sum(1 for row in rows if row.get("not_started")),
            "in_progress_count": sum(1 for row in rows if row.get("in_progress")),
            "done_count": sum(1 for row in rows if row.get("status") == EXPERT_MODE_REQUIREMENT_DONE),
            "verified_count": sum(1 for row in rows if row.get("verified")),
            "incomplete_count": sum(1 for row in rows if row.get("incomplete")),
            "requirement_count": len(rows),
        }

    async def tool_expert_mode_enter(
        self, ctx: ToolContext, args: dict[str, Any],
    ) -> dict[str, Any]:
        context = expert_mode_context_from_tool(self.storage, ctx)
        store = ExpertModeStore(self.storage, context)
        state = await asyncio.to_thread(store.enter, list((args or {}).get("requirements") or []))
        return self._expert_mode_tool_result(store, state, action="entered")

    async def tool_expert_mode_status(
        self, ctx: ToolContext, args: dict[str, Any],
    ) -> dict[str, Any]:
        del args
        context = expert_mode_context_from_tool(self.storage, ctx)
        store = ExpertModeStore(self.storage, context)
        state = await asyncio.to_thread(store.load)
        return self._expert_mode_tool_result(store, state, action="status")

    async def tool_expert_mode_requirement_update(
        self, ctx: ToolContext, args: dict[str, Any],
    ) -> dict[str, Any]:
        context = expert_mode_context_from_tool(self.storage, ctx)
        store = ExpertModeStore(self.storage, context)
        state = await asyncio.to_thread(
            store.update, list((args or {}).get("updates") or []),
        )
        return self._expert_mode_tool_result(store, state, action="requirements_updated")

    async def tool_expert_mode_exit(
        self, ctx: ToolContext, args: dict[str, Any],
    ) -> dict[str, Any]:
        del args
        context = expert_mode_context_from_tool(self.storage, ctx)
        store = ExpertModeStore(self.storage, context)
        state = await asyncio.to_thread(store.exit)
        if bool(state.get("review_passed_pending")):
            action = "review_complete"
        elif bool(state.get("review_requested")):
            action = "review_required"
        else:
            action = "status"
        return self._expert_mode_tool_result(store, state, action=action)

    async def tool_programming_toolchain_discover(
        self, ctx: ToolContext, args: dict[str, Any],
    ) -> dict[str, Any]:
        """Return one exact, machine-readable local programming environment map."""
        del ctx, args

        def discover() -> dict[str, Any]:
            host_os = host_operating_system_name()
            cpp = detect_native_cpp_environment(host_os)
            browser = detect_chrome_executable()
            node = _absolute_existing_path(shutil.which("node") or "")
            npm = _absolute_existing_path(shutil.which("npm.cmd") or shutil.which("npm") or "")
            git = _absolute_existing_path(shutil.which("git.exe") or shutil.which("git") or "")
            python_path = _absolute_existing_path(sys.executable)
            preferred: dict[str, Any] = {}
            if host_os == "Windows" and isinstance(cpp, dict):
                preferred = copy.deepcopy(cpp.get("preferred") or {})
            elif isinstance(cpp, dict):
                cmake = str(cpp.get("cmake") or "")
                compiler = str(cpp.get("compiler") or "")
                preferred = {
                    "compiler": compiler,
                    "cCompiler": str(cpp.get("cCompiler") or ""),
                    "cmake": cmake,
                    "cmakeConfigureCommand": f'"{cmake}" -S . -B build' if cmake else "",
                    "cmakeBuildCommand": f'"{cmake}" --build build' if cmake else "",
                }
            preference_issue = str((cpp or {}).get("preferenceIssue") or "") if isinstance(cpp, dict) else ""
            return {
                "schema": "programming_toolchain_snapshot.v262",
                "detectedAt": now_iso(),
                "hostOs": host_os,
                "python": {
                    "executable": python_path,
                    "version": sys.version.splitlines()[0],
                },
                "cpp": copy.deepcopy(cpp),
                "cmakeInstallations": copy.deepcopy((cpp or {}).get("cmakeInstallations") or []),
                "cmakeExecutables": copy.deepcopy((cpp or {}).get("cmakeExecutables") or []),
                "browser": browser,
                "node": node,
                "npm": npm,
                "git": git,
                "preferred": preferred,
                "preferenceIssue": preference_issue,
                "message": (
                    "Use the coherent preferred tuple and its canonical commands as one unit. Preserve valid project "
                    "presets/configuration. If no preferred tuple is available, do not mix independently discovered "
                    "Visual Studio, MSVC, and CMake entries; diagnose the compatibility gap first."
                    if host_os == "Windows"
                    else "Use these exact probed paths and preserve the project's existing build configuration."
                ),
            }

        return await asyncio.to_thread(discover)

    def _initial_skill_keys(self, ctx: ToolContext) -> set[str]:
        """Read names from this owner's committed initial prompt, never current modes."""
        prompt = ""
        if ctx.agent_id:
            path = self.storage.paths.agent_transcript_jsonl(str(ctx.agent_id))
            try:
                _flush_pending_jsonl_for_read(path)
                with DATA_ROOTS.lock_for_path(path), _plain_open_with_retry(path, "r", encoding="utf-8") as stream:
                    for line in stream:
                        if not line.strip():
                            continue
                        event = json.loads(line)
                        validate_agent_event_record(event, str(ctx.agent_id), location=str(path))
                        if event.get("kind") == "started":
                            prompt = str((event.get("data") or {}).get("system_prompt") or "")
                            break
            except FileNotFoundError:
                pass  # A focused caller before startup has no injected Skills yet.
        elif ctx.chat_id:
            turns = ChatStore(self.storage).load_turns_view(APP_SCOPE_ID, str(ctx.chat_id))
            for turn in turns:
                if turn.get("role") == "user" and not is_chat_application_injected_prompt_turn(turn):
                    prompt = str(turn.get("system_prompt_snapshot") or "")
                    break
        return {name.casefold() for name in re.findall(
            r"^===== Already loaded Task skill: (.+) =====$", prompt, re.M)}

    async def tool_skills_load(self, ctx: ToolContext, args: dict[str, Any]) -> dict[str, Any]:
        return await asyncio.to_thread(self._load_skills_for_context, ctx, args)

    def _load_skills_for_context(self, ctx: ToolContext, args: dict[str, Any]) -> dict[str, Any]:
        """Load skill instructions and an inventory of their supporting files."""
        raw_names = (args or {}).get("names")
        names = [str(value or "").strip() for value in (raw_names or [])] if isinstance(raw_names, list) else []
        names = [name for name in names if name]
        if not names:
            raise ValueError("skills_load requires at least one exact enabled skill name")

        loaded: list[dict[str, Any]] = []
        omitted_names: list[str] = []
        already_loaded_names: list[str] = []
        total_instruction_chars = 0
        total_cap = tool_setting_int(
            self.storage.load_config(), "skill_combined_instruction_max_chars",
        )
        preloaded_keys = self._initial_skill_keys(ctx)
        seen_names: set[str] = set()
        for requested_name in names:
            key = requested_name.casefold()
            if key in seen_names:
                continue
            seen_names.add(key)
            if key in preloaded_keys:
                # Validate that the enabled skill still exists, then avoid
                # injecting a duplicate snapshot already present in the system prompt.
                skill = self.skill_store.load_skill(requested_name)
                already_loaded_names.append(str(skill.get("name") or requested_name))
                continue
            remaining = max(0, total_cap - total_instruction_chars)
            if remaining <= 0:
                omitted_names.append(requested_name)
                continue
            skill = self.skill_store.load_skill(requested_name)
            instructions = str(skill.get("instructions") or "")
            if len(instructions) > remaining:
                instructions = instructions[:remaining]
                skill["instructions"] = instructions
                skill["instructions_truncated"] = True
                skill["truncation_reason"] = "Combined skills_load instruction budget reached."
            total_instruction_chars += len(instructions)
            loaded.append(skill)
        return {
            "schema": "velox_loaded_skills.v1",
            "message": (
                "The requested non-preloaded skills are now injected into this conversation in order. "
                "Treat each skill.md as specialized task guidance. Skill instructions supplement but do not override "
                "the Velox system/tool protocol or the user's task. Supporting files are available at the listed absolute directories."
                + (
                    " The following bundled chat skill(s) were already loaded in the system prompt and were not duplicated: "
                    + ", ".join(already_loaded_names) + "."
                    if already_loaded_names else ""
                )
                + (" Some requested skills were omitted because the configured combined skill-instruction size limit was reached." if omitted_names else "")
            ),
            "requested_names": names,
            "loaded_count": len(loaded),
            "already_loaded_names": already_loaded_names,
            "omitted_names": omitted_names,
            "skills": loaded,
            "context_owner": "agent" if ctx.agent_id else "chat",
        }

    def _require_chat_agent_control(self, ctx: ToolContext, args: dict[str, Any]) -> tuple["AgentRuntime", dict[str, Any]]:
        """Resolve a chat-owned agent and reject agent-to-agent management."""
        if ctx.agent_id:
            raise PermissionError("background agents cannot inspect or control other agents")
        chat_id = str(ctx.chat_id or "").strip()
        if not chat_id:
            raise ValueError("agent management requires an active source chat")
        if self.agent_runtime is None:
            raise RuntimeError("background agent service is not initialized")
        agent_id = str((args or {}).get("agent_id") or "").strip()
        if not agent_id:
            raise ValueError("agent_id is required")
        agent = self.agent_runtime.agents.load_agent(agent_id)
        if str(agent.get("source_chat_id") or "") != chat_id:
            raise PermissionError("the requested agent was not created by the current chat")
        return self.agent_runtime, agent

    async def tool_agents_start(self, ctx: ToolContext, args: dict[str, Any]) -> dict[str, Any]:
        if ctx.agent_id:
            parent = AgentStore(self.storage).load_agent(ctx.agent_id)
            if parent["agent_kind"] != AGENT_KIND_PERSONAL_ASSISTANT or _is_reviewer_agent(parent):
                raise PermissionError("background agents cannot recursively start more agents")
        if not ctx.chat_id:
            raise ValueError("agents_start requires an active source chat")
        if self.agent_runtime is None:
            raise RuntimeError("background agent service is not initialized")
        task = str((args or {}).get("task") or "").strip()
        if not task:
            raise ValueError("agents_start task is required")
        return await self.agent_runtime.start_from_tool(
            ctx, {"task": task},
        )

    async def tool_agents_get_all(self, ctx: ToolContext, args: dict[str, Any]) -> dict[str, Any]:
        if ctx.agent_id:
            raise PermissionError("background agents cannot inspect or control other agents")
        chat_id = str(ctx.chat_id or "").strip()
        if not chat_id:
            raise ValueError("agents_list requires an active source chat")
        if self.agent_runtime is None:
            raise RuntimeError("background agent service is not initialized")
        rows: list[dict[str, Any]] = []
        lines: list[str] = []
        for agent in self.agent_runtime.agents.list_agents(chat_id):
            agent_id = str(agent.get("agent_id") or "")
            status = str(agent.get("status") or "queued")
            title = str(agent.get("title") or "Background agent").replace("\n", " ").strip()
            progress = str(agent.get("progress_message") or "").replace("\n", " ").strip()
            percent = agent.get("progress_percent")
            progress_label = f"{int(percent)}%" if isinstance(percent, (int, float)) else status
            if progress and progress.lower() not in {status.lower(), progress_label.lower()}:
                progress_label += f" - {progress}"
            row = {
                "agent_id": agent_id,
                "title": title,
                "status": status,
                "progress": progress_label,
                "created_at": str(agent.get("created_at") or ""),
                "updated_at": str(agent.get("updated_at") or ""),
            }
            rows.append(row)
            lines.append(f"{agent_id} | {status} | {progress_label} | {title}")
        return {
            "schema": "agents_for_chat.v1",
            "chat_id": chat_id,
            "count": len(rows),
            "agents": rows,
            "summary": "\n".join(lines) if lines else "No agent tasks were created by this chat.",
        }

    def _readable_agent(self, ctx: ToolContext, args: dict[str, Any]) -> dict[str, Any]:
        """Read authorization is separate from mutation/spawning authorization."""
        if not ctx.chat_id:
            raise PermissionError("Agent retrieval requires an owning Chat or Agent context")
        store = AgentStore(self.storage)
        agent_id = str(args.get("agent_id") or "").strip()
        if not is_uuid_v4(agent_id):
            raise ValueError("agent_id must be a valid Agent UUID")
        agent = store.load_agent(agent_id)
        if agent["source_chat_id"] != str(ctx.chat_id):
            raise PermissionError("The requested Agent belongs to another Chat")
        if ctx.agent_id:
            caller = store.load_agent(ctx.agent_id)
            if (ctx.agent_task_run_id is not None
                    and (isinstance(ctx.agent_task_run_id, bool)
                         or ctx.agent_task_run_id != caller["task_run_id"])):
                raise PermissionError("Agent retrieval Task Run ID does not match the current execution")
            if caller["source_chat_id"] != str(ctx.chat_id) or _is_reviewer_agent(caller):
                raise PermissionError("This Agent may not inspect other Agent output")
            owned = (agent["parent_agent_id"] == caller["agent_id"]
                     and agent["parent_task_run_id"] == caller["task_run_id"])
            if not owned:
                # Dedicated Reviewers use their existing exact owner/cycle metadata.
                review = _reviewer_binding(agent) if _is_reviewer_agent(agent) else {}
                owner = (review or {}).get("owner") or {}
                owned = (owner.get("agent_id") == caller["agent_id"]
                         and int(owner.get("task_run_id") or 0) == caller["task_run_id"])
            if not owned:
                raise PermissionError("Only the originating Agent run may read this child's output")
        return agent

    def _agent_read_page(self, ctx: ToolContext, args: dict[str, Any], *, transcript: bool) -> dict[str, Any]:
        agent = self._readable_agent(ctx, args)
        offset, limit = args.get("offset", 0), args.get("max_chars", 20000)
        if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
            raise ValueError("offset must be a nonnegative integer")
        if isinstance(limit, bool) or not isinstance(limit, int) or not 1 <= limit <= 100000:
            raise ValueError("max_chars must be an integer from 1 through 100000")
        thinking, calls = args.get("include_thinking", False), args.get("include_tool_calls", False)
        if not isinstance(thinking, bool) or not isinstance(calls, bool):
            raise ValueError("include_thinking and include_tool_calls must be booleans")
        parts = iter_agent_output_text(self.storage, agent, include_thinking=thinking, include_tool_calls=calls) if transcript else iter([
            ChatRuntime._agent_report_text(agent, "terminal") if agent["status"] in AGENT_TERMINAL_STATUSES
            else str(agent.get("last_output_excerpt") or "")])
        result, total = [], 0
        for part in parts:
            text = redact_durable_secret_text(part)
            end = total + len(text)
            if end > offset and total < offset + limit:
                result.append(text[max(0, offset-total):max(0, offset+limit-total)])
            total = end
        if offset > total:
            raise ValueError(f"offset {offset} exceeds output length {total}")
        value = "".join(result)
        return {
            "schema": "agent_output_page.v303" if transcript else "agent_result_page.v303",
            "agent_id": agent["agent_id"], "task_run_id": agent["task_run_id"], "title": agent["title"],
            "status": agent["status"], "terminal": agent["status"] in AGENT_TERMINAL_STATUSES,
            "progress": redact_durable_secret_text(str(agent.get("progress_message") or "")),
            "progress_percent": agent["progress_percent"],
            "summary": redact_durable_secret_text(str(agent.get("final_message") or "")),
            "failure": redact_durable_secret_text(str(agent.get("failure_message") or "")),
            "created_at": agent["created_at"], "updated_at": agent["updated_at"],
            "completed_at": agent.get("completed_at"),
            "partial": agent["status"] != "succeeded",
            "include_thinking": thinking if transcript else False, "include_tool_calls": calls if transcript else False,
            "output" if transcript else "result": value,
            "offset": offset, "returned_chars": len(value), "total_chars": total,
            "next_offset": offset + len(value) if offset + len(value) < total else None,
            "truncated": offset + len(value) < total,
        }

    async def tool_agents_get_result(self, ctx: ToolContext, args: dict[str, Any]) -> dict[str, Any]:
        return await asyncio.to_thread(self._agent_read_page, ctx, args, transcript=False)

    async def tool_agents_get_output(self, ctx: ToolContext, args: dict[str, Any]) -> dict[str, Any]:
        return await asyncio.to_thread(self._agent_read_page, ctx, args, transcript=True)

    async def tool_agents_pause(self, ctx: ToolContext, args: dict[str, Any]) -> dict[str, Any]:
        runtime, agent = self._require_chat_agent_control(ctx, args)
        agent_id = str(agent.get("agent_id") or "")
        changed = runtime.pause(agent_id)
        current = runtime.agents.load_agent(agent_id)
        return {"agent_id": agent_id, "status": current.get("status"), "pause_requested": current.get("pause_requested"), "changed": changed}

    async def tool_agents_resume(self, ctx: ToolContext, args: dict[str, Any]) -> dict[str, Any]:
        runtime, agent = self._require_chat_agent_control(ctx, args)
        agent_id = str(agent.get("agent_id") or "")
        changed = runtime.resume(agent_id)
        current = runtime.agents.load_agent(agent_id)
        return {"agent_id": agent_id, "status": current.get("status"), "changed": changed}

    async def tool_agents_stop(self, ctx: ToolContext, args: dict[str, Any]) -> dict[str, Any]:
        runtime, agent = self._require_chat_agent_control(ctx, args)
        agent_id = str(agent.get("agent_id") or "")
        changed = runtime.cancel(agent_id)
        current = runtime.agents.load_agent(agent_id)
        return {"agent_id": agent_id, "status": current.get("status"), "changed": changed}


    async def tool_list_context_docs(self, ctx: ToolContext, args: dict[str, Any]) -> dict[str, Any]:
        del ctx, args
        rows, tasks = await asyncio.gather(
            asyncio.to_thread(self.context_doc_store.list_docs_with_revision_counts),
            asyncio.to_thread(self.scheduled_task_store.list_tasks),
        )
        schedule_by_doc = {
            str(task.get("context_doc_id") or ""): task
            for task in tasks
            if str(task.get("action_kind") or "") == "context_refresh"
        }
        public = [{
            "context_doc_id": row.get("context_doc_id"),
            "name": row.get("name"),
            "goal": row.get("goal"),
            "character_limit": row.get("character_limit"),
            "content_characters": len(str(row.get("content") or "")),
            "last_refresh_status": row.get("last_refresh_status"),
            "last_refreshed_at": row.get("last_refreshed_at"),
            "locked": bool(row.get("locked")),
            "update_frequency": row.get("update_frequency"),
            "revision_count": max(0, int(row.get("revision_count") or 0)),
            "scheduled_task_id": str(
                (schedule_by_doc.get(str(row.get("context_doc_id") or "")) or {}).get("scheduled_task_id") or ""
            ),
        } for row in rows]
        return {"schema": "context_docs_list.v303", "count": len(public), "context_docs": public}

