    async def tool_time_sleep(self, ctx: ToolContext, args: dict[str, Any]) -> dict[str, Any]:
        """Wait without retaining endpoint capacity, then wake the same logical Task."""
        try:
            minutes = float((args or {}).get("minutes"))
        except Exception as exc:
            raise ValueError("minutes must be a number") from exc
        if not math.isfinite(minutes) or minutes <= 0:
            raise ValueError("minutes must be greater than zero")
        max_minutes = tool_setting_float(self.storage.load_config(), "sleep_max_minutes")
        if minutes > max_minutes:
            raise ValueError(f"minutes cannot exceed the configured maximum of {max_minutes:g}")
        message = str((args or {}).get("message") or "").strip()
        if not message:
            raise ValueError("message is required and must describe why inference should resume")

        started_at = now_iso()
        monitor = self.task_monitor
        task_id = str(ctx.monitor_task_id or "").strip()
        agent_token: dict[str, Any] | None = None
        if ctx.agent_id and self.agent_runtime is not None:
            try:
                current = self.agent_runtime.agents.load_agent(str(ctx.agent_id))
                agent_token = {
                    "agent_id": str(ctx.agent_id),
                    "progress_message": str(current.get("progress_message") or ""),
                    "progress_percent": current.get("progress_percent"),
                }
                self.agent_runtime._stop_active_clock(str(ctx.agent_id))
                self.agent_runtime.agents.update_agent(str(ctx.agent_id), {
                    "progress_message": f"Sleeping: {message}",
                    "active_started_at": None,
                })
            except Exception:
                agent_token = None
        if monitor is not None and task_id:
            monitor.set_phase(task_id, "sleeping")
            monitor.set_activity(task_id, "inactive")

        try:
            await asyncio.sleep(minutes * 60.0)
            ctx.raise_if_cancelled("Sleep cancelled")
            return {
                "status": "woke",
                "slept_minutes": minutes,
                "started_at": started_at,
                "woke_at": now_iso(),
                "wake_message": message,
                "message": message,
            }
        finally:
            if monitor is not None and task_id:
                try:
                    metadata = monitor.record_metadata(task_id)
                    if (
                        str(metadata.get("phase") or "").lower() == "sleeping"
                        and not bool(metadata.get("pause_requested"))
                    ):
                        monitor.set_phase(task_id, "ready")
                        monitor.set_activity(task_id, "inactive")
                except Exception:
                    pass
            if isinstance(agent_token, dict) and self.agent_runtime is not None:
                agent_id = str(agent_token.get("agent_id") or "")
                try:
                    current = self.agent_runtime.agents.load_agent(agent_id)
                    if (
                        str(current.get("status") or "") == "running"
                        and not bool(current.get("pause_requested"))
                        and not current.get("active_started_at")
                    ):
                        self.agent_runtime.agents.update_agent(agent_id, {
                            "active_started_at": now_iso(),
                            "progress_message": str(agent_token.get("progress_message") or ""),
                            "progress_percent": agent_token.get("progress_percent"),
                        })
                except Exception:
                    pass

