    async def tool_vault_search(self, ctx: ToolContext, args: dict[str, Any]) -> dict[str, Any]:
        del ctx
        source_type = str((args or {}).get("source") or "").strip()
        if source_type not in {GOOGLE_CALENDAR_SOURCE_TYPE, GMAIL_SOURCE_TYPE, SLACK_SOURCE_TYPE}:
            raise ValueError("source must be google_calendar, gmail, or slack")
        query = str((args or {}).get("query") or "").strip().casefold()
        sources = [
            row for row in self.vault_store.list_data_sources()
            if str(row.get("source_type") or "") == source_type and bool(row.get("enabled", True))
        ]
        sources.sort(key=lambda row: (0 if str(row.get("connection_state") or "") == "connected" else 1, str(row.get("display_name") or "").casefold()))
        if not sources:
            return {"source": source_type, "query": str((args or {}).get("query") or ""), "count": 0, "items": [], "message": f"No configured local {source_type} Vault source is available."}
        source = sources[0]
        allowed_types = {
            GOOGLE_CALENDAR_SOURCE_TYPE: {"calendar_event"},
            GMAIL_SOURCE_TYPE: {"gmail_message"},
            SLACK_SOURCE_TYPE: {"slack_message", "slack_thread_reply"},
        }[source_type]
        containers = {row["id"]: row for row in self.vault_store.list_containers(source["id"])}
        rows = []
        for item in self.vault_store.list_items(source_id=source["id"], item_types=allowed_types, include_deleted=False):
            participant_text = " ".join(
                f"{row.get('display_name','')} {row.get('email','')}" for row in item.get("participants") or [] if isinstance(row, dict)
            )
            container = containers.get(str(item.get("container_id") or ""), {})
            haystack = "\n".join([
                str(item.get("title") or ""), str(item.get("summary") or ""), str(item.get("body_text") or ""),
                str(item.get("author_display_name") or ""), participant_text,
                str(container.get("display_name") or container.get("name") or ""),
            ]).casefold()
            if query and query not in haystack:
                continue
            rows.append(item)
        rows.sort(key=lambda row: (str(row.get("primary_timestamp") or ""), str(row.get("id") or "")), reverse=True)
        public = []
        for item in rows[:100]:
            public.append({
                "item_id": item.get("id"), "item_type": item.get("item_type"),
                "title": item.get("title"), "summary": item.get("summary"),
                "author": item.get("author_display_name"), "timestamp": item.get("primary_timestamp"),
                "container": (containers.get(str(item.get("container_id") or ""), {}) or {}).get("display_name"),
                "source_url": item.get("source_url"), "is_unread": item.get("is_unread"),
                "thread_id": item.get("thread_id"), "parent_item_id": item.get("parent_item_id"),
            })
        return {
            "source": source_type, "source_id": source["id"], "source_name": source.get("display_name"),
            "query": str((args or {}).get("query") or ""), "count": len(public),
            "truncated": len(rows) > len(public), "items": public, "read_only": True,
        }

