    def _require_google_drive_connector(self) -> "GoogleDriveConnector":
        if self.google_drive_connector is None:
            raise RuntimeError("Google Drive integration is unavailable")
        return self.google_drive_connector

    @staticmethod
    def _drive_tool_limit(args: dict[str, Any], *, default: int = GOOGLE_DRIVE_DEFAULT_RESULT_LIMIT) -> int:
        raw = (args or {}).get("limit", default)
        try:
            value = int(raw)
        except (TypeError, ValueError):
            value = int(default)
        return int(clamp(value, 1, GOOGLE_DRIVE_MAX_RESULT_LIMIT))

    async def tool_drive_list_drives(self, ctx: ToolContext, args: dict[str, Any]) -> Any:
        del ctx
        connector = self._require_google_drive_connector()
        return await connector.list_drives(self._drive_tool_limit(args, default=GOOGLE_DRIVE_MAX_RESULT_LIMIT))

