@dataclass(slots=True)
class Rect:
    x: int
    y: int
    w: int
    h: int

    def inset(self, n: int) -> "Rect":
        return Rect(self.x + n, self.y + n, max(0, self.w - 2 * n), max(0, self.h - 2 * n))

    def split_top(self, h: int) -> tuple["Rect", "Rect"]:
        h = min(h, self.h)
        return Rect(self.x, self.y, self.w, h), Rect(self.x, self.y + h, self.w, self.h - h)


def vault_header_title_count_rects(header: Rect, *, count_width: int = 72) -> tuple[Rect, Rect]:
    """Keep Vault header text on the full line box while separating the count."""
    pad = 12
    gap = 10
    content_w = max(1, int(header.w) - pad * 2)
    resolved_count_w = min(max(42, int(count_width)), max(42, content_w // 3))
    title_w = max(1, content_w - resolved_count_w - gap)
    title = Rect(header.x + pad, header.y, title_w, header.h)
    count = Rect(title.x + title.w + gap, header.y, resolved_count_w, header.h)
    return title, count


def google_drive_table_columns(table_width: int) -> list[dict[str, Any]]:
    """Return GDrive columns with Name consuming all space left by fixed metadata columns."""
    content_w = max(1, int(table_width) - 28)
    type_w = 100
    modified_w = 300
    size_w = 40
    name_preferred = max(120, content_w - type_w - modified_w - size_w)
    return [
        {"key": "name", "title": "Name", "preferred_width": name_preferred, "min_width": 120, "weight": 1.0},
        {"key": "type", "title": "Type", "width": type_w, "min_width": 70},
        {"key": "modified", "title": "Modified", "width": modified_w, "min_width": 120},
        {"key": "size", "title": "Size", "width": size_w, "min_width": 40, "align": "right"},
    ]


def google_calendar_settings_table_columns(table_width: int) -> list[dict[str, Any]]:
    """Return fixed defaults with Calendar retaining half the visible table."""
    content_w = max(5 * 32, int(table_width) - 28)
    sync_w = 88
    calendar_w = max(150, int(round(content_w * 0.50)))
    color_w = 132
    access_w = 150
    source_w = max(160, content_w - sync_w - calendar_w - color_w - access_w)
    return [
        {"key": "sync", "title": "Sync", "width": sync_w, "min_width": 76, "sortable": False, "align": "center"},
        {"key": "calendar", "title": "Calendar", "width": calendar_w, "min_width": 150},
        {"key": "display_color", "title": "Color", "width": color_w, "min_width": 108, "sortable": False},
        {"key": "access", "title": "Access", "width": access_w, "min_width": 100},
        {"key": "source_id", "title": "Calendar ID", "width": source_w, "min_width": 160},
    ]


@dataclass(frozen=True, slots=True)
class SettingsAccountActionLayout:
    setup_heading: Rect
    actions_heading: Rect
    setup: Rect
    actions: Rect


def settings_account_action_layout(
    inner: Rect,
    y: int,
    *,
    heading_h: int,
    compact: bool = False,
    preferred_gap_px: int = 200,
) -> SettingsAccountActionLayout:
    """Return responsive Initial Setup / Actions columns.

    Compact account cards keep each button column at one quarter of its former
    half-column width, then place Actions directly after Initial Setup with a
    preferred 200-pixel visual gap. The gap contracts before either column
    overlaps or leaves the card at narrow widths.
    """
    minimum_gap = 24
    full_column_w = max(1, (inner.w - minimum_gap) // 2)
    if compact:
        button_w = min(full_column_w, max(180, int(round(full_column_w * 0.25))))
        left_w = max(1, min(button_w, inner.w))
        available_gap = max(0, inner.w - left_w - button_w)
        responsive_gap = min(max(minimum_gap, int(preferred_gap_px)), available_gap)
        if available_gap < minimum_gap:
            responsive_gap = available_gap
        right_x = inner.x + left_w + responsive_gap
        right_w = max(1, min(button_w, inner.x + inner.w - right_x))
    else:
        left_w = full_column_w
        right_x = inner.x + full_column_w + minimum_gap
        right_w = max(1, inner.x + inner.w - right_x)
    setup_heading = Rect(inner.x, int(y), left_w, max(1, int(heading_h)))
    actions_heading = Rect(right_x, int(y), right_w, max(1, int(heading_h)))
    body_y = int(y) + max(1, int(heading_h)) + 4
    remaining_h = max(1, inner.y + inner.h - body_y)
    return SettingsAccountActionLayout(
        setup_heading=setup_heading,
        actions_heading=actions_heading,
        setup=Rect(setup_heading.x, body_y, setup_heading.w, remaining_h),
        actions=Rect(actions_heading.x, body_y, actions_heading.w, remaining_h),
    )


def settings_compact_two_column_rects(
    rect: Rect,
    *,
    left_preferred_w: int = 430,
    right_preferred_w: int = 430,
    gap: int = 48,
    minimum_column_w: int = 180,
) -> tuple[Rect, Rect]:
    """Pack two Settings control groups against the left edge.

    Wide account cards should not stretch a pair of small settings across the
    complete window. Each column keeps a bounded preferred width and a modest
    gap. At narrow widths the gap and both columns contract proportionally,
    preserving non-overlap and the exact right edge.
    """
    width = max(1, int(rect.w))
    minimum = max(1, int(minimum_column_w))
    preferred_gap = max(0, int(gap))
    left_preferred = max(minimum, int(left_preferred_w))
    right_preferred = max(minimum, int(right_preferred_w))

    # Keep the requested gap when both minimum columns fit. Otherwise contract
    # it first so fields remain useful rather than being squeezed by whitespace.
    resolved_gap = min(preferred_gap, max(0, width - minimum * 2))
    available = max(2, width - resolved_gap)
    if available >= left_preferred + right_preferred:
        left_w = left_preferred
        right_w = right_preferred
    else:
        preferred_total = max(1, left_preferred + right_preferred)
        left_w = int(round(available * left_preferred / preferred_total))
        left_w = int(clamp(left_w, 1, max(1, available - 1)))
        right_w = max(1, available - left_w)
    right_x = int(rect.x) + left_w + resolved_gap
    return (
        Rect(int(rect.x), int(rect.y), left_w, int(rect.h)),
        Rect(right_x, int(rect.y), right_w, int(rect.h)),
    )


# Calendar screen geometry is intentionally centralized. The immediate-mode
# renderer receives one deterministic layout contract, and unit tests can verify
# responsive behavior without constructing SDL resources.
CALENDAR_COLUMN_GAP_PX = 10
CALENDAR_BACKLOG_RAIL_W = 44
CALENDAR_BACKLOG_EXPANDED_W = 384
CALENDAR_CHAT_WIDTH_DEFAULT = 380
CALENDAR_CHAT_WIDTH_MIN = 280
CALENDAR_CHAT_WIDTH_MAX = 900
CALENDAR_WEEK_MIN_W = 560
CALENDAR_RIGHT_STACK_GAP_PX = 10
CALENDAR_RIGHT_SPLIT_DEFAULT = 0.80
CALENDAR_RIGHT_SPLIT_MIN = 0.25
CALENDAR_RIGHT_SPLIT_MAX = 0.82
CALENDAR_WEEK_CHAT_MIN_H = 220
CALENDAR_AGENT_TASKS_MIN_H = 150
CALENDAR_CHAT_DIVIDER_HOVER_HALF_PX = 4
CALENDAR_RIGHT_STACK_DIVIDER_HOVER_HALF_PX = 4

# Chat uses the same direct-manipulation principles as Calendar. Both the
# conversation-list width and the message-composer height are persisted in the
# strict app-state model, while narrow windows keep practical responsive floors.
CHAT_COLUMN_GAP_PX = 12
CHAT_ACTIVITY_PULSE_SECONDS = 1.95
CHAT_ACTIVITY_GLOW_RANGE_MULTIPLIER = 1.20
CHAT_LIST_WIDTH_DEFAULT = 830
CHAT_LIST_WIDTH_MIN = 260
CHAT_LIST_MAX_WIDTH_FRACTION = 0.50
CHAT_LIST_ROW_RIGHT_GUTTER_PX = 20
CHAT_MAIN_WIDTH_MIN = 420
CHAT_DIVIDER_HOVER_HALF_PX = 4
CHAT_COMPOSER_HEIGHT_DEFAULT = 390
CALENDAR_CHAT_COMPOSER_HEIGHT_DEFAULT = 300
CHAT_COMPOSER_HEIGHT_MIN = 180
CHAT_COMPOSER_HEIGHT_MAX = 900
CHAT_OUTPUT_HEIGHT_MIN = 120
CHAT_STACK_GAP_PX = 12
CHAT_STACK_DIVIDER_HOVER_HALF_PX = 4

CALENDAR_INLINE_BACKLOG_MIN_TOTAL_W = 2400
CALENDAR_TIMELINE_HOUR_PX = 72
CALENDAR_TIMELINE_SNAP_MINUTES = 15
CALENDAR_TIMELINE_DEFAULT_START_HOUR = 7
CALENDAR_HOUR_LABEL_W = 58
CALENDAR_ALL_DAY_ROW_H = 72
CALENDAR_ALL_DAY_MAX_VISIBLE = 4
CALENDAR_OVERLAP_DEPTH_FRACTION = 0.20
CALENDAR_ITEM_CARD_MIN_H = 38
CALENDAR_EVENT_CARD_MIN_H = 38
CALENDAR_DRAG_START_DISTANCE_PX = 5
DATE_PICKER_PAST_YEARS = 10
DATE_PICKER_FUTURE_YEARS = 5


@dataclass(frozen=True, slots=True)
class ChatUILayout:
    chats: Rect
    main: Rect
    divider: Rect


def chat_layout_for_rect(rect: Rect, *, chat_list_width: int | None = None) -> ChatUILayout:
    """Return responsive Chat columns with one persisted draggable divider."""
    gap = CHAT_COLUMN_GAP_PX
    available = max(1, int(rect.w) - gap)
    requested = int(chat_list_width if chat_list_width is not None else CHAT_LIST_WIDTH_DEFAULT)
    if available >= CHAT_LIST_WIDTH_MIN + CHAT_MAIN_WIDTH_MIN:
        minimum = CHAT_LIST_WIDTH_MIN
    else:
        # On narrow windows, retain more room for the primary conversation
        # surface. The list remains usable but cannot swallow most of the page.
        minimum = max(80, min(CHAT_LIST_WIDTH_MIN, int(round(available * 0.28))))
    # Bound against the current viewport, not an absolute pixel ceiling. Subtract
    # the divider first, so even at the limit the transcript owns at least half
    # of the usable width. On very narrow windows the sidebar floor yields too.
    maximum = max(1, int(available * CHAT_LIST_MAX_WIDTH_FRACTION))
    minimum = min(minimum, maximum)
    list_w = int(clamp(requested, minimum, maximum))
    main_w = max(1, available - list_w)
    chats = Rect(rect.x, rect.y, max(1, list_w), rect.h)
    divider = Rect(chats.x + chats.w, rect.y, gap, rect.h)
    main = Rect(divider.x + divider.w, rect.y, main_w, rect.h)
    return ChatUILayout(chats=chats, main=main, divider=divider)


@dataclass(frozen=True, slots=True)
class ChatStackLayout:
    header: Rect
    output: Rect
    composer: Rect
    divider: Rect
    composer_height: int


def chat_stack_layout_for_rect(
    rect: Rect,
    *,
    header_height: int,
    composer_height: int | None = None,
    gap: int = CHAT_STACK_GAP_PX,
    min_output_height: int = CHAT_OUTPUT_HEIGHT_MIN,
    min_composer_height: int = CHAT_COMPOSER_HEIGHT_MIN,
    max_composer_height: int = CHAT_COMPOSER_HEIGHT_MAX,
) -> ChatStackLayout:
    """Partition a Chat surface so dragging the composer steals space from output."""
    header_h = int(clamp(int(header_height), 1, max(1, int(rect.h))))
    gap_px = max(1, int(gap))
    usable = max(1, int(rect.h) - header_h - gap_px * 2)
    requested = int(composer_height if composer_height is not None else CHAT_COMPOSER_HEIGHT_DEFAULT)

    # Responsive floors shrink only when the entire surface is too short.
    composer_floor = min(max(1, int(min_composer_height)), max(1, usable // 2))
    output_floor = min(max(1, int(min_output_height)), max(1, usable - composer_floor))
    composer_ceiling = max(composer_floor, min(int(max_composer_height), usable - output_floor))
    resolved_composer_h = int(clamp(requested, composer_floor, composer_ceiling))
    output_h = max(1, usable - resolved_composer_h)

    header = Rect(rect.x, rect.y, rect.w, header_h)
    output = Rect(rect.x, header.y + header.h + gap_px, rect.w, output_h)
    divider = Rect(rect.x, output.y + output.h, rect.w, gap_px)
    composer = Rect(rect.x, divider.y + divider.h, rect.w, max(1, resolved_composer_h))
    return ChatStackLayout(
        header=header, output=output, composer=composer, divider=divider,
        composer_height=resolved_composer_h,
    )


def date_picker_year_values(
    *,
    reference_date: date | None = None,
    selected_year: int | None = None,
) -> list[str]:
    """Return the reusable DD/MM/YYYY control's bounded year choices."""
    base_year = int((reference_date or date.today()).year)
    years = list(range(base_year - DATE_PICKER_PAST_YEARS, base_year + DATE_PICKER_FUTURE_YEARS + 1))
    if selected_year is not None and int(selected_year) not in years:
        years.append(int(selected_year))
        years.sort()
    return [str(year) for year in years]


def date_picker_iso_value(day_text: str, month_text: str, year_text: str) -> str:
    """Build a valid ISO date, clamping the day after month/year changes."""
    try:
        year = int(str(year_text).strip())
        month = int(str(month_text).strip())
        day_number = int(str(day_text).strip())
    except Exception as exc:
        raise ValueError("Date picker values must be numeric") from exc
    month = int(clamp(month, 1, 12))
    max_day = calendar_module.monthrange(year, month)[1]
    day_number = int(clamp(day_number, 1, max_day))
    return date(year, month, day_number).isoformat()


@dataclass(frozen=True, slots=True)
class CalendarTimelineBlockLayout:
    kind: str
    object_id: str
    start_minute: int
    end_minute: int
    lane: int
    lane_count: int
    lane_span: int
    order: int


def calendar_timeline_lane_assignments(
    blocks: list[tuple[str, str, int, int]],
    *,
    max_lanes: int = 8,
) -> list[CalendarTimelineBlockLayout]:
    """Assign stable overlap lanes and expansion spans for cascading cards.

    Connected overlap groups receive deterministic lanes. Each record starts in the
    first free lane and records how many later lanes are unused for its interval.
    The renderer uses these facts to keep the base record broad and layer later
    simultaneous records progressively to the right, matching the familiar Google
    Calendar cascade instead of fixed equal-width columns.
    """
    lane_cap = max(1, int(max_lanes))
    normalized: list[tuple[str, str, int, int, int]] = []
    for order, raw in enumerate(blocks):
        kind, object_id, start_minute, end_minute = raw
        start_minute = int(clamp(int(start_minute), 0, 24 * 60))
        end_minute = int(clamp(max(start_minute + 1, int(end_minute)), 1, 24 * 60))
        normalized.append((str(kind), str(object_id), start_minute, end_minute, order))
    # Google Calendar favors earlier events and, for equal starts, longer events.
    normalized.sort(key=lambda row: (row[2], -row[3], row[4]))

    out: list[CalendarTimelineBlockLayout] = []
    index = 0
    while index < len(normalized):
        group: list[tuple[str, str, int, int, int]] = [normalized[index]]
        group_end = normalized[index][3]
        index += 1
        while index < len(normalized) and normalized[index][2] < group_end:
            group.append(normalized[index])
            group_end = max(group_end, normalized[index][3])
            index += 1

        lane_ends: list[int] = []
        assigned: list[tuple[tuple[str, str, int, int, int], int]] = []
        for row in group:
            start_minute = row[2]
            lane = next((i for i, lane_end in enumerate(lane_ends) if lane_end <= start_minute), -1)
            if lane < 0:
                if len(lane_ends) < lane_cap:
                    lane = len(lane_ends)
                    lane_ends.append(row[3])
                else:
                    lane = lane_cap - 1
                    lane_ends[lane] = max(lane_ends[lane], row[3])
            else:
                lane_ends[lane] = row[3]
            assigned.append((row, lane))

        lane_count = max(1, min(lane_cap, max((lane for _row, lane in assigned), default=0) + 1))
        by_lane: list[list[tuple[str, str, int, int, int]]] = [[] for _ in range(lane_count)]
        for row, lane in assigned:
            by_lane[min(lane, lane_count - 1)].append(row)

        def overlaps(left: tuple[str, str, int, int, int], right: tuple[str, str, int, int, int]) -> bool:
            return left[2] < right[3] and right[2] < left[3]

        for row, lane in assigned:
            span = 1
            for candidate_lane in range(lane + 1, lane_count):
                if any(overlaps(row, other) for other in by_lane[candidate_lane]):
                    break
                span += 1
            out.append(CalendarTimelineBlockLayout(
                kind=row[0], object_id=row[1], start_minute=row[2], end_minute=row[3],
                lane=lane, lane_count=lane_count, lane_span=span, order=row[4],
            ))
    out.sort(key=lambda block: block.order)
    return out


def calendar_timeline_lane_rect(
    content: Rect,
    block: CalendarTimelineBlockLayout,
    *,
    top: int,
    height: int,
    lane_gap: int = 5,
) -> Rect:
    """Return one 20%-per-depth cascading overlap rectangle.

    The base card keeps the complete day width. Every later simultaneous depth
    moves right and loses 20% of the day width, subject to a readable minimum.
    Cards retain a common right edge and later lanes are painted above earlier
    lanes. Lane span metadata does not change the requested twenty-percent depth.
    """
    count = max(1, int(block.lane_count))
    lane = int(clamp(block.lane, 0, count - 1))
    if count <= 1:
        x = int(content.x)
    else:
        step = max(int(lane_gap), int(round(content.w * CALENDAR_OVERLAP_DEPTH_FRACTION)))
        minimum_width = min(max(52, int(round(content.w * 0.20))), max(1, int(content.w)))
        maximum_indent = max(0, int(content.w) - minimum_width)
        indent = min(maximum_indent, lane * step)
        x = int(content.x) + indent
    right = int(content.x) + int(content.w)
    width = max(1, right - x)
    return Rect(x, int(top) + 2, width, max(1, int(height) - 4))


def calendar_all_day_card_rects(
    area: Rect,
    event_count: int,
    *,
    max_visible: int = CALENDAR_ALL_DAY_MAX_VISIBLE,
    gap: int = 3,
) -> list[Rect]:
    """Fit up to four all-day Event cards side by side in one fixed row."""
    visible = min(max(0, int(event_count)), max(1, int(max_visible)), max(1, int(area.w)))
    if visible <= 0:
        return []
    resolved_gap = min(
        max(0, int(gap)),
        max(0, (max(1, int(area.w)) - visible) // max(1, visible - 1)),
    )
    available = max(visible, int(area.w) - resolved_gap * max(0, visible - 1))
    base = available // visible
    remainder = available % visible
    rows: list[Rect] = []
    x = int(area.x)
    for index in range(visible):
        width = base + (1 if index < remainder else 0)
        rows.append(Rect(x, int(area.y), max(1, width), max(1, int(area.h))))
        x += width + resolved_gap
    return rows


def calendar_card_text_rects(card: Rect, *, line_h: int) -> tuple[Rect, Rect | None]:
    """Lay out title/subtitle rows only when complete glyph lines fit."""
    pad_x = 8
    pad_y = 4
    inner = Rect(card.x + pad_x, card.y + pad_y, max(1, card.w - pad_x * 2), max(1, card.h - pad_y * 2))
    row_h = max(1, int(line_h) + 8)
    title = Rect(inner.x, inner.y, inner.w, min(inner.h, row_h))
    subtitle_y = title.y + title.h + 1
    remaining = inner.y + inner.h - subtitle_y
    subtitle = Rect(inner.x, subtitle_y, inner.w, row_h) if remaining >= row_h else None
    return title, subtitle


@dataclass(frozen=True, slots=True)
class CalendarUILayout:
    """Resizable Sunday-to-Saturday Calendar geometry."""
    backlog: Rect
    week: Rect
    chat_divider: Rect
    week_chat: Rect
    agent_tasks: Rect
    right_rail: Rect
    right_stack_divider: Rect
    backlog_overlay: Rect | None
    backlog_collapsed: bool


def calendar_layout_for_rect(
    rect: Rect,
    *,
    backlog_expanded: bool,
    chat_width: int | None = None,
    right_split_fraction: float | None = None,
) -> CalendarUILayout:
    """Return a week plus a user-resizable right rail."""
    gap = CALENDAR_COLUMN_GAP_PX
    width = max(1, int(rect.w))
    backlog_inline = bool(backlog_expanded and width >= CALENDAR_INLINE_BACKLOG_MIN_TOTAL_W)
    backlog_w = CALENDAR_BACKLOG_EXPANDED_W if backlog_inline else CALENDAR_BACKLOG_RAIL_W
    backlog = Rect(rect.x, rect.y, min(width, backlog_w), rect.h)

    main_x = backlog.x + backlog.w + gap
    main_w = max(1, rect.x + rect.w - main_x)
    default_right = int(round(main_w * 0.20))
    requested_right = int(chat_width if chat_width is not None else default_right)
    max_right = max(1, min(CALENDAR_CHAT_WIDTH_MAX, main_w - gap - min(CALENDAR_WEEK_MIN_W, max(1, main_w // 2))))
    min_right = min(CALENDAR_CHAT_WIDTH_MIN, max_right)
    right_w = int(clamp(requested_right, min_right, max_right))
    week_w = max(1, main_w - right_w - gap)
    week = Rect(main_x, rect.y, week_w, rect.h)
    chat_divider = Rect(week.x + week.w, rect.y, gap, rect.h)
    right_rail = Rect(chat_divider.x + chat_divider.w, rect.y, right_w, rect.h)

    stack_gap = CALENDAR_RIGHT_STACK_GAP_PX
    available_stack_h = max(2, right_rail.h - stack_gap)
    requested_fraction = float(
        CALENDAR_RIGHT_SPLIT_DEFAULT if right_split_fraction is None else right_split_fraction
    )
    requested_fraction = float(clamp(
        requested_fraction, CALENDAR_RIGHT_SPLIT_MIN, CALENDAR_RIGHT_SPLIT_MAX,
    ))
    minimum_chat_h = min(CALENDAR_WEEK_CHAT_MIN_H, max(1, available_stack_h - 1))
    maximum_chat_h = max(minimum_chat_h, available_stack_h - min(CALENDAR_AGENT_TASKS_MIN_H, max(1, available_stack_h - 1)))
    chat_h = int(clamp(
        int(round(available_stack_h * requested_fraction)), minimum_chat_h, maximum_chat_h,
    ))
    week_chat = Rect(right_rail.x, right_rail.y, right_rail.w, chat_h)
    right_stack_divider = Rect(
        right_rail.x, week_chat.y + week_chat.h, right_rail.w, stack_gap,
    )
    agent_tasks = Rect(
        right_rail.x, right_stack_divider.y + right_stack_divider.h, right_rail.w,
        max(1, right_rail.y + right_rail.h - (right_stack_divider.y + right_stack_divider.h)),
    )

    backlog_overlay: Rect | None = None
    if backlog_expanded and not backlog_inline:
        overlay_w = min(CALENDAR_BACKLOG_EXPANDED_W, max(200, width - CALENDAR_BACKLOG_RAIL_W - gap * 2))
        backlog_overlay = Rect(backlog.x + backlog.w + gap, rect.y, overlay_w, rect.h)

    return CalendarUILayout(
        backlog=backlog, week=week, chat_divider=chat_divider,
        week_chat=week_chat, agent_tasks=agent_tasks, right_rail=right_rail,
        right_stack_divider=right_stack_divider,
        backlog_overlay=backlog_overlay, backlog_collapsed=not backlog_inline,
    )


@dataclass(frozen=True, slots=True)
class CalendarBacklogRailLayout:
    top_chevron: Rect
    label: Rect
    bottom_chevron: Rect


def calendar_backlog_rail_layout(rect: Rect, *, line_h: int) -> CalendarBacklogRailLayout:
    """Center only the expand chevrons and vertical BACKLOG title in the rail."""
    chevron_h = max(22, min(30, int(line_h) + 4))
    gap = 4
    letter_step = max(10, min(max(1, int(line_h) - 1), 18))
    label_h = letter_step * len("BACKLOG")
    stack_h = chevron_h + gap + label_h + gap + chevron_h
    top = rect.y + max(6, (rect.h - stack_h) // 2)
    top_chevron = Rect(rect.x, top, rect.w, chevron_h)
    label = Rect(rect.x, top_chevron.y + top_chevron.h + gap, rect.w, label_h)
    bottom_chevron = Rect(rect.x, label.y + label.h + gap, rect.w, chevron_h)
    overflow = bottom_chevron.y + bottom_chevron.h - (rect.y + rect.h - 6)
    if overflow > 0:
        top_chevron = Rect(top_chevron.x, top_chevron.y - overflow, top_chevron.w, top_chevron.h)
        label = Rect(label.x, label.y - overflow, label.w, label.h)
        bottom_chevron = Rect(bottom_chevron.x, bottom_chevron.y - overflow, bottom_chevron.w, bottom_chevron.h)
    return CalendarBacklogRailLayout(
        top_chevron=top_chevron,
        label=label,
        bottom_chevron=bottom_chevron,
    )


def calendar_agent_tasks_for_display(
    agents: Iterable[dict[str, Any]], chats: Iterable[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Return PA Tasks plus Agent Tasks whose source is any Calendar Week Chat."""
    week_chats: dict[str, dict[str, Any]] = {
        str(chat.get("chat_id") or ""): chat
        for chat in chats
        if isinstance(chat, dict) and str(chat.get("chat_kind") or "") == "week"
        and str(chat.get("chat_id") or "")
    }
    rows: list[dict[str, Any]] = []
    for raw in agents:
        if not isinstance(raw, dict):
            continue
        source_chat_id = str(raw.get("source_chat_id") or "")
        is_pa = str(raw.get("agent_kind") or "") == AGENT_KIND_PERSONAL_ASSISTANT
        week_chat = week_chats.get(source_chat_id)
        if not is_pa and week_chat is None:
            continue
        row = copy.deepcopy(raw)
        if is_pa:
            origin = "PA"
        else:
            day_value = str((week_chat or {}).get("week_start_date") or "")
            origin = day_value or "Week Chat"
        row["calendar_origin"] = origin
        rows.append(row)
    rows.sort(
        key=lambda row: (
            str(row.get("created_at") or ""), str(row.get("agent_id") or ""),
        ),
        reverse=True,
    )
    return rows


def calendar_week_chat_title(day_value: str) -> str:
    start = calendar_week_start(day_value)
    end = start + timedelta(days=6)
    if start.year == end.year and start.month == end.month:
        span = f"{start.strftime('%B')} {start.day}–{end.day}, {start.year}"
    elif start.year == end.year:
        span = f"{start.strftime('%b')} {start.day}–{end.strftime('%b')} {end.day}, {start.year}"
    else:
        span = f"{start.strftime('%b')} {start.day}, {start.year}–{end.strftime('%b')} {end.day}, {end.year}"
    return "WEEK CHAT - " + span


def calendar_shift_iso_date(day_value: str, days: int) -> str:
    base = date.fromisoformat(normalize_iso_date(day_value, field_name="Calendar date"))
    return (base + timedelta(days=int(days))).isoformat()


def calendar_week_start(day_value: str) -> date:
    """Return the Sunday that contains ``day_value``."""
    resolved = date.fromisoformat(normalize_iso_date(day_value, field_name="Calendar date"))
    return resolved - timedelta(days=(resolved.weekday() + 1) % 7)


def calendar_week_dates(day_value: str) -> list[str]:
    """Return the complete Sunday-to-Saturday week containing ``day_value``."""
    start = calendar_week_start(day_value)
    return [(start + timedelta(days=offset)).isoformat() for offset in range(7)]


def calendar_week_title(day_value: str) -> str:
    start = calendar_week_start(day_value)
    end = start + timedelta(days=6)
    if start.year == end.year and start.month == end.month:
        return f"{start.strftime('%B')} {start.day}–{end.day}, {start.year}"
    if start.year == end.year:
        return f"{start.strftime('%b')} {start.day} – {end.strftime('%b')} {end.day}, {start.year}"
    return f"{start.strftime('%b')} {start.day}, {start.year} – {end.strftime('%b')} {end.day}, {end.year}"


def calendar_hour_label_rect(
    viewport: Rect,
    line_y: int,
    *,
    line_h: int,
    label_w: int = CALENDAR_HOUR_LABEL_W,
) -> Rect:
    """Place the label inside its hour block, half a text height below the line."""
    height = min(max(24, int(line_h) + 6), max(1, viewport.h))
    max_y = viewport.y + max(0, viewport.h - height)
    top = int(clamp(
        int(line_y) - height // 2 + max(1, int(line_h) // 2),
        viewport.y, max_y,
    ))
    return Rect(viewport.x, top, max(1, min(int(label_w) - 5, viewport.w)), height)


def calendar_time_to_minutes(value: str) -> int:
    normalized = normalize_iso_time(value, field_name="Calendar time")
    hour, minute = (int(part) for part in normalized.split(":", 1))
    return hour * 60 + minute


def calendar_minutes_to_time(minutes: int) -> str:
    bounded = int(clamp(int(minutes), 0, 24 * 60 - 1))
    return f"{bounded // 60:02d}:{bounded % 60:02d}"


def calendar_hour_label(hour: int) -> str:
    """Return one fixed-width 24-hour Calendar label such as ``0100``."""
    return f"{int(hour) % 24:02d}00"


def calendar_timeline_y_for_minutes(minutes: int, *, hour_px: int = CALENDAR_TIMELINE_HOUR_PX) -> int:
    return int(round(int(minutes) * max(1, int(hour_px)) / 60.0))


def calendar_minutes_from_timeline_y(
    y: int | float,
    *,
    hour_px: int = CALENDAR_TIMELINE_HOUR_PX,
    snap_minutes: int = CALENDAR_TIMELINE_SNAP_MINUTES,
) -> int:
    raw = float(y) * 60.0 / max(1, int(hour_px))
    snap = max(1, int(snap_minutes))
    snapped = int(round(raw / snap) * snap)
    return int(clamp(snapped, 0, 24 * 60 - snap))


def aspect_fit_rect(bounds: Rect, source_w: int | float, source_h: int | float) -> Rect:
    """Center an image in bounds while preserving source aspect ratio."""
    try:
        sw = float(source_w)
        sh = float(source_h)
    except Exception:
        sw = sh = 0.0
    if bounds.w <= 0 or bounds.h <= 0 or sw <= 0 or sh <= 0:
        return bounds
    scale = min(bounds.w / sw, bounds.h / sh)
    w = max(1, int(round(sw * scale)))
    h = max(1, int(round(sh * scale)))
    return Rect(bounds.x + (bounds.w - w) // 2, bounds.y + (bounds.h - h) // 2, w, h)


@dataclass(frozen=True, slots=True)
class Color:
    r: int
    g: int
    b: int
    a: int = 255


# =============================================================================
# Theme colors
# =============================================================================

# Modern dark palette inspired by attached UI screenshot.
THEME_BG = Color(9, 9, 10)
THEME_PANEL = Color(18, 18, 20)
THEME_PANEL_ALT = Color(14, 14, 16)
THEME_PANEL_RAISED = Color(26, 26, 30)
THEME_INPUT_BG = Color(15, 15, 18)
THEME_INPUT_ACTIVE = Color(22, 22, 27)
THEME_HOVER = Color(34, 34, 40)
THEME_SELECTED = Color(30, 62, 130)
THEME_PRIMARY = Color(40, 110, 220)
THEME_PRIMARY_HOVER = Color(58, 126, 235)
THEME_DANGER_BG = Color(105, 0, 0)
THEME_DANGER_HOVER = Color(136, 20, 20)
THEME_TEXT = Color(244, 244, 246)
THEME_TEXT_MUTED = Color(178, 178, 184)
THEME_TEXT_DIM = Color(126, 126, 136)
THEME_ACCENT = Color(40, 110, 220)
THEME_ACCENT_2 = Color(150, 150, 255)
THEME_DANGER = Color(210, 82, 82)
THEME_WARN = Color(255, 205, 96)
THEME_THINKING = Color(210, 181, 84)
THEME_OK = Color(88, 214, 150)
THEME_BORDER = Color(42, 42, 50)
THEME_SCROLL_TRACK = Color(20, 20, 24)
THEME_SCROLL_THUMB = Color(54, 58, 86)
THEME_SCROLL_THUMB_HOVER = Color(75, 84, 136)
THEME_CODE_BG = Color(8, 11, 14, 220)
THEME_MODAL_BACKDROP = Color(0, 0, 0, 180)
THEME_BLACK = Color(0, 0, 0)
THEME_WHITE = Color(255, 255, 255)


_THEME_ALPHA_CACHE: dict[tuple[int, int, int, int], Color] = {}
_THEME_LERP_CACHE: dict[tuple[tuple[int, int, int, int], tuple[int, int, int, int], int], Color] = {}


def _color_key(c: Color) -> tuple[int, int, int, int]:
    return (int(c.r), int(c.g), int(c.b), int(c.a))


def theme_alpha(color: Color, alpha: int) -> Color:
    # micro-opt: alpha variants are requested thousands of times per frame.
    a = int(clamp(alpha, 0, 255))
    key = (int(color.r), int(color.g), int(color.b), a)
    cached = _THEME_ALPHA_CACHE.get(key)
    if cached is not None:
        return cached
    out = Color(key[0], key[1], key[2], key[3])
    if len(_THEME_ALPHA_CACHE) > 1024:
        _THEME_ALPHA_CACHE.clear()
    _THEME_ALPHA_CACHE[key] = out
    return out


def theme_lerp(a: Color, b: Color, t: float) -> Color:
    # Quantize to 0.1% so gradient colors become cacheable.
    tq = int(clamp(float(t), 0.0, 1.0) * 1000 + 0.5)
    key = (_color_key(a), _color_key(b), tq)
    cached = _THEME_LERP_CACHE.get(key)
    if cached is not None:
        return cached
    tt = tq / 1000.0
    out = Color(
        int(a.r + (b.r - a.r) * tt),
        int(a.g + (b.g - a.g) * tt),
        int(a.b + (b.b - a.b) * tt),
        int(a.a + (b.a - a.a) * tt),
    )
    if len(_THEME_LERP_CACHE) > 4096:
        _THEME_LERP_CACHE.clear()
    _THEME_LERP_CACHE[key] = out
    return out


def theme_mix(a: Color, b: Color, amount: float = 0.5) -> Color:
    return theme_lerp(a, b, amount)


