@dataclass(slots=True)
class LayoutRow:
    # Feature: long text layout generates display rows left-to-right, top-to-bottom.
    text: str
    x: int
    y: int
    h: int
    kind: str = "text"
    color: Color = field(default_factory=lambda: Palette.text)
    bg: Color | None = None
    spans: list[dict[str, Any]] = field(default_factory=list)
    cells: list[Rect] = field(default_factory=list)
    # Table spans are grouped once during layout so each cell needs one clip pair,
    # rather than one push/pop pair per styled span on every frame.
    table_span_groups: list[list[dict[str, Any]]] = field(default_factory=list)
    # Per-layout-row draw classification and plain-run geometry are cached after
    # first paint. This removes repeated span scans/measurements on every frame.
    draw_mode: str = ""
    draw_tail_index: int = 0
    plain_text_x: int = -1
    plain_text_width: int = -1
    # Pixel baseline from the row top. -1 supports directly constructed test rows.
    baseline_y: int = -1


@dataclass(frozen=True, slots=True)
class WrappedTextRow:
    """One visual editor row mapped back to the original source string."""
    text: str
    start: int
    end: int
    width: int


@dataclass(slots=True)
class TextLayout:
    rows: list[LayoutRow]
    width: int
    height: int
    row_tops: list[int]
    # Incremented when an append-only large-card layout mutates this object in
    # place. Selection/copy caches key on both object identity and this revision.
    revision: int = 0


@dataclass
class UIInput:
    mouse_x: int = 0
    mouse_y: int = 0
    mouse_press_x: int = -1
    mouse_press_y: int = -1
    mouse_release_x: int = -1
    mouse_release_y: int = -1
    mouse_moved: bool = False
    mouse_down: bool = False
    mouse_pressed: bool = False
    mouse_released: bool = False
    mouse_button: int = 0
    mouse_clicks: int = 0
    right_pressed: bool = False
    right_released: bool = False
    mouse_consumed: bool = False
    wheel_y: int = 0
    text: str = ""
    key_backspace: bool = False
    key_delete: bool = False
    key_enter: bool = False
    key_escape: bool = False
    key_tab: bool = False
    key_left: bool = False
    key_right: bool = False
    key_up: bool = False
    key_down: bool = False
    key_home: bool = False
    key_end: bool = False
    key_page_up: bool = False
    key_page_down: bool = False
    find_requested: bool = False
    paste_text: str = ""
    paste_file_paths: list[str] = field(default_factory=list)
    paste_image_paths: list[str] = field(default_factory=list)
    paste_image_data: list[dict[str, Any]] = field(default_factory=list)
    copy_requested: bool = False
    cut_requested: bool = False
    undo_requested: bool = False
    redo_requested: bool = False
    select_all: bool = False
    ctrl_down: bool = False
    cmd_down: bool = False
    shift_down: bool = False
    quit: bool = False

    def begin_frame(self) -> None:
        self.mouse_moved = False
        self.mouse_press_x = -1
        self.mouse_press_y = -1
        self.mouse_release_x = -1
        self.mouse_release_y = -1
        self.mouse_pressed = False
        self.mouse_released = False
        self.mouse_button = 0
        self.mouse_clicks = 0
        self.right_pressed = False
        self.right_released = False
        self.mouse_consumed = False
        self.wheel_y = 0
        self.text = ""
        self.key_backspace = False
        self.key_delete = False
        self.key_enter = False
        self.key_escape = False
        self.key_tab = False
        self.key_left = False
        self.key_right = False
        self.key_up = False
        self.key_down = False
        self.key_home = False
        self.key_end = False
        self.key_page_up = False
        self.key_page_down = False
        self.find_requested = False
        self.paste_text = ""
        self.paste_file_paths = []
        self.paste_image_paths = []
        self.paste_image_data = []
        self.copy_requested = False
        self.cut_requested = False
        self.undo_requested = False
        self.redo_requested = False
        self.select_all = False
        self.quit = False

    @property
    def primary_modifier(self) -> bool:
        return self.ctrl_down or self.cmd_down

    def snapshot(self) -> dict[str, Any]:
        # Immediate-mode UI sometimes needs to draw a background scene under a modal.
        # Keep a complete copy so modal controls receive the original input after the
        # background has been rendered with interaction suppressed.
        snap: dict[str, Any] = {}
        for name in self.__dataclass_fields__:
            value = getattr(self, name)
            snap[name] = list(value) if isinstance(value, list) else value
        return snap

    def restore(self, snapshot: dict[str, Any]) -> None:
        for name, value in snapshot.items():
            setattr(self, name, value)

    def suppress_for_background_overlay(self) -> None:
        # Block all click, drag, wheel, text, clipboard, and navigation events while
        # drawing UI that is visually underneath a modal/dropdown. Mouse position is
        # preserved so drawing code that depends on coordinates remains harmless.
        self.mouse_down = False
        self.mouse_press_x = -1
        self.mouse_press_y = -1
        self.mouse_release_x = -1
        self.mouse_release_y = -1
        self.mouse_pressed = False
        self.mouse_released = False
        self.mouse_button = 0
        self.mouse_clicks = 0
        self.right_pressed = False
        self.right_released = False
        self.mouse_consumed = True
        self.wheel_y = 0
        self.text = ""
        self.key_backspace = False
        self.key_delete = False
        self.key_enter = False
        self.key_escape = False
        self.key_tab = False
        self.key_left = False
        self.key_right = False
        self.key_up = False
        self.key_down = False
        self.key_home = False
        self.key_end = False
        self.key_page_up = False
        self.key_page_down = False
        self.find_requested = False
        self.paste_text = ""
        self.paste_file_paths = []
        self.paste_image_paths = []
        self.paste_image_data = []
        self.copy_requested = False
        self.cut_requested = False
        self.undo_requested = False
        self.redo_requested = False
        self.select_all = False


