@dataclass
class Services:
    storage: Storage
    chats: ChatStore
    agents: AgentStore
    llm: LLMClient
    context: ContextAssembler
    tools: ToolRegistry
    summaries: SummaryService
    chat: ChatRuntime
    agent_runtime: AgentRuntime
    monitor: LLMTaskMonitor
    context_docs: ContextDocStore | None = None
    context_doc_service: ContextDocService | None = None
    scheduled_tasks: ScheduledTaskStore | None = None
    scheduled_task_scheduler: ScheduledTaskScheduler | None = None
    inference_scheduler: EndpointInferenceScheduler | None = None
    calendar: CalendarStore | None = None
    vault: VaultStore | None = None
    vault_query: VaultQueryService | None = None
    google_calendar: GoogleCalendarIntegration | None = None
    google_drive: GoogleDriveConnector | None = None
    gmail: GmailConnector | None = None
    slack: SlackConnector | None = None
    vault_connectors: VaultConnectorManager | None = None
    calendar_refresh_callback: Callable[[], Any] | None = None
    credentials: CredentialStore | None = None

    def refresh_calendar(self) -> Any:
        """Start one guarded read-only Google Calendar synchronization."""
        if callable(self.calendar_refresh_callback):
            return self.calendar_refresh_callback()
        if self.google_calendar is not None:
            return self.google_calendar.refresh()
        raise RuntimeError("Google Calendar synchronization is unavailable")

    def connect_google_calendar(self) -> Any:
        if self.google_calendar is None:
            raise RuntimeError("Google Calendar integration is unavailable")
        return self.google_calendar.connect()

    def disconnect_google_calendar(self) -> Any:
        if self.google_calendar is None:
            raise RuntimeError("Google Calendar integration is unavailable")
        return self.google_calendar.disconnect()

    def google_calendar_status(self) -> dict[str, Any]:
        if self.google_calendar is None:
            return {
                "connected": False, "token_present": False,
                "oauth_client_configured": False, "oauth_client_source": "missing",
                "dependencies": {"available": False, "message": "Google Calendar integration is unavailable"},
                "account": default_google_calendar_account_identity(), "calendars": [],
                "last_attempted_at": "", "last_successful_at": "", "last_error": "",
                "operation_in_progress": False,
            }
        return self.google_calendar.status()

    def set_google_calendar_enabled(self, calendar_id: str, enabled: bool) -> dict[str, Any]:
        if self.google_calendar is None:
            raise RuntimeError("Google Calendar integration is unavailable")
        return self.google_calendar.set_calendar_enabled(calendar_id, enabled)

    def set_google_calendar_display_color(self, calendar_id: str, color_key: str) -> dict[str, Any]:
        if self.google_calendar is None:
            raise RuntimeError("Google Calendar integration is unavailable")
        return self.google_calendar.set_calendar_display_color(calendar_id, color_key)

    def vault_connector_status(self, source_type: str) -> dict[str, Any]:
        if self.vault_connectors is None:
            raise RuntimeError("Vault connector manager is unavailable")
        return self.vault_connectors.status(source_type)

    def start_vault_connector_operation(self, source_type: str, operation: str) -> asyncio.Task:
        if self.vault_connectors is None:
            raise RuntimeError("Vault connector manager is unavailable")
        return self.vault_connectors.start(source_type, operation)

    def delete_agent(self, agent_id: str) -> dict[str, Any]:
        """Delete one paused or finished agent task through the live runtime."""
        return self.agent_runtime.delete_agent(agent_id, force=False)

    def delete_chat(self, chat_id: str) -> dict[str, Any]:
        """Delete a chat and every durable agent task linked to that chat."""
        resolved = str(chat_id or "").strip()
        if not resolved:
            raise ValueError("chat_id is required")
        self.chats.load_chat(resolved)
        # Mark the chat before cancelling work so an already-running idle summary
        # cannot publish a late result after the directory is removed.
        self.summaries.discard_chat(resolved)
        try:
            self.tools.terminal_runtime.close_all_for_owner(
                "chat", resolved, reason="Source chat was deleted; active terminal session closed."
            )
            agent_ids = [
                str(row.get("agent_id") or "")
                for row in self.agents.list_agents(resolved)
                if str(row.get("agent_id") or "")
            ]
            self.chat.discard_chat(resolved, agent_ids=agent_ids)
            deleted_agent_ids = self.agent_runtime.delete_agents_for_chat(resolved)
            self.chats.delete_chat(APP_SCOPE_ID, resolved)
        except Exception:
            # A failed delete must not permanently disable summaries for a chat
            # that remains on disk.
            if self.storage.paths.chat_json(resolved).is_file():
                self.summaries.restore_chat(resolved)
            raise
        return {"chat_id": resolved, "deleted_agent_ids": deleted_agent_ids}


@dataclass(slots=True)
class AssistantStreamingSectionState:
    """Small parser checkpoint for one append-only reasoning/answer stream."""

    raw_length: int
    head: str
    boundary_tail: str
    opener: str
    closer: str
    open_end: int
    close_start: int = -1
    close_end: int = -1
    last_used: float = 0.0


def chat_missing_reasoning_diagnostic(turn: dict[str, Any]) -> str:
    if str(turn.get("status") or "") == "streaming":
        return ""
    stats = turn.get("stats") if isinstance(turn.get("stats"), dict) else {}
    count = _nonnegative_token_value(stats.get("reported_reasoning_tokens"))
    rows = stats.get("section_stats") if isinstance(stats.get("section_stats"), list) else []
    if count is None:
        count = next((int(row.get("output_tokens") or 0) for row in rows
            if isinstance(row, dict) and row.get("kind") == "thinking"
            and row.get("token_allocation") == "provider_reasoning_details"), 0)
    if not count or stats.get("reasoning_text_available"):
        return ""
    if any(isinstance(row, dict) and row.get("kind") == "thinking"
           and int(row.get("visible_output_chars") or row.get("output_chars") or 0) > 0 for row in rows):
        return ""
    if reasoning_content_from_text(str(turn.get("text") or "")):
        return ""
    return (f"Endpoint usage reports {count:,} reasoning tokens, but no readable reasoning text was captured "
            "for this response. This is a delivery diagnostic, not the model's thoughts. "
            "Decode speed cannot be inferred from the final tool-call burst. See request details.")


class Panels:
    def __init__(self, widgets: Widgets, state: UIState, services: Services):
        self.widgets = widgets
        self.state = state
        self.services = services
        self.widgets.markdown_local_candidates_provider = self._markdown_local_candidates
        self._assistant_section_stream_cache: dict[tuple[str, bool], AssistantStreamingSectionState] = {}

    @property
    def r(self) -> Renderer:
        return self.widgets.renderer

    @property
    def f(self) -> FontAtlas:
        return self.widgets.font

    def _markdown_context_chat_id(self) -> str:
        """Return the active Chat whose workspace owns rendered Markdown."""
        return str(self.state.active_chat_id or "").strip()

    def _markdown_local_candidates(self, source: str) -> list[Path]:
        """Resolve relative Markdown files against the current Chat workspace."""
        raw = str(source or "").strip()
        if not raw or raw.startswith("#"):
            return []
        parsed = urllib.parse.urlparse(raw)
        if parsed.scheme.casefold() in {"http", "https", "data", "blob", "mailto"}:
            return []
        normalized = urllib.parse.unquote(raw).replace("\\", "/")
        named_prefix = any(
            normalized.casefold().startswith(prefix + "/")
            for prefix in RELATIVE_LOCAL_PATH_ROOT_NAMES
        )
        if not (
            named_prefix
            or normalized.startswith(("./", "../"))
            or is_probable_relative_local_path_text(normalized)
        ):
            return []
        chat_id = self._markdown_context_chat_id()
        if not chat_id:
            return []
        return _local_markdown_path_candidates(self.services.storage.paths, chat_id, raw)

    def _yolo_deletes_enabled(self) -> bool:
        try:
            if isinstance(self.state.config_draft, dict):
                return bool(self.state.config_draft.get("ui", {}).get("yolo_deletes", False))
            return bool(self.services.storage.load_config().get("ui", {}).get("yolo_deletes", False))
        except Exception:
            return False

    def _clear_deleted_chat_ui_state(self, chat_id: str) -> None:
        """Remove every transient UI reference to a chat that no longer exists."""
        resolved = str(chat_id or "").strip()
        if not resolved:
            return
        self.state.chat_composer_drafts.pop(resolved, None)
        self.state.chat_attachment_drafts.pop(resolved, None)
        self.state.composer_editor_drafts.pop(self._chat_composer_draft_key(resolved), None)
        self.state.chat_selected_checklist_ids.pop(resolved, None)
        if self.state.calendar_previous_chat_id == resolved:
            self.state.calendar_previous_chat_id = None
        if self.state.calendar_week_chat_bound_id == resolved:
            self.state.calendar_week_chat_bound_id = ""
        for mapping in (
            self.state.chat_thread_positions,
            self.state.chat_thread_anchors,
            self.state.chat_autoscroll_target,
            self.state.chat_autoscroll_enabled,
            self.state.chat_autoscroll_changed_at,
        ):
            for key in [key for key in mapping if str(key).endswith(":" + resolved)]:
                mapping.pop(key, None)
        if self.state.chat_task_label_chat_id == resolved:
            self.state.chat_task_label_chat_id = ""
            self.state.chat_task_label_chat_source = None
            self.state.chat_task_label_config_source = None
            self.state.chat_task_label_value = ""
        if self.state.active_chat_id == resolved:
            self.state.active_chat_id = None
            self.state.composer_draft_binding = ""
            self.state.composer_text = ""
            self.state.queued_attachments = []
            self.state.chat_context_usage_cache = {}
        self._reset_chat_ui_cache(reset_scroll=self.state.active_chat_id is None)

    def _delete_chat_now(self, chat_id: str) -> bool:
        resolved = str(chat_id or "").strip()
        if not resolved:
            return False
        delete_error: Exception | None = None
        try:
            summary_task = getattr(self.state, "chat_summary_task", None)
            summary_chat_id = ""
            if isinstance(self.state.modal, dict):
                summary_chat_id = str(self.state.modal.get("summary_chat_id") or "")
            if summary_task and not summary_task.done() and (
                self.state.active_chat_id == resolved or summary_chat_id == resolved
            ):
                summary_task.cancel()
                self.state.chat_summary_task = None
            self.services.delete_chat(resolved)
        except Exception as exc:
            delete_error = exc

        # A delete can commit on disk and then encounter a late cleanup/logging
        # error. Decide from the durable record, not from the exception alone.
        chat_still_exists = self.services.chats.paths.chat_json(resolved).is_file()
        if delete_error is not None and chat_still_exists:
            if isinstance(self.state.modal, dict):
                self.state.modal["error"] = f"{type(delete_error).__name__}: {delete_error}"
            else:
                self.state.add_toast(
                    "Chat deletion failed",
                    f"{type(delete_error).__name__}: {delete_error}",
                    "error",
                )
            return False

        # Once chat.json is gone, the old ID is invalid even if a late operation
        # raised. Clear it before any fallible list/search work so the next draw
        # cannot dereference deleted metadata.
        self._clear_deleted_chat_ui_state(resolved)
        selection_error: Exception | None = None
        try:
            self._ensure_active_chat_selection()
        except Exception as exc:
            # Keep the state safely unbound; draw_frame will retry selection.
            self.state.active_chat_id = None
            self.state.composer_draft_binding = ""
            self.state.composer_text = ""
            self.state.queued_attachments = []
            self._reset_chat_ui_cache(reset_scroll=True)
            selection_error = exc
        if self.state.chat_search_active:
            try:
                self._perform_chat_search()
            except Exception as exc:
                if selection_error is None:
                    selection_error = exc

        warning_parts: list[str] = []
        if delete_error is not None:
            warning_parts.append(f"post-delete cleanup: {type(delete_error).__name__}: {delete_error}")
        if selection_error is not None:
            warning_parts.append(f"selection recovery: {type(selection_error).__name__}: {selection_error}")
        if warning_parts:
            try:
                self.services.storage.append_app_log(
                    "chat.delete.recovery_warning",
                    {"chat_id": resolved, "warning": "; ".join(warning_parts)},
                )
            except Exception:
                pass
        return True

    def _request_chat_delete(self, chat_id: str, name: str = "") -> None:
        resolved = str(chat_id or "").strip()
        if not resolved:
            return
        if self._yolo_deletes_enabled():
            self._delete_chat_now(resolved)
            return
        linked_count = len(self.services.agents.list_agents(resolved))
        self.state.modal = {
            "kind": "confirm_delete_chat",
            "chat_id": resolved,
            "name": str(name or "Chat"),
            "linked_agent_count": linked_count,
            "error": "",
        }

    def _delete_agent_now(self, agent_id: str) -> bool:
        resolved = str(agent_id or "").strip()
        if not resolved:
            return False
        delete_error: Exception | None = None
        try:
            self.services.delete_agent(resolved)
        except Exception as exc:
            delete_error = exc
        agent_still_exists = self.services.storage.paths.agent_json(resolved).is_file()
        if delete_error is not None and agent_still_exists:
            if isinstance(self.state.modal, dict):
                self.state.modal["error"] = f"{type(delete_error).__name__}: {delete_error}"
            else:
                self.state.add_toast(
                    "Agent deletion failed",
                    f"{type(delete_error).__name__}: {delete_error}",
                    "error",
                )
            return False
        # If the durable record disappeared, deletion committed. Never leave a
        # selected-agent pointer behind merely because a late cleanup/log failed.
        if self.state.selected_agent_id == resolved:
            self.state.selected_agent_id = None
        if self.state.chat_selected_agent_id == resolved:
            self.state.chat_selected_agent_id = None
        if self.state.calendar_selected_agent_id == resolved:
            self.state.calendar_selected_agent_id = None
        if isinstance(self.state.modal, dict) and str(self.state.modal.get("agent_id") or "") == resolved:
            self.state.modal = None
        if delete_error is not None:
            try:
                self.services.storage.append_app_log(
                    "agent.delete.recovery_warning",
                    {"agent_id": resolved, "warning": f"{type(delete_error).__name__}: {delete_error}"},
                )
            except Exception:
                pass
        return True

    def _request_agent_delete(self, agent_id: str) -> None:
        resolved = str(agent_id or "").strip()
        if not resolved:
            return
        try:
            agent = self.services.agents.load_agent(resolved)
            status = str(agent.get("status") or "")
            if status not in AGENT_DELETABLE_STATUSES:
                raise ValueError("Only paused or finished agent tasks can be deleted.")
        except Exception as exc:
            self.state.add_toast("Agent cannot be deleted", f"{type(exc).__name__}: {exc}", "error")
            return
        if self._yolo_deletes_enabled():
            self._delete_agent_now(resolved)
            return
        self.state.modal = {
            "kind": "confirm_delete_agent",
            "agent_id": resolved,
            "title": str(agent.get("title") or "Background agent"),
            "status": status,
            "error": "",
        }

    def _open_skill_editor(self, name: str) -> None:
        try:
            text = self.services.tools.skill_store.read_skill_text(name)
            row, _directory = self.services.tools.skill_store._resolve_skill(name)
            canonical_name = str(row.get("name") or name)
            self.state.selected_skill_name = canonical_name
            self.state.modal = {
                "kind": "edit_skill",
                "name": canonical_name,
                "text": text,
                "original_text": text,
                "path": str(row.get("skill_file") or ""),
                "error": "",
            }
            self.state.text_cursors["modal.skill.editor"] = 0
            self.state.text_selections["modal.skill.editor"] = 0
            self.state.text_scroll_y["modal.skill.editor"] = 0
        except Exception as exc:
            self.state.add_toast("Skill could not be opened", f"{type(exc).__name__}: {exc}", "error")

    def _valid_file_picker_dir(self, preferred: str | Path | None = None) -> str:
        candidates: list[Path] = []
        if preferred:
            try:
                p = Path(preferred).expanduser()
                candidates.append(p if p.is_dir() else p.parent)
            except Exception:
                pass
        try:
            candidates.append(Path(str(getattr(self.state, "file_picker_last_dir", "") or "")).expanduser())
        except Exception:
            pass
        candidates.append(Path.home())
        for candidate in candidates:
            try:
                if candidate and candidate.is_dir():
                    return str(candidate.resolve())
            except Exception:
                continue
        return str(Path.home())

    def _open_file_picker(self, target: str, preferred: str | Path | None = None) -> None:
        self.state.file_picker_target = target
        self.state.file_picker_save = False
        self.state.file_picker_save_context = None
        self.state.file_picker_dir = self._valid_file_picker_dir(preferred)
        self.state.file_picker_last_dir = self.state.file_picker_dir
        self.state.file_picker_selected = None
        self.state.file_picker_selected_paths = []
        self.state.file_picker_manual = ""
        self.state.file_picker_selection_anchor = ""
        self.state.file_picker_attachment_owner = (
            (str(self.state.active_chat_id or ""), str(self.state.composer_draft_binding or ""))
            if target == "chat" else None
        )
        self.state.scroll["fp.list"] = 0
        self.state.active_widget = None
        self.state.file_picker_open = True

    def _calendar_store(self) -> CalendarStore:
        calendar = self.services.calendar
        if calendar is None:
            calendar = CalendarStore(self.services.storage)
            self.services.calendar = calendar
        return calendar

    def _reset_chat_ui_cache(self, *, reset_scroll: bool = True) -> None:
        # Section objects retain their own exact row/body geometry caches. Clear
        # those before discarding the top-level lists so Appearance changes such
        # as table-cell wrapping cannot reuse a pre-toggle card height.
        for section in list(getattr(self.state, "chat_sections_cache", []) or []):
            if isinstance(section, dict):
                section.pop("_chat_body_geometry_cache", None)
                section.pop("_chat_row_layout_cache", None)
        self.state.chat_turn_cache_key = None
        self.state.chat_turn_cache_identity = None
        self.state.chat_section_measure_cache.clear()
        self.state.chat_section_estimate_cache.clear()
        self.state.chat_sections_cache_key = None
        self.state.chat_sections_cache = []
        self.state.chat_sections_source_turns = []
        self.state.chat_sections_turn_ranges = []
        self.state.chat_sections_pending_media_after_turn = []
        self.state.chat_sections_changed_from_index = 0
        self.state.chat_rows_cache_key = None
        self.state.chat_rows_cache = []
        self.state.chat_rows_cache_tops = []
        self.state.chat_rows_cache_total_h = 0
        self.state.chat_rows_cache_base_key = None
        self.state.chat_rows_cache_sections = None
        getattr(self, "_assistant_section_stream_cache", {}).clear()
        if reset_scroll:
            self.state.scroll["chat.thread"] = 0

    @staticmethod
    def _chat_composer_draft_key(chat_id: str | None) -> str:
        resolved = str(chat_id or "").strip()
        return f"chat:{resolved}" if resolved else ""


    def _save_composer_editor_state(self, draft_key: str) -> None:
        """Save the fixed composer widget's complete transient editor state."""
        key = str(draft_key or "").strip()
        if not key:
            return
        widget_id = "composer.text"
        self.state.composer_editor_drafts[key] = {
            "cursor": int(self.state.text_cursors.get(widget_id, len(self.state.composer_text))),
            "selection": int(self.state.text_selections.get(widget_id, len(self.state.composer_text))),
            "scroll_x": int(self.state.text_scroll_x.get(widget_id, 0)),
            "scroll_y": int(self.state.text_scroll_y.get(widget_id, 0)),
            "manual_scroll_locked": bool(self.state.text_manual_scroll_locked.get(widget_id, False)),
            "undo": copy.deepcopy(self.state.text_undo_stacks.get(widget_id, [])),
            "redo": copy.deepcopy(self.state.text_redo_stacks.get(widget_id, [])),
            "history_value": str(self.state.text_history_values.get(widget_id, self.state.composer_text)),
            "preferred_col": self.state.text_preferred_col.get(widget_id),
            "caret_reset_at": self.state.text_caret_reset_at.get(widget_id),
        }

    def _load_composer_editor_state(self, draft_key: str) -> None:
        """Restore one chat/week editor without sharing history with another."""
        key = str(draft_key or "").strip()
        widget_id = "composer.text"
        saved = self.state.composer_editor_drafts.get(key) if key else None
        if isinstance(saved, dict):
            text_length = len(self.state.composer_text)
            self.state.text_cursors[widget_id] = int(clamp(int(saved.get("cursor", text_length)), 0, text_length))
            self.state.text_selections[widget_id] = int(clamp(int(saved.get("selection", text_length)), 0, text_length))
            self.state.text_scroll_x[widget_id] = max(0, int(saved.get("scroll_x", 0)))
            self.state.text_scroll_y[widget_id] = max(0, int(saved.get("scroll_y", 0)))
            self.state.text_manual_scroll_locked[widget_id] = bool(saved.get("manual_scroll_locked", False))
            self.state.text_undo_stacks[widget_id] = copy.deepcopy(saved.get("undo") or [])
            self.state.text_redo_stacks[widget_id] = copy.deepcopy(saved.get("redo") or [])
            self.state.text_history_values[widget_id] = str(saved.get("history_value", self.state.composer_text))
            preferred = saved.get("preferred_col")
            if preferred is None:
                self.state.text_preferred_col.pop(widget_id, None)
            else:
                self.state.text_preferred_col[widget_id] = int(preferred)
            caret_reset = saved.get("caret_reset_at")
            if caret_reset is None:
                self.state.text_caret_reset_at.pop(widget_id, None)
            else:
                self.state.text_caret_reset_at[widget_id] = float(caret_reset)
        else:
            end = len(self.state.composer_text)
            self.state.text_cursors[widget_id] = end
            self.state.text_selections[widget_id] = end
            self.state.text_scroll_x.pop(widget_id, None)
            self.state.text_scroll_y.pop(widget_id, None)
            self.state.text_manual_scroll_locked.pop(widget_id, None)
            self.state.text_undo_stacks.pop(widget_id, None)
            self.state.text_redo_stacks.pop(widget_id, None)
            self.state.text_history_values[widget_id] = self.state.composer_text
            self.state.text_preferred_col.pop(widget_id, None)
            self.state.text_caret_reset_at.pop(widget_id, None)
        if self.state.text_drag_widget == widget_id:
            self.state.text_drag_widget = None
        self.state.composer_draft_binding = key

    def _save_chat_composer_draft(self, chat_id: str | None) -> None:
        resolved = str(chat_id or "").strip()
        if not resolved:
            return
        key = self._chat_composer_draft_key(resolved)
        self.state.chat_composer_drafts[resolved] = str(self.state.composer_text or "")
        self.state.chat_attachment_drafts[resolved] = copy.deepcopy(self.state.queued_attachments)
        self._save_composer_editor_state(key)
        self.state.composer_draft_binding = key

    def _load_chat_composer_draft(self, chat_id: str | None) -> None:
        resolved = str(chat_id or "").strip()
        if not resolved:
            self.state.composer_text = ""
            self.state.queued_attachments = []
            self._load_composer_editor_state("")
            return
        self.state.composer_text = str(self.state.chat_composer_drafts.get(resolved, ""))
        self.state.queued_attachments = copy.deepcopy(
            self.state.chat_attachment_drafts.get(resolved, [])
        )
        self._load_composer_editor_state(self._chat_composer_draft_key(resolved))

    @staticmethod
    def _chat_row_anchor(rows: list[Any], index: int) -> tuple[str, str, int]:
        section = rows[index][0]
        turn_id, kind = str((section.get("turn") or {}).get("turn_id") or ""), str(section.get("kind") or "")
        ordinal = sum(1 for row in rows[:index]
                      if str((row[0].get("turn") or {}).get("turn_id") or "") == turn_id
                      and str(row[0].get("kind") or "") == kind)
        return turn_id, kind, ordinal

    def _remember_chat_scroll(self, chat_id: str) -> None:
        key = f"{APP_SCOPE_ID}:{chat_id}"
        offset = max(0, int(self.state.scroll.get("chat.thread", 0)))
        self.state.chat_thread_positions[key] = offset
        rows = self.state.chat_rows_cache
        if rows and not self.state.chat_thread_restore:
            tops = self.state.chat_rows_cache_tops
            if len(tops) != len(rows):
                tops = [row[1] for row in rows]
            index = max(0, min(len(rows)-1, bisect.bisect_right(tops, offset)-1))
            self.state.chat_thread_anchors[key] = (self._chat_row_anchor(rows, index), offset-int(rows[index][1]))

    def _restore_chat_scroll(
        self, rows: list[Any], offset: int, *, stable: bool, manual_input: bool = False,
    ) -> int:
        pending = self.state.chat_thread_restore
        if not pending:
            return offset
        key, frames = pending
        if (key != f"{self.state.active_scope_id}:{self.state.active_chat_id}"
                or self.state.chat_autoscroll_enabled.get(key, True)
                or manual_input or self.state.drag_scrollbar_id == "chat.thread"
                or self.state.chat_jump_query):
            self.state.chat_thread_restore = None
            return offset
        anchor = self.state.chat_thread_anchors.get(key)
        if not anchor:
            self.state.chat_thread_restore = None
            return offset
        identity, within = anchor
        ordinal = 0
        for section, y, height, _measure_key in rows:
            if (str((section.get("turn") or {}).get("turn_id") or ""), str(section.get("kind") or "")) == identity[:2]:
                if ordinal == identity[2]:
                    self.state.chat_thread_restore = None if stable or frames <= 1 else (key, frames-1)
                    return max(0, int(y) + min(max(0, within), max(0, int(height)-1)))
                ordinal += 1
        self.state.chat_thread_restore = None  # The anchored card was removed.
        return offset

    def _switch_active_chat(
        self,
        chat_id: str | None,
        *,
        save_current: bool = True,
        reset_scroll: bool = True,
        restore_composer: bool | None = None,
    ) -> bool:
        """Switch chat identity atomically while preserving each chat's private draft.

        Validate the destination before mutating ``active_chat_id``. A stale list
        row, Calendar mapping, or concurrently deleted chat must never poison the
        UI state with an ID whose metadata cannot be loaded.
        """
        next_id = str(chat_id or "").strip()
        current_id = str(self.state.active_chat_id or "").strip()
        next_endpoint_profile_id = ""
        if next_id:
            # This is intentionally before every state mutation below.
            destination = self.services.chats.load_chat(next_id)
            next_endpoint_profile_id = str(destination.get("endpoint_profile_id") or "").strip()
        if save_current and current_id and self.state.active_panel == "chat":
            self._save_chat_composer_draft(current_id)
        changed = next_id != current_id
        if changed and current_id:
            self._remember_chat_scroll(current_id)
        self.state.active_chat_id = next_id or None
        if next_id:
            self.state.composer_endpoint_profile_id = next_endpoint_profile_id
        should_restore = self.state.active_panel == "chat" if restore_composer is None else bool(restore_composer)
        if should_restore:
            self._load_chat_composer_draft(next_id)
        if changed:
            self._reset_chat_ui_cache(reset_scroll=False)
            next_key = f"{APP_SCOPE_ID}:{next_id}"
            self.state.scroll["chat.thread"] = self.state.chat_thread_positions.get(next_key, 0)
            self.state.chat_thread_restore = (next_key, 4) if next_key in self.state.chat_thread_anchors else None
            # An in-flight drag belongs to the old viewport, not the new Chat.
            if self.state.drag_scrollbar_id == "chat.thread":
                self.state.drag_scrollbar_id = None
            if str(self.state.active_widget or "").startswith("chat.thread"):
                self.state.active_widget = None
        return changed

    def _ensure_active_chat_selection(self) -> str:
        """Enforce the invariant that Chat always has one valid selected chat."""
        self.state.active_scope_id = APP_SCOPE_ID
        current_id = str(self.state.active_chat_id or "").strip()
        # The common path is one direct existence check. Do not trust the
        # 350-ms list cache for a correctness invariant after deletion.
        if current_id and self.services.chats.paths.chat_json(current_id).is_file():
            expected_key = self._chat_composer_draft_key(current_id)
            if self.state.active_panel == "chat" and self.state.composer_draft_binding != expected_key:
                self._load_chat_composer_draft(current_id)
            return current_id

        if current_id:
            self._clear_deleted_chat_ui_state(current_id)

        # Recovery is rare, so force a fresh list snapshot. If the selected row
        # disappears between listing and metadata load, retry once rather than
        # leaving a stale ID in UI state.
        for attempt in range(2):
            chats = self.services.chats.list_chats_view(
                APP_SCOPE_ID, external_poll_seconds=0.0,
            )
            if chats:
                selected_id = str(chats[0].get("chat_id") or "").strip()
            else:
                selected_id = str(self.services.chats.create_chat("New Chat")["chat_id"])
            if not selected_id:
                raise RuntimeError("Velox could not create or select a chat")
            try:
                self._switch_active_chat(
                    selected_id,
                    save_current=False,
                    reset_scroll=True,
                    restore_composer=self.state.active_panel == "chat",
                )
                return selected_id
            except FileNotFoundError:
                if attempt == 0:
                    continue
                raise
        raise RuntimeError("Velox could not create or select a chat")

    def _ensure_live_chat_for_action(
        self, ensure_active_chat: Callable[[], str | None] | None = None,
    ) -> str:
        """Return a live chat ID for a composer/attachment action or an empty string."""
        current_id = str(self.state.active_chat_id or "").strip()
        if current_id and self.services.chats.paths.chat_json(current_id).is_file():
            return current_id
        if current_id:
            self._clear_deleted_chat_ui_state(current_id)
        try:
            if callable(ensure_active_chat):
                ensure_active_chat()
            elif self.state.active_panel == "chat":
                self._ensure_active_chat_selection()
        except Exception as exc:
            self.state.add_toast(
                "Chat selection could not be restored",
                f"{type(exc).__name__}: {exc}",
                "error",
            )
            return ""
        resolved = str(self.state.active_chat_id or "").strip()
        return resolved if resolved and self.services.chats.paths.chat_json(resolved).is_file() else ""

    def _calendar_save_week_draft(self) -> None:
        week_start = calendar_week_start(self.state.calendar_selected_date).isoformat()
        self.state.calendar_week_composer_drafts[week_start] = str(self.state.composer_text or "")
        self.state.calendar_week_attachment_drafts[week_start] = copy.deepcopy(self.state.queued_attachments)
        self._save_composer_editor_state("week:" + week_start)
        self.state.composer_draft_binding = "week:" + week_start

    def _calendar_load_week_draft(self, day_value: str) -> None:
        week_start = calendar_week_start(day_value).isoformat()
        self.state.composer_text = str(self.state.calendar_week_composer_drafts.get(week_start, ""))
        self.state.queued_attachments = copy.deepcopy(
            self.state.calendar_week_attachment_drafts.get(week_start, [])
        )
        self._load_composer_editor_state("week:" + week_start)

    def _calendar_enter(self) -> None:
        if self.state.active_panel == "calendar":
            return
        self.state.calendar_previous_chat_id = self.state.active_chat_id
        if self.state.active_chat_id:
            self._save_chat_composer_draft(self.state.active_chat_id)
        self._calendar_load_week_draft(self.state.calendar_selected_date)
        self._calendar_sync_week_chat_selection(create=False)

    def _calendar_leave(self, destination: str) -> None:
        self._calendar_save_week_draft()
        if destination != "chat":
            return
        active_id = str(self.state.active_chat_id or "")
        active_is_week_chat = False
        if active_id:
            try:
                active_is_week_chat = self.services.chats.load_chat(active_id).get("chat_kind") == "week"
            except Exception:
                active_is_week_chat = False
        if active_is_week_chat:
            # Week Chats are ordinary chat rows when opened from Chat. Preserve
            # the same in-progress Calendar draft under that chat identity too.
            self._save_chat_composer_draft(active_id)
            self.state.composer_draft_binding = self._chat_composer_draft_key(active_id)
            self._reset_chat_ui_cache(reset_scroll=False)
            return
        previous = str(self.state.calendar_previous_chat_id or "")
        if previous and self.services.storage.paths.chat_json(previous).is_file():
            self._switch_active_chat(
                previous, save_current=False, reset_scroll=True, restore_composer=True,
            )
        else:
            self.state.active_chat_id = None
            self.state.composer_draft_binding = ""
            self.state.composer_text = ""
            self.state.queued_attachments = []
            self._reset_chat_ui_cache(reset_scroll=True)

    def _calendar_sync_week_chat_selection(self, *, create: bool) -> dict[str, Any] | None:
        day_value = normalize_iso_date(
            self.state.calendar_selected_date, field_name="Calendar selected date",
        )
        week_start = calendar_week_start(day_value).isoformat()
        calendar = self._calendar_store()
        chat = calendar.get_or_create_week_chat(week_start) if create else calendar.get_week_chat(week_start)
        next_id = str(chat.get("chat_id") or "") if isinstance(chat, dict) else ""
        if next_id != str(self.state.active_chat_id or ""):
            self._switch_active_chat(
                next_id or None,
                save_current=False,
                reset_scroll=True,
                restore_composer=False,
            )
        self.state.calendar_week_chat_bound_date = week_start
        self.state.calendar_week_chat_bound_id = next_id
        if next_id:
            self.state.composer_endpoint_profile_id = self.services.chats.get_chat_endpoint_profile_id(next_id)
        return chat

    def _calendar_ensure_week_chat(self) -> str | None:
        try:
            chat = self._calendar_sync_week_chat_selection(create=True)
            return str(chat.get("chat_id") or "") if isinstance(chat, dict) else None
        except Exception as exc:
            self.state.add_toast("Week Chat could not be created", f"{type(exc).__name__}: {exc}", "error")
            return None

    def _calendar_set_selected_date(self, day_value: str) -> None:
        normalized = normalize_iso_date(day_value, field_name="Calendar selected date")
        if normalized == self.state.calendar_selected_date:
            return
        previous_week = calendar_week_start(self.state.calendar_selected_date).isoformat()
        next_week = calendar_week_start(normalized).isoformat()
        if previous_week != next_week:
            self._calendar_save_week_draft()
        self.state.calendar_selected_date = normalized
        self.state.calendar_selected_kind = None
        self.state.calendar_selected_id = None
        self.state.scroll["calendar.timeline"] = CALENDAR_TIMELINE_DEFAULT_START_HOUR * CALENDAR_TIMELINE_HOUR_PX
        if previous_week != next_week:
            self._calendar_load_week_draft(normalized)
            self._calendar_sync_week_chat_selection(create=False)

    def _calendar_shift_selected_date(self, days: int) -> None:
        self._calendar_set_selected_date(
            calendar_shift_iso_date(self.state.calendar_selected_date, days),
        )

    def _calendar_select_object(self, kind: str, object_id: str) -> None:
        resolved_kind = str(kind or "").strip().lower()
        resolved_id = str(object_id or "").strip()
        if resolved_kind not in {"item", "event"} or not resolved_id:
            self.state.calendar_selected_kind = None
            self.state.calendar_selected_id = None
            return
        self.state.calendar_selected_kind = resolved_kind
        self.state.calendar_selected_id = resolved_id

    @staticmethod
    def _calendar_item_status_color(status: str) -> Color:
        return {
            "Info": Palette.accent2,
            "Action": Palette.warn,
            "Agent WIP": Palette.accent,
            "Review": Color(190, 125, 255),
            "Done": Palette.ok,
        }.get(str(status or ""), Palette.muted2)

    @staticmethod
    def _calendar_priority_color(priority: str) -> Color:
        return {"P1": Palette.danger, "P2": Palette.warn, "P3": Palette.muted2}.get(
            str(priority or ""), Palette.muted2,
        )

    def _calendar_event_minutes(self, event: dict[str, Any], day_value: str) -> tuple[int, int]:
        if bool(event.get("all_day")):
            return 0, 24 * 60
        zone = self._calendar_store().display_timezone()
        start_dt = _parse_iso_datetime(event.get("start"), field_name="Event start")
        end_dt = _parse_iso_datetime(event.get("end"), field_name="Event end")
        if start_dt.tzinfo is None:
            start_dt = start_dt.replace(tzinfo=timezone.utc)
        if end_dt.tzinfo is None:
            end_dt = end_dt.replace(tzinfo=timezone.utc)
        start_local = start_dt.astimezone(zone)
        end_local = end_dt.astimezone(zone)
        selected = date.fromisoformat(normalize_iso_date(day_value, field_name="Calendar date"))
        day_start = datetime.combine(selected, datetime_time.min, tzinfo=zone)
        start_min = int((start_local - day_start).total_seconds() // 60)
        end_min = int(math.ceil((end_local - day_start).total_seconds() / 60.0))
        return int(clamp(start_min, 0, 24 * 60)), int(clamp(end_min, 0, 24 * 60))


    @staticmethod
    def _item_editor_context_links_text(links: Any) -> str:
        rows: list[str] = []
        for link in links if isinstance(links, list) else []:
            if not isinstance(link, dict):
                continue
            fields = [
                str(link.get("type") or ""),
                str(link.get("label") or ""),
                str(link.get("url_or_path") or ""),
                str(link.get("source_excerpt") or ""),
                str(link.get("external_source_id") or ""),
            ]
            rows.append(" | ".join(field.replace("\n", " ").strip() for field in fields))
        return "\n".join(rows)

    @staticmethod
    def _parse_item_editor_context_links(text: str) -> list[dict[str, Any]]:
        links: list[dict[str, Any]] = []
        for line_number, raw in enumerate(str(text or "").splitlines(), start=1):
            line = raw.strip()
            if not line:
                continue
            if line.startswith("{"):
                try:
                    parsed = json.loads(line)
                except json.JSONDecodeError as exc:
                    raise ValueError(f"Context Link line {line_number} is not valid JSON") from exc
                links.append(normalize_context_link(parsed))
                continue
            parts = [part.strip() for part in line.split("|", 4)]
            if len(parts) < 3:
                raise ValueError(
                    f"Context Link line {line_number} must contain type | label | URL or local path"
                )
            while len(parts) < 5:
                parts.append("")
            links.append(normalize_context_link({
                "type": parts[0],
                "label": parts[1],
                "url_or_path": parts[2],
                "source_excerpt": parts[3],
                "external_source_id": parts[4],
            }))
        return links

    @staticmethod
    def _parse_item_editor_attachments(text: str) -> list[str]:
        rows: list[str] = []
        seen: set[str] = set()
        for raw in str(text or "").splitlines():
            path = raw.strip().strip('"').strip("'")
            if path and path not in seen:
                seen.add(path)
                rows.append(path)
        return rows

    def _calendar_event_option_map(
        self,
        *,
        day_value: str,
        linked_event_id: str | None = None,
    ) -> tuple[list[str], dict[str, str], dict[str, str]]:
        # Event linkage is independent of Item scheduling. Show every retained
        # Event, not only Events occurring on the Item's scheduled date.
        normalize_iso_date(day_value, field_name="Item editor date")
        events = self._calendar_store().list_all_events()
        if linked_event_id and all(str(row.get("event_id") or "") != linked_event_id for row in events):
            try:
                events.append(self._calendar_store().get_event(linked_event_id))
            except Exception:
                pass
        options = ["None"]
        display_to_id = {"None": ""}
        id_to_display = {"": "None"}
        counts: dict[str, int] = {}
        for event in sorted(events, key=self._calendar_store()._event_sort_key):
            if event.get("all_day"):
                lead = f"{str(event.get('start') or '')} · All day"
            else:
                try:
                    lead = _parse_iso_datetime(event.get("start"), field_name="Event start").strftime("%Y-%m-%d %H:%M")
                except Exception:
                    lead = "Date and time unavailable"
            base = f"{lead} — {str(event.get('title') or 'Untitled Event')}"
            counts[base] = counts.get(base, 0) + 1
            label = base if counts[base] == 1 else f"{base} ({counts[base]})"
            event_id = str(event.get("event_id") or "")
            options.append(label)
            display_to_id[label] = event_id
            id_to_display[event_id] = label
        return options, display_to_id, id_to_display

    def _open_item_editor(
        self,
        item: dict[str, Any] | None = None,
        *,
        scheduled_date: str | None = None,
        scheduled_start_time: str | None = None,
        linked_event_id: str | None = None,
        title: str = "",
        priority: str = "P2",
    ) -> None:
        existing = copy.deepcopy(item) if isinstance(item, dict) else None
        if existing is not None:
            draft = {
                "title": str(existing.get("title") or ""),
                "description": str(existing.get("description") or ""),
                "status": str(existing.get("status") or "Action"),
                "priority": str(existing.get("priority") or "P2"),
                "backlog": existing.get("scheduled_date") is None,
                "scheduled_date": str(existing.get("scheduled_date") or self.state.calendar_selected_date),
                "scheduled_start_time": str(existing.get("scheduled_start_time") or "09:00"),
                "duration_minutes": str(existing.get("duration_minutes") or DEFAULT_ITEM_DURATION_MINUTES),
                "linked_event_id": str(existing.get("linked_event_id") or ""),
                "context_links_text": self._item_editor_context_links_text(existing.get("context_links")),
                "attachments_text": "\n".join(str(path) for path in existing.get("attachments") or []),
            }
            mode = "edit"
            item_id = str(existing.get("item_id") or "")
        else:
            resolved_date = None if scheduled_date in (None, "") else normalize_iso_date(
                scheduled_date, field_name="Item scheduled date",
            )
            resolved_time = None if scheduled_start_time in (None, "") else normalize_iso_time(
                scheduled_start_time, field_name="Item scheduled start time",
            )
            if (resolved_date is None) != (resolved_time is None):
                raise ValueError("A new scheduled Item requires both date and start time")
            draft = {
                "title": str(title or ""),
                "description": "",
                "status": "Action",
                "priority": str(priority or "P2"),
                "backlog": resolved_date is None,
                "scheduled_date": resolved_date or self.state.calendar_selected_date,
                "scheduled_start_time": resolved_time or "09:00",
                "duration_minutes": str(DEFAULT_ITEM_DURATION_MINUTES),
                "linked_event_id": str(linked_event_id or ""),
                "context_links_text": "",
                "attachments_text": "",
            }
            mode = "create"
            item_id = ""
        self.state.modal = {
            "kind": "item_editor",
            "mode": mode,
            "item_id": item_id,
            "draft": draft,
            "error": "",
        }
        self.state.scroll["modal.item.editor"] = 0
        self.state.active_widget = "modal.item.title"
        self.state.text_cursors["modal.item.title"] = len(str(draft.get("title") or ""))

    def _save_item_editor(self, modal: dict[str, Any]) -> dict[str, Any]:
        draft = modal.get("draft") if isinstance(modal.get("draft"), dict) else {}
        title = str(draft.get("title") or "").strip()
        if not title:
            raise ValueError("Item title is required")
        status = str(draft.get("status") or "Action")
        priority = str(draft.get("priority") or "P2")
        if status not in ITEM_STATUSES:
            raise ValueError("Item status is invalid")
        if priority not in ITEM_PRIORITIES:
            raise ValueError("Item priority is invalid")
        backlog = bool(draft.get("backlog"))
        scheduled_date: str | None = None
        scheduled_time: str | None = None
        duration: int | None = None
        if not backlog:
            scheduled_date = normalize_iso_date(draft.get("scheduled_date"), field_name="Item scheduled date")
            scheduled_time = normalize_iso_time(
                draft.get("scheduled_start_time"), field_name="Item scheduled start time",
            )
            raw_duration = str(draft.get("duration_minutes") or "").strip()
            duration = DEFAULT_ITEM_DURATION_MINUTES if not raw_duration else int(raw_duration)
        linked_event_id = str(draft.get("linked_event_id") or "").strip() or None
        context_links = self._parse_item_editor_context_links(str(draft.get("context_links_text") or ""))
        attachments = self._parse_item_editor_attachments(str(draft.get("attachments_text") or ""))
        calendar = self._calendar_store()
        if str(modal.get("mode") or "") == "edit":
            item_id = str(modal.get("item_id") or "")
            saved = calendar.update_item(item_id, {
                "title": title,
                "description": str(draft.get("description") or ""),
                "status": status,
                "priority": priority,
                "scheduled_date": scheduled_date,
                "scheduled_start_time": scheduled_time,
                "duration_minutes": duration,
                "linked_event_id": linked_event_id,
                "context_links": context_links,
                "attachments": attachments,
            })
        else:
            saved = calendar.create_item(
                title,
                str(draft.get("description") or ""),
                status,
                priority,
                scheduled_date=scheduled_date,
                scheduled_start_time=scheduled_time,
                duration_minutes=duration,
                linked_event_id=linked_event_id,
                context_links=context_links,
                attachments=attachments,
            )
        self._calendar_select_object("item", str(saved["item_id"]))
        if saved.get("scheduled_date") == self.state.calendar_selected_date:
            self._calendar_sync_week_chat_selection(create=False)
        return saved

    def _append_google_calendar_event(self, message: Any) -> None:
        """Append one timestamped Google Calendar status line without spam."""
        clean = " ".join(str(message or "").split()).strip()
        if not clean:
            return
        entries = self.state.google_calendar_events
        if entries:
            previous = entries[-1].split("] ", 1)[-1]
            if previous == clean:
                return
        stamp = datetime.now().astimezone().strftime("%Y-%m-%d %H:%M:%S")
        entries.append(f"[{stamp}] {clean}")
        if len(entries) > 200:
            del entries[:-200]

    def _sync_google_calendar_status_events(
        self, status: dict[str, Any], connection_text: str, dependency_text: str,
    ) -> None:
        """Translate service-state changes into the visible timestamped event log."""
        snapshot = {
            "connection": str(connection_text or ""),
            "dependencies": str(dependency_text or ""),
            "last_error": str(status.get("last_error") or ""),
            "last_successful_at": str(status.get("last_successful_at") or ""),
        }
        previous = self.state.google_calendar_status_snapshot
        if snapshot["connection"] and snapshot["connection"] != previous.get("connection"):
            self._append_google_calendar_event(snapshot["connection"])
        if snapshot["dependencies"] and snapshot["dependencies"] != previous.get("dependencies"):
            self._append_google_calendar_event(snapshot["dependencies"])
        if snapshot["last_error"] and snapshot["last_error"] != previous.get("last_error"):
            self._append_google_calendar_event("Warning: " + snapshot["last_error"])
        if (
            snapshot["last_successful_at"]
            and snapshot["last_successful_at"] != previous.get("last_successful_at")
        ):
            self._append_google_calendar_event(
                "Last successful sync: " + self._calendar_format_sync_time(snapshot["last_successful_at"])
            )
        self.state.google_calendar_status_snapshot = snapshot

    def _google_calendar_complete_operation(self, result: Any) -> None:
        message = "Google Calendar operation complete"
        if isinstance(result, dict):
            message = str(result.get("message") or message)
            synced_at = str(result.get("last_successful_sync_at") or "")
            if synced_at:
                self.state.calendar_last_successful_sync_at = synced_at
                self.state.calendar_refresh_error = ""
        self.state.google_calendar_status = message
        self.state.google_calendar_error = ""
        self._append_google_calendar_event(message)
        self.state.google_calendar_operation = ""
        self.state.google_calendar_task = None

    def _google_calendar_fail_operation(self, exc: BaseException) -> None:
        self.state.google_calendar_error = f"{type(exc).__name__}: {exc}"
        self.state.google_calendar_status = ""
        self._append_google_calendar_event("Error: " + self.state.google_calendar_error)
        self.state.google_calendar_operation = ""
        self.state.google_calendar_task = None

    async def _google_calendar_await_operation(self, awaitable: Any) -> None:
        try:
            result = await awaitable
            self._google_calendar_complete_operation(result)
        except asyncio.CancelledError:
            self.state.google_calendar_operation = ""
            self.state.google_calendar_task = None
            raise
        except Exception as exc:
            self._google_calendar_fail_operation(exc)

    def _begin_google_calendar_operation(self, operation: str) -> bool:
        if self.state.google_calendar_task is not None and not self.state.google_calendar_task.done():
            return False
        normalized = str(operation or "").strip().lower()
        self.state.google_calendar_operation = normalized
        self.state.google_calendar_error = ""
        labels = {"connect": "Connecting Google Calendar…", "disconnect": "Disconnecting…", "refresh": "Synchronizing…"}
        self.state.google_calendar_status = labels.get(normalized, "Working…")
        self._append_google_calendar_event(self.state.google_calendar_status)
        try:
            if normalized == "connect":
                result = self.services.connect_google_calendar()
            elif normalized == "disconnect":
                result = self.services.disconnect_google_calendar()
            elif normalized == "refresh":
                result = self.services.refresh_calendar()
            else:
                raise ValueError(f"Unknown Google Calendar operation: {operation}")
            if inspect.isawaitable(result):
                try:
                    self.state.google_calendar_task = asyncio.create_task(
                        self._google_calendar_await_operation(result),
                    )
                except RuntimeError:
                    self._google_calendar_complete_operation(asyncio.run(result))
            else:
                self._google_calendar_complete_operation(result)
            return True
        except Exception as exc:
            self._google_calendar_fail_operation(exc)
            return False

    def _append_vault_connector_event(self, source_type: str, message: Any) -> None:
        clean = " ".join(str(message or "").split()).strip()
        if not clean:
            return
        entries = self.state.vault_connector_events.setdefault(str(source_type), [])
        if entries and entries[-1].split("] ", 1)[-1] == clean:
            return
        stamp = datetime.now().astimezone().strftime("%Y-%m-%d %H:%M:%S")
        entries.append(f"[{stamp}] {clean}")
        del entries[:-CONNECTOR_MAX_STATUS_EVENTS]

    def _vault_connector_events_text(self, source_type: str, status: dict[str, Any]) -> str:
        """Combine timestamped UI and connector events without duplicating adjacent messages."""
        rows: list[str] = []
        for entry in self.state.vault_connector_events.get(str(source_type), []):
            clean = str(entry or "").strip()
            if clean and (not rows or rows[-1] != clean):
                rows.append(clean)
        for entry in status.get("events", []) if isinstance(status.get("events"), list) else []:
            clean = str(entry or "").strip()
            if clean and (not rows or rows[-1].split("] ", 1)[-1] != clean.split("] ", 1)[-1]):
                rows.append(clean)
        message = str(status.get("message") or "").strip()
        if message and (not rows or rows[-1].split("] ", 1)[-1] != message):
            stamp = datetime.now().astimezone().strftime("%Y-%m-%d %H:%M:%S")
            rows.append(f"[{stamp}] {message}")
        error = str(status.get("last_error") or "").strip()
        if error and (not rows or error not in rows[-1]):
            stamp = datetime.now().astimezone().strftime("%Y-%m-%d %H:%M:%S")
            rows.append(f"[{stamp}] Error: {error}")
        return "\n".join(rows[-CONNECTOR_MAX_STATUS_EVENTS:])

    async def _await_vault_connector_operation(
        self, source_type: str, operation: str, task: asyncio.Task,
    ) -> None:
        try:
            result = await task
            message = "Complete"
            if isinstance(result, dict):
                if operation == "sync":
                    message = f"Complete — {int(result.get('processed') or 0)} records processed"
                elif operation == "connect":
                    message = "Connected"
                elif operation == "disconnect":
                    message = "Disconnected"
                elif operation == "test":
                    message = "Connection test succeeded"
            self._append_vault_connector_event(source_type, message)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            self._append_vault_connector_event(source_type, f"Error: {type(exc).__name__}: {exc}")
        finally:
            self.state.vault_connector_tasks.pop(source_type, None)
            self.state.vault_connector_operations.pop(source_type, None)

    def _begin_vault_connector_operation(self, source_type: str, operation: str) -> bool:
        source_type = str(source_type or "").strip().lower()
        running = self.state.vault_connector_tasks.get(source_type)
        if running is not None and not running.done():
            return False
        labels = {
            "connect": "Connecting...", "test": "Testing connection...",
            "sync": "Synchronizing...", "disconnect": "Disconnecting...",
        }
        self.state.vault_connector_operations[source_type] = operation
        self._append_vault_connector_event(source_type, labels.get(operation, "Working..."))
        try:
            manager_task = self.services.start_vault_connector_operation(source_type, operation)
            wrapper = asyncio.create_task(
                self._await_vault_connector_operation(source_type, operation, manager_task)
            )
            self.state.vault_connector_tasks[source_type] = wrapper
            return True
        except Exception as exc:
            self.state.vault_connector_operations.pop(source_type, None)
            self._append_vault_connector_event(source_type, f"Error: {type(exc).__name__}: {exc}")
            return False

    def _calendar_complete_refresh(self, result: Any) -> None:
        timestamp = now_iso()
        message = "Calendar refreshed"
        if isinstance(result, dict):
            timestamp = str(result.get("last_successful_sync_at") or result.get("synced_at") or timestamp)
            message = str(result.get("message") or message)
        self.state.calendar_last_successful_sync_at = timestamp
        self.state.calendar_refresh_status = message
        self.state.calendar_refresh_error = ""
        self.state.calendar_refresh_in_progress = False
        self.state.calendar_refresh_task = None

    def _calendar_fail_refresh(self, exc: BaseException) -> None:
        self.state.calendar_refresh_error = f"{type(exc).__name__}: {exc}"
        self.state.calendar_refresh_status = ""
        self.state.calendar_refresh_in_progress = False
        self.state.calendar_refresh_task = None

    async def _calendar_await_refresh(self, awaitable: Any) -> None:
        try:
            result = await awaitable
            self._calendar_complete_refresh(result)
        except asyncio.CancelledError:
            self.state.calendar_refresh_in_progress = False
            self.state.calendar_refresh_task = None
            raise
        except Exception as exc:
            self._calendar_fail_refresh(exc)

    def _begin_calendar_refresh(self) -> bool:
        if self.state.calendar_refresh_in_progress:
            return False
        self.state.calendar_refresh_in_progress = True
        self.state.calendar_refresh_error = ""
        self.state.calendar_refresh_status = "Refreshing Calendar…"
        try:
            result = self.services.refresh_calendar()
            if inspect.isawaitable(result):
                try:
                    self.state.calendar_refresh_task = asyncio.create_task(
                        self._calendar_await_refresh(result),
                    )
                except RuntimeError:
                    self._calendar_complete_refresh(asyncio.run(result))
            else:
                self._calendar_complete_refresh(result)
            return True
        except Exception as exc:
            self._calendar_fail_refresh(exc)
            return False

    def _calendar_begin_item_drag(self, item: dict[str, Any], origin: str) -> None:
        self.state.calendar_drag_item_id = str(item.get("item_id") or "")
        self.state.calendar_drag_origin = str(origin or "")
        self.state.calendar_drag_start_x = int(self.state.input.mouse_x)
        self.state.calendar_drag_start_y = int(self.state.input.mouse_y)
        self.state.calendar_drag_active = False
        self.state.calendar_drag_title = str(item.get("title") or "Item")

    def _calendar_clear_item_drag(self) -> None:
        self.state.calendar_drag_item_id = None
        self.state.calendar_drag_origin = None
        self.state.calendar_drag_active = False
        self.state.calendar_drag_title = ""

    def _calendar_update_item_drag(self) -> None:
        item_id = str(self.state.calendar_drag_item_id or "")
        if not item_id:
            return
        if self.state.input.mouse_down and not self.state.calendar_drag_active:
            dx = self.state.input.mouse_x - self.state.calendar_drag_start_x
            dy = self.state.input.mouse_y - self.state.calendar_drag_start_y
            if math.hypot(dx, dy) >= CALENDAR_DRAG_START_DISTANCE_PX:
                self.state.calendar_drag_active = True
        if not self.state.input.mouse_released:
            return
        try:
            if not self.state.calendar_drag_active:
                return
            calendar = self._calendar_store()
            mx, my = self.state.input.mouse_x, self.state.input.mouse_y
            linked_event_id = next((
                event_id for event_id, target in reversed(list(self.state.calendar_event_drop_targets.items()))
                if point_in_rect(mx, my, target)
            ), "")
            if linked_event_id:
                saved = calendar.link_event(item_id, linked_event_id)
                self.state.calendar_refresh_status = f"Linked Item to {calendar.get_event(linked_event_id).get('title') or 'Event'}"
            elif self.state.calendar_backlog_drop_rect and point_in_rect(mx, my, self.state.calendar_backlog_drop_rect):
                saved = calendar.move_item_to_backlog(item_id)
                self.state.calendar_refresh_status = "Moved Item to Backlog"
            else:
                timeline_target = next((
                    (day_value, target)
                    for day_value, target in self.state.calendar_timeline_content_targets.items()
                    if point_in_rect(mx, my, target)
                ), None)
                if timeline_target is None and self.state.calendar_timeline_content_rect and point_in_rect(
                    mx, my, self.state.calendar_timeline_content_rect,
                ):
                    timeline_target = (self.state.calendar_selected_date, self.state.calendar_timeline_content_rect)
                if timeline_target is None:
                    return
                target_day, content = timeline_target
                scroll_key = "calendar.week.timeline" if self.state.calendar_timeline_content_targets else "calendar.timeline"
                scroll_y = int(self.state.scroll.get(scroll_key, 0))
                minute = calendar_minutes_from_timeline_y(my - content.y + scroll_y)
                current = calendar.get_item(item_id)
                existing_duration = current.get("duration_minutes")
                saved = calendar.schedule_item(
                    item_id,
                    target_day,
                    calendar_minutes_to_time(minute),
                    existing_duration if isinstance(existing_duration, int) else None,
                )
                self.state.calendar_refresh_status = f"Scheduled Item at {saved['scheduled_start_time']}"
            self._calendar_select_object("item", str(saved["item_id"]))
        except Exception as exc:
            self.state.add_toast("Item move failed", f"{type(exc).__name__}: {exc}", "error")
        finally:
            self._calendar_clear_item_drag()

    def _draw_calendar_drag_overlay(self) -> None:
        if not self.state.calendar_drag_active or not self.state.calendar_drag_item_id:
            return
        width = min(300, max(150, self.widgets._text_width(self.state.calendar_drag_title) + 38))
        rect = Rect(self.state.input.mouse_x + 14, self.state.input.mouse_y + 14, width, 44)
        self.r.draw_card(
            rect, radius=12, fill=theme_alpha(Palette.panel3, 240),
            border=theme_alpha(Palette.accent, 190), overlay=True,
        )
        self.widgets.clipped_text(
            rect.inset(10), self.state.calendar_drag_title, Palette.text, overlay=True,
        )

    def _calendar_draw_wrapped_text(
        self,
        rect: Rect,
        text: str,
        color: Color = Palette.text,
        *,
        max_lines: int | None = None,
        overlay: bool = False,
    ) -> int:
        """Draw measured wrapped text and return the consumed height."""
        rows = self.widgets._wrap_display_rows(str(text or ""), max(1, rect.w))
        if max_lines is not None:
            rows = rows[: max(0, int(max_lines))]
        line_h = max(1, self.f.line_h)
        self.r.push_clip(rect)
        for index, row in enumerate(rows):
            y = rect.y + index * line_h
            if y + line_h > rect.y + rect.h:
                break
            self.r.draw_text(str(row.text), rect.x, y, color, overlay=overlay)
        self.r.pop_clip()
        return min(rect.h, len(rows) * line_h)

    def _calendar_today(self) -> date:
        return datetime.now(self._calendar_store().display_timezone()).date()

    def _calendar_format_sync_time(self, value: str) -> str:
        if not str(value or "").strip():
            return "Never synchronized"
        try:
            parsed = _parse_iso_datetime(value, field_name="Calendar sync time")
            if parsed.tzinfo is None:
                parsed = parsed.replace(tzinfo=timezone.utc)
            return parsed.astimezone(self._calendar_store().display_timezone()).strftime("%b %d, %I:%M %p").replace(" 0", " ")
        except Exception:
            return str(value)

    def _calendar_event_time_label(self, event: dict[str, Any]) -> str:
        if bool(event.get("all_day")):
            return "All day"
        try:
            zone = self._calendar_store().display_timezone()
            start = _parse_iso_datetime(event.get("start"), field_name="Event start")
            end = _parse_iso_datetime(event.get("end"), field_name="Event end")
            if start.tzinfo is None:
                start = start.replace(tzinfo=timezone.utc)
            if end.tzinfo is None:
                end = end.replace(tzinfo=timezone.utc)
            start = start.astimezone(zone)
            end = end.astimezone(zone)
            return f"{start.strftime('%H%M')}–{end.strftime('%H%M')}"
        except Exception:
            return "Time unavailable"

    def _draw_calendar_backlog_rail(self, rect: Rect, backlog: list[dict[str, Any]]) -> None:
        hover = self.widgets._can_receive_pointer("calendar.backlog.rail") and point_in_rect(
            self.state.input.mouse_x, self.state.input.mouse_y, rect,
        )
        drag_hover = bool(
            self.state.calendar_drag_active
            and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, rect)
        )
        fill = Palette.hover if hover else Palette.panel
        border = Palette.accent if drag_hover else Palette.border
        self.r.draw_card(rect, radius=16, fill=fill, border=border)
        self.state.calendar_backlog_drop_rect = rect
        expanded = bool(self.state.calendar_backlog_expanded)
        action = "Collapse" if expanded else "Expand"
        self.widgets._queue_tooltip(
            "calendar.backlog.rail", rect,
            f"{action} Backlog ({len(backlog)} Item{'s' if len(backlog) != 1 else ''})",
        )
        if hover:
            self.state.requested_cursor = "hand"
        if hover and self.state.input.mouse_pressed and not self.state.input.mouse_consumed:
            self.state.calendar_backlog_expanded = not expanded
            self.state.input.mouse_consumed = True

        layout = calendar_backlog_rail_layout(rect, line_h=self.f.line_h)
        chevron = "<" if expanded else ">"
        self.widgets.clipped_text(layout.top_chevron, chevron, Palette.muted2, align="center")
        label = "BACKLOG"
        step = max(10, min(max(1, self.f.line_h - 1), max(10, layout.label.h // len(label))))
        label_h = step * len(label)
        label_y = layout.label.y + max(0, (layout.label.h - label_h) // 2)
        for index, ch in enumerate(label):
            ch_rect = Rect(rect.x, label_y + index * step, rect.w, max(step, self.f.line_h))
            self.widgets.clipped_text(ch_rect, ch, Palette.muted, align="center")
        self.widgets.clipped_text(layout.bottom_chevron, chevron, Palette.muted2, align="center")

    def _draw_calendar_backlog_panel(
        self,
        rect: Rect,
        backlog: list[dict[str, Any]],
        *,
        owns_drop_target: bool = True,
    ) -> None:
        self.r.draw_card(rect, radius=18, fill=Palette.panel, border=Palette.border)
        if owns_drop_target:
            self.state.calendar_backlog_drop_rect = rect
        inner = rect.inset(12)
        header_h = 82
        close_rect = Rect(inner.x + inner.w - 32, inner.y, 32, 28)
        badge_rect = Rect(close_rect.x - 46, inner.y + 1, 38, 25)
        title_rect = Rect(inner.x, inner.y, max(1, badge_rect.x - inner.x - 8), 28)
        backlog_title_font = getattr(self.widgets, "bold_font", self.f)
        self.r.draw_text_run_font(backlog_title_font, "BACKLOG", title_rect.x, title_rect.y, Palette.white)
        self.widgets._queue_tooltip("calendar.backlog.title", title_rect, "Backlog Items")
        self.widgets.badge(badge_rect, str(len(backlog)), Palette.accent)
        if self.widgets.button(
            "calendar.backlog.close", close_rect, "X", tooltip="Collapse Backlog",
        ):
            self.state.calendar_backlog_expanded = False
        if self.widgets.button(
            "calendar.backlog.new", Rect(inner.x, inner.y + 40, inner.w, 34), "New Backlog Item", primary=True,
        ):
            self._open_item_editor()

        body = Rect(inner.x, inner.y + header_h, inner.w, max(1, inner.h - header_h))
        groups = [(priority, [item for item in backlog if item.get("priority") == priority]) for priority in ITEM_PRIORITIES]
        row_h = 66
        group_h = max(34, self.f.line_h + 10)
        empty_message_h = 62 if not backlog else 0
        total_h = sum(group_h + len(items) * row_h + (8 if items else 0) for _priority, items in groups) + empty_message_h
        scroll_id = "calendar.backlog.list"
        scroll_y = int(self.state.scroll.get(scroll_id, 0))
        if self.widgets._can_receive_pointer(scroll_id) and point_in_rect(
            self.state.input.mouse_x, self.state.input.mouse_y, body,
        ) and self.state.input.wheel_y:
            scroll_y -= int(self.state.input.wheel_y) * 48
            self.state.input.mouse_consumed = True
        scroll_y = int(clamp(scroll_y, 0, max(0, total_h - body.h)))
        scroll_y = self.widgets._scrollbar_input(scroll_id, body, scroll_y, total_h)
        self.state.scroll[scroll_id] = scroll_y
        self.r.push_clip(body)
        y = body.y - scroll_y
        for priority, items in groups:
            color = self._calendar_priority_color(priority)
            self.widgets.badge(Rect(body.x + 4, y + 2, 42, 24), priority, color)
            self.widgets.clipped_text(
                Rect(body.x + 54, y, max(1, body.w - 70), 28),
                f"{len(items)} Item{'s' if len(items) != 1 else ''}", Palette.muted2,
            )
            y += group_h
            for item in items:
                item_id = str(item.get("item_id") or "")
                row = Rect(body.x + 2, y + 3, max(1, body.w - 14), row_h - 6)
                hovered = self.widgets._can_receive_pointer(f"calendar.backlog.item.{item_id}") and point_in_rect(
                    self.state.input.mouse_x, self.state.input.mouse_y, row,
                )
                selected = self.state.calendar_selected_kind == "item" and self.state.calendar_selected_id == item_id
                self.r.draw_card(
                    row, radius=12,
                    fill=Palette.selected if selected else (Palette.hover if hovered else Palette.panel2),
                    border=theme_alpha(self._calendar_priority_color(str(item.get("priority") or "P3")), 150),
                )
                self.widgets.clipped_text(
                    Rect(row.x + 10, row.y + 5, max(1, row.w - 20), 24),
                    str(item.get("title") or "Untitled Item"), Palette.text,
                    tooltip=str(item.get("title") or "Untitled Item"),
                )
                status = str(item.get("status") or "Action")
                self.widgets.badge(
                    Rect(row.x + 10, row.y + row.h - 27, min(94, max(52, self.widgets._text_width(status) + 18)), 22),
                    status, self._calendar_item_status_color(status),
                )
                if item.get("linked_event_id"):
                    self.widgets.clipped_text(
                        Rect(row.x + row.w - 84, row.y + row.h - 27, 74, 22), "Linked", Palette.accent2, align="right",
                    )
                if hovered and self.state.input.mouse_pressed:
                    self._calendar_select_object("item", item_id)
                    self._calendar_begin_item_drag(item, "backlog")
                    self.state.input.mouse_consumed = True
                y += row_h
            if items:
                y += 8
        if not backlog:
            self.widgets.clipped_text(
                Rect(body.x + 10, y + 8, max(1, body.w - 20), 54),
                "No Items are waiting in the Backlog.", Palette.muted2,
            )
        self.r.pop_clip()
        self.widgets._scrollbar_draw(scroll_id, body, scroll_y, total_h)

    def _calendar_event_tooltip(self, event: dict[str, Any]) -> str:
        """Return complete Event details for the card tooltip."""
        title = str(event.get("title") or "Untitled Event")
        lines = [title, f"Time: {self._calendar_event_time_label(event)}"]
        calendar_name = str(event.get("calendar_name") or "").strip()
        if calendar_name:
            lines.append(f"Calendar: {calendar_name}")
        status = str(event.get("status") or "unknown").strip()
        lines.append(f"Source status: {status}")
        location = str(event.get("location") or "").strip()
        if location:
            lines.append(f"Location: {location}")
        organizer = event.get("organizer") if isinstance(event.get("organizer"), dict) else {}
        organizer_text = " · ".join(
            value for value in (
                str(organizer.get("name") or "").strip(),
                str(organizer.get("email") or "").strip(),
            ) if value
        )
        if organizer_text:
            lines.append(f"Organizer: {organizer_text}")
        attendees = event.get("attendees") if isinstance(event.get("attendees"), list) else []
        attendee_labels: list[str] = []
        for row in attendees:
            if not isinstance(row, dict):
                continue
            label = " · ".join(
                value for value in (
                    str(row.get("name") or "").strip(),
                    str(row.get("email") or "").strip(),
                ) if value
            )
            if label:
                attendee_labels.append(label)
        if attendee_labels:
            lines.append("Participants: " + ", ".join(attendee_labels))
        description = str(event.get("description") or "").strip()
        if description:
            lines.append("Description: " + description)
        meeting_url = str(event.get("meeting_url") or "").strip()
        if meeting_url:
            lines.append("Meeting: " + meeting_url)
        try:
            linked_items = self._calendar_store().list_items_linked_to_event(str(event.get("event_id") or ""))
        except Exception:
            linked_items = []
        if linked_items:
            status_counts = {status_name: 0 for status_name in ITEM_STATUSES}
            linked_item_labels: list[str] = []
            attachment_labels: list[str] = []
            seen_attachments: set[str] = set()
            for linked_item in linked_items:
                item_status = str(linked_item.get("status") or "Action")
                if item_status in status_counts:
                    status_counts[item_status] += 1
                linked_item_labels.append(
                    f"{str(linked_item.get('title') or 'Untitled Item')} ({item_status})"
                )
                for raw_path in linked_item.get("attachments") or []:
                    attachment_path = str(raw_path or "").strip()
                    if attachment_path and attachment_path not in seen_attachments:
                        seen_attachments.add(attachment_path)
                        attachment_labels.append(Path(attachment_path).name or attachment_path)
            preparation = ", ".join(
                f"{count} {status_name}" for status_name, count in status_counts.items() if count
            )
            lines.append("Linked Items: " + "; ".join(linked_item_labels))
            if attachment_labels:
                lines.append("Related attachments: " + ", ".join(attachment_labels))
        else:
            preparation = "No linked preparation Items"
        lines.append("Preparation status: " + preparation)
        lines.append("Meeting capture: Not captured")
        return "\n".join(lines)

    def _calendar_item_tooltip(self, item: dict[str, Any]) -> str:
        lines = [str(item.get("title") or "Untitled Item")]
        status = str(item.get("status") or "Action")
        priority = str(item.get("priority") or "P3")
        lines.append(f"Status: {status}")
        lines.append(f"Priority: {priority}")
        scheduled_date = str(item.get("scheduled_date") or "").strip()
        scheduled_time = str(item.get("scheduled_start_time") or "").strip()
        if scheduled_date or scheduled_time:
            lines.append("Schedule: " + " ".join(value for value in (scheduled_date, scheduled_time) if value))
        duration = item.get("duration_minutes")
        if duration not in (None, ""):
            lines.append(f"Duration: {int(duration)} minutes")
        description = str(item.get("description") or "").strip()
        if description:
            lines.append("Description: " + description)
        if item.get("linked_event_id"):
            lines.append("Linked to a Calendar Event")
        agent_count = len([value for value in item.get("linked_agent_ids") or [] if str(value or "")])
        if agent_count:
            lines.append(f"Linked agents: {agent_count}")
        return "\n".join(lines)

    def _calendar_event_context_items(self, event: dict[str, Any]) -> list[dict[str, Any]]:
        event_id = str(event.get("event_id") or "")
        original_url = str(event.get("original_url") or "").strip()
        return [{
            "action": "open_original_event",
            "label": "Open original calendar event",
            "enabled": bool(original_url),
            "payload": {"event_id": event_id, "url": original_url},
        }]

    def _calendar_consume_event_context_action(self) -> None:
        action = self.widgets.consume_context_action("calendar.week.event.actions")
        if not action:
            return
        payload = action.get("payload") if isinstance(action.get("payload"), dict) else {}
        if str(action.get("action") or "") != "open_original_event":
            return
        url = str(payload.get("url") or "").strip()
        if not url:
            event_id = str(payload.get("event_id") or "")
            try:
                event = self._calendar_store().get_event(event_id)
                url = str(event.get("original_url") or "").strip()
            except Exception:
                url = ""
        if url:
            try:
                self._open_link(url)
            except Exception as exc:
                self.state.add_toast("Calendar link could not be opened", f"{type(exc).__name__}: {exc}", "error")

    def _draw_calendar_week_header(self, rect: Rect) -> None:
        self.r.draw_card(rect, radius=16, fill=Palette.panel)
        inner = rect.inset(10)
        row_h = min(34, max(28, inner.h))
        gap = 6
        picker_w = min(240, max(154, inner.w // 5))
        previous_rect = Rect(inner.x, inner.y, 34, row_h)
        picker_rect = Rect(previous_rect.x + previous_rect.w + gap, inner.y, picker_w, row_h)
        today_w = 78
        today_rect = Rect(picker_rect.x + picker_rect.w + gap, inner.y, today_w, row_h)
        next_rect = Rect(today_rect.x + today_rect.w + gap, inner.y, 34, row_h)
        if self.widgets.button("calendar.week.previous", previous_rect, "<", tooltip="Previous week"):
            self._calendar_shift_selected_date(-7)
        picked_date = self.widgets.date_picker(
            "calendar.week.date", picker_rect, self.state.calendar_selected_date,
            reference_date=self._calendar_today(),
        )
        if picked_date != self.state.calendar_selected_date:
            self._calendar_set_selected_date(picked_date)
        if self.widgets.button("calendar.week.today", today_rect, "Today"):
            self._calendar_set_selected_date(self._calendar_today().isoformat())
        if self.widgets.button("calendar.week.next", next_rect, ">", tooltip="Next week"):
            self._calendar_shift_selected_date(7)

        new_w = 132
        refresh_w = 112
        refresh_rect = Rect(inner.x + inner.w - refresh_w, inner.y, refresh_w, row_h)
        new_rect = Rect(refresh_rect.x - gap - new_w, inner.y, new_w, row_h)
        if self.widgets.button("calendar.week.new_item", new_rect, "New Item", primary=True):
            self._open_item_editor(
                scheduled_date=self.state.calendar_selected_date, scheduled_start_time="09:00",
            )
        refresh_label = "Refreshing…" if self.state.calendar_refresh_in_progress else "Refresh"
        if self.widgets.button(
            "calendar.week.refresh", refresh_rect, refresh_label,
            enabled=not self.state.calendar_refresh_in_progress,
            tooltip="Synchronize read-only external Calendar Events",
        ):
            self._begin_calendar_refresh()

        title_x = next_rect.x + next_rect.w + 12
        title_w = max(1, new_rect.x - title_x - 12)
        title = calendar_week_title(self.state.calendar_selected_date)
        title_rect = Rect(title_x, inner.y, title_w, row_h)
        title_font = getattr(self.widgets, "bold_font", self.f)
        title_display = self.widgets._truncate_to_width(title.upper(), title_rect.w)
        title_draw_x = title_rect.x + max(0, (title_rect.w - title_font.measure_text(title_display)) // 2)
        title_draw_y = centered_visible_text_y(title_font, title_display, title_rect.y, title_rect.h)
        self.r.push_clip(title_rect)
        self.r.draw_text_run_font(title_font, title_display, title_draw_x, title_draw_y, Palette.white)
        self.r.pop_clip()
        self.widgets._queue_tooltip(
            "calendar.week.title", title_rect, title,
            visible_text=title_display, visible_text_fully_shown=(title_display == title.upper()),
        )

    def _draw_calendar_week_day(
        self,
        rect: Rect,
        day_value: str,
        events: list[dict[str, Any]],
        items: list[dict[str, Any]],
        *,
        draw_scrollbar: bool = False,
    ) -> None:
        """Draw one non-selectable day with a fixed all-day row and 24-hour grid."""
        self.r.draw_card(rect, radius=14, fill=Palette.panel, border=Palette.border)
        inner = rect.inset(5)
        resolved = date.fromisoformat(day_value)
        line_box_h = max(22, self.f.line_h + 4)
        header = Rect(inner.x, inner.y, inner.w, line_box_h * 2 + 4)
        self._draw_card_title_text(
            f"calendar.week.header_title.{day_value}",
            Rect(header.x + 4, header.y, max(1, header.w - 8), line_box_h),
            resolved.strftime("%A"),
            tooltip=resolved.strftime("%A, %B %d, %Y").replace(" 0", " "),
            align="center",
        )
        self.widgets.clipped_text(
            Rect(header.x + 4, header.y + line_box_h, max(1, header.w - 8), line_box_h),
            resolved.strftime("%b %d").replace(" 0", " "), Palette.text, align="center",
        )

        all_day_events = [event for event in events if bool(event.get("all_day"))]
        timed_events = [event for event in events if not bool(event.get("all_day"))]
        label_h = max(20, self.f.line_h + 4)
        event_h = max(34, self.f.line_h + 12)
        strip_h = max(CALENDAR_ALL_DAY_ROW_H, label_h + event_h + 10)
        strip = Rect(inner.x, header.y + header.h + 4, inner.w, strip_h)
        self.r.draw_card(
            strip, radius=9,
            fill=theme_mix(Palette.panel2, Palette.white, 0.035),
            border=theme_alpha(Palette.border, 155),
        )
        self._draw_card_title_text(
            f"calendar.week.all_day_title.{day_value}",
            Rect(strip.x + 5, strip.y + 2, max(1, strip.w - 10), label_h),
            "ALL DAY", align="center",
        )
        separator_y = strip.y + label_h + 4
        self.r.draw_line(
            strip.x + 5, separator_y, strip.x + strip.w - 5, separator_y,
            theme_alpha(Palette.border, 125),
        )
        event_area = Rect(
            strip.x + 4, separator_y + 4, max(1, strip.w - 8),
            max(1, strip.y + strip.h - (separator_y + 8)),
        )
        if all_day_events:
            card_area = Rect(event_area.x, event_area.y, event_area.w, min(event_h, event_area.h))
            all_day_cards = calendar_all_day_card_rects(card_area, len(all_day_events))
            for event, row in zip(all_day_events[:len(all_day_cards)], all_day_cards):
                event_id = str(event.get("event_id") or "")
                widget_id = f"calendar.week.allday.{day_value}.{event_id}"
                hover = self.widgets._can_receive_pointer(widget_id) and point_in_rect(
                    self.state.input.mouse_x, self.state.input.mouse_y, row,
                )
                selected = self.state.calendar_selected_kind == "event" and self.state.calendar_selected_id == event_id
                cancelled = str(event.get("status") or "").lower() == "cancelled"
                fill, border = calendar_event_card_colors(
                    event, selected=selected, hovered=hover, cancelled=cancelled,
                )
                self.r.draw_card(row, radius=7, fill=fill, border=border)
                title_rect, _subtitle_rect = calendar_card_text_rects(row, line_h=self.f.line_h)
                self.widgets.clipped_text(
                    title_rect, str(event.get("title") or "Untitled Event"),
                    Palette.muted if cancelled else Palette.text,
                )
                self.state.calendar_event_drop_targets[event_id] = row
                if hover:
                    self.widgets._queue_tooltip(widget_id + ".tooltip", row, self._calendar_event_tooltip(event))
                if hover and self.state.input.right_pressed and not self.state.input.mouse_consumed:
                    self._calendar_select_object("event", event_id)
                    self.widgets.open_action_context_menu(
                        "calendar.week.event.actions", self._calendar_event_context_items(event),
                    )
                    self.state.input.mouse_consumed = True
                elif hover and self.state.input.mouse_pressed and not self.state.input.mouse_consumed:
                    self._calendar_select_object("event", event_id)
                    self.state.input.mouse_consumed = True
            overflow = len(all_day_events) - len(all_day_cards)
            if overflow > 0:
                self.widgets.badge(
                    Rect(strip.x + strip.w - 39, strip.y + 2, 34, 20),
                    f"+{overflow}", Palette.accent,
                )
        else:
            self.widgets.clipped_text(
                event_area, "No all-day events", Palette.muted2, align="center",
            )

        timeline_y = strip.y + strip.h + 4
        timeline = Rect(inner.x, timeline_y, inner.w, max(1, inner.y + inner.h - timeline_y))
        self._draw_calendar_timeline(
            timeline, timed_events, items, day_value=day_value, compact=True,
            draw_scrollbar=draw_scrollbar,
        )

    def _draw_calendar_week(
        self,
        rect: Rect,
        events_by_day: dict[str, list[dict[str, Any]]],
        items_by_day: dict[str, list[dict[str, Any]]],
    ) -> None:
        header_h = min(58, max(50, self.f.line_h + 24))
        header = Rect(rect.x, rect.y, rect.w, min(rect.h, header_h))
        self._draw_calendar_week_header(header)
        body_y = header.y + header.h + CALENDAR_COLUMN_GAP_PX
        body = Rect(rect.x, body_y, rect.w, max(1, rect.y + rect.h - body_y))
        day_gap = 6
        available = max(7, body.w - day_gap * 6)
        base = available // 7
        remainder = available % 7
        x = body.x
        for index, day_value in enumerate(calendar_week_dates(self.state.calendar_selected_date)):
            width = base + (1 if index < remainder else 0)
            day_rect = Rect(x, body.y, max(1, width), body.h)
            self._draw_calendar_week_day(
                day_rect, day_value,
                events_by_day.get(day_value, []), items_by_day.get(day_value, []),
                draw_scrollbar=index == 6,
            )
            x += width + day_gap
        self._calendar_consume_event_context_action()


    def _draw_calendar_timeline(
        self,
        rect: Rect,
        events: list[dict[str, Any]],
        items: list[dict[str, Any]],
        *,
        day_value: str | None = None,
        compact: bool = False,
        draw_scrollbar: bool = True,
    ) -> None:
        """Draw a scrollable 24-hour grid with left-to-right overlap lanes."""
        resolved_day = normalize_iso_date(
            day_value or self.state.calendar_selected_date, field_name="Calendar timeline date",
        )
        self.r.draw_card(rect, radius=10 if compact else 16, fill=Palette.panel)
        viewport = rect.inset(4 if compact else 7)
        label_w = min(CALENDAR_HOUR_LABEL_W, max(50, viewport.w // 4)) if compact else CALENDAR_HOUR_LABEL_W
        scrollbar_gutter = 12 if draw_scrollbar else 3
        content = Rect(
            viewport.x + label_w, viewport.y,
            max(1, viewport.w - label_w - scrollbar_gutter), viewport.h,
        )
        self.state.calendar_timeline_content_targets[resolved_day] = content
        if resolved_day == self.state.calendar_selected_date:
            self.state.calendar_timeline_content_rect = content
            self.state.calendar_timeline_drop_rect = content

        total_h = 24 * CALENDAR_TIMELINE_HOUR_PX
        scroll_id = "calendar.week.timeline" if compact else "calendar.timeline"
        scroll_y = int(self.state.scroll.get(
            scroll_id, CALENDAR_TIMELINE_DEFAULT_START_HOUR * CALENDAR_TIMELINE_HOUR_PX,
        ))
        if self.widgets._can_receive_pointer(scroll_id) and point_in_rect(
            self.state.input.mouse_x, self.state.input.mouse_y, viewport,
        ) and self.state.input.wheel_y:
            scroll_y -= int(self.state.input.wheel_y) * max(24, CALENDAR_TIMELINE_HOUR_PX // 2)
            self.state.input.mouse_consumed = True
        scroll_y = int(clamp(scroll_y, 0, max(0, total_h - viewport.h)))
        if draw_scrollbar:
            scroll_y = self.widgets._scrollbar_input(scroll_id, viewport, scroll_y, total_h)
        self.state.scroll[scroll_id] = scroll_y

        if self.state.calendar_drag_active and point_in_rect(
            self.state.input.mouse_x, self.state.input.mouse_y, content,
        ):
            self.r.draw_round_outline(content, 8, Palette.accent)

        def draw_dashed(y: int, color: Color, *, dash: int, gap: int) -> None:
            x = content.x
            limit = content.x + content.w
            while x < limit:
                self.r.draw_line(x, y, min(limit, x + dash), y, color)
                x += dash + gap

        self.r.push_clip(viewport)
        for hour in range(25):
            line_y = viewport.y + calendar_timeline_y_for_minutes(hour * 60) - scroll_y
            if line_y < viewport.y - self.f.line_h or line_y > viewport.y + viewport.h:
                continue
            if hour < 24:
                self.widgets.clipped_text(
                    calendar_hour_label_rect(viewport, line_y, line_h=self.f.line_h, label_w=label_w),
                    calendar_hour_label(hour), Palette.muted2, align="right",
                )
            draw_dashed(
                line_y, theme_alpha(Palette.border, 105 if hour < 24 else 70),
                dash=7, gap=5,
            )
        for half_hour in range(1, 48, 2):
            line_y = viewport.y + calendar_timeline_y_for_minutes(half_hour * 30) - scroll_y
            if viewport.y <= line_y <= viewport.y + viewport.h:
                draw_dashed(line_y, theme_alpha(Palette.border, 42), dash=3, gap=7)

        if resolved_day == self._calendar_today().isoformat():
            now_local = datetime.now(self._calendar_store().display_timezone())
            minute = now_local.hour * 60 + now_local.minute
            line_y = viewport.y + calendar_timeline_y_for_minutes(minute) - scroll_y
            if viewport.y <= line_y <= viewport.y + viewport.h:
                self.r.draw_line(content.x - 3, line_y, content.x + content.w, line_y, Palette.danger)
                self.r.draw_round_rect(Rect(content.x - 4, line_y - 3, 7, 7), 4, Palette.danger)

        event_by_id: dict[str, dict[str, Any]] = {}
        item_by_id: dict[str, dict[str, Any]] = {}
        raw_blocks: list[tuple[str, str, int, int]] = []
        for event in events:
            event_id = str(event.get("event_id") or "")
            if not event_id:
                continue
            try:
                start_min, end_min = self._calendar_event_minutes(event, resolved_day)
            except Exception:
                continue
            event_by_id[event_id] = event
            raw_blocks.append(("event", event_id, start_min, end_min))
        for item in items:
            item_id = str(item.get("item_id") or "")
            if not item_id:
                continue
            try:
                start_min = calendar_time_to_minutes(str(item.get("scheduled_start_time") or ""))
            except Exception:
                continue
            duration = max(1, int(item.get("duration_minutes") or DEFAULT_ITEM_DURATION_MINUTES))
            item_by_id[item_id] = item
            raw_blocks.append(("item", item_id, start_min, min(24 * 60, start_min + duration)))

        render_rows: list[dict[str, Any]] = []
        for block in calendar_timeline_lane_assignments(raw_blocks, max_lanes=6 if compact else 8):
            base_minimum_h = CALENDAR_EVENT_CARD_MIN_H if block.kind == "event" else CALENDAR_ITEM_CARD_MIN_H
            minimum_h = max(base_minimum_h, int(self.f.line_h) + (10 if compact else 16))
            top = viewport.y + calendar_timeline_y_for_minutes(block.start_minute) - scroll_y
            height = max(
                minimum_h,
                calendar_timeline_y_for_minutes(max(1, block.end_minute - block.start_minute)),
            )
            card = calendar_timeline_lane_rect(
                content, block, top=top, height=height, lane_gap=3 if compact else 5,
            )
            if card.y + card.h < viewport.y or card.y > viewport.y + viewport.h:
                continue
            visible = Rect(
                card.x, max(card.y, viewport.y), card.w,
                max(1, min(card.y + card.h, viewport.y + viewport.h) - max(card.y, viewport.y)),
            )
            render_rows.append({
                "block": block, "card": card, "visible": visible,
                "record": event_by_id.get(block.object_id) if block.kind == "event" else item_by_id.get(block.object_id),
            })

        # Cascading cards must be painted back-to-front by lane so later overlap
        # lanes sit above the wider base event, matching the familiar Google
        # Calendar visual model. Non-overlapping groups are separated vertically.
        render_rows.sort(key=lambda row: (
            int(row["block"].lane), int(row["block"].start_minute), int(row["block"].order),
        ))

        hovered_row: dict[str, Any] | None = None
        if not self.state.input.mouse_consumed:
            for row in reversed(render_rows):
                if point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, row["visible"]):
                    block = row["block"]
                    if self.widgets._can_receive_pointer(
                        f"calendar.timeline.{resolved_day}.{block.kind}.{block.object_id}"
                    ):
                        hovered_row = row
                    break

        for row in render_rows:
            block: CalendarTimelineBlockLayout = row["block"]
            card: Rect = row["card"]
            visible: Rect = row["visible"]
            record = row["record"] or {}
            hover = row is hovered_row
            title_rect, subtitle_rect = calendar_card_text_rects(card, line_h=self.f.line_h)
            widget_id = f"calendar.timeline.{resolved_day}.{block.kind}.{block.object_id}"
            if block.kind == "event":
                selected = self.state.calendar_selected_kind == "event" and self.state.calendar_selected_id == block.object_id
                cancelled = str(record.get("status") or "").lower() == "cancelled"
                event_drop_hover = bool(self.state.calendar_drag_active and hover)
                fill, border = calendar_event_card_colors(
                    record, selected=selected, hovered=hover, cancelled=cancelled,
                    drop_hover=event_drop_hover,
                )
                self.r.draw_card(
                    card, radius=7 if compact else 10, fill=fill, border=border,
                )
                self.widgets.clipped_text(
                    title_rect, str(record.get("title") or "Untitled Event"),
                    Palette.muted if cancelled else Palette.text,
                )
                self.state.calendar_event_drop_targets[block.object_id] = visible
                if hover:
                    self.widgets._queue_tooltip(widget_id + ".tooltip", visible, self._calendar_event_tooltip(record))
            else:
                selected = self.state.calendar_selected_kind == "item" and self.state.calendar_selected_id == block.object_id
                status = str(record.get("status") or "Action")
                priority = str(record.get("priority") or "P3")
                self.r.draw_card(
                    card, radius=7 if compact else 10,
                    fill=Palette.selected if selected else (
                        Palette.hover if hover else theme_alpha(self._calendar_item_status_color(status), 42)
                    ),
                    border=self._calendar_priority_color(priority),
                )
                self.widgets.clipped_text(
                    title_rect, str(record.get("title") or "Untitled Item"), Palette.text,
                )
                if subtitle_rect is not None and not compact:
                    self.widgets.clipped_text(subtitle_rect, f"{priority} · {status}", Palette.muted2)
                if hover:
                    self.widgets._queue_tooltip(widget_id + ".tooltip", visible, self._calendar_item_tooltip(record))

        if hovered_row is not None and self.state.input.right_pressed and not self.state.input.mouse_consumed:
            block = hovered_row["block"]
            record = hovered_row["record"] or {}
            self._calendar_select_object(block.kind, block.object_id)
            if block.kind == "event":
                self.widgets.open_action_context_menu(
                    "calendar.week.event.actions", self._calendar_event_context_items(record),
                )
            self.state.input.mouse_consumed = True
        elif hovered_row is not None and self.state.input.mouse_pressed and not self.state.input.mouse_consumed:
            block = hovered_row["block"]
            record = hovered_row["record"] or {}
            self._calendar_select_object(block.kind, block.object_id)
            if block.kind == "item":
                self._calendar_begin_item_drag(record, "timeline")
            self.state.input.mouse_consumed = True

        self.r.pop_clip()
        if draw_scrollbar:
            self.widgets._scrollbar_draw(scroll_id, viewport, scroll_y, total_h)

        if (
            hovered_row is None
            and self.widgets._can_receive_pointer(f"calendar.timeline.blank.{resolved_day}")
            and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, content)
            and self.state.input.mouse_pressed
            and int(self.state.input.mouse_clicks or 0) >= 2
        ):
            minute = calendar_minutes_from_timeline_y(self.state.input.mouse_y - content.y + scroll_y)
            self._open_item_editor(
                scheduled_date=resolved_day, scheduled_start_time=calendar_minutes_to_time(minute),
            )
            self.state.input.mouse_consumed = True


    def _draw_calendar_week_chat(self, rect: Rect) -> None:
        if self.state.calendar_week_chat_bound_date != calendar_week_start(self.state.calendar_selected_date).isoformat():
            self._calendar_sync_week_chat_selection(create=False)
        header_h = max(44, self.f.line_h + 20)
        stack = chat_stack_layout_for_rect(
            rect, header_height=header_h,
            composer_height=self.state.calendar_chat_composer_height,
        )
        if self.handle_composer_divider("calendar", rect, stack):
            stack = chat_stack_layout_for_rect(
                rect, header_height=header_h,
                composer_height=self.state.calendar_chat_composer_height,
            )
        header, body, composer = stack.header, stack.output, stack.composer
        self.state.composer_capture_rect = composer
        existing_captures = list(self.state.top_input_capture)
        self.state.top_input_capture = existing_captures + [
            {"rect": composer, "prefix": "composer."},
        ]
        if self.state.active_chat_id:
            turns = self._load_active_turns_cached()
            self.draw_chat_thread_header(
                header, turns, title_override=calendar_week_chat_title(self.state.calendar_selected_date),
            )
            self.draw_chat_view(body)
        else:
            self.r.draw_card(header, radius=14, fill=Palette.panel)
            week_title = calendar_week_chat_title(self.state.calendar_selected_date).upper()
            week_title_font = getattr(self.widgets, "bold_font", self.f)
            week_title_y = centered_visible_text_y(week_title_font, week_title, header.y, header.h)
            self.r.draw_text_run_font(week_title_font, week_title, header.x + 12, week_title_y, Palette.white)
            self.r.draw_card(body, radius=16, fill=Palette.panel2)
            week_start = calendar_week_start(self.state.calendar_selected_date)
            week_end = week_start + timedelta(days=6)
            message = (
                f"This is the Week Chat for {week_start.isoformat()} through {week_end.isoformat()}. "
                "It will be created when you send a message or attach a file. "
                "Use it to ask about the week, create or reschedule Items, and start agents."
            )
            self._calendar_draw_wrapped_text(body.inset(22), message, Palette.muted, max_lines=7)
        self.draw_message_composer(
            composer,
            ensure_active_chat=self._calendar_ensure_week_chat,
            placeholder="Ask about this week…  Ctrl/Cmd+Enter to send.",
        )
        self.state.top_input_capture = existing_captures


    def _calendar_agent_tasks_snapshot(self) -> list[dict[str, Any]]:
        now = time.monotonic()
        if now - float(self.state.calendar_agent_tasks_cache_at or 0.0) < 1.0:
            return self.state.calendar_agent_tasks_cache
        try:
            all_agents = self.services.agents.list_agents()
            all_chats = self.services.chats.list_chats_view(APP_SCOPE_ID)
            rows = calendar_agent_tasks_for_display(all_agents, all_chats)
        except Exception as exc:
            self.state.add_toast(
                "Calendar agent tasks unavailable", f"{type(exc).__name__}: {exc}", "error",
            )
            rows = self.state.calendar_agent_tasks_cache
        self.state.calendar_agent_tasks_cache = rows
        self.state.calendar_agent_tasks_cache_at = now
        return rows

    def _draw_calendar_agent_tasks(self, rect: Rect) -> None:
        """Draw Calendar-origin and PA Tasks with the shared Agent row behavior."""
        self.r.draw_card(rect, radius=18, fill=Palette.panel, border=Palette.border)
        inner = rect.inset(12)
        title_font = getattr(self.widgets, "bold_font", self.f)
        self.r.draw_text_run_font(title_font, "AGENT TASKS", inner.x, inner.y, Palette.white)
        agents = self._calendar_agent_tasks_snapshot()
        if agents:
            self.widgets.clipped_text(
                Rect(inner.x + inner.w - 44, inner.y, 44, self.f.line_h),
                str(len(agents)), Palette.muted2, align="right",
            )
        header_h = max(30, self.f.line_h + 8)
        body = Rect(inner.x, inner.y + header_h, inner.w, max(1, inner.h - header_h))
        if not agents:
            self.widgets.clipped_text(
                Rect(body.x + 8, body.y + 6, max(1, body.w - 16), max(34, self.f.line_h + 12)),
                "No PA or Calendar agent tasks yet", Palette.muted2,
            )
            return
        rows: list[dict[str, Any]] = []
        for agent in agents:
            agent_id = str(agent.get("agent_id") or "")
            status = str(agent.get("status") or "queued")
            rows.append({
                "id": agent_id,
                "title": str(agent.get("title") or "Background agent"),
                "origin": str(agent.get("calendar_origin") or "Calendar"),
                "progress": {
                    "label": self._agent_progress_text(agent),
                    "sort": int(agent.get("progress_percent") or (-1 if status == "queued" else 0)),
                    "color": self._agent_status_color(status),
                },
                "_tooltip": (lambda resolved=agent_id: self._agent_statistics_tooltip_for_id(resolved)),
                "_context_menu": self._agent_row_context_items(agent),
            })
        origin_w = min(102, max(76, inner.w // 4))
        progress_w = min(124, max(92, inner.w // 3))
        columns = [
            {"key": "title", "title": "Title", "min_width": 92},
            {"key": "origin", "title": "Origin", "width": origin_w},
            {"key": "progress", "title": "Progress", "width": progress_w, "sort_type": "number"},
        ]
        current_sort = self.state.table_sort.get("calendar.agent_tasks")
        if not isinstance(current_sort, tuple) or current_sort[0] not in {"title", "origin", "progress"}:
            self.state.table_sort["calendar.agent_tasks"] = ("progress", False)
        self.state.calendar_selected_agent_id, action = self.widgets.table_view(
            "calendar.agent_tasks", body, columns, rows,
            self.state.calendar_selected_agent_id, id_key="id",
            row_h=max(32, self.f.line_h + 10), double_click_action="view",
        )
        if action:
            self._handle_agent_row_action(action[0], action[1])


    def _calendar_handle_dividers(self, rect: Rect, layout: CalendarUILayout) -> bool:
        """Resize the right rail horizontally and its Week Chat/Agent Tasks split vertically."""
        inp = self.state.input
        width_hit = Rect(
            layout.chat_divider.x - CALENDAR_CHAT_DIVIDER_HOVER_HALF_PX,
            layout.chat_divider.y,
            layout.chat_divider.w + CALENDAR_CHAT_DIVIDER_HOVER_HALF_PX * 2,
            layout.chat_divider.h,
        )
        stack_hit = Rect(
            layout.right_stack_divider.x,
            layout.right_stack_divider.y - CALENDAR_RIGHT_STACK_DIVIDER_HOVER_HALF_PX,
            layout.right_stack_divider.w,
            layout.right_stack_divider.h + CALENDAR_RIGHT_STACK_DIVIDER_HOVER_HALF_PX * 2,
        )
        width_active = self.state.calendar_divider_dragging == "chat"
        stack_active = self.state.calendar_divider_dragging == "right_stack"
        width_hovered = point_in_rect(inp.mouse_x, inp.mouse_y, width_hit)
        stack_hovered = point_in_rect(inp.mouse_x, inp.mouse_y, stack_hit)
        if width_hovered or width_active:
            self.state.requested_cursor = "resize_x"
        elif stack_hovered or stack_active:
            self.state.requested_cursor = "resize_y"

        if inp.mouse_pressed and not inp.mouse_consumed and not (width_active or stack_active):
            if width_hovered:
                self.state.calendar_divider_dragging = "chat"
                width_active = True
                inp.mouse_consumed = True
            elif stack_hovered:
                self.state.calendar_divider_dragging = "right_stack"
                stack_active = True
                inp.mouse_consumed = True

        changed = False
        if width_active:
            if inp.mouse_down:
                requested = rect.x + rect.w - inp.mouse_x
                requested = int(clamp(requested, CALENDAR_CHAT_WIDTH_MIN, CALENDAR_CHAT_WIDTH_MAX))
                if requested != self.state.calendar_chat_width:
                    self.state.calendar_chat_width = requested
                    changed = True
                inp.mouse_consumed = True
            else:
                self.state.calendar_divider_dragging = ""
                width_active = False
        elif stack_active:
            if inp.mouse_down:
                available = max(1, layout.right_rail.h - CALENDAR_RIGHT_STACK_GAP_PX)
                requested_h = inp.mouse_y - layout.right_rail.y
                requested_fraction = float(clamp(
                    requested_h / available, CALENDAR_RIGHT_SPLIT_MIN, CALENDAR_RIGHT_SPLIT_MAX,
                ))
                if abs(requested_fraction - self.state.calendar_right_split_fraction) > 1e-6:
                    self.state.calendar_right_split_fraction = requested_fraction
                    changed = True
                inp.mouse_consumed = True
            else:
                self.state.calendar_divider_dragging = ""
                stack_active = False

        center_x = layout.chat_divider.x + layout.chat_divider.w // 2
        self.r.draw_rect(
            Rect(center_x, layout.chat_divider.y, 1, layout.chat_divider.h),
            Palette.accent if width_hovered or width_active else theme_alpha(Palette.border, 155),
        )
        center_y = layout.right_stack_divider.y + layout.right_stack_divider.h // 2
        self.r.draw_rect(
            Rect(layout.right_stack_divider.x, center_y, layout.right_stack_divider.w, 1),
            Palette.accent if stack_hovered or stack_active else theme_alpha(Palette.border, 155),
        )
        return changed


    def draw_calendar_panel(self, rect: Rect) -> None:
        """Draw the weekly Calendar, Week Chat, Agent Tasks, and Backlog."""
        self.r.draw_rect(rect, Palette.bg)
        self.state.calendar_backlog_expanded = bool(self.state.calendar_backlog_expanded)
        if self.state.calendar_week_chat_bound_date != calendar_week_start(self.state.calendar_selected_date).isoformat():
            self._calendar_sync_week_chat_selection(create=False)
        calendar = self._calendar_store()
        week_dates = calendar_week_dates(self.state.calendar_selected_date)
        events_by_day: dict[str, list[dict[str, Any]]] = {}
        items_by_day: dict[str, list[dict[str, Any]]] = {}
        try:
            calendar_colors = google_calendar_display_color_map(calendar.get_google_sync_state())
        except Exception:
            calendar_colors = {}
        try:
            for day_value in week_dates:
                day_events = calendar.list_events_for_date(day_value)
                for event in day_events:
                    calendar_id = str(event.get("external_calendar_id") or event.get("calendar_name") or "Google Calendar")
                    event["_display_color"] = calendar_colors.get(
                        calendar_id, default_google_calendar_display_color(calendar_id),
                    )
                events_by_day[day_value] = day_events
                items_by_day[day_value] = calendar.list_scheduled_items(day_value)
            backlog = calendar.list_backlog_items()
        except Exception as exc:
            self.state.add_toast(
                "Calendar data could not be loaded", f"{type(exc).__name__}: {exc}", "error",
            )
            events_by_day = {day_value: [] for day_value in week_dates}
            items_by_day = {day_value: [] for day_value in week_dates}
            backlog = []

        if self.state.calendar_selected_kind == "item" and self.state.calendar_selected_id:
            try:
                calendar.get_item(self.state.calendar_selected_id)
            except Exception:
                self._calendar_select_object("", "")
        elif self.state.calendar_selected_kind == "event" and self.state.calendar_selected_id:
            try:
                calendar.get_event(self.state.calendar_selected_id)
            except Exception:
                self._calendar_select_object("", "")

        layout = calendar_layout_for_rect(
            rect,
            backlog_expanded=self.state.calendar_backlog_expanded,
            chat_width=self.state.calendar_chat_width,
            right_split_fraction=self.state.calendar_right_split_fraction,
        )
        self._calendar_handle_dividers(rect, layout)
        self.state.calendar_event_drop_targets = {}
        self.state.calendar_backlog_drop_rect = None
        self.state.calendar_timeline_drop_rect = None
        self.state.calendar_timeline_content_rect = None
        self.state.calendar_timeline_content_targets = {}
        captures: list[dict[str, Any]] = []
        if layout.backlog_overlay is not None:
            captures.append({"rect": layout.backlog_overlay, "prefix": "calendar.backlog."})
        self.state.top_input_capture = captures

        if layout.backlog.w <= CALENDAR_BACKLOG_RAIL_W + 2:
            self._draw_calendar_backlog_rail(layout.backlog, backlog)
        else:
            self._draw_calendar_backlog_panel(layout.backlog, backlog, owns_drop_target=True)
        self._draw_calendar_week(layout.week, events_by_day, items_by_day)
        self._draw_calendar_week_chat(layout.week_chat)
        self._draw_calendar_agent_tasks(layout.agent_tasks)

        if layout.backlog_overlay is not None:
            self.r.draw_rect(rect, theme_alpha(Palette.black, 70))
            self._draw_calendar_backlog_panel(
                layout.backlog_overlay, backlog, owns_drop_target=True,
            )
            if (
                self.state.input.mouse_pressed
                and not point_in_rect(
                    self.state.input.mouse_x, self.state.input.mouse_y,
                    layout.backlog_overlay,
                )
                and not self.state.input.mouse_consumed
            ):
                self.state.calendar_backlog_expanded = False
                self.state.input.mouse_consumed = True

        self._calendar_update_item_drag()
        self._draw_calendar_drag_overlay()
        self.state.top_input_capture = []
        self.state.composer_capture_rect = None

    def _vault_status_snapshot(self) -> dict[str, dict[str, Any]]:
        statuses: dict[str, dict[str, Any]] = {}
        try:
            calendar_state = self._calendar_store().get_google_sync_state()
            account = calendar_state.get("connected_account") if isinstance(calendar_state.get("connected_account"), dict) else {}
            connected = bool(str(account.get("account_id") or account.get("email") or "").strip())
            statuses[GOOGLE_CALENDAR_SOURCE_TYPE] = {
                "configured": connected,
                "connected": connected,
                "operation_in_progress": bool(self.state.calendar_refresh_in_progress),
                "last_error": str(calendar_state.get("last_error") or ""),
            }
        except Exception:
            statuses[GOOGLE_CALENDAR_SOURCE_TYPE] = {}
        for source_type, connector in (
            (GOOGLE_DRIVE_SOURCE_TYPE, self.services.google_drive),
            (GMAIL_SOURCE_TYPE, self.services.gmail),
            (SLACK_SOURCE_TYPE, self.services.slack),
        ):
            try:
                statuses[source_type] = connector.get_status() if connector is not None else {}
            except Exception:
                statuses[source_type] = {}
        return statuses

    def _vault_controller(self) -> VaultUIController:
        query = self.services.vault_query
        if query is None:
            vault = self.services.vault or VaultStore(self.services.storage)
            self.services.vault = vault
            query = VaultQueryService(vault)
            self.services.vault_query = query
        now_mono = time.monotonic()
        if now_mono - float(self.state.vault_timezone_polled_at or 0.0) >= 1.0:
            try:
                config = self.services.storage.load_config()
                timezone_key = str(config.get("vault", {}).get("local_timezone") or VAULT_LOCAL_TIMEZONE_DEFAULT)
                if timezone_key != self.state.vault_timezone_key:
                    query.local_timezone = resolve_vault_timezone(timezone_key)
                    self.state.vault_timezone_key = timezone_key
                    if self.state.vault_controller is not None:
                        self.state.vault_controller.clear()
            except Exception:
                pass
            self.state.vault_timezone_polled_at = now_mono
        controller = self.state.vault_controller
        if controller is None or controller.query is not query:
            controller = VaultUIController(query, status_provider=self._vault_status_snapshot)
            self.state.vault_controller = controller
        elif controller.status_provider is None:
            controller.status_provider = self._vault_status_snapshot
        return controller

    def _vault_selection_key(self, source_type: str, source_id: str) -> str:
        return str(source_id or source_type or "google_calendar")

    def _vault_selected_id(self, source_type: str, source_id: str) -> str:
        return str(self.state.vault_selected_by_source.get(self._vault_selection_key(source_type, source_id), ""))

    def _vault_set_selected_id(self, source_type: str, source_id: str, selected_id: str) -> None:
        key = self._vault_selection_key(source_type, source_id)
        if selected_id:
            self.state.vault_selected_by_source[key] = str(selected_id)
        else:
            self.state.vault_selected_by_source.pop(key, None)

    def _vault_refresh_snapshot(self, *, force_search: bool = False) -> dict[str, Any]:
        now_mono = time.monotonic()
        pending_search = self.state.vault_search_text != self.state.vault_applied_search_text
        if pending_search and (
            force_search
            or now_mono - float(self.state.vault_search_changed_at or 0.0) >= VAULT_SEARCH_DEBOUNCE_SECONDS
        ):
            self.state.vault_applied_search_text = self.state.vault_search_text
            pending_search = False
        controller = self._vault_controller()
        selected = self._vault_selected_id(self.state.vault_source_type, self.state.vault_source_id)
        try:
            snapshot = controller.load(
                self.state.vault_source_type,
                self.state.vault_source_id,
                self.state.vault_start_date_iso,
                self.state.vault_end_date_iso,
                self.state.vault_applied_search_text,
                selected,
            )
            self.state.vault_source_type = str(snapshot.get("source_type") or "google_calendar")
            self.state.vault_source_id = str(snapshot.get("source_id") or "")
            self.state.vault_source_option_label = str((snapshot.get("option") or {}).get("label") or "")
            self._vault_set_selected_id(
                self.state.vault_source_type,
                self.state.vault_source_id,
                str(snapshot.get("selected_id") or ""),
            )
            snapshot["search_pending"] = pending_search
            # The controller owns immutable cached row lists; retaining the snapshot
            # avoids cloning large Gmail/Slack result sets every frame.
            self.state.vault_query_snapshot = snapshot
            self.state.vault_query_error = ""
        except Exception as exc:
            self.state.vault_query_error = f"{type(exc).__name__}: {exc}"
            snapshot = dict(self.state.vault_query_snapshot)
            snapshot["search_pending"] = pending_search
            snapshot["query_error"] = self.state.vault_query_error
        return snapshot


    def _vault_clear_dates(self) -> None:
        """Clear only the inclusive Vault date range, preserving source and search."""
        self.state.vault_start_date_iso = None
        self.state.vault_end_date_iso = None
        self.state.vault_date_error = ""

    def _vault_source_status_text(self, snapshot: dict[str, Any]) -> tuple[str, Color]:
        source = snapshot.get("source") if isinstance(snapshot.get("source"), dict) else None
        if source is None:
            return "Not connected", Palette.muted2
        state = str(source.get("connection_state") or "not_configured")
        last_success = format_vault_local_timestamp(
            source.get("last_successful_sync_at"), self._vault_controller().query.local_timezone,
        )
        if state == "syncing":
            return f"Syncing {VAULT_SOURCE_LABELS.get(snapshot.get('source_type'), 'source')}...", Palette.accent
        if state == "error" or source.get("last_sync_error"):
            suffix = f" · Last successful {last_success}" if last_success else ""
            return "Sync failed" + suffix, Palette.danger
        if state == "disabled" or not bool(source.get("enabled", True)):
            return "Disabled", Palette.muted2
        if last_success:
            return f"Synced · {last_success}", Palette.ok
        if state == "connected":
            return "Connected · Not yet synchronized", Palette.accent2
        return "Not configured", Palette.muted2

    def _vault_draw_status(self, rect: Rect, snapshot: dict[str, Any]) -> None:
        """Draw source state in the existing right header without a page title."""
        status, color = self._vault_source_status_text(snapshot)
        if snapshot.get("search_pending"):
            status = "Searching... · " + status
            color = Palette.accent
        if self.state.vault_query_error:
            status = self.state.vault_query_error
            color = Palette.danger
        status_x = rect.x + max(100, rect.w // 3)
        self.widgets.clipped_text(
            Rect(status_x, rect.y, max(1, rect.x + rect.w - status_x - 12), rect.h),
            status,
            color,
            align="right",
            tooltip=status,
        )

    def _vault_draw_toolbar(self, rect: Rect) -> bool:
        """Draw one-row source/search/two three-dropdown date controls."""
        changed = False
        self.r.draw_card(rect, radius=14, fill=Palette.panel)
        inner = rect.inset(6)
        layout = vault_toolbar_layout(inner, line_h=self.f.line_h)
        controller = self._vault_controller()
        options = controller.source_options()
        labels = [str(row["label"]) for row in options]
        if not self.state.vault_source_option_label or self.state.vault_source_option_label not in labels:
            _source, chosen = controller.resolve_source(self.state.vault_source_type, self.state.vault_source_id)
            self.state.vault_source_option_label = str(chosen["label"])
        selected_label = self.widgets.dropdown(
            "vault.source", layout.source, self.state.vault_source_option_label, labels,
            tooltip="Select one cached Vault data source",
        )
        if selected_label != self.state.vault_source_option_label:
            chosen = next(row for row in options if str(row["label"]) == selected_label)
            self.state.vault_source_option_label = selected_label
            prior_source_type = self.state.vault_source_type
            self.state.vault_source_type = str(chosen["source_type"])
            self.state.vault_source_id = str(chosen["source_id"])
            if prior_source_type != self.state.vault_source_type:
                self._vault_drive_reset_browser(clear_path=True)
            self.state.vault_focus_area = "left"
            self.state.scroll["vault.left"] = 0
            self.state.scroll["vault.right.markdown"] = 0
            self.state.scroll["vault.right.slack"] = 0
            changed = True

        placeholder = VAULT_SEARCH_PLACEHOLDERS.get(self.state.vault_source_type, "Search this source...")
        search_value = self.widgets.text_input(
            "vault.search", layout.search, self.state.vault_search_text, placeholder=placeholder,
            tooltip="Search only the selected cached source",
        )
        if search_value != self.state.vault_search_text:
            self.state.vault_search_text = search_value
            self.state.vault_search_changed_at = time.monotonic()

        start_value = self.widgets.date_picker(
            "vault.start_date", layout.start_picker, self.state.vault_start_date_iso,
            reference_date=date.today(), optional=True,
        )
        if start_value != str(self.state.vault_start_date_iso or ""):
            old = self.state.vault_start_date_iso
            self.state.vault_start_date_iso = start_value or None
            if self.state.vault_start_date_iso and self.state.vault_end_date_iso and self.state.vault_start_date_iso > self.state.vault_end_date_iso:
                self.state.vault_start_date_iso = old
                self.state.vault_date_error = "Vault start date cannot follow end date"
            else:
                self.state.vault_date_error = ""
                changed = True
        self.widgets.clipped_text(layout.dash, "–", Palette.muted, align="center")
        end_value = self.widgets.date_picker(
            "vault.end_date", layout.end_picker, self.state.vault_end_date_iso,
            reference_date=date.today(), optional=True,
        )
        if end_value != str(self.state.vault_end_date_iso or ""):
            old = self.state.vault_end_date_iso
            self.state.vault_end_date_iso = end_value or None
            if self.state.vault_start_date_iso and self.state.vault_end_date_iso and self.state.vault_start_date_iso > self.state.vault_end_date_iso:
                self.state.vault_end_date_iso = old
                self.state.vault_date_error = "Vault start date cannot follow end date"
            else:
                self.state.vault_date_error = ""
                changed = True
        if self.widgets.button("vault.clear_dates", layout.clear, "×", tooltip="Clear date range"):
            self._vault_clear_dates()
            changed = True
        focused_rects = {
            "source": layout.source,
            "start": layout.start_picker,
            "end": layout.end_picker,
            "clear": layout.clear,
        }
        focused_rect = focused_rects.get(self.state.vault_focus_area)
        if focused_rect is not None:
            self.r.draw_round_outline(focused_rect, 12, Palette.focus)
        if self.state.vault_date_error:
            self.r.draw_round_outline(layout.start_picker, 12, Palette.danger)
            self.r.draw_round_outline(layout.end_picker, 12, Palette.danger)
        return changed

    def _vault_current_divider_fraction(self) -> float:
        if self.state.vault_source_type == GOOGLE_DRIVE_SOURCE_TYPE:
            return normalize_vault_divider_fraction(self.state.vault_drive_divider_fraction)
        return normalize_vault_divider_fraction(self.state.vault_divider_fraction)

    def _vault_set_current_divider_fraction(self, value: Any) -> None:
        fraction = normalize_vault_divider_fraction(value)
        if self.state.vault_source_type == GOOGLE_DRIVE_SOURCE_TYPE:
            self.state.vault_drive_divider_fraction = fraction
        else:
            self.state.vault_divider_fraction = fraction

    def _vault_handle_divider(self, rect: Rect, layout: VaultUILayout) -> bool:
        hit = Rect(layout.divider.x - VAULT_DIVIDER_HIT_PX // 2, layout.divider.y, VAULT_DIVIDER_HIT_PX, layout.divider.h)
        hovered = point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, hit)
        if hovered or self.state.vault_divider_dragging:
            self.state.requested_cursor = "resize_x"
        changed = False
        if hovered and self.state.input.mouse_pressed and not self.state.input.mouse_consumed:
            self.state.vault_divider_dragging = True
            self.state.input.mouse_consumed = True
        if self.state.vault_divider_dragging:
            if self.state.input.mouse_down:
                available = max(2, rect.w - layout.divider.w)
                raw_fraction = (self.state.input.mouse_x - rect.x) / available
                self._vault_set_current_divider_fraction(float(clamp(raw_fraction, 0.18, 0.72)))
                self.state.vault_divider_dirty = True
                self.state.input.mouse_consumed = True
                changed = True
            else:
                self.state.vault_divider_dragging = False
                if self.state.vault_divider_dirty:
                    fraction = self._vault_current_divider_fraction()
                    try:
                        if self.state.vault_source_type == GOOGLE_DRIVE_SOURCE_TYPE:
                            self.services.storage.update_config(
                                lambda cfg: cfg["vault"]["google_drive"].__setitem__("divider_fraction", fraction)
                            )
                        else:
                            self.services.storage.update_config(
                                lambda cfg: cfg["vault"].__setitem__("divider_fraction", fraction)
                            )
                    except Exception as exc:
                        self.state.add_toast("Vault divider could not be saved", f"{type(exc).__name__}: {exc}", "error")
                    self.state.vault_divider_dirty = False
        self.r.draw_rect(layout.divider, Palette.border)
        if hovered or self.state.vault_divider_dragging:
            self.r.draw_rect(Rect(layout.divider.x + max(0, layout.divider.w // 2 - 1), layout.divider.y, 2, layout.divider.h), Palette.accent)
        return changed

    def _vault_left_row_height(self, source_type: str) -> int:
        if source_type == GOOGLE_DRIVE_SOURCE_TYPE:
            return max(VAULT_GOOGLE_DRIVE_ROW_H, self.f.line_h * 3 + 18)
        if source_type == GMAIL_SOURCE_TYPE:
            return max(VAULT_GMAIL_ROW_H, self.f.line_h * 3 + 18)
        if source_type == SLACK_SOURCE_TYPE:
            return max(VAULT_SLACK_CHANNEL_ROW_H, self.f.line_h * 2 + 16)
        return max(VAULT_CALENDAR_ROW_H, self.f.line_h + 18)

    @staticmethod
    def _vault_participant_label(item: dict[str, Any], roles: set[str]) -> str:
        values: list[str] = []
        for participant in item.get("participants", []):
            if str(participant.get("role") or "") not in roles:
                continue
            label = str(participant.get("display_name") or participant.get("email") or participant.get("external_id") or "").strip()
            if label and label not in values:
                values.append(label)
        return ", ".join(values)

    def _vault_draw_left_pane(self, rect: Rect, snapshot: dict[str, Any]) -> bool:
        raw_rows = snapshot.get("left_rows")
        rows = raw_rows if isinstance(raw_rows, list) else []
        source_type = str(snapshot.get("source_type") or "google_calendar")
        selected_id = str(snapshot.get("selected_id") or "")
        row_h = self._vault_left_row_height(source_type)
        scroll_id = "vault.left"
        total_h = len(rows) * row_h
        scroll_y = int(self.state.scroll.get(scroll_id, 0))
        if self.widgets._can_receive_pointer(scroll_id) and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, rect) and self.state.input.wheel_y:
            scroll_y -= int(self.state.input.wheel_y) * row_h
            self.state.input.mouse_consumed = True
        scroll_y = int(clamp(scroll_y, 0, max(0, total_h - rect.h)))
        scroll_y = self.widgets._scrollbar_input(scroll_id, rect, scroll_y, total_h)
        self.state.scroll[scroll_id] = scroll_y
        self.r.draw_rect(rect, Palette.panel2)
        self.r.push_clip(rect)
        start, end = vault_visible_row_range(scroll_y, row_h, len(rows), rect.h)
        changed = False
        for index in range(start, end):
            row = rows[index]
            row_id = str(row.get("id") or "")
            rr = Rect(rect.x + 6, rect.y + index * row_h - scroll_y + 3, max(1, rect.w - 18), row_h - 6)
            hovered = self.widgets._can_receive_pointer(scroll_id) and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, rr)
            selected = row_id == selected_id
            if selected:
                self.r.draw_round_rect(rr, 10, Palette.selected)
            elif hovered:
                self.r.draw_round_rect(rr, 10, Palette.hover)
            if hovered and self.state.input.mouse_pressed and not self.state.input.mouse_consumed:
                self._vault_set_selected_id(source_type, str(snapshot.get("source_id") or ""), row_id)
                self.state.vault_focus_area = "left"
                self.state.input.mouse_consumed = True
                changed = True
            text_x = rr.x + 12
            usable_w = max(1, rr.w - 24)
            if source_type == GOOGLE_CALENDAR_SOURCE_TYPE:
                label = str(row.get("label") or format_vault_day_label(row.get("day")))
                self.widgets.clipped_text(Rect(text_x, rr.y, usable_w, rr.h), label, Palette.text, tooltip=label)
            elif source_type == GOOGLE_DRIVE_SOURCE_TYPE:
                metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
                name = str(row.get("title") or row.get("external_id") or "Untitled Drive file")
                is_folder = bool(metadata.get("is_folder"))
                kind = google_drive_type_label(metadata.get("mime_type"), is_folder=is_folder)
                modified = format_vault_local_timestamp(
                    row.get("primary_timestamp"), self._vault_controller().query.local_timezone,
                )
                owner = str(row.get("author_display_name") or self._vault_participant_label(row, {"author"}) or "")
                self.widgets.clipped_text(
                    Rect(text_x, rr.y + 3, usable_w, self.f.line_h + 4),
                    name, Palette.text, tooltip=name,
                )
                subtitle = kind + (f" · {owner}" if owner else "")
                self.widgets.clipped_text(
                    Rect(text_x, rr.y + self.f.line_h + 4, usable_w, self.f.line_h + 4),
                    subtitle, Palette.muted2, tooltip=subtitle,
                )
                self.widgets.clipped_text(
                    Rect(text_x, rr.y + self.f.line_h * 2 + 5, usable_w, self.f.line_h + 4),
                    modified, Palette.muted2, tooltip=modified,
                )
            elif source_type == GMAIL_SOURCE_TYPE:
                sender = str(row.get("author_display_name") or self._vault_participant_label(row, {"sender", "author"}) or "Unknown sender")
                subject = str(row.get("title") or row.get("metadata", {}).get("subject") or "(No subject)")
                stamp = format_vault_local_timestamp(row.get("primary_timestamp"), self._vault_controller().query.local_timezone)
                if bool(row.get("is_unread")):
                    self.r.draw_round_rect(Rect(rr.x + 5, rr.y + 10, 6, 6), 3, Palette.accent)
                    text_x += 8
                    usable_w -= 8
                self.widgets.clipped_text(Rect(text_x, rr.y + 3, usable_w, self.f.line_h + 4), sender, Palette.text, tooltip=sender)
                self.widgets.clipped_text(Rect(text_x, rr.y + self.f.line_h + 4, usable_w, self.f.line_h + 4), subject, Palette.text, tooltip=subject)
                attach = " · attachment" if row.get("attachments") else ""
                self.widgets.clipped_text(Rect(text_x, rr.y + self.f.line_h * 2 + 5, usable_w, self.f.line_h + 4), stamp + attach, Palette.muted2, tooltip=stamp + attach)
            else:
                name = str(row.get("display_name") or row.get("name") or "Conversation")
                count = int(row.get("matching_message_count") or 0)
                latest = format_vault_local_timestamp(row.get("latest_matching_message_timestamp"), self._vault_controller().query.local_timezone)
                metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
                unread = bool(metadata.get("is_unread")) or int(metadata.get("unread_count") or 0) > 0
                if unread:
                    self.r.draw_round_rect(Rect(rr.x + 5, rr.y + 11, 6, 6), 3, Palette.accent)
                    text_x += 8
                    usable_w -= 8
                self.widgets.clipped_text(Rect(text_x, rr.y + 4, usable_w, self.f.line_h + 4), name, Palette.text, tooltip=name)
                subtitle = f"{count} matching message{'s' if count != 1 else ''}"
                if latest:
                    subtitle += f" · {latest}"
                self.widgets.clipped_text(Rect(text_x, rr.y + self.f.line_h + 6, usable_w, self.f.line_h + 4), subtitle, Palette.muted2, tooltip=subtitle)
        self.r.pop_clip()
        self.widgets._scrollbar_draw(scroll_id, rect, scroll_y, total_h)
        return changed

    @staticmethod
    def _vault_markdown_escape_inline(value: Any) -> str:
        return str(value or "").replace("\n", " ").replace("\r", " ").strip()

    def _vault_calendar_markdown(self, snapshot: dict[str, Any]) -> str:
        selected = str(snapshot.get("selected_id") or "")
        if not selected:
            return ""
        day_value = date.fromisoformat(selected)
        lines = [f"# {day_value.strftime('%A, %d %B %Y')}"]
        rows = list(snapshot.get("right_rows") or [])
        calendar_names = {str(row.get("metadata", {}).get("calendar_display_name") or "") for row in rows}
        show_calendar = len({name for name in calendar_names if name}) > 1
        tz = self._vault_controller().query.local_timezone
        for event in rows:
            metadata = event.get("metadata", {})
            if bool(event.get("is_all_day")):
                time_label = "All day"
            else:
                start = format_vault_local_timestamp(event.get("start_timestamp") or event.get("primary_timestamp"), tz, include_date=False)
                end = format_vault_local_timestamp(event.get("end_timestamp"), tz, include_date=False)
                time_label = f"{start}–{end}" if end else start
            title = self._vault_markdown_escape_inline(event.get("title") or "Untitled event")
            lines.extend(["", f"## {time_label}  {title}"])
            if show_calendar:
                lines.append(f"**Calendar:** {self._vault_markdown_escape_inline(metadata.get('calendar_display_name'))}")
            organizer = self._vault_participant_label(event, {"organizer"})
            attendees = self._vault_participant_label(event, {"attendee"})
            if organizer:
                lines.append(f"**Organizer:** {organizer}")
            if attendees:
                lines.append(f"**Attendees:** {attendees}")
            location = self._vault_markdown_escape_inline(metadata.get("location"))
            if location:
                lines.append(f"**Location:** {location}")
            if bool(event.get("is_all_day")):
                lines.append("**All day:** Yes")
            if metadata.get("recurring_series_id") or metadata.get("recurrence"):
                lines.append("**Recurring:** Yes")
            meeting_url = str(metadata.get("conference_url") or "").strip()
            if meeting_url:
                lines.append(f"[Open conference]({meeting_url})")
            source_url = str(event.get("source_url") or "").strip()
            if source_url:
                lines.append(f"[Open source event]({source_url})")
            description = str(event.get("body_text") or "").strip()
            if description:
                lines.extend(["", description])
        return "\n".join(lines)[:VAULT_MAX_DETAIL_MARKDOWN_CHARS]

    def _vault_gmail_markdown(self, item: dict[str, Any]) -> str:
        tz = self._vault_controller().query.local_timezone
        sender = self._vault_participant_label(item, {"sender", "author"}) or str(item.get("author_display_name") or "")
        recipients = self._vault_participant_label(item, {"recipient"})
        cc = self._vault_participant_label(item, {"cc"})
        subject = str(item.get("title") or item.get("metadata", {}).get("subject") or "(No subject)")
        lines = [
            f"**From:** {sender or 'Unknown'}",
            f"**To:** {recipients or '—'}",
        ]
        if cc:
            lines.append(f"**CC:** {cc}")
        lines.extend([
            f"**Date:** {format_vault_local_timestamp(item.get('primary_timestamp'), tz)}",
            f"**Subject:** {subject}",
        ])
        attachments = list(item.get("attachments") or [])
        if attachments:
            lines.extend(["", "### Attachments"])
            for attachment in attachments:
                size = int(attachment.get("size_bytes") or 0)
                size_text = f" · {human_bytes(size)}" if size else ""
                lines.append(f"- {attachment.get('filename') or 'Attachment'} ({attachment.get('mime_type') or 'unknown type'}{size_text})")
        body = str(item.get("body_text") or "").strip()
        if not body:
            html_body = str(item.get("body_html") or "")
            if html_body:
                raw = re.sub(r"(?is)<(script|style|head|noscript|svg|iframe)[^>]*>.*?</\1>", " ", html_body)
                raw = re.sub(r"(?is)<br\s*/?>|</(?:p|div|li|h[1-6])>", "\n", raw)
                body = html.unescape(re.sub(r"(?is)<[^>]+>", " ", raw))
                body = "\n".join(line.strip() for line in body.splitlines() if line.strip())
        lines.extend(["", "---", "", body or "_No readable message body is available._"])
        return "\n".join(lines)[:VAULT_MAX_DETAIL_MARKDOWN_CHARS]

    @staticmethod
    def _vault_slack_markdown_text(value: Any) -> str:
        text = str(value or "")
        text = re.sub(r"<((?:https?://)[^>|]+)\|([^>]+)>", r"[\2](\1)", text)
        text = re.sub(r"<((?:https?://)[^>]+)>", r"\1", text)
        text = re.sub(r"<@([A-Z0-9]+)>", r"@\1", text)
        text = re.sub(r"<#([A-Z0-9]+)(?:\|([^>]+))?>", lambda m: "#" + (m.group(2) or m.group(1)), text)
        return text

    def _vault_slack_message_markdown(self, row: dict[str, Any]) -> str:
        """Return readable Slack text plus retained file/link/reaction metadata."""
        sections: list[str] = []
        body = self._vault_slack_markdown_text(row.get("body_text")).strip()
        if row.get("parent_outside_range"):
            sections.append("_Parent message is outside the current date range._")
        if body:
            sections.append(body)

        attachments = [entry for entry in (row.get("attachments") or []) if isinstance(entry, dict)]
        if attachments:
            attachment_lines = ["**Files**"]
            for attachment in attachments[:20]:
                filename = self._vault_markdown_escape_inline(attachment.get("filename") or "Attachment")
                source_url = str(attachment.get("source_url") or "").strip()
                mime_type = self._vault_markdown_escape_inline(attachment.get("mime_type"))
                size = int(attachment.get("size_bytes") or 0)
                details = ", ".join(part for part in (mime_type, human_bytes(size) if size else "") if part)
                label = f"[{filename}]({source_url})" if source_url else filename
                attachment_lines.append(f"- {label}" + (f" — {details}" if details else ""))
            if len(attachments) > 20:
                attachment_lines.append(f"- _{len(attachments) - 20} more files_…")
            sections.append("\n".join(attachment_lines))

        metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
        links = [entry for entry in (metadata.get("links") or []) if isinstance(entry, dict)]
        if links:
            link_lines = ["**Links**"]
            for link in links[:20]:
                url = str(link.get("url") or link.get("source_url") or "").strip()
                label = self._vault_markdown_escape_inline(
                    link.get("display_label") or link.get("label") or link.get("title") or url
                )
                if url:
                    link_lines.append(f"- [{label or url}]({url})")
                elif label:
                    link_lines.append(f"- {label}")
            if len(links) > 20:
                link_lines.append(f"- _{len(links) - 20} more links_…")
            sections.append("\n".join(link_lines))

        reactions = metadata.get("reactions")
        if isinstance(reactions, list) and reactions:
            reaction_text = " · ".join(
                f":{reaction.get('name', 'reaction')}: {int(reaction.get('count') or 0)}"
                for reaction in reactions if isinstance(reaction, dict)
            )
            if reaction_text:
                sections.append(f"**Reactions:** {reaction_text}")
        elif reactions:
            sections.append(f"**Reactions:** {self._vault_markdown_escape_inline(reactions)}")

        source_url = str(row.get("source_url") or "").strip()
        if source_url:
            sections.append(f"[Open in Slack]({source_url})")
        return "\n\n".join(section for section in sections if section).strip()

    def _vault_draw_slack_messages(self, rect: Rect, snapshot: dict[str, Any]) -> None:
        raw_rows = snapshot.get("right_rows")
        rows = raw_rows if isinstance(raw_rows, list) else []
        if not rows:
            self._vault_draw_empty_message(rect, "No messages match the current search and date range.\n\nClear the search or expand the date range.")
            return
        scroll_id = "vault.right.slack"
        width_bucket = max(1, rect.w // 32)
        revision = self._vault_controller().revision()
        layout_key = (
            revision, str(snapshot.get("source_id") or ""), str(snapshot.get("selected_id") or ""),
            self.state.vault_start_date_iso or "", self.state.vault_end_date_iso or "",
            self.state.vault_applied_search_text, width_bucket, len(rows),
        )
        fixed_layout = len(rows) > VAULT_SLACK_DYNAMIC_LAYOUT_MAX_ROWS
        if fixed_layout:
            stride = max(VAULT_SLACK_FIXED_ROW_H, self.f.line_h * 5 + 24) + 4
            total_h = len(rows) * stride
            heights: list[int] = []
            tops: list[int] = []
        else:
            if self.state.vault_slack_layout_key != layout_key:
                heights = []
                tops = []
                running = 0
                for row in rows:
                    cache_key = (str(row.get("id") or ""), width_bucket)
                    height = self.state.vault_slack_height_cache.get(cache_key)
                    if height is None:
                        indent = 30 if int(row.get("indentation_depth") or 0) else 0
                        cols = max(12, (rect.w - 48 - indent) // max(1, self.f.char_w))
                        message_markdown = self._vault_slack_message_markdown(row)
                        line_count = int(clamp(
                            estimate_wrapped_line_count_fast(message_markdown, cols), 1, 20,
                        ))
                        height = max(58, self.f.line_h * (line_count + 1) + 24)
                        self.state.vault_slack_height_cache[cache_key] = height
                    tops.append(running)
                    heights.append(height)
                    running += height + 4
                self.state.vault_slack_layout_key = layout_key
                self.state.vault_slack_layout_tops = tops
                self.state.vault_slack_layout_heights = heights
                self.state.vault_slack_layout_total_h = running
            tops = self.state.vault_slack_layout_tops
            heights = self.state.vault_slack_layout_heights
            total_h = self.state.vault_slack_layout_total_h

        scroll_y = int(self.state.scroll.get(scroll_id, 0))
        if self.widgets._can_receive_pointer(scroll_id) and point_in_rect(
            self.state.input.mouse_x, self.state.input.mouse_y, rect,
        ) and self.state.input.wheel_y:
            scroll_y -= int(self.state.input.wheel_y) * self.f.line_h * 4
            self.state.input.mouse_consumed = True
        scroll_y = int(clamp(scroll_y, 0, max(0, total_h - rect.h)))
        scroll_y = self.widgets._scrollbar_input(scroll_id, rect, scroll_y, total_h)
        self.state.scroll[scroll_id] = scroll_y
        self.r.draw_rect(rect, Palette.panel2)
        self.r.push_clip(rect)
        if fixed_layout:
            start_index, end_index = vault_visible_row_range(scroll_y, stride, len(rows), rect.h, overscan=2)
        else:
            start_index = max(0, bisect.bisect_right(tops, scroll_y) - 1)
            end_index = min(len(rows), bisect.bisect_left(tops, scroll_y + rect.h) + 2)
        tz = self._vault_controller().query.local_timezone
        for index in range(start_index, end_index):
            row = rows[index]
            top = index * stride if fixed_layout else tops[index]
            height = stride - 4 if fixed_layout else heights[index]
            y = rect.y + top - scroll_y
            indent = 30 if int(row.get("indentation_depth") or 0) else 0
            rr = Rect(rect.x + 10 + indent, y + 2, max(1, rect.w - 26 - indent), height)
            if indent:
                self.r.draw_rect(Rect(rect.x + 16, rr.y, 2, rr.h), theme_alpha(Palette.accent, 100))
            self.r.draw_round_rect(rr, 10, theme_mix(Palette.input_bg, Palette.white, 0.015))
            author = str(row.get("author_display_name") or "Unknown")
            stamp = format_vault_local_timestamp(row.get("primary_timestamp"), tz, include_date=False)
            edited = " · edited" if row.get("metadata", {}).get("edited_timestamp") else ""
            self.widgets.clipped_text(
                Rect(rr.x + 10, rr.y + 5, rr.w - 20, self.f.line_h + 4),
                f"{stamp}  {author}{edited}", Palette.text,
            )
            body_y = rr.y + self.f.line_h + 9
            body_rect = Rect(rr.x + 8, body_y, rr.w - 16, max(1, rr.y + rr.h - body_y - 4))
            body_text = self._vault_slack_message_markdown(row)
            self.widgets.markdown_renderer.view(
                f"vault.slack.message.{row.get('id')}", body_rect, body_text,
                selectable=True, draw_card=False, vertical_scroll=False,
                visible_clip=rect, cache_key=f"vault.slack.message.{row.get('id')}.{width_bucket}",
            )
        self.r.pop_clip()
        self.widgets._scrollbar_draw(scroll_id, rect, scroll_y, total_h)

    def _vault_draw_empty_message(
        self, rect: Rect, message: str, *, settings_button: bool = False,
        retry_button: bool = False, retry_source_type: str = "",
    ) -> None:
        self.r.draw_rect(rect, Palette.panel2)
        inner = rect.inset(24)
        text_h = min(inner.h - 50, max(self.f.line_h * 4, 100))
        self._calendar_draw_wrapped_text(Rect(inner.x, inner.y, inner.w, max(1, text_h)), message, Palette.muted, max_lines=max(2, text_h // max(1, self.f.line_h)))
        x = inner.x
        y = inner.y + text_h + 12
        if settings_button:
            if self.widgets.button("vault.empty.settings", Rect(x, y, 180, 36), "Open Settings"):
                self.state.settings_section = "Accounts"
                self._activate_global_destination("settings")
            x += 190
        if retry_button:
            if self.widgets.button("vault.empty.retry", Rect(x, y, 120, 36), "Retry"):
                source_type = str(retry_source_type or self.state.vault_source_type or "google_calendar")
                if source_type == GOOGLE_CALENDAR_SOURCE_TYPE:
                    self._begin_calendar_refresh()
                else:
                    self._begin_vault_connector_operation(source_type, "sync")

    def _vault_drive_reset_browser(self, *, clear_path: bool = True) -> None:
        task = self.state.vault_drive_task
        if task is not None and not task.done():
            task.cancel()
        self.state.vault_drive_task = None
        self.state.vault_drive_request_key = None
        self.state.vault_drive_loaded_key = None
        self.state.vault_drive_rows = []
        self.state.vault_drive_selected_id = ""
        self.state.vault_drive_status = ""
        self.state.vault_drive_error = ""
        self.state.vault_drive_result_meta = {}
        action_task = self.state.vault_drive_action_task
        if action_task is not None and not action_task.done():
            action_task.cancel()
        self.state.vault_drive_action_task = None
        self.state.vault_drive_action_status = ""
        self.state.vault_drive_action_error = ""
        if clear_path:
            self.state.vault_drive_path = []

    def _vault_drive_request_key(self) -> tuple[Any, ...]:
        query = str(self.state.vault_applied_search_text or "").strip()
        serial = int(self.state.vault_drive_refresh_serial)
        if query:
            drive_id = str(self.state.vault_drive_path[0].get("drive_id") or "") if self.state.vault_drive_path else ""
            return ("search", query, drive_id, serial)
        if not self.state.vault_drive_path:
            return ("drives", serial)
        node = self.state.vault_drive_path[-1]
        kind = str(node.get("kind") or "")
        if kind == "drive":
            return ("root", str(node.get("drive_id") or ""), serial)
        return (
            "folder", str(node.get("folder_id") or ""),
            str(node.get("drive_id") or ""), serial,
        )

    async def _vault_drive_fetch(self, key: tuple[Any, ...]) -> dict[str, Any]:
        connector = self.services.google_drive
        if connector is None:
            raise RuntimeError("Google Drive integration is unavailable")
        mode = str(key[0])
        if mode == "drives":
            result = await connector.list_drives(GOOGLE_DRIVE_MAX_RESULT_LIMIT)
            rows: list[dict[str, Any]] = [{
                "file_id": "drive:my", "name": "My Drive", "mime_type": GOOGLE_DRIVE_FOLDER_MIME_TYPE,
                "is_folder": True, "entry_kind": "drive", "drive_id": "", "parents": [],
                "description": "Top-level files and folders in My Drive.",
            }]
            for drive in result.get("shared_drives") or []:
                if not isinstance(drive, dict):
                    continue
                drive_id = str(drive.get("drive_id") or "")
                if not drive_id:
                    continue
                rows.append({
                    "file_id": "drive:" + drive_id,
                    "name": str(drive.get("name") or "Shared Drive"),
                    "mime_type": GOOGLE_DRIVE_FOLDER_MIME_TYPE,
                    "is_folder": True, "entry_kind": "drive", "drive_id": drive_id,
                    "parents": [], "created_at": str(drive.get("created_at") or ""),
                    "description": "Shared Drive root.",
                })
            return {"mode": mode, "files": rows, **result}
        if mode == "search":
            return {"mode": mode, **(await connector.search_files(str(key[1]), 500, str(key[2])))}
        if mode == "root":
            return {"mode": mode, **(await connector.list_root(str(key[1]), 500))}
        if mode == "folder":
            return {"mode": mode, **(await connector.list_children(str(key[1]), 500))}
        raise RuntimeError(f"Unsupported Drive browser request mode: {mode}")

    def _vault_drive_consume_task(self, current_key: tuple[Any, ...]) -> None:
        task = self.state.vault_drive_task
        if task is None or not task.done():
            return
        request_key = self.state.vault_drive_request_key
        self.state.vault_drive_task = None
        self.state.vault_drive_request_key = None
        try:
            result = task.result()
        except asyncio.CancelledError:
            return
        except Exception as exc:
            if request_key == current_key:
                self.state.vault_drive_error = f"{type(exc).__name__}: {exc}"
                self.state.vault_drive_status = "Drive request failed"
            return
        if request_key != current_key:
            return
        rows = [copy.deepcopy(row) for row in result.get("files") or [] if isinstance(row, dict)]
        rows.sort(key=lambda row: (
            0 if bool(row.get("is_folder")) else 1,
            str(row.get("name") or "").casefold(), str(row.get("file_id") or ""),
        ))
        self.state.vault_drive_rows = rows
        self.state.vault_drive_loaded_key = current_key
        self.state.vault_drive_result_meta = {
            key: copy.deepcopy(result.get(key))
            for key in (
                "mode", "count", "query", "corpora", "result_order", "incomplete_search",
                "truncated", "next_page_token_available", "location", "folder", "account",
            ) if key in result
        }
        valid_ids = {str(row.get("file_id") or "") for row in rows}
        if self.state.vault_drive_selected_id not in valid_ids:
            self.state.vault_drive_selected_id = str(rows[0].get("file_id") or "") if rows else ""
        self.state.vault_drive_error = ""
        suffix = ""
        if bool(result.get("truncated")):
            suffix = " · result limit reached"
        elif bool(result.get("incomplete_search")):
            suffix = " · Google reported an incomplete search"
        self.state.vault_drive_status = f"{len(rows)} row{'s' if len(rows) != 1 else ''}{suffix}"

    def _vault_drive_ensure_loaded(self, *, force: bool = False) -> tuple[Any, ...]:
        key = self._vault_drive_request_key()
        task = self.state.vault_drive_task
        if task is not None and self.state.vault_drive_request_key != key:
            if not task.done():
                task.cancel()
            self.state.vault_drive_task = None
            self.state.vault_drive_request_key = None
        self._vault_drive_consume_task(key)
        if force:
            self.state.vault_drive_loaded_key = None
        if self.state.vault_drive_loaded_key != key and self.state.vault_drive_task is None:
            try:
                self.state.vault_drive_task = asyncio.create_task(self._vault_drive_fetch(key))
                self.state.vault_drive_request_key = key
                self.state.vault_drive_status = "Loading Google Drive..."
                self.state.vault_drive_error = ""
            except RuntimeError as exc:
                self.state.vault_drive_error = str(exc)
        return key

    def _vault_drive_open_row(self, row: dict[str, Any]) -> None:
        if not bool(row.get("is_folder")):
            source_url = str(row.get("source_url") or "").strip()
            if source_url:
                webbrowser.open(source_url)
            return
        # Folder navigation leaves search mode and switches back to the concrete
        # hierarchy represented by the selected row.
        self.state.vault_search_text = ""
        self.state.vault_applied_search_text = ""
        if str(row.get("entry_kind") or "") == "drive":
            drive_id = str(row.get("drive_id") or "")
            self.state.vault_drive_path = [{
                "kind": "drive", "drive_id": drive_id,
                "folder_id": drive_id or "root", "name": str(row.get("name") or "Drive"),
            }]
        else:
            drive_id = str(row.get("drive_id") or "")
            if not self.state.vault_drive_path:
                self.state.vault_drive_path = [{
                    "kind": "drive", "drive_id": drive_id,
                    "folder_id": drive_id or "root",
                    "name": "Shared Drive" if drive_id else "My Drive",
                }]
            self.state.vault_drive_path.append({
                "kind": "folder", "drive_id": drive_id,
                "folder_id": str(row.get("file_id") or ""),
                "name": str(row.get("name") or "Folder"),
            })
        self.state.vault_drive_selected_id = ""
        self.state.vault_drive_loaded_key = None
        self.state.scroll["vault.drive.table"] = 0

    def _vault_drive_up(self) -> None:
        if self.state.vault_drive_path:
            self.state.vault_drive_path.pop()
            self.state.vault_drive_selected_id = ""
            self.state.vault_drive_loaded_key = None
            self.state.scroll["vault.drive.table"] = 0

    async def _vault_drive_download_selected(self, row: dict[str, Any]) -> dict[str, Any]:
        connector = self.services.google_drive
        if connector is None:
            raise RuntimeError("Google Drive integration is unavailable")
        file_id = str(row.get("file_id") or "").strip()
        if not file_id or bool(row.get("is_folder")):
            raise ValueError("Select a downloadable Google Drive file")
        destination = self.services.storage.paths.root_dir / "downloads" / "google_drive"
        max_bytes = web_setting_int(self.services.storage.load_config(), "download_max_bytes")
        return await connector.download_file(file_id, destination, max_bytes)

    def _vault_drive_begin_download(self, row: dict[str, Any]) -> None:
        task = self.state.vault_drive_action_task
        if task is not None and not task.done():
            return
        self.state.vault_drive_action_status = "Downloading..."
        self.state.vault_drive_action_error = ""
        try:
            self.state.vault_drive_action_task = asyncio.create_task(
                self._vault_drive_download_selected(copy.deepcopy(row))
            )
        except RuntimeError as exc:
            self.state.vault_drive_action_error = str(exc)

    def _vault_drive_consume_action_task(self) -> None:
        task = self.state.vault_drive_action_task
        if task is None or not task.done():
            return
        self.state.vault_drive_action_task = None
        try:
            result = task.result()
        except asyncio.CancelledError:
            return
        except Exception as exc:
            self.state.vault_drive_action_error = f"{type(exc).__name__}: {exc}"
            self.state.vault_drive_action_status = "Download failed"
            return
        path = str(result.get("path") or "") if isinstance(result, dict) else ""
        self.state.vault_drive_action_error = ""
        self.state.vault_drive_action_status = f"Downloaded to {path}" if path else "Download complete"

    def _vault_drive_detail_markdown(self, row: dict[str, Any] | None) -> str:
        if not isinstance(row, dict):
            return "Select a Drive, folder, or file to inspect it."
        title = str(row.get("name") or "Untitled")
        kind = google_drive_type_label(
            row.get("mime_type"),
            is_folder=bool(row.get("is_folder")),
            entry_kind=row.get("entry_kind"),
        )
        lines = [f"# {self._vault_markdown_escape_inline(title)}", "", f"**Type:** {kind}"]
        if row.get("modified_at"):
            lines.append(f"**Modified:** {row.get('modified_at')}")
        if row.get("created_at"):
            lines.append(f"**Created:** {row.get('created_at')}")
        if int(row.get("size_bytes") or 0):
            lines.append(f"**Size:** {human_bytes(int(row.get('size_bytes') or 0))}")
        if row.get("drive_id"):
            lines.append(f"**Drive ID:** `{row.get('drive_id')}`")
        if row.get("file_id") and str(row.get("entry_kind") or "") != "drive":
            lines.append(f"**File ID:** `{row.get('file_id')}`")
        owners = [str(value) for value in row.get("owners") or [] if str(value).strip()]
        if owners:
            lines.append("**Owner:** " + ", ".join(owners))
        description = str(row.get("description") or "").strip()
        if description:
            lines.extend(["", "## Description", "", description])
        source_url = str(row.get("source_url") or "").strip()
        if source_url:
            lines.extend(["", f"[Open in Google Drive]({source_url})"])
        return "\n".join(lines)

    def _vault_draw_google_drive_explorer(self, layout: VaultUILayout, snapshot: dict[str, Any]) -> None:
        status = (snapshot.get("option") or {}).get("status") if isinstance(snapshot.get("option"), dict) else {}
        status = status if isinstance(status, dict) else {}
        self.r.draw_rect(layout.left_header, Palette.panel3)
        self.r.draw_rect(layout.right_header, Palette.panel3)
        if not bool(status.get("connected")):
            self._draw_card_title_text(
                "vault.drive.disconnected.left.title",
                Rect(layout.left_header.x + 12, layout.left_header.y, max(1, layout.left_header.w - 24), layout.left_header.h),
                "GOOGLE DRIVE",
            )
            self._draw_card_title_text(
                "vault.drive.disconnected.right.title",
                Rect(layout.right_header.x + 12, layout.right_header.y, max(1, layout.right_header.w - 24), layout.right_header.h),
                "DETAIL",
            )
            self._vault_draw_empty_message(
                Rect(layout.left_body.x, layout.left_body.y, layout.left_body.w + layout.divider.w + layout.right_body.w, layout.left_body.h),
                "Google Drive is not connected. Configure read-only Google Drive access in Settings > Accounts.",
                settings_button=True,
            )
            return

        self._vault_drive_consume_action_task()
        self._vault_drive_ensure_loaded()
        drive_title_rect, drive_count_rect = vault_header_title_count_rects(layout.left_header)
        self._draw_card_title_text("vault.drive.left.title", drive_title_rect, "DRIVE BROWSER")
        self.widgets.clipped_text(
            drive_count_rect, f"{len(self.state.vault_drive_rows):,}", Palette.muted2, align="right",
        )
        right_title_rect = Rect(
            layout.right_header.x + 12, layout.right_header.y,
            max(1, min(240, layout.right_header.w // 3) - 12), layout.right_header.h,
        )
        self._draw_card_title_text("vault.drive.right.title", right_title_rect, "DETAIL")
        status_text = (
            self.state.vault_drive_action_error or self.state.vault_drive_error
            or self.state.vault_drive_action_status or self.state.vault_drive_status or "Ready"
        )
        self.widgets.clipped_text(
            Rect(layout.right_header.x + max(90, layout.right_header.w // 3), layout.right_header.y,
                 max(1, layout.right_header.w - max(90, layout.right_header.w // 3) - 12), layout.right_header.h),
            status_text, Palette.danger if (self.state.vault_drive_error or self.state.vault_drive_action_error) else Palette.muted2,
            align="right", tooltip=status_text,
        )

        toolbar = Rect(layout.left_body.x, layout.left_body.y, layout.left_body.w, 42)
        table_rect = Rect(layout.left_body.x, toolbar.y + toolbar.h + 4, layout.left_body.w,
                          max(1, layout.left_body.y + layout.left_body.h - toolbar.y - toolbar.h - 4))
        self.r.draw_rect(toolbar, Palette.panel2)
        back_rect = Rect(toolbar.x + 6, toolbar.y + 5, 64, 32)
        if self.widgets.button(
            "vault.drive.up", back_rect, "Up", enabled=bool(self.state.vault_drive_path),
            tooltip="Return to the parent folder or Drive list",
        ):
            self._vault_drive_up()
        refresh_rect = Rect(toolbar.x + toolbar.w - 38, toolbar.y + 5, 32, 32)
        if self.widgets.button(
            "vault.drive.refresh", refresh_rect, "", icon="regen", tooltip="Refresh",
        ):
            self.state.vault_drive_refresh_serial += 1
            self._vault_drive_ensure_loaded(force=True)
        breadcrumb = "Drives" if not self.state.vault_drive_path else " / ".join(
            str(node.get("name") or "Folder") for node in self.state.vault_drive_path
        )
        if str(self.state.vault_applied_search_text or "").strip():
            breadcrumb = f"Search: {self.state.vault_applied_search_text}"
        self.widgets.clipped_text(
            Rect(back_rect.x + back_rect.w + 8, toolbar.y, max(1, refresh_rect.x - back_rect.x - back_rect.w - 16), toolbar.h),
            breadcrumb, Palette.text, tooltip=breadcrumb,
        )

        source_rows = self.state.vault_drive_rows
        lookup: dict[str, dict[str, Any]] = {}
        table_rows: list[dict[str, Any]] = []
        for row in source_rows:
            row_id = str(row.get("file_id") or "")
            if not row_id:
                continue
            lookup[row_id] = row
            type_label = google_drive_type_label(
                row.get("mime_type"),
                is_folder=bool(row.get("is_folder")),
                entry_kind=row.get("entry_kind"),
            )
            size_label = "" if bool(row.get("is_folder")) else (
                human_bytes(int(row.get("size_bytes") or 0)) if int(row.get("size_bytes") or 0) else ""
            )
            table_rows.append({
                "id": row_id,
                "name": ("[Folder] " if bool(row.get("is_folder")) and str(row.get("entry_kind") or "") != "drive" else "") + str(row.get("name") or "Untitled"),
                "type": type_label,
                "modified": str(row.get("modified_at") or row.get("created_at") or ""),
                "size": size_label,
                "_tooltip": "\n".join(filter(None, [
                    str(row.get("name") or "Untitled"), type_label,
                    ("Modified: " + str(row.get("modified_at"))) if row.get("modified_at") else "",
                    ("Double-click to open" if bool(row.get("is_folder")) else "Double-click to open in Google Drive"),
                ])),
            })
        columns = google_drive_table_columns(table_rect.w)
        selected, action = self.widgets.table_view(
            "vault.drive.table", table_rect, columns, table_rows,
            self.state.vault_drive_selected_id or None, double_click_action="open",
        )
        self.state.vault_drive_selected_id = str(selected or "")
        if action and action[1] == "open":
            row = lookup.get(str(action[0]))
            if row is not None:
                self._vault_drive_open_row(row)
        selected_row = lookup.get(self.state.vault_drive_selected_id)
        action_h = 44 if selected_row is not None else 0
        detail_rect = layout.right_body
        if selected_row is not None:
            actions = Rect(layout.right_body.x, layout.right_body.y, layout.right_body.w, action_h)
            self.r.draw_rect(actions, Palette.panel2)
            x = actions.x + 8
            if self.widgets.button(
                "vault.drive.open", Rect(x, actions.y + 6, 168, 32),
                "Open folder" if bool(selected_row.get("is_folder")) else "Open in Drive",
                enabled=bool(selected_row.get("is_folder") or selected_row.get("source_url")),
            ):
                self._vault_drive_open_row(selected_row)
            x += 176
            if not bool(selected_row.get("is_folder")):
                downloading = bool(
                    self.state.vault_drive_action_task is not None
                    and not self.state.vault_drive_action_task.done()
                )
                if self.widgets.button(
                    "vault.drive.download", Rect(x, actions.y + 6, 96, 32), "Download",
                    enabled=not downloading,
                    tooltip="Download a read-only copy into Velox downloads/google_drive",
                ):
                    self._vault_drive_begin_download(selected_row)
                x += 104
            file_id = str(selected_row.get("file_id") or "")
            if file_id and self.widgets.button(
                "vault.drive.copy_id", Rect(x, actions.y + 6, 86, 32), "Copy ID",
            ):
                self.widgets.set_clipboard_text(file_id)
            detail_rect = Rect(
                layout.right_body.x, layout.right_body.y + action_h, layout.right_body.w,
                max(1, layout.right_body.h - action_h),
            )
        markdown = self._vault_drive_detail_markdown(selected_row)
        self.widgets.markdown_renderer.view(
            "vault.drive.detail", detail_rect, markdown,
            selectable=True, draw_card=True, vertical_scroll=True,
            cache_key=f"vault.drive.detail.{self.state.vault_drive_selected_id}.{self.state.vault_drive_loaded_key}",
        )

    def _vault_draw_right_pane(self, rect: Rect, snapshot: dict[str, Any]) -> None:
        source_type = str(snapshot.get("source_type") or "google_calendar")
        source = snapshot.get("source") if isinstance(snapshot.get("source"), dict) else None
        if source is None:
            noun = VAULT_SOURCE_LABELS.get(source_type, "This source")
            self._vault_draw_empty_message(
                rect,
                f"{noun} is not connected.\n\nConfigure {noun} in Settings to synchronize data.",
                settings_button=True,
            )
            return
        if not snapshot.get("has_any_data"):
            noun = {
                GOOGLE_CALENDAR_SOURCE_TYPE: "Calendar events",
                GOOGLE_DRIVE_SOURCE_TYPE: "Google Drive data",
                GMAIL_SOURCE_TYPE: "Gmail data",
                SLACK_SOURCE_TYPE: "Slack data",
            }.get(source_type, "Vault data")
            source_error = str(source.get("last_sync_error") or "").strip()
            if source_error:
                last_success = format_vault_local_timestamp(
                    source.get("last_successful_sync_at"), self._vault_controller().query.local_timezone,
                )
                message = f"{VAULT_SOURCE_LABELS.get(source_type, noun)} could not be synchronized.\n\n{source_error}"
                if last_success:
                    message += f"\n\nLast successful sync: {last_success}"
            else:
                message = f"No {noun} is available.\n\nRun synchronization or check the connector."
            self._vault_draw_empty_message(
                rect, message, settings_button=True, retry_button=True,
                retry_source_type=source_type,
            )
            return
        if not snapshot.get("left_rows"):
            noun = {
                GOOGLE_CALENDAR_SOURCE_TYPE: "events",
                GOOGLE_DRIVE_SOURCE_TYPE: "files",
                GMAIL_SOURCE_TYPE: "messages",
                SLACK_SOURCE_TYPE: "channels",
            }.get(source_type, "items")
            self._vault_draw_empty_message(
                rect,
                f"No {noun} match the current search and date range.\n\nClear the search or expand the date range.",
            )
            return
        if source_type == SLACK_SOURCE_TYPE:
            self._vault_draw_slack_messages(rect, snapshot)
            return
        if source_type == GOOGLE_CALENDAR_SOURCE_TYPE:
            markdown = self._vault_calendar_markdown(snapshot)
        else:
            right_rows = list(snapshot.get("right_rows") or [])
            markdown = self._vault_gmail_markdown(right_rows[0]) if right_rows else ""
        if not markdown:
            self._vault_draw_empty_message(rect, "Select an item to inspect it.")
            return
        self.widgets.markdown_renderer.view(
            "vault.right.markdown", rect, markdown,
            selectable=True, draw_card=True, vertical_scroll=True,
            cache_key=f"vault.right.{source_type}.{snapshot.get('selected_id')}.{self._vault_controller().revision()}",
        )

    def _vault_move_selection(self, snapshot: dict[str, Any], direction: str) -> bool:
        raw_rows = snapshot.get("left_rows")
        rows = raw_rows if isinstance(raw_rows, list) else []
        if not rows:
            return False
        ids = [str(row.get("id") or "") for row in rows]
        selected = str(snapshot.get("selected_id") or "")
        try:
            index = ids.index(selected)
        except ValueError:
            index = 0
        if direction == "up":
            index = max(0, index - 1)
        elif direction == "down":
            index = min(len(ids) - 1, index + 1)
        elif direction == "home":
            index = 0
        elif direction == "end":
            index = len(ids) - 1
        next_id = ids[index]
        if next_id == selected:
            return False
        self._vault_set_selected_id(str(snapshot.get("source_type") or ""), str(snapshot.get("source_id") or ""), next_id)
        return True

    def _vault_handle_keyboard(self, snapshot: dict[str, Any], layout: VaultUILayout) -> bool:
        changed = False
        inp = self.state.input
        if inp.find_requested:
            self.state.active_widget = "vault.search"
            self.state.vault_focus_area = "search"
            self.state.text_selections["vault.search"] = 0
            self.state.text_cursors["vault.search"] = len(self.state.vault_search_text)
            inp.find_requested = False
        if inp.key_tab and not self.state.open_dropdown:
            order = [
                "source", "search", "start", "end", "clear", "left", "right",
            ]
            current = self.state.vault_focus_area if self.state.vault_focus_area in order else "left"
            next_index = (order.index(current) + (-1 if inp.shift_down else 1)) % len(order)
            focus = order[next_index]
            self.state.vault_focus_area = focus
            mapping = {
                "search": "vault.search",
                "start": None,
                "end": None,
            }
            self.state.active_widget = mapping.get(focus)
            inp.key_tab = False
        if inp.key_enter and not self.state.active_widget:
            focus = self.state.vault_focus_area
            if focus == "source":
                self.state.open_dropdown = None if self.state.open_dropdown == "vault.source" else "vault.source"
                inp.key_enter = False
            elif focus == "clear":
                self._vault_clear_dates()
                inp.key_enter = False
                changed = True
        if self.state.vault_focus_area == "left" and not self.state.active_widget:
            direction = ""
            if inp.key_up:
                direction = "up"
                inp.key_up = False
            elif inp.key_down:
                direction = "down"
                inp.key_down = False
            elif inp.key_home:
                direction = "home"
                inp.key_home = False
            elif inp.key_end:
                direction = "end"
                inp.key_end = False
            if direction:
                changed = self._vault_move_selection(snapshot, direction) or changed
            if inp.key_enter:
                # Arrow navigation already highlights the selected row; Enter
                # confirms that row without invoking its secondary action.
                inp.key_enter = False
                changed = bool(snapshot.get("selected_id")) or changed
        focused_scroll = "vault.left" if self.state.vault_focus_area == "left" else (
            "vault.right.slack" if snapshot.get("source_type") == "slack" else "vault.right.markdown"
        )
        focused_rect = layout.left_body if self.state.vault_focus_area == "left" else layout.right_body
        if inp.key_page_up:
            self.state.scroll[focused_scroll] = max(0, int(self.state.scroll.get(focused_scroll, 0)) - focused_rect.h)
            inp.key_page_up = False
        if inp.key_page_down:
            self.state.scroll[focused_scroll] = int(self.state.scroll.get(focused_scroll, 0)) + focused_rect.h
            inp.key_page_down = False
        return changed

    def draw_vault_panel(self, rect: Rect) -> None:
        """Draw the read-only two-pane Vault browser over VaultQueryService."""
        self.r.draw_rect(rect, Palette.bg)
        snapshot = self._vault_refresh_snapshot()
        divider_fraction = self._vault_current_divider_fraction()
        layout = vault_layout_for_rect(rect, divider_fraction, line_h=self.f.line_h)
        if self._vault_handle_divider(rect, layout):
            layout = vault_layout_for_rect(rect, self._vault_current_divider_fraction(), line_h=self.f.line_h)
        toolbar_changed = self._vault_draw_toolbar(layout.toolbar)
        if toolbar_changed:
            snapshot = self._vault_refresh_snapshot(force_search=True)

        self.r.draw_rect(layout.left_header, Palette.panel3)
        self.r.draw_rect(layout.right_header, Palette.panel3)
        self.r.draw_line(layout.left_header.x, layout.left_header.y + layout.left_header.h - 1, layout.left_header.x + layout.left_header.w, layout.left_header.y + layout.left_header.h - 1, Palette.border)
        self.r.draw_line(layout.right_header.x, layout.right_header.y + layout.right_header.h - 1, layout.right_header.x + layout.right_header.w, layout.right_header.y + layout.right_header.h - 1, Palette.border)
        source_type = str(snapshot.get("source_type") or "google_calendar")
        if source_type == GOOGLE_DRIVE_SOURCE_TYPE:
            self._vault_draw_google_drive_explorer(layout, snapshot)
            self.state.top_input_capture = []
            self.state.composer_capture_rect = None
            return
        left_header = VAULT_LEFT_HEADERS.get(source_type, "ITEMS")
        right_header = VAULT_RIGHT_HEADERS.get(source_type, "DETAIL")
        left_title_rect, left_count_rect = vault_header_title_count_rects(layout.left_header)
        self._draw_card_title_text("vault.left.title", left_title_rect, left_header)
        self.widgets.clipped_text(
            left_count_rect, f"{int(snapshot.get('visible_count') or 0):,}", Palette.muted2, align="right",
        )
        right_title_w = max(88, min(layout.right_header.w // 3, 240))
        self._draw_card_title_text(
            "vault.right.title",
            Rect(layout.right_header.x + 12, layout.right_header.y, max(1, right_title_w - 12), layout.right_header.h),
            right_header,
        )
        self._vault_draw_status(layout.right_header, snapshot)

        if self.state.input.mouse_pressed and not self.state.input.mouse_consumed:
            if point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, layout.left_body):
                self.state.vault_focus_area = "left"
            elif point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, layout.right_body):
                self.state.vault_focus_area = "right"
        if self._vault_handle_keyboard(snapshot, layout):
            snapshot = self._vault_refresh_snapshot(force_search=True)
        if self._vault_draw_left_pane(layout.left_body, snapshot):
            snapshot = self._vault_refresh_snapshot(force_search=True)
        self._vault_draw_right_pane(layout.right_body, snapshot)
        self.state.top_input_capture = []
        self.state.composer_capture_rect = None


    def draw_velox_logo(self, rect: Rect) -> None:
        # Vector logo: three forward-slanted wind-swept strokes. Use one blue hue
        # with lightness variation; avoid cap rectangles so no stray horizontal
        # tick appears at small sizes.
        colors = [Color(78, 95, 232), Color(97, 113, 248), Color(125, 138, 255)]
        stroke = max(3, rect.w // 10)
        spacing = max(6, rect.w // 5)
        start_x = rect.x + max(3, rect.w // 10)
        bottom = rect.y + rect.h - 5
        top = rect.y + 5
        slant = max(7, rect.w // 4)
        for i, color in enumerate(colors):
            x1 = start_x + i * spacing
            x2 = x1 + slant
            # Center stroke plus translucent shoulder strokes for a smoother vector feel.
            self.r.draw_line(x1 - 1, bottom, x2 - 1, top, theme_alpha(color, 80))
            for off in range(stroke):
                self.r.draw_line(x1 + off, bottom, x2 + off, top, color)
            self.r.draw_line(x1 + stroke, bottom, x2 + stroke, top, theme_alpha(color, 80))

    def _activate_global_destination(self, destination: str) -> None:
        key = "chat" if destination == "brand" else normalize_active_panel(destination)
        previous = normalize_active_panel(self.state.active_panel)
        if previous == "settings" and key != "settings" and isinstance(self.state.config_draft, dict):
            self.state.active_widget = None
            self._autosave_settings_if_changed(self.state.config_draft)
        if key == "calendar" and previous != "calendar":
            self._calendar_enter()
        elif previous == "calendar" and key != "calendar":
            self._calendar_leave(key)
        if previous == "vault" and key != "vault":
            if str(self.state.active_widget or "").startswith("vault."):
                self.state.active_widget = None
            task = self.state.vault_drive_task
            if task is not None and not task.done():
                task.cancel()
            self.state.vault_drive_task = None
            self.state.vault_drive_request_key = None
            action_task = self.state.vault_drive_action_task
            if action_task is not None and not action_task.done():
                action_task.cancel()
            self.state.vault_drive_action_task = None
        if key == "chat":
            self._ensure_active_chat_selection()
        self.state.active_panel = key
        self.state.active_widget = None
        self.state.open_dropdown = None
        self.state.context_menu = None

    def _toggle_developer_mode_from_brand(self) -> bool:
        """Toggle Developer Mode and its FPS overlay together from the VELOX brand."""
        if isinstance(self.state.config_draft, dict):
            self.state.active_widget = None
            self._autosave_settings_if_changed(self.state.config_draft)
            current_ui = self.state.config_draft.get("ui", {})
        else:
            current_ui = self.services.storage.load_config_view().get("ui", {})
        next_enabled = not bool((current_ui or {}).get("developer_mode", False))

        def update(cfg: dict[str, Any]) -> None:
            ui = cfg.setdefault("ui", {})
            ui["developer_mode"] = next_enabled
            ui["show_perf_overlay"] = next_enabled

        saved = self.services.storage.update_config(update)
        self.state.config_draft = self._settings_config_to_draft(saved)
        self.state.settings_last_valid_config = copy.deepcopy(saved)
        self.state.settings_last_saved_config_json = json.dumps(
            saved, ensure_ascii=False, sort_keys=True,
        )
        self.state.developer_mode_visible = next_enabled
        return next_enabled


    def draw_application_navigation(self, rect: Rect) -> None:
        """Draw the permanent uppercase bold top-level navigation bar."""
        self.r.draw_rect(rect, Palette.panel)
        self.r.draw_rect(Rect(rect.x, rect.y + rect.h - 1, rect.w, 1), theme_alpha(Palette.white, 34))
        nav_h = max(GLOBAL_NAV_ITEM_MIN_H, min(rect.h - 6, self.f.line_h + 18))
        nav_y = rect.y + max(3, (rect.h - nav_h) // 2)
        pad_x = 14 if rect.w >= 700 else 8
        x = rect.x + pad_x

        logo_size = max(18, min(22, nav_h - 14))
        brand_font = getattr(self.widgets, "bold_font", self.f)
        brand_w = max(92, logo_size + 8 + brand_font.text_width("VELOX") + 22)
        brand_rect = Rect(x, nav_y, brand_w, nav_h)
        brand_hover = bool(
            self.widgets._can_receive_pointer("global_nav.brand")
            and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, brand_rect)
        )
        if brand_hover:
            self.state.requested_cursor = "hand"
            current_dev_mode = bool(self.state.developer_mode_visible)
            brand_tip = (
                "Disable Developer Mode and FPS overlay"
                if current_dev_mode else "Enable Developer Mode and FPS overlay"
            )
            self.widgets._queue_tooltip("global_nav.brand.tip", brand_rect, brand_tip)
        logo_rect = Rect(brand_rect.x + 10, brand_rect.y + (brand_rect.h - logo_size) // 2, logo_size, logo_size)
        self.draw_velox_logo(logo_rect)
        brand_text_rect = Rect(
            logo_rect.x + logo_rect.w + 8, brand_rect.y,
            max(1, brand_rect.x + brand_rect.w - logo_rect.x - logo_rect.w - 16), brand_rect.h,
        )
        brand_text_y = brand_text_rect.y + max(0, (brand_text_rect.h - brand_font.line_h) // 2)
        self.r.push_clip(brand_text_rect)
        self.r.draw_text_run_font(brand_font, "VELOX", brand_text_rect.x, brand_text_y, Palette.white)
        self.r.pop_clip()
        if brand_hover and self.state.input.mouse_pressed:
            self.state.input.mouse_consumed = True
            self.state.global_nav_focus_id = "brand"
            self._toggle_developer_mode_from_brand()

        divider_x = brand_rect.x + brand_rect.w + 8
        self.r.draw_rect(Rect(divider_x, nav_y + 9, 1, max(1, nav_h - 18)), theme_alpha(Palette.white, 44))
        x = divider_x + (15 if rect.w >= 700 else 9)
        navs = [
            ("agents", "DASHBOARD"), ("chat", "CHAT"), ("calendar", "CALENDAR"),
            ("context", "CONTEXT"), ("vault", "DATA"), ("settings", "SETTINGS"),
        ]
        if self.state.active_panel not in {key for key, _label in navs}:
            self.state.active_panel = "chat"

        focus_order = ["brand"] + [key for key, _label in navs]
        self.state.global_nav_focus_order = focus_order
        if self.state.global_nav_focus_id not in focus_order:
            self.state.global_nav_focus_id = None
        page_has_focus = bool(
            self.state.active_widget
            or self.state.open_dropdown
            or self.state.modal
            or self.state.file_picker_open
        )
        if self.state.input.key_tab and not page_has_focus:
            direction = -1 if self.state.input.shift_down else 1
            current = self.state.global_nav_focus_id
            if current is None:
                self.state.global_nav_focus_id = self.state.active_panel
                self.state.input.key_tab = False
            else:
                index = focus_order.index(current)
                next_index = index + direction
                if 0 <= next_index < len(focus_order):
                    self.state.global_nav_focus_id = focus_order[next_index]
                    self.state.input.key_tab = False
                elif direction < 0:
                    self.state.global_nav_focus_id = focus_order[-1]
                    self.state.input.key_tab = False
                else:
                    self.state.global_nav_focus_id = None
        if self.state.global_nav_focus_id and self.state.input.key_enter and not self.state.active_widget:
            destination = self.state.global_nav_focus_id
            self.state.input.key_enter = False
            if destination == "brand":
                self._toggle_developer_mode_from_brand()
            else:
                self._activate_global_destination(destination)

        available_right = rect.x + rect.w - pad_x
        items: list[tuple[str, str, int]] = []
        for key, label in navs:
            items.append((key, label, max(70, self.widgets._text_width(label) + (34 if rect.w >= 700 else 24))))
        total_needed = sum(width for _key, _label, width in items) + max(0, len(items) - 1) * 6
        available = max(1, available_right - x)
        if total_needed > available:
            shrink_each = int(math.ceil((total_needed - available) / max(1, len(items))))
            items = [(key, label, max(self.widgets._text_width(label) + 16, width - shrink_each)) for key, label, width in items]
        for key, label, width in items:
            if x >= available_right:
                break
            actual_w = min(width, max(1, available_right - x))
            item_rect = Rect(x, nav_y, actual_w, nav_h)
            if self.widgets.global_nav_button(
                "global_nav." + key,
                item_rect,
                label,
                active=self.state.active_panel == key,
                focused=self.state.global_nav_focus_id == key,
            ):
                self.state.global_nav_focus_id = key
                self._activate_global_destination(key)
            x += actual_w + 6


    def _load_active_turns_cached(self) -> list[dict[str, Any]]:
        """Return the active transcript without O(history) work per token batch.

        In-process revisions are authoritative for local writes because ChatStore
        already patched its stable list. Disk signatures are polled only at a
        bounded cadence to notice external recovery or manual edits.
        """
        wsid = self.state.active_scope_id
        cid = self.state.active_chat_id
        if not wsid or not cid:
            self.state.chat_turn_cache_key = None
            self.state.chat_turn_cache = []
            self.state.chat_turn_cache_identity = None
            self.state.chat_turn_seen_revision = -1
            self.state.chat_turn_changed_from_index = 0
            self.state.chat_turn_seen_running = False
            self.state.chat_turn_file_signature = (0, 0)
            self.state.chat_turn_last_stat_poll_monotonic = 0.0
            return []

        identity = (str(wsid), str(cid))
        try:
            revision = int(self.services.chats.turn_revision(wsid, cid)) if hasattr(self.services.chats, "turn_revision") else 0
        except Exception:
            revision = 0
        try:
            running = bool(getattr(self.services, "chat", None) and self.services.chat.is_running(cid))
        except Exception:
            running = False

        now_mono = time.monotonic()
        identity_changed = self.state.chat_turn_cache_identity != identity
        revision_changed = self.state.chat_turn_seen_revision != revision
        running_changed = self.state.chat_turn_seen_running != running

        if identity_changed or revision_changed or running_changed or self.state.chat_turn_cache_key is None:
            previous_revision = int(self.state.chat_turn_seen_revision)
            try:
                loader = getattr(self.services.chats, "load_turns_view", None)
                turns = loader(wsid, cid, check_disk=identity_changed) if callable(loader) else self.services.chats.load_turns(wsid, cid)
            except Exception:
                turns = self.state.chat_turn_cache if self.state.chat_turn_cache_identity == identity else []
            changed_from_index = 0
            if not identity_changed and revision_changed and previous_revision >= 0:
                change_getter = getattr(self.services.chats, "turn_change_from_index", None)
                if callable(change_getter):
                    try:
                        changed_from_index = int(
                            change_getter(wsid, cid, previous_revision)
                        )
                    except Exception:
                        changed_from_index = 0
            elif not identity_changed and not revision_changed:
                changed_from_index = len(turns)
            self.state.chat_turn_cache_identity = identity
            self.state.chat_turn_seen_revision = revision
            self.state.chat_turn_changed_from_index = int(clamp(
                changed_from_index, 0, len(turns),
            ))
            self.state.chat_turn_seen_running = running
            if identity_changed:
                self.state.chat_turn_last_stat_poll_monotonic = now_mono
            file_sig = self.state.chat_turn_file_signature
            self.state.chat_turn_cache_key = (
                wsid, cid, int(file_sig[0]), int(file_sig[1]), revision, running, "local",
            )
            self.state.chat_turn_cache = turns
            return turns

        poll_interval = CHAT_TURN_FILE_POLL_ACTIVE_SECONDS if running else CHAT_TURN_FILE_POLL_IDLE_SECONDS
        if now_mono - self.state.chat_turn_last_stat_poll_monotonic < poll_interval:
            return self.state.chat_turn_cache
        self.state.chat_turn_last_stat_poll_monotonic = now_mono

        try:
            paths = self.services.storage.paths
            main_path = paths.chat_turns_jsonl(cid)
            live_path = paths.chat_stream_snapshot_json(cid)
            try:
                main_st = main_path.stat()
                file_sig = (int(main_st.st_mtime_ns), int(main_st.st_size))
            except (FileNotFoundError, OSError):
                file_sig = (0, 0)
            try:
                live_st = live_path.stat()
                live_sig = (int(live_st.st_mtime_ns), int(live_st.st_size))
            except (FileNotFoundError, OSError):
                live_sig = (0, 0)
            key = (wsid, cid, file_sig[0], file_sig[1], live_sig[0], live_sig[1], revision, running, "disk")
            previous_key = self.state.chat_turn_cache_key
            self.state.chat_turn_file_signature = file_sig
            if previous_key == key:
                return self.state.chat_turn_cache
            loader = getattr(self.services.chats, "load_turns_view", None)
            turns = loader(wsid, cid, check_disk=True) if callable(loader) else self.services.chats.load_turns(wsid, cid)
            self.state.chat_turn_changed_from_index = 0
            self.state.chat_turn_cache_key = key
            self.state.chat_turn_cache = turns
            return turns
        except Exception:
            return self.state.chat_turn_cache

    def _activate_chat_from_list(self, chat_id: str, *, apply_search_jump: bool = True) -> None:
        chat_id = str(chat_id or "").strip()
        if not chat_id:
            return
        self._switch_active_chat(chat_id, save_current=True, reset_scroll=True, restore_composer=True)
        if apply_search_jump and self.state.chat_search_active:
            self.state.chat_jump_query = self.state.chat_search_query

    def _open_chat_workspace(self, chat_id: str, title: str = "") -> None:
        """Open one chat's durable workspace directory in the OS file explorer."""
        resolved = str(chat_id or "").strip()
        if not resolved:
            return
        try:
            workspace = self.services.storage.paths.chat_workspace_dir(resolved)
            workspace.mkdir(parents=True, exist_ok=True)
            open_local_path(workspace)
        except Exception as exc:
            label = str(title or "Chat").strip() or "Chat"
            self.state.add_toast(
                "Workspace could not be opened",
                f"{label}: {type(exc).__name__}: {exc}",
                "error",
            )

    def _handle_chat_list_context_action(self, action: dict[str, Any]) -> None:
        payload = action.get("payload") if isinstance(action.get("payload"), dict) else {}
        chat_id = str(payload.get("chat_id") or "")
        if not chat_id:
            return
        title = str(payload.get("title") or "Untitled chat")
        self._activate_chat_from_list(chat_id)
        action_name = str(action.get("action") or "")
        if action_name == "workspace":
            self._open_chat_workspace(chat_id, title)
            return
        try:
            turns = self.services.chats.load_turns(APP_SCOPE_ID, chat_id)
        except Exception as exc:
            self.state.add_toast("Chat action failed", f"{type(exc).__name__}: {exc}", "error")
            return
        if action_name == "terminals":
            self._open_terminal_dialog("chat", chat_id, f"Terminals — {title}")
        elif action_name == "statistics":
            self._open_chat_statistics_dialog(turns, title)
        elif action_name == "copy":
            self._copy_current_thread_to_clipboard(turns)
        elif action_name == "export_debug":
            self._request_chat_debug_export()
        elif action_name == "summary":
            self._open_current_chat_summary()
        elif action_name == "compact":
            summary_task = getattr(self.state, "chat_summary_task", None)
            if (not summary_task or summary_task.done()) and not self.services.chat.is_running(chat_id):
                endpoint_profile_id = self.services.chats.get_chat_endpoint_profile_id(chat_id)
                self.state.chat_summary_task = asyncio.create_task(
                    self._ui_summarize_chat(
                        APP_SCOPE_ID, chat_id, endpoint_profile_id, compact=True,
                    )
                )

    def _chat_list_is_working(self, chat_id: str) -> bool:
        resolved = str(chat_id or "").strip()
        if not resolved:
            return False
        return bool(
            self.services.chat.is_running(resolved)
            or self.services.tools.has_active_chat_tool_calls(resolved)
        )

    @staticmethod
    def _chat_activity_pulse(now_seconds: float | None = None) -> float:
        """Return the deterministic 0..1 active-chat pulse."""
        now_value = time.monotonic() if now_seconds is None else float(now_seconds)
        return 0.5 + 0.5 * math.sin(now_value * (math.tau / CHAT_ACTIVITY_PULSE_SECONDS))

    @staticmethod
    def _chat_activity_colors(active: bool, pulse: float) -> tuple[Color, Color, Color]:
        """Return fill, outer glow, and outline with a 20%-larger pulse range."""
        phase = float(clamp(float(pulse), 0.0, 1.0))
        range_scale = CHAT_ACTIVITY_GLOW_RANGE_MULTIPLIER
        if active:
            fill = theme_lerp(Palette.selected, Palette.primary_hover, 0.10 + phase * 0.16 * range_scale)
            glow = theme_alpha(Palette.accent, int(round(23 + phase * 33 * range_scale)))
            outline = theme_alpha(Palette.focus, int(round(115 + phase * 88 * range_scale)))
        else:
            fill = theme_lerp(Palette.panel, Palette.hover, 0.25 + phase * 0.42 * range_scale)
            glow = theme_alpha(Palette.white, int(round(8 + phase * 19 * range_scale)))
            outline = theme_alpha(Palette.white, int(round(35 + phase * 45 * range_scale)))
        return fill, glow, outline

    def draw_chat_list(self, rect: Rect) -> None:
        """Draw chat creation, search, and the current all/results list in one card."""
        wsid = APP_SCOPE_ID
        toolbar, list_rect = rect.split_top(58)
        new_rect = Rect(toolbar.x + 4, toolbar.y + 7, 44, 44)
        if self.widgets.button("chat.new", new_rect, "", primary=True, icon="new_chat", tooltip="New chat"):
            conv = self.services.chats.create_chat("New Chat")
            self._switch_active_chat(
                str(conv["chat_id"]), save_current=True, reset_scroll=True, restore_composer=True,
            )

        search_button_w = 44
        search_gap = 8
        search_x = new_rect.x + new_rect.w + 10
        search_button = Rect(toolbar.x + toolbar.w - search_button_w - 4, toolbar.y + 7, search_button_w, 44)
        search_input = Rect(search_x, toolbar.y + 7, max(80, search_button.x - search_gap - search_x), 44)
        self.state.chat_search_query = self.widgets.text_input(
            "chat.search.query", search_input, self.state.chat_search_query,
            "Search chats", right_padding=38,
        )
        clear_rect = Rect(search_input.x + search_input.w - 36, search_input.y + 4, 32, max(28, search_input.h - 8))
        if self.widgets.button(
            "chat.search.clear", clear_rect, "X", enabled=bool(self.state.chat_search_query or self.state.chat_search_active),
            tooltip="Clear search and show all chats",
        ):
            self.state.chat_search_query = ""
            self.state.chat_search_results = []
            self.state.chat_search_status = ""
            self.state.chat_search_active = False
            self.state.scroll["chat.list"] = 0
            if self.state.active_widget == "chat.search.query":
                self.state.text_cursors["chat.search.query"] = 0
                self.state.text_selections["chat.search.query"] = 0
        search_requested = self.widgets.button(
            "chat.search.go", search_button, "", primary=True, icon="search",
            tooltip=self.state.chat_search_status or "Search chat titles and messages",
        )
        if search_requested or (self.state.active_widget == "chat.search.query" and self.state.input.key_enter):
            self._perform_chat_search()

        all_convs = self.services.chats.list_chats_view(wsid)
        rows: list[dict[str, Any]] = []
        if self.state.chat_search_active:
            by_id = {str(conv.get("chat_id") or ""): conv for conv in all_convs}
            seen: set[str] = set()
            for hit in self.state.chat_search_results:
                cid = str(hit.get("chat_id") or "")
                if not cid or cid in seen or cid not in by_id:
                    continue
                row = dict(by_id[cid])
                row["_search_snippet"] = str(hit.get("snippet") or "")
                row["_search_role"] = str(hit.get("role") or "chat")
                rows.append(row)
                seen.add(cid)
        else:
            # The cached records are read-only here; do not clone every visible
            # chat record on every frame merely to draw it.
            rows = all_convs

        inner = list_rect
        row_h = max(68, self.f.line_h * 2 + 32)
        total_h = max(1, len(rows) * row_h + 8)
        scroll_y = int(self.state.scroll.get("chat.list", 0))
        if self.widgets._can_receive_pointer("chat.list") and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, inner) and self.state.input.wheel_y:
            scroll_y -= self.state.input.wheel_y * self.f.line_h * 3
            self.state.input.mouse_consumed = True
        scroll_y = int(clamp(scroll_y, 0, max(0, total_h - inner.h)))
        scroll_y = self.widgets._scrollbar_input("chat.list", inner, scroll_y, total_h)
        self.state.scroll["chat.list"] = scroll_y
        self.r.push_clip(inner)
        deleted_id: str | None = None
        deleted_name: str = ""
        rename_conv: dict[str, Any] | None = None
        selected_id: str | None = None
        if not rows:
            empty = "No matching chats" if self.state.chat_search_active else "No chats yet"
            self.widgets.clipped_text(Rect(inner.x + 10, inner.y + 10, max(1, inner.w - 20), 32), empty, Palette.muted2)
        for i, conv in enumerate(rows):
            cy = inner.y + 4 + i * row_h - scroll_y
            # Keep every Chat card and its rename/delete actions clear of the
            # list scrollbar. The scrollbar owns the final right-side gutter.
            rr = chat_list_row_rect(inner, int(cy), row_h)
            if rr.y + rr.h < inner.y or rr.y > inner.y + inner.h:
                continue
            cid = str(conv.get("chat_id") or "")
            active = cid == self.state.active_chat_id
            working = self._chat_list_is_working(cid)
            visible_rr = rect_intersection(rr, inner)
            hovered = bool(
                visible_rr is not None
                and self.widgets._can_receive_pointer("chat.list")
                and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, visible_rr)
            )
            if working:
                pulse = self._chat_activity_pulse()
                fill, glow_color, outline = self._chat_activity_colors(active, pulse)
                self.r.draw_round_rect(
                    Rect(rr.x - 2, rr.y - 2, rr.w + 4, rr.h + 4),
                    14, glow_color,
                )
            else:
                fill = Palette.selected if active else (Palette.hover if hovered else Palette.panel)
                outline = theme_alpha(Palette.white, 35) if hovered or active else Palette.border
            self.r.draw_round_rect(rr, 12, fill)
            self.r.draw_round_outline(rr, 12, outline)
            del_size = 44
            del_rect = Rect(rr.x + rr.w - del_size - 8, rr.y + max(4, (rr.h - del_size) // 2), del_size, del_size)
            rename_rect = Rect(max(rr.x + 8, del_rect.x - del_size - 8), del_rect.y, del_size, del_rect.h)
            text_w = max(1, rename_rect.x - rr.x - 22)
            title = str(conv.get("name") or "Chat")
            chat_title_rect = Rect(rr.x + 12, rr.y + 6, text_w, self.f.line_h + 6)
            chat_title_font = getattr(self.widgets, "bold_font", self.f)
            chat_title_display = self.widgets._truncate_to_width(title, max(1, chat_title_rect.w))
            self.r.push_clip(chat_title_rect)
            self.r.draw_text_run_font(
                chat_title_font, chat_title_display, chat_title_rect.x,
                centered_visible_text_y(chat_title_font, chat_title_display, chat_title_rect.y, chat_title_rect.h),
                Palette.white if active else Palette.text,
            )
            self.r.pop_clip()
            if hovered and chat_title_display != title:
                self.widgets._queue_tooltip(
                    f"chat.row.title.{cid}", chat_title_rect, title,
                    visible_text=chat_title_display, visible_text_fully_shown=False,
                )
            if self.state.chat_search_active:
                snippet = str(conv.get("_search_snippet") or "")
                role = str(conv.get("_search_role") or "chat").title()
                subtitle = f"{role} · {snippet}" if snippet else role
            else:
                subtitle = format_display_datetime(str(conv.get("updated_at") or ""))
            self.widgets.clipped_text(Rect(rr.x + 12, rr.y + 8 + self.f.line_h, text_w, self.f.line_h + 4), subtitle, Palette.muted2, align="left", tooltip=subtitle)
            visible_rename_rect = rect_intersection(rename_rect, inner)
            visible_delete_rect = rect_intersection(del_rect, inner)
            # Do not create hit regions below the clipped Chat-list viewport.
            # Partially visible edge rows keep their card/text but action buttons
            # appear only once the full button is inside the list viewport.
            if visible_rename_rect == rename_rect and self.widgets.button(
                f"chat.row.rename.{cid}", rename_rect, "", icon="rename",
            ):
                rename_conv = conv
                break
            if visible_delete_rect == del_rect and self.widgets.button(
                f"chat.row.delete.{cid}", del_rect, "", danger=True, icon="delete",
            ):
                deleted_id = cid
                deleted_name = title
                break
            if hovered and self.state.input.right_pressed and not self.state.input.mouse_consumed:
                running_summary = bool(
                    getattr(self.state, "chat_summary_task", None)
                    and not self.state.chat_summary_task.done()
                )
                running_chat = bool(self.services.chat.is_running(cid))
                payload = {"chat_id": cid, "title": title}
                self.widgets.open_action_context_menu(
                    "chat.list.actions",
                    [
                        {"action": "workspace", "label": "Open workspace", "payload": payload},
                        {"action": "terminals", "label": "View terminals", "payload": payload},
                        {"action": "statistics", "label": "View statistics", "payload": payload},
                        {"action": "copy", "label": "Copy formatted thread", "payload": payload},
                        {"action": "export_debug", "label": "Export chat debug report", "payload": payload},
                        {
                            "action": "summary", "label": "Show or refresh summary",
                            "enabled": not running_summary, "payload": payload,
                        },
                        {
                            "action": "compact", "label": "Compact older context",
                            "enabled": not running_summary and not running_chat, "payload": payload,
                        },
                    ],
                )
            if hovered and self.state.input.mouse_pressed and not self.state.input.mouse_consumed:
                self.state.input.mouse_consumed = True
                selected_id = cid
        self.r.pop_clip()
        self.widgets._scrollbar_draw("chat.list", inner, scroll_y, total_h)
        context_action = self.widgets.consume_context_action("chat.list.actions")
        if context_action:
            self._handle_chat_list_context_action(context_action)
        elif rename_conv:
            self.state.modal = {"kind": "rename_chat", "title": "Rename chat", "chat_id": str(rename_conv.get("chat_id") or ""), "name": str(rename_conv.get("name") or "Chat"), "error": ""}
        elif deleted_id:
            self._request_chat_delete(deleted_id, deleted_name)
        elif selected_id:
            self._activate_chat_from_list(selected_id)


    @staticmethod
    def _chat_column_divider_hit_rect(divider: Rect) -> Rect:
        center_x = divider.x + divider.w // 2
        return Rect(
            center_x - CHAT_DIVIDER_HOVER_HALF_PX, divider.y,
            CHAT_DIVIDER_HOVER_HALF_PX * 2 + 1, divider.h,
        )

    def handle_chat_column_divider(self, rect: Rect, layout: ChatUILayout) -> bool:
        """Handle the persisted Chat-list/main-column horizontal resize affordance.

        SDL can deliver press, motion, and release in one poll when a long Chat
        frame takes longer to render. Use the preserved edge coordinates so that
        coalesced input still starts, applies, and consumes the divider drag.
        """
        inp = self.state.input
        active = bool(self.state.chat_column_divider_dragging)
        hit = self._chat_column_divider_hit_rect(layout.divider)
        hovered = point_in_rect(inp.mouse_x, inp.mouse_y, hit)
        press_x = inp.mouse_press_x if inp.mouse_press_x >= 0 else inp.mouse_x
        press_y = inp.mouse_press_y if inp.mouse_press_y >= 0 else inp.mouse_y
        pressed_on_divider = bool(
            inp.mouse_pressed and point_in_rect(press_x, press_y, hit)
        )
        if hovered or active or pressed_on_divider:
            self.state.requested_cursor = "resize_x"
        if not active and pressed_on_divider and not inp.mouse_consumed:
            self.state.chat_column_divider_dragging = True
            active = True
            inp.mouse_consumed = True

        changed = False
        if active:
            if inp.mouse_down or inp.mouse_released:
                drag_x = (
                    inp.mouse_release_x
                    if inp.mouse_released and inp.mouse_release_x >= 0
                    else inp.mouse_x
                )
                requested = drag_x - rect.x - CHAT_COLUMN_GAP_PX // 2
                resolved = chat_layout_for_rect(rect, chat_list_width=requested).chats.w
                if resolved != int(self.state.chat_list_width):
                    self.state.chat_list_width = resolved
                    changed = True
                # Consume both motion and release so the transcript underneath
                # cannot interpret the completed divider drag as a click/scroll.
                inp.mouse_consumed = True
            if not inp.mouse_down:
                self.state.chat_column_divider_dragging = False
                active = False

        center_x = layout.divider.x + layout.divider.w // 2
        self.r.draw_rect(
            Rect(center_x, layout.divider.y, 1, layout.divider.h),
            Palette.accent if hovered or active or pressed_on_divider else theme_alpha(Palette.border, 155),
        )
        return changed

    @staticmethod
    def _composer_divider_hit_rect(divider: Rect) -> Rect:
        center_y = divider.y + divider.h // 2
        return Rect(
            divider.x, center_y - CHAT_STACK_DIVIDER_HOVER_HALF_PX,
            divider.w, CHAT_STACK_DIVIDER_HOVER_HALF_PX * 2 + 1,
        )

    def handle_composer_divider(
        self, owner: str, rect: Rect, layout: ChatStackLayout,
    ) -> bool:
        """Resize Chat or Calendar composer vertically, taking space from output above."""
        resolved_owner = "calendar" if str(owner) == "calendar" else "chat"
        inp = self.state.input
        active_owner = str(self.state.composer_divider_dragging or "")
        active = active_owner == resolved_owner
        hit = self._composer_divider_hit_rect(layout.divider)
        hovered = point_in_rect(inp.mouse_x, inp.mouse_y, hit)
        if hovered or active:
            self.state.requested_cursor = "resize_y"
        if not active_owner and hovered and inp.mouse_pressed and not inp.mouse_consumed:
            self.state.composer_divider_dragging = resolved_owner
            active = True
            inp.mouse_consumed = True

        changed = False
        if active:
            if inp.mouse_down:
                requested = rect.y + rect.h - inp.mouse_y - layout.divider.h // 2
                resolved = chat_stack_layout_for_rect(
                    rect, header_height=layout.header.h, composer_height=requested,
                    gap=layout.divider.h,
                ).composer_height
                field = (
                    "calendar_chat_composer_height"
                    if resolved_owner == "calendar" else "chat_composer_height"
                )
                if resolved != int(getattr(self.state, field)):
                    setattr(self.state, field, resolved)
                    changed = True
                inp.mouse_consumed = True
            else:
                self.state.composer_divider_dragging = ""
                active = False

        center_y = layout.divider.y + layout.divider.h // 2
        self.r.draw_rect(
            Rect(layout.divider.x, center_y, layout.divider.w, 1),
            Palette.accent if hovered or active else theme_alpha(Palette.border, 155),
        )
        return changed

    def _perform_chat_search(self, query: str | None = None) -> None:
        q = str(self.state.chat_search_query if query is None else query).strip()
        self.state.chat_search_query = q
        self.state.chat_search_results = []
        self.state.scroll["chat.list"] = 0
        if not q:
            self.state.chat_search_active = False
            self.state.chat_search_status = ""
            return
        self.state.chat_search_active = True
        try:
            self.state.chat_search_results = SearchService(self.services.storage).search_chats(q, limit=80)
            unique_count = len({str(row.get("chat_id") or "") for row in self.state.chat_search_results if row.get("chat_id")})
            self.state.chat_search_status = f"{unique_count} matching chat(s)"
        except Exception as exc:
            self.state.chat_search_status = f"{type(exc).__name__}: {exc}"

    @staticmethod
    def _agent_status_color(status: str) -> Color:
        return {
            "queued": Palette.muted,
            "waiting": Palette.muted2,
            "running": Palette.accent,
            "inference": Palette.accent,
            "stalled": Palette.warn,
            "retrying": Palette.warn,
            "tool": Palette.accent2,
            "pausing": Palette.warn,
            "paused": Palette.warn,
            "ready": Palette.muted2,
            "completed": Palette.ok,
            "succeeded": Palette.ok,
            "failed": Palette.danger,
            "cancelled": Palette.warn,
        }.get(str(status or "").lower(), Palette.muted2)

    def _agent_progress_text(self, agent: dict[str, Any]) -> str:
        status = str(agent.get("status") or "queued").lower()
        message = str(agent.get("progress_message") or "").strip()
        percent = agent.get("progress_percent")
        if percent is not None:
            try:
                lead = f"{int(clamp(int(percent), 0, 100))}%"
            except Exception:
                lead = status.title()
        else:
            lead = "0%" if status not in AGENT_TERMINAL_STATUSES else status.title()
        if message and message.lower() not in {lead.lower(), status, "queued", "running", "paused", "completed", "failed", "cancelled"}:
            return f"{lead} — {message}"
        return lead

    def _open_agent_details(self, agent_id: str) -> None:
        agent_id = str(agent_id or "").strip()
        if not agent_id:
            return
        try:
            self.services.agents.load_agent(agent_id)
        except Exception as exc:
            self.state.add_toast("Agent unavailable", f"{type(exc).__name__}: {exc}", "error")
            return
        self.state.selected_agent_id = agent_id
        self.state.modal = {"kind": "agent_details", "agent_id": agent_id, "tab": "output"}


    def _agent_statistics_tooltip_for_id(self, agent_id: str) -> str:
        resolved = str(agent_id or "").strip()
        now = time.monotonic()
        cache = getattr(self, "_agent_statistics_tooltip_cache", None)
        if not isinstance(cache, dict):
            cache = {}
            self._agent_statistics_tooltip_cache = cache
        cached = cache.get(resolved)
        if isinstance(cached, tuple) and len(cached) == 2 and now - float(cached[0]) < 1.0:
            return str(cached[1])
        agent, events = self._agent_record_with_events(resolved)
        text = agent_statistics_tooltip(agent, events)
        cache[resolved] = (now, text)
        if len(cache) > 128:
            oldest = sorted(cache.items(), key=lambda row: float(row[1][0]))[:32]
            for key, _value in oldest:
                cache.pop(key, None)
        return text

    def _agent_record_with_events(self, agent_id: str) -> tuple[dict[str, Any], list[dict[str, Any]]]:
        resolved = str(agent_id or "").strip()
        if not resolved:
            raise ValueError("agent_id is required")
        agent = self.services.agents.load_agent(resolved)
        events = self.services.agents.load_transcript(resolved)
        return agent, events

    def _open_agent_statistics_dialog(self, agent_id: str) -> None:
        try:
            agent, events = self._agent_record_with_events(agent_id)
        except Exception as exc:
            self.state.add_toast("Agent statistics unavailable", f"{type(exc).__name__}: {exc}", "error")
            return
        summary_text = agent_statistics_text(agent, events)
        tool_rows = agent_tool_statistics_rows(agent)
        self.state.modal = {
            "kind": "agent_statistics",
            "title": "Agent Statistics",
            "summary_text": summary_text,
            "tool_rows": tool_rows,
            "copy_text": self._chat_statistics_clipboard_text(summary_text, tool_rows),
        }
        self.state.scroll["modal.chat.statistics.text"] = 0
        self.state.scroll["modal.chat.statistics.tools"] = 0


    def _open_agent_source_chat(self, agent_id: str) -> None:
        try:
            agent = self.services.agents.load_agent(str(agent_id or ""))
            source_chat_id = str(agent.get("source_chat_id") or "")
            chat = self.services.chats.load_chat(APP_SCOPE_ID, source_chat_id)
        except Exception as exc:
            self.state.add_toast("Source chat unavailable", f"{type(exc).__name__}: {exc}", "error")
            return
        if str(chat.get("chat_kind") or "") == "week":
            day_value = str(chat.get("week_start_date") or self.state.calendar_selected_date)
            try:
                self._calendar_set_selected_date(day_value)
            except Exception:
                self.state.calendar_selected_date = day_value
            self._activate_global_destination("calendar")
        else:
            self._activate_global_destination("chat")
            self._activate_chat_from_list(source_chat_id, apply_search_jump=False)

    def _agent_row_context_items(
        self, agent: dict[str, Any], *, include_source_chat: bool = False,
    ) -> list[dict[str, Any]]:
        status = str(agent.get("status") or "queued")
        pause_requested = bool(agent.get("pause_requested"))
        paused = status == "paused" or pause_requested
        active = status not in AGENT_TERMINAL_STATUSES
        deletable = status in AGENT_DELETABLE_STATUSES and not pause_requested
        payload = {"agent_id": str(agent.get("agent_id") or "")}
        items = [
            {"action": "view", "label": "View output", "payload": payload},
            {"action": "terminals", "label": "View terminals", "payload": payload},
            {"action": "statistics", "label": "Statistics", "payload": payload},
            {"action": "export_debug", "label": "Copy debug report", "payload": payload},
            {
                "action": "resume" if paused else "pause",
                "label": "Unpause agent execution" if paused else "Pause agent execution",
                "enabled": active or paused,
                "separator_before": True,
                "payload": payload,
            },
            {"action": "cancel", "label": "Cancel agent", "enabled": active, "danger": True, "payload": payload},
            {"action": "delete", "label": "Delete agent", "enabled": deletable, "danger": True, "payload": payload},
        ]
        if include_source_chat and str(agent.get("source_chat_id") or ""):
            items.insert(4, {
                "action": "open_source_chat", "label": "Open source chat",
                "separator_before": True, "payload": payload,
            })
            items[5]["separator_before"] = False
        return items

    def _handle_agent_row_action(self, agent_id: str, action_name: str) -> None:
        resolved = str(agent_id or "").strip()
        action = str(action_name or "").strip()
        if not resolved or not action:
            return
        try:
            agent = self.services.agents.load_agent(resolved)
            title = str(agent.get("title") or "Background agent")
            if action == "view":
                self._open_agent_details(resolved)
            elif action == "terminals":
                self._open_terminal_dialog("agent", resolved, f"Terminals — {title}")
            elif action == "statistics":
                self._open_agent_statistics_dialog(resolved)
            elif action == "export_debug":
                self._request_agent_debug_export(resolved)
            elif action == "pause":
                self.services.agent_runtime.pause(resolved)
            elif action == "resume":
                self.services.agent_runtime.resume(resolved)
            elif action == "cancel":
                self.services.agent_runtime.cancel(resolved)
            elif action == "delete":
                self._request_agent_delete(resolved)
            elif action == "open_source_chat":
                self._open_agent_source_chat(resolved)
        except Exception as exc:
            self.state.add_toast("Agent action failed", f"{type(exc).__name__}: {exc}", "error")

    def _open_terminal_dialog(self, owner_type: str, owner_id: str, title: str = "") -> None:
        owner_type = str(owner_type or "").strip().lower()
        owner_id = str(owner_id or "").strip()
        if owner_type not in {"chat", "agent"} or not owner_id:
            return
        try:
            if owner_type == "chat":
                self.services.chats.load_chat(APP_SCOPE_ID, owner_id)
                heading = str(title or "Chat terminals")
            else:
                agent = self.services.agents.load_agent(owner_id)
                heading = str(title or agent.get("title") or "Agent terminals")
        except Exception as exc:
            self.state.add_toast("Terminals unavailable", f"{type(exc).__name__}: {exc}", "error")
            return
        # Terminal viewers always open newest-first. The user may still sort a
        # different column while the dialog remains open.
        self.state.table_sort["modal.terminals.list"] = ("started", False)
        self.state.modal = {
            "kind": "terminals",
            "owner_type": owner_type,
            "owner_id": owner_id,
            "title": heading,
            "active_only": False,
            "selected_terminal_id": "",
            "view_tab": "screen",
            "transcript_signature": None,
            "transcript_text": "",
            "transcript_truncated": False,
            "screen_signature": None,
            "screen_text": "",
            "terminal_input": "",
            "terminal_sensitive": False,
            "terminal_key": "ctrl_c",
            "terminal_columns": "",
            "terminal_rows": "",
            "error": "",
        }

    @staticmethod
    def _expert_mode_table_columns() -> list[dict[str, Any]]:
        """Structural order is fixed: a requirement can never sort away from its steps."""
        return [
            {"key": "expand", "title": "", "width": 28, "fixed_width": 28, "sortable": False},
            {"key": "status", "title": "", "width": 34, "fixed_width": 34, "sortable": False, "align": "center"},
            {"key": "requirement_id", "title": "ID", "width": 100, "fixed_width": 100, "sortable": False},
            {"key": "requirement", "title": "Requirement / Step", "min_width": 170, "sortable": False},
            {"key": "progress", "title": "Progress / Result", "min_width": 170, "sortable": False},
        ]

    @staticmethod
    def _expert_mode_table_rows(state: dict[str, Any] | None, collapsed: set[str] | None = None) -> list[dict[str, Any]]:
        """Read-only two-level rows with the same state markers for requirements/steps."""
        output: list[dict[str, Any]] = []
        collapsed = collapsed or set()
        for row, parent_id in checklist_presentation_items(state):
            if parent_id in collapsed:
                continue
            item_state = str(row.get("state") or CHECKLIST_ITEM_NOT_STARTED)
            item_id = str(row.get("id") or "")
            marker, color = {
                CHECKLIST_ITEM_VERIFIED: ("\u2713", Palette.warn),
                CHECKLIST_ITEM_DONE: ("\u2713", Palette.ok),
                CHECKLIST_ITEM_IN_PROGRESS: ("\u25cf", Palette.white),
            }.get(item_state, ("", Palette.muted2))
            state_label = item_state.replace("_", " ").upper()
            children = row.get("subitems") or []
            step_counts = checklist_presentation_counts(children)
            finished = step_counts[CHECKLIST_ITEM_DONE] + step_counts[CHECKLIST_ITEM_VERIFIED]
            progress = str(row.get("latest_comment") or "")
            if children:
                progress = f"Steps {finished}/{len(children)} complete" + (" - " + progress if progress else "")
            kind = f"Implementation step of {parent_id}" if parent_id else "Original requirement / acceptance criterion"
            details = [f"{item_id}: {kind}", "State: " + state_label, str(row.get("text") or "")]
            if children:
                details.append("Implementation steps: " + _checklist_progress_text(step_counts))
                details.append("Finishing the steps does not automatically accept the requirement.")
            if row.get("latest_comment"):
                details.append("Latest comment: " + str(row["latest_comment"]))
            tooltip = "\n".join(details)
            output.append({
                "id": item_id, "_parent_id": parent_id, "_depth": 1 if parent_id else 0,
                "expand": {"type": "disclosure", "expanded": item_id not in collapsed,
                           "action": "toggle_subitems", "tooltip": "Expand implementation steps" if item_id in collapsed else "Collapse implementation steps"} if children else "",
                "status": {"type": "status_icon", "icon": "check" if item_state in (CHECKLIST_ITEM_DONE, CHECKLIST_ITEM_VERIFIED) else "dot" if item_state == CHECKLIST_ITEM_IN_PROGRESS else "",
                           "label": marker, "color": color, "tooltip": state_label},
                "requirement_id": {"label": item_id, "color": Palette.muted2 if parent_id else Palette.text, "tooltip": kind},
                "requirement": {"label": str(row.get("text") or ""), "indent": 18 if parent_id else 0,
                                "tree_branch": bool(parent_id), "tooltip": tooltip},
                "progress": {"label": progress, "tooltip": tooltip},
                "_tooltip": tooltip,
            })
        return output

    @staticmethod
    def _expert_mode_summary(state: dict[str, Any] | None) -> str:
        if not state or "items" not in state:
            return "NOT ACTIVE"
        lifecycle = str(state.get("lifecycle") or "open").replace("_", " ").upper()
        if lifecycle == "OPEN":
            lifecycle = "ACTIVE" if state.get("active") else "OPEN"
            review = str(state.get("review_status") or "idle")
            if review in ("requested", "running", "error", "cancelled", "failed"):
                lifecycle += " / REVIEW " + review.upper()
        requirements = (state or {}).get("counts")
        steps = (state or {}).get("subitem_counts")
        if not isinstance(requirements, dict) or not isinstance(steps, dict):
            rows = checklist_presentation_items(state)
            requirements = checklist_presentation_counts(item for item, parent in rows if not parent)
            steps = checklist_presentation_counts(item for item, parent in rows if parent)
        def progress(counts: dict[str, int]) -> str:
            return f"{counts['done'] + counts['verified']}/{counts['total']}"
        return f"{lifecycle} \u00b7 REQUIREMENTS {progress(requirements)} \u00b7 STEPS {progress(steps)}"

    @staticmethod
    def _expert_mode_summary_tooltip(state: dict[str, Any] | None) -> str:
        requirements = (state or {}).get("counts")
        steps = (state or {}).get("subitem_counts")
        if not isinstance(requirements, dict) or not isinstance(steps, dict):
            rows = checklist_presentation_items(state)
            requirements = checklist_presentation_counts(item for item, parent in rows if not parent)
            steps = checklist_presentation_counts(item for item, parent in rows if parent)
        return (Panels._expert_mode_summary(state) + "\n"
                "Progress fractions count done or verified items. Checklist completion requires independent verification.\n"
                "Requirements: " + _checklist_progress_text(requirements) + "\n"
                "Implementation steps: " + _checklist_progress_text(steps) + "\n"
                "Blank: not started. White dot: in progress. Green check: done. Gold check: independently verified.")

    @staticmethod
    def _checklist_display_name(state: dict[str, Any] | None) -> str:
        if not isinstance(state, dict):
            return "No active checklist"
        return checklist_display_label(
            state.get("name") or state.get("checklist_name") or "Checklist",
            state.get("created_at"),
        )

    def _draw_expert_mode_table(self, widget_id: str, rect: Rect, state: dict[str, Any] | None) -> None:
        """Virtualized nested table; disclosure/selection affect presentation only."""
        checklist_id = str((state or {}).get("checklist_id") or "")
        views = getattr(self, "_checklist_table_views", None)
        if views is None:
            views = self._checklist_table_views = {}
        view = views.setdefault(widget_id, {})
        if view.get("checklist_id") != checklist_id:
            view.clear()
            view.update(checklist_id=checklist_id, collapsed=set(), selected=None)
            self.state.scroll.pop(widget_id, None)
        # UI snapshots are immutable and identity-stable between refreshes.
        collapsed = view["collapsed"]
        key = (id(state), frozenset(collapsed))
        if view.get("row_key") != key or view.get("source") is not state:
            view["rows"] = self._expert_mode_table_rows(state, collapsed)
            view["row_key"], view["source"] = key, state
        rows = view["rows"]
        if not rows:
            message = "Checklist is not active for this Task." if not state else "No checklist items are available."
            self.widgets.clipped_text(Rect(rect.x + 8, rect.y + 6, max(1, rect.w - 16), max(34, self.f.line_h + 12)),
                                      message, Palette.muted2, tooltip=message)
            return
        # Discard any sort persisted by the former flat table, including descending ID.
        self.state.table_sort[widget_id] = ("", True)
        view["selected"], action = self.widgets.table_view(
            widget_id, rect, self._expert_mode_table_columns(), rows, view.get("selected"),
            id_key="id", row_h=max(32, self.f.line_h + 10), double_click_action="toggle_subitems")
        if action and action[1] == "toggle_subitems":
            item_id = action[0]
            parent = next((row for row in (state or {}).get("items", []) if row.get("id") == item_id), None)
            if parent and parent.get("subitems"):
                if item_id in collapsed:
                    collapsed.remove(item_id)
                else:
                    collapsed.add(item_id)
                view["selected"] = item_id

    @staticmethod
    def _chat_checklist_owner(chat_id: str) -> dict[str, Any]:
        return {"owner_kind": "chat", "chat_id": str(chat_id or ""), "agent_id": "", "task_run_id": 0}

    def _dashboard_checklist_owner(
        self, record: dict[str, Any],
    ) -> tuple[dict[str, Any] | None, str]:
        task_type, chat_id, agent_id, _workspace_chat_id = self._dashboard_task_context_ids(record)
        try:
            if task_type == "Chat" and chat_id:
                return self._chat_checklist_owner(chat_id), ""
            if task_type == "Agent" and agent_id:
                metadata = record.get("metadata") if isinstance(record.get("metadata"), dict) else {}
                agent = self.services.agents.load_agent(agent_id)
                source_chat_id = str(chat_id or agent.get("source_chat_id") or "").strip()
                task_run_id = int(metadata.get("agent_task_run_id") or agent.get("task_run_id") or 0)
                if not source_chat_id:
                    return None, "Agent Checklist history requires its source Chat identity."
                if task_run_id <= 0:
                    return None, "Agent Checklist history requires a valid Task Run ID."
                return {
                    "owner_kind": "agent", "chat_id": source_chat_id,
                    "agent_id": str(agent_id), "task_run_id": task_run_id,
                }, ""
            return None, "Checklist applies only to Chat and Agent Tasks."
        except Exception as exc:
            return None, f"{type(exc).__name__}: {exc}"

    def _checklist_ui_snapshot(self, owner: dict[str, Any]) -> tuple[dict[str, Any] | None, str]:
        """Single-flight, bounded live-view reads; large plans never parse in draw."""
        cache = getattr(self, "_checklist_ui_cache", None)
        if cache is None:
            cache = self._checklist_ui_cache = collections.OrderedDict()
        key = (owner.get("owner_kind"), owner.get("chat_id"), owner.get("agent_id"), owner.get("task_run_id"))
        entry = cache.setdefault(key, {"snapshot": None, "error": "", "loaded_at": 0.0})
        cache.move_to_end(key)
        while len(cache) > 8:
            _key, evicted = cache.popitem(last=False)
            task = evicted.get("task")
            if isinstance(task, asyncio.Task) and not task.done():
                task.cancel()
        task = entry.get("task")
        if isinstance(task, asyncio.Task) and task.done():
            entry.pop("task", None)
            try:
                entry["snapshot"] = task.result()
                entry["error"] = ""
            except asyncio.CancelledError:
                pass
            except Exception as exc:
                entry["error"] = f"{type(exc).__name__}: {exc}"
            entry["loaded_at"] = time.monotonic()
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            # Deterministic noninteractive callers can consume the same projection.
            try:
                entry["snapshot"] = ChecklistStore(self.services.storage).ui_snapshot(owner, entry["snapshot"])
                entry["error"] = ""
            except Exception as exc:
                entry["error"] = f"{type(exc).__name__}: {exc}"
        else:
            if not entry.get("task") and time.monotonic() - entry["loaded_at"] >= 0.5:
                task = loop.create_task(asyncio.to_thread(
                    ChecklistStore(self.services.storage).ui_snapshot, dict(owner), entry["snapshot"]),
                    name="velox-checklist-ui-snapshot")
                task.add_done_callback(self._observe_background_task)
                entry["task"] = task
        return entry["snapshot"], entry["error"]

    def _load_chat_expert_mode_state_for_ui(self) -> tuple[dict[str, Any] | None, str]:
        chat_id = str(self.state.active_chat_id or "").strip()
        if not chat_id:
            return None, ""
        snapshot, error = self._checklist_ui_snapshot(self._chat_checklist_owner(chat_id))
        if snapshot is None:
            return None, error
        return next((row for row in snapshot["checklists"] if row.get("active")), None), error

    def _load_chat_checklist_selector_for_ui(
        self,
    ) -> tuple[dict[str, Any] | None, list[str], dict[str, str], str, str]:
        """Load every Chat checklist oldest-first and resolve the per-Chat UI selection."""
        chat_id = str(self.state.active_chat_id or "").strip()
        if not chat_id:
            return None, [], {}, "", ""
        try:
            owner = self._chat_checklist_owner(chat_id)
            listing, error = self._checklist_ui_snapshot(owner)
            if error:
                return None, [], {}, "", error
            if listing is None:
                return None, [], {}, "Loading Checklists...", ""
            rows = [row for row in (listing.get("checklists") or []) if isinstance(row, dict)]
            # ChecklistStore already guarantees oldest-created first. Keep the UI
            # defensive because dropdown ordering is user-visible and must never
            # depend on collection insertion order.
            rows.sort(key=lambda row: (str(row.get("created_at") or "9999"), str(row.get("checklist_id") or "")))
            options: list[str] = []
            label_to_id: dict[str, str] = {}
            id_to_label: dict[str, str] = {}
            label_seen: dict[str, int] = {}
            for row in rows:
                checklist_id = str(row.get("checklist_id") or "")
                base_label = str(row.get("display_name") or checklist_display_label(row.get("name") or "Checklist", row.get("created_at")))
                label_seen[base_label] = label_seen.get(base_label, 0) + 1
                occurrence = label_seen[base_label]
                # Normally the second-resolution timestamp makes labels unique.
                # Preserve a deterministic mapping even if two lists with the same
                # LLM name are created during the same second.
                label = base_label if occurrence == 1 else f"{base_label} ({occurrence})"
                options.append(label)
                label_to_id[label] = checklist_id
                id_to_label[checklist_id] = label
            selected_by_chat = getattr(self.state, "chat_selected_checklist_ids", None)
            if not isinstance(selected_by_chat, dict):
                selected_by_chat = {}
                self.state.chat_selected_checklist_ids = selected_by_chat
            selected_id = str(selected_by_chat.get(chat_id) or "")
            prior_selected_id = selected_id
            valid_ids = set(id_to_label)
            if selected_id not in valid_ids:
                active_id = str(listing.get("active_checklist_id") or "")
                selected_id = active_id if active_id in valid_ids else (str(rows[-1].get("checklist_id") or "") if rows else "")
                if selected_id:
                    selected_by_chat[chat_id] = selected_id
                else:
                    selected_by_chat.pop(chat_id, None)
            # Follow new active work until the user deliberately browses history.
            # Completing/stopping a list does not erase the last automatic choice.
            follow = getattr(self, "_checklist_auto_selection", None)
            if follow is None:
                follow = self._checklist_auto_selection = {}
            active_id = str(listing.get("active_checklist_id") or "")
            if prior_selected_id not in valid_ids or (active_id and selected_id == active_id):
                follow[chat_id] = selected_id
            elif active_id in valid_ids and selected_id == follow.get(chat_id):
                selected_id = active_id
                selected_by_chat[chat_id] = selected_id
                follow[chat_id] = selected_id
            selected_label = id_to_label.get(selected_id, "")
            state = next((row for row in rows if row.get("checklist_id") == selected_id), None)
            return state, options, label_to_id, selected_label, ""
        except Exception as exc:
            return None, [], {}, "", f"{type(exc).__name__}: {exc}"

    def _dashboard_expert_mode_state(self, record: dict[str, Any]) -> tuple[dict[str, Any] | None, str]:
        owner, error = self._dashboard_checklist_owner(record)
        if owner is None:
            return None, error
        snapshot, error = self._checklist_ui_snapshot(owner)
        if snapshot is None:
            return None, error
        rows = snapshot["checklists"]
        # A finished/stopped task still has an inspectable final checklist.
        return next((row for row in rows if row.get("active")), rows[-1] if rows else None), error

    @staticmethod
    def _expert_mode_history_label(entry: dict[str, Any], ordinal: int) -> str:
        when = format_display_datetime(
            str(entry.get("completed_at") or entry.get("updated_at") or entry.get("created_at") or "")
        ) or f"Report {ordinal}"
        prefix = "Current" if bool(entry.get("active")) else when
        counts = entry.get("counts") if isinstance(entry.get("counts"), dict) else {}
        status = str(entry.get("lifecycle") or "open").replace("_", " ").upper()
        name = str(entry.get("name") or "Checklist")
        return (
            f"{prefix} · {name} · {status} · "
            f"{int(counts.get(CHECKLIST_ITEM_VERIFIED) or 0)}/{int(counts.get('total') or 0)} VERIFIED · #{ordinal}"
        )

    def _expert_mode_history_store_for_modal(
        self, modal: dict[str, Any],
    ) -> tuple[Any | None, dict[str, Any] | None, str, str]:
        task_id = str(modal.get("task_id") or "").strip()
        if task_id:
            record = self._dashboard_task_record(task_id)
            title = str(record.get("title") or record.get("description") or modal.get("title") or "Task")
            owner, error = self._dashboard_checklist_owner(record)
            return (ChecklistStore(self.services.storage) if owner is not None else None), owner, title, error
        chat_id = str(modal.get("chat_id") or "").strip()
        if not chat_id:
            return None, None, str(modal.get("title") or "Chat"), "Chat identity is unavailable."
        try:
            chat = self.services.chats.load_chat(APP_SCOPE_ID, chat_id)
            title = str(chat.get("name") or modal.get("title") or "Chat")
            owner = self._chat_checklist_owner(chat_id)
            return ChecklistStore(self.services.storage), owner, title, ""
        except Exception as exc:
            return None, None, str(modal.get("title") or "Chat"), f"{type(exc).__name__}: {exc}"

    def _export_checklist_report(self, owner: dict[str, Any], title: str) -> Path:
        """Write the same canonical nested Markdown used by history as one HTML page."""
        store = ChecklistStore(self.services.storage)
        entries = store.history_reports(owner)
        markdown_text = checklist_history_report_markdown(title, entries)
        html_text = checklist_history_report_html(markdown_text, title=f"Checklist History - {title}")
        # Share the existing owner transaction lock with deletion. A late export
        # cannot recreate a removed Chat/Agent directory after reading its history.
        with _CHECKLIST_LOCK, DATA_ROOTS.lock_for_path(store._collection_path(owner)):
            _require_durable_owner(store._collection_path(owner))
            if owner.get("owner_kind") == "agent":
                report_path = store._owner_dir(owner) / f"checklist-history-run-{int(owner['task_run_id'])}.html"
            else:
                workspace = self.services.storage.paths.chat_workspace_dir(str(owner["chat_id"]))
                workspace.mkdir(parents=True, exist_ok=True)
                report_path = workspace / "checklist-history-report.html"
            atomic_write_text(report_path, html_text)
        open_local_path(report_path)
        return report_path

    def _export_chat_checklist_report(self, chat_id: str, title: str) -> Path:
        if not str(chat_id or "").strip():
            raise ValueError("Chat identity is unavailable.")
        return self._export_checklist_report(self._chat_checklist_owner(chat_id), title)

    def _request_checklist_export(self, owner: dict[str, Any], title: str) -> None:
        """Keep history reads, Markdown/HTML conversion and filesystem writes off draw."""
        tasks = getattr(self, "_checklist_export_tasks", None)
        if tasks is None:
            tasks = self._checklist_export_tasks = {}
        key = tuple(owner.get(k) for k in ("owner_kind", "chat_id", "agent_id", "task_run_id"))
        if key in tasks and not tasks[key].done():
            return
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            self._export_checklist_report(owner, title)
            return
        async def export() -> None:
            try:
                path = await asyncio.to_thread(self._export_checklist_report, dict(owner), title)
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                self.state.add_toast("Checklist export failed", f"{type(exc).__name__}: {exc}", "error")
            finally:
                tasks.pop(key, None)
        task = loop.create_task(export(), name="velox-checklist-export")
        tasks[key] = task
        task.add_done_callback(self._observe_background_task)

    def _draw_chat_expert_mode(self, rect: Rect, *, active_tab: Rect | None = None) -> None:
        """Draw the selected Chat's live Checklist content for the Lists tab."""
        self.r.draw_card(rect, radius=12, fill=Palette.panel)
        self._erase_chat_tab_body_seam(rect, active_tab)
        inner = rect.inset(10)
        layout = checklist_card_header_layout(inner, self.f.line_h)
        state, checklist_options, checklist_label_to_id, selected_checklist_label, error = self._load_chat_checklist_selector_for_ui()
        self._draw_card_title_text(
            "chat.expert_mode.title", layout.title, "CHECKLISTS",
        )
        chat_id = str(self.state.active_chat_id or "").strip()
        title = "Chat"
        if chat_id:
            try:
                title = str(self.services.chats.load_chat(APP_SCOPE_ID, chat_id).get("name") or title)
            except Exception:
                pass
        if self.widgets.button(
            "chat.expert_mode.export", layout.export_button,
            "", icon="checklist_export", enabled=bool(chat_id), tooltip="Export Checklist history page",
        ):
            try:
                self._request_checklist_export(self._chat_checklist_owner(chat_id), title)
            except Exception as exc:
                self.state.add_toast("Checklist export failed", f"{type(exc).__name__}: {exc}", "error")
        if self.widgets.button(
            "chat.expert_mode.history", layout.history_button,
            "", icon="expert_history", enabled=bool(chat_id), tooltip="Checklist history",
        ):
            self.state.modal = {
                "kind": "expert_mode_history", "chat_id": chat_id, "title": title,
            }
            self.state.scroll.pop("modal.expert_mode_history.report", None)
        selector_value = selected_checklist_label or ("Checklist state unavailable" if error else "No checklists")
        next_label = self.widgets.dropdown(
            "chat.expert_mode.checklist_selector",
            layout.name,
            selector_value,
            checklist_options,
            enabled=bool(checklist_options) and not bool(error),
            tooltip=error or "View the active Checklist or a historical record; selection does not change execution",
        )
        if next_label != selected_checklist_label and next_label in checklist_label_to_id and chat_id:
            selected_id = str(checklist_label_to_id[next_label])
            self.state.chat_selected_checklist_ids[chat_id] = selected_id
            try:
                state, _options, _mapping, _label, error = self._load_chat_checklist_selector_for_ui()
                error = ""
            except Exception as exc:
                state = None
                error = f"{type(exc).__name__}: {exc}"
        summary = self._expert_mode_summary(state) if not error else "STATE ERROR"
        summary_color = Palette.danger if error else (
            Palette.ok if state and str(state.get("lifecycle") or "") == CHECKLIST_LIFECYCLE_COMPLETED
            else Palette.muted2
        )
        status_rect = layout.status
        if state and state.get("lifecycle") == CHECKLIST_LIFECYCLE_CANCELLED_BY_USER and not error:
            summary_color = Palette.warn
            button_w = min(76, max(52, layout.status.w // 4))
            button = Rect(layout.status.x + layout.status.w - button_w, layout.status.y, button_w, layout.status.h)
            status_rect = Rect(layout.status.x, layout.status.y, max(1, layout.status.w - button_w - 8), layout.status.h)
            runtime = getattr(self.services, "chat", None)
            if self.widgets.button("chat.expert_mode.resume", button, "Resume",
                    enabled=bool(runtime) and not runtime.is_running(chat_id),
                    tooltip="Resume this cancelled Checklist and continue; keep your unsent message and attachments"):
                try:
                    runtime.resume_checklist_from_ui(chat_id, str(state["checklist_id"]))
                except Exception as exc:
                    self.state.add_toast("Checklist resume failed", f"{type(exc).__name__}: {exc}", "error")
        self.widgets.clipped_text(
            status_rect, summary, summary_color, tooltip=error or self._expert_mode_summary_tooltip(state),
        )
        if error:
            self.r.draw_card(layout.body, radius=14, fill=Palette.input_bg)
            self.widgets.clipped_text(layout.body.inset(12), error, Palette.danger, tooltip=error)
            return
        self._draw_expert_mode_table("chat.expert_mode.requirements", layout.body, state)

    def _draw_expert_mode_modal(self, rect: Rect, modal: dict[str, Any]) -> None:
        """Draw the Dashboard Checklist dialog using the Chat card's table contract."""
        self.r.draw_rect(rect, Palette.modal_backdrop)
        mw = min(max(1, rect.w - 24), min(980, max(680, rect.w - 180)))
        mh = min(max(1, rect.h - 24), min(760, max(500, rect.h - 140)))
        box = Rect(rect.x + (rect.w - mw) // 2, rect.y + (rect.h - mh) // 2, mw, mh)
        self.r.draw_card(box, radius=24, fill=Palette.panel)
        inner = box.inset(22)
        task_id = str(modal.get("task_id") or "")
        record = self._dashboard_task_record(task_id)
        title = str(record.get("title") or record.get("description") or modal.get("title") or "Task")
        self._draw_card_title_text(
            "modal.expert_mode.title", Rect(inner.x, inner.y, max(1, inner.w - 140), 34),
            "CHECKLISTS", tooltip=f"Checklist — {title}",
        )
        if self.widgets.button(
            "modal.expert_mode.close.x", Rect(inner.x + inner.w - 36, inner.y, 36, 34), "X",
            tooltip="Close Checklist",
        ) or self.state.input.key_escape:
            self.state.modal = None
            return
        owner, owner_error = self._dashboard_checklist_owner(record)
        if self.widgets.button("modal.expert_mode.export", Rect(inner.x + inner.w - 124, inner.y, 34, 34), "",
                icon="checklist_export", enabled=owner is not None, tooltip="Export complete nested Checklist history"):
            self._request_checklist_export(owner, title)
        if self.widgets.button("modal.expert_mode.history", Rect(inner.x + inner.w - 80, inner.y, 34, 34), "",
                icon="expert_history", enabled=owner is not None, tooltip="Checklist history"):
            self.state.modal = {"kind": "expert_mode_history", "task_id": task_id, "title": title}
            self.state.scroll.pop("modal.expert_mode_history.report", None)
            return
        state, error = self._dashboard_expert_mode_state(record)
        task_type, _chat_id, _agent_id, _workspace_chat_id = self._dashboard_task_context_ids(record)
        summary = self._expert_mode_summary(state) if not error else "STATE ERROR"
        subtitle = f"{task_type} · {title} · {summary}"
        self.widgets.clipped_text(
            Rect(inner.x, inner.y + 42, inner.w, 30), subtitle,
            Palette.danger if error else Palette.muted2, tooltip=error or self._expert_mode_summary_tooltip(state),
        )
        footer_y = box.y + box.h - 56
        self.widgets.clipped_text(Rect(inner.x, inner.y + 74, inner.w, 30), self._checklist_display_name(state), Palette.text)
        table_y = inner.y + 110
        if error:
            self.widgets.clipped_text(
                Rect(inner.x, table_y, inner.w, 42), error, Palette.danger, tooltip=error,
            )
            table_y += 48
        table_rect = Rect(inner.x, table_y, inner.w, max(1, footer_y - table_y - 10))
        self._draw_expert_mode_table("modal.expert_mode.requirements", table_rect, state)
        if self.widgets.button(
            "modal.expert_mode.close", Rect(box.x + box.w - 104, footer_y, 82, 34),
            "Close", primary=True,
        ):
            self.state.modal = None

    def _consume_expert_mode_history_refresh(self, modal: dict[str, Any]) -> None:
        """Apply one completed off-thread history snapshot to the open modal."""
        task = modal.get("history_refresh_task")
        if not isinstance(task, asyncio.Task) or not task.done():
            return
        modal.pop("history_refresh_task", None)
        try:
            rows = task.result()
        except asyncio.CancelledError:
            return
        except Exception as exc:
            modal["history_refresh_error"] = f"{type(exc).__name__}: {exc}"
        else:
            modal["history_entries"] = rows if isinstance(rows, list) else []
            modal["history_refresh_error"] = ""
        modal["history_loaded_at"] = time.monotonic()

    def _queue_expert_mode_history_refresh(
        self, modal: dict[str, Any], store: ChecklistStore, owner: dict[str, Any],
    ) -> None:
        """Refresh generic Checklist reports off the UI thread at a bounded cadence."""
        self._consume_expert_mode_history_refresh(modal)
        active = modal.get("history_refresh_task")
        if isinstance(active, asyncio.Task) and not active.done():
            return
        now_mono = time.monotonic()
        if (
            "history_entries" in modal
            and now_mono - float(modal.get("history_loaded_at") or 0.0) < 1.5
        ):
            return
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            try:
                modal["history_entries"] = store.history_reports(owner)
                modal["history_refresh_error"] = ""
            except Exception as exc:
                modal["history_refresh_error"] = f"{type(exc).__name__}: {exc}"
            modal["history_loaded_at"] = now_mono
            return
        task = loop.create_task(
            asyncio.to_thread(store.history_reports, owner),
            name="velox-checklist-history-refresh",
        )
        task.add_done_callback(self._observe_background_task)
        modal["history_refresh_task"] = task

    @staticmethod
    def _cancel_expert_mode_history_refresh(modal: dict[str, Any]) -> None:
        task = modal.pop("history_refresh_task", None)
        if isinstance(task, asyncio.Task) and not task.done():
            task.cancel()

    def _draw_expert_mode_history_modal(self, rect: Rect, modal: dict[str, Any]) -> None:
        """Render the complete current/archive Checklist history as one Markdown document."""
        self.r.draw_rect(rect, Palette.modal_backdrop)
        mw = min(max(1, rect.w - 24), min(1120, max(720, rect.w - 140)))
        mh = min(max(1, rect.h - 24), min(860, max(560, rect.h - 100)))
        box = Rect(rect.x + (rect.w - mw) // 2, rect.y + (rect.h - mh) // 2, mw, mh)
        self.r.draw_card(box, radius=24, fill=Palette.panel)
        inner = box.inset(22)
        self._draw_card_title_text(
            "modal.expert_mode_history.title", Rect(inner.x, inner.y, max(1, inner.w - 100), 34),
            "CHECKLISTS HISTORY",
        )
        if self.widgets.button(
            "modal.expert_mode_history.close.x", Rect(inner.x + inner.w - 36, inner.y, 36, 34), "X",
            tooltip="Close Checklist history",
        ) or self.state.input.key_escape:
            self._cancel_expert_mode_history_refresh(modal)
            self.state.modal = None
            return

        store, owner, title, error = self._expert_mode_history_store_for_modal(modal)
        if self.widgets.button("modal.expert_mode_history.export", Rect(inner.x + inner.w - 80, inner.y, 34, 34), "",
                icon="checklist_export", enabled=owner is not None and not bool(error), tooltip="Export complete nested Checklist history"):
            self._request_checklist_export(owner, title)
        entries: list[dict[str, Any]] = []
        if store is not None and owner is not None and not error:
            self._queue_expert_mode_history_refresh(modal, store, owner)
            self._consume_expert_mode_history_refresh(modal)
            entries = modal.get("history_entries") or []
            error = str(modal.get("history_refresh_error") or "")

        if modal.get("history_signature_entries") is not entries:
            modal["history_signature_entries"] = entries
            modal["history_entries_signature"] = checklist_history_report_signature(entries)
        report_signature = (title, modal.get("history_entries_signature"))
        if error:
            report_text = (
                f"# Checklist History - {_checklist_report_inline(title)}\n\n"
                f"**Error:** {_checklist_report_inline(error)}\n"
            )
            cache_key = "error:" + hashlib.sha1(report_text.encode("utf-8")).hexdigest()[:16]
        elif "history_entries" not in modal and isinstance(modal.get("history_refresh_task"), asyncio.Task):
            report_text = "# Checklist History\n\n_Loading Checklist history..._\n"
            cache_key = "loading"
        else:
            if modal.get("history_report_signature") != report_signature:
                modal["history_markdown"] = checklist_history_report_markdown(title, entries)
                modal["history_report_signature"] = report_signature
                modal["history_cache_key"] = "report:" + hashlib.sha256(modal["history_markdown"].encode("utf-8")).hexdigest()[:20]
            report_text = str(modal["history_markdown"])
            cache_key = str(modal["history_cache_key"])

        footer_y = box.y + box.h - 56
        body_y = inner.y + 44
        body = Rect(inner.x, body_y, inner.w, max(1, footer_y - body_y - 10))
        self.widgets.markdown_renderer.view(
            "modal.expert_mode_history.report", body, report_text,
            selectable=True, draw_card=True, vertical_scroll=True, cache_key=cache_key, checklist_report=True,
        )
        if self.widgets.button(
            "modal.expert_mode_history.close", Rect(box.x + box.w - 104, footer_y, 82, 34),
            "Close", primary=True,
        ):
            self._cancel_expert_mode_history_refresh(modal)
            self.state.modal = None

    def _draw_chat_agent_tasks(self, rect: Rect, *, active_tab: Rect | None = None) -> None:
        """Compact active-chat agent table with the shared Agent row actions."""
        self.r.draw_card(rect, radius=12, fill=Palette.panel)
        self._erase_chat_tab_body_seam(rect, active_tab)
        inner = rect.inset(10)
        title_h = chat_tab_card_title_height(self.f.line_h)
        title_rect = Rect(inner.x, inner.y, inner.w, title_h)
        self._draw_card_title_text(
            "chat.agent_tasks.title", title_rect, "AGENT TASKS",
        )
        chat_id = str(self.state.active_chat_id or "")
        agents = self.services.agents.list_agents(chat_id) if chat_id else []
        count_text = str(len(agents)) if agents else ""
        if count_text:
            self.widgets.clipped_text(
                Rect(inner.x + inner.w - 44, inner.y, 44, title_h),
                count_text, Palette.muted2, align="right",
            )
        body = Rect(
            inner.x, inner.y + title_h, inner.w,
            max(1, inner.h - title_h),
        )
        if not agents:
            self.widgets.clipped_text(Rect(body.x + 8, body.y + 6, max(1, body.w - 16), max(34, self.f.line_h + 12)), "No agent tasks yet", Palette.muted2)
            return
        rows: list[dict[str, Any]] = []
        for agent in agents:
            agent_id = str(agent.get("agent_id") or "")
            status = str(agent.get("status") or "queued")
            rows.append({
                "id": agent_id,
                "title": str(agent.get("title") or "Background agent"),
                "progress": {
                    "label": self._agent_progress_text(agent),
                    "sort": int(agent.get("progress_percent") or (-1 if status == "queued" else 0)),
                    "color": self._agent_status_color(status),
                },
                "_tooltip": (lambda resolved=agent_id: self._agent_statistics_tooltip_for_id(resolved)),
                "_context_menu": self._agent_row_context_items(agent),
            })
        columns = [
            {"key": "title", "title": "Title", "min_width": 120},
            {"key": "progress", "title": "Progress", "width": 125, "sort_type": "number"},
        ]
        current_sort = self.state.table_sort.get("chat.agents")
        if not isinstance(current_sort, tuple) or current_sort[0] not in {"title", "progress"}:
            self.state.table_sort["chat.agents"] = ("title", True)
        self.state.chat_selected_agent_id, action = self.widgets.table_view(
            "chat.agents", body, columns, rows, self.state.chat_selected_agent_id,
            id_key="id", row_h=max(32, self.f.line_h + 10), double_click_action="view",
        )
        if action:
            self._handle_agent_row_action(action[0], action[1])

    def _draw_chat_sidebar_tab(
        self, widget_id: str, rect: Rect, label: str, *, selected: bool,
    ) -> bool:
        """Draw one flat trapezoid tab with angled sides and neutral outlines."""
        slant = max(8, min(18, rect.h // 2))
        hovered = bool(
            self.widgets._can_receive_pointer(widget_id)
            and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, rect)
        )
        fill = Palette.panel if selected else (Palette.hover if hovered else Palette.input_bg)
        # Active state is communicated by bold text and continuity with the body,
        # not by a blue/accent outline. Both tabs keep the same neutral border.
        border = Palette.border
        denom = max(1, rect.h - 1)
        for row in range(max(1, rect.h)):
            inset = max(0, slant - int(round(slant * row / denom)))
            self.r.draw_rect(Rect(rect.x + inset, rect.y + row, max(1, rect.w - inset * 2), 1), fill)
        self.r.draw_line(rect.x + slant, rect.y, rect.x + rect.w - slant - 1, rect.y, border)
        self.r.draw_line(rect.x + slant, rect.y, rect.x, rect.y + rect.h - 1, border)
        self.r.draw_line(rect.x + rect.w - slant - 1, rect.y, rect.x + rect.w - 1, rect.y + rect.h - 1, border)
        if not selected:
            self.r.draw_line(rect.x, rect.y + rect.h - 1, rect.x + rect.w - 1, rect.y + rect.h - 1, border)

        text_rect = Rect(
            rect.x + max(10, slant // 2), rect.y,
            max(1, rect.w - max(20, slant)), rect.h,
        )
        run_font = getattr(self.widgets, "bold_font", self.f) if selected else self.f
        text_color = Palette.white if selected else CHAT_SIDEBAR_TAB_INACTIVE_TEXT
        label_w = min(text_rect.w, run_font.text_width(label))
        text_x = text_rect.x + max(0, (text_rect.w - label_w) // 2)
        self.r.push_clip(text_rect)
        self.r.draw_text_run_font(
            run_font, label, text_x,
            centered_visible_text_y(run_font, label, text_rect.y, text_rect.h),
            text_color,
        )
        self.r.pop_clip()
        clicked = bool(
            hovered and self.state.input.mouse_pressed and not self.state.input.mouse_consumed
        )
        if clicked:
            self.state.input.mouse_consumed = True
        return clicked

    def _draw_chat_sidebar_tabs(self, rect: Rect) -> Rect:
        """Draw angled Lists/Tasks tabs and return the final active-tab rectangle."""
        selected = str(getattr(self.state, "chat_sidebar_tab", "lists") or "lists").lower()
        if selected not in {"lists", "tasks"}:
            selected = "lists"
            self.state.chat_sidebar_tab = selected
        gap = 4
        left = rect.x + min(CHAT_SIDEBAR_TAB_LEFT_INSET_PX, max(0, rect.w // 8))
        available_w = max(1, rect.x + rect.w - left)
        tab_w = min(160, max(110, (available_w - gap) // 3))
        lists_rect = Rect(left, rect.y, tab_w, rect.h)
        tasks_rect = Rect(lists_rect.x + lists_rect.w + gap, rect.y, tab_w, rect.h)
        if self._draw_chat_sidebar_tab(
            "chat.sidebar.tab.lists", lists_rect, "Lists", selected=selected == "lists",
        ):
            self.state.chat_sidebar_tab = "lists"
            selected = "lists"
        if self._draw_chat_sidebar_tab(
            "chat.sidebar.tab.tasks", tasks_rect, "Tasks", selected=selected == "tasks",
        ):
            self.state.chat_sidebar_tab = "tasks"
            selected = "tasks"
        return tasks_rect if selected == "tasks" else lists_rect

    def _erase_chat_tab_body_seam(self, body: Rect, active_tab: Rect | None) -> None:
        """Remove the body top border directly under the active tab."""
        if active_tab is None or body.w <= 0 or body.h <= 0:
            return
        seam = rect_intersection(
            Rect(active_tab.x, body.y, active_tab.w, CHAT_SIDEBAR_TAB_SEAM_H_PX), body,
        )
        if seam is not None:
            self.r.draw_rect(seam, Palette.panel)

    def draw_chat_chats_panel(self, rect: Rect) -> None:
        """Give Chats 50% of the rail and reserve the lower 50% for Lists/Tasks tabs."""
        self.r.draw_card(rect, radius=22, fill=Palette.panel2)
        inner = rect.inset(12)
        layout = chat_sidebar_split_layout(inner, self.f.line_h)
        self.draw_chat_list(layout.chats)
        active_tab = self._draw_chat_sidebar_tabs(layout.tab_bar)
        selected = str(getattr(self.state, "chat_sidebar_tab", "lists") or "lists").lower()
        if selected == "tasks":
            self._draw_chat_agent_tasks(layout.tab_body, active_tab=active_tab)
        else:
            self._draw_chat_expert_mode(layout.tab_body, active_tab=active_tab)


    def _quote_reasoning(self, text: str) -> str:
        lines = str(text or "").strip().splitlines() or [""]
        quoted = ["> **Thinking / reasoning**", ">"]
        quoted.extend("> " + line for line in lines)
        return "\n".join(quoted)

    def _split_reasoning_segments(self, text: str) -> list[tuple[str, str]]:
        # Local reasoning models use several tag spellings, and streamed/error
        # outputs sometimes leave a <think> block unterminated. Split robustly so
        # hidden reasoning is actually hidden instead of leaking raw tags.
        raw = str(text or "")
        tag_re = re.compile(r"(?is)<(/?)(think|thinking|reasoning)>")
        segments: list[tuple[str, str]] = []
        pos = 0
        mode = "visible"
        for m in tag_re.finditer(raw):
            if m.start() > pos:
                segments.append((mode, raw[pos:m.start()]))
            closing = bool(m.group(1))
            mode = "visible" if closing else "reasoning"
            pos = m.end()
        if pos < len(raw):
            segments.append((mode, raw[pos:]))
        return [(kind, value) for kind, value in segments if value]

    def _render_text_with_reasoning(self, text: str, include_reasoning: bool) -> str:
        # Supports common reasoning delimiters produced by local reasoning models.
        parts: list[str] = []
        for kind, value in self._split_reasoning_segments(text):
            chunk = value.strip("\n")
            if not chunk:
                continue
            if kind == "reasoning":
                if include_reasoning:
                    parts.append(self._quote_reasoning(chunk))
            else:
                parts.append(chunk)
        return "\n\n".join(parts).strip()

    def _format_chat_markdown(self, turns: list[dict[str, Any]], *, include_reasoning: bool | None = None) -> str:
        include_reasoning = self.state.show_reasoning_content if include_reasoning is None else include_reasoning
        parts: list[str] = []
        for turn in turns:
            role = str(turn.get("role", "message"))
            role_lower = role.lower()
            text = str(turn.get("text", ""))
            if role_lower in {"thinking", "reasoning", "thought"}:
                if not include_reasoning:
                    continue
                rendered = self._quote_reasoning(text)
                parts.append(f"### Reasoning  {turn.get('created_at', '')}\n\n{rendered}")
                continue
            status = turn.get("status", "")
            heading = f"### {role.title()}  {turn.get('created_at', '')}"
            if status and status not in ("complete", ""):
                heading += f"  [{status}]"
            parts.append(heading + "\n")
            attachments = turn.get("attachments") or []
            if attachments:
                for att in attachments:
                    parts.append(f"`attachment` **{att.get('filename','file')}**  {att.get('mime','')}  {att.get('bytes',0)} bytes\n")
                parts.append("\n")
            reasoning_field = turn.get("reasoning_content") or turn.get("thinking") or turn.get("reasoning")
            combined_text = (f"<thinking>{reasoning_field}</thinking>\n{text}" if reasoning_field else text)
            rendered_text = self._render_text_with_reasoning(combined_text, include_reasoning)
            if rendered_text:
                parts.append(rendered_text)
            stats = turn.get("stats") or {}
            if stats:
                speed = stats.get("tokens_per_second")
                toks = stats.get("completion_tokens") or stats.get("approx_output_tokens")
                dur = stats.get("duration_ms")
                ft = stats.get("first_token_ms")
                tools = stats.get("tool_call_count", 0)
                parts.append(f"\n\n`stats` {toks} out tok | {speed} tok/s | {dur} ms total | first {ft} ms | tools {tools}\n")
            parts.append("\n")
        return "\n".join(parts).strip() + ("\n" if parts else "")

    def _copy_current_thread_to_clipboard(self, turns: list[dict[str, Any]]) -> None:
        text = self._format_chat_markdown(turns, include_reasoning=True)
        if self.r.host:
            self.r.host.set_clipboard_text(text)

    def _request_chat_debug_export(self, chat_id: str | None = None) -> None:
        self._request_debug_export("chat", str(chat_id or self.state.active_chat_id or ""))

    def _request_agent_debug_export(self, agent_id: str) -> None:
        self._request_debug_export("agent", str(agent_id or ""))

    def _request_debug_export(self, kind: str, identity: str) -> None:
        """Bind identity now; do not build a report or touch the clipboard in draw."""
        if kind not in {"chat", "agent"} or not identity:
            self.state.add_toast("Debug report unavailable", "The selected Task has no identity.", "error")
            return
        self._open_file_picker("debug_export")
        self.state.file_picker_save = True
        self.state.file_picker_save_context = {"kind": kind, "identity": identity}
        safe_id = re.sub(r"[^A-Za-z0-9_-]", "_", identity)[:32]
        self.state.file_picker_manual = f"velox-{kind}-{safe_id}-{datetime.now().strftime('%Y%m%d-%H%M%S')}.txt"

    def _build_debug_export_lines(self, owner: dict[str, str]) -> Iterable[str]:
        """Read an isolated owner snapshot on the export worker, not the UI thread."""
        identity = owner["identity"]
        config = self.services.storage.load_config()
        if owner["kind"] == "agent":
            agent, events = self._agent_record_with_events(identity)
            endpoint = endpoint_profile_ref(config, str(agent.get("endpoint_profile_id") or ""))
            source_chat: dict[str, Any] = {}
            source_id = str(agent.get("source_chat_id") or "")
            if source_id:
                try:
                    source_chat = self.services.chats.load_chat(APP_SCOPE_ID, source_id)
                except Exception as exc:
                    source_chat = {"chat_id": source_id, "load_error": f"{type(exc).__name__}: {exc}"}
            yield from iter_agent_debug_report_lines(
                agent, events, endpoint=endpoint, source_chat=source_chat,
                data_root=str(self.services.storage.paths.root_dir),
            )
            return
        chat = self.services.chats.load_chat(APP_SCOPE_ID, identity)
        turns = self.services.chats.load_turns(APP_SCOPE_ID, identity)
        endpoint = endpoint_profile_ref(config, str(chat.get("endpoint_profile_id") or ""))
        try:
            summary = read_json(self.services.storage.paths.chat_summary_json(identity), {}) or {}
        except Exception as exc:
            summary = {"load_error": f"{type(exc).__name__}: {exc}"}
        yield from iter_chat_debug_report_lines(
            chat, turns, endpoint=endpoint,
            tool_settings={"chat_features": chat.get("features") or {},
                           "global_features": config.get("features") or {},
                           "tool_limits": config.get("tools") or {},
                           "chat_compaction": {"mode": "complete-request capacity fitting",
                                               "effective_capacity": "context window minus reserved maximum output"}},
            summary_record=summary, data_root=str(self.services.storage.paths.root_dir),
        )

    def _request_debug_export_write(
        self, owner: dict[str, str], path: Path,
        expected_target: tuple[int, int, int, int, int] | None = None,
    ) -> None:
        tasks = getattr(self, "_debug_export_tasks", None)
        if tasks is None:
            tasks = self._debug_export_tasks = {}
        key = (owner["kind"], owner["identity"])
        if key in tasks and not tasks[key].done():
            return
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            self.state.add_toast("Debug export unavailable", "The application event loop is not running.", "error")
            return
        bound_owner = dict(owner)
        cancel = threading.Event()
        statuses = getattr(self, "_debug_export_status", None)
        if statuses is None:
            statuses = self._debug_export_status = {}
        statuses[key] = {"state": "running", "path": str(path)}
        # This is presentation state, not a second persistent report index.
        for old_key in list(statuses):
            if len(statuses) <= 64:
                break
            if old_key not in tasks and old_key != key:
                statuses.pop(old_key, None)

        async def export() -> None:
            worker = asyncio.create_task(asyncio.to_thread(
                write_debug_report_atomic, path, self._build_debug_export_lines(bound_owner),
                expected_target=expected_target, cancel_event=cancel,
            ))
            try:
                result = await asyncio.shield(worker)
                statuses[key] = dict(result, state="complete")
            except asyncio.CancelledError:
                cancel.set()
                statuses[key] = {"state": "cancelling", "path": str(path)}
                # A cancelled asyncio wrapper cannot interrupt a running filesystem
                # call. Keep ownership until the writer exits, even if shutdown or
                # another caller repeats cancel(). Publication is the commit point:
                # cancellation arriving afterwards must not mislabel a saved file.
                while not worker.done():
                    try:
                        await asyncio.shield(worker)
                    except asyncio.CancelledError:
                        continue
                    except Exception:
                        break
                try:
                    result = worker.result()
                except (InterruptedError, asyncio.CancelledError):
                    statuses[key] = {"state": "cancelled", "path": str(path)}
                except Exception as exc:
                    statuses[key] = {"state": "failed", "path": str(path), "error": f"{type(exc).__name__}: {exc}"}
                    self.state.add_toast("Debug export failed", f"{type(exc).__name__}: {exc}", "error")
                else:
                    statuses[key] = dict(result, state="complete")
                raise
            except Exception as exc:
                statuses[key] = {"state": "failed", "path": str(path), "error": f"{type(exc).__name__}: {exc}"}
                self.state.add_toast("Debug export failed", f"{type(exc).__name__}: {exc}", "error")
            finally:
                tasks.pop(key, None)
        task = loop.create_task(export(), name="velox-debug-export")
        tasks[key] = task
        def observe(finished: asyncio.Task[Any]) -> None:
            # Cancellation before the coroutine starts must also clear the UI.
            if tasks.get(key) is finished:
                tasks.pop(key, None)
            if finished.cancelled() and statuses.get(key, {}).get("state") == "running":
                statuses[key] = {"state": "cancelled", "path": str(path)}
            self._observe_background_task(finished)
        task.add_done_callback(observe)

    def _debug_export_tooltip(self, kind: str, identity: str) -> str:
        title = "Export chat debug report" if kind == "chat" else "Export Agent debug report"
        status = getattr(self, "_debug_export_status", {}).get((kind, identity)) or {}
        if not status:
            return title
        label = str(status.get("state") or "").upper()
        detail = f"Last export: {label}"
        if status.get("state") == "complete":
            detail += f" ({int(status.get('bytes') or 0):,} bytes)"
        return "\n".join((title, detail, str(status.get("path") or ""), str(status.get("error") or ""))).rstrip()

    def _draw_debug_export_overwrite(self, rect: Rect, modal: dict[str, Any]) -> None:
        self.r.draw_rect(rect, Palette.modal_backdrop)
        width = max(300, min(700, rect.w - 32))
        height = min(300, max(240, rect.h - 32))
        box = Rect(rect.x + (rect.w - width) // 2, rect.y + (rect.h - height) // 2, width, height)
        self.r.draw_card(box, radius=24, fill=Palette.panel)
        inner = box.inset(24)
        self._draw_card_title_text("modal.debug.export.title", Rect(inner.x, inner.y, inner.w, 36), "Replace debug report?")
        # This is a literal filesystem destination, not model-authored Markdown.
        # Keep spaces, backticks and brackets intact; do not turn a filename suffix
        # into a misleading relative link in the overwrite confirmation.
        self.widgets.multiline_text_input(
            "modal.debug.export.path", Rect(inner.x, inner.y + 48, inner.w, max(60, inner.h - 112)),
            "Replace the existing text file?\n" + str(modal["path"]), editable=False,
        )
        y = box.y + box.h - 58
        if self.widgets.button("modal.debug.export.cancel", Rect(box.x + box.w - 238, y, 100, 36), "Cancel") or self.state.input.key_escape:
            self.state.modal = None
            return
        if self.widgets.button("modal.debug.export.replace", Rect(box.x + box.w - 126, y, 104, 36), "Replace", danger=True):
            self.state.modal = None
            self._request_debug_export_write(dict(modal["owner"]), Path(modal["path"]), modal["expected_target"])

    async def _ui_summarize_chat(self, scope_id: str, chat_id: str, endpoint_profile_id: str, *, compact: bool = False) -> None:
        try:
            if compact:
                await self.services.chat.compact_chat_now(scope_id, chat_id, endpoint_profile_id)
                self.state.scroll["chat.thread"] = 10**9
            else:
                await self.services.chat.summarize_chat(scope_id, chat_id, endpoint_profile_id)
        except Exception as e:
            title = "Chat compaction failed" if compact else "Chat summary failed"
            self.state.add_toast(title, f"{type(e).__name__}: {e}", "error")


    def _copy_image_to_clipboard(self, path: Path) -> None:
        # Best-effort native image clipboard. If platform support is unavailable,
        # copy the path so the user still gets a useful result.
        try:
            if sys.platform == "win32" and path.exists():
                ps = (
                    "Add-Type -AssemblyName System.Windows.Forms;"
                    "Add-Type -AssemblyName System.Drawing;"
                    "$p=@'\n" + str(path) + "\n'@;"
                    "$img=[System.Drawing.Image]::FromFile($p);"
                    "[System.Windows.Forms.Clipboard]::SetImage($img);"
                    "$img.Dispose();"
                )
                result = subprocess.run(["powershell", "-NoProfile", "-Sta", "-Command", ps], capture_output=True, timeout=8)
                if result.returncode == 0:
                    return
            if sys.platform == "darwin" and path.exists():
                script = f'set the clipboard to (read POSIX file "{str(path).replace(chr(34), chr(92)+chr(34))}" as TIFF picture)'
                result = subprocess.run(["osascript", "-e", script], capture_output=True, timeout=8)
                if result.returncode == 0:
                    return
        except Exception:
            pass
        if self.r.host:
            self.r.host.set_clipboard_text(str(path))


    def _open_path_in_file_manager(self, path: Path) -> None:
        try:
            path = path.resolve()
            if sys.platform == "win32":
                subprocess.Popen(["explorer", "/select,", str(path)])
            elif sys.platform == "darwin":
                subprocess.Popen(["open", "-R", str(path)])
            else:
                subprocess.Popen(["xdg-open", str(path.parent)])
        except Exception as e:
            self.state.add_toast("Open failed", f"{type(e).__name__}: {e}", "error")


    @staticmethod
    def _endpoint_profile_display_map(config: dict[str, Any] | None) -> tuple[list[str], dict[str, str], dict[str, str]]:
        profiles = sorted(
            endpoint_profiles_from_config(config),
            key=lambda profile: (
                str(profile.get("label") or "Unnamed endpoint").casefold(),
                str(profile.get("id") or "").casefold(),
            ),
        )
        counts: dict[str, int] = {}
        for profile in profiles:
            label = str(profile.get("label") or "Unnamed endpoint")
            counts[label.casefold()] = counts.get(label.casefold(), 0) + 1
        options: list[str] = []
        display_to_id: dict[str, str] = {}
        id_to_display: dict[str, str] = {}
        for profile in profiles:
            profile_id = str(profile.get("id") or "")
            label = str(profile.get("label") or "Unnamed endpoint")
            display = label if counts.get(label.casefold(), 0) == 1 else f"{label} [{profile_id[:8]}]"
            options.append(display)
            display_to_id[display] = profile_id
            id_to_display[profile_id] = display
        return options, display_to_id, id_to_display

    def _endpoint_profile_display_map_cached(
        self, config: dict[str, Any],
    ) -> tuple[list[str], dict[str, str], dict[str, str]]:
        cached_source = getattr(self.state, "endpoint_display_map_source", None)
        cached_value = getattr(self.state, "endpoint_display_map_value", None)
        if cached_source is config and cached_value is not None:
            return cached_value
        value = self._endpoint_profile_display_map(config)
        self.state.endpoint_display_map_source = config
        self.state.endpoint_display_map_value = value
        return value

    def _chat_task_label_cached(
        self, chat_id: str, chat: dict[str, Any], config: dict[str, Any],
    ) -> str:
        if (
            getattr(self.state, "chat_task_label_chat_id", "") == chat_id
            and getattr(self.state, "chat_task_label_chat_source", None) is chat
            and getattr(self.state, "chat_task_label_config_source", None) is config
        ):
            cached = str(getattr(self.state, "chat_task_label_value", "") or "")
            if cached:
                return cached
        stored_endpoint = str(chat.get("endpoint_profile_id") or "").strip()
        endpoint = endpoint_profile_view_for_id(config, stored_endpoint)
        endpoint_name = str(
            endpoint.get("label") or endpoint.get("profile_label") or stored_endpoint or "No endpoint"
        )
        value = chat_task_settings_label(endpoint_name, chat.get("features"))
        self.state.chat_task_label_chat_id = chat_id
        self.state.chat_task_label_chat_source = chat
        self.state.chat_task_label_config_source = config
        self.state.chat_task_label_value = value
        return value

    def _endpoint_profile_editor_draft(self, profile: dict[str, Any]) -> dict[str, Any]:
        draft = copy.deepcopy(profile)
        draft["_ui_timeout_minutes"] = self._settings_minutes_text(
            draft.get("timeout_seconds", ENDPOINT_TIMEOUT_SECONDS_DEFAULT),
            ENDPOINT_TIMEOUT_SECONDS_DEFAULT,
        )
        draft["_ui_error_recovery_delay_minutes"] = self._settings_minutes_text(
            draft.get(
                "error_recovery_delay_seconds",
                ENDPOINT_ERROR_RECOVERY_DELAY_SECONDS_DEFAULT,
            ),
            ENDPOINT_ERROR_RECOVERY_DELAY_SECONDS_DEFAULT,
        )
        for field in ENDPOINT_PROFILE_OPTIONAL_FLOAT_FIELDS + ENDPOINT_PROFILE_OPTIONAL_INT_FIELDS:
            value = draft.get(field)
            draft[field] = "" if value is None else str(value)
        draft["_ui_stop_sequences"] = json.dumps(draft.get("stop_sequences") or [], ensure_ascii=False)
        return draft

    @staticmethod
    def _apply_endpoint_model_type_to_editor_draft(draft: dict[str, Any], model_type: Any) -> None:
        """Replace model-specific fields with a preset while preserving connection fields."""
        preset = endpoint_model_type_defaults(model_type)
        if (preset["model_type"] == ENDPOINT_MODEL_TYPE_GLM_5_3_FLASH
                and endpoint_provider_name(str(draft.get("base_url") or ""), draft.get("provider")) == ENDPOINT_PROVIDER_NOVITA):
            # Hosted Novita IDs are lowercase; the local family preset names
            # the Hugging Face repository instead. Reapplying the family in
            # the editor must not turn a valid bundled endpoint into a bad ID.
            preset["model"] = "zai-org/glm-5.3-flash"
        if (preset["model_type"] == ENDPOINT_MODEL_TYPE_QWEN_3_8_FLASH_NEXT
                and endpoint_provider_name(str(draft.get("base_url") or ""), draft.get("provider")) == ENDPOINT_PROVIDER_NOVITA):
            preset["model"] = "qwen/qwen3.8-flash"
        optional_fields = set(ENDPOINT_PROFILE_OPTIONAL_FLOAT_FIELDS + ENDPOINT_PROFILE_OPTIONAL_INT_FIELDS)
        for key, value in preset.items():
            if key == "system_prompt_addon":
                continue
            if key == "stop_sequences":
                draft["stop_sequences"] = list(value or [])
                draft["_ui_stop_sequences"] = json.dumps(value or [], ensure_ascii=False)
            elif key in optional_fields:
                draft[key] = "" if value is None else str(value)
            else:
                draft[key] = copy.deepcopy(value)

    def _endpoint_profile_from_editor_draft(self, draft: dict[str, Any]) -> dict[str, Any]:
        profile = {key: copy.deepcopy(draft.get(key, endpoint_profile_template().get(key))) for key in ENDPOINT_PROFILE_USER_FIELDS}
        raw_minutes = str(draft.get("_ui_timeout_minutes") or "").strip()
        try:
            minutes = float(raw_minutes)
        except Exception as exc:
            raise ValueError("Timeout must be a finite number of minutes") from exc
        if not math.isfinite(minutes) or minutes <= 0:
            raise ValueError("Timeout must be greater than zero minutes")
        profile["timeout_seconds"] = max(1, int(round(minutes * 60.0)))
        retry_minutes_value = draft.get("_ui_error_recovery_delay_minutes")
        if retry_minutes_value is None or not str(retry_minutes_value).strip():
            retry_minutes_value = endpoint_error_recovery_delay_seconds(draft) / 60.0
        raw_retry_minutes = str(retry_minutes_value).strip()
        try:
            retry_minutes = float(raw_retry_minutes)
        except Exception as exc:
            raise ValueError("Endpoint recovery wait must be a finite number of minutes") from exc
        if not math.isfinite(retry_minutes) or retry_minutes < 0:
            raise ValueError("Endpoint recovery wait must be zero or more minutes")
        profile["error_recovery_delay_seconds"] = int(round(retry_minutes * 60.0))
        raw_stops = str(draft.get("_ui_stop_sequences") or "").strip()
        if raw_stops:
            try:
                stops = json.loads(raw_stops)
            except Exception as exc:
                raise ValueError("Stop sequences must be a JSON array of strings") from exc
        else:
            stops = []
        profile["stop_sequences"] = stops
        return normalize_endpoint_profile(profile, location="endpoint profile")

    def _endpoint_config_with_profile(
        self,
        config: dict[str, Any],
        clean_profile: dict[str, Any],
    ) -> dict[str, Any]:
        """Return a settings copy with one validated endpoint inserted or replaced."""
        config_to_save = copy.deepcopy(config)
        llm = config_to_save.setdefault("llm", {})
        profiles = [copy.deepcopy(item) for item in endpoint_profiles_from_config(config_to_save)]
        if any(
            str(item.get("id") or "") != clean_profile["id"]
            and str(item.get("label") or "").casefold() == clean_profile["label"].casefold()
            for item in profiles
        ):
            raise ValueError("Endpoint labels must be unique")
        for index, item in enumerate(profiles):
            if str(item.get("id") or "") == clean_profile["id"]:
                profiles[index] = copy.deepcopy(clean_profile)
                break
        else:
            profiles.append(copy.deepcopy(clean_profile))
        llm["endpoint_profiles"] = profiles
        return config_to_save

    def _autosave_endpoint_editor_draft(
        self,
        modal: dict[str, Any],
        config: dict[str, Any],
    ) -> bool:
        """Persist a valid endpoint draft immediately and leave invalid text editable."""
        try:
            draft = modal.setdefault("draft", {})
            clean_profile = self._endpoint_profile_from_editor_draft(draft)
            existing = next(
                (item for item in endpoint_profiles_from_config(config)
                 if str(item.get("id") or "") == str(clean_profile.get("id") or "")),
                None,
            )
            changed = existing != clean_profile or bool(modal.get("is_new"))
            if changed:
                saved = self._commit_settings_config_now(
                    self._endpoint_config_with_profile(config, clean_profile),
                )
                modal["profile_id"] = str(clean_profile["id"])
                modal["is_new"] = False
                # Keep the raw editor strings/caret state. The normalized copy is
                # already in state.config_draft and on disk.
                config = saved
            modal["last_saved_profile_json"] = json.dumps(
                clean_profile, ensure_ascii=False, sort_keys=True,
            )
            modal["save_status"] = "Saved automatically"
            modal["error"] = ""
            return True
        except Exception as exc:
            modal["save_status"] = "Not saved"
            modal["error"] = f"{type(exc).__name__}: {exc}"
            return False

    @staticmethod
    def _http_headers_preview_text(headers: dict[str, str]) -> str:
        return "\n".join(f"{key}: {value}" for key, value in headers.items())

    def _endpoint_header_preview(self, profile: dict[str, Any], *, stream: bool = True) -> str:
        headers = {
            "User-Agent": endpoint_user_agent(profile),
            "Content-Type": "application/json",
            "Accept": "text/event-stream, application/json" if stream else "application/json",
            "Accept-Encoding": "identity",
        }
        try:
            auth_configured = bool(normalize_endpoint_api_key(profile.get("api_key")))
        except Exception:
            auth_configured = False
        if auth_configured:
            headers["Authorization"] = "Bearer [REDACTED]"
        return self._http_headers_preview_text(headers)

    def _web_header_preview(self, web_cfg: dict[str, Any]) -> str:
        mode = str(web_cfg.get("user_agent_mode") or "desktop_firefox")
        return self._http_headers_preview_text(
            web_request_headers(mode, accept=WebTools.TEXT_ACCEPT)
        )

    def _open_http_headers_dialog(self, title: str, text: str, *, return_modal: dict[str, Any] | None = None) -> None:
        self.state.modal = {
            "kind": "http_headers",
            "title": str(title),
            "text": str(text),
            "return_modal": copy.deepcopy(return_modal) if isinstance(return_modal, dict) else None,
        }

    def _open_endpoint_editor(self, profile_id: str = "", *, new_profile: dict[str, Any] | None = None) -> None:
        config = self.state.config_draft or self._settings_config_to_draft(self.services.storage.load_config())
        profiles = endpoint_profiles_from_config(config)
        is_new = isinstance(new_profile, dict)
        profile = copy.deepcopy(new_profile) if is_new else next(
            (copy.deepcopy(item) for item in profiles if str(item.get("id") or "") == str(profile_id or "")),
            copy.deepcopy(profiles[0]) if profiles else new_endpoint_profile("New endpoint"),
        )
        self.state.modal = {
            "kind": "endpoint_editor",
            "profile_id": str(profile.get("id") or ""),
            "draft": self._endpoint_profile_editor_draft(profile),
            "is_new": bool(is_new),
            "error": "",
            "save_status": "Waiting to save" if is_new else "Saved automatically",
            "last_saved_profile_json": "" if is_new else json.dumps(
                normalize_endpoint_profile(profile, location="endpoint profile"),
                ensure_ascii=False, sort_keys=True,
            ),
        }
        self.state.scroll["modal.endpoint.editor"] = 0

    def _commit_settings_config_now(self, config: dict[str, Any]) -> dict[str, Any]:
        sanitized = self._sanitized_settings_config(config)
        try:
            latest_disk = self.services.storage.load_config()
            latest_ui = latest_disk.get("ui") if isinstance(latest_disk.get("ui"), dict) else {}
            target_ui = sanitized.setdefault("ui", {})
            for geometry_key in ("window_width", "window_height", "window_x", "window_y"):
                if geometry_key in latest_ui:
                    target_ui[geometry_key] = copy.deepcopy(latest_ui[geometry_key])
        except Exception:
            pass
        self.services.storage.write_config(sanitized, preserve_live_fields=True)
        self.state.settings_last_saved_config_json = json.dumps(sanitized, ensure_ascii=False, sort_keys=True)
        self.state.settings_last_valid_config = copy.deepcopy(sanitized)
        self.state.config_draft = self._settings_config_to_draft(sanitized)
        return sanitized

    def _draw_card_title_text(
        self, widget_id: str, rect: Rect, title: Any, *, tooltip: str = "", align: str = "left",
    ) -> None:
        """Draw one clipped structural card title using the global title contract."""
        title_text = str(title or "").upper()
        if not title_text or rect.w <= 0 or rect.h <= 0:
            return
        title_font = getattr(self.widgets, "bold_font", self.f)
        title_display = self.widgets._truncate_to_width(title_text, rect.w)
        title_x = rect.x
        title_width = title_font.measure_text(title_display)
        if align == "center":
            title_x = rect.x + max(0, (rect.w - title_width) // 2)
        elif align == "right":
            title_x = rect.x + max(0, rect.w - title_width)
        self.r.push_clip(rect)
        self.r.draw_text_run_font(
            title_font, title_display, title_x,
            centered_visible_text_y(title_font, title_display, rect.y, rect.h),
            Palette.white,
        )
        self.r.pop_clip()
        effective_tooltip = str(tooltip or (title_text if title_display != title_text else ""))
        if effective_tooltip:
            self.widgets._queue_tooltip(
                widget_id, rect, effective_tooltip,
                visible_text=title_display, visible_text_fully_shown=(title_display == title_text),
            )

    def draw_modals(self, rect: Rect) -> None:
            self._consume_dashboard_raw_copy_task()
            modal = self.state.modal
            if not modal or modal.get("kind") != "chat_attachments":
                self._close_attachment_manager(clear_modal=False)
            if not modal:
                return
            kind = modal.get("kind")
            if kind == "chat_attachments":
                self._draw_attachment_manager(rect, modal)
                return
            if kind == "debug_export_overwrite":
                self._draw_debug_export_overwrite(rect, modal)
                return
            if kind == "task_raw":
                self._draw_dashboard_task_raw_modal(rect, modal)
                return
            if kind == "expert_mode":
                self._draw_expert_mode_modal(rect, modal)
                return
            if kind == "expert_mode_history":
                self._draw_expert_mode_history_modal(rect, modal)
                return
            if kind == "scheduled_task_raw":
                self._draw_scheduled_task_raw_modal(rect, modal)
                return
            if kind == "new_context_doc":
                self.r.draw_rect(rect, Palette.modal_backdrop)
                mw = min(760, max(520, rect.w - 220))
                mh = min(560, max(500, rect.h - 180))
                box = Rect(rect.x + (rect.w - mw) // 2, rect.y + (rect.h - mh) // 2, mw, mh)
                self.r.draw_card(box, radius=24, fill=Palette.panel)
                inner = box.inset(24)
                self._draw_card_title_text("modal.context.new.title", Rect(inner.x, inner.y, inner.w - 52, 34), "NEW CONTEXT DOC")
                if self.widgets.button("modal.context.new.close", Rect(inner.x + inner.w - 36, inner.y, 36, 34), "X"):
                    self.state.modal = None
                    return
                y = inner.y + 52
                label_h = 24
                control_h = 40
                self.widgets.clipped_text(Rect(inner.x, y, inner.w, label_h), "NAME", Palette.muted2)
                y += label_h
                modal["name"] = self.widgets.text_input(
                    "modal.context.new.name", Rect(inner.x, y, inner.w, control_h),
                    str(modal.get("name") or ""), "Context Doc name",
                )
                y += control_h + 12
                self.widgets.clipped_text(Rect(inner.x, y, inner.w, label_h), "GOAL", Palette.muted2)
                y += label_h
                modal["goal"] = self.widgets.multiline_text_input(
                    "modal.context.new.goal", Rect(inner.x, y, inner.w, 126),
                    str(modal.get("goal") or ""), "Define the durable knowledge this document should maintain.",
                )
                y += 138
                half_gap = 12
                half_w = max(160, (inner.w - half_gap) // 2)
                self.widgets.clipped_text(Rect(inner.x, y, half_w, label_h), "CHARACTER LIMIT", Palette.muted2)
                self.widgets.clipped_text(Rect(inner.x + half_w + half_gap, y, half_w, label_h), "UPDATE FREQUENCY", Palette.muted2)
                y += label_h
                modal["character_limit"] = self.widgets.text_input(
                    "modal.context.new.limit", Rect(inner.x, y, half_w, control_h),
                    str(modal.get("character_limit") or CONTEXT_DOC_DEFAULT_CHARACTER_LIMIT), "24000",
                )
                modal["update_frequency"] = self.widgets.dropdown(
                    "modal.context.new.frequency", Rect(inner.x + half_w + half_gap, y, half_w, control_h),
                    str(modal.get("update_frequency") or "Daily"), ["Hourly", "Daily"],
                )
                error = str(modal.get("error") or "")
                if error:
                    self.widgets.clipped_text(Rect(inner.x, y + control_h + 12, inner.w, 40), error, Palette.danger, tooltip=error)
                btn_y = box.y + box.h - 58
                if self.widgets.button("modal.context.new.cancel", Rect(box.x + box.w - 226, btn_y, 94, 36), "Cancel") or self.state.input.key_escape:
                    self.state.modal = None
                    return
                if self.widgets.button("modal.context.new.create", Rect(box.x + box.w - 120, btn_y, 98, 36), "Create", primary=True):
                    try:
                        if self.services.context_docs is None:
                            raise RuntimeError("Context Docs are unavailable")
                        created = self.services.context_docs.create_doc(
                            str(modal.get("name") or ""),
                            str(modal.get("goal") or ""),
                            int(str(modal.get("character_limit") or "").replace(",", "")),
                            str(modal.get("update_frequency") or "Daily").lower(),
                        )
                        self.state.context_selected_doc_id = str(created.get("context_doc_id") or "")
                        self.state.context_selected_revision_key = "current"
                        self.state.context_edit_loaded_key = None
                        self._refresh_context_docs_cache(force=True)
                        self.state.modal = None
                    except Exception as exc:
                        modal["error"] = f"{type(exc).__name__}: {exc}"
                return
