    def _current_chat_show_reasoning(self) -> bool:
        if self.state.active_scope_id and self.state.active_chat_id:
            return self.services.chats.get_chat_feature(self.state.active_scope_id, self.state.active_chat_id, "show_reasoning_content", False)
        return bool(self.state.show_reasoning_content)

    def _close_attachment_manager(self, *, clear_modal: bool = True) -> None:
        cache = getattr(self, "_attachment_list_previews", None)
        if cache is not None:
            cache.close()
            self._attachment_list_previews = None
        if self.state.drag_scrollbar_id == "modal.attachments.list":
            self.state.drag_scrollbar_id = None
        if clear_modal and (self.state.modal or {}).get("kind") == "chat_attachments":
            self.state.modal = None
            self.state.active_widget = None

    def _open_attachment_manager(self) -> None:
        chat_id = str(self.state.active_chat_id or "")
        if not chat_id:
            return
        try:
            self.services.chats.load_chat_view(chat_id)
        except (FileNotFoundError, ValueError):
            self.state.add_toast("Attachments unavailable", "The Chat no longer exists.", "error")
            return
        self._close_attachment_manager()
        self._attachment_list_previews = AttachmentListPreviewCache(self.services.storage.paths, chat_id)
        self.state.modal = {"kind": "chat_attachments", "chat_id": chat_id,
                            "draft_binding": str(self.state.composer_draft_binding or "")}
        self.state.scroll["modal.attachments.list"] = 0
        self.state.active_widget = None
        self.state.open_dropdown = None
        self.state.dropdown_overlay = None
        self.state.context_menu = None

    def _attachment_manager_owner_matches(self, modal: dict[str, Any]) -> bool:
        return (str(modal.get("chat_id") or "") == str(self.state.active_chat_id or "")
                and str(modal.get("draft_binding") or "") == str(self.state.composer_draft_binding or ""))

    def _remove_queued_attachment(self, modal: dict[str, Any], file_id: str) -> bool:
        """Detach only from the bound unsent draft, never delete source/history files."""
        if not file_id or not self._attachment_manager_owner_matches(modal):
            return False
        try:
            self.services.chats.load_chat_view(str(modal["chat_id"]))
        except (FileNotFoundError, ValueError):
            self._close_attachment_manager()
            return False
        index = next((i for i, meta in enumerate(self.state.queued_attachments)
                      if str(meta.get("file_id") or "") == file_id), None)
        if index is None:
            return False
        self.state.queued_attachments.pop(index)
        if str(self.state.composer_draft_binding or "").startswith("week:"):
            self._calendar_save_week_draft()
        else:
            self._save_chat_composer_draft(str(modal["chat_id"]))
        modal.pop("layout_key", None)
        return True

    def _attachment_manager_path(self, meta: dict[str, Any], chat_id: str) -> str:
        # Original full path for selected files; pasted images have only a stored
        # full path. These are literal display strings, not Markdown or links.
        source = str(meta.get("source_path") or "")
        if source:
            return source
        relative = str(meta.get("path") or "")
        return str(self.services.storage.paths.chat_dir(chat_id) / relative) if relative else "Path unavailable"

    @staticmethod
    def _attachment_manager_details(meta: dict[str, Any], preview: dict[str, Any]) -> str:
        size = _nonnegative_token_value(preview.get("bytes", meta.get("bytes")))
        size_text = (f"{size / 1024:,.3f} KB" if 0 < size < 1024 else f"{size / 1024:,.1f} KB") if size is not None else "Size unavailable"
        if not attachment_meta_is_image(meta):
            return size_text
        width = _nonnegative_token_value(preview.get("width")) or 0
        height = _nonnegative_token_value(preview.get("height")) or 0
        dimensions = f"{width:,} x {height:,} px" if width and height else (
            "Reading image dimensions..." if preview.get("status") == "loading" else "Dimensions unavailable")
        return dimensions + "  |  " + size_text

    def _draw_attachment_manager(self, rect: Rect, modal: dict[str, Any]) -> None:
        if not self._attachment_manager_owner_matches(modal):
            self._close_attachment_manager()
            return
        try:
            self.services.chats.load_chat_view(str(modal["chat_id"]))
        except (FileNotFoundError, ValueError):
            self._close_attachment_manager()
            return
        cache = getattr(self, "_attachment_list_previews", None)
        if cache is None:
            cache = self._attachment_list_previews = AttachmentListPreviewCache(
                self.services.storage.paths, str(modal["chat_id"]))
        attachments = self.state.queued_attachments
        self.r.draw_rect(rect, Palette.modal_backdrop)
        width, height = max(1, min(1080, rect.w - 40)), max(1, min(800, rect.h - 40))
        box = Rect(rect.x + (rect.w - width) // 2, rect.y + (rect.h - height) // 2, width, height)
        self.r.draw_card(box, radius=22, fill=Palette.panel)
        inner = box.inset(20)
        title = f"ATTACHMENTS ({len(attachments)})"
        self._draw_card_title_text("modal.attachments.title", Rect(inner.x, inner.y, max(1, inner.w - 52), 34), title)
        close = self.widgets.button("modal.attachments.close", Rect(inner.x + inner.w - 36, inner.y, 36, 34), "X",
                                    tooltip="Close attachment list")
        if close or self.state.input.key_escape:
            self.state.input.mouse_consumed = True
            self._close_attachment_manager()
            return
        subtitle = "Queued for the next message. Removing an entry does not delete its source file."
        subrows = self.widgets._wrap_display_rows(subtitle, inner.w)
        sub_y = inner.y + 44
        for index, row in enumerate(subrows):
            self.r.draw_text(row.text, inner.x, sub_y + index * self.f.line_h, Palette.muted2)
        footer_y = inner.y + inner.h - 36
        top = sub_y + len(subrows) * self.f.line_h + 16
        body = Rect(inner.x, top, inner.w, max(1, footer_y - top - 12))
        text_width = max(1, body.w - 168)  # thumbnail + gutters + X + scrollbar
        font_key = (self.f.line_h, self.f.char_w, id(self.f))
        key = (body.w, font_key, tuple((str(a.get("file_id") or ""), str(a.get("filename") or ""),
                                       self._attachment_manager_path(a, str(modal["chat_id"]))) for a in attachments))
        if modal.get("layout_key") != key:
            layouts, tops, y = [], [], 0
            for meta in attachments:
                filename = str(meta.get("filename") or "Attachment")
                name_rows = self.widgets._wrap_display_rows(filename, text_width)
                path_rows = self.widgets._wrap_display_rows(self._attachment_manager_path(meta, str(modal["chat_id"])), text_width)
                row_height = max(112, 28 + (len(name_rows) + len(path_rows) + 1) * self.f.line_h + 10)
                tops.append(y)
                layouts.append((name_rows, path_rows, row_height))
                y += row_height + 8
            modal.update(layout_key=key, layouts=layouts, tops=tops, total_h=max(0, y - 8))
        layouts, tops, total_h = modal["layouts"], modal["tops"], int(modal["total_h"])
        scroll_id = "modal.attachments.list"
        scroll = int(self.state.scroll.get(scroll_id, 0))
        inp = self.state.input
        pointer_inside = point_in_rect(inp.mouse_x, inp.mouse_y, body)
        if pointer_inside and inp.wheel_y and not self.widgets._input_blocked(scroll_id):
            scroll -= int(inp.wheel_y * max(32, self.f.line_h * 3))
            inp.mouse_consumed = True
            inp.wheel_y = 0
        scroll = int(clamp(scroll, 0, max(0, total_h - body.h)))
        scroll = self.widgets._scrollbar_input(scroll_id, body, scroll, total_h)
        self.state.scroll[scroll_id] = scroll
        self.r.push_clip(body)
        removed = False
        if not attachments:
            self.r.draw_text("No attachments queued.", body.x + 14, body.y + 20, Palette.muted2)
        first = max(0, bisect.bisect_right(tops, scroll) - 1)
        end = min(len(layouts), bisect.bisect_left(tops, scroll + body.h) + 1)
        for index in range(first, end):
            meta = attachments[index]
            name_rows, path_rows, row_h = layouts[index]
            y = body.y + tops[index] - scroll
            row_rect = Rect(body.x, y, max(1, body.w - 18), row_h)
            self.r.draw_card(row_rect, radius=10, fill=Palette.panel2 if index % 2 == 0 else Palette.bg)
            preview_rect = Rect(row_rect.x + 12, y + 14, 80, 80)
            self.r.draw_round_rect(preview_rect, 8, Palette.panel)
            preview = cache.get(meta)
            thumbnail = str(preview.get("thumbnail") or "")
            if thumbnail:
                self.r.draw_image_file(thumbnail, aspect_fit_rect(preview_rect.inset(3),
                    int(preview.get("width") or 1), int(preview.get("height") or 1)))
            else:
                # Generic document icon, also used as the pending/broken-image
                # fallback. Vector lines do not depend on special font glyphs.
                page = Rect(preview_rect.x + 23, preview_rect.y + 16, 34, 48)
                self.r.draw_outline_rect(page, Palette.muted2)
                for line in range(3):
                    ly = page.y + 14 + line * 8
                    self.r.draw_line(page.x + 7, ly, page.x + page.w - 7, ly, Palette.muted2)
                if preview.get("error"):
                    self.widgets._queue_tooltip("modal.attachments.preview." + str(meta.get("file_id")),
                                                preview_rect, str(preview["error"]))
            x, text_y = row_rect.x + 106, y + 12
            for row in name_rows:
                self.r.draw_text(row.text, x, text_y, Palette.white)
                text_y += self.f.line_h
            text_y += 4
            for row in path_rows:
                self.r.draw_text(row.text, x, text_y, Palette.muted2)
                text_y += self.f.line_h
            text_y += 6
            self.widgets.clipped_text(Rect(x, text_y, text_width, self.f.line_h),
                self._attachment_manager_details(meta, preview), Palette.muted2,
                tooltip=self._attachment_manager_details(meta, preview) + "\n1 KB = 1,024 bytes")
            remove_rect = Rect(row_rect.x + row_rect.w - 44, y + 12, 32, 32)
            # A clipped row cannot steal input from the dialog header/footer.
            prior_consumed = inp.mouse_consumed
            if not pointer_inside:
                inp.mouse_consumed = True
            clicked = self.widgets.button("modal.attachments.remove." + str(meta.get("file_id") or ""),
                    remove_rect, "X",
                    tooltip="Remove from this draft (source file and sent messages are unchanged)")
            if not pointer_inside:
                inp.mouse_consumed = prior_consumed
            if clicked:
                removed = self._remove_queued_attachment(modal, str(meta.get("file_id") or ""))
                if removed:
                    break
        self.r.pop_clip()
        self.widgets._scrollbar_draw(scroll_id, body, scroll, total_h)
        self.widgets.clipped_text(Rect(inner.x, footer_y, max(1, inner.w - 112), 34),
                                  "1 KB = 1,024 bytes", Palette.muted2)
        if self.widgets.button("modal.attachments.done", Rect(inner.x + inner.w - 96, footer_y, 96, 34), "Close", primary=True):
            self._close_attachment_manager()
        if removed:
            # Geometry is recalculated next frame, without retaining a removed
            # row/index as an action target. Stable file IDs own all actions.
            self.state.scroll[scroll_id] = min(scroll, max(0, total_h - body.h))

    def _attachment_abs_path(self, meta: dict[str, Any]) -> Path | None:
        try:
            chat_id = str(meta.get("chat_id") or self.state.active_chat_id or "").strip()
            if not chat_id:
                return None
            root = self.services.storage.paths.chat_dir(chat_id)
            candidate = ensure_inside(root, root / str(meta.get("path") or ""))
            return candidate if candidate.exists() else None
        except Exception:
            return None

    def _attachment_preview_markdown(self, meta: dict[str, Any]) -> str:
        if not self.state.active_scope_id:
            return ""
        try:
            return AttachmentStore(self.services.storage).attachment_text_for_prompt(self.state.active_scope_id, meta, max_chars=250_000)
        except Exception as e:
            return f"# Preview failed\n\n{type(e).__name__}: {e}"

    def _open_attachment_preview(self, meta: dict[str, Any]) -> None:
        path = self._attachment_abs_path(meta)
        modal = {
            "kind": "attachment_preview",
            "title": str(meta.get("filename") or "Attachment"),
            "mime": str(meta.get("mime") or ""),
            "bytes": int(meta.get("bytes") or 0),
            "path": str(path or ""),
            "meta": dict(meta),
            "is_image": attachment_meta_is_image(meta),
            "text": "" if attachment_meta_is_image(meta) else self._attachment_preview_markdown(meta),
        }
        self.state.modal = modal
        self.state.scroll.pop("modal.attachment.preview", None)

    def _draw_attachment_chip(
        self, widget_id: str, rect: Rect, meta: dict[str, Any], *, interactive: bool = True,
    ) -> bool:
        is_img = attachment_meta_is_image(meta)
        label = str(meta.get("filename") or "file")
        hovered = bool(
            interactive
            and self.widgets._can_receive_pointer(widget_id)
            and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, rect)
        )
        fill = theme_alpha(Palette.accent2 if is_img else Palette.accent, 65 if hovered else 38)
        self.r.draw_round_rect(rect, 10, fill)
        self.r.draw_round_outline(rect, 10, theme_alpha(Palette.white, 45 if hovered else 25))
        icon = Rect(rect.x + 8, rect.y + max(5, (rect.h - 18) // 2), 18, 18)
        if is_img:
            path = self._attachment_abs_path(meta)
            if path:
                self.r.draw_image_file(path, icon)
                self.r.draw_round_outline(icon, 4, theme_alpha(Palette.white, 80))
            else:
                self.widgets._draw_shape("page", icon, Palette.accent2)
        else:
            self.widgets._draw_shape("page", icon, Palette.accent)
        self.widgets.clipped_text(Rect(rect.x + 32, rect.y, max(1, rect.w - 40), rect.h), label, Palette.text)
        if hovered:
            full_path = str(meta.get("path") or meta.get("source_path") or self._attachment_abs_path(meta) or label)
            self.widgets._queue_tooltip(widget_id, rect, full_path)
        clicked = hovered and self.state.input.mouse_pressed
        if clicked:
            self.state.input.mouse_consumed = True
            self._open_attachment_preview(meta)
        return bool(clicked)

    def _assistant_text_without_tool_blocks(self, text: str) -> str:
        raw = str(text or "")
        raw = re.sub(r"(?is)\n*\*\*Tool `[^`]+` (?:ok|failed):\*\*\s*```json\s*.*?```\s*", "\n", raw)
        return raw.strip()

    def _visible_text_and_reasoning(self, turn: dict[str, Any], include_reasoning: bool) -> tuple[str, str]:
        text = str(turn.get("text", ""))
        reasoning_field = turn.get("reasoning_content") or turn.get("thinking") or turn.get("reasoning")
        combined = (f"<thinking>{reasoning_field}</thinking>\n{text}" if reasoning_field else text)
        visible_parts: list[str] = []
        reasoning_parts: list[str] = []
        for kind, value in self._split_reasoning_segments(combined):
            chunk = value.strip("\n")
            if not chunk:
                continue
            if kind == "reasoning":
                reasoning_parts.append(chunk)
            else:
                visible_parts.append(chunk)
        visible = self._assistant_text_without_tool_blocks("\n\n".join(visible_parts))
        reasoning = "\n\n".join(reasoning_parts).strip() if include_reasoning else ""
        return visible, reasoning

    def _tool_elapsed_label(self, result: dict[str, Any]) -> str:
        return f"{tool_call_elapsed_seconds(result):.1f} s"

    def _tool_summary_text(self, result: dict[str, Any]) -> str:
        name = str(result.get("tool_name") or "tool")
        if result.get("status") == "running" or result.get("ok") is None:
            status = "running"
        elif result.get("cancelled") or str(result.get("status") or "") == "cancelled":
            status = "cancelled"
        elif result.get("ok") and result.get("warning"):
            status = "succeeded with warnings"
        else:
            status = "succeeded" if result.get("ok") else "failed"
        return f"{status}: {name} in {self._tool_elapsed_label(result)}"

    def _tool_raw_result_text(self, result: dict[str, Any]) -> str:
        if result.get("ok"):
            payload: Any = result.get("result")
            if payload is None:
                excerpt = str(result.get("output_excerpt") or "").strip()
                payload = (
                    {"result_unavailable_in_snapshot": True, "output_excerpt": excerpt}
                    if excerpt else
                    {"result_unavailable_in_snapshot": True}
                )
            if result.get("warning"):
                payload = {
                    "result": result.get("result"),
                    "warning": result.get("warning"),
                    "verification_recommended": bool(result.get("verification_recommended")),
                    "original_parse_error": result.get("original_parse_error"),
                }
        else:
            payload = {"error": result.get("error"), "retry_instructions": result.get("retry_instructions")}
        try:
            return json.dumps(payload, ensure_ascii=False, indent=2, default=str)
        except Exception:
            return str(payload)

    def _tool_details_text(self, result: dict[str, Any]) -> str:
        raw_call = str(result.get("raw_tool_call") or "")
        if result.get("status") == "running" or result.get("ok") is None:
            status = "running"
        elif result.get("cancelled") or str(result.get("status") or "") == "cancelled":
            status = "cancelled"
        elif result.get("ok") and result.get("warning"):
            status = "succeeded with warnings"
        else:
            status = "succeeded" if result.get("ok") else "failed"
        phase = str(result.get("endpoint_phase") or "").strip()
        stream_text = str(result.get("endpoint_stream_text") or "")
        stream_reasoning = str(result.get("endpoint_reasoning") or "")
        stream_output = str(result.get("endpoint_output") or "")
        payload = result.get("result") if isinstance(result.get("result"), dict) else {}
        if not stream_text and isinstance(payload, dict):
            stream_text = str(payload.get("raw_response") or "")
        if not stream_reasoning and isinstance(payload, dict):
            stream_reasoning = str(payload.get("reasoning") or "")
        if not stream_output and isinstance(payload, dict):
            stream_output = str(payload.get("analysis") or "")
        sections = [
            f"Tool: {result.get('tool_name', 'tool')}",
            f"Status: {status}",
            f"Elapsed: {self._tool_elapsed_label(result)}",
        ]
        if phase:
            sections.append(f"Current phase: {phase}")
        if result.get("cancel_requested"):
            sections.append(f"Cancellation requested: {result.get('cancel_reason') or 'yes'}")
        sections.extend([
            "",
            "Original LLM tool call output:",
            raw_call or "[not recorded]",
        ])
        if stream_text or stream_reasoning or stream_output:
            sections.extend([
                "",
                "Image endpoint streamed response — exact reasoning and output:",
                stream_text or "[no combined stream text recorded]",
                "",
                "Image endpoint reasoning:",
                stream_reasoning or "[no separate reasoning recorded]",
                "",
                "Image endpoint final output:",
                stream_output or "[no separate output recorded yet]",
            ])
        sections.extend([
            "",
            "Raw tool result:",
            self._tool_raw_result_text(result),
        ])
        return "\n".join(sections)


    def _tool_arg_summary(self, args: Any) -> str:
        if args is None:
            return ""
        if isinstance(args, dict):
            try:
                text = json.dumps(args, ensure_ascii=False, separators=(",", ":"))
            except Exception:
                text = str(args)
        else:
            text = str(args)
        return " ".join(text.replace("\r", " ").replace("\n", " ").split())

    def _tool_row_summary(self, tool_call: dict[str, Any]) -> str:
        name = str(tool_call.get("tool_name") or "tool")
        params = self._tool_arg_summary(tool_call.get("input") or {})
        suffix = " — verify file" if tool_call.get("warning") else ""
        return f"{name} {params}{suffix}".strip()

    def _tool_row_height(self) -> int:
        return max(32, self.f.line_h + 12)

    def _tool_row_state(self, tool_call: dict[str, Any]) -> tuple[str, Color, Color]:
        ok = tool_call.get("ok")
        status = str(tool_call.get("status") or "")
        if status == "constructing":
            return "constructing", theme_alpha(Palette.selected, 210), Palette.accent
        if status == "cancelled" or tool_call.get("cancelled"):
            return "cancelled", Color(82, 55, 17, 220), Palette.warn
        if status == "failed" or ok is False:
            return "failed", theme_alpha(Palette.danger_bg, 205), Palette.danger
        if ok is True and tool_call.get("warning"):
            return "warning", Color(88, 63, 16, 220), Palette.warn
        if status == "complete" or ok is True:
            return "complete", Color(18, 72, 38, 220), Color(126, 225, 154)
        return "running", theme_alpha(Palette.selected, 210), Palette.accent


    @staticmethod
    def _checklist_review_card_payload(tool_call: dict[str, Any]) -> dict[str, Any] | None:
        """Include failed sub-items and their owning requirement in the review card."""
        if str(tool_call.get("tool_name") or "") != "verify_checklist":
            return None
        if tool_call.get("ok") is not True or str(tool_call.get("status") or "") not in {"complete", "completed", "success"}:
            return None
        result = tool_call.get("result") if isinstance(tool_call.get("result"), dict) else {}
        if result.get("action") != "review_completed":
            return None
        items = checklist_presentation_items(result)
        failed_rows = [{"item_id": str(item.get("id") or ""), "parent_id": parent,
                        "reason": str(item.get("latest_comment") or "Independent review failed this item.")}
                       for item, parent in items if item.get("state") == CHECKLIST_ITEM_IN_PROGRESS]
        failed_count = int(result.get("failed_count", len(failed_rows)))
        return {
            "checklist_id": str(result.get("checklist_id") or ""),
            "name": str(result.get("name") or "Checklist"),
            "display_name": str(result.get("display_name") or ""),
            "created_at": str(result.get("created_at") or ""),
            "review_cycle": int(result.get("review_cycle") or 0),
            "review_result": str(result.get("review_result") or ("failed" if failed_count else "passed")),
            "failed_count": failed_count,
            "verified_count": int(result.get("verified_count", sum(item.get("state") == CHECKLIST_ITEM_VERIFIED for item, parent in items))),
            "failed_rows": failed_rows,
        }

    @staticmethod
    def _checklist_review_card_markdown(payload: dict[str, Any]) -> str:
        """Build the review-complete card body, emphasizing failed items and reasons."""
        visible_name = str(payload.get("display_name") or checklist_display_label(
            payload.get("name") or "Checklist", payload.get("created_at"),
        ))
        name = _checklist_report_inline(visible_name)
        failed_rows = [row for row in (payload.get("failed_rows") or []) if isinstance(row, dict)]
        failed_count = int(payload.get("failed_count") or len(failed_rows))
        verified_count = int(payload.get("verified_count") or 0)
        has_failures = bool(failed_count or str(payload.get("review_result") or "") == "failed")
        result_label = "FAILED" if has_failures else "PASSED"
        lines = [
            f"**Checklist:** {name}",
            f"**Result:** {result_label} · {verified_count} verified · {failed_count} failed",
            "",
            "| Item | Result | Why |",
            "| --- | --- | --- |",
        ]
        if failed_rows:
            for row in failed_rows:
                item_id = _checklist_report_inline(row.get("item_id") or "Item")
                reason = _checklist_report_inline(row.get("reason") or "Independent review failed this item.")
                parent_id = _checklist_report_inline(row.get("parent_id") or "")
                label = f"{item_id} (step of {parent_id})" if parent_id else item_id
                lines.append(f"| {label} | Failed | {reason} |")
        elif has_failures:
            lines.append("| Review | Failed | Item-level details are unavailable; inspect the durable review history. |")
        else:
            lines.append("| All items | Passed | No checklist items failed independent review. |")
        return "\n".join(lines)

    @classmethod
    def _checklist_review_card_stamp(cls, tool_call: dict[str, Any]) -> tuple[Any, ...]:
        payload = cls._checklist_review_card_payload(tool_call)
        if not payload:
            return ()
        failed_rows = tuple(
            (str(row.get("item_id") or ""), str(row.get("parent_id") or ""), fast_text_signature(str(row.get("reason") or "")))
            for row in (payload.get("failed_rows") or []) if isinstance(row, dict)
        )
        return (
            str(payload.get("checklist_id") or ""), str(payload.get("display_name") or ""),
            str(payload.get("created_at") or ""), int(payload.get("review_cycle") or 0),
            str(payload.get("review_result") or ""),
            int(payload.get("failed_count") or 0),
            int(payload.get("verified_count") or 0), failed_rows,
        )

    def _build_chat_body_blocks(self, raw_text: str, inline_tools: list[dict[str, Any]]) -> list[dict[str, Any]]:
        raw = str(raw_text or "")
        # Ordinary user/assistant prose is overwhelmingly the hot path. Avoid a
        # full multiline-regex scan for every UI publication when the text
        # contains no internal durable tool-row placeholder.
        if not inline_tools and "[[VELOX_TOOL_ROW:" not in raw:
            return [{"type": "text", "text": raw}]
        blocks: list[dict[str, Any]] = []
        used_tool_indexes: set[int] = set()
        last = 0
        for match in TOOL_INLINE_MARKER_RE.finditer(raw):
            before = raw[last:match.start()]
            clean_before = strip_tool_markup_from_text(before)
            if clean_before.strip():
                blocks.append({"type": "text", "text": clean_before})
            try:
                idx = int(match.group(1))
            except Exception:
                idx = -1
            if 0 <= idx < len(inline_tools) and idx not in used_tool_indexes:
                tool_call = inline_tools[idx]
                blocks.append({"type": "tool", "tool": tool_call, "tool_index": idx})
                review_payload = self._checklist_review_card_payload(tool_call)
                if review_payload:
                    blocks.append({
                        "type": "review_result", "review": review_payload,
                        "markdown": self._checklist_review_card_markdown(review_payload),
                        "tool_index": idx,
                    })
                used_tool_indexes.add(idx)
            last = match.end()
            while last < len(raw) and raw[last:last + 1] == "\n":
                last += 1
        tail = strip_tool_markup_from_text(raw[last:])
        if tail.strip():
            blocks.append({"type": "text", "text": tail})
        for idx, tool_call in enumerate(inline_tools):
            if idx not in used_tool_indexes:
                blocks.append({"type": "tool", "tool": tool_call, "tool_index": idx})
                review_payload = self._checklist_review_card_payload(tool_call)
                if review_payload:
                    blocks.append({
                        "type": "review_result", "review": review_payload,
                        "markdown": self._checklist_review_card_markdown(review_payload),
                        "tool_index": idx,
                    })
        if not blocks:
            blocks.append({"type": "text", "text": strip_tool_markup_from_text(raw)})
        return blocks

    def _chat_body_blocks_for_section(self, section: dict[str, Any]) -> list[dict[str, Any]]:
        """Return parsed text/tool body blocks, caching them on the UI section.

        A cached section owns immutable/replaced text and tool-list objects. Identity
        is therefore the authoritative invalidation signal. The former per-frame
        tuple over every historical tool call made giant cards O(tool count) even
        while completely idle.
        """
        raw_obj = section.get("text")
        raw = str(raw_obj or "")
        tools_obj = section.get("inline_tools")
        inline_tools = tools_obj if isinstance(tools_obj, list) else list(tools_obj or [])
        cached = section.get("_chat_body_blocks_cache")
        if (
            isinstance(cached, dict)
            and cached.get("text_obj") is raw_obj
            and cached.get("tools_obj") is tools_obj
        ):
            blocks = cached.get("blocks")
            if isinstance(blocks, list):
                return blocks
        blocks = self._build_chat_body_blocks(raw, inline_tools)
        section["_chat_body_blocks_cache"] = {
            "text_obj": raw_obj,
            "tools_obj": tools_obj,
            "blocks": blocks,
        }
        section.pop("_chat_body_geometry_cache", None)
        return blocks

    @staticmethod
    def _visible_chat_body_block_range(
        tops: list[int], heights: list[int], visible_top: int, visible_bottom: int,
    ) -> tuple[int, int]:
        """Return intersecting body blocks in O(log n + visible blocks)."""
        if not tops or len(tops) != len(heights) or visible_bottom <= visible_top:
            return 0, 0
        start = max(0, bisect.bisect_right(tops, int(visible_top)) - 1)
        while start < len(tops) and tops[start] + heights[start] < visible_top:
            start += 1
        end = min(len(tops), bisect.bisect_left(tops, int(visible_bottom)))
        if end < len(tops) and tops[end] < visible_bottom:
            end += 1
        return start, max(start, end)

    def _chat_table_word_wrap_enabled(self) -> bool:
        """Return the active Markdown table-wrap policy without assuming a full UI cache."""
        layout_cache = getattr(getattr(self, "widgets", None), "layout_cache", None)
        markdown = getattr(layout_cache, "md", None)
        return bool(getattr(markdown, "table_word_wrap", True))

    @staticmethod
    def _chat_section_uses_incremental_layout(section: dict[str, Any], text: str) -> bool:
        text_len = len(str(text or ""))
        if text_len >= CHAT_LARGE_TEXT_INCREMENTAL_THRESHOLD_CHARS:
            return True
        turn = section.get("turn") if isinstance(section.get("turn"), dict) else {}
        return bool(
            str(turn.get("status") or "") == "streaming"
            and text_len >= CHAT_STREAMING_INCREMENTAL_LAYOUT_MIN_CHARS
        )

    def _chat_body_geometry_for_section(
        self,
        section: dict[str, Any],
        body_blocks: list[dict[str, Any]],
        measure_key: str,
        md_layout_w: int,
        md_viewport_w: int,
    ) -> dict[str, Any]:
        """Compile immutable body-block offsets/layouts once per section revision."""
        cache_key = (
            str(measure_key), id(body_blocks), int(md_layout_w), int(md_viewport_w),
            int(self.f.line_h), int(self.f.char_w),
            self._chat_table_word_wrap_enabled(),
        )
        cached = section.get("_chat_body_geometry_cache")
        if isinstance(cached, dict) and cached.get("key") == cache_key:
            return cached
        entries: list[dict[str, Any]] = []
        tops: list[int] = []
        heights: list[int] = []
        cursor = 0
        for idx, block in enumerate(body_blocks):
            block_type = str(block.get("type") or "text")
            layout: TextLayout | None = None
            block_key = f"{measure_key}.block.{idx}"
            if block_type == "tool":
                height = self._chat_tool_block_height()
            elif block_type == "review_result":
                text = str(block.get("markdown") or "")
                if not text_has_non_whitespace(text):
                    continue
                review_layout_w = max(1, md_layout_w - CHAT_REVIEW_CARD_HORIZONTAL_BUFFER_PX)
                review_viewport_w = max(1, md_viewport_w - CHAT_REVIEW_CARD_HORIZONTAL_BUFFER_PX)
                layout = self.widgets.layout_cache.get(block_key, text, review_layout_w)
                markdown_h = self._chat_text_block_render_height(
                    layout.height, layout.width > review_viewport_w,
                )
                height = max(
                    96,
                    CHAT_REVIEW_CARD_HEADER_H_PX + 8 + markdown_h + CHAT_REVIEW_CARD_BOTTOM_PAD_PX,
                )
            else:
                text = str(block.get("text") or "")
                if not text_has_non_whitespace(text):
                    continue
                layout = self.widgets.layout_cache.get(
                    block_key,
                    text,
                    md_layout_w,
                    incremental_large=self._chat_section_uses_incremental_layout(section, text),
                )
                height = self._chat_text_block_render_height(
                    layout.height, layout.width > md_viewport_w,
                )
            tops.append(cursor)
            heights.append(int(height))
            entries.append({
                "block_index": idx, "block": block, "top": cursor,
                "height": int(height), "layout": layout, "block_key": block_key,
            })
            cursor += int(height) + CHAT_CARD_BODY_BLOCK_GAP_PX
        total_height = max(0, cursor - (CHAT_CARD_BODY_BLOCK_GAP_PX if entries else 0))
        compiled = {
            "key": cache_key, "entries": entries, "tops": tops, "heights": heights,
            "total_height": total_height,
        }
        section["_chat_body_geometry_cache"] = compiled
        return compiled


    def _draw_checklist_review_result_card(
        self, widget_id: str, rect: Rect, payload: dict[str, Any], markdown_text: str, *,
        visible_clip: Rect | None = None, cache_key: str = "", interactive: bool = True,
    ) -> None:
        """Draw one completed independent-review summary as a flat green Chat card."""
        if visible_clip is not None and rect_intersection(rect, visible_clip) is None:
            return
        failed_count = int(payload.get("failed_count") or 0)
        result_label = "FAILED" if failed_count else "PASSED"
        fill = Color(18, 66, 39, 238)
        border = Color(77, 178, 109, 230)
        self.r.draw_round_rect(rect, 14, fill)
        self.r.draw_round_outline(rect, 14, border)
        header = Rect(
            rect.x + CHAT_REVIEW_CARD_INSET_PX, rect.y + 3,
            max(1, rect.w - CHAT_REVIEW_CARD_INSET_PX * 2), CHAT_REVIEW_CARD_HEADER_H_PX - 4,
        )
        result_w = min(110, max(70, self.widgets._text_width(result_label) + 18))
        title_rect = Rect(header.x, header.y, max(1, header.w - result_w - 8), header.h)
        result_rect = Rect(header.x + header.w - result_w, header.y, result_w, header.h)
        self.widgets.clipped_text(
            title_rect, "CHECKLIST REVIEW COMPLETE", Color(209, 244, 220), align="left",
            tooltip=str(payload.get("name") or "Checklist review"),
        )
        self.widgets.clipped_text(
            result_rect, result_label, Palette.warn if failed_count else Color(146, 239, 174), align="right",
        )
        markdown_y = rect.y + CHAT_REVIEW_CARD_HEADER_H_PX + 8
        markdown_rect = Rect(
            rect.x + CHAT_REVIEW_CARD_INSET_PX, markdown_y,
            max(1, rect.w - CHAT_REVIEW_CARD_INSET_PX * 2),
            max(1, rect.y + rect.h - CHAT_REVIEW_CARD_BOTTOM_PAD_PX - markdown_y),
        )
        markdown_clip = (
            rect_intersection(markdown_rect, visible_clip)
            if visible_clip is not None else markdown_rect
        )
        if markdown_clip is not None:
            self.widgets.markdown_renderer.view(
                widget_id + ".markdown", markdown_rect, str(markdown_text or ""),
                selectable=interactive, draw_card=False, vertical_scroll=False,
                visible_clip=markdown_clip, cache_key=cache_key or widget_id + ".markdown",
                neutral_code_color=False, incremental_large=False, cache_textures=False,
                pointer_interactive=interactive, table_style=CHECKLIST_REVIEW_TABLE_STYLE,
            )

    def _draw_inline_tool_row(
        self, widget_id: str, rect: Rect, tool_call: dict[str, Any], *,
        tool_index: int = 0, interactive: bool = True,
    ) -> bool:
        hovered = bool(
            interactive
            and self.widgets._can_receive_pointer(widget_id)
            and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, rect)
        )
        pressed = hovered and self.state.input.mouse_down
        status_name, fill, accent = self._tool_row_state(tool_call)
        draw_rect = Rect(rect.x, rect.y + (1 if pressed else 0), rect.w, rect.h)
        self.r.draw_round_rect(
            Rect(draw_rect.x + 1, draw_rect.y + 2, draw_rect.w, draw_rect.h),
            10, theme_alpha(Palette.black, 70),
        )
        self.r.draw_round_rect(
            draw_rect, 10, theme_mix(fill, Palette.white, 0.06) if hovered else fill,
        )
        self.r.draw_round_outline(draw_rect, 10, accent if hovered else theme_alpha(accent, 180))
        icon_box = Rect(draw_rect.x + 8, draw_rect.y + max(0, (draw_rect.h - 22) // 2), 22, 22)
        self.r.draw_round_rect(icon_box, 7, accent)
        self.r.draw_round_outline(icon_box, 7, theme_alpha(Palette.white, 55))
        self.r.draw_embedded_icon("tool", Rect(icon_box.x + 3, icon_box.y + 3, 16, 16))
        summary = self._tool_row_summary(tool_call)
        elapsed_label = self._tool_elapsed_label(tool_call)
        running = status_name == "running"
        cancel_w = 30 if running else 0
        cancel_gap = 6 if running else 0
        timer_w = min(104, max(64, int(draw_rect.w * 0.16)))
        text_x = icon_box.x + icon_box.w + 10
        right_edge = draw_rect.x + draw_rect.w - 10
        cancel_rect = Rect(right_edge - cancel_w, draw_rect.y + max(1, (draw_rect.h - 28) // 2), cancel_w, 28)
        timer_right = cancel_rect.x - cancel_gap if running else right_edge
        timer_rect = Rect(
            max(text_x, timer_right - timer_w),
            draw_rect.y,
            max(1, min(timer_w, timer_right - text_x)),
            draw_rect.h,
        )
        summary_rect = Rect(
            text_x,
            draw_rect.y,
            max(1, timer_rect.x - text_x - 10),
            draw_rect.h,
        )
        self.widgets.clipped_text(
            summary_rect, summary, Palette.text, align="left",
            tooltip=summary if interactive else "",
        )
        self.widgets.clipped_text(
            timer_rect, elapsed_label, accent, align="right",
            tooltip=f"Tool execution time: {elapsed_label}" if interactive else "",
        )
        cancel_clicked = False
        if interactive and running and cancel_rect.w > 0:
            cancel_clicked = self.widgets.button(
                widget_id + ".cancel",
                cancel_rect,
                "X",
                danger=True,
                tooltip="Cancel this running tool call",
            )
            if cancel_clicked:
                tool_call_id = str(tool_call.get("tool_call_id") or "")
                request_cancel = getattr(self.services.tools, "request_cancel_tool_call", None)
                cancel_method = request_cancel if callable(request_cancel) else self.services.tools.cancel_tool_call
                cancel_method(
                    tool_call_id,
                    reason="The user cancelled this tool call from the chat interface.",
                    cancelled_by_user=True,
                )
                self.state.input.mouse_consumed = True
                return False
        if hovered:
            self.state.hot = widget_id
        clicked = bool(
            interactive and hovered and self.state.input.mouse_pressed
            and not self.state.input.mouse_consumed
        )
        if clicked:
            live_snapshot = self.services.tools.tool_execution_snapshot(
                str(tool_call.get("tool_call_id") or ""),
            )
            # Recent execution metadata can be newer than the durable chat row,
            # while the durable row can be the only copy containing a large raw
            # result after restart. Merge both instead of letting a metadata-only
            # snapshot replace a real result with JSON null.
            snapshot = copy.deepcopy(tool_call)
            if isinstance(live_snapshot, dict):
                snapshot.update(copy.deepcopy(live_snapshot))
                if live_snapshot.get("result") is None and tool_call.get("result") is not None:
                    snapshot["result"] = copy.deepcopy(tool_call.get("result"))
            self.state.modal = {
                "kind": "tool_details",
                "title": self._tool_summary_text(snapshot),
                "tool_result": snapshot,
                "tool_call_id": str(snapshot.get("tool_call_id") or ""),
                "details": self._tool_details_text(snapshot),
            }
            self.state.input.mouse_consumed = True
        return clicked


    @staticmethod
    def _tool_call_media_reuse_stamp(call: dict[str, Any]) -> tuple[Any, ...]:
        """Return a bounded mutation stamp for tool-produced media or review cards.

        Tool records are normally replaced atomically, but live progress and test
        recovery paths may update a result dictionary in place. Include list
        identity, count, and edge-item fields so media additions or path changes
        invalidate reused Chat sections without serializing large tool results.
        """
        tool_name = str(call.get("tool_name") or "")
        result_obj = call.get("result")
        result = result_obj if isinstance(result_obj, dict) else {}
        if tool_name in {"browser_run_headless", "browser_demo_playback"}:
            artifacts_obj = result.get("artifacts")
            artifacts = artifacts_obj if isinstance(artifacts_obj, dict) else {}
            screenshot_obj = artifacts.get("screenshot")
            screenshot = screenshot_obj if isinstance(screenshot_obj, dict) else {}
            playback_obj = artifacts.get("playbackScreenshots")
            playback = playback_obj if isinstance(playback_obj, list) else []
            first = playback[0] if playback and isinstance(playback[0], dict) else {}
            last = playback[-1] if playback and isinstance(playback[-1], dict) else {}
            return (
                tool_name, id(result_obj), id(artifacts_obj),
                id(screenshot_obj), str(screenshot.get("path") or ""),
                id(playback_obj), len(playback),
                str(first.get("path") or ""), str(last.get("path") or ""),
            )
        if tool_name == "verify_checklist":
            items = result.get("items") if isinstance(result.get("items"), list) else []
            failed = tuple(
                (str(item.get("id") or ""), str(item.get("state") or ""), fast_text_signature(str(item.get("latest_comment") or "")))
                for item in items if isinstance(item, dict) and str(item.get("state") or "") == CHECKLIST_ITEM_IN_PROGRESS
            )
            return (
                tool_name, id(result_obj), str(result.get("action") or ""),
                int(result.get("review_cycle") or 0), int(result.get("failed_count") or 0),
                int(result.get("verified_count") or 0), failed,
            )
        if tool_name.startswith("comfy_"):
            outputs_obj = result.get("outputs")
            outputs = outputs_obj if isinstance(outputs_obj, list) else []
            first = outputs[0] if outputs and isinstance(outputs[0], dict) else {}
            last = outputs[-1] if outputs and isinstance(outputs[-1], dict) else {}
            return (
                tool_name, id(result_obj), id(outputs_obj), len(outputs),
                str(first.get("path") or ""), str(first.get("kind") or ""),
                str(last.get("path") or ""), str(last.get("kind") or ""),
            )
        return (tool_name, id(result_obj), 0)

    @classmethod
    def _tool_calls_media_reuse_stamp(cls, tool_calls: Any) -> tuple[Any, ...]:
        """Return a mutation stamp for every media/review-producing call in one turn.

        A provider may return several tool calls in one batch. The first Comfy or
        browser call can finish while a later non-media call remains the list tail,
        so watching only the final call leaves stale section/card geometry alive.
        Scanning only media-capable rows keeps the stamp bounded in the common case
        while guaranteeing that any newly produced thumbnail invalidates reuse.
        """
        calls = tool_calls if isinstance(tool_calls, list) else []
        stamps = tuple(
            cls._tool_call_media_reuse_stamp(call)
            for call in calls
            if isinstance(call, dict)
            and (
                str(call.get("tool_name") or "").startswith("comfy_")
                or str(call.get("tool_name") or "") in {"browser_run_headless", "browser_demo_playback", "verify_checklist"}
            )
        )
        return (id(tool_calls), len(calls), stamps)

    def _tool_call_media_outputs(self, tool_calls: list[dict[str, Any]]) -> list[dict[str, Any]]:
        media: list[dict[str, Any]] = []
        for call in tool_calls or []:
            tool_name = str(call.get("tool_name") or "")
            result = call.get("result") if isinstance(call.get("result"), dict) else {}
            if tool_name in {"browser_run_headless", "browser_demo_playback"}:
                artifacts = result.get("artifacts") if isinstance(result.get("artifacts"), dict) else {}
                candidates: list[dict[str, Any]] = []
                screenshot = artifacts.get("screenshot") if isinstance(artifacts.get("screenshot"), dict) else {}
                if screenshot:
                    candidates.append(screenshot)
                playback_shots = artifacts.get("playbackScreenshots") if isinstance(artifacts.get("playbackScreenshots"), list) else []
                candidates.extend(item for item in playback_shots if isinstance(item, dict))
                for item in candidates:
                    path = str(item.get("path") or "")
                    if path:
                        media.append(dict(item, kind="image", chat_id=str(call.get("chat_id") or self.state.active_chat_id or "")))
                continue
            if not tool_name.startswith("comfy_"):
                continue
            for item in result.get("outputs") or []:
                if not isinstance(item, dict):
                    continue
                kind = str(item.get("kind") or "").lower()
                mime = str(item.get("mime") or "")
                path = str(item.get("path") or "")
                if not path:
                    continue
                if kind == "image" or mime.startswith("image/"):
                    media.append(dict(item, kind="image"))
                elif kind == "video" or mime.startswith("video/"):
                    media.append(dict(item, kind="video"))
        return media

    @staticmethod
    def _inline_media_grid_metrics(media_count: int, width: int) -> tuple[int, int, int, int, int]:
        """Return thumb, gap, columns, rows, and exact reserved grid height."""
        count = max(0, int(media_count))
        if count <= 0:
            return 0, 0, 0, 0, 0
        thumb = min(128, MARKDOWN_IMAGE_THUMBNAIL_MAX_PX)
        gap = 12
        cols = max(1, min(4, max(1, int(width)) // (thumb + gap)))
        rows = (count + cols - 1) // cols
        height = int(rows * (thumb + 34) + max(0, rows - 1) * gap + 8)
        return thumb, gap, cols, rows, height

    def _inline_media_grid_height(self, media: list[dict[str, Any]], width: int) -> int:
        return self._inline_media_grid_metrics(len(media or []), width)[4]

    @staticmethod
    def _chat_inline_media_rect(body: Rect, text_height: int, media_height: int) -> Rect | None:
        """Place media inside the card body even if a stale/rough height is short.

        Exact measurement normally reserves the full media height. This bounded
        geometry is a second line of defense for streaming/recovery mutations: it
        clamps the media grid to the card body instead of allowing a thumbnail to
        paint over the next Chat card.
        """
        if body.h <= 0 or media_height <= 0:
            return None
        height = min(max(0, int(media_height)), max(0, int(body.h)))
        if height <= 0:
            return None
        reserved_y = body.y + body.h - height
        desired_y = body.y + max(0, int(text_height)) + 4
        y = max(body.y, min(desired_y, reserved_y))
        height = min(height, max(0, body.y + body.h - y))
        return Rect(body.x, y, body.w, height) if height > 0 else None

    def _media_abs_path(self, meta: dict[str, Any]) -> Path | None:
        raw = str(meta.get("path") or "").strip()
        if not raw:
            return None
        candidate = Path(raw).expanduser()
        if candidate.is_absolute():
            return candidate.resolve()
        chat_id = str(meta.get("chat_id") or self.state.active_chat_id or "").strip()
        if not chat_id:
            return None
        try:
            root = self.services.storage.paths.chat_dir(chat_id)
            return ensure_inside(root, root / raw)
        except Exception:
            return None

    def _draw_inline_media_grid(
        self, widget_id: str, rect: Rect, media: list[dict[str, Any]], *,
        interactive: bool = True,
    ) -> None:
        """Draw tool media inside a strict card-local clip rectangle."""
        if not media or rect.h <= 0 or rect.w <= 0:
            return
        thumb, gap, cols, _rows, _height = self._inline_media_grid_metrics(len(media), rect.w)
        if thumb <= 0:
            return
        self.r.push_clip(rect)
        try:
            for i, meta in enumerate(media):
                row = i // cols
                col = i % cols
                x = rect.x + col * (thumb + gap)
                y = rect.y + row * (thumb + 34 + gap)
                card = Rect(x, y, thumb, thumb + 28)
                if card.y >= rect.y + rect.h:
                    break
                visible_card = rect_intersection(card, rect)
                if visible_card is None:
                    continue
                self.r.draw_card(card, radius=12, fill=Palette.panel2, border=Palette.border)
                media_path = self._media_abs_path(meta)
                raw_path = str(meta.get("path") or "").strip()
                source = str(media_path) if media_path is not None else raw_path
                title = str(meta.get("filename") or Path(raw_path or "output").name)
                kind = str(meta.get("kind") or "").lower()
                mime = str(meta.get("mime") or "").lower()
                is_image = kind == "image" or mime.startswith("image/")
                image_box = Rect(card.x + 4, card.y + 4, thumb - 8, thumb - 8)
                visible_image_box = rect_intersection(image_box, rect)
                if is_image:
                    record = MARKDOWN_IMAGE_CACHE.get(source, self.widgets.markdown_local_candidates(source))
                    status = str(record.get("status") or "broken")
                    if status == "ready":
                        ready_path = Path(str(record.get("path") or ""))
                        w, h = image_size_from_file(ready_path)
                        draw_rect = aspect_fit_rect(image_box, w or image_box.w, h or image_box.h)
                        self.r.draw_image_file(str(ready_path), draw_rect)
                        self.r.draw_round_outline(image_box, 10, theme_alpha(Palette.white, 50))
                    else:
                        border = Palette.danger if status == "broken" else Palette.accent
                        self.r.draw_round_rect(image_box, 10, Palette.input_bg)
                        self.r.draw_round_outline(image_box, 10, theme_alpha(border, 170))
                        if status == "loading":
                            self.widgets.clipped_text(Rect(image_box.x + 8, image_box.y + 25, image_box.w - 16, 28), "Loading image...", Palette.muted2, align="center")
                            self.widgets.clipped_text(Rect(image_box.x + 8, image_box.y + 55, image_box.w - 16, 50), source, Palette.muted, align="center", tooltip=source)
                        else:
                            self.widgets.clipped_text(Rect(image_box.x + 8, image_box.y + 20, image_box.w - 16, 28), "link broken +", Palette.danger, align="center")
                            self.widgets.clipped_text(Rect(image_box.x + 8, image_box.y + 50, image_box.w - 16, 58), source, Palette.danger, align="center", tooltip=f"link broken + {source}")
                    if (
                        interactive and visible_image_box is not None
                        and self.widgets._can_receive_pointer(visible_image_box)
                        and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, visible_image_box)
                        and self.state.input.mouse_pressed
                    ):
                        self.state.modal = {
                            "kind": "image_preview", "title": title, "source": source,
                            "path": str(record.get("path") or "") if status == "ready" else "",
                            "image_status": status, "image_error": str(record.get("error") or ""),
                        }
                        self.state.input.mouse_consumed = True
                else:
                    center = Rect(card.x + card.w // 2 - 18, card.y + 42, 36, 36)
                    self.r.draw_embedded_icon("attachment", center)
                    if (
                        interactive and self.widgets._can_receive_pointer(visible_card)
                        and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, visible_card)
                        and self.state.input.mouse_pressed
                    ):
                        if media_path:
                            self._open_path_in_file_manager(media_path.parent)
                        self.state.input.mouse_consumed = True
                title_rect = Rect(card.x + 8, card.y + thumb, max(1, card.w - 16), 24)
                self.widgets.clipped_text(
                    title_rect, title, Palette.accent if source else Palette.muted2,
                    align="center", tooltip=title if interactive else "",
                )
                visible_title = rect_intersection(title_rect, rect)
                if (
                    interactive and not is_image and media_path and visible_title is not None
                    and self.widgets._can_receive_pointer(visible_title)
                    and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, visible_title)
                    and self.state.input.mouse_pressed
                ):
                    self._open_path_in_file_manager(media_path.parent)
                    self.state.input.mouse_consumed = True
        finally:
            self.r.pop_clip()

    def _user_stats_inline(self, turn: dict[str, Any]) -> str:
        """Compact one-line user prompt-size stats for the message header."""
        stats = turn.get("stats") or {}
        if not stats:
            return ""
        def token_value(*names: str) -> int | None:
            for name in names:
                value = stats.get(name)
                if value is None:
                    continue
                try:
                    return max(0, int(float(value)))
                except Exception:
                    continue
            return None
        total_prompt_tokens = token_value("prompt_total_tokens", "prompt_tokens", "input_tokens", "_estimated_prompt_tokens", "total_tokens")
        return f"Total Tokens: {total_prompt_tokens}" if total_prompt_tokens is not None else ""

    def _stats_inline(self, turn: dict[str, Any]) -> str:
        """Compact one-line assistant timing stats for the message header."""
        stats = turn.get("stats") or {}
        if not stats:
            return ""
        def seconds(*names: str) -> float:
            for name in names:
                value = stats.get(name)
                if value is None:
                    continue
                try:
                    return max(0.0, float(value))
                except Exception:
                    continue
            return 0.0
        def rate(*names: str) -> float:
            for name in names:
                value = stats.get(name)
                if value is None:
                    continue
                try:
                    return max(0.0, float(value))
                except Exception:
                    continue
            return 0.0
        prompt_s = seconds("prompt_seconds")
        answer_s = seconds("generation_seconds")
        response_s = seconds("total_seconds")
        prompt_rate = rate("prompt_tokens_per_second")
        gen_rate = rate("generation_tokens_per_second", "tokens_per_second")
        tools = int(stats.get("tool_call_count") or 0)
        return (
            f"Prompt: {prompt_s:.1f} s | Answer: {answer_s:.1f} s | Response: {response_s:.1f} s | "
            f"Input: {prompt_rate:.1f} t/s | Gen: {gen_rate:.1f} t/s | Tool calls: {tools}"
        )


    def _chat_card_header_height(self) -> int:
        """Height of the one-row card header shared by estimate, measure, and draw."""
        return max(50, self.f.line_h + 20)

    @staticmethod
    def _chat_section_stats_record(turn: dict[str, Any], kind: str) -> dict[str, Any]:
        stats = turn.get("stats") if isinstance(turn.get("stats"), dict) else {}
        target = "thinking" if str(kind or "") == "thinking" else "assistant"
        rows = stats.get("section_stats") if isinstance(stats.get("section_stats"), list) else []
        for row in rows:
            if isinstance(row, dict) and str(row.get("kind") or "") == target:
                return row
        return stats if target == "assistant" else {}

    def _chat_section_stats_tooltip(self, section: dict[str, Any]) -> str:
        """Return date/status/statistics shown only while hovering the card label."""
        turn = section.get("turn") if isinstance(section.get("turn"), dict) else {}
        kind = str(section.get("kind") or "metadata")
        created = format_display_datetime(str(turn.get("created_at") or ""))
        status = str(turn.get("status") or "complete").strip().replace("_", " ").title()
        prefix_lines = [part for part in (created, status) if part]
        stats = turn.get("stats") if isinstance(turn.get("stats"), dict) else {}
        if kind == "user":
            prompt_tokens = next(
                (parsed for key in CHAT_INPUT_TOKEN_ALIASES if (parsed := _nonnegative_token_value(stats.get(key))) is not None),
                None,
            )
            if prompt_tokens is not None:
                return "\n".join(prefix_lines + [f"Prompt tokens: {prompt_tokens:,}"])
            return "\n".join(prefix_lines)
        if kind not in {"assistant", "thinking", "compaction"}:
            return "\n".join(prefix_lines)
        row = self._chat_section_stats_record(turn, kind)
        if not row:
            return "\n".join(prefix_lines)
        total_seconds = _stats_nonnegative_float(row, "total_seconds", "execution_seconds") or 0.0
        prompt_seconds = _stats_nonnegative_float(row, "prompt_seconds") or 0.0
        generation_seconds = _stats_nonnegative_float(row, "generation_seconds") or 0.0
        tool_seconds = _stats_nonnegative_float(row, "tool_seconds") or 0.0
        output_tokens = next(
            (parsed for key in CHAT_OUTPUT_TOKEN_ALIASES if (parsed := _nonnegative_token_value(row.get(key))) is not None),
            0,
        )
        generation_rate = _stats_nonnegative_float(
            row, "generation_tokens_per_second", "tokens_per_second",
        ) or 0.0
        tool_count = int(row.get("tool_call_count") or 0)
        token_suffix = " est." if str(row.get("token_allocation") or "") == "proportional_estimate" else ""
        details = [
            f"Total: {format_compact_duration_seconds(total_seconds)}",
            f"Input: {format_compact_duration_seconds(prompt_seconds)}",
            f"Gen: {format_compact_duration_seconds(generation_seconds)}",
            f"Output {int(output_tokens):,}{token_suffix}",
            f"Generation throughput: {generation_rate:.1f} t/s (tokens/s)",
            f"Tools: {tool_count}",
            f"Tool time: {format_compact_duration_seconds(tool_seconds)}",
        ]
        stats = turn.get("stats") if isinstance(turn.get("stats"), dict) else {}
        if stats.get("generation_timing_basis") == "unavailable_reasoning_not_received":
            details = [line for line in details if not line.startswith("Generation throughput:")]
            details.append("Generation throughput: unavailable (reasoning not received)")
        details.append(f"Provider rounds: {int(stats.get('model_round_count') or 1)}")
        return "\n".join(prefix_lines + details)

    @staticmethod
    def _chat_statistics_text(turns: list[dict[str, Any]], *, title: str = "") -> str:
        stats = chat_thread_runtime_stats(turns)
        lines = []
        if str(title or "").strip():
            lines.append(f"Conversation: {str(title).strip()}")
            lines.append("")
        lines.extend([
            f"Total execution runtime: {format_compact_duration_seconds(stats.get('total_runtime_seconds'))}",
            f"Inference runtime: {format_compact_duration_seconds(stats.get('inference_runtime_seconds'))}",
            f"Tool runtime: {format_compact_duration_seconds(stats.get('tool_runtime_seconds'))}",
            f"Endpoint waits: {format_compact_duration_seconds(stats.get('endpoint_wait_seconds'))}",
            f"Non-inference overhead: {format_compact_duration_seconds(stats.get('overhead_runtime_seconds'))}",
            f"Input runtime: {format_compact_duration_seconds(stats.get('prompt_seconds'))}",
            f"Generation runtime: {format_compact_duration_seconds(stats.get('generation_seconds'))}",
            f"Input tokens: {int(stats.get('input_tokens') or 0):,}",
            f"Output tokens: {int(stats.get('output_tokens') or 0):,}",
            f"Largest response: {int(stats.get('largest_response_output_tokens') or 0):,} tokens",
            f"Average generation throughput: {float(stats.get('average_generation_tokens_per_second') or 0.0):.2f} tokens/s",
            f"Average input throughput: {float(stats.get('average_prompt_tokens_per_second') or 0.0):.2f} tokens/s",
            f"Model rounds: {int(stats.get('model_round_count') or 0):,}",
            f"Tool calls: {int(stats.get('tool_call_count') or 0):,}",
            f"Failed tool calls: {int(stats.get('failed_tool_call_count') or 0):,}",
            f"Compaction events: {int(stats.get('compaction_count') or 0):,}",
            f"Turns with runtime data: {int(stats.get('turn_count') or 0):,}",
        ])
        return "\n".join(lines)

    def _chat_tool_statistics_rows(self, turns: list[dict[str, Any]]) -> list[dict[str, Any]]:
        by_type: dict[str, dict[str, int]] = {}
        if self.state.active_scope_id and self.state.active_chat_id:
            try:
                chat = self.services.chats.load_chat(self.state.active_scope_id, self.state.active_chat_id)
                raw = (chat.get("stats") or {}).get("tool_calls_by_type")
                if isinstance(raw, dict):
                    for name, row in raw.items():
                        if isinstance(row, dict):
                            by_type[str(name)] = {
                                "total": max(0, int(row.get("total") or 0)),
                                "succeeded": max(0, int(row.get("succeeded") or 0)),
                                "failed": max(0, int(row.get("failed") or 0)),
                            }
            except Exception:
                by_type = {}
        if not by_type:
            for turn in turns or []:
                if not isinstance(turn, dict):
                    continue
                for call in turn.get("tool_calls") or []:
                    if not isinstance(call, dict):
                        continue
                    name = str(call.get("tool_name") or "tool")
                    row = by_type.setdefault(name, {"total": 0, "succeeded": 0, "failed": 0})
                    row["total"] += 1
                    if call.get("ok") is False or str(call.get("status") or "").lower() in {"failed", "error"}:
                        row["failed"] += 1
                    elif call.get("ok") is True:
                        row["succeeded"] += 1
        return [
            {
                "id": name,
                "tool": name,
                "total": int(row.get("total") or 0),
                "succeeded": int(row.get("succeeded") or 0),
                "failed": int(row.get("failed") or 0),
            }
            for name, row in sorted(by_type.items(), key=lambda item: (-int(item[1].get("total") or 0), item[0].casefold()))
        ]

    @staticmethod
    def _chat_statistics_clipboard_text(summary_text: str, tool_rows: list[dict[str, Any]]) -> str:
        lines = [str(summary_text or "").rstrip(), "", "Tool calls by type:"]
        if not tool_rows:
            lines.append("(none)")
        else:
            lines.append("Tool\tTotal\tSucceeded\tFailed")
            for row in tool_rows:
                lines.append(
                    f"{row.get('tool', '')}\t{int(row.get('total') or 0)}\t"
                    f"{int(row.get('succeeded') or 0)}\t{int(row.get('failed') or 0)}"
                )
        return "\n".join(lines).strip() + "\n"

    def _open_chat_statistics_dialog(self, turns: list[dict[str, Any]], title: str) -> None:
        summary_text = self._chat_statistics_text(turns, title=title)
        tool_rows = self._chat_tool_statistics_rows(turns)
        self.state.modal = {
            "kind": "chat_statistics",
            "title": "Conversation Statistics",
            "summary_text": summary_text,
            "tool_rows": tool_rows,
            "copy_text": self._chat_statistics_clipboard_text(summary_text, tool_rows),
        }
        self.state.scroll["modal.chat.statistics.text"] = 0
        self.state.scroll["modal.chat.statistics.tools"] = 0

    def _cached_chat_section_stats_tooltip(self, section: dict[str, Any]) -> str:
        turn = section.get("turn") if isinstance(section.get("turn"), dict) else {}
        kind = str(section.get("kind") or "metadata")
        turn_id = str(turn.get("turn_id") or f"section:{id(section)}")
        status = str(turn.get("status") or "")
        calls = [row for row in (turn.get("tool_calls") or []) if isinstance(row, dict)]
        signature = (
            status,
            str(turn.get("updated_at") or "") if status != "streaming" else "streaming",
            len(calls),
            tuple((str(row.get("tool_call_id") or ""), str(row.get("status") or ""), row.get("ok")) for row in calls),
        )
        cache_key = f"{turn_id}:{kind}"
        now = time.monotonic()
        cached = self.state.chat_section_tooltip_cache.get(cache_key)
        if (
            isinstance(cached, dict)
            and cached.get("signature") == signature
            and now - float(cached.get("refreshed_at") or 0.0) < CHAT_STATS_TOOLTIP_REFRESH_SECONDS
        ):
            return str(cached.get("text") or "")
        text = self._chat_section_stats_tooltip(section)
        self.state.chat_section_tooltip_cache[cache_key] = {
            "signature": signature, "refreshed_at": now, "text": text,
        }
        if len(self.state.chat_section_tooltip_cache) > 256:
            oldest = min(
                self.state.chat_section_tooltip_cache,
                key=lambda key: float(self.state.chat_section_tooltip_cache[key].get("refreshed_at") or 0.0),
            )
            self.state.chat_section_tooltip_cache.pop(oldest, None)
        return text


    @staticmethod
    def _chat_layout_widths(transcript_inner_w: int) -> tuple[int, int, int, int]:
        """Use the same nested card, body and Markdown widths for measure and draw.

        A wider measurement than rendering produces extra wrapped rows and
        unstable scrolling. Keep all three insets in one calculation."""
        card_w = max(1, int(transcript_inner_w) - 34)
        section_inner_w = max(1, card_w - 28)  # Rect.inset(14)
        md_viewport_w = max(1, section_inner_w - 24)
        md_layout_w = max(1, md_viewport_w - 16)
        return card_w, section_inner_w, md_layout_w, md_viewport_w

    def _chat_section_measure_signature(self, section: dict[str, Any], layout_w: int, viewport_w: int, section_inner_w: int) -> tuple[Any, ...]:
        raw_text = str(section.get("text") or "")
        turn = section.get("turn") or {}
        attachments = tuple((str(a.get("file_id") or a.get("path") or a.get("filename") or ""), int(a.get("bytes") or 0)) for a in (section.get("attachments") or []))
        media = tuple((str(m.get("path") or ""), str(m.get("kind") or ""), int(m.get("bytes") or 0)) for m in (section.get("inline_media") or []))
        tools = tuple((str(c.get("tool_call_id") or c.get("id") or ""), str(c.get("tool_name") or ""), str(c.get("status") or ""), str(c.get("ok") or ""), str(c.get("elapsed_seconds") or ""), len(str(c.get("output_excerpt") or "")), self._checklist_review_card_stamp(c)) for c in (section.get("inline_tools") or []) if isinstance(c, dict))
        return (
            "chat-card-height", self.f.line_h, self.f.char_w,
            self._chat_table_word_wrap_enabled(),
            str(turn.get("turn_id") or ""), str(turn.get("updated_at") or ""),
            str(section.get("kind") or ""), layout_w, viewport_w, section_inner_w,
            fast_text_signature(raw_text), attachments, media, tools,
        )

    def _chat_text_block_render_height(self, layout_height: int, has_horizontal_scroll: bool) -> int:
        # Shared by estimate, exact measure, and draw so the card's outer height
        # matches the actual cardless Markdown viewport. This removes the blank
        # trailing line that came from measuring cardless chat text as if it still
        # had a full Markdown card inset.
        hbar = CHAT_CARD_HORIZONTAL_SCROLLBAR_PAD_PX if has_horizontal_scroll else 0
        return max(1, int(layout_height) + CHAT_CARD_TEXT_BLOCK_PAD_Y_PX + hbar)

    def _chat_tool_block_height(self) -> int:
        return self._tool_row_height()

    def _chat_body_height_from_blocks(self, block_heights: list[int]) -> int:
        if not block_heights:
            return 0
        return max(0, sum(block_heights) + CHAT_CARD_BODY_BLOCK_GAP_PX * (len(block_heights) - 1))

    def _chat_card_chrome_height(self, header_h: int, att_h: int, media_h: int) -> int:
        media_extra = media_h + 8 if media_h else 0
        return header_h + 18 + att_h + media_extra + CHAT_CARD_BODY_BOTTOM_PAD_PX + CHAT_CARD_LAST_LINE_BUFFER_PX

    @staticmethod
    def _chat_body_has_large_text(body_blocks: list[dict[str, Any]]) -> bool:
        return any(
            block.get("type") != "tool"
            and len(str(block.get("text") or "")) >= CHAT_LARGE_TEXT_INCREMENTAL_THRESHOLD_CHARS
            for block in body_blocks
        )

    def _estimate_chat_section_height(
        self,
        section: dict[str, Any],
        md_layout_w: int,
        md_viewport_w: int,
        section_inner_w: int,
        *,
        body_blocks: list[dict[str, Any]] | None = None,
    ) -> int:
        if str(section.get("kind") or "") == "compaction" and bool(section.get("collapsed")):
            return max(64, self.f.line_h + 34)
        raw_text = str(section.get("text") or "")
        attachments = list(section.get("attachments") or [])
        media = list(section.get("inline_media") or [])
        inline_tools = list(section.get("inline_tools") or [])
        att_sig = tuple((str(a.get("file_id") or a.get("path") or a.get("filename") or ""), int(a.get("bytes") or 0)) for a in attachments)
        media_sig = tuple((str(m.get("path") or ""), str(m.get("kind") or ""), int(m.get("bytes") or 0)) for m in media)
        tool_sig = tuple((str(t.get("tool_call_id") or t.get("id") or ""), str(t.get("tool_name") or ""), str(t.get("status") or ""), str(t.get("ok") or ""), len(str(t.get("output_excerpt") or "")), self._checklist_review_card_stamp(t)) for t in inline_tools if isinstance(t, dict))
        cols = max(8, md_layout_w // max(1, self.f.char_w))
        sig = (
            "chat-layout-estimate", self.f.line_h, self.f.char_w,
            self._chat_table_word_wrap_enabled(),
            cols, md_viewport_w, section_inner_w, fast_text_signature(raw_text),
            att_sig, media_sig, tool_sig,
        )
        cached = self.state.chat_section_estimate_cache.get(sig)
        if cached is not None:
            return int(cached)
        block_heights: list[int] = []
        blocks = body_blocks if body_blocks is not None else self._chat_body_blocks_for_section(section)
        for block in blocks:
            block_type = str(block.get("type") or "text")
            if block_type == "tool":
                block_heights.append(self._chat_tool_block_height())
                continue
            if block_type == "review_result":
                text = str(block.get("markdown") or "")
                review_layout_w = max(1, md_layout_w - CHAT_REVIEW_CARD_HORIZONTAL_BUFFER_PX)
                review_viewport_w = max(1, md_viewport_w - CHAT_REVIEW_CARD_HORIZONTAL_BUFFER_PX)
                layout = self.widgets.layout_cache.get(
                    f"chat.review.estimate.{fast_text_signature(text)}", text, review_layout_w,
                )
                markdown_h = self._chat_text_block_render_height(
                    layout.height, layout.width > review_viewport_w,
                )
                block_heights.append(max(
                    96,
                    CHAT_REVIEW_CARD_HEADER_H_PX + 8 + markdown_h + CHAT_REVIEW_CARD_BOTTOM_PAD_PX,
                ))
                continue
            text = str(block.get("text") or "")
            if not text_has_non_whitespace(text):
                continue
            line_est = estimate_wrapped_line_count_fast(text, cols)
            estimated_layout_h = max(1, line_est * self.f.line_h)
            scan_limit = 60
            start_i = 0
            widest_chars = 0
            for _ in range(scan_limit):
                end_i = text.find("\n", start_i)
                if end_i < 0:
                    end_i = len(text)
                widest_chars = max(widest_chars, min(500, end_i - start_i))
                if end_i >= len(text):
                    break
                start_i = end_i + 1
            estimated_w = widest_chars * max(1, self.f.char_w)
            block_heights.append(self._chat_text_block_render_height(estimated_layout_h, estimated_w > md_viewport_w))
        body_h = self._chat_body_height_from_blocks(block_heights)
        att_h = 0
        if attachments:
            chip_x = 0
            rows_count = 1
            for att in attachments:
                label = str(att.get("filename") or "file")
                chip_w = min(max(128, min(360, len(label) * self.f.char_w + 48)), max(160, section_inner_w - 8))
                if chip_x and chip_x + chip_w > section_inner_w:
                    rows_count += 1
                    chip_x = 0
                chip_x += chip_w + 8
            att_h = rows_count * 38 + 4
        media_h = self._inline_media_grid_height(media, section_inner_w)
        header_h = self._chat_card_header_height()
        result = max(88, self._chat_card_chrome_height(header_h, att_h, media_h) + body_h)
        if len(self.state.chat_section_estimate_cache) > 4096:
            self.state.chat_section_estimate_cache.clear()
        self.state.chat_section_estimate_cache[sig] = int(result)
        return int(result)

    def _measure_chat_section_height(
        self,
        section: dict[str, Any],
        md_layout_w: int,
        md_viewport_w: int,
        section_inner_w: int,
        *,
        prefer_estimate: bool,
        body_blocks: list[dict[str, Any]] | None = None,
    ) -> tuple[int, str]:
        turn_id = str((section.get("turn") or {}).get("turn_id", ""))
        if str(section.get("kind") or "") == "compaction" and bool(section.get("collapsed")):
            return max(64, self.f.line_h + 34), f"chat.thread.measure.{turn_id}.compaction"
        tool_i = str(section.get("tool_index", ""))
        measure_key = f"chat.thread.measure.{turn_id}.{section.get('kind')}.{tool_i}"
        sig = self._chat_section_measure_signature(section, md_layout_w, md_viewport_w, section_inner_w)
        cached = self.state.chat_section_measure_cache.get(sig)
        if cached is not None:
            return int(cached), measure_key
        body_blocks = body_blocks if body_blocks is not None else self._chat_body_blocks_for_section(section)
        has_large_text = self._chat_body_has_large_text(body_blocks)
        if prefer_estimate and not has_large_text:
            return self._estimate_chat_section_height(
                section, md_layout_w, md_viewport_w, section_inner_w,
                body_blocks=body_blocks,
            ), measure_key
        raw_text = str(section.get("text") or "")
        attachments = list(section.get("attachments") or [])
        media = list(section.get("inline_media") or [])
        inline_tools = list(section.get("inline_tools") or [])
        body_geometry = self._chat_body_geometry_for_section(
            section, body_blocks, measure_key, md_layout_w, md_viewport_w,
        )
        body_h = int(body_geometry.get("total_height") or 0)
        att_h = 0
        if attachments:
            chip_x = 0
            rows_count = 1
            for att in attachments:
                label = str(att.get("filename") or "file")
                chip_w = min(max(128, self.widgets._text_width(label) + 48), max(160, section_inner_w - 8))
                if chip_x and chip_x + chip_w > section_inner_w:
                    rows_count += 1
                    chip_x = 0
                chip_x += chip_w + 8
            att_h = rows_count * 38 + 4
        media_h = self._inline_media_grid_height(media, section_inner_w)
        header_h = self._chat_card_header_height()
        card_h = max(88, self._chat_card_chrome_height(header_h, att_h, media_h) + body_h)
        if len(self.state.chat_section_measure_cache) > 2048:
            self.state.chat_section_measure_cache.clear()
        self.state.chat_section_measure_cache[sig] = card_h
        return card_h, measure_key

    def _streaming_reasoning_sections(
        self,
        turn: dict[str, Any],
        raw: str,
        created: str,
        title_suffix: str,
        include_reasoning: bool,
        time_line: str,
        tool_calls: list[dict[str, Any]],
        stream_preview: str,
    ) -> list[dict[str, Any]] | None:
        """Parse the common append-only ``<think>...answer`` shape incrementally.

        The generic parser supports arbitrary interleaved reasoning and tool rows,
        but rescanning a multi-megabyte open thinking block at every publication is
        unnecessary. This checkpoint validates only a short prefix/boundary sample
        and searches newly appended bytes for the closing tag. Terminal turns still
        take the full parser once, preserving complete edit/tool semantics.
        """
        turn_id = str(turn.get("turn_id") or "")
        if (
            not turn_id
            or str(turn.get("status") or "") != "streaming"
            or tool_calls
            or stream_preview
        ):
            return None
        cache = getattr(self, "_assistant_section_stream_cache", None)
        if cache is None:
            cache = {}
            self._assistant_section_stream_cache = cache
        key = (turn_id, bool(include_reasoning))
        state = cache.get(key)

        if state is not None:
            boundary_start = max(0, state.raw_length - len(state.boundary_tail))
            append_valid = (
                len(raw) >= state.raw_length
                and raw.startswith(state.head)
                and raw[boundary_start:state.raw_length] == state.boundary_tail
            )
            if not append_valid:
                cache.pop(key, None)
                state = None
            else:
                appended = raw[state.raw_length:]
                if "[[VELOX_TOOL_ROW:" in appended:
                    cache.pop(key, None)
                    return None
                if state.close_start < 0:
                    search_at = max(state.open_end, state.raw_length - len(state.closer) + 1)
                    close_at = raw.find(state.closer, search_at)
                    if close_at >= 0:
                        state.close_start = close_at
                        state.close_end = close_at + len(state.closer)
                        answer_tail = raw[state.close_end:]
                        if any(token in answer_tail for token in ("<think>", "<thinking>", "<reasoning>")):
                            cache.pop(key, None)
                            return None
                elif any(token in appended for token in ("<think>", "<thinking>", "<reasoning>")):
                    cache.pop(key, None)
                    return None
                state.raw_length = len(raw)
                state.boundary_tail = raw[max(0, len(raw) - 96):]
                state.last_used = time.monotonic()

        if state is None:
            opener = ""
            closer = ""
            for candidate, candidate_close in (
                ("<think>", "</think>"),
                ("<thinking>", "</thinking>"),
                ("<reasoning>", "</reasoning>"),
            ):
                if raw.startswith(candidate):
                    opener, closer = candidate, candidate_close
                    break
            if not opener:
                return None
            if "[[VELOX_TOOL_ROW:" in raw:
                return None
            close_at = raw.find(closer, len(opener))
            close_end = close_at + len(closer) if close_at >= 0 else -1
            if close_at >= 0 and any(
                token in raw[close_end:] for token in ("<think>", "<thinking>", "<reasoning>")
            ):
                return None
            state = AssistantStreamingSectionState(
                raw_length=len(raw),
                head=raw[:96],
                boundary_tail=raw[max(0, len(raw) - 96):],
                opener=opener,
                closer=closer,
                open_end=len(opener),
                close_start=close_at,
                close_end=close_end,
                last_used=time.monotonic(),
            )
            cache[key] = state
            while len(cache) > 64:
                victim = min(cache.items(), key=lambda pair: pair[1].last_used)[0]
                cache.pop(victim, None)

        sections: list[dict[str, Any]] = []
        reasoning_end = state.close_start if state.close_start >= 0 else len(raw)
        reasoning_text = raw[state.open_end:reasoning_end]
        if include_reasoning and text_has_non_whitespace(reasoning_text):
            sections.append({
                "kind": "thinking", "title": "THINKING",
                "time": created + title_suffix, "text": reasoning_text,
                "attachments": [], "inline_tools": [], "inline_media": [], "turn": turn,
            })
        if state.close_start >= 0:
            answer_text = raw[state.close_end:]
            if text_has_non_whitespace(answer_text) or turn.get("attachments"):
                sections.append({
                    "kind": "assistant", "title": "AI", "time": time_line,
                    "text": answer_text, "attachments": turn.get("attachments") or [],
                    "inline_tools": [], "inline_media": [], "turn": turn,
                })
        return sections

    def _assistant_ordered_sections(self, turn: dict[str, Any], created: str, title_suffix: str, include_reasoning: bool) -> list[dict[str, Any]]:
        diagnostic = chat_missing_reasoning_diagnostic(turn) if include_reasoning else ""
        diagnostic_sections = [{
            "kind": "thinking", "title": "REASONING UNAVAILABLE", "time": created + title_suffix,
            "text": diagnostic, "attachments": [], "inline_tools": [], "inline_media": [],
            "turn": turn, "provider_diagnostic": True,
        }] if diagnostic else []
        raw = str(turn.get("text") or "")
        tool_calls = list(turn.get("tool_calls") or [])
        stream_preview = str(turn.get("streaming_tool_preview") or "")
        stats_inline = self._stats_inline(turn)
        time_line = created + title_suffix
        if stats_inline:
            time_line = (time_line + "  |  " + stats_inline) if time_line else stats_inline

        incremental_reasoning = self._streaming_reasoning_sections(
            turn, raw, created, title_suffix, include_reasoning, time_line, tool_calls, stream_preview,
        )
        if incremental_reasoning is not None:
            return diagnostic_sections + incremental_reasoning if diagnostic_sections else incremental_reasoning

        # The overwhelmingly common streaming case is one ordinary assistant
        # section. Avoid a regex walk, protocol stripper, and temporary chunk list
        # on every UI publication when no reasoning/tool marker is present.
        possible_section_control = "<" in raw or "[[" in raw
        if (
            not tool_calls
            and not stream_preview
            and (
                not possible_section_control
                or ASSISTANT_SECTION_TOKEN_RE.search(raw) is None
            )
        ):
            if text_has_non_whitespace(raw) or turn.get("attachments"):
                return diagnostic_sections + [{
                    "kind": "assistant", "title": "AI", "time": time_line,
                    "text": raw, "attachments": turn.get("attachments") or [],
                    "inline_tools": [], "inline_media": [], "turn": turn,
                }]
            return diagnostic_sections

        sections: list[dict[str, Any]] = []
        current: dict[str, Any] | None = None
        mode = "assistant"
        used_tool_indexes: set[int] = set()

        def ensure(kind: str) -> dict[str, Any]:
            nonlocal current
            if current is not None and current.get("kind") != kind:
                flush()
            if current is None:
                current = {
                    "kind": kind,
                    "title": "THINKING" if kind == "thinking" else "AI",
                    "time": created + title_suffix if kind == "thinking" else time_line,
                    "text": "",
                    "_text_parts": [],
                    "attachments": (turn.get("attachments") or []) if kind == "assistant" else [],
                    "inline_tools": [],
                    "inline_media": [],
                    "turn": turn,
                }
            return current

        def append_text(kind: str, value: str) -> None:
            if value:
                ensure(kind).setdefault("_text_parts", []).append(value)

        def current_has_visible_text() -> bool:
            return bool(current is not None and any(str(part).strip() for part in (current.get("_text_parts") or [])))

        def flush() -> None:
            nonlocal current
            if current is None:
                return
            text = "".join(str(part) for part in current.pop("_text_parts", []))
            current["text"] = text
            tools = list(current.get("inline_tools") or [])
            current["inline_media"] = self._tool_call_media_outputs(tools)
            if text_has_non_whitespace(text) or tools or current.get("attachments") or current.get("inline_media"):
                sections.append(current)
            current = None

        def attach_tool(tool_index: int) -> None:
            if tool_index in used_tool_indexes:
                return
            section = ensure("assistant")
            if 0 <= tool_index < len(tool_calls):
                section.setdefault("inline_tools", []).append(tool_calls[tool_index])
                used_tool_indexes.add(tool_index)

        last = 0
        for match in ASSISTANT_SECTION_TOKEN_RE.finditer(raw):
            chunk = raw[last:match.start()]
            if chunk:
                clean = strip_tool_markup_from_text(chunk)
                if mode == "thinking":
                    if include_reasoning and clean.strip():
                        append_text("thinking", clean)
                else:
                    if current is not None and current.get("kind") == "thinking" and clean.strip():
                        flush()
                    if current is not None and current.get("kind") == "assistant" and current.get("inline_tools") and clean.strip():
                        flush()
                    if clean.strip():
                        append_text("assistant", clean)
                    elif current is not None:
                        current.setdefault("_text_parts", []).append(clean)
            explicit_tool_index = match.group(3)
            if explicit_tool_index is not None:
                try:
                    tool_index = int(explicit_tool_index)
                except Exception:
                    tool_index = -1
                attach_tool(tool_index)
                mode = "assistant"
            elif match.group(1):
                mode = "assistant"
            else:
                if current is not None and current.get("kind") == "assistant" and current_has_visible_text():
                    flush()
                mode = "thinking"
                if include_reasoning:
                    ensure("thinking")
            last = match.end()

        tail = raw[last:]
        if tail:
            clean_tail = strip_tool_markup_from_text(tail)
            if mode == "thinking":
                if include_reasoning and clean_tail.strip():
                    append_text("thinking", clean_tail)
            else:
                if current is not None and current.get("kind") == "thinking" and clean_tail.strip():
                    flush()
                if current is not None and current.get("kind") == "assistant" and current.get("inline_tools") and clean_tail.strip():
                    flush()
                if clean_tail.strip():
                    append_text("assistant", clean_tail)
                elif current is not None:
                    current.setdefault("_text_parts", []).append(clean_tail)
        flush()

        leftovers = [tool for idx, tool in enumerate(tool_calls) if idx not in used_tool_indexes]
        if leftovers:
            target = next((section for section in reversed(sections) if section.get("kind") == "assistant"), None)
            if target is None:
                target = {
                    "kind": "assistant", "title": "AI", "time": time_line, "text": "",
                    "attachments": turn.get("attachments") or [], "inline_tools": [],
                    "inline_media": [], "turn": turn,
                }
                sections.append(target)
            target.setdefault("inline_tools", []).extend(leftovers)
            target["inline_media"] = self._tool_call_media_outputs(target.get("inline_tools") or [])

        if stream_preview and str(turn.get("status") or "") == "streaming":
            target = next((section for section in reversed(sections) if section.get("kind") == "assistant"), None)
            if target is None:
                target = {
                    "kind": "assistant", "title": "AI", "time": time_line, "text": "",
                    "attachments": turn.get("attachments") or [], "inline_tools": [],
                    "inline_media": [], "turn": turn,
                }
                sections.append(target)
            preview_tools: list[dict[str, Any]] = []
            try:
                preview_payload = json.loads(stream_preview)
                preview_calls = preview_payload.get("tool_calls") if isinstance(preview_payload, dict) else []
            except Exception:
                preview_calls = []
            for preview_index, provider_call in enumerate(preview_calls or []):
                if not isinstance(provider_call, dict):
                    continue
                function = provider_call.get("function") if isinstance(provider_call.get("function"), dict) else {}
                arguments = function.get("arguments")
                try:
                    parsed_arguments = json.loads(arguments) if isinstance(arguments, str) and arguments.strip() else {}
                except Exception:
                    parsed_arguments = {"partial_arguments": str(arguments or "")}
                if not isinstance(parsed_arguments, dict):
                    parsed_arguments = {"arguments": parsed_arguments}
                preview_tools.append({
                    "tool_call_id": "constructing:" + str(provider_call.get("id") or preview_index),
                    "tool_name": str(function.get("name") or "function call"),
                    "input": parsed_arguments,
                    "status": "constructing",
                    "ok": None,
                    "started_at": str(turn.get("updated_at") or turn.get("created_at") or ""),
                    "provider_tool_call": copy.deepcopy(provider_call),
                    "raw_tool_call": json.dumps(provider_call, ensure_ascii=False, default=str),
                })
            if preview_tools:
                target.setdefault("inline_tools", []).extend(preview_tools)
            else:
                preview_block = "**Constructing function call**\n\n```text\n" + stream_preview + "\n```"
                existing = str(target.get("text") or "").rstrip()
                target["text"] = (existing + "\n\n" + preview_block).strip() if existing else preview_block

        if not sections and (text_has_non_whitespace(raw) or turn.get("attachments")):
            sections.append({
                "kind": "assistant", "title": "AI", "time": time_line,
                "text": strip_tool_markup_from_text(strip_reasoning_content(raw)),
                "attachments": turn.get("attachments") or [], "inline_tools": [],
                "inline_media": [], "turn": turn,
            })
        return diagnostic_sections + sections if diagnostic_sections else sections

    def _chat_sections_source_key(self, turns: list[dict[str, Any]], include_reasoning: bool) -> tuple[Any, ...]:
        """Build a cache key without rescanning the active transcript every frame."""
        active_key = self.state.chat_turn_cache_key
        if turns is self.state.chat_turn_cache and active_key is not None:
            last = turns[-1] if turns else {}
            # The file/revision key is authoritative for the active transcript.
            # O(1) tail metadata also protects direct in-memory append/status edits
            # without re-hashing every older message.
            last_tools = last.get("tool_calls") if isinstance(last.get("tool_calls"), list) else []
            last_tool = last_tools[-1] if last_tools and isinstance(last_tools[-1], dict) else {}
            return (
                "chat-active-sections",
                bool(include_reasoning),
                active_key,
                id(turns),
                len(turns),
                str(last.get("turn_id") or ""),
                str(last.get("updated_at") or last.get("created_at") or ""),
                str(last.get("status") or ""),
                len(str(last.get("text") or "")),
                len(str(last.get("streaming_tool_preview") or "")),
                len(last_tools),
                self._tool_calls_media_reuse_stamp(last_tools),
            )
        # Non-active callers and tests retain the full content-aware fallback.
        return (
            "chat-fallback-sections",
            bool(include_reasoning),
            tuple((
                str(t.get("turn_id") or ""),
                str(t.get("updated_at") or t.get("created_at") or ""),
                str(t.get("role") or ""),
                str(t.get("status") or ""),
                len(str(t.get("text") or "")),
                len(str(t.get("streaming_tool_preview") or "")),
                len(t.get("attachments") or []),
                tuple((
                    str(c.get("tool_name") or ""),
                    str(c.get("status") or ""),
                    str(c.get("ok") or ""),
                    str(c.get("elapsed_seconds") or ""),
                    self._tool_call_media_reuse_stamp(c),
                ) for c in (t.get("tool_calls") or []) if isinstance(c, dict)),
                fast_text_signature(str(t.get("text") or "")),
                fast_text_signature(str(t.get("streaming_tool_preview") or "")),
                str(t.get("compaction_meta") or ""),
            ) for t in turns),
        )

    @staticmethod
    def _chat_turn_reuse_stamp(
        turn: dict[str, Any], include_reasoning: bool,
    ) -> tuple[Any, ...]:
        """Return an O(1) mutation guard for one cached source turn."""
        text_obj = turn.get("text")
        preview_obj = turn.get("streaming_tool_preview")
        tools_obj = turn.get("tool_calls")
        tools = tools_obj if isinstance(tools_obj, list) else []
        last_tool = tools[-1] if tools and isinstance(tools[-1], dict) else {}
        return (
            bool(include_reasoning),
            id(turn),
            id(text_obj),
            len(str(text_obj or "")),
            id(preview_obj),
            len(str(preview_obj or "")),
            str(turn.get("updated_at") or turn.get("created_at") or ""),
            str(turn.get("status") or ""),
            bool(turn.get("hidden_from_ui", False)),
            id(tools_obj),
            len(tools),
            id(last_tool) if last_tool else 0,
            str(last_tool.get("status") or ""),
            str(last_tool.get("ok") or ""),
            str(last_tool.get("elapsed_seconds") or ""),
            len(str(last_tool.get("output_excerpt") or "")),
            len(str(last_tool.get("endpoint_stream_text") or "")),
            Panels._tool_calls_media_reuse_stamp(tools),
        )

    def _chat_sections(self, turns: list[dict[str, Any]], include_reasoning: bool) -> list[dict[str, Any]]:
        """Rebuild only the transcript suffix whose source turns changed.

        Keep section ranges and forwarded media state for identity-stable turns.
        Streaming updates invalidate the changed suffix instead of rescanning
        every earlier turn and reallocating the entire section list."""
        key = self._chat_sections_source_key(turns, include_reasoning)
        sections = (
            self.state.chat_sections_cache
            if isinstance(self.state.chat_sections_cache, list)
            else []
        )
        if self.state.chat_sections_cache_key == key:
            self.state.chat_sections_changed_from_index = len(sections)
            return sections

        source_turns = self.state.chat_sections_source_turns
        turn_ranges = self.state.chat_sections_turn_ranges
        pending_after_turn = self.state.chat_sections_pending_media_after_turn
        previous_key = self.state.chat_sections_cache_key
        cache_shape_valid = bool(
            isinstance(source_turns, list)
            and isinstance(turn_ranges, list)
            and isinstance(pending_after_turn, list)
            and len(source_turns) == len(turn_ranges) == len(pending_after_turn)
            and all(
                isinstance(row, tuple)
                and len(row) == 2
                and 0 <= int(row[0]) <= int(row[1]) <= len(sections)
                for row in turn_ranges
            )
        )
        same_reasoning_mode = bool(
            isinstance(previous_key, tuple)
            and len(previous_key) > 1
            and bool(previous_key[1]) == bool(include_reasoning)
        )

        rebuild_turn_index = 0
        if cache_shape_valid and same_reasoning_mode:
            if turns is self.state.chat_turn_cache:
                rebuild_turn_index = int(clamp(
                    self.state.chat_turn_changed_from_index,
                    0,
                    min(len(source_turns), len(turns)),
                ))
                # A direct in-memory tail mutation can change the O(1) source key
                # without going through ChatStore's revision history.  Rebuild the
                # last turn rather than trusting a stale "nothing changed" marker.
                if key != previous_key and rebuild_turn_index >= min(len(source_turns), len(turns)):
                    if len(source_turns) == len(turns) and turns:
                        rebuild_turn_index = len(turns) - 1
            else:
                # Non-active inspectors/tests do not have ChatStore revision
                # history.  Their bounded fallback may compare the identity-stable
                # prefix; the hot active transcript never enters this loop.
                common = min(len(source_turns), len(turns))
                while rebuild_turn_index < common:
                    old_turn = source_turns[rebuild_turn_index]
                    new_turn = turns[rebuild_turn_index]
                    if str(old_turn.get("turn_id") or "") != str(new_turn.get("turn_id") or ""):
                        break
                    range_start, range_end = turn_ranges[rebuild_turn_index]
                    cached_turn_sections = sections[int(range_start):int(range_end)]
                    current_stamp = self._chat_turn_reuse_stamp(new_turn, include_reasoning)
                    # Direct callers may mutate one source dictionary in place,
                    # so object identity alone is not a valid fallback guard.
                    # Compare against the immutable stamp captured in its prior
                    # sections; active ChatStore rendering never enters this loop.
                    if cached_turn_sections and all(
                        section.get("_turn_reuse_stamp") == current_stamp
                        for section in cached_turn_sections
                    ):
                        rebuild_turn_index += 1
                        continue
                    if not cached_turn_sections and bool(new_turn.get("hidden_from_ui", False)):
                        # Hidden turns deliberately own an empty section range.
                        # Their content cannot affect visible layout except through
                        # forwarded media, which is captured at the boundary.
                        rebuild_turn_index += 1
                        continue
                    break
                if len(source_turns) != len(turns):
                    rebuild_turn_index = min(rebuild_turn_index, common)

        # Preserve only the old changed suffix as reuse candidates.  A normal
        # stream contains one or two entries here rather than hundreds of turns.
        old_source_suffix: dict[int, dict[str, Any]] = {}
        old_section_suffix: dict[int, list[dict[str, Any]]] = {}
        if cache_shape_valid:
            for turn_index in range(rebuild_turn_index, len(source_turns)):
                start_index, end_index = turn_ranges[turn_index]
                old_source_suffix[turn_index] = source_turns[turn_index]
                old_section_suffix[turn_index] = sections[int(start_index):int(end_index)]

        if cache_shape_valid and rebuild_turn_index < len(turn_ranges):
            changed_section_index = int(turn_ranges[rebuild_turn_index][0])
        elif cache_shape_valid and rebuild_turn_index >= len(turn_ranges):
            changed_section_index = len(sections)
        else:
            rebuild_turn_index = 0
            changed_section_index = 0

        del sections[changed_section_index:]
        del source_turns[rebuild_turn_index:]
        del turn_ranges[rebuild_turn_index:]
        del pending_after_turn[rebuild_turn_index:]
        pending_generated_media: list[dict[str, Any]] = (
            list(pending_after_turn[-1]) if pending_after_turn else []
        )

        def add_section(section: dict[str, Any]) -> None:
            nonlocal pending_generated_media
            source_turn = section.get("turn") if isinstance(section.get("turn"), dict) else {}
            source_turn_id = str(source_turn.get("turn_id") or "")
            if source_turn_id and "_turn_reuse_stamp" not in section:
                section["_turn_reuse_stamp"] = self._chat_turn_reuse_stamp(
                    source_turn, include_reasoning,
                )
            if source_turn_id and "_turn_source_stamp" not in section:
                section["_turn_source_stamp"] = (
                    bool(include_reasoning),
                    bool(source_turn.get("hidden_from_ui", False)),
                    str(source_turn.get("role") or "message").lower(),
                    str(source_turn.get("status") or ""),
                    str(source_turn.get("updated_at") or source_turn.get("created_at") or ""),
                    fast_text_signature(str(source_turn.get("text") or "")),
                    fast_text_signature(str(source_turn.get("streaming_tool_preview") or "")),
                    len(source_turn.get("attachments") or []),
                    tuple((
                        str(call.get("tool_call_id") or call.get("id") or ""),
                        str(call.get("status") or ""),
                        str(call.get("ok") or ""),
                        str(call.get("elapsed_seconds") or ""),
                        len(str(call.get("output_excerpt") or "")),
                        len(str(call.get("endpoint_stream_text") or "")),
                        self._tool_call_media_reuse_stamp(call),
                    ) for call in (source_turn.get("tool_calls") or []) if isinstance(call, dict)),
                    str(source_turn.get("compaction_meta") or ""),
                )
            media = list(section.get("inline_media") or [])
            if media:
                pending_generated_media = media
            elif pending_generated_media and section.get("kind") == "assistant" and str(section.get("text") or "").strip():
                # Keep generated media visible even when the actual Comfy tool call
                # happened in a hidden/thinking segment and the next visible AI
                # response only says "generated N images".
                if re.search(r"\b(generated|saved|output|image|video)\b", str(section.get("text") or ""), re.I):
                    # Reused sections are immutable layout objects. Clone before
                    # attaching forwarded media so an exact height cached before
                    # the media existed can never be reused by the new card.
                    section = dict(section)
                    for cache_name in (
                        "_chat_row_layout_cache", "_chat_body_geometry_cache",
                        "_chat_body_blocks_cache",
                    ):
                        section.pop(cache_name, None)
                    section["inline_media"] = list(pending_generated_media)
                    pending_generated_media = []
            sections.append(section)

        for turn_index in range(rebuild_turn_index, len(turns)):
            turn = turns[turn_index]
            section_start = len(sections)
            old_turn = old_source_suffix.get(turn_index)
            reusable = old_section_suffix.get(turn_index, [])
            if old_turn is not None and str(old_turn.get("turn_id") or "") != str(turn.get("turn_id") or ""):
                reusable = []

            # ChatStore normally replaces only the changed turn dictionary. The
            # O(1) stamp also catches direct in-place test/recovery edits without
            # rescanning historical text or every historical tool call.
            reuse_stamp = self._chat_turn_reuse_stamp(turn, include_reasoning)
            reused = bool(reusable) and all(
                previous.get("_turn_reuse_stamp") == reuse_stamp
                for previous in reusable
            )
            if not reused and reusable:
                turn_stamp = (
                    bool(include_reasoning),
                    bool(turn.get("hidden_from_ui", False)),
                    str(turn.get("role") or "message").lower(),
                    str(turn.get("status") or ""),
                    str(turn.get("updated_at") or turn.get("created_at") or ""),
                    fast_text_signature(str(turn.get("text") or "")),
                    fast_text_signature(str(turn.get("streaming_tool_preview") or "")),
                    len(turn.get("attachments") or []),
                    tuple((
                        str(call.get("tool_call_id") or call.get("id") or ""),
                        str(call.get("status") or ""),
                        str(call.get("ok") or ""),
                        str(call.get("elapsed_seconds") or ""),
                        len(str(call.get("output_excerpt") or "")),
                        len(str(call.get("endpoint_stream_text") or "")),
                        self._tool_call_media_reuse_stamp(call),
                    ) for call in (turn.get("tool_calls") or []) if isinstance(call, dict)),
                    str(turn.get("compaction_meta") or ""),
                )
                reused = all(
                    previous.get("_turn_source_stamp") == turn_stamp
                    for previous in reusable
                )
            if reused:
                for previous in reusable:
                    add_section(previous)
            elif not bool(turn.get("hidden_from_ui", False)):
                role = str(turn.get("role", "message")).lower()
                created = format_display_datetime(str(turn.get("created_at", "")))
                status = str(turn.get("status", ""))
                title_suffix = (f"  [{status}]" if status and status not in {"complete", ""} else "")
                compaction_meta = turn.get("compaction_meta") if isinstance(turn.get("compaction_meta"), dict) else {}
                if str(compaction_meta.get("kind") or "") == "chat_context_compaction":
                    display_text = (
                        str(turn.get("text") or "Compacting chat context…")
                        if status == "streaming"
                        else str(compaction_meta.get("display_text") or turn.get("text") or "Context compacted")
                    )
                    add_section({
                        "kind": "compaction",
                        "title": "CONTEXT COMPACTION" + (" (STREAMING)" if status == "streaming" else ""),
                        "time": created + title_suffix,
                        "text": display_text,
                        "details": str(turn.get("compaction_details") or ""),
                        "compaction_meta": compaction_meta,
                        "collapsed": status == "complete",
                        "turn": turn,
                    })
                elif role in {"thinking", "reasoning", "thought"}:
                    if include_reasoning:
                        add_section({"kind": "thinking", "title": "THINKING", "time": created, "text": str(turn.get("text", "")), "turn": turn})
                elif role == "user":
                    visible, _reasoning = self._visible_text_and_reasoning(turn, include_reasoning)
                    user_stats_inline = self._user_stats_inline(turn)
                    user_time_line = (created + "  |  " + user_stats_inline) if created and user_stats_inline else (user_stats_inline or created)
                    if is_chat_expert_mode_prompt_turn(turn):
                        add_section({
                            "kind": "expert_mode",
                            "title": "CHECKLISTS CONTINUATION",
                            "time": user_time_line,
                            "text": visible or str(turn.get("text", "")),
                            "attachments": turn.get("attachments") or [],
                            "turn": turn,
                        })
                    else:
                        add_section({"kind": "user", "title": "USER", "time": user_time_line, "text": visible or str(turn.get("text", "")), "attachments": turn.get("attachments") or [], "turn": turn})
                elif role == "assistant":
                    # _assistant_ordered_sections performs the one required scan
                    # for reasoning/tool markers. Calling
                    # _visible_text_and_reasoning first doubled the cost for
                    # multi-megabyte streaming cards.
                    for section in self._assistant_ordered_sections(
                        turn, created, title_suffix, include_reasoning,
                    ):
                        add_section(section)
                else:
                    visible, _reasoning = self._visible_text_and_reasoning(turn, include_reasoning)
                    add_section({"kind": "metadata", "title": role.upper(), "time": created, "text": visible or str(turn.get("text", "")), "turn": turn})

            source_turns.append(turn)
            turn_ranges.append((section_start, len(sections)))
            pending_after_turn.append(list(pending_generated_media))

        self.state.chat_sections_cache_key = key
        self.state.chat_sections_cache = sections
        self.state.chat_sections_changed_from_index = int(clamp(
            changed_section_index, 0, len(sections),
        ))
        return sections

    def _section_colors(self, kind: str) -> tuple[Color, Color, Color]:
        # micro-opt: every visible card asks for these every frame.
        k = str(kind or "metadata")
        cache = getattr(self.r, "_chat_section_color_cache", {})
        cached = cache.get(k)
        if cached is not None:
            return cached
        if k == "user":
            out = (theme_mix(Palette.panel3, Palette.white, 0.03), Palette.border, Color(180, 210, 255))
        elif k == "assistant":
            out = (Palette.input_bg, Palette.border, Palette.accent)
        elif k == "thinking":
            out = (Color(7, 18, 39), theme_alpha(Color(45, 115, 225), 135), Color(88, 150, 255))
        elif k == "tool":
            out = (Color(3, 8, 24), theme_alpha(Color(40, 110, 220), 150), Color(40, 110, 220))
        elif k == "tool_stream":
            out = (Color(4, 35, 20), theme_alpha(Color(54, 200, 115), 190), Color(78, 225, 145))
        elif k == "compaction":
            out = (Color(48, 34, 6), theme_alpha(Color(224, 166, 46), 210), Color(255, 205, 96))
        elif k == "expert_mode":
            out = (Color(54, 25, 4), theme_alpha(Color(230, 118, 20), 220), Color(255, 179, 82))
        else:
            out = (Palette.panel2, theme_alpha(Palette.border, 150), Palette.muted2)
        cache[k] = out
        return out

    def _copy_text(self, text: str) -> None:
        if self.r.host:
            self.r.host.set_clipboard_text(text)

    def _chat_section_action(self, action: str, section: dict[str, Any]) -> None:
        section_kind = str(section.get("kind") or "")
        if action == "details":
            if section_kind == "compaction":
                details = str(section.get("details") or section.get("text") or "")
                self.state.modal = {
                    "kind": "tool_details",
                    "title": "Chat context compaction",
                    "tool_result": {},
                    "details": details,
                }
                return
            result = section.get("tool_result") if isinstance(section.get("tool_result"), dict) else {}
            self.state.modal = {"kind": "tool_details", "title": self._tool_summary_text(result), "tool_result": result, "details": self._tool_details_text(result)}
            return
        if action == "copy":
            if section_kind == "tool":
                result = section.get("tool_result") if isinstance(section.get("tool_result"), dict) else {}
                self._copy_text(self._tool_details_text(result))
            elif section_kind == "compaction":
                self._copy_text(str(section.get("details") or section.get("text") or ""))
            else:
                self._copy_text(str(section.get("text") or ""))
            return
        turn = section.get("turn") or {}
        turn_id = str(turn.get("turn_id") or "")
        wsid = self.state.active_scope_id
        cid = self.state.active_chat_id
        if not wsid or not cid or not turn_id:
            return
        if action == "regen":
            endpoint_profile_id = self.services.chats.get_chat_endpoint_profile_id(cid)
            self.services.chat.regenerate_from_turn(wsid, cid, turn_id, endpoint_profile_id)
        elif action == "delete":
            self.services.chats.truncate_after_turn(wsid, cid, turn_id, include_turn=False)
            self.state.scroll["chat.thread"] = 0
        elif action == "branch":
            conv = self.services.chats.branch_chat(wsid, cid, turn_id)
            self._switch_active_chat(
                str(conv["chat_id"]), save_current=True, reset_scroll=True, restore_composer=True,
            )

    def _active_chat_search_highlight_terms(self) -> tuple[str, ...]:
        """Return draw-only highlight terms while the Chat search surface is active."""
        if not bool(self.state.chat_search_active):
            return ()
        return normalize_search_highlight_terms(self.state.chat_search_query)


    def _draw_chat_section(
        self, widget_id: str, rect: Rect, section: dict[str, Any], *,
        visible_clip: Rect | None = None, layout_key: str | None = None,
        interactive: bool = True,
    ) -> None:
        kind = str(section.get("kind") or "metadata")
        fill, border, accent = self._section_colors(kind)
        if visible_clip is not None:
            visible_rect = rect_intersection(rect, visible_clip)
            if visible_rect is None:
                return
        else:
            visible_rect = rect
        if kind == "compaction" and bool(section.get("collapsed")):
            self.r.draw_round_rect(rect, 14, fill)
            self.r.draw_round_outline(rect, 14, border)
            inner = rect.inset(12)
            dot_size = 8
            dot = Rect(inner.x, inner.y + max(0, (inner.h - dot_size) // 2), dot_size, dot_size)
            self.r.draw_round_rect(dot, 5, accent)
            button_w = 40
            gap = 6
            details_rect = Rect(inner.x + inner.w - button_w * 2 - gap, inner.y, button_w, inner.h)
            copy_rect = Rect(inner.x + inner.w - button_w, inner.y, button_w, inner.h)
            text_right = details_rect.x if interactive else inner.x + inner.w
            text_rect = Rect(
                inner.x + dot_size + 10, inner.y,
                max(1, text_right - (inner.x + dot_size + 10) - 10), inner.h,
            )
            self.widgets.clipped_text(
                text_rect, str(section.get("text") or "Context compacted"), accent, align="left",
                tooltip=(
                    self._cached_chat_section_stats_tooltip(section)
                    if interactive and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, text_rect)
                    else ""
                ),
                tooltip_id=widget_id + ".stats",
            )
            if interactive and self.widgets.button(
                widget_id + ".details", details_rect, "", icon="chat_compact",
                tooltip="View exact post-compaction endpoint messages",
            ):
                self._chat_section_action("details", section)
            if interactive and self.widgets.button(
                widget_id + ".copy", copy_rect, "", icon="copy",
                tooltip="Copy full compaction details",
            ):
                self._chat_section_action("copy", section)
            return
        # Normal cards use the renderer's cached rounded geometry. Extremely
        # tall streaming cards use bounded visible geometry instead: giving SDL
        # a hundreds-of-thousands-pixel surface and changing that cache key on
        # every token publication can dominate the frame despite clipping.
        virtual_threshold = max(
            CHAT_CARD_VIRTUAL_SURFACE_MIN_HEIGHT_PX,
            int((visible_clip.h if visible_clip is not None else 0) * CHAT_CARD_VIRTUAL_SURFACE_VIEW_MULTIPLIER),
        )
        if visible_clip is not None and rect.h > virtual_threshold:
            fill_rects, border_rects = virtualized_rounded_rect_geometry(rect, visible_clip, 16)
            for fill_rect in fill_rects:
                self.r.draw_rect(fill_rect, fill)
            for border_rect in border_rects:
                self.r.draw_rect(border_rect, border)
        else:
            self.r.draw_round_rect(rect, 16, fill)
            self.r.draw_round_outline(rect, 16, border)
        inner = rect.inset(14)
        header_h = self._chat_card_header_height()
        title_rect = Rect(inner.x + 18, inner.y + 3, max(1, inner.w - 36), max(28, self.f.line_h + 4))
        dot_size = 7
        dot = Rect(inner.x + 2, title_rect.y + max(0, (title_rect.h - dot_size) // 2), dot_size, dot_size)
        self.r.draw_round_rect(dot, max(1, dot_size // 2 + 1), accent)
        icon_w = 44
        gap = 6
        actions: list[tuple[str, str, bool, int, str]] = []
        if interactive:
            actions = [("copy", "copy", False, icon_w, "")]
            if kind == "compaction":
                actions = [("details", "chat_compact", False, icon_w, ""), ("copy", "copy", False, icon_w, "")]
            elif kind in {"user", "assistant"}:
                # Visual left-to-right order: Copy, Regenerate, Branch, Delete.
                actions = [("copy", "copy", False, icon_w, ""), ("regen", "regen", False, icon_w, ""), ("branch", "branch", False, icon_w, ""), ("delete", "delete", True, icon_w, "")]
        total_buttons_w = sum(a[3] for a in actions) + max(0, len(actions) - 1) * gap
        title_w = max(1, inner.w - total_buttons_w - 36)
        title_rect = Rect(inner.x + 18, inner.y + 3, title_w, max(28, self.f.line_h + 4))
        self.widgets.clipped_text(
            title_rect,
            str(section.get("title") or "MESSAGE"),
            Palette.text,
            align="left",
            tooltip=(
                self._cached_chat_section_stats_tooltip(section)
                if interactive and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, title_rect)
                else ""
            ),
            tooltip_id=widget_id + ".stats",
        )
        btn_y = inner.y + 4
        x = inner.x + inner.w - total_buttons_w
        for action_name, icon_name, is_danger, button_w, label in actions:
            icon_value = icon_name or None
            if self.widgets.button(widget_id + "." + action_name, Rect(x, btn_y, button_w, icon_w), label, danger=is_danger, icon=icon_value):
                self._chat_section_action(action_name, section)
            x += button_w + gap
        y = inner.y + header_h + 8
        attachments = list(section.get("attachments") or [])
        if attachments:
            chip_x = inner.x
            chip_y = y
            for ai, att in enumerate(attachments):
                label = str(att.get("filename") or "file")
                chip_w = min(max(128, self.widgets._text_width(label) + 48), max(160, inner.w - 8))
                if chip_x + chip_w > inner.x + inner.w:
                    chip_x = inner.x
                    chip_y += 38
                self._draw_attachment_chip(
                    widget_id + f".att.{ai}", Rect(chip_x, chip_y, chip_w, 32), att,
                    interactive=interactive,
                )
                chip_x += chip_w + 8
            y = chip_y + 42
        body_h = max(1, rect.y + rect.h - y - CHAT_CARD_BODY_BOTTOM_PAD_PX)
        body = Rect(inner.x, y, inner.w, body_h)
        raw_text = str(section.get("text") or "")
        inline_tools = list(section.get("inline_tools") or [])
        media = list(section.get("inline_media") or [])
        media_h = self._inline_media_grid_height(media, body.w)
        media_reserve_h = media_h + (8 if media_h else 0)
        available_body_h = max(0, body.h - media_reserve_h)
        body_clip_rect = Rect(body.x, body.y, body.w, available_body_h)
        body_visible_clip = (
            rect_intersection(body_clip_rect, visible_clip)
            if visible_clip is not None else body_clip_rect
        )
        body_blocks = self._chat_body_blocks_for_section(section)
        text_w = max(1, body.w - 24)
        layout_w = max(1, text_w - 16)
        resolved_layout_key = layout_key or widget_id + ".body"
        body_geometry = self._chat_body_geometry_for_section(
            section, body_blocks, resolved_layout_key, layout_w, text_w,
        )
        entries = body_geometry.get("entries") if isinstance(body_geometry.get("entries"), list) else []
        tops = body_geometry.get("tops") if isinstance(body_geometry.get("tops"), list) else []
        heights = body_geometry.get("heights") if isinstance(body_geometry.get("heights"), list) else []
        visible_top = 0
        visible_bottom = available_body_h
        if available_body_h <= 0 or body_visible_clip is None:
            first_body = end_body = 0
        elif visible_clip is not None:
            visible_top = max(0, body_visible_clip.y - body.y)
            visible_bottom = min(
                available_body_h, body_visible_clip.y + body_visible_clip.h - body.y,
            )
            first_body, end_body = self._visible_chat_body_block_range(
                tops, heights, visible_top, visible_bottom,
            )
        else:
            first_body, end_body = 0, len(entries)
        for entry_index in range(first_body, end_body):
            entry = entries[entry_index]
            block = entry.get("block") if isinstance(entry.get("block"), dict) else {}
            bi = int(entry.get("block_index") or 0)
            cursor_y = body.y + int(entry.get("top") or 0)
            if cursor_y >= body.y + available_body_h:
                continue
            block_h = min(
                int(entry.get("height") or 1),
                max(0, body.y + available_body_h - cursor_y),
            )
            if block_h <= 0:
                continue
            if block.get("type") == "tool":
                tool_call = block.get("tool") if isinstance(block.get("tool"), dict) else {}
                horizontal_pad = min(
                    CHAT_TOOL_ROW_HORIZONTAL_BUFFER_PX // 2, max(0, (body.w - 1) // 2),
                )
                row_rect = Rect(
                    body.x + horizontal_pad, cursor_y,
                    max(1, body.w - horizontal_pad * 2), block_h,
                )
                self._draw_inline_tool_row(
                    widget_id + f".toolrow.{block.get('tool_index', bi)}",
                    row_rect, tool_call, tool_index=int(block.get("tool_index", bi)),
                    interactive=interactive,
                )
                continue
            if block.get("type") == "review_result":
                review_payload = block.get("review") if isinstance(block.get("review"), dict) else {}
                review_markdown = str(block.get("markdown") or "")
                horizontal_pad = min(
                    CHAT_REVIEW_CARD_HORIZONTAL_BUFFER_PX // 2, max(0, (body.w - 1) // 2),
                )
                review_rect = Rect(
                    body.x + horizontal_pad, cursor_y,
                    max(1, body.w - horizontal_pad * 2), block_h,
                )
                block_key = str(entry.get("block_key") or f"{resolved_layout_key}.block.{bi}")
                self._draw_checklist_review_result_card(
                    widget_id + f".review.{block.get('tool_index', bi)}",
                    review_rect, review_payload, review_markdown,
                    visible_clip=body_visible_clip, cache_key=block_key, interactive=interactive,
                )
                continue
            block_text = str(block.get("text") or "")
            layout = entry.get("layout")
            if not isinstance(layout, TextLayout):
                continue
            block_key = str(entry.get("block_key") or f"{resolved_layout_key}.block.{bi}")
            text_rect = Rect(body.x, cursor_y, text_w, block_h)
            neutral_thinking = kind == "thinking"
            self.widgets.markdown_renderer.view(
                widget_id + f".body.{bi}",
                text_rect,
                block_text,
                selectable=interactive,
                draw_card=False,
                vertical_scroll=False,
                visible_clip=body_visible_clip,
                cache_key=block_key,
                neutral_code_color=neutral_thinking,
                incremental_large=self._chat_section_uses_incremental_layout(section, block_text),
                cache_textures=False,
                pointer_interactive=interactive,
                highlight_terms=self._active_chat_search_highlight_terms(),
            )
        if media:
            media_rect = self._chat_inline_media_rect(
                body, int(body_geometry.get("total_height") or 0), media_h,
            )
            if media_rect is not None:
                self._draw_inline_media_grid(
                    widget_id + ".media", media_rect, media, interactive=interactive,
                )


    def _chat_summary_dialog_text(self, scope_id: str, chat_id: str) -> str:
        summary = load_chat_summary_record(self.services.storage.paths, chat_id)
        one = str(summary.get("one_sentence_summary") or "").strip()
        bullets = str(summary.get("bullet_summary_markdown") or summary.get("summary_markdown") or "").strip()
        updated = str(summary.get("updated_at") or "not generated yet")
        stale = "stale" if summary.get("stale") else ("current" if summary.get("updated_at") else "not generated")
        parts = [f"**Status:** {stale}  ", f"**Updated:** {updated}"]
        if one:
            parts.append(f"\n**One-line summary**\n{one}")
        if bullets:
            parts.append(f"\n**Bullet summary**\n{bullets}")
        if not one and not bullets:
            parts.append("\n_No stored summary exists yet. Click **Refresh** to generate and store one using the global Chat Endpoint._")
        return "\n".join(parts)

    def _open_current_chat_summary(self) -> None:
        wsid = self.state.active_scope_id
        cid = self.state.active_chat_id
        if not wsid or not cid:
            return
        self.state.modal = {
            "kind": "chat_summary",
            "title": "Chat Summary",
            "summary": self._chat_summary_dialog_text(wsid, cid),
            "summary_chat_id": cid,
            "summary_scope_id": wsid,
        }

    async def _ui_refresh_current_chat_summary(self, scope_id: str, chat_id: str) -> None:
        try:
            summary = await self.services.summaries.refresh_chat_summary(scope_id, chat_id)
            if isinstance(self.state.modal, dict) and self.state.modal.get("summary_chat_id") == chat_id:
                self.state.modal["summary"] = self._chat_summary_dialog_text(scope_id, chat_id)
                self.state.modal.pop("error", None)
        except Exception as e:
            if isinstance(self.state.modal, dict):
                self.state.modal["error"] = f"Refresh failed: {type(e).__name__}: {e}"
            self.state.add_toast("Chat summary refresh failed", str(e), "error")

    def _chat_runtime_stats_cached(self, turns: list[dict[str, Any]]) -> dict[str, Any]:
        """Refresh live toolbar statistics at most once per monotonic second.

        Terminal revisions are recomputed immediately so final totals are exact.
        Token-by-token transcript updates do not require a full statistics scan."""
        try:
            is_running = getattr(self.services.chat, "is_running", None)
            running = bool(
                self.state.active_chat_id
                and callable(is_running)
                and is_running(self.state.active_chat_id)
            )
        except Exception:
            running = False
        if turns is self.state.chat_turn_cache and self.state.chat_turn_cache_key is not None:
            source_key: Any = self.state.chat_turn_cache_key
            source_identity: Any = (
                str(self.state.active_scope_id or ""),
                str(self.state.active_chat_id or ""),
                id(turns),
            )
        else:
            last = turns[-1] if turns else {}
            source_key = (
                id(turns), len(turns), str(last.get("turn_id") or ""),
                str(last.get("updated_at") or last.get("created_at") or ""),
                str(last.get("status") or ""),
            )
            source_identity = (id(turns),)
        key = (
            "running", source_identity, int(time.monotonic())
        ) if running else (
            "terminal", source_key,
        )
        if self.state.chat_runtime_stats_cache_key == key:
            return self.state.chat_runtime_stats_cache
        stats = chat_thread_runtime_stats(turns)
        self.state.chat_runtime_stats_cache_key = key
        self.state.chat_runtime_stats_cache = stats
        return stats


    @staticmethod
    def _chat_activity_elapsed_label(seconds: Any) -> str:
        try:
            elapsed = max(0.0, float(seconds))
        except Exception:
            elapsed = 0.0
        return f"{elapsed:.1f} s"

    @staticmethod
    def _chat_activity_started_epoch(turn: dict[str, Any]) -> float | None:
        for key in ("started_at", "created_at", "updated_at"):
            parsed = _iso_timestamp_epoch(turn.get(key))
            if parsed is not None:
                return parsed
        return None

    @staticmethod
    def _chat_error_detail(turn: dict[str, Any]) -> str:
        if not isinstance(turn, dict):
            return ""
        status = str(turn.get("status") or "").strip().lower()
        text = str(turn.get("text") or "")
        detail = ""
        matches = list(re.finditer(r"(?is)\[error\]\s*(.+)", text))
        if matches:
            detail = matches[-1].group(1)
        elif status == "error":
            detail = text
        if not detail:
            return ""
        return re.sub(r"\s+", " ", detail).strip()[:2000]

    def _chat_toolbar_activity(
        self, turns: list[dict[str, Any]],
    ) -> tuple[str, str]:
        """Return the always-present selected-Chat status and its full tooltip.

        Scheduler wait/ready/paused states intentionally read Inactive. Provider
        work begins at Prompt only after the Task actually owns an endpoint slot.
        A live compaction card and a live tool phase override provider-generation
        metadata because those are the operations currently blocking progress.
        """
        now_mono = time.monotonic()
        now_epoch = time.time()

        # Compaction is represented by its ordinary streaming card. This remains
        # authoritative even while the nested semantic-summary request itself is
        # technically in a provider inference phase.
        for turn in reversed(turns or []):
            if not isinstance(turn, dict):
                continue
            if (
                str(turn.get("role") or "").lower() == "compaction"
                and str(turn.get("status") or "").lower() == "streaming"
            ):
                started_epoch = self._chat_activity_started_epoch(turn)
                elapsed = max(0.0, now_epoch - started_epoch) if started_epoch is not None else 0.0
                label = f"Compaction {self._chat_activity_elapsed_label(elapsed)}"
                return label, label

        chat_id = str(self.state.active_chat_id or "")
        runtime = getattr(self.services, "chat", None)
        monitor = getattr(runtime, "monitor", None)
        task_ids = getattr(runtime, "_monitor_task_ids", {})
        task_id = str(task_ids.get(chat_id) or "") if isinstance(task_ids, dict) else ""
        snapshot: dict[str, Any] = {}
        if task_id and monitor is not None:
            getter = getattr(monitor, "record_snapshot", None)
            if callable(getter):
                try:
                    value = getter(task_id)
                    snapshot = value if isinstance(value, dict) else {}
                except Exception:
                    snapshot = {}

        if snapshot:
            metadata = snapshot.get("metadata") if isinstance(snapshot.get("metadata"), dict) else {}
            state = str(snapshot.get("state") or "").strip().lower()
            phase = str(metadata.get("phase") or "ready").strip().lower()
            if state == "failed":
                detail = str(metadata.get("activity_detail") or snapshot.get("description") or "Task failed")
                detail = re.sub(r"\s+", " ", detail).strip()
                return f"Error: {detail[:240]}", f"Error: {detail}"
            if state in {"completed", "cancelled"}:
                return "Inactive", "Inactive"
            activity = str(metadata.get("activity") or "inactive").strip().lower()
            if activity == "cooldown":
                try:
                    cooldown_until = float(metadata.get("cooldown_until_monotonic"))
                    remaining = max(0.0, cooldown_until - now_mono)
                except Exception:
                    remaining = 0.0
                recovery = str(metadata.get("cooldown_kind") or "") == "error_recovery"
                name = "Endpoint Error Recovery" if recovery else "Cooldown"
                attempt_label = f" {int(metadata.get('cooldown_attempt') or 0)}/{int(metadata.get('cooldown_maximum') or 0)}" if recovery else ""
                label = f"{name}{attempt_label} {self._chat_activity_elapsed_label(remaining)}"
                reason = re.sub(
                    r"\s+", " ", str(metadata.get("cooldown_reason") or "Endpoint rate-limit cooldown"),
                ).strip()
                attempt = max(0, int(metadata.get("cooldown_attempt") or 0))
                maximum = max(0, int(metadata.get("cooldown_maximum") or 0))
                attempt_line = f"\nRetry: {attempt}/{maximum}" if attempt and maximum else ""
                waited = max(0.0, float(metadata.get("endpoint_wait_seconds") or 0.0))
                tooltip = (
                    f"{label}\n{reason}{attempt_line}\n"
                    f"Accumulated endpoint cooldown: {format_compact_duration_seconds(waited)}.\n"
                    "Cooldown consumes no endpoint slot; the Task re-enters the endpoint queue automatically afterward, and Pause/Stop remain responsive."
                )
                return label, tooltip
            if phase == "tool":
                try:
                    started_mono = float(metadata.get("phase_started_monotonic"))
                    elapsed = max(0.0, now_mono - started_mono)
                except Exception:
                    elapsed = 0.0
                label = f"Tool {self._chat_activity_elapsed_label(elapsed)}"
                return label, label
            if str(metadata.get("activity") or "") == "retrying" and phase not in {"paused", "pausing"} and not metadata.get("pause_requested"):
                detail = str(metadata.get("activity_detail") or "Retrying endpoint request")
                return "Retrying", detail
            if phase in {"queued", "ready", "active", "paused", "pausing"}:
                return "Inactive", "Inactive"
            if phase == "inference":
                activity, elapsed, stalled_for = llm_inference_activity_snapshot(metadata, now_mono)
                if activity == "error":
                    detail = re.sub(r"\s+", " ", str(metadata.get("activity_detail") or "Endpoint request failed")).strip()
                    return f"Error: {detail[:240]}", f"Error: {detail}"
                name = {"prompt": "Prompt", "thinking": "Thinking", "answer": "Answer"}[activity]
                try:
                    stall_warning_seconds = (
                        monitor.activity_stall_warning_seconds()
                        if monitor is not None and hasattr(monitor, "activity_stall_warning_seconds")
                        else llm_activity_stall_warning_seconds(self.services.storage.load_config_view())
                    )
                except Exception:
                    stall_warning_seconds = LLM_ACTIVITY_STALL_WARNING_MINUTES_DEFAULT * 60.0
                if stalled_for >= stall_warning_seconds:
                    stalled_label = self._chat_activity_elapsed_label(stalled_for)
                    elapsed_label = self._chat_activity_elapsed_label(elapsed)
                    label = f"Stalled: {name} {stalled_label}"
                    tooltip = (
                        f"{name} request has produced no endpoint stream progress for {stalled_label}.\n"
                        f"Total request time: {elapsed_label}.\n"
                        "The endpoint no-progress timeout resets on meaningful provider progress. "
                        "Empty timed-out attempts are retried within the configured retry limit; Stop cancels recovery."
                    )
                    return label, tooltip
                if activity == "prompt" and metadata.get("prompt_progress_percent") is not None:
                    try:
                        progress = min(100.0, max(0.0, float(metadata["prompt_progress_percent"])))
                    except Exception:
                        progress = None
                    if progress is not None:
                        label = f"Prompt {progress:.0f}%"
                        processed = metadata.get("prompt_tokens_processed")
                        total = metadata.get("prompt_tokens_total")
                        if processed is not None and total is not None:
                            tooltip = f"{label}\nPrompt tokens: {int(processed):,} / {int(total):,}"
                        else:
                            tooltip = label
                        return label, tooltip
                label = f"{name} {self._chat_activity_elapsed_label(elapsed)}"
                return label, label

        # Minimal test runtimes and a tiny window between Task setup/publication
        # can lack monitor metadata. Infer the same stage from the newest live card,
        # but never revive a stale streaming card after the owner has stopped.
        runtime_is_running = getattr(runtime, "is_running", None)
        allow_streaming_fallback = True
        if callable(runtime_is_running):
            try:
                allow_streaming_fallback = bool(runtime_is_running(chat_id))
            except Exception:
                allow_streaming_fallback = True
        for turn in reversed(turns or []) if allow_streaming_fallback else ():
            if not isinstance(turn, dict):
                continue
            if str(turn.get("status") or "").lower() != "streaming":
                continue
            if str(turn.get("role") or "").lower() != "assistant":
                continue
            calls = turn.get("tool_calls") if isinstance(turn.get("tool_calls"), list) else []
            running_call = next((
                row for row in reversed(calls)
                if isinstance(row, dict) and str(row.get("status") or "").lower() == "running"
            ), None)
            if running_call is not None:
                elapsed = tool_call_elapsed_seconds(running_call, current_time=now_epoch)
                label = f"Tool {self._chat_activity_elapsed_label(elapsed)}"
                return label, label
            text = str(turn.get("text") or "")
            visible = usable_assistant_text(text)
            reasoning = str(
                turn.get("reasoning_content") or turn.get("thinking")
                or reasoning_content_from_text(text) or ""
            ).strip()
            name = "Answer" if visible else ("Thinking" if reasoning else "Prompt")
            started_epoch = self._chat_activity_started_epoch(turn)
            elapsed = max(0.0, now_epoch - started_epoch) if started_epoch is not None else 0.0
            label = f"{name} {self._chat_activity_elapsed_label(elapsed)}"
            return label, label

        latest = next((turn for turn in reversed(turns or []) if isinstance(turn, dict)), {})
        detail = self._chat_error_detail(latest)
        if detail:
            return f"Error: {detail[:240]}", f"Error: {detail}"
        return "Inactive", "Inactive"

    def _chat_context_usage_line(self, turns: list[dict[str, Any]]) -> str:
        """Return a next-request context snapshot without rebuilding it per token.

        Constructing the exact prepared message array is intentionally expensive.
        During one provider stream, only the not-yet-replayed assistant tail is
        changing, so the toolbar keeps the request-boundary snapshot.  The first
        terminal revision recomputes immediately, including that complete output,
        tool results, Skills, attachments, and schemas.
        """
        scope_id = str(self.state.active_scope_id or "")
        chat_id = str(self.state.active_chat_id or "")
        if not scope_id or not chat_id:
            return "Context Used: unavailable"
        try:
            endpoint_profile_id = self.services.chats.get_chat_endpoint_profile_id(chat_id)
        except Exception:
            return "Context Used: unavailable"
        try:
            is_running = getattr(self.services.chat, "is_running", None)
            running = bool(chat_id and callable(is_running) and is_running(chat_id))
        except Exception:
            running = False
        if turns is self.state.chat_turn_cache and self.state.chat_turn_cache_key is not None:
            source_revision: Any = self.state.chat_turn_cache_key
        else:
            latest = turns[-1] if turns and isinstance(turns[-1], dict) else {}
            source_revision = (
                id(turns), len(turns), str(latest.get("turn_id") or ""),
                str(latest.get("updated_at") or latest.get("created_at") or ""),
                str(latest.get("status") or ""),
                len(str(latest.get("text") or "")),
            )
        latest_turn = turns[-1] if turns and isinstance(turns[-1], dict) else {}
        # Streaming revisions update text/status constantly; only a new durable turn
        # changes this key. Preserve the existing per-stream O(1) reuse guarantee.
        request_boundary = str(latest_turn.get("turn_id") or "")
        base_key = (scope_id, chat_id, endpoint_profile_id, request_boundary)
        cache = self.state.chat_context_usage_cache
        if cache.get("base_key") == base_key:
            cached_line = str(cache.get("line") or "Context Used: unavailable")
            # A running request uses its stable request-boundary value.  This
            # avoids rebuilding and tokenizing a 100k+ token transcript at 60 FPS.
            if running:
                return cached_line
            if cache.get("source_revision") == source_revision and not cache.get("running"):
                return cached_line
        try:
            messages = self.services.chat._build_messages(
                scope_id, chat_id, endpoint_profile_id=endpoint_profile_id,
            )
            # Model the next send with an otherwise empty user message so the
            # normal role/framing overhead is included but new text contributes
            # zero tokens, exactly matching the tooltip contract.
            next_messages = [*messages, {"role": "user", "content": ""}]
            used_tokens = self.services.chat._estimate_messages_tokens(next_messages)
            config = self.services.storage.load_config()
            endpoint = endpoint_with_token_calibration(
                self.services.storage, endpoint_profile_for_id(config, endpoint_profile_id),
            )
            registry = getattr(self.services.chat, "tools", None)
            native_tools = registry.build_openai_chat_completion_tools(scope_id, chat_id) if isinstance(registry, ToolRegistry) else []
            capacity = prepared_request_capacity_snapshot(
                endpoint, estimated_message_tokens=used_tokens,
                message_count=len(next_messages), native_tools=native_tools,
            )
            percent = max(0.0, float(capacity["complete_tokens"]) * 100.0 / max(1, int(capacity["prompt_capacity_tokens"])))
            line = f"Context Used: {percent:.1f}%"
        except Exception:
            line = "Context Used: unavailable"
        cache.clear()
        cache.update({
            "base_key": base_key,
            "source_revision": source_revision,
            "running": running,
            "at": time.monotonic(),
            "line": line,
        })
        return line

    def draw_chat_thread_header(
        self, rect: Rect, turns: list[dict[str, Any]], *, title_override: str = "",
    ) -> None:
        self.r.draw_card(rect, radius=14, fill=Palette.panel)
        inner = rect.inset(10)
        title = str(title_override or "").strip() or "Untitled chat"
        if not title_override and self.state.active_scope_id and self.state.active_chat_id:
            try:
                chat = self.services.chats.load_chat(self.state.active_scope_id, self.state.active_chat_id)
                title = str(chat.get("name") or "Untitled chat")
            except Exception:
                pass
        running_summary = bool(getattr(self.state, "chat_summary_task", None) and not self.state.chat_summary_task.done())
        button_h = max(28, min(34, rect.h - 12))
        y = rect.y + max(0, (rect.h - button_h) // 2)
        gap = 8
        workspace_w = terminal_w = statistics_w = copy_w = raw_w = summary_w = button_h
        total_buttons_w = (
            workspace_w + terminal_w + statistics_w + copy_w + raw_w + summary_w
            + gap * 5
        )
        x = inner.x + inner.w - total_buttons_w
        runtime_stats = self._chat_runtime_stats_cached(turns)
        statistics_rect = Rect(
            x + workspace_w + gap + terminal_w + gap, y, statistics_w, button_h,
        )
        context_line = self._chat_context_usage_line(turns)
        activity_label, activity_tooltip = self._chat_toolbar_activity(turns)
        statistics_tooltip = (
            f"Status: {activity_tooltip}\n"
            f"Input: {int(runtime_stats.get('input_tokens') or 0):,}\n"
            f"Output: {int(runtime_stats.get('output_tokens') or 0):,}\n"
            f"Avg input: {float(runtime_stats.get('average_prompt_tokens_per_second') or 0.0):,.2f} tokens/sec\n"
            f"Avg generated: {float(runtime_stats.get('average_generation_tokens_per_second') or 0.0):,.2f} tokens/sec\n"
            f"{context_line}"
        )
        statistics_label_rect = Rect(inner.x, rect.y, max(1, x - inner.x - 14), rect.h)
        context_value = str(context_line).replace("Context Used:", "").strip() or "—"
        input_value = float(runtime_stats.get("average_prompt_tokens_per_second") or 0.0)
        generation_value = float(runtime_stats.get("average_generation_tokens_per_second") or 0.0)
        input_label = f"{input_value:,.1f} t/s" if input_value > 0 else "—"
        generation_label = f"{generation_value:,.1f} t/s" if generation_value > 0 else "—"
        metrics_label = (
            f"Ctx: {context_value} | In: {input_label} | Out: {generation_label}"
        )
        activity_max_w = max(1, min(statistics_label_rect.w, int(statistics_label_rect.w * 0.46)))
        activity_display = self.widgets._truncate_to_width(activity_label, activity_max_w)
        activity_text_w = self.widgets._text_width(activity_display)
        activity_x = statistics_label_rect.x + max(0, (statistics_label_rect.w - activity_text_w) // 2)
        statistics_y = centered_visible_text_y(
            self.f, activity_display or metrics_label, statistics_label_rect.y, statistics_label_rect.h,
        )
        normalized_activity = str(activity_label or "").strip().lower()
        if normalized_activity == "inactive":
            activity_color = Palette.muted
        elif normalized_activity.startswith("error"):
            activity_color = Palette.danger
        elif normalized_activity.startswith(("stalled", "cooldown", "endpoint error recovery")):
            activity_color = Palette.warn
        else:
            activity_color = Palette.ok
        metrics_rect = Rect(
            statistics_label_rect.x, statistics_label_rect.y,
            max(0, activity_x - statistics_label_rect.x - 12), statistics_label_rect.h,
        )
        metrics_display = self.widgets._truncate_to_width(metrics_label, max(1, metrics_rect.w))
        metrics_y = centered_visible_text_y(
            self.f, metrics_display, metrics_rect.y, metrics_rect.h,
        )
        self.r.push_clip(statistics_label_rect)
        if metrics_rect.w > 0 and metrics_display:
            self.r.draw_text_run_font(self.f, metrics_display, metrics_rect.x, metrics_y, Palette.muted)
        self.r.draw_text_run_font(self.f, activity_display, activity_x, statistics_y, activity_color)
        self.r.pop_clip()
        if self.widgets.button(
            "chat.thread.header.workspace", Rect(x, y, workspace_w, button_h), "",
            icon="workspace", tooltip="Open workspace",
        ):
            if self.state.active_chat_id:
                self._open_chat_workspace(self.state.active_chat_id, title)
        x += workspace_w + gap
        if self.widgets.button(
            "chat.thread.header.terminals", Rect(x, y, terminal_w, button_h), "",
            icon="terminal", tooltip="View terminals",
        ):
            if self.state.active_chat_id:
                self._open_terminal_dialog("chat", self.state.active_chat_id, f"Terminals — {title}")
        x += terminal_w + gap
        if self.widgets.button(
            "chat.thread.header.statistics", statistics_rect, "",
            icon="statistics", tooltip=statistics_tooltip,
        ):
            self._open_chat_statistics_dialog(turns, title)
        x += statistics_w + gap
        if self.widgets.button("chat.thread.header.copy", Rect(x, y, copy_w, button_h), "", icon="copy", tooltip="Copy formatted thread"):
            self._copy_current_thread_to_clipboard(turns)
        x += copy_w + gap
        if self.widgets.button("chat.thread.header.export_debug", Rect(x, y, raw_w, button_h), "", icon="debug_export", tooltip=self._debug_export_tooltip("chat", str(self.state.active_chat_id or ""))):
            self._request_chat_debug_export()
        x += raw_w + gap
        if self.widgets.button(
            "chat.thread.header.summary", Rect(x, y, summary_w, button_h), "",
            icon="chat_summary", enabled=not running_summary,
            tooltip="Show or refresh the stored chat summary",
        ):
            self._open_current_chat_summary()

    def _visible_chat_row_range(
        self,
        rows: list[tuple[dict[str, Any], int, int, str]],
        row_tops: list[int],
        scroll_y: int,
        viewport_h: int,
    ) -> tuple[int, int]:
        """Return the potentially visible row slice in O(log n + visible)."""
        if not rows:
            return 0, 0
        if len(row_tops) != len(rows):
            row_tops = [int(row[1]) for row in rows]
        top = max(0, int(scroll_y))
        bottom = top + max(0, int(viewport_h))
        start = max(0, bisect.bisect_right(row_tops, top) - 1)
        while start < len(rows) and int(rows[start][1]) + int(rows[start][2]) < top:
            start += 1
        end = min(len(rows), bisect.bisect_right(row_tops, bottom))
        if end < start:
            end = start
        return start, end

    def _draw_new_chat_task_settings(self, view: Rect) -> bool:
        """Draw endpoint/tool choices in the empty transcript before first send."""
        cid = str(self.state.active_chat_id or "")
        if not cid or self.services.chats.is_chat_endpoint_locked(cid):
            return False
        chat = self.services.chats.load_chat_view(APP_SCOPE_ID, cid)
        raw_features = chat.get("features") if isinstance(chat.get("features"), dict) else {}
        features = dict(raw_features)

        # Preserve the prior responsive width calculation, then apply the
        # requested forty-percent reduction exactly. A narrow viewport can still
        # contract below that target without pushing the card off-screen.
        former_card_w = min(max(420, view.w - 80), 760)
        target_card_w = max(252, int(round(former_card_w * 0.60)))
        card_w = min(max(1, view.w - 24), target_card_w)
        target_card_h = 294
        card_h = min(max(1, view.h - 24), target_card_h)
        card = Rect(
            view.x + max(0, (view.w - card_w) // 2),
            view.y + max(0, (view.h - card_h) // 2),
            max(1, card_w),
            card_h,
        )
        self.r.draw_card(card, radius=18, fill=Palette.panel, border=theme_alpha(Palette.accent, 150))
        inner = card.inset(18)
        title_font = getattr(self.widgets, "bold_font", self.f)
        self.r.draw_text_run_font(title_font, "NEW CHAT SETTINGS", inner.x, inner.y, Palette.white)
        y = inner.y + self.f.line_h + 12

        config = self.services.storage.load_config_view()
        endpoint_options, display_to_id, id_to_display = self._endpoint_profile_display_map_cached(config)
        stored_endpoint = str(chat.get("endpoint_profile_id") or "").strip()
        current_display = id_to_display.get(stored_endpoint, stored_endpoint or "No endpoint")
        label_w = min(82, max(58, inner.w // 3))
        self.widgets.clipped_text(Rect(inner.x, y, label_w, SETTINGS_CONTROL_H), "Endpoint", Palette.text)
        endpoint_rect = Rect(inner.x + label_w + 10, y, max(1, inner.w - label_w - 10), SETTINGS_CONTROL_H)
        selected_display = self.widgets.dropdown(
            "chat.task_setup.endpoint", endpoint_rect, current_display,
            endpoint_options or [current_display],
            tooltip="This endpoint is locked when the first user message is committed.",
        )
        selected_endpoint = display_to_id.get(selected_display, stored_endpoint)
        if selected_endpoint and selected_endpoint != stored_endpoint:
            self.services.chats.set_chat_endpoint_profile_id(cid, selected_endpoint)
            self.state.composer_endpoint_profile_id = selected_endpoint
        y += SETTINGS_CONTROL_H + 12

        self.r.draw_text_run_font(title_font, "TOOLS", inner.x, y, Palette.white)
        y += self.f.line_h + 6
        tooltip_by_key = {
            "file_tools_enabled": "Local file and document read, write, edit, search, import, and PDF-rendering functions.",
            "system_tools_enabled": "Shell and Python execution, ordinary terminals, images, Calendar, Data, Drive, skills, time, and other local/system functions.",
            "web_tools_enabled": "Web search, fetch, download, page links, and browser verification functions.",
            "agent_tools_enabled": "Start, list, pause, resume, stop, and inspect background agents owned by this chat.",
            "chat_history_enabled": "Stored chat search and summary functions.",
            "checklists_enabled": "Allow durable Checklists, implementation steps and independent review. Off disables Checklist tools and automatic Checklist continuation for this chat and its agents. Locked at the first user message.",
        }
        column_gap = 16
        column_w = max(1, (inner.w - column_gap) // 2)
        for index, (key, label) in enumerate(CHAT_TOOL_CATEGORY_LABELS):
            row_index = index // 2
            column_index = index % 2
            toggle_rect = Rect(
                inner.x + column_index * (column_w + column_gap),
                y + row_index * (SETTINGS_CONTROL_H + SETTINGS_ROW_GAP),
                column_w,
                SETTINGS_CONTROL_H,
            )
            current = bool(features[key])
            next_value = self.widgets.toggle(
                f"chat.task_setup.{key}", toggle_rect,
                label, current, tooltip=tooltip_by_key[key],
            )
            if next_value != current:
                saved = self.services.chats.set_chat_feature(APP_SCOPE_ID, cid, key, next_value)
                saved_features = saved.get("features") if isinstance(saved.get("features"), dict) else {}
                features = dict(saved_features)
        return True

    def draw_chat_view(self, rect: Rect) -> None:
        # Chat transcript is a structured, scrollable thread: user,
        # assistant, thinking, tool, and metadata cards are visually distinct and
        # each user/assistant card has Copy/Regen/Delete/Branch actions.
        self.r.draw_rect(rect, Palette.bg)
        if not self.state.active_scope_id or not self.state.active_chat_id:
            self.r.draw_text("Create a chat to start.", rect.x + 20, rect.y + 20, Palette.muted)
            return
        active_chat_id = str(self.state.active_chat_id or "").strip()
        try:
            endpoint_profile_id_for_warning = self.services.chats.get_chat_endpoint_profile_id(active_chat_id)
        except FileNotFoundError:
            # Selection was valid earlier in the frame but the chat disappeared
            # before this metadata read (YOLO delete, another Velox process, or a
            # committed delete followed by late cleanup failure). Never crash the
            # render loop on that transient stale pointer.
            self._clear_deleted_chat_ui_state(active_chat_id)
            self.r.draw_text(
                "The selected chat was deleted. Selecting another chat...",
                rect.x + 20, rect.y + 20, Palette.muted,
            )
            return
        turns = self._load_active_turns_cached()
        include_reasoning = self._current_chat_show_reasoning()
        self.state.show_reasoning_content = include_reasoning
        sections = self._chat_sections(turns, include_reasoning)
        # The transcript card owns the exact frame rectangle so its outer edge
        # aligns with the thread toolbar, composer, and left-side Chats card.
        view = rect
        if not self.services.llm.is_endpoint_configured(endpoint_profile_id_for_warning):
            banner = Rect(view.x, view.y, view.w, 44)
            self.r.draw_card(banner, radius=14, fill=theme_alpha(Palette.warn, 36), border=theme_alpha(Palette.warn, 150))
            self.widgets.clipped_text(Rect(banner.x + 14, banner.y, max(1, banner.w - 28), banner.h), self.services.llm.missing_endpoint_message(endpoint_profile_id_for_warning), Palette.text, align="left")
            view = Rect(view.x, view.y + 54, view.w, max(1, view.h - 54))
        if self._draw_new_chat_task_settings(view):
            self.state.perf_visible_chat_cards = 0
            self.state.perf_total_chat_sections = 0
            return
        composer_capture = getattr(self.state, "composer_capture_rect", None)
        pointer_over_composer = bool(composer_capture and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, composer_capture))
        outer_inner = view.inset(10)
        card_w, section_inner_w, md_layout_w, md_viewport_w = self._chat_layout_widths(outer_inner.w)
        scroll_y = int(self.state.scroll.get("chat.thread", 0))
        # performance: cache the chat card vertical layout for the current
        # viewport band. When nothing changes, rendering no longer re-measures or
        # re-parses every section on every frame. The band is included because
        # far-off cards intentionally use cheap estimates until the user scrolls
        # near them.
        band = int(scroll_y // max(1, outer_inner.h))
        # _chat_sections already builds a stable invalidation key
        # from turn ids, update times, text signatures, attachments, and tool
        # summaries. Reusing that key avoids recomputing expensive section/tool
        # fingerprints every frame while preserving all layout invalidation cases.
        sections_cache_key = self.state.chat_sections_cache_key or (bool(include_reasoning), len(sections), id(sections))
        table_word_wrap = self._chat_table_word_wrap_enabled()
        rows_base_key = (
            "chat-rows-base", table_word_wrap, card_w, md_layout_w, md_viewport_w,
            section_inner_w, outer_inner.w, outer_inner.h, band,
        )
        rows_cache_key = (*rows_base_key, sections_cache_key)
        rows = self.state.chat_rows_cache
        row_tops = self.state.chat_rows_cache_tops
        exact_cache_hit = bool(
            self.state.chat_rows_cache_key == rows_cache_key
            and self.state.chat_rows_cache_sections is sections
            and len(row_tops) == len(rows)
        )
        if exact_cache_hit:
            total_h = max(1, int(self.state.chat_rows_cache_total_h))
        else:
            incremental_start: int | None = None
            if (
                self.state.chat_rows_cache_base_key == rows_base_key
                and self.state.chat_rows_cache_sections is sections
                and len(row_tops) == len(rows)
            ):
                candidate_start = int(clamp(
                    self.state.chat_sections_changed_from_index,
                    0,
                    len(sections),
                ))
                if candidate_start <= len(rows):
                    incremental_start = candidate_start

            if incremental_start is None:
                rows = []
                row_tops = []
                incremental_start = 0
                y = 0
            else:
                if incremental_start < len(rows):
                    y = int(rows[incremental_start][1])
                elif rows:
                    last_section, last_y, last_h, last_measure_key = rows[-1]
                    _ = (last_section, last_measure_key)
                    y = int(last_y) + int(last_h) + 14
                else:
                    y = 0
                del rows[incremental_start:]
                del row_tops[incremental_start:]

            # Rough cull band: exact Markdown layout is only needed for cards near
            # the viewport. Far-off cards use a fast text/line estimate until the
            # user scrolls near them, avoiding full parsing of large offscreen
            # messages. A stable band plus a streaming tail now appends only that
            # changed suffix; scrolling to a new band intentionally rechecks all
            # cached row heights so newly visible estimates become exact.
            rough_top = max(0, scroll_y - outer_inner.h * 2)
            rough_bottom = scroll_y + outer_inner.h * 3
            section_layout_key = (
                "chat-section-row", table_word_wrap, card_w, md_layout_w, md_viewport_w,
                section_inner_w, self.f.line_h, self.f.char_w,
            )
            for section in sections[incremental_start:]:
                # Reused immutable section objects retain their measured height.
                # A streaming tail revision therefore measures only the changed
                # tail instead of rebuilding signatures/layout for every prior
                # card. Estimated far-off rows are promoted to exact layout when
                # they enter the viewport band.
                cached_row = section.get("_chat_row_layout_cache")
                use_cached = False
                if isinstance(cached_row, dict) and cached_row.get("key") == section_layout_key:
                    cached_h = max(1, int(cached_row.get("height") or 1))
                    cached_exact = bool(cached_row.get("exact"))
                    still_far = (y + cached_h < rough_top) or (y > rough_bottom)
                    if cached_exact or still_far:
                        card_h = cached_h
                        measure_key = str(cached_row.get("measure_key") or "")
                        use_cached = True
                if not use_cached:
                    # Parse the section's interleaved text/tool blocks once. A
                    # very large active card must be measured exactly; running
                    # the rough estimator first would be a second complete pass.
                    body_blocks = self._chat_body_blocks_for_section(section)
                    large_text = self._chat_body_has_large_text(body_blocks)
                    exact_layout = bool(large_text)
                    if large_text:
                        card_h, measure_key = self._measure_chat_section_height(
                            section,
                            md_layout_w,
                            md_viewport_w,
                            section_inner_w,
                            prefer_estimate=False,
                            body_blocks=body_blocks,
                        )
                    else:
                        estimate = self._estimate_chat_section_height(
                            section,
                            md_layout_w,
                            md_viewport_w,
                            section_inner_w,
                            body_blocks=body_blocks,
                        )
                        far_from_view = (y + estimate < rough_top) or (y > rough_bottom)
                        exact_layout = not far_from_view
                        card_h, measure_key = self._measure_chat_section_height(
                            section,
                            md_layout_w,
                            md_viewport_w,
                            section_inner_w,
                            prefer_estimate=far_from_view,
                            body_blocks=body_blocks,
                        )
                    section["_chat_row_layout_cache"] = {
                        "key": section_layout_key,
                        "height": int(card_h),
                        "measure_key": str(measure_key),
                        "exact": bool(exact_layout),
                    }
                row_tops.append(y)
                rows.append((section, y, card_h, measure_key))
                y += card_h + 14
            total_h = max(1, y + 8)
            self.state.chat_rows_cache_key = rows_cache_key
            self.state.chat_rows_cache = rows
            self.state.chat_rows_cache_tops = row_tops
            self.state.chat_rows_cache_total_h = total_h
            self.state.chat_rows_cache_base_key = rows_base_key
            self.state.chat_rows_cache_sections = sections
        # Only input owned by this viewport may cancel its reading anchor.
        # A wheel over the sidebar, composer or a modal belongs to that control.
        transcript_wheel = bool(
            (not pointer_over_composer)
            and self.widgets._can_receive_pointer("chat.thread")
            and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, view)
            and self.state.input.wheel_y
        )
        scroll_y = self._restore_chat_scroll(
            rows, scroll_y, stable=exact_cache_hit, manual_input=transcript_wheel,
        )
        wsid = self.state.active_scope_id
        cid = self.state.active_chat_id
        state_key = f"{wsid}:{cid}" if wsid and cid else ""
        now_monotonic = time.monotonic()
        autoscroll_enabled = bool(
            self.state.chat_autoscroll_enabled.get(state_key, True)
            if state_key else True
        )
        if state_key:
            self.state.chat_autoscroll_enabled.setdefault(state_key, True)
            self.state.chat_autoscroll_changed_at.setdefault(state_key, 0.0)

        wheel_gesture = False
        wheel_away_from_bottom = False
        wheel_toward_bottom = False
        if transcript_wheel:
            wheel_delta = int(self.state.input.wheel_y)
            scroll_y -= wheel_delta * self.f.line_h * 3
            wheel_gesture = True
            wheel_away_from_bottom = wheel_delta > 0
            wheel_toward_bottom = wheel_delta < 0
            self.state.input.mouse_consumed = True
        if self.state.chat_jump_query:
            q = self.state.chat_jump_query.lower().strip()
            if q:
                for section, sy, _h, _measure_key in rows:
                    if q in str(section.get("text") or "").lower():
                        scroll_y = max(0, sy - self.f.line_h)
                        break
            self.state.chat_jump_query = ""

        self.r.draw_card(view, radius=18, fill=Palette.input_bg)
        inner = view.inset(10)
        max_scroll = max(0, total_h - inner.h)
        scroll_y = int(clamp(scroll_y, 0, max_scroll))
        before_bar_scroll = scroll_y
        scrollbar_was_active = bool(
            (not pointer_over_composer)
            and self.state.drag_scrollbar_id == "chat.thread"
        )
        scroll_y = scroll_y if pointer_over_composer else self.widgets._scrollbar_input(
            "chat.thread", inner, scroll_y, total_h,
        )
        scroll_y = int(clamp(scroll_y, 0, max_scroll))
        scrollbar_moved = scroll_y != before_bar_scroll
        scrollbar_toward_bottom = bool(scrollbar_moved and scroll_y > before_bar_scroll)
        scrollbar_active = bool(
            (not pointer_over_composer)
            and self.state.drag_scrollbar_id == "chat.thread"
        )
        scrollbar_drag_started = bool(
            scrollbar_active
            and not scrollbar_was_active
            and self.state.input.mouse_pressed
        )
        manual_scroll_started = bool(
            wheel_gesture
            or scrollbar_drag_started
            or (scrollbar_moved and self.state.input.mouse_pressed)
        )
        manual_scroll_active = bool(wheel_gesture or scrollbar_moved or scrollbar_active)
        manual_scroll_toward_bottom = bool(wheel_toward_bottom or scrollbar_toward_bottom)
        at_bottom = scroll_y >= max(0, max_scroll - CHAT_AUTOSCROLL_BOTTOM_TOLERANCE_PX)

        changed_at = self.state.chat_autoscroll_changed_at.get(state_key, 0.0) if state_key else 0.0
        next_autoscroll = chat_autoscroll_state_after_manual_input(
            autoscroll_enabled,
            at_bottom=at_bottom,
            manual_scroll_started=manual_scroll_started,
            manual_scroll_active=manual_scroll_active,
            seconds_since_change=max(0.0, now_monotonic - changed_at),
            manual_scroll_away_from_bottom=wheel_away_from_bottom,
            manual_scroll_grabbed=scrollbar_drag_started,
            manual_scroll_toward_bottom=manual_scroll_toward_bottom,
        )
        if state_key and next_autoscroll != autoscroll_enabled:
            autoscroll_enabled = bool(next_autoscroll)
            self.state.chat_autoscroll_enabled[state_key] = autoscroll_enabled
            self.state.chat_autoscroll_changed_at[state_key] = now_monotonic

        previous_autoscroll_target = (
            int(self.state.chat_autoscroll_target.get(state_key, max_scroll))
            if state_key else max_scroll
        )
        if autoscroll_enabled and not manual_scroll_active:
            scroll_y = chat_follow_scroll_position(
                scroll_y,
                previous_max_scroll=previous_autoscroll_target,
                max_scroll=max_scroll,
                line_height=self.f.line_h,
            )
        scroll_y = int(clamp(scroll_y, 0, max_scroll))
        if state_key:
            # Store the actual layout boundary every frame. Manual mode does not
            # follow it, but refreshing the anchor prevents a large catch-up jump
            # when the user deliberately returns to the bottom later.
            self.state.chat_autoscroll_target[state_key] = max_scroll
        self.state.scroll["chat.thread"] = scroll_y
        if state_key:
            self.state.chat_thread_positions[state_key] = scroll_y
        first_visible, end_visible = self._visible_chat_row_range(rows, row_tops, scroll_y, inner.h)
        visible_count = 0
        self.r.push_clip(inner)
        for i in range(first_visible, end_visible):
            section, sy, card_h, measure_key = rows[i]
            draw_y = inner.y + sy - scroll_y
            if draw_y + card_h < inner.y or draw_y > inner.y + inner.h:
                continue
            # Leave a permanent gutter for the transcript scrollbar so card text
            # never sits underneath the scrollbar thumb.
            card_rect = Rect(inner.x + 4, int(draw_y), card_w, card_h)
            self._draw_chat_section(f"chat.section.{i}.{section.get('kind')}.{(section.get('turn') or {}).get('turn_id','')}", card_rect, section, visible_clip=inner, layout_key=measure_key)
            visible_count += 1
        self.r.pop_clip()
        self.state.perf_visible_chat_cards = visible_count
        self.state.perf_total_chat_sections = len(rows)
        self.widgets._scrollbar_draw("chat.thread", inner, scroll_y, total_h)

    def draw_message_composer(
        self,
        rect: Rect,
        *,
        ensure_active_chat: Callable[[], str | None] | None = None,
        placeholder: str = "Type a message...  Ctrl/Cmd+Enter to send. Drag to select text.",
    ) -> None:
        """Draw one editor and one bottom-anchored, single-row composer footer."""
        self.handle_clipboard_attachment_paste(ensure_active_chat=ensure_active_chat)
        self.r.draw_card(rect, radius=22, fill=Palette.panel)
        panel = rect.inset(14)

        endpoint_label_text = "No endpoint - No Tools"
        endpoint_tooltip = "Create or select a Chat to configure its Task."
        if self.state.active_chat_id:
            try:
                config = self.services.storage.load_config_view()
                chat = self.services.chats.load_chat_view(self.state.active_chat_id)
                stored_endpoint = str(chat.get("endpoint_profile_id") or "").strip()
                self.state.composer_endpoint_profile_id = stored_endpoint
                endpoint_label_text = self._chat_task_label_cached(
                    self.state.active_chat_id, chat, config,
                )
                endpoint_tooltip = (
                    endpoint_label_text
                    + "\nLocked for this Chat Task after the first user message. Agents spawned from it "
                    "inherit the same endpoint and tool categories."
                )
            except Exception as exc:
                endpoint_label_text = "Endpoint unavailable"
                endpoint_tooltip = str(exc)

        footer_gap = 10
        right_controls_w = 294
        # Thinking visibility and attachment actions share one compact icon cluster.
        count_width = max(34, self.f.text_width(str(len(self.state.queued_attachments))) + 16)
        left_cluster_w = 100 + count_width if self.state.queued_attachments else 94
        label_x = panel.x + left_cluster_w + 10
        label_right = panel.x + panel.w - right_controls_w - 12
        label_w = max(1, label_right - label_x)
        label_rows = self.widgets._wrap_display_rows(endpoint_label_text, label_w)
        footer_h = max(42, len(label_rows) * self.f.line_h + 10)
        input_area = Rect(panel.x, panel.y, panel.w, max(1, panel.h - footer_gap - footer_h))
        controls = Rect(panel.x, panel.y + panel.h - footer_h, panel.w, footer_h)
        self.state.composer_text = self.widgets.multiline_text_input(
            "composer.text", input_area, self.state.composer_text, placeholder,
        )

        cy = controls.y + max(0, (controls.h - 38) // 2)
        thinking_rect = Rect(controls.x, cy, 44, 38)
        show_thinking = self._current_chat_show_reasoning()
        next_show_thinking = self.widgets.icon_toggle_button(
            "composer.show_thinking", thinking_rect, show_thinking,
            enabled=bool(self.state.active_chat_id),
            tooltip_on="Hide thinking",
            tooltip_off="Show thinking",
        )
        if next_show_thinking != show_thinking and self.state.active_chat_id:
            self.services.chats.set_chat_feature(
                APP_SCOPE_ID, self.state.active_chat_id,
                "show_reasoning_content", next_show_thinking,
            )
            self.state.show_reasoning_content = next_show_thinking
            self._reset_chat_ui_cache(reset_scroll=False)

        attach_rect = Rect(thinking_rect.x + thinking_rect.w + 6, cy, 44, 38)
        if self.widgets.button(
            "composer.attach.open", attach_rect, "", icon="attachment",
            tooltip="Attach one or more local files",
        ):
            if self._ensure_live_chat_for_action(ensure_active_chat):
                self._open_file_picker("chat")

        if self.state.queued_attachments:
            count_text = str(len(self.state.queued_attachments))
            count_rect = Rect(attach_rect.x + attach_rect.w + 6, cy + 5, count_width, 28)
            if self.widgets.button(
                "composer.attach.count", count_rect, count_text, primary=True,
                tooltip=f"Manage {count_text} attachments queued for the next message",
            ):
                self._open_attachment_manager()

        running = bool(
            self.state.active_chat_id
            and self.services.chat.is_running(self.state.active_chat_id)
        )
        paused = bool(
            self.state.active_chat_id
            and self.services.chat.is_paused(self.state.active_chat_id)
        )
        pause_requested = bool(
            self.state.active_chat_id
            and self.services.chat.is_pause_requested(self.state.active_chat_id)
        )
        pause_mode = paused or pause_requested
        button_y = controls.y + max(0, (controls.h - 34) // 2)
        pause_rect = Rect(controls.x + controls.w - 294, button_y, 96, 34)
        stop_rect = Rect(controls.x + controls.w - 188, button_y, 82, 34)
        send_rect = Rect(controls.x + controls.w - 96, button_y, 88, 34)

        # The locked endpoint/tool policy is ordinary text, not a field. It is
        # measured inside this same footer row and may wrap vertically on narrow
        # windows, so no glyph is clipped in either dimension.
        label_rect = Rect(label_x, controls.y, label_w, controls.h)
        label_content_h = len(label_rows) * self.f.line_h
        label_y = label_rect.y + max(0, (label_rect.h - label_content_h) // 2)
        self.r.push_clip(label_rect)
        for row_index, row in enumerate(label_rows):
            row_text = str(row.text)
            row_x = label_rect.x + max(0, (label_rect.w - int(row.width)) // 2)
            self.r.draw_text(
                row_text, row_x, label_y + row_index * self.f.line_h, Palette.muted2,
            )
        self.r.pop_clip()
        self.widgets._queue_tooltip(
            "composer.task_label", label_rect, endpoint_tooltip,
            visible_text=endpoint_label_text, visible_text_fully_shown=True,
        )

        pause_label = "Resume" if pause_mode else "Pause"
        pause_tooltip = (
            "Resume from the exact preserved Chat execution boundary."
            if pause_mode else
            "Pause before the next tool call, or immediately after the current tool finishes."
        )
        if self.widgets.button(
            "composer.pause_resume", pause_rect, pause_label,
            enabled=running, success=pause_mode, tooltip=pause_tooltip,
        ):
            if self.state.active_chat_id:
                if pause_mode:
                    self.services.chat.resume(self.state.active_chat_id)
                else:
                    self.services.chat.pause(self.state.active_chat_id)
        if self.widgets.button(
            "composer.stop", stop_rect, "Stop", danger=True, enabled=running,
        ):
            if self.state.active_chat_id:
                self.services.chat.cancel(self.state.active_chat_id)
        can_send = bool(
            self.state.active_scope_id
            and (self.state.active_chat_id or callable(ensure_active_chat))
            and not running
        )
        send_clicked = self.widgets.button(
            "composer.send", send_rect, "Send", primary=True, enabled=can_send,
        )
        if send_clicked or (
            self.state.input.key_enter
            and self.state.input.primary_modifier
            and self.state.active_widget == "composer.text"
        ):
            self._send_composer_message(ensure_active_chat=ensure_active_chat)
        if (
            self.state.input.mouse_pressed
            and point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, rect)
            and not self.state.input.mouse_consumed
        ):
            self.state.input.mouse_consumed = True

    def handle_clipboard_attachment_paste(
        self,
        *,
        ensure_active_chat: Callable[[], str | None] | None = None,
    ) -> None:
        # Ctrl/Cmd+V in the Chat panel can queue files copied from the OS file
        # manager and bitmap images copied to the clipboard. Text paste still goes
        # to the active editor normally.
        if self.state.active_panel not in {"chat", "calendar"} or self.state.file_picker_open or self.state.modal:
            return
        inp = self.state.input
        paths = list(inp.paste_image_paths or []) + list(inp.paste_file_paths or [])
        image_payloads = list(getattr(inp, "paste_image_data", []) or [])
        if not paths and not image_payloads:
            return
        if not self._ensure_live_chat_for_action(ensure_active_chat):
            return
        # Do not hijack file/path paste while a non-composer text field is active.
        if self.state.active_widget and self.state.active_widget not in {"composer.text", "chat.view"}:
            return
        existing = {str(att.get("sha256", "")) for att in self.state.queued_attachments if att.get("sha256")}
        queued = 0
        store = AttachmentStore(self.services.storage)
        for payload in image_payloads:
            try:
                data = payload.get("data") if isinstance(payload, dict) else None
                if not isinstance(data, (bytes, bytearray)) or not data:
                    continue
                filename = str(payload.get("filename") or "clipboard_image.png")
                mime = str(payload.get("mime") or mimetypes.guess_type(filename)[0] or "image/png")
                meta = store.attach_bytes(self.state.active_scope_id, bytes(data), filename, mime, "chat", self.state.active_chat_id)  # type: ignore[arg-type]
                digest = str(meta.get("sha256", ""))
                if digest and digest in existing:
                    continue
                if digest:
                    existing.add(digest)
                self.state.queued_attachments.append(meta)
                queued += 1
            except Exception as e:
                self.state.add_toast("Clipboard image failed", f"{type(e).__name__}: {e}", "error")
        for raw in paths:
            before = len(self.state.queued_attachments)
            self.attach_file_by_path(str(raw))
            if len(self.state.queued_attachments) > before:
                meta = self.state.queued_attachments[-1]
                digest = str(meta.get("sha256", ""))
                if digest and digest in existing:
                    self.state.queued_attachments.pop()
                    continue
                if digest:
                    existing.add(digest)
                queued += 1
        if queued:
            # Treat copied files/images as attachment paste, not text paste, so the
            # composer does not also receive a raw file path/URI on the same frame.
            inp.paste_file_paths = []
            inp.paste_image_paths = []
            inp.paste_image_data = []
            inp.paste_text = ""

    def _send_composer_message(
        self,
        *,
        ensure_active_chat: Callable[[], str | None] | None = None,
    ) -> None:
        text = self.state.composer_text.strip()
        if (not text and not self.state.queued_attachments) or not self.state.active_scope_id:
            return
        if not self._ensure_live_chat_for_action(ensure_active_chat):
            return
        if self.services.chat.is_running(self.state.active_chat_id):
            return
        if not text:
            text = "Please review the attached file(s)."
        attachments = list(self.state.queued_attachments)
        endpoint_profile_id = self.services.chats.get_chat_endpoint_profile_id(self.state.active_chat_id)
        self.state.composer_endpoint_profile_id = endpoint_profile_id
        try:
            self.services.chat.send_from_ui(
                self.state.active_scope_id,
                self.state.active_chat_id,
                text,
                endpoint_profile_id,
                attachments=attachments,
            )
        except Exception as exc:
            self.state.add_toast("Message not sent", f"{type(exc).__name__}: {exc}", "error")
            return
        # Sending resumes transcript following even when manual scrolling disabled it.
        # The large target is clamped to the current transcript bottom on the next draw.
        self.state.scroll["chat.thread"] = 10**9
        state_key = f"{self.state.active_scope_id}:{self.state.active_chat_id}"
        self.state.chat_autoscroll_enabled[state_key] = True
        self.state.chat_autoscroll_changed_at[state_key] = time.monotonic()
        self.state.chat_turn_cache_key = None
        self.state.composer_text = ""
        self.state.queued_attachments.clear()
        self.state.text_cursors["composer.text"] = 0
        self.state.text_selections.pop("composer.text", None)
        self.state.text_scroll_y.pop("composer.text", None)
        self.state.text_scroll_x.pop("composer.text", None)
        if self.state.active_panel == "calendar":
            self._calendar_save_week_draft()
        else:
            self._save_chat_composer_draft(self.state.active_chat_id)

    def _normalize_attachment_path(self, path_str: str) -> Path | None:
        # Accept OS file-manager paths, file:// URIs, Windows and
        # POSIX separators, quoted paths, NUL/CRLF-delimited clipboard payloads,
        # and paths selected by the local file picker. Return an existing file or
        # None without raising.
        raw0 = str(path_str or "")
        raw = raw0.replace("\ufeff", "").replace("\u200b", "").strip().strip('"').strip("'")
        if not raw:
            return None
        raw = raw.split("\x00", 1)[0].splitlines()[0].strip().strip('"').strip("'")
        candidates: list[str] = []

        def add(value: str) -> None:
            value = str(value or "").strip().strip('"').strip("'")
            if value and value not in candidates:
                candidates.append(value)

        add(raw)
        try:
            add(urllib.parse.unquote(raw))
        except Exception:
            pass
        if raw.lower().startswith("file://"):
            try:
                parsed = urllib.parse.urlparse(raw)
                uri_path = urllib.parse.unquote(parsed.path or "")
                if parsed.netloc and not uri_path.startswith("/"):
                    uri_path = f"//{parsed.netloc}/{uri_path}"
                if sys.platform == "win32" and uri_path.startswith("/") and len(uri_path) > 2 and uri_path[2] == ":":
                    uri_path = uri_path[1:]
                add(uri_path)
            except Exception:
                pass
        if sys.platform == "win32":
            for value in list(candidates):
                add(value.replace("/", "\\"))
                if value.startswith("/") and len(value) > 2 and value[2] == ":":
                    add(value[1:])
        else:
            for value in list(candidates):
                add(value.replace("\\", "/"))

        path_candidates: list[Path] = []
        for value in candidates:
            try:
                p = Path(value).expanduser()
                path_candidates.append(p if p.is_absolute() else (Path.cwd() / p))
            except Exception:
                continue
        if self.state.active_chat_id:
            root = self.services.storage.paths.chat_workspace_dir(self.state.active_chat_id)
            for value in candidates:
                try:
                    path_candidates.append(root / value)
                except Exception:
                    pass
        seen: set[str] = set()
        for cand in path_candidates:
            try:
                # Try the exact candidate first; Windows shell paths and synced
                # providers can be valid even when resolve() rewrites them into a
                # form that later fails.
                key0 = str(cand)
                if key0 not in seen:
                    seen.add(key0)
                    if cand.exists() and cand.is_file():
                        return cand
                resolved = cand.resolve(strict=False)
                key = str(resolved)
                if key in seen:
                    continue
                seen.add(key)
                if resolved.exists() and resolved.is_file():
                    return resolved
            except Exception:
                continue
        return None

    def attach_file_by_path(self, path_str: str) -> None:
        """Adapt one paste/drop path to the shared multi-path attachment path."""
        self.attach_files_by_paths([path_str])

    def handle_file_picker_paths(self, path_values: Iterable[str | Path]) -> None:
        """Route the shared picker result to Settings or the chat attachment flow."""
        values = [str(Path(value).expanduser()) for value in path_values if str(value or "").strip()]
        target = str(self.state.file_picker_target or "chat")
        if target == "debug_export":
            owner = getattr(self.state, "file_picker_save_context", None)
            self.state.file_picker_save_context = None
            self.state.file_picker_save = False
            self.state.file_picker_target = "chat"
            if not owner or len(values) != 1:
                self.state.add_toast("Debug export cancelled", "No bound Task or destination was selected.", "error")
                return
            try:
                path = debug_export_destination(values[0], self.state.file_picker_dir)
                stamp = debug_export_target_stamp(path)
                if stamp is not None:
                    self.state.modal = {"kind": "debug_export_overwrite", "path": str(path),
                                        "owner": dict(owner), "expected_target": stamp}
                else:
                    self._request_debug_export_write(dict(owner), path)
            except (OSError, ValueError) as exc:
                self.state.add_toast("Debug export failed", str(exc), "error")
            return
        owner = self.state.file_picker_attachment_owner
        self.state.file_picker_attachment_owner = None
        if owner is not None and owner != (str(self.state.active_chat_id or ""), str(self.state.composer_draft_binding or "")):
            self.state.add_toast("Attachments not added", "The Chat draft changed while selecting files. Reopen the picker in the intended Chat.", "error")
            return
        self.attach_files_by_paths(values)

    def attach_files_by_paths(self, path_values: Iterable[str | Path]) -> None:
        if not self.state.active_scope_id or not self.state.active_chat_id:
            return
        try:
            self.services.chats.load_chat_view(self.state.active_chat_id)
        except (FileNotFoundError, ValueError):
            self.state.add_toast("Attachments not added", "This Chat no longer exists.", "error")
            return
        paths: list[Path] = []
        seen: set[str] = set()
        missing: list[str] = []
        for raw_value in path_values:
            raw = str(raw_value or "").strip().strip('"').strip("'")
            if not raw:
                continue
            path = self._normalize_attachment_path(raw)
            if path is None:
                missing.append(raw)
                continue
            key = str(path)
            if key not in seen:
                seen.add(key)
                paths.append(path)
        if missing:
            detail = missing[0][:180] if len(missing) == 1 else f"{len(missing)} selected files could not be found"
            self.state.add_toast("Attachment not found", detail, "error")
        if not paths:
            return

        self.state.file_picker_target = "chat"
        store = AttachmentStore(self.services.storage)
        failures: list[str] = []
        for path in paths:
            try:
                # File-picker and path-paste attachments are copied in chunks.
                # Clipboard bitmap bytes continue to use attach_bytes(), but a
                # large ordinary file must never be loaded in full by the UI.
                meta = store.attach_file(
                    self.state.active_scope_id, path, "chat", self.state.active_chat_id,
                )
                self.state.queued_attachments.append(meta)
            except Exception as exc:
                failures.append(f"{path.name}: {type(exc).__name__}: {exc}")
        if failures:
            self.state.add_toast("Some attachments failed", failures[0][:220], "error")
        if self.state.active_panel == "calendar":
            self._calendar_save_week_draft()
        else:
            self._save_chat_composer_draft(self.state.active_chat_id)

    @staticmethod
    def _coerce_settings_int(value: Any, default: int, lo: int, hi: int | None = None) -> int:
        try:
            if isinstance(value, str):
                value = value.strip()
            parsed = max(int(lo), int(value))
            return min(parsed, int(hi)) if hi is not None else parsed
        except Exception:
            return int(default)

    @staticmethod
    def _coerce_settings_float(value: Any, default: float, lo: float = 0.0, hi: float | None = None) -> float:
        try:
            if isinstance(value, bool):
                raise ValueError("boolean is not a numeric setting")
            parsed = float(str(value).strip()) if isinstance(value, str) else float(value)
            if not math.isfinite(parsed):
                raise ValueError("setting must be finite")
            parsed = max(float(lo), parsed)
            return min(parsed, float(hi)) if hi is not None else parsed
        except Exception:
            return float(default)

    @staticmethod
    def _settings_minutes_text(seconds: Any, default_seconds: int) -> str:
        """Format a persisted seconds value for a minutes-based Settings editor."""
        try:
            value = max(0.0, float(seconds)) / 60.0
        except Exception:
            value = max(0.0, float(default_seconds)) / 60.0
        if abs(value - round(value)) < 1e-9:
            return str(int(round(value)))
        return f"{value:.3f}".rstrip("0").rstrip(".")

    @staticmethod
    def _settings_timeout_seconds_from_draft(
        container: dict[str, Any],
        default_seconds: int,
        minimum_seconds: int,
        maximum_seconds: int | None = None,
    ) -> int:
        """Convert a draft-only minutes editor into the persisted seconds value."""
        raw_minutes = container.pop("_ui_timeout_minutes", None)
        if raw_minutes is None:
            try:
                return Panels._coerce_settings_int(container.get("timeout_seconds", default_seconds), default_seconds, minimum_seconds, maximum_seconds)
            except Exception:
                return int(default_seconds)
        try:
            seconds = int(round(float(str(raw_minutes).strip()) * 60.0))
            return Panels._coerce_settings_int(seconds, default_seconds, minimum_seconds, maximum_seconds)
        except Exception:
            try:
                return Panels._coerce_settings_int(container.get("timeout_seconds", default_seconds), default_seconds, minimum_seconds, maximum_seconds)
            except Exception:
                return int(default_seconds)

    def _settings_config_to_draft(self, config: dict[str, Any]) -> dict[str, Any]:
        """Create a UI draft while keeping saved endpoint profiles canonical."""
        draft = json.loads(json.dumps(config or default_config()))
        ui = draft.setdefault("ui", {})
        ui["_ui_font_size"] = str(ui.get("font_size", 18))
        llm = draft.setdefault("llm", {})
        comfy = llm.setdefault("comfy", {})
        comfy["_ui_timeout_minutes"] = self._settings_minutes_text(
            comfy.get("timeout_seconds", 900), 900,
        )
        meshy = draft.setdefault("meshy", {})
        meshy["_ui_timeout_minutes"] = self._settings_minutes_text(meshy.get("timeout_seconds", 1800), 1800)
        return draft

    def _sanitized_settings_config(self, config: dict[str, Any]) -> dict[str, Any]:
        # Numeric resource settings have documented minimums but no hidden upper
        # clamps. Per-call requests are bounded by these persisted user maxima.
        if not isinstance(config, dict):
            raise UnsupportedDataVersionError("Settings draft must use the exact Velox data model")
        cfg = json.loads(json.dumps(config))
        cfg["features"] = filter_known_feature_flags(cfg.get("features"), CONFIG_FEATURE_DEFAULTS)
        ui = cfg.setdefault("ui", {})
        ui_face = str(ui.get("ui_font_face") or preferred_font_face("Sans"))
        code_face = str(ui.get("code_font_face") or preferred_font_face("Mono"))
        ui["ui_font_face"] = ui_face if ui_face in FONT_SANS_OPTIONS else preferred_font_face("Sans")
        ui["code_font_face"] = code_face if code_face in FONT_MONO_OPTIONS else preferred_font_face("Mono")
        ui["font_face"] = "Sans"
        prior_font_size = self._coerce_settings_int(ui.get("font_size", 18), 18, 10, 40)
        raw_font_size = ui.pop("_ui_font_size", prior_font_size)
        ui["font_size"] = self._coerce_settings_int(raw_font_size, prior_font_size, 10, 40)
        ui["font_weight"] = normalize_font_weight(ui.get("font_weight", "heavy"))
        ui["table_word_wrap"] = bool(ui.get("table_word_wrap", True))
        ui["text_undo_limit"] = self._coerce_settings_int(
            ui.get("text_undo_limit", TEXT_UNDO_LIMIT_DEFAULT),
            TEXT_UNDO_LIMIT_DEFAULT, TEXT_UNDO_LIMIT_MIN, TEXT_UNDO_LIMIT_MAX,
        )
        ui["tooltip_max_lines"] = self._coerce_settings_int(
            ui.get("tooltip_max_lines", TOOLTIP_MAX_LINES_DEFAULT),
            TOOLTIP_MAX_LINES_DEFAULT, TOOLTIP_MAX_LINES_MIN, TOOLTIP_MAX_LINES_MAX,
        )
        ui["tooltip_max_chars_per_line"] = self._coerce_settings_int(
            ui.get("tooltip_max_chars_per_line", TOOLTIP_MAX_CHARS_PER_LINE_DEFAULT),
            TOOLTIP_MAX_CHARS_PER_LINE_DEFAULT,
            TOOLTIP_MAX_CHARS_PER_LINE_MIN, TOOLTIP_MAX_CHARS_PER_LINE_MAX,
        )
        ui["yolo_deletes"] = bool(ui.get("yolo_deletes", False))
        ui["developer_mode"] = bool(ui.get("developer_mode", False))
        ui["show_perf_overlay"] = bool(ui.get("show_perf_overlay", False)) if ui["developer_mode"] else False

        llm = cfg.setdefault("llm", {})
        llm["stall_detection_minutes"] = self._coerce_settings_float(
            llm.get("stall_detection_minutes", LLM_ACTIVITY_STALL_WARNING_MINUTES_DEFAULT),
            LLM_ACTIVITY_STALL_WARNING_MINUTES_DEFAULT,
            LLM_ACTIVITY_STALL_WARNING_MINUTES_MIN,
            None,
        )
        profiles_raw = llm.get("endpoint_profiles")
        if not isinstance(profiles_raw, list) or not profiles_raw:
            profiles_raw = copy.deepcopy(default_config()["llm"]["endpoint_profiles"])
        profiles: list[dict[str, Any]] = []
        seen_ids: set[str] = set()
        for index, raw_profile in enumerate(profiles_raw):
            try:
                clean_profile = normalize_endpoint_profile(raw_profile, location=f"settings.llm.endpoint_profiles[{index}]")
            except Exception:
                # The modal validates before replacing a profile. If an external
                # caller supplied a broken draft, preserve a matching last-valid
                # profile instead of silently inventing sampling values.
                prior_profiles = endpoint_profiles_from_config(getattr(self.state, "settings_last_valid_config", None))
                raw_id = str(raw_profile.get("id") or "") if isinstance(raw_profile, dict) else ""
                prior = next((item for item in prior_profiles if str(item.get("id") or "") == raw_id), None)
                if prior is None:
                    continue
                clean_profile = normalize_endpoint_profile(prior, location=f"settings.llm.endpoint_profiles[{index}]")
            if clean_profile["id"] in seen_ids:
                continue
            seen_ids.add(clean_profile["id"])
            profiles.append(clean_profile)
        if not profiles:
            profiles = copy.deepcopy(default_config()["llm"]["endpoint_profiles"])
            seen_ids = {str(item["id"]) for item in profiles}
        llm["endpoint_profiles"] = profiles
        fallback_id = DEFAULT_ENDPOINT_PROFILE_ID if DEFAULT_ENDPOINT_PROFILE_ID in seen_ids else str(profiles[0]["id"])
        selected = str(llm.get("default_profile_id") or "")
        llm["default_profile_id"] = selected if selected in seen_ids else fallback_id
        comfy = llm.setdefault("comfy", {})
        comfy["base_url"] = str(comfy.get("base_url") or "http://127.0.0.1:8188")
        comfy["timeout_seconds"] = self._settings_timeout_seconds_from_draft(comfy, 900, 1, None)
        for comfy_key in ("workflow_text_to_image_path", "workflow_image_to_image_path"):
            comfy[comfy_key] = str(comfy.get(comfy_key) or "")

        web_cfg = cfg.setdefault("web", {})
        provider = str(web_cfg.get("search_provider") or "duckduckgo").strip().lower()
        web_cfg["search_provider"] = provider if provider in {"duckduckgo", "bing", "google"} else "duckduckgo"
        ua_mode = str(web_cfg.get("user_agent_mode") or "desktop_firefox").strip().lower()
        web_cfg["user_agent_mode"] = ua_mode if ua_mode in WEB_USER_AGENT_MODES else "desktop_firefox"
        for key, (default, minimum, kind) in WEB_RESOURCE_SETTING_SPECS.items():
            if kind == "float":
                web_cfg[key] = self._coerce_settings_float(web_cfg.get(key, default), float(default), float(minimum), None)
            else:
                web_cfg[key] = self._coerce_settings_int(web_cfg.get(key, default), int(default), int(minimum), None)

        tools_cfg = cfg.setdefault("tools", {})
        for key, (default, minimum, kind) in TOOL_RESOURCE_SETTING_SPECS.items():
            if kind == "float":
                tools_cfg[key] = self._coerce_settings_float(tools_cfg.get(key, default), float(default), float(minimum), None)
            else:
                tools_cfg[key] = self._coerce_settings_int(tools_cfg.get(key, default), int(default), int(minimum), None)

        history_cfg = cfg.setdefault("history", {})
        history_cfg["background_summary_idle_seconds"] = self._coerce_settings_int(
            history_cfg.get("background_summary_idle_seconds", CHAT_HISTORY_SUMMARY_IDLE_SECONDS_DEFAULT),
            CHAT_HISTORY_SUMMARY_IDLE_SECONDS_DEFAULT, CHAT_HISTORY_SUMMARY_IDLE_SECONDS_MIN, None,
        )
        history_cfg["first_message_context_max_chars"] = self._coerce_settings_int(
            history_cfg.get("first_message_context_max_chars", CHAT_HISTORY_CONTEXT_MAX_CHARS_DEFAULT),
            CHAT_HISTORY_CONTEXT_MAX_CHARS_DEFAULT, CHAT_HISTORY_CONTEXT_MAX_CHARS_MIN, None,
        )
        prompt = str(history_cfg.get("chat_summary_prompt") or DEFAULT_CHAT_HISTORY_SUMMARY_PROMPT).strip()
        history_cfg["chat_summary_prompt"] = prompt or DEFAULT_CHAT_HISTORY_SUMMARY_PROMPT
        prompting_cfg = cfg.setdefault("prompting", {})
        prompting_cfg["system_prompt_addon"] = str(prompting_cfg.get("system_prompt_addon") or "")

        raw_chat_cfg = cfg.get("chat") if isinstance(cfg.get("chat"), dict) else {}
        cfg["chat"] = {
            "auto_compaction_enabled": bool(raw_chat_cfg.get("auto_compaction_enabled", True)),
        }

        agent_defaults = default_config()["agents"]
        raw_agent_cfg = cfg.get("agents") if isinstance(cfg.get("agents"), dict) else {}
        agent_cfg = {
            "timeout_minutes": self._coerce_settings_int(
                raw_agent_cfg.get("timeout_minutes", AGENT_TIMEOUT_MINUTES_DEFAULT),
                AGENT_TIMEOUT_MINUTES_DEFAULT, AGENT_TIMEOUT_MINUTES_MIN, None,
            ),
            "auto_compaction_enabled": bool(raw_agent_cfg.get("auto_compaction_enabled", True)),
        }
        raw_pa = raw_agent_cfg.get("personal_assistant") if isinstance(raw_agent_cfg.get("personal_assistant"), dict) else {}
        start_time = str(raw_pa.get("start_time") or PA_AGENT_START_TIME_DEFAULT).strip()
        if not re.fullmatch(r"(?:[01]\d|2[0-3]):[0-5]\d", start_time):
            start_time = PA_AGENT_START_TIME_DEFAULT
        agent_cfg["personal_assistant"] = {
            "enabled": bool(raw_pa.get("enabled", PA_AGENT_ENABLED_DEFAULT)),
            "start_time": start_time,
            "check_interval_minutes": self._coerce_settings_int(
                raw_pa.get("check_interval_minutes", PA_AGENT_CHECK_INTERVAL_MINUTES_DEFAULT),
                PA_AGENT_CHECK_INTERVAL_MINUTES_DEFAULT, PA_AGENT_CHECK_INTERVAL_MINUTES_MIN, None,
            ),
            "report_days_back": self._coerce_settings_int(
                raw_pa.get("report_days_back", PA_AGENT_REPORT_DAYS_BACK_DEFAULT),
                PA_AGENT_REPORT_DAYS_BACK_DEFAULT, PA_AGENT_REPORT_DAYS_BACK_MIN, PA_AGENT_REPORT_DAYS_BACK_MAX,
            ),
            "timeout_minutes": self._coerce_settings_int(
                raw_pa.get("timeout_minutes", AGENT_TIMEOUT_MINUTES_DEFAULT),
                AGENT_TIMEOUT_MINUTES_DEFAULT, AGENT_TIMEOUT_MINUTES_MIN, None,
            ),
            "auto_compaction_enabled": bool(raw_pa.get("auto_compaction_enabled", True)),
        }
        cfg["agents"] = agent_cfg

        vault_cfg = cfg.setdefault("vault", {})
        vault_cfg["local_timezone"] = str(vault_cfg.get("local_timezone") or VAULT_LOCAL_TIMEZONE_DEFAULT)
        vault_cfg["divider_fraction"] = normalize_vault_divider_fraction(
            vault_cfg.get("divider_fraction", VAULT_DIVIDER_DEFAULT_FRACTION)
        )
        raw_calendar_cfg = vault_cfg.get("google_calendar") if isinstance(vault_cfg.get("google_calendar"), dict) else {}
        vault_cfg["google_calendar"] = {
            "sync_window_days": self._coerce_settings_int(
                raw_calendar_cfg.get("sync_window_days", GOOGLE_CALENDAR_SYNC_WINDOW_DAYS_DEFAULT),
                GOOGLE_CALENDAR_SYNC_WINDOW_DAYS_DEFAULT,
                GOOGLE_CALENDAR_SYNC_WINDOW_DAYS_MIN, GOOGLE_CALENDAR_SYNC_WINDOW_DAYS_MAX,
            ),
        }
        raw_drive_cfg = vault_cfg.get("google_drive") if isinstance(vault_cfg.get("google_drive"), dict) else {}
        vault_cfg["google_drive"] = {
            "include_shared_drives": bool(raw_drive_cfg.get("include_shared_drives", True)),
            "divider_fraction": normalize_vault_divider_fraction(
                raw_drive_cfg.get("divider_fraction", VAULT_GOOGLE_DRIVE_DIVIDER_DEFAULT_FRACTION)
            ),
        }
        gmail_cfg = vault_cfg.setdefault("gmail", {})
        gmail_cfg["enabled"] = bool(gmail_cfg.get("enabled", False))
        gmail_cfg["initial_history_days"] = self._coerce_settings_int(
            gmail_cfg.get("initial_history_days", GMAIL_INITIAL_HISTORY_DAYS_DEFAULT),
            GMAIL_INITIAL_HISTORY_DAYS_DEFAULT, 0, None,
        )
        gmail_cfg["sync_interval_minutes"] = self._coerce_settings_int(
            gmail_cfg.get("sync_interval_minutes", GMAIL_SYNC_INTERVAL_MINUTES_DEFAULT),
            GMAIL_SYNC_INTERVAL_MINUTES_DEFAULT, 1, None,
        )
        gmail_cfg["include_spam"] = bool(gmail_cfg.get("include_spam", False))
        gmail_cfg["include_trash"] = bool(gmail_cfg.get("include_trash", False))
        slack_cfg = vault_cfg.setdefault("slack", {})
        slack_cfg["enabled"] = bool(slack_cfg.get("enabled", False))
        redirect_uri = str(slack_cfg.get("redirect_uri") or SLACK_REDIRECT_URI_DEFAULT).strip()
        try:
            parsed_redirect = urllib.parse.urlparse(redirect_uri)
            if parsed_redirect.scheme != "http" or parsed_redirect.hostname not in {"127.0.0.1", "localhost"} or not parsed_redirect.port:
                raise ValueError
            slack_cfg["redirect_uri"] = redirect_uri
        except Exception:
            slack_cfg["redirect_uri"] = SLACK_REDIRECT_URI_DEFAULT
        slack_cfg["initial_history_days"] = self._coerce_settings_int(
            slack_cfg.get("initial_history_days", SLACK_INITIAL_HISTORY_DAYS_DEFAULT),
            SLACK_INITIAL_HISTORY_DAYS_DEFAULT, 0, None,
        )
        slack_cfg["sync_interval_minutes"] = self._coerce_settings_int(
            slack_cfg.get("sync_interval_minutes", SLACK_SYNC_INTERVAL_MINUTES_DEFAULT),
            SLACK_SYNC_INTERVAL_MINUTES_DEFAULT, 1, None,
        )
        for key in (
            "include_public_channels", "include_private_channels",
            "include_direct_messages", "include_group_direct_messages",
        ):
            slack_cfg[key] = bool(slack_cfg.get(key, True))

        meshy_cfg = cfg.setdefault("meshy", {})
        meshy_cfg["api_token"] = str(meshy_cfg.get("api_token") or "")
        meshy_cfg["base_url"] = str(meshy_cfg.get("base_url") or "https://api.meshy.ai").strip().rstrip("/") or "https://api.meshy.ai"
        meshy_cfg["timeout_seconds"] = self._settings_timeout_seconds_from_draft(meshy_cfg, 1800, 1, None)
        meshy_cfg["poll_interval_seconds"] = self._coerce_settings_float(meshy_cfg.get("poll_interval_seconds", 5.0), 5.0, 0.001, None)
        meshy_cfg["download_results"] = bool(meshy_cfg.get("download_results", True))
        return cfg

    @staticmethod
    def _settings_widget_config_path(widget_id: str) -> tuple[str, ...] | None:
        """Map an editable Settings widget to its draft configuration path."""
        widget = str(widget_id or "")
        exact: dict[str, tuple[str, ...]] = {
            "settings.font.size": ("ui", "_ui_font_size"),
            "settings.text.undo_limit": ("ui", "text_undo_limit"),
            "settings.tooltip.max_lines": ("ui", "tooltip_max_lines"),
            "settings.tooltip.max_chars_per_line": ("ui", "tooltip_max_chars_per_line"),
            "settings.accounts.google_calendar.sync_window_days": ("vault", "google_calendar", "sync_window_days"),
            "settings.history.summary_idle_seconds": ("history", "background_summary_idle_seconds"),
            "settings.history.first_message_context_max_chars": ("history", "first_message_context_max_chars"),
            "settings.history.chat_summary_prompt": ("history", "chat_summary_prompt"),
            "settings.system_prompt.addon": ("prompting", "system_prompt_addon"),
            "settings.comfy.url": ("llm", "comfy", "base_url"),
            "settings.comfy.workflow_text_to_image_path": ("llm", "comfy", "workflow_text_to_image_path"),
            "settings.comfy.workflow_image_to_image_path": ("llm", "comfy", "workflow_image_to_image_path"),
            "settings.comfy.timeout": ("llm", "comfy", "_ui_timeout_minutes"),
            "settings.agents.timeout_minutes": ("agents", "timeout_minutes"),
            "settings.agents.pa.start_time": ("agents", "personal_assistant", "start_time"),
            "settings.agents.pa.check_interval_minutes": ("agents", "personal_assistant", "check_interval_minutes"),
            "settings.agents.pa.report_days_back": ("agents", "personal_assistant", "report_days_back"),
            "settings.agents.pa.timeout_minutes": ("agents", "personal_assistant", "timeout_minutes"),
            "settings.meshy.base_url": ("meshy", "base_url"),
            "settings.meshy.api_token": ("meshy", "api_token"),
            "settings.meshy.timeout": ("meshy", "_ui_timeout_minutes"),
            "settings.meshy.poll_interval": ("meshy", "poll_interval_seconds"),
            "settings.accounts.gmail.initial_history_days": ("vault", "gmail", "initial_history_days"),
            "settings.accounts.gmail.sync_interval_minutes": ("vault", "gmail", "sync_interval_minutes"),
            "settings.accounts.slack.redirect_uri": ("vault", "slack", "redirect_uri"),
            "settings.accounts.slack.initial_history_days": ("vault", "slack", "initial_history_days"),
            "settings.accounts.slack.sync_interval_minutes": ("vault", "slack", "sync_interval_minutes"),
        }
        if widget in exact:
            return exact[widget]
        match = re.fullmatch(r"settings\.(web|tools)\.([A-Za-z0-9_]+)", widget)
        if match:
            return (match.group(1), match.group(2))
        return None

    _SETTINGS_NUMERIC_EDITOR_KINDS: dict[str, str] = {
        "settings.font.size": "int",
        "settings.text.undo_limit": "int",
        "settings.history.summary_idle_seconds": "int",
        "settings.history.first_message_context_max_chars": "int",
        "settings.agents.timeout_minutes": "int",
        "settings.agents.pa.check_interval_minutes": "int",
        "settings.agents.pa.report_days_back": "int",
        "settings.agents.pa.timeout_minutes": "int",
        "settings.comfy.timeout": "float",
        "settings.meshy.timeout": "float",
        "settings.meshy.poll_interval": "float",
        "settings.accounts.gmail.initial_history_days": "int",
        "settings.accounts.gmail.sync_interval_minutes": "int",
        "settings.accounts.slack.initial_history_days": "int",
        "settings.accounts.slack.sync_interval_minutes": "int",
        **{f"settings.web.{key}": kind for key, (_default, _minimum, kind) in WEB_RESOURCE_SETTING_SPECS.items()},
        **{f"settings.tools.{key}": kind for key, (_default, _minimum, kind) in TOOL_RESOURCE_SETTING_SPECS.items()},
    }

    @classmethod
    def _settings_numeric_editor_kind(cls, widget_id: str) -> str:
        """Return ``int``/``float`` for Settings editors that require numbers."""
        return cls._SETTINGS_NUMERIC_EDITOR_KINDS.get(str(widget_id or ""), "")

    @classmethod
    def _settings_numeric_editor_is_parseable(cls, widget_id: str, value: Any) -> bool:
        """Return whether a numeric editor has a complete finite value."""
        kind = cls._settings_numeric_editor_kind(widget_id)
        if not kind:
            return True
        raw = str(value).strip()
        if not raw:
            return False
        try:
            number = int(raw) if kind == "int" else float(raw)
        except Exception:
            return False
        return math.isfinite(float(number))

    @staticmethod
    def _settings_path_get(config: dict[str, Any], path: tuple[str, ...] | None, default: Any = None) -> Any:
        current: Any = config
        for key in path or ():
            if not isinstance(current, dict) or key not in current:
                return default
            current = current[key]
        return current

    @staticmethod
    def _settings_path_set(config: dict[str, Any], path: tuple[str, ...] | None, value: Any) -> bool:
        if not path:
            return False
        current: dict[str, Any] = config
        for key in path[:-1]:
            child = current.get(key)
            if not isinstance(child, dict):
                child = {}
                current[key] = child
            current = child
        current[path[-1]] = value
        return True

    def _end_settings_text_focus_on_blank_click(self, rect: Rect) -> bool:
        """Commit an editor when the user clicks unused space in Settings."""
        active = str(getattr(self.state, "active_widget", "") or "")
        inp = self.state.input
        if (
            not active.startswith("settings.")
            or not inp.mouse_pressed
            or inp.mouse_consumed
            or not point_in_rect(inp.mouse_x, inp.mouse_y, rect)
        ):
            return False
        self.state.active_widget = None
        self.state.text_drag_widget = None
        inp.mouse_consumed = True
        return True


    def _autosave_settings_if_changed(self, config: dict[str, Any]) -> None:
        """Validate a Settings editor only after it loses focus, then autosave."""
        # Validate the exact current-schema draft. Other data-root schemas are rejected;
        # the editor never synthesizes removed fields or migration aliases.
        active_raw = str(getattr(self.state, "active_widget", "") or "")
        active = active_raw if active_raw.startswith("settings.") else ""
        previous = str(getattr(self.state, "settings_last_active_widget", "") or "")
        self.state.settings_last_active_widget = active or None

        last_valid = getattr(self.state, "settings_last_valid_config", None)
        if not isinstance(last_valid, dict):
            last_valid = self._sanitized_settings_config(self.services.storage.load_config())
            self.state.settings_last_valid_config = copy.deepcopy(last_valid)
        if getattr(self.state, "settings_last_saved_config_json", None) is None:
            self.state.settings_last_saved_config_json = json.dumps(last_valid, ensure_ascii=False, sort_keys=True)

        if active and (not previous or active == previous):
            return

        candidate = json.loads(json.dumps(config or default_config()))
        active_path = self._settings_widget_config_path(active) if active else None
        active_value_marker = object()
        active_raw_value = self._settings_path_get(candidate, active_path, active_value_marker)

        valid_draft = self._settings_config_to_draft(last_valid)
        for widget_id in self._SETTINGS_NUMERIC_EDITOR_KINDS:
            path = self._settings_widget_config_path(widget_id)
            raw_value = self._settings_path_get(candidate, path, active_value_marker)
            if raw_value is active_value_marker or self._settings_numeric_editor_is_parseable(widget_id, raw_value):
                continue
            prior_value = self._settings_path_get(valid_draft, path, active_value_marker)
            if prior_value is not active_value_marker:
                self._settings_path_set(candidate, path, prior_value)
        if active_path and active_raw_value is not active_value_marker:
            prior_value = self._settings_path_get(valid_draft, active_path, active_value_marker)
            if prior_value is not active_value_marker:
                self._settings_path_set(candidate, active_path, prior_value)

        sanitized = self._sanitized_settings_config(candidate)

        # Window geometry is updated independently by the live app. Merge only
        # that geometry before saving; Accounts is an ordinary editable section.
        try:
            latest_disk = self.services.storage.load_config()
            latest_ui = latest_disk.get("ui") if isinstance(latest_disk.get("ui"), dict) else {}
            target_ui = sanitized.setdefault("ui", {})
            for geometry_key in ("window_width", "window_height", "window_x", "window_y"):
                if geometry_key in latest_ui:
                    target_ui[geometry_key] = copy.deepcopy(latest_ui[geometry_key])
        except Exception:
            pass

        current_json = json.dumps(sanitized, ensure_ascii=False, sort_keys=True)
        previous_json = str(getattr(self.state, "settings_last_saved_config_json", "") or "")
        if current_json != previous_json:
            self.services.storage.write_config(sanitized, preserve_live_fields=True)
            self.state.settings_last_saved_config_json = current_json
        self.state.settings_last_valid_config = copy.deepcopy(sanitized)

        normalized_draft = self._settings_config_to_draft(sanitized)
        if active_path and active_raw_value is not active_value_marker:
            self._settings_path_set(normalized_draft, active_path, active_raw_value)
        if json.dumps(config, ensure_ascii=False, sort_keys=True) != json.dumps(normalized_draft, ensure_ascii=False, sort_keys=True):
            self.state.config_draft = normalized_draft

    def _draw_settings_card_shell(self, rect: Rect, title: str, *, tooltip: str = "") -> Rect:
        """Draw a settings/developer card using the shared padding contract."""
        self.r.draw_card(rect, radius=16, fill=Palette.panel)
        title_font = getattr(self.widgets, "bold_font", self.f)
        title_text = str(title).upper()
        title_x = rect.x + SETTINGS_CARD_PAD_X
        title_y = rect.y + SETTINGS_CARD_PAD_Y - 2
        title_available_w = max(1, rect.w - SETTINGS_CARD_PAD_X * 2)
        title_display = self.widgets._truncate_to_width(title_text, title_available_w)
        self.r.draw_text_run_font(title_font, title_display, title_x, title_y, Palette.white)
        effective_tooltip = str(tooltip or (title_text if title_display != title_text else ""))
        if effective_tooltip:
            title_rect = Rect(
                title_x,
                rect.y + SETTINGS_CARD_PAD_Y - 4,
                min(title_available_w, max(1, self.widgets._text_width(title_display) + 10)),
                max(self.f.line_h + 8, SETTINGS_CARD_TITLE_H),
            )
            self.widgets._queue_tooltip(
                f"settings.card.title.{safe_filename(title_text).casefold()}.{rect.y}",
                title_rect, effective_tooltip, visible_text=title_display,
                visible_text_fully_shown=(title_display == title_text),
            )
        return Rect(
            rect.x + SETTINGS_CARD_PAD_X,
            rect.y + SETTINGS_CARD_PAD_Y + SETTINGS_CARD_TITLE_H,
            max(1, rect.w - SETTINGS_CARD_PAD_X * 2),
            max(1, rect.h - SETTINGS_CARD_PAD_Y * 2 - SETTINGS_CARD_TITLE_H),
        )

    def _settings_card_rect(self, col: Rect, y: int, h: int) -> Rect:
        return Rect(col.x, int(y), max(1, col.w - 4), int(h))


    def _draw_settings_account_action_columns(
        self, inner: Rect, y: int, *, compact: bool = False,
    ) -> tuple[Rect, Rect]:
        """Draw the shared Initial Setup / Actions headings and return button columns."""
        layout = settings_account_action_layout(
            inner, y, heading_h=max(24, self.f.line_h + 4), compact=compact,
        )
        self.widgets.clipped_text(layout.setup_heading, "Initial Setup", Palette.muted2)
        self.widgets.clipped_text(layout.actions_heading, "Actions", Palette.muted2)
        return layout.setup, layout.actions

    @staticmethod
    def _settings_account_action_button_rect(column: Rect, row_index: int) -> Rect:
        step = SETTINGS_CONTROL_H + SETTINGS_ROW_GAP
        return Rect(column.x, column.y + max(0, int(row_index)) * step, column.w, SETTINGS_CONTROL_H)


    def _comfy_endpoint_column_widths(self, inner_width: int) -> tuple[int, int]:
        """Return readable label and shared value widths for ComfyUI rows."""
        inner_width = max(1, int(inner_width))
        longest_label_w = self.widgets._text_width("Image to image") + 16
        # The normal two-column Settings layout guarantees at least 268px of
        # interior width. Reserve a useful 96px value field before reducing the
        # measured label width on an unusually narrow window.
        label_w = min(max(154, longest_label_w), max(96, inner_width - 106))
        value_w = max(1, inner_width - label_w - 10)
        return int(label_w), int(value_w)

    def _draw_app_data_card(self, rect: Rect) -> None:
        """Show the application-data paths under the working directory."""
        inner = self._draw_settings_card_shell(rect, "Application data")
        y = inner.y
        label_w = min(180, max(120, int(inner.w * 0.26)))
        rows = [
            ("Working directory", str(self.services.storage.paths.root_dir)),
            ("app.json", str(self.services.storage.paths.app_json_path)),
            ("Chats", str(self.services.storage.paths.chats_dir())),
            ("Agents", str(self.services.storage.paths.agents_dir())),
            ("Skills", str(self.services.storage.paths.skills_dir())),
            ("Log", str(self.services.storage.paths.log_jsonl_path)),
        ]
        for index, (label, value) in enumerate(rows):
            self.widgets.label(Rect(inner.x, y, label_w, SETTINGS_CONTROL_H), label, Palette.muted2)
            available_w = max(1, inner.w - label_w - 10)
            ro = Rect(inner.x + label_w + 10, y, min(SETTINGS_LONG_INPUT_W, available_w), SETTINGS_CONTROL_H)
            self.r.draw_round_rect(ro, 10, Palette.panel2)
            self.r.draw_round_outline(ro, 10, Palette.border)
            self.widgets.clipped_text(Rect(ro.x + 8, ro.y, max(0, ro.w - 16), ro.h), value, Palette.muted)
            if point_in_rect(self.state.input.mouse_x, self.state.input.mouse_y, ro):
                self.widgets._queue_tooltip(f"settings.app_data.{index}", ro, value)
            y += SETTINGS_CONTROL_H + SETTINGS_ROW_GAP

    def _prompt_preview_cache_key(self, cache_id: str, config: dict[str, Any]) -> str:
        """Hash only prompt-affecting state; never assemble a prompt in the draw path."""
        chat_id = str(self.state.active_chat_id or "")
        chat_signature: dict[str, Any] = {}
        if chat_id:
            try:
                chat = self.services.chats.load_chat(APP_SCOPE_ID, chat_id)
                chat_signature = {
                    "updated_at": str(chat.get("updated_at") or ""),
                    "features": copy.deepcopy(chat.get("features") or {}),
                    "endpoint_profile_id": str(chat.get("endpoint_profile_id") or ""),
                }
            except Exception as exc:
                chat_signature = {"error": f"{type(exc).__name__}: {exc}"}
        skill_store = getattr(self.services.tools, "skill_store", None)
        skill_revision = int(getattr(skill_store, "catalog_revision", 0) or 0)
        prompt_inputs = {
            "cache_id": str(cache_id),
            "chat_id": chat_id,
            "chat": chat_signature,
            "date": date.today().isoformat(),
            "features": copy.deepcopy(config.get("features") or {}),
            "prompting": copy.deepcopy(config.get("prompting") or {}),
            "llm": copy.deepcopy(config.get("llm") or {}),
            "agents": copy.deepcopy(config.get("agents") or {}),
            "tools": copy.deepcopy(config.get("tools") or {}),
            "skill_revision": skill_revision,
        }
        encoded = json.dumps(
            prompt_inputs, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str,
        ).encode("utf-8")
        return hashlib.sha256(encoded).hexdigest()

    def _cached_prompt_preview_text(
        self, cache_id: str, config: dict[str, Any], builder: Callable[[], str], *, refresh: bool = False,
    ) -> str:
        """Build a large preview once per meaningful input revision."""
        key = self._prompt_preview_cache_key(cache_id, config)
        cache = self.state.settings_prompt_preview_cache
        entry = cache.get(str(cache_id))
        if refresh or not isinstance(entry, dict) or entry.get("key") != key:
            text = str(builder() or "")
            cache[str(cache_id)] = {"key": key, "text": text}
            # Bound stale entries if future Settings sections add more previews.
            if len(cache) > 12:
                for stale_id in list(cache)[:-12]:
                    cache.pop(stale_id, None)
            return text
        return str(entry.get("text") or "")

    def _draw_system_prompt_preview_card(self, rect: Rect, config: dict[str, Any]) -> None:
        """Show a cached active-chat prompt independent of Developer Mode."""
        inner = self._draw_settings_card_shell(rect, "System prompt preview")
        refresh_w = self.widgets.button_width("Refresh", min_width=92, horizontal_padding=20)
        refresh_rect = Rect(inner.x + inner.w - refresh_w, inner.y, refresh_w, SETTINGS_CONTROL_H)
        refresh = self.widgets.button(
            "settings.system_prompt.preview.refresh", refresh_rect, "Refresh",
            tooltip="Rebuild the preview after editing Skill files outside Velox.",
        )
        self.widgets.clipped_text(
            Rect(inner.x, inner.y, max(1, inner.w - refresh_w - 12), SETTINGS_CONTROL_H),
            "Cached until prompt, endpoint, tool, chat, or in-app Skill settings change.", Palette.muted2,
        )
        preview = self._cached_prompt_preview_text(
            "chat", config, lambda: self._settings_system_prompt_preview_text(config), refresh=refresh,
        )
        preview_rect = Rect(
            inner.x, inner.y + SETTINGS_CONTROL_H + SETTINGS_BLOCK_GAP, inner.w,
            max(1, inner.h - SETTINGS_CONTROL_H - SETTINGS_BLOCK_GAP),
        )
        self.widgets.selectable_text_view(
            "settings.system_prompt.preview", preview_rect, preview,
        )

    def _draw_log_card(self, rect: Rect, widget_prefix: str = "developer") -> None:
        inner = self._draw_settings_card_shell(rect, "Log")
        y = inner.y
        level_options = ["Errors", "Warnings", "Info"]
        current_level_name = str(getattr(self.state, "log_level_filter", "Info") or "Info")
        if current_level_name not in level_options:
            current_level_name = "Info"
        self.widgets.label(Rect(inner.x, y, 88, SETTINGS_CONTROL_H), "Verbosity", Palette.muted2)
        current_level_name = self.widgets.dropdown(f"{widget_prefix}.log.level", Rect(inner.x + 98, y, 150, SETTINGS_CONTROL_H), current_level_name, level_options)
        setattr(self.state, "log_level_filter", current_level_name)
        log_path = self.services.storage.log_path()
        refresh_rect = Rect(inner.x + inner.w - 92, y, 92, SETTINGS_CONTROL_H)
        should_refresh = self.widgets.button(f"{widget_prefix}.log.refresh", refresh_rect, "Refresh", primary=True, tooltip="Reload log.jsonl from disk")
        if str(log_path) != getattr(self.state, "log_entries_cache_path", ""):
            should_refresh = True
        if should_refresh:
            self.state.log_entries_cache = self.services.storage.read_log_entries(max_level=LOG_LEVEL_INFO, limit=500)
            self.state.log_entries_cache_path = str(log_path)
            self.state.log_entries_last_refresh = format_display_datetime(now_iso())
        y += SETTINGS_CONTROL_H + SETTINGS_ROW_GAP
        level_value = {"Errors": LOG_LEVEL_ERROR, "Warnings": LOG_LEVEL_WARNING, "Info": LOG_LEVEL_INFO}.get(current_level_name, LOG_LEVEL_INFO)
        level_names = {LOG_LEVEL_ERROR: "ERROR", LOG_LEVEL_WARNING: "WARN", LOG_LEVEL_INFO: "INFO"}
        log_rows: list[dict[str, Any]] = []
        for i, entry in enumerate(self.state.log_entries_cache[-500:]):
            try:
                lvl = int(entry.get("level", LOG_LEVEL_INFO))
            except Exception:
                lvl = LOG_LEVEL_INFO
            if lvl > level_value:
                continue
            log_rows.append({
                "id": f"log.{i}",
                "level": level_names.get(lvl, "INFO"),
                "datetime": str(entry.get("datetime") or ""),
                "message": str(entry.get("log msg") or ""),
            })
        if not log_rows:
            log_rows.append({"id": "empty", "level": "", "datetime": "", "message": "No log entries loaded. Click Refresh."})
        self.widgets.table_view(
            f"{widget_prefix}.log.table",
            Rect(inner.x, y, inner.w, max(1, inner.y + inner.h - y)),
            [
                {"key": "level", "title": "Level", "width": 76},
                {"key": "datetime", "title": "Date", "width": 190},
                {"key": "message", "title": "Message"},
            ],
            log_rows,
            None,
            id_key="id",
            row_h=max(32, self.f.line_h + 12),
        )

    def _refresh_llm_task_entries(self) -> bool:
        try:
            rows = self.services.monitor.dashboard_records(None)
            for row in rows:
                task_id = str(row.get("task_id") or "")
                row["cancellable"] = self.services.monitor.can_cancel_task(task_id)
                row["deletable"] = self.services.monitor.can_delete_task(task_id)
                row["pausable"] = self.services.monitor.can_pause_task(task_id)
                row["resumable"] = self.services.monitor.can_resume_task(task_id)
            self.state.llm_task_entries_cache = rows
            self.state.llm_task_stats_cache = self.services.monitor.statistics()
            self.state.llm_task_cache_scope_id = APP_SCOPE_ID
            self.state.llm_task_cache_revision = int(self.services.monitor.revision)
            self.state.llm_task_last_refresh = format_display_datetime(now_iso())
            self.state.llm_task_last_refresh_monotonic = time.monotonic()
            self.state.llm_task_cache_error = ""
            return True
        except Exception as exc:
            self.state.llm_task_cache_scope_id = APP_SCOPE_ID
            self.state.llm_task_last_refresh_monotonic = time.monotonic()
            self.state.llm_task_cache_error = f"{type(exc).__name__}: {exc}"
            try:
                self.services.storage.append_app_log(
                    "developer.task_feed_failed",
                    {"error": self.state.llm_task_cache_error},
                )
            except Exception:
                pass
            return False


    def _settings_system_prompt_preview_text(self, config: dict[str, Any]) -> str:
        """Return the complete active-chat system prompt preview."""
        try:
            cid = self.state.active_chat_id or ""
            if not cid:
                return "No active chat system prompt preview is available."
            tool_features = self.services.chats.get_chat_tool_features(cid)
            base = "\n\n".join(
                str(message.get("content") or "")
                for message in self.services.context.assemble_chat_context(APP_SCOPE_ID, cid)
                if message.get("role") == "system"
            ).strip()
            try:
                preview_endpoint_id = self.services.chats.get_chat_endpoint_profile_id(cid)
                preview_endpoint = self.services.llm.resolve_endpoint(preview_endpoint_id)
            except Exception:
                preview_endpoint = {"vision": "disabled"}
            system_tools = bool(tool_features.get("system_tools_enabled"))
            skill_block = self.services.tools.build_skill_system_block(
                APP_SCOPE_ID, cid,
                feature_overrides=tool_features,
            ).strip()
            tool_block = self.services.tools.build_openai_tool_system_block(
                APP_SCOPE_ID, cid, feature_overrides=tool_features,
            ).strip()
            preview = "\n\n".join(
                block for block in (base, skill_block, tool_block) if block
            ).strip()
            return append_system_prompt_addon(
                preview, system_prompt_addon_from_config(config)
            ) or "No active chat system prompt preview is available."
        except Exception as exc:
            return f"System prompt preview unavailable: {type(exc).__name__}: {exc}"

    def _agent_system_prompt_preview_text(self, agent_kind: str) -> str:
        """Return one generated, non-editable Agent Task system prompt preview."""
        try:
            chat_id = str(self.state.active_chat_id or "")
            if not chat_id:
                chats = self.services.chats.list_chats(APP_SCOPE_ID)
                chat_id = str(chats[0].get("chat_id") or "") if chats else "preview-chat"
            config = self.services.storage.load_config()
            is_pa = str(agent_kind or AGENT_KIND_GENERAL) == AGENT_KIND_PERSONAL_ASSISTANT
            if self.state.active_chat_id:
                endpoint_profile_id = self.services.chats.get_chat_endpoint_profile_id(chat_id)
                tool_features = self.services.chats.get_chat_tool_features(chat_id)
            else:
                endpoint_profile_id = endpoint_profile_id_from_config(
                    config
                )
                tool_features = normalize_tool_feature_flags(config.get("features"))
            preview_agent = {
                "agent_id": "preview-pa-agent" if is_pa else "preview-agent",
                "source_chat_id": chat_id,
                "agent_kind": AGENT_KIND_PERSONAL_ASSISTANT if is_pa else AGENT_KIND_GENERAL,
                "pa_date": date.today().isoformat() if is_pa else None,
                "endpoint_profile_id": endpoint_profile_id,
                "tool_features": tool_features,
                "task_run_id": 1,
            }
            return self.services.agent_runtime.build_standard_system_prompt(preview_agent)
        except Exception as exc:
            return f"Agent system message unavailable: {type(exc).__name__}: {exc}"

    def _agent_standard_system_prompt_preview_text(self) -> str:
        return self._agent_system_prompt_preview_text(AGENT_KIND_GENERAL)

    def _pa_agent_system_prompt_preview_text(self) -> str:
        return self._agent_system_prompt_preview_text(AGENT_KIND_PERSONAL_ASSISTANT)

    def _settings_sections(self) -> list[str]:
        return ["General", "Appearance", "Endpoints", "Accounts", "Agents", "Skills", "Tools", "Developer"]


    @staticmethod
    def _settings_rows_height(row_count: int) -> int:
        count = max(0, int(row_count))
        return 0 if count == 0 else SETTINGS_CONTROL_H * count + SETTINGS_ROW_GAP * (count - 1)

    @staticmethod
    def _settings_card_height_for_content(content_height: int) -> int:
        shell_h = SETTINGS_CARD_PAD_Y * 2 + SETTINGS_CARD_TITLE_H
        return int(shell_h + max(0, int(content_height)) + SETTINGS_CARD_BOTTOM_PAD)

    def _settings_wrapped_text_height(self, text: str, width: int, *, minimum_lines: int = 1) -> int:
        wrapper = getattr(self.widgets, "_wrap_display_rows", None)
        if callable(wrapper):
            rows = wrapper(str(text or ""), max(1, int(width)))
            row_count = len(rows)
        else:
            # Geometry tests and non-UI diagnostics may provide only font metrics.
            char_w = max(1, int(getattr(self.f, "char_w", 8) or 8))
            chars_per_line = max(1, int(width) // char_w)
            row_count = max(1, math.ceil(len(str(text or "")) / chars_per_line))
        return max(max(1, int(minimum_lines)), row_count) * max(1, self.f.line_h)

    @staticmethod
    def _settings_inner_width_for_column(column_width: int) -> int:
        return max(1, int(column_width) - 4 - SETTINGS_CARD_PAD_X * 2)

    def _general_settings_card_heights(self, column_width: int) -> tuple[int, ...]:
        _ = column_width
        one_control_h = self._settings_card_height_for_content(SETTINGS_CONTROL_H)
        data_h = self._settings_card_height_for_content(self._settings_rows_height(6))
        history_h = self._settings_card_height_for_content(
            self._settings_rows_height(2) + SETTINGS_ROW_GAP + 28 + 180
        )
        return (
            data_h, 450, one_control_h, one_control_h, one_control_h,
            one_control_h, one_control_h, history_h, 246,
        )

    def _endpoint_settings_card_heights(self, column_width: int) -> tuple[int, int, int]:
        inner_w = self._settings_inner_width_for_column(column_width)
        description_h = self._settings_wrapped_text_height(
            ENDPOINT_DEFAULTS_DESCRIPTION, inner_w,
        )
        llm_h = self._settings_card_height_for_content(
            description_h + SETTINGS_BLOCK_GAP + self._settings_rows_height(1)
            + SETTINGS_BLOCK_GAP + SETTINGS_CONTROL_H
        )
        comfy_h = self._settings_card_height_for_content(self._settings_rows_height(4))
        meshy_h = self._settings_card_height_for_content(self._settings_rows_height(5))
        return llm_h, comfy_h, meshy_h

    def _github_settings_card_height(self, column_width: int) -> int:
        inner_w = self._settings_inner_width_for_column(column_width)
        description_h = self._settings_wrapped_text_height(
            "Store one GitHub username and personal access token for chats and agents to use through ordinary shell or terminal workflows.", inner_w,
        )
        note_h = self._settings_wrapped_text_height(
            "Reads are available when relevant. Writes should have a direct task reason, ideally explicit direction from the user.", inner_w,
        )
        return self._settings_card_height_for_content(
            description_h + SETTINGS_BLOCK_GAP + self._settings_rows_height(2) + SETTINGS_BLOCK_GAP + note_h
        )

    @staticmethod
    def _account_connector_card_heights() -> tuple[int, int, int, int]:
        """Return Calendar, Drive, Gmail, and Slack card heights for the grouped layout."""
        return 1040, 640, 770, 980

    def _agent_settings_layout(self, column_width: int) -> tuple[int, int, int, int]:
        inner_w = self._settings_inner_width_for_column(column_width)
        general_intro_h = self._settings_wrapped_text_height(
            "General Agents use Velox's immutable agent protocol plus the editable General Agent skill. They execute concrete background work and cannot spawn other agents.", inner_w,
        )
        pa_intro_h = self._settings_wrapped_text_height(
            "The PA reviews locally cached Gmail and Slack data plus Calendar Events and Items after the daily start time, then checks again at the configured interval when no PA Task is active. It may create or update Items and delegate concrete deliverables to General Agents. Google Drive remains ad hoc only.", inner_w,
        )
        general_h = self._settings_card_height_for_content(
            general_intro_h + SETTINGS_BLOCK_GAP + self._settings_rows_height(2)
        )
        report_h = max(self.f.line_h, 24)
        pa_h = self._settings_card_height_for_content(
            pa_intro_h + SETTINGS_BLOCK_GAP + self._settings_rows_height(6) + SETTINGS_BLOCK_GAP + report_h
        )
        return int(general_h), int(pa_h), int(general_intro_h), int(pa_intro_h)

    def _agent_settings_card_heights(self, column_width: int = 1200) -> tuple[int, int]:
        general_h, pa_h, _general_intro_h, _pa_intro_h = self._agent_settings_layout(column_width)
        return general_h, pa_h

    def _settings_section_content_height(
        self, section: str, *, content_width: int = 1200, developer_mode: bool = False,
    ) -> int:
        gap = SETTINGS_CARD_GAP_Y
        general_cards = self._general_settings_card_heights(content_width)
        endpoint_cards = self._endpoint_settings_card_heights(content_width)
        agent_card_h, pa_card_h = self._agent_settings_card_heights(content_width)
        github_h = self._github_settings_card_height(content_width)
        calendar_h, drive_h, gmail_h, slack_h = self._account_connector_card_heights()
        defaults_h = self._settings_card_height_for_content(self._settings_rows_height(6))
        heights = {
            "General": sum(general_cards) + gap * (len(general_cards) - 1) + 8,
            "Appearance": self._settings_card_height_for_content(self._settings_rows_height(10)) + 20,
            "Endpoints": sum(endpoint_cards) + gap * (len(endpoint_cards) - 1) + 20,
            "Accounts": github_h + gap + calendar_h + gap + drive_h + gap + gmail_h + gap + slack_h + 24,
            "Agents": agent_card_h + gap + pa_card_h + gap + 360 + gap + 360 + 20,
            "Skills": 1240 + 20,
            "Tools": (
                defaults_h
                + SETTINGS_RESOURCE_ROW_H * 2
                + sum(SETTINGS_RESOURCE_CARD_BASE_H + SETTINGS_RESOURCE_ROW_H * len(rows) for _title, rows in WEB_SETTINGS_UI_GROUPS)
                + sum(SETTINGS_RESOURCE_CARD_BASE_H + SETTINGS_RESOURCE_ROW_H * len(rows) for _title, rows in TOOL_SETTINGS_UI_GROUPS)
                + gap * (len(WEB_SETTINGS_UI_GROUPS) + len(TOOL_SETTINGS_UI_GROUPS) + 1)
                + 20
            ),
            "Developer": (
                self._settings_card_height_for_content(self._settings_rows_height(2))
                + gap + 510 + gap + 510 + 2
            ) if developer_mode else (
                self._settings_card_height_for_content(self._settings_rows_height(2))
                + gap + 160 + 8
            ),
        }
        return heights.get(section, 400)

    def _draw_settings_section_nav(self, rect: Rect) -> None:
        self.r.draw_card(rect, radius=18, fill=Palette.panel)
        inner = rect.inset(12)
        y = inner.y
        sections = self._settings_sections()
        if self.state.settings_section not in sections:
            self.state.settings_section = "General"
        row_h = max(40, self.f.line_h + 14)
        for section in sections:
            if self.widgets.nav_button(
                "settings.section." + safe_filename(section).lower().replace(" ", "_"),
                Rect(inner.x, y, inner.w, row_h),
                section,
                active=self.state.settings_section == section,
            ):
                self.state.settings_section = section
                self.state.scroll["settings.content"] = 0
                self.state.active_widget = None
                self.state.open_dropdown = None
            y += row_h + 6


    def _draw_tool_defaults_card(self, rect: Rect, config: dict[str, Any]) -> None:
        inner = self._draw_settings_card_shell(rect, "Tool defaults")
        features = config.setdefault("features", {})
        y = inner.y
        rows = [
            ("file_tools_enabled", "File tools", True),
            ("system_tools_enabled", "System tools", True),
            ("web_tools_enabled", "Web tools", True),
            ("agent_tools_enabled", "Agent tools", True),
            ("chat_history_enabled", "Chat history", True),
        ]
        tool_tooltips = {
            "file_tools_enabled": "Default for fs_ and doc_ local file/document read, write, edit, search, import, and PDF-rendering tools.",
            "system_tools_enabled": (
                "Default for execution, ordinary terminals, desktop/image, Calendar, Data, Drive, skills, "
                "ComfyUI, Meshy, time, and other non-file local/system tools."
            ),
            "web_tools_enabled": "Default for web search, fetch, crawl, download, and webpage rendering tools.",
            "agent_tools_enabled": "Default for starting, listing, pausing, resuming, stopping, and inspecting chat-owned agents.",
            "chat_history_enabled": "Default for chat search and stored chat-summary tools.",
        }
        for key, label, default in rows:
            features[key] = self.widgets.toggle(
                "settings.tools." + key,
                Rect(inner.x, y, inner.w, SETTINGS_CONTROL_H),
                label,
                bool(features.get(key, default)),
                tooltip=tool_tooltips.get(key, ""),
            )
            y += SETTINGS_CONTROL_H + SETTINGS_ROW_GAP


    def _draw_document_handling_card(self, rect: Rect, config: dict[str, Any]) -> None:
        """Draw global document-input behavior that applies to every chat."""
