    def _draw_timezone_settings_card(self, rect: Rect, config: dict[str, Any]) -> None:
        inner = self._draw_settings_card_shell(rect, "Date and time")
        vault_cfg = config.setdefault("vault", {})
        current = str(vault_cfg.get("local_timezone") or VAULT_LOCAL_TIMEZONE_DEFAULT).strip() or VAULT_LOCAL_TIMEZONE_DEFAULT
        timezone_options = [
            "system", "UTC",
            "America/Toronto", "America/Vancouver", "America/Edmonton",
            "America/Winnipeg", "America/Halifax", "America/St_Johns",
            "America/New_York", "America/Chicago", "America/Denver",
            "America/Los_Angeles", "Europe/London",
        ]
        if current not in timezone_options:
            timezone_options.insert(1, current)
        label_w = min(190, max(145, int(inner.w * 0.28)))
        input_x = inner.x + label_w + 10
        input_w = max(180, inner.x + inner.w - input_x)
        tooltip = (
            "System is the default. This timezone controls Calendar dates, Event times, Vault filters, "
            "source timestamps, and date grouping. External source timestamps keep their original instant; "
            "only Velox display and grouping change."
        )
        self.widgets.clipped_text(
            Rect(inner.x, inner.y, label_w, SETTINGS_CONTROL_H),
            "Display timezone", Palette.muted2, tooltip=tooltip,
        )
        selected = self.widgets.dropdown(
            "settings.general.display_timezone",
            Rect(input_x, inner.y, min(360, input_w), SETTINGS_CONTROL_H),
            current, timezone_options, tooltip=tooltip,
        )
        vault_cfg["local_timezone"] = selected

