        drive_token_present = bool(validation.get("token_present")) or isinstance(drive_credentials.get("token"), dict)
        drive_busy = bool(drive_status.get("operation_in_progress")) or GOOGLE_DRIVE_SOURCE_TYPE in self.state.vault_connector_tasks
        setup_column, actions_column = self._draw_settings_account_action_columns(inner, cy, compact=True)
