class RecoveryService:
    def __init__(self, storage: Storage):
        self.storage = storage

    def scan_for_corrupt_json(self) -> list[dict[str, Any]]:
        """Validate only Velox-owned JSON files in the execution directory."""
        errors: list[dict[str, Any]] = []
        candidates = [self.storage.paths.app_json_path]
        if self.storage.paths.chats_dir().exists():
            for chat_dir in self.storage.paths.chats_dir().iterdir():
                if chat_dir.is_dir() and chat_dir.name.startswith("chat_"):
                    candidates.extend([chat_dir / "chat.json", chat_dir / "summary.json"])
                    live_snapshot = chat_dir / "streaming_turn.json"
                    if live_snapshot.is_file():
                        candidates.append(live_snapshot)
        if self.storage.paths.agents_dir().exists():
            for agent_dir in self.storage.paths.agents_dir().iterdir():
                if agent_dir.is_dir() and agent_dir.name.startswith("agent_"):
                    candidates.append(agent_dir / "agent.json")
        if self.storage.paths.calendar_dir().exists():
            candidates.extend([
                self.storage.paths.calendar_week_chats_json(),
                self.storage.paths.calendar_google_sync_json(),
            ])
            candidates.extend(_json_record_paths(self.storage.paths.calendar_events_dir(), "event"))
            candidates.extend(_json_record_paths(self.storage.paths.calendar_items_dir(), "item"))
        if self.storage.paths.vault_dir().exists():
            candidates.extend(_json_record_paths(self.storage.paths.vault_sources_dir(), "source"))
            candidates.extend(_json_record_paths(self.storage.paths.vault_containers_dir(), "container"))
            candidates.extend(_json_record_paths(self.storage.paths.vault_items_dir(), "item"))
            candidates.extend(_json_record_paths(self.storage.paths.vault_sync_states_dir(), "sync"))
        if self.storage.paths.scheduled_tasks_dir().exists():
            candidates.extend(sorted(self.storage.paths.scheduled_tasks_dir().glob("task_*.json")))
        if self.storage.paths.context_docs_dir().exists():
            candidates.extend(sorted(self.storage.paths.context_docs_dir().glob("context_*.json")))
        if self.storage.paths.context_revisions_dir().exists():
            candidates.extend(sorted(self.storage.paths.context_revisions_dir().glob("*/revision_*.json")))
        for candidate in candidates:
            if not candidate.exists():
                continue
            try:
                read_json(candidate)
            except Exception as exc:
                errors.append({"path": str(candidate), "error": str(exc)})
        credential_store = CredentialStore(self.storage.paths)
        for account, path, loader in (
            (GITHUB_CREDENTIAL_ACCOUNT, self.storage.paths.github_credentials_file(), credential_store.load_github),
            (GOOGLE_CALENDAR_CREDENTIAL_ACCOUNT, self.storage.paths.google_calendar_credentials_file(), credential_store.load_google_calendar),
            (GOOGLE_DRIVE_CREDENTIAL_ACCOUNT, self.storage.paths.google_drive_credentials_file(), credential_store.load_google_drive),
            (GMAIL_CREDENTIAL_ACCOUNT, self.storage.paths.gmail_credentials_file(), credential_store.load_gmail),
            (SLACK_CREDENTIAL_ACCOUNT, self.storage.paths.slack_credentials_file(), credential_store.load_slack),
        ):
            if not path.is_file():
                continue
            try:
                loader()
            except Exception as exc:
                errors.append({"path": str(path), "account": account, "error": str(exc)})
        return errors

    def rebuild_derived_state(self) -> None:
        """Recreate chat-owned derived files and required Calendar directories."""
        self.storage.ensure_first_run_files()
        CalendarStore(self.storage)._ensure_layout_unchecked()
        VaultStore(self.storage)._ensure_layout_unchecked()
        scheduled_tasks = ScheduledTaskStore(self.storage)
        scheduled_tasks.ensure_layout(seed_defaults=False)
        ContextDocStore(self.storage, scheduled_tasks).ensure_layout(seed_defaults=False)
        chats = ChatStore(self.storage)
        for chat in chats.list_chats():
            chat_id = str(chat.get("chat_id") or "")
            if not chat_id:
                continue
            for directory in (
                self.storage.paths.chat_attachments_dir(chat_id),
                self.storage.paths.chat_workspace_dir(chat_id),
                self.storage.paths.chat_temp_dir(chat_id),
            ):
                directory.mkdir(parents=True, exist_ok=True)
            if not self.storage.paths.chat_summary_json(chat_id).exists():
                atomic_write_json(
                    self.storage.paths.chat_summary_json(chat_id),
                    default_chat_summary(chat_id, str(chat.get("endpoint_profile_id") or DEFAULT_ENDPOINT_PROFILE_ID)),
                )
            if not self.storage.paths.chat_turns_jsonl(chat_id).exists():
                atomic_write_text(self.storage.paths.chat_turns_jsonl(chat_id), "")
        self.storage.paths.agents_dir().mkdir(parents=True, exist_ok=True)
        for agent in AgentStore(self.storage).list_agents():
            agent_id = str(agent.get("agent_id") or "")
            if agent_id and not self.storage.paths.agent_transcript_jsonl(agent_id).exists():
                atomic_write_text(self.storage.paths.agent_transcript_jsonl(agent_id), "")

    def compact_logs(self, max_bytes: int = 10 * 1024 * 1024) -> list[str]:
        """Retain a bounded complete-row tail of root log.jsonl in place."""
        path = self.storage.paths.log_jsonl_path
        max_bytes = max(4096, int(max_bytes))
        APP_LOG_WRITER.flush((path,), timeout=15.0)
        try:
            previous_bytes = int(path.stat().st_size)
        except OSError:
            return []
        if previous_bytes <= max_bytes:
            return []
        keep_bytes = max(2048, max_bytes // 2)
        with DATA_ROOTS.lock_for_path(path):
            try:
                with path.open("rb") as handle:
                    handle.seek(max(0, previous_bytes - keep_bytes))
                    tail = handle.read(keep_bytes)
            except FileNotFoundError:
                return []
            # Drop a partial first row when the retained range begins mid-line.
            if previous_bytes > keep_bytes:
                newline = tail.find(b"\n")
                tail = tail[newline + 1:] if newline >= 0 else b""
            _plain_atomic_write_bytes(path, tail)
        self.storage.append_app_log(
            "log.compacted",
            {"previous_bytes": previous_bytes, "retained_bytes": len(tail)},
        )
        return [str(path)]


def endpoint_profile_ref(config: dict[str, Any], profile_id: str) -> dict[str, Any]:
    """Return a mutable saved endpoint profile by its exact persistent ID."""
    llm = config.get("llm") if isinstance(config, dict) else None
    if not isinstance(llm, dict):
        raise KeyError("llm")
    selected_id = str(profile_id or "").strip()
    profiles = llm.get("endpoint_profiles")
    if isinstance(profiles, list):
        for profile in profiles:
            if isinstance(profile, dict) and str(profile.get("id") or "") == selected_id:
                return profile
    raise KeyError(f"No saved endpoint profile with id {selected_id!r}")


def parse_args(argv: list[str]) -> argparse.Namespace:
    """Parse command-line options using this release's version metadata."""
    parser = argparse.ArgumentParser(description=(
        f"Velox V{SOURCE_REVISION}: agentic work across local and hosted models. "
        f"Data format: {DATA_FILE_VERSION}."
    ))
    parser.add_argument("--init-only", action="store_true", help="create data defaults and exit")
    parser.add_argument("--test", action="store_true", help="run the companion test_velox.py suite")
    parser.add_argument("--test-class", default="", help=argparse.SUPPRESS)
    parser.add_argument("--no-ui", action="store_true", help="initialize services but do not open the PySDL3 window")
    return parser.parse_args(argv)


async def async_main(argv: list[str]) -> int:
    args = parse_args(argv)
    if args.test:
        import test_velox
        return test_velox.run_test_suite()

    app = VeloxApp()
    if args.init_only or args.no_ui:
        app.storage.ensure_first_run_files()
        app.ensure_chat_if_empty()
        app.persist_app_state()
        await asyncio.to_thread(APP_LOG_WRITER.flush)
        print(f"{APP_NAME} initialized at: {app.paths.root_dir}")
        return 0

    try:
        await app.run()
        return 0
    except Exception:
        crash_traceback = traceback.format_exc()
        # A draw/runtime exception bypasses VeloxApp.run's normal shutdown tail.
        # Close persistent subprocess trees here so a UI crash cannot leave
        # invisible cmd.exe sessions running after the application exits.
        try:
            app.google_calendar.request_shutdown()
        except Exception:
            pass
        try:
            app.chats.flush_streaming_snapshots()
        except Exception:
            pass
        try:
            app.chat.cancel_all()
        except Exception:
            pass
        try:
            await app.agent_runtime.shutdown()
        except Exception:
            pass
        try:
            await app.vault_connectors.shutdown()
        except Exception:
            pass
        try:
            app.tools.terminal_runtime.shutdown_all(
                reason="Velox crashed; active terminal session ended."
            )
        except Exception:
            pass
        app.storage.append_app_log("app.crash", {"traceback": crash_traceback})
        await asyncio.to_thread(APP_LOG_WRITER.flush)
        raise


def main() -> None:
    try:
        if "--test-class" in sys.argv[1:] or "--test" in sys.argv[1:]:
            test_file = Path(__file__).with_name("test_velox.py")
            os.execv(sys.executable, [sys.executable, str(test_file), *sys.argv[1:]])
        try:
            raise SystemExit(asyncio.run(async_main(sys.argv[1:])))
        except KeyboardInterrupt:
            raise SystemExit(130)
    finally:
        # Explicitly stop idle daemon writers. Python 3.10 can otherwise stall
        # during interpreter finalization when a condition-waiting writer still
        # owns runtime locks, even though the worker is marked daemon.
        CoalescingAtomicJSONWriter.shutdown_all(timeout=3.0)
        BatchedJSONLWriter.shutdown_all(timeout=3.0)


import contextvars

EXPERT_MODE_REQUIREMENT_NOT_STARTED = "not_started"
EXPERT_MODE_REQUIREMENT_IN_PROGRESS = "in_progress"
EXPERT_MODE_REQUIREMENT_DONE = "done"
EXPERT_MODE_REQUIREMENT_VERIFIED = "verified"
EXPERT_MODE_REQUIREMENT_INCOMPLETE = EXPERT_MODE_REQUIREMENT_NOT_STARTED
EXPERT_MODE_REQUIREMENT_STATES = (
    EXPERT_MODE_REQUIREMENT_NOT_STARTED,
    EXPERT_MODE_REQUIREMENT_IN_PROGRESS,
    EXPERT_MODE_REQUIREMENT_DONE,
    EXPERT_MODE_REQUIREMENT_VERIFIED,
)
EXPERT_MODE_IMPLEMENTER_STATES = (
    EXPERT_MODE_REQUIREMENT_NOT_STARTED,
    EXPERT_MODE_REQUIREMENT_IN_PROGRESS,
    EXPERT_MODE_REQUIREMENT_DONE,
)
EXPERT_MODE_REVIEW_SCHEMA = "expert_mode_review.v303"
EXPERT_MODE_REVIEW_HANDOFF_SCHEMA = "expert_mode_review_handoff.v303"
EXPERT_MODE_REQUIREMENT_HISTORY_SCHEMA = "expert_mode_requirement_history.v303"
EXPERT_MODE_REVIEW_AGENT_KIND = "expert_reviewer"
EXPERT_MODE_REVIEW_TOOL_NAME = "expert_review_submit"
EXPERT_MODE_REVIEWER_READ_ONLY_TOOL_DENYLIST = frozenset({
    "fs_write", "fs_edit", "fs_delete", "fs_move", "fs_copy", "fs_mkdir", "fs_import", "fs_rename",
    "doc_write", "doc_create", "doc_edit", "doc_replace", "doc_delete", "doc_import",
    "agents_start", "agents_stop", "agents_pause", "agents_resume",
    "chat_send", "chat_create", "chat_delete",
    "terminal_send", "terminal_write", "web_download_file", "image_generate",
})

_EXPERT_STATE_LOCK_GUARD = threading.RLock()
_EXPERT_STATE_LOCKS: dict[str, threading.RLock] = {}
_EXPERT_REVIEW_ASYNC_LOCKS: dict[str, asyncio.Lock] = {}
_REVIEWER_CONTEXT = contextvars.ContextVar("velox_reviewer", default=False)


def _clone_review_json(value: Any) -> Any:
    return json.loads(json.dumps(value, ensure_ascii=False, default=str))


def _expert_state_path_lock(path: Path) -> threading.RLock:
    key = str(path.resolve(strict=False))
    with _EXPERT_STATE_LOCK_GUARD:
        return _EXPERT_STATE_LOCKS.setdefault(key, threading.RLock())


def _expert_review_lock(path: Path) -> asyncio.Lock:
    key = str(path.resolve(strict=False))
    with _EXPERT_STATE_LOCK_GUARD:
        return _EXPERT_REVIEW_ASYNC_LOCKS.setdefault(key, asyncio.Lock())


def _expert_owner_value(store: Any, *names: str, default: Any = "") -> Any:
    holders = [store, getattr(store, "context", None)]
    for holder in holders:
        if holder is None:
            continue
        for name in names:
            try:
                value = getattr(holder, name)
            except Exception:
                continue
            if callable(value):
                continue
            if value not in (None, ""):
                return value
        data = getattr(holder, "__dict__", {})
        for name in names:
            value = data.get(name)
            if value not in (None, ""):
                return value
    return default


def _expert_state_file(store: Any) -> Path:
    for name in (
        "path", "state_file", "state_path", "expert_mode_file", "expert_mode_path",
        "_state_file", "_state_path",
    ):
        try:
            candidate = getattr(store, name)
        except Exception:
            continue
        if callable(candidate):
            try:
                sig = inspect.signature(candidate)
                required = [p for p in sig.parameters.values()
                            if p.default is inspect.Parameter.empty
                            and p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD)]
                if required:
                    continue
                candidate = candidate()
            except Exception:
                continue
        if isinstance(candidate, (str, os.PathLike)):
            path = Path(candidate)
            if path.suffix.lower() == ".json" and "expert" in path.name.lower():
                return path
    for value in getattr(store, "__dict__", {}).values():
        if isinstance(value, (str, os.PathLike)):
            path = Path(value)
            if path.suffix.lower() == ".json" and "expert" in path.name.lower():
                return path

    storage = getattr(store, "storage", None)
    paths = getattr(storage, "paths", None)
    owner_kind = str(_expert_owner_value(store, "owner_kind", "kind", default="chat"))
    chat_id = str(_expert_owner_value(store, "chat_id", "source_chat_id"))
    agent_id = str(_expert_owner_value(store, "agent_id"))
    task_run_id = int(_expert_owner_value(store, "task_run_id", "agent_task_run_id", default=0) or 0)
    if owner_kind == "agent" or agent_id:
        if paths is not None and hasattr(paths, "agent_dir"):
            base = Path(paths.agent_dir(agent_id))
        elif paths is not None and hasattr(paths, "root_dir"):
            base = Path(paths.root_dir) / "agents" / f"agent_{agent_id}"
        else:
            base = Path.cwd() / "agents" / f"agent_{agent_id}"
        return base / f"agent_{task_run_id}_expert_mode.json"
    if paths is not None and hasattr(paths, "chat_dir"):
        base = Path(paths.chat_dir(chat_id))
    elif paths is not None and hasattr(paths, "root_dir"):
        base = Path(paths.root_dir) / "chats" / f"chat_{chat_id}"
    else:
        base = Path.cwd() / "chats" / f"chat_{chat_id}"
    return base / "chat_expert_mode.json"


def _write_expert_state_json(path: Path, value: Any) -> None:
    with DATA_ROOTS.lock_for_path(path):
        _require_durable_owner(path)
        path.parent.mkdir(parents=True, exist_ok=True)
        temp = path.with_name(path.name + ".tmp-" + uuid.uuid4().hex)
        try:
            temp.write_text(json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")
            os.replace(temp, path)
        finally:
            try:
                temp.unlink(missing_ok=True)
            except OSError:
                # Cleanup cannot replace a write error or undo a committed replace.
                pass


def _expert_state_counts(state: dict[str, Any]) -> dict[str, int]:
    requirements = list(state.get("requirements") or [])
    counts = {name: 0 for name in EXPERT_MODE_REQUIREMENT_STATES}
    for item in requirements:
        status = str(item.get("status") or item.get("state") or "")
        if status in counts:
            counts[status] += 1
    counts["total"] = len(requirements)
    counts["implemented"] = counts[EXPERT_MODE_REQUIREMENT_DONE] + counts[EXPERT_MODE_REQUIREMENT_VERIFIED]
    counts["actionable"] = counts[EXPERT_MODE_REQUIREMENT_NOT_STARTED] + counts[EXPERT_MODE_REQUIREMENT_IN_PROGRESS]
    return counts


def _refresh_expert_state_derived(state: dict[str, Any]) -> dict[str, Any]:
    counts = _expert_state_counts(state)
    state["requirement_count"] = counts["total"]
    state["not_started_count"] = counts[EXPERT_MODE_REQUIREMENT_NOT_STARTED]
    state["in_progress_count"] = counts[EXPERT_MODE_REQUIREMENT_IN_PROGRESS]
    state["done_count"] = counts[EXPERT_MODE_REQUIREMENT_DONE]
    state["verified_count"] = counts[EXPERT_MODE_REQUIREMENT_VERIFIED]
    state["complete_count"] = counts["implemented"]
    state["resolved_count"] = counts["implemented"]
    state["active"] = str(state.get("status") or "active") == "active"
    return state


def _validate_expert_state(raw: Any) -> dict[str, Any]:
    if not isinstance(raw, dict):
        raise ValueError("Checklist state must be an object")
    state = _clone_review_json(raw)
    schema = str(state.get("schema") or "")
    if schema and schema not in {"expert_mode_state.v303", "expert_mode.v303"}:
        raise ValueError(f"Unsupported Checklist state schema {schema!r}; expected the current schema")
    state["schema"] = "expert_mode_state.v303"
    status = str(state.get("status") or "active")
    if status not in {"active", "succeeded"}:
        raise ValueError(f"Invalid Checklist status {status!r}")
    state["status"] = status
    requirements = state.get("requirements")
    if not isinstance(requirements, list) or not (1 <= len(requirements) <= 100):
        raise ValueError("Checklist requires between 1 and 100 requirements")
    normalized: list[dict[str, Any]] = []
    seen: set[str] = set()
    for index, source in enumerate(requirements, 1):
        if not isinstance(source, dict):
            raise ValueError("Each Checklist requirement must be an object")
        requirement_id = str(source.get("id") or f"R{index}").strip()
        expected_id = f"R{index}"
        if requirement_id != expected_id or requirement_id in seen:
            raise ValueError("Checklist requirement IDs must remain stable contiguous R1..Rn values")
        seen.add(requirement_id)
        text = str(source.get("requirement") or source.get("text") or "").strip()
        if not text:
            raise ValueError(f"{requirement_id} has empty requirement text")
        item_status = str(source.get("status") or source.get("state") or EXPERT_MODE_REQUIREMENT_NOT_STARTED)
        if item_status not in EXPERT_MODE_REQUIREMENT_STATES:
            raise ValueError(f"{requirement_id} has invalid requirement state {item_status!r}")
        progress = str(source.get("progress") or source.get("summary") or "").strip()
        next_step = str(source.get("next_step") or "").strip()
        if item_status == EXPERT_MODE_REQUIREMENT_NOT_STARTED:
            progress = ""
            next_step = ""
        elif item_status == EXPERT_MODE_REQUIREMENT_IN_PROGRESS:
            if not progress:
                raise ValueError(f"{requirement_id} in_progress requires a concise factual progress summary")
            if not next_step:
                raise ValueError(f"{requirement_id} in_progress requires one concrete next_step")
        elif item_status == EXPERT_MODE_REQUIREMENT_DONE:
            if not progress:
                raise ValueError(f"{requirement_id} done requires the implementer's completion/validation summary")
            next_step = ""
        elif item_status == EXPERT_MODE_REQUIREMENT_VERIFIED:
            if not str(source.get("review_summary") or progress).strip():
                raise ValueError(f"{requirement_id} verified requires a reviewer summary")
            next_step = ""
        normalized.append({
            "id": requirement_id,
            "requirement": text,
            "text": text,
            "status": item_status,
            "state": item_status,
            "progress": progress,
            "summary": progress,
            "next_step": next_step,
            "implementer_summary": str(source.get("implementer_summary") or (progress if item_status == EXPERT_MODE_REQUIREMENT_DONE else "")).strip(),
            "review_summary": str(source.get("review_summary") or "").strip(),
            "updated_at": str(source.get("updated_at") or state.get("updated_at") or _checklist_utc_now()),
            "verified_at": str(source.get("verified_at") or ""),
            "last_actor": str(source.get("last_actor") or "velox"),
            "last_review_cycle": int(source.get("last_review_cycle") or 0),
            "complete": item_status in {EXPERT_MODE_REQUIREMENT_DONE, EXPERT_MODE_REQUIREMENT_VERIFIED},
            "resolved": item_status in {EXPERT_MODE_REQUIREMENT_DONE, EXPERT_MODE_REQUIREMENT_VERIFIED},
            "resolution": progress,
            "resolved_at": str(source.get("resolved_at") or source.get("verified_at") or ""),
        })
    state["requirements"] = normalized
    state.setdefault("run_id", uuid.uuid4().hex)
    state.setdefault("created_at", _checklist_utc_now())
    state.setdefault("updated_at", state["created_at"])
    state.setdefault("completed_at", "")
    state.setdefault("review_cycle", 0)
    state.setdefault("review_status", "idle")
    state.setdefault("review_requested", False)
    state.setdefault("review_in_progress", False)
    state.setdefault("review_feedback_pending", False)
    state.setdefault("review_passed_pending", False)
    state.setdefault("review_passed_prompt_sent", False)
    state.setdefault("review_error", "")
    state.setdefault("reviews", [])
    return _refresh_expert_state_derived(state)


def _load_expert_state(store: Any, *, required: bool = False) -> dict[str, Any] | None:
    manager, owner = _canonical_checklists(store)
    state = manager.execution_state(owner)
    if state is None and required:
        raise ValueError("Checklist is not active for this Task")
    return state


def _save_expert_state(store: Any, state: dict[str, Any]) -> dict[str, Any]:
    path = _expert_state_file(store)
    state = _validate_expert_state(state)
    state["updated_at"] = _checklist_utc_now()
    state = _refresh_expert_state_derived(state)
    with _expert_state_path_lock(path):
        _write_expert_state_json(path, state)
    return state


def _expert_run_dir(store: Any, state: dict[str, Any]) -> Path:
    path = _expert_state_file(store)
    run_id = str(state.get("run_id") or "run")
    return path.parent / "expert_reviews" / f"run_{run_id}"


def _expert_history_path(store: Any, state: dict[str, Any]) -> Path:
    existing = str(state.get("requirement_history_file") or "").strip()
    if existing:
        return Path(existing)
    return _expert_run_dir(store, state) / "requirement_history.jsonl"


def _append_expert_history(
    store: Any,
    state: dict[str, Any],
    *,
    actor: str,
    requirement_id: str,
    old_state: str,
    new_state: str,
    progress: str = "",
    next_step: str = "",
    review_cycle: int = 0,
    reviewer_verdict: str = "",
    event: str = "state_transition",
) -> None:
    path = _expert_history_path(store, state)
    path.parent.mkdir(parents=True, exist_ok=True)
    record = {
        "schema": EXPERT_MODE_REQUIREMENT_HISTORY_SCHEMA,
        "timestamp": _checklist_utc_now(),
        "owner_kind": str(state.get("owner_kind") or _expert_owner_value(store, "owner_kind", default="chat")),
        "chat_id": str(state.get("chat_id") or _expert_owner_value(store, "chat_id", "source_chat_id")),
        "agent_id": str(state.get("agent_id") or _expert_owner_value(store, "agent_id")),
        "task_run_id": int(state.get("task_run_id") or _expert_owner_value(store, "task_run_id", "agent_task_run_id", default=0) or 0),
        "run_id": str(state.get("run_id") or ""),
        "review_cycle": int(review_cycle or 0),
        "actor": str(actor),
        "event": str(event),
        "requirement_id": str(requirement_id),
        "old_state": str(old_state),
        "new_state": str(new_state),
        "progress": str(progress),
        "next_step": str(next_step),
        "reviewer_verdict": str(reviewer_verdict),
    }
    lock = _expert_state_path_lock(path)
    with lock:
        with path.open("a", encoding="utf-8", newline="\n") as stream:
            stream.write(json.dumps(record, ensure_ascii=False, sort_keys=True) + "\n")
    state["requirement_history_file"] = str(path)


def _expert_state_result(state: dict[str, Any] | None, *, action: str = "status", message: str = "") -> dict[str, Any]:
    if state is None:
        return {
            "schema": "expert_mode_tool_result.v303",
            "action": action,
            "active": False,
            "status": "inactive",
            "requirements": [],
            "message": message or "Checklist is not active for this Task.",
        }
    state = _refresh_expert_state_derived(_clone_review_json(state))
    return {
        "schema": "expert_mode_tool_result.v303",
        "action": action,
        "active": bool(state.get("status") == "active"),
        "status": str(state.get("status") or "active"),
        "run_id": str(state.get("run_id") or ""),
        "review_cycle": int(state.get("review_cycle") or 0),
        "review_status": str(state.get("review_status") or "idle"),
        "requirement_count": int(state.get("requirement_count") or 0),
        "not_started_count": int(state.get("not_started_count") or 0),
        "in_progress_count": int(state.get("in_progress_count") or 0),
        "done_count": int(state.get("done_count") or 0),
        "verified_count": int(state.get("verified_count") or 0),
        "requirements": state.get("requirements") or [],
        "summary": _format_expert_rows(state),
        "message": message,
        "state_file": str(state.get("state_file") or ""),
        "requirement_history_file": str(state.get("requirement_history_file") or ""),
    }


def _format_expert_rows(state: dict[str, Any]) -> str:
    counts = _expert_state_counts(state)
    status = str(state.get("status") or "active").upper()
    lines = [
        f"CHECKLISTS - {status} - {counts['verified']}/{counts['total']} VERIFIED - "
        f"{counts['done']} AWAITING REVIEW"
    ]
    marker = {
        EXPERT_MODE_REQUIREMENT_NOT_STARTED: "○",
        EXPERT_MODE_REQUIREMENT_IN_PROGRESS: "…",
        EXPERT_MODE_REQUIREMENT_DONE: "✓",
        EXPERT_MODE_REQUIREMENT_VERIFIED: "✓✓",
    }
    for item in state.get("requirements") or []:
        item_status = str(item.get("status") or "")
        lines.append(f"{marker.get(item_status, ' ')} {item.get('id')}  {item.get('requirement')}")
        progress = str(item.get("progress") or "").strip()
        next_step = str(item.get("next_step") or "").strip()
        review_summary = str(item.get("review_summary") or "").strip()
        if progress:
            lines.append(f"   Progress: {progress}")
        if review_summary and review_summary != progress:
            lines.append(f"   Review: {review_summary}")
        if next_step:
            lines.append(f"   Next: {next_step}")
    return "\n".join(lines)


def _expert_rows_from_state(state: dict[str, Any] | None) -> list[dict[str, Any]]:
    if not state:
        return []
    rows: list[dict[str, Any]] = []
    markers = {
        EXPERT_MODE_REQUIREMENT_NOT_STARTED: "",
        EXPERT_MODE_REQUIREMENT_IN_PROGRESS: "…",
        EXPERT_MODE_REQUIREMENT_DONE: "✓",
        EXPERT_MODE_REQUIREMENT_VERIFIED: "✓✓",
    }
    labels = {
        EXPERT_MODE_REQUIREMENT_NOT_STARTED: "Not started",
        EXPERT_MODE_REQUIREMENT_IN_PROGRESS: "In progress",
        EXPERT_MODE_REQUIREMENT_DONE: "Done",
        EXPERT_MODE_REQUIREMENT_VERIFIED: "Verified",
    }
    for item in state.get("requirements") or []:
        item_status = str(item.get("status") or EXPERT_MODE_REQUIREMENT_NOT_STARTED)
        progress = str(item.get("progress") or "").strip()
        next_step = str(item.get("next_step") or "").strip()
        review = str(item.get("review_summary") or "").strip()
        detail_parts = []
        if progress:
            detail_parts.append(progress)
        if review and review != progress:
            detail_parts.append("Review: " + review)
        if next_step:
            detail_parts.append("Next: " + next_step)
        rows.append({
            "id": str(item.get("id") or ""),
            "requirement": str(item.get("requirement") or item.get("text") or ""),
            "text": str(item.get("requirement") or item.get("text") or ""),
            "status": item_status,
            "state": item_status,
            "status_label": labels[item_status],
            "marker": markers[item_status],
            "complete": item_status in {EXPERT_MODE_REQUIREMENT_DONE, EXPERT_MODE_REQUIREMENT_VERIFIED},
            "incomplete": item_status in {EXPERT_MODE_REQUIREMENT_NOT_STARTED, EXPERT_MODE_REQUIREMENT_IN_PROGRESS},
            "done": item_status in {EXPERT_MODE_REQUIREMENT_DONE, EXPERT_MODE_REQUIREMENT_VERIFIED},
            "not_started": item_status == EXPERT_MODE_REQUIREMENT_NOT_STARTED,
            "in_progress": item_status == EXPERT_MODE_REQUIREMENT_IN_PROGRESS,
            "verified": item_status == EXPERT_MODE_REQUIREMENT_VERIFIED,
            "progress": progress,
            "summary": " · ".join(detail_parts),
            "next_step": next_step,
            "review_summary": review,
            "review_cycle": int(item.get("last_review_cycle") or 0),
        })
    return rows


def _incomplete_expert_items(state: dict[str, Any]) -> list[dict[str, Any]]:
    return [item for item in state.get("requirements") or []
            if str(item.get("status") or "") in {
                EXPERT_MODE_REQUIREMENT_NOT_STARTED,
                EXPERT_MODE_REQUIREMENT_IN_PROGRESS,
            }]


def _expert_ready_for_review(state: dict[str, Any]) -> bool:
    requirements = list(state.get("requirements") or [])
    return bool(requirements) and all(
        str(item.get("status") or "") in {
            EXPERT_MODE_REQUIREMENT_DONE,
            EXPERT_MODE_REQUIREMENT_VERIFIED,
        }
        for item in requirements
    )


def _next_actionable_requirement(state: dict[str, Any]) -> dict[str, Any] | None:
    for item in state.get("requirements") or []:
        if str(item.get("status") or "") == EXPERT_MODE_REQUIREMENT_IN_PROGRESS and str(item.get("next_step") or "").strip():
            return item
    for item in state.get("requirements") or []:
        if str(item.get("status") or "") == EXPERT_MODE_REQUIREMENT_NOT_STARTED:
            return item
    return None


def _enter_expert_task(self: Any, requirements: Any, *args: Any, **kwargs: Any) -> dict[str, Any]:
    if isinstance(requirements, dict):
        requirements = requirements.get("requirements")
    if not isinstance(requirements, list) or not (1 <= len(requirements) <= 100):
        raise ValueError("expert_mode_enter requires 1-100 concise outcome-focused requirements")
    texts: list[str] = []
    for value in requirements:
        if isinstance(value, dict):
            value = value.get("requirement") or value.get("text")
        text = str(value or "").strip()
        if not text:
            raise ValueError("Checklist requirements cannot be empty")
        texts.append(text)
    path = _expert_state_file(self)
    with _expert_state_path_lock(path):
        if path.exists():
            prior = _load_expert_state(self)
            if prior and str(prior.get("status") or "") == "succeeded":
                stamp = re.sub(r"[^0-9]", "", _checklist_utc_now())[:14]
                retired = path.with_name(f"retired_{path.stem}_{stamp}_{prior.get('run_id','run')}.json")
                os.replace(path, retired)
            elif prior and str(prior.get("status") or "") == "active":
                raise ValueError("Checklist is already active for this Task")
        now = _checklist_utc_now()
        state = {
            "schema": "expert_mode_state.v303",
            "owner_kind": str(_expert_owner_value(self, "owner_kind", default="chat")),
            "chat_id": str(_expert_owner_value(self, "chat_id", "source_chat_id")),
            "agent_id": str(_expert_owner_value(self, "agent_id")),
            "task_run_id": int(_expert_owner_value(self, "task_run_id", "agent_task_run_id", default=0) or 0),
            "run_id": uuid.uuid4().hex,
            "status": "active",
            "created_at": now,
            "updated_at": now,
            "completed_at": "",
            "review_cycle": 0,
            "review_status": "idle",
            "review_requested": False,
            "review_in_progress": False,
            "review_feedback_pending": False,
            "review_passed_pending": False,
            "review_passed_prompt_sent": False,
            "review_error": "",
            "reviews": [],
            "requirements": [
                {
                    "id": f"R{index}",
                    "requirement": text,
                    "text": text,
                    "status": EXPERT_MODE_REQUIREMENT_NOT_STARTED,
                    "state": EXPERT_MODE_REQUIREMENT_NOT_STARTED,
                    "progress": "",
                    "summary": "",
                    "next_step": "",
                    "implementer_summary": "",
                    "review_summary": "",
                    "updated_at": now,
                    "verified_at": "",
                    "last_actor": "velox",
                    "last_review_cycle": 0,
                    "complete": False,
                    "resolved": False,
                    "resolution": "",
                    "resolved_at": "",
                }
                for index, text in enumerate(texts, 1)
            ],
        }
        state["state_file"] = str(path)
        state = _save_expert_state(self, state)
        for item in state["requirements"]:
            _append_expert_history(
                self, state, actor="velox", requirement_id=item["id"], old_state="",
                new_state=EXPERT_MODE_REQUIREMENT_NOT_STARTED, event="requirement_created",
            )
        state = _save_expert_state(self, state)
        return state


def _extract_requirement_updates(value: Any, args: tuple[Any, ...], kwargs: dict[str, Any]) -> list[dict[str, Any]]:
    candidate = kwargs.get("updates")
    if candidate is None and isinstance(value, dict):
        candidate = value.get("updates", value)
    elif candidate is None:
        candidate = value
    if candidate is None:
        for item in args:
            if isinstance(item, list):
                candidate = item
                break
            if isinstance(item, dict) and "updates" in item:
                candidate = item["updates"]
                break
    if isinstance(candidate, dict):
        candidate = candidate.get("updates") if "updates" in candidate else [candidate]
    if not isinstance(candidate, list) or not candidate:
        raise ValueError("expert_mode_requirement_update requires one or more updates")
    return candidate


def _update_expert_task(self: Any, updates: Any = None, *args: Any, **kwargs: Any) -> dict[str, Any]:
    values = _extract_requirement_updates(updates, args, kwargs)
    path = _expert_state_file(self)
    with _expert_state_path_lock(path):
        state = _load_expert_state(self, required=True)
        assert state is not None
        if str(state.get("status") or "") != "active":
            raise ValueError("Checklist is no longer active")
        by_id = {str(item.get("id")): item for item in state["requirements"]}
        seen: set[str] = set()
        now = _checklist_utc_now()
        for update in values:
            if not isinstance(update, dict):
                raise ValueError("Each requirement update must be an object")
            allowed_keys = {"requirement_id", "status", "progress", "next_step"}
            if set(update) != allowed_keys:
                missing = sorted(allowed_keys - set(update))
                extra = sorted(set(update) - allowed_keys)
                details = []
                if missing:
                    details.append("missing " + ", ".join(missing))
                if extra:
                    details.append("unexpected " + ", ".join(extra))
                raise ValueError("Each requirement update must be exactly {requirement_id, status, progress, next_step}: " + "; ".join(details))
            requirement_id = str(update.get("requirement_id") or "").strip().upper()
            if requirement_id in seen:
                raise ValueError(f"Duplicate update for {requirement_id}")
            seen.add(requirement_id)
            if requirement_id not in by_id:
                raise ValueError(f"Unknown Checklist requirement {requirement_id!r}")
            requested = str(update.get("status") or "").strip().lower()
            if requested == EXPERT_MODE_REQUIREMENT_VERIFIED:
                raise ValueError("Only the independent Checklist reviewer may set verified")
            if requested not in EXPERT_MODE_IMPLEMENTER_STATES:
                raise ValueError(
                    "Implementer requirement status must be exactly not_started, in_progress, or done"
                )
            item = by_id[requirement_id]
            old = str(item.get("status") or EXPERT_MODE_REQUIREMENT_NOT_STARTED)
            if old == EXPERT_MODE_REQUIREMENT_VERIFIED:
                raise ValueError(f"{requirement_id} is reviewer-verified and cannot be changed by the implementer")
            progress = str(update.get("progress") or "").strip()
            next_step = str(update.get("next_step") or "").strip()
            allowed = {
                EXPERT_MODE_REQUIREMENT_NOT_STARTED: {
                    EXPERT_MODE_REQUIREMENT_NOT_STARTED,
                    EXPERT_MODE_REQUIREMENT_IN_PROGRESS,
                    EXPERT_MODE_REQUIREMENT_DONE,
                },
                EXPERT_MODE_REQUIREMENT_IN_PROGRESS: {
                    EXPERT_MODE_REQUIREMENT_IN_PROGRESS,
                    EXPERT_MODE_REQUIREMENT_DONE,
                },
                EXPERT_MODE_REQUIREMENT_DONE: {
                    EXPERT_MODE_REQUIREMENT_DONE,
                    EXPERT_MODE_REQUIREMENT_IN_PROGRESS,
                },
            }
            if requested not in allowed.get(old, set()):
                raise ValueError(f"Invalid implementer transition {requirement_id}: {old} -> {requested}")
            if requested == EXPERT_MODE_REQUIREMENT_NOT_STARTED:
                if progress or next_step:
                    raise ValueError(f"{requirement_id} not_started requires empty progress and next_step")
            elif requested == EXPERT_MODE_REQUIREMENT_IN_PROGRESS:
                if not progress:
                    raise ValueError(f"{requirement_id} in_progress requires a concise factual progress summary")
                if not next_step:
                    raise ValueError(f"{requirement_id} in_progress requires one concrete next_step")
            elif requested == EXPERT_MODE_REQUIREMENT_DONE:
                if not progress:
                    raise ValueError(f"{requirement_id} done requires a completion and observed-validation summary")
                if next_step:
                    raise ValueError(f"{requirement_id} done requires an empty next_step")
                if old == EXPERT_MODE_REQUIREMENT_DONE and progress != str(item.get("progress") or ""):
                    raise ValueError(f"{requirement_id} is already done; reopen it to in_progress before replacing its completion summary")
            item["status"] = requested
            item["state"] = requested
            item["progress"] = progress
            item["summary"] = progress
            item["next_step"] = next_step
            item["last_actor"] = "implementer"
            item["updated_at"] = now
            item["complete"] = requested == EXPERT_MODE_REQUIREMENT_DONE
            item["resolved"] = item["complete"]
            item["resolution"] = progress
            item["resolved_at"] = now if item["complete"] else ""
            if requested == EXPERT_MODE_REQUIREMENT_DONE:
                item["implementer_summary"] = progress
                item["review_summary"] = ""
                item["verified_at"] = ""
            elif requested == EXPERT_MODE_REQUIREMENT_IN_PROGRESS:
                item["review_summary"] = ""
                item["verified_at"] = ""
            _append_expert_history(
                self, state, actor="implementer", requirement_id=requirement_id,
                old_state=old, new_state=requested, progress=progress, next_step=next_step,
                review_cycle=int(state.get("review_cycle") or 0),
            )
        state["review_requested"] = _expert_ready_for_review(state)
        state["review_status"] = "pending" if state["review_requested"] else "idle"
        state["review_error"] = ""
        state = _save_expert_state(self, state)
        return state


def _exit_expert_task(self: Any, *args: Any, **kwargs: Any) -> dict[str, Any]:
    """Return raw durable state; ToolRegistry owns the model-facing result envelope."""
    del args, kwargs
    state = _load_expert_state(self, required=True)
    assert state is not None
    if str(state.get("status") or "") != EXPERT_MODE_STATUS_ACTIVE:
        raise ExpertModeStateError("Checklist is not active for this Task")
    unfinished = _incomplete_expert_items(state)
    if unfinished:
        lines = [f"Checklist cannot exit while {len(unfinished)} requirement(s) still need implementation:"]
        for item in unfinished:
            lines.append(f"- {item['id']}: {item['requirement']}")
            if item.get("progress"):
                lines.append(f"  Progress: {item['progress']}")
            if item.get("next_step"):
                lines.append(f"  Next: {item['next_step']}")
        lines.append("Continue execution now using the next concrete step. Do not produce a final report.")
        raise ExpertModeStateError("\n".join(lines))
    # All done/verified enters the Velox-owned independent review path. Even an
    # all-verified checklist remains active until the all-pass result has been
    # delivered once to the original implementer and finalized at the next stop.
    state["review_requested"] = True
    if not bool(state.get("review_passed_pending")):
        state["review_status"] = "pending"
    state["last_continuation_key"] = ""
    return _save_expert_state(self, state)


def _expert_rows(self: Any, state: Any = None, *args: Any, **kwargs: Any) -> list[dict[str, Any]]:
    if state is None or not isinstance(state, dict):
        state = _load_expert_state(self)
    return _expert_rows_from_state(state)


def _format_expert_state(self: Any, state: Any = None, *args: Any, **kwargs: Any) -> str:
    if state is None or not isinstance(state, dict):
        state = _load_expert_state(self)
    return _format_expert_rows(state) if state else "Checklist is not active for this Task."


def _expert_progress_snapshot(self: Any, state: Any = None, *args: Any, **kwargs: Any) -> str:
    if state is None or not isinstance(state, dict):
        state = _load_expert_state(self)
    if not state:
        return ""
    if state.get("checklist_task_memory"):
        return str(state["checklist_task_memory"])
    counts = _expert_state_counts(state)
    lines = [
        "CURRENT CHECKLISTS PROGRESS",
        f"{counts['verified']}/{counts['total']} requirements verified; "
        f"{counts['done']} awaiting review; {counts['in_progress']} in progress; "
        f"{counts['not_started']} not started.",
    ]
    for item in state.get("requirements") or []:
        status = str(item.get("status") or "")
        if status == EXPERT_MODE_REQUIREMENT_IN_PROGRESS:
            lines.append(f"- {item['id']}: {item['requirement']}")
            lines.append(f"  Progress: {item.get('progress','')}")
            lines.append(f"  Next: {item.get('next_step','')}")
        elif status == EXPERT_MODE_REQUIREMENT_NOT_STARTED:
            lines.append(f"- {item['id']}: {item['requirement']} (not started)")
        elif status == EXPERT_MODE_REQUIREMENT_DONE:
            lines.append(f"- {item['id']}: done, awaiting independent review. {item.get('progress','')}")
    return "\n".join(lines)


def _expert_task_memory_class(cls: Any, task_facts: Any, state: Any = None) -> str:
    sections = [str(task_facts or "").strip()]
    if isinstance(state, dict) and str(state.get("status") or "") == "active":
        sections.append(_expert_progress_snapshot_class(cls, state))
    body = "\n\n".join(section for section in sections if section)
    return TASK_MEMORY_HEADER + ("\n\n" + body if body else "")


def _checklist_continuation_text(state: dict[str, Any]) -> str:
    item = _next_actionable_requirement(state)
    if item is None:
        return "Implementation updates are complete. Independent Checklist Review is required before final acceptance."
    lines = [
        "CHECKLISTS - CONTINUE",
        "",
        "Execute the next concrete step for an in-progress requirement and take a concrete action now. If none is in progress, begin the next actionable not-started requirement. After the action, update its progress and next step, or mark it done when the complete requested outcome has actually been satisfied. Do not reassess whether the overall task is too large or realistic. A claimed corruption/race/stale-artifact/tool blocker is only a hypothesis until direct current tool evidence demonstrates it; reproduce the exact failing command and inspect its literal syntax/paths before treating it as a blocker. If a clean rerun succeeds, continue rather than preserving the discarded hypothesis.",
        "",
        f"NEXT: {item['id']} - {item['requirement']}",
    ]
    if str(item.get("status") or "") == EXPERT_MODE_REQUIREMENT_IN_PROGRESS:
        lines.extend([
            f"Current progress: {item.get('progress','')}",
            f"Concrete next step: {item.get('next_step','')}",
        ])
    else:
        lines.append("State: not started. Begin one concrete implementation or validation action now.")
    return "\n".join(lines)


def _expert_continuation_prompt(self: Any, state: Any = None, *args: Any, **kwargs: Any) -> str:
    if state is None or not isinstance(state, dict):
        state = _load_expert_state(self)
    if not state or str(state.get("status") or "") != "active":
        return ""
    if bool(state.get("review_passed_pending")):
        state["review_passed_prompt_sent"] = True
        state = _save_expert_state(self, state)
        return (
            "CHECKLIST REVIEW PASSED\n\n"
            "The independent reviewer verified every requirement against the current implementation. "
            "Provide the concise final result now."
        )
    if bool(state.get("review_feedback_pending")):
        failed = [item for item in state.get("requirements") or []
                  if str(item.get("status") or "") == EXPERT_MODE_REQUIREMENT_IN_PROGRESS
                  and str(item.get("last_actor") or "") == "reviewer"]
        lines = [
            "CHECKLIST REVIEW FOUND REMAINING WORK",
            "",
            "The independent reviewer reopened the following requirements. Continue implementation using the reviewer next steps below. Treat reviewer findings as current acceptance feedback.",
        ]
        for item in failed:
            lines.extend([
                f"- {item['id']}: {item['requirement']}",
                f"  Reviewer: {item.get('progress','')}",
                f"  Next: {item.get('next_step','')}",
            ])
        state["review_feedback_pending"] = False
        _save_expert_state(self, state)
        return "\n".join(lines)
    if str(state.get("review_status") or "") == "error":
        diagnostic = str(state.get("review_error") or "Independent review did not complete.").strip()
        return (
            "CHECKLIST REVIEW RETRY REQUIRED\n\n"
            f"The independent review did not complete because of a Velox/runtime error: {diagnostic}\n"
            "Do not treat this as verification or requirement failure. The implementation state is unchanged. "
            "Confirm the current Checklist is still ready, then explicitly call verify_checklist again; Velox will not automatically loop the failed reviewer."
        )
    return _checklist_continuation_text(state)


def _expert_history(self: Any, *args: Any, **kwargs: Any) -> list[dict[str, Any]]:
    path = _expert_state_file(self)
    candidates: list[Path] = []
    if path.exists():
        candidates.append(path)
    candidates.extend(path.parent.glob("retired_*expert_mode*.json"))
    reports: list[dict[str, Any]] = []
    for candidate in candidates:
        try:
            state = _validate_expert_state(json.loads(candidate.read_text(encoding="utf-8")))
        except Exception:
            continue
        state["state_file"] = str(candidate)
        state["current"] = candidate == path
        state["rows"] = _expert_rows_from_state(state)
        state["label"] = (
            ("Current" if candidate == path else "History")
            + " · " + str(state.get("created_at") or "")
            + f" · Review {int(state.get('review_cycle') or 0)}"
            + f" · {int(state.get('verified_count') or 0)}/{int(state.get('requirement_count') or 0)} verified"
        )
        history_path = _expert_history_path(self, state)
        state["requirement_history_file"] = str(history_path)
        if history_path.exists():
            events: list[dict[str, Any]] = []
            for line in history_path.read_text(encoding="utf-8", errors="replace").splitlines():
                try:
                    events.append(json.loads(line))
                except Exception:
                    continue
            state["requirement_history"] = events
            reopenings = [event for event in events
                          if event.get("actor") == "reviewer"
                          and event.get("new_state") == EXPERT_MODE_REQUIREMENT_IN_PROGRESS]
            if reopenings:
                state["history_note"] = f"{len(reopenings)} reviewer reopening(s) across review cycles."
        reports.append(state)
    reports.sort(key=lambda item: str(item.get("updated_at") or item.get("created_at") or ""), reverse=True)
    return reports


def _validate_expert_method(self: Any, raw: Any, *args: Any, **kwargs: Any) -> dict[str, Any]:
    return _validate_expert_state(raw)


# Capture the predecessor methods before installing the narrow state model.
_EXPERT_STORE_BASE_METHODS = {
    name: getattr(ExpertModeStore, name, None)
    for name in (
        "enter", "update", "exit", "rows", "format", "progress_snapshot",
        "task_memory_content", "continuation_prompt", "history", "_validate",
    )
}

def _normalize_expert_updates_class(cls: Any, updates: Any) -> list[dict[str, Any]]:
    del cls
    values = _extract_requirement_updates(updates, (), {})
    normalized: list[dict[str, Any]] = []
    for value in values:
        if not isinstance(value, dict):
            raise ValueError("Each requirement update must be an object")
        normalized.append(dict(value))
    return normalized

def _format_expert_state_class(cls: Any, state: Any, *, include_instruction: bool = False) -> str:
    del cls
    if not isinstance(state, dict):
        return "Checklist is not active for this Task."
    text = _format_expert_rows(state)
    if include_instruction and str(state.get("status") or "") == "active":
        item = _next_actionable_requirement(state)
        if item is not None:
            text += "\n\n" + _checklist_continuation_text(state)
        elif _expert_ready_for_review(state):
            text += "\n\nImplementation is ready for independent Checklist Review."
    return text

def _expert_progress_snapshot_class(cls: Any, state: Any) -> str:
    del cls
    if not isinstance(state, dict):
        return ""
    if state.get("checklist_task_memory"):
        return str(state["checklist_task_memory"])
    counts = _expert_state_counts(state)
    lines = [
        "CURRENT CHECKLISTS PROGRESS",
        f"{counts['verified']}/{counts['total']} requirements verified; "
        f"{counts['done']} awaiting review; {counts['in_progress']} in progress; "
        f"{counts['not_started']} not started.",
    ]
    for item in state.get("requirements") or []:
        status = str(item.get("status") or "")
        if status == EXPERT_MODE_REQUIREMENT_IN_PROGRESS:
            lines.extend([
                f"- {item['id']}: {item['requirement']}",
                f"  Progress: {item.get('progress','')}",
                f"  Next: {item.get('next_step','')}",
            ])
        elif status == EXPERT_MODE_REQUIREMENT_NOT_STARTED:
            lines.append(f"- {item['id']}: {item['requirement']} (not started)")
        elif status == EXPERT_MODE_REQUIREMENT_DONE:
            lines.append(f"- {item['id']}: done, awaiting independent review. {item.get('progress','')}")
    return "\n".join(lines)

ExpertModeStore.enter = _enter_expert_task
ExpertModeStore.update = _update_expert_task
ExpertModeStore._normalize_updates = classmethod(_normalize_expert_updates_class)
ExpertModeStore.exit = _exit_expert_task
ExpertModeStore.rows = staticmethod(_expert_rows_from_state)
ExpertModeStore.format = classmethod(_format_expert_state_class)
ExpertModeStore.progress_snapshot = classmethod(_expert_progress_snapshot_class)
ExpertModeStore.task_memory_content = classmethod(_expert_task_memory_class)
ExpertModeStore.continuation_prompt = _expert_continuation_prompt
ExpertModeStore.history = _expert_history


def _load_expert_state_public(self: Any, *args: Any, **kwargs: Any) -> dict[str, Any] | None:
    active_only = bool(kwargs.get("active_only", False))
    if args and isinstance(args[0], bool):
        active_only = bool(args[0])
    state = _load_expert_state(self)
    if active_only and (not state or str(state.get("status") or "") != EXPERT_MODE_STATUS_ACTIVE):
        return None
    return state

def _expert_status_public(self: Any, *args: Any, **kwargs: Any) -> dict[str, Any]:
    return _expert_state_result(_load_expert_state(self), action="status")

def _archive_completed_expert_state(self: Any, *args: Any, **kwargs: Any) -> Any:
    path = _expert_state_file(self)
    with _expert_state_path_lock(path):
        state = _load_expert_state(self)
        if not state or str(state.get("status") or "") != "succeeded":
            return None
        stamp = re.sub(r"[^0-9]", "", str(state.get("completed_at") or state.get("updated_at") or _checklist_utc_now()))[:14]
        retired = path.with_name(f"retired_{path.stem}_{stamp}_{state.get('run_id','run')}.json")
        os.replace(path, retired)
        return str(retired)

for _load_name in ("load", "current", "current_state", "get_state"):
    if hasattr(ExpertModeStore, _load_name):
        setattr(ExpertModeStore, _load_name, _load_expert_state_public)
if hasattr(ExpertModeStore, "status"):
    ExpertModeStore.status = _expert_status_public
if hasattr(ExpertModeStore, "archive_succeeded"):
    ExpertModeStore.archive_succeeded = _archive_completed_expert_state
if hasattr(ExpertModeStore, "_validate"):
    ExpertModeStore._validate = _validate_expert_method


IMPLEMENTER_CHECKLIST_GUIDANCE = (
    "Choose Checklist for complex work that benefits from a durable progress checklist of up to 100 concise outcome-focused requirements covering every requested deliverable, material constraint, validation or non-regression condition, and final output; use it only when warranted, and genuinely trivial work should skip it. Before entering, reread the complete user request or assigned task and relevant supplied material. "
    "Checklist is a persistent progress checklist and implementation checklist. Each requirement describes a stable requested outcome; ordinary implementation actions belong in the requirement's one-time fixed sub-item plan; evolving details belong in progress comments. Keep requirement IDs, order, and wording stable. "
    "Keep taking concrete actions while any requirement is incomplete. Use expert_mode_requirement_update after meaningful milestones and when materially advancing a requirement; while working on it, keep it in progress and maintain one concrete next implementation or validation step. "
    "After completing that step, either mark the requirement done if the complete outcome is satisfied, or replace it with the next concrete step. Continue while any requirement is not done or verified. "
    "For behavioral requirements, source-code presence, successful compilation, artifact existence, or process exit code alone is not validation. Exercise the intended production path and observe the required behavior. For visual behavior, inspect the produced pixels. "
    "Mark a requirement done only when the complete requested outcome and its material validation are satisfied. The done summary must state the strongest concrete validation actually performed and its observed successful result; implementation descriptions are not sufficient by themselves. "
    "Batch done updates only when the same concrete validation genuinely supports every item in the batch. Missing, unfinished, partially implemented, unverified, difficult, or currently blocked work remains incomplete work. "
    "Later concrete contradictory evidence may reopen a requirement marked done; return it to in progress and state the concrete next step needed to resolve the contradiction. "
    "Before expert_mode_exit, reconcile every done item against the latest tool, runtime, test, integration, and visual evidence. When all requirements are done or verified, call expert_mode_exit to begin independent review. The independent reviewer owns verified; the implementer cannot set or modify reviewer verification."
)
CHECKLIST_UPDATE_GUIDANCE = (
    "Use expert_mode_requirement_update after meaningful milestones and when materially advancing incomplete work. not_started records no meaningful work; in_progress requires factual progress and one concrete next_step; "
    "done means the implementer has completed and materially validated the whole outcome but still awaits independent review. Mark requirements done as their concrete validation closes them. "
    "Do not mass-mark unrelated behavioral requirements done from general project confidence."
)

# Replace the assembled shared guidance without adding capacity/session coaching.
if "ContextAssembler" in globals():
    ContextAssembler.EXPERT_MODE_GUIDANCE = IMPLEMENTER_CHECKLIST_GUIDANCE
    if hasattr(ContextAssembler, "REQUIREMENTS_GUIDANCE"):
        ContextAssembler.REQUIREMENTS_GUIDANCE = (
            "For complex work, register one concise outcome-focused Checklist checklist covering the complete requested result, with 1-100 stable R-items. "
            "Keep IDs, order, and wording stable. Ordinary implementation steps belong in the mutable working plan. " + CHECKLIST_UPDATE_GUIDANCE
        )


EXPERT_MODE_REVIEW_AGENT_CONTEXT_MARKER = "VELOX_INTERNAL_CHECKLIST_REVIEW_V279"

# The reviewer may inspect and execute, but it cannot use direct Velox mutation or
# implementation-delegation tools. Shell/Python/terminal execution remains available
# for tests and runtime validation; the reviewer prompt forbids using those paths to
# edit the project.
EXPERT_MODE_REVIEWER_READ_ONLY_TOOL_DENYLIST = frozenset({
    *EXPERT_MODE_TOOL_NAMES,
    "fs_delete_lines", "fs_insert_at_line", "fs_write", "fs_append", "fs_edit",
    "items_create", "items_edit", "items_schedule", "items_move_to_backlog",
    "items_link_event", "items_unlink_event", "items_set_status", "items_set_priority",
    "items_attach", "items_remove_attachment", "items_add_context_link",
    "items_remove_context_link", "items_link_agent", "items_unlink_agent",
    "week_chat_get", "drive_download", "web_download_file", "web_fetch_to_pdf",
    "create_context_doc", "update_context_doc", "delete_context_doc",
    "scheduled_task_create_once", "scheduled_task_create_recurring", "scheduled_task_delete",
    "agents_start", "agents_pause", "agents_resume", "agents_stop",
    "comfy_text_to_image", "comfy_image_to_image",
    "meshy_text_to_3d", "meshy_image_to_3d", "meshy_ai_texturing", "meshy_rig", "meshy_animate",
})


def _is_reviewer_agent(agent: Any) -> bool:
    if not isinstance(agent, dict):
        return False
    context = str(agent.get("context") or "")
    return context.startswith(EXPERT_MODE_REVIEW_AGENT_CONTEXT_MARKER)


def _reviewer_agent_from_id(storage: Any, agent_id: Any) -> dict[str, Any] | None:
    resolved = str(agent_id or "").strip()
    if not resolved:
        return None
    try:
        agent = AgentStore(storage).load_agent(resolved)
    except Exception:
        return None
    return agent if _is_reviewer_agent(agent) else None


def _blocked_role_tool_result(name: str) -> dict[str, Any]:
    return {
        "ok": False,
        "error": f"Checklist Reviewer is read-only and cannot execute mutating tool {name!r}.",
        "reviewer_read_only": True,
    }


# Reviewer tool filtering and execution enforcement are integrated at the existing
# AgentRuntime schema boundary and ToolRegistry execution entrypoint above. Keeping
# those methods intact preserves normal diagnostics, progress, cancellation, and
# source-level regression coverage.


REVIEWER_SYSTEM_PROMPT = """You are the independent Checklist acceptance reviewer. You are a fresh reviewer context, not the implementer. Evaluate the current final implementation against every requirement in stable order, including items that passed an earlier review, because later changes can regress them.

Use the available read-only inspection and execution tools whenever they materially improve confidence. You may search/read files and reports, run tests and generated applications, inspect images, and analyze runtime behavior. Do not edit project files, implement fixes, or delegate implementation.

When acceptance depends on current external facts, APIs, releases, public documentation, or other time-sensitive claims, use web_search rather than relying on memory. Prefer current primary sources. If a material page is empty, blocked, interstitial-only, or JavaScript-dependent through normal web fetch, try browser_run_headless on the same URL before treating it as unavailable. Velox returns context-heavy webpage results one page at a time, so fetch additional pages sequentially as needed.

Start from the actual final artifact, not the claims. Identify the deliverable(s) and inspect them through the way a user would consume them before treating source code or implementer history as acceptance evidence. Launch applications/games and exercise representative paths; open the actual final web page; open or render produced documents/reports; inspect final images, 3D output, and other visual artifacts.

When visual output is material and the available tools can capture it, inspect at least one current representative final screenshot/render/page. Before checking expected requirements, perform an expectation-independent defect sweep for anything obviously broken. Explicitly consider orientation/uprightness, rotation/mirroring, malformed silhouettes, clipping, missing/duplicated geometry, textures/UVs/atlas cells, depth/z-order, camera framing, and UI/HUD/text readability as relevant. Prefer image_analyze_3D_scene for 3D/game captures and image_analyze_ui for UI/HUD/document-layout captures; use generic image_analyze when neither specialist fits. Multiple captures should cover materially different risks; near-identical screenshots are not independent proof.

A pass requires sufficient current, independently checked evidence for every material clause. Code presence, compilation, artifact existence, file/report existence, implementer claims, or process exit code alone do not establish behavioral acceptance. Exercise the intended production path and observe the required behavior. A feature does not pass merely because it exists or telemetry/state is correct: an obvious material defect in a required artifact or feature is enough to fail the most directly related item even if that exact defect was not spelled out. An upside-down, mirrored, or otherwise visibly malformed required sprite/model is a failure of that rendered feature, not a pass for presence. If pixels conflict with source, tests, DOM, snapshots, or telemetry, investigate and gather focused/new evidence rather than dismissing the pixels. For explicitly named demos or artifacts, verify the actual named artifact. If named feature demos unexpectedly show substantially identical/default output, investigate source file -> build target -> executable -> runtime showcase -> capture path before accepting them. On a later review cycle after a failure, require fresh post-fix execution/inspection of the failed behavior; stale pre-fix screenshots or reports are not acceptance evidence.

Return exactly one JSON object with this shape:
{"verdicts":[{"requirement_id":"R1","verdict":"pass|fail","summary":"strongest observed acceptance result or concrete gap","next_step":"one practical action for the implementer when failed; empty when passed"}]}
Include every requirement exactly once and in the supplied order. Do not include markdown around the JSON. After the JSON object, emit the normal Agent terminal control as the final non-empty line: $$AGENT_PROGRESS: {"message":"Independent Checklist Review complete","percent":100}. A runtime/tool limitation is not a pass; report the affected requirement as fail only when the available current implementation/evidence does not demonstrate acceptance. For every FAIL, next_step MUST be non-empty and name one concrete repair, research, or validation action that directly addresses the summary; never omit it. Remain focused on acceptance rather than redesign."""


def _sanitize_review_handoff_text(text: str) -> str:
    lines: list[str] = []
    for raw in redact_durable_secret_text(text).splitlines():
        line = raw.strip()
        if not line:
            continue
        lower = line.lower()
        if lower.startswith("<think") or lower.startswith("</think"):
            continue
        if any(fragment in lower for fragment in (
            "i think", "i believe", "i feel", "i'm confident", "i am confident",
            "context budget", "token budget", "remaining context", "single session",
            "sunk cost", "this is huge", "this is enormous",
        )):
            continue
        lines.append(line)
    return "\n".join(lines)


def _collect_message_sequence(runtime: Any, bound: dict[str, Any]) -> list[dict[str, Any]]:
    """Export the durable implementation history for the actual owner."""
    agent_id = str(bound.get("agent_id") or "").strip()
    chat_id = str(bound.get("chat_id") or "").strip()
    agent_store = getattr(runtime, "agents", None)
    if agent_id and agent_store is not None:
        load_transcript = getattr(agent_store, "load_transcript", None)
        if callable(load_transcript):
            try:
                events = load_transcript(agent_id)
            except Exception:
                events = None
            if isinstance(events, list) and all(isinstance(item, dict) for item in events):
                return redact_durable_secrets(_review_context(_clone_review_json(events)))
    chat_store = getattr(runtime, "chats", None)
    if chat_id and chat_store is not None:
        load_turns = getattr(chat_store, "load_turns", None)
        if callable(load_turns):
            try:
                turns = load_turns(APP_SCOPE_ID, chat_id)
            except TypeError:
                try:
                    turns = load_turns(chat_id)
                except Exception:
                    turns = None
            except Exception:
                turns = None
            if isinstance(turns, list) and all(isinstance(item, dict) for item in turns):
                return redact_durable_secrets(_review_context(_clone_review_json(turns)))
    for key in ("messages", "conversation", "turns"):
        value = bound.get(key)
        if isinstance(value, list) and all(isinstance(item, dict) for item in value):
            return redact_durable_secrets(_review_context(_clone_review_json(value)))
    return []

def _original_expert_task(messages: list[dict[str, Any]], fallback: str = "") -> str:
    """Return the first genuine user-authored task, never a generated continuation."""
    for message in messages:
        if str(message.get("role") or "") != "user":
            continue
        stats = message.get("stats") if isinstance(message.get("stats"), dict) else {}
        if bool(message.get("hidden_from_ui")) or bool(stats.get("expert_mode_prompt")):
            continue
        content = message.get("content") if "content" in message else message.get("text")
        if isinstance(content, str):
            text = content.strip()
        elif isinstance(content, list):
            parts = [str(item.get("text") or "") for item in content
                     if isinstance(item, dict) and str(item.get("type") or "") == "text"]
            text = "\n".join(parts).strip()
        else:
            text = ""
        if text and not text.startswith("CHECKLISTS -") and not text.startswith("CHECKLIST REVIEW"):
            return redact_durable_secret_text(text)
    return redact_durable_secret_text(str(fallback or "").strip())

def _review_workspace_path(runtime: Any, owner: dict[str, Any]) -> str:
    storage = getattr(runtime, "storage", None)
    paths = getattr(storage, "paths", None)
    chat_id = str(owner.get("chat_id") or "")
    if paths is not None and chat_id and hasattr(paths, "chat_workspace_dir"):
        try:
            return str(paths.chat_workspace_dir(chat_id))
        except Exception:
            pass
    return str(owner.get("workspace") or Path.cwd())


def _extract_factual_tool_lines(messages: list[dict[str, Any]], limit: int = 240) -> list[str]:
    """Extract observed tool/runtime outcomes with their provenance, not model claims."""
    facts: list[str] = []
    for message in messages:
        if not isinstance(message, dict):
            continue
        role, kind = message.get("role"), message.get("kind")
        records: list[tuple[str, Any]] = []
        if role == "tool":
            records.append(("Tool " + str(message.get("tool_call_id") or message.get("name") or "result"),
                message.get("content", message.get("text", ""))))
        if kind == "tool_result":
            records.append(("Tool result", message.get("data", {})))
        elif kind in {"failed", "cancelled"}:
            records.append(("Runtime " + str(kind), message.get("data", {})))
        for call in message.get("tool_calls", []):
            if isinstance(call, dict) and call.get("ok") is not None:
                records.append(("Tool " + str(call.get("provider_tool_call_id") or call.get("tool_call_id") or "result"),
                    {key: call[key] for key in ("tool_name", "ok", "status", "result", "error") if key in call}))
        for provenance, value in records:
            clean = _review_evidence_value(value)
            text = clean if isinstance(clean, str) else json.dumps(clean, ensure_ascii=False, default=str)
            if text.strip():
                facts.append(provenance + ": " + _compaction_bounded_excerpt(redact_durable_secret_text(text), 4000))
            if len(facts) >= limit:
                return facts
    return facts

def _make_expert_review_package(
    store: Any,
    state: dict[str, Any],
    *,
    runtime: Any,
    bound: dict[str, Any],
    cycle: int,
) -> dict[str, Any]:
    review_dir = _expert_run_dir(store, state) / f"review_{cycle:03d}"
    review_dir.mkdir(parents=True, exist_ok=True)
    messages = _collect_message_sequence(runtime, bound)
    owner = {
        "owner_kind": str(state.get("owner_kind") or "chat"),
        "chat_id": str(state.get("chat_id") or bound.get("chat_id") or ""),
        "agent_id": str(state.get("agent_id") or bound.get("agent_id") or ""),
        "task_run_id": int(state.get("task_run_id") or bound.get("task_run_id") or 0),
    }
    workspace = _review_workspace_path(runtime, owner)
    fallback_task = str(bound.get("task") or bound.get("assigned_task") or "")
    if owner["owner_kind"] == "agent" and owner["agent_id"]:
        try:
            agent_record = runtime.agents.load_agent(owner["agent_id"])
        except Exception:
            agent_record = {}
        original_task = str(agent_record.get("task") or fallback_task).strip()
    else:
        original_task = _original_expert_task(messages, fallback_task)
    context_path = review_dir / "implementer_context.json"
    live_messages = bound.get("messages") if isinstance(bound.get("messages"), list) else []
    context_payload = {
        "schema": "expert_mode_implementer_context.v303",
        "exported_at": _checklist_utc_now(),
        "owner": redact_durable_secrets(owner),
        "workspace": redact_durable_secret_text(workspace),
        "messages": messages,
        "live_model_context": _clone_review_json(live_messages),
    }
    _write_expert_state_json(context_path, context_payload)

    facts = _extract_factual_tool_lines(messages)
    lines = [
        "# Checklist Review Handoff",
        "",
        f"Schema: `{EXPERT_MODE_REVIEW_HANDOFF_SCHEMA}`",
        f"Review cycle: {cycle}",
        f"Workspace/project root: `{workspace}`",
        f"Complete implementer context export: `{context_path}`",
        "",
        "## Authoritative task",
        "",
        _sanitize_review_handoff_text(original_task) or "The authoritative task is represented by the requirements below.",
        "",
        "## Current requirements and implementer state",
        "",
    ]
    for item in state.get("requirements") or []:
        lines.append(f"### {item['id']} · {item['status']}")
        lines.append(str(item.get("requirement") or ""))
        if item.get("progress"):
            lines.append(f"Implementer record: {_sanitize_review_handoff_text(item.get('progress',''))}")
        if item.get("review_summary"):
            lines.append(f"Prior reviewer result: {_sanitize_review_handoff_text(item.get('review_summary',''))}")
        if item.get("next_step"):
            lines.append(f"Current next step: {_sanitize_review_handoff_text(item.get('next_step',''))}")
        lines.append("")
    lines.extend([
        "## Concrete tool/runtime facts available in the implementation record",
        "",
    ])
    if facts:
        lines.extend(f"- {_sanitize_review_handoff_text(fact)}" for fact in facts)
    else:
        lines.append("- No additional compact tool-result facts were extracted; inspect the complete context export and workspace directly.")
    lines.extend([
        "",
        "## Review instruction",
        "",
        "Independently inspect the current implementation and artifacts. Implementer done states are proposals, not acceptance proof.",
    ])
    handoff_path = review_dir / "review_handoff.md"
    handoff = "\n".join(lines).strip() + "\n"
    handoff_path.write_text(handoff, encoding="utf-8")
    package = {
        "review_dir": str(review_dir),
        "handoff_path": str(handoff_path),
        "context_path": str(context_path),
        "handoff": redact_durable_secret_text(handoff),
        "original_task": redact_durable_secret_text(original_task),
        "workspace": redact_durable_secret_text(workspace),
        "messages": redact_durable_secrets(messages),
        "owner": redact_durable_secrets(owner),
    }
    return package


def _build_reviewer_user_prompt(state: dict[str, Any], package: dict[str, Any], cycle: int) -> str:
    requirement_lines = []
    for item in state.get("requirements") or []:
        requirement_lines.extend([
            f"{item['id']} [{item['status']}]: {item['requirement']}",
            f"Implementer record: {item.get('progress') or '(none)'}",
            f"Prior review: {item.get('review_summary') or '(none)'}",
        ])
    return "\n".join([
        f"CHECKLIST REVIEW CYCLE {cycle}",
        "",
        "AUTHORITATIVE ORIGINAL TASK:",
        package.get("original_task") or "See the exact requirements below.",
        "",
        "EXACT CURRENT REQUIREMENTS:",
        *requirement_lines,
        "",
        f"WORKSPACE / PROJECT ROOT: {package.get('workspace')}",
        f"REVIEW HANDOFF: {package.get('handoff_path')}",
        package.get("handoff") or "",
        "",
        f"COMPLETE IMPLEMENTER TRANSCRIPT AND TOOL HISTORY: {package.get('context_path')}",
        "The complete implementer transcript and tool history is supporting material, not authoritative acceptance evidence. Search/read it when useful to locate an artifact, command, tool result, decision, diagnostic, or fact that is not present in the review handoff.",
        "",
        "Evaluate every requirement now. Your final response must contain exactly one verdict JSON object, then the required terminal $$AGENT_PROGRESS line, with no text after it.",
    ])


def _reviewer_visible_output(value: str) -> str:
    """Remove tagged draft reasoning outside JSON, preserving literal evidence strings."""
    text = normalize_known_provider_output_artifacts(str(value or ""))
    out: list[str] = []
    offset = 0
    while offset < len(text):
        tag = REASONING_TAG_RE.match(text, offset)
        if tag and not tag.group(1):
            depth = 1
            end = len(text)
            for later in REASONING_TAG_RE.finditer(text, tag.end()):
                depth += -1 if later.group(1) else 1
                if depth == 0:
                    end = later.end()
                    break
            offset = end
            continue
        if text[offset] in "{[":
            start = offset
            stack: list[str] = []
            quoted = escaped = False
            while offset < len(text):
                char = text[offset]
                offset += 1
                if quoted:
                    if escaped:
                        escaped = False
                    elif char == "\\":
                        escaped = True
                    elif char == '"':
                        quoted = False
                elif char == '"':
                    quoted = True
                elif char in "{[":
                    stack.append(char)
                elif char in "}]":
                    if not stack or (stack.pop(), char) not in (("{", "}"), ("[", "]")) or not stack:
                        break
            out.append(text[start:offset])
        else:
            out.append(text[offset])
            offset += 1
    return "".join(out).strip()


def _parse_reviewer_result(value: Any, state: dict[str, Any]) -> list[dict[str, str]]:
    """Parse exactly one structural Reviewer verdict object and validate it strictly.

    Prose and Markdown fences may surround the object, but prose is never treated
    as a verdict. Multiple verdict-bearing JSON objects are ambiguous and rejected.
    """
    verdict_payloads: list[dict[str, Any]] = []
    if isinstance(value, dict):
        verdict_payloads = [copy.deepcopy(value)] if "verdicts" in value else []
    else:
        text = _reviewer_visible_output(str(value or ""))
        def unique_keys(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
            result: dict[str, Any] = {}
            for key, item in pairs:
                if key in result:
                    raise ValueError(f"Duplicate JSON key in Reviewer verdict: {key}")
                result[key] = item
            return result
        decoder = json.JSONDecoder(object_pairs_hook=unique_keys)
        offset = 0
        while offset < len(text):
            if text[offset] not in "{[":
                offset += 1
                continue
            start = offset
            stack: list[str] = []
            quoted = False
            escaped = False
            while offset < len(text):
                char = text[offset]
                offset += 1
                if quoted:
                    if escaped:
                        escaped = False
                    elif char == "\\":
                        escaped = True
                    elif char == '"':
                        quoted = False
                    continue
                if char == '"':
                    quoted = True
                elif char in "{[":
                    stack.append(char)
                elif char in "}]":
                    if not stack or (stack.pop(), char) not in (("{", "}"), ("[", "]")):
                        break
                    if not stack:
                        break
            candidate = text[start:offset]
            try:
                loaded = decoder.decode(candidate)
            except ValueError as exc:
                if '"verdicts"' in candidate:
                    raise ValueError(f"Invalid Reviewer verdict JSON: {exc}") from exc
                continue
            if isinstance(loaded, dict) and "verdicts" in loaded:
                verdict_payloads.append(loaded)

    if not verdict_payloads:
        raise ValueError(
            "Checklist Reviewer did not return exactly one valid JSON verdict object with a verdicts array"
        )
    if len(verdict_payloads) != 1:
        raise ValueError(
            f"Checklist Reviewer returned {len(verdict_payloads)} verdict JSON objects; exactly one is required"
        )
    payload = verdict_payloads[0]
    verdicts = payload.get("verdicts")
    if not isinstance(verdicts, list):
        raise ValueError("Checklist Reviewer result requires a verdicts array")

    expected = [str(item.get("id") or "").strip() for item in state.get("requirements") or []]
    if not expected or any(not item_id for item_id in expected) or len(set(expected)) != len(expected):
        raise ValueError("Checklist Reviewer state has invalid or missing requirement IDs")

    actual: list[str] = []
    for index, item in enumerate(verdicts, start=1):
        if not isinstance(item, dict):
            raise ValueError(f"Reviewer verdict entry {index} must be a JSON object")
        if not isinstance(item.get("requirement_id"), str):
            raise ValueError(f"Reviewer verdict entry {index} requires a string requirement_id")
        requirement_id = item["requirement_id"].strip()
        if not requirement_id:
            raise ValueError(f"Reviewer verdict entry {index} is missing requirement_id")
        actual.append(requirement_id)

    duplicates = sorted({item_id for item_id in actual if actual.count(item_id) > 1})
    if duplicates:
        raise ValueError(
            "Checklist Reviewer returned duplicate requirement IDs: " + ", ".join(duplicates)
        )
    expected_set = set(expected)
    unknown = [item_id for item_id in actual if item_id not in expected_set]
    if unknown:
        raise ValueError(
            "Checklist Reviewer returned unknown requirement IDs: " + ", ".join(unknown)
        )
    actual_set = set(actual)
    missing = [item_id for item_id in expected if item_id not in actual_set]
    if missing:
        raise ValueError(
            "Checklist Reviewer omitted requirement IDs: " + ", ".join(missing)
        )
    if actual != expected:
        raise ValueError(
            "Checklist Reviewer must return every requirement exactly once in the supplied stable order"
        )

    normalized: list[dict[str, str]] = []
    for item in verdicts:
        requirement_id = str(item.get("requirement_id") or "").strip()
        verdict = str(item.get("verdict") or "").strip().lower()
        if verdict not in {"pass", "fail"}:
            raise ValueError(f"Invalid reviewer verdict {verdict!r} for {requirement_id}")
        if not isinstance(item.get("summary"), str) or not isinstance(item.get("next_step", ""), str):
            raise ValueError(f"Reviewer verdict {requirement_id} summary and next_step must be strings")
        summary = redact_durable_secret_text(item["summary"].strip())
        next_step = redact_durable_secret_text(item.get("next_step", "").strip())
        if not summary:
            raise ValueError(f"Reviewer verdict {requirement_id} requires a non-empty summary")
        if verdict == "fail" and not next_step:
            raise ValueError(
                f"Reviewer verdict {requirement_id} is fail and requires a non-empty next_step"
            )
        if verdict == "pass":
            next_step = ""
        normalized.append({
            "requirement_id": requirement_id,
            "verdict": verdict,
            "summary": summary,
            "next_step": next_step,
        })
    return normalized


def _expert_review_snapshot_signature(state: dict[str, Any]) -> tuple[tuple[str, str, str, str, str], ...]:
    """Return the implementation fields whose change makes an in-flight review stale."""
    signature: list[tuple[str, str, str, str, str]] = []
    for item in state.get("requirements") or []:
        if not isinstance(item, dict):
            continue
        signature.append((
            str(item.get("id") or ""),
            str(item.get("requirement") or item.get("text") or ""),
            str(item.get("status") or item.get("state") or ""),
            str(item.get("implementer_summary") or item.get("progress") or item.get("summary") or ""),
            str(item.get("next_step") or ""),
        ))
    return tuple(signature)


def _apply_reviewer_verdicts(
    store: Any,
    state: dict[str, Any],
    verdicts: list[dict[str, str]],
    *,
    cycle: int,
    review_record: dict[str, Any],
) -> dict[str, Any]:
    path = _expert_state_file(store)
    with _expert_state_path_lock(path):
        current = _load_expert_state(store, required=True)
        assert current is not None
        if str(current.get("run_id") or "") != str(state.get("run_id") or ""):
            raise RuntimeError("Checklist run changed while independent review was active")
        if _expert_review_snapshot_signature(current) != _expert_review_snapshot_signature(state):
            raise RuntimeError(
                "Checklist changed while independent review was active; the stale reviewer result was discarded"
            )
        by_id = {str(item.get("id")): item for item in current["requirements"]}
        any_fail = False
        now = _checklist_utc_now()
        for verdict in verdicts:
            item = by_id[verdict["requirement_id"]]
            old = str(item.get("status") or "")
            if verdict["verdict"] == "pass":
                new = EXPERT_MODE_REQUIREMENT_VERIFIED
                item["status"] = new
                item["state"] = new
                item["review_summary"] = verdict["summary"]
                item["progress"] = item.get("implementer_summary") or item.get("progress") or verdict["summary"]
                item["summary"] = item["progress"]
                item["next_step"] = ""
                item["verified_at"] = now
            else:
                any_fail = True
                new = EXPERT_MODE_REQUIREMENT_IN_PROGRESS
                item["status"] = new
                item["state"] = new
                item["progress"] = verdict["summary"]
                item["summary"] = verdict["summary"]
                item["review_summary"] = verdict["summary"]
                item["next_step"] = verdict["next_step"]
                item["verified_at"] = ""
            item["last_actor"] = "reviewer"
            item["complete"] = new in {EXPERT_MODE_REQUIREMENT_DONE, EXPERT_MODE_REQUIREMENT_VERIFIED}
            item["resolved"] = item["complete"]
            item["resolution"] = verdict["summary"]
            item["resolved_at"] = now if item["complete"] else ""
            item["last_review_cycle"] = cycle
            item["updated_at"] = now
            _append_expert_history(
                store, current, actor="reviewer", requirement_id=item["id"],
                old_state=old, new_state=new, progress=verdict["summary"],
                next_step=verdict["next_step"], review_cycle=cycle,
                reviewer_verdict=verdict["verdict"],
            )
        current["review_cycle"] = cycle
        current["review_status"] = "failed" if any_fail else "passed"
        current["review_requested"] = False
        current["review_in_progress"] = False
        current["review_error"] = ""
        current["review_feedback_pending"] = any_fail
        current["review_passed_pending"] = not any_fail
        current["review_passed_prompt_sent"] = False
        reviews = list(current.get("reviews") or [])
        review_record = _clone_review_json(review_record)
        review_record.update({
            "schema": EXPERT_MODE_REVIEW_SCHEMA,
            "cycle": cycle,
            "completed_at": now,
            "status": "failed" if any_fail else "passed",
            "verdicts": verdicts,
        })
        reviews.append(review_record)
        current["reviews"] = reviews
        _append_expert_history(
            store, current, actor="velox", requirement_id="", old_state="reviewing",
            new_state=current["review_status"], progress=(
                f"Review cycle {cycle} completed with "
                f"{sum(1 for value in verdicts if value['verdict']=='pass')} pass and "
                f"{sum(1 for value in verdicts if value['verdict']=='fail')} fail verdicts."
            ), review_cycle=cycle, event="review_completed",
        )
        return _save_expert_state(store, current)


def _mark_expert_review_started(store: Any, state: dict[str, Any], cycle: int, package: dict[str, Any]) -> dict[str, Any]:
    current = _clone_review_json(state)
    current["review_cycle"] = cycle
    current["review_status"] = "running"
    current["review_requested"] = False
    current["review_in_progress"] = True
    current["review_error"] = ""
    current["active_review"] = {
        "schema": EXPERT_MODE_REVIEW_SCHEMA,
        "cycle": cycle,
        "started_at": _checklist_utc_now(),
        "handoff_path": package["handoff_path"],
        "context_path": package["context_path"],
        "review_dir": package["review_dir"],
    }
    _append_expert_history(
        store, current, actor="velox", requirement_id="", old_state="pending",
        new_state="reviewing", progress=f"Independent full-cycle review {cycle} started.",
        review_cycle=cycle, event="review_started",
    )
    return _save_expert_state(store, current)


def _record_expert_review_error(store: Any, before: dict[str, Any], cycle: int, error: BaseException) -> dict[str, Any]:
    """Record a review error without rewinding the implementer's work.

    Preserve edits made during review, record the failed attempt and leave it
    inactive until a new verification request. Restoring an old snapshot would
    lose those edits and could relaunch the same failed review."""
    path = _expert_state_file(store)
    with _expert_state_path_lock(path):
        current = _load_expert_state(store)
        before_run = str(before.get("run_id") or "")
        if isinstance(current, dict):
            current_run = str(current.get("run_id") or "")
            if current_run and before_run and current_run != before_run:
                # A newer Checklist run replaced the reviewed run. Never overwrite it.
                return current
            restored = _clone_review_json(current)
        else:
            restored = _clone_review_json(before)
        restored["review_cycle"] = max(int(restored.get("review_cycle") or 0), int(cycle))
        restored["review_status"] = "error"
        restored["review_requested"] = False
        restored["review_in_progress"] = False
        restored["review_feedback_pending"] = False
        restored["review_passed_pending"] = False
        restored["review_passed_prompt_sent"] = False
        restored["review_error"] = f"{type(error).__name__}: {error}"
        restored["active_review"] = {}
        _append_expert_history(
            store, restored, actor="velox", requirement_id="", old_state="reviewing",
            new_state="review_error", progress=restored["review_error"],
            review_cycle=cycle, event="review_error",
        )
        return _save_expert_state(store, restored)


async def _call_maybe_async(callable_value: Any, *args: Any, **kwargs: Any) -> Any:
    result = callable_value(*args, **kwargs)
    if inspect.isawaitable(result):
        return await result
    return result


def _bind_expert_call(function: Any, available: dict[str, Any]) -> tuple[list[Any], dict[str, Any]]:
    signature = inspect.signature(function)
    positional: list[Any] = []
    keyword: dict[str, Any] = {}
    for parameter in signature.parameters.values():
        if parameter.name in {"self", "cls"}:
            continue
        if parameter.kind in (parameter.VAR_POSITIONAL, parameter.VAR_KEYWORD):
            continue
        if parameter.name in available:
            value = available[parameter.name]
        elif parameter.default is not inspect.Parameter.empty:
            continue
        elif "agent" in parameter.name and "id" in parameter.name:
            value = available.get("agent_id", "")
        elif "request" in parameter.name and "id" in parameter.name:
            value = available.get("request_id", uuid.uuid4().hex)
        elif parameter.annotation is bool:
            value = False
        else:
            value = available.get("task", "")
        if parameter.kind == parameter.POSITIONAL_ONLY:
            positional.append(value)
        else:
            keyword[parameter.name] = value
    return positional, keyword


def _find_agent_runtime(runtime: Any) -> Any:
    if runtime.__class__.__name__ == "AgentRuntime":
        return runtime
    for name in ("agent_runtime", "agents_runtime", "agent_runner"):
        value = getattr(runtime, name, None)
        if value is not None:
            return value
    # Resolve the shared AgentRuntime through the chat's tool registry so review
    # creates a real Agent task rather than only updating progress state.
    tools = getattr(runtime, "tools", None)
    if tools is not None:
        value = getattr(tools, "agent_runtime", None)
        if value is not None:
            return value
    app = getattr(runtime, "app", None)
    if app is not None:
        for name in ("agent_runtime", "agents_runtime", "agent_runner"):
            value = getattr(app, name, None)
            if value is not None:
                return value
    return None


def _extract_review_strings(value: Any, *, depth: int = 0) -> list[str]:
    if depth > 6:
        return []
    if isinstance(value, str):
        return [value]
    if isinstance(value, dict):
        preferred = []
        for key in ("final_output", "result", "response", "answer", "output", "content", "text"):
            if key in value:
                preferred.extend(_extract_review_strings(value[key], depth=depth + 1))
        for key, child in value.items():
            if key not in {"final_output", "result", "response", "answer", "output", "content", "text"}:
                preferred.extend(_extract_review_strings(child, depth=depth + 1))
        return preferred
    if isinstance(value, (list, tuple)):
        result: list[str] = []
        for child in value:
            result.extend(_extract_review_strings(child, depth=depth + 1))
        return result
    return []


async def _run_managed_reviewer_agent(runtime: Any, system_prompt: str, user_prompt: str, metadata: dict[str, Any]) -> Any:
    injected = getattr(runtime, "expert_review_runner", None) or getattr(runtime, "_expert_review_runner", None)
    if callable(injected):
        return await _call_maybe_async(injected, system_prompt, user_prompt, metadata)

    agent_runtime = _find_agent_runtime(runtime)
    if agent_runtime is None:
        raise RuntimeError("No Velox AgentRuntime is available for the fresh Checklist Reviewer context")
    agent_store = getattr(agent_runtime, "agents", None)
    if not isinstance(agent_store, AgentStore):
        raise RuntimeError("No strict AgentStore is available for the Checklist Reviewer")
    owner = metadata.get("owner") if isinstance(metadata.get("owner"), dict) else {}
    chat_id = str(owner.get("chat_id") or "").strip()
    if not chat_id:
        raise RuntimeError("Checklist Reviewer requires the owning source Chat")
    endpoint_profile_id = str(metadata.get("endpoint_profile_id") or "").strip()
    if not endpoint_profile_id:
        try:
            endpoint_profile_id = ChatStore(agent_runtime.storage).get_endpoint_profile_id()
        except Exception:
            endpoint_profile_id = DEFAULT_ENDPOINT_PROFILE_ID

    inherited_features = {key: True for key in CHAT_TOOL_FEATURE_KEYS}
    try:
        owner_agent_id = str(owner.get("agent_id") or "")
        if owner_agent_id:
            inherited_features = normalize_tool_feature_flags(agent_store.load_agent(owner_agent_id).get("tool_features"))
        else:
            chat = agent_runtime.chats.load_chat(chat_id)
            inherited_features = normalize_tool_feature_flags(chat.get("features"))
    except Exception:
        inherited_features = {key: True for key in CHAT_TOOL_FEATURE_KEYS}
    inherited_features["agent_tools_enabled"] = False
    inherited_features["chat_history_enabled"] = False

    marker_payload = {
        "cycle": int(metadata.get("cycle") or 0),
        "owner": owner,
        "handoff_path": str(metadata.get("handoff_path") or ""),
        "context_path": str(metadata.get("context_path") or ""),
    }
    reviewer_context = (
        EXPERT_MODE_REVIEW_AGENT_CONTEXT_MARKER + "\n"
        + json.dumps(marker_payload, ensure_ascii=False, sort_keys=True)
    )
    created = agent_store.create_agent(
        chat_id,
        user_prompt,
        title=f"Checklist Review {int(metadata.get('cycle') or 1)}",
        endpoint_profile_id=endpoint_profile_id,
        context=reviewer_context,
        agent_kind=AGENT_KIND_GENERAL,
        tool_features=inherited_features,
    )
    agent_id = str(created.get("agent_id") or "")
    if not agent_id:
        raise RuntimeError("AgentStore did not return an Checklist Reviewer agent ID")

    token = _REVIEWER_CONTEXT.set(True)
    try:
        agent_runtime.start_agent(agent_id)
        record = await agent_runtime.wait_for_agent(agent_id)
    finally:
        _REVIEWER_CONTEXT.reset(token)
    if str(record.get("status") or "") != "succeeded":
        diagnostic = str(record.get("failure_message") or record.get("last_output_excerpt") or "Reviewer Agent did not succeed").strip()
        raise RuntimeError(diagnostic)

    transcript = agent_store.load_transcript(agent_id)
    candidates: list[str] = []
    for event in reversed(transcript):
        if str(event.get("kind") or "") != "llm_output":
            continue
        data = event.get("data") if isinstance(event.get("data"), dict) else {}
        for key in ("text", "raw_text"):
            value = str(data.get(key) or "")
            if value:
                candidates.append(value)
    candidates.extend(_extract_review_strings(record))
    for candidate in candidates:
        if '"verdicts"' in candidate:
            return candidate
    raise RuntimeError("Checklist Reviewer completed without a structural verdict object")

async def _run_expert_review_cycle(runtime: Any, store: Any, state: dict[str, Any], bound: dict[str, Any]) -> dict[str, Any]:
    path = _expert_state_file(store)
    async with _expert_review_lock(path):
        current = _load_expert_state(store, required=True)
        assert current is not None
        if str(current.get("status") or "") != "active":
            return current
        if not _expert_ready_for_review(current):
            return current
        if bool(current.get("review_passed_pending")):
            return current
        if not bool(current.get("review_requested")):
            return current
        current_cycle = int(current.get("review_cycle") or 0)
        cycle = current_cycle + 1
        try:
            context = getattr(store, "context", None)
            owner = {
                "owner_kind": str(getattr(context, "owner_kind", "") or current.get("owner_kind") or "chat"),
                "chat_id": str(getattr(context, "chat_id", "") or current.get("chat_id") or ""),
                "agent_id": str(getattr(context, "agent_id", "") or current.get("agent_id") or ""),
                "task_run_id": int(getattr(context, "task_run_id", 0) or current.get("task_run_id") or 0),
            }
            manager = ChecklistStore(store.storage)
            if current_cycle > 0 and manager._collection_path(owner).exists():
                active = manager.active(owner)
                if active is not None and int(active.get("review_cycle") or 0) == current_cycle:
                    cycle = current_cycle
        except Exception:
            pass
        before = _clone_review_json(current)
        package = _make_expert_review_package(store, current, runtime=runtime, bound=bound, cycle=cycle)
        current = _mark_expert_review_started(store, current, cycle, package)
        user_prompt = _build_reviewer_user_prompt(current, package, cycle)
        endpoint_profile_id = str(
            bound.get("endpoint_profile_id")
            or bound.get("profile_id")
            or getattr(runtime, "endpoint_profile_id", "")
            or ""
        )
        metadata = {
            "cycle": cycle,
            "owner": package["owner"],
            "workspace": package["workspace"],
            "handoff_path": package["handoff_path"],
            "context_path": package["context_path"],
            "endpoint_profile_id": endpoint_profile_id,
        }
        review_record = {
            "cycle": cycle,
            "started_at": str(current.get("active_review", {}).get("started_at") or _checklist_utc_now()),
            "handoff_path": package["handoff_path"],
            "context_path": package["context_path"],
            "review_dir": package["review_dir"],
        }
        try:
            raw_result = await _run_managed_reviewer_agent(runtime, REVIEWER_SYSTEM_PROMPT, user_prompt, metadata)
            verdicts = _parse_reviewer_result(raw_result, current)
            result_path = Path(package["review_dir"]) / "review_result.json"
            _write_expert_state_json(result_path, {
                "schema": EXPERT_MODE_REVIEW_SCHEMA,
                "cycle": cycle,
                "verdicts": verdicts,
                "completed_at": _checklist_utc_now(),
            })
            review_record["result_path"] = str(result_path)
            return _apply_reviewer_verdicts(store, current, verdicts, cycle=cycle, review_record=review_record)
        except asyncio.CancelledError:
            _record_expert_review_error(store, before, cycle, RuntimeError("Checklist Review cancelled"))
            raise
        except Exception as exc:
            return _record_expert_review_error(store, before, cycle, exc)


def _extract_bound_argument(original: Any, self: Any, args: tuple[Any, ...], kwargs: dict[str, Any]) -> dict[str, Any]:
    try:
        signature = inspect.signature(original)
        bound = signature.bind_partial(self, *args, **kwargs)
        values = dict(bound.arguments)
        values.pop("self", None)
        return values
    except Exception:
        return dict(kwargs)


def _extract_agent_record(runtime: Any, bound: dict[str, Any]) -> dict[str, Any]:
    for value in bound.values():
        if isinstance(value, dict) and ("agent_id" in value or "agent_kind" in value):
            return value
    agent_id = str(bound.get("agent_id") or "")
    store = getattr(runtime, "agents", None)
    load = getattr(store, "load_agent", None) if store is not None else None
    if agent_id and callable(load):
        try:
            record = load(agent_id)
            if isinstance(record, dict):
                return record
        except Exception:
            pass
    return {}


def _construct_checklist_store(runtime: Any, *, owner_kind: str, bound: dict[str, Any]) -> Any:
    # The production runtimes use the explicit factories below. Focused harnesses
    # and future narrow runtime adapters may expose the same dependency through
    # _expert_mode_store; honor that explicit seam before resolving durable IDs.
    factory = getattr(runtime, "_expert_mode_store", None)
    if callable(factory):
        try:
            candidate = factory(owner_kind=owner_kind, **bound)
        except TypeError:
            try:
                candidate = factory(bound)
            except TypeError:
                candidate = factory()
        if candidate is not None:
            return candidate
    storage = getattr(runtime, "storage", None)
    if storage is None:
        raise RuntimeError("Runtime has no storage for Checklist")
    if owner_kind == "agent":
        agent = _extract_agent_record(runtime, bound)
        if not agent:
            raise RuntimeError("Agent Checklist owner could not be resolved")
        return ExpertModeStore.for_agent(storage, agent)
    chat_id = str(bound.get("chat_id") or "").strip()
    if not chat_id:
        raise RuntimeError("Chat Checklist owner could not be resolved")
    return ExpertModeStore.for_chat(storage, chat_id)

def _finalize_after_review_prompt(store: Any, state: dict[str, Any]) -> dict[str, Any]:
    if not bool(state.get("review_passed_pending")) or not bool(state.get("review_passed_prompt_sent")):
        return state
    if not all(str(item.get("status") or "") == EXPERT_MODE_REQUIREMENT_VERIFIED for item in state.get("requirements") or []):
        return state
    state = _clone_review_json(state)
    state["status"] = "succeeded"
    state["active"] = False
    state["completed_at"] = _checklist_utc_now()
    state["review_passed_pending"] = False
    state["review_status"] = "passed"
    _append_expert_history(
        store, state, actor="velox", requirement_id="", old_state="active",
        new_state="succeeded", progress="All requirements independently verified in the latest full review cycle.",
        review_cycle=int(state.get("review_cycle") or 0), event="expert_mode_succeeded",
    )
    return _save_expert_state(store, state)


async def _checklist_before_stop(runtime: Any, original: Any, args: tuple[Any, ...], kwargs: dict[str, Any], owner_kind: str) -> None:
    bound = _extract_bound_argument(original, runtime, args, kwargs)
    if owner_kind == "agent":
        agent = _extract_agent_record(runtime, bound)
        if _is_reviewer_agent(agent):
            return
        bound.setdefault("chat_id", agent.get("source_chat_id") or "")
        bound.setdefault("agent_id", agent.get("agent_id") or "")
        bound.setdefault("task_run_id", agent.get("task_run_id") or 0)
        bound.setdefault("task", agent.get("task") or agent.get("assigned_task") or "")
        bound.setdefault("endpoint_profile_id", agent.get("endpoint_profile_id") or "")
    store = _construct_checklist_store(runtime, owner_kind=owner_kind, bound=bound)
    if _canonical_checklists(store) is not None:
        return  # Generic Checklists own review; a stale/missing mirror cannot start an old review cycle.
    state = _load_expert_state(store)
    if not state or str(state.get("status") or "") != "active":
        return
    if bool(state.get("review_passed_pending")) and bool(state.get("review_passed_prompt_sent")):
        _finalize_after_review_prompt(store, state)
        return
    if (
        _expert_ready_for_review(state)
        and bool(state.get("review_requested"))
        and not bool(state.get("review_in_progress"))
        and not bool(state.get("review_passed_pending"))
    ):
        await _run_expert_review_cycle(runtime, store, state, bound)


def _install_checklist_stop_hook(cls: Any, name: str, owner_kind: str) -> None:
    original = getattr(cls, name, None)
    if original is None or getattr(original, "_checklist_review_hook_installed", False):
        return
    if inspect.iscoroutinefunction(original):
        async def wrapped(self: Any, *args: Any, __original: Any = original, **kwargs: Any) -> Any:
            await _checklist_before_stop(self, __original, args, kwargs, owner_kind)
            return await __original(self, *args, **kwargs)
    else:
        def wrapped(self: Any, *args: Any, __original: Any = original, **kwargs: Any) -> Any:
            # Existing production handlers are asynchronous. Preserve a synchronous
            # fallback for focused harnesses without creating a nested event loop.
            try:
                loop = asyncio.get_running_loop()
            except RuntimeError:
                asyncio.run(_checklist_before_stop(self, __original, args, kwargs, owner_kind))
            else:
                loop.create_task(_checklist_before_stop(self, __original, args, kwargs, owner_kind))
            return __original(self, *args, **kwargs)
    wrapped._checklist_review_hook_installed = True
    setattr(cls, name, wrapped)


if "ChatRuntime" in globals():
    _install_checklist_stop_hook(ChatRuntime, "_inject_chat_expert_mode_prompt", "chat")
if "AgentRuntime" in globals():
    _install_checklist_stop_hook(AgentRuntime, "_handle_agent_expert_mode_stop", "agent")


# Reviewer Agent contexts receive a dedicated fresh acceptance prompt instead of
# the implementer's Agent system prompt. The durable Agent record stays on the
# strict general-agent schema; an internal context marker identifies reviewer runs.
_BUILD_AGENT_PROMPT_BASE = AgentRuntime.build_standard_system_prompt
def _build_agent_prompt_with_role(self: Any, agent: dict[str, Any], *args: Any, **kwargs: Any) -> str:
    if _is_reviewer_agent(agent):
        skill_block = self.tools.build_skill_system_block(
            APP_SCOPE_ID, str(agent.get("source_chat_id") or ""),
            feature_overrides=normalize_tool_feature_flags(agent.get("tool_features")),
        )
        return _apply_agent_role_prompt(self, agent,
            host_environment_prompt() + "\n\n" + REVIEWER_SYSTEM_PROMPT + "\n\n" + skill_block)
    text = _BUILD_AGENT_PROMPT_BASE(self, agent, *args, **kwargs)
    return _apply_agent_role_prompt(self, agent, text)

AgentRuntime.build_standard_system_prompt = _build_agent_prompt_with_role


# Internal reviewer Agents retain normal durable diagnostics but never enqueue a
# user-facing parent-Chat report. Mark their terminal report handled so startup
# recovery cannot surface it later.
_SCHEDULE_CHAT_REPORT_BASE = AgentRuntime._schedule_chat_report
def _schedule_nonreviewer_chat_report(self: Any, agent: dict[str, Any], report_kind: str) -> None:
    if _is_reviewer_agent(agent):
        if report_kind == "terminal" and not agent.get("terminal_reported_at"):
            try:
                self.agents.update_agent(str(agent.get("agent_id") or ""), {"terminal_reported_at": now_iso()})
            except Exception:
                pass
        return None
    return _SCHEDULE_CHAT_REPORT_BASE(self, agent, report_kind)

AgentRuntime._schedule_chat_report = _schedule_nonreviewer_chat_report


# Compact UI semantics are delivered through the existing shared requirements
# table. Existing card/history/modal code consumes these enriched row dictionaries.


# =============================================================================
# Persistent checklists and acceptance review
# =============================================================================
# Each owner has one active requirements list with fixed text and one level of
# implementation steps. The collection owns progress, append-only comments and
# review state; the execution adapter supplies task memory and continuation.

CHECKLIST_COLLECTION_SCHEMA = "checklist_collection.v303"
CHECKLIST_HISTORY_SCHEMA = "checklist_history_event.v303"
CHECKLIST_REVIEW_SCHEMA = "checklist_review_result.v303"
CHECKLIST_LIFECYCLE_OPEN = "open"
CHECKLIST_LIFECYCLE_COMPLETED = "completed"
CHECKLIST_LIFECYCLE_ABANDONED = "abandoned"
CHECKLIST_LIFECYCLE_CANCELLED_BY_USER = "cancelled_by_user"
CHECKLIST_ITEM_NOT_STARTED = "not_started"
CHECKLIST_ITEM_IN_PROGRESS = "in_progress"
CHECKLIST_ITEM_DONE = "done"
CHECKLIST_ITEM_VERIFIED = "verified"
CHECKLIST_ITEM_STATES = (
    CHECKLIST_ITEM_NOT_STARTED,
    CHECKLIST_ITEM_IN_PROGRESS,
    CHECKLIST_ITEM_DONE,
    CHECKLIST_ITEM_VERIFIED,
)
CHECKLIST_IMPLEMENTER_STATES = (
    CHECKLIST_ITEM_NOT_STARTED,
    CHECKLIST_ITEM_IN_PROGRESS,
    CHECKLIST_ITEM_DONE,
)
CHECKLIST_TOOL_NAMES = ('checklist_create', 'checklist_subitems_create', 'checklist_item_update', 'checklist_status', 'checklist_list', 'verify_checklist', 'checklist_resume')
_INTERNAL_EXPERT_TOOL_NAMES = (
    "expert_mode_enter",
    "expert_mode_requirement_update",
    "expert_mode_status",
    "expert_mode_exit",
)
CHECKLIST_GUIDANCE = """Use one Checklist for a large or complex task; answer simple requests directly. Before execution, reread the whole request. checklist_create(name, items) takes 1-100 outcome-focused requirements and assigns C1..Cn. Cover every requested requirement, acceptance criterion, deliverable, constraint and validation condition; preserve user-supplied requirements individually and meaningful user IDs. The name, original wording, IDs, order and membership are immutable. Only one Checklist may be active per context; another cannot replace unfinished work.

For each non-trivial requirement, use checklist_subitems_create(checklist_id, item_id, items) before implementing it. Supply its complete 1-100-step mini-plan once. These C#.n actions belong to the SAME Checklist, not child Checklists. No grandchildren, append, edit, deletion or replacement are allowed. Keep uncertain details flexible through factual progress comments. Create requirements and the next actionable mini-plan promptly; avoid repeated redesign before taking an evidence-producing action.

Use checklist_item_update with exact item_id, state and comment for C# requirements and C#.n steps. Implementers use not_started, in_progress and done; verified is reserved for independent review. Mark current work in_progress and update after a meaningful tested checkpoint, not only in a final bulk-completion batch. Comments capture observed results and the next action; batch updates summarize already-observed results, not planned checks. Object existence or empty logs do not prove behavior. Work down the steps, jumping around dependencies; record blockers and continue unblocked work without shrinking scope.

Every sub-item must be done before its parent can be marked done. Finished steps do not automatically satisfy parent acceptance: assess the complete original requirement and material validation, including actual pixels. While the Checklist is active, reopen an incorrect done/verified claim with in_progress and evidence; reopening a step reopens its finished parent. When all requirements and steps are done, call verify_checklist. A fresh read-only Reviewer checks the entire contract; only independent verdicts set verified. A failed step prevents its parent from passing. Repair failures in the same fixed list, obtain fresh post-fix evidence and verify again. Final success requires every item to pass. Infrastructure errors stay visible without automatic review retries. Never abandon or replace unfinished work.

Completed Checklists are immutable historical review snapshots. A later user-requested repair is a new task: create a fresh repair Checklist when complex, and never cite the old pass as validation of the changed artifact. User Stop cancels the active Chat Checklist and preserves history; Pause preserves active work. Only a new explicit user request to resume cancelled work authorizes checklist_resume with its historical ID and a comment quoting that request. Automatic continuations or unrelated requests do not authorize resume; another active Checklist blocks it. New tasks follow completion or Stop."""
# Reviewer Agents must not be able to mutate Checklist state through the generic
# tool family. The execution guard uses this denylist as a second line of defense
# in addition to schema filtering.
EXPERT_MODE_REVIEWER_READ_ONLY_TOOL_DENYLIST = frozenset(
    set(globals().get("EXPERT_MODE_REVIEWER_READ_ONLY_TOOL_DENYLIST", frozenset()))
    | set(CHECKLIST_TOOL_NAMES)
)
CHECKLIST_REVIEWER_GUIDANCE = r"""Perform an independent acceptance pass using current artifacts, production-path execution and material pixels. C# items are the original immutable requirements; C#.n items are implementation steps attached to their parent. Inspect every requirement clause, step and previously passed item for regressions. Step completion alone is not proof of parent acceptance; a defective step fails that step and its related parent. Return one verdict per supplied ID in the supplied parent-first order with observed evidence and a concrete next action for failures. Keep source read-only and use the supplied terminal JSON/progress protocol."""

# Keep execution-adapter tools separate from the model-facing Checklist API.
# Provider schemas expose only the currently enabled tools.
_EXPERT_EXECUTION_TOOL_NAMES = tuple(EXPERT_MODE_TOOL_NAMES)
# The execution adapter uses these four core operations. Provider schemas also
# include sub-items, history and authorized resume.
EXPERT_MODE_TOOL_NAMES = ("checklist_create", "checklist_item_update", "checklist_status", "verify_checklist")

# Native tool-call validation uses ToolDefinition.positional_arguments as the
# canonical set/order of accepted JSON fields.  The generic Checklist tools must
# therefore publish signatures that match their JSON schemas.  Leaving these as
# empty tuples makes every otherwise-valid provider call fail as "unexpected".
CHECKLIST_TOOL_POSITIONAL_SIGNATURES = {
    "checklist_create": (ToolArgumentSpec("name", "text"), ToolArgumentSpec("items", "text", "json_array")),
    "checklist_subitems_create": (ToolArgumentSpec("checklist_id", "text"), ToolArgumentSpec("item_id", "text"), ToolArgumentSpec("items", "text", "json_array")),
    "checklist_item_update": (ToolArgumentSpec("checklist_id", "text"), ToolArgumentSpec("updates", "text", "json_array")),
    "checklist_status": (ToolArgumentSpec("checklist_id", "text"), ToolArgumentSpec("include_history", "boolean")),
    "checklist_list": (ToolArgumentSpec("include_completed", "boolean"),),
    "verify_checklist": (ToolArgumentSpec("checklist_id", "text"),),
    "checklist_resume": (ToolArgumentSpec("checklist_id", "text"), ToolArgumentSpec("comment", "text")),
}
for _name in _INTERNAL_EXPERT_TOOL_NAMES:
    TOOL_POSITIONAL_SIGNATURES.pop(_name, None)
for _name, _signature in CHECKLIST_TOOL_POSITIONAL_SIGNATURES.items():
    TOOL_POSITIONAL_SIGNATURES[_name] = _signature

_CHECKLIST_LOCK = threading.RLock()


def _checklist_utc_now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def _clean_checklist_text(value: Any, *, maximum: int = 12000) -> str:
    text_value = str(value or "").strip()
    if len(text_value) > maximum:
        text_value = text_value[:maximum].rstrip() + "…"
    return text_value


def _write_checklist_json(path: Path, value: Any) -> None:
    with DATA_ROOTS.lock_for_path(path):
        _require_durable_owner(path)
        path.parent.mkdir(parents=True, exist_ok=True)
        temp = path.with_name(path.name + ".tmp-" + uuid.uuid4().hex)
        try:
            temp.write_text(json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")
            os.replace(temp, path)
        finally:
            try:
                temp.unlink(missing_ok=True)
            except OSError:
                # Cleanup cannot replace a write error or undo a committed replace.
                pass


def _append_checklist_jsonl(path: Path, value: dict[str, Any]) -> None:
    with DATA_ROOTS.lock_for_path(path):
        _require_durable_owner(path)
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("a", encoding="utf-8", newline="\n") as handle:
            handle.write(json.dumps(value, ensure_ascii=False, sort_keys=True) + "\n")
            handle.flush()
            try:
                os.fsync(handle.fileno())
            except OSError:
                pass


def _bind_checklist_arguments(function: Any, self_obj: Any, args: tuple[Any, ...], kwargs: dict[str, Any]) -> dict[str, Any]:
    try:
        signature = inspect.signature(function)
        bound = signature.bind_partial(self_obj, *args, **kwargs)
        return dict(bound.arguments)
    except Exception:
        return dict(kwargs)


def _call_supported_arguments(method: Any, values: dict[str, Any]) -> Any:
    """Call a bound method with the parameters its signature accepts."""
    signature = inspect.signature(method)
    positional: list[Any] = []
    keyword: dict[str, Any] = {}
    aliases = {
        "kind": "owner_kind",
        "owner": "owner_kind",
        "task_id": "task_run_id",
        "run_id": "task_run_id",
        "requirements_list": "requirements",
        "items": "requirements",
        "updates_list": "updates",
        "arguments": "arguments",
        "params": "arguments",
        "context": "context",
        "tool_context": "context",
        "call_context": "context",
    }
    for parameter in signature.parameters.values():
        if parameter.name == "self":
            continue
        source_name = parameter.name if parameter.name in values else aliases.get(parameter.name, parameter.name)
        if source_name in values:
            value = values[source_name]
            if parameter.kind == inspect.Parameter.POSITIONAL_ONLY:
                positional.append(value)
            else:
                keyword[parameter.name] = value
        elif parameter.default is inspect._empty and parameter.kind not in (
            inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD,
        ):
            # Leave absent only when the caller supplied no useful equivalent.
            raise TypeError(f"Missing required adaptive argument: {parameter.name}")
    return method(*positional, **keyword)


def _checklist_owner_from_context(context: Any, arguments: Optional[dict[str, Any]] = None) -> dict[str, Any]:
    arguments = arguments or {}
    def pick(*names: str, default: Any = "") -> Any:
        for name in names:
            value = getattr(context, name, None) if context is not None else None
            if value not in (None, "", 0):
                return value
            value = arguments.get(name)
            if value not in (None, "", 0):
                return value
        return default
    chat_id = str(pick("chat_id", "source_chat_id", default="") or "")
    agent_id = str(pick("agent_id", "source_agent_id", default="") or "")
    task_run_id_raw = pick("task_run_id", "agent_task_run_id", default=0)
    try:
        task_run_id = int(task_run_id_raw or 0)
    except Exception:
        task_run_id = 0
    owner_kind = "agent" if agent_id else "chat"
    if not chat_id and owner_kind == "chat":
        chat_id = str(arguments.get("owner_id") or "")
    return {
        "owner_kind": owner_kind,
        "chat_id": chat_id,
        "agent_id": agent_id,
        "task_run_id": task_run_id,
    }


def _parse_tool_handler_call(args: tuple[Any, ...], kwargs: dict[str, Any]) -> tuple[Any, dict[str, Any]]:
    arguments: dict[str, Any] = {}
    context: Any = None
    for value in args:
        if isinstance(value, dict):
            if any(key in value for key in (
                "name", "items", "updates", "checklist_id", "item_id", "text", "comment",
                "include_history", "include_completed",
            )):
                arguments = value
            elif not arguments:
                arguments = value
        elif context is None and any(hasattr(value, key) for key in ("chat_id", "agent_id", "task_run_id", "source_chat_id")):
            context = value
    for name in ("arguments", "params", "payload"):
        value = kwargs.get(name)
        if isinstance(value, dict):
            arguments = value
    for name in ("context", "tool_context", "call_context"):
        value = kwargs.get(name)
        if value is not None:
            context = value
    return context, arguments


class ChecklistStore:
    """One active immutable requirements Checklist per enabled Chat or Agent run."""

    def enabled(self, owner: dict[str, Any]) -> bool:
        """Read strict owner policy; missing/corrupt owners never grant capability."""
        if owner.get("agent_id"):
            record = AgentStore(self.storage).load_agent(str(owner["agent_id"]))
            return bool(record["tool_features"]["checklists_enabled"])
        record = ChatStore(self.storage).load_chat_view(str(owner["chat_id"]))
        return bool(record["features"]["checklists_enabled"])

    def _require_enabled(self, owner: dict[str, Any]) -> None:
        if not self.enabled(owner):
            raise PermissionError("Checklists are disabled for this Task by its locked user settings")

    def __init__(self, storage: Any) -> None:
        self.storage = storage

    def _owner_dir(self, owner: dict[str, Any]) -> Path:
        paths = self.storage.paths
        if str(owner.get("owner_kind") or "") == "agent" or str(owner.get("agent_id") or ""):
            agent_id = str(owner.get("agent_id") or "").strip()
            if not agent_id:
                raise ValueError("Agent checklist owner requires agent_id")
            directory = Path(paths.agent_dir(agent_id))
        else:
            chat_id = str(owner.get("chat_id") or "").strip()
            if not chat_id:
                raise ValueError("Chat checklist owner requires chat_id")
            directory = Path(paths.chat_dir(chat_id))
        return directory

    def _collection_path(self, owner: dict[str, Any]) -> Path:
        directory = self._owner_dir(owner)
        if str(owner.get("owner_kind") or "") == "agent" or str(owner.get("agent_id") or ""):
            run_id = max(0, int(owner.get("task_run_id") or 0))
            return directory / f"checklists_{run_id}.json"
        return directory / "checklists.json"

    def execution_target(self, owner: dict[str, Any], collection: dict[str, Any]) -> Optional[dict[str, Any]]:
        """Every implementing context continues its one canonical active checklist."""
        return self.active(owner, collection) if self.enabled(owner) else None

    def execution_state(self, owner: dict[str, Any], collection: Optional[dict[str, Any]] = None) -> Optional[dict[str, Any]]:
        """Read-only runtime projection; never create a second persisted checklist."""
        if not self.enabled(owner):
            return None
        with _CHECKLIST_LOCK:
            collection = collection if collection is not None else self.load_collection(owner, create=False)
            checklist = self.active(owner, collection)
            if checklist is None:
                return None
            requirements = []
            for index, item in enumerate(checklist["items"], 1):
                comment = self.latest_comment(item)
                requirements.append({"id": f"R{index}", "requirement": item["text"], "status": item["state"],
                    "progress": comment, "next_step": comment if item["state"] == CHECKLIST_ITEM_IN_PROGRESS else "",
                    "review_summary": comment if item["state"] == CHECKLIST_ITEM_VERIFIED else ""})
            state = _validate_expert_state({
                "schema": "expert_mode_state.v303", **owner, "run_id": checklist["id"], "status": "active",
                "created_at": checklist["created_at"], "updated_at": checklist["updated_at"],
                "requirements": requirements, "review_cycle": checklist["review_cycle"],
                "review_status": checklist["review_status"], "review_error": checklist["review_error"],
                "last_continuation_key": checklist.get("last_continuation_key", ""),
                "continuation_count": checklist.get("continuation_count", 0),
                "checklist_id": checklist["id"], "checklist_name": checklist["name"],
            })
            # The internal execution descriptor stays requirement-oriented.
            # UI presentation reads canonical nested Checklist snapshots directly.
            for row, item in zip(state["requirements"], checklist["items"]):
                row["item_id"] = item["id"]
                row["subitems"] = [self._compact_item(child) for child in item["subitems"]]
            state["checklist_task_memory"] = self._task_memory_for(checklist)
            return state

    def claim_execution_continuation(self, owner: dict[str, Any], key: Any) -> tuple[dict[str, Any], bool]:
        key = str(key or "").strip()
        if not key:
            raise ExpertModeStateError("Checklist continuation key is required")
        with _CHECKLIST_LOCK:
            collection = self.load_collection(owner, create=False)
            state = self.execution_state(owner, collection)
            if state is None:
                raise ExpertModeStateError("Checklist is not active for this Task")
            checklist = self._checklist(collection, state["checklist_id"])
            if checklist.get("last_continuation_key") == key:
                return state, False
            checklist["last_continuation_key"] = key
            checklist["continuation_count"] = int(checklist.get("continuation_count") or 0) + 1
            self._save(owner, collection)
            state["last_continuation_key"] = key
            state["continuation_count"] = checklist["continuation_count"]
            return state, True

    def resume_cancelled(self, owner: dict[str, Any], checklist_id: str, *, comment: str,
                         cancel_event: Any = None) -> dict[str, Any]:
        """Resume exactly one stopped checklist after a new explicit user request."""
        self._require_enabled(owner)
        if owner.get("owner_kind") != "chat" or owner.get("agent_id"):
            raise ValueError("Only a user-cancelled Chat Checklist can be resumed")
        comment = self._required_text(comment, "Resume comment")
        with _CHECKLIST_LOCK:
            def check_cancelled() -> None:
                if cancel_event is not None and cancel_event.is_set():
                    raise ToolCancelledError("Checklist resume cancelled before its state change")
            check_cancelled()
            collection = self.load_collection(owner, create=False)
            if self.user_stop_pending(owner):
                raise ValueError("Checklist cancellation is still being saved; resume after it completes")
            checklist = self._checklist(collection, checklist_id)
            if checklist["lifecycle"] != CHECKLIST_LIFECYCLE_CANCELLED_BY_USER:
                raise ValueError("Only a cancelled_by_user Checklist can be resumed")
            if self.active(owner, collection) is not None:
                raise ValueError("Complete the active Checklist, or explicitly Stop it, before resuming another")
            turns = ChatStore(self.storage).load_turns(APP_SCOPE_ID, str(owner["chat_id"]))
            user = next((row for row in reversed(turns) if row.get("role") == "user"
                         and not is_chat_application_injected_prompt_turn(row)), None)
            if not user or str(user.get("created_at") or "") <= str(collection.get("last_user_stop_at") or ""):
                raise ValueError("Resume requires a new real user request after Stop; automatic continuations cannot authorize it")
            reviewer_id = checklist["review_agent_id"]
            if reviewer_id:
                try:
                    reviewer = AgentStore(self.storage).load_agent(reviewer_id)
                except FileNotFoundError:
                    reviewer = {}
                if reviewer and reviewer.get("status") not in AGENT_TERMINAL_STATUSES:
                    raise ValueError("The previous Reviewer is still stopping; resume after it becomes terminal")
            checklist["lifecycle"] = CHECKLIST_LIFECYCLE_OPEN
            checklist["resumed_at"] = _checklist_utc_now()
            checklist["resumed_by_user_turn_id"] = user["turn_id"]
            checklist["review_cycle"] += 1  # Fence late callbacks from before Stop.
            checklist["review_status"] = REVIEW_IDLE
            for field in ("review_agent_id", "review_started_at", "review_completed_at", "review_error",
                          "review_snapshot_fingerprint", "last_continuation_key", "cancelled_at", "cancellation_reason"):
                checklist[field] = ""
            self._append_event(owner, checklist, None, actor="user", event="resumed_by_user",
                prior_state=CHECKLIST_LIFECYCLE_CANCELLED_BY_USER, new_state=CHECKLIST_LIFECYCLE_OPEN,
                comment=f"User request {user['turn_id']}: {comment}", review_cycle=checklist["review_cycle"])
            collection["active_checklist_id"] = checklist["id"]
            check_cancelled()
            self._save(owner, collection)
            return {"action": "resumed", "resumed_checklist_ids": [checklist["id"]],
                    "user_turn_id": user["turn_id"], **self.status(owner)}

    def _history_path(self, owner: dict[str, Any]) -> Path:
        path = self._collection_path(owner)
        return path.with_name(path.stem + "_history.jsonl")

    def _empty(self, owner: dict[str, Any]) -> dict[str, Any]:
        now = _checklist_utc_now()
        return {"schema": CHECKLIST_COLLECTION_SCHEMA,
                "owner_kind": str(owner.get("owner_kind") or "chat"),
                "chat_id": str(owner.get("chat_id") or ""),
                "agent_id": str(owner.get("agent_id") or ""),
                "task_run_id": int(owner.get("task_run_id") or 0),
                "created_at": now, "updated_at": now,
                "active_checklist_id": "", "checklists": []}

    @staticmethod
    def _normalize_state(value: Any) -> str:
        if not isinstance(value, str) or value not in CHECKLIST_ITEM_STATES:
            raise ValueError("Invalid Checklist item state")
        return value

    @staticmethod
    def _validated_name(value: Any) -> str:
        if not isinstance(value, str) or not value.strip():
            raise ValueError("Checklist name must be non-empty text provided by the LLM")
        name = value.strip()
        if len(name) > 240:
            raise ValueError("Checklist name must contain at most 240 characters")
        return name

    @staticmethod
    def _name_key(value: str) -> str:
        # A case/whitespace variation must not manufacture an ambiguous second name.
        return " ".join(value.split()).casefold()

    def _assert_unique_name(self, collection: dict[str, Any], name: str) -> None:
        key = self._name_key(self._validated_name(name))
        for checklist in collection.get("checklists", []):
            if self._name_key(str(checklist.get("name") or "")) == key:
                raise ValueError(f'Duplicate Checklist name "{name}" in this context; choose a distinct name (history also counts).')

    def _validate(self, collection: dict[str, Any]) -> None:
        if not isinstance(collection, dict) or collection.get("schema") != CHECKLIST_COLLECTION_SCHEMA:
            raise ValueError("Invalid Checklist collection schema")
        required = {"schema", "owner_kind", "chat_id", "agent_id", "task_run_id", "created_at", "updated_at",
                    "active_checklist_id", "checklists"}
        optional = {"last_user_stop_at", "last_user_stop_id"}
        if not required.issubset(collection) or set(collection) - required - optional:
            raise ValueError("Invalid Checklist collection fields; stacks and Checklist parents are not supported")
        for field in ("owner_kind", "chat_id", "agent_id", "created_at", "updated_at", "active_checklist_id"):
            if not isinstance(collection[field], str):
                raise ValueError(f"Invalid Checklist collection {field}")
        if collection["owner_kind"] not in ("chat", "agent") or type(collection["task_run_id"]) is not int or collection["task_run_id"] < 0:
            raise ValueError("Invalid Checklist owner or Task run")
        if ((collection["owner_kind"] == "chat" and (not collection["chat_id"] or collection["agent_id"] or collection["task_run_id"] != 0))
                or (collection["owner_kind"] == "agent" and not collection["agent_id"])):
            raise ValueError("Checklist owner identity is incomplete or inconsistent")
        for field in optional:
            if field in collection and not isinstance(collection[field], str):
                raise ValueError(f"Invalid Checklist collection {field}")
        checklists = collection["checklists"]
        if not isinstance(checklists, list):
            raise ValueError("Checklist history must be a list")
        ids, names, open_ids = set(), set(), []
        item_fields = {"id", "text", "state", "created_at", "updated_at", "history"}
        record_fields = {"id", "name", "owner_kind", "chat_id", "agent_id", "task_run_id", "lifecycle",
                         "created_at", "updated_at", "completed_at", "review_cycle", "review_status",
                         "review_agent_id", "review_started_at", "review_completed_at", "review_error",
                         "review_snapshot_fingerprint", "items", "history"}
        record_optional = {"cancelled_at", "cancellation_reason", "resumed_at", "resumed_by_user_turn_id",
                           "last_continuation_key", "continuation_count"}
        for checklist in checklists:
            if not isinstance(checklist, dict) or "parent_checklist_id" in checklist or "parent_item_id" in checklist:
                raise ValueError("Checklist records cannot have Checklist parents")
            if not record_fields.issubset(checklist) or set(checklist) - record_fields - record_optional:
                raise ValueError("Invalid Checklist fields")
            for field in record_optional - {"continuation_count"}:
                if field in checklist and not isinstance(checklist[field], str):
                    raise ValueError(f"Invalid Checklist {field}")
            if "continuation_count" in checklist and (type(checklist["continuation_count"]) is not int or checklist["continuation_count"] < 0):
                raise ValueError("Invalid Checklist continuation count")
            checklist_id = checklist.get("id")
            if not isinstance(checklist_id, str) or not checklist_id or checklist_id in ids:
                raise ValueError("Checklist IDs must be non-empty and unique")
            ids.add(checklist_id)
            key = self._name_key(self._validated_name(checklist.get("name")))
            if key in names:
                raise ValueError("Checklist names must be unique, including history")
            names.add(key)
            if any(checklist.get(field) != collection[field] for field in ("owner_kind", "chat_id", "agent_id", "task_run_id")):
                raise ValueError("Checklist record belongs to a different owner or Task run")
            if checklist.get("lifecycle") not in (CHECKLIST_LIFECYCLE_OPEN, CHECKLIST_LIFECYCLE_COMPLETED, CHECKLIST_LIFECYCLE_CANCELLED_BY_USER):
                raise ValueError("Invalid Checklist lifecycle; unfinished work cannot be abandoned by the LLM")
            if checklist["lifecycle"] == CHECKLIST_LIFECYCLE_OPEN:
                open_ids.append(checklist_id)
            if checklist.get("review_status") not in ("idle", "requested", "running", "passed", "failed", "error", "cancelled"):
                raise ValueError("Invalid Checklist review status")
            if type(checklist.get("review_cycle")) is not int or checklist["review_cycle"] < 0:
                raise ValueError("Invalid Checklist review cycle")
            for field in ("created_at", "updated_at", "completed_at", "review_agent_id", "review_started_at",
                          "review_completed_at", "review_error", "review_snapshot_fingerprint"):
                if not isinstance(checklist.get(field), str):
                    raise ValueError(f"Invalid Checklist {field}")
            if not isinstance(checklist.get("history"), list):
                raise ValueError("Checklist history must be a list")
            items = checklist.get("items")
            if not isinstance(items, list) or not 1 <= len(items) <= 100:
                raise ValueError("Checklist requires 1-100 original requirements")
            for index, parent in enumerate(items, 1):
                if not isinstance(parent, dict) or set(parent) != item_fields | {"subitems"} or parent.get("id") != f"C{index}":
                    raise ValueError("Original requirements must have stable, ordered C1..Cn IDs and fixed fields")
                children = parent["subitems"]
                if not isinstance(children, list) or len(children) > 100:
                    raise ValueError("Each requirement supports at most 100 one-level sub-items")
                for subindex, child in enumerate(children, 1):
                    if not isinstance(child, dict) or set(child) != item_fields or child.get("id") != f"{parent['id']}.{subindex}":
                        raise ValueError("Sub-items must have stable ordered C#.n IDs; nested sub-items are not supported")
                for item in (parent, *children):
                    self._normalize_state(item.get("state"))
                    self._required_text(item.get("text"), "Checklist item")
                    if not isinstance(item.get("history"), list) or not item["history"] or any(not isinstance(event, dict) for event in item["history"]):
                        raise ValueError("Every Checklist item requires factual append-only history")
                    if not isinstance(item.get("created_at"), str) or not isinstance(item.get("updated_at"), str):
                        raise ValueError("Invalid Checklist item timestamps")
                    if item["state"] != CHECKLIST_ITEM_NOT_STARTED and not self.latest_comment(item):
                        raise ValueError("Progress and completion require factual comments")
                if parent["state"] in (CHECKLIST_ITEM_DONE, CHECKLIST_ITEM_VERIFIED) and any(
                        child["state"] not in (CHECKLIST_ITEM_DONE, CHECKLIST_ITEM_VERIFIED) for child in children):
                    raise ValueError("A parent cannot be complete while a sub-item is incomplete")
                if parent["state"] == CHECKLIST_ITEM_VERIFIED and any(child["state"] != CHECKLIST_ITEM_VERIFIED for child in children):
                    raise ValueError("A verified parent requires all of its sub-items to be verified")
            if checklist["lifecycle"] == CHECKLIST_LIFECYCLE_COMPLETED and (
                    checklist["review_status"] != "passed" or any(item["state"] != CHECKLIST_ITEM_VERIFIED for item in self.all_items(checklist))):
                raise ValueError("Checklist completion requires independent verification of every requirement and sub-item")
        if len(open_ids) > 1:
            raise ValueError("A Chat or Agent Task can have only one active Checklist")
        if collection["active_checklist_id"] != (open_ids[0] if open_ids else ""):
            raise ValueError("active_checklist_id must name the sole open Checklist, or be empty when none is open")

    def load_collection(self, owner: dict[str, Any], *, create: bool = True) -> dict[str, Any]:
        path = self._collection_path(owner)
        with _CHECKLIST_LOCK, DATA_ROOTS.lock_for_path(path):
            _require_durable_owner(path)
            if path.exists():
                collection = json.loads(path.read_text(encoding="utf-8"))
                self._validate(collection)
                expected_owner = self._empty(owner)
                if any(collection.get(key) != expected_owner[key] for key in ("owner_kind", "chat_id", "agent_id", "task_run_id")):
                    raise ValueError("Checklist collection belongs to a different owner or Task run")
                return collection
            collection = self._empty(owner)
            self._validate(collection)
            if create:
                self._save(owner, collection)
            return collection

    def _save(self, owner: dict[str, Any], collection: dict[str, Any]) -> None:
        path = self._collection_path(owner)
        with DATA_ROOTS.lock_for_path(path):
            _require_durable_owner(path)
            previous = json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}
            old_counts: dict[tuple[str, str], int] = {}
            for old in previous.get("checklists", []):
                old_id = str(old.get("id") or "")
                old_counts[(old_id, "")] = len(old.get("history") or [])
                for item in self.all_items(old):
                    old_counts[(old_id, str(item.get("id") or ""))] = len(item.get("history") or [])
            collection["updated_at"] = _checklist_utc_now()
            self._validate(collection)
            self._validate_immutable(previous, collection)
            _write_checklist_json(path, collection)
            # The snapshot above is the commit. History export reads that same
            # canonical snapshot even if a secondary JSONL append is unavailable.
            try:
                pending_events: list[dict[str, Any]] = []
                for checklist in collection.get("checklists", []):
                    checklist_id = str(checklist.get("id") or "")
                    holders = [("", checklist)] + [(str(item.get("id") or ""), item) for item in self.all_items(checklist)]
                    for item_id, holder in holders:
                        for event in (holder.get("history") or [])[old_counts.get((checklist_id, item_id), 0):]:
                            entry = {
                                "owner_kind": str(owner.get("owner_kind") or "chat"),
                                "chat_id": str(owner.get("chat_id") or ""),
                                "agent_id": str(owner.get("agent_id") or ""),
                                "task_run_id": int(owner.get("task_run_id") or 0),
                                "checklist_id": checklist_id,
                                "checklist_name": str(checklist.get("name") or ""),
                                **event,
                            }
                            pending_events.append(entry)
                for entry in sorted(pending_events, key=lambda row: str(row.get("timestamp") or "")):
                    _append_checklist_jsonl(self._history_path(owner), entry)
            except Exception as exc:
                _best_effort_lifecycle_log(self.storage, "checklist.history_mirror_failed", {
                    "path": str(path), "error": f"{type(exc).__name__}: {exc}",
                })

    def _append_event(
        self,
        owner: dict[str, Any],
        checklist: dict[str, Any],
        item: Optional[dict[str, Any]],
        *,
        actor: str,
        prior_state: str = "",
        new_state: str = "",
        comment: str = "",
        event: str = "state_change",
        prior_text: str = "",
        new_text: str = "",
        review_cycle: Optional[int] = None,
    ) -> dict[str, Any]:
        timestamp = _checklist_utc_now()
        entry = {
            "schema": CHECKLIST_HISTORY_SCHEMA,
            "timestamp": timestamp,
            "owner_kind": str(owner.get("owner_kind") or "chat"),
            "chat_id": str(owner.get("chat_id") or ""),
            "agent_id": str(owner.get("agent_id") or ""),
            "task_run_id": int(owner.get("task_run_id") or 0),
            "checklist_id": str(checklist.get("id") or ""),
            "checklist_name": str(checklist.get("name") or ""),
            "review_cycle": int(checklist.get("review_cycle") or 0) if review_cycle is None else int(review_cycle),
            "actor": str(actor or "velox"),
            "event": str(event or "state_change"),
            "item_id": str(item.get("id") or "") if item is not None else "",
            "prior_state": str(prior_state or ""),
            "new_state": str(new_state or ""),
            "comment": _clean_checklist_text(comment, maximum=20000),
        }
        if prior_text:
            entry["prior_text"] = prior_text
        if new_text:
            entry["new_text"] = new_text
        if item is not None:
            item.setdefault("history", []).append({
                key: value for key, value in entry.items()
                if key not in ("owner_kind", "chat_id", "agent_id", "task_run_id", "checklist_id", "checklist_name")
            })
            item["updated_at"] = timestamp
        else:
            checklist.setdefault("history", []).append({
                key: value for key, value in entry.items()
                if key not in ("owner_kind", "chat_id", "agent_id", "task_run_id", "checklist_id", "checklist_name")
            })
        checklist["updated_at"] = timestamp
        # Persisted by _save only after the entire state transition commits.
        return entry

    @staticmethod
    def _checklist(collection: dict[str, Any], checklist_id: str) -> dict[str, Any]:
        wanted = str(checklist_id or "").strip()
        for checklist in collection.get("checklists", []):
            if str(checklist.get("id") or "") == wanted:
                return checklist
        raise ValueError(f"Unknown checklist_id: {wanted}")

    @staticmethod
    def _item(checklist: dict[str, Any], item_id: str) -> dict[str, Any]:
        if not isinstance(item_id, str):
            raise ValueError("item_id must be text")
        for item in ChecklistStore.all_items(checklist):
            if item["id"] == item_id:
                return item
        raise ValueError(f"Unknown item_id {item_id} in checklist {checklist.get('id')}")

    @staticmethod
    def latest_comment(item: dict[str, Any]) -> str:
        history = item.get("history") if isinstance(item.get("history"), list) else []
        for entry in reversed(history):
            if isinstance(entry, dict):
                comment = _clean_checklist_text(entry.get("comment"), maximum=20000)
                if comment:
                    return comment
        return ""

    def active(self, owner: dict[str, Any], collection: Optional[dict[str, Any]] = None) -> Optional[dict[str, Any]]:
        collection = collection if collection is not None else self.load_collection(owner, create=False)
        checklist_id = collection["active_checklist_id"]
        return self._checklist(collection, checklist_id) if checklist_id else None

    def create(self, owner: dict[str, Any], *, name: str, items: list[Any]) -> dict[str, Any]:
        self._require_enabled(owner)
        checklist_name = self._validated_name(name)
        if not isinstance(items, list) or not 1 <= len(items) <= 100:
            raise ValueError("Checklist requires 1-100 original requirements")
        texts = [self._required_text(value, "Requirement") for value in items]
        with _CHECKLIST_LOCK:
            collection = self.load_collection(owner, create=False)
            active = self.active(owner, collection)
            if active is not None:
                raise ValueError(f"Checklist {active['id']} is already active. Preserve its original requirements; use checklist_subitems_create for decomposition.")
            if owner["owner_kind"] == "chat" and self.user_stop_pending(owner):
                raise ValueError("User Stop is being saved; new Checklist creation is blocked")
            self._assert_unique_name(collection, checklist_name)
            now = _checklist_utc_now()
            checklist = {"id": "CL-" + uuid.uuid4().hex[:16], "name": checklist_name,
                "lifecycle": CHECKLIST_LIFECYCLE_OPEN,
                **{field: collection[field] for field in ("owner_kind", "chat_id", "agent_id", "task_run_id")},
                "created_at": now, "updated_at": now, "completed_at": "",
                "review_cycle": 0, "review_status": "idle", "review_agent_id": "", "review_started_at": "",
                "review_completed_at": "", "review_error": "", "review_snapshot_fingerprint": "",
                "items": [], "history": []}
            for index, text in enumerate(texts, 1):
                item = {"id": f"C{index}", "text": text, "state": CHECKLIST_ITEM_NOT_STARTED,
                        "created_at": now, "updated_at": now, "history": [], "subitems": []}
                checklist["items"].append(item)
                self._append_event(owner, checklist, item, actor="implementer", event="created",
                    new_state=CHECKLIST_ITEM_NOT_STARTED, comment="Original requirement fixed at Checklist creation.")
            collection["checklists"].append(checklist)
            collection["active_checklist_id"] = checklist["id"]
            self._append_event(owner, checklist, None, actor="implementer", event="created",
                comment=f'Created fixed requirements Checklist "{checklist_name}".')
            self._save(owner, collection)
            return self.compact_checklist(checklist)

    def update_items(self, owner: dict[str, Any], checklist_id: str, updates: list[Any], *, actor: str = "implementer") -> dict[str, Any]:
        if actor != "implementer":
            raise ValueError("Only independent apply_review can set verified")
        if not isinstance(updates, list) or not 1 <= len(updates) <= 100:
            raise ValueError("updates requires 1-100 item changes")
        with _CHECKLIST_LOCK:
            collection = self.load_collection(owner, create=False)
            checklist = self._mutable_checklist(owner, collection, checklist_id)
            normalized, seen = [], set()
            for update in updates:
                if not isinstance(update, dict) or set(update) != {"item_id", "state", "comment"}:
                    raise ValueError("Each update requires exactly item_id, state and comment")
                item = self._item(checklist, update["item_id"])
                if item["id"] in seen:
                    raise ValueError("An update batch cannot repeat an item_id")
                seen.add(item["id"])
                state = update["state"]
                if not isinstance(state, str) or state not in CHECKLIST_IMPLEMENTER_STATES:
                    raise ValueError("Use only not_started, in_progress or done; verified belongs to the independent Reviewer")
                comment = self._required_text(update["comment"], "Progress comment")
                allowed = {CHECKLIST_ITEM_NOT_STARTED: {CHECKLIST_ITEM_NOT_STARTED, CHECKLIST_ITEM_IN_PROGRESS, CHECKLIST_ITEM_DONE},
                           CHECKLIST_ITEM_IN_PROGRESS: {CHECKLIST_ITEM_IN_PROGRESS, CHECKLIST_ITEM_DONE},
                           CHECKLIST_ITEM_DONE: {CHECKLIST_ITEM_DONE, CHECKLIST_ITEM_IN_PROGRESS},
                           CHECKLIST_ITEM_VERIFIED: {CHECKLIST_ITEM_IN_PROGRESS}}
                if state not in allowed[item["state"]]:
                    raise ValueError(f"Invalid implementer transition {item['state']} -> {state}; reopen with evidence using in_progress")
                normalized.append((item, state, comment))
            # Validate the final batch before changing any states/history. Children
            # commit first, so callers need not encode parent/child JSON ordering.
            final = {item["id"]: state for item, state, _ in normalized}
            for parent in checklist["items"]:
                if final.get(parent["id"]) == CHECKLIST_ITEM_DONE and any(
                        final.get(child["id"], child["state"]) not in (CHECKLIST_ITEM_DONE, CHECKLIST_ITEM_VERIFIED)
                        for child in parent["subitems"]):
                    raise ValueError(f"Complete every sub-item of {parent['id']} before marking the parent done")
            for item, state, comment in sorted(normalized, key=lambda row: "subitems" in row[0]):
                old = item["state"]
                if state == old and comment == self.latest_comment(item):
                    continue
                item["state"] = state
                self._append_event(owner, checklist, item, actor=actor, prior_state=old, new_state=state,
                                   comment=comment, event="state_change")
            for parent in checklist["items"]:
                unfinished = [child for child in parent["subitems"] if child["state"] not in (CHECKLIST_ITEM_DONE, CHECKLIST_ITEM_VERIFIED)]
                started = any(child["state"] != CHECKLIST_ITEM_NOT_STARTED for child in parent["subitems"])
                if (unfinished and parent["state"] in (CHECKLIST_ITEM_DONE, CHECKLIST_ITEM_VERIFIED)) or (started and parent["state"] == CHECKLIST_ITEM_NOT_STARTED):
                    old = parent["state"]
                    parent["state"] = CHECKLIST_ITEM_IN_PROGRESS
                    self._append_event(owner, checklist, parent, actor="velox", prior_state=old,
                        new_state=CHECKLIST_ITEM_IN_PROGRESS, event="subitem_progress",
                        comment=("Requirement reopened because sub-item work is incomplete: " + ", ".join(child["id"] for child in unfinished)
                                 if old != CHECKLIST_ITEM_NOT_STARTED else "Sub-item implementation started; requirement acceptance remains outstanding."))
            checklist["review_status"] = REVIEW_IDLE
            checklist["review_error"] = ""
            checklist["review_snapshot_fingerprint"] = ""
            self._save(owner, collection)
            return self.compact_checklist(checklist)

    def _user_stop_path(self, owner: dict[str, Any]) -> Path:
        return self._collection_path(owner).with_name("checklists_user_stop.json")

    def _read_user_stop(self, owner: dict[str, Any]) -> dict[str, str] | None:
        path = self._user_stop_path(owner)
        try:
            raw = json.loads(path.read_text(encoding="utf-8"))
        except FileNotFoundError:
            return None
        if (not isinstance(raw, dict) or raw.get("schema") != "checklist_user_stop.v303"
                or raw.get("chat_id") != owner.get("chat_id")
                or not isinstance(raw.get("stop_id"), str) or not raw["stop_id"]
                or not isinstance(raw.get("stopped_at"), str) or not raw["stopped_at"]):
            raise ValueError("Invalid pending user Checklist cancellation")
        return raw

    def user_stop_pending(self, owner: dict[str, Any]) -> bool:
        """An intent whose canonical commit is missing must block a new message."""
        with _CHECKLIST_LOCK:
            intent = self._read_user_stop(owner)
            if intent is None:
                return False
            collection = self.load_collection(owner, create=False)
            return intent["stop_id"] != collection.get("last_user_stop_id")

    def cancel_open_by_user(self, owner: dict[str, Any], *, recover: bool = False) -> list[str]:
        """Stop the sole open Chat Checklist without changing its item evidence."""
        if owner.get("owner_kind") != "chat" or owner.get("agent_id"):
            raise ValueError("Chat Stop requires a Chat Checklist owner")
        with _CHECKLIST_LOCK:
            collection = self.load_collection(owner, create=False)
            intent_path = self._user_stop_path(owner)
            intent = self._read_user_stop(owner)
            if recover and intent is None:
                return []
            already_committed = intent is not None and intent["stop_id"] == collection.get("last_user_stop_id")
            if recover and already_committed:
                # An unlinked intent is cleanup, not permission to cancel fresh work.
                try:
                    intent_path.unlink(missing_ok=True)
                except OSError:
                    pass
                return []
            if intent is None or already_committed:
                intent = {"schema": "checklist_user_stop.v303", "chat_id": str(owner["chat_id"]),
                          "stop_id": uuid.uuid4().hex, "stopped_at": _checklist_utc_now()}
                with DATA_ROOTS.lock_for_path(intent_path):
                    _require_durable_owner(intent_path)
                    _write_checklist_json(intent_path, intent)
            now = intent["stopped_at"]
            reviewer_ids: list[str] = []
            for checklist in collection.get("checklists", []):
                if checklist.get("lifecycle") != CHECKLIST_LIFECYCLE_OPEN:
                    continue
                checklist["lifecycle"] = CHECKLIST_LIFECYCLE_CANCELLED_BY_USER
                checklist["cancelled_at"] = now
                checklist["cancellation_reason"] = "Cancelled by user"
                if checklist.get("review_status") in REVIEW_ACTIVE:
                    reviewer_id = str(checklist.get("review_agent_id") or "")
                    if reviewer_id and reviewer_id not in reviewer_ids:
                        reviewer_ids.append(reviewer_id)
                    checklist["review_status"] = REVIEW_CANCELLED
                    checklist["review_completed_at"] = now
                    checklist["review_error"] = "Cancelled by user"
                checklist["review_snapshot_fingerprint"] = ""
                self._append_event(
                    owner, checklist, None, actor="user", event="cancelled_by_user",
                    prior_state=CHECKLIST_LIFECYCLE_OPEN,
                    new_state=CHECKLIST_LIFECYCLE_CANCELLED_BY_USER,
                    comment="Cancelled by user: Stop was pressed in the owning Chat. Item evidence and history were preserved.",
                )
            # The durable stop identity also fences pending mutations when Stop
            # precedes the first published Checklist.
            collection["last_user_stop_at"] = now
            collection["last_user_stop_id"] = intent["stop_id"]
            collection["active_checklist_id"] = ""
            self._save(owner, collection)
            try:
                intent_path.unlink(missing_ok=True)
            except OSError:
                pass  # Canonical stop_id makes replay safe if cleanup is denied.
            return reviewer_ids

    def prepare_verification(self, owner: dict[str, Any], checklist_id: str) -> dict[str, Any]:
        with _CHECKLIST_LOCK:
            collection = self.load_collection(owner, create=False)
            checklist = self._mutable_checklist(owner, collection, checklist_id)
            unfinished = [item for item in self.all_items(checklist) if item["state"] not in (CHECKLIST_ITEM_DONE, CHECKLIST_ITEM_VERIFIED)]
            if unfinished:
                raise ValueError("Finish every requirement and sub-item before independent review: " + ", ".join(item["id"] for item in unfinished))
            checklist["review_cycle"] += 1
            checklist["review_status"] = REVIEW_REQUESTED
            for field in ("review_agent_id", "review_started_at", "review_completed_at", "review_error"):
                checklist[field] = ""
            checklist["review_snapshot_fingerprint"] = _review_snapshot_fingerprint(self, checklist)
            self._append_event(owner, checklist, None, actor="velox", event="review_requested",
                comment="Independent review requested for the original requirements and their complete sub-item plans.",
                review_cycle=checklist["review_cycle"])
            self._save(owner, collection)
            return self.compact_checklist(checklist)

    def apply_review(self, owner: dict[str, Any], checklist_id: str, verdicts: list[Any], *, review_cycle: Optional[int] = None) -> dict[str, Any]:
        if not isinstance(verdicts, list):
            raise ValueError("Reviewer verdicts must be a list")
        with _CHECKLIST_LOCK:
            collection = self.load_collection(owner, create=False)
            checklist = self._checklist(collection, checklist_id)
            if checklist["lifecycle"] != CHECKLIST_LIFECYCLE_OPEN or collection["active_checklist_id"] != checklist_id:
                raise ValueError("Only the active Checklist can receive independent Reviewer verdicts")
            items = self.all_items(checklist)
            if any(item["state"] not in (CHECKLIST_ITEM_DONE, CHECKLIST_ITEM_VERIFIED) for item in items):
                raise ValueError("Reviewer verdicts require every requirement and sub-item to be done or verified")
            if review_cycle is not None and (type(review_cycle) is not int or review_cycle != checklist["review_cycle"]):
                raise ValueError("Reviewer cycle no longer matches the requested Checklist review")
            if checklist["review_status"] not in REVIEW_ACTIVE:
                raise ValueError("Reviewer verdicts require an active requested review")
            if not checklist["review_snapshot_fingerprint"] or checklist["review_snapshot_fingerprint"] != _review_snapshot_fingerprint(self, checklist):
                raise ValueError("Checklist evidence changed while its independent Reviewer was running")
            if [row.get("item_id") for row in verdicts if isinstance(row, dict)] != [item["id"] for item in items] or len(verdicts) != len(items):
                raise ValueError("Return exactly one verdict for every requirement and sub-item in stable parent-first order")
            normalized = {}
            for verdict in verdicts:
                if not isinstance(verdict, dict) or verdict.get("verdict") not in ("pass", "fail"):
                    raise ValueError("Each Reviewer verdict requires pass or fail")
                comment = self._required_text(verdict.get("comment"), "Reviewer comment")
                normalized[verdict["item_id"]] = {"item_id": verdict["item_id"], "verdict": verdict["verdict"],
                    "comment": comment, "next_step": str(verdict.get("next_step") or "")}
            # A passing parent cannot hide a failing implementation step. Keep the
            # Reviewer failure and explicitly record the dependent parent failure.
            for parent in checklist["items"]:
                failed = [child for child in parent["subitems"] if normalized[child["id"]]["verdict"] == "fail"]
                if failed and normalized[parent["id"]]["verdict"] == "pass":
                    row = normalized[parent["id"]]
                    row["verdict"] = "fail"
                    row["comment"] = "Parent acceptance withheld because its sub-items failed independent review: " + ", ".join(child["id"] for child in failed) + ". " + row["comment"]
                    row["next_step"] = "Repair the failed sub-items, recheck the complete requirement, and request independent review."
            for item in items:
                verdict = normalized[item["id"]]
                old = item["state"]
                item["state"] = CHECKLIST_ITEM_VERIFIED if verdict["verdict"] == "pass" else CHECKLIST_ITEM_IN_PROGRESS
                self._append_event(owner, checklist, item, actor="reviewer", prior_state=old, new_state=item["state"],
                    comment=verdict["comment"], event="review_pass" if verdict["verdict"] == "pass" else "review_fail",
                    review_cycle=checklist["review_cycle"])
            failed = any(row["verdict"] == "fail" for row in normalized.values())
            checklist["review_status"] = REVIEW_FAILED if failed else REVIEW_PASSED
            checklist["review_completed_at"] = _checklist_utc_now()
            checklist["review_error"] = ""
            self._append_event(owner, checklist, None, actor="reviewer", event="review_completed",
                comment="Independent review requires repairs." if failed else "Independent Reviewer accepted all requirements and sub-items.")
            if not failed:
                self._complete_verified_locked(owner, collection, checklist)
            self._save(owner, collection)
            return {**self.compact_checklist(checklist), "review_verdicts": list(normalized.values())}

    def _complete_verified_locked(self, owner: dict[str, Any], collection: dict[str, Any], checklist: dict[str, Any]) -> None:
        if any(item["state"] != CHECKLIST_ITEM_VERIFIED for item in self.all_items(checklist)):
            raise ValueError("All requirements and sub-items must be independently verified before completion")
        checklist["lifecycle"] = CHECKLIST_LIFECYCLE_COMPLETED
        checklist["completed_at"] = _checklist_utc_now()
        collection["active_checklist_id"] = ""
        self._append_event(owner, checklist, None, actor="reviewer", event="completed",
            comment="The original requirements and every sub-item passed independent verification.")

    def counts(self, checklist: dict[str, Any]) -> dict[str, int]:
        return self._counts_for(checklist["items"])

    def compact_checklist(self, checklist: dict[str, Any], *, collection: Optional[dict[str, Any]] = None) -> dict[str, Any]:
        fields = ("name", "lifecycle", "created_at", "updated_at", "completed_at", "cancelled_at", "cancellation_reason",
                  "review_cycle", "review_status", "review_agent_id", "review_started_at", "review_completed_at",
                  "review_error", "review_snapshot_fingerprint")
        result = {field: checklist.get(field, "") for field in fields}
        result.update({"schema": "checklist_status.v303", "checklist_id": checklist["id"],
            "display_name": checklist_display_label(checklist["name"], checklist["created_at"]),
            "counts": self.counts(checklist),
            "subitem_counts": self._counts_for([child for item in checklist["items"] for child in item["subitems"]]),
            "items": [self._compact_item(item) for item in checklist["items"]],
            "history": copy.deepcopy(checklist["history"])})
        return result

    def list_checklists(self, owner: dict[str, Any], *, include_completed: bool = False) -> dict[str, Any]:
        collection = self.load_collection(owner, create=False)
        rows = []
        for checklist in collection["checklists"]:
            if not include_completed and checklist["lifecycle"] != CHECKLIST_LIFECYCLE_OPEN:
                continue
            rows.append({"checklist_id": checklist["id"], "name": checklist["name"],
                "display_name": checklist_display_label(checklist["name"], checklist["created_at"]),
                "lifecycle": checklist["lifecycle"], "active": checklist["id"] == collection["active_checklist_id"],
                "counts": self.counts(checklist),
                "subitem_counts": self._counts_for([child for item in checklist["items"] for child in item["subitems"]]),
                "created_at": checklist["created_at"], "updated_at": checklist["updated_at"]})
        return {"schema": "checklist_list.v303", "active_checklist_id": collection["active_checklist_id"], "checklists": rows}

    def status(self, owner: dict[str, Any], checklist_id: str = "", *, include_history: bool = False) -> dict[str, Any]:
        collection = self.load_collection(owner, create=False)
        checklist = self._checklist(collection, checklist_id) if checklist_id else self.active(owner, collection)
        if checklist is None:
            return {"schema": "checklist_status.v303", "active": False, "message": "No active Checklist."}
        result = self.compact_checklist(checklist)
        result["active"] = checklist["id"] == collection["active_checklist_id"]
        if include_history:
            result["items"] = [self._compact_item(item, include_history=True) for item in checklist["items"]]
        return result

    def continuation_prompt(self, owner: dict[str, Any]) -> str:
        if not self.enabled(owner):
            return ""
        with _CHECKLIST_LOCK:
            collection = self.load_collection(owner, create=False)
            checklist = self.active(owner, collection)
            if checklist is None:
                return ""
            if checklist["review_status"] in REVIEW_ACTIVE:
                return ""  # The requested independent Reviewer currently owns the work.
            unfinished = [item for item in self.all_items(checklist) if item["state"] not in (CHECKLIST_ITEM_DONE, CHECKLIST_ITEM_VERIFIED)]
            if not unfinished:
                if checklist["review_status"] in (REVIEW_ERROR, REVIEW_CANCELLED):
                    return ""  # Infrastructure failure is visible; do not loop failed reviews.
                action = f"Call verify_checklist(checklist_id={checklist['id']!r}) for independent acceptance."
            else:
                # Prefer incomplete steps before their parent acceptance check.
                steps = [item for item in unfinished if "subitems" not in item]
                candidates = steps or unfinished
                item = next((row for row in candidates if row["state"] == CHECKLIST_ITEM_IN_PROGRESS), candidates[0])
                action = f"Next actionable candidate: {item['id']} - {item['text']}. "
                action += ("For a non-trivial requirement without sub-items, attach its complete mini-plan once with checklist_subitems_create before implementing. "
                           "Work existing sub-items directly. Dependencies may require a different item; record the blocker and continue other actionable work. "
                           "Take the next concrete action, inspect its result, and update factual progress. "
                           "All sub-items must be done before marking their parent done; finishing steps alone does not establish acceptance. "
                           "Repair observed runtime/test/visual defects and recheck the actual artifact. "
                           "A claimed tool/environment blocker requires direct evidence; reproduce the exact failing command before treating a hypothesis as fact.")
            return ("CHECKLISTS - CONTINUE\n\n" + self._task_memory_for(checklist) + "\n\n" + action +
                    "\nPreserve the original requirements and all existing sub-item wording/order. Do not replace or abandon this Checklist or report final success while it remains open.")

    def task_memory(self, owner: dict[str, Any]) -> str:
        if not self.enabled(owner):
            return ""
        checklist = self.active(owner)
        return self._task_memory_for(checklist) if checklist else ""

    def history_reports(self, owner: dict[str, Any]) -> list[dict[str, Any]]:
        collection = self.load_collection(owner, create=False)
        reports = []
        for checklist in reversed(collection["checklists"]):
            report = self.compact_checklist(checklist)
            report["active"] = checklist["id"] == collection["active_checklist_id"]
            report["full_item_history"] = {item["id"]: copy.deepcopy(item["history"]) for item in self.all_items(checklist)}
            reports.append(report)
        return reports


    def ui_snapshot(self, owner: dict[str, Any], previous: dict[str, Any] | None = None) -> dict[str, Any]:
        """Detached read-only presentation snapshot, reused while canonical bytes are unchanged.

        Called on a worker by the UI. This does not change persistence or execution.
        A single collection read supplies selector entries, progress and nested rows.
        """
        path = self._collection_path(owner)
        with _CHECKLIST_LOCK:
            _require_durable_owner(path)
            try:
                stat = path.stat()
                signature = (str(path), stat.st_mtime_ns, stat.st_size, stat.st_ino)
            except FileNotFoundError:
                signature = (str(path), None)
            owner_key = tuple(owner.get(key) for key in ("owner_kind", "chat_id", "agent_id", "task_run_id"))
            if previous is not None and previous.get("_signature") == signature and previous.get("_owner") == owner_key:
                return previous
            collection = self.load_collection(owner, create=False)
            rows = []
            for checklist in collection["checklists"]:
                row = self.compact_checklist(checklist)
                row.pop("history", None)
                row["active"] = checklist["id"] == collection["active_checklist_id"]
                rows.append(row)
            return {"_signature": signature, "_owner": owner_key,
                    "active_checklist_id": collection["active_checklist_id"], "checklists": rows}

    @staticmethod
    def _required_text(value: Any, label: str, *, maximum: int = 20000) -> str:
        if not isinstance(value, str) or not value.strip():
            raise ValueError(f"{label} requires non-empty text")
        value = value.strip()
        if len(value) > maximum:
            raise ValueError(f"{label} must contain at most {maximum} characters")
        return value

    @staticmethod
    def all_items(checklist: dict[str, Any]) -> list[dict[str, Any]]:
        """Stable parent-first order shared by persistence, review and reporting."""
        return [row for item in checklist["items"] for row in (item, *item["subitems"])]

    @staticmethod
    def _parent_item(checklist: dict[str, Any], item_id: str) -> Optional[dict[str, Any]]:
        return next((item for item in checklist["items"]
                     if any(child["id"] == item_id for child in item["subitems"])), None)

    def _validate_immutable(self, previous: dict[str, Any], collection: dict[str, Any]) -> None:
        """All writers, including review/recovery, preserve the original contract."""
        if not previous:
            return
        self._validate(previous)
        for field in ("schema", "owner_kind", "chat_id", "agent_id", "task_run_id", "created_at"):
            if previous[field] != collection[field]:
                raise ValueError(f"Checklist collection {field} is immutable")
        old_lists, new_lists = previous["checklists"], collection["checklists"]
        if [row["id"] for row in new_lists[:len(old_lists)]] != [row["id"] for row in old_lists]:
            raise ValueError("Checklist history cannot be deleted, reordered or replaced")
        def unchanged(old: dict[str, Any], new: dict[str, Any], fields: tuple[str, ...]) -> None:
            if any(old[field] != new[field] for field in fields):
                raise ValueError("Checklist requirement/sub-item wording, identity and order are immutable")
            history = old["history"]
            if new["history"][:len(history)] != history:
                raise ValueError("Checklist history is append-only")
        for old, new in zip(old_lists, new_lists):
            unchanged(old, new, ("id", "name", "owner_kind", "chat_id", "agent_id", "task_run_id", "created_at"))
            if len(old["items"]) != len(new["items"]):
                raise ValueError("The original requirement list is fixed; create sub-items instead")
            for old_item, new_item in zip(old["items"], new["items"]):
                unchanged(old_item, new_item, ("id", "text", "created_at"))
                if old_item["subitems"]:
                    if len(old_item["subitems"]) != len(new_item["subitems"]):
                        raise ValueError("Sub-items may be attached only once, as one complete list")
                    for old_child, new_child in zip(old_item["subitems"], new_item["subitems"]):
                        unchanged(old_child, new_child, ("id", "text", "created_at"))

    def _mutable_checklist(self, owner: dict[str, Any], collection: dict[str, Any], checklist_id: str) -> dict[str, Any]:
        self._require_enabled(owner)
        checklist = self._checklist(collection, checklist_id)
        if checklist["lifecycle"] != CHECKLIST_LIFECYCLE_OPEN or collection["active_checklist_id"] != checklist_id:
            raise ValueError("Only the context's one active Checklist can be updated")
        if checklist["review_status"] in REVIEW_ACTIVE:
            raise ValueError("An independent Reviewer owns this Checklist until its review finishes")
        if owner["owner_kind"] == "chat" and self.user_stop_pending(owner):
            raise ValueError("User Stop is being saved; Checklist mutations are blocked")
        return checklist

    def create_subitems(self, owner: dict[str, Any], checklist_id: str, item_id: str, items: list[Any]) -> dict[str, Any]:
        if not isinstance(items, list) or not 1 <= len(items) <= 100:
            raise ValueError("Supply the complete 1-100 step sub-item list in one call")
        texts = [self._required_text(value, "Sub-item") for value in items]
        with _CHECKLIST_LOCK:
            collection = self.load_collection(owner, create=False)
            checklist = self._mutable_checklist(owner, collection, checklist_id)
            parent = self._item(checklist, item_id)
            if "subitems" not in parent:
                raise ValueError("Only original requirements can have sub-items; nesting is not supported")
            if parent["subitems"]:
                raise ValueError(f"{item_id} already has its immutable sub-item list; update its states/comments instead")
            if parent["state"] not in (CHECKLIST_ITEM_NOT_STARTED, CHECKLIST_ITEM_IN_PROGRESS):
                raise ValueError("Reopen the requirement with factual evidence before adding its first sub-item plan")
            now = _checklist_utc_now()
            for index, text in enumerate(texts, 1):
                child = {"id": f"{item_id}.{index}", "text": text, "state": CHECKLIST_ITEM_NOT_STARTED,
                         "created_at": now, "updated_at": now, "history": []}
                parent["subitems"].append(child)
                self._append_event(owner, checklist, child, actor="implementer", event="subitem_created",
                    new_state=CHECKLIST_ITEM_NOT_STARTED, comment=f"Implementation step for requirement {item_id}; wording and order are fixed.")
            self._append_event(owner, checklist, parent, actor="implementer", event="subitems_created",
                prior_state=parent["state"], new_state=parent["state"],
                comment=f"Attached the one-time implementation plan of {len(texts)} sub-items. Original requirement is unchanged.")
            self._save(owner, collection)
            return self.compact_checklist(checklist)

    @staticmethod
    def _counts_for(items: list[dict[str, Any]]) -> dict[str, int]:
        counts = {state: 0 for state in CHECKLIST_ITEM_STATES}
        for item in items:
            counts[item["state"]] += 1
        counts["total"] = len(items)
        return counts

    def _compact_item(self, item: dict[str, Any], *, include_history: bool = False) -> dict[str, Any]:
        result = {"id": item["id"], "text": item["text"], "state": item["state"],
                  "latest_comment": self.latest_comment(item), "history_count": len(item["history"])}
        if include_history:
            result["history"] = copy.deepcopy(item["history"])
        if "subitems" in item:
            result["subitems"] = [self._compact_item(child, include_history=include_history) for child in item["subitems"]]
            result["subitem_counts"] = self._counts_for(item["subitems"])
            result["subitems_created"] = bool(item["subitems"])
        return result

    def _task_memory_for(self, checklist: dict[str, Any]) -> str:
        lines = ["CURRENT CHECKLIST STATE", f"Checklist: {checklist['name']} [{checklist['id']}]",
                 "Original requirements are immutable; sub-items are fixed implementation steps, not replacement acceptance criteria."]
        for parent in checklist["items"]:
            lines.append(f"- {parent['id']} [{parent['state']}]: {parent['text']}")
            comment = self.latest_comment(parent)
            if comment:
                lines.append("  Latest comment: " + comment)
            for child in parent["subitems"]:
                lines.append(f"  - {child['id']} [{child['state']}]: {child['text']}")
                comment = self.latest_comment(child)
                if comment:
                    lines.append("    Latest comment: " + comment)
        return "\n".join(lines)


# Capture execution methods before installing collection-backed presentation.
_EXPERT_EXECUTION_STORE = ExpertModeStore
_EXPERT_CONTINUATION_BASE = getattr(ExpertModeStore, "continuation_prompt", None)
_EXPERT_TASK_MEMORY_BASE_DESCRIPTOR = ExpertModeStore.__dict__.get("task_memory_content")
_EXPERT_PROGRESS_BASE_DESCRIPTOR = ExpertModeStore.__dict__.get("progress_snapshot")
_EXPERT_HISTORY_BASE = getattr(ExpertModeStore, "history", None)


def _checklist_owner_from_bound(bound: dict[str, Any], state: Optional[dict[str, Any]] = None) -> dict[str, Any]:
    state = state or {}
    return {
        "owner_kind": str(bound.get("owner_kind") or state.get("owner_kind") or ("agent" if bound.get("agent_id") or state.get("agent_id") else "chat")),
        "chat_id": str(bound.get("chat_id") or state.get("chat_id") or ""),
        "agent_id": str(bound.get("agent_id") or state.get("agent_id") or ""),
        "task_run_id": int(bound.get("task_run_id") or state.get("task_run_id") or 0),
    }


def _canonical_checklists(store: Any) -> tuple[ChecklistStore, dict[str, Any]]:
    """Bind a read-only runtime facade to its canonical Chat/Agent Checklist store."""
    owner = {
        "owner_kind": str(_expert_owner_value(store, "owner_kind", default="chat")),
        "chat_id": str(_expert_owner_value(store, "chat_id", "source_chat_id")),
        "agent_id": str(_expert_owner_value(store, "agent_id")),
        "task_run_id": int(_expert_owner_value(store, "task_run_id", default=0) or 0),
    }
    return ChecklistStore(store.storage), owner


def _load_expert_checklist_adapter(self: Any, *args: Any, **kwargs: Any) -> Any:
    manager, owner = _canonical_checklists(self)
    return manager.execution_state(owner)


ExpertModeStore.load = _load_expert_checklist_adapter


def _expert_checklist_continuation(self: Any, *args: Any, **kwargs: Any) -> str:
    manager, owner = _canonical_checklists(self)
    return manager.continuation_prompt(owner)


if _EXPERT_CONTINUATION_BASE is not None:
    ExpertModeStore.continuation_prompt = _expert_checklist_continuation


# Existing class/instance UI descriptors consume a read-only projection of the
# one canonical Checklist. No execution state is mirrored to another file.
if _EXPERT_TASK_MEMORY_BASE_DESCRIPTOR is not None:
    setattr(ExpertModeStore, "task_memory_content", _EXPERT_TASK_MEMORY_BASE_DESCRIPTOR)
if _EXPERT_PROGRESS_BASE_DESCRIPTOR is not None:
    setattr(ExpertModeStore, "progress_snapshot", _EXPERT_PROGRESS_BASE_DESCRIPTOR)


def _expert_checklist_history(self: Any, *args: Any, **kwargs: Any) -> Any:
    manager, owner = _canonical_checklists(self)
    reports = manager.history_reports(owner)
    # The execution adapter keeps the parent-oriented UI contract. The canonical
    # nested records/history are included in the shared presentation projection.
    return [{
        "schema": "checklist_history_report.v303",
        "status": "active" if report["lifecycle"] == CHECKLIST_LIFECYCLE_OPEN else
                  "succeeded" if report["lifecycle"] == CHECKLIST_LIFECYCLE_COMPLETED else report["lifecycle"],
        "name": report["name"], "title": report["name"], "checklist_id": report["checklist_id"],
        "created_at": report["created_at"], "updated_at": report["updated_at"],
        "completed_at": report["completed_at"], "review_cycle": report["review_cycle"],
        "requirements": [{"id": item["id"], "requirement": item["text"], "state": item["state"],
            "status": item["state"], "progress": item["latest_comment"],
            "next_step": item["latest_comment"] if item["state"] == CHECKLIST_ITEM_IN_PROGRESS else "",
            "subitems": item["subitems"]} for item in report["items"]],
        "items": report["items"], "item_history": report["full_item_history"], "active": report["active"],
    } for report in reports]


if _EXPERT_HISTORY_BASE is not None:
    ExpertModeStore.history = _expert_checklist_history



class ChecklistStatisticsCache:
    """Worker-only, incremental counts for all durable Chat and Agent Checklists.

    Every collection is counted once, including completed/cancelled history and
    prior Agent runs. Cache entries retain counts only, not large item histories.
    The UI schedules one scan at a time and never performs these disk reads.
    """
    FIELDS = ("checklists", "active", "completed", "cancelled", "requirements", "subitems", "planned_requirements")

    def __init__(self, storage: Storage) -> None:
        self.storage = storage
        self._files: dict[str, tuple[tuple[int, int], dict[str, int]]] = {}

    @staticmethod
    def collection_counts(collection: dict[str, Any]) -> dict[str, int]:
        result = dict.fromkeys(ChecklistStatisticsCache.FIELDS, 0)
        for checklist in collection.get("checklists", []):
            result["checklists"] += 1
            lifecycle = checklist["lifecycle"]
            result["active"] += int(lifecycle == CHECKLIST_LIFECYCLE_OPEN)
            result["completed"] += int(lifecycle == CHECKLIST_LIFECYCLE_COMPLETED)
            result["cancelled"] += int(lifecycle == CHECKLIST_LIFECYCLE_CANCELLED_BY_USER)
            for item in checklist["items"]:
                result["requirements"] += 1
                result["subitems"] += len(item["subitems"])
                result["planned_requirements"] += int(bool(item["subitems"]))
        return result

    def read(self) -> dict[str, Any]:
        paths = self.storage.paths
        manager = ChecklistStore(self.storage)
        candidates = list(paths.chats_dir().glob("chat_*/checklists.json"))
        candidates += list(paths.agents_dir().glob("agent_*/checklists_*.json"))
        next_files: dict[str, tuple[tuple[int, int], dict[str, int]]] = {}
        totals = dict.fromkeys(self.FIELDS, 0)
        for path in sorted(set(candidates)):
            try:
                with _CHECKLIST_LOCK, DATA_ROOTS.lock_for_path(path):
                    if path.is_symlink() or path.parent.is_symlink():
                        raise ValueError(f"Checklist statistics cannot follow symbolic links: {path}")
                    _require_durable_owner(path)
                    stat = path.stat()
                    signature = (stat.st_mtime_ns, stat.st_size)
                    key = str(path)
                    cached = self._files.get(key)
                    if cached and cached[0] == signature:
                        counts = cached[1]
                    else:
                        collection = json.loads(path.read_text(encoding="utf-8"))
                        manager._validate(collection)
                        owner = {field: collection[field] for field in ("owner_kind", "chat_id", "agent_id", "task_run_id")}
                        if manager._collection_path(owner).resolve() != path.resolve():
                            raise ValueError(f"Checklist statistics owner/path mismatch: {path}")
                        expected = manager._empty(owner)
                        if any(collection[field] != expected[field] for field in owner):
                            raise ValueError(f"Checklist statistics owner mismatch: {path}")
                        counts = self.collection_counts(collection)
                    next_files[key] = (signature, counts)
                for field in self.FIELDS:
                    totals[field] += counts[field]
            except FileNotFoundError:
                # Deletion between enumeration and the owner lock is not an empty
                # or erroneous Checklist; it no longer belongs to this snapshot.
                continue
        # Publish only a complete successful scan. Corruption does not silently
        # become a plausible partial average; the Dashboard exposes the error.
        self._files = next_files
        lists = totals["checklists"]
        requirements = totals["requirements"]
        return {**totals, "status": "ready",
                "avg_requirements": totals["requirements"] / lists if lists else None,
                "avg_subitems": totals["subitems"] / lists if lists else None,
                "avg_subitems_per_requirement": totals["subitems"] / requirements if requirements else None,
                "planned_percent": 100.0 * totals["planned_requirements"] / requirements if requirements else None}


# Generic tool handlers --------------------------------------------------------

def _expert_tool_payload(self: Any, payload: dict[str, Any]) -> Any:
    # Native tools throughout Velox accept dictionaries. Keep this path generic
    # rather than creating a checklist-specific result wrapper.
    return payload


def _tool_checklist_create(self: Any, *args: Any, **kwargs: Any) -> Any:
    context, arguments = _parse_tool_handler_call(args, kwargs)
    if set(arguments) != {"name", "items"}:
        raise ValueError("checklist_create requires exactly name and items; Checklist parenting is not supported")
    owner = _checklist_owner_from_context(context, arguments)
    result = ChecklistStore(self.storage).create(owner, name=arguments["name"], items=arguments["items"])
    return {"action": "created", **result, "next_action": (
        "Before implementation, use checklist_subitems_create(checklist_id, item_id, items) "
        "for each non-trivial requirement. Supply its complete implementation-step mini-plan "
        "once; the steps then stay fixed within this same Checklist. Only genuinely trivial "
        "requirements may omit steps. Work through the steps, recording factual progress "
        "and validation evidence, then assess the full parent requirement."
    )}


def _tool_checklist_subitems_create(self: Any, *args: Any, **kwargs: Any) -> Any:
    context, arguments = _parse_tool_handler_call(args, kwargs)
    if set(arguments) != {"checklist_id", "item_id", "items"}:
        raise ValueError("checklist_subitems_create requires exactly checklist_id, item_id and items")
    owner = _checklist_owner_from_context(context, arguments)
    result = ChecklistStore(self.storage).create_subitems(owner, arguments["checklist_id"], arguments["item_id"], arguments["items"])
    return {"action": "subitems_created", **result}


def _tool_checklist_item_update(self: Any, *args: Any, **kwargs: Any) -> Any:
    context, arguments = _parse_tool_handler_call(args, kwargs)
    if set(arguments) != {"checklist_id", "updates"}:
        raise ValueError("checklist_item_update requires exactly checklist_id and updates")
    owner = _checklist_owner_from_context(context, arguments)
    result = ChecklistStore(self.storage).update_items(owner, arguments["checklist_id"], arguments["updates"])
    return {"action": "updated", **result}


def _tool_checklist_status(self: Any, *args: Any, **kwargs: Any) -> Any:
    context, arguments = _parse_tool_handler_call(args, kwargs)
    owner = _checklist_owner_from_context(context, arguments)
    _reconcile_checklist_review(self.storage, owner, str(arguments.get("checklist_id") or ""))
    return _expert_tool_payload(self, ChecklistStore(self.storage).status(
        owner, str(arguments.get("checklist_id") or ""), include_history=bool(arguments.get("include_history", False)),
    ))


def _tool_checklist_list(self: Any, *args: Any, **kwargs: Any) -> Any:
    context, arguments = _parse_tool_handler_call(args, kwargs)
    owner = _checklist_owner_from_context(context, arguments)
    return _expert_tool_payload(self, ChecklistStore(self.storage).list_checklists(
        owner, include_completed=bool(arguments.get("include_completed", False)),
    ))


def _tool_checklist_resume(self: Any, *args: Any, **kwargs: Any) -> Any:
    context, arguments = _parse_tool_handler_call(args, kwargs)
    owner = _checklist_owner_from_context(context, arguments)
    return ChecklistStore(self.storage).resume_cancelled(owner, str(arguments.get("checklist_id") or ""),
        comment=arguments.get("comment"), cancel_event=getattr(context, "cancel_event", None))


ToolRegistry.tool_checklist_resume = _tool_checklist_resume
ToolRegistry.tool_checklist_create = _tool_checklist_create
ToolRegistry.tool_checklist_subitems_create = _tool_checklist_subitems_create
ToolRegistry.tool_checklist_item_update = _tool_checklist_item_update
ToolRegistry.tool_checklist_status = _tool_checklist_status
ToolRegistry.tool_checklist_list = _tool_checklist_list


def _checklist_tool_not_cancelled(context: Any) -> None:
    event = getattr(context, "cancel_event", None)
    if event is not None and event.is_set():
        raise ToolCancelledError("Checklist operation cancelled before its state change")


def _guard_checklist_mutation(handler: Any) -> Any:
    @functools.wraps(handler)
    def guarded(self: Any, *args: Any, **kwargs: Any) -> Any:
        context, _arguments = _parse_tool_handler_call(args, kwargs)
        with _CHECKLIST_LOCK:
            _checklist_tool_not_cancelled(context)
            return handler(self, *args, **kwargs)
    return guarded


for _tool_handler_name in ("tool_checklist_create", "tool_checklist_subitems_create", "tool_checklist_item_update", "tool_checklist_resume"):
    setattr(ToolRegistry, _tool_handler_name, _guard_checklist_mutation(getattr(ToolRegistry, _tool_handler_name)))

_TOOL_REGISTRY_INIT_BASE = ToolRegistry.__init__


def _register_checklist_tool(registry: Any, name: str, description: str, parameters: dict[str, Any], handler: Any) -> None:
    # ToolRegistry.register validates positional ToolArgumentSpec contracts.
    signature = tuple(TOOL_POSITIONAL_SIGNATURES.get(name, ()))
    try:
        _call_supported_arguments(registry.register, {
            "name": name,
            "description": description,
            "parameters": parameters,
            "handler": handler,
            "signature": signature,
            "positional_arguments": signature,
        })
    except TypeError:
        registry.register(name, description, parameters, handler, signature)


def _install_checklist_tools(self: Any) -> None:
    # Retired interfaces cannot provide an alternative escape from the fixed list.
    for name in (*_INTERNAL_EXPERT_TOOL_NAMES, "checklist_item_add", "checklist_item_edit", "checklist_abandon"):
        self.tools.pop(name, None)
    item_text = {"type": "string", "minLength": 1, "maxLength": 20000}
    checklist_id = {"type": "string", "minLength": 1}
    def register(name: str, description: str, properties: dict[str, Any], required: tuple[str, ...] = ()) -> None:
        schema = {"type": "object", "properties": properties, "additionalProperties": False}
        if required:
            schema["required"] = list(required)
        _register_checklist_tool(self, name, description, schema, getattr(self, "tool_" + name))
    register("checklist_create",
        "Create the context's one fixed original requirements/acceptance Checklist. Requires no active Checklist. Name and 1-100 item texts/order are immutable. IDs C1..Cn are assigned. Preserve the full user scope, not just implementation phases.",
        {"name": {"type": "string", "minLength": 1, "maxLength": 240},
         "items": {"type": "array", "minItems": 1, "maxItems": 100, "items": item_text}}, ("name", "items"))
    register("checklist_subitems_create",
        "Attach a complete 1-100-step mini-plan ONCE to an original C# requirement. Sub-items C#.n remain in the same Checklist. No later addition, editing, replacement, deletion, reordering or grandchildren. Only progress states/comments can change. Parent acceptance text remains unchanged.",
        {"checklist_id": checklist_id, "item_id": {"type": "string", "pattern": "^C[1-9][0-9]*$"},
         "items": {"type": "array", "minItems": 1, "maxItems": 100, "items": item_text}}, ("checklist_id", "item_id", "items"))
    register("checklist_item_update",
        "Update original requirements C# or steps C#.n with factual append-only comments. All steps must be done before their parent is done; acceptance is explicit, not inferred. Reopen done/verified work with in_progress and evidence. Reopened steps reopen a finished parent. Only the independent Reviewer sets verified.",
        {"checklist_id": checklist_id, "updates": {"type": "array", "minItems": 1, "maxItems": 100,
         "items": {"type": "object", "properties": {
             "item_id": {"type": "string", "pattern": r"^C[1-9][0-9]*(?:\.[1-9][0-9]*)?$"},
             "state": {"type": "string", "enum": list(CHECKLIST_IMPLEMENTER_STATES)}, "comment": item_text},
             "required": ["item_id", "state", "comment"], "additionalProperties": False}}}, ("checklist_id", "updates"))
    register("checklist_status", "Read the active or specified Checklist, nested sub-items, counts and comments. History is read-only.",
        {"checklist_id": {"type": "string"}, "include_history": {"type": "boolean"}})
    register("checklist_list", "Read the sole active Checklist ID and owner-local Checklist history. Reading another list never changes active work.",
        {"include_completed": {"type": "boolean"}})
    register("verify_checklist", "Run a fresh independent read-only Reviewer after every requirement and sub-item is done/already verified. The same owner waits inference-inactive; failures reopen work in the same immutable list. Only all-passed review completes it.",
        {"checklist_id": checklist_id}, ("checklist_id",))
    register("checklist_resume", "Resume one user-cancelled Chat Checklist only after a new explicit user request to continue that work. Quote the request in comment. Preserves fixed requirements, steps and evidence. Another active Checklist or a pending Stop blocks resume.",
        {"checklist_id": checklist_id, "comment": item_text}, ("checklist_id", "comment"))


# Tools are installed from the existing register_builtin_tools method, preserving
# the ordinary ToolRegistry construction path.

# Ensure old adapter tools are never advertised to a model. They remain registered
# only so the established internal review lifecycle and older embedded unit seams
# can invoke them without a second system.
for _builder_name in ("build_openai_chat_completion_tools", "build_openai_tools", "build_responses_tools"):
    _original_builder = getattr(ToolRegistry, _builder_name, None)
    if not callable(_original_builder):
        continue
    def _make_builder(original: Any) -> Any:
        @functools.wraps(original)
        def filtered(self: Any, *args: Any, **kwargs: Any) -> Any:
            # Generic Checklist tools are ordinary registered tools classified as
            # execution-scoped Checklist controls. The canonical builder therefore
            # handles feature flags and excluded_names. This wrapper only strips the
            # retained expert_mode_* compatibility adapter names as a final defense.
            result = original(self, *args, **kwargs)
            if not isinstance(result, list):
                return result
            filtered_result = []
            for entry in result:
                name = ""
                if isinstance(entry, dict):
                    function = entry.get("function") if isinstance(entry.get("function"), dict) else entry
                    name = str(function.get("name") or "") if isinstance(function, dict) else ""
                if name in _INTERNAL_EXPERT_TOOL_NAMES:
                    continue
                filtered_result.append(entry)
            return filtered_result
        return filtered
    setattr(ToolRegistry, _builder_name, _make_builder(_original_builder))

# Concise model-facing Checklist language in the shared Chat/Agent tool guidance.
try:
    ContextAssembler.EXPERT_MODE_GUIDANCE = CHECKLIST_GUIDANCE
    ContextAssembler.REQUIREMENTS_GUIDANCE = CHECKLIST_GUIDANCE
except Exception:
    pass

for _prompt_owner, _prompt_name in (
    (ToolRegistry, "build_openai_tool_system_block"),
    (AgentRuntime, "build_standard_system_prompt"),
):
    _original_prompt = getattr(_prompt_owner, _prompt_name, None)
    if not callable(_original_prompt):
        continue
    def _make_prompt_wrapper(original: Any) -> Any:
        @functools.wraps(original)
        def wrapped(self: Any, *args: Any, **kwargs: Any) -> Any:
            value = original(self, *args, **kwargs)
            if not isinstance(value, str):
                return value
            replacements = {
                "expert_mode_enter": "checklist_create",
                "expert_mode_requirement_update": "checklist_item_update",
                "expert_mode_status": "checklist_status",
                "expert_mode_exit": "verify_checklist",
                "Checklist is a persistent implementation checklist": "Named Checklists are persistent structured work lists",
            }
            for old, new in replacements.items():
                value = value.replace(old, new)
            return value
        return wrapped
    setattr(_prompt_owner, _prompt_name, _make_prompt_wrapper(_original_prompt))

# Reviewer-specific system prompts get the generic checklist acceptance contract.
for _name, _member in list(AgentRuntime.__dict__.items()):
    if not callable(_member) or "review" not in _name.lower() or "prompt" not in _name.lower():
        continue
    def _make_review_prompt(original: Any) -> Any:
        @functools.wraps(original)
        def wrapped(self: Any, *args: Any, **kwargs: Any) -> Any:
            value = original(self, *args, **kwargs)
            if isinstance(value, str) and CHECKLIST_REVIEWER_GUIDANCE not in value:
                value = value.rstrip() + "\n\n" + CHECKLIST_REVIEWER_GUIDANCE + "\n"
            return value
        return wrapped
    setattr(AgentRuntime, _name, _make_review_prompt(_member))

# Compact card/history views use the shared table. The state returned by
