for _owner_type in (Panels,):
    for _name, _member in list(_owner_type.__dict__.items()):
        if not callable(_member) or not any(token in _name.lower() for token in ("context_menu", "history", "expert_mode")):
            continue
        # Literal UI strings were already revised at source level. No broad wrapper
        # is needed; retaining this loop documents the intentionally narrow UI seam.
        pass


class _ToolNameTuple(tuple):
    """Tuple-compatible tool-name collection with the set helpers old callers use."""
    def intersection(self, *others: Any) -> set[str]:
        return set(self).intersection(*others)

    def union(self, *others: Any) -> set[str]:
        return set(self).union(*others)

    def difference(self, *others: Any) -> set[str]:
        return set(self).difference(*others)

    def issubset(self, other: Any) -> bool:
        return set(self).issubset(other)

    def issuperset(self, other: Any) -> bool:
        return set(self).issuperset(other)


def _tool_name_tuple(value: Any) -> _ToolNameTuple:
    if isinstance(value, _ToolNameTuple):
        return value
    return _ToolNameTuple(tuple(value or ()))

# Preserve tuple ordering/equality while restoring the set-style intersection
# contract used by ToolRegistry policy tests and internal filters.
if "EXPERT_MODE_TOOL_NAMES" in globals():
    EXPERT_MODE_TOOL_NAMES = _tool_name_tuple(EXPERT_MODE_TOOL_NAMES)
if "CHECKLIST_TOOL_NAMES" in globals():
    CHECKLIST_TOOL_NAMES = _tool_name_tuple(CHECKLIST_TOOL_NAMES)


# =============================================================================
# Agent roles, scoped tools and delegation
# =============================================================================
# Role prompts and enabled tools specialize the shared agent execution path.
# It does not create a second orchestration framework or semantic checklist types.

AGENT_SUBTYPE_GENERAL = "general"
AGENT_SUBTYPE_ORCHESTRATOR = "orchestrator"
AGENT_SUBTYPE_PLANNER = "planner"
AGENT_SUBTYPE_IMPLEMENTER = "implementer"
AGENT_SUBTYPE_REVIEWER = "reviewer"  # internal verification lifecycle only
AGENT_USER_SELECTABLE_SUBTYPES = (
    AGENT_SUBTYPE_GENERAL,
    AGENT_SUBTYPE_PLANNER,
    AGENT_SUBTYPE_IMPLEMENTER,
)
AGENT_ROLE_SIDECAR_SCHEMA = "agent_role.v303"
AGENT_ROLE_SIDECAR_FILENAME = "agent_role.v303.json"

class _PendingAgentRole:
    """Task-local pending role metadata spanning async Agent creation safely."""
    def __init__(self) -> None:
        self._value = contextvars.ContextVar("velox_pending_agent_role", default=None)
    def get(self) -> dict[str, Any] | None:
        value = self._value.get()
        return dict(value) if isinstance(value, dict) else None
    def set(self, value: dict[str, Any] | None) -> Any:
        return self._value.set(dict(value) if isinstance(value, dict) else None)
    def reset(self, token: Any) -> None:
        self._value.reset(token)

_PENDING_AGENT_ROLE = _PendingAgentRole()


def _agent_role_utc_now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def _agent_role_dir(storage: Any, agent_id: str) -> Path:
    paths = getattr(storage, "paths", None)
    if paths is None or not hasattr(paths, "agent_dir"):
        raise ValueError("Agent role storage requires Storage.paths.agent_dir")
    return Path(paths.agent_dir(str(agent_id)))


def _write_agent_role_json(path: Path, value: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    payload = json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    temporary.write_text(payload, encoding="utf-8")
    os.replace(temporary, path)


class AgentRoleStore:
    """Small persisted role/configuration sidecar for otherwise normal Agents."""

    def __init__(self, storage: Any):
        self.storage = storage

    def path(self, agent_id: str) -> Path:
        return _agent_role_dir(self.storage, agent_id) / AGENT_ROLE_SIDECAR_FILENAME

    @staticmethod
    def default(agent_id: str) -> dict[str, Any]:
        return {
            "schema": AGENT_ROLE_SIDECAR_SCHEMA,
            "agent_id": str(agent_id),
            "subtype": AGENT_SUBTYPE_GENERAL,
            "parent_objective": "",
            "global_constraints": "",
            "created_at": "",
            "updated_at": "",
        }

    @staticmethod
    def validate(value: Any, *, agent_id: str = "") -> dict[str, Any]:
        if not isinstance(value, dict):
            raise ValueError("Agent role sidecar must be an object")
        expected = {
            "schema", "agent_id", "subtype", "parent_objective",
            "global_constraints", "created_at", "updated_at",
        }
        if set(value) != expected:
            raise ValueError("Agent role sidecar fields are invalid")
        if value.get("schema") != AGENT_ROLE_SIDECAR_SCHEMA:
            raise ValueError("Agent role sidecar schema is invalid")
        actual_id = str(value.get("agent_id") or "")
        if not actual_id or (agent_id and actual_id != str(agent_id)):
            raise ValueError("Agent role sidecar agent_id is invalid")
        subtype = str(value.get("subtype") or "")
        if subtype not in AGENT_USER_SELECTABLE_SUBTYPES:
            raise ValueError("Agent subtype is invalid")
        for key in (
            "parent_objective", "global_constraints", "created_at", "updated_at",
        ):
            if not isinstance(value.get(key), str):
                raise ValueError(f"Agent role sidecar {key} must be text")
        return dict(value)

    def load(self, agent_id: str) -> dict[str, Any]:
        path = self.path(agent_id)
        if not path.exists():
            return self.default(agent_id)
        return self.validate(json.loads(path.read_text(encoding="utf-8")), agent_id=agent_id)

    def save(self, agent_id: str, metadata: dict[str, Any]) -> dict[str, Any]:
        allowed = {"subtype", "parent_objective", "global_constraints"}
        if not isinstance(metadata, dict) or set(metadata) - allowed:
            raise ValueError("Agent role accepts subtype, parent_objective and global_constraints only; Checklist links are not supported")
        current = self.load(agent_id)
        now = _agent_role_utc_now()
        value = self.default(agent_id)
        value.update({
            "subtype": str(metadata.get("subtype") or AGENT_SUBTYPE_GENERAL),
            "parent_objective": str(metadata.get("parent_objective") or "").strip(),
            "global_constraints": str(metadata.get("global_constraints") or "").strip(),
            "created_at": str(current.get("created_at") or now),
            "updated_at": now,
        })
        value = self.validate(value, agent_id=agent_id)
        _write_agent_role_json(self.path(agent_id), value)
        return value


def _extract_role_agent_id(value: Any) -> str:
    if isinstance(value, str):
        return value if value.strip() and len(value) >= 8 else ""
    if isinstance(value, dict):
        direct = str(value.get("agent_id") or "").strip()
        if direct:
            return direct
        for child in value.values():
            found = _extract_role_agent_id(child)
            if found:
                return found
    if isinstance(value, (list, tuple)):
        for child in value:
            found = _extract_role_agent_id(child)
            if found:
                return found
    return ""


def _internal_reviewer_role(agent: dict[str, Any]) -> bool:
    if not isinstance(agent, dict):
        return False
    existing = globals().get("_is_reviewer_agent")
    if callable(existing):
        try:
            if existing(agent):
                return True
        except Exception:
            pass
    marker = " ".join(str(agent.get(key) or "") for key in (
        "internal_role", "agent_role", "role", "review_kind", "task_kind",
    )).lower()
    return bool(
        agent.get("is_expert_reviewer")
        or agent.get("is_checklist_reviewer")
        or agent.get("internal_reviewer")
        or "reviewer" in marker
    )


def _load_agent_role(storage: Any, agent: dict[str, Any]) -> dict[str, Any]:
    agent_id = str(agent.get("agent_id") or "") if isinstance(agent, dict) else ""
    if not agent_id:
        return AgentRoleStore.default("")
    try:
        return AgentRoleStore(storage).load(agent_id)
    except Exception:
        return AgentRoleStore.default(agent_id)


def _agent_checklist_owner(agent: dict[str, Any]) -> dict[str, Any]:
    return {
        "owner_kind": "agent",
        "chat_id": str(agent.get("source_chat_id") or ""),
        "agent_id": str(agent.get("agent_id") or ""),
        "task_run_id": int(agent.get("task_run_id") or 0),
    }


def _chat_checklist_owner(chat_id: str) -> dict[str, Any]:
    return {
        "owner_kind": "chat", "chat_id": str(chat_id or ""),
        "agent_id": "", "task_run_id": 0,
    }


def _context_chat_id(args: tuple[Any, ...], kwargs: dict[str, Any]) -> str:
    for value in list(args) + list(kwargs.values()):
        if hasattr(value, "chat_id"):
            chat_id = str(getattr(value, "chat_id", "") or "").strip()
            if chat_id:
                return chat_id
        if isinstance(value, dict):
            chat_id = str(value.get("chat_id") or value.get("source_chat_id") or "").strip()
            if chat_id:
                return chat_id
    return ""


def _validate_role_assignment(storage: Any, args: tuple[Any, ...], kwargs: dict[str, Any], metadata: dict[str, Any]) -> None:
    if metadata.get("subtype") in (AGENT_SUBTYPE_PLANNER, AGENT_SUBTYPE_IMPLEMENTER) and not _context_chat_id(args, kwargs):
        raise ValueError("A prompted Planner/Implementer assignment requires its source Chat")


_ORCHESTRATOR_PROMPT = r"""AGENT SUBTYPE: ORCHESTRATOR
Preserve your one original requirements/acceptance Checklist. Attach each non-trivial requirement's complete mini-plan once with checklist_subitems_create. Work those fixed steps in dependency order; jump between actionable items when needed. Delegate bounded independent tasks with exact non-overlapping writable file/directory scopes, or read-only analysis. A Planner returns suggestions, not another active list. Workers manage their own context and return evidence/results; you alone inspect and integrate those results, update your steps and explicitly assess the original parent requirements. Independent review covers the complete original contract. Do not replace requirements with worker plans or infer acceptance from worker success."""

_PLANNER_PROMPT = r"""AGENT SUBTYPE: PLANNER
Inspect the bounded objective, current source and relevant Skills. Keep implementation source read-only. Return a concise proposed mini-plan with dependencies, an early executable checkpoint and relevant validation. The owner decides which proposed steps to attach to its requirements; no list is imported automatically. If your planning task itself is complex enough for a Checklist, create your one list of planning-deliverable acceptance criteria, finish that analysis and its review before terminal success. Do not register implementation work that you are not assigned to perform, leave an open list for someone else, or spawn workers."""

_IMPLEMENTER_PROMPT = r"""AGENT SUBTYPE: IMPLEMENTER
Complete the exact delegated objective within your exclusive writable scope. For complex work, create your own single immutable requirements Checklist and attach fixed one-time sub-item mini-plans for non-trivial requirements. No owner Checklist is shared or copied to you. Implement, execute and inspect the real output, repair defects and record factual progress. Mark steps done, explicitly assess parent acceptance, then use independent verify_checklist and repair reopened failures in the same list. Return precise artifacts, changes, evidence and remaining integration considerations. Your success does not itself mark the assigning context's requirements complete."""

_CHAT_ORCHESTRATION_GUIDANCE = r"""For large multi-feature work, preserve one original acceptance Checklist and decompose non-trivial requirements into fixed one-time sub-items. Delegate bounded independent tasks with non-overlapping exclusive file scopes; inspect returned work and validate integration before updating your own requirements. A Planner helps genuine planning uncertainty and returns proposed steps, never an automatically imported Checklist. Worker success does not substitute for owner acceptance or independent review. Ready Agent results are delivered between model rounds before Checklist continuation; integrate them before redoing delegated work. Use agents_get_result for a saved outcome and agents_get_output for detailed output (thinking/tool calls are opt-in), not repeated polling."""


_PROGRAMMING_WORKFLOW_GUIDANCE = r"""Follow the shared Checklist contract. Use the smallest coherent repair objective and factual evidence to advance the full acceptance scope."""


def _agent_assignment_block(metadata: dict[str, Any], *, checklists_enabled: bool = True) -> str:
    lines = ["ASSIGNED WORK CONTEXT:"]
    for field, label in (("parent_objective", "Relevant owner objective"), ("global_constraints", "Relevant global constraints")):
        if str(metadata.get(field) or "").strip():
            lines.append(f"- {label}: {metadata[field]}")
    lines.append("Your context owns only its own Checklist. Return evidence and results; the owner alone updates its original requirements."
                 if checklists_enabled else "Return evidence and results within your assigned scope; the owner validates integration.")
    return "\n".join(lines)


def _agent_role_prompt(subtype: str, metadata: dict[str, Any], *, checklists_enabled: bool = True) -> str:
    role_text = {
        AGENT_SUBTYPE_PLANNER: _PLANNER_PROMPT,
        AGENT_SUBTYPE_IMPLEMENTER: _IMPLEMENTER_PROMPT,
    }.get(subtype, "")
    if not checklists_enabled:
        role_text = {
            AGENT_SUBTYPE_PLANNER: "AGENT SUBTYPE: PLANNER\nInspect the bounded objective, source and relevant Skills read-only. Return a proposed mini-plan, dependencies and validation. Do not implement or spawn workers.",
            AGENT_SUBTYPE_IMPLEMENTER: "AGENT SUBTYPE: IMPLEMENTER\nComplete the assigned objective within your exclusive writable scope. Execute and inspect real output, repair defects and return artifacts, changes, validation evidence and integration considerations. Do not spawn workers.",
        }.get(subtype, "")
    assignment = _agent_assignment_block(metadata, checklists_enabled=checklists_enabled)
    if role_text and assignment:
        return role_text + "\n\n" + assignment
    return role_text or assignment


def _role_tool_name(schema: Any) -> str:
    if not isinstance(schema, dict):
        return ""
    function = schema.get("function")
    if isinstance(function, dict):
        return str(function.get("name") or "")
    return str(schema.get("name") or "")


_AGENT_MANAGEMENT_TOOL_PREFIXES = (
    "agents_", "agent_start", "agent_spawn", "agent_create",
)
_PLANNER_ALLOWED_CHECKLIST_TOOLS = set(CHECKLIST_TOOL_NAMES) - {"checklist_resume"}
_IMPLEMENTER_ALLOWED_CHECKLIST_TOOLS = set(CHECKLIST_TOOL_NAMES) - {"checklist_resume"}
_ROLE_CHECKLIST_TOOL_NAMES = set(CHECKLIST_TOOL_NAMES)
_MUTATING_TOOL_FRAGMENTS = (
    "write", "edit", "patch", "delete", "remove", "rename", "move",
    "mkdir", "create_file", "save_file", "import_file", "upload",
)
_PLANNER_EXECUTION_TOOLS = {
    "shell_exec", "python_exec", "terminal_open", "terminal_write",
    "terminal_read", "terminal_close",
}


def _is_agent_management_tool(name: str) -> bool:
    lowered = str(name or "").lower()
    return any(lowered.startswith(prefix) for prefix in _AGENT_MANAGEMENT_TOOL_PREFIXES)


def _is_mutating_project_tool(name: str) -> bool:
    lowered = str(name or "").lower()
    if lowered in _ROLE_CHECKLIST_TOOL_NAMES:
        return False
    if lowered.startswith(("fs_", "file_", "doc_", "document_", "drive_")):
        return any(fragment in lowered for fragment in _MUTATING_TOOL_FRAGMENTS)
    return lowered in {"image_save", "browser_download", "web_download_file"}


def _role_allows_tool(subtype: str, name: str) -> bool:
    lowered = str(name or "").lower()
    if subtype in (AGENT_SUBTYPE_GENERAL, AGENT_SUBTYPE_ORCHESTRATOR):
        return True
    if subtype == AGENT_SUBTYPE_PLANNER:
        if _is_agent_management_tool(lowered):
            return False
        if lowered in _PLANNER_EXECUTION_TOOLS:
            return False
        if _is_mutating_project_tool(lowered):
            return False
        if lowered in _ROLE_CHECKLIST_TOOL_NAMES:
            return lowered in _PLANNER_ALLOWED_CHECKLIST_TOOLS
        return True
    if subtype == AGENT_SUBTYPE_IMPLEMENTER:
        if _is_agent_management_tool(lowered):
            return False
        if lowered in _ROLE_CHECKLIST_TOOL_NAMES:
            return lowered in _IMPLEMENTER_ALLOWED_CHECKLIST_TOOLS
        return True
    return False


def _filter_role_native_tools(tools: Any, subtype: str) -> Any:
    if not isinstance(tools, (list, tuple)):
        return tools
    filtered = [tool for tool in tools if _role_allows_tool(subtype, _role_tool_name(tool))]
    return tuple(filtered) if isinstance(tools, tuple) else filtered


def _extract_role_arguments(args: tuple[Any, ...], kwargs: dict[str, Any]) -> tuple[tuple[Any, ...], dict[str, Any], dict[str, Any]]:
    keys = ("agent_subtype", "parent_objective", "global_constraints")
    retired = {"assigned_checklist_id", "parent_checklist_id", "parent_item_id"}
    clean_kwargs = dict(kwargs)
    if retired.intersection(clean_kwargs):
        raise ValueError("Agent Checklist links/copies are retired; delegate a bounded task and return results instead")
    raw = {key: clean_kwargs.pop(key, "") for key in keys}
    clean_args = list(args)
    for index in range(len(clean_args) - 1, -1, -1):
        value = clean_args[index]
        if not isinstance(value, dict):
            continue
        if retired.intersection(value):
            raise ValueError("Agent Checklist links/copies are retired")
        if not any(key in value for key in keys):
            continue
        cloned = dict(value)
        for key in keys:
            field = cloned.pop(key, "")
            if field and not raw[key]:
                raw[key] = field
        clean_args[index] = cloned
        break
    if any(not isinstance(value, str) for value in raw.values()):
        raise ValueError("Agent role arguments must be text")
    subtype = (raw.pop("agent_subtype") or AGENT_SUBTYPE_GENERAL).strip().lower()
    if subtype not in AGENT_USER_SELECTABLE_SUBTYPES:
        raise ValueError(f"Unsupported Agent subtype: {subtype}")
    return tuple(clean_args), clean_kwargs, {"subtype": subtype, **raw}


def _bind_agent_role_result(storage: Any, result: Any, metadata: dict[str, Any]) -> None:
    agent_id = _extract_role_agent_id(result)
    if agent_id:
        AgentRoleStore(storage).save(agent_id, metadata)


# Persist role metadata at the ordinary Agent creation boundary so prompt/tool
# selection sees it before the Agent runtime starts.
if hasattr(AgentStore, "create_agent"):
    _CREATE_AGENT_BASE = AgentStore.create_agent

    @functools.wraps(_CREATE_AGENT_BASE)
    def _create_agent_with_role(self: Any, *args: Any, **kwargs: Any) -> Any:
        result = _CREATE_AGENT_BASE(self, *args, **kwargs)
        metadata = _PENDING_AGENT_ROLE.get()
        if metadata and not _is_reviewer_agent(result):
            try:
                _bind_agent_role_result(self.storage, result, metadata)
            except Exception:
                agent_id = _extract_role_agent_id(result)
                if agent_id:
                    try:
                        self.delete_agent(agent_id, force=True)
                    except Exception:
                        pass
                raise
        return result

    AgentStore.create_agent = _create_agent_with_role


def _wrap_agent_start_with_role(registry: Any, original_handler: Callable[..., Any]) -> Callable[..., Any]:
    if inspect.iscoroutinefunction(original_handler):
        @functools.wraps(original_handler)
        async def wrapped_async(*args: Any, **kwargs: Any) -> Any:
            clean_args, clean_kwargs, metadata = _extract_role_arguments(tuple(args), kwargs)
            _validate_role_assignment(registry.storage, clean_args, clean_kwargs, metadata)
            token = _PENDING_AGENT_ROLE.set(metadata)
            try:
                resolved = await original_handler(*clean_args, **clean_kwargs)
                _bind_agent_role_result(registry.storage, resolved, metadata)
                return resolved
            finally:
                _PENDING_AGENT_ROLE.reset(token)
        return wrapped_async

    @functools.wraps(original_handler)
    def wrapped_sync(*args: Any, **kwargs: Any) -> Any:
        clean_args, clean_kwargs, metadata = _extract_role_arguments(tuple(args), kwargs)
        _validate_role_assignment(registry.storage, clean_args, clean_kwargs, metadata)
        token = _PENDING_AGENT_ROLE.set(metadata)
        try:
            result = original_handler(*clean_args, **clean_kwargs)
            if inspect.isawaitable(result):
                async def finish() -> Any:
                    inner_token = _PENDING_AGENT_ROLE.set(metadata)
                    try:
                        resolved = await result
                        _bind_agent_role_result(registry.storage, resolved, metadata)
                        return resolved
                    finally:
                        _PENDING_AGENT_ROLE.reset(inner_token)
                return finish()
            _bind_agent_role_result(registry.storage, result, metadata)
            return result
        finally:
            _PENDING_AGENT_ROLE.reset(token)
    return wrapped_sync


# Add convenient role inspection without changing the strict ordinary Agent
# record schema. The sidecar is the durable source of role configuration.
def _get_agent_role(self: Any, agent_id: str) -> dict[str, Any]:
    return AgentRoleStore(self.storage).load(agent_id)

AgentStore.get_agent_role = _get_agent_role


# Shared top-level Chat and programming guidance. Append to existing concise
# fields so normal simple tasks retain their current behavior.
if hasattr(ContextAssembler, "AGENT_GUIDANCE"):
    ContextAssembler.AGENT_GUIDANCE = (
        str(ContextAssembler.AGENT_GUIDANCE).rstrip()
        + " " + _CHAT_ORCHESTRATION_GUIDANCE
    )


def _extend_agent_start_schema(self: Any) -> None:
    definition = self.tools.get("agents_start")
    if definition is None or getattr(definition.handler, "_agent_role_hook_installed", False):
        return
    role_signature = (ToolArgumentSpec("task", "text"), ToolArgumentSpec("agent_subtype", "text"),
                      ToolArgumentSpec("parent_objective", "text"), ToolArgumentSpec("global_constraints", "text"))
    TOOL_POSITIONAL_SIGNATURES["agents_start"] = role_signature
    parameters = copy.deepcopy(definition.parameters)
    properties = parameters.setdefault("properties", {})
    properties.update({
        "agent_subtype": {"type": "string", "enum": list(AGENT_USER_SELECTABLE_SUBTYPES), "default": AGENT_SUBTYPE_GENERAL,
                          "description": "General, read/research-only Planner, or scoped Implementer. Each worker owns its own task Checklist when enabled."},
        "parent_objective": {"type": "string", "description": "Relevant owner objective, not a shared Checklist ID."},
        "global_constraints": {"type": "string", "description": "Material constraints for this bounded assignment."},
    })
    description = (str(definition.description or "").rstrip() +
        " Choose general, planner or implementer. Delegate a bounded task with exact exclusive writable scope or read-only work. "
        "Workers return evidence/results; no Checklist is copied or imported, and only the owning context updates its original requirements.")
    handler = _wrap_agent_start_with_role(self, definition.handler)
    setattr(handler, "_agent_role_hook_installed", True)
    self.tools["agents_start"] = dataclasses.replace(definition, description=description, parameters=parameters,
        handler=handler, positional_arguments=role_signature)


def _apply_agent_role_prompt(self: Any, agent: dict[str, Any], base: str) -> str:
    if _internal_reviewer_role(agent):
        return base
    metadata = _load_agent_role(self.storage, agent)
    subtype = str(metadata.get("subtype") or AGENT_SUBTYPE_GENERAL)
    if subtype == AGENT_SUBTYPE_GENERAL:
        return base
    addition = _agent_role_prompt(subtype, metadata,
        checklists_enabled=bool(normalize_tool_feature_flags(agent.get("tool_features"))["checklists_enabled"]))
    return str(base).rstrip() + "\n\n" + addition + "\n"


def _filter_reviewer_tools(tools: Any) -> Any:
    if not isinstance(tools, (list, tuple)):
        return tools
    denied = set(_ROLE_CHECKLIST_TOOL_NAMES)
    denied.update({"agents_start", "checklist_abandon"})
    filtered = [tool for tool in tools if _role_tool_name(tool) not in denied and not _is_mutating_project_tool(_role_tool_name(tool)) and not _is_agent_management_tool(_role_tool_name(tool))]
    return tuple(filtered) if isinstance(tools, tuple) else filtered


def _apply_agent_role_tools(self: Any, agent: dict[str, Any], tools: Any) -> Any:
    if _internal_reviewer_role(agent):
        return _filter_reviewer_tools(tools)
    metadata = _load_agent_role(self.storage, agent)
    return _filter_role_native_tools(tools, str(metadata.get("subtype") or AGENT_SUBTYPE_GENERAL))


REVIEW_IDLE = "idle"
REVIEW_REQUESTED = "requested"
REVIEW_RUNNING = "running"
REVIEW_PASSED = "passed"
REVIEW_FAILED = "failed"
REVIEW_ERROR = "error"
REVIEW_CANCELLED = "cancelled"
REVIEW_ACTIVE = frozenset((REVIEW_REQUESTED, REVIEW_RUNNING))

# Keep the execution-level guard broader than the provider-visible tool filter so
# a malformed/manual call cannot bypass Reviewer isolation.
EXPERT_MODE_REVIEWER_READ_ONLY_TOOL_DENYLIST = frozenset(
    set(EXPERT_MODE_REVIEWER_READ_ONLY_TOOL_DENYLIST)
    | set(CHECKLIST_TOOL_NAMES)
    | set(_ROLE_CHECKLIST_TOOL_NAMES)
    | {name for name in getattr(TOOL_POSITIONAL_SIGNATURES, "keys", lambda: [])() if str(name).startswith("agents_")}
)

REVIEWER_SYSTEM_PROMPT = r"""You are the independent Checklist acceptance Reviewer, a fresh dedicated Velox Agent Task. Perform one finite acceptance pass over all supplied items, including previous passes affected by later changes. Keep project source read-only; use available inspection/execution tools, then return verdicts. Checklist, Agent/delegation and recursive review tools are unavailable.

""" + QUALITY_EFFORT_GUIDANCE + "\n\n" + REVIEW_EVIDENCE_GUIDANCE + r"""

Start from the actual final artifact through its user-facing path. Run/open/render it, exercise representative inputs and inspect output before using source or implementer history as corroboration. Load relevant Skills. Verify unfamiliar or current external facts with primary sources using web_search/web_fetch; try browser_run_headless for blocked or JavaScript-only pages. Fetch pages sequentially.

A pass needs independently checked evidence for every material clause, including explicit required/forbidden implementation choices. Source presence, a successful build, report flag or exit code alone establishes neither behavior nor compliance. Preserve the user's criteria when evidence is inconvenient. A known defect in a required behavior fails its directly related item; distinguish implementation-step success from original parent requirement acceptance. C# items are requirements; C#.n items are attached steps. A failing step also fails its parent.

For visual work inspect current representative pixels. Make an expectation-independent defect sweep before scoring: orientation/uprightness, rotation/mirroring, malformed/missing geometry or textures, depth/z-order, camera framing, and UI/HUD/glyph clipping/readability. Prefer image_analyze_3D_scene or image_analyze_ui; use generic image_analyze where appropriate. Compare distinct states for animation/input. For user-facing controls, test the real input-to-visible-outcome path in both directions; a demo that sets state directly does not verify the input mapping. Startup checks that only confirm buffers, objects or clean logs are not behavioral acceptance evidence. Reuse browser visualReview.reviews; investigate discrepancies with a focused capture or measurement. Identical named demo output calls for tracing source -> target -> executable -> runtime showcase -> capture. Require fresh post-fix evidence after a visual/runtime failure.

Group diagnostic work by causal subsystem and reuse an observation only where it genuinely supports each clause. Leave repairs to the implementer. Unavailable validation is an evidence gap, not a pass; state the concrete missing proof rather than claiming an unobserved implementation failure.

FINAL RESPONSE: exactly one unwrapped JSON object with every supplied C# requirement and C#.n step once, in the supplied parent-first order:
{"verdicts":[{"requirement_id":"C1","verdict":"pass|fail","summary":"observed evidence or concrete gap","next_step":"one concrete repair/research/validation action for a failure; empty for a pass"}]}
Every failure requires a non-empty next_step. Then emit this final non-empty line, with nothing after it:
$$AGENT_PROGRESS: {"message":"Independent Checklist Review complete","percent":100}"""


def _recover_interrupted_checklist_reviews(storage: Storage) -> int:
    """Startup-only reconciliation: no waiter survives a process restart."""
    recovered = 0
    paths = storage.paths
    manager = ChecklistStore(storage)
    # Finish durable explicit Stop intents before ordinary review recovery. This
    # does not turn crashes/shutdown into user cancellations of unrelated work.
    for intent_path in paths.chats_dir().glob("chat_*/checklists_user_stop.json"):
        try:
            chat = json.loads((intent_path.parent / "chat.json").read_text(encoding="utf-8"))
            manager.cancel_open_by_user(_chat_checklist_owner(str(chat["chat_id"])), recover=True)
        except FileNotFoundError:
            continue
        except Exception as exc:
            _best_effort_lifecycle_log(storage, "checklist.user_stop_recovery_failed", {
                "path": str(intent_path), "error": f"{type(exc).__name__}: {exc}"})
    candidates = list(paths.chats_dir().glob("chat_*/checklists.json"))
    candidates += list(paths.agents_dir().glob("agent_*/checklists_*.json"))
    for path in candidates:
        try:
            with _CHECKLIST_LOCK:
                _require_durable_owner(path)
                raw = json.loads(path.read_text(encoding="utf-8"))
                owner = {key: raw.get(key) for key in ("owner_kind", "chat_id", "agent_id", "task_run_id")}
                collection = manager.load_collection(owner, create=False)
                checklist_ids = [str(row["id"]) for row in collection.get("checklists", [])
                                 if row.get("review_status") in REVIEW_ACTIVE]
            for checklist_id in checklist_ids:
                # A terminal Reviewer may have committed its output immediately
                # before shutdown. Finish that exact review; don't discard it or
                # create another Reviewer just because the original waiter died.
                result = _reconcile_checklist_review(storage, owner, checklist_id)
                if result is not None:
                    recovered += 1
                    continue
                with _CHECKLIST_LOCK:
                    collection = manager.load_collection(owner, create=False)
                    checklist = manager._checklist(collection, checklist_id)
                    if checklist.get("review_status") not in REVIEW_ACTIVE:
                        continue
                    checklist["review_status"] = REVIEW_ERROR
                    checklist["review_completed_at"] = _checklist_utc_now()
                    checklist["review_error"] = "Velox restarted before this independent review was committed. Request a fresh review explicitly."
                    manager._append_event(owner, checklist, None, actor="velox", event="review_interrupted", comment=checklist["review_error"])
                    manager._save(owner, collection)
                    recovered += 1
        except FileNotFoundError:
            continue
        except Exception as exc:
            _best_effort_lifecycle_log(storage, "checklist.recovery_failed", {"path": str(path), "error": f"{type(exc).__name__}: {exc}"})
    return recovered


def _review_snapshot_payload(manager: ChecklistStore, checklist: dict[str, Any]) -> list[dict[str, Any]]:
    return [{"id": item["id"], "text": item["text"], "state": item["state"],
             "kind": "requirement" if "subitems" in item else "step",
             "history": copy.deepcopy(item["history"])} for item in manager.all_items(checklist)]


def _review_snapshot_fingerprint(manager: ChecklistStore, checklist: dict[str, Any]) -> str:
    payload = _review_snapshot_payload(manager, checklist)
    raw = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def _set_checklist_review_state(
    manager: ChecklistStore,
    owner: dict[str, Any],
    checklist_id: str,
    status: str,
    *,
    agent_id: str = "",
    error: str = "",
    event: str = "review_status",
    comment: str = "",
    review_cycle: Optional[int] = None,
) -> dict[str, Any]:
    with _CHECKLIST_LOCK:
        collection = manager.load_collection(owner)
        checklist = manager._checklist(collection, checklist_id)
        if checklist.get("lifecycle") == CHECKLIST_LIFECYCLE_CANCELLED_BY_USER:
            return manager.compact_checklist(checklist)
        if review_cycle is not None and int(checklist.get("review_cycle") or 0) != int(review_cycle):
            raise ValueError("Late Reviewer callback belongs to a different review cycle")
        current_status = str(checklist.get("review_status") or REVIEW_IDLE)
        if current_status in (REVIEW_PASSED, REVIEW_FAILED, REVIEW_ERROR, REVIEW_CANCELLED):
            return manager.compact_checklist(checklist)
        if current_status not in REVIEW_ACTIVE or status not in (REVIEW_RUNNING, REVIEW_ERROR, REVIEW_CANCELLED):
            raise ValueError("Reviewer status changes require an active requested review; verdicts must use apply_review")
        checklist["review_status"] = status
        if agent_id:
            checklist["review_agent_id"] = str(agent_id)
        if status == REVIEW_RUNNING:
            checklist["review_started_at"] = _checklist_utc_now()
            checklist["review_completed_at"] = ""
            checklist["review_error"] = ""
        elif status in (REVIEW_PASSED, REVIEW_FAILED, REVIEW_ERROR, REVIEW_CANCELLED):
            checklist["review_completed_at"] = _checklist_utc_now()
            checklist["review_error"] = _clean_checklist_text(error, maximum=20000)
        manager._append_event(
            owner, checklist, None, actor="velox" if status in (REVIEW_ERROR, REVIEW_CANCELLED) else "reviewer",
            comment=comment or error or f"Checklist review status changed to {status}.",
            event=event, review_cycle=int(checklist.get("review_cycle") or 0),
        )
        manager._save(owner, collection)
        return manager.compact_checklist(checklist)


def _checklist_reviewer_state(manager: ChecklistStore, checklist: dict[str, Any]) -> dict[str, Any]:
    requirements = []
    for item in manager.all_items(checklist):
        latest = manager.latest_comment(item)
        prior = next((str(event.get("comment") or "") for event in reversed(item["history"])
                      if event.get("actor") == "reviewer"), "")
        parent_id = item["id"].split(".", 1)[0] if "." in item["id"] else ""
        requirements.append({"id": item["id"], "status": item["state"],
            "requirement": item["text"], "progress": latest, "review_summary": prior,
            "kind": "implementation_step" if parent_id else "original_requirement",
            "parent_item_id": parent_id,
            "next_step": latest if item["state"] == CHECKLIST_ITEM_IN_PROGRESS else ""})
    return {"requirements": requirements}


def _make_checklist_review_package(
    registry: ToolRegistry,
    owner: dict[str, Any],
    checklist: dict[str, Any],
    *,
    endpoint_profile_id: str,
) -> tuple[dict[str, Any], dict[str, Any], str]:
    agent_runtime = registry.agent_runtime
    if agent_runtime is None:
        raise RuntimeError("Checklist Review requires the bound normal Velox AgentRuntime")
    manager = ChecklistStore(registry.storage)
    cycle = int(checklist.get("review_cycle") or 0)
    review_dir = manager._owner_dir(owner) / "checklist_reviews" / str(checklist.get("id") or "checklist") / f"review_{cycle:03d}"
    bound = {
        "chat_id": str(owner.get("chat_id") or ""),
        "agent_id": str(owner.get("agent_id") or ""),
        "task_run_id": int(owner.get("task_run_id") or 0),
        "endpoint_profile_id": endpoint_profile_id,
    }
    messages = _collect_message_sequence(agent_runtime, bound)
    if owner.get("agent_id"):
        try:
            original_task = redact_durable_secret_text(
                str(agent_runtime.agents.load_agent(str(owner.get("agent_id") or "")).get("task") or "").strip()
            )
        except Exception:
            original_task = ""
    else:
        original_task = _original_expert_task(messages, "")
    workspace = _review_workspace_path(agent_runtime, owner)
    context_path = review_dir / "implementer_context.json"
    _write_expert_state_json(context_path, {
        "schema": "checklist_implementer_context.v303",
        "exported_at": _checklist_utc_now(),
        "owner": redact_durable_secrets(owner),
        "workspace": redact_durable_secret_text(workspace),
        "checklist_id": str(checklist.get("id") or ""),
        "review_cycle": cycle,
        "items": redact_durable_secrets(copy.deepcopy(checklist["items"])),
        "messages": messages,
    })
    state = _checklist_reviewer_state(manager, checklist)
    lines = [
        "# Checklist Review Handoff", "",
        "Schema: `checklist_review_handoff.v303`",
        f"Checklist: `{checklist.get('name')}` (`{checklist.get('id')}`)",
        f"Review cycle: {cycle}",
        f"Workspace/project root: `{workspace}`",
        f"Complete implementer context export: `{context_path}`", "",
        "## Authoritative task", "",
        _sanitize_review_handoff_text(original_task) or "The authoritative outcome is represented by the Checklist items below.", "",
        "## Original requirements and attached implementation steps", "",
        "C# items are original requirements. C#.n items are fixed implementation steps within that same Checklist.",
        "Evaluate original acceptance independently; passed steps do not by themselves prove their parent requirement.",
        "Return one verdict for every supplied ID in the supplied parent-first order.", "",
    ]
    for item in state["requirements"]:
        lines.extend([
            f"### {item['id']} · {item['status']}",
            ("Implementation step of " + item["parent_item_id"] if item["parent_item_id"] else "Original requirement / acceptance criterion"),
            item["requirement"],
            f"Implementer record: {_sanitize_review_handoff_text(item['progress']) or '(none)'}",
            f"Prior review: {_sanitize_review_handoff_text(item['review_summary']) or '(none)'}",
            "",
        ])
    facts = _extract_factual_tool_lines(messages)
    lines.extend(["## Concrete runtime/tool facts", ""])
    lines.extend([f"- {_sanitize_review_handoff_text(row)}" for row in facts] or ["- Inspect the complete context export and workspace directly."])
    lines.extend(["", "## Review instruction", "", "Begin with the actual final artifact through its user-facing consumption path, including fresh runtime/rendered inspection when material. Perform an expectation-independent defect sweep before scoring Checklist clauses. Done states, implementer claims, and stale prior captures are leads, not acceptance proof."])
    handoff = redact_durable_secret_text("\n".join(lines).strip() + "\n")
    handoff_path = review_dir / "review_handoff.md"
    with DATA_ROOTS.lock_for_path(handoff_path):
        _require_durable_owner(handoff_path)
        handoff_path.write_text(handoff, encoding="utf-8")
    package = {
        "review_dir": str(review_dir),
        "handoff_path": str(handoff_path),
        "context_path": str(context_path),
        "handoff": redact_durable_secret_text(handoff),
        "original_task": redact_durable_secret_text(original_task),
        "workspace": redact_durable_secret_text(workspace),
        "messages": redact_durable_secrets(messages),
        "owner": redact_durable_secrets(owner),
    }
    return state, package, str(context_path)


def _recover_completed_reviewer_result(runtime: AgentRuntime, agent_id: str, diagnostic: dict[str, Any]) -> bool:
    """Recover only formatting, never missing review work or a failed/cancelled run."""
    agent = runtime.agents.load_agent(agent_id)
    if not _is_reviewer_agent(agent) or agent.get("status") in AGENT_TERMINAL_STATUSES:
        return False
    try:
        marker = json.loads(str(agent.get("context") or "").split("\n", 1)[1])
        ids = marker.get("requirement_ids")
        if not isinstance(ids, list) or not ids or any(not isinstance(item, str) for item in ids):
            return False
        result = _extract_reviewer_result(runtime, agent_id, agent)
        _parse_reviewer_result(result, {"requirements": [{"id": item} for item in ids]})
    except (ValueError, RuntimeError, IndexError):
        return False
    runtime.agents.append_event(agent_id, "reviewer_terminal_result_recovered", {
        "message": "Complete independently produced verdict retained after bounded progress-control recovery.",
        "protocol_status": str(diagnostic.get("status") or "unknown"),
    })
    runtime._mark_succeeded(agent_id, "Independent review completed; malformed or absent terminal progress control was recovered.", result)
    return True


def _extract_reviewer_result(agent_runtime: AgentRuntime, agent_id: str, record: dict[str, Any]) -> str:
    """Use the final actual Reviewer output, with only protocol-only carryover.

    Never search the Agent's task/context or resurrect a verdict from before a
    later tool run. A control-only reply to a recorded recovery prompt may retain
    the immediately preceding verdict; all other missing results fail closed.
    """
    transcript = agent_runtime.agents.load_transcript(agent_id)
    outputs = [(index, event.get("data") or {}) for index, event in enumerate(transcript) if event.get("kind") == "llm_output"]
    for position in range(len(outputs) - 1, -1, -1):
        index, data = outputs[position]
        if data.get("native_tool_calls") or data.get("provider_native_tool_calls") or data.get("termination_category") in ("tool", "truncated", "safety", "cancelled", "error"):
            break
        candidate = _reviewer_visible_output(str(data.get("raw_text") if data.get("raw_text") is not None else data.get("text") or ""))
        if '"verdicts"' in candidate:
            return candidate
        # A terminal control by itself may repair framing, but is not new evidence.
        remainder = re.sub(r"(?m)^\s*\$\$AGENT_PROGRESS[^\n]*$", "", candidate).strip()
        if remainder or position == 0:
            break
        previous_index = outputs[position - 1][0]
        intervening = transcript[previous_index + 1:index]
        if not any(event.get("kind") == "reviewer_terminal_recovery" for event in intervening):
            break
        if any(event.get("kind") in ("tool_call", "tool_result", "tool_batch") for event in intervening):
            break
    raise RuntimeError("Checklist Reviewer Agent completed without a current structural verdict object")


def _begin_source_review_wait(registry: ToolRegistry, context: Any, owner: dict[str, Any], reviewer_agent_id: str) -> dict[str, Any]:
    token: dict[str, Any] = {"source_agent": None}
    monitor = getattr(registry, "task_monitor", None) or getattr(registry.agent_runtime, "monitor", None)
    task_id = str(getattr(context, "monitor_task_id", "") or "")
    if monitor is not None and task_id:
        try:
            monitor.update_metadata(task_id, {"waiting_for_reviewer_agent_id": reviewer_agent_id})
            monitor.set_phase(task_id, "waiting")
            monitor.set_activity(task_id, "inactive")
        except Exception:
            pass
    source_agent_id = str(owner.get("agent_id") or "")
    agent_runtime = registry.agent_runtime
    if source_agent_id and agent_runtime is not None:
        try:
            current = agent_runtime.agents.load_agent(source_agent_id)
            token["source_agent"] = {
                "agent_id": source_agent_id,
                "progress_message": str(current.get("progress_message") or ""),
                "progress_percent": current.get("progress_percent"),
            }
            agent_runtime._stop_active_clock(source_agent_id)
            agent_runtime.agents.update_agent(source_agent_id, {
                "progress_message": "Inactive - waiting for independent Checklist Reviewer",
                "active_started_at": None,
            })
        except Exception:
            token["source_agent"] = None
    return token


def _end_source_review_wait(registry: ToolRegistry, context: Any, token: dict[str, Any]) -> None:
    source = token.get("source_agent") if isinstance(token, dict) else None
    agent_runtime = registry.agent_runtime
    if isinstance(source, dict) and agent_runtime is not None:
        agent_id = str(source.get("agent_id") or "")
        try:
            current = agent_runtime.agents.load_agent(agent_id)
            if str(current.get("status") or "") == "running" and not current.get("active_started_at"):
                agent_runtime.agents.update_agent(agent_id, {
                    "active_started_at": now_iso(),
                    "progress_message": str(source.get("progress_message") or ""),
                    "progress_percent": source.get("progress_percent"),
                })
        except Exception:
            pass
    monitor = getattr(registry, "task_monitor", None) or getattr(agent_runtime, "monitor", None)
    task_id = str(getattr(context, "monitor_task_id", "") or "")
    if monitor is not None and task_id:
        try:
            monitor.update_metadata(task_id, {"waiting_for_reviewer_agent_id": ""})
            # The source remains ready/inactive until the normal runtime begins its
            # next provider request; that transition will set inference/activity.
            monitor.set_phase(task_id, "ready")
            monitor.set_activity(task_id, "inactive")
        except Exception:
            pass


def _safe_checklist_status(manager: ChecklistStore, owner: dict[str, Any], checklist_id: str) -> dict[str, Any]:
    try:
        return manager.status(owner, checklist_id, include_history=False)
    except FileNotFoundError:
        return {"checklist_id": checklist_id, "owner_deleted": True}


def _review_continuation_block(storage: Storage, owner: dict[str, Any]) -> str:
    """The generic review owns continuation even if its compatibility mirror lags.

    Only suppress the old automatic stop-continuation when implementation is done
    and review is pending, errored or cancelled. Failed acceptance with reopened
    items still continues normally. No new review or model request is launched.
    """
    manager = ChecklistStore(storage)
    if not manager.enabled(owner):
        return ""
    collection = manager.load_collection(owner, create=False)
    active = manager.active(owner, collection)
    if (active is not None
            and active.get("review_status") in (REVIEW_REQUESTED, REVIEW_RUNNING, REVIEW_ERROR, REVIEW_CANCELLED)
            and all(item.get("state") in (CHECKLIST_ITEM_DONE, CHECKLIST_ITEM_VERIFIED) for item in active.get("items", []))):
        return str(active.get("review_error") or "Independent review is unresolved; acceptance was not granted. An explicit review request is required.")
    return ""


def _reviewer_binding(agent: dict[str, Any]) -> dict[str, Any] | None:
    if not _is_reviewer_agent(agent):
        return None
    try:
        binding = json.loads(str(agent.get("context") or "").split("\n", 1)[1])
    except (ValueError, IndexError):
        return None
    if not isinstance(binding, dict) or binding.get("schema") != "checklist_reviewer_context.v303":
        return None
    return binding


def _review_outcome(manager: ChecklistStore, owner: dict[str, Any], checklist: dict[str, Any]) -> dict[str, Any]:
    """Rebuild delivery from canonical state; never repeat the acceptance commit."""
    result = manager.compact_checklist(checklist)
    status = str(checklist.get("review_status") or "")
    if status in (REVIEW_PASSED, REVIEW_FAILED):
        cycle = int(checklist.get("review_cycle") or 0)
        failed_count = sum(
            1 for item in manager.all_items(checklist)
            if any(event.get("event") == "review_fail" and int(event.get("review_cycle") or 0) == cycle
                   for event in item.get("history", []))
        )
        path = manager._owner_dir(owner) / "checklist_reviews" / str(checklist["id"]) / f"review_{cycle:03d}" / "review_result.json"
        try:
            exported = path.is_file()
        except OSError:
            exported = False  # Secondary export metadata cannot invalidate acceptance.
        return {**result, "action": "review_completed", "review_result": status,
                "failed_count": failed_count, "verified_count": len(manager.all_items(checklist)) - failed_count,
                "export_warning": "" if exported else "Reviewer result committed, but its JSON export is unavailable."}
    cancelled = status == REVIEW_CANCELLED or checklist.get("lifecycle") == CHECKLIST_LIFECYCLE_CANCELLED_BY_USER
    diagnostic = str(checklist.get("review_error") or checklist.get("cancellation_reason") or "Independent review did not complete.")
    stale = any(row.get("event") == "review_stale" and row.get("review_cycle") == checklist.get("review_cycle")
                for row in checklist.get("history", []))
    action = "review_cancelled" if cancelled else "review_stale" if stale else "review_error"
    return {**result, "action": action,
            "error": diagnostic, "retry_in_same_turn": False,
            "message": "Independent Reviewer ended without acceptance. Implementation state is unchanged; do not loop verify_checklist in this turn."}


def _finish_checklist_review(
    storage: Storage, owner: dict[str, Any], checklist_id: str, reviewer_agent_id: str, cycle: int,
) -> dict[str, Any] | None:
    """Join durable Reviewer output to exactly its requested cycle, without LLM work.

    Both the Reviewer terminal path and its source waiter use this function. Large
    transcript reads/parsing happen off the caller/UI thread and outside the state
    lock; the original identity, snapshot and active-status guards are rechecked at
    the existing atomic acceptance boundary. A repeated/later callback is a read.
    """
    manager = ChecklistStore(storage)

    def current() -> dict[str, Any] | None:
        collection = manager.load_collection(owner, create=False)
        checklist = manager._checklist(collection, checklist_id)
        if str(checklist.get("review_agent_id") or "") != reviewer_agent_id or int(checklist.get("review_cycle") or 0) != cycle:
            return None
        if owner.get("agent_id"):
            source = AgentStore(storage).load_agent(str(owner["agent_id"]))
            if (str(source.get("source_chat_id") or "") != str(owner.get("chat_id") or "")
                    or int(source.get("task_run_id") or 0) != int(owner.get("task_run_id") or 0)):
                return None
        return checklist

    try:
        with _CHECKLIST_LOCK:
            checklist = current()
            if checklist is None:
                return None
            if checklist.get("review_status") not in REVIEW_ACTIVE or checklist.get("lifecycle") != CHECKLIST_LIFECYCLE_OPEN:
                return _review_outcome(manager, owner, checklist)
            state = _checklist_reviewer_state(manager, checklist)
            fingerprint = str(checklist.get("review_snapshot_fingerprint") or "")
    except FileNotFoundError:
        return None  # Never recreate deleted owners or their collections.

    agents = AgentStore(storage)
    diagnostic = ""
    outcome_status = REVIEW_ERROR
    event = "review_error"
    verdicts: list[dict[str, Any]] = []
    try:
        record = agents.load_agent(reviewer_agent_id)
        if str(record.get("status") or "") not in AGENT_TERMINAL_STATUSES:
            return None
        binding = _reviewer_binding(record)
        if (binding is None or binding.get("owner") != owner
                or binding.get("checklist_id") != checklist_id or binding.get("cycle") != cycle
                or str(record.get("source_chat_id") or "") != str(owner.get("chat_id") or "")
                or binding.get("requirement_ids") != [item["id"] for item in state["requirements"]]
                or binding.get("snapshot_fingerprint") != fingerprint):
            raise ValueError("Reviewer identity does not match the requested owner, Checklist, cycle and snapshot")
        if record.get("status") != "succeeded":
            diagnostic = str(record.get("failure_message") or record.get("progress_message") or f"Reviewer Agent ended with status {record.get('status')}")
            if record.get("status") == "cancelled":
                outcome_status, event = REVIEW_CANCELLED, "review_cancelled"
        else:
            raw = _extract_reviewer_result(SimpleNamespace(agents=agents), reviewer_agent_id, record)
            parsed = _parse_reviewer_result(raw, state)
            verdicts = [{
                "item_id": row["requirement_id"], "verdict": row["verdict"],
                "comment": row["summary"] + (f" Next step: {row.get('next_step')}" if row["verdict"] == "fail" and row.get("next_step") else ""),
                "next_step": row.get("next_step") or "",
            } for row in parsed]
    except (FileNotFoundError, ValueError, RuntimeError) as exc:
        diagnostic = f"{type(exc).__name__}: {exc}"

    try:
        with _CHECKLIST_LOCK:
            checklist = current()
            if checklist is None:
                return None
            if checklist.get("review_status") not in REVIEW_ACTIVE or checklist.get("lifecycle") != CHECKLIST_LIFECYCLE_OPEN:
                return _review_outcome(manager, owner, checklist)
            if (not fingerprint or fingerprint != str(checklist.get("review_snapshot_fingerprint") or "")
                    or fingerprint != _review_snapshot_fingerprint(manager, checklist)):
                diagnostic = "Checklist changed while the independent Reviewer Agent was running; stale verdicts were discarded."
                outcome_status, event = REVIEW_ERROR, "review_stale"
            if diagnostic:
                _set_checklist_review_state(manager, owner, checklist_id, outcome_status,
                    review_cycle=cycle, agent_id=reviewer_agent_id, error=diagnostic, event=event)
                updated = current()
                result = _review_outcome(manager, owner, updated)
                if event == "review_stale":
                    result["action"] = "review_stale"
                return result
            # apply_review owns strict item validation and the single atomic
            # item/outcome/history/single-owner continuation commit. No alternative path
            # may set verified, including a plain Agent status of succeeded.
            result = manager.apply_review(owner, checklist_id, verdicts, review_cycle=cycle)
            verdicts = result.pop("review_verdicts", verdicts)
    except FileNotFoundError:
        return None

    export_warning = ""
    review_dir = manager._owner_dir(owner) / "checklist_reviews" / checklist_id / f"review_{cycle:03d}"
    try:
        _write_expert_state_json(review_dir / "review_result.json", {
            "schema": CHECKLIST_REVIEW_SCHEMA, "review_cycle": cycle,
            "review_agent_id": reviewer_agent_id, "completed_at": result.get("review_completed_at"),
            "verdicts": verdicts,
        })
    except Exception as exc:
        export_warning = f"Reviewer result committed, but its JSON export failed: {type(exc).__name__}: {exc}"
        _best_effort_lifecycle_log(storage, "checklist.review_export_failed", {
            "checklist_id": checklist_id, "review_cycle": cycle, "error": export_warning,
        })
    failed_count = sum(row["verdict"] == "fail" for row in verdicts)
    return {**result, "action": "review_completed", "review_result": "failed" if failed_count else "passed",
            "failed_count": failed_count, "verified_count": len(verdicts) - failed_count,
            "export_warning": export_warning}


def _finish_reviewer_agent(storage: Storage, reviewer_agent_id: str) -> dict[str, Any] | None:
    try:
        agent = AgentStore(storage).load_agent(reviewer_agent_id)
        binding = _reviewer_binding(agent)
        if binding is None or not isinstance(binding.get("owner"), dict):
            return None
        return _finish_checklist_review(storage, binding["owner"], str(binding.get("checklist_id") or ""),
                                             reviewer_agent_id, int(binding.get("cycle") or 0))
    except FileNotFoundError:
        return None


def _reconcile_checklist_review(storage: Storage, owner: dict[str, Any], checklist_id: str) -> dict[str, Any] | None:
    """Repair only an unresolved join. Never start/retry substantive review work."""
    manager = ChecklistStore(storage)
    collection = manager.load_collection(owner, create=False)
    checklist = manager._checklist(collection, checklist_id) if checklist_id else manager.active(owner, collection)
    if checklist is None or checklist.get("review_status") not in REVIEW_ACTIVE or not checklist.get("review_agent_id"):
        return None
    return _finish_checklist_review(storage, owner, str(checklist["id"]),
                                         str(checklist["review_agent_id"]), int(checklist.get("review_cycle") or 0))


async def _tool_verify_checklist(self: ToolRegistry, *args: Any, **kwargs: Any) -> Any:
    context, arguments = _parse_tool_handler_call(args, kwargs)
    owner = _checklist_owner_from_context(context, arguments)
    manager = ChecklistStore(self.storage)
    checklist_id = str(arguments.get("checklist_id") or "").strip()
    if not checklist_id:
        active = manager.active(owner)
        if active is None:
            raise ValueError("No active Checklist")
        checklist_id = str(active.get("id") or "")

    # Reviews always run through a dedicated AgentRuntime binding,
    # required before mutating review state, so wiring errors cannot create fake cycles.
    agent_runtime = getattr(self, "agent_runtime", None)
    if not isinstance(agent_runtime, AgentRuntime):
        raise RuntimeError("verify_checklist requires the bound normal Velox AgentRuntime")

    _checklist_tool_not_cancelled(context)
    recovered = await asyncio.to_thread(_reconcile_checklist_review, self.storage, owner, checklist_id)
    if recovered is not None:
        return recovered
    with _CHECKLIST_LOCK:
        _checklist_tool_not_cancelled(context)
        prepared = manager.prepare_verification(owner, checklist_id)
    cycle = int(prepared.get("review_cycle") or 0)
    reviewer_agent_id = ""
    wait_token: dict[str, Any] = {}
    try:
        collection = manager.load_collection(owner)
        checklist = manager._checklist(collection, checklist_id)
        endpoint_profile_id = str(getattr(context, "endpoint_profile_id", "") or "").strip()
        if not endpoint_profile_id:
            if owner.get("agent_id"):
                endpoint_profile_id = str(agent_runtime.agents.load_agent(str(owner.get("agent_id") or "")).get("endpoint_profile_id") or "")
            if not endpoint_profile_id:
                endpoint_profile_id = agent_runtime.chats.get_chat_endpoint_profile_id(str(owner.get("chat_id") or ""))

        state, package, _context_path = _make_checklist_review_package(
            self, owner, checklist, endpoint_profile_id=endpoint_profile_id,
        )
        inherited_features = {key: True for key in CHAT_TOOL_FEATURE_KEYS}
        try:
            if owner.get("agent_id"):
                inherited_features = normalize_tool_feature_flags(agent_runtime.agents.load_agent(str(owner.get("agent_id") or "")).get("tool_features"))
            else:
                inherited_features = normalize_tool_feature_flags(agent_runtime.chats.load_chat(str(owner.get("chat_id") or "")).get("features"))
        except Exception:
            pass
        inherited_features["agent_tools_enabled"] = False
        inherited_features["chat_history_enabled"] = False
        marker_payload = {
            "schema": "checklist_reviewer_context.v303",
            "cycle": cycle,
            "checklist_id": checklist_id,
            "requirement_ids": [str(item["id"]) for item in state["requirements"]],
            "snapshot_fingerprint": str(checklist.get("review_snapshot_fingerprint") or ""),
            "owner": owner,
            "handoff_path": package["handoff_path"],
            "context_path": package["context_path"],
        }
        reviewer_context = EXPERT_MODE_REVIEW_AGENT_CONTEXT_MARKER + "\n" + json.dumps(marker_payload, ensure_ascii=False, sort_keys=True)
        config = self.storage.load_config()
        reviewer = agent_runtime.agents.create_agent(
            str(owner.get("chat_id") or ""),
            _build_reviewer_user_prompt(state, package, cycle),
            title=f"Checklist Review {cycle}: {str(checklist.get('name') or checklist_id)}",
            endpoint_profile_id=endpoint_profile_id,
            context=reviewer_context,
            timeout_minutes=agent_timeout_minutes_from_config(config),
            auto_compaction_enabled=agent_auto_compaction_enabled_from_config(config),
            context_window_tokens=endpoint_context_window_tokens_from_config(config, endpoint_profile_id),
            max_output_tokens=endpoint_max_output_tokens_from_config(config, endpoint_profile_id),
            agent_kind=AGENT_KIND_GENERAL,
            tool_features=inherited_features,
        )
        reviewer_agent_id = str(reviewer.get("agent_id") or "")
        if not reviewer_agent_id:
            _set_checklist_review_state(manager, owner, checklist_id, REVIEW_ERROR, review_cycle=cycle, error="Reviewer Agent creation returned no agent_id", event="review_error")
            raise RuntimeError("Reviewer Agent creation returned no agent_id")

        _set_checklist_review_state(
            manager, owner, checklist_id, REVIEW_RUNNING, review_cycle=cycle,
            agent_id=reviewer_agent_id, event="review_started",
            comment=f"Independent review running in Reviewer Agent {reviewer_agent_id}.",
        )
        wait_token = _begin_source_review_wait(self, context, owner, reviewer_agent_id)
        reviewer_task = agent_runtime.start_agent(reviewer_agent_id)
        # wait() completes normally even if the child was cancelled; only source
        # cancellation interrupts this await. Unlike shield(), this needs no
        # Task.cancelling() (unavailable on supported Python 3.10) to distinguish
        # the two lifecycles, and it never cancels/detaches the child implicitly.
        await asyncio.wait({reviewer_task})
        record = agent_runtime.agents.load_agent(reviewer_agent_id)
        status = str(record.get("status") or "")
        if status not in AGENT_TERMINAL_STATUSES:
            # A dedicated Reviewer is one-shot: a paused/ended coroutine has no
            # continuing source waiter and must not become a resumable orphan.
            diagnostic = str(record.get("failure_message") or record.get("progress_message") or f"Reviewer ended with status {status}")
            _set_checklist_review_state(manager, owner, checklist_id, REVIEW_ERROR,
                review_cycle=cycle, agent_id=reviewer_agent_id, error=diagnostic, event="review_error")
            agent_runtime.cancel(reviewer_agent_id)
        result = await asyncio.to_thread(
            _finish_checklist_review, self.storage, owner, checklist_id, reviewer_agent_id, cycle,
        )
        if result is None:
            current = _safe_checklist_status(manager, owner, checklist_id)
            return {"action": "review_error" if current.get("owner_deleted") else "review_stale", "retry_in_same_turn": False,
                    "error": "Reviewer no longer owns this Checklist review; no verdict was applied.",
                    **current}
        return result
    except asyncio.CancelledError:
        # Child cancellation is a normal result of wait(), so this is always the
        # source being stopped/cancelled. Retire the review even if child cleanup
        # fails, and preserve the caller's cancellation rather than swallowing it.
        try:
            if reviewer_agent_id:
                agent_runtime.cancel(reviewer_agent_id)
        except Exception:
            pass
        try:
            _set_checklist_review_state(
                manager, owner, checklist_id, REVIEW_CANCELLED, review_cycle=cycle,
                agent_id=reviewer_agent_id, error="Checklist Review cancelled with its source owner.",
                event="review_cancelled",
            )
        except Exception as exc:
            _best_effort_lifecycle_log(self.storage, "checklist.review_cancel_cleanup_failed", {
                "checklist_id": checklist_id, "review_cycle": cycle, "error": f"{type(exc).__name__}: {exc}",
            })
        raise
    except Exception as exc:
        diagnostic = f"{type(exc).__name__}: {exc}"
        if reviewer_agent_id:
            try:
                agent_runtime.cancel(reviewer_agent_id)
            except Exception:
                pass
        try:
            _set_checklist_review_state(
                manager, owner, checklist_id, REVIEW_ERROR, review_cycle=cycle,
                agent_id=reviewer_agent_id, error=diagnostic, event="review_error",
                comment=f"Independent Reviewer Agent infrastructure error: {diagnostic}",
            )
        except Exception:
            pass
        return {
            "action": "review_error",
            "review_agent_id": reviewer_agent_id,
            "review_cycle": cycle,
            "error": diagnostic,
            "retry_in_same_turn": False,
            "message": "Independent Reviewer Agent did not complete. Implementation state is unchanged; do not loop verify_checklist in this turn.",
            **_safe_checklist_status(manager, owner, checklist_id),
        }
    finally:
        _end_source_review_wait(self, context, wait_token)


ToolRegistry.tool_verify_checklist = _tool_verify_checklist


_PROMPT_SNAPSHOT_LOCK = threading.RLock()
_REVIEW_REASONING_FIELDS = frozenset({
    "reasoning", "reasoning_content", "reasoning_details", "reasoning_fields", "thinking", "thinking_blocks", "raw_reasoning",
    "endpoint_reasoning", "reasoning_text", "encrypted_content", "_model_result_text",
})


class _ToolExecutionTimeout(TimeoutError):
    """The registry's own budget expired, rather than a handler's inner operation."""


def _best_effort_log(storage: Storage, event: str, data: dict[str, Any]) -> None:
    try:
        storage.append_app_log(event, data)
    except Exception:
        pass


def _canonical_mapping(value: Any) -> Any:
    """Canonicalize JSON object ordering without changing ordered schema arrays."""
    if isinstance(value, dict):
        return {key: _canonical_mapping(value[key]) for key in sorted(value)}
    if isinstance(value, list):
        return [_canonical_mapping(item) for item in value]
    return value


def _tool_result_failure(name: str, result: Any) -> str:
    """Distinguish execution failure from a successfully completed acceptance review."""
    if not isinstance(result, dict):
        return ""
    if name in {"shell_exec", "python_exec"}:
        code = result.get("returncode")
        if isinstance(code, int) and not isinstance(code, bool) and code != 0:
            return f"{name} exited with returncode {code}; inspect stdout and stderr."
    if name in {"browser_run_headless", "browser_demo_playback"}:
        if result.get("launchError"):
            return "Browser execution failed: " + str(result["launchError"])
        if result.get("success") is False:
            return "Browser execution reported failure; inspect its diagnostics."
    # An explicit native handler failure is not a successful invocation. Checklist
    # acceptance uses review_result=failed, not ok=False: that remains tool success.
    if result.get("ok") is False:
        return str(result.get("error") or result.get("message") or "Tool handler reported failure")
    return ""


BROWSER_TOOL_NAMES = frozenset({"browser_run_headless", "browser_demo_playback"})
BROWSER_MODEL_RESULT_MAX_CHARS = 64_000


def browser_model_result_view(result: dict[str, Any]) -> dict[str, Any]:
    """Group repeated captured diagnostics for inference, not the durable report.

    Only top-level event timestamps are ignored in equality. Every other field,
    including stack/source/line/severity, must match. Counts refer to *captured*
    records, not uncaptured browser events. Original chronology remains on disk.
    """
    projected = dict(result)
    aggregation: dict[str, Any] = {}
    for section, keys in (
        ("events", ("console", "exceptions", "logEntries", "networkFailures")),
        ("page", ("capturedErrors", "capturedRejections")),
    ):
        original = result.get(section)
        if not isinstance(original, dict):
            continue
        changed = dict(original)
        for key in keys:
            records = original.get(key)
            if not isinstance(records, list) or len(records) < 2:
                continue
            unique: list[Any] = []
            lookup: dict[str, int] = {}
            groups: list[dict[str, Any]] = []
            for index, record in enumerate(records):
                identity = ({k: v for k, v in record.items() if k != "timestamp"}
                            if isinstance(record, dict) else record)
                fingerprint = json.dumps(identity, ensure_ascii=False, sort_keys=True,
                                         separators=(",", ":"), default=str)
                slot = lookup.get(fingerprint)
                if slot is None:
                    slot = len(unique)
                    lookup[fingerprint] = slot
                    unique.append(record)
                    groups.append({"record_index": slot, "occurrences": 0,
                                   "first_index": index, "last_index": index})
                group = groups[slot]
                group["occurrences"] += 1
                group["last_index"] = index
                if isinstance(record, dict) and "timestamp" in record:
                    group.setdefault("first_timestamp", record["timestamp"])
                    group["last_timestamp"] = record["timestamp"]
            if len(unique) < len(records):
                changed[key] = unique
                aggregation[f"{section}.{key}"] = {
                    "captured_records": len(records), "unique_records": len(unique),
                    "repeated_records": [group for group in groups if group["occurrences"] > 1],
                }
        projected[section] = changed
    if aggregation:
        projected["diagnosticAggregation"] = {
            "schema": "browser_diagnostic_groups.v303",
            "notice": "Repeated captured diagnostics grouped by identical contents except timestamp. "
                      "Rows keep first-occurrence order. Counts and first/last positions are below; "
                      "the full captured sequence remains in artifacts.result and tool history. "
                      "This does not make a failed run pass or establish uncaptured event counts.",
            "groups": aggregation,
        }
    return projected


def compact_browser_diagnostic_message(storage: Any, message: dict[str, Any]) -> dict[str, Any]:
    """Explicit compaction may re-project an oversized retained browser result.

    Do not touch user text, tool arguments, Skills or an ordinary replay prefix.
    Matching call/result identity, outcome and the durable raw report are retained.
    """
    def project(text: Any) -> Any:
        if not isinstance(text, str) or len(text) < 4096:
            return text
        try:
            value = json.loads(text)
        except (ValueError, TypeError):
            return text
        if not isinstance(value, dict) or value.get("tool_name") not in BROWSER_TOOL_NAMES:
            return text
        if not isinstance(value.get("result"), dict):
            return text
        value.pop("_model_result_text", None)
        candidate = _tool_result_payload(storage, value)
        return candidate if len(candidate) < len(text) else text

    if message.get("role") in {"user", "system", "developer"}:
        return dict(message)
    out = dict(message)
    if message.get("role") == "tool":
        out["content"] = project(message.get("content"))
    if message.get("type") == "function_call_output":
        out["output"] = project(message.get("output"))
    if isinstance(message.get("response_output_items"), list):
        out["response_output_items"] = [
            dict(row, output=project(row.get("output")))
            if isinstance(row, dict) and row.get("type") == "function_call_output" else row
            for row in message["response_output_items"]
        ]
    return out


def _tool_result_payload(storage: Storage, result: dict[str, Any]) -> str:
    """Freeze one model-facing result; bounded results remain valid, explicit JSON."""
    cached = result.get("_model_result_text")
    if isinstance(cached, str):
        return cached
    cancelled = result.get("cancelled") or result.get("status") == "cancelled"
    status = ("CANCELLED_BY_USER" if result.get("cancelled_by_user") else "CANCELLED") if cancelled else (
        "SUCCESS_WITH_WARNINGS" if result.get("ok") and result.get("warning") else
        "SUCCESS" if result.get("ok") else "FAILED")
    name = str(result.get("tool_name") or result.get("name") or "tool")
    payload = {key: value for key, value in result.items() if key not in {
        "_model_result_text", "tool_failure_count", "malformed_tool_call_streak",
    }}
    # An executed native call already carries its exact arguments in the preceding
    # assistant message. Repeating them (including nested raw/provider mirrors) can
    # force even a small stdout/stderr through output truncation. This is a view
    # projection only: never mutate the durable input/raw records or old replay.
    if not result.get("malformed_tool_call") and isinstance(result.get("provider_tool_call"), dict):
        for key in ("input", "raw_tool_call", "provider_tool_call"):
            payload.pop(key, None)
        payload["input_echo_omitted"] = (
            "Arguments remain in the matching native call and tool details/history; "
            "result contains the handler output, not the input source."
        )
    if name in BROWSER_TOOL_NAMES and isinstance(payload.get("result"), dict):
        payload["result"] = browser_model_result_view(payload["result"])
    payload.setdefault("velox_status", status)
    payload.setdefault("velox_message", f"VELOX TOOL RESULT {status}: {name}")
    serialize = lambda value: json.dumps(value, ensure_ascii=False, separators=(",", ":"), default=str)
    text = serialize(payload)
    limit = tool_setting_int(storage.load_config(), "tool_result_max_chars")
    if name in BROWSER_TOOL_NAMES:
        limit = min(limit, BROWSER_MODEL_RESULT_MAX_CHARS)
    if name not in SELF_BOUNDED_TOOL_RESULT_NAMES and len(text) > limit:
        original_chars = len(text)
        priority = {key: index for index, key in enumerate((
            "ok", "status", "tool_call_id", "tool_name", "result", "error",
            "returncode", "exit_code", "timed_out", "cancelled", "review_result",
            "stderr", "stdout", "provider_tool_call_id", "passed", "failed",
            "success", "diagnosticsClean", "launchError", "consoleErrorCount",
            "capturedErrorCount", "capturedRejectionCount", "logErrorCount",
            "artifacts", "diagnosticAggregation", "events", "page", "visualReview", "playback",
        ))}
        def bound(value: Any, chars: int, fields: int, depth: int = 0) -> Any:
            if isinstance(value, str):
                if len(value) <= chars:
                    return value
                head = max(1, chars * 2 // 3)
                tail = max(1, chars - head)
                return value[:head] + f"\n[TRUNCATED: {len(value) - head - tail} characters omitted]\n" + value[-tail:]
            if isinstance(value, dict):
                if depth >= 6:
                    return {"_velox_truncated": True, "original_fields": len(value)}
                keys = sorted(value, key=lambda key: (priority.get(key, 1000), str(key)))
                out = {key: bound(value[key], chars, fields, depth + 1) for key in keys[:max(fields, min(8, len(keys)))]}
                if len(keys) > len(out):
                    out["_velox_omitted_fields"] = len(keys) - len(out)
                return out
            if isinstance(value, (list, tuple)):
                out = [bound(item, chars, fields, depth + 1) for item in value[:fields]] if depth < 6 else []
                if len(value) > len(out):
                    out.append({"_velox_omitted_items": len(value) - len(out)})
                return out
            return value
        chars, fields = max(64, limit // 8), 24
        while True:
            bounded = bound(payload, chars, fields)
            bounded["truncation"] = {
                "truncated": True, "original_chars": original_chars,
                "notice": "This is a partial tool result, not complete evidence. Full output remains in tool details/history.",
            }
            if name in BROWSER_TOOL_NAMES:
                raw_result = payload.get("result") or {}
                artifacts = raw_result.get("artifacts") or {}
                bounded["truncation"]["full_result"] = artifacts.get("result") or {}
                bounded["truncation"]["notice"] += " Inspect full_result for the captured browser report before acceptance."
            text = serialize(bounded)
            if len(text) <= limit or (chars <= 16 and fields <= 4):
                break
            chars, fields = max(16, chars // 2), max(4, fields - 4)
        # Identity/outcome are never sacrificed to a large body. For extremely
        # small configured budgets, return a minimal manifest rather than broken JSON.
        if len(text) > limit:
            bounded = {key: payload[key] for key in ("ok", "status", "tool_call_id", "tool_name") if key in payload}
            if "error" in payload:
                bounded["error"] = bound(str(payload["error"]), max(16, limit // 8), 4)
            bounded["truncation"] = {"truncated": True, "original_chars": original_chars}
            bounded["result"] = {key: payload["result"][key] for key in ("returncode", "exit_code", "review_result")
                                 if isinstance(payload.get("result"), dict) and key in payload["result"]}
            text = serialize(bounded)
    result["_model_result_text"] = text
    return text


def _review_evidence_value(value: Any) -> Any:
    """Drop private reasoning carriers, leaving literal user/tool strings intact."""
    if isinstance(value, dict):
        if value.get("type") == "reasoning":
            return {"type": "reasoning_omitted", "notice": "Private reasoning is not execution evidence."}
        return {key: _review_evidence_value(item) for key, item in value.items()
                if key not in _REVIEW_REASONING_FIELDS and key not in {"raw_response", "raw", "model_replay_messages"}}
    if isinstance(value, (list, tuple)):
        return [_review_evidence_value(item) for item in value]
    return value


def _review_context(value: Any) -> Any:
    if isinstance(value, list):
        return [_review_context(item) for item in value]
    if not isinstance(value, dict):
        return value
    result = {key: _review_context(item) for key, item in value.items()
              if key not in _REVIEW_REASONING_FIELDS and key not in {"raw_response", "raw"}}
    if result.get("type") == "reasoning":
        return {"type": "reasoning_omitted", "notice": "Private reasoning is not execution evidence."}
    if value.get("role") == "user":
        for key in ("content", "text"):
            if key in value:
                result[key] = copy.deepcopy(value[key])
    if value.get("role") == "assistant" or value.get("type") == "message" and value.get("role") == "assistant":
        for key in ("text", "content"):
            result[key] = _strip_review_assistant_text(result.get(key))
    if value.get("kind") == "llm_output" and isinstance(result.get("data"), dict):
        for key in ("text", "content"):
            if key in result["data"]:
                result["data"][key] = _strip_review_assistant_text(result["data"][key])
    return result


def _make_vision_context_room(
    messages: list[dict[str, Any]], endpoint: dict[str, Any], incoming_images: int,
    *, allow_ordinary: bool = False,
) -> int:
    """Append-only while images fit; explicitly compact old pixels at the hard cap.

    Preserve every original text instruction and its position. A pixel-budget
    rollover replaces old image blocks with an omission notice rather than deleting
    whole user turns or silently losing the newest material.
    """
    limit = endpoint_max_image_inputs(endpoint)
    needed = max(0, message_image_input_count(messages) + min(incoming_images, limit) - limit)
    if not needed:
        return 0
    removed = 0
    candidates = [index for index, row in enumerate(messages) if row.get(CURRENT_CONTEXT_VISION_MESSAGE_MARKER)]
    if allow_ordinary:
        candidates += [index for index, row in enumerate(messages)
                       if row.get("role") == "user" and not row.get(CURRENT_CONTEXT_VISION_MESSAGE_MARKER)]
    for index in candidates:
        row = messages[index]
        content = row.get("content")
        if not isinstance(content, list):
            continue
        out = []
        changed = False
        for part in content:
            is_image = isinstance(part, dict) and (part.get("type") in {"image_url", "input_image", "image"} or "image_url" in part)
            if is_image and needed:
                out.append({"type": "text", "text": "[Earlier image omitted at the endpoint image-budget boundary. Its original attachment/tool output remains on disk; this is not fresh visual evidence.]"})
                needed -= 1
                removed += 1
                changed = True
            else:
                out.append(part)
        if changed:
            messages[index] = {**row, "content": out, "_velox_image_budget_compaction": True}
        if not needed:
            break
    return removed


async def _execute_agent_tool(
    runtime: AgentRuntime, owner_agent_id: str, pending: dict[str, Any],
    scope_id: str, tool_call: dict[str, Any], **origin: Any,
) -> dict[str, Any]:
    """Checkpoint dispatch intent/result in the existing durable pending call.

    A crash between an external side effect and its result commit has an unknown
    outcome. Never silently reexecute that call; return explicit recovery evidence
    for inspection. A committed result is replayed without another side effect.
    """
    current = runtime.agents.load_agent(owner_agent_id)
    record = copy.deepcopy(current.get("pending_tool_call") or {})
    slots = record.get("calls", []) if record.get("parallel_image_batch") else [record]
    execution_id = str(pending.get("execution_id") or "")
    slot = next((item for item in slots if isinstance(item, dict) and (
        (execution_id and item.get("execution_id") == execution_id) or
        (not execution_id and item.get("iteration") == pending.get("iteration")
         and item.get("provider_tool_call_id") == pending.get("provider_tool_call_id")
         and item.get("raw_tool_call") == pending.get("raw_tool_call")))), None)
    if slot is None:
        raise RuntimeError("The pending Agent call changed before dispatch")
    execution_id = str(slot.get("execution_id") or execution_id or uuid_v4())
    slot["execution_id"] = execution_id
    pending["execution_id"] = execution_id
    if isinstance(slot.get("execution_result"), dict):
        return copy.deepcopy(slot["execution_result"])
    if slot.get("execution_started"):
        return {
            "ok": False, "status": "failed", "outcome_unknown": True,
            "tool_name": str(pending.get("normalized_name") or tool_call.get("name") or "tool"),
            "tool_call_id": execution_id,
            "error": "Execution was interrupted before its result was committed. It was NOT executed again; inspect the external state before explicitly retrying.",
            "started_at": str(slot.get("execution_started_at") or ""),
            "ended_at": now_iso(), "elapsed_seconds": 0.0,
        }
    slot["execution_started"] = True
    slot["execution_started_at"] = now_iso()
    pending.update(copy.deepcopy(slot))
    runtime.agents.update_agent(owner_agent_id, {"pending_tool_call": record})
    result = await runtime.tools.execute_tool_call(scope_id, tool_call, tool_call_id=execution_id, **origin)
    # Another member of a parallel image batch may have committed meanwhile.
    current = runtime.agents.load_agent(owner_agent_id)
    record = copy.deepcopy(current.get("pending_tool_call") or {})
    slots = record.get("calls", []) if record.get("parallel_image_batch") else [record]
    slot = next((item for item in slots if item.get("execution_id") == execution_id), None)
    if slot is None:
        raise RuntimeError("The Agent pending call disappeared after execution; do not repeat its side effect")
    slot["execution_result"] = runtime._json_safe(result)
    pending["execution_result"] = copy.deepcopy(slot["execution_result"])
    runtime.agents.update_agent(owner_agent_id, {"pending_tool_call": record})
    return result


def _record_agent_tool_result(runtime: AgentRuntime, agent_id: str, data: dict[str, Any]) -> None:
    result = data.get("result") or {}
    identity = str(result.get("tool_call_id") or "")
    for event in reversed(runtime.agents.load_transcript(agent_id)):
        if event.get("kind") == "tool_result" and identity and str(((event.get("data") or {}).get("result") or {}).get("tool_call_id") or "") == identity:
            return
    runtime.agents.append_event(agent_id, "tool_result", data)


def _strip_review_assistant_text(value: Any) -> Any:
    if isinstance(value, str):
        return strip_reasoning_content(value)
    if isinstance(value, list):
        return [
            {**part, "text": strip_reasoning_content(part["text"])}
            if isinstance(part, dict) and isinstance(part.get("text"), str) else part
            for part in value
        ]
    return value


async def _drain_cancelled_tool_handler(task: asyncio.Task[Any]) -> None:
    # Cancellation cannot preempt an arbitrary synchronous worker. Built-in process
    # handlers observe the cancellation event and terminate their owned process
    # trees before they finish. Do not allow an uncooperative adapter to hang Stop.
    done, _ = await asyncio.wait({task}, timeout=6.0)
    if done:
        try:
            task.result()
        except (Exception, asyncio.CancelledError):
            pass
    else:
        task.add_done_callback(lambda finished: finished.exception() if not finished.cancelled() else None)


def _compaction_termination_succeeded(finish: Any, stop: Any) -> bool:
    reasons = {normalize_llm_termination_reason(finish), normalize_llm_termination_reason(stop)}
    return not reasons.intersection({"cancelled", "canceled", "error", "failed", "incomplete"}) and llm_termination_category(finish, stop) == "normal"


if __name__ == "__main__":
    main()
